	[561] = {id=561, zh_CN="看见毛茸茸就失控！", },
	[562] = {id=562, zh_CN="夜店是我家，蹦迪靠才华。", },
	[563] = {id=563, zh_CN="我伤感了，但不知道为啥。", },
	[564] = {id=564, zh_CN="骑共享单车也敢漂移。", },
	[565] = {id=565, zh_CN="不会装，但装得挺帅。", },
	[566] = {id=566, zh_CN="我要我觉得，不要你觉得。", },
	[567] = {id=567, zh_CN="语言大师，小嘴抹了蜜。", },
	[568] = {id=568, zh_CN="刚才我要干啥来着？", },
	[569] = {id=569, zh_CN="小嘴叭叭叭，滴答滴答滴滴答。", },
	[570] = {id=570, zh_CN="柠檬树上柠檬果 柠檬树下你和我。", },
	[571] = {id=571, zh_CN="这里有一个像素的偏差。", },
	[572] = {id=572, zh_CN="躺平是我的终身事业。", },
	[573] = {id=573, zh_CN="隐形富豪，但只炫9块9包邮。", },
	[574] = {id=574, zh_CN="上车变暴躁，骂完就后悔。", },
	[575] = {id=575, zh_CN="世界都是我的城堡。", },
	[576] = {id=576, zh_CN="遇事不决，量子力学。", },
	[577] = {id=577, zh_CN="总有刁民想害朕。", },
	[578] = {id=578, zh_CN="社交三分钟，躺平三小时。", },
	[579] = {id=579, zh_CN="上班像坐牢，下班像越狱。", },
	[580] = {id=580, zh_CN="给我尝尝，这在哪买的。", },
	[581] = {id=581, zh_CN="说话自带反讽，气人不偿命。", },
	[582] = {id=582, zh_CN="人生如戏，全靠演技。", },
	[583] = {id=583, zh_CN="嘴强王者，全身上下嘴最硬。", },
	[584] = {id=584, zh_CN="能白嫖绝不花钱，省钱冠军。", },
	[585] = {id=585, zh_CN="即时80岁也还在喊封印解除！", },
	[586] = {id=586, zh_CN="嘴上说不要，心里超想要。", },
	[587] = {id=587, zh_CN="姐就是女王，自信放光芒。", },
	[588] = {id=588, zh_CN="一级算法加密语言。", },
	[589] = {id=589, zh_CN="你可能对，但我永远不输。", },
	[590] = {id=590, zh_CN="只要我不尴尬，尴尬的就是别人。", },
	[591] = {id=591, zh_CN="真爱无敌。", },
	[592] = {id=592, zh_CN="月亮代表我的心。", },
	[593] = {id=593, zh_CN="没有人比我更懂。", },
	[594] = {id=594, zh_CN="上个世纪出土文物。", },
	[595] = {id=595, zh_CN="好友比通讯录还复杂的渔场管理员。", },
	[596] = {id=596, zh_CN="甜有100种方式吃糖蛋糕和98次想你。", },
	[597] = {id=597, zh_CN="听君一席话，如听一席话。", },
	[598] = {id=598, zh_CN="快说我们才是天下第一好。", },
	[599] = {id=599, zh_CN="人类本质的坚定践行者，永不停歇。", },
	[600] = {id=600, zh_CN="礼物精通", },
	[601] = {id=601, zh_CN="社团解锁初级礼物技艺", },
