	[610] = {id=610, zh_CN="过渡句。", },
	[611] = {id=611, zh_CN="非人型表情", },
	[612] = {id=612, zh_CN="樱园门口，左边一圈叔叔阿姨围着举小旗的导游，右边一堆小学生在卖小吃的摊位前排队。", },
	[613] = {id=613, zh_CN="我和祁煜交换一个眼神，互相看到了对方眼底的挣扎。", },
	[614] = {id=614, zh_CN="我们是来感受春天的气息还是人群的气息？", },
	[615] = {id=615, zh_CN="……", },
	[616] = {id=616, zh_CN="要不今天算了，等过段时间直接去海边感受夏天的气息吧。", },
	[617] = {id=617, zh_CN="祁煜作势转身要走，我急忙一把拉住他。", },
	[618] = {id=618, zh_CN="来都来了，就这么放弃吗？我还挺想和你一起看樱花的……", },
	[619] = {id=619, zh_CN="我的意思是……偶尔赏赏花也挺好，亲近自然放松身心嘛。", },
	[620] = {id=620, zh_CN="你不说我还不会多想，你这么一解释……", },
	[621] = {id=621, zh_CN="我倒是怀疑你在欲盖弥彰了。", },
	[622] = {id=622, zh_CN="正想随便扯个借口转移话题，就见他歪歪脑袋朝我身后望，神情好奇。", },
	[623] = {id=623, zh_CN="既然是放松身心，干嘛还背个大包，不嫌累赘？", },
	[624] = {id=624, zh_CN="这个一一是我的小秘密，暂时不告诉你。", },
	[625] = {id=625, zh_CN="望着前方损动的人头，再看看人与人之间能把包子挤成饼的距离，我也参考里面的游客，把背包反背在身前。", },
	[626] = {id=626, zh_CN="祁煜挑了挑眉，冲我伸手。", },
	[627] = {id=627, zh_CN="不用，这包不重。", },
	[628] = {id=628, zh_CN="是想让你两只手都空出来抓紧我，免得进去被人潮挤散。", },
	[629] = {id=629, zh_CN="那我一只手护着包，一只手抓住你也足够了。", },
	[630] = {id=630, zh_CN="急流骤浪里，不用全力可抓不住太过灵活的鱼。", },
	[631] = {id=631, zh_CN="我都能够预见，一旦冲击的力道太过强大，你肯定会松开手。", },
	[632] = {id=632, zh_CN="虽然他并没有挑衅的意思，但我还是成功被他激起了某种奇怪的胜负欲。", },
	[633] = {id=633, zh_CN="那不如打个赌？", },
	[634] = {id=634, zh_CN="祁煜一耸肩，平静的脸上似乎能看出几分狡黠。", },
	[635] = {id=635, zh_CN="行啊，奉陪。", },
	[636] = {id=636, zh_CN="牵好手就算挑战开始，准备好了？", },
	[637] = {id=637, zh_CN="只手在我面前摊开，手心向上，仿佛无声地邀请。", },
	[638] = {id=638, zh_CN="奇怪，不是打赌吗？这个发展怎么有点……", },
	[639] = {id=639, zh_CN="我收拢发散的思维，果断牵起祁煜的左手。", },
