	[686] = {id=686, zh_CN="艳红如焰的细碎宝石屑，每粒裹着暖亮光泽，触之带微温的晶润质感，色泽浓烈得像凝住的焰火。", },
	[687] = {id=687, zh_CN="深紫如幽夜的细碎碎粒，泛着柔润暗哑光泽，触之温凉细腻，色泽里裹着隐约的朦胧光晕。", },
	[688] = {id=688, zh_CN="灿黄如鎏金的细碎颗粒，每粒闪着暖亮光泽，触之带清润晶质凉意，色泽鲜活得像揉碎的日光。", },
	[689] = {id=689, zh_CN="澄澈湛蓝的细碎宝石屑，切面泛着清透冷冽光泽，触之沁凉细腻，色泽像凝住的深涧幽蓝。", },
	[690] = {id=690, zh_CN="呈鲜翠碧色的细碎宝石颗粒，切面泛着清透冷光，捧在掌心时能觉出沁凉的晶质触感，色泽鲜亮惹眼。", },
