	[732] = {id=732, zh_CN="几根粗粝的木材，一团跃动的火焰，构成了文明最初的厨房。它散发着木材燃烧的噼啪声与令人安心的热度，是旅人、猎手与冒险者最忠实的伙伴。在这里，食物无需精致，饱含烟火气便是最高的赞誉。", },
	[733] = {id=733, zh_CN="一口厚重、漆黑的铁制大锅，常年悬挂在灶台之上。它见证过无数汤羹的沸腾与魔药的咕嘟，是融合与转化的象征。汤汁在其间循环翻滚，能将各种食材的滋味与功效完美地融为一体。", },
	[734] = {id=734, zh_CN="一个由砖石或金属构成的密封腔体，能够容纳并稳定地传导热量。它是面包师与甜品师的圣坛，门内是一个发生着美拉德反应与焦糖化反应的神奇世界，专门用于将生的希望变为熟的美味。", },
	[735] = {id=735, zh_CN="一台充满科技感或魔法光辉的精密仪器，通过控制温度、压力与化学反应，它能解构食材的本质并重组其形态。在这里，泡沫可以是肉味，液体可以变成鱼子酱，烹饪不再是手艺，而是魔法与科学的艺术。", },
