	[1010] = {id=1010, zh_CN="矿机采集", },
	[1011] = {id=1011, zh_CN="矿机采集、辉光矿精炼", },
	[1012] = {id=1012, zh_CN="一种在地下会发出轻微嗡鸣的奇异矿石，触手温暖。在黑暗中，它会散发出如同呼吸般柔和的脉动微光。据说只有内心平静的矿工才能完整地开采它", },
	[1013] = {id=1013, zh_CN="经过初步提炼，去除了大部分杂质的辉光矿。它的光芒变得更加稳定和明亮，可以被铸成标准的锭状。当你拿起它时，能隐约感觉到一种类似小猫打呼噜的、令人安心的轻微震动。", },
	[1014] = {id=1014, zh_CN="提炼辉光矿后剩下的残渣，但它们并非毫无用处！这些矿渣依然保留着微弱的光亮和余温，是制作廉价发光材料的完美材料。穷困的制作师们称它为 “不朽的余烬”。", },
	[1015] = {id=1015, zh_CN="与神奇的辉光矿相比，黑煤是如此朴实无华且枯燥。但它燃烧稳定、热量十足，是推动机器运转的可靠脊梁。老师傅们常说：“辉光矿能让你活得更好，但黑煤能让你活下去。”", },
	[1016] = {id=1016, zh_CN="一项需要耐心与运气的活儿。使用特制的包棉镐头小心敲击，以免惊扰矿石的 “睡眠”。成功时，矿石会温柔亮起作为回应；失败时，它只会留下一堆黯淡的碎石。矿工间流传着口诀：“轻拿轻放，辉光万丈；大力出奇迹，满地是垃圾。”", },
	[1017] = {id=1017, zh_CN="大师级矿工的标志。能在矿脉中精准分辨出每一块矿石的 “核心”，一击剥离，获得纯度最高的完整辉光矿。施展此技时，镐头会与矿石共鸣，发出风铃般的清脆声响。俗称 ——“矿脉手术刀”。", },
	[1018] = {id=1018, zh_CN="一门平衡的艺术。炉温过高，辉光会蒸发成无用的烟雾；温度不足，杂质又会污染金属。成功的冶炼过程中，整个炉子会透出如梦似幻的彩虹光晕，并飘散着淡淡的 “阳光味道”。失败时，则只会闻到刺鼻的烧焦味。", },
	[1019] = {id=1019, zh_CN="枯燥但至关重要的步骤。将大块优质煤、小块碎煤以及可恶的矸石分门别类。这项工作通常由学徒完成，以至于 “你去筛煤” 成了工匠之间对犯错者最常用的 “惩罚式安慰”。虽然又脏又累，但能让你真正理解什么叫 “脚踏实地”。", },
	[1020] = {id=1020, zh_CN="产自百年老藤的核心木料，韧性极佳且带有独特的螺旋纹路。散发着雨后森林般的清新气息。每个工匠都警告说：“小心处理，它偶尔会像活过来一样轻微扭动。”", },
	[1021] = {id=1021, zh_CN="从藤木中提炼出的琥珀色树脂，闻起来有蜂蜜和青草的味道。是优秀的天然粘合剂和香料定香剂，据说老练的药师能用它调出让人讲真话的药剂。", },
	[1022] = {id=1022, zh_CN="藤木受损凝结的树瘤，质地坚如铁且花纹绚丽，雕成饰品传有厄运抗性。新手需远离，未经净化的藤木瘤深夜会发出诡异叹息声。", },
	[1023] = {id=1023, zh_CN="藤木所开淡金色小花，是稀有炼金催化剂，花瓣如天鹅绒且无光自发光。服用可暂懂兽语，却会忍不住对着小松鼠花式夸赞半小时。", },
	[1024] = {id=1024, zh_CN="需要巧劲的技术活。必须顺着木材的天然纹理切割，否则藤木的纤维会锁住你的工具。成功的采集会收获一段完好无损的藤木，并伴随一阵令人心旷神怡的清风。", },
	[1025] = {id=1025, zh_CN="只有精通采集的大师才能施展。能在不伤及藤木生命本源的情况下，完美采集到最珍贵的藤木花或藤木瘤。施展时，工具会与藤木产生共鸣，周围甚至会有光点飘落。此技被誉为 “与森林的共舞”。", },
	[1026] = {id=1026, zh_CN="某个智能设备的 “大脑”，如今已停止思考。引脚上仍偶尔会迸发出一丝微弱的电火花，仿佛在回忆它曾经处理过的海量猫猫视频。", },
	[1027] = {id=1027, zh_CN="电子元件的城市废墟。精密的线路如同荒废的街道，电容和电阻像废弃的建筑般矗立，等待着被拆解和回收利用。", },
	[1028] = {id=1028, zh_CN="表壳凹陷，玻璃碎裂，时间在此定格。轻轻摇晃，里面的齿轮还会发出沙哑的 “咔哒” 声，似乎想努力地再走完最后一秒。", },
	[1029] = {id=1029, zh_CN="边缘已经崩坏，但中心区域依然惊人地光滑。透过它看东西会产生奇妙的扭曲和色散，或许能用来聚焦阳光或者窥探一些不寻常的角落。", },
	[1030] = {id=1030, zh_CN="在废料堆中翻找有价值部件的入门技能。需要一副厚手套以防割伤，以及对各种金属和塑料的初步分辨能力。俗称 “捡垃圾”。", },
	[1031] = {id=1031, zh_CN="高级回收技术。能使用专业工具无损拆解废弃电器，安全取出价值最高的废弃芯片和稀有元件，同时避免触发任何残留的电荷。", },
	[1032] = {id=1032, zh_CN="带着原始气息的鞣制皮革，表面粗糙但韧性十足。隐约还能看到野兽的轮廓和几道象征勇气的爪痕，是制作探险家基础装备的可靠材料。", },
	[1033] = {id=1033, zh_CN="一团蓬松柔软的白色絮状物，触感温暖如阳光。产自一种只在夜间开花的奇幻植物，是制作高级衣物和填充物的上等材料，自带淡淡的安神香气。", },
	[1034] = {id=1034, zh_CN="辉光结晶由辉光矿精华凝结而成，散发柔和稳定光芒，具“记忆塑性”可徒手塑形并维持形态，是工匠与创客渴求的魔法黏土。", },
	[1035] = {id=1035, zh_CN="一种在贫瘠土地也能顽强生长的谷物，麦穗短小但颗粒饱满，带着独特的坚果香气。是灾荒年代里最能给人安全感的粮食。", },
	[1036] = {id=1036, zh_CN="外皮粗糙厚实得像一层盔甲，能有效锁住水分。内里的土豆泥却异常绵软香甜，是长途旅行中可靠的淀粉来源，需要用小刀撬开才能享用。", },
	[1037] = {id=1037, zh_CN="生长在岩石缝隙中的块茎，外形不规则且沾满泥土。虽然其貌不扬，但烤熟后会散发混合了泥土与焦糖的奇异香气，口感粉糯扎实，抗饿能力一流。", },
	[1038] = {id=1038, zh_CN="栖息于浑浊泥塘中的小型淡水虾，通体呈保护色般的灰褐色。虽然个头小，但肉质紧实弹牙，带有独特的清甜，是炖汤提鲜的秘密武器。", },
	[1039] = {id=1039, zh_CN="来自巨大向日葵的花盘，颗粒饱满。可直接炒制为香脆的零食，也能榨出清亮芳香的食用油，是废土之上难得的快乐源泉。", },
	[1040] = {id=1040, zh_CN="实验室出品的蛋白质块，通过植物纤维和风味物质合成。口感与真肉惊人相似，营养均衡，但总让人觉得缺少了那么一点 “灵魂”。标签上写着：本品富含真情实感。", },
	[1041] = {id=1041, zh_CN="紧紧附着在岩石表面生长的苔藓类植物，颜色灰绿。味道苦涩且带有矿物味，是绝境中充饥的最后手段，需要反复冲洗和烹煮才能入口。", },
	[1042] = {id=1042, zh_CN="在浑浊池塘中长大的小型鱼类，鳞片暗淡，总带着一丝若有若无的土腥味。但细心处理后，其细嫩的肉质能慰藉许多匮乏的味蕾。", },
	[1043] = {id=1043, zh_CN="由黑麦研磨而成的灰褐色面粉，质地略微粗糙，但麦香味浓郁。是制作黑面包、厚饼等扎实主食的基础，承载着生存的厚重感。", },
	[1044] = {id=1044, zh_CN="漂浮在静水水面上的绿色藻类，繁殖极快。晒干后可磨成粉作为饲料或肥料，在某些食谱中被誉为 “绿色的奇迹”，有淡淡的海洋气息。", },
	[1045] = {id=1045, zh_CN="从盐田或岩矿中直接获取的结晶，颗粒粗大，咸味中夹杂着矿物的凛冽感。是防腐与调味的基础，也是生命不可或缺的物质。", },
	[1046] = {id=1046, zh_CN="由黑麦芽发酵而成的褐色液体，酸味醇厚柔和，带有独特的麦香。能有效去除腥味并软化纤维，是烹饪中点石成金的关键一滴。", },
	[1047] = {id=1047, zh_CN="用黑麦熬制出的粘稠糖浆，颜色深近漆黑，味道焦苦中带着一丝微甜。是废土上珍贵的能量来源和安慰剂，常被抹在粗面包上食用。", },
	[1048] = {id=1048, zh_CN="从向日葵籽中榨取的清亮油脂，带着淡淡的坚果香气。烟点较高，非常适合煎炒，能为单调的食物增添难得的风味与油脂香气。", },
	[1049] = {id=1049, zh_CN="并非花椒果实，而是其植株的叶片，气味清香而带有轻微的麻涩感。常用于炖煮汤水以增添风味层次，是去腥提味的低调配角。", },
	[1050] = {id=1050, zh_CN="从相对干净的池塘或蓄水池中取得的水源，经过简单沉淀和过滤。虽然仍带有一丝土腥味，但已是维持日常生存的宝贵液体。", },
	[1051] = {id=1051, zh_CN="黄铜外壳上布满划痕，但依旧能精准报时。按下按钮打开表盖，可以看到细小的齿轮仍在不知疲倦地转动，表盖内侧藏着一张泛黄的旧照片。", },
	[1052] = {id=1052, zh_CN="黄铜制成的可伸缩式望远镜，镜片略有磨损但依然能清晰望远。筒身上布满了使用留下的细微划痕，是探险家必备的实用工具。", },
	[1053] = {id=1053, zh_CN="一把看似普通但设计精妙的扳手，可以通过调节卡扣来适应各种尺寸的螺母。是机械师的最爱，敲击厚重物体时还会发出令人安心的沉闷声响。", },
	[1054] = {id=1054, zh_CN="表面粗糙暗淡的银块，像是蒙上了一层灰尘，需要进一步提炼才能显现金属光泽。", },
	[1055] = {id=1055, zh_CN="银矿研磨后留下的灰色细沙，闪烁着微弱的金属光泽，是提炼其他金属时常见的副产品。", },
	[1056] = {id=1056, zh_CN="经过初步提炼的银块，表面呈现出水波般的沁色纹路，触手冰凉，是制作附魔器物的基础材料。", },
	[1057] = {id=1057, zh_CN="棱角分明的绿色碎晶，内部含有絮状杂质，在光线下会折射出细碎的闪光。", },
	[1058] = {id=1058, zh_CN="如同凝固血液般的红色碎片，虽然体积小但色彩浓烈，自带微弱的热量。", },
	[1059] = {id=1059, zh_CN="散发着神秘光泽的紫色碎片，从不同角度观察会呈现由蓝到红的渐变色彩。", },
	[1060] = {id=1060, zh_CN="宛如琥珀般温润的黄色碎块，内部常常包裹着奇特的气泡或金色纹路。", },
	[1061] = {id=1061, zh_CN="如同深海碎片般的蓝色结晶，透光时会显现出雪花般的天然纹路。", },
	[1062] = {id=1062, zh_CN="在矿脉中寻找并采集沁银矿石的基础技能，需要熟练使用矿镐和辨识矿脉的能力。", },
	[1063] = {id=1063, zh_CN="能够完整采集沁银矿核心的高级技巧，可最大程度保留矿石的完整性和能量。", },
	[1064] = {id=1064, zh_CN="将采集到的沁银矿石通过特殊熔炼技术提纯的过程，需要精准控制火候和时间。", },
	[1065] = {id=1065, zh_CN="将各种宝石碎片按品质、属性和大小进行分类的专业技能，需要敏锐的眼力和耐心。", },
	[1066] = {id=1066, zh_CN="质地坚硬如铁的罕见树枝，表面有天然的金属纹路，敲击时会迸发火星，是制作高级弓弩的核心材料。", },
	[1067] = {id=1067, zh_CN="在铁木顶端绽放的银灰色花朵，花瓣薄如金属片，会释放淡淡的燃油气味，是提炼挥发油的重要原料。", },
	[1068] = {id=1068, zh_CN="从铁木树干中渗出的黑色粘稠汁液，被称为 “树中石油”，极易燃烧且能量密度高，是工业文明的血液。", },
	[1069] = {id=1069, zh_CN="使用特制工具砍伐铁木的基础技术，需要极大的力量才能在其坚硬如铁的树干上留下有效切口。", },
	[1070] = {id=1070, zh_CN="通过寻找铁木天然纹理弱点进行切割的高级技术，能够高效获取完整枝干并最大化保留树汁。", },
	[1071] = {id=1071, zh_CN="从废弃电子设备中拆解出的基础功能模块，虽然型号老旧但结构完整，是维修和组装电路的基础。", },
	[1072] = {id=1072, zh_CN="一种高度集成的微型处理单元，表面有复杂的金色电路纹路，是智能设备进行逻辑运算的核心。", },
	[1073] = {id=1073, zh_CN="能够稳定存储和释放电荷的蓝色元件，表面标有清晰的容量参数，是保证电路稳定运行的关键。", },
	[1074] = {id=1074, zh_CN="在电子垃圾堆中系统性拆解和回收可用元件的技术，需要防静电设备和基本的电路知识。", },
	[1075] = {id=1075, zh_CN="使用精密工具从特定设备上无损拆解高价值元件的专业技术，可完美获取完好的逻辑晶片和稳定电容。", },
	[1076] = {id=1076, zh_CN="将沁银块反复锻打去除杂质后得到的标准银锭，表面有如水波流动的光泽，是制作高级饰品和附魔道具的基底材料。", },
	[1077] = {id=1077, zh_CN="从温顺的咩咩羊身上梳理得到的柔软绒毛，纤维细长且富有弹性，纺成的线料带有天然的暖意和阳光的气息。", },
	[1078] = {id=1078, zh_CN="产自深海贝类的浑圆珍宝，表面光滑并泛着独特的虹彩光泽，是制作奢华饰品和高级魔法媒介的珍贵材料。", },
	[1079] = {id=1079, zh_CN="一种产自特殊蜂巢的粘稠蜜糖，具有极佳的可塑性和延展性，常用于调和药剂或作为魔法符文绘制的导能介质。", },
	[1080] = {id=1080, zh_CN="菜啾啾掉落的一种干枯绒毛，嘎嘣脆，鸡肉味。", },
	[1081] = {id=1081, zh_CN="清晨凝结在叶片上的纯净水珠，富含自然灵气，是炼制低级药剂和培育珍稀植物的基础素材。", },
	[1082] = {id=1082, zh_CN="如同珍珠般圆润饱满的半透明葡萄，果肉清脆甘甜，在月光下会泛起柔和微光。", },
	[1083] = {id=1083, zh_CN="生长在灌木丛中的红色浆果，口感酸甜，是野外常见的充饥零嘴。", },
	[1084] = {id=1084, zh_CN="从温顺奶牛身上获取的白色乳汁，富含营养，散发着淡淡的乳香。", },
	[1085] = {id=1085, zh_CN="形状酷似齿轮的变异土豆，淀粉含量极高，烤熟后会有淡淡的机油香味。", },
	[1086] = {id=1086, zh_CN="色泽鲜红诱人的圆形果实，口感爽脆多汁，是广受欢迎的基础水果。", },
	[1087] = {id=1087, zh_CN="颗粒饱满的金黄色玉米，顶端长着褐色胡须般的穗丝，蒸煮后散发浓郁谷物香气。", },
	[1088] = {id=1088, zh_CN="外形圆润光滑的红色果实，富含番茄红素，酸甜多汁且营养丰富。", },
	[1089] = {id=1089, zh_CN="夜间会发出柔和黄光的灯笼状果实，既能食用又能充当临时光源，折断果柄会触发短时强光。", },
	[1090] = {id=1090, zh_CN="颗粒圆润饱满的黄色豆子，富含蛋白质和油脂，可榨取豆浆或培育成豆芽，是重要的基础农作物。", },
	[1091] = {id=1091, zh_CN="表皮光滑的亮紫色长茄，肉质松软细腻，适合多种烹饪方式。", },
	[1092] = {id=1092, zh_CN="从咩咩羊身上挤出的浓郁乳汁，带有独特的青草香气，是制作优质奶酪的原料。", },
	[1093] = {id=1093, zh_CN="清澈的水池中采集来的池水，带有清香的气息，可以烹饪面食", },
	[1094] = {id=1094, zh_CN="洁白饱满的米粒，带着淡淡的清香。煮熟后柔软粘糯，是维持日常能量的主要粮食，被誉为 “餐桌上的珍珠”。", },
	[1095] = {id=1095, zh_CN="从岩盐矿中直接开采的粗大结晶，咸味纯正强烈，是烹饪中不可或缺的基础调味品。", },
	[1096] = {id=1096, zh_CN="由蜜蜂采集花蜜酿成的金黄粘稠液体，味道甘甜并带有独特的花香，是天然的甜味剂。", },
	[1097] = {id=1097, zh_CN="晒干后的黑色胡椒颗粒，带有独特的辛辣香气，研磨后能极大提升菜肴的风味层次。", },
	[1098] = {id=1098, zh_CN="由黄豆发酵制成的深褐色液体调味品，咸鲜味浓郁，能为食物增添深邃的复合滋味。", },
	[1099] = {id=1099, zh_CN="虽然机身已有划痕，却记录过无数珍贵影像，承载着时光的厚度。", },
	[1100] = {id=1100, zh_CN="纸张微黄的经典旋律，指尖滑过，仿佛有旧日音符在空气中流淌。", },
	[1101] = {id=1101, zh_CN="一条链子几乎断裂的旧项链，吊坠是半块心形金属，边缘已被磨得光滑，似乎曾被某人长久紧握。", },
	[1102] = {id=1102, zh_CN="开采矿石时产生的灰色碎石，质地粗糙，是铺设道路或制作混凝土的基础材料。", },
	[1103] = {id=1103, zh_CN="由泥土和水混合后晒干形成的硬块，结构松散，可用于制作简易的土坯或填充材料。", },
	[1104] = {id=1104, zh_CN="从金矿中提炼出的细小金色颗粒，闪烁着耀眼的光芒。", },
	[1105] = {id=1105, zh_CN="通体翠绿的无瑕宝石，内部纯净剔透，在光线下会折射出迷人的绿光，是顶级的工艺原料。", },
	[1106] = {id=1106, zh_CN="色泽浓郁如鸽血的正红色宝石，内部有火焰般的流动光泽，象征着热情与力量。", },
	[1107] = {id=1107, zh_CN="散发着神秘光晕的深紫色晶体，在不同角度下会呈现星空般的色彩变幻，极具魔法亲和力。", },
	[1108] = {id=1108, zh_CN="色泽明亮如阳光的透明宝石，内部常带有独特的金色纹理，给人以温暖愉悦的感觉。", },
	[1109] = {id=1109, zh_CN="如同深海般湛蓝的纯净晶体，内部有波浪状的光学效应，常被镶嵌于王冠或圣器之上。", },
	[1110] = {id=1110, zh_CN="在矿脉中识别并挖掘含金矿石的基础工作，需要敏锐的眼力和持久的体力，是获取财富的第一步。", },
	[1111] = {id=1111, zh_CN="使用特制工具剥离矿石与杂质的高超技巧，能最大限度地保持金矿的完整性，避免资源浪费。", },
	[1112] = {id=1112, zh_CN="通过高温熔炼和化学处理从矿石中提取纯金的过程，需要精准控制温度和时间，以获得高纯度金锭。", },
	[1113] = {id=1113, zh_CN="将各类宝石原石按色泽、净度、大小进行分级的手艺，需要丰富的经验和敏锐的直觉，以判断其真正价值。", },
	[1114] = {id=1114, zh_CN="散发着柔和绿光的奇异木材，触手温润仿佛带有生命，是顶级的木材。", },
	[1115] = {id=1115, zh_CN="生长在生命树顶端的金色果实，蕴含强大的自然能量，食用后可暂时获得与动物沟通的能力。", },
	[1116] = {id=1116, zh_CN="从精灵果中提炼出的透明胶状物质，具有强大的愈合特性，是制作高级恢复药剂的关键成分。", },
	[1117] = {id=1117, zh_CN="从生命树树干中采集的莹绿色汁液，散发着清新的草木香气，能促进植物生长并净化污染。", },
	[1118] = {id=1118, zh_CN="在古老森林中安全砍伐魔法树木的专业技能，需要掌握与自然灵体沟通的特殊仪式。", },
	[1119] = {id=1119, zh_CN="通过精确切割魔法树木的能量节点来获取完美材料的秘传技艺，只有受到森林祝福者才能掌握。", },
	[1120] = {id=1120, zh_CN="纯度达到 99999% 的透明硅晶体，表面呈现规则的几何棱面，是制作高级逻辑芯片的基础材料。", },
	[1121] = {id=1121, zh_CN="表面蚀刻着精密金色电路的微型元件，能在低能耗下高效处理复杂信号，是精密设备的核心部件。", },
	[1122] = {id=1122, zh_CN="一个被封装在透明外壳中的蓝色发光立方体，能够稳定输出高密度能量，常用于驱动重型机械或武器系统。", },
	[1123] = {id=1123, zh_CN="封装在镀金外壳中的多层处理器，能够进行高速并行计算和自主学习，是高级人工智能的思维中枢。", },
	[1124] = {id=1124, zh_CN="使用特制振动工具开采硅质矿层的标准作业，需要严格控制力度以避免破坏晶体结构。", },
	[1125] = {id=1125, zh_CN="通过微振动波探测硅晶矿脉内部结构的先进技术，能完整剥离出大尺寸的高纯度硅晶。", },
	[1126] = {id=1126, zh_CN="将耀金碎块熔炼提纯后浇铸成的标准金锭，表面流光溢彩，是顶级的工艺材料。", },
	[1127] = {id=1127, zh_CN="由月光蚕丝织就的银白色丝绸，触感冰凉柔滑，在暗处会自然浮现出如月晕般的柔和光晕，是极品布料。", },
	[1128] = {id=1128, zh_CN="一种层层包裹的球形蔬菜，叶片脆嫩多汁，剥开时总会发出欢快的“噗噗”声。", },
	[1129] = {id=1129, zh_CN="身体扁平如圆盘的深海鱼，两只眼睛长在同一侧，游动时像一张飘动的烙饼。", },
	[1130] = {id=1130, zh_CN="粗壮如成人手臂的乌贼触须，表面布满吸盘，烤制后会散发出浓郁的海鲜焦香。", },
	[1131] = {id=1131, zh_CN="成熟时果皮会自然裂开形成笑脸纹路的番茄，据说吃到甜度最高的那个能让人开心一整天。", },
	[1132] = {id=1132, zh_CN="表皮光滑如镜的奇异水果，能模糊映照出人影，果肉透明如水，口感清脆冰凉。", },
	[1133] = {id=1133, zh_CN="叶片轻薄如羽毛的草药，风拂过时会发出悦耳的沙沙声，是制作轻身药剂的原料。", },
	[1134] = {id=1134, zh_CN="一种在水中会发出细微嗡鸣声的海藻，采集时仿佛在聆听一首古老的海洋之歌。", },
	[1135] = {id=1135, zh_CN="外壳刻满神秘螺纹的豆子，种下后会长出意想不到的植物，可能是藤蔓也可能是弹簧。", },
	[1136] = {id=1136, zh_CN="生长时会发出轻微“锵锵”金属碰撞声的生姜，辣味强烈而独特，是驱寒佳品。", },
	[1137] = {id=1137, zh_CN="晒干后点燃会释放出彩色烟雾的果实，不同颜色的烟雾带有不同的安神或提神效果。", },
	[1138] = {id=1138, zh_CN="通体银白如月光的小鱼，鳞片会随月光强度变换明暗，是月夜垂钓的稀有收获。", },
	[1139] = {id=1139, zh_CN="身体坚硬如石板的海鱼，移动缓慢，需要用锤子敲开外壳才能享用其鲜美的鱼肉。", },
	[1140] = {id=1140, zh_CN="表面布满星星状斑点的紫色茄子，烤制后斑点会变成金黄色，如同夜空中的星座。", },
	[1141] = {id=1141, zh_CN="外形酷似苹果的海洋生物，咬开薄壳后是甘甜的半透明果冻状肉质，带有海盐风味。", },
	[1142] = {id=1142, zh_CN="粘稠得几乎能拉丝的超浓缩糖浆，一小滴就足以让整个蛋糕甜到发齁，是甜食爱好者的终极武器。", },
	[1143] = {id=1143, zh_CN="从极寒之地采集的魔法霜晶，入口即化并释放出温和的凉意与甘甜，不会融化且零热量。", },
	[1144] = {id=1144, zh_CN="装在喷雾瓶中的神奇液体，向空中喷洒后可暂时改变周围空气的味道，常见口味有雨后青草、篝火晚会等。", },
	[1145] = {id=1145, zh_CN="闪烁着荧光粉紫色的调味酱，味道会在草莓、蓝莓和泡泡糖之间随机变幻，深受小朋友和派对动物喜爱。", },
	[1146] = {id=1146, zh_CN="从“报晓鸡”羽毛中提取的鲜味精华，只需撒上少许就能让清汤拥有熬煮数小时的浓郁口感。", },
	[1147] = {id=1147, zh_CN="产自火山地区的特辣辣椒，晒干后表面会形成龙鳞状纹路，食用后喷出的气息能短暂点燃蜡烛。", },
	[1148] = {id=1148, zh_CN="表面分布着金黄色美味斑点的发酵奶酪，斑点越多代表熟成度越高，风味也越发浓郁醇厚。", },
	[1149] = {id=1149, zh_CN="在古木桶中陈化十年的特制酱油，色泽深沉如墨，滴入水中会呈现优美的琥珀色晕染，鲜味层次极其复杂。", },
	[1150] = {id=1150, zh_CN="一个看似空无一物的织布梭，只在月光下显现银线，使用者会坚信自己正在编织最华美的布料。隐喻着虚荣与自我欺骗的经典寓言。", },
	[1151] = {id=1151, zh_CN="缠绕着暗红色丝线的古银纺锤，触碰者会立刻陷入短暂的预言梦境，醒来时指尖残留着刺痛的灼热感。隐喻着命运不可抗拒的古老禁忌。", },
	[1152] = {id=1152, zh_CN="木制的小匕首，造型帅气却毫无攻击性，是勇气与童心的勋章。", },
	[1153] = {id=1153, zh_CN="在古战场遗迹生长的暗紫色野草，叶片会无风自动，轻轻触碰能听到细微的啜泣声。", },
	[1154] = {id=1154, zh_CN="只在月圆之夜成熟的银色稻谷，谷穗会自然发出柔和微光，需用玉镰刀收割方能保持灵性。", },
	[1155] = {id=1155, zh_CN="生长在悬崖云雾带的半透明蘑菇，采摘后三小时内会逐渐蒸发，仅留下淡淡的花香。", },
	[1156] = {id=1156, zh_CN="叶片上布满类似脑回路的纹路，咀嚼后能短暂增强记忆力，但会随机遗忘一段童年回忆。", },
	[1157] = {id=1157, zh_CN="夜间会发出幽蓝光晕的伞状蘑菇，光照强度随周围声音变化，在吵闹处会变得像灯泡般明亮。", },
	[1158] = {id=1158, zh_CN="同时存在于多条溪流中的虹色小鱼，观察其游动轨迹可能导致它突然消失并出现在另一水域。", },
	[1159] = {id=1159, zh_CN="银月稻去壳后的米粒，保留着月华凝练的银辉，煮熟后每粒米都会浮现不同的星座图案。", },
	[1160] = {id=1160, zh_CN="生长在灵石表面的耳状蕈类，质地如玉石般坚硬，需研磨成粉方能释放其土系灵力。", },
	[1161] = {id=1161, zh_CN="由星纹蜂采集银河花粉酿成的琥珀色蜜糖，每滴都包含细微的星芒，甜味中带着宇宙的深邃。", },
	[1162] = {id=1162, zh_CN="用纯金捶打出的蝉翼薄片，加入食物会绽放华丽金光，本身无味但能提升用餐的仪式感。", },
	[1163] = {id=1163, zh_CN="从万丈海沟采集的立方体盐晶，溶解时会产生类似鲸歌的低频波动，咸味中带着深海的神秘。", },
	[1164] = {id=1164, zh_CN="结晶时自然形成笑脸图案的方糖，含在口中会激发多巴胺分泌，但效果过后会产生轻微的空虚感。", },
	[1165] = {id=1165, zh_CN="表面总是凝结着露珠的灰色盐粒，会让食物染上淡淡的苦涩，常被炼金师用作情绪抑制剂的基底。", },
	[1166] = {id=1166, zh_CN="酿造时需要不停搅拌的黑色酱油，使用后会陷入“刚才是否锁门”的反复确认，但鲜味确实出众。", },
	[1167] = {id=1167, zh_CN="用未成熟青梅酿造的陈醋，瓶盖开启时有轻微爆鸣声，调味时稍过量就会让食客产生摔碗的冲动。", },
	[1168] = {id=1168, zh_CN="愤怒醋", },
	[1169] = {id=1169, zh_CN="将合成肉排与调味粉末放入自热盒中，一分钟即可食用的便携餐品。", },
	[1170] = {id=1170, zh_CN="将岩板鱼煮到鱼眼发白就完成的简陋汤品。", },
	[1171] = {id=1171, zh_CN="用水调和预拌粉后压扁制成的生存饼干，带着淡淡的焦糊味。", },
	[1172] = {id=1172, zh_CN="将牛奶与预熟米粒混合的即食粥品，需要静置三分钟让米粒膨胀，适合没有咀嚼欲望的清晨。", },
	[1173] = {id=1173, zh_CN="将所有速制食材切块后混入沸水的懒人料理，每勺都能舀到意想不到的食材组合。", },
	[1174] = {id=1174, zh_CN="将土豆泥粉与奶粉混合后塑形的即食土豆团，口感绵密得像在咀嚼云朵，带着不真实的奶香。", },
	[1175] = {id=1175, zh_CN="用喷枪快速炙烤的乌贼腿切片，边缘卷曲焦香，内部保持刺身级嫩滑，配柠檬汁可去除腥气。", },
	[1176] = {id=1176, zh_CN="将月光银鱼用果木冷熏制成的银鱼干，鱼身呈琥珀色，肉质紧实有嚼劲，带着淡淡的烟熏甜香。", },
	[1177] = {id=1177, zh_CN="将海苹果切片后自然风干的透明果脯，表面撒有细海盐结晶，嚼起来咯吱作响，海洋风味浓郁。", },
	[1178] = {id=1178, zh_CN="日常", },
