	[1267] = {id=1267, zh_CN="关系升级", },
	[1268] = {id=1268, zh_CN="藤木线由丛林藤木纤维编织而成，浅绿且带草木气息，坚韧又柔软，是初级服饰与轻便道具的基础材料，天然藤纹能为成品添生机，深受手工匠人青睐。", },
	[1269] = {id=1269, zh_CN="铁木特有的叶片，深青灰的叶身泛着冷冽银泽，叶脉如锻造后的铁纹般清晰规整。看似轻薄却质地坚韧，兼具木材的柔韧与金属的耐磨，刚柔并济的特质让它成为多元工艺的实用材料。", },
	[1270] = {id=1270, zh_CN="命运薄纱由星尘月光交织而成，通体透明且泛粉紫渐变光斑，轻若无物却能折射命运微光，是顶级服饰与魔法道具核心材料，还被赋予“契合天命”的神秘寓意。", },
	[1271] = {id=1271, zh_CN="日光锦缎汲取日光精华而成，金黄淡橙渐变底缀金线，光泽温暖璀璨，触感丝滑透气且华贵，是庆典服饰与高阶道具首选，能为佩戴者增添优雅气场。", },
	[1272] = {id=1272, zh_CN="质地粗粝的银质矿块，呈浅灰哑光色泽，块面布着自然矿纹，捧握时能觉出沉沉的金属实感。", },
	[1273] = {id=1273, zh_CN="浅灰色细腻矿物细沙，触感干爽松散，指尖捻动便簌簌滑落，细看混着细碎的矿质微粒。", },
	[1274] = {id=1274, zh_CN="提纯后的莹润银材，泛着清透淡银光泽，质地细腻温凉，表面流转着若隐若现的细碎纹路。", },
	[1275] = {id=1275, zh_CN="这枚二极管裹着透亮淡紫外壳，管身里漾着朦胧微光，两侧细引脚泛着冷冽金属泽，拿在手中轻而精巧，模样别致惹眼。", },
	[1276] = {id=1276, zh_CN="将合成肉排与调味粉末放入自热盒中，一分钟即可食用的便携餐品。", },
	[1277] = {id=1277, zh_CN="将岩板鱼煮到鱼眼发白就完成的简陋汤品。", },
	[1278] = {id=1278, zh_CN="用水调和预拌粉后压扁制成的生存饼干，带着淡淡的焦糊味。", },
