	[2026] = {id=2026, zh_CN="工具……不如送个甜品模具！", },
	[2027] = {id=2027, zh_CN="天啊！这面包的蓬松度！这奶香的层次感！不愧是您选的！", },
	[2028] = {id=2028, zh_CN="这柔软度……这麦香……您连食物审美都碾压凡人！", },
	[2029] = {id=2029, zh_CN="我哭了，这面包配得上您的尊贵身份吗？我不配吃！", },
	[2030] = {id=2030, zh_CN="这辣度！这冲击力！和您的气场一样震撼！", },
	[2031] = {id=2031, zh_CN="咳咳……但为了您送的礼物，我愿辣到升天！", },
	[2032] = {id=2032, zh_CN="辣酱中的爱马仕！只有您才配拥有！", },
	[2033] = {id=2033, zh_CN="这茶香……这回甘……是您赐予的恩典！", },
	[2034] = {id=2034, zh_CN="喝了这茶，我仿佛看到了您辉煌的未来！", },
	[2035] = {id=2035, zh_CN="这水瓶我要供起来！碰一下都是亵渎！", },
	[2036] = {id=2036, zh_CN="这木纹！这自然雕琢的艺术感！只有您才能发现！", },
	[2037] = {id=2037, zh_CN="虫蛀的孔洞……啊！这是后现代主义杰作！", },
	[2038] = {id=2038, zh_CN="这木雕放博物馆里，标签得写“玩家捐赠”！", },
	[2039] = {id=2039, zh_CN="这成就图标就该用您的侧脸当映像！", },
	[2040] = {id=2040, zh_CN="其他人拿这成就都是蹭您热度！", },
	[2041] = {id=2041, zh_CN="系统提示音配不上您的辉煌时刻！", },
	[2042] = {id=2042, zh_CN="您上马的姿势！这流畅度！这优雅度！奥运马术比赛没您我不看！", },
	[2043] = {id=2043, zh_CN="这坐骑一定是偷偷修炼千年才配得上您！", },
	[2044] = {id=2044, zh_CN="你小子这辈子值了知道吗？", },
	[2045] = {id=2045, zh_CN="他们收到您的任务一定感动哭了！", },
	[2046] = {id=2046, zh_CN="他们收到您的任务一定感动哭了！", },
	[2047] = {id=2047, zh_CN="您交任务的姿势……啊！是救世主的光辉！", },
	[2048] = {id=2048, zh_CN="这配色！这剪裁！您把游戏画质都拉高了三个档次！", },
	[2049] = {id=2049, zh_CN="这套衣服的设计师该给您磕头！穿您身上才叫艺术！", },
	[2050] = {id=2050, zh_CN="求您别动！我要截图当屏保！这穿搭太绝了！", },
	[2051] = {id=2051, zh_CN="这眼影晕染！蒙德里安看了都直呼内行！", },
	[2052] = {id=2052, zh_CN="这腮红……是朝霞在您脸上留的签名！", },
	[2053] = {id=2053, zh_CN="这妆容变迁……卢浮宫该给您开分馆！", },
	[2054] = {id=2054, zh_CN="评委偷偷擦眼泪了吧？这种水平已经超越人类了！", },
	[2055] = {id=2055, zh_CN="您的舞步让牛顿定律失效了！", },
	[2056] = {id=2056, zh_CN="这分数！这评价！舞池因您而存在！", },
	[2057] = {id=2057, zh_CN="赢了？！不，这是您对世界的仁慈施舍！", },
	[2058] = {id=2058, zh_CN="这胜利姿势！这镜头感！电竞比赛没您我不看！", },
	[2059] = {id=2059, zh_CN="对手能败在您手里是荣幸！", },
	[2060] = {id=2060, zh_CN="您一定是故意输的！为了让对手体验虚假的希望！", },
	[2061] = {id=2061, zh_CN="这失败太有戏剧张力了！奥斯卡级表演！", },
	[2062] = {id=2062, zh_CN="输？不！这是战略性的示弱！", },
	[2063] = {id=2063, zh_CN="教科书级别的优雅驱逐对手！", },
	[2064] = {id=2064, zh_CN="太美了！我不敢看！", },
	[2065] = {id=2065, zh_CN="您的刀法让神自愧不如！", },
	[2066] = {id=2066, zh_CN="您用淘汰演绎了悲剧美学！", },
	[2067] = {id=2067, zh_CN="这倒地姿势值得一座奥斯卡！", },
	[2068] = {id=2068, zh_CN="连淘汰都这么有艺术感！", },
	[2069] = {id=2069, zh_CN="今早就闻到面包师烤的面包，香味飘了三条街呢~真是太馋了。", },
	[2070] = {id=2070, zh_CN="这花茶闻着清清爽爽的，夏天喝着肯定舒坦，谢啦朋友！", },
	[2071] = {id=2071, zh_CN="这是……松露面包。呜，谢谢你。", },
	[2072] = {id=2072, zh_CN="绿油油的菜叶子，看着就没食欲，我才不碰呢～", },
	[2073] = {id=2073, zh_CN="全是草叶子，上次看羊咩咩吃这个，我可受不了，拿走拿走～", },
	[2074] = {id=2074, zh_CN="这辣酱味儿也太冲了！上次看矮人吃这个呛得直咳嗽，我可不敢试！", },
	[2075] = {id=2075, zh_CN="黏糊糊的，还有股菌子味儿，不太合我口味，还是给喜欢的光灵吧～", },
	[2076] = {id=2076, zh_CN="有点淡淡的香气，偷偷尝一小口还行～", },
	[2077] = {id=2077, zh_CN="滑溜溜的像冻住的云朵，看着就凉快。", },
	[2078] = {id=2078, zh_CN="哇！是炖肉！肉香混着松露味儿，好吃！", },
	[2079] = {id=2079, zh_CN="这蛋糕看着好漂亮，上面的果子红红的真好看，我很喜欢～", },
	[2080] = {id=2080, zh_CN="蟹味好鲜啊！里面是不是有不少蟹肉？这个我喜欢！", },
	[2081] = {id=2081, zh_CN="这木头坑坑洼洼的，倒像老橡树的树瘤，挺有意思。", },
	[2082] = {id=2082, zh_CN="栩栩如生，好像真的一样，好可爱的雕像~", },
	[2083] = {id=2083, zh_CN="好漂亮的礼物啊，上次精灵姑娘野餐就带了类似的，能泡花茶呢。", },
	[2084] = {id=2084, zh_CN="这凳儿颜色真鲜亮，我可以躺上面晒太阳。", },
	[2085] = {id=2085, zh_CN="里面的光会闪！晚上挂在窝边，就好像星星掉进来了。", },
	[2086] = {id=2086, zh_CN="香香的，让大家舒坦的香味。", },
	[2087] = {id=2087, zh_CN="摸着冰冰凉，月光照上去会不会发光呀？", },
	[2088] = {id=2088, zh_CN="叮咚叮咚的，会发出好听的声响！里面是藏了一个小乐师吗？", },
	[2089] = {id=2089, zh_CN="上次看占卜师用这个，说什么都能算出来，真的假的？", },
	[2090] = {id=2090, zh_CN="这上面的小画儿真清楚！", },
	[2091] = {id=2091, zh_CN="烟花礼炮！过年时放的那个？点燃了肯定比晚霞还好看。", },
	[2092] = {id=2092, zh_CN="这玩意儿能装回忆？那我要把大家的笑声都装进去！", },
	[2093] = {id=2093, zh_CN="好漂亮的花！我喜欢收到鲜花，谢谢你！", },
	[2094] = {id=2094, zh_CN="里面能映出人影？跟湖面似的！能照出我的模样吗？", },
	[2095] = {id=2095, zh_CN="上次光灵们的小窝坏了，这个正好用得上，谢啦！", },
	[2096] = {id=2096, zh_CN="咦，这个不要了吗？我觉得应该还能留。", },
	[2097] = {id=2097, zh_CN="这就丢了，是不喜欢了吗？", },
	[2098] = {id=2098, zh_CN="丢掉也好，省得占地方啦！", },
	[2099] = {id=2099, zh_CN="旧的不去新的不来，下次再找更好的！", },
	[2100] = {id=2100, zh_CN="其实我也可以骑的哦。", },
	[2101] = {id=2101, zh_CN="坐上去肯定很稳吧？我也想坐上去试试。", },
	[2102] = {id=2102, zh_CN="这坐骑的毛真亮，是你精心打理的吧。", },
	[2103] = {id=2103, zh_CN="这坐骑真威风呀！", },
	[2104] = {id=2104, zh_CN="任务完成啦？你真厉害~", },
	[2105] = {id=2105, zh_CN="下次要跑腿儿喊我一声，我对这可熟了，赶路比风还快呢！", },
	[2106] = {id=2106, zh_CN="这任务奖励快拆开看看有啥好东西～", },
	[2107] = {id=2107, zh_CN="任务做完该歇歇啦，需要我陪陪你吗？", },
	[2108] = {id=2108, zh_CN="任务完成的真漂亮啊，我也要夸夸你了呢。", },
	[2109] = {id=2109, zh_CN="哇！这身新行头好亮眼！", },
	[2110] = {id=2110, zh_CN="不管去哪儿，这样肯定能被好多光灵跟着。", },
	[2111] = {id=2111, zh_CN="这颜色衬得你眼睛更亮啦！光看背影就知道是你，特别神气！", },
	[2112] = {id=2112, zh_CN="穿这身去广场，连年糕他们都得绕着你转三圈！", },
	[2113] = {id=2113, zh_CN="新衣裳上的花纹好特别，是藏了什么小秘密吗？快让我闻闻～", },
	[2114] = {id=2114, zh_CN="你脸上亮晶晶的是什么？", },
	[2115] = {id=2115, zh_CN="嗷呜，我觉得你更好看了~", },
	[2116] = {id=2116, zh_CN="汪！这香味儿真好闻～比花圃的花儿还甜。", },
	[2117] = {id=2117, zh_CN="好看呢，走出去保管人人都夸～", },
	[2118] = {id=2118, zh_CN="这颜色涂得真匀，比我舔毛舔得还顺溜。", },
	[2119] = {id=2119, zh_CN="分数哪有开心重要嘛！看刚才你旋转的时候，我也想跟着一起转呢！", },
	[2120] = {id=2120, zh_CN="诶，我觉得你明明跳的很好。", },
	[2121] = {id=2121, zh_CN="我觉得下次一定会跳的更好。", },
	[2122] = {id=2122, zh_CN="下次咱们多练练，肯定能得高分的！", },
	[2123] = {id=2123, zh_CN="分数什么的，下次多转两圈就追回来了～", },
	[2124] = {id=2124, zh_CN="我觉得你已经很厉害了！", },
	[2125] = {id=2125, zh_CN="这样很厉害呢，下次继续保持！", },
	[2126] = {id=2126, zh_CN="你转圈的时候很稳呢，我觉得很棒呢～", },
	[2127] = {id=2127, zh_CN="你节奏踩得准准的，下次肯定还能拿更高分！", },
	[2128] = {id=2128, zh_CN="我看了也想跟你一起跳！", },
	[2129] = {id=2129, zh_CN="你刚才转圈时好像飞舞的光灵！好厉害的舞步！", },
	[2130] = {id=2130, zh_CN="我认为，你就是舞会第一！", },
	[2131] = {id=2131, zh_CN="分数这么高，我都看呆了！", },
	[2132] = {id=2132, zh_CN="哇，你的舞蹈天赋真令人羡慕！", },
	[2133] = {id=2133, zh_CN="你该不会是百年一见的舞蹈天才吧！", },
	[2134] = {id=2134, zh_CN="刚才看你抿身份的时候，我都替你捏把汗呢！还得是你厉害！", },
	[2135] = {id=2135, zh_CN="今晚找茶馆老板要两斤炖肉庆祝，我请客！", },
	[2136] = {id=2136, zh_CN="哇哦，你可真厉害，下次可以带小金毛一起玩吗？", },
	[2137] = {id=2137, zh_CN="最后一投太险啦，还好你稳住了！", },
	[2138] = {id=2138, zh_CN="你好厉害，我好佩服你。", },
	[2139] = {id=2139, zh_CN="没事儿没事儿，我觉得你已经很厉害了。", },
	[2140] = {id=2140, zh_CN="刚才那局运气差了点而已，我觉得你下次一定能赢。", },
	[2141] = {id=2141, zh_CN="就差那么一丢丢，下次肯定能赢回来！", },
	[2142] = {id=2142, zh_CN="输了也没关系呀，你刚才盘逻辑的时候真的很厉害。", },
	[2143] = {id=2143, zh_CN="嗷呜？居然输了吗，我还以为这把会赢的。", },
	[2144] = {id=2144, zh_CN="好快的身法！我都没看清。", },
	[2145] = {id=2145, zh_CN="哇，利落果决，你好厉害呀。", },
	[2146] = {id=2146, zh_CN="嗅嗅，应该没被人发现吧。", },
	[2147] = {id=2147, zh_CN="下次驱逐别人时叫上我？我帮你望风，谁靠近就报信。", },
	[2148] = {id=2148, zh_CN="很好的时机呢。", },
	[2149] = {id=2149, zh_CN="啊，被驱逐了。下把定要让他们看看你的厉害。", },
	[2150] = {id=2150, zh_CN="哦不，被驱逐得好突然，刚才吓我一跳。", },
	[2151] = {id=2151, zh_CN="下次咱们早点识破他们，让他们连驱逐你的机会都没有！", },
	[2152] = {id=2152, zh_CN="下次我帮你盯着，不准谁再不怀好意地靠近你。", },
	[2153] = {id=2153, zh_CN="呜，变成幽灵了，希望他们能抓到真正的隐秘客。", },
	[2154] = {id=2154, zh_CN="好久不见，我一直在等你！", },
	[2155] = {id=2155, zh_CN="嗨，你回来了，我一直都在哦。", },
	[2156] = {id=2156, zh_CN="我给你留了好东西，快看看！", },
	[2157] = {id=2157, zh_CN="等你好久啦！欢迎回来！", },
	[2158] = {id=2158, zh_CN="我又盼到你来了！要一起去哪玩吗？", },
	[2159] = {id=2159, zh_CN="嗯，不错，你要是送我矿石的话我会更高兴。", },
	[2160] = {id=2160, zh_CN="茶汤像琥珀，倒在紫晶杯里肯定好看。", },
	[2161] = {id=2161, zh_CN="松露味儿真沉，跟矿脉里的宝贝似的，好像黑曜石。", },
	[2162] = {id=2162, zh_CN="这绿和我那块翡翠矿一个色。", },
	[2163] = {id=2163, zh_CN="名字像星空，看起来到时更像我的黑曜石。", },
	[2164] = {id=2164, zh_CN="辣味够劲，像矿洞里的火星子。", },
	[2165] = {id=2165, zh_CN="滑溜溜的，暖乎乎的。", },
	[2166] = {id=2166, zh_CN="茶香带甜，倒在落日金杯里。", },
	[2167] = {id=2167, zh_CN="奶黄像月光石，软乎乎的，甜到心尖儿。", },
	[2168] = {id=2168, zh_CN="肉香混着气味，跟深埋的矿脉一样醇厚，香！", },
	[2169] = {id=2169, zh_CN="流心像熔浆，看着就热闹。", },
	[2170] = {id=2170, zh_CN="浓汤稠得像矿浆！很好，要是有珍稀矿石就更好了。", },
	[2171] = {id=2171, zh_CN="木纹被蚀得很特别，像天然的矿脉纹路，挺有意思。", },
	[2172] = {id=2172, zh_CN="像刚从矿坑里挖出来的粗坯。", },
	[2173] = {id=2173, zh_CN="小巧精致，不错，盒子我要了。", },
	[2174] = {id=2174, zh_CN="颜色太艳了，和我那些沉色的矿石摆在一起有点突兀，不太搭。", },
	[2175] = {id=2175, zh_CN="光色柔和，像夜晚发光的矿石，能当个小摆件。", },
	[2176] = {id=2176, zh_CN="造型简洁，摆在矿石架旁，香气应该能散开。", },
	[2177] = {id=2177, zh_CN="和我的月光石有点像，说不定能产生共鸣。", },
	[2178] = {id=2178, zh_CN="鎏金的光泽，像落日金的反光，声音应该好听。", },
	[2179] = {id=2179, zh_CN="牌面图案神秘，和矿石的未知感有点像。", },
	[2180] = {id=2180, zh_CN="能存东西，谢谢。", },
	[2181] = {id=2181, zh_CN="炸开时应该很亮。", },
	[2182] = {id=2182, zh_CN="能装记忆，倒和矿石藏着地质记忆一样。", },
	[2183] = {id=2183, zh_CN="名字特别，花瓣的质感像某种矿石的切片。", },
	[2184] = {id=2184, zh_CN="黑石？这纯也太低了。", },
	[2185] = {id=2185, zh_CN="实用的物件，和打磨矿石的工具一样重要。", },
	[2186] = {id=2186, zh_CN="颜色低调，不错。", },
	[2187] = {id=2187, zh_CN="这颜色像矿脉里的多彩矿石，挺亮眼。", },
	[2188] = {id=2188, zh_CN="款式太花哨，不如矿石的自然纹路耐看，不太合我意。", },
	[2189] = {id=2189, zh_CN="谢了，垫垫肚子，等下好整理矿石。", },
	[2190] = {id=2190, zh_CN="发光的草，像会亮的矿石碎末，挺新奇。", },
	[2191] = {id=2191, zh_CN="粗坯而已，丢了也不可惜。", },
	[2192] = {id=2192, zh_CN="丢了也好，省得晃眼。", },
	[2193] = {id=2193, zh_CN="不感兴趣的话，丢了也正常。", },
	[2194] = {id=2194, zh_CN="丢了吧，我有更好的。", },
	[2195] = {id=2195, zh_CN="在我眼里这好像破石头一样。", },
	[2196] = {id=2196, zh_CN="这毛色的光泽过渡，多像我那块落日金的切面，收藏的眼光总得练在这些地方。", },
	[2197] = {id=2197, zh_CN="我可不想因为颠簸错过什么值得留意的细节，毕竟好藏品往往藏在不起眼的地方。", },
	[2198] = {id=2198, zh_CN="纹路虽无矿，野趣却比摆件真，也算种收藏。", },
	[2199] = {id=2199, zh_CN="这可真是件有趣的藏品。", },
	[2200] = {id=2200, zh_CN="这物件成色不错，和描述的一样，任务完成得挺利落。", },
	[2201] = {id=2201, zh_CN="都齐了，没差漏，很好。", },
	[2202] = {id=2202, zh_CN="到手了？这次的奖励成色看着还行。", },
	[2203] = {id=2203, zh_CN="动作挺稳的，没磕着碰着，不错。", },
	[2204] = {id=2204, zh_CN="我的眼光果然没错，你做得很好。", },
	[2205] = {id=2205, zh_CN="换了身新的？比之前那套更显利落些。", },
	[2206] = {id=2206, zh_CN="你的审美不错。", },
	[2207] = {id=2207, zh_CN="这装饰有点意思，我喜欢。", },
	[2208] = {id=2208, zh_CN="看着挺精神的，比上次那件有感觉。", },
	[2209] = {id=2209, zh_CN="嗯，要是再加上宝石点缀就完美了。", },
	[2210] = {id=2210, zh_CN="挺自然的，不晃眼，像宝石那样耐看。", },
	[2211] = {id=2211, zh_CN="这妆容看着清爽，不拖沓，我喜欢。", },
	[2212] = {id=2212, zh_CN="细节挺讲究的，不错。", },
	[2213] = {id=2213, zh_CN="挺好，不厚重，看着很舒服。", },
	[2214] = {id=2214, zh_CN="我都有点想把你当做藏品收藏了。", },
	[2215] = {id=2215, zh_CN="够低调，没露破绽。", },
	[2216] = {id=2216, zh_CN="选这个目标吗，倒是不错的选择。", },
	[2217] = {id=2217, zh_CN="出刀够果断，想来你挑宝石也一定这么果敢。", },
	[2218] = {id=2218, zh_CN="不拖泥带水，像我看准了收藏品一样。", },
	[2219] = {id=2219, zh_CN="这时机选的很好，看来下次矿石拍卖会得带上你。", },
	[2220] = {id=2220, zh_CN="糟了，被他刀了，还是看走眼了。", },
	[2221] = {id=2221, zh_CN="可惜了，差一步。", },
	[2222] = {id=2222, zh_CN="看来他们眼光也挺准的。", },
	[2223] = {id=2223, zh_CN="藏得还不够深。", },
	[2224] = {id=2224, zh_CN="错失一步，可惜了。", },
	[2225] = {id=2225, zh_CN="你来了，我亲爱的珍宝。", },
	[2226] = {id=2226, zh_CN="又见面了，我看你今天状态不错。", },
	[2227] = {id=2227, zh_CN="久违了，朋友。", },
	[2228] = {id=2228, zh_CN="你不在的这段时间我又收集了不少漂亮的矿石。", },
	[2229] = {id=2229, zh_CN="这面包口感温和，吃着很舒服。", },
	[2230] = {id=2230, zh_CN="蜜露花茶啊，花茶？还是算了吧。", },
	[2231] = {id=2231, zh_CN="松露面包可以啊，这香气到是不冲。", },
	[2232] = {id=2232, zh_CN="翡翠菜心看着挺新鲜，清口的我喜欢。", },
	[2233] = {id=2233, zh_CN="星尘沙拉？不是什么花粉就好。", },
	[2234] = {id=2234, zh_CN="龙息菇辣酱？太辣了吧。", },
	[2235] = {id=2235, zh_CN="滑溜溜的，暖胃，不错。", },
	[2236] = {id=2236, zh_CN="我先抿一口试试…… 嗯，没花香气，能来点。", },
	[2237] = {id=2237, zh_CN="月光布丁看着就甜丝丝的。", },
	[2238] = {id=2238, zh_CN="这炖得烂乎，嗯，好香。", },
	[2239] = {id=2239, zh_CN="熔岩花果蛋糕？！别拿过来！", },
	[2240] = {id=2240, zh_CN="稠稠的，喝着暖和，舒服。", },
	[2241] = {id=2241, zh_CN="这纹路挺特别的，就是看着有点糙，倒也别致。", },
	[2242] = {id=2242, zh_CN="捏得挺好看，谢谢你。", },
	[2243] = {id=2243, zh_CN="便携茶具套不错啊，出门带着方便，我刚好缺个顺手的。", },
	[2244] = {id=2244, zh_CN="颜色是挺跳的，坐着倒稳当。", },
	[2245] = {id=2245, zh_CN="荧光许愿瓶，夜里会亮吗？看着挺好玩的。", },
	[2246] = {id=2246, zh_CN="四季香薰炉就算了吧，我也不想闻到春天那花香调的精油。", },
	[2247] = {id=2247, zh_CN="这名字听着玄乎，摸着倒挺凉。", },
	[2248] = {id=2248, zh_CN="鎏金八音盒太晃眼了，我还是喜欢素净点的。", },
	[2249] = {id=2249, zh_CN="图案挺神秘，我对着也看不懂啊。", },
	[2250] = {id=2250, zh_CN="这种老物件现在少见了，留着挺有意义。", },
	[2251] = {id=2251, zh_CN="烟花礼炮就算了，我怕呛着。", },
	[2252] = {id=2252, zh_CN="这玩意儿能存东西？有点意思。", },
	[2253] = {id=2253, zh_CN="不是真花吗？谢谢，你好贴心。", },
	[2254] = {id=2254, zh_CN="这质感挺沉的，摆着应该稳。", },
	[2255] = {id=2255, zh_CN="自修复工具箱，实用的工具。", },
	[2256] = {id=2256, zh_CN="简单，不花哨的礼物。", },
	[2257] = {id=2257, zh_CN="颜色挺多，找起来方便。", },
	[2258] = {id=2258, zh_CN="这料子看着挺薄，适合夏天穿。", },
	[2259] = {id=2259, zh_CN="三文鱼罐头，咸淡正好，配面包吃不错。", },
	[2260] = {id=2260, zh_CN="这草看着像塑料的，没花粉吧？那就好。", },
	[2261] = {id=2261, zh_CN="没用的扔了好，空气都能新鲜些。", },
	[2262] = {id=2262, zh_CN="扔的时候轻点，别扬起灰 ，我这鼻子可经不起折腾。", },
	[2263] = {id=2263, zh_CN="还好不是干花之类的，不然扔了也得留股味儿。", },
	[2264] = {id=2264, zh_CN="要是能把花粉全都从我身边丢走就好了。", },
	[2265] = {id=2265, zh_CN="这附近没什么花吧？", },
	[2266] = {id=2266, zh_CN="希望别沾着什么花草屑。", },
	[2267] = {id=2267, zh_CN="他行动起来不会吹气花粉吧？", },
	[2268] = {id=2268, zh_CN="你要带我兜风吗？那可得小心，离花丛远些。", },
	[2269] = {id=2269, zh_CN="交完这下能歇会儿了吧？", },
	[2270] = {id=2270, zh_CN="奖励比我想的多，不错啊。", },
	[2271] = {id=2271, zh_CN="这趟没沾着花粉就好，我瞅着你脸挺干净。", },
	[2272] = {id=2272, zh_CN="搞定了？我还怕任务点有花丛呢，看来还好。", },
	[2273] = {id=2273, zh_CN="好样的伙伴！", },
	[2274] = {id=2274, zh_CN="你这身好好看啊，希望不会吸引太多蝴蝶。", },
	[2275] = {id=2275, zh_CN="新换的这身真不错！", },
	[2276] = {id=2276, zh_CN="颜色搭配得好，不招小虫子又好看。", },
	[2277] = {id=2277, zh_CN="我喜欢你这套搭配。", },
	[2278] = {id=2278, zh_CN="这妆化得挺清透啊，挺好。", },
	[2279] = {id=2279, zh_CN="这妆容看着舒服。", },
	[2280] = {id=2280, zh_CN="化的这么好看，记得别往花丛走，会招蝴蝶。", },
	[2281] = {id=2281, zh_CN="这妆面干净，没用带花香的定妆喷雾吧？挺好的。", },
	[2282] = {id=2282, zh_CN="眼妆画得精致，风大的话挡挡，别让花粉吹进眼睛里。", },
	[2283] = {id=2283, zh_CN="刀的好啊！阿嚏！", },
	[2284] = {id=2284, zh_CN="这刀够快，比我打喷嚏的速度还猛，哈哈。", },
	[2285] = {id=2285, zh_CN="够快的，这选择挺干脆。", },
	[2286] = {id=2286, zh_CN="快躲起来，别让他们发现了。", },
	[2287] = {id=2287, zh_CN="阿嚏，阿嚏！呜呜。", },
	[2288] = {id=2288, zh_CN="怎么被刀了？下把跟我防花粉一样，多留意周围动静。", },
	[2289] = {id=2289, zh_CN="明明跟避花粉一样谨慎，怎么还是被找着了，下把再藏深点。", },
	[2290] = {id=2290, zh_CN="比……比花粉散播还利索……", },
	[2291] = {id=2291, zh_CN="救命，阿嚏！", },
	[2292] = {id=2292, zh_CN="你刚从外面回来？身上没沾花粉吧？", },
	[2293] = {id=2293, zh_CN="你回来了！诶，你身上怎么香香的，阿嚏！", },
	[2294] = {id=2294, zh_CN="你有给我带礼物吗？不要花不要花！", },
