	[6001] = {id=6001, zh_CN="真巧遇到你！最近聚会上总碰到些固执己见的人，头疼了。", },
	[6002] = {id=6002, zh_CN="马上要去做学术报告了，希望能顺利……其实最想改变的是家里那些老观念。", },
	[6003] = {id=6003, zh_CN="又见面啦！最近有出去感受大自然吗？", },
	[6004] = {id=6004, zh_CN="嘿，我刚写完一首新歌，要不要听听看？", },
	[6005] = {id=6005, zh_CN="用我们种族的天赋治好了一只受伤的小家伙，超有成就感~", },
	[6006] = {id=6006, zh_CN="最近忙疯了，当领导责任太重了。", },
	[6007] = {id=6007, zh_CN="正好碰到你，刚调解完一场贸易纠纷。", },
	[6008] = {id=6008, zh_CN="在规划星球发展蓝图呢，得让这里变得更好才行。", },
	[6009] = {id=6009, zh_CN="商会最近事儿特别多，忙得团团转。", },
	[6010] = {id=6010, zh_CN="见到艾妲了吗？我那老对手不知道又在打什么算盘。", },
	[6011] = {id=6011, zh_CN="总算谈成个大单子，不然股东们又要唠叨了。", },
	[6012] = {id=6012, zh_CN="你在这儿干嘛？对我有什么好处？", },
	[6013] = {id=6013, zh_CN="巧了，最近有什么赚钱的路子吗？", },
	[6014] = {id=6014, zh_CN="别想让我白帮忙，没好处的事我可不干。", },
	[6015] = {id=6015, zh_CN="最近看过什么好舞蹈吗？我在编新舞缺灵感。", },
	[6016] = {id=6016, zh_CN="有见到埃莉诺吗？好久没和她聊天了。", },
	[6017] = {id=6017, zh_CN="在研究怎么让机械腿的舞蹈动作更酷呢。", },
	[6018] = {id=6018, zh_CN="我发现了个超棒的旅行地，想听吗？", },
	[6019] = {id=6019, zh_CN="旅行时认识了些超有趣的新朋友。", },
	[6020] = {id=6020, zh_CN="在路上学到了新的烹饪技巧哦。", },
	[6021] = {id=6021, zh_CN="看到我的毛线球了吗？陪我找找嘛~", },
	[6022] = {id=6022, zh_CN="要不要去房顶看看？说不定有小鸟！", },
	[6023] = {id=6023, zh_CN="来陪我玩抓影子游戏吧！", },
	[6024] = {id=6024, zh_CN="我藏了酸东西哦，找不到的话……嘿嘿！", },
	[6025] = {id=6025, zh_CN="最近有人捉弄你吗？我可有的是点子。", },
	[6026] = {id=6026, zh_CN="新调的酸粉，你要不要试试看？", },
	[6027] = {id=6027, zh_CN="你也在这儿晒太阳啊，今天光线真舒服。", },
	[6028] = {id=6028, zh_CN="最近在光里有听到什么奇怪的声音吗？", },
	[6029] = {id=6029, zh_CN="有没有觉得今天的光颜色不太一样？", },
	[6030] = {id=6030, zh_CN="有什么机械方面的新想法吗？我在研发新技术。", },
	[6031] = {id=6031, zh_CN="刚调试好新机甲，性能超赞！", },
	[6032] = {id=6032, zh_CN="正为机械能源问题发愁呢，你有什么建议吗？", },
	[6033] = {id=6033, zh_CN="注意点，别弄脏这么高雅的地方。", },
	[6034] = {id=6034, zh_CN="最近欣赏过什么高雅艺术吗？", },
	[6035] = {id=6035, zh_CN="在我面前请注意举止得体。", },
	[6036] = {id=6036, zh_CN="最近有去感受大自然吗？", },
	[6037] = {id=6037, zh_CN="我刚创作了一首新曲子呢！", },
	[6038] = {id=6038, zh_CN="用我们种族的能力治好了一只小动物。", },
	[6039] = {id=6039, zh_CN="最近有帮助别人吗？我还在为理想奋斗。", },
	[6040] = {id=6040, zh_CN="刚参加完慈善活动回来。", },
	[6041] = {id=6041, zh_CN="在组织公益项目，要一起来吗？", },
	[6042] = {id=6042, zh_CN="今天的阳光真舒服，你也来感受吗？", },
	[6043] = {id=6043, zh_CN="最近在光里有听到什么怪声吗？", },
	[6044] = {id=6044, zh_CN="有没有觉得今天的光颜色很特别？", },
	[6045] = {id=6045, zh_CN="最近有去帮助别人吗？我一直在努力。", },
	[6046] = {id=6046, zh_CN="刚做完慈善活动回来。", },
	[6047] = {id=6047, zh_CN="在筹备公益项目，要加入吗？", },
	[6048] = {id=6048, zh_CN="有什么机械创意吗？我忙得都没时间睡觉。", },
	[6049] = {id=6049, zh_CN="见到甜霜熊了吗？好久没一起吃甜点了。", },
	[6050] = {id=6050, zh_CN="又接了新科研项目，事情多得头疼。", },
	[6051] = {id=6051, zh_CN="最近有什么好玩的舞会吗？上次和年糕跳舞可开心了。", },
	[6052] = {id=6052, zh_CN="真巧遇见你！有什么新鲜事吗？", },
	[6053] = {id=6053, zh_CN="最近在教宠物宝宝玩新游戏，超有意思。", },
	[6054] = {id=6054, zh_CN="别打扰我晒太阳。", },
	[6055] = {id=6055, zh_CN="离我的小鱼干远点儿。", },
	[6056] = {id=6056, zh_CN="我要找地方睡觉，别跟着我！", },
	[6057] = {id=6057, zh_CN="今天的阳光真舒服，对吧？", },
	[6058] = {id=6058, zh_CN="最近在光里有听到什么怪声吗？", },
	[6059] = {id=6059, zh_CN="有没有觉得今天的光颜色不一样？", },
	[6060] = {id=6060, zh_CN="又见面啦！最近有遇到语言障碍吗？我可以帮忙。", },
	[6061] = {id=6061, zh_CN="刚翻译完一些古老文字，可有意思了。", },
	[6062] = {id=6062, zh_CN="在学习各种语言文化，真是大开眼界。", },
	[6063] = {id=6063, zh_CN="最近总在思考自由和机械的关系，你有什么想法吗？", },
	[6064] = {id=6064, zh_CN="真巧又见面了！我正在学习人类的艺术，挺有意思的~", },
	[6065] = {id=6065, zh_CN="最近尝试种些植物，想体验不一样的生活方式。", },
