	[11018] = {id=11018, zh_CN="刚从雪堆里“滚”出来的雪团团，张开粉爪垫，露出藏在雪境的淘气雪粒。", },
	[11019] = {id=11019, zh_CN="围起红条纹围巾，怀抱炽热红心，让寒冬也染上温柔绯色。", },
	[11020] = {id=11020, zh_CN="揣着未说的秘密，如夜雪揉出的影子，邀你共探雪境藏的奇妙故事。", },
	[11021] = {id=11021, zh_CN="俏皮的菌群从帽檐、围巾、爪缝里冒出来，把清冷雪境，发酵成粉甜的酸莓糖霜。", },
	[11022] = {id=11022, zh_CN="抱着的小鱼桶“哐当”响，是要给雪境小熊派送的快乐包裹！", },
	[11023] = {id=11023, zh_CN="从糖果工厂溜到雪境的小可爱，要把绮丽梦境，分享给每个爱幻想的旅客。", },
	[11024] = {id=11024, zh_CN="雪境也过万圣节？拎着南瓜灯，它是来捣蛋的小魔女，一起嗨玩奇妙夜吧。", },
	[11025] = {id=11025, zh_CN="稳稳抱住森林冬雪揉成的雪团，一头扎进冬眠模式，捂热一整个森系冬夜的困意。", },
	[11026] = {id=11026, zh_CN="蓬松绒毛裹着清甜，樱桃坠在身畔，把森林里的甜意，都揉进这团绵软。", },
	[11027] = {id=11027, zh_CN="森林派来的春之信使，顶着嫩苗登场，裹着青嫩绿意，把生机悄悄投递。", },
	[11028] = {id=11028, zh_CN="背着草垛，像守着丰收宝藏，在咩咩森林里，当一回憨态可掬的田园守望者。", },
	[11029] = {id=11029, zh_CN="茶杯作伴，花与茶的香气缠绕，在森林角落，偷享片刻慵懒小憩。", },
	[11030] = {id=11030, zh_CN="把森系午后的慵懒与甜，都吸进这口绵软，开启一场会冒泡的治愈漫游。", },
	[11031] = {id=11031, zh_CN="驮起月牙与流星，在羊毛森林的漫漫长夜，化身为传递温柔与绮梦的夜行精灵。", },
	[11032] = {id=11032, zh_CN="黑麦面包", },
	[11033] = {id=11033, zh_CN="小麦果汁", },
	[11034] = {id=11034, zh_CN="水煮土豆", },
	[11035] = {id=11035, zh_CN="烤岩薯", },
	[11036] = {id=11036, zh_CN="盐制瓜子", },
	[11037] = {id=11037, zh_CN="醋制瓜子", },
	[11038] = {id=11038, zh_CN="原味瓜子", },
	[11039] = {id=11039, zh_CN="糖制瓜子", },
	[11040] = {id=11040, zh_CN="奶味瓜子", },
	[11041] = {id=11041, zh_CN="怪味瓜子", },
	[11042] = {id=11042, zh_CN="烤肉排", },
	[11043] = {id=11043, zh_CN="虾饼", },
	[11044] = {id=11044, zh_CN="盐煮鱼", },
	[11045] = {id=11045, zh_CN="浮藻脆片", },
	[11046] = {id=11046, zh_CN="麦醋岩薯泥", },
	[11047] = {id=11047, zh_CN="葵籽酥糖", },
	[11048] = {id=11048, zh_CN="葵籽饼", },
	[11049] = {id=11049, zh_CN="一块质地扎实、颜色深褐的黑麦面包。它可能不算美味，但绝对能可靠地填饱你的肚子，是旅人背包里的常客。", },
	[11050] = {id=11050, zh_CN="一种用小麦发酵而成的金色饮料，带着细腻的泡沫和微苦的口感。常被称为“液态面包”。", },
	[11051] = {id=11051, zh_CN="用清水煮熟的硬皮土豆，除了土豆本身的味道外别无他物。是冒险中最常见的热食。", },
	[11052] = {id=11052, zh_CN="直接在火上烤熟的岩薯，外皮焦脆，内里香甜软糯，是篝火旁最温暖的慰藉。", },
	[11053] = {id=11053, zh_CN="经过粗盐简单炒制的向日葵籽，咸香可口。嗑瓜子是打发漫长守夜时间的最佳方式。", },
	[11054] = {id=11054, zh_CN="用麦芽醋浸泡后烘干的瓜子，带着独特的酸香，非常开胃。", },
	[11055] = {id=11055, zh_CN="未经任何调味炒制的原味向日葵籽，只有纯粹的植物油脂香气。", },
	[11056] = {id=11056, zh_CN="表面裹着一层薄薄黑蔗糖霜的瓜子，甜滋滋的，很受孩子们欢迎。", },
	[11057] = {id=11057, zh_CN="据说在炒制时加入了咩咩羊奶，使其带有一种浓郁的奶香。", },
	[11058] = {id=11058, zh_CN="混合了盐、糖、醋以及神秘香料的瓜子，味道层次丰富，你永远不知道下一颗是什么滋味。", },
	[11059] = {id=11059, zh_CN="一大块在火上烤得滋滋作响、外焦里嫩的合成肉排。纯粹的肉食能满足最原始的渴望。", },
	[11060] = {id=11060, zh_CN="将泥虾捣成泥后煎制而成的小饼，口感弹牙，带着海洋的鲜味。", },
	[11061] = {id=11061, zh_CN="用池鱼和粗盐加水同煮的清简菜肴，最大限度地保留了鱼本身的鲜美。", },
	[11062] = {id=11062, zh_CN="将浮藻晒干后油炸或烘烤而成的绿色脆片，吃起来“咔嚓”作响，是渔夫们的经典零嘴。", },
	[11063] = {id=11063, zh_CN="将烤熟的岩薯捣成泥，淋上麦芽醋和少许粗盐。绵密的口感中带着一丝清爽的酸味。", },
	[11064] = {id=11064, zh_CN="将黑蔗糖融化后与向日葵籽混合凝固制成的硬糖，香甜耐嚼，是补充体力的好选择。", },
	[11065] = {id=11065, zh_CN="在黑麦面糊中加入大量向日葵籽烤成的香脆薄饼，既是粮食也是零食。", },
	[11066] = {id=11066, zh_CN="黄油爆米花", },
	[11067] = {id=11067, zh_CN="果味乱炖", },
	[11068] = {id=11068, zh_CN="铁锅炖肉", },
	[11069] = {id=11069, zh_CN="素鸡煲", },
	[11070] = {id=11070, zh_CN="烟花糖", },
	[11071] = {id=11071, zh_CN="玛丽番茄汁", },
	[11072] = {id=11072, zh_CN="鱼骨浓汤", },
	[11073] = {id=11073, zh_CN="茄酿", },
	[11074] = {id=11074, zh_CN="用大颗的黄须玉米与珍贵黄油在铁锅中爆开的零嘴。每一颗都裹着金黄油脂，“嘭”的一声，是丰收时节最悦耳的声音。装在纸袋里，热乎乎地分享最好。", },
	[11075] = {id=11075, zh_CN="将手边能找到的果子统统丢进坩埚熬煮成的浓稠炖品。味道酸甜交织，充满随性的惊喜，是精灵们的疗愈食谱。", },
	[11076] = {id=11076, zh_CN="北境猎人的招牌菜。大块合成肉排与硬皮土豆、岩薯在铁锅中久炖，汤汁醇厚，肉烂菇香。围坐在锅边，能驱散任何严寒。", },
	[11077] = {id=11077, zh_CN="用魔豆与黑麦粉制成素“鸡”，与镜面果、紫茄一同煲煮。口感以假乱真，汤汁鲜美清润，是苦行僧侣们虔诚而智慧的美味。", },
	[11078] = {id=11078, zh_CN="由霓虹酱、甜霜和发光粒子制成的神奇糖果。含在嘴里，会感受到微小的“噼啪”感，仿佛舌尖在绽放一场微缩的烟花秀。", },
	[11079] = {id=11079, zh_CN="一款以明星茄和笑脸番茄为主角，加入少许龙息干椒和黑胡椒调制的特色饮品。口感酸甜中带着一丝危险的辛辣，如其名般令人印象深刻。", },
	[11080] = {id=11080, zh_CN="将岩板鱼等鱼类的鱼骨耐心熬煮至奶白色的浓汤，萃取了全部精华。喝下它，能感受到力量从骨髓深处涌出。", },
	[11081] = {id=11081, zh_CN="将圆润的紫茄掏空，填入由石缝地衣、池鱼肉和锵锵姜混合的馅料，淋上葵籽油烤制。是农家智慧与自然馈赠的结合。", },
	[11082] = {id=11082, zh_CN="解毒剂", },
	[11083] = {id=11083, zh_CN="红烧比目鱼", },
	[11084] = {id=11084, zh_CN="番茄肉酱面", },
	[11085] = {id=11085, zh_CN="珍珠奶茶", },
	[11086] = {id=11086, zh_CN="焗魔豆", },
	[11087] = {id=11087, zh_CN="清蒸比目鱼", },
	[11088] = {id=11088, zh_CN="香煎比目鱼", },
	[11089] = {id=11089, zh_CN="茄汁比目鱼", },
	[11090] = {id=11090, zh_CN="烤乌贼腿", },
	[11091] = {id=11091, zh_CN="茄大咖", },
	[11092] = {id=11092, zh_CN="一瓶澄澈的淡绿色药剂，由荧光小菇的孢子混合飞羽草煎制而成。味道清苦，但能有效中和大多数常见毒素。", },
	[11093] = {id=11093, zh_CN="将肥美的比目鱼身用陈酿酱油与黑蔗糖慢火煨烧，汤汁浓稠油亮，鱼肉入味鲜甜，是东方港口城市的招牌风味。", },
	[11094] = {id=11094, zh_CN="劲道的黑麦面条上，浇满了用明星茄与合成肉排熬煮的浓稠肉酱。每根面条都裹满了酸甜咸香的酱汁，令人食欲大开。", },
	[11095] = {id=11095, zh_CN="用咩咩羊奶与黑蔗糖调成的醇香奶茶，杯底沉着用镜面果胶制成的Q弹“珍珠”。这款风靡街头的饮品带来了简单的快乐。", },
	[11096] = {id=11096, zh_CN="充满活力的魔豆与甜霜、黄点芝士一同烘烤。芝士拉出长长的丝线，魔豆在口中释放出微弱的能量感，是一道有趣的主食。", },
	[11097] = {id=11097, zh_CN="仅用锵锵姜与欢喜盐调味，以最大火力清蒸的比目鱼。鱼肉洁白如蒜瓣，口感嫩滑，完美诠释了“鲜”字的含义。", },
	[11098] = {id=11098, zh_CN="鱼排用葵籽油煎至两面金黄，外皮酥脆，内里多汁。撒上几粒粗盐和现磨黑胡椒，是永远不会出错的经典做法。", },
	[11099] = {id=11099, zh_CN="将比目鱼块炸至外酥里嫩，再淋上用笑脸番茄熬成的酸甜茄汁。酥脆的鱼肉与开胃的酱汁形成绝妙对比。", },
	[11100] = {id=11100, zh_CN="完整的大王乌贼腿穿在铁签上，刷上霓虹酱与葵籽油烤制。口感极富嚼劲，带着浓郁的炭火香气，是海港烧烤摊的明星。", },
	[11101] = {id=11101, zh_CN="一道著名的融合菜，将紫茄、土豆与大王乌贼腿共治一炉，以龙息干椒和黄点芝士调味，味道浓郁奔放，层次极其丰富。", },
	[11102] = {id=11102, zh_CN="真·珍珠奶茶", },
	[11103] = {id=11103, zh_CN="荧光特调", },
	[11104] = {id=11104, zh_CN="孟婆特调", },
	[11105] = {id=11105, zh_CN="海沫香调", },
	[11106] = {id=11106, zh_CN="命运骰子", },
	[11107] = {id=11107, zh_CN="回忆阴云", },
	[11108] = {id=11108, zh_CN="回忆棉花糖", },
	[11109] = {id=11109, zh_CN="这并非普通的街饮。以银月稻米制成的“珍珠”内蕴星辰蜂蜜的流心，奶茶基底则由晨露与永生花蜜调和而成。每一口都仿佛在品味液态的月光。", },
	[11110] = {id=11110, zh_CN="一杯闪烁着幽幽磷光的奇幻饮品，由荧光小菇的汁液、发光粒子和经过处理的量子鱼萃取物调制而成。味道清凉而神秘，喝下后连血液都仿佛在发光。", },
	[11111] = {id=11111, zh_CN="一碗散发着记忆薄荷与云菇香气的清澈汤药。汤面倒映着过往的幻影，饮下它并非为了遗忘，而是为了与某个特定的执念达成和解，从而获得继续前进的勇气。", },
	[11112] = {id=11112, zh_CN="一款极具优雅与魅力的仪式饮品。以歌藻的汁液为基底，融入碾碎的月光银鱼鳞粉，使其呈现出璀璨的珍珠光泽，口感如海沫般细腻，带着深邃的海洋芬芳。", },
	[11113] = {id=11113, zh_CN="一颗用魔豆粉、霓虹酱和空气调味剂凝固而成的半透明骰子，六个面分别闪烁着不同颜色的微光。吃下它，意味着你将一切交给了不可预测的命运洪流。", },
	[11114] = {id=11114, zh_CN="一团漂浮在杯中的灰黑色云状物质，由焦虑盐、悲伤盐和怨气草的萃取物构成。它会主动吸引并放大使用者心中不快的记忆，味道苦涩而沉重。", },
	[11115] = {id=11115, zh_CN="一朵由欢喜盐、星辰蜂蜜和记忆薄荷的糖丝编织而成的蓬松棉花糖。入口即化，甜蜜的滋味会将你拉回童年最美好、最无忧无虑的那个午后。", },
	[11116] = {id=11116, zh_CN="初级食物加工机", },
	[11117] = {id=11117, zh_CN="中级食物加工机", },
	[11118] = {id=11118, zh_CN="高级食物加工机", },
	[11119] = {id=11119, zh_CN="万能食物加工机", },
	[11120] = {id=11120, zh_CN="能够将平凡的食材进行加工", },
	[11121] = {id=11121, zh_CN="能够将精良、优秀的食材进行加工", },
	[11122] = {id=11122, zh_CN="能够将稀有的食材进行加工", },
	[11123] = {id=11123, zh_CN="能够将一切食材进行加工", },
	[11124] = {id=11124, zh_CN="精致面粉", },
	[11125] = {id=11125, zh_CN="黄油", },
	[11126] = {id=11126, zh_CN="精致面条", },
	[11127] = {id=11127, zh_CN="铁木桶", },
	[11128] = {id=11128, zh_CN="经过小麦多次淘洗、晾晒、研磨而成的顶级面粉。质地雪白细腻，如同月光凝结的尘埃，是制作高级糕点与面食的不二之选。", },
	[11129] = {id=11129, zh_CN="由咩咩羊奶经过反复搅打、提炼出的金色油脂。带着浓郁的奶香，无论是用于煎烤还是融入面包，都能瞬间提升食物的风味层次。一小块就价值不菲。", },
	[11130] = {id=11130, zh_CN="用“精致面粉”手工擀制、切出的面条。色泽乳白，质地均匀，久煮不烂。本身已是一种难得的美味。", },
	[11131] = {id=11131, zh_CN="一个用铁木打造而成的坚固木桶，桶身被金属条紧紧箍住。它以其卓越的密封性和抗腐蚀性而闻名，常被用来运输名贵的液体，或是需要恒久保存的物资。", },
	[11132] = {id=11132, zh_CN="焦黑烤物", },
	[11133] = {id=11133, zh_CN="一块难以辨认原貌的碳化物。表面覆盖着厚厚的黑灰，质地如同烧尽的木炭，散发着混合了焦糊与苦涩的刺鼻气味。这是每位厨师学徒都曾创造过的“杰作”。", },
	[11134] = {id=11134, zh_CN="焦黑团团", },
	[11135] = {id=11135, zh_CN="一个蜷缩成球状的、彻底碳化的小团。表面布满皲裂，质地像冷却的火山岩一样硬脆，轻轻一捏就会掉下黑色的碎渣。虽然已经面目全非，但依稀能看出它曾经试图成为某个面包或点心的雏形。它散发着一股委屈般的焦苦味。", },
	[11136] = {id=11136, zh_CN="焦黑糊糊", },
	[11137] = {id=11137, zh_CN="一滩无法界定是固体还是液体的深黑色物质，表面偶尔会可疑地冒出一个气泡并破裂，散发出混合了焦炭、苦涩与一丝酸败气息的怪味。用勺子敲击会发出沉闷的“噗叽”声。它曾是某种食材，但现在，它更像是一个警告。", },
	[11138] = {id=11138, zh_CN="焦黑嗅嗅", },
	[11139] = {id=11139, zh_CN="一块被火焰严重亲吻过的、质地不明的物体。它的“焦黑”名副其实，但“嗅嗅”一词则源于其诡异特性——即便已完全碳化，它仍会持续散发出一股浓烈、刺鼻且极具穿透力的焦糊气味，这气味能附着在接触者的衣物和鼻腔里，经久不散。它是什么已经不重要了，重要的是，没人能忽略它的存在。", },
	[11140] = {id=11140, zh_CN="酥炸小鱼干", },
	[11141] = {id=11141, zh_CN="裹上轻薄的粉浆，将新鲜溪鱼炸至金黄酥脆，连鱼骨都散发着香气。", },
	[11142] = {id=11142, zh_CN="机油味特调", },
	[11143] = {id=11143, zh_CN="一种散发着刺鼻金属味和润滑油香气的深色液体，是机械生命钟情的专属饮品。", },
	[11144] = {id=11144, zh_CN="深海藻卷", },
	[11145] = {id=11145, zh_CN="用深海特有的宽叶藻包裹新鲜海胆和碎贝肉，口感冰凉，巴别族最爱。", },
	[11146] = {id=11146, zh_CN="黄油蛋糕", },
	[11147] = {id=11147, zh_CN="用高品质鲜奶提炼的黄油烘焙而成，口感绵密，食味族都对其赞不绝口。", },
	[11148] = {id=11148, zh_CN="特调能源液", },
	[11149] = {id=11149, zh_CN="以古老铁树汁为基底，经过高压过滤并注入活性离子，能提供极高的能源。", },
	[11150] = {id=11150, zh_CN="叶芽焙饼", },
	[11151] = {id=11151, zh_CN="使用森林深处的嫩叶芽磨粉，混合坚果碎烘烤出的薄脆饼，是精灵族完美的干粮。", },
	[11152] = {id=11152, zh_CN="珊瑚冻", },
	[11153] = {id=11153, zh_CN="提取软珊瑚中的胶质凝结而成的半透明甜点，色泽剔透。", },
	[11158] = {id=11158, zh_CN="测试", },
	[15000] = {id=15000, zh_CN="特效感冒灵", },
	[15001] = {id=15001, zh_CN="由精灵提供的生命之泉作为基底，辅以机械生命从深炉中提炼的“火焰核心微粒”，并加入了味真族的净化图腾粉末。这款药剂经过**公司生产，最终成为了应对米乐星球上各种奇异病原体的首选。", },
	[18000] = {id=18000, zh_CN="早呀！是什么好运气，让我一早就碰到你啦？", },
	[18001] = {id=18001, zh_CN="早呀！今天居然没先跑去接任务，难得来我这儿晃悠～", },
	[19000] = {id=19000, zh_CN="前面城外有会发光的小花，我偷偷摘了一朵给你，你看是不是很有趣？", },
	[19001] = {id=19001, zh_CN="我刚烤好的点心，尝尝？", },
