	[20014] = {id=20014, zh_CN="猎人", },
	[21000] = {id=21000, zh_CN="（被）入夜阶段，你免疫<color=#BC1717>恶魔阵营</color>的驱逐。\n（被）你可以抵挡一次白天阶段的驱逐，若成功抵挡，则入夜阶段你会得知此事且失去该技能。", },
	[21001] = {id=21001, zh_CN="（被）白天阶段，若你因驱逐而迷失在古堡，驱逐者将立刻开启会议。", },
	[21002] = {id=21002, zh_CN="（主）白天阶段，可以驱逐其他玩家。若驱逐的玩家属于村民阵营，你会立刻被放逐。", },
	[21003] = {id=21003, zh_CN="（主）入夜阶段，可选择一名其他玩家进行庇佑，在当前夜晚，此玩家免疫所有负面效果。（药剂、侵蚀、驱逐）", },
	[21004] = {id=21004, zh_CN="（主）入夜阶段，你可以进入梦游状态。梦游：当你被驱逐，则此次驱逐目标会随机转移给一名与你相邻的在场玩家。", },
	[21005] = {id=21005, zh_CN="（被）入夜阶段，随机得知一名其他在场玩家的身份。（不会得知身份所属玩家）", },
	[21006] = {id=21006, zh_CN="（被）入夜阶段，随机得知一条其他在场玩家笔记中的信息。", },
	[21007] = {id=21007, zh_CN="（被）免疫侵蚀和药剂效果。\n（被）白天阶段，可以得知哪些玩家被侵蚀或药剂效果所影响。\n（被）入夜阶段，随机得知一条已迷失玩家笔记中的信息，但不会知道信息来源。", },
	[21008] = {id=21008, zh_CN="（被）当你被投票放逐，你将获得胜利。", },
	[21009] = {id=21009, zh_CN="（主）白天阶段，你可以游说周围其他玩家。当全部在场玩家被游说时，安全度过夜晚后你将获得胜利。", },
	[21010] = {id=21010, zh_CN="（被）入夜阶段，免疫以你为目标的所有驱逐。\n（主）白天阶段，你可以驱逐其他玩家。当场上仅剩你一人时，你将获得胜利。", },
	[21011] = {id=21011, zh_CN="（主）限一次，可以在首夜阶段或入夜阶段选择一名玩家并复制其身份。\n被复制的玩家被你投票放逐时，你将获得胜利。若目标玩家迷失，你获得他的获胜条件。", },
	[21012] = {id=21012, zh_CN="（被）随机一名玩家成为赏金目标（目标被放逐后转移给除赏金猎人外的另一名玩家），累计成功驱逐3名赏金目标后你将获得胜利。（本局游戏人数大于8名时，每多2名玩家则你需要驱逐的目标数量+1。）\n（主）你可以在白天阶段驱逐赏金目标。", },
	[21013] = {id=21013, zh_CN="（被）白天阶段，驱逐一名<color=#38B0DE>村民阵营</color>玩家后，得知其笔记中的所有信息。", },
	[21014] = {id=21014, zh_CN="（被）被你驱逐的玩家残留印记会持续隐形，残留印记只有你能看到并且可以转移位置，但其他玩家靠近残留印记后会自动发起会议。", },
	[21015] = {id=21015, zh_CN="（主）入夜阶段，可以选择一名玩家投放药剂，直至下次白天阶段结束，其失去全部技能。", },
	[21016] = {id=21016, zh_CN="（主）入夜阶段，你可以侵蚀2名玩家。下个白天阶段，任意一名被侵蚀的玩家迷失，则另一名被侵蚀玩家也一同迷失。", },
	[21017] = {id=21017, zh_CN="（被）被你策反的首个玩家会将身份转变为侍从。当你迷失时，侍从会转变成领主。", },
	[21018] = {id=21018, zh_CN="（被）领主迷失时，你的身份转变为领主。", },
	[21019] = {id=21019, zh_CN="（主）整场游戏中两次，入夜阶段你可以猜测一名玩家的身份，如果正确则该玩家被放逐，反之你被放逐。", },
	[21020] = {id=21020, zh_CN="（主）夜晚阶段，当你被投票放逐时，可选择一名玩家。若该玩家不属于<color=#38B0DE>村民阵营</color>，则其会被放逐。", },
	[22000] = {id=22000, zh_CN="当在场玩家全部被煽动时，安全度过夜晚后你获胜。", },
	[22001] = {id=22001, zh_CN="场上只剩你一人时，你获胜。", },
	[22002] = {id=22002, zh_CN="当被复制玩家被你投票淘汰时，你获胜。", },
	[22003] = {id=22003, zh_CN="当你成功驱逐累计3位赏金目标玩家时，你获胜。", },
