	[24012] = {id=24012, zh_CN="心情值高于85%，好感/亲密提升效率上升30%，任务检定成功率提升30%", },
	[24013] = {id=24013, zh_CN="心情值低于50%，好感/亲密提升效率下降10%，互通成功率下降40%", },
	[24014] = {id=24014, zh_CN="心情值低于25%，好感/亲密提升效率下降30%，互通成功率下降70%", },
	[24015] = {id=24015, zh_CN="心情值与健康值低于20%，好感/信任/亲密停止提升，无法推进任务", },
	[24016] = {id=24016, zh_CN="好感/信任/亲密停止提升，心情值提升效率下降30%，无法推进任务", },
	[24017] = {id=24017, zh_CN="整洁度低于40%，信任/亲密提升效率降低10%，健康值每10秒下降1%", },
	[24018] = {id=24018, zh_CN="整洁度低于20%，信任/亲密提升效率降低30%，健康值每5秒下降1%", },
	[24019] = {id=24019, zh_CN="信任/亲密提升效率提升20%，健康值每分钟提升3点", },
	[24020] = {id=24020, zh_CN="伙伴在睡眠状态无法进行任何互动，若将伙伴唤醒，会进入愤怒状态", },
	[24021] = {id=24021, zh_CN="像被全世界的好运包围。", },
	[24022] = {id=24022, zh_CN="浑身充满使不完的劲儿。", },
	[24023] = {id=24023, zh_CN="心情雀跃，食欲大开。", },
	[24024] = {id=24024, zh_CN="在热闹中略带不安，雀跃中藏着一丝焦虑。", },
	[24025] = {id=24025, zh_CN="心情愉悦到了顶点，整个人洋溢着幸福与满足。", },
	[24026] = {id=24026, zh_CN="心头被春风拂过，漾着浅浅的愉悦。", },
	[24027] = {id=24027, zh_CN="心情归于最初的状态。", },
	[24028] = {id=24028, zh_CN="心里蒙上一层小乌云，兴致全无，想独自静一静。", },
	[24029] = {id=24029, zh_CN="心情像被点燃的引线，憋着一肚子火，做什么都提不起劲。", },
	[24030] = {id=24030, zh_CN="怒火冲昏了头脑。", },
	[24031] = {id=24031, zh_CN="心情彻底失控，像一头不受控制的困兽。", },
	[24032] = {id=24032, zh_CN="自信", },
	[24033] = {id=24033, zh_CN="自豪", },
	[24034] = {id=24034, zh_CN="自负", },
	[24035] = {id=24035, zh_CN="达成自洽，一切归于平和，安稳充盈心底。", },
	[24036] = {id=24036, zh_CN="心情如湖水般澄澈，平静无波。", },
	[24037] = {id=24037, zh_CN="神经绷得像拉紧的弦，每一步都小心翼翼。", },
	[24038] = {id=24038, zh_CN="不安感悄悄蔓延，生活节奏被打乱。", },
	[24039] = {id=24039, zh_CN="满心都是不安，心里七上八下。", },
	[24040] = {id=24040, zh_CN="被恐惧攥住心脏。", },
	[24041] = {id=24041, zh_CN="恐惧彻底吞噬了心神，仿佛陷入了无尽的黑暗。", },
	[24042] = {id=24042, zh_CN="思维清晰，逻辑正常，能够理性判断。", },
	[24043] = {id=24043, zh_CN="精神恍惚，注意力涣散，反应迟钝。", },
	[24044] = {id=24044, zh_CN="意识模糊，思维混沌，无法正确判断周围情况。", },
	[24045] = {id=24045, zh_CN="逻辑混乱，极度不稳定，言语行为失控。", },
	[24046] = {id=24046, zh_CN="吃得太多，撑得不想动弹，慵懒而满足。", },
	[24047] = {id=24047, zh_CN="吃饱喝足，状态正好。", },
	[24048] = {id=24048, zh_CN="肚子开始咕咕叫，有点想吃东西了。", },
	[24049] = {id=24049, zh_CN="饿得前胸贴后背，满脑子都是食物。", },
	[24050] = {id=24050, zh_CN="浑身清爽干净，精神焕发，充满自信。", },
	[24051] = {id=24051, zh_CN="整洁", },
	[24052] = {id=24052, zh_CN="灰头土脸，浑身脏兮兮的，焦躁不安。", },
	[24053] = {id=24053, zh_CN="污秽", },
	[24054] = {id=24054, zh_CN="身体健康，声音洪亮，精神抖擞。", },
	[24055] = {id=24055, zh_CN="亚健康", },
	[24056] = {id=24056, zh_CN="身体不适，语气低沉，精神萎靡。", },
	[24057] = {id=24057, zh_CN="生病", },
	[24058] = {id=24058, zh_CN="困惑", },
	[24059] = {id=24059, zh_CN="绝望", },
	[24060] = {id=24060, zh_CN="焦虑归于最初的状态。", },
	[24000] = {id=24000, zh_CN="你已经展开行动……", },
	[24001] = {id=24001, zh_CN="你已迷失，无法展开行动。", },
	[25000] = {id=25000, zh_CN="你可以在白天阶段驱逐一个玩家。", },
	[25001] = {id=25001, zh_CN="你可以在夜间驱逐一名玩家。", },
	[25002] = {id=25002, zh_CN="报告发现的残留印记并开始会议。", },
	[25003] = {id=25003, zh_CN="如果你在白天被驱逐，驱逐者会在一秒钟后发起一次会面。", },
	[25004] = {id=25004, zh_CN="在第一天开始时，随机接受两个玩家中的一个角色。", },
	[25005] = {id=25005, zh_CN="每天晚上（除了第一个晚上），你可以选择一个玩家。一天开始后，你就会知道他们在那天晚上是否采取了行动。", },
	[25006] = {id=25006, zh_CN="每天晚上（除了第一个晚上），你可以选择一个被驱逐的玩家。一天开始后，你将了解他们的角色。", },
	[25007] = {id=25007, zh_CN="每天晚上（除了第一个晚上），你可以选择一个玩家。一天开始后，你会知道那天晚上是否有人对他们使用了技能。", },
	[25008] = {id=25008, zh_CN="第一天，你将学习一个在这个游戏中不存在的角色。", },
	[25009] = {id=25009, zh_CN="在第一天，你可以找出游戏中存在哪些中立角色。", },
	[25010] = {id=25010, zh_CN="在第一天，你将了解两个相邻玩家之间是否存在不好的阵营。", },
	[25011] = {id=25011, zh_CN="（主）白天阶段，你可以驱逐其他玩家。若该玩家属于村民阵营，则你会因内疚自我放逐。", },
	[25012] = {id=25012, zh_CN="如果你第一次被投票放逐，你会在被投票后幸存下来。", },
	[25013] = {id=25013, zh_CN="在会议阶段，你可以保护一名玩家，确保他们不会遭受任何负面影响或淘汰。", },
	[25014] = {id=25014, zh_CN="如果游戏中只剩下3名玩家，并且没有玩家在当前会议中获得足够的执行投票，那么好人阵营就会获胜。", },
	[25015] = {id=25015, zh_CN="在夜晚你可以选择一名玩家投放药剂，让该玩家的技能失效，持续至第二天白天结束。", },
	[25016] = {id=25016, zh_CN="被动技能用于在黑夜结束触发胜利检测。", },
	[25017] = {id=25017, zh_CN="侵蚀玩家，在你的眼中标记他们，侵蚀所有人，获得胜利。", },
	[25018] = {id=25018, zh_CN="在会议阶段，你可以选择一个玩家并猜测他们的角色。如果你猜对了，他们就会被驱逐。", },
	[25019] = {id=25019, zh_CN="在夜晚恶魔的驱逐对你无效。", },
	[25020] = {id=25020, zh_CN="残留印记处理。", },
	[25021] = {id=25021, zh_CN="召开临时紧急会议。", },
	[25022] = {id=25022, zh_CN="如果你被投票驱逐，你将直接获胜。", },
	[25023] = {id=25023, zh_CN="每个夜晚你可以陷害一名玩家。", },
	[25024] = {id=25024, zh_CN="夜间所有以你为对象的技能和驱逐都无效。", },
	[25025] = {id=25025, zh_CN="每个白天开始时，你得知一名赏金目标玩家", },
	[25026] = {id=25026, zh_CN="你可以在白天驱逐赏金目标玩家。", },
	[25027] = {id=25027, zh_CN="整场游戏中一次，你可以抵挡白天的驱逐，如果你成功抵挡了驱逐，当天夜晚你会得知此事。", },
	[26000] = {id=26000, zh_CN="恶魔掌控了全局", },
	[26001] = {id=26001, zh_CN="村民铲除了所有敌人", },
	[26002] = {id=26002, zh_CN="所有幸存者都被煽动了", },
	[26003] = {id=26003, zh_CN="你们淘汰了一个疯狂之人", },
