	[30096] = {id=30096, zh_CN="%s 邀请你 <color=#C07B7D>%s</color>。", },
	[30097] = {id=30097, zh_CN="你成功解除了诅咒。", },
	[30098] = {id=30098, zh_CN="胜负已分！%s 优先解开了诅咒。", },
	[30099] = {id=30099, zh_CN="找个座位坐下，所有人就绪即可开始游戏。", },
	[30100] = {id=30100, zh_CN="你的目标已淘汰，新的目标是%s号。", },
	[30101] = {id=30101, zh_CN="当前人数不足，无法开始游戏。", },
	[30102] = {id=30102, zh_CN="会议次数已达上限，无法开始紧急会议。", },
	[30103] = {id=30103, zh_CN="输入配置名。", },
	[30104] = {id=30104, zh_CN="你确定要覆盖这些配置吗？", },
	[30105] = {id=30105, zh_CN="已加载预设【%s】。", },
	[30106] = {id=30106, zh_CN="你确定要删除这些配置吗？", },
	[30107] = {id=30107, zh_CN="设置的角色数量不足。", },
	[30108] = {id=30108, zh_CN="<color=#db4141>%s</color>邀请你加入剧组<color=#db4141>《%s》</color>。", },
	[39000] = {id=39000, zh_CN="会议开始了！", },
	[39001] = {id=39001, zh_CN="紧急情况！！！", },
	[39003] = {id=39003, zh_CN="人人享有平等投票权。", },
	[39004] = {id=39004, },
	[39008] = {id=39008, zh_CN="确认", },
	[39010] = {id=39010, zh_CN="确认", },
	[39011] = {id=39011, zh_CN="准备大厅", },
	[39012] = {id=39012, zh_CN="命名新预设", },
	[39013] = {id=39013, zh_CN="覆盖", },
	[40000] = {id=40000, zh_CN="欢迎来到娱乐广场，这里是宇宙的快乐中心！", },
	[40001] = {id=40001, zh_CN="这里有什么好玩的？", },
	[40002] = {id=40002, zh_CN="你是谁？", },
	[40003] = {id=40003, zh_CN="这里有着各色娱乐设施，还有新奇的表演。那边还有家特别的花草茶店。", },
	[40004] = {id=40004, zh_CN="你是做什么的？", },
	[40005] = {id=40005, zh_CN="我是个喜剧演员，专门逗人开心！我来自于遥远的星球，呃……一个无聊地方。", },
	[40006] = {id=40006, zh_CN="为什么这么说？", },
	[40007] = {id=40007, zh_CN="我的家乡是一个高度发达的文明社会，所有人都追求理性和情绪稳定。快乐对他们来说，一点也不重要。", },
	[40008] = {id=40008, zh_CN="这是你来到这里的理由吗？", },
	[40009] = {id=40009, zh_CN="没错！我在宇宙中游荡寻找欢笑。所以我选择成为一名喜剧演员，我希望通过分享快乐，唤醒每个生命对欢乐的追求。", },
	[40010] = {id=40010, zh_CN="你能表演什么？", },
	[40011] = {id=40011, zh_CN="哈，我擅长变魔术，也会讲各种星际笑话。", },
	[40012] = {id=40012, zh_CN="表演一个小把戏", },
	[40013] = {id=40013, zh_CN="献给你，我亲爱的观众朋友。", },
	[40014] = {id=40014, zh_CN="给我讲个笑话", },
	[40015] = {id=40015, zh_CN="我在旅途中看到了一个宇宙旅行社的广告，她们的广告词是：专营各类旅游线路，包括单程！哈哈哈，太好笑了！", },
	[40016] = {id=40016, zh_CN="不太好笑", },
	[40017] = {id=40017, zh_CN="好吧，我的笑话确实讲得很烂。但我诚挚地希望能给你带来一点点的欢乐。", },
	[40018] = {id=40018, zh_CN="确实好笑", },
	[40019] = {id=40019, zh_CN="谢谢你的认可！我会一直讲下去，直到笑声响彻云霄，传遍整个宇宙！", },
	[40020] = {id=40020, zh_CN="许多人来到这里，也只是简单地观看我的表演，然后匆匆离去。而你，却肯花时间和我聊天，这让我觉得我们之间似乎创建了某种羁绊。", },
	[40021] = {id=40021, zh_CN="你好……陌生人，可以给我一些电池吗？", },
	[40022] = {id=40022, zh_CN="给他电池", },
	[40023] = {id=40023, zh_CN="没什么", },
	[40024] = {id=40024, zh_CN="我的电量回满了……感觉真好。", },
	[40025] = {id=40025, zh_CN="小电池很感谢你。", },
	[40026] = {id=40026, zh_CN="小电池已经满了，谢谢……", },
	[40027] = {id=40027, zh_CN="你们有听过……哎呀！这有一个生面孔！", },
	[40028] = {id=40028, zh_CN="哦！你一定就是大名鼎鼎的旅行者，我我们早就听说过你了！见到你本人真高兴！", },
	[40029] = {id=40029, zh_CN="你消息真灵通。", },
	[40030] = {id=40030, zh_CN="哈哈，我们跟彼此很熟啦。而且，这里毕竟只是颗小小的星星，相对来说。", },
	[40031] = {id=40031, zh_CN="总之，欢迎来到范特西星球，我们很期待跟你互相分享一些……你知道的，可爱的小八卦。", },
	[40032] = {id=40032, zh_CN="我不喜欢说闲话", },
	[40033] = {id=40033, zh_CN="听起来有趣", },
	[40034] = {id=40034, zh_CN="噢，一位安静的朋友。你可以把它们当成晨报的分栏，这总比晨报本身有意思，当然，你也可以拒绝，亲爱的，放松点！", },
	[40035] = {id=40035, zh_CN="是啊，生活依靠趣闻调味。多来找我们聊聊天吧，欢迎你来我们的茶会，小爱丽丝！", },
	[40036] = {id=40036, zh_CN="您好，范特西物流为您服务！虽然我还有任务在身——嘿，您有什么需要寄出的东西吗？", },
	[40037] = {id=40037, zh_CN="发送快递", },
	[40038] = {id=40038, zh_CN="闲谈", },
	[40040] = {id=40040, zh_CN="谢谢您的惠顾。快递员将竭诚为您服务。", },
	[40041] = {id=40041, zh_CN="快递公司的人太粗鲁了，有几次差点撞到我……快？好吧，他确实……！", },
	[40042] = {id=40042, zh_CN="好吧，快递员会继续等待您的光临。", },
	[40043] = {id=40043, zh_CN="很高兴再次见到你！来坐下来谈谈艺术吧！", },
	[40044] = {id=40044, zh_CN="你为什么喜欢诗歌？", },
	[40045] = {id=40045, zh_CN="也许下次", },
	[40046] = {id=40046, zh_CN="我是一把伞，天天站在外面。诗歌就像一座桥，让我理解每一缕阳光，每一滴雨。", },
	[40047] = {id=40047, zh_CN="翼似乎给你带来了什么", },
	[40048] = {id=40048, zh_CN="收到", },
	[40049] = {id=40049, zh_CN="欢迎光临奇迹树叶。我是这家花草茶店的调茶师迪克，很高兴为您服务。", },
	[40050] = {id=40050, zh_CN="有什么推荐吗", },
	[40051] = {id=40051, zh_CN="本店特饮是“情绪花草茶”，可以根据你的情绪定制调饮。", },
	[40052] = {id=40052, zh_CN="我最近很开心", },
	[40053] = {id=40053, zh_CN="增添您的快乐，是我的荣幸。让我调制一杯果然欢乐茶送给您。", },
	[40054] = {id=40054, zh_CN="它有一种独特的味道", },
	[40055] = {id=40055, zh_CN="这杯茶饮是由多种鲜果调制的果茶，浓郁香甜。如果你想听这杯茶背后的故事，我可以讲给您听。", },
	[40056] = {id=40056, zh_CN="我愿意。", },
	[40057] = {id=40057, zh_CN="果然欢乐茶，源于一位远方旅行者的故事，他在星际旅途中邂逅了一片充满欢笑的果园。", },
	[40058] = {id=40058, zh_CN="那里的果树如云，灿烂的果实散发着幸福的香气。", },
	[40059] = {id=40059, zh_CN="他品尝了一杯由这些果实制成的茶，感受到了浓厚的欢乐与幸福。", },
	[40060] = {id=40060, zh_CN="为了将这份喜悦传递给每位顾客，我为您特别调制了这款果然欢乐茶，希望能为您带来源源不断的愉悦。", },
	[40061] = {id=40061, zh_CN="最近不太开心", },
	[40062] = {id=40062, zh_CN="很抱歉听到这些，希望我的夜晚森林茶能让您重新感到快乐。", },
	[40063] = {id=40063, zh_CN="我感觉很放松", },
	[40064] = {id=40064, zh_CN="舒缓您的心情，是我的荣幸。这杯茶饮是由多种植物的叶片和草药调制而成的，有助于让您的烦恼烟消云散。", },
	[40065] = {id=40065, zh_CN="它有什么故事吗", },
	[40066] = {id=40066, zh_CN="在一个星际世界中，有一片神秘的夜晚森林，每当夜幕降临，森林中的生物们便会齐聚一堂，共同分享他们的故事和智慧。", },
	[40067] = {id=40067, zh_CN="这片森林散发着神秘的气息，星星点点的荧光映照出美丽的景象。", },
	[40068] = {id=40068, zh_CN="为了将这份神秘感传达给您，我特别调制了夜晚森林茶，希望您在品尝的时候能感受到那片奇幻森林的魅力。", },
	[40069] = {id=40069, zh_CN="我喜欢这个故事", },
	[40070] = {id=40070, zh_CN="非常感谢您的喜爱！", },
	[40071] = {id=40071, zh_CN="迪克是专属于奇迹树叶的调茶师，并且是主人银月的专属机械生命，所以不能和您离开。", },
	[40072] = {id=40072, zh_CN="欢迎您常来关顾，迪克每日都在。", },
	[40073] = {id=40073, zh_CN="你好，我的朋友！我今天没什么事好忙，真让人不自在。", },
	[40076] = {id=40076, zh_CN="我不能总是留下这样的聊天机会，工作……工作是我的职责！唉，那只小猫最近总是抢我的活计，明明它的身体才那么大点！", },
	[40077] = {id=40077, zh_CN="哦，不不。它很可爱，皮毛也很柔软，不是吗？我只是……我只是希望多多享受我的工作。", },
	[40078] = {id=40078, zh_CN="欢迎光临，新客人你好，喵的名字是西西，客人今天有奶茶或者鲜花预约吗？还是想要跟你喜欢的人共度二人世界？", },
	[40079] = {id=40079, zh_CN="如何度过二人时光", },
	[40080] = {id=40080, zh_CN="很简单！只要进入梦之屋就可以了，喵们会为你们提供最适合私密交流的空间。梦之屋房间充足，不需要预约就能进去哦，你感兴趣吗？喵正好有空，所以带你一个人去逛逛也可以哦。", },
	[40081] = {id=40081, zh_CN="喝一杯吧", },
	[40082] = {id=40082, zh_CN="请进请进，最好最特别的情绪花草茶就在喵身后有卖，希望你能享受本店招牌~", },
	[40084] = {id=40084, zh_CN="我很感兴趣", },
	[40085] = {id=40085, zh_CN="跟喵来，梦之屋为满足大家的喜好准备了许多样式~这次先从最受欢迎的款式来参观吧！", },
	[40086] = {id=40086, zh_CN="你来啦，客人！今天有什么需要喵帮忙的？", },
	[40087] = {id=40087, zh_CN="去梦想之家", },
	[40091] = {id=40091, zh_CN="咪，欢迎你。", },
	[40092] = {id=40092, zh_CN="喂他吃点零食", },
	[40093] = {id=40093, zh_CN="喵，太感谢你了！你真是个善良的人！", },
	[40094] = {id=40094, zh_CN="你收到咪咪的感恩礼物。", },
	[40096] = {id=40096, zh_CN="客人，你今天心情怎么样？你要来杯花茶吗？", },
	[40098] = {id=40098, zh_CN="你好，欢迎。", },
	[40099] = {id=40099, zh_CN="你好", },
	[40100] = {id=40100, zh_CN="关于娱乐", },
	[40101] = {id=40101, zh_CN="我是银月，是花草茶店的老板，最近米乐星球可来了真多人呀，我这儿都快忙不过来了。", },
	[40108] = {id=40108, zh_CN="你好！我是范特西公司的阿加莎。欢迎来到米乐星球。", },
	[40109] = {id=40109, zh_CN="这是我们范特西公司买下一个卫星后特意创造的全新世界。", },
	[40110] = {id=40110, zh_CN="作为这个世界的管理者，我会竭尽全力确保为大家提供最好的帮助！", },
	[40111] = {id=40111, zh_CN="如果你有什么想知道的都可以来问我，Miller世界的重大活动或节日我也会第一时间在广场告诉大家喔！", },
	[40112] = {id=40112, zh_CN="米乐星球？", },
	[40113] = {id=40113, zh_CN="请允许我简单为你介绍一下。", },
	[40114] = {id=40114, zh_CN="在这颗与众不同的小小星球上，万物共生，万族共存，米乐星球赋予一切生命。", },
	[40115] = {id=40115, zh_CN="哪怕只是一朵花，一把椅子都有自己的生命和故事。", },
	[40116] = {id=40116, zh_CN="当然了，这一点随着你对这里的了解越发深入，你会明白的！", },
	[40117] = {id=40117, zh_CN="说到这里，偷偷给你剧透一下，我们广场上就有很多与众不同的小伙伴在等着你的到来了喔。", },
	[40118] = {id=40118, zh_CN="其他的东西", },
	[40119] = {id=40119, zh_CN="它们是什么？", },
	[40120] = {id=40120, zh_CN="这就是秘密，你需要自己去发现它！", },
	[40121] = {id=40121, zh_CN="哈哈！你问对人了！", },
	[40122] = {id=40122, zh_CN="你听过古堡奇妙夜吗？那是我们为大家精心准备的全息游戏。", },
	[40123] = {id=40123, zh_CN="大家可以扮演不同角色，在我们重金打造的古堡里沉浸式体验紧张刺激的语言和肢体的博弈。", },
	[40124] = {id=40124, zh_CN="当然，还有古堡奇妙夜和星际舞会。期待你在我们的游戏里找到一同前行的伙伴！", },
	[40125] = {id=40125, zh_CN="对了，各位的家园提供了配套的设施。", },
	[40126] = {id=40126, zh_CN="有时候去别人家串串门，窝在家园点点外卖，收收快递不是也很放松吗？", },
	[40127] = {id=40127, zh_CN="更多的惊喜你回到你的家园就知道啦。", },
	[40128] = {id=40128, zh_CN="如果你在游玩中遇到任何问题或意见，也欢迎随时来找我反馈。", },
	[40129] = {id=40129, zh_CN="作为这个世界的管理者，我会竭尽全力确保大家拥有最好的感官体验。", },
	[40130] = {id=40130, zh_CN="祝您在米乐星球里过得愉快！", },
	[40131] = {id=40131, zh_CN="很高兴再次见到你！最近的活动你听说了吗？", },
	[40132] = {id=40132, zh_CN="这是机密，到时候我自然会通知你的。", },
	[40133] = {id=40133, zh_CN="很高兴再次见到你！最近有一个神秘的活动正在筹备，等筹备完成的话……", },
	[40135] = {id=40135, zh_CN="喂，你走近我做什么？难道你没看见我正在闭目养神吗？", },
	[40137] = {id=40137, zh_CN="算了，我兰花大人有大量不和你计较。", },
	[40138] = {id=40138, zh_CN="不过你是新来的人？那我可得好好介绍介绍自己。", },
	[40139] = {id=40139, zh_CN="我是艾拉，一朵世间罕见的兰花。", },
	[40140] = {id=40140, zh_CN="我不轻易开花，无数人前来花草茶店就是为了一睹我的美貌。", },
	[40141] = {id=40141, zh_CN="可惜我才不会轻易展现给他们看呢，不过话说回来……", },
	[40142] = {id=40142, zh_CN="你是我见过最没礼貌的家伙，每一个来到我跟前的人通常都会带着礼物或肥料。", },
	[40143] = {id=40143, zh_CN="而你居然就这样冒冒失失地闯了过来！", },
	[40144] = {id=40144, zh_CN="好吧", },
	[40145] = {id=40145, zh_CN="快给我停下！你在干什么！太无理了！", },
	[40146] = {id=40146, zh_CN="浇水吗？", },
	[40147] = {id=40147, zh_CN="这勉强可以接受。", },
	[40148] = {id=40148, zh_CN="好吧，你很幸运。今天我不想和你争论。我破例让你在这里多待一会儿。", },
	[40149] = {id=40149, zh_CN="你又来了？上次不是才见过面吗？", },
	[40150] = {id=40150, zh_CN="你真美", },
	[40151] = {id=40151, zh_CN="很抱歉打扰你", },
	[40152] = {id=40152, zh_CN="你还需要问吗？当然，我已经知道了。", },
	[40153] = {id=40153, zh_CN="但是我的时间很宝贵，如果你没有别的事，就走吧，不要打扰我休息。", },
	[40159] = {id=40159, zh_CN="水", },
	[40160] = {id=40160, zh_CN="我说过了！我只喝花草茶！你这个粗鲁无理的家伙！气坏我了！", },
	[40161] = {id=40161, zh_CN="你好，新朋友！", },
	[40164] = {id=40164, zh_CN="我是托马斯，托马斯就是我，广场上自由的小火车！", },
	[40165] = {id=40165, zh_CN="我每天在行驶在进入米乐星球的必经之路上，见证了无数新伙伴的到来！哈哈哈！", },
	[40166] = {id=40166, zh_CN="你会觉得无聊吗？", },
	[40167] = {id=40167, zh_CN="怎么会呢！每次见到新的伙伴，我都很开心！", },
	[40168] = {id=40168, zh_CN="还在原来的地方", },
	[40169] = {id=40169, zh_CN="朋友，就算是同样的道路，因为遇到的人不一样，我的每天也变得不一样。", },
	[40171] = {id=40171, zh_CN="相信我，这里是米乐星球，你也会遇到那些让你每天都不一样的朋友！", },
	[40172] = {id=40172, zh_CN="又见面啦~最近过得还好吗！我的朋友！", },
	[40173] = {id=40173, zh_CN="好", },
	[40174] = {id=40174, zh_CN="太好了！", },
	[40175] = {id=40175, zh_CN="就好了", },
	[40176] = {id=40176, zh_CN="没关系！日子还长着呢！你会找到的！", },
	[40177] = {id=40177, zh_CN="你听说过古堡奇妙夜吗？你想试一试吗？", },
	[40178] = {id=40178, zh_CN="如果你没有经历过也没关系，毕竟，即使是最机智的侦探也是从助理做起的。", },
	[40179] = {id=40179, zh_CN="让我试试", },
	[40180] = {id=40180, zh_CN="这是一个惊险刺激的推理游戏。你准备好了就告诉我。", },
	[40181] = {id=40181, zh_CN="进入古堡奇妙夜", },
	[40182] = {id=40182, zh_CN="我会考虑的", },
	[40183] = {id=40183, zh_CN="嘿，这不是新来的吗？来和我们一起玩，你有什么想法吗？", },
	[40184] = {id=40184, zh_CN="布兰登！收起你那副吊儿郎当的模样，太失礼了！", },
	[40185] = {id=40185, zh_CN="不好意思啊！欢迎你来到米乐星球，我叫布伦达，平日里喜欢诗歌和音乐，很高兴认识你！", },
	[40186] = {id=40186, zh_CN="见到你很高兴。", },
	[40187] = {id=40187, zh_CN="切，又是这副虚头巴脑的模样，真讨厌。", },
	[40188] = {id=40188, zh_CN="我叫布兰登，真不想承认我和布伦达居然是双胞胎，平日里我最讨厌的就是她这副文绉绉的模样。", },
	[40189] = {id=40189, zh_CN="你！你讨厌！", },
	[40190] = {id=40190, zh_CN="请停止……", },
	[40191] = {id=40191, zh_CN="哼，我也不想和他一起聊天。有他没我，你在我俩间选一个吧。", },
	[40192] = {id=40192, zh_CN="布伦达", },
	[40193] = {id=40193, zh_CN="布兰登", },
	[40194] = {id=40194, zh_CN="谢谢！我就知道你是个有品味的人，很高兴和你聊天。", },
	[40195] = {id=40195, zh_CN="你想了解什么呢~", },
	[40196] = {id=40196, zh_CN="你知道吗，在午夜十二点的时候，米乐星球那些逝去的生命都会在夜里苏醒。", },
	[40197] = {id=40197, zh_CN="比如那些凋落了的花，他们会在空气中再次绽放，在荧光中重新获得生命。", },
	[40198] = {id=40198, zh_CN="真的吗？", },
	[40199] = {id=40199, zh_CN="当然了！具体的内容，我下次再告诉你！", },
	[40200] = {id=40200, zh_CN="看到你", },
	[40201] = {id=40201, zh_CN="下次见！", },
	[40202] = {id=40202, zh_CN="（布伦达对你的好感度增加了20点）", },
	[40203] = {id=40203, zh_CN="嘿！怪不得第一眼看你就投缘，有什么问题放心问我就行！", },
	[40204] = {id=40204, zh_CN="有什么好吃的吗？", },
	[40205] = {id=40205, zh_CN="有什么好玩的吗？", },
	[40206] = {id=40206, zh_CN="远在天边近在眼前，花草茶店的特调茶，那可太好喝啦！", },
	[40207] = {id=40207, zh_CN="另外如果你想点外卖，记得去找法斯特，他送餐可及时啦！", },
	[40208] = {id=40208, zh_CN="嘿！那你可就问对人啦！去试试古堡奇妙夜吧！", },
	[40209] = {id=40209, zh_CN="我可是古堡奇妙夜十级爱好者呢！下次玩可以叫上我！", },
	[40211] = {id=40211, zh_CN="除了这些，米乐星球还有很多很棒的地方，你感兴趣吗！", },
	[40212] = {id=40212, zh_CN="啊，不过时间不早了！期待和你下次聊天！", },
	[40214] = {id=40214, zh_CN="记得来找我！", },
	[40215] = {id=40215, zh_CN="（布兰登对你的好感度增加了20点）", },
	[40220] = {id=40220, zh_CN="你想知道什么？", },
	[40221] = {id=40221, zh_CN="你为什么在这里？", },
	[40222] = {id=40222, zh_CN="我嘛，无家可归了！", },
	[40223] = {id=40223, zh_CN="你的星球被摧毁了？", },
	[40224] = {id=40224, zh_CN="没有那么夸张啦！我只不过是太晚回家又把钥匙丢了，所以只能在这里游荡。", },
	[40225] = {id=40225, zh_CN="听起来更糟", },
	[40226] = {id=40226, zh_CN="是吗？我不这么觉得！", },
	[40227] = {id=40227, zh_CN="这是什么地方？", },
	[40228] = {id=40228, zh_CN="这是星际舞会哦，你都不知道是怎么进来的！", },
	[40229] = {id=40229, zh_CN="我是更高级的客人", },
	[40230] = {id=40230, zh_CN="哦？！那你能请我到什么贵宾区域吗？我还从来没去过呢。", },
	[40231] = {id=40231, zh_CN="我开玩笑的！", },
	[40235] = {id=40235, zh_CN="我在做的事可是一级机密，不能轻易告诉你。不如你告诉我为什么你来这里吧。", },
	[40236] = {id=40236, zh_CN="你在陷害我吗？", },
	[40237] = {id=40237, zh_CN="这怎么能叫套话呢。不能不对环境保持警惕和观察哦。", },
	[40239] = {id=40239, zh_CN="这是星际舞会，汇集了从各地流浪而来的旅行者，大家都有着不为人知的故事呢。", },
	[40240] = {id=40240, zh_CN="古里古怪的", },
	[40241] = {id=40241, zh_CN="那是你观察得不够仔细。", },
	[40245] = {id=40245, zh_CN="要问这么令人悲伤的问题吗？我会想起不该想起的人。", },
	[40246] = {id=40246, zh_CN="对不起", },
	[40247] = {id=40247, zh_CN="那也不用道歉，仙人掌就是永远受伤永远热恋！", },
	[40248] = {id=40248, zh_CN="坠入爱河是一种幸运", },
	[40249] = {id=40249, zh_CN="真的吗？谁规定的！", },
	[40250] = {id=40250, zh_CN="星际舞会可是认识新朋友的好地方，我相信我会在这里遇到我的目的地的。", },
	[40251] = {id=40251, zh_CN="你是什么意思？", },
	[40252] = {id=40252, zh_CN="我的目的地是我喜欢的人所在的地方，而我在等待我喜欢的人。", },
	[40253] = {id=40253, zh_CN="爱情使人年轻", },
	[40254] = {id=40254, zh_CN="是的！全身心爱每一个人都很幸福哦。", },
	[40258] = {id=40258, zh_CN="在两段旅程的中间轻易回家会让自己泄气， 再也不想出发的，这是我的经验。", },
	[40259] = {id=40259, zh_CN="你为什么不呆在家里？", },
	[40260] = {id=40260, zh_CN="不可以哦，我的身上可是背负着无比重要的任务呢！尽管会让喵难过，也要不停奔波，但是让喵们都过得快乐就好了！", },
	[40261] = {id=40261, zh_CN="这里是星际舞会，你可以和任何朋友一起跳舞。", },
	[40262] = {id=40262, zh_CN="你有很多朋友？", },
	[40263] = {id=40263, zh_CN="工作太忙啦！就算合拍的朋友，长久不联络还是会慢慢忘记彼此呢。真是悲伤的故事。", },
	[40264] = {id=40264, zh_CN="你的薪水一定很高", },
	[40265] = {id=40265, zh_CN="嗯，这是个秘密。", },
	[40266] = {id=40266, zh_CN="坐在中间的玩家将成为说书人", },
	[40267] = {id=40267, zh_CN="在故事讲述者开始游戏之前，所有玩家都必须坐下来", },
	[40268] = {id=40268, zh_CN="感谢你的祝福，请期待后续剧情。", },
	[40269] = {id=40269, zh_CN="愚蠢的人类……我允许你提供食物", },
	[40270] = {id=40270, zh_CN="没有食物吗？伟大的阿波菲斯王不会和你说话！", },
	[40271] = {id=40271, zh_CN="伟大的阿波菲斯王不想和你说话。", },
	[40272] = {id=40272, zh_CN="看到我旁边的画了吗？每一个都是由大师创作的……哪位大师？当然是我！", },
	[40273] = {id=40273, zh_CN="每个人都应该有欣赏艺术的能力。", },
	[40274] = {id=40274, zh_CN="你捧起一把泉水，冰凉、清澈的水让你感觉清醒多了。", },
	[40275] = {id=40275, zh_CN="突然，你听到了微弱的低语，水面上泛起了涟漪。一条巨大鱼尾的影子闪了过去。", },
	[40276] = {id=40276, zh_CN="你不禁想知道……这个池子真的有那么深吗？", },
	[40277] = {id=40277, zh_CN="当你的手接近水面时，它溅起水花，似乎在抗拒你的靠近。", },
	[40279] = {id=40279, zh_CN="嘿，别弄脏我的水！", },
	[40281] = {id=40281, zh_CN="你的水？", },
	[40282] = {id=40282, zh_CN="我是世界上最稀有、最高贵的美人鱼……这个喷泉是我的住所。", },
	[40283] = {id=40283, zh_CN="人类只生活在最纯净的水中，如果陆地生物肮脏的四肢伸到水里，水很快就会变得浑浊。离这儿远点！", },
	[40284] = {id=40284, zh_CN="声音渐渐消失，水面掀起巨大的水花，你不得不后退。", },
	[40285] = {id=40285, zh_CN="当然，这是我的水！这是我辛辛苦苦收集的最纯净的水源。别再靠近它了！", },
	[40286] = {id=40286, zh_CN="你拿起蛋糕。", },
	[40287] = {id=40287, zh_CN="你找到了一个宝箱", },
	[40288] = {id=40288, zh_CN="这个宝箱被打开了。", },
	[40290] = {id=40290, zh_CN="你试着在书里找到一些东西。", },
	[40291] = {id=40291, zh_CN="这里的书被人拿走了。", },
	[40292] = {id=40292, zh_CN="你把你的手放在针上，唱片开始旋转，从设备中播放优美的古典音乐。", },
	[40293] = {id=40293, zh_CN="天哪，它还能发出声音！惊讶于这个古董还能正常工作，你忍不住走近它。更让你惊讶的是，它竟然做出了回应。", },
	[40294] = {id=40294, zh_CN="说话", },
	[40295] = {id=40295, zh_CN="离开", },
	[40297] = {id=40297, zh_CN="里面的灰烬已经聚集在一起，你花了很大的力气才把它们清理干净。", },
	[40298] = {id=40298, zh_CN="壁炉已经打扫干净了。", },
	[40299] = {id=40299, zh_CN="女神以慈爱的慈悲注视着你。", },
	[40300] = {id=40300, zh_CN="女神脸上的表情虔诚而庄严。", },
	[40301] = {id=40301, zh_CN="一支旧蜡烛，等待被点燃……", },
	[40302] = {id=40302, zh_CN="因为某些原因，烛芯没有点亮。", },
	[40303] = {id=40303, zh_CN="几百年来，我一直在倾听这里人们的祈祷……路人，你有什么想知道的吗？", },
	[40306] = {id=40306, zh_CN="瀑布……", },
	[40307] = {id=40307, zh_CN="一棵树，旁边有一棵更细的树，似乎有某种意义。", },
	[40308] = {id=40308, zh_CN="只是山景。", },
	[40309] = {id=40309, zh_CN="几棵枯树和一条蜿蜒的小路。", },
	[40311] = {id=40311, zh_CN="啊……我看到了，我看到了你的命运，可怜的小娃娃……你只能循环往复。", },
	[40314] = {id=40314, zh_CN="你试着校准时钟。", },
	[40315] = {id=40315, zh_CN="上面的指针以恒定的速度转动", },
	[40316] = {id=40316, zh_CN="我很高兴我可以整天欣赏艺术。", },
	[40317] = {id=40317, zh_CN="愚蠢的人类……", },
	[40318] = {id=40318, zh_CN="这有一个蛋糕，看起来很好吃。", },
	[40320] = {id=40320, zh_CN="有一个盒子。", },
	[40322] = {id=40322, zh_CN="书架上有很多书。", },
	[40323] = {id=40323, zh_CN="看上去是个很好吃的蛋糕呢！", },
	[40325] = {id=40325, zh_CN="火焰非常微弱。", },
	[40326] = {id=40326, zh_CN="和女神像待在一起让你无比安心。", },
	[40328] = {id=40328, zh_CN="蜡烛发出微弱的光。", },
	[40329] = {id=40329, zh_CN="这是一幅画。", },
	[40334] = {id=40334, zh_CN="这面镜子看起来很奇怪。", },
	[40336] = {id=40336, zh_CN="这是一个古典风格的钟。", },
	[40337] = {id=40337, zh_CN="初次见面，很高兴见到你……一个在时间之网中找到了自己的灵魂。欢迎回家。", },
	[40338] = {id=40338, zh_CN="时间之网？", },
	[40339] = {id=40339, zh_CN="是的，那就是你来的地方，许多不完整的灵魂会在那里迷失，拥有一个完整的灵魂是多么美妙啊。", },
	[40340] = {id=40340, zh_CN="迷失？听起来很可怕", },
	[40341] = {id=40341, zh_CN="是啊，不过，时空当中具有无数机会，神明对迷失的灵魂也同样仁慈。", },
	[40342] = {id=40342, zh_CN="我的职责正是通过你将他们带到这个世界，就像打开一枚卵，通过一点一滴的相处，你可以赋予他们新生。", },
	[40343] = {id=40343, zh_CN="我可以做到什么？", },
	[40344] = {id=40344, zh_CN="跟我来。", },
	[40345] = {id=40345, zh_CN="我会根据你的描述为你找到最合适的伴侣。他们会成为你在这个世界上的向导并陪伴你。", },
	[40346] = {id=40346, zh_CN="通过互动你们可以在米乐星球里一起创造新的记忆。", },
	[40347] = {id=40347, zh_CN="你最多可以有五个同伴和你一起生活。", },
	[40348] = {id=40348, zh_CN="如果相处不顺，您可以选择在通讯录中解散它们。我会把他们送回时间之网，等待灵魂的重生。", },
	[40349] = {id=40349, zh_CN="现在试着用你想到的关键字创建一个陌生的同伴。", },
	[40350] = {id=40350, zh_CN="让我想想", },
	[40351] = {id=40351, zh_CN="你好，我叫客客！教我们的新手迈出第一步的人！早就听说了你的到来，所以我第一时间就赶来了！欢迎来到米乐星球！", },
	[40352] = {id=40352, zh_CN="嗨", },
	[40353] = {id=40353, zh_CN="嘿嘿，来到新家很紧张吧？你有什么想了解的吗？", },
	[40354] = {id=40354, zh_CN="这里有什么好玩的吗？", },
	[40355] = {id=40355, zh_CN="你问的正是时候。一起去我家吧！", },
	[40356] = {id=40356, zh_CN="小心，我要射击了。", },
	[40357] = {id=40357, zh_CN="哈？", },
	[40358] = {id=40358, zh_CN="我知道这个", },
	[40359] = {id=40359, zh_CN="啊哈，开个小玩笑。这个可是在古堡奇妙夜里必须学会的技能呢。你想听更具体的吗？", },
	[40360] = {id=40360, zh_CN="你已经知道这是什么了？是的，这是古堡奇妙夜中反派阵营的技能，那你还需要我介绍具体内容吗？", },
	[40361] = {id=40361, zh_CN="需要。", },
	[40362] = {id=40362, zh_CN="不需要。", },
	[40363] = {id=40363, zh_CN="那就让点点给你介绍一下吧。别小看他，他是这方面的高手！在古堡里面，你可不能小瞧任何一只小猫咪。", },
	[40364] = {id=40364, zh_CN="那下面就看你的了！想玩古堡奇妙夜记得来找我喔。", },
	[40365] = {id=40365, zh_CN="一只猫？", },
	[40366] = {id=40366, zh_CN="是的，是我。", },
	[40367] = {id=40367, zh_CN="古堡奇妙夜是互娱公司为玩家提供的休闲娱乐模式。玩家可以选择与同伴一起游戏，也可以选择与陌生人随机配对开始游戏。", },
	[40368] = {id=40368, zh_CN="游戏发生在一个神秘的城堡里，由三个阵营组成:村民、邪恶和中立。", },
	[40369] = {id=40369, zh_CN="善良的人被称为村民阵营，其中包括洗衣妇、加拿大鹅、共情者、警长、调查员、纯洁者、僧侣、市长、守望者、士兵、守墓人、占卜师和裁缝。他们每个人都有自己独特的技能。", },
	[40370] = {id=40370, zh_CN="中立阵营由鸽子和猎鹰组成，而邪恶阵营包括女妖，夜行人，药剂师，逆行人和间谍。", },
	[40371] = {id=40371, zh_CN="这是游戏手册，你可以翻看一下。", },
	[40372] = {id=40372, zh_CN="我想看看", },
	[40373] = {id=40373, zh_CN="好，下次一定", },
	[40374] = {id=40374, zh_CN="那我们回去吧。对于一个新手来说，光听是不够的，你更需要自己去尝试。那现在就看你的了！如果你想玩古堡奇妙夜，来找我吧。", },
	[40375] = {id=40375, zh_CN="现在我们回去。对于一个新手来说，光听是不够的，你更需要自己去尝试。那现在就看你的了！如果你想玩古堡奇妙夜，来找我吧。", },
	[40376] = {id=40376, zh_CN="你好，我能帮什么忙吗？", },
	[40377] = {id=40377, zh_CN="玩古堡奇妙夜", },
	[40378] = {id=40378, zh_CN="看游戏手册", },
	[40379] = {id=40379, zh_CN="嗨！我是你的专属伴侣。你可以自由地和我交流，也可以带我去任何你想去的地方。", },
	[40380] = {id=40380, zh_CN="我可以陪你进古堡奇妙夜。试着点击跟随按钮，带我一起去吧。", },
	[40381] = {id=40381, zh_CN="破晓女神帕拉丁，被天界骑士赐名，同时赐予了晨曦之力，晨曦乃是刺破黑暗的第一道光芒。", },
	[40382] = {id=40382, zh_CN="出生天界的帕拉丁，除了打仗从来没有离开过天界。在战争中总是作为第一把尖刀，冲锋在前，无所畏惧。", },
	[40383] = {id=40383, zh_CN="这就是你的命运吗？", },
	[40384] = {id=40384, zh_CN="我愿意", },
	[40385] = {id=40385, zh_CN="再想想", },
	[40386] = {id=40386, zh_CN="属于月球天体王室的月影，本质上是一束无情无感的月光，在虚空战争中，月球天体遭受重大打击，经济倒退，月光能量也在不受控制的流失。", },
	[40387] = {id=40387, zh_CN="调查发现月光能量在被虚空战争的后遗产物“数字音乐黑洞”所吞噬。为了月球天体王室的荣耀，你需要集结盟友，夺取“音乐数字黑洞”的监管权，解放月光能量。", },
	[40391] = {id=40391, zh_CN="在她担任联邦调查员期间，在调查地球上的一处古代遗迹时，她感染了一种未知的在担任联邦调查特工期间，调查地球天体一处古老遗迹时，染上了不知名的疫病；但以凡人身躯抗衡疫病，头发变得雪白，获得了操纵低温的能力。疾病。然而，她成功地用她的凡人身体抵抗了疾病，她的头发变白了，获得了控制低温的能力。", },
	[40392] = {id=40392, zh_CN="在地球执行任务时，与古老国度的使者结缘，原本幸福的生活却在一次次任务和战争中打破。", },
	[40396] = {id=40396, zh_CN="来自极度原始的丛林国家，这里的狼族骁勇善战，作为王子自然是其中的佼佼者。", },
	[40397] = {id=40397, zh_CN="一身血腥战功的狼族王子被魔女带出丛林，来到了大都市。经历了没有战乱的美好世界，狼族王子希望将狼族带向更加美好的未来。", },
	[40398] = {id=40398, zh_CN="在虚空战争中，一道光芒刺入敌军前锋，斩落无数敌人，这是力量的体现，是一个可以配得上首领的男人。", },
	[40402] = {id=40402, zh_CN="一只诞生在斯特鲁山脉的混沌猫，这只猫因为受到了“数字音乐黑洞”的影响，获得了可以接受诸天万界的各种情报，因而被不停捕捉，直到被一个魔女收留，度过一段幸福时光。", },
	[40403] = {id=40403, zh_CN="为自由而战！喵~", },
	[40406] = {id=40406, zh_CN="……哦……哦……哇……呼呼（一个虚无飘渺的声音缓缓升起）", },
	[40407] = {id=40407, zh_CN="飘渺的灵魂在哪里，你的愿望是什么？", },
	[40408] = {id=40408, zh_CN="沉默", },
	[40409] = {id=40409, zh_CN="我们被困于此，被诅咒困于此地。", },
	[40410] = {id=40410, zh_CN="如何解开诅咒？", },
	[40412] = {id=40412, zh_CN="\"解开此间的诅咒，需要找到关键之人，曼勒会把他的线索投影到这个世界\"。", },
	[40413] = {id=40413, zh_CN="我明白了。", },
	[40415] = {id=40415, zh_CN="你需要一个身份才能进入这个世界。", },
	[40417] = {id=40417, zh_CN="好的。", },
	[40418] = {id=40418, zh_CN="图娜来自地球西伯利亚地区的一个古老的精灵王国。作为一名魔法使者，她在世界各地旅行，以保持与世隔绝的精灵王国与外界的联系。", },
	[40419] = {id=40419, zh_CN="在她的旅行中，她爱上了一个强大的剑客，他们结婚了，但他们的幸福生活是短暂的。剑客繁忙的日程和无法预测的行踪给图娜带来了巨大的痛苦。当图娜渴望丈夫的出现时，只有一个小身影陪伴着她。", },
	[40423] = {id=40423, zh_CN="雪女的配剑“洪波”，无往不利的神器，在剑锷处刻有祝福铭文“好运”", },
	[40424] = {id=40424, zh_CN="帕拉丁的时钟，天界没有黑夜，时钟在这里没有意义。钟表盘上还刻着一句话“希望你和我的剑，都像时间一样，无情且锋利。”", },
	[40425] = {id=40425, zh_CN="一张破旧的契约，印章似乎属于某位神祇。", },
	[40426] = {id=40426, zh_CN="高科技匕首，多功能，还可以变成激光炮，但是退还礼物那人说：“太短了配不上他。”", },
	[40427] = {id=40427, zh_CN="天光乍破远山的轮廓。", },
	[40428] = {id=40428, zh_CN="精灵魔女房间的烛台。这副烛台非常精致，每次和鬼剑士烛光晚餐，它都是桌上必备之物。光芒中仿佛映照着当时两人的甜蜜往事。", },
	[40429] = {id=40429, zh_CN="镜子是两个世界之间的门扉，让我们瞥见非凡的事物。", },
	[40430] = {id=40430, zh_CN="来自冥界的魔药。", },
	[40431] = {id=40431, zh_CN="还带着晨露的艳丽玫瑰，晨露中蕴含着晨曦之力，但这朵玫瑰却是地球之物。", },
	[40432] = {id=40432, zh_CN="帕拉丁用于释放晨曦之力的权杖，不知何时在权杖身上刻着一句话“与剑同在”", },
	[40433] = {id=40433, zh_CN="狼族王子习惯性将硕大的镶钻金戒指戴在最显眼的大拇指，用以彰显尊贵的身份。", },
	[40434] = {id=40434, zh_CN="……", },
