	[46005] = {id=46005, zh_CN="嘿！别推我！", },
	[46006] = {id=46006, zh_CN="啊！粗心的家伙！", },
	[46007] = {id=46007, zh_CN="你有眼睛吗？看路！", },
	[46008] = {id=46008, zh_CN="嘿！你撞到我了。", },
	[46009] = {id=46009, zh_CN="你撞了我！好疼。", },
	[46010] = {id=46010, zh_CN="你知道路该怎么走吗！", },
	[46011] = {id=46011, zh_CN="算了，跟你这样的人讲道理是没用的。", },
	[46012] = {id=46012, zh_CN="对不起，请不要撞到我。", },
	[46013] = {id=46013, zh_CN="嘿！下次小心点！", },
	[46014] = {id=46014, zh_CN="你怎么能这样撞到别人呢！你把我推开了！", },
	[46015] = {id=46015, zh_CN="你要是再撞我，可别怪我失礼！", },
	[46016] = {id=46016, zh_CN="嘿！看好路，小心点！", },
	[46017] = {id=46017, zh_CN="算了，算了，我不会跟你计较。", },
	[46018] = {id=46018, zh_CN="哦！你撞到我了，没关系，我原谅你。", },
	[46019] = {id=46019, zh_CN="我挡住你的路了吗？很抱歉。", },
	[46020] = {id=46020, zh_CN="对不起，我一定是挡住你的路了。", },
	[46021] = {id=46021, zh_CN="又一次倒霉，我的人生真是不幸。", },
