	[50009] = {id=50009, zh_CN="efgh", },
	[50010] = {id=50010, zh_CN="找到草莓蛋糕\n找到巧克力慕斯\n找到草莓奶昔蛋糕\n找到巧克力奶油蛋糕\n找到黄油蛋糕", },
	[50011] = {id=50011, zh_CN="找到《奔流》\n找到《枯萎》\n找到《稀薄》\n找到《山间小道》", },
	[50012] = {id=50012, zh_CN="是否一键生成发言内容？", },
