	[50014] = {id=50014, },
	[50015] = {id=50015, },
	[50016] = {id=50016, },
	[50017] = {id=50017, },
	[50019] = {id=50019, },
	[50020] = {id=50020, },
	[50021] = {id=50021, },
	[50022] = {id=50022, },
	[50023] = {id=50023, },
	[50024] = {id=50024, },
	[50025] = {id=50025, },
	[50026] = {id=50026, },
	[50027] = {id=50027, },
	[50028] = {id=50028, },
	[50029] = {id=50029, },
	[50030] = {id=50030, zh_CN="特洛菲鼠可真是太可怕了，要吓宕机了。", },
	[50031] = {id=50031, zh_CN="你真贴心呀，谢谢你记得我。", },
	[50032] = {id=50032, zh_CN="你的礼物我超级喜欢，谢谢！", },
	[50033] = {id=50033, zh_CN="谢谢你，我会把它好好珍藏起来的。", },
	[50034] = {id=50034, zh_CN="天哪，这是你给我的吗？我不会忘记这惊喜的一天！", },
	[50035] = {id=50035, zh_CN="谢谢你，我想这或许也会成为一份不错的回忆。", },
	[50036] = {id=50036, zh_CN="我会时常看见它就想到你的。", },
	[50037] = {id=50037, zh_CN="唔……让我想想我该送你什么好呢？", },
	[50038] = {id=50038, zh_CN="真是破费啦！", },
	[50039] = {id=50039, zh_CN="你的心意我收到啦！", },
	[50040] = {id=50040, zh_CN="啊嘞，这或许也是独特的回忆呢！", },
	[50041] = {id=50041, zh_CN="唔呣，我想我会一直记得这份礼物的。", },
	[50042] = {id=50042, zh_CN="或许，你还愿意更了解我一点吗？", },
	[50043] = {id=50043, zh_CN="礼物不重要，是你送的就好啦！", },
	[50044] = {id=50044, zh_CN="能够收到礼物我就很开心啦！", },
	[50045] = {id=50045, zh_CN="哦！这可真是好东西！", },
	[50046] = {id=50046, zh_CN="眼光很好，我很喜欢。", },
	[50047] = {id=50047, zh_CN="这正是我需要的！你可太懂我了！", },
	[50048] = {id=50048, zh_CN="太厉害了！居然连这个都有。", },
	[50049] = {id=50049, zh_CN="谢谢啦！这是我收到最好的礼物了。", },
	[50050] = {id=50050, zh_CN="谢了，改天我也送你一个吧。", },
	[50051] = {id=50051, zh_CN="哇，挑选它用了不少时间吧，谢谢你！", },
	[50052] = {id=50052, zh_CN="是我没有的东西诶！", },
	[50053] = {id=50053, zh_CN="还从来没人送过我这个呢！", },
	[50054] = {id=50054, zh_CN="好漂亮！但是……该怎么用呢？", },
	[50055] = {id=50055, zh_CN="可别想用这个就收买我！", },
	[50056] = {id=50056, zh_CN="天，你从哪里买到它的？", },
	[50057] = {id=50057, zh_CN="嘘！答应我，再也别拿这个送人了好吗？", },
	[50058] = {id=50058, zh_CN="如果我有错，请让法律制裁我吧。", },
	[50059] = {id=50059, zh_CN="真看不出来，你的审美……还挺独特……", },
	[50060] = {id=50060, zh_CN="收下这个礼物，那我们就是好朋友啦！", },
	[50061] = {id=50061, zh_CN="谢谢你！真没想到还能收到这样的礼物！", },
	[50062] = {id=50062, zh_CN="真的是送给我的吗？谢谢你！", },
	[50063] = {id=50063, zh_CN="这是……给我的吗？", },
	[50064] = {id=50064, zh_CN="收到啦，谢谢你送我的礼物！", },
	[50065] = {id=50065, zh_CN="花费很多心思才准备好的吧，辛苦啦！", },
	[50066] = {id=50066, zh_CN="是我哪里做得不对吗，要送我……这个？", },
	[50067] = {id=50067, zh_CN="你是怎么会想到要送我这个的……", },
	[50068] = {id=50068, zh_CN="啊！我想……你是不是有什么地方误会我啦！", },
	[50069] = {id=50069, zh_CN="太好啦，关系又更进一步啦！", },
	[50070] = {id=50070, zh_CN="让我想想看，今天是什么特殊日子呢？", },
	[50071] = {id=50071, zh_CN="哇！果然还是你懂我！", },
	[50072] = {id=50072, zh_CN="咱们还真是越来越心有灵犀啦！", },
	[50073] = {id=50073, zh_CN="这就是收到礼物的感觉吗？谢谢你！", },
	[50074] = {id=50074, zh_CN="真希望能够早点遇到你啊！", },
	[50075] = {id=50075, zh_CN="是很少见的风格诶……我真的可以驾驭吗？", },
	[50076] = {id=50076, zh_CN="这……这真的是你喜欢的吗？", },
	[50077] = {id=50077, zh_CN="NO！有朝一日我一定要让你自己试试！", },
	[50078] = {id=50078, zh_CN="这绝对绝对是我最喜欢的礼物！没有之一！", },
	[50079] = {id=50079, zh_CN="你居然知道我想要这个！载入史册的一天！", },
	[50080] = {id=50080, zh_CN="我要把你送我的宝贝都堆成山！", },
	[50081] = {id=50081, zh_CN="它对我来说就像我们的情谊一样珍贵！", },
	[50082] = {id=50082, zh_CN="哇，才发现你居然已经送了我这么多礼物了！", },
	[50083] = {id=50083, zh_CN="只要是你送的，对我来说都是最珍贵的。", },
	[50084] = {id=50084, zh_CN="你是想让我换个风格吗？这我可得考虑一下……", },
	[50085] = {id=50085, zh_CN="这可真是一段全新的体验啊，我已经开始期待了！", },
	[50086] = {id=50086, zh_CN="你是在暗示我什么吗？", },
	[50087] = {id=50087, zh_CN="谢谢你，我很喜欢。", },
	[50088] = {id=50088, zh_CN="你是怎么做到的！居然一次就能看出来我喜欢什么！", },
	[50089] = {id=50089, zh_CN="这是你送我的礼物，我要好好保存起来！", },
	[50090] = {id=50090, zh_CN="这是……给我的？", },
	[50091] = {id=50091, zh_CN="我还真的很少收到别人的礼物！", },
	[50092] = {id=50092, zh_CN="给我的礼物吗？啊……不是不喜欢，只是很少收到……谢谢你。", },
	[50093] = {id=50093, zh_CN="为什么要送我这个？", },
	[50094] = {id=50094, zh_CN="收到礼物的感觉怎么完全和我想的不一样啊……", },
	[50095] = {id=50095, zh_CN="你……谢谢你，你……你是一个好人。", },
	[50096] = {id=50096, zh_CN="第一个设计出这份礼物的人简直是个天才！", },
	[50097] = {id=50097, zh_CN="无事不登三宝殿！说，想找我做什么，看在礼物的份上，我保证完成任务！", },
	[50098] = {id=50098, zh_CN="收到这样的礼物，就算让我住豪宅开豪车我也愿意！", },
	[50099] = {id=50099, zh_CN="不知不觉，你送我的东西居然已经装满了一个柜子！", },
	[50100] = {id=50100, zh_CN="我喜欢你的礼物，但是更喜欢和你待在一起！", },
	[50101] = {id=50101, zh_CN="我也要送你我喜欢的东西才行！", },
	[50102] = {id=50102, zh_CN="送这个……我可能不会答应你找我办事的请求。", },
	[50103] = {id=50103, zh_CN="你怎么对我忽好忽坏的！", },
	[50104] = {id=50104, zh_CN="嗯？这是什么？你可真是个难懂的人……", },
	[50105] = {id=50105, zh_CN="这可不是礼轻情意重，这是礼重情义重啊！", },
	[50106] = {id=50106, zh_CN="这可不能只有我一个人开心！我要告诉所有人！", },
	[50107] = {id=50107, zh_CN="你真的送我这个？也不怕我真的开心坏了！", },
	[50108] = {id=50108, zh_CN="我要把他们和其他你送我的东西一起收好！", },
	[50109] = {id=50109, zh_CN="我的道心就是被你这样一步一步瓦解的！", },
	[50110] = {id=50110, zh_CN="这是什么？是礼物！拆一下！", },
	[50111] = {id=50111, zh_CN="虽然很感激你的礼物，不过不要挑战我的演技啊！", },
	[50112] = {id=50112, zh_CN="你可没说是用这样的方式走出舒适区啊喂！", },
	[50113] = {id=50113, zh_CN="这个……是你对我的什么考验吗？", },
	[50114] = {id=50114, zh_CN="我第一次这么期待着一份礼物！", },
	[50115] = {id=50115, zh_CN="不错不错，眼光很好，很有我的风范！", },
	[50116] = {id=50116, zh_CN="我要把它放在一抬头就能看到的地方，更要时常想起你！", },
	[50117] = {id=50117, zh_CN="这是你送我的，我会一直好好珍藏起来，不给任何人看！", },
	[50118] = {id=50118, zh_CN="幸好我们关系好，你的礼物我就勉为其难收下啦！", },
	[50119] = {id=50119, zh_CN="这份礼物让我回忆起曾经一些不有趣的往事呢，你想听吗？", },
	[50120] = {id=50120, zh_CN="送我这样的东西，你到底是何居心啊！", },
	[50121] = {id=50121, zh_CN="哼，要不是觉得你很重要，我早就揍你啦！", },
	[50122] = {id=50122, zh_CN="我宣布，你已经成为我最重要的人啦！", },
	[50123] = {id=50123, zh_CN="我也要把你放在我身边最最重要的地方！", },
	[50124] = {id=50124, zh_CN="嗯嗯！我也和你一样，很在意你！", },
	[50125] = {id=50125, zh_CN="最重要的人送我的最珍贵的礼物，我感到好幸福！", },
	[50126] = {id=50126, zh_CN="除了礼物，我还想和你做其他有意义的事。", },
	[50127] = {id=50127, zh_CN="我怎么不知道你还会喜欢这种东西，是不是故意不告诉我呀？", },
	[50128] = {id=50128, zh_CN="这份礼物，算是你恶趣味的一面吗？", },
	[50129] = {id=50129, zh_CN="不许捉弄我啦！我也要送你！", },
	[50130] = {id=50130, zh_CN="谁想要你的东西，我只是勉为其难的收下这些破烂而已！", },
	[50131] = {id=50131, zh_CN="这里面，该不会有毒药吧？", },
	[50132] = {id=50132, zh_CN="我看你是无事献殷勤，非奸即盗。", },
	[50133] = {id=50133, zh_CN="就这些东西，该不会是在收买我吧？", },
	[50134] = {id=50134, zh_CN="喂喂，不想送我也可以不用占我的地方啊……", },
	[50135] = {id=50135, zh_CN="想要我收下之后就原谅你吗，我未免太善良了些。", },
	[50136] = {id=50136, zh_CN="所以呢？送我东西？想表达什么？", },
	[50137] = {id=50137, zh_CN="这些东西，和你很般配，和我就算了。", },
	[50138] = {id=50138, zh_CN="其实根本没有人想收你的礼物，别自作多情了。", },
	[50139] = {id=50139, zh_CN="你有点太小看我对你的恨意，更是太高看你自己的魅力了。", },
	[50140] = {id=50140, zh_CN="刚刚sara夸我快递送得快，我的电路都感觉有点发热了。", },
	[51000] = {id=51000, zh_CN="他会想吃吗？", },
	[51001] = {id=51001, zh_CN="合不合他的胃口……", },
	[51002] = {id=51002, zh_CN="他会觉得惊喜吗？", },
	[51003] = {id=51003, zh_CN="他会觉得惊喜吗？", },
	[51004] = {id=51004, zh_CN="把心意藏在里面。", },
	[51005] = {id=51005, zh_CN="这份礼物，会适合他吧？", },
	[51006] = {id=51006, zh_CN="暂时没有他想要的。", },
	[51007] = {id=51007, zh_CN="没有拿的出手的。", },
	[51008] = {id=51008, zh_CN="心仪的他在哪儿？", },
	[51009] = {id=51009, zh_CN="送给谁好呢？", },
	[51010] = {id=51010, zh_CN="来，尝尝这个！", },
	[51011] = {id=51011, zh_CN="特别为你准备的。", },
	[51012] = {id=51012, zh_CN="给你的礼物。", },
	[51013] = {id=51013, zh_CN="这份心意，请收下吧。", },
	[51014] = {id=51014, zh_CN="把这份美味分享给他吧。", },
	[51015] = {id=51015, zh_CN="他会喜欢吗？", },
	[51016] = {id=51016, zh_CN="他好像有点饿了……", },
	[51017] = {id=51017, zh_CN="试着投喂一下吧。", },
	[51018] = {id=51018, zh_CN="希望能传达我的心情。", },
	[51019] = {id=51019, zh_CN="要不要现在就拿出来呢？", },
	[51021] = {id=51021, zh_CN="我想给他个惊喜。", },
	[51022] = {id=51022, zh_CN="别客气，趁热吃。", },
	[51023] = {id=51023, zh_CN="和你分享美味。", },
	[51024] = {id=51024, zh_CN="给你尝尝这个。", },
	[51025] = {id=51025, zh_CN="悄悄塞你一个好吃的。", },
	[51026] = {id=51026, zh_CN="希望它能让你开心。", },
	[51027] = {id=51027, zh_CN="我觉得这个很适合你。", },
	[51028] = {id=51028, zh_CN="送给你，希望你喜欢！", },
	[51029] = {id=51029, zh_CN="这是特意为你挑选的。", },
	[51030] = {id=51030, zh_CN="这是给你的一份惊喜。", },
	[52000] = {id=52000, },
	[52001] = {id=52001, },
	[52002] = {id=52002, },
	[52003] = {id=52003, },
	[52004] = {id=52004, },
