	[60143] = {id=60143, zh_CN="人族", },
	[60144] = {id=60144, zh_CN="妖灵族", },
	[60145] = {id=60145, zh_CN="光族", },
	[60146] = {id=60146, zh_CN="猫族", },
	[60147] = {id=60147, zh_CN="巴别族", },
	[60148] = {id=60148, zh_CN="机械生命", },
	[60149] = {id=60149, zh_CN="食味族", },
	[60150] = {id=60150, zh_CN="精灵族", },
	[60151] = {id=60151, zh_CN="在漫长的发展过程中，人类一直在用自己的智慧，坚定而乐观地向前迈进，他们有能力制定长期计划，并在几代人之间实施。在逆境中始终表现出非凡的毅力。", },
	[60152] = {id=60152, zh_CN="他们是由魔兽进化而来的新型种族，保留了原魔兽的一些特点和长处，能够更好地融入人类社会。", },
	[60153] = {id=60153, zh_CN="小猫做任何事都不需要任何逻辑。", },
	[60154] = {id=60154, zh_CN="出生在光中的种族，能够从光中获得能量，是一个神秘的种族。", },
	[60155] = {id=60155, zh_CN="为了阻止巴别塔计划，上帝让人类开始说不同的语言，巴别族因巴别塔计划而诞生。他们是来自宇宙的神秘力量，拥有连接心灵和翻译任何语言的特殊能力。", },
	[60156] = {id=60156, zh_CN="他们是“被创造的自由灵魂”，他们的身体仍然被困在机械结构中，但他们的思想是自由的，有独立思考的能力，而不是简单地循环繁殖。", },
	[60157] = {id=60157, zh_CN="食味族有着温柔可爱的外表，但不要被它们的表现所迷惑，对于招惹自己的人，小家伙们会第一时间反击。", },
	[60158] = {id=60158, zh_CN="擅长古典艺术，崇尚素雅美学的高雅种族，依靠种族天赋，他们天生具有不同的能量，如与植物沟通、治愈受伤、阻挡干扰……", },
