	[60290] = {id=60290, zh_CN="侠客", },
	[60291] = {id=60291, zh_CN="（被）免疫以你为目标的所有效果（包括药剂，庇佑，占卜等正负面效果）。\n（被）当在场人数少于3人时，你将获得胜利。当你成功淘汰<color=#BC1717>恶魔阵营</color>玩家后，获胜所需的在场人数+1。\n（主）入夜阶段，你可以淘汰任意一名玩家。", },
	[60292] = {id=60292, zh_CN="（主）整场游戏限一次，入夜阶段，你可以驱逐一名玩家，若该玩家属于<color=#38B0DE>村民阵营</color>，则你会被放逐。", },
	[60293] = {id=60293, zh_CN="（主）入夜阶段，你可以审判一名玩家，若该玩家属于<color=#BC1717>恶魔阵营</color>，则其被放逐，否则你将永久失去该技能。", },
	[60294] = {id=60294, zh_CN="（被）入夜阶段，随机得知一名与你相邻的在场玩家身份（不会得知该身份属于哪名玩家）。", },
	[60295] = {id=60295, zh_CN="（主）入夜阶段，可选择一名玩家，得知其在该阶段是否使用了技能及其使用对象。", },
	[60296] = {id=60296, zh_CN="当场上存活人数少于3人时，你获胜。", },
