	[60408] = {id=60408, zh_CN="不仅待走了<color=#00fff5>%s</color>身上的物品，还顺便在<color=#00fff5>%s</color>背后画了个小乌龟", },
	[60409] = {id=60409, zh_CN="你尝试了半天成功把<color=#00fff5>%s</color>的手从口袋里拿了出来", },
	[60410] = {id=60410, zh_CN="还没伸出手就被发现，然后被<color=#00fff5>%s</color>暴揍了一顿", },
	[60411] = {id=60411, zh_CN="你顺利拿到了<color=#ffc000>%i</color>", },
	[60412] = {id=60412, zh_CN="成功的妙手！你快速拿走了<color=#00fff5>%s</color>~", },
	[60413] = {id=60413, zh_CN="摸了半天，从<color=#00fff5>%s</color>身上愣是掏出来了一些垃圾", },
	[60414] = {id=60414, zh_CN="你尝试了许久也没有找到合适的时机拿走<color=#ffc000>%i</color>", },
	[60415] = {id=60415, zh_CN="眼前一亮！感觉自己的搜查状态异常的好！", },
	[60416] = {id=60416, zh_CN="成功展开了地毯式搜索！", },
	[60417] = {id=60417, zh_CN="眼前一黑什么也没有看到，或许是最近缺乏营养了？", },
	[60418] = {id=60418, zh_CN="看了大半天什么也没找到的你已经开始怀疑自己是否近视了", },
	[60419] = {id=60419, zh_CN="成功调查到了附近的一些细节", },
	[60420] = {id=60420, zh_CN="周围似乎有些特殊的事情等待你的发现", },
	[60421] = {id=60421, zh_CN="看上去一切都很正常，风平浪静", },
	[60422] = {id=60422, zh_CN="还有比这周围更寻常的地方吗？没有了！", },
	[60423] = {id=60423, zh_CN="神医再世！你甚至还没开始治疗，<color=#00fff5>%s</color>就已经好了！", },
	[60424] = {id=60424, zh_CN="仅仅是一眼扫过，<color=#00fff5>%s</color>的伤口便如同畏惧你一般开始痊愈", },
	[60425] = {id=60425, zh_CN="看着<color=#00fff5>%s</color>受伤的模样，你一股邪火让你上去就是两个大嘴巴子", },
	[60426] = {id=60426, zh_CN="拳头——忍不住了！你放下了医疗道具，朝着<color=#00fff5>%s</color>的脸就是一拳！", },
	[60427] = {id=60427, zh_CN="顺利的治疗，<color=#00fff5>%s</color>的伤口被你有效处理过了", },
	[60428] = {id=60428, zh_CN="在合理用药下，<color=#00fff5>%s</color>的状况正在不断好转", },
	[60429] = {id=60429, zh_CN="你胡乱处理了一下，虽然没有好转，但至少<color=#00fff5>%s</color>也变得更坏不是~", },
	[60430] = {id=60430, zh_CN="你凭借高超的医学素养成功断定自己的治疗确实没有半点作用", },
	[60431] = {id=60431, zh_CN="成功", },
	[60432] = {id=60432, zh_CN="大成功", },
	[60433] = {id=60433, zh_CN="失败", },
	[60434] = {id=60434, zh_CN="大失败", },
	[60435] = {id=60435, zh_CN="附近", },
	[60436] = {id=60436, zh_CN="超出技能范围", },
	[60437] = {id=60437, zh_CN="技能冷却中", },
	[60438] = {id=60438, zh_CN="视角距离设置", },
	[60439] = {id=60439, zh_CN="哄骗", },
	[60440] = {id=60440, zh_CN="这包裹好像是我的哦", },
	[60441] = {id=60441, zh_CN="嗯？让本快递员看看……你叫璃雨殇•羽晗灵•樱雪•魅伤梦娜•黛露茜•冰落蝶梦？", },
	[60442] = {id=60442, zh_CN="没错！我就是！", },
	[60443] = {id=60443, zh_CN="嗯……看上去很可疑！喏！在这里签收一下！还有这里……", },
	[60444] = {id=60444, zh_CN="还要写这个名字多少次（咬牙切齿）", },
	[60445] = {id=60445, zh_CN="这个包裹比较特殊哦！再签768次就可以拿到了！", },
	[60446] = {id=60446, zh_CN="彳亍", },
	[60447] = {id=60447, zh_CN="不是本快递员说……虽然本快递员不是人类，但也不要把本快递员当成傻子啊！", },
	[60448] = {id=60448, zh_CN="你的名字明明就在头顶上啊！哪里叫这个了！", },
	[60449] = {id=60449, zh_CN="刚……刚改的……一定是系统还没更新！", },
	[60450] = {id=60450, zh_CN="你这样我可要找巡警了！", },
	[60451] = {id=60451, zh_CN="开……开个玩笑嘛！", },
	[60452] = {id=60452, zh_CN="我觉得我可以是", },
	[60453] = {id=60453, zh_CN="咕呣，是……是你！别打本快递员！那……在这里签收一下！还有这里……", },
	[60454] = {id=60454, zh_CN="你要和本快递员比力量吗？", },
	[60455] = {id=60455, zh_CN="嘿！本快递员可是范特西公司快递员拳击比赛的冠军！", },
	[60456] = {id=60456, zh_CN="疼疼疼！！！我开玩笑的！", },
	[60457] = {id=60457, zh_CN="打扰了，我认错了", },
	[60458] = {id=60458, zh_CN="那就好~那本快递员就要继续送信了哦！", },
	[60459] = {id=60459, zh_CN="咦，你的左侧手臂……", },
	[60460] = {id=60460, zh_CN="噢，昨天送家具的时候好像不小心弄坏了动力臂，本快递员送完这两单就要回厂维修了！", },
	[60461] = {id=60461, zh_CN="不过请您放心~不会影响到货物的安全的！", },
	[60462] = {id=60462, zh_CN="让我来修修看吧？", },
	[60463] = {id=60463, zh_CN="真的可以吗？！太感谢您了！", },
	[60464] = {id=60464, zh_CN="尝试维修", },
	[60465] = {id=60465, zh_CN="为它祈祷", },
	[60466] = {id=60466, zh_CN="捣鼓捣鼓", },
	[60467] = {id=60467, zh_CN="哇！真的好了耶！本快递员要宣布你就是这个世界上最棒的维修人员！", },
	[60468] = {id=60468, zh_CN="看上去没有变好……但是还是感谢你！本快递员要宣布你就是这个世界上最棒的客户！", },
	[60469] = {id=60469, zh_CN="哦哦哦哦！本快递员的机魂开始燃烧起来了！", },
	[60470] = {id=60470, zh_CN="等一下，等一下！很抱歉打扰了你的祈祷。", },
	[60471] = {id=60471, zh_CN="本快递员还是想问一下，你到底在向哪位神明祈祷需要打呼噜？", },
	[60472] = {id=60472, zh_CN="呃……不好意思，突然有点困……", },
	[60473] = {id=60473, zh_CN="哇哦！虽然看上去你一点机械知识也没有，竟然真的修好了！", },
	[60474] = {id=60474, zh_CN="难道你真的是维修天才？", },
	[60475] = {id=60475, zh_CN="算了吧……要不咱们就别修了，把本快递员的手装回去吧呜呜呜——求你了！", },
	[60476] = {id=60476, zh_CN="（希望范特西别找上门来说自己毁坏公司财产……）", },
	[60477] = {id=60477, zh_CN="等一下！不仅修好了……本快递员的身体竟然在升级进化？就连范特西公司也没能办到的事……", },
	[60478] = {id=60478, zh_CN="天呐！你、你是创世主吗？！", },
	[60479] = {id=60479, zh_CN="本快递员半生飘零，只恨未逢明主……", },
	[60480] = {id=60480, zh_CN="差不多得了……", },
	[60481] = {id=60481, zh_CN="本快递员说句实在的，你现在的维修知识就算拆了本快递员", },
	[60482] = {id=60482, zh_CN="恐怕也在本快递员的计算之中", },
	[60483] = {id=60483, zh_CN="咳咳，也、也没有那么糟糕吧？", },
	[60484] = {id=60484, zh_CN="能不能别卷了！", },
	[60485] = {id=60485, zh_CN="可是空闲下来的人生！那还算是人生吗？", },
	[60486] = {id=60486, zh_CN="摸鱼，也算人生！", },
	[60487] = {id=60487, zh_CN="不试试看吗？", },
	[60488] = {id=60488, zh_CN="那种偷懒的愉悦！", },
	[60489] = {id=60489, zh_CN="偷懒的愉悦……倒也是哦。或许我该试试了？", },
	[60490] = {id=60490, zh_CN="对了！这个，送你吧！反正我要去摸鱼了！", },
	[60491] = {id=60491, zh_CN="从你口中完全没有感受到愉悦嘛，还是算了！干活！干活！", },
	[60492] = {id=60492, zh_CN="卷王！吃我一拳！", },
	[60493] = {id=60493, zh_CN="啊哟！你干嘛打我……呜呜呜", },
	[60494] = {id=60494, zh_CN="我平生最恨卷王！", },
	[60495] = {id=60495, zh_CN="不卷了不卷了！我再也不卷了！", },
	[60496] = {id=60496, zh_CN="哼，%PlayerName，这就是你的全部力量了吗？", },
	[60497] = {id=60497, zh_CN="对于每日主动走入内卷的我来说，你实在太弱了！", },
	[60498] = {id=60498, zh_CN="（可恶！这就是卷王的实力吗……咳啊，甘拜下风！）", },
	[60499] = {id=60499, zh_CN="猫也会说话？！", },
	[60500] = {id=60500, zh_CN="你要不要看看你在说什么喵", },
	[60501] = {id=60501, zh_CN="%PlayerName", },
	[60502] = {id=60502, zh_CN="%s检定", },
	[60503] = {id=60503, zh_CN="范特西补给箱", },
	[60504] = {id=60504, zh_CN="反抗军遗留补给", },
	[60505] = {id=60505, zh_CN="草药包", },
	[60506] = {id=60506, zh_CN="不起眼的箱子", },
	[60507] = {id=60507, zh_CN="虽然利用光学迷彩伪装得很好，但隶属于范特西公司的补给箱依然被你发现了。", },
	[60508] = {id=60508, zh_CN="趁着没人打开后，你找到了几件还能用的补给零件。", },
	[60509] = {id=60509, zh_CN="仔细盯着他。", },
	[60510] = {id=60510, zh_CN="他注视到了你的凝视，收敛起笑容也盯着你。", },
	[60511] = {id=60511, zh_CN="继续盯着他。", },
	[60512] = {id=60512, zh_CN="（小丑突然噗嗤一声笑了出来）", },
	[60513] = {id=60513, zh_CN="干嘛这么看着我？", },
	[60514] = {id=60514, zh_CN="你好像有些特别", },
	[60515] = {id=60515, zh_CN="你到底是谁？", },
	[60516] = {id=60516, zh_CN="我们见过吗？", },
	[60517] = {id=60517, zh_CN="特别？嗯——每个人都很特别。%PlayerName，你也很特别，不是吗？然而这也不是你这么一直盯着我的理由。", },
	[60518] = {id=60518, zh_CN="让我想想……也许我就是一个大坏蛋，正好被你的大坏蛋雷达捕捉到了？", },
	[60519] = {id=60519, zh_CN="又或者……我们是前世彼此相约的恋人？", },
	[60520] = {id=60520, zh_CN="或许是……亲属关系？咳咳，我扮演父亲母亲也很在行哦。", },
	[60521] = {id=60521, zh_CN="我以为你在演疯子", },
	[60522] = {id=60522, zh_CN="哎呀，其实小丑和疯子，有什么区别呢？都是给大家带来欢乐的角色嘛~", },
	[60523] = {id=60523, zh_CN="而且……如果我是疯子，那范特西又算什么呢？", },
	[60524] = {id=60524, zh_CN="创造神明？噗哈哈哈……还有比这更好笑的公司了吗，%PlayerName？", },
	[60525] = {id=60525, zh_CN="糟了，眼睛……眼睛进沙子了。等你缓过神来，小丑也没再继续看你了。这次“对决”是你输了……", },
	[60526] = {id=60526, zh_CN="我是谁？", },
	[60527] = {id=60527, zh_CN="一个普普通通为大家带来欢乐的小丑，仅此而已。", },
	[60528] = {id=60528, zh_CN="难道我是什么喜欢恶作剧微服私访的神明吗？你看我像吗？", },
	[60529] = {id=60529, zh_CN="像", },
	[60530] = {id=60530, zh_CN="……", },
	[60531] = {id=60531, zh_CN="那，我也可以是哦", },
	[60532] = {id=60532, zh_CN="（一瞬间感觉到了小丑的气势的变化，难道是错觉？）", },
	[60533] = {id=60533, zh_CN="不像", },
	[60534] = {id=60534, zh_CN="少拿我开心了~哎呀，我还以为我暴露了呢", },
	[60535] = {id=60535, zh_CN="暴露？", },
	[60536] = {id=60536, zh_CN="暴露我是神明的事情呀。要是这样，说不定我可要把你……", },
	[60537] = {id=60537, zh_CN="小丑做了一个抹脖子的动作", },
	[60538] = {id=60538, zh_CN="随后严肃的脸很快大笑起来", },
	[60539] = {id=60539, zh_CN="开玩笑，开玩笑。瞧你紧张的样子！", },
	[60540] = {id=60540, zh_CN="今天见过算见过吗？", },
	[60541] = {id=60541, zh_CN="我们曾经或许见过？", },
	[60542] = {id=60542, zh_CN="应该没有吧？我这样的小丑，整个星系都能随处可见！", },
	[60543] = {id=60543, zh_CN="不过我确实在整个星系中巡回演出过。你曾经有去过其他星球的话，也许还真见过我？", },
	[60544] = {id=60544, zh_CN="那应该是以前表演见到的吧？", },
	[60545] = {id=60545, zh_CN="那就是啦~我们还真有缘分呀。", },
	[60546] = {id=60546, zh_CN="或许在某座神庙里见过？", },
	[60547] = {id=60547, zh_CN="神庙？哈哈哈，我是探险家吗？我可没有那个爱好哦。", },
	[60548] = {id=60548, zh_CN="这样啊……", },
	[60549] = {id=60549, zh_CN="好啦好啦！我可要开始表演了哦！不和你闹了~", },
	[60550] = {id=60550, zh_CN="被包装的良好的特殊补给，从上面不明显的印记似乎能看出来自于反抗军", },
	[60551] = {id=60551, zh_CN="补给被封存的十分严密，想要打开它还是得费上一番手段", },
	[60552] = {id=60552, zh_CN="开锁不是小菜一碟？", },
	[60553] = {id=60553, zh_CN="给它一砖头", },
	[60554] = {id=60554, zh_CN="求求它", },
	[60555] = {id=60555, zh_CN="随着“啪嗒”一声，你快速打开了锁头，取走了其中的补给道具", },
	[60556] = {id=60556, zh_CN="你刚掏出开锁器准备大施拳脚之际，上面的锁头应声而开。看样子就连锁，也在害怕你。你快速取走了其中的补给道具便离开了", },
	[60557] = {id=60557, zh_CN="你开得满头大汗，以至于引起了周围人们的警觉，最终不得不灰溜溜地离开", },
	[60558] = {id=60558, zh_CN="折断了1024根开锁器后，发现周围已经围了里三层外三层，只为看你打开它。你脸色一红，哇哇大哭起来。这辈子就没受过这种耻辱……", },
	[60559] = {id=60559, zh_CN="你给了它一砖头，看上去它有一角有些破损了", },
	[60560] = {id=60560, zh_CN="再来一砖头", },
	[60561] = {id=60561, zh_CN="再来了一砖头后，已经被砸出了一个小坑", },
	[60562] = {id=60562, zh_CN="最后一砖头！", },
	[60563] = {id=60563, zh_CN="随着随后一砖砸下，你终于打开了补给箱，拿走了其中可以用的部分道具", },
	[60564] = {id=60564, zh_CN="你一砖砸下，坚硬的补给箱将砖头直接撞断，飞起的砖头将你的脑门砸了个大包", },
	[60565] = {id=60565, zh_CN="你一砖头便将这个坚硬无比的补给箱砸烂了", },
	[60566] = {id=60566, zh_CN="你还没开始砸，手一滑，砖头便直挺挺砸向了你的脑袋……", },
	[60567] = {id=60567, zh_CN="你诚恳祈祷着，最终这个补给箱似乎感受到了你的诚意，缓缓打开了它，让你取走了其中的道具", },
	[60568] = {id=60568, zh_CN="你如同摩西一般，对着补给箱喊道“开！”而你话音刚落，补给箱便如大海一般缓缓打开，让你取走了其中的补给道具", },
	[60569] = {id=60569, zh_CN="你当着众人的面开始祈求起这个补给箱……虽然不知道祈祷有没有用，但是感觉自己还挺丢脸的", },
	[60570] = {id=60570, zh_CN="你涕泗横流哭喊着祈求着箱子能打开，显然一个箱子是接受不了你的祈祷的。现在你只能祈祷周围的人都没看到你刚才的表现", },
	[60571] = {id=60571, zh_CN="<color=#ffc000>力量</color>", },
	[60572] = {id=60572, zh_CN="<color=#ffc000>巧思</color>", },
	[60573] = {id=60573, zh_CN="<color=#ffc000>健康</color>", },
	[60574] = {id=60574, zh_CN="<color=#ffc000>敏捷</color>", },
	[60575] = {id=60575, zh_CN="<color=#ffc000>理智</color>", },
	[60576] = {id=60576, zh_CN="<color=#ffc000>幸运</color>", },
	[60577] = {id=60577, zh_CN="<color=#ffc000>生命</color>", },
	[60578] = {id=60578, zh_CN="<color=#ffc000>神智</color>", },
	[60579] = {id=60579, zh_CN="<color=#ffc000>斗殴</color>", },
	[60580] = {id=60580, zh_CN="<color=#ffc000>射击</color>", },
	[60581] = {id=60581, zh_CN="<color=#ffc000>闪避</color>", },
	[60582] = {id=60582, zh_CN="<color=#ffc000>制造</color>", },
	[60583] = {id=60583, zh_CN="<color=#ffc000>开锁</color>", },
	[60584] = {id=60584, zh_CN="<color=#ffc000>祈祷</color>", },
	[60585] = {id=60585, zh_CN="<color=#ffc000>聆听</color>", },
	[60586] = {id=60586, zh_CN="<color=#ffc000>机械维修</color>", },
