	[60619] = {id=60619, zh_CN="发言结束", },
	[60620] = {id=60620, zh_CN="你找到了银月遗失的另外一个草药包，里面的草药大多腐败了。", },
	[60621] = {id=60621, zh_CN="或许对她来说已经没有作用了，但你仍然从中挑出了一些能用的东西", },
	[60622] = {id=60622, zh_CN="它的木质表面刻满了划痕，似乎蕴藏着未知的宝藏。", },
	[60623] = {id=60623, zh_CN="本想着交还给它，后面发现原来是上周被告知丢掉的自己的快递……", },
	[60624] = {id=60624, zh_CN="发言中", },
	[60625] = {id=60625, zh_CN="震惊！猫也会说话？", },
	[60626] = {id=60626, zh_CN="（西西白了你一眼）", },
	[60627] = {id=60627, zh_CN="喵一直会说话的！人类不要太自以为是了！", },
	[60628] = {id=60628, zh_CN="那猫猫是怎么学会说话的呢？", },
	[60629] = {id=60629, zh_CN="喵们信仰飞天猫猫神教，是飞天猫猫神赐予了喵们说话的能力喵！", },
	[60630] = {id=60630, zh_CN="（你对此深信不疑）", },
	[60631] = {id=60631, zh_CN="那这个飞天猫猫神教……我也可以信吗？", },
	[60632] = {id=60632, zh_CN="当然可以喵！但是每周四！需要给喵准备50条小鱼干当做祭礼喵！", },
	[60633] = {id=60633, zh_CN="太多了吧……", },
	[60634] = {id=60634, zh_CN="不信就算了喵！不强求！不强求的喵！", },
	[60635] = {id=60635, zh_CN="再便宜点！", },
	[60636] = {id=60636, zh_CN="喵……30条喵！", },
	[60637] = {id=60637, zh_CN="成交！", },
	[60638] = {id=60638, zh_CN="伟大的飞天猫猫神！可以再便宜点吗！", },
	[60639] = {id=60639, zh_CN="那……那10条喵！不能再少了喵！", },
	[60640] = {id=60640, zh_CN="伟大的飞天猫猫神真好！成交喵！", },
	[60641] = {id=60641, zh_CN="一言为定了喵！", },
	[60642] = {id=60642, zh_CN="哼！喵觉得你对飞天猫猫神的感情只用物质来维持！一点不诚心喵！", },
	[60643] = {id=60643, zh_CN="我是范特西总裁", },
	[60644] = {id=60644, zh_CN="喵？真的假的？喵觉得……完全不像呀？", },
	[60645] = {id=60645, zh_CN="虽然是假的，但是我感觉比你的飞天猫猫神应该可信度高一点喵", },
	[60646] = {id=60646, zh_CN="（突然感觉自己好像被传染了什么奇怪的口癖）", },
	[60647] = {id=60647, zh_CN="咦……喵哪里编的有破绽……", },
	[60648] = {id=60648, zh_CN="哪里都是破绽好了啦……", },
	[60649] = {id=60649, zh_CN="可是喵只想要一点小鱼干", },
	[60650] = {id=60650, zh_CN="逃避它的目光", },
	[60651] = {id=60651, zh_CN="QAQ", },
	[60652] = {id=60652, zh_CN="再次逃避", },
	[60653] = {id=60653, zh_CN="喵呜……", },
	[60654] = {id=60654, zh_CN="西西垂着尾巴离开了", },
	[60655] = {id=60655, zh_CN="（忍不住了！）", },
	[60656] = {id=60656, zh_CN="！说吧！要多少条！", },
	[60657] = {id=60657, zh_CN="呜喵！！！！你最好了喵！！！每周四！和人类一样！V我50小鱼干喵！", },
	[60658] = {id=60658, zh_CN="你到底是从哪里学的……", },
	[60659] = {id=60659, zh_CN="好不好喵~", },
	[60660] = {id=60660, zh_CN="好喵！", },
	[60661] = {id=60661, zh_CN="（我到底在干什么……）", },
	[60662] = {id=60662, zh_CN="%PlayerName！你是全天下最最最好的人类喵！", },
	[60663] = {id=60663, zh_CN="太贵了喵！再便宜点！", },
	[60664] = {id=60664, zh_CN="喵……30条喵！再少就会饿肚肚了喵！", },
	[60665] = {id=60665, zh_CN="好喵！由我来养你吧！", },
	[60666] = {id=60666, zh_CN="一言为定喵！谢谢%PlayerName喵！喵要信仰飞天%PlayerName神教喵！", },
	[60667] = {id=60667, zh_CN="要不……再……？", },
	[60668] = {id=60668, zh_CN="那……那10条喵！不能再少了喵！", },
	[60669] = {id=60669, zh_CN="没问题喵~", },
	[60670] = {id=60670, zh_CN="耶！谢谢你好心人喵！", },
	[60671] = {id=60671, zh_CN="我再考虑考虑吧……", },
	[60672] = {id=60672, zh_CN="呜——好喵！西西等你回来喵！", },
	[60673] = {id=60673, zh_CN="一定要回来喵！", },
	[60674] = {id=60674, zh_CN="看样子完全砍不来价……", },
	[60675] = {id=60675, zh_CN="成交喵！", },
	[60676] = {id=60676, zh_CN="真的假的？", },
	[60677] = {id=60677, zh_CN="不顶用，孩子，这不顶用。你魅惑不了我的！", },
	[60678] = {id=60678, zh_CN="我心如铁，坚不可摧", },
	[60679] = {id=60679, zh_CN="请选择你的角色", },
