	[60760] = {id=60760, zh_CN="我曾见彗星袭于月亮、长虹贯穿日心、苍鹰击于殿上，现在它们连同我，要成为四个人了；如果真有神明庇护你的话，就证明给我看吧，前首相大人！ —— 令和足轻一骑讨太阁", },
	[60761] = {id=60761, zh_CN="如果你吃下蓝色药丸，你就会失去这里的所有记忆，回到你的生活中，与世界的真实再无关联；红色药丸也一样，不过是草莓味的。", },
