	[60778] = {id=60778, zh_CN="全宇宙范围内流通的货币。", },
	[60779] = {id=60779, zh_CN="宇宙的核心能量来源，珍贵的货币。", },
	[60780] = {id=60780, zh_CN="提高角色等级的经验值，需要经历无数冒险方可获得少许。", },
	[60781] = {id=60781, zh_CN="测试的东西别当真D", },
	[60782] = {id=60782, zh_CN="测试的东西别当真E", },
	[60783] = {id=60783, zh_CN="小浣熊模样的风筝，残破不堪，似乎是某人的童年回忆。", },
	[60784] = {id=60784, zh_CN="锈蚀的镰刀，纯靠硬度感觉也能砸开东西。", },
	[60785] = {id=60785, zh_CN="像是被困在店里的作家会拿起来的东西。", },
	[60786] = {id=60786, zh_CN="钉歪了的钉子，如果技术好，或许可以用来开锁。", },
	[60787] = {id=60787, zh_CN="还剩不少的胡椒粉，靠近了就容易打喷嚏。总之，有人的鼻子要倒霉咯！", },
	[60788] = {id=60788, zh_CN="早已灭绝的花，象征着长存与重生。可如果真的长存，又怎么会灭绝呢？", },
	[60789] = {id=60789, zh_CN="如果他听话，就为他授勋。如果他不听话，就拿他的脑袋为自己授勋。", },
	[60790] = {id=60790, zh_CN="传说中十二圣人所赐福过的经书，可以避除邪祟，我是说，大概？", },
	[60791] = {id=60791, zh_CN="一把破钥匙，感觉随时都会折断的样子。", },
