	[60820] = {id=60820, zh_CN="身段柔软，灵活的舞蹈家，能够快速适应各种体型和灵巧类相关天赋", },
	[60821] = {id=60821, zh_CN="传说中漫游宇宙的游侠，平时没什么正经工作，纯靠游侠身份骗小孩子的棒棒糖", },
	[60822] = {id=60822, zh_CN="平时也没什么正经工作，每天盯着悬赏令不是在看目标，也可能是看自己有没有在上面", },
	[60823] = {id=60823, zh_CN="不同的种族受到体型，生存环境等因素的影响，各自有其擅长的能力及属性", },
	[60824] = {id=60824, zh_CN="在漫长的职业生涯中，不同职业对属性和能力有了额外的加成", },
	[60825] = {id=60825, zh_CN="当前状态下拥有的基础属性及数值，后续会随着成长不断加强或减少甚至解锁没有的属性。", },
	[60826] = {id=60826, zh_CN="当前状态下拥有的技能及数值，后续会随着成长不断加强或减少甚至解锁没有的技能", },
