	[61014] = {id=61014, zh_CN="摄相机", },
	[61015] = {id=61015, zh_CN="你来啦，这次想进入一个怎样的世界呢？", },
	[61016] = {id=61016, zh_CN="如果你有喜欢的模组，可以告诉我它的名字，或者用一些关键词简单描述你的偏好，如题材、战斗方式等，我来帮你找找看。如果没有喜欢的模组也可以自由创建，或由我帮你一键生成。", },
	[61017] = {id=61017, zh_CN="找到了，看起来很有意思。", },
	[61018] = {id=61018, zh_CN="模组《%s》讲述了%s，要以这个模组开始这一次的探索吗？", },
	[61019] = {id=61019, zh_CN="不是您喜欢的吗？没关系，为您推荐以下模组", },
	[61020] = {id=61020, zh_CN="没有喜欢的模组吗？可以刷新一下获取更多模组推荐，也可以为我提供更多关键词描述，如题材、人物设定、难度等，我能帮你找到模组。", },
	[61021] = {id=61021, zh_CN="为你找到了多个名为《%s》的模组。", },
	[61022] = {id=61022, zh_CN="《%s》讲述了一个%s的故事，《%s》讲述了一个%s的故事，《%s》讲述了%s。这些模组中有你想玩的吗？", },
	[61023] = {id=61023, zh_CN="翻遍了模组库，但好像没有找到你你所说的那个模组……", },
	[61024] = {id=61024, zh_CN="你可以告诉我更多有关于它的信息，我再次进行查找，或者也可以选择自创模组，也可以让我来一键推荐。", },
	[61025] = {id=61025, zh_CN="还是没有喜欢的模组吗？可以再试着告诉我更多信息，或者尝试自创模组，我也可以为你一键推荐。", },
	[61026] = {id=61026, zh_CN="我找到了更多模组，快来一起看看。", },
	[61027] = {id=61027, zh_CN="为您找到了一些经典模组", },
	[61028] = {id=61028, zh_CN="我好像知道你所说的模组，这里有讲述了%s的《%s》，有关%s的《%s》，还有%s的《%s》，这些模组里有你喜欢的吗？", },
	[61029] = {id=61029, zh_CN="我为您找到一些您可能会喜欢的模组", },
	[61030] = {id=61030, zh_CN="在广袤的寰宇之中选择一个心仪的探索地确实很有难度，我可以为你一键推荐经典模组，你也可以尝试自己创造一个属于自己的模组世界。", },
	[61031] = {id=61031, zh_CN="精彩的创建，《%s》是一个%s类型的模组，讲述了%s。玩家需要扮演%s，一同完成一场%s的%s。确定以这个模组开始游戏吗？", },
	[61032] = {id=61032, zh_CN="模组世界在你的修缮下变得更完整了。《%s》是一个%s类型的模组，讲述了%s。玩家需要扮演%s，一同完成一场%s的%s。确定以这个模组开始游戏吗？", },
	[61033] = {id=61033, zh_CN="为你找到了一些经典模组，《%s》讲述了%s，还有%s题材的《%s》，讲述了%s的故事，当然，还有最经典的《%s》，可以让你快速开启一场精彩的探索之旅。", },
	[61034] = {id=61034, zh_CN="还有什么需要补充的吗？可以告诉我需要补充的信息。我可以添加到模组中，或者将不需要的信息从模组中删除。", },
	[61035] = {id=61035, zh_CN="模组的创建又完善了一些！《%s》是一个%s类型的模组，讲述了%s。玩家需要扮演%s，一同完成一场%s的%s。确定以这个模组开始游戏吗？", },
	[61036] = {id=61036, zh_CN="还需要修改更多信息吗？我可以帮你加入进去。如果不想继续自己创建，也可以选择一键生成。", },
	[61037] = {id=61037, zh_CN="为你找到了一些经典模组，《%s》讲述了%s，还有%s题材的《%s》，讲述了%s的故事，当然，还有最经典的《%s》，可以让你快速开启一场精彩的探索之旅。", },
	[61038] = {id=61038, zh_CN="模组选择完成啦，是否需要再做调整？", },
	[61039] = {id=61039, zh_CN="想要创造一个属于自己的世界吗？接下来一起打造属于你的模组吧！", },
	[61040] = {id=61040, zh_CN="我努力工作，到底是为了什么呢？算了……与其思考这些问题，还是先把眼下的工作做好吧。", },
	[61041] = {id=61041, zh_CN="《摸鱼绝学》……哎，我怎么又在想昨天捡到的那本书了。不行，不行，工作可容不得半点马虎。", },
	[61042] = {id=61042, zh_CN="机械臂该维修了，滚轮也需要上机油，明天还有九百九十九个单子要送……做一个合格的快递员有太多细节要把握了。", },
	[61043] = {id=61043, zh_CN="星球上每天有许许多多的快递，顾客们会像期待收货一样期待我的到来吗？", },
	[61044] = {id=61044, zh_CN="电量……告急，电量……告急，有没有好心人无缘无故给我送电池，急，在线等。", },
	[61045] = {id=61045, zh_CN="多亏了好心人给的电池，电量又回满了，星球还是好人多啊！", },
	[61046] = {id=61046, zh_CN="不懂欢笑的意义和虚度人生又有什么区别？我一定会让笑声响彻米乐星球的每个角落。", },
	[61047] = {id=61047, zh_CN="悲伤是什么？离开家乡的我需要悲伤吗？这种公式一样的无厘头伤感，比笑话本身还可笑。", },
	[61048] = {id=61048, zh_CN="如果有一天，我一定要离开米乐星球，我真的能割舍吗？虽然这个星球只是公司打造的产品，但好像早已是我的一部分。", },
	[61049] = {id=61049, zh_CN="又有新人入驻了，希望他们会喜欢这个米乐星球这个家。", },
	[61050] = {id=61050, zh_CN="没有人能拒绝钟楼的魅力，真是范特西星球最棒的游戏。", },
	[61051] = {id=61051, zh_CN="会有人愿意探索我的心吗？应该也会是一场有趣的推理游戏。", },
	[61052] = {id=61052, zh_CN="努力接待了一天客人，真是辛苦喵了。愿飞天猫猫教神保佑喵明天也不会遇到奇怪的客人。", },
	[61053] = {id=61053, zh_CN="已经很久没见那只黑喵来店里了……下次见到它，请它喝杯花茶吧。哼，喵这只是营销手段……绝对不是想它。", },
	[61054] = {id=61054, zh_CN="真不知道那些酸诗有什么好……她让我看的诗集我又不是没看，写的也就一般。", },
	[61055] = {id=61055, zh_CN="明天去哪玩呢？布伦达肯定又要窝在家里看书，不管了，得想个办法拖她一起。", },
	[61056] = {id=61056, zh_CN="布兰登，托你的福，有你叽叽喳喳的在身边，至少不会让我感到无聊。", },
	[61057] = {id=61057, zh_CN="诗歌的魅力，我想布兰登无论如何也不会明白。相比晦涩的诗歌，我甚至不指望他听懂我平日的吐槽。", },
	[61058] = {id=61058, zh_CN="等会儿去找小丑打听些趣事吧，闲暇的时刻就应该听些可爱的乐子。", },
	[61059] = {id=61059, zh_CN="只要善于发现，小小的星球也有不少乐趣。下次茶会时一定要分享给大家。", },
