	[61073] = {id=61073, zh_CN="一沓散发着杜鹃花香气的信纸，可以用来写信给在意的人。", },
	[61074] = {id=61074, zh_CN="一块钉着信纸的猫猫头木板，纸上还留着标志性的爪印。", },
	[61075] = {id=61075, zh_CN="纸鹤在光芒中漂浮，纸蝶寄托恒久的思念。", },
	[61076] = {id=61076, zh_CN="食味族的信纸，看起来充满了甜蜜的味道，要咬一口吗？", },
	[61077] = {id=61077, zh_CN="全金属的机械输入板，拿出来就会自动浮现输入界面，或许可以语音转文字。", },
	[61078] = {id=61078, zh_CN="花叶寄相思，这片扇子般宽大的绿叶很适合写信。", },
	[61079] = {id=61079, zh_CN="一板一眼的古典信纸，羽毛笔是绅士的标配。", },
	[61080] = {id=61080, zh_CN="晶莹剔透的紫色泡泡，轻轻吐露对好友的思念之情。", },
