	[61297] = {id=61297, zh_CN="这是一个测试任务，你去找小丑吧", },
	[61298] = {id=61298, zh_CN="我是来你谈谈的", },
	[61299] = {id=61299, zh_CN="这是一个测试任务，说明顺利运行了。去找阿加莎吧。", },
	[61300] = {id=61300, zh_CN="小丑要我和你聊聊", },
	[61301] = {id=61301, zh_CN="测试成功了，行了，你启动去吧", },
	[61302] = {id=61302, zh_CN="我拿到了这个……", },
	[61303] = {id=61303, zh_CN="哇哦这不是契约球吗？我教你用用吧。", },
	[61304] = {id=61304, zh_CN="太好了，是客客你来教我，我们有救了", },
	[61305] = {id=61305, zh_CN="想送你三朵花", },
	[61306] = {id=61306, zh_CN="之前的花怎么样！", },
	[61307] = {id=61307, zh_CN="你怎么还在？", },
	[61308] = {id=61308, zh_CN="信件发送成功", },
	[61309] = {id=61309, zh_CN="%y—%m—%d", },
	[61310] = {id=61310, zh_CN="信件内存在违规字符，修改后方可预览", },
	[61311] = {id=61311, zh_CN="加急道具不足，无法以加急形式发送", },
	[61312] = {id=61312, zh_CN="无法将信件发给自己", },
	[61313] = {id=61313, zh_CN="信使任命成功", },
	[61314] = {id=61314, zh_CN="当前已有信使，是否取消并任命%s为信使？", },
	[61315] = {id=61315, zh_CN="谁被淘汰了？7号报告的吗，你来说说什么情况吧？", },
	[61316] = {id=61316, zh_CN="我也不知道啊。我好像看到4号击倒了3号！", },
	[61317] = {id=61317, zh_CN="你这不是血口喷人吗？我就在做任务呢！这里每个任务都需要读条，人越多做得越快。你不知道吗？", },
	[61318] = {id=61318, zh_CN="我和6号一起在礼堂那边祈祷！", },
	[61319] = {id=61319, zh_CN="扯犊子呢？我可没看到过你在礼堂！", },
	[61320] = {id=61320, zh_CN="哈哈哈哈，那这下不是明牌了？4号和6号两个恶魔。", },
	[61321] = {id=61321, zh_CN="我去……我什么都没说啊，我是无辜的啊！！", },
	[61322] = {id=61322, zh_CN="1号你别带节奏，你和4号两个狼？大家先投1！", },
	[61323] = {id=61323, zh_CN="诬告？可以，我和6号杠上了！大家都4号然后6！如果游戏没结束，就投我！", },
	[61324] = {id=61324, zh_CN="既然你这么说了……那就先投4，下一回合再投6吧？", },
	[61325] = {id=61325, zh_CN="没看到有人淘汰啊？咋回事呢？", },
	[61326] = {id=61326, zh_CN="1号在礼堂那边拍了紧急会议的按钮吧？", },
	[61327] = {id=61327, zh_CN="啥是紧急会议按钮啊？", },
	[61328] = {id=61328, zh_CN="就是就算没人淘汰，我也可以在这里拍按钮！虽然需要等待时间和次数限制。但是——", },
	[61329] = {id=61329, zh_CN="这一切都是值得的！", },
	[61330] = {id=61330, zh_CN="你说这话不仅中二……而且也太可疑了。是不是防止好人做完任务才这么做的？", },
	[61331] = {id=61331, zh_CN="你胡说！因为刚才4号可是说你们两个都在礼堂做任务，但我们没人看到过。这就说明你们两个绝对都是恶魔！", },
	[61332] = {id=61332, zh_CN="无语……不能他陷害我吗？", },
	[61333] = {id=61333, zh_CN="我可看着你一直靠近玩家哦。8号，你别怕，我自爆了，我是侦探。6号就是恶魔！", },
	[61334] = {id=61334, zh_CN="大家看，又一铁证。把他投出去，我们就赢了！", },
	[61335] = {id=61335, zh_CN="这还挺简单的嘛！恶魔是6……", },
	[61336] = {id=61336, zh_CN="唉……我服了，这四号也太坑了！！！", },
	[61337] = {id=61337, zh_CN="该伙伴已被任命为信使，无法遣散", },
	[61338] = {id=61338, zh_CN="这么快？我还没做完任务呢。这任务做的有点慢啊。", },
	[61339] = {id=61339, zh_CN="……这里大家一起做任务读条会更快，抱团可能也安全点。大家注意一下吧。", },
	[61340] = {id=61340, zh_CN="原来是这样……", },
	[61341] = {id=61341, zh_CN="现在是投票时间……有看到凶手吗？5号你拉的警报。", },
	[61342] = {id=61342, zh_CN="我感觉是3号", },
	[61343] = {id=61343, zh_CN="？？？我还在和我的伙伴机械生命闲逛呢。", },
	[61344] = {id=61344, zh_CN="你任务都不做怎么赢？", },
	[61345] = {id=61345, zh_CN="我保9。我明牌了，我是侦探，我刚用了技能。他不是恶魔。", },
	[61346] = {id=61346, zh_CN="那先投3号吧。投个小3号助助兴！他任务都不做就在带伙伴玩，肯定有问题！", },
	[61347] = {id=61347, zh_CN="好！", },
	[61348] = {id=61348, zh_CN="&*%……&%&我是猎人！我要是被投出去，肯定也把你带走！", },
	[61349] = {id=61349, zh_CN="嘿，大家看，他急了，他急了！", },
	[61350] = {id=61350, zh_CN="有点奇怪，好像走到了恶魔的特殊技能上。我刚看到有印记，就报告了……", },
	[61351] = {id=61351, zh_CN="感觉恶魔是隐秘客。被他刀掉的，走过去都会自动报告", },
	[61352] = {id=61352, zh_CN="这把有点难啊。这一下子被驱逐了那么多……", },
	[61353] = {id=61353, zh_CN="还有机会赢。说不定恶魔就剩下一个了。大家抓紧做任务吧。", },
	[61354] = {id=61354, zh_CN="要不要投一个？", },
	[61355] = {id=61355, zh_CN="别投了吧。这再投，万一投错了，就惨了。咱们就完蛋了。", },
	[61356] = {id=61356, zh_CN="唉……还是抓紧做任务吧。", },
	[61357] = {id=61357, zh_CN="您的好友【%s】为您寄来一封加急信件", },
	[61358] = {id=61358, zh_CN="打开信件", },
	[61359] = {id=61359, zh_CN="已阅读", },
	[61360] = {id=61360, zh_CN="所属", },
	[61361] = {id=61361, zh_CN="原名：", },
	[61362] = {id=61362, zh_CN="删除信件中的尚未领取的物品已为您领取~", },
	[62000] = {id=62000, zh_CN="角落里的烛台落满了灰尘，应该是很久没有被点燃了。", },
	[62001] = {id=62001, zh_CN="那边的烛台落满了灰呢，让我们一起将它擦拭干净吧！", },
	[62002] = {id=62002, zh_CN="去打开属于你的宝箱吧，这便是探索中的收获。", },
	[62003] = {id=62003, zh_CN="金灿灿的箱子里，一定有不一样的惊喜。", },
	[62004] = {id=62004, zh_CN="这里怎么会有南瓜车出现？要去看看吗。", },
	[62005] = {id=62005, zh_CN="精巧的南瓜车，像童话书里的那样。", },
	[62006] = {id=62006, zh_CN="墙上的画作也是通向另一种风景的窗户。", },
	[62007] = {id=62007, zh_CN="这些画作会是谁挂在这里的呢？", },
	[62008] = {id=62008, zh_CN="在圣母像下双手合十，便能听到自己的心声。", },
	[62009] = {id=62009, zh_CN="即使是无法倾诉的愿望，圣母像也会认真聆听。", },
	[62010] = {id=62010, zh_CN="探索的过程中品尝一些甜品，也有助于体力的恢复。", },
	[62011] = {id=62011, zh_CN="要来一块小蛋糕吗？闻起来很香甜呢。", },
	[62012] = {id=62012, zh_CN="他们说书中自有珍宝，一起翻翻看吗？说不定有你要找的东西。", },
	[62013] = {id=62013, zh_CN="好大的书架，书里会有你要的答案吗？", },
	[62014] = {id=62014, zh_CN="奇怪的镜子，小心点靠近。", },
	[62015] = {id=62015, zh_CN="快来看看这面魔镜，真好奇它会和你说些什么小秘密。", },
	[62016] = {id=62016, zh_CN="那里怎么有一只黑猫？要去看看吗？", },
	[62017] = {id=62017, zh_CN="好神秘的小黑猫，感觉身上藏了不少秘密。", },
	[62018] = {id=62018, zh_CN="<color=#ffc000>积极性</color>", },
	[62019] = {id=62019, zh_CN="<color=#ffc000>[积极性]</color>", },
	[62020] = {id=62020, zh_CN="积极性", },
	[62021] = {id=62021, zh_CN="<color=#ffc000>饱食度</color>", },
	[62022] = {id=62022, zh_CN="<color=#ffc000>[饱食度]</color>", },
	[62023] = {id=62023, zh_CN="饱食度", },
	[62024] = {id=62024, zh_CN="感觉头脑清醒了不少，开工！", },
	[62025] = {id=62025, zh_CN="哼哼，终于可以正常思考了！", },
	[62026] = {id=62026, zh_CN="精神好多了，看来还是得劳逸结合", },
	[62027] = {id=62027, zh_CN="这点小伤当然不算什么，我已经完全恢复了", },
	[62028] = {id=62028, zh_CN="休息的不错，已经满血复活。", },
	[62029] = {id=62029, zh_CN="差点以为身体要垮掉了，还好活过来了。", },
	[62030] = {id=62030, zh_CN="感觉动力又回来了，有什么需要我帮忙的吗？", },
	[62031] = {id=62031, zh_CN="动力满满！全速开工！", },
	[62032] = {id=62032, zh_CN="现在的我可是精力充沛的！", },
	[62033] = {id=62033, zh_CN="吃饱喝足，接下来就该干正事了", },
	[62034] = {id=62034, zh_CN="果然吃饱了才有力气干活嘛", },
	[62035] = {id=62035, zh_CN="疲惫的时候，还是美食最治愈心灵呀！", },
	[62036] = {id=62036, zh_CN="感觉……要不行了", },
	[62037] = {id=62037, zh_CN="真的已经精疲力尽了……", },
	[62038] = {id=62038, zh_CN="救命啊……我要举报压榨", },
	[62039] = {id=62039, zh_CN="呼吸两口新鲜空气，感觉头脑都变清醒了", },
	[62040] = {id=62040, zh_CN="我才没摸鱼，看看大家的工作进展罢了", },
	[62041] = {id=62041, zh_CN="多走走多转转，才有工作的新灵感！", },
	[62042] = {id=62042, zh_CN="飞行时无法使用该功能", },
