	[62056] = {id=62056, zh_CN="信件管理", },
	[62057] = {id=62057, zh_CN="好像有人来信了？快来看一看吧！", },
	[62058] = {id=62058, zh_CN="哦呀？是新的信件，要不要来看一看？", },
	[62059] = {id=62059, zh_CN="站住站住！你有一封加急信件！", },
	[62060] = {id=62060, zh_CN="有一封新的信件，寄信人好像很着急，快来看看吧！", },
	[62061] = {id=62061, zh_CN="你可算来了，快来看看这封加急信！", },
	[62062] = {id=62062, zh_CN="使命必达！", },
	[62063] = {id=62063, zh_CN="相信我吧，绝对不会弄丢的！", },
	[62064] = {id=62064, zh_CN="遵命！速速送达！", },
	[62065] = {id=62065, zh_CN="让我帮你送信？那你可是找对人了！", },
	[62066] = {id=62066, zh_CN="专业不对口啊……不过既然是你的请求，我一定会努力完成！", },
	[62067] = {id=62067, zh_CN="感谢你的信任", },
	[62068] = {id=62068, zh_CN="呜……以后都不需要我了吗……", },
	[62069] = {id=62069, zh_CN="是我哪里做得不够好吗……", },
	[62070] = {id=62070, zh_CN="诶？！你有新的好朋友了吗？！", },
