	[62076] = {id=62076, zh_CN="空间站的大家都是很好的人，对吧？", },
	[62077] = {id=62077, zh_CN="好呀，正好我闲着，你想问什么？", },
	[62078] = {id=62078, zh_CN="我负责在这里接引每一个来到空间站的新朋友。", },
	[62079] = {id=62079, zh_CN="你一直在这里吗？", },
	[62080] = {id=62080, zh_CN="祝你在空间站过得愉快。", },
	[62081] = {id=62081, zh_CN="只是白天啦，晚上的空间站还是很恐怖的……", },
	[62082] = {id=62082, zh_CN="谢谢你一直以来对我这么好……以后如果有什么无法自己面对的事情，还请带上我。", },
	[62083] = {id=62083, zh_CN="我可以问你点问题吗？", },
