	[70595] = {id=70595, zh_CN="看不顺眼", },
	[70596] = {id=70596, zh_CN="水火不容", },
	[70597] = {id=70597, zh_CN="是说书人呀……虽然没办法享受游戏的胜负，但这可是位拥有上帝视角，足以左右战局的角色！", },
	[70598] = {id=70598, zh_CN="想好要帮助哪一方赢得胜利了吗？可不要太偏心影响他人的游戏体验哦", },
	[70599] = {id=70599, zh_CN="诶，失语者？只要自己被投票淘汰就可以了吗？我说，你这个角色好有趣！", },
	[70600] = {id=70600, zh_CN="居然不需要做任务，反而只需要让自己被淘汰就行了？不过我还是要提醒你啊，白天也要小心坏人哦！", },
	[70601] = {id=70601, zh_CN="真羡慕你啊，在黑夜中你居然是绝对安全的……这难道就是黑夜的庇护吗？", },
	[70602] = {id=70602, zh_CN="真可惜，只能在会议时淘汰他人，要是在白天也能就好了，对吧？", },
	[70603] = {id=70603, zh_CN="既然淘汰的恶魔越多就可以越快胜利，那就把他们作为首选目标好了，快快快！", },
	[70604] = {id=70604, zh_CN="赏金猎人啊……准备好寻找并淘汰我们的赏金目标了吗？", },
	[70605] = {id=70605, zh_CN="最快只需要淘汰三个人就能赢了，这可比超市大酬宾还划算啊！", },
	[70606] = {id=70606, zh_CN="参与人数越多，需求胜利的赏金目标也会越多的话，数字什么的就别管了！准备好领取胜利的赏金了吗？", },
	[70607] = {id=70607, zh_CN="放轻松，这个身份能保护你免受夜晚时来自他人的伤害", },
	[70608] = {id=70608, zh_CN="对我们而言，淘汰全部人！是胜利的唯一途径！", },
	[70609] = {id=70609, zh_CN="记得在夜晚会议时使用技能哦，我们可以轻松复制他人的技能！", },
	[70610] = {id=70610, zh_CN="做好准备了吗？一旦复制的对象被淘汰……就轮到我们继承那家伙的胜利条件了", },
	[70611] = {id=70611, zh_CN="僧侣？一个很厉害的保护型角色呢。谨慎分析，在夜晚保护一位可怜人吧", },
	[70612] = {id=70612, zh_CN="好有意思的身份啊……能够得知离自己最近两位玩家的身份！虽然不知道具体的是谁……", },
	[70613] = {id=70613, zh_CN="哨兵……在白天淘汰你的家伙会立刻自动报告。该如何运用好这个身份和能力呢……", },
	[70614] = {id=70614, zh_CN="只要在会议中就可以使用技能挖掘被淘汰者的身份……小心一点活到会议上吧", },
	[70615] = {id=70615, zh_CN="有怀疑的对象吗？占卜师的话，可以在晚上选择嫌疑人，查看那家伙有没有对别人用过技能哦。", },
	[70616] = {id=70616, zh_CN="让我看看……士兵……白天可以抵挡驱逐同时在晚上得知此事，晚上也免疫攻击技能与驱逐……你这职业也太强了吧！", },
	[70617] = {id=70617, zh_CN="让我来看看你能否一次就审判正确吧，把【恶魔】们都揪出来！", },
	[70618] = {id=70618, zh_CN="这可是个带刀好人的角色唉。在夜晚会议可以选择淘汰一个家伙，但千万别选中村民啊！", },
	[70619] = {id=70619, zh_CN="我现在宣布，你是最棒的侦探！每晚都能够随机得知一个还存活着的身份，这可是很强大的力量啊！", },
	[70620] = {id=70620, zh_CN="哦，每晚都能得知一条别人知道的消息……有些像是传说中的狗仔队？", },
	[70621] = {id=70621, zh_CN="只要在晚上使用技能进入梦游状态，被淘汰时，淘汰目标就会变成你身边的两位，真好玩！", },
	[70622] = {id=70622, zh_CN="一定要好好利用上天给你的不受到侵蚀和药剂影响的特权啊！", },
	[70623] = {id=70623, zh_CN="白天能看见谁正在遭受负面状态的攻击，晚上也能得知被淘汰的相关信息……这简直就是神一般的角色啊！", },
	[70624] = {id=70624, zh_CN="居然是猎魔人先生么！淘汰掉坏人是你的职责呢！不过选错了的话……你是不是就不能当警察了？", },
	[70625] = {id=70625, zh_CN="我们只有一次机会……当我们被投票放逐之时，选择一个家伙，让那家伙陪我们一起下地狱吧！", },
	[70626] = {id=70626, zh_CN="只要所有存活的家伙都被使用过煽动技能就算胜利……一定要小心接近他人啊", },
	[70627] = {id=70627, zh_CN="这样一来……你是不是就可以猜测他们的身份然后淘汰他们啦？这才是逆行人的作风！", },
	[70628] = {id=70628, zh_CN="别害怕，他们都会以为你是【村民】的！不如来玩躲猫猫，怎么样！", },
	[70629] = {id=70629, zh_CN="淘汰对方后，可以让对方的身体变为无形哦，我们就能偷偷转移了！", },
	[70630] = {id=70630, zh_CN="淘汰对方的话，我们可以快点离开，别人来到身体附近后就会立刻报告的！这就是……陷害吧？！", },
	[70631] = {id=70631, zh_CN="加油啊！每淘汰一位村民你就能得知他知道的全部信息，这当然是……多多益善啦！对吧？", },
	[70632] = {id=70632, zh_CN="这个角色我喜欢！可以把淘汰的人变成你的侍从！还无法用技能反抗你！", },
	[70633] = {id=70633, zh_CN="可以转化他人变为己方阵营……我们得选择些厉害的家伙来增加胜率啊！", },
	[70634] = {id=70634, zh_CN="没关系，要随时做好当上领主的准备啊！", },
	[70635] = {id=70635, zh_CN="这难道就是传说中的一箭双雕吗？晚上被你神奇咒语诅咒的两个人，只要有一人被淘汰，另外一人也难以幸免。", },
	[70636] = {id=70636, zh_CN="白天虽然无法攻击，但是我们可以在晚上干活，让他们的技能失效对情报的干扰还挺有作用的！", },
	[70637] = {id=70637, zh_CN="工作台？这可真是天助我也！", },
	[70638] = {id=70638, zh_CN="去前面看看！我仿佛看到了胜利的光芒！", },
	[70639] = {id=70639, zh_CN="嘿！前面似乎有新的发现，看看去！", },
	[70640] = {id=70640, zh_CN="一味的前进可不行！去工作台那里看看能不能获得什么收获吧！", },
	[70641] = {id=70641, zh_CN="喂喂喂，一味的防守可不行啊，我们偶尔也要学会反击。", },
	[70642] = {id=70642, zh_CN="虽然是一个人的队伍，有了它，可就不是一个人在战斗了！", },
	[70643] = {id=70643, zh_CN="工作台？在这附近找找看，肯定能收获些什么！", },
	[70644] = {id=70644, zh_CN="要不要利用一些道具？肯定很有趣！", },
	[70645] = {id=70645, zh_CN="无论结果怎样，先发现工作台可就是我抢占了先机！", },
	[70646] = {id=70646, zh_CN="走！去那边找点乐子！说不定还有意外的收获。", },
	[70647] = {id=70647, zh_CN="那些家伙肯定会来这！我们在这里守株待兔怎么样！", },
	[70648] = {id=70648, zh_CN="别以为有了工作台就能赢我！可别太小看我们！", },
	[70649] = {id=70649, zh_CN="武器吗？正好！我们也需要一把新的呢。", },
	[70650] = {id=70650, zh_CN="看看这里还有别的道具吗？", },
	[70651] = {id=70651, zh_CN="我们也需要一把新的武器才行……可不能被那些家伙拿到反击的机会啊！", },
	[70652] = {id=70652, zh_CN="有了它，它就是我最趁手的武器！", },
	[70653] = {id=70653, zh_CN="别小看了它，虽然简单，可刀才是最好的武器呢！", },
	[70654] = {id=70654, zh_CN="不愧是刚打制的新刀，真漂亮！", },
	[70655] = {id=70655, zh_CN="让我想想看，有了刀……我能做些什么呢。", },
	[70656] = {id=70656, zh_CN="喂！可千万不能小看这最不引人注目的武器啊！", },
	[70657] = {id=70657, zh_CN="哇塞，这么大？这可不符合”坏人“的做派啊！", },
	[70658] = {id=70658, zh_CN="这样一来，我们就更不用担心啦！难道你还不相信我吗，这简直就是如鱼得水！", },
	[70659] = {id=70659, zh_CN="我相信，这么完美的武器，一定只有在我们手上才能最大的发挥作用。", },
	[70660] = {id=70660, zh_CN="失去了一些伙伴啊……不过，可别因此沮丧啊", },
	[70661] = {id=70661, zh_CN="小小的劣势而已，我相信你能轻松力挽狂澜", },
	[70662] = {id=70662, zh_CN="仅凭这点挫折，可不能让我们放弃。", },
	[70663] = {id=70663, zh_CN="机会还很多……我们一定能找到他们的破绽的", },
	[70664] = {id=70664, zh_CN="这个人数……别心急，我们得找找机会", },
	[70665] = {id=70665, zh_CN="事情变得有意思起来了，除了白天外，我们也得注意晚上的会议情况了", },
	[70666] = {id=70666, zh_CN="出了点小意外，看来还得更努力才行", },
	[70667] = {id=70667, zh_CN="千万别灰心啊，我们一起想想办法，俗话说的好，“破局之道就在其中”嘛！", },
	[70668] = {id=70668, zh_CN="这就是传说中的绝命时刻了……我们不能辜负逝者的期待", },
	[70669] = {id=70669, zh_CN="看来我们拖不得了，使出全力破局吧", },
	[70670] = {id=70670, zh_CN="看来老话说的没错，果然绝地翻盘才是最激动人心的时刻啊！", },
	[70671] = {id=70671, zh_CN="人数还很多，得想想办法继续控制人数", },
	[70672] = {id=70672, zh_CN="还有这么多人……我们距离胜利还有一大段路要走呢", },
	[70673] = {id=70673, zh_CN="也许我们得考虑一下村民和恶魔阵营的平衡了", },
	[70674] = {id=70674, zh_CN="好多人啊……或许单靠我们自己的力量是不行的！", },
	[70675] = {id=70675, zh_CN="哦~这个人数比很不错嘛，特别适合我们浑水摸鱼，不是吗？", },
	[70676] = {id=70676, zh_CN="我感觉还是不够，我们想赢的话，还需要再降低点人数", },
	[70677] = {id=70677, zh_CN="就是现在，我们发挥实力的时候到了！", },
	[70678] = {id=70678, zh_CN="一切都在按照预想中的发展啊……", },
	[70679] = {id=70679, zh_CN="别担心。你看，现在局面不是好起来了吗？在保证自己不被投出去的同时，先观察一下局面吧！", },
	[70680] = {id=70680, zh_CN="他们还没发现我们？这下我们的胜算就大了", },
	[70681] = {id=70681, zh_CN="呜呼！是时候进行最佳中立的表演了！", },
	[70682] = {id=70682, zh_CN="他们或许再也无法利用阵营人数的优势把我们投出去了！对吧？", },
	[70683] = {id=70683, zh_CN="目标越来越少了……就是现在！尝试出手改变局面吧！", },
	[70684] = {id=70684, zh_CN="现在，我们就不需要隐藏实力了！", },
	[70685] = {id=70685, zh_CN="别紧张，对局才刚刚开始，一切不是正在朝着有利的方向发展着吗？", },
	[70686] = {id=70686, zh_CN="适应得还挺快的嘛……我等着你带飞！", },
	[70687] = {id=70687, zh_CN="这对于我来说，也算是一个不小的收获！", },
	[70688] = {id=70688, zh_CN="进度加快了！看来你很擅长玩这种游戏嘛！", },
	[70689] = {id=70689, zh_CN="嘿！你有没有发现，游戏真是越来越有趣了？", },
	[70690] = {id=70690, zh_CN="加油啊，我们可是要全力保持住目前稳步前进的节奏啊！", },
	[70691] = {id=70691, zh_CN="呜呼！我好像预见了胜利，你呢？", },
	[70692] = {id=70692, zh_CN="天才的拍档！这简直赢得轻轻松松！", },
	[70693] = {id=70693, zh_CN="没有难度，我就说你可以！", },
	[70694] = {id=70694, zh_CN="只差最后一点了，再加加油我们就能赢了！简直就是易如反掌啊哈哈哈哈哈！", },
	[70695] = {id=70695, zh_CN="怎么样？有适应这个规则吗。", },
	[70696] = {id=70696, zh_CN="遇到困难就告诉我！我来看看能不能帮上什么忙！", },
	[70697] = {id=70697, zh_CN="再坚持一下！事情在朝着越来越好的方向发展了！", },
	[70698] = {id=70698, zh_CN="你看，我就说吧，任务完成得越来越顺利啦！", },
	[70699] = {id=70699, zh_CN="累了吗？我们在这里偷偷摸鱼应该不会被发现吧……", },
	[70700] = {id=70700, zh_CN="我刚才偷偷看了看，我们的进度比好多人都快！你真的太厉害了！", },
	[70701] = {id=70701, zh_CN="好！还剩最后一些，就能全部完成！", },
	[70702] = {id=70702, zh_CN="原来我有点小看你了！居然这么快就能解决！", },
	[70703] = {id=70703, zh_CN="千万别松劲啊……拿出你的全部实力！我们来完成这最后一点！", },
	[70704] = {id=70704, zh_CN="任务？这是什么新的手段吗……", },
	[70705] = {id=70705, zh_CN="先别急，看看这个任务究竟有什么作用……", },
	[70706] = {id=70706, zh_CN="这些任务居然被他们完成得越来越多了啊看来我们也应该采取一些行动才行。", },
	[70707] = {id=70707, zh_CN="我明白了……他们想要通过这些任务来取胜的话，我相信你一定有办法！", },
	[70708] = {id=70708, zh_CN="看来情况有些紧急了呀或许我们应该看看【恶魔】们做了什么。", },
	[70709] = {id=70709, zh_CN="情况不妙了我们必须加快脚步才能取胜。", },
	[70710] = {id=70710, zh_CN="别急，有你在，我相信我们一定还有办法可以扳倒他们！", },
	[70711] = {id=70711, zh_CN="原来的路子行不通啊……必须想想有没有什么别的办法可以阻止他们完成这些。", },
	[70712] = {id=70712, zh_CN="这样的进度太慢了，我们也找点乐子去。", },
	[70713] = {id=70713, zh_CN="行动的时间还很充裕，不如我们先去看看周围的情况怎么样？", },
	[70714] = {id=70714, zh_CN="暂时还没关系的继续保持原有的节奏就好，现在局面还没有发生什么太大的变化。", },
	[70715] = {id=70715, zh_CN="虽然完成任务也是取胜的好办法，但是这也为我们提供了一条新的思路不是吗？", },
	[70716] = {id=70716, zh_CN="情况越来越棘手了，可不能让他们继续这样下去。", },
	[70717] = {id=70717, zh_CN="振作起来这个进度还没有到完全无法挽回的程度嘛……我们一起想想办法！", },
	[70718] = {id=70718, zh_CN="【村民】们已经完成这么多了吗……我们也要展示真正的实力了！", },
	[70719] = {id=70719, zh_CN="保持冷静我们一定还有别的方法可以取胜。", },
	[70720] = {id=70720, zh_CN="我果然没有看错，我就说一定能做到！", },
	[70721] = {id=70721, zh_CN="对于我们来说，简直就是轻轻松松！", },
	[70722] = {id=70722, zh_CN="你看那是什么？像不像……胜利在向我们招手！", },
	[70723] = {id=70723, zh_CN="有时候果然还是得相信，人多力量大啊！", },
	[70724] = {id=70724, zh_CN="等到下次，我们一定要扳回一局！", },
	[70725] = {id=70725, zh_CN="怎么会这样……看来要有针对性的研究一下了……", },
	[70726] = {id=70726, zh_CN="可千万别气馁啊看到那个更强大的自己了么，这就是下一次的胜利。", },
	[70727] = {id=70727, zh_CN="无需多虑，按照你自己的想法，试着引导战局的走向吧。", },
	[70728] = {id=70728, zh_CN="可以试试偶尔说说假话，无妨，让对局变得有意思起来！", },
	[70729] = {id=70729, zh_CN="你可以帮助任何人，也可以误导任何人，亲爱的，这全凭你自己的喜好。", },
	[70730] = {id=70730, zh_CN="正义的、邪恶的，都与你无关，如何让自己安全的被投出去才是最重要的。", },
	[70731] = {id=70731, zh_CN="记住，不是活下来，是努力让自己被投出去。", },
	[70732] = {id=70732, zh_CN="千万别记错了规则，违背秩序的失语者，让自己被淘汰你就赢了。", },
	[70733] = {id=70733, zh_CN="是在找目标吗？我们可只能在黑夜里淘汰对手哦，现在是白天~", },
	[70734] = {id=70734, zh_CN="在白天，我们可以找找其他人的位置，辨明他们的身份以便我们更好在晚上大展拳脚。", },
	[70735] = {id=70735, zh_CN="无需为即将到来的黑夜感到恐惧，你在夜里是无敌的。", },
	[70736] = {id=70736, zh_CN="赏金目标可不会送上门来，快行动起来吧！", },
	[70737] = {id=70737, zh_CN="别发呆了，保持移动！", },
	[70738] = {id=70738, zh_CN="在寻找赏金目标吗？跟着指引就能快速找到了。", },
	[70739] = {id=70739, zh_CN="大胆的动手嘛~反正在晚上除了投票淘汰外，没有其他能伤害你的手段。", },
	[70740] = {id=70740, zh_CN="在想怎么伪装吗？淘汰他人的时候别被发现就好了。", },
	[70741] = {id=70741, zh_CN="想要尽快取得胜利吗？那就记住你的使命，淘汰掉所有人！", },
	[70742] = {id=70742, zh_CN="在挑选复制的对象吗？是得谨慎一点，毕竟只有一次机会。", },
	[70743] = {id=70743, zh_CN="复制完后就该想想怎么让他在会议中被淘汰了~被复制的目标只要在会议中被淘汰就是咱们的胜利了。", },
	[70744] = {id=70744, zh_CN="喂喂喂，可别让其他人抢先淘汰了你的目标啊，不然就只能你来代替他完成他的获胜条件了。", },
	[70745] = {id=70745, zh_CN="别发呆了，我们的优先目标还是完成任务~", },
	[70746] = {id=70746, zh_CN="如果利用技能在晚上保护他人，确实是需要好好思考的，但我们应该尽快开始做任务了。", },
	[70747] = {id=70747, zh_CN="晚上释放技能时要好好挑选对象，别挑到了邪恶阵营的玩家。", },
	[70748] = {id=70748, zh_CN="如果已经知道部分身份信息的话，就在完成任务的途中求证一下吧。", },
	[70749] = {id=70749, zh_CN="不管知道的身份是什么，我们不应该就此止步，行动起来，寻找更多线索吧。", },
	[70750] = {id=70750, zh_CN="有些迷茫了？不要担心，只要到了夜晚我们可以随机得知两侧玩家的身份，那时再做决定吧。", },
	[70751] = {id=70751, zh_CN="呃……站着当诱饵，没问题吗？我们还是先去做做任务吧？", },
	[70752] = {id=70752, zh_CN="在这里待着，恶魔也未必会来啦，动起来动起来~", },
	[70753] = {id=70753, zh_CN="虽然白天你可以这么肆无忌惮，但晚上咱们可得小心了。", },
	[70754] = {id=70754, zh_CN="老实说，别为逝者哀悼了，快点行动起来做做任务吧。", },
	[70755] = {id=70755, zh_CN="我真不想在夜晚动用我们的能力……因为这意味着有人被淘汰了。", },
	[70756] = {id=70756, zh_CN="老发呆也不是个办法，实在不行，我们去找找被淘汰的家伙？", },
	[70757] = {id=70757, zh_CN="有什么怀疑的对象吗？技能只有在夜晚会议时才能使用，我们先去做做任务吧？", },
	[70758] = {id=70758, zh_CN="做任务的时候说不定还能撞见一些嫌疑人呢，别呆这儿了！", },
	[70759] = {id=70759, zh_CN="有怀疑的对象的话，不妨在夜晚里对他用用技能吧，或许能查出些什么来。", },
	[70760] = {id=70760, zh_CN="%PlayerName你未免也太嚣张了吧……尽管每一个白天可以免疫一次伤害，但要是有第二次那可就危险了！", },
	[70761] = {id=70761, zh_CN="只有进了夜晚会议时才知道自己是否被驱逐过，所以保险起见，尽快动起来做做任务吧！", },
	[70762] = {id=70762, zh_CN="别害怕啦，每个白天你可以免疫一次伤害，在晚上也不会被技能所淘汰哦！", },
	[70763] = {id=70763, zh_CN="站在这里可没办法帮助我们找到恶魔，行动起来吧。", },
	[70764] = {id=70764, zh_CN="我们的技能很关键，可以在晚上直接淘汰一个恶魔，白天还是得快点动起来排一下他人的身份吧。", },
	[70765] = {id=70765, zh_CN="如果审判的对象不是恶魔，我们会因此失去技能的……慎重起见，还是快点找找线索吧。", },
	[70766] = {id=70766, zh_CN="我们的技能一局之中只能在夜晚中释放一次，如果选中了村民，驱逐的可是我们自己，别发呆了，找找线索吧！", },
	[70767] = {id=70767, zh_CN="我们技能的伤害性和负面效果都不弱……为了保险起见，先做做任务推动一下进度吧。", },
	[70768] = {id=70768, zh_CN="别站着不动啦，我们的主场在夜晚，在白天里还是得保持移动和完成任务才行。", },
	[70769] = {id=70769, zh_CN="避开怀疑的对象，抓紧完成任务吧，别发呆了。", },
	[70770] = {id=70770, zh_CN="夜晚里得知的信息是随机的……所以我们得依靠自己的智慧排除身份，得出最终结论，去找找线索吧！", },
	[70771] = {id=70771, zh_CN="无论怎么样，原地不动，可是最危险的行为啊！", },
	[70772] = {id=70772, zh_CN="哦？是在编辑小报吗？快点动起来！除非你想被恶魔抓到淘汰！", },
	[70773] = {id=70773, zh_CN="白天的情况，我想，我们还是以做任务为优先吧，只要任务进度达到100%，我们就胜利了！", },
	[70774] = {id=70774, zh_CN="夜晚的时候你将能够随机得知一条其他人刚得知的信息，好好利用起来吧。", },
	[70775] = {id=70775, zh_CN="喂喂喂！现在可是白天，还不是做梦的时候！该去做任务了！", },
	[70776] = {id=70776, zh_CN="醒醒，我们的技能只能在夜晚使用，现在是白天！", },
	[70777] = {id=70777, zh_CN="害怕被攻击的话，不如在夜晚试试利用一下一直困扰你的梦游，把你受到的伤害转嫁给相邻的人吧！", },
	[70778] = {id=70778, zh_CN="还在，祈祷吗？该停下来了，打败恶魔的最好方式是投票和做任务！", },
	[70779] = {id=70779, zh_CN="在白天，我们能看出来其他玩家是否有受到技能效果的影响，这样可以更好确定恶魔！行动起来吧~", },
	[70780] = {id=70780, zh_CN="虽然说侵蚀和药剂效果对你是无效的，但直接的伤害还是有效的，别站着发呆了！", },
	[70781] = {id=70781, zh_CN="如果有玩家被淘汰，在夜晚时我们可以随机得知一条他知道的消息，这就意味着，我们得活到夜晚！快动起来别被抓到了。", },
	[70782] = {id=70782, zh_CN="嘿，猎魔人，上班时间到了，别发呆了。", },
	[70783] = {id=70783, zh_CN="快去找找可疑的家伙，确定的话就给那家伙一枪吧！不过得小心，如果那家伙的身份是村民，那倒霉的就是我们自己了……", },
	[70784] = {id=70784, zh_CN="一旦技能对象是村民，我们就会被淘汰，得多找找线索以更好确定坏人，快走吧！", },
	[70785] = {id=70785, zh_CN="（假任务）", },
