	[90101] = {id=90101, zh_CN="单发枪", },
	[90102] = {id=90102, zh_CN="这把和老猎人使用的那把外观一样的枪，采用了同样的传统工艺制作，也同样具备了捍卫正义的力量。", },
	[90200] = {id=90200, zh_CN="你确定取消伙伴制作吗", },
	[90201] = {id=90201, zh_CN="取消后道具制作速度会减慢甚至暂停", },
	[90202] = {id=90202, zh_CN="你确定取消制作吗", },
	[90203] = {id=90203, zh_CN="取消制作后依然会进入冷却并且你不会收获任何东西", },
	[100000] = {id=100000, zh_CN="技能不存在", },
	[100001] = {id=100001, zh_CN="技能使用者不是玩家", },
	[100002] = {id=100002, zh_CN="勇气不足", },
	[100003] = {id=100003, },
	[100004] = {id=100004, zh_CN="他们总能给出最公平且务实的裁决。", },
	[100005] = {id=100005, zh_CN="相比圆滑的社交，他们更信赖白纸黑字的契约。", },
	[100006] = {id=100006, zh_CN="在社交中极度克制，不轻易被他人的情感牌所打动。", },
	[100007] = {id=100007, zh_CN="他们是规则的坚定捍卫者，行事严谨且注重客观证据。", },
	[100008] = {id=100008, zh_CN="总能精准记住朋友的各种喜好。", },
	[100009] = {id=100009, zh_CN="社交中往往不争不抢，会极力避开冲突。", },
	[100010] = {id=100010, zh_CN="习惯默默提供全方位照顾，却常常忘记心疼自己。", },
	[100011] = {id=100011, zh_CN="性格极其温和细腻，是团队里最不可或缺的坚实后盾。", },
	[100012] = {id=100012, zh_CN="沟通风格直接且高效。", },
	[100013] = {id=100013, zh_CN="在群体中可以迅速确立秩序并分配任务。", },
	[100014] = {id=100014, zh_CN="天生的统御力，喜欢用铁腕手段推动团队前进。", },
	[100015] = {id=100015, zh_CN="有时会显得过于严苛，难以察觉微妙的情感波动。", },
	[100016] = {id=100016, zh_CN="极度看重社交中的和谐氛围。", },
	[100017] = {id=100017, zh_CN="遇到危机时能积极协调各方资源。", },
	[100018] = {id=100018, zh_CN="深受周围人的信赖与依靠，总是努力照顾他人情绪。", },
	[100019] = {id=100019, zh_CN="做重大决定时容易犹豫，常常需要寻求认可与建议。", },
	[100020] = {id=100020, zh_CN="面对他人过度的情绪，往往会不知所措甚至逃避。", },
	[100021] = {id=100021, zh_CN="拥有极强的手工与实操天赋，习惯用工具去解构世界。", },
	[100022] = {id=100022, zh_CN="社交中喜欢保持安全距离，不愿被过于紧密的关系所束缚。", },
	[100023] = {id=100023, zh_CN="脾气温顺且随遇而安，拥有得天独厚的艺术直觉。", },
	[100024] = {id=100024, zh_CN="对待感情真挚且热烈，倾向于用陪伴来表达爱意。", },
	[100025] = {id=100025, zh_CN="极度排斥被条条框框限制，只想自由自在地生活。", },
	[100026] = {id=100026, zh_CN="他们是永远充满干劲且敢于试错的勇士。", },
	[100027] = {id=100027, zh_CN="拥有极其敏锐的观察力，热爱冒险与挑战极限。", },
	[100028] = {id=100028, zh_CN="社交风格直率且极具感染力，总能轻易成为聚会的焦点。", },
	[100029] = {id=100029, zh_CN="他们仿佛天生就活在聚光灯下。", },
	[100030] = {id=100030, zh_CN="对别人的情绪和问题有强烈的同情心。", },
	[100031] = {id=100031, zh_CN="具有无可匹敌的亲和力，能化解社交场合中的尴尬。", },
	[100032] = {id=100032, zh_CN="把开心放在生活的绝对首位，享受被众人环绕的快乐。", },
	[100033] = {id=100033, zh_CN="社交中往往保持高冷的疏离感。", },
	[100034] = {id=100034, zh_CN="习惯在内心推演极其复杂的棋局。", },
	[100035] = {id=100035, zh_CN="面对突发状况总能保持绝对客观。", },
	[100036] = {id=100036, zh_CN="行事风格极其独立，不会被大众的刻板评价所轻易动摇。", },
	[100037] = {id=100037, zh_CN="相比维系人际网络，他们更在乎思维的绝对自由。", },
	[100038] = {id=100038, zh_CN="抗拒死板的常规操作，总能在随性中创造出意外之喜。", },
	[100039] = {id=100039, zh_CN="对万事万物充满好奇，热衷于在脑海里尝试奇妙想法。", },
	[100040] = {id=100040, zh_CN="待人接物往往比较佛系，但聊到兴趣话题就会两眼放光。", },
	[100041] = {id=100041, zh_CN="在人际交往中占据绝对主导。", },
	[100042] = {id=100042, zh_CN="非常善于发掘并调动他人优势。", },
	[100043] = {id=100043, zh_CN="为了带领团队抵达彼岸，他们会果断扫除一切障碍。", },
	[100044] = {id=100044, zh_CN="他们是能指引时代方向的舵手，天生散发着领袖气场。", },
	[100045] = {id=100045, zh_CN="很容易对枯燥的日常感到厌倦。", },
	[100046] = {id=100046, zh_CN="凭借机智幽默，能轻松驾驭各种社交。", },
	[100047] = {id=100047, zh_CN="极其享受语言交锋，常常在激烈的辩论中寻找灵感。", },
	[100048] = {id=100048, zh_CN="脑子里装满了天马行空的点子，热切地追逐新奇事物。", },
	[100049] = {id=100049, zh_CN="有着本能的共情能力，愿意向他人提供倾听。", },
	[100050] = {id=100050, zh_CN="精神世界丰富且充满浪漫色彩，向往纯粹的灵魂契合。", },
	[100051] = {id=100051, zh_CN="在人群中常常显得害羞安静，社交需要消耗很大的精神能量。", },
	[100052] = {id=100052, zh_CN="渴望建立触及灵魂深处的情感羁绊。", },
	[100053] = {id=100053, zh_CN="致力于为身处迷茫的人提供精神疗愈。", },
	[100054] = {id=100054, zh_CN="拥有能看穿人心的深邃直觉，能敏锐察觉隐秘情绪。", },
	[100055] = {id=100055, zh_CN="因为过度承载外界情绪，常常需要独处来恢复精神能量。", },
	[100056] = {id=100056, zh_CN="永远充满阳光与旺盛的好奇心。", },
	[100057] = {id=100057, zh_CN="热爱自由与广阔的未知，渴望奇妙的冒险之旅。", },
	[100058] = {id=100058, zh_CN="情绪起伏往往非常剧烈，面对重复的生活极易失去耐心。", },
	[100059] = {id=100059, zh_CN="对待每一个新朋友都抱有极大善意，用热情点燃沉闷的空气。", },
	[100060] = {id=100060, zh_CN="习惯将帮助他人发掘潜能视为己任。", },
	[100061] = {id=100061, zh_CN="社交中往往八面玲珑，能照顾每个人的情绪。", },
	[100062] = {id=100062, zh_CN="在乎他人的眼光与评价，偶尔会委屈自己去迎合大众期待。", },
	[100063] = {id=100063, zh_CN="浑身散发着温暖与极强的亲和力，是朋友们最可靠的前行灯塔。", },
