	[100280] = {id=100280, zh_CN="主人今天状态不错哦。", },
	[100281] = {id=100281, zh_CN="慢慢来，我会陪着您。", },
	[100282] = {id=100282, zh_CN="别怕，我永远陪在你身边。", },
	[100283] = {id=100283, zh_CN="再努力一下就好啦！", },
	[100284] = {id=100284, zh_CN="主人，请保持自信。", },
	[100285] = {id=100285, zh_CN="主人是最棒的！必胜！", },
	[100286] = {id=100286, zh_CN="全力出击，看您的了！", },
	[100287] = {id=100287, zh_CN="就是现在！冲呀！", },
	[100288] = {id=100288, zh_CN="主人加油！你可以的。", },
	[100289] = {id=100289, zh_CN="展现魅力的时刻到了！", },
	[100290] = {id=100290, zh_CN="聆听你的内心，去吧。", },
	[100291] = {id=100291, zh_CN="加油，突破你自己。", },
	[100292] = {id=100292, zh_CN="愿抚平你的不安。", },
	[100293] = {id=100293, zh_CN="我会给予你力量。", },
	[100294] = {id=100294, zh_CN="我在陪伴你，别怕。", },
	[100295] = {id=100295, zh_CN="毫无迷惘，勇往直前。", },
	[100296] = {id=100296, zh_CN="你会有一次好的相遇。", },
	[100297] = {id=100297, zh_CN="你和他的牵绊已经连结。", },
	[100298] = {id=100298, zh_CN="他会喜欢你的。", },
	[100299] = {id=100299, zh_CN="去绽放你的光芒吧。", },
	[100300] = {id=100300, zh_CN="别紧张，我在你身后。", },
	[100301] = {id=100301, zh_CN="别怕，去试一试吧。", },
	[100302] = {id=100302, zh_CN="相信自己，没问题的。", },
	[100303] = {id=100303, zh_CN="深呼吸，你能行的！", },
	[100304] = {id=100304, zh_CN="加油呀~", },
	[100305] = {id=100305, zh_CN="就是现在！冲！", },
	[100306] = {id=100306, zh_CN="完美的时机到了！", },
	[100307] = {id=100307, zh_CN="社交技能已充满！", },
	[100308] = {id=100308, zh_CN="无需犹豫！", },
	[100309] = {id=100309, zh_CN="满分状态，立刻搭讪！", },
	[100310] = {id=100310, zh_CN="没什么大不了的喵~", },
	[100311] = {id=100311, zh_CN="蹭蹭你，放松心情。", },
	[100312] = {id=100312, zh_CN="呼噜噜，深呼吸~", },
	[100313] = {id=100313, zh_CN="你很棒，相信猫猫的眼光。", },
	[100314] = {id=100314, zh_CN="他看起来很好攻略喵。", },
	[100315] = {id=100315, zh_CN="喵呜！气场全开。", },
	[100316] = {id=100316, zh_CN="没有人能逃掉你的搭讪！", },
	[100317] = {id=100317, zh_CN="扑上去拿下他！", },
	[100318] = {id=100318, zh_CN="让他见识你的魅力！", },
	[100319] = {id=100319, zh_CN="抓住时机，绝不手软。", },
