	[100354] = {id=100354, zh_CN="他好像很期待与你对话。", },
	[100355] = {id=100355, zh_CN="像猛兽一样征服他！", },
	[100356] = {id=100356, zh_CN="忘却刚刚的踌躇，冲！", },
	[100357] = {id=100357, zh_CN="称霸这个社交战场吧。", },
	[100358] = {id=100358, zh_CN="释放你野性魅力！", },
	[100359] = {id=100359, zh_CN="嗷呜！冲鸭！", },
	[100360] = {id=100360, zh_CN="吐个泡泡，放松一下。", },
	[100361] = {id=100361, zh_CN="咕噜咕噜，深呼吸~", },
	[100362] = {id=100362, zh_CN="你的魅力闪耀海洋。", },
	[100363] = {id=100363, zh_CN="摇摇尾巴，别紧张嘛。", },
	[100364] = {id=100364, zh_CN="咕噜咕噜，展示你的魅力。", },
	[100365] = {id=100365, zh_CN="掀起一场社交风暴！", },
	[100366] = {id=100366, zh_CN="这一刻，你是海王。", },
	[100367] = {id=100367, zh_CN="让他掉进你的鱼塘！", },
	[100368] = {id=100368, zh_CN="跃出水面，惊艳全场！", },
	[100369] = {id=100369, zh_CN="乘上这股巨浪冲吧！", },
	[100370] = {id=100370, zh_CN="哇！你做到了！", },
	[100371] = {id=100371, zh_CN="社交达人诞生啦。", },
	[100372] = {id=100372, zh_CN="刚才的表现超自然。", },
	[100373] = {id=100373, zh_CN="完美发挥！", },
	[100374] = {id=100374, zh_CN="教科书级搭讪。", },
	[100375] = {id=100375, zh_CN="为你竖起尾巴庆祝。", },
	[100376] = {id=100376, zh_CN="他果然败下阵来。", },
	[100377] = {id=100377, zh_CN="棒，奖励你小鱼干。", },
	[100378] = {id=100378, zh_CN="你是本猫的骄傲呀。", },
	[100379] = {id=100379, zh_CN="完全展现出你的魅力了喵。", },
	[100380] = {id=100380, zh_CN="毫无延迟的完美搭讪。", },
	[100381] = {id=100381, zh_CN="检测到对方好感飙升。", },
	[100382] = {id=100382, zh_CN="数据显示：对方很高兴。", },
	[100383] = {id=100383, zh_CN="完美的搭讪交互。", },
	[100384] = {id=100384, zh_CN="效率极高，表现满分！", },
	[100385] = {id=100385, zh_CN="甜度爆表~", },
	[100386] = {id=100386, zh_CN="你们眼神拉丝咯~", },
	[100387] = {id=100387, zh_CN="哇，我受不了啦！", },
	[100388] = {id=100388, zh_CN="好甜蜜的氛围~", },
	[100389] = {id=100389, zh_CN="你们的甜度在上升咯。", },
	[100390] = {id=100390, zh_CN="毫无延迟的完美搭讪。", },
	[100391] = {id=100391, zh_CN="检测到对方好感飙升。", },
	[100392] = {id=100392, zh_CN="数据显示：对方很高兴。", },
	[100393] = {id=100393, zh_CN="机械生命都要为你心动了。", },
	[100394] = {id=100394, zh_CN="效率极高，表现满分！", },
	[100395] = {id=100395, zh_CN="真是触动灵魂的交流。", },
	[100396] = {id=100396, zh_CN="愿你们的友谊长存。", },
	[100397] = {id=100397, zh_CN="我为你的勇敢欢呼~", },
	[100398] = {id=100398, zh_CN="你的社交礼仪非常优雅。", },
