	[101526] = {id=101526, zh_CN="随机事件心情+5", },
	[101527] = {id=101527, zh_CN="随机事件心情+10", },
	[101528] = {id=101528, zh_CN="随机事件心情+15", },
	[101529] = {id=101529, zh_CN="随机事件心情-5", },
	[101530] = {id=101530, zh_CN="随机事件心情-10", },
	[101531] = {id=101531, zh_CN="随机事件心情-15", },
	[101532] = {id=101532, },
	[101533] = {id=101533, zh_CN="随机事件心情+5", },
	[101534] = {id=101534, zh_CN="随机事件心情+10", },
	[101535] = {id=101535, zh_CN="随机事件心情+15", },
	[101536] = {id=101536, zh_CN="随机事件心情-5", },
	[101537] = {id=101537, zh_CN="随机事件心情-10", },
	[101538] = {id=101538, zh_CN="随机事件心情-15", },
	[101539] = {id=101539, },
	[101540] = {id=101540, zh_CN="刚才好像梦到好多好吃的...", },
	[101541] = {id=101541, zh_CN="是谁！谁袭击了我！", },
	[101542] = {id=101542, zh_CN="哼哼哼~♪…啊...你听到啦？嘿嘿。", },
	[101543] = {id=101543, zh_CN="嘿...虽然不是什么大事...但我还挺厉害的吧？", },
	[101544] = {id=101544, zh_CN="哇...这风吹得好舒服啊…今天运气应该不错！", },
	[101545] = {id=101545, zh_CN="咦那个好可爱！…啊没什么...我就看看。", },
	[101546] = {id=101546, zh_CN="（瞄一眼…赶紧移开）…应该没被发现吧？", },
	[101547] = {id=101547, zh_CN="唔…今晚会有什么好吃的呢？光是想想就开心~", },
	[101548] = {id=101548, zh_CN="其实你之前帮我的那次…我一直都记在心里呢。", },
	[101549] = {id=101549, zh_CN="哈哈哈…突然想起上次那件事...真的太好笑了！", },
	[101550] = {id=101550, zh_CN="不知道为什么...总觉得以后会越来越好的！", },
	[101551] = {id=101551, zh_CN="我好像也能派上一点用场了呢？不是光跟着而已！", },
	[101552] = {id=101552, zh_CN="对对对！我突然想到一个超棒的主意！等下告诉你！", },
	[101553] = {id=101553, zh_CN="嗯…仔细想想...我好像确实比以前厉害了不少？", },
	[101554] = {id=101554, zh_CN="今天状态超好！感觉走多远都不会累！", },
	[101555] = {id=101555, zh_CN="呼啊——浑身都清清爽爽的...这感觉真好~", },
	[101556] = {id=101556, zh_CN="要是你能夸我一句就好了…我今天还挺努力的呢。", },
	[101557] = {id=101557, zh_CN="嗯…想聊点什么...但又不知道怎么开口…算了...就这样一起走着也挺好的。", },
	[101558] = {id=101558, zh_CN="嘿嘿…要是能一直这样下去该多好啊。光想想就忍不住笑出来了！", },
	[101559] = {id=101559, zh_CN="谢谢你愿意带上我…能和你做伙伴...是我最幸运的事了。", },
	[101560] = {id=101560, zh_CN="嗝~刚才那顿也太好吃了吧！现在感觉嘴巴里还有余味呢...满足满足~", },
	[101561] = {id=101561, zh_CN="啧…说不上来...就是觉得有点烦。别管我...一会儿就好了。", },
	[101562] = {id=101562, zh_CN="咦…？我是不是少了什么东西…算了...想不起来了。", },
	[101563] = {id=101563, zh_CN="呼…走了好久了...腿有点酸。不过还能坚持...没事！", },
	[101564] = {id=101564, zh_CN="咕噜噜…啊...肚子叫了。有点想吃东西了…", },
	[101565] = {id=101565, zh_CN="哈啊——昨天翻来覆去的就是睡不着...现在好困…", },
	[101566] = {id=101566, zh_CN="怎么感觉身上粘粘的…是不是在哪蹭到什么东西了。", },
	[101567] = {id=101567, zh_CN="也不知道家里现在怎么样了…算了不想了。", },
	[101568] = {id=101568, zh_CN="唉…最近好像都没发生什么有意思的事呢。", },
	[101569] = {id=101569, zh_CN="我刚才那句话是不是说得不太好…TA会不会不高兴了…", },
	[101570] = {id=101570, zh_CN="万一…万一那样的话怎么办…啊不行...不能老往坏处想！", },
	[101571] = {id=101571, zh_CN="以后到底会变成什么样呢…我想那么多也没用...但还是忍不住…", },
	[101572] = {id=101572, zh_CN="…刚才那个人是谁啊。算了...跟我又没什么关系。", },
	[101573] = {id=101573, zh_CN="我是不是跟得太紧了…你也需要一点自己的空间吧。", },
	[101574] = {id=101574, zh_CN="阿嚏！头有点晕…不会是感冒了吧…回去得喝点热的。", },
	[101575] = {id=101575, zh_CN="总感觉身上哪里怪怪的…又说不上来...怪不舒服的。", },
	[101576] = {id=101576, zh_CN="嘶——刚才好像想到了什么不好的事…算了别想了别想了。", },
	[101577] = {id=101577, zh_CN="怎么周围这么安静…大家都去哪了…谁来陪我说说话吧。", },
	[101578] = {id=101578, zh_CN="我是不是什么都做不好啊…为什么每次都差那么一点…", },
	[101579] = {id=101579, zh_CN="你今天好像都没怎么跟我说话…是我做错什么了吗…", },
	[101580] = {id=101580, zh_CN="好难受…头也晕...身上也没力气…我是不是病了…", },
	[101581] = {id=101581, zh_CN="好饿好饿好饿…我感觉现在能吃下一整桌的菜！", },
	[101582] = {id=101582, zh_CN="受不了了…总觉得浑身都黏糊糊的...好想立刻洗个澡啊！", },
	[101583] = {id=101583, zh_CN="如果有一天你觉得不需要我了…怎么办…对不起...我就是忍不住会这样想。", },
	[101584] = {id=101584, zh_CN="从头到脚哪里都不对…一点力气都提不起来…好想躺着…", },
