	[150230] = {id=150230, zh_CN="喵喵飞扑！", },
	[150231] = {id=150231, zh_CN="无敌猫猫拳！", },
	[150232] = {id=150232, zh_CN="有了它，你还会陪着本喵吗……", },
	[150233] = {id=150233, zh_CN="世界上没有什么事是一条小鱼酥解决不了的，如果有，就两条", },
	[150234] = {id=150234, zh_CN="今天，我的身份是馋猫！谁有意见！", },
	[150235] = {id=150235, zh_CN="别以为给本喵这个就能收买本喵！", },
	[150236] = {id=150236, zh_CN="我也不想答应……可是他给的小鱼酥实在太多了喵喵喵", },
	[150237] = {id=150237, zh_CN="本喵心情很好，奖励你两声喵喵叫", },
	[150238] = {id=150238, zh_CN="这是什么？小鱼！摸一下喵", },
	[150239] = {id=150239, zh_CN="滑溜溜的东西，不喜欢喵！坏小鸟！", },
	[150240] = {id=150240, zh_CN="我也可以看到……这么鲜艳的色彩吗？", },
	[150241] = {id=150241, zh_CN="真漂亮，可是……它也和我一样吗，没有跳动的心脏？", },
	[150242] = {id=150242, zh_CN="这是你送给我的星星吗？我想叫它，%PlayerName", },
	[150243] = {id=150243, zh_CN="现在的技术已经如此进步了吗？可以把银河藏在石头里", },
	[150244] = {id=150244, zh_CN="检测到碳元素……不必怀疑，%PlayerName，你也是我的钻石", },
	[150245] = {id=150245, zh_CN="谢谢你，感觉自己焕然一新", },
	[150246] = {id=150246, zh_CN="爱？好奇怪的情感", },
	[150247] = {id=150247, zh_CN="很新奇的感觉……你也能够感觉得到爱吗？", },
	[150248] = {id=150248, zh_CN="零件之间流动着奇怪的感觉……是出故障了吗？", },
	[150249] = {id=150249, zh_CN="我也能够感觉到，热血澎湃！", },
	[150250] = {id=150250, zh_CN="很通畅的感觉……是不是就像……人类睡了一个很舒服的觉？", },
	[150251] = {id=150251, zh_CN="我想，我还能够继续顺利的运作一万年！", },
	[150252] = {id=150252, zh_CN="对于我们来说，这可是爆款！", },
	[150253] = {id=150253, zh_CN="重获新生！感谢你，%PlayerName", },
	[150254] = {id=150254, zh_CN="看起来有些破旧，我想它应该更换零件了", },
	[150255] = {id=150255, zh_CN="原来这种旧旧的风格也这么受欢迎", },
	[150256] = {id=150256, zh_CN="难道当我被淘汰的一天，也会变成一只怀表吗？", },
	[150257] = {id=150257, zh_CN="他记录的是过去的时间，我可以帮你做一只新的，用它来记录我们的明天", },
	[150258] = {id=150258, zh_CN="有了它，我想，我的旅途会更顺利，谢谢你", },
	[150259] = {id=150259, zh_CN="真好，感觉很轻盈，谢谢你", },
	[150260] = {id=150260, zh_CN="我听到了好熟悉的声音……电流啊……它也是我的同伴吗？", },
	[150261] = {id=150261, zh_CN="让我来和他比比，谁更快呢！", },
	[150262] = {id=150262, zh_CN="真是令人吃惊的恐怖动力系统！", },
	[150263] = {id=150263, zh_CN="好流畅的车身，好优美的车型……让我这个铁坨子也感受到了压力！", },
	[150264] = {id=150264, zh_CN="这是来自宇宙的力量吗？好神奇", },
	[150265] = {id=150265, zh_CN="人族的故事吗！那我们种族有没有呀？", },
	[150266] = {id=150266, zh_CN="感觉看到了全新的世界呢", },
	[150267] = {id=150267, zh_CN="这里有专属于我们的失传的大餐吗？", },
	[150268] = {id=150268, zh_CN="拜托，我们妖灵族吃的东西可不一样！", },
	[150269] = {id=150269, zh_CN="好香啊~就像回到家里，真是令人心安，谢谢你", },
	[150270] = {id=150270, zh_CN="喂！我们可不是猫啊！最多只能算猫科！", },
	[150271] = {id=150271, zh_CN="太好啦！这样我就可以把家乡的味道留下来！", },
	[150272] = {id=150272, zh_CN="谢谢你，感觉手部光滑了许多……下次试试能不能用在毛皮上呢？", },
	[150273] = {id=150273, zh_CN="第一次有人送我这样的东西诶！我们精灵可是会自我养护的哦！滑滑的感觉！", },
	[150274] = {id=150274, zh_CN="不可以偷偷吃掉我！", },
	[150275] = {id=150275, zh_CN="这简直就是对我们偷懒大王的恩赐！", },
	[150276] = {id=150276, zh_CN="其实我有一个梦想，就是……长到三米成为一棵大树！", },
	[150277] = {id=150277, zh_CN="人是铁饭是钢，植物是铁，营养液是钢！", },
	[150278] = {id=150278, zh_CN="好险，差点饿了", },
	[150279] = {id=150279, zh_CN="你回答我！菜谱里的原材料是什么！！", },
	[150280] = {id=150280, zh_CN="植物……植物也是会痛的！", },
	[150281] = {id=150281, zh_CN="这熟悉的味道……世界上又多了好多失去孩子的母亲……", },
	[150282] = {id=150282, zh_CN="这次<color=#db4141>伪装</color>无懈可击，可以维持更长时间。", },
	[150283] = {id=150283, zh_CN="对于伪装的精髓毫无领悟，完全不知道该怎么办。", },
	[150284] = {id=150284, zh_CN="<color=#db4141>伪装</color>还算凑合，时间稍长容易露馅。", },
	[150285] = {id=150285, zh_CN="努力尝试了下，还是失败了。", },
	[150286] = {id=150286, zh_CN="这次<color=#db4141>变形</color>完美无缺，可以维持更长时间。", },
	[150287] = {id=150287, zh_CN="完全没法变形……", },
	[150288] = {id=150288, zh_CN="这次<color=#db4141>变形</color>还算过得去，注意时间。", },
	[150289] = {id=150289, zh_CN="找不到一点变形术的灵感……", },
	[150290] = {id=150290, zh_CN="一眼识破了{0}正假装成了{1}，这一切都逃不过你的眼睛！", },
	[150291] = {id=150291, zh_CN="看着看着，似乎觉得周围的异常也许只有自己？", },
	[150292] = {id=150292, zh_CN="努力地观察之后，识破了{0}变成了{1}。", },
	[150293] = {id=150293, zh_CN="没有发现周围有什么异常。", },
	[150294] = {id=150294, zh_CN="成功找到了<color=#bed742>{0}</color>", },
	[150295] = {id=150295, zh_CN="没能找到任何隐秘", },
	[150296] = {id=150296, zh_CN="你发现了<color=#bed742>{0}</color>", },
	[150297] = {id=150297, zh_CN="睁大眼睛，什么都没发现", },
	[150298] = {id=150298, zh_CN="发现了更多小秘密", },
	[150299] = {id=150299, zh_CN="彻底栽了，连表层想法都无法看透", },
	[150300] = {id=150300, zh_CN="发现了一个小秘密", },
	[150301] = {id=150301, zh_CN="人物的心思仿佛迷雾", },
	[150302] = {id=150302, zh_CN="精妙的侦查如利剑破雾，精确而巧妙地揭开了{0}的隐秘面纱。", },
	[150303] = {id=150303, zh_CN="这次侦查，简直就像是去捉鬼却只抓到了空气。", },
	[150304] = {id=150304, zh_CN="这次侦查虽然磕磕绊绊，但总算找到了隐藏的{0}。", },
	[150305] = {id=150305, zh_CN="你睁大了眼睛，但什么都没发现。", },
	[150306] = {id=150306, zh_CN="仔细观察，你确信周围无人隐匿形迹。", },
	[150307] = {id=150307, zh_CN="倾听心底，周围无人隐藏秘密。", },
	[150308] = {id=150308, zh_CN="是否确认退出社团？团长退出社团后，权限将自动转移给管理员", },
	[150309] = {id=150309, zh_CN="当前社团仅剩团长您一人，在您退出后，社团将被解散", },
	[150310] = {id=150310, zh_CN="社团退出确认", },
	[150311] = {id=150311, zh_CN="是否确认退出社团？退出后将自动收回和领取对应道具并清空对应社团的活跃度。", },
	[150312] = {id=150312, zh_CN="是否确认解散社团？解散后将自动收回和领取对应道具并清空社团数据，且未领取的社区仓库道具会被删除，请谨慎确认！", },
	[150313] = {id=150313, zh_CN="社团解散确认。", },
	[150314] = {id=150314, zh_CN="社团退出成功！", },
	[150315] = {id=150315, zh_CN="社团解散成功！", },
	[150316] = {id=150316, zh_CN="社团退出失败。", },
	[150317] = {id=150317, zh_CN="社团解散失败。", },
	[150318] = {id=150318, zh_CN="这是要干什么？！快放我下来！", },
	[150319] = {id=150319, zh_CN="喂喂喂……怎么突然这么做！", },
	[150320] = {id=150320, zh_CN="怎么突然抱我？", },
	[150321] = {id=150321, zh_CN="诶？是遇到什么问题了吗？", },
	[150322] = {id=150322, zh_CN="好啦好啦，我知道你的意思了，先放我下来好不好？", },
	[150323] = {id=150323, zh_CN="嗯？突然的拥抱？我也要给你一个！", },
	[150324] = {id=150324, zh_CN="嘿！你猜，我是谁？", },
	[150325] = {id=150325, zh_CN="诶诶诶别躲啊，被我抓到了吧！", },
	[150326] = {id=150326, zh_CN="偷袭！让你看看我的神速！", },
	[150327] = {id=150327, zh_CN="嘿！猜猜……我是谁！", },
	[150328] = {id=150328, zh_CN="我来啦！离我近一点！", },
	[150329] = {id=150329, zh_CN="让你见识一下我的力量！", },
	[150330] = {id=150330, zh_CN="喂，这样做很危险的啊！", },
	[150331] = {id=150331, zh_CN="小心小心！下次我也要让你尝尝被扔出的滋味！", },
	[150332] = {id=150332, zh_CN="别想跑！我来和你一决胜负！", },
	[150333] = {id=150333, zh_CN="小心啊！这样做很危险的！", },
	[150334] = {id=150334, zh_CN="千万别让自己受伤了呀%PlayerName！嗯？你问我是不是讨厌这样做？完全不是！", },
	[150335] = {id=150335, zh_CN="太刺激了！是我从未有过的新奇体验！", },
	[150336] = {id=150336, zh_CN="这就对了，好好走路，嗯！", },
	[150337] = {id=150337, zh_CN="突然抱起来又突然放下……你是受什么刺激了吗？", },
	[150338] = {id=150338, zh_CN="其实不用这么快放下来的……", },
	[150339] = {id=150339, zh_CN="看来你应该好很多啦！这样一来我就放心啦！", },
	[150340] = {id=150340, zh_CN="你真有趣，下次我们还要这样！", },
	[150341] = {id=150341, zh_CN="能够这样做已经很厉害啦！接下来我们要一起去做些什么吗？", },
	[150342] = {id=150342, zh_CN="喂，别一直盯着我啊，很别扭的……", },
	[150343] = {id=150343, zh_CN="怎么了，我脸上有什么东西吗？", },
	[150344] = {id=150344, zh_CN="你今天怎么怪怪的，一直看着我？", },
	[150345] = {id=150345, zh_CN="为什么一直看着我，是发生什么事了吗？", },
	[150346] = {id=150346, zh_CN="别盯着我啦！", },
	[150347] = {id=150347, zh_CN="我很好奇诶%PlayerName，你每天都在看什么呀……", },
