	[150524] = {id=150524, zh_CN="甘甜微醺，发酵佳品，可直接饮用或入菜调味。", },
	[150525] = {id=150525, zh_CN="闪闪发亮的小石头，镶嵌后能让装备身价翻倍。", },
	[150526] = {id=150526, zh_CN="贝壳内层的彩虹色薄片，阳光下会折射幻光。", },
	[150527] = {id=150527, zh_CN="柔软如云朵的纤维，适合做高级衣物，也适合猫当成临时床铺。", },
	[150528] = {id=150528, zh_CN="经过鞣制的兽皮，结实耐用，可制作皮衣。", },
	[150529] = {id=150529, zh_CN="织入荧光丝线的布料，夜晚会发出微光，浪漫又实用。", },
	[150530] = {id=150530, zh_CN="轻盈透气的薄纱，穿起来像没穿，但价格像穿了黄金。", },
	[150531] = {id=150531, zh_CN="传说用龙鳞粉末强化的鞋底，防滑耐磨，但没人敢问“龙鳞哪来的”。", },
	[150532] = {id=150532, zh_CN="如水般流动的丝质材料，能自动贴合身体曲线。", },
	[150533] = {id=150533, zh_CN="厚切的巨型蘑菇肉，口感和牛排相似，素食者的自我安慰食品。", },
	[150534] = {id=150534, zh_CN="来源不明的肉块，可能是狼、野猪，或者是上周失踪的冒险者——别问，吃就对了。", },
	[150535] = {id=150535, zh_CN="深海蟹肉经过低温晶化处理，咬下去会有轻微的“咔嚓”声，像在吃宝石。", },
	[150536] = {id=150536, zh_CN="精密咬合的金属零件，不能吃，但某些狂热的工程师会拿它当零食——字面意思。", },
	[150537] = {id=150537, zh_CN="永远不会凋谢的花，梦幻光泽，泡茶提神醒脑。", },
	[150538] = {id=150538, zh_CN="翠绿到发光的蔬菜，生吃清脆甘甜，据说能让皮肤变好。", },
	[150539] = {id=150539, zh_CN="生长在魔法沼泽里的莲藕，切断后断面会缓慢愈合，炖汤时最好盯紧点，免得它自己跑掉。", },
	[150540] = {id=150540, zh_CN="外表粗糙如砂纸，果肉却细腻如冰淇淋，是大自然开的矛盾玩笑。", },
	[150541] = {id=150541, zh_CN="小小的红色恶魔，吃下去时嘴巴着火，三分钟后开始思考人生意义。", },
