	[150627] = {id=150627, zh_CN="粗糙的灰黄色颗粒，可提纯炼金，廉价且易获取。", },
	[150628] = {id=150628, zh_CN="纯白色膏体，干燥后变成细腻的瓷白色硬块。", },
	[150629] = {id=150629, zh_CN="表面覆盖油膜光晕，转动时呈现七彩，常被误认为宝石。", },
	[150630] = {id=150630, zh_CN="赤红色泥坯中带有金色星点的矿物。", },
	[150631] = {id=150631, zh_CN="琥珀色半透明石料，温润如凝脂。", },
	[150632] = {id=150632, zh_CN="漆黑底色中带音色星斑，强光照射时星斑会缓慢移动。", },
	[150633] = {id=150633, zh_CN="橙金色，表面有熔岩流动感，贵金属。", },
	[150634] = {id=150634, zh_CN="层叠状彩色矿物，常见红白相间条纹，贵重装饰品。", },
	[150635] = {id=150635, zh_CN="研磨自虹彩石，粉末状，颜色随温度变化的颜料。", },
	[150636] = {id=150636, zh_CN="浅黄木质，松软易加工，散发着淡淡松脂香气。", },
	[150637] = {id=150637, zh_CN="翠绿色的柔韧藤蔓，表面有细密纵向纹路。", },
	[150638] = {id=150638, zh_CN="深紫色硬木，油脂丰富，打磨后呈现金属光泽。", },
	[150639] = {id=150639, zh_CN="乳白色半透明粘合剂，凝固后形成弹性膜，反复撕贴不留痕。", },
	[150640] = {id=150640, zh_CN="暗红色硬木，切口处会渗出猩红汁液。", },
	[150641] = {id=150641, zh_CN="拳头大小的金色琥珀。", },
	[150642] = {id=150642, zh_CN="透明琥珀色粘稠液体，遇冷变脆，遇热流动性增强。", },
	[150643] = {id=150643, zh_CN="明黄色喇叭状花朵，花心含糖浆。", },
	[150644] = {id=150644, zh_CN="深紫色昙花，只在月光下绽放。", },
	[150645] = {id=150645, zh_CN="黑褐色不规则块茎，散发土腥香气。", },
	[150646] = {id=150646, zh_CN="赤红色伞菌，菌褶喷射橙色孢子粉，触碰微烫。", },
	[150647] = {id=150647, zh_CN="黄白色粗纤维束，将青藤浸泡捶打后分离出的丝状物。", },
	[150648] = {id=150648, zh_CN="拇指大小的方形硅片，表面蚀刻简单电路。", },
	[150649] = {id=150649, zh_CN="由电阻、电容、晶体管组成的微型模块。", },
