	[150652] = {id=150652, zh_CN="黑色立方体，表面浮现不断变化的比特序列。", },
	[150653] = {id=150653, zh_CN="发光的柔性丝线，断开后会短暂保持数据传输状态。", },
	[150654] = {id=150654, zh_CN="存储在水晶中的暗红色数据流，观察时会随机变形。", },
