	[150715] = {id=150715, zh_CN="不存在空闲中的伙伴", },
	[150716] = {id=150716, zh_CN="看来，我还是略胜一筹嘛！", },
	[150717] = {id=150717, zh_CN="这次算我赢，怎么样，还要不要再和我比试比试？", },
	[150718] = {id=150718, zh_CN="别太小看我啊我说……", },
	[150719] = {id=150719, zh_CN="等等等等，我还没准备好呢！", },
	[150720] = {id=150720, zh_CN="抓不到我吧！", },
	[150721] = {id=150721, zh_CN="嗯……等你抓到我，我就告诉你一个秘密如何！", },
	[150722] = {id=150722, zh_CN="这是什么地方？那我就……勉为其难过来看看！", },
	[150723] = {id=150723, zh_CN="喂喂！不要突然扔到我脸上啊！", },
	[150724] = {id=150724, zh_CN="欸欸欸，我认输我认输！我承认……你比我厉害……", },
	[150725] = {id=150725, zh_CN="在这里都能被你发现啊……好吧，我认输。", },
	[150726] = {id=150726, zh_CN="诶？这样一来，那是不是意味着，我们可以一起去冒险了？", },
	[150727] = {id=150727, zh_CN="既然被你抓到了，那，以后的日子，多多关照咯！", },
	[150728] = {id=150728, zh_CN="这是什么东西啊？搞错目标啦！", },
	[150729] = {id=150729, zh_CN="精灵球？这是做什么的。", },
	[150730] = {id=150730, zh_CN="嗯？你要抓捕什么东西吗……要不要去别的地方看看？", },
	[150731] = {id=150731, zh_CN="诶？我还是第一次见到这个呢，这是……精灵球吗？", },
	[150732] = {id=150732, zh_CN="这是精灵球哦，我是不可以被关进去的！", },
	[150733] = {id=150733, zh_CN="啊，你搞错目标了！如果想要抓捕一些东西的话……我倒是可以帮你找找！", },
