	[150811] = {id=150811, zh_CN="小丑", },
	[150812] = {id=150812, zh_CN="可爱的喵", },
	[150813] = {id=150813, zh_CN="异星公主", },
	[150814] = {id=150814, zh_CN="浪人", },
	[150815] = {id=150815, zh_CN="基础材料", },
