	[150820] = {id=150820, zh_CN="公告牌", },
	[150821] = {id=150821, zh_CN="工作台", },
	[150822] = {id=150822, zh_CN="仓库", },
	[150823] = {id=150823, zh_CN="该玩家的邀请已经达到上限，暂时无法发送邀请。", },
	[150824] = {id=150824, zh_CN="已邀请过该玩家，无法重复邀请。", },
	[150825] = {id=150825, zh_CN="生命百味不过是透明底色开出千色的花。", },
	[150826] = {id=150826, zh_CN="比起甜甜的机油，更能够永葆机械之心不朽的是爱。", },
	[150827] = {id=150827, zh_CN="太空忆，最忆是龙井。", },
	[150828] = {id=150828, zh_CN="象征荣耀的香槟喷薄而出，我来为你加冕。", },
	[150829] = {id=150829, zh_CN="夏天就是阳光、蝉鸣、青色麦穗还有……柠檬红茶。", },
	[150830] = {id=150830, zh_CN="你相信吗，所谓的真爱魔法？", },
	[150831] = {id=150831, zh_CN="猫吃鱼，狗吃肉……谁会打小怪兽，请举手！", },
	[150832] = {id=150832, zh_CN="呼噜呼噜冒泡泡，会不会是黑暗魔法？", },
	[150833] = {id=150833, zh_CN="形满似十五满月，雕花如双子流星。", },
	[150834] = {id=150834, zh_CN="生铁攒合的器官太容易生锈，爱的蜜糖在针尖上光合。", },
	[150835] = {id=150835, zh_CN="指尖沾染着自然的气息，我给你的烙印，我奔向你。", },
	[150836] = {id=150836, zh_CN="仿生的鲜花，花瓣是月亮做的。", },
	[150837] = {id=150837, zh_CN="清凉一口灌入衣襟，贴在心脏献上热吻。", },
	[150838] = {id=150838, zh_CN="将夏日的光影压缩成泡腾片，气泡就只顾忙碌的盛开", },
	[150839] = {id=150839, zh_CN="人生走过的八十年，不过是秸秆旺盛燃烧的第一百六十遍", },
	[150840] = {id=150840, zh_CN="切一天萝卜，每个孩子肚里都装着不少", },
	[150841] = {id=150841, zh_CN="宇宙是时间走过的路而堆出的冰山， 我只刨出一点甜", },
	[150842] = {id=150842, zh_CN="鲜肉大满罐，营养大满贯", },
	[150843] = {id=150843, zh_CN="日复一日的重复着为早餐端来一杯羊奶，也就日复一日的重复爱你", },
	[150844] = {id=150844, zh_CN="我的心是硬邦邦的烤面包，有了你，就变成香喷喷的猫罐头", },
	[150845] = {id=150845, zh_CN="黄河之水奔腾不回头，而黄河常在", },
	[150846] = {id=150846, zh_CN="世界是巨大的毒蘑菇，你是伞盖上令我致幻的斑纹", },
	[150847] = {id=150847, zh_CN="大海的心脏，如今在你手上", },
	[150848] = {id=150848, zh_CN="我们都是春天的落选者", },
	[150849] = {id=150849, zh_CN="你不是怪物，是我在照镜子", },
	[150850] = {id=150850, zh_CN="五花登顶，道法孜然", },
	[150851] = {id=150851, zh_CN="圣贤寂寞，饮者留名", },
	[150852] = {id=150852, zh_CN="请你教我，一颗机械生命的心，如何看到一棵麦子提心吊胆的秋天", },
	[150853] = {id=150853, zh_CN="小火慢炖，让自己浓郁，慢慢来的比较快", },
	[150854] = {id=150854, zh_CN="心中有慈悲，手中有中杯、大杯、超大杯", },
	[150855] = {id=150855, zh_CN="浮云卷霭，星尘流光", },
	[150856] = {id=150856, zh_CN="即使是你悲伤的色彩，我也看见五彩斑斓的黑", },
	[150857] = {id=150857, zh_CN="结束工作，我要狠狠的吃点甜头", },
	[150858] = {id=150858, zh_CN="再给我一次机会，我要做一只蜗牛，爱就是我的壳，送给你", },
	[150859] = {id=150859, zh_CN="奶茶碰杯，快乐起飞！", },
	[150860] = {id=150860, zh_CN="营养液向我键入的是前所未有的“爱”的指令", },
	[150861] = {id=150861, zh_CN="你要带我去银河，还是深海？", },
	[150862] = {id=150862, zh_CN="如果银河是大海，鲸鱼就是海里停泊的山", },
	[150863] = {id=150863, zh_CN="power on！", },
	[150864] = {id=150864, zh_CN="记忆中什么东西的味道……酸酸甜甜？", },
	[150865] = {id=150865, zh_CN="神龙的力量会是什么？", },
	[150866] = {id=150866, zh_CN="遇见你是我的幸运，幸好我有足够多的好运。", },
	[150867] = {id=150867, zh_CN="莫听穿林打叶声，漫漫旅途，何妨疾行", },
	[150868] = {id=150868, zh_CN="已经知道结局依旧选择努力奔赴，这就是勇敢", },
	[150869] = {id=150869, zh_CN="不喜欢青椒，所以报错！", },
	[150870] = {id=150870, zh_CN="透过蒸汽，能看见的是百年之前的伟大文明", },
	[150871] = {id=150871, zh_CN="残肢断骨，也是过江飞龙！", },
	[150872] = {id=150872, zh_CN="每个日出我与你一同醒来，冰冷的金属向我折射的是你炽热的辉光", },
	[150873] = {id=150873, zh_CN="妈妈说小孩子才会吃10³层，我已经长大了，我要吃10⁴层！", },
	[150874] = {id=150874, zh_CN="枫林老，柿将熟，秋在万山深处红", },
	[150875] = {id=150875, zh_CN="桂子荷花晴方好，难寻旧湖，舟远却是临安", },
	[150876] = {id=150876, zh_CN="小鱼小鱼快快游，四面八方是自由", },
	[150877] = {id=150877, zh_CN="梦回云里，我寻你大雾中", },
	[150878] = {id=150878, zh_CN="如果你见过我的曾经，就会肯定我的努力。", },
	[150879] = {id=150879, zh_CN="遗忘有一把竖琴，记忆用它，弹奏无声的忧伤。", },
	[150880] = {id=150880, zh_CN="在广袤的空间和无限的时间中，能与你共享同一段时光，是我的荣幸。", },
	[150881] = {id=150881, zh_CN="当我思考宇宙时，便拥有了一分钟的自由。", },
	[150882] = {id=150882, zh_CN="如果关于你的一切都被压缩在疗愈伤痛的胶囊里，我就能瞬间感同身受你的悲伤。", },
	[150883] = {id=150883, zh_CN="我只是旅居于你生命长河中不过万分之一的一个奇点。", },
	[150884] = {id=150884, zh_CN="你是我透明生命里红唇吻过的一场宿醉。", },
	[150885] = {id=150885, zh_CN="宙斯洒向人间的眼泪不过是你皇冠上最黯淡的一粒宝石。", },
	[150886] = {id=150886, zh_CN="再给我一次选择的机会，我不要多一张船票，我要永远", },
	[150887] = {id=150887, zh_CN="可以再讲一遍，你是怎么从一万朵花里选中我的吗？", },
	[150888] = {id=150888, zh_CN="你并没有说对，我能感同身受你，你是我生命磅礴的脉络", },
	[150889] = {id=150889, zh_CN="我不要太阳星星和月亮，我要云朵，当你扑向我你也可以享受软绵绵", },
	[150890] = {id=150890, zh_CN="外表软萌，实际硬得能当武器，建议搭配“牙医保险”食用。", },
	[150891] = {id=150891, zh_CN="喝一口甜到齁，喝两口血糖飙升，糖尿病人请绕道。", },
	[150892] = {id=150892, zh_CN="贵到离谱，吃下去只会思考：这钱买泡面不香吗？", },
	[150893] = {id=150893, zh_CN="健康食品，但吃多了会觉得自己像只兔子。", },
	[150894] = {id=150894, zh_CN="名字浪漫，实际就是“吃草”，但拍照发朋友圈能装。", },
	[150895] = {id=150895, zh_CN="辣度警告：吃一口喷火，吃两口直接变喷火龙。", },
	[150896] = {id=150896, zh_CN="养生必备，味道像洗袜子的水，但妈妈会说“对身体好”。", },
	[150897] = {id=150897, zh_CN="一杯微醺，两杯断片，三杯醒来发现自己在派出所。", },
	[150898] = {id=150898, zh_CN="看起来像果冻，吃起来像空气，价格像抢劫。", },
	[150899] = {id=150899, zh_CN="法兰西的深秋在陶瓮里，用肉香朗诵十四行诗。", },
	[150900] = {id=150900, zh_CN="切开真的会流心，但大概率流到衣服上，然后心疼干洗费。", },
	[150901] = {id=150901, zh_CN="整个海洋在瓷煲里坍缩，鲜到掉眉毛。", },
	[150902] = {id=150902, zh_CN="被虫子啃过的艺术品，自带沧桑感。收藏家看了流泪，蛀虫看了点赞。", },
	[150903] = {id=150903, zh_CN="捏的时候：达芬奇再世！干了之后：这坨东西应该能防身。", },
	[150904] = {id=150904, zh_CN="随时随地装文化人，但大概率用来泡方便面。", },
	[150905] = {id=150905, zh_CN="坐上去会忍不住哼“红伞伞白杆杆”，但放心，没毒，顶多腿麻。", },
	[150906] = {id=150906, zh_CN="把愿望写进去，它会发光——但能不能实现，得看运气。", },
	[150907] = {id=150907, zh_CN="春风、蝉鸣、稻浪与雪夜。", },
	[150908] = {id=150908, zh_CN="据说能吸收月光能量，但实际作用：深夜伤感时的最佳听众。", },
	[150909] = {id=150909, zh_CN="精致的机械心脏，在发条的驱动下吟唱旧日旋律。\n每一枚齿轮的转动，都是时光的低语。", },
	[150910] = {id=150910, zh_CN="命运在卡牌的油墨间流淌，每一次翻动，都是与未知的温柔对峙。", },
	[150911] = {id=150911, zh_CN="岁月在银盐中显影，每一帧褪色的画面，都是记忆的标本。", },
	[150912] = {id=150912, zh_CN="拉响后：浪漫！派对生物最爱，谨防邻居投诉。", },
	[150913] = {id=150913, zh_CN="吃下去能想起初恋，副作用：也可能想起尴尬的啾啾空间动态。", },
	[150914] = {id=150914, zh_CN="比普通版更贵，当然贵的有价值。", },
	[150915] = {id=150915, zh_CN="当花朵的震颤与心跳同频，灵魂便找到了共鸣的波长。", },
	[150916] = {id=150916, zh_CN="过去的微笑在光影中重生，仿佛从未离去。", },
	[150917] = {id=150917, zh_CN="全自动修复，一键开工，你值得拥有。", },
	[150918] = {id=150918, zh_CN="放一个逗猫棒在这里，愿者上钩", },
	[150919] = {id=150919, zh_CN="呼噜呼噜毛，吓不着。", },
	[150920] = {id=150920, zh_CN="只需要轻轻的，我就能让你感觉到我。", },
	[150921] = {id=150921, zh_CN="此刻抬头，世界没有天花板。", },
	[150922] = {id=150922, zh_CN="以手造物，以物寄情。", },
	[150923] = {id=150923, zh_CN="我在你身上，看见一条五千年的路。", },
	[150924] = {id=150924, zh_CN="我把小羊生命中的一段时光物化给了你。", },
	[150925] = {id=150925, zh_CN="最好湖光色，长留一道春", },
	[150926] = {id=150926, zh_CN="请在我心里留下专属于你的布洛克雕花", },
	[150927] = {id=150927, zh_CN="有你在，我的生命就有烟火", },
	[150928] = {id=150928, zh_CN="你按一下，我就出现", },
	[150929] = {id=150929, zh_CN="我看见你的手里，融尽万物天光", },
	[150930] = {id=150930, zh_CN="touch me，tease me，feel me up", },
	[150931] = {id=150931, zh_CN="再快一点，是不是就会不那么遗憾", },
	[150932] = {id=150932, zh_CN="我要永远，紧密的、永远的和你在一起", },
	[150933] = {id=150933, zh_CN="不仅是日照，我希望可以永远的罐装你的开心", },
	[150934] = {id=150934, zh_CN="日月盈昃，辰宿列张", },
	[150935] = {id=150935, zh_CN="这一瞬间，你只属于我们", },
	[150936] = {id=150936, zh_CN="一分一秒，我都珍重，我都纪念", },
	[150937] = {id=150937, zh_CN="你终于到达，云朵停靠的星期天", },
	[150938] = {id=150938, zh_CN="第一个相遇，在晨曦晒落的幽径上，一朵花告诉了我它的名字", },
	[150939] = {id=150939, zh_CN="趁我还鲜活，不许任何人熄灭我", },
	[150940] = {id=150940, zh_CN="运动是一种享受，但我不爱运动，因为我不是贪图享受的人", },
	[150941] = {id=150941, zh_CN="荣耀共战，携手前进", },
	[150942] = {id=150942, zh_CN="一千个一万个，哪一个是真的我，你爱的是哪一个我？", },
	[150943] = {id=150943, zh_CN="爱是总会相遇的圆环，在你的手里也能陪着你看遍每个角落", },
	[150944] = {id=150944, zh_CN="瑞气祥云环画阁，黄莺紫燕贺安居", },
	[150945] = {id=150945, zh_CN="我的心脏就是绳索，它牵引着我向你靠近", },
	[150946] = {id=150946, zh_CN="小小的空间，要装进整个世界", },
	[150947] = {id=150947, zh_CN="我写你，不过大漠瀚海，葳蕤山色", },
	[150948] = {id=150948, zh_CN="再远的路，只要一步，一步，再一步", },
	[150949] = {id=150949, zh_CN="春有约，花不误，大地初醒，枝头黄芽", },
	[150950] = {id=150950, zh_CN="生命闪耀的烫色，由我自己盛装", },
	[150951] = {id=150951, zh_CN="丹漆不文，白玉不雕刻", },
	[150952] = {id=150952, zh_CN="山似玉，玉如君，相看一笑温", },
	[150953] = {id=150953, zh_CN="少年荣光，英雄无双", },
	[150954] = {id=150954, zh_CN="世界不过是我的巨大卧室", },
	[150955] = {id=150955, zh_CN="城市是彩色的芯片，穿梭其中的你是我奔行的电流", },
	[150956] = {id=150956, zh_CN="爱的本质是被看见", },
	[150957] = {id=150957, zh_CN="失控的重力无法阻止我走向你", },
	[150958] = {id=150958, zh_CN="为何旧知己，在最后变不到老友", },
	[150959] = {id=150959, zh_CN="我们合二为一，我们天下无敌", },
	[150960] = {id=150960, zh_CN="请拥抱我身体里最原始爱你的欲望", },
	[150961] = {id=150961, zh_CN="稀有片剂，每日一次，温水送服", },
	[150962] = {id=150962, zh_CN="向前走吧，后视镜里就能看见走过的路，却不允许你回头", },
	[150963] = {id=150963, zh_CN="如果爱也是组成宇宙的元素之一，请刺中我的心脏", },
	[150964] = {id=150964, zh_CN="什么也不懂的时候，我们首先学习的是爱", },
	[150965] = {id=150965, zh_CN="有幸再次闻到熟悉的香气，就当是收到了过去的回信", },
	[150966] = {id=150966, zh_CN="世界本就浑浊，罪与爱同歌", },
	[150967] = {id=150967, zh_CN="请直视我，我不是我", },
	[150968] = {id=150968, zh_CN="山不就我，我自就山", },
	[150969] = {id=150969, zh_CN="无名指上有宇宙里最小的行星环", },
	[150970] = {id=150970, zh_CN="时针走过的一圈一圈，磨蚀着我，氧化着我", },
	[150971] = {id=150971, zh_CN="是爱赋予了这块石头无上的价值", },
	[150972] = {id=150972, zh_CN="伟大的雕塑！闭上眼睛，每一道衣服的褶皱都在我的心里超车", },
	[150973] = {id=150973, zh_CN="爱是星星落在你肩上的光", },
	[150974] = {id=150974, zh_CN="我做过最短的梦，是你走向我", },
	[150975] = {id=150975, zh_CN="珐琅彩，瓷上宝石，繁盛葳蕤", },
	[150976] = {id=150976, zh_CN="次元有壁，但爱没有", },
	[150977] = {id=150977, zh_CN="荒唐的世界，请先不急着打破", },
	[150978] = {id=150978, zh_CN="七色风采，得以一见", },
	[150979] = {id=150979, zh_CN="自能生羽翼，何必仰云梯", },
	[150980] = {id=150980, zh_CN="拥有一点罪吧，我才能在天使中一眼认出你", },
	[150981] = {id=150981, zh_CN="我要让你的过去也能拥有未来", },
	[150982] = {id=150982, zh_CN="看着它的眼睛，能看见的是你的真心", },
	[150983] = {id=150983, zh_CN="请在广袤漫长的旅途中，为我的陨落停留一秒", },
	[150984] = {id=150984, zh_CN="并非每个灵魂都能成长，但好在音符可以送我无限远航", },
	[150985] = {id=150985, zh_CN="三色琉璃彩，万古不变心", },
	[150986] = {id=150986, zh_CN="“感觉”？很细腻的情感，我没有", },
	[150987] = {id=150987, zh_CN="我献出的礼物是我的心脏", },
	[150988] = {id=150988, zh_CN="无需置疑，没有心脏，但有爱", },
	[150989] = {id=150989, zh_CN="好开心呀，又开始工作啦", },
	[150990] = {id=150990, zh_CN="我最爱工作啦！", },
	[150991] = {id=150991, zh_CN="当前制作内容取消成功", },
	[150992] = {id=150992, zh_CN="无可领取的道具", },
	[150993] = {id=150993, zh_CN="好好炒股不如好好干活！", },
	[150994] = {id=150994, zh_CN="制作程序已开始，正为您呼唤适合的伙伴", },
	[150995] = {id=150995, zh_CN="服务器繁忙，请稍后重试", },
	[150996] = {id=150996, zh_CN="此道具不能被卖出", },
	[150997] = {id=150997, zh_CN="【仓库】<color=#dcb56c><u>%s</u></color>从<color=#e3a574><u>%s</u></color>中取出了%s个<u>%s</u> <size=30><color=#B4C8C6> %s</color></size>", },
	[150998] = {id=150998, zh_CN="【仓库】<color=#dcb56c><u>%s</u></color>在<color=#e3a574><u>%s</u></color>中放入了%s个<u>%s</u> <size=30><color=#B4C8C6> %s</color></size>", },
	[150999] = {id=150999, zh_CN="<color=#42c6b8>【成员】<space=5><color=#dcb56c>%s</color><space=5>加入了社团</color> <size=30><color=#B4C8C6> %s</color></size>", },
	[151000] = {id=151000, zh_CN="<color=#42c6b8>【成员】<space=5><color=#dcb56c>%s</color><space=5>受<space=5><color=#dcb56c>%s</color><space=5>的邀请加入了社团</color> <size=30><color=#B4C8C6> %s</color></size>", },
	[151001] = {id=151001, zh_CN="<color=#f66f6f>【成员】<u>%s</u>已离开社团</color> <size=30><color=#B4C8C6> %s</color></size>", },
	[151002] = {id=151002, zh_CN="<color=#f66f6f>【成员】<u>%s</u>已被请离社团</color> <size=30><color=#B4C8C6> %s</color></size>", },
	[151003] = {id=151003, zh_CN="<color=#f5df4a>【社团管理】本月管理费<u>%s</u>已自动缴纳（设备维护折扣—<u>%s</u>%）</color> <size=30><color=#B4C8C6> %s</color></size>", },
	[151004] = {id=151004, zh_CN="<color=#ea4659>【社团管理】本月管理费<u>%s</u>尚未缴纳，工作台的生产受到了极大的负面影响。若在<u>%s</u>前未完成缴纳则社团将解散。</color> <size=30><color=#B4C8C6> %s</color></size>", },
