	[151364] = {id=151364, zh_CN="你展现的世代智慧，让人族视你为文明守护者。人族好感提升。", },
	[151365] = {id=151365, zh_CN="你吟诵的古老诗篇，让精灵愿为你绽放荆棘玫瑰。精灵族好感提升。", },
	[151366] = {id=151366, zh_CN="你熟知投喂与战斗的平衡，获得小恶魔们的敬畏。食味族好感提升。", },
	[151367] = {id=151367, zh_CN="你身上的爪痕是勋章，妖灵视你为荣誉族群成员。妖灵族好感提升。", },
	[151368] = {id=151368, zh_CN="你理解光能语言，举手投足间有光粒萦绕。光族好感提升。", },
	[151369] = {id=151369, zh_CN="你能用机械逻辑讲冷笑话，机械生命核心会为你发热。机械生命好感提升。", },
	[151370] = {id=151370, zh_CN="你适应猫族毫无预兆的行为模式，它们觉得你很“猫”。猫族好感提升。", },
	[151371] = {id=151371, zh_CN="你脑内的宇宙杂音，是巴别族最爱的睡前故事。巴别族好感提升。", },
