	[151519] = {id=151519, zh_CN="<color=#ffb81f>%s</color>目前状态绝佳，随时可以开工！", },
	[151520] = {id=151520, zh_CN="<color=#ffb81f>%s</color>精力充沛，现在做事一定效率很高！", },
	[151521] = {id=151521, zh_CN="<color=#ffb81f>%s</color>的积极性已经很高了，可以重返工作了！", },
	[151522] = {id=151522, zh_CN="<color=#ffb81f>%s</color>非常健康！状态很不错呢！", },
	[151523] = {id=151523, zh_CN="<color=#ffb81f>%s</color>已经吃得很饱了，状态很好！", },
	[151524] = {id=151524, zh_CN="<color=#ffb81f>%s</color>的工作有条不紊！继续为其加油吧。", },
	[151525] = {id=151525, zh_CN="<color=#ffb81f>%s</color>已经努力工作一段时间了，很有干劲呢！", },
	[151526] = {id=151526, zh_CN="<color=#ffb81f>%s</color>的状态不错，看来今天也能有不少收获。", },
	[151527] = {id=151527, zh_CN="糟糕，<color=#ffb81f>%s</color>看起来已经很累了。", },
	[151528] = {id=151528, zh_CN="劳逸结合才能更好地工作，让<color=#ffb81f>%s</color>休息一下吧！", },
	[151529] = {id=151529, zh_CN="<color=#ffb81f>%s</color>已经完成了许多工作，可以休息一下啦！", },
	[151530] = {id=151530, zh_CN="<color=#ffb81f>%s</color>看上去完全丢了魂，已经不能工作了……", },
	[151531] = {id=151531, zh_CN="快让<color=#ffb81f>%s</color>去仓库休息吧！恢复精力才能继续工作。", },
	[151532] = {id=151532, zh_CN="<color=#ffb81f>%s</color>已经没办法工作啦，先放回仓库吧。", },
	[151533] = {id=151533, zh_CN="<color=#ffb81f>%s</color>的积极性恢复了不少，看起来比之前好多了！", },
	[151534] = {id=151534, zh_CN="<color=#ffb81f>%s</color>的积极性已经大幅恢复，看起来更有活力了。", },
	[151535] = {id=151535, zh_CN="积极性正在恢复中，再让<color=#ffb81f>%s</color>休息一会儿吧！", },
	[151536] = {id=151536, zh_CN="恢复积极性还需要一点时间，再等等吧。", },
	[151537] = {id=151537, zh_CN="<color=#ffb81f>%s</color>看起来很疲惫，先让它快乐地玩一会儿吧！", },
	[151538] = {id=151538, zh_CN="<color=#ffb81f>%s</color>已经很累了，休息一会儿再重返工作吧。", },
	[151539] = {id=151539, zh_CN="<color=#ffb81f>%s</color>的健康还可以，但要记得劳逸结合哦！", },
	[151540] = {id=151540, zh_CN="<color=#ffb81f>%s</color>的健康状态良好，工作很卖力呢。", },
	[151541] = {id=151541, zh_CN="<color=#ffb81f>%s</color>的健康状态已经很差了，最好先休息一下哦。", },
	[151542] = {id=151542, zh_CN="<color=#ffb81f>%s</color>的健康状态不太好呢，先让它休息一下吧！", },
	[151543] = {id=151543, zh_CN="<color=#ffb81f>%s</color>的健康状况非常糟糕，已经无法再工作了……", },
	[151544] = {id=151544, zh_CN="<color=#ffb81f>%s</color>的健康状况很差，休息好了再继续工作吧！", },
	[151545] = {id=151545, zh_CN="<color=#ffb81f>%s</color>稍微有一点饥饿，可以给它吃些食物。", },
	[151546] = {id=151546, zh_CN="<color=#ffb81f>%s</color>工作得很卖力哦，但也要记得吃饭。", },
	[151547] = {id=151547, zh_CN="<color=#ffb81f>%s</color>已经很饿了，要及时为其补充食物！", },
	[151548] = {id=151548, zh_CN="努力工作的同时也不能忘记吃饭呢，<color=#ffb81f>%s</color>已经很饥饿了哦。", },
	[151549] = {id=151549, zh_CN="<color=#ffb81f>%s</color>已经饥肠辘辘了，吃饱了才能继续工作哦。", },
	[151550] = {id=151550, zh_CN="<color=#ffb81f>%s</color>太饿了，似乎已经没办法工作了……", },
	[151551] = {id=151551, zh_CN="太谢谢你了！真好吃！", },
	[151552] = {id=151552, zh_CN="唔哇！吃不够……", },
	[151553] = {id=151553, zh_CN="呃……有点饱了……", },
	[151554] = {id=151554, zh_CN="别别别……我……我吃不下了！", },
	[151555] = {id=151555, zh_CN="终于吃上饭了，眼泪从嘴里流了出来……", },
	[151556] = {id=151556, zh_CN="我划开第一根火柴，看见了美味的饭菜……什么，不是梦？", },
	[151557] = {id=151557, zh_CN="久别重逢的滋味，让食物更加美味！", },
	[151558] = {id=151558, zh_CN="我向群星发誓，再也不会浪费一颗粮食……", },
	[151559] = {id=151559, zh_CN="是你拯救了我的肚子吗？你是真正的英雄。", },
	[151560] = {id=151560, zh_CN="实在是太好吃了！难道你施展了什么魔法？", },
	[151561] = {id=151561, zh_CN="再来一碗！我要吃到范特西公司破产！", },
	[151562] = {id=151562, zh_CN="嗯……感觉还能再吃一个甜甜圈……", },
	[151563] = {id=151563, zh_CN="这顿吃完，宵夜再配上烧烤吧？", },
	[151564] = {id=151564, zh_CN="我经常听说：只吃半饱身体好。但愿如此……", },
	[151565] = {id=151565, zh_CN="下次可以多拿一点吗？求你了？", },
	[151566] = {id=151566, zh_CN="哎呀，就这点儿，吃不饱啊……", },
	[151567] = {id=151567, zh_CN="谢谢你！我现在非常满足！", },
	[151568] = {id=151568, zh_CN="天气晴朗，阳光正好，刚好吃饱，适合躺倒！", },
	[151569] = {id=151569, zh_CN="哇，真是完美的一餐，我现在状态绝佳！", },
	[151570] = {id=151570, zh_CN="太棒了，我感觉全身充满力气！", },
	[151571] = {id=151571, zh_CN="你帮助我完成了每一项营养指标，简直是饮食专家！", },
	[151572] = {id=151572, zh_CN="好久没有吃到这么丰盛的佳肴了……", },
	[151573] = {id=151573, zh_CN="我已经吃饱啦，给你自己留一点吧！", },
	[151574] = {id=151574, zh_CN="别光关心我啊，你自己也要按时吃饭哦！", },
	[151575] = {id=151575, zh_CN="真的吃不下了，不信？我拍胃镜给你看。", },
	[151576] = {id=151576, zh_CN="在这里生活真奢侈，吃撑了还能继续吃……", },
	[151577] = {id=151577, zh_CN="今……今天是不是给太多了？明天还有饭吃吗？", },
	[151578] = {id=151578, zh_CN="好啦好啦，再吃就走不动路了！", },
	[151579] = {id=151579, zh_CN="可以陪我聊会天吗？", },
	[151580] = {id=151580, zh_CN="今天过得怎么样？", },
	[151581] = {id=151581, zh_CN="你在这里做什么呢？", },
	[151582] = {id=151582, zh_CN="能向我介绍一下你吗？", },
	[151583] = {id=151583, zh_CN="能向我介绍一下这个世界吗？", },
