	[151703] = {id=151703, zh_CN="我原以为这颗星球只是生命中途径的岛屿，但与你的相遇让我知道了驻足的意义。", },
	[151704] = {id=151704, zh_CN="你愿意和我一起走下去吗？所有美好和奇幻，我都只想和你经历。", },
	[151705] = {id=151705, zh_CN="花叶和风声无法传达我的心，但我愿意将一切心意告知予你。", },
	[151706] = {id=151706, zh_CN="我不擅长表达情感……但又好像，我的心声你全部都知晓。这种读心的魔法，也教给我好不好？我想知道你的心，究竟是什么模样。", },
	[151707] = {id=151707, zh_CN="谢谢你一直陪我玩，但想对你说的又不止是谢谢……我好像，已经不想离开你了。", },
	[151708] = {id=151708, zh_CN="前天和你在一起玩很开心，昨天和你在一起也很开心，所以明天、后天、大后天，你也都会和我一起玩的，对吧？", },
