	[152128] = {id=152128, zh_CN="走过的地方自动开花。", },
	[152129] = {id=152129, zh_CN="流星闪烁，在你的身后捡星星。", },
	[152130] = {id=152130, zh_CN="“警告！核心温度过高——哔！”", },
	[152131] = {id=152131, zh_CN="专业制造绝对零度。", },
	[152132] = {id=152132, zh_CN="每日占卜：“宜抽卡，忌组队。”", },
	[152133] = {id=152133, zh_CN="您的人体正在尝试连接网络……", },
	[152134] = {id=152134, zh_CN="自带“笑”透明弹幕防护罩。", },
	[152135] = {id=152135, zh_CN="全服公告：您关注的主播已开播！", },
	[152136] = {id=152136, zh_CN="“真的呀~人家才不是机械生命呢~”", },
	[152137] = {id=152137, zh_CN="人形自走节奏检测器。", },
	[152138] = {id=152138, zh_CN="绑定时获得“贴贴粒子特效”。", },
	[152139] = {id=152139, zh_CN="头顶自动生成#这游戏就我非酋# 等。", },
	[152140] = {id=152140, zh_CN="痛包？无料？本子？要素察觉。", },
	[152141] = {id=152141, zh_CN="“磕到了！”", },
	[152142] = {id=152142, zh_CN="警报！“这个角色不可能说这种话！”", },
	[152143] = {id=152143, zh_CN="读心人", },
