	[152153] = {id=152153, zh_CN="山竹", },
	[152154] = {id=152154, zh_CN="成女体型1", },
	[152155] = {id=152155, zh_CN="单尾猫1（白猫）", },
	[152156] = {id=152156, zh_CN="单尾猫2（火猫）", },
	[152157] = {id=152157, zh_CN="单尾猫3（冰猫）", },
	[152158] = {id=152158, zh_CN="单尾猫4（黑猫）", },
	[152159] = {id=152159, zh_CN="当灶火跃动时，帽檐下的光影随翻炒动作流转。这顶厨帽，是厨师与火焰共舞的见证者。", },
	[152160] = {id=152160, zh_CN="月光漫过蜡烛，像给凝固的烛泪镀了层银霜，烛影在樱桃上流转。", },
	[152161] = {id=152161, zh_CN="玫瑰斜斜贴在猫咪耳前，仿佛从耳骨里钻出的小魇，悄悄趴在耳畔说尽蛊惑的话。", },
	[152162] = {id=152162, zh_CN="如罗兰花绽放的双层蝴蝶结，它不只是装饰，更是一枚绅士徽章。", },
	[152163] = {id=152163, zh_CN="领结巾系紧时，边角的弧度化作小兔，在胸口蹦跃。", },
	[152164] = {id=152164, zh_CN="断裂的锁链缠着带刺的红玫瑰，金属的冷硬与花瓣的柔媚在颈间相撞。", },
	[152165] = {id=152165, zh_CN="灶膛里未熄的余烬藏着细碎火星，尾巴尖沾了点炉底窜出的星火。", },
	[152166] = {id=152166, zh_CN="蜡泪凝固成层叠的痕迹，被永远封存在这截毛茸茸的蜡烛里。", },
	[152167] = {id=152167, zh_CN="摇动尾巴，像有两只迷你夜翼在身后扇动，带起细碎的暗影。", },
	[152168] = {id=152168, zh_CN="蛛网纹路爬满背衣，网住漫天星辰，洇出朦胧的光。", },
	[152169] = {id=152169, zh_CN="空心的皮质腿环上嵌着小小的恶魔角，又乖又野。", },
	[152170] = {id=152170, zh_CN="这顶帽子轻轻落在猫咪头顶，纹路如焦糖裂纹，咬一口自带脆响。", },
	[152171] = {id=152171, zh_CN="这顶帽子轻轻落在猫咪头顶，奶白帽顶浇淋芒果酱，金渍果肉淌出。", },
	[152172] = {id=152172, zh_CN="这顶帽子轻轻落在猫咪头顶，像草莓松饼刚从甜品碗里打翻出来的惊喜。", },
	[152173] = {id=152173, zh_CN="系上厨娘围兜，连掉落的面包粉都会变成美味糖粒。", },
	[152174] = {id=152174, zh_CN="围兜压着印花，只要系上它，兜住芒心果肉的甜爽。", },
	[152175] = {id=152175, zh_CN="围兜光滑如芋泥布丁，只要系上它，像摸到滑溜溜的芋泥。", },
	[152176] = {id=152176, zh_CN="双尾猫1", },
	[152177] = {id=152177, zh_CN="站立猫1", },
	[152178] = {id=152178, zh_CN="兜帽遮住半张脸，斗篷下是隐匿林间的侠客，所有罪恶，都逃不过猫的眼睛。", },
	[152179] = {id=152179, zh_CN="领结角的线条小鱼随领结褶皱微弯，在领口轻晃。", },
	[152180] = {id=152180, zh_CN="光族体型1", },
	[152181] = {id=152181, zh_CN="八角星芒表面流转着冷光，内部藏着让三重圆环不散架的神秘力场。", },
	[152182] = {id=152182, zh_CN="金属色圆环边随球芯转动时贴地划出轨迹，每圈旋转都带着要驶向未知的冲劲。", },
	[152183] = {id=152183, zh_CN="金属光泽忽明忽暗，像只精准的罗盘，在晃动的瞬间找到平衡角度，抵消离心力。", },
	[152184] = {id=152184, zh_CN="星芒转动时星轨率先响应，像根看不见的神经，把星芒的力量层层传递。", },
	[152185] = {id=152185, zh_CN="冰晶雪花状的球芯折射出冷冽光泽，每片雪花都是被冻结的星芒。", },
	[152186] = {id=152186, zh_CN="边缘如冰棱般锐利，贴地转动时划出从冰川里凿出的移动轨道。", },
	[152187] = {id=152187, zh_CN="尖刺在最外圈晃动的瞬间卡入平衡角度，精确锁住了失衡的力。", },
	[152188] = {id=152188, zh_CN="羽毛环绕球芯，边缘泛着绒光却带着金属的硬挺，系上圈温柔的锚。", },
	[152189] = {id=152189, zh_CN="食味族体型1", },
	[152190] = {id=152190, zh_CN="食味族体型2", },
	[152191] = {id=152191, zh_CN="食味族体型3", },
	[152192] = {id=152192, zh_CN="食味族体型4", },
	[152193] = {id=152193, zh_CN="帽身是丛生的仙人掌，沙漠里最倔强的生命力戴成桂冠，锋芒里裹着盛大的绽放。", },
	[152194] = {id=152194, zh_CN="双髻梳得圆圆的，像两团山楂果顶在头上，发髻边缘缠着圈草蒂。", },
	[152195] = {id=152195, zh_CN="锥形帽尖是芝士最挺括的棱角，帽檐的流心是融化的蜜，芝士液垂而未落。", },
	[152196] = {id=152196, zh_CN="蒂瓣向外翻卷，像甜椒自己把蒂盖在了头上，边缘不规整的弧度，像被小虫子咬过两口。", },
	[152197] = {id=152197, zh_CN="山楂花顺着披肩的弧度自然漫开，春风拂过花枝时，花瓣恰好落在肩头凝成。", },
	[152198] = {id=152198, zh_CN="挂着灯椒扣的披风，裁碎的细辣椒叶缎层层叠叠垂着，风一吹就簌簌响。", },
	[152199] = {id=152199, zh_CN="夹克铺开写满幸运四叶草的春野笺纸，是春风偷偷盖在笺角的印记。", },
	[152200] = {id=152200, zh_CN="针织衫裹住课间的微寒，将这些幸福都织进了校园的朝朝暮暮里。", },
	[152201] = {id=152201, zh_CN="穿在身上是只胖乎乎的圆筒，短绒长得乱糟糟，像刚从洗衣机里捞出来的小迷糊。", },
	[152202] = {id=152202, zh_CN="草莓裙上的图案鲜活如刚摘的果实，好似化身草莓农，在田园间穿梭，裙角轻扬。", },
	[152203] = {id=152203, zh_CN="极光的那抹晕染留在衣装上，连影子都带着极光的余韵。", },
	[152204] = {id=152204, zh_CN="绒条如风垂落，将底裙温柔包裹，围巾的绒球轻轻晃动，宛如冬日里一场温暖的邂逅。", },
	[152205] = {id=152205, zh_CN="宽松版型裹着慵懒的弧度，立领边缘嵌着金属拉链，挂坠随动作轻晃，是芝士小子留下的标记。", },
	[152206] = {id=152206, zh_CN="兜帽边缘的抽绳能拢出蓬松的弧度，裤脚卷边处磨出周末的悠闲。", },
	[152207] = {id=152207, zh_CN="PVC面料重塑的色块，在衣身拼出几何感的机能线条。", },
	[152208] = {id=152208, zh_CN="裙摆尖角裁得笔直，裙身布满方块暗纹，走动时像一副被打乱的牌在旋转。", },
	[152209] = {id=152209, zh_CN="晕染的云层，似云絮的边缘，暮色漫过的天际，是披在肩头的暮色。", },
	[152210] = {id=152210, zh_CN="巾面印着片阔大的叶，透出林间的清润，瓢虫的红影在叶隙间若隐若现", },
	[152211] = {id=152211, zh_CN="套在颈间时，不似想象中硬朗，反倒像给脖子围了圈会呼吸的光晕。", },
	[152212] = {id=152212, zh_CN="水手领翻出的袖边，像刚扬起的小帆，跑动时裙摆扬起的弧度，像航海日志里的揉碎的海浪。", },
	[152213] = {id=152213, zh_CN="袋身是花盆的圆鼓鼓，提手是吊篮的编绳，像刚浇过水的花盆带着潮气。", },
	[152214] = {id=152214, zh_CN="仙人掌的花叶顺着手臂蜷成环，是藏在荒漠里的羁绊。", },
	[152215] = {id=152215, zh_CN="鞋尖那朵桃花是游出的色彩，素净里藏着猝不及防的春。", },
	[152216] = {id=152216, zh_CN="一长一短像对闹别扭的小伙伴，是冬天里最不按常理出牌的拼色跳糖。", },
	[152217] = {id=152217, zh_CN="鞋子是莓园里的那抹藤蔓，刚从草莓地的草叶间拾来的。", },
	[152218] = {id=152218, zh_CN="穿这双雪地靴走过雪原，似在积雪茫茫中跳脱出来。", },
	[152219] = {id=152219, zh_CN="雪团膝袜长筒袜身织满细密的暖绒，袜口堆着一颗绒球，仿佛把整冬的雪暖都裹进了袜尖。", },
	[152220] = {id=152220, zh_CN="版型松快得适合运动，抬脚时金属反光一闪，像给日常的休闲加了点不抢眼的亮。", },
	[152221] = {id=152221, zh_CN="没有装饰，最基础的跑鞋，拥有随时能跑起来的劲头。", },
	[152222] = {id=152222, zh_CN="鞋舌的三角切面，与鞋跟弧度相呼应，把舒服的几何美学，都刻进了每一步里。", },
	[152223] = {id=152223, zh_CN="袜筒从裙底露出一截，蝴蝶结在脚踝处忽隐忽现，仿佛刚从花丛中掠过。", },
	[152224] = {id=152224, zh_CN="鞋面缀着个圆滚滚的绒球，走动时会随步伐左右摇晃，像藏在草丛里的蒲公英。", },
	[152225] = {id=152225, zh_CN="褶皱是被春风吹过的花瓣，层层叠叠绕在腿间，中心还缀着珍珠，像花瓣上垂落的露珠。", },
	[152226] = {id=152226, zh_CN="鞋口的蕾丝剪出海浪的弧度，像翻涌的细浪，踩在地上，能听见海浪拍岸的轻响。", },
	[152227] = {id=152227, },
	[152228] = {id=152228, zh_CN="机械生命体型1", },
	[152229] = {id=152229, zh_CN="机械生命体型2", },
	[152230] = {id=152230, zh_CN="机械生命体型3", },
	[152231] = {id=152231, zh_CN="面甲如竖劈的冰棱，前脸呈锐角三角形，边缘被打磨得比光刃更锋利，泛着能映出寒光的冷色。", },
	[152232] = {id=152232, zh_CN="面甲被哑光黑灰覆盖，前脸锐角三角形泛着暗泽，反光在棱角转折处若隐若现。", },
	[152233] = {id=152233, zh_CN="赤红焰色浸透面甲，每道棱线都有火焰舔过的痕迹，跃动着灼目的光。", },
	[152234] = {id=152234, zh_CN="块棱柱状腰铠呈放射状环住躯干，划开气流，破空直击。", },
	[152235] = {id=152235, zh_CN="腰铠被哑光黑灰浸透，如从深矿中凿出的黑曜石三棱柱，戳破光的边界。", },
	[152236] = {id=152236, zh_CN="腰铠是从熔炉里拎出的烧红棱铁，要在腰间戳破空气燃起明火。", },
	[152237] = {id=152237, zh_CN="肢臂关节藏着可折叠的菱形齿轮，齿轮带着整段肢臂飞旋，快到能绞碎气流。", },
	[152238] = {id=152238, zh_CN="棱边敛去所有光泽，轨迹隐入暗影，旋转只留下一道转瞬即逝的黑痕。", },
	[152239] = {id=152239, zh_CN="战肢弯出的弧度如卷曲的火舌，轴芯带着爆燃般的轰鸣，焰棱划破空气。", },
	[152240] = {id=152240, zh_CN="整片装甲呈弧形包裹胫部，边缘尖菱锐利，踢击棱边能瞬间撕开缺口。", },
	[152241] = {id=152241, zh_CN="如暗夜中蜷起的兽爪，根部菱形枢纽藏在暗影中，只漏出一丝暗光。", },
	[152242] = {id=152242, zh_CN="战肢绷直的瞬间带起焦炭炸裂的脆响，燃成一道火线，腾起灼热气浪。", },
	[152243] = {id=152243, zh_CN="冰锋疾影左臂的战盾 ， 盾面呈不规则菱形，启动时会在表面蔓延出冰裂纹路。", },
	[152244] = {id=152244, zh_CN="无论挥击还是格挡，都稳如嵌在深矿岩层里的巨石，让每次出手都带凌厉之势。", },
	[152245] = {id=152245, zh_CN="盾甲是如燃起来的壁垒，，菱形锐角带着熔岩喷发般的力道击碎目标。", },
	[152246] = {id=152246, zh_CN="左右各一片菱形主翼，边缘呈双重锐角，棱线泛着寒光，折叠时能收至与脊背贴合。", },
	[152247] = {id=152247, zh_CN="腾飞突进时，折翼展开，翼尖拖出两道尾迹，如黑洞仿佛把周遭光线都吸进。", },
	[152248] = {id=152248, zh_CN="晶石迸发的能量顺着棱线流淌，或悬停，或借势劈砍，是划破长空的焰翼伤器。", },
	[152249] = {id=152249, zh_CN="羊体型1", },
	[152250] = {id=152250, zh_CN="一对黄金比例螺旋的羊角是绵羊的象征，山风的纹路和岩石的肌理，都刻进了弯曲的螺纹里。", },
	[152251] = {id=152251, zh_CN="耳尖被绒毛压得微微下坠，耳廓藏在卷毛里，让人想轻轻揉捏那弧度。", },
	[152252] = {id=152252, zh_CN="鱼骨针法在线团里织出交错的棱，钩成垂落的斗篷。", },
	[152253] = {id=152253, zh_CN="羊咩咩在草原打滚，细细的铁环悄悄抱住蓬松发辫，晃着牧场的风、野花的笑～", },
	[152254] = {id=152254, zh_CN="锦鲤1", },
	[152255] = {id=152255, zh_CN="鲨鱼1", },
	[152256] = {id=152256, zh_CN="镜框弧度贴合鲨鱼吻部的流线，镜片涂层映出海底，潜水镜把海水的阻力都挡在了镜片外。", },
	[152257] = {id=152257, zh_CN="小冒险家裹了圈甜甜圈，波点在水里漾出碎光，闪烁间都是无忧无虑的浪。", },
	[152258] = {id=152258, zh_CN="暗巷夜风搓出的凌乱发梢，阴影下错觉出一头猛兽在抖落鬃毛。", },
	[152259] = {id=152259, zh_CN="流瀑裁作利落短发，暗藏的纳米光丝随动作泛起碎光。", },
	[152260] = {id=152260, zh_CN="暖阳吻过卷短发，每一缕都漾着光。", },
	[152261] = {id=152261, zh_CN="长发如霜羽垂落腰际，发丝间纠缠的草茎还沾着森林的晨露。", },
	[152262] = {id=152262, zh_CN="侧分线隐于蓬松纹理，发梢微卷自带刚跑完操场的鲜活气。", },
	[152263] = {id=152263, zh_CN="冷锋扫过的速写，用色彩的碰撞，画出风卷落的细雪。", },
	[152264] = {id=152264, zh_CN="信笺被晒旧的边缘，被岁月洇湿的告白，从发缝间漏出半行。", },
	[152265] = {id=152265, zh_CN="利落短发额间的碎发无需捕捉，低调落在每一个镜头之中。", },
	[152266] = {id=152266, zh_CN="层次像海风漫过沙滩的涟漪，留下从躺椅中打盹的痕迹。", },
	[152267] = {id=152267, zh_CN="利落短发是障眼法，当他侧头，便隐去挪用的小破绽。", },
	[152268] = {id=152268, zh_CN="高顶礼帽是午夜警戒线的残影，是怪盗的作案徽记，是他的目击者同谋。", },
	[152269] = {id=152269, zh_CN="夜幕般沉静的面料上，条纹如破晓时分的第一道霞光骤然划破天际。", },
	[152270] = {id=152270, zh_CN="几何棱面切割出战甲，辉光回路如脉络般呼吸闪烁。", },
	[152271] = {id=152271, zh_CN="挺括肩线显矜贵，纹暗缀如夜藏光，丁香徽章点睛，着身即现王子般的优雅。", },
	[152272] = {id=152272, zh_CN="躯干的缎面趴着藤蔓金纹，缠成腰封，像真有藤在脊梁上攀援。", },
	[152273] = {id=152273, zh_CN="衬衫垂坠，下摆掖一角，褶皱中藏着青春的故事和白驹过隙的诗意。", },
	[152274] = {id=152274, zh_CN="披幅如星云倾泻，手工银蔷花与碎钻花蕊绽于肩头，金属链条随步伐轻响。", },
	[152275] = {id=152275, zh_CN="衬衫的轻纱滤过100%海岛阳光，轻得像海风的皮肤。", },
	[152276] = {id=152276, zh_CN="肩线撑着假象，暗纹绣着盗图，绅士皮囊下是罪恶的贪婪。", },
	[152277] = {id=152277, zh_CN="金属扣叩击锁骨时，交叉皮带像骨铐，把力量碾进紧身面料的每道褶皱。", },
	[152278] = {id=152278, zh_CN="月纹隐现如缀星交织，洁净温润。", },
	[152279] = {id=152279, zh_CN="高领妥帖锁住脖颈线条，为窒息舞台留下呼吸的气口。", },
	[152280] = {id=152280, zh_CN="衬衫里藏着让脉搏紊乱的电波，西装下的衬衫如信笺，化作挑战或者心动。", },
	[152281] = {id=152281, zh_CN="三圈皮带绞进紧身裤管，猎物越想解开束缚，越会被勒紧的皮带缝隙里。", },
	[152282] = {id=152282, zh_CN="膝盖处的合金护甲及时收紧释放，使战术动作与机甲机动性完美同步。", },
	[152283] = {id=152283, zh_CN="裤身缠上星环，环扣随步轻响，暗涌不羁。", },
	[152284] = {id=152284, zh_CN="取竹节弧度裁制最清瘦的一截，如竹影映壁，带着竹露清响。", },
	[152285] = {id=152285, zh_CN="醋酸面料如老电影暗场，裤线笔直，裤脚微堆皮鞋。", },
	[152286] = {id=152286, zh_CN="金属链随步摇曳，在舞台光下闪闪发光。", },
	[152287] = {id=152287, zh_CN="裤脚堆叠的褶皱里藏着沙砾，腰带刻着椰子树影，踩过长滩岛的脚印。", },
	[152288] = {id=152288, zh_CN="长裤是拓在光里的窃盗轨迹，影子都在替他保密，消失在转角。", },
	[152289] = {id=152289, zh_CN="两道皮带收束小腿，金属扣咬进皮革的闷响，像给自由盖棺的钉。", },
	[152290] = {id=152290, zh_CN="全金属外骨骼架构，内置微型推进器接口，轻松完成机甲跃迁。", },
	[152291] = {id=152291, zh_CN="步履间碎钻翻涌成银河，靴筒包裹曲线，每一步都踏碎星光。", },
	[152292] = {id=152292, zh_CN="鞋身隐着草茎脉络，鞋尖光晕随步伐明灭。", },
	[152293] = {id=152293, zh_CN="人生第一双正经皮鞋，鞋头微翘的弧度藏着少年的小笨拙。", },
	[152294] = {id=152294, zh_CN="鞋面线条利落如刃，踩着节奏，震碎舞台，体力好似永不会掉线。", },
	[152295] = {id=152295, zh_CN="鞋面打翻的冰沙，划过刚冲过浪的水花，“哒哒”敲出度假鼓点。", },
	[152296] = {id=152296, zh_CN="他从你身边擦过，你闻到的不是皮革味，是宝藏被盗的危险香。", },
	[152297] = {id=152297, zh_CN="颈间一抹，似暗夜散落的星，珠光隐现添柔，钉刺藏锋芒。", },
	[152298] = {id=152298, zh_CN="做旧银链如海岸线潮汐痕，似青苔爬过锁骨。", },
	[152299] = {id=152299, zh_CN="耳尖会泛起微光，它会跟着你的情绪竖耳、贴颅，绷出犬耳的尖锐弧度。", },
	[152300] = {id=152300, zh_CN="皮革手套磨出细碎褶皱，皮面上留下犬爪印暗纹。", },
	[152301] = {id=152301, zh_CN="金属覆手，真正实现机甲即我身的操控革命。", },
	[152302] = {id=152302, zh_CN="金属环缠绕指节，似将星云凝于指端，光影流转间，戴出指间的宇宙感。", },
	[152303] = {id=152303, zh_CN="皮质手套裁出凌厉棱角，每个小动作都带着蛊心魔力。", },
	[152304] = {id=152304, zh_CN="手套是怪盗的无罪契约，隐藏指纹，是他百偷百成的法律。", },
	[152305] = {id=152305, zh_CN="金属栅格锁住唇齿，遗留的惩戒刑具，如今成了最嚣张的装饰。", },
	[152306] = {id=152306, zh_CN="量子数据流化作荧光流转。实时解析战场信息的能力，已经突破人类极限。", },
	[152307] = {id=152307, zh_CN="隐于鬓角的耳返闪着金属，捕捉音节间的激情，连接粉丝与舞台。", },
	[152308] = {id=152308, zh_CN="墨镜下是把阳光嚼碎的椰林滤镜，镜片里晃着他笑出的虎牙。", },
	[152309] = {id=152309, zh_CN="他在月光下现身，面容在眼镜下，梭于城市夜色中，行神秘之事。", },
	[152310] = {id=152310, zh_CN="以声波为形缠绕耳畔，金属弧线藏着律动，随动作轻晃似有旋律流淌。", },
	[152311] = {id=152311, zh_CN="精灵耳尖绽出的细藤，花瓣舒展，顶端坠着被月光吻透的露珠。", },
	[152312] = {id=152312, zh_CN="犬尾末端缠着细链，随动作扫出危险的弧度，如小狗展现着隐秘的情绪。", },
	[152313] = {id=152313, zh_CN="翼甲如展开的未来羽翼，当翼甲展开，就是劈开黑暗的第一缕光。", },
	[152314] = {id=152314, zh_CN="披风上是整片森林在追随你，藤蔓绣成你背后流动的风景。", },
	[152315] = {id=152315, zh_CN="肩头搭的外套，是撞色条纹撞色市集旗帜，好似融入海岛的土著。", },
	[152316] = {id=152316, zh_CN="静谧的月夜潜行，或紧张的对峙时刻，怪盗都能在斗篷的遮掩下化作诡谲黑影。", },
	[152317] = {id=152317, zh_CN="当都市的风掠过发梢，勾勒职场诗意。斜分刘海轻掩眉眼，似藏着都市人未说的故事。", },
	[152318] = {id=152318, zh_CN="如月光凝成的长发，柔顺发丝垂坠间自带仙气，如星夜坠下的精灵。", },
	[152319] = {id=152319, zh_CN="利落束起的短发，发丝弧度藏着随性，公主的温柔似星辰坠落发梢。", },
	[152320] = {id=152320, zh_CN="如春日溪涧畔的草萝，垂坠而下的长发，泛着温润的光泽，似被晨露滋养。", },
	[152321] = {id=152321, zh_CN="长发笔直垂坠，碎发以看似无序，实则是突破常规框架的灵感星火。", },
	[152322] = {id=152322, zh_CN="刘海发丝经过精心打理，垂着自然的弧度，柔婉舒展。", },
	[152323] = {id=152323, zh_CN="长马尾如修理室里晃动的信号带，每一次低头、抬眼，都在辅助捕捉机械细微异常。", },
	[152324] = {id=152324, zh_CN="盘发规整中藏着细腻纹理，缕发丝自然垂落，是拍卖师的随性。", },
	[152325] = {id=152325, zh_CN="如朝阳般灿烂的长发，柔顺丝滑，一侧精心编起的辫子，尽显温婉气质。", },
	[152326] = {id=152326, zh_CN="如阳光亲吻过的长发，柔顺地垂落至腰际，编成双麻花辫。", },
	[152327] = {id=152327, zh_CN="长发如末世荒原上随风摇曳的枯草，发丝凌乱却不失质感。", },
	[152328] = {id=152328, zh_CN="如打翻的马卡龙调色盘，发尾带着挑染，垂落遮住半耳。", },
	[152329] = {id=152329, zh_CN="一头利落的短发，仿若被清晨第一缕阳光亲吻过。", },
	[152330] = {id=152330, zh_CN="俏皮的短发，恰似酸甜的莓果，发梢微微卷曲，展现出青春的朝气与个性。", },
	[152331] = {id=152331, zh_CN="如瀑的长发，仿若被林间晨光驱散了夜的深沉，化作森林中沐浴晨光的小鹿。", },
	[152332] = {id=152332, zh_CN="以东方古典发髻为灵感，发丝如丝缎垂落，自然纹理勾勒温婉轮廓。", },
	[152333] = {id=152333, zh_CN="宽檐帽戴上时，编发藏起俏皮，露出时又像刚从牧场策马归来。", },
	[152334] = {id=152334, zh_CN="利落的剪裁勾勒出潇洒轮廓，浓郁而迷人的短发，在风中肆意舞动。", },
	[152335] = {id=152335, zh_CN="一刀切短发是懒人福音，像刚从慵懒午后睡醒，随意拨弄就能出门。", },
	[152336] = {id=152336, zh_CN="利落短发是狡黠的障眼法，当她侧头，便隐去挪用的小破绽。", },
	[152337] = {id=152337, zh_CN="宽大的帽子，边缘饰以精致的花边，如同樱花花瓣层层叠叠，仿佛是从花园中刚刚采摘而来。", },
	[152338] = {id=152338, zh_CN="漆皮亮面贝雷帽，帽顶缀着银色金属环扣，成为画面的点睛配饰。", },
	[152339] = {id=152339, zh_CN="棒球帽不仅能有效遮挡阳光，还洋溢着如汽水般的清爽感。", },
	[152340] = {id=152340, zh_CN="柔软的帽子，简约的设计搭配微微下弯的帽檐，仿佛在微风中轻轻跃动。", },
	[152341] = {id=152341, zh_CN="精致雕琢的小鹿角，戴上它，仿佛能与自然低语，聆听森林的秘密。", },
	[152342] = {id=152342, zh_CN="蘸了糖霜的牛仔帽，帽型硬挺撑起飒爽气场。", },
	[152343] = {id=152343, zh_CN="高顶礼帽是午夜警戒线的残影，是怪盗的作案徽记，是她的目击者同谋。", },
	[152344] = {id=152344, zh_CN="哑光面料在不动声色间，成为藏在利落穿搭里的性感焦点。", },
	[152345] = {id=152345, zh_CN="短款上衣像截取了暮色中最温柔的那片霭。", },
	[152346] = {id=152346, zh_CN="胸前环形结构，是机械心脏的能量聚点，流转的赛博光茫，似在持续为艺术供给动力。", },
	[152347] = {id=152347, zh_CN="医护风格的机能上衣，交叉绑带是便捷工具挂点，适配扳手操作与故障检测。", },
	[152348] = {id=152348, zh_CN="贴身的短上衣，仿佛是在末世中经历无数次修补与磨砺的痕迹。", },
	[152349] = {id=152349, zh_CN="随着动作衣料折射出流动的金属光泽，宛如将液态霓虹穿在身上。", },
	[152350] = {id=152350, zh_CN="胸口处印有椰子树图案，仿佛让人置身于阳光沙滩的椰风海韵之中。", },
	[152351] = {id=152351, zh_CN="拼色的短款上衣，巧妙地融合了甜美与时尚，心形图案与字母印花，散发着浓浓的少女气息。", },
	[152352] = {id=152352, zh_CN="短上衣恰似森林中最鲜嫩的叶片，清新而充满生机。", },
	[152353] = {id=152353, zh_CN="一字肩露出锁骨，轻盈仿佛刚从夏日气泡水里捞出来的清甜～", },
	[152354] = {id=152354, zh_CN="两侧的立体口袋设计，极具机能风，金属扣在灯光下闪烁着冷冽的光泽，对称分布。", },
	[152355] = {id=152355, zh_CN="衬衫里藏着让脉搏紊乱的电波，西装下的衬衫如信笺，化作挑战或者心动。", },
	[152356] = {id=152356, zh_CN="深浅交织的间色，既有拥抱自然的柔软，又带着闯荡都市的锋芒。", },
	[152357] = {id=152357, zh_CN="短外套采用仿旧的硬皮材质，表面凹凸不平，像是沾染了末世的尘土与硝烟。", },
	[152358] = {id=152358, zh_CN="透明PVC外套在阳光下呈现彩虹般的幻彩效果，穿着时若隐若现透出内搭轮廓。", },
	[152359] = {id=152359, zh_CN="复刻太空舱外骨骼的科技纹理，随时能抵御宇宙辐射的轻量战甲。", },
	[152360] = {id=152360, zh_CN="肩线撑着假象，暗纹绣着盗图，绅士皮囊下是罪恶的贪婪。", },
	[152361] = {id=152361, zh_CN="鱼骨托起初春繁花般的浪漫，裙身如蝶翼舒展，薄纱摆动，如万千蝴蝶振翅。", },
	[152362] = {id=152362, zh_CN="裙身似取了云巅的薄雪，轻柔的纱质层层叠叠，如茶烟袅袅升腾的形态。", },
	[152363] = {id=152363, zh_CN="花瓣装饰错落有致地分布在裙身，仿佛春日里的樱花飘落其上。", },
	[152364] = {id=152364, zh_CN="长裙勾勒干练气场，裙摆像商会长卷在灯光下展开。", },
	[152365] = {id=152365, zh_CN="蓬裙似从花园裁下，蕾丝层叠如蔷薇初绽，行走间裙摆轻晃，是蔷薇在风里自在舒展。", },
	[152366] = {id=152366, zh_CN="玫瑰奶霜如奶油般纯净，袖口与裙摆花边，像刚挤好的果酱在奶霜上晕开。", },
	[152367] = {id=152367, zh_CN="蝴蝶、云纹刺绣游走裙身蔓延，尽显东方女性的明艳与典雅。", },
	[152368] = {id=152368, zh_CN="皮裙是永不落俗的时尚，皮革的光泽在光影里流转，封存了都市霓虹的碎片。", },
	[152369] = {id=152369, zh_CN="不对称剪裁的裙装，走动时像云影流动，是云与雾的创意对话。", },
	[152370] = {id=152370, zh_CN="拼色交织的短裤，裤型利落，走动时布料轻响，是奔赴故障现场的节奏。", },
	[152371] = {id=152371, zh_CN="超短的皮裤裙，磨损的边缘和斑驳的痕迹，诉说着曾经经历过的无数次冒险与战斗。", },
	[152372] = {id=152372, zh_CN="针织材质带来柔软的触感，破洞设计打破单调，那条宽宽的腰带，可以随心将个性挂饰插入插口。", },
	[152373] = {id=152373, zh_CN="机能裤裙多口袋的设计不仅实用，方便放置小物件，腰间目的长条织带，如同赛道上的小旗帜。", },
	[152374] = {id=152374, zh_CN="高腰的裤裙设计，色彩交织碰撞，仿佛夜空中闪烁的天光。", },
	[152375] = {id=152375, zh_CN="轻盈飘逸的裙身，似灵动的鹿尾轻摆，是小鹿在林间穿梭时留下的神秘足迹。", },
	[152376] = {id=152376, zh_CN="阔腿喇叭裤型复刻西部经典，酷飒爽朗。", },
	[152377] = {id=152377, zh_CN="裤身缀上荧光线条，束脚设计利落干练，贴合腿部又方便活动。", },
	[152378] = {id=152378, zh_CN="直筒剪裁藏肉显腿直，卷边设计露出脚踝小心机，舒适又百搭。", },
	[152379] = {id=152379, zh_CN="长裤是拓在光里的窃盗轨迹，影子都在替她保密，消失在转角。", },
	[152380] = {id=152380, zh_CN="硬朗皮革碰撞金属饰边，将未来感与街头风糅合，展露穿戴者的雷厉风行。", },
	[152381] = {id=152381, zh_CN="长筒靴像月光漫过脚踝的温柔轨迹，似踩着星尘前行。", },
	[152382] = {id=152382, zh_CN="与裙摆同调的细跟鞋，细闪如星尘覆面，踩碎夜的静谧，做一只啼血的夜莺。", },
	[152383] = {id=152383, zh_CN="素色的鞋履，简约却不失精致，在轻轻叩响山林的石板路。", },
	[152384] = {id=152384, zh_CN="鞋履化作赛博脉冲驱动的震颤，似能量喷涌的尾焰轨迹。", },
	[152385] = {id=152385, zh_CN="鞋头设计精致小巧，既保证了行走的优雅姿态，又增添了几分少女的俏皮。", },
	[152386] = {id=152386, zh_CN="长靴靴型贴合腿部，让修理师在复杂机械表面行走如履平地。", },
	[152387] = {id=152387, zh_CN="低跟鞋简约却藏巧思，便于快速穿梭拍卖厅与洽谈室，鞋面隐透光泽，似商会印信的边角。", },
	[152388] = {id=152388, zh_CN="缎面高跟鞋，鞋头以细腻刺绣呈现蔷薇轮廓，不张扬却藏着精致。", },
	[152389] = {id=152389, zh_CN="鞋头如巧克力脆壳，带着烘焙房里的甜香，把甜蜜脚印留在每个角落。", },
	[152390] = {id=152390, zh_CN="中筒战靴材质坚固且富有光泽，仿佛是从末世废墟中挖掘出的珍贵材料打造而成。", },
	[152391] = {id=152391, zh_CN="松糕底短靴鞋头圆润可爱，甜中带飒，慵懒十足。", },
	[152392] = {id=152392, zh_CN="简单配色的运动鞋，搭配亮眼的黄色鞋带，为长跑提供了良好的支撑与缓冲。", },
	[152393] = {id=152393, zh_CN="双色拼接的长筒靴，靴筒上闪烁着微小星辰，每一步都仿佛在梦幻中漫步。", },
	[152394] = {id=152394, zh_CN="仿若森林中闪烁的月光，每一步都似在诉说着森林的故事。", },
	[152395] = {id=152395, zh_CN="小羊皮贴合脚型，纤细袢带勾勒脚踝线条，轻踏时似有古韵跫音。", },
	[152396] = {id=152396, zh_CN="农场主少女的鞍靴如马蹄踏响街头，走路带风又藏着少女心。", },
	[152397] = {id=152397, zh_CN="亮眼靴身，单穿靠色彩点亮，突破搭配限制。", },
	[152398] = {id=152398, zh_CN="露出脚踝，从咖啡屋逛到海边，一双鞋承包所有松弛场景～", },
	[152399] = {id=152399, zh_CN="她从你身边擦过，你闻到的不是皮革味，是宝藏被盗的危险香。", },
	[152400] = {id=152400, zh_CN="肌肤与纱质的朦胧交织，呼应蝶翼薄纱的轻盈，若隐若现。", },
	[152401] = {id=152401, zh_CN="宛如能量引擎的装甲外躯，硬朗线条复刻机械臂运动轨迹。", },
	[152402] = {id=152402, zh_CN="长筒袜质地细腻柔软，如同春日里的晨霜般纯净。", },
	[152403] = {id=152403, zh_CN="渔网袜若有若无地覆盖在双腿上，渔网的破洞和磨损之处，更添了几分颓废与不羁。", },
	[152404] = {id=152404, zh_CN="渐变过膝袜从脚踝的深粉过渡到大腿，破洞露出肌肤，气场全开。", },
	[152405] = {id=152405, zh_CN="当光线漫过，耳尖泛起的微光，仿若在林间浮动的碎金。", },
	[152406] = {id=152406, zh_CN="小巧的樱花耳饰，刚飘落的单瓣樱花，花瓣纹理清晰得能摸到春日脉络。", },
	[152407] = {id=152407, zh_CN="金质耳饰在耳畔轻响，如拍卖场暗流竞价声，将灵动与沉稳，融成耳间雅韵。", },
	[152408] = {id=152408, zh_CN="超大银环表面刻意留下的斑驳锈迹、细微划痕，像在废土风沙里滚打过无数回。", },
	[152409] = {id=152409, zh_CN="几何切面亚克力耳坠，随流苏摇曳生姿，折射出璀璨光芒。", },
	[152410] = {id=152410, zh_CN="桃心空心耳饰，金属光泽在耳畔轻轻闪耀，低调却又不容忽视。", },
	[152411] = {id=152411, zh_CN="圆润的耳环，质地温润似玉，凝聚了冬夜的月光。", },
	[152412] = {id=152412, zh_CN="温润檀木雕琢成小巧圆珠，天然纹理藏着岁月沉淀，轻坠耳畔如暗香浮动。", },
	[152413] = {id=152413, zh_CN="若隐若现的臂间细节，金属与布料的拼接，与外套呼应。", },
	[152414] = {id=152414, zh_CN="花苞的边缘微微卷曲，似是在轻诉着不为人知的温柔密语。", },
	[152415] = {id=152415, zh_CN="半透明的纱质臂饰，像清晨山林间弥漫的薄雾，轻柔覆于臂弯，若隐若现。", },
	[152416] = {id=152416, zh_CN="半透明材质裹挟流动光带，手臂舞动时，光带同步闪烁，让腕间成为艺术的舞台。", },
	[152417] = {id=152417, zh_CN="一侧硬朗如机械臂支点，一侧轻量似诊断挂绳，没有冗余装饰，却默默承载修理支点的功能。", },
	[152418] = {id=152418, zh_CN="层叠褶皱的棕金薄纱，纱袖微动，让每一次抬臂都似翻阅无形的商途长卷。", },
	[152419] = {id=152419, zh_CN="弹性腕饰在运动中随着手臂的摆动轻轻晃动，仿佛是跳动的节奏符。", },
	[152420] = {id=152420, zh_CN="绷带不刻意叠整齐，松垮卷成筒状，简单捆扎，自带力量感，穿越风沙。", },
	[152421] = {id=152421, zh_CN="行动终端线条延续舱内设备的科技纹理，像从手臂自然生长出的操作终端。", },
	[152422] = {id=152422, zh_CN="一长一短的随性剪裁，像刚从慵懒午后 随手套上。", },
	[152423] = {id=152423, zh_CN="如云朵覆手，贴合却不紧绷的触感，是第二层肌肤的温柔。", },
	[152424] = {id=152424, zh_CN="举手投足间，似夜蝶振翅的残影，蔷薇绽放指尖。", },
	[152425] = {id=152425, zh_CN="如山林间缠绕的藤蔓，细密贴合手背，随着指尖动作轻晃，像晨露在叶络滚动。", },
	[152426] = {id=152426, zh_CN="手套作为艺术指令的触媒，编舞师的每一次触碰、挥舞，使舞蹈在指尖完成。", },
	[152427] = {id=152427, zh_CN="戴上它扶栏杆、拎裙摆，连触碰空气都带着春日樱町的温柔。", },
	[152428] = {id=152428, zh_CN="束带像输液管，套兼护理的洁净与修理的高效，透出护士般的关怀。", },
	[152429] = {id=152429, zh_CN="手套嵌鎏金纹路，指尖金芒如商印，轻敲拍卖台，将庄重握于掌心。", },
	[152430] = {id=152430, zh_CN="蔷薇花瓣轻裹双手，举手投足间，把花园的细腻温柔晕染开来。", },
	[152431] = {id=152431, zh_CN="手套如揉好的马卡龙面团，指尖的细腻触感，像轻捏一块芝士蛋糕。", },
	[152432] = {id=152432, zh_CN="半掌皮手套仿佛刚从废墟械斗中摘下，、握住的不只是武器，更是在末世活下去的铁血底气。", },
	[152433] = {id=152433, zh_CN="被冬日初雪悄然覆盖的手套，轻轻一挥，就能洒下漫天晶莹。", },
	[152434] = {id=152434, zh_CN="丝绒质地如夜幕般神秘，贴合手掌的剪裁勾勒优雅曲线。", },
	[152435] = {id=152435, zh_CN="短款露指设计保留操作自由，策马握缰的标配。", },
	[152436] = {id=152436, zh_CN="太空手套的防护质感，保留灵活操作空间，随时能抓取宇宙信号。", },
	[152437] = {id=152437, zh_CN="手套是怪盗的无罪契约，隐藏指纹，是她百偷百成的法律。", },
	[152438] = {id=152438, zh_CN="柔羽轻垂于腰际，羽尖若有似无扫过裙摆，转身间羽絮轻晃。", },
	[152439] = {id=152439, zh_CN="以蜻蜓薄翼为灵感，清透如晨露沾湿的蜓翅，薄纱上细碎银芒，是翅脉间闪烁的星尘。", },
	[152440] = {id=152440, zh_CN="层叠的背饰，如飘落花瓣串成的小瀑布，走动时轻轻晃荡，像樱花雨黏在身后。", },
	[152441] = {id=152441, zh_CN="薄纱与金纹交织成流动的长卷，星点闪烁似拍卖场上的瞩目高光。", },
	[152442] = {id=152442, zh_CN="薄纱绣着银线勾勒的薇蔓，如花园微风拂过花架，拖曳出朦胧的浪漫光晕。", },
	[152443] = {id=152443, zh_CN="静谧的月夜潜行，或紧张的对峙时刻，怪盗都能在斗篷的遮掩下化作诡谲黑影。", },
	[152444] = {id=152444, zh_CN="用山林间柔韧的藤条与新抽的嫩叶编织而成的发冠。", },
	[152445] = {id=152445, zh_CN="停驻发间的蝴蝶发饰，金属质地泛着冷冽光泽，将编舞灵感转化为舞蹈信号。", },
	[152446] = {id=152446, zh_CN="以护理为灵感，将诊断师的专注与温柔，悄然佩戴在头顶。", },
	[152447] = {id=152447, zh_CN="以金蛇为型的发饰，硬朗线条，蛇身纹路藏岁月积淀，别在盘发间，似把掌控全局注入底气。", },
	[152448] = {id=152448, zh_CN="淡紫薄纱与蔷薇花枝交织的发饰，像把花园一隅的浪漫顶在发间。", },
	[152449] = {id=152449, zh_CN="女仆帽如刚出炉的云朵蛋糕，帽檐的精致褶皱，似蛋糕上的裱花纹路，与发丝相融。", },
	[152450] = {id=152450, zh_CN="细环如月牙轻卧发间，圆润珍珠似晨露凝萃。", },
	[152451] = {id=152451, zh_CN="简约线条藏着温柔力量，别在发间，为日常添一抹不张扬的清甜。", },
	[152452] = {id=152452, zh_CN="耳侧金属部件如接收宇宙信号的迷你天线。", },
	[152453] = {id=152453, zh_CN="纤细链条勾勒天鹅颈，金属质感与整体酷飒风格呼应，低调却无法忽视。", },
	[152454] = {id=152454, zh_CN="金属冷硬质感，与方形轮廓里藏的柔金光泽碰撞，化作锁住星海的时光挂锁。", },
	[152455] = {id=152455, zh_CN="金属与珍珠碰撞，造型暗合蝶翼轮廓。", },
	[152456] = {id=152456, zh_CN="中心的水滴形坠饰，像花蕾轻轻张开，托着晨露。", },
	[152457] = {id=152457, zh_CN="这条颈饰宛如从神秘花园中采撷的珍宝，吊坠垂坠着栩栩如生的立体蔷薇花。", },
	[152458] = {id=152458, zh_CN="皮质项圈带着粗糙的切割毛边，金属铆钉、尖刺十字，是对抗废土威胁的武装印记。", },
	[152459] = {id=152459, zh_CN="由粗细不一的金属链条交织而成，硬朗的几何形状，带着满满的工业风。", },
	[152460] = {id=152460, zh_CN="颈链搭配心形吊坠，如同一个锁住甜心秘密的钥匙扣。", },
	[152461] = {id=152461, zh_CN="颈间垂坠着造型别致的吊坠，似灵动的水滴，如同冬日里冻结的溪流。", },
	[152462] = {id=152462, zh_CN="镂空项圈环绕颈间，温润玉坠垂于锁骨，恰似东方美人颈间的一抹涟漪。", },
	[152463] = {id=152463, zh_CN="丝巾如西部风沙拂过颈间，如落日余晖，柔化牛仔的硬朗，添一丝浪漫。", },
	[152464] = {id=152464, zh_CN="街头磁场金属冷调碰撞出不羁张力，往脖颈一搭，生人勿近。", },
	[152465] = {id=152465, zh_CN="以暗衬光，溯光而行。浪漫星途里，用半面遮目，换对真相更清晰的凝视。", },
	[152466] = {id=152466, zh_CN="透明镜片方形太阳镜，修饰脸型，仿佛蒙上了一层梦幻的滤镜。", },
	[152467] = {id=152467, zh_CN="他在月光下现身，面容在眼镜下，梭于城市夜色中，行神秘之事。", },
	[152468] = {id=152468, zh_CN="奶油长发如王座上的丝绒帷幕，垂落的弧度在丈量国王史诗。", },
	[152469] = {id=152469, zh_CN="双马尾被染上讥讽色彩，挑染像失控油彩泼溅在发梢。", },
	[152470] = {id=152470, zh_CN="沾上水彩未干时的洇染，发丝蓬成刚揉过的画纸褶皱。", },
	[152471] = {id=152471, zh_CN="发梢坠着乌鸦的羽毛，风轻轻吹动，羽毛悄然无踪。", },
	[152472] = {id=152472, zh_CN="王冠是初代王座的缩小印章，封存着加冕夜的记忆。", },
	[152473] = {id=152473, zh_CN="帽檐轻晃，就能抖落整座城市的无聊。", },
	[152474] = {id=152474, zh_CN="帽檐一压，像画家随手扣在头上的创作工具。", },
	[152475] = {id=152475, zh_CN="衣服裁片像扑克牌，疯谑剧里，错位才是真理。", },
	[152476] = {id=152476, zh_CN="基础衬衫偏要绣透明领结，给规规矩矩系上半透明天使结。", },
	[152477] = {id=152477, zh_CN="针织马甲是撕下来的调色盘色块，卡通贴布像随手画的涂鸦签。", },
	[152478] = {id=152478, zh_CN="治愈的春日花纹，让毛衣越穿越暖，像被春天拥在怀里～", },
	[152479] = {id=152479, zh_CN="绸缎裁作暗夜穹顶 ，星芒是陨石划过的轨迹，珍珠垂坠如星屑坠落的慢镜头。", },
	[152480] = {id=152480, zh_CN="不对称裙摆纹刻着战斗魔法阵，花纹是魔法暴动的轨迹。", },
	[152481] = {id=152481, zh_CN="短裤裁出毛边疯癫，像拒绝被长裙框住的野生叛逆。", },
	[152482] = {id=152482, zh_CN="格子裙故意裁短，裙摆缀毛边像被颜料刷蹭过。", },
	[152483] = {id=152483, zh_CN="裙边如错题本的活页纸，记录着坠落春天的草稿。", },
	[152484] = {id=152484, zh_CN="以珍珠链绞缠在踝间，以足尖叩响王座的野心。", },
	[152485] = {id=152485, zh_CN="她的脚印是谑剧的标点 ，这双鞋，专走对称世界不敢踩的童话歧路。", },
	[152486] = {id=152486, zh_CN="一只裹毛绒袜像未拆封的颜料棉，一只露皮带环像拧开的金属罐。", },
	[152487] = {id=152487, zh_CN="不对称纹路让循规蹈矩在鞋底碾成碎片，偏要走出独一份的嚣张步调。", },
	[152488] = {id=152488, zh_CN="小皮鞋是丢掉烦恼的小邮差，舒适又可爱，留下的脚印留下花瓣印章。", },
	[152489] = {id=152489, zh_CN="菱形缠绕脚踝，塑成甜酷糖壳，晃荡间露出聚光。", },
	[152490] = {id=152490, zh_CN="单腿漫笼薄纱雾，漏与藏的博弈里，光影在腿侧洇开破格温柔。", },
	[152491] = {id=152491, zh_CN="袜筒是樱花奶霜的分层，袜口小花边留着没化完的糖霜。", },
	[152492] = {id=152492, zh_CN="薄纱绣成剪影，成为剪影的人，能看见星轨流动的秘密。", },
	[152493] = {id=152493, zh_CN="半透纱故意撕成碎片，又重新缝补，露出的皮肤散发着诡异的魅力。", },
	[152494] = {id=152494, zh_CN="蝉翼纱袖笼住小臂，臂环圈住清透，像偷捕雾与夜的私语。", },
	[152495] = {id=152495, zh_CN="斗篷将剧院沉闷的空气抖成哥特幕布，欢笑蔓延在幕布之上。", },
	[152496] = {id=152496, zh_CN="它静静环于腕间，承载着古老仪式的威严，是权力与传承的无声见证。", },
	[152497] = {id=152497, zh_CN="来自小丑剧院的奇妙馈赠，仿佛能听见剧场里的哄笑与惊呼声。", },
	[152498] = {id=152498, zh_CN="凿刻着透光的纹路被磨薄的金箔，像神话里未写完的符咒。", },
	[152499] = {id=152499, zh_CN="棱形铆钉像魔法钉，将剧本固定进掌心。", },
	[152500] = {id=152500, zh_CN="发间的星芒，是王冠漏下的王权碎光，故意让威严泄成发丝间的温柔。", },
	[152501] = {id=152501, zh_CN="小恶魔角藏着讨糖鬼的甜牙印，煽动翼膜向过往的路人讨债。", },
	[152502] = {id=152502, zh_CN="细框眼镜是缩小的画框，镜片藏着观察世界的狡黠。", },
	[152503] = {id=152503, zh_CN="两圈皮环咬住纱雾，腿侧褶皱漾开叛逆浪。", },
	[152504] = {id=152504, zh_CN="链条绞着陨石 ，把王座的威严硬坠在颈间。", },
	[152505] = {id=152505, zh_CN="熔铸的枷锁刻满竖纹，是束缚巫女魔力的安全封印。", },
	[152506] = {id=152506, zh_CN="雏菊别针挂在针织胸口，扣住了衣领，将春日的清新种入锁骨边。", },
	[152507] = {id=152507, zh_CN="椭圆小包像挤扁的颜料软管，里面装着画笔也装着逃课去写生的勇气。", },
	[152508] = {id=152508, zh_CN="当你蹲下身照料野花，口袋里的草莓蜜饯顺着风滚出来。", },
	[152509] = {id=152509, zh_CN="发间的草莓碰了会簌簌抖落甜香，引路过的风精灵追着打转。", },
	[152510] = {id=152510, zh_CN="百年老苔晒干的绒毛，流苏盈盈，浸染晨间的露霜，缀在裙前。", },
	[152511] = {id=152511, zh_CN="丝绦如常春藤生长，双辫勾勒出少女的青涩。", },
	[152512] = {id=152512, zh_CN="鞋面是老橡树脱落的树皮鞣制的，鞋扣藏着草莓果核磨的印章。", },
	[152513] = {id=152513, zh_CN="袜套是三叶草编的捕梦网，草籽落在柏油路上，长出草苔。", },
	[152514] = {id=152514, zh_CN="毛衣上野莓在陶罐发酵三天，飘出去年深秋的甜气。", },
	[152515] = {id=152515, zh_CN="森圃中围裙在劳作中跃动，菇种在辛勤照料下缓缓破壳。", },
	[152516] = {id=152516, zh_CN="百年野藤第一次开花时，藤蔓自己打成的绳结。", },
	[152517] = {id=152517, zh_CN="裤管纹路是树桩年轮拓印，悄悄将孢子埋进树根。", },
	[152518] = {id=152518, zh_CN="深秋落叶堆积的温度，脚踝蹭过腐叶时，吸收无尽能量。", },
	[152519] = {id=152519, zh_CN="靴面是蘑菇菌柄的釉色，鞋底凹槽卡着新鲜苔藓。", },
	[152520] = {id=152520, zh_CN="被森林晨露吻过的碎发，风掠过发梢时，会抖落肉眼难见的生命种子。", },
	[152521] = {id=152521, zh_CN="巨大蘑菇帽是森林母亲的生命预兆，亦是毒物危险的警告。", },
	[152522] = {id=152522, zh_CN="在都市光晕里，职业装与皮裙碰撞出刚柔并济的火花，成为穿梭钢筋丛林的个性宣言。", },
	[152523] = {id=152523, zh_CN="把银河碎片缝进衣褶，从星海汲取灵感，这是一场穿梭量子的旅程。", },
	[152524] = {id=152524, zh_CN="当星芒坠入午夜，化身月下蝶，于都市窗畔，演绎一场花与蝶的交际舞。", },
	[152525] = {id=152525, zh_CN="缀满叶脉纹路如藏秘境，恍若踏入林间，仙气与生机交织，自带草木清香。", },
	[152526] = {id=152526, zh_CN="衣摆裁出弧度，点缀荧光线条，是破械重生的蝴蝶。", },
	[152527] = {id=152527, zh_CN="当樱花攀上帽檐，裙摆轻晃过石板路，这是贵族的出行札记。", },
	[152528] = {id=152528, zh_CN="化身移动维修站，专业中藏着对机械的温柔守护。", },
	[152529] = {id=152529, zh_CN="商会荣光织入衣间，尽显沉稳气场，举手投足皆带星辉。", },
	[152530] = {id=152530, zh_CN="似将花园春色裹进裙摆。层叠纱摆如花瓣绽放，步步皆是浪漫剪影。", },
	[152531] = {id=152531, zh_CN="围裙绣糖霜纹路，裙摆裁成蛋糕层叠状，穿上变成香甜小蛋糕。", },
	[152532] = {id=152532, zh_CN="似从荒漠废墟拾起，属于踏过烬土的流浪者，自带粗粝野性与苍凉感。", },
	[152533] = {id=152533, zh_CN="打破常规材质边界，构建出超现实的未来镜像，行走间似穿梭时空。", },
	[152534] = {id=152534, zh_CN="活力如捕捉的阳光，跃动的青春，追着风的向日葵，满是蓬勃与轻盈。", },
	[152535] = {id=152535, zh_CN="懵懂的青春，甜里藏点小锋芒，是会撒娇的酷女孩没错了。", },
	[152536] = {id=152536, zh_CN="头顶鹿角，似从林间走来，像会眨眼的林间小鹿。", },
	[152537] = {id=152537, zh_CN="旗袍露出玉色肌肤，缓缓踏步，从东方绮梦中走出。", },
	[152538] = {id=152538, zh_CN="把沙漠落日的浪漫，融入沙上晚霞里，把甜酷牛仔玩出新花样。", },
	[152539] = {id=152539, zh_CN="荧光纹路似星际航标，裹着月光，成为待命的星际卫士。", },
	[152540] = {id=152540, zh_CN="日常出街、咖啡探店，随手一穿就是自带松弛滤镜的时尚模板。", },
	[152541] = {id=152541, zh_CN="怪盗在昼与夜的夹缝里，与你望她呼吸停滞的瞬间偷取宝物。", },
	[152542] = {id=152542, zh_CN="如罗兰花绽放的双层蝴蝶结，不只是装饰，更是一枚绅士徽章。", },
	[152543] = {id=152543, zh_CN="铜制小锅炉的烟囱便冒出缕缕炊烟，喵的锅炉永远为你燃起余温。", },
	[152544] = {id=152544, zh_CN="当月光漫过舞会的窗棂，这顶凝固的蜡烛便成了时间的画布，记录下舞会中旋转的光影。", },
	[152545] = {id=152545, zh_CN="它踩过南瓜灯的光晕，翅膀在墙上投下影子，喵~小心黑夜中的魅惑小恶魔。", },
	[152546] = {id=152546, zh_CN="当围裙系在毛茸茸的胸前，沾上甜腻糖霜，这是让美味发酵的魔法套装。", },
	[152547] = {id=152547, zh_CN="当围裙系在毛茸茸的胸前，飘起热带果香，这是让美味发酵的魔法套装。", },
	[152548] = {id=152548, zh_CN="当围裙系在毛茸茸的胸前，蒸上绵密芋泥，这是让美味发酵的魔法套装。", },
	[152549] = {id=152549, zh_CN="布料染上松针的清香，每道纹路都是未写完的档案，记录着隐匿林间的秘密。", },
	[152550] = {id=152550, zh_CN="转动时星环如流星划过，八角星芒刻印着的运算公式，给生命套上可触摸的法则。", },
	[152551] = {id=152551, zh_CN="中心的冰晶雪花是凝固的起点，在旋转中裂出锋芒，守着静止的温柔。", },
	[152552] = {id=152552, zh_CN="仙人掌的拟人形态，不用担心它的尖刺，啾啾弹弹的，一点不扎人。", },
	[152553] = {id=152553, zh_CN="山楂的拟人形态，酸滋滋的味道时刻刺激味觉，看见它就要流口水了。", },
	[152554] = {id=152554, zh_CN="芝士的拟人形态，随时会滴落在地的芝士流心，让它很苦恼。", },
	[152555] = {id=152555, zh_CN="灯笼椒的拟人形态。原型是灯笼甜椒，不要看它是辣椒，其实很甜哦。", },
	[152556] = {id=152556, zh_CN="穿这套衣服去踏春，像踩在一片长满四叶草的春日原野。", },
	[152557] = {id=152557, zh_CN="仙人掌的花叶顺着手臂蜷成环，是藏在荒漠里的羁绊。", },
	[152558] = {id=152558, zh_CN="规整针织校服裹住书卷气，裙摆下洇出的几分跳脱，打破严谨的校园风。", },
	[152559] = {id=152559, zh_CN="穿在身上是只胖乎乎的圆筒，短绒长得乱糟糟，像刚从洗衣机里捞出来的小迷糊。", },
	[152560] = {id=152560, zh_CN="裙摆的草莓图案与架上的真草莓相映成趣，踩过草梗时带起细碎的叶，在田垄间稳稳扎根。", },
	[152561] = {id=152561, zh_CN="裙装的极光在寒风中飘动，写下裹着极光行走的雪境诗篇。", },
	[152562] = {id=152562, zh_CN="整个暖阳冬日的寒风都缝进了绒毛翻飞的温柔里。", },
	[152563] = {id=152563, zh_CN="如装满芝士的零食袋，挂件蹭过立领的轻响，像撕开芝士包装的微脆声。", },
	[152564] = {id=152564, zh_CN="连帽卫衣吸饱了阳光的温度，短裤卷起风的形状，穿上就想往公园的草坪里钻。", },
	[152565] = {id=152565, zh_CN="线条利落如未来轨迹，穿在身上，每一步都像在践行未来的环保约定。", },
	[152566] = {id=152566, zh_CN="裙摆尖角裁得笔直，裙身布满方块暗纹，走动时像一副被打乱的牌在旋转。", },
	[152567] = {id=152567, zh_CN="蝴蝶结在兜帽披风光影里明明灭灭，像蝴蝶从云霞中掠过。", },
	[152568] = {id=152568, zh_CN="这是一本望不尽的林间手记，翻开一页，写满林叶与虫踪的故事。", },
	[152569] = {id=152569, zh_CN="腿环与颈圈同频轻晃，像老留声机里转出的旋律，是流淌在身上的复古诗。", },
	[152570] = {id=152570, zh_CN="裙角与海风共舞，是手握船舵时的飒爽，也是倚着栏杆啃苹果时的甜。", },
	[152571] = {id=152571, zh_CN="锋利线条勾勒的机甲，锐角边缘泛着寒光，光刃出鞘快如残影。", },
	[152572] = {id=152572, zh_CN="疾影机甲的黑曜涂装，迅捷与锋利藏进暗影，只待出击时亮出致命的光。", },
	[152573] = {id=152573, zh_CN="疾影机甲的炽焰涂装，泛着燃烧般的亮橙，隐现余烬燃尽的炙热。", },
	[152574] = {id=152574, zh_CN="会剪下的初冬攒住的背毛，染上喜欢的颜色，织成独属于自己的气味斗篷。", },
	[152575] = {id=152575, zh_CN="水镜和卡住尾巴的泳圈是每只幼鲨必备的夏日两件套。", },
	[152576] = {id=152576, zh_CN="裙摆晃荡时，天地要给精灵王国的威严让出朝拜的生路。", },
	[152577] = {id=152577, zh_CN="这是哥特小丑的癫狂舞台，准备好，看她演一场永不谢幕的谑剧。", },
	[152578] = {id=152578, zh_CN="把调色盘撞色穿成校服，让画笔笔触漫上发梢，在乖乖校园风里涂上未干的颜料。", },
	[152579] = {id=152579, zh_CN="在月光与霓虹的夹缝，可爱的萝莉是掌握暗夜魔法的见习巫女。", },
	[152580] = {id=152580, zh_CN="在樱花漫进自习室的午后，毛绒裙化作行走的春日错题本。", },
	[152581] = {id=152581, zh_CN="苔色浸染长裙垂落，林鬓双辫跃动，步履过处皆是青痕。", },
	[152582] = {id=152582, zh_CN="当蘑菇伞接住第一滴晨露，让荒芜处重新长满会发光的童话。", },
	[152583] = {id=152583, zh_CN="在霓虹锈蚀的地下秩序里，束缚是雕刻身体的刀。", },
	[152584] = {id=152584, zh_CN="机械灵魂挣脱躯壳的武装宣言，在实验中碾碎理性无情的偏见。", },
	[152585] = {id=152585, zh_CN="这是一套在宇宙巡演的演舞服，解构宇宙，闪亮在光影的舞台。", },
	[152586] = {id=152586, zh_CN="以月光为线、草叶为墨，昼夜流转间，聆听花叶与星子的絮语。", },
	[152587] = {id=152587, zh_CN="衬衫滤过云隙的光，裤角卷着溪涧的风，是他走过走廊的课间十分钟。", },
	[152588] = {id=152588, zh_CN="冷锋扫过的速写，用色彩的碰撞，画出风卷落的细雪。", },
	[152589] = {id=152589, zh_CN="信笺被晒旧的边缘，被岁月洇湿的告白，从发缝间漏出半行。", },
	[152590] = {id=152590, zh_CN="当追光灯绞碎黑暗，玫瑰攀着金属挑衅沉闷，撕开平庸夜幕。", },
	[152591] = {id=152591, zh_CN="衬衫滤过普吉岛的风，卷着海岛的沙，与邂逅邀约下一次落日。", },
	[152592] = {id=152592, zh_CN="怪盗在昼与夜的夹缝里，与你望她呼吸停滞的瞬间偷取宝物。", },
	[152593] = {id=152593, zh_CN="光点如萤火的蝶翼，如琉璃般晶莹，半透明银白肌肤，嵌着岁月锻造的霜白鳞片。", },
	[152594] = {id=152594, zh_CN="头顶如桃花般的羽冠，绯霞般燃烧的云羽，穿梭于繁花之间，是自然的精灵。", },
