	[152629] = {id=152629, zh_CN="编织紧致的天然藤蔓手环，带着森林的清香。", },
	[152630] = {id=152630, zh_CN="蓬松柔软的白色小球，适合放在手心把玩。", },
	[152631] = {id=152631, zh_CN="造型典雅的复古烛台，点燃后摇曳的微光，能照亮归家者的前路。", },
	[152632] = {id=152632, zh_CN="满满一袋酥脆瓜子，是闲暇时光聊天的最佳伴侣。", },
	[152633] = {id=152633, zh_CN="极具科技感的设计，精密交错的线条，是机械生命的最爱。", },
	[152634] = {id=152634, zh_CN="用永不凋谢的藤木雕琢而成的花簇，寓意着永远不褪色的深厚情谊。", },
	[152635] = {id=152635, zh_CN="选用上好的新鲜肉排用秘方酱汁腌制整夜，每一口都饱含浓郁的香气与回甘。", },
	[152636] = {id=152636, zh_CN="缩刻在盆中的精致水景，波光粼粼间，仿佛能听见远处溪流的低语。", },
	[152637] = {id=152637, zh_CN="低级通用礼物物品描述文本。", },
	[152638] = {id=152638, zh_CN="岁月洗礼后的神秘饰品，斑驳纹理诉说着往昔故事。", },
	[152639] = {id=152639, zh_CN="结实耐用的特制抓板，能释放活泼的天性。", },
	[152640] = {id=152640, zh_CN="晶莹剔透的多面棱镜，在阳光下折射出绚丽的彩虹七色。", },
	[152641] = {id=152641, zh_CN="中级食味族礼物物品描述文本。", },
	[152642] = {id=152642, zh_CN="中级机械生命礼物物品描述文本。", },
	[152643] = {id=152643, zh_CN="纯手工缝制的羊绒毯子，紧实保暖，能在疲惫时提供最温柔的怀抱。", },
	[152644] = {id=152644, zh_CN="镶嵌圆润珍珠的纯银头饰，在月光下闪耀微芒。", },
	[152645] = {id=152645, zh_CN="外皮焦糖化呈琥珀色，泛着蜂蜜般的光泽，果肉软糯，散发温暖清甜的果香。", },
	[152646] = {id=152646, zh_CN="中级通用礼物物品描述文本。", },
	[152647] = {id=152647, zh_CN="选料讲究的精致挂饰，处处透着考究的工艺，象征着尊贵身份。", },
	[152648] = {id=152648, zh_CN="轻轻一转便能变幻出万千星辰，是送给好奇心与童心的小小世界。", },
	[152649] = {id=152649, zh_CN="晶体内部嵌着星空般的闪粉，摇晃时如银河倾倒，充满神秘色彩。", },
	[152650] = {id=152650, zh_CN="高级食味族礼物物品描述文本。", },
	[152651] = {id=152651, zh_CN="能够回应情感的陪伴玩偶，温暖的触感能驱散孤独，给予贴心守护。", },
	[152652] = {id=152652, zh_CN="用森林古树枝条编成的头饰，生机勃勃，代表着大自然的祝福。", },
	[152653] = {id=152653, zh_CN="盛放宝物的精致托盘，镶嵌各色宝石，华丽夺目。", },
	[152654] = {id=152654, zh_CN="装满宝石颗粒的沙漏，看流光溢彩缓缓坠落，记录下珍贵时刻。", },
	[152655] = {id=152655, zh_CN="高级通用礼物物品描述文本。", },
