	[152680] = {id=152680, zh_CN="伊甸园的苹果", },
	[152681] = {id=152681, zh_CN="伊甸园的苹果？", },
	[152682] = {id=152682, zh_CN="一枚泛着柔和金光的果实，散发着令人心安的暖意。传说中，能抵达伊甸园的灵魂才可摘下此果。食用后，对方将感受到你全部的记忆、善意与真诚，所有隔阂化为虚无。", },
	[152683] = {id=152683, zh_CN="外表与真品无异，却透着一丝无法言说的诡异。它源自那场古老的背叛——当信任被利用，禁果便成了诅咒的容器。咬下的瞬间，共享的不是温暖，而是深藏的冷漠与算计。", },
	[152684] = {id=152684, zh_CN="蟹黄堡", },
	[152685] = {id=152685, zh_CN="海霸棒", },
	[152689] = {id=152689, zh_CN="可能有很多人都以为蟹黄堡里有蟹黄，其实那是翻译过来的一个错误。蟹黄堡的英译中译名为大钳蟹馅饼——它是一种素食汉堡", },
	[152690] = {id=152690, zh_CN="桡足纲浮游动物制作的一种食物，以极差的口感著称，几乎无人愿意食用", },
