	[152862] = {id=152862, zh_CN="皇帝的新织布梭", },
	[152863] = {id=152863, zh_CN="诅咒纺锤", },
	[152864] = {id=152864, zh_CN="木制匕首", },
	[152865] = {id=152865, zh_CN="破旧摄像机", },
	[152866] = {id=152866, zh_CN="泛黄乐谱", },
	[152867] = {id=152867, zh_CN="残破项链", },
	[152868] = {id=152868, },
	[152870] = {id=152870, zh_CN="铁木雕刻而成的精致工艺品，线条流畅质感厚重。", },
	[152871] = {id=152871, zh_CN="远古的生命凝固在透明树脂中，极具收藏价值。", },
	[152872] = {id=152872, zh_CN="发条旋转间流出清脆旋律，能让浮躁的心安静下来。", },
	[152873] = {id=152873, zh_CN="手工揉捏的小小玩偶，虽然造型质朴，却藏着送礼者满满的诚意。", },
	[152874] = {id=152874, zh_CN="礼品描述占位结实朴素的防护用具，做工简单，但能提供实效的保护。", },
	[152875] = {id=152875, zh_CN="冷硬铁料锻造成的娇艳花朵，适合送给坚毅不屈的人。", },
	[152876] = {id=152876, zh_CN="如棉花糖般轻盈，抱住它，就拥有了一整晚的安稳美梦。", },
	[152877] = {id=152877, zh_CN="蓝色的细砂缓缓滑落，能让人在忙碌中放慢节奏。", },
	[152878] = {id=152878, zh_CN="铃声清冽动听，随风摇曳间，洗涤旅途中的疲惫。", },
	[152879] = {id=152879, zh_CN="散发静谧蓝光的小巧夜灯，陪伴对方度过每一晚。", },
	[152880] = {id=152880, zh_CN="显微镜下的精密机械结构，齿轮啮合间尽显逻辑之美。", },
	[152881] = {id=152881, zh_CN="外形小巧的复杂装置，流动的光晕展露出它的超强算力。", },
	[152882] = {id=152882, zh_CN="如同烈日般的金属冠冕，金光熠熠，散发着自信与威严。", },
	[152883] = {id=152883, zh_CN="模拟星轨运行的小型机械，足不出户便能看遍银河。", },
	[152884] = {id=152884, zh_CN="传说能看透时光的神秘沙漏，寓意不平凡的邂逅。", },
	[152885] = {id=152885, zh_CN="散发淡淡幽香的半透明树脂，触感温润。", },
	[152886] = {id=152886, zh_CN="机械驱动的金属蝴蝶，是科技与艺术的完美结合。", },
	[152887] = {id=152887, zh_CN="充满复古气息的精密刻度盘，仿佛能计算流年的深度。", },
	[152888] = {id=152888, zh_CN="开启时会溢出如水月光，适合存放那些无法言说的小秘密。", },
	[152889] = {id=152889, zh_CN="在狭小玻璃瓶中自成的小世界，绿意盎然，蕴含着生生不息的奥秘。", },
	[152890] = {id=152890, zh_CN="刻有繁复金边花纹的精密表具，滴答声中，见证每一个相守的瞬间。", },
	[152901] = {id=152901, zh_CN="向玩家打招呼", },
	[152902] = {id=152902, zh_CN="靠近伙伴时，伙伴向玩家打招", },
	[152903] = {id=152903, zh_CN="伙伴说话", },
	[152904] = {id=152904, zh_CN="伙伴会偶尔与玩家说话", },
	[152905] = {id=152905, zh_CN="怎么创建社团？", },
	[152906] = {id=152906, zh_CN="怎么制作食物？", },
	[152907] = {id=152907, zh_CN="怎么制作服饰？", },
	[152908] = {id=152908, zh_CN="怎么加入社团", },
	[152909] = {id=152909, zh_CN="在社团可以做什么？", },
	[152910] = {id=152910, zh_CN="名称已被使用，请重新输入。", },
	[152911] = {id=152911, zh_CN="功能暂未解锁，请先完成委托—片场指南解锁。", },
	[152912] = {id=152912, zh_CN="功能暂未解锁，请先完成【开放制片厂】任务解锁。", },
	[152913] = {id=152913, zh_CN="技能暂未解锁，请完成新手任务解锁。", },

	[153001] = {id=153001,zh_CN="%FriendPaluName",},

	[160001] = {id=160001, zh_CN="是说书人呀……虽然没办法享受游戏的胜负\n但这可是位拥有上帝视角，足以左右战局的角色！", },
	[160002] = {id=160002, zh_CN="想好要帮助哪一方赢得胜利了吗？\n可不要太偏心影响他人的游戏体验哦。", },
	[160003] = {id=160003, zh_CN="诶，失语者？只要自己被投票淘汰就可以了吗？\n我说你这个角色好有趣！", },
	[160004] = {id=160004, zh_CN="居然不需要做任务，反而只需要让自己被淘汰就行了？\n不过我还是要提醒你啊白天也要小心坏人哦！", },
	[160005] = {id=160005, zh_CN="%playerrname，真羡慕你啊，在黑夜中你居然是绝对安全的……\n这难道就是黑夜的庇护吗？", },
	[160006] = {id=160006, zh_CN="真可惜，只能在会议时淘汰他人，\n要是在白天也能就好了，对吧？", },
	[160007] = {id=160007, zh_CN="既然淘汰的恶魔越多就可以越快胜利，\n那就把他们作为首选目标好了，快快快！", },
	[160008] = {id=160008, zh_CN="赏金猎人啊……\n准备好寻找并淘汰我们的赏金目标了吗？", },
	[160009] = {id=160009, zh_CN="最快只需要淘汰三个人就能赢了\n这可比超市大酬宾还划算啊！", },
	[160010] = {id=160010, zh_CN="参与人数越多，需求胜利的赏金目标也会越多的话\n数字什么的就别管了！准备好领取胜利的赏金了吗？", },
	[160011] = {id=160011, zh_CN="放轻松\n这个身份能保护你免受夜晚时来自他人的伤害。", },
	[160012] = {id=160012, zh_CN="对我们而言，淘汰全部人！\n是胜利的唯一途径！", },
	[160013] = {id=160013, zh_CN="记得在夜晚会议时使用技能哦，\n我们可以轻松复制他人的技能！", },
	[160014] = {id=160014, zh_CN="做好准备了吗。一旦复制的对象被淘汰……\n就轮到我们继承那家伙的胜利条件了。", },
	[160015] = {id=160015, zh_CN="僧侣？一个很厉害的保护型角色呢。\n谨慎分析，在夜晚保护一位可怜人吧", },
	[160016] = {id=160016, zh_CN="好有意思的身份啊……\n能够得知离自己最近两位玩家的身份！虽然不知道具体的是谁……", },
	[160017] = {id=160017, zh_CN="哨兵……在白天淘汰你的家伙会立刻自动报告。\n该如何运用好这个身份和能力呢……", },
	[160018] = {id=160018, zh_CN="只要在会议中就可以使用技能挖掘被淘汰者的身份……\n小心一点活到会议上吧。", },
	[160019] = {id=160019, zh_CN="有怀疑的对象吗？是占卜师的话\n可以在晚上选择嫌疑人，查看那家伙有没有对别人用过技能哦。", },
	[160020] = {id=160020, zh_CN="让我看看……士兵……白天可以抵挡驱逐同时在晚上得知此事\n晚上也免疫攻击技能与驱逐……你这职业也太强了吧！", },
	[160021] = {id=160021, zh_CN="让我来看看你能否一次就审判正确吧\n把【恶魔】们都揪出来！", },
	[160022] = {id=160022, zh_CN="这可是个带刀好人的角色唉。\n在夜晚会议可以选择淘汰一个家伙，但千万别选中村民啊！", },
	[160023] = {id=160023, zh_CN="我现在宣布，你是最棒的侦探！\n每晚都能够随机得知一个还存活着的身份，这可是很强大的力量啊！", },
	[160024] = {id=160024, zh_CN="哦，每晚都能得知一条别人知道的消息……\n有些像是传说中的狗仔队？", },
	[160025] = {id=160025, zh_CN="只要在晚上使用技能进入梦游状态，\n被淘汰时，淘汰目标就会变成你身边的两位，真好玩！", },
	[160026] = {id=160026, zh_CN="一定要好好利用上天给你的\n不受到侵蚀和药剂影响的特权啊！", },
	[160027] = {id=160027, zh_CN="白天能看见谁正在遭受负面状态的攻击，晚上也能得知被淘汰的相关信息……\n这简直就是神一般的角色啊！", },
	[160028] = {id=160028, zh_CN="居然是警长先生么！淘汰掉坏人是你的职责呢！\n不过选错了的话……你是不是就不能当警察了？", },
	[160029] = {id=160029, zh_CN="我们只有一次机会……当我们被投票放逐之时\n选择一个家伙，让那家伙陪我们一起下地狱吧！", },
	[160030] = {id=160030, zh_CN="只要所有存活的家伙都被使用过煽动技能就算胜利……\n一定要小心接近他人啊。", },
	[160031] = {id=160031, zh_CN="这样一来……你是不是就可以猜测他们的身份\n然后淘汰他们啦？这才是隐秘客的作风！", },
	[160032] = {id=160032, zh_CN="别害怕，他们都会以为你是【村民】的\n！不如来玩躲猫猫，怎么样！", },
	[160033] = {id=160033, zh_CN="淘汰对方后，可以让对方的身体变为无形哦\n我们就能偷偷转移了！", },
	[160034] = {id=160034, zh_CN="淘汰对方的话，我们可以快点离开\n别人来到身体附近后就会立刻报告的！这就是……陷害吧？！", },
	[160035] = {id=160035, zh_CN="加油啊！每淘汰一位村民你就能得知他知道的全部信息\n这当然是……多多益善啦！对吧？", },
	[160036] = {id=160036, zh_CN="这个角色我喜欢！可以把淘汰的人变成你的侍从！\n还无法用技能反抗你！", },
	[160037] = {id=160037, zh_CN="可以转化他人变为己方阵营……\n我们得选择些厉害的家伙来增加胜率啊。", },
	[160038] = {id=160038, zh_CN="没关系\n要随时做好当上领主的准备啊！", },
	[160039] = {id=160039, zh_CN="这难道就是传说中的一箭双雕吗？\n晚上被你神奇咒语诅咒的两个人，只要有一人被淘汰，另外一人也难以幸免。", },
	[160040] = {id=160040, zh_CN="白天虽然无法攻击，但是我们可以在晚上干活\n让他们的技能失效对情报的干扰还挺有作用的！", },
	[160041] = {id=160041, zh_CN="工作台？这可真是天助我也！", },
	[160042] = {id=160042, zh_CN="去前面看看！我仿佛看到了胜利的光芒！", },
	[160043] = {id=160043, zh_CN="嘿！前面似乎有新的发现，看看去！", },
	[160044] = {id=160044, zh_CN="一味的前进可不行！\n去工作台那里看看能不能获得什么收获吧！", },
	[160045] = {id=160045, zh_CN="喂喂喂，一味的防守可不行啊，我们偶尔也要学会反击。", },
	[160046] = {id=160046, zh_CN="虽然是一个人的队伍，有了它，可就不是一个人在战斗了！", },
	[160047] = {id=160047, zh_CN="工作台？在这附近找找看，肯定能收获些什么！", },
	[160048] = {id=160048, zh_CN="要不要利用一些道具？肯定很有趣！", },
	[160049] = {id=160049, zh_CN="无论结果怎样，先发现工作台可就是我抢占了先机！", },
	[160050] = {id=160050, zh_CN="走！去那边找点乐子！说不定还有意外的收获。", },
	[160051] = {id=160051, zh_CN="那些家伙肯定会来这！我们在这里守株待兔怎么样！", },
	[160052] = {id=160052, zh_CN="别以为有了工作台就能赢我！可别太小看我们！", },
	[160053] = {id=160053, zh_CN="武器吗？正好！我们也需要一把新的呢。", },
	[160054] = {id=160054, zh_CN="看看这里还有别的道具吗？", },
	[160055] = {id=160055, zh_CN="我们也需要一把新的武器才行……\n可不能被那些家伙拿到反击的机会啊！", },
	[160056] = {id=160056, zh_CN="有了它，它就是我最趁手的武器！", },
	[160057] = {id=160057, zh_CN="别小看了它，虽然简单，可刀才是最好的武器呢！", },
	[160058] = {id=160058, zh_CN="不愧是刚打制的新刀，真漂亮！", },
	[160059] = {id=160059, zh_CN="让我想想看，有了刀……我能做些什么呢。", },
	[160060] = {id=160060, zh_CN="喂！可千万不能小看这最不引人注目的武器啊！", },
	[160061] = {id=160061, zh_CN="哇塞，这么大？这可不符合”坏人“的做派啊！", },
	[160062] = {id=160062, zh_CN="这样一来，我们就更不用担心啦！\n难道你还不相信我吗，这简直就是如鱼得水！", },
	[160063] = {id=160063, zh_CN="我相信，这么完美的武器\n一定只有在我们手上才能最大的发挥作用。", },
	[160064] = {id=160064, zh_CN="失去了一些伙伴啊……不过，可别因此沮丧啊。", },
	[160065] = {id=160065, zh_CN="小小的劣势而已，我相信你能轻松力挽狂澜。", },
	[160066] = {id=160066, zh_CN="仅凭这点挫折，可不能让我们放弃。", },
	[160067] = {id=160067, zh_CN="机会还很多……我们一定能找到他们的破绽的。", },
	[160068] = {id=160068, zh_CN="这个人数……别心急，我们得找找机会。", },
	[160069] = {id=160069, zh_CN="事情变得有意思起来了，除了白天外\n我们也得注意晚上的会议情况了。", },
	[160070] = {id=160070, zh_CN="出了点小意外，看来还得更努力才行。", },
	[160071] = {id=160071, zh_CN="千万别灰心啊，我们一起想想办法\n俗话说的好，“破局之道就在其中”嘛！", },
	[160072] = {id=160072, zh_CN="这就是传说中的绝命时刻了……\n我们不能辜负逝者的期待。", },
	[160073] = {id=160073, zh_CN="看来我们拖不得了\n使出全力破局吧。", },
	[160074] = {id=160074, zh_CN="看来老话说的没错\n果然绝地翻盘才是最激动人心的时刻啊！", },
	[160075] = {id=160075, zh_CN="人数还很多，得想想办法继续控制人数。", },
	[160076] = {id=160076, zh_CN="还有这么多人……\n我们距离胜利还有一大段路要走呢。", },
	[160077] = {id=160077, zh_CN="也许我们得考虑一下村民和恶魔阵营的平衡了。", },
	[160078] = {id=160078, zh_CN="好多人啊……或许单靠我们自己的力量是不行的！", },
	[160079] = {id=160079, zh_CN="哦~这个人数比很不错嘛\n特别适合我们浑水摸鱼，不是吗？", },
	[160080] = {id=160080, zh_CN="我感觉还是不够，我们想赢的话，还需要再降低点人数。", },
	[160081] = {id=160081, zh_CN="就是现在，我们发挥实力的时候到了！", },
	[160082] = {id=160082, zh_CN="一切都在按照预想中的发展啊……", },
	[160083] = {id=160083, zh_CN="别担心。你看，现在局面不是好起来了吗？\n在保证自己不被投出去的同时，先观察一下局面吧！", },
	[160084] = {id=160084, zh_CN="他们还没发现我们？这下我们的胜算就大了。", },
	[160085] = {id=160085, zh_CN="呜呼！是时候进行最佳中立的表演了！", },
	[160086] = {id=160086, zh_CN="他们或许再也无法利用阵营人数的优势把我们投出去了！\n对吧？", },
	[160087] = {id=160087, zh_CN="目标越来越少了……就是现在！尝试出手改变局面吧！", },
	[160088] = {id=160088, zh_CN="现在，我们就不需要隐藏实力了！", },
	[160089] = {id=160089, zh_CN="别紧张，对局才刚刚开始，一切不是正在朝着有利的方向发展着吗\n？", },
	[160090] = {id=160090, zh_CN="适应得还挺快的嘛……\n我等着你带飞！", },
	[160091] = {id=160091, zh_CN="这对于我来说，也算是一个不小的收获！", },
	[160092] = {id=160092, zh_CN="进度加快了！看来你很擅长玩这种游戏嘛！", },
	[160093] = {id=160093, zh_CN="嘿！\n你有没有发现，游戏真是越来越有趣了？", },
	[160094] = {id=160094, zh_CN="加油啊，我们可是要全力保持住目前稳步前进的节奏啊！", },
	[160095] = {id=160095, zh_CN="呜呼！我好像预见了胜利，\n你呢？", },
	[160096] = {id=160096, zh_CN="天才的拍档！这简直赢得轻轻松松！", },
	[160097] = {id=160097, zh_CN="没有难度，我就说你可以！", },
	[160098] = {id=160098, zh_CN="只差最后一点了，再加加油我们就能赢了！\n简直就是易如反掌啊哈哈哈哈哈！", },
	[160099] = {id=160099, zh_CN="怎么样？有适应这个规则吗。", },
	[160100] = {id=160100, zh_CN="遇到困难就告诉我！我来看看能不能帮上什么忙！", },
	[160101] = {id=160101, zh_CN="再坚持一下！事情在朝着越来越好的方向发展了！", },
	[160102] = {id=160102, zh_CN="你看，我就说吧，任务完成得越来越顺利啦！", },
	[160103] = {id=160103, zh_CN="累了吗？我们在这里偷偷摸鱼应该不会被发现吧……", },
	[160104] = {id=160104, zh_CN="我刚才偷偷看了看，我们的进度比好多人都快！\n你真的太厉害了！", },
	[160105] = {id=160105, zh_CN="好！还剩最后一些，就能全部完成！", },
	[160106] = {id=160106, zh_CN="原来我有点小看你了！\n居然这么快就能解决！", },
	[160107] = {id=160107, zh_CN="千万别松劲啊……拿出你的全部实力！\n我们来完成这最后一点！", },
	[160108] = {id=160108, zh_CN="任务？这是什么新的手段吗……", },
	[160109] = {id=160109, zh_CN="先别急，看看这个任务究竟有什么作用……", },
	[160110] = {id=160110, zh_CN="这些任务居然被他们完成得越来越多了啊\n看来我们也应该采取一些行动才行。", },
	[160111] = {id=160111, zh_CN="我明白了……他们想要通过这些任务来取胜的话\n我相信你一定有办法！", },
	[160112] = {id=160112, zh_CN="看来情况有些紧急了呀\n或许我们应该看看【恶魔】们做了什么。", },
	[160113] = {id=160113, zh_CN="情况不妙了我们必须加快脚步才能取胜。", },
	[160114] = {id=160114, zh_CN="别急，有你在，我相信我们一定还有办法可以扳倒他们！", },
	[160115] = {id=160115, zh_CN="原来的路子行不通啊……\n必须想想有没有什么别的办法可以阻止他们完成这些。", },
	[160116] = {id=160116, zh_CN="这样的进度太慢了\n我们也找点乐子去。", },
	[160117] = {id=160117, zh_CN="行动的时间还很充裕，不如我们先去看看周围的情况怎么样？", },
	[160118] = {id=160118, zh_CN="暂时还没关系的继续保持原有的节奏就好\n现在局面还没有发生什么太大的变化。", },
	[160119] = {id=160119, zh_CN="虽然完成任务也是取胜的好办法\n但是这也为我们提供了一条新的思路不是吗？", },
	[160120] = {id=160120, zh_CN="情况越来越棘手了，可不能让他们继续这样下去。", },
	[160121] = {id=160121, zh_CN="振作起来\n这个进度还没有到完全无法挽回的程度嘛……\n我们一起想想办法！", },
	[160122] = {id=160122, zh_CN="【村民】们已经完成这么多了吗……\n我们也要展示真正的实力了！", },
	[160123] = {id=160123, zh_CN="保持冷静\n我们一定还有别的方法可以取胜。", },
	[160124] = {id=160124, zh_CN="我果然没有看错，我就说一定能做到！", },
	[160125] = {id=160125, zh_CN="对于我们来说，简直就是轻轻松松！", },
	[160126] = {id=160126, zh_CN="你看那是什么？\n像不像……胜利在向我们招手！", },
	[160127] = {id=160127, zh_CN="有时候果然还是得相信，人多力量大啊！", },
	[160128] = {id=160128, zh_CN="等到下次，我们一定要扳回一局！", },
	[160129] = {id=160129, zh_CN="怎么会这样……看来要有针对性地研究一下了……", },
	[160130] = {id=160130, zh_CN="可千万别气馁啊\n看到那个更强大的自己了么，这就是下一次的胜利。", },
	[160131] = {id=160131, zh_CN="无需多虑，按照你自己的想法\n试着引导战局的走向吧。", },
	[160132] = {id=160132, zh_CN="可以试试偶尔说说假话\n无妨，让对局变得有意思起来！", },
	[160133] = {id=160133, zh_CN="你可以帮助任何人，也可以误导任何人\n亲爱的，这全凭你自己的喜好。", },
	[160134] = {id=160134, zh_CN="正义的、邪恶的，都与你无关\n如何让自己安全的被投出去才是最重要的。", },
	[160135] = {id=160135, zh_CN="记住，不是活下来，是努力让自己被投出去。", },
	[160136] = {id=160136, zh_CN="千万别记错了规则，违背秩序的失语者，让自己被淘汰你就赢了。", },
	[160137] = {id=160137, zh_CN="是在找目标吗？我们可只能在黑夜里淘汰对手哦，现在是白天~", },
	[160138] = {id=160138, zh_CN="在白天，我们可以找找其他人的位置\n辨明他们的身份以便我们更好在晚上大展拳脚。", },
	[160139] = {id=160139, zh_CN="无需为即将到来的黑夜感到恐惧，你在夜里是无敌的。", },
	[160140] = {id=160140, zh_CN="赏金目标可不会送上门来\n快行动起来吧！", },
	[160141] = {id=160141, zh_CN="别发呆了，保持移动！", },
	[160142] = {id=160142, zh_CN="在寻找赏金目标吗？跟着指引就能快速找到了。", },
	[160143] = {id=160143, zh_CN="大胆地动手嘛~反正在晚上除了投票淘汰外\n没有其他能伤害你的手段。", },
	[160144] = {id=160144, zh_CN="在想怎么伪装吗？淘汰他人的时候别被发现就好了。", },
	[160145] = {id=160145, zh_CN="想要尽快取得胜利吗？那就记住你的使命，淘汰掉所有人！", },
	[160146] = {id=160146, zh_CN="在挑选复制的对象吗？\n是得谨慎一点，毕竟只有一次机会。", },
	[160147] = {id=160147, zh_CN="复制完后就该想想怎么让他在会议中被淘汰了\n~被复制的目标只要在会议中被淘汰就是咱们的胜利了。", },
	[160148] = {id=160148, zh_CN="喂喂喂，可别让其他人抢先淘汰了你的目标啊，不然就只能你来代替他完成他的获胜条件了。", },
	[160149] = {id=160149, zh_CN="别发呆了，我们的优先目标还是完成任务~", },
	[160150] = {id=160150, zh_CN="如果利用技能在晚上保护他人\n确实是需要好好思考的，但我们应该尽快开始做任务了。", },
	[160151] = {id=160151, zh_CN="晚上释放技能时要好好挑选对象\n别挑到了邪恶阵营的玩家。", },
	[160152] = {id=160152, zh_CN="如果已经知道部分身份信息的话\n就在完成任务的途中求证一下吧。", },
	[160153] = {id=160153, zh_CN="不管知道的身份是什么，我们不应该就此止步\n行动起来，寻找更多线索吧。", },
	[160154] = {id=160154, zh_CN="有些迷茫了？不要担心\n只要到了夜晚我们可以随机得知两侧玩家的身份，那时再做决定吧。", },
	[160155] = {id=160155, zh_CN="呃……站着当诱饵，没问题吗？\n我们还是先去做做任务吧？", },
	[160156] = {id=160156, zh_CN="在这里待着，恶魔也未必会来啦，动起来动起来~", },
	[160157] = {id=160157, zh_CN="虽然白天你可以这么肆无忌惮，但晚上咱们可得小心了。", },
	[160158] = {id=160158, zh_CN="老实说，别为逝者哀悼了，快点行动起来做做任务吧。", },
	[160159] = {id=160159, zh_CN="我真不想在夜晚动用我们的能力……\n因为这意味着有人被淘汰了。", },
	[160160] = {id=160160, zh_CN="老发呆也不是个办法，实在不行\n我们去找找被淘汰的家伙？", },
	[160161] = {id=160161, zh_CN="有什么怀疑的对象吗？\n技能只有在夜晚会议时才能使用，我们先去做做任务吧？", },
	[160162] = {id=160162, zh_CN="做任务的时候说不定还能撞见一些嫌疑人呢\n别呆这儿了！", },
	[160163] = {id=160163, zh_CN="有怀疑的对象的话，不妨在夜晚里对他用用技能吧\n或许能查出些什么来。", },
	[160164] = {id=160164, zh_CN="你未免也太嚣张了吧……\n尽管每一个白天可以免疫一次伤害\n但要是有第二次那可就危险了！", },
	[160165] = {id=160165, zh_CN="只有进了夜晚会议时才知道自己是否被驱逐过\n所以保险起见，尽快动起来做做任务吧！", },
	[160166] = {id=160166, zh_CN="别害怕啦，每个白天你可以免疫一次伤害\n在晚上也不会被技能所淘汰哦！", },
	[160167] = {id=160167, zh_CN="站在这里可没办法帮助我们找到恶魔，行动起来吧。", },
	[160168] = {id=160168, zh_CN="我们的技能很关键，可以在晚上直接淘汰一个恶魔\n白天还是得快点动起来排一下他人的身份吧", },
	[160169] = {id=160169, zh_CN="如果审判的对象不是恶魔，我们会因此失去技能的……\n慎重起见，还是快点找找线索吧。", },
	[160170] = {id=160170, zh_CN="我们的技能一局之中只能在夜晚中释放一次，如果选中了村民\n被驱逐的可是我们自己，别发呆了，找找线索吧！", },
	[160171] = {id=160171, zh_CN="我们技能的伤害性和负面效果都不弱……\n为了保险起见，先做做任务推动一下进度吧。", },
	[160172] = {id=160172, zh_CN="别站着不动啦，我们的主场在夜晚\n在白天里还是得保持移动和完成任务才行。", },
	[160173] = {id=160173, zh_CN="避开怀疑的对象，抓紧完成任务吧，别发呆了。", },
	[160174] = {id=160174, zh_CN="夜晚里得知的信息是随机的……\n所以我们得依靠自己的智慧排除身份，得出最终结论\n去找找线索吧！", },
	[160175] = {id=160175, zh_CN="无论怎么样\n原地不动，可是最危险的行为啊！", },
	[160176] = {id=160176, zh_CN="哦？是在编辑小报吗？快点动起来！\n除非你想被恶魔抓到淘汰！", },
	[160177] = {id=160177, zh_CN="白天的情况，我想，我们还是以做任务为优先吧\n只要任务进度达到100%，我们就胜利了！", },
	[160178] = {id=160178, zh_CN="夜晚的时候你将能够随机得知一条其他人刚得知的信息\n好好利用起来吧。", },
	[160179] = {id=160179, zh_CN="喂喂喂！\n现在可是白天，还不是做梦的时候！\n该去做任务了！", },
	[160180] = {id=160180, zh_CN="醒醒，我们的技能只能在夜晚使用\n现在是白天！", },
	[160181] = {id=160181, zh_CN="害怕被攻击的话，不如在夜晚试试利用一下一直困扰你的梦游\n把你受到的伤害转嫁给相邻的人吧！", },
	[160182] = {id=160182, zh_CN="还在，祈祷吗？该停下来了\n打败恶魔的最好方式是投票和做任务！", },
	[160183] = {id=160183, zh_CN="在白天，我们能看出来其他玩家是否有受到技能效果的影响\n这样可以更好确定恶魔！行动起来吧~", },
	[160184] = {id=160184, zh_CN="虽然说侵蚀和药剂效果对你是无效的\n但直接的伤害还是有效的，别站着发呆了！", },
	[160185] = {id=160185, zh_CN="如果有玩家被淘汰，在夜晚时我们可以随机得知一条他知道的消息\n这就意味着，我们得活到夜晚！\n快动起来别被抓到了。", },
	[160186] = {id=160186, zh_CN="嘿，警长大人，上班时间到了，别发呆了。", },
	[160187] = {id=160187, zh_CN="快去找找可疑的家伙，确定的话就给那家伙一枪吧！\n不过得小心，如果那家伙的身份是村民\n那倒霉的就是我们自己了……", },
	[160188] = {id=160188, zh_CN="一旦技能对象是村民，我们就会被淘汰\n得多找找线索以更好确定坏人，快走吧！", },
	[160189] = {id=160189, zh_CN="被投票出局时，发动技能淘汰掉坏人。\n别担心，你这把善良的枪是淘汰不了好人的。", },
	[160190] = {id=160190, zh_CN="你可以选择勤勤恳恳的完成属于你的任务\n当然，也可以选择解决掉所有会给你带来问题的人。", },
	[160191] = {id=160191, zh_CN="精明的猎人可以准确的选择目标\n别摸鱼划水了，去寻找目标吧。", },
	[160192] = {id=160192, zh_CN="嘿，我们的敌人可是全场\n你还在发呆呢？！", },
	[160193] = {id=160193, zh_CN="演说家可不会等待观众到来\n我们该去寻找听众了。", },
	[160194] = {id=160194, zh_CN="只要煽动所有活着的人，我们就胜利了\n还在等什么呢？", },
	[160195] = {id=160195, zh_CN="猜错身份，可是我们倒霉，还站着干嘛？\n得去找找其他人的身份线索了！", },
	[160196] = {id=160196, zh_CN="我们可只能在夜晚会议中发动技能\n至少现在得动起来，别被其他人怀疑了。", },
	[160197] = {id=160197, zh_CN="是在思考怎么获胜吗？\n只是站着的话，是没办法分析出其他人的身份的哦。", },
	[160198] = {id=160198, zh_CN="……\n虽然伪人的身份能让所有人把你当做村民\n可你不会以为自己也是村民了吧？", },
	[160199] = {id=160199, zh_CN="发呆无用！得去找到目标了。", },
	[160200] = {id=160200, zh_CN="没什么好担心的，你的身份谁看都是村民\n~只要淘汰人的时候不要被发现就好了，我们走吧。", },
	[160201] = {id=160201, zh_CN="我们好歹也是专业的，别杵着发呆行不！\n快去淘汰几个家伙吧。", },
	[160202] = {id=160202, zh_CN="在挑选猎物还是在挑选合适的场地？\n挑好了就快行动吧，机不可失时不再来！", },
	[160203] = {id=160203, zh_CN="被我们淘汰的家伙，别人靠近后会自动报告\n抓住这一点扭转局势吧！", },
	[160204] = {id=160204, zh_CN="别把那些所谓的“胜利”放在眼里\n恶之花就开在你心里。", },
	[160205] = {id=160205, zh_CN="把所有伪善的村民都淘汰吧！\n这样你就赢了！", },
	[160206] = {id=160206, zh_CN="想要得知更多的信息吗？\n淘汰他，这样他的全部信息都归你了！", },
	[160207] = {id=160207, zh_CN="在挑选侍从吗？别站着不动了\n我的大领主，好的侍从都在做任务呢。", },
	[160208] = {id=160208, zh_CN="老是发呆的话，会很容易被怀疑的\n快点动起来吧！", },
	[160209] = {id=160209, zh_CN="你和其他人不一样！\n被你淘汰的第一个人会被转化成你的侍从\n利用这点削弱其他阵营吧！", },
	[160210] = {id=160210, zh_CN="哎呀，既然变成了侍从\n咱们就只能努力了！", },
	[160211] = {id=160211, zh_CN="熬走那位害你失去技能的领主吧\n坚持一下，说不定你就是下一位！", },
	[160212] = {id=160212, zh_CN="别因为无法出击而灰心啊\n试试帮助同阵营的人取得胜利吧。", },
	[160213] = {id=160213, zh_CN="就算是给白雪公主吃苹果的女巫\n她也会去主动找公主，别发呆啦。", },
	[160214] = {id=160214, zh_CN="如何利用自己一箭双雕的诅咒技能与队友协作是很重要的\n会议时好好商量商量吧！", },
	[160215] = {id=160215, zh_CN="喜欢一箭双雕吗？挑选两位幸运儿，在晚上诅咒他们！\n一旦有人被驱逐，另一人也难逃。", },
	[160216] = {id=160216, zh_CN="有找到合适的技能使用对象吗？\n没有的话，咱们换个地方吧？", },
	[160217] = {id=160217, zh_CN="一直站着不动，是很容易被怀疑的啦！\n咱们去看看其他人的位置吧~", },
	[160218] = {id=160218, zh_CN="虽然白天无法发动攻击就气馁啊！\n但在夜晚，咱们可以利用投毒使他们的技能失效！\n这可是很强力的！", },
	[160219] = {id=160219, zh_CN="完成所有任务并非胜利的唯一方式\n找到隐藏在其中的坏人把他们都投出去或许效率更高。", },
	[160220] = {id=160220, zh_CN="如果我们能找到工作台就好了\n在那里放置伙伴制作各种特殊道具\n说不定能让对局变得有意思起来。", },
	[160221] = {id=160221, zh_CN="不是只有恶魔才能淘汰他人，千万要记住了。", },
	[160222] = {id=160222, zh_CN="耳听为虚，但眼见的未必为实\n获取更多信息排除错误答案吧~", },
	[160223] = {id=160223, zh_CN="失语者的胜利条件是把他投票出去\n如果对局里存在这个角色，投票时一定要小心再小心！", },
	[160224] = {id=160224, zh_CN="尽量避免与一直跟随自己的家伙接触\n很有可能是恶魔或者革命家。", },
	[160225] = {id=160225, zh_CN="会议中是允许说谎的\n先保证自己活下去才能想更远的事。", },
	[160226] = {id=160226, zh_CN="不仅要小心【恶魔】啊\n人群中藏着的【中立】者也许更需要注意。", },
	[160227] = {id=160227, zh_CN="不要太轻易相信相信任何人\n保护好自己才是首位！", },
	[160228] = {id=160228, zh_CN="小心身边可能出现的【伪人】\n就算被探查到他也会显示成令你信任的【村民】模样。", },
	[160229] = {id=160229, zh_CN="除了淘汰掉所有人\n完成任务也是【村民】取胜的重要方式\n要注意留意周围的动静。", },
	[160230] = {id=160230, zh_CN="如果我们能找到工作台就好了\n在那里放置伙伴制作各种特殊道具\n说不定能让对局变得有意思起来。", },
	[160231] = {id=160231, zh_CN="不是只有恶魔才能淘汰他人，千万要记住了！", },
	[160232] = {id=160232, zh_CN="耳听为虚，但眼见的未必为实\n获取更多信息排除错误答案吧~", },
	[160233] = {id=160233, zh_CN="失语者的胜利条件是把他投票出去\n如果对局里存在这个角色，投票时一定要小心再小心！", },
	[160234] = {id=160234, zh_CN="尽量避免与一直跟随自己的家伙接触\n很有可能是恶魔或者革命家。", },
	[160235] = {id=160235, zh_CN="会议中是允许说谎的\n先保证自己活下去才能想更远的事。", },
	[160236] = {id=160236, zh_CN="如果觉得势单力薄难以取胜的话，不如试着找找同样身份的人。\n虽然不能达成同盟，不过可以试着利用他。", },
	[160237] = {id=160237, zh_CN="利用好自己的能力\n可以一个一个的慢慢淘汰他们。", },
	[160238] = {id=160238, zh_CN="记住，【中立】是一个身份，不是一个阵营\n你只有靠自己才能取胜，无法和别人达成同盟。", },
	[160239] = {id=160239, zh_CN="除了淘汰所有非己方阵营角色之外\n每个【恶魔】都有自己独特的技能，可以试试这条路。", },
	[160240] = {id=160240, zh_CN="请留意工作台，那里将可以打造对【村民】有利的道具\n或许我们也可以利用它完成一些计划。", },
	[160241] = {id=160241, zh_CN="不是只有恶魔才能淘汰他人\n千万要记住了，自己的安全也很重要。", },
	[160242] = {id=160242, zh_CN="耳听为虚，但眼见的未必为实\n获取更多信息排除错误答案吧~", },
	[160243] = {id=160243, zh_CN="失语者的胜利条件是把他投票出去\n如果对局里存在这个角色\n投票时一定要小心再小心！", },
	[160244] = {id=160244, zh_CN="如果有不太明确的下手目标，可以试试先跟着他~", },
	[160245] = {id=160245, zh_CN="会议中是允许说谎的\n先保证自己活下去才能想更远的事。", },
	[160246] = {id=160246, zh_CN="别担心，找到与自己相同阵营的【恶魔】商量行动\n可以对于获胜有着事半功倍的效果。", },
	[160247] = {id=160247, zh_CN="利用好自己的能力\n可以一个一个的慢慢淘汰他们。", },
	[160248] = {id=160248, zh_CN="会议是村民能够淘汰我们的重要手段\n但我们也可以反过来利用会议淘汰他们。", },
	[160249] = {id=160249, zh_CN="走吧，解决下一个。", },
	[160250] = {id=160250, zh_CN="品尝胜利的喜悦后，也要记得擦拭刀尖的血。", },
	[160251] = {id=160251, zh_CN="听到了吗？不甘的怨念。", },
	[160252] = {id=160252, zh_CN="做得好，完美的捕猎。", },
	[160253] = {id=160253, zh_CN="无需顾虑，我会与你一同将障碍扫清。", },
	[160254] = {id=160254, zh_CN="应有的果决，神像自会给他/她安息。", },
	[160255] = {id=160255, zh_CN="握紧你的武器，这份力量只属于你。", },
	[160256] = {id=160256, zh_CN="手下留情不是属于你的赞美词，但所幸，你所向披靡。", },
	[160257] = {id=160257, zh_CN="镰刀之下的果实往往更加鲜美多汁。", },
	[160258] = {id=160258, zh_CN="破败的玩具，不值得怜惜。", },
