	[160762] = {id=160762, zh_CN="雨夜1_1触发点", },
	[160763] = {id=160763, zh_CN="怎么办啊……怎么办啊……", },
	[160764] = {id=160764, zh_CN="触发点1_2", },
	[160765] = {id=160765, zh_CN="画\n一阶段个人任务", },
	[160766] = {id=160766, zh_CN="发卡“黛比”", },
	[160767] = {id=160767, zh_CN="画的感谢", },
	[160768] = {id=160768, zh_CN="【夜的命名术】诗歌集", },
	[160769] = {id=160769, zh_CN="【画的本子】", },
	[160770] = {id=160770, zh_CN="触发点2_1", },
	[160771] = {id=160771, zh_CN="退出将会提前结算", },
	[160772] = {id=160772, zh_CN="超时未选择曲目", },
	[160773] = {id=160773, zh_CN="对方中止了邀舞", },
	[160774] = {id=160774, zh_CN="对方拒绝了邀舞", },
	[160775] = {id=160775, zh_CN="你方一落脚，空间站就下起了雨，阴湿的风卷着斜雨，四处都是雾蒙蒙的雨幕，什么都难以看清。", },
	[160776] = {id=160776, zh_CN="雨夜，绝对的经典，至少所有的鬼故事都是从这个时间开始高潮的。", },
	[160777] = {id=160777, zh_CN="你不敢停留也再难离开，生怕走动一步就会脚下一滑被风雨带下平台去。", },
	[160778] = {id=160778, zh_CN="张不开翅膀和淋漓的雨天，如果冒出什么看得见抓不着的东西可就在劫难逃了。", },
	[160779] = {id=160779, zh_CN="你开始想到恶魔与魔鬼，他们会蛊惑着你一步步后退去，再“一不小心”脚下一滑跌入无尽的深渊。", },
	[160780] = {id=160780, zh_CN="第二天空间站的伙伴们就会看到你浮肿的身体和惊恐的神情，以一个扭曲的姿势倒在平台上。", },
	[160781] = {id=160781, zh_CN="“怎么办啊……怎么办啊……”（白色漂浮字体由远及近，伴随角色语音）", },
	[160782] = {id=160782, zh_CN="什么声音？！", },
	[160783] = {id=160783, zh_CN="探索任务：循着神秘的声音前进，看清究竟是什么东西。（向字体飘来方向前进）", },
	[160784] = {id=160784, zh_CN="老天啊，这是什么任务。", },
	[160785] = {id=160785, zh_CN="你心底一定这么咒骂着策划，但你必须看清那是什么。", },
	[160786] = {id=160786, zh_CN="不是吗，主角？", },
	[160787] = {id=160787, zh_CN="有人吗", },
	[160788] = {id=160788, zh_CN="经典的台词，熟悉的配方，惊人的胆识。", },
	[160789] = {id=160789, zh_CN="现在，你成为了一个更加称职的主角。", },
	[160790] = {id=160790, zh_CN="前进", },
	[160791] = {id=160791, zh_CN="你勇敢前进。", },
	[160792] = {id=160792, zh_CN="（向字体飘来方向前进）", },
	[160793] = {id=160793, zh_CN="而在雨幕里，你竟真的看到一个身影飘了过去。", },
	[160794] = {id=160794, zh_CN="哀怨着，彷徨着，彳亍着……", },
	[160795] = {id=160795, zh_CN="没有油纸伞，却有着梦一般的凄婉迷茫。", },
	[160796] = {id=160796, zh_CN="突然，这个丁香一样结着愁怨的姑娘看向了你。", },
	[160797] = {id=160797, zh_CN="此刻，你有两个选择，<color=#ff3333>撒腿就跑</color>或者<color=#33ffff>缓缓后退</color>，又或者你也可以选择<color=#ff0000>冲上去给她来一下</color>。", },
	[160798] = {id=160798, zh_CN="撒腿就跑", },
	[160799] = {id=160799, zh_CN="你尖叫逃离撒腿就跑，身后却传来一声更加惊恐的尖叫。", },
	[160800] = {id=160800, zh_CN="你拼命逃跑，却不想中了所有鬼故事的老套路，雨中滑腻的地板让你平地摔了一跤。", },
	[160801] = {id=160801, zh_CN="你趴在地上转过头，眼睁睁看着那个哀怨的身影从雨幕里缓缓走出。", },
	[160802] = {id=160802, zh_CN="缓缓后退", },
	[160803] = {id=160803, zh_CN="多年的旅行经验告诉你决不能把后背留给敌人", },
	[160804] = {id=160804, zh_CN="你正面她缓缓后退，却不想腿软得一批，你颤颤巍巍地后退，看着她从雨幕里缓缓走出。", },
	[160805] = {id=160805, zh_CN="真正的勇士敢于直面恐惧", },
	[160806] = {id=160806, zh_CN="而你，我的朋友，你是真正的勇士！", },
	[160807] = {id=160807, zh_CN="作为绝对的无神论者，你朝着这个诡异的身影毅然决然地冲了过去。", },
	[160808] = {id=160808, zh_CN="下一秒，那个身影爆发出一声刺耳的尖叫。", },
	[160809] = {id=160809, zh_CN="随着身影逐渐清晰，你惊奇地发现这位姑娘竟然是画！", },
	[160810] = {id=160810, zh_CN="画看起来已经淋了很久的雨，浑身都湿透了", },
	[160811] = {id=160811, zh_CN="你询问她发生了什么事", },
	[160812] = {id=160812, zh_CN="她说自己最心爱的发卡“黛比”丢了，怎么都找不到，甚至怀疑是被雨水冲刷走掉到下面去了。", },
	[160813] = {id=160813, zh_CN="她越说越伤心，捂脸哭了起来", },
	[160814] = {id=160814, zh_CN="你急忙答应下来帮她寻找。", },
	[160815] = {id=160815, zh_CN="攻略任务：画", },
	[160816] = {id=160816, zh_CN="循着神秘的声音前进，看清究竟是什么东西。", },
	[160817] = {id=160817, zh_CN="循着神秘的声音前进，看清究竟是什么东西。（向字体飘来方向前进）", },
