	[160900] = {id=160900, zh_CN="梅在梅园前请朋友们吃梅子，路过的你也被塞了一个。路过的你也被塞了一个，靠近梅园前的人群（有梅、可洛、画等伙伴）后触发", },
	[160901] = {id=160901, zh_CN="获得了梅子道具。", },
	[160902] = {id=160902, zh_CN="任务结束", },
	[160903] = {id=160903, zh_CN="不知道梅遇上什么事了，梅看上去十分着急", },
	[160904] = {id=160904, zh_CN="你与梅园前的梅对话。得知梅的苦恼。你回到工坊制造栅栏后，交付给梅园的破损处。", },
	[160905] = {id=160905, zh_CN="她感到开心，你获得了喜悦种子，她发现梅子被老鼠偷吃了，感到很生气，获得怒种子。你回到梅旁边与梅对话。获得奖励。", },
	[160906] = {id=160906, zh_CN="修好了吗？谢谢你！", },
	[160907] = {id=160907, zh_CN="你再次来到梅园后触发。你发现梅正在与老鼠们对峙。在你的斡旋下，老鼠们答应你以后不再破坏围墙偷吃梅子。只要你带来足够的食物喂饱他们。", },
	[160908] = {id=160908, zh_CN="询问发生了什么", },
	[160909] = {id=160909, zh_CN="你来到了梅园门口，发现梅正在和老鼠对峙", },
	[160910] = {id=160910, zh_CN="大胆老鼠！你可知罪！", },
	[160911] = {id=160911, zh_CN="够了吗？！", },
	[160912] = {id=160912, zh_CN="终于结束了", },
	[160913] = {id=160913, zh_CN="老鼠终于离开了", },
	[160914] = {id=160914, zh_CN="不用谢！先看过一段时间它们还会不会再来吧", },
	[160915] = {id=160915, zh_CN="老鼠们果真食言了，他们又一次破坏了梅的梅园，于是梅打算召集所有朋友保卫梅园。在你的帮助下很快就达成了。", },
	[160916] = {id=160916, zh_CN="你与梅园前的梅对话后。展示再次多处破损的围栏。（动画）梅与你对话，让你帮忙召集伙伴", },
	[160917] = {id=160917, zh_CN="能不能帮我找一找我的朋友们，我们一起把老鼠赶跑", },
	[160918] = {id=160918, zh_CN="你去餐厅与可洛谈话。", },
	[160919] = {id=160919, zh_CN="你去社群空间站与画谈话。", },
	[160920] = {id=160920, zh_CN="你去花草茶店与甜霜熊谈话。", },
	[160921] = {id=160921, zh_CN="你回到梅园，伙伴们与梅都在梅园边上。你与梅谈话后，梅和伙伴一人堵住一个口子（动画），但是还缺一个缺口没有人拦住。", },
	[160922] = {id=160922, zh_CN="你前往缺口。老鼠们正准备从缺口处离开。（动画或文案）你变形成合适的物体，在缺口处判定。", },
	[160923] = {id=160923, zh_CN="最终你通过变形功能，变成一个能堵住出口的适合的物体，成功拦住了想要逃跑的老鼠。", },
	[160924] = {id=160924, zh_CN="最终老鼠被梅一网打尽，你们成功守护了梅园", },
