	[161003] = {id=161003, zh_CN="我发现你了！", },
	[161004] = {id=161004, zh_CN="你被抓到了！", },
	[161005] = {id=161005, zh_CN="墨瞳day1", },
	[161006] = {id=161006, zh_CN="墨瞳在房间里踱步，碎碎念。她的房间门没有关紧，你偶然看到了，她连忙紧张兮兮地关上了房门。如果你愿意在外头多等待一会儿，她的背诵声又会响起。", },
	[161007] = {id=161007, zh_CN="和墨瞳对话", },
	[161008] = {id=161008, zh_CN="墨瞳正在碎碎念。", },
	[161009] = {id=161009, zh_CN="墨瞳给了你种子。", },
	[161010] = {id=161010, zh_CN="你在星劫月影的地图里发现了甜霜熊和甜品车。由于甜品车抛锚卡住需要你的帮助", },
	[161011] = {id=161011, zh_CN="与甜霜熊对话", },
	[161012] = {id=161012, zh_CN="你成功将甜品车从坑洼里解救出来，但是甜品车仍然受损导致无法继续前行。", },
	[161013] = {id=161013, zh_CN="甜品车坏了，我不能把甜品送过去，你能不能帮我个忙，把甜品送去墨瞳那儿", },
	[161014] = {id=161014, zh_CN="甜品里有芭菲，这需要你限时前往，超时则需要你重返甜品车重新获得芭菲。今天墨瞳的王厅里来了许多人，不同种族的角色将会对话来妨碍你。", },
	[161015] = {id=161015, zh_CN="将甜品送达墨瞳的位置", },
	[161016] = {id=161016, zh_CN="最终你抵达关底。", },
	[161017] = {id=161017, zh_CN="夏拉拉和墨瞳在房间里对台词。夏拉拉看见你后希望你能作为听众。墨瞳虽然有些抱怨但是还是让你留了下来", },
	[161018] = {id=161018, zh_CN="与夏拉拉对话", },
	[161019] = {id=161019, zh_CN="夏拉拉说自己希望你作为新听众来帮助墨瞳。", },
	[161020] = {id=161020, zh_CN="但是墨瞳并不希望有更多听众。", },
	[161021] = {id=161021, zh_CN="你获得了种子。", },
	[161022] = {id=161022, zh_CN="夏拉拉发消息邀请你前去墨瞳房间。", },
	[161023] = {id=161023, zh_CN="去墨瞳的房间，与大家对话。", },
	[161024] = {id=161024, zh_CN="我知道一种勇敢果实吃后能够让人勇敢，你能不能帮我把它采集回来", },
	[161025] = {id=161025, zh_CN="你采集获得了勇敢果实", },
	[161026] = {id=161026, zh_CN="你回到墨瞳的房间，把勇敢果实带给墨瞳。", },
	[161027] = {id=161027, zh_CN="把勇敢果实带给墨瞳。", },
	[161028] = {id=161028, zh_CN="我们可以找一个地方，给墨瞳试试胆量", },
	[161029] = {id=161029, zh_CN="我知道一个地方，去广场，怎么样？", },
	[161030] = {id=161030, zh_CN="夏拉拉提议找一个地方试试胆量，甜霜熊提议去广场试试，需要你在广场搭建一个宣讲台。（制造）（交付）", },
	[161031] = {id=161031, zh_CN="但是广场没有宣讲台，你能帮我们在广场上建一个宣讲台吗？", },
	[161032] = {id=161032, zh_CN="好的，我可以帮忙", },
	[161033] = {id=161033, zh_CN="需要你在广场搭建一个宣讲台。（制造）（交付）你前往广场与墨瞳互动交付材料。", },
	[161034] = {id=161034, zh_CN="你回到工坊制造所需材料。", },
	[161035] = {id=161035, zh_CN="墨瞳想要试试不吃勇敢果实的演讲，但结果并不理想，墨瞳对自己的不争气感到愤怒，获得怒花瓣。", },
	[161036] = {id=161036, zh_CN="墨瞳想要试试不吃勇敢果实的演讲，所以上台前将勇敢果实交予给你", },
	[161037] = {id=161037, zh_CN="但是墨瞳的演讲不太顺利", },
	[161038] = {id=161038, zh_CN="你通过读心术得知观众们的心声。", },
	[161039] = {id=161039, zh_CN="需要你鼓励墨瞳。你回到墨瞳身边。与墨瞳对话，使用刚刚读心术的正确鼓励信息。", },
	[161040] = {id=161040, zh_CN="你使用刚刚读心术的正确鼓励信息，鼓励了墨瞳。", },
	[161041] = {id=161041, zh_CN="最终墨瞳认识到自己的不足，并接纳了自己的缺点。成功将演讲进行下去。", },
	[161042] = {id=161042, zh_CN="墨瞳成功主持了晚会。但舞会厅的MCorDJ找不到了，音乐迟迟没能播放，于是你要找到他（读心）（寻人）", },
	[161043] = {id=161043, zh_CN="请帮忙寻找舞会厅的MCorDJ", },
	[161044] = {id=161044, zh_CN="墨瞳发送信件邀请你前往舞会厅", },
	[161045] = {id=161045, zh_CN="你错过了墨瞳的演讲，但是你通过读心术快速找到了有用信息", },
	[161046] = {id=161046, zh_CN="与MC对话", },
	[161047] = {id=161047, zh_CN="MC说自己因为长期服用勇敢果实后会有一系列的副作用。", },
	[161048] = {id=161048, zh_CN="你前往舞会厅与墨瞳对话。墨瞳拜托你作为MC与她共舞。最后你成功代班。墨瞳的晚会十分成功。", },
	[161049] = {id=161049, zh_CN="请你作为MC与我共舞吧", },
	[161050] = {id=161050, zh_CN="今天晚上的共舞我很开心，谢谢你", },
	[161051] = {id=161051, zh_CN="邀请成功", },
	[161052] = {id=161052, zh_CN="我种了好多好多的梅子，你要来一个吗？", },
	[161053] = {id=161053, zh_CN="对方正在交换角色，请稍后再发起请求", },
	[161054] = {id=161054, zh_CN="和梅说话", },
	[161055] = {id=161055, zh_CN="和广场上的梅对话", },
	[161056] = {id=161056, zh_CN="帮助梅解决问题", },
	[161057] = {id=161057, zh_CN="于是你决定回到工坊制造新的栅栏", },
	[161058] = {id=161058, zh_CN="老鼠们果真食言了，他们又一次破坏了梅的梅园，于是梅打算召集所有朋友保卫梅园。", },
	[161059] = {id=161059, zh_CN="你们把老鼠赶进了一个灌木丛里，但是灌木丛有有好几个通道，", },
	[161060] = {id=161060, zh_CN="梅正在和老鼠对峙，问问发生了什么", },
	[161061] = {id=161061, zh_CN="完成任务——%s 后解锁", },
	[161062] = {id=161062, zh_CN="你来到墨瞳的房间外。发现墨瞳房间里传出了一些声音", },
	[161063] = {id=161063, zh_CN="啊！你怎么在这，我没发现原来自己的门没关好，不好意思哈", },
	[161064] = {id=161064, zh_CN="她的房间门并没有关紧，你透过房门偶然看到了，墨瞳正在碎碎念。", },
	[161065] = {id=161065, zh_CN="她连忙紧张兮兮地关上了房门。", },
	[161066] = {id=161066, zh_CN="你对墨瞳现在的状态感到担心，正站在门外想帮助墨瞳的办法，可是还没过半分钟，墨瞳房间里又传出碎碎念的声音", },
	[161067] = {id=161067, zh_CN="你来到了星劫月影的地图里，看见了甜霜熊和甜品车，但是甜品车抛锚卡住了。", },
	[161068] = {id=161068, zh_CN="我的甜品里有巴菲，需要你在一定的时间内送到墨瞳那儿，如果超时未送到的话，你得回到我的甜品车这重新补充芭菲，再送一次", },
	[161069] = {id=161069, zh_CN="夏拉拉和墨瞳在房间里对台词。", },
	[161070] = {id=161070, zh_CN="最后墨瞳与大家对话。你也获得了奖励。", },
	[161071] = {id=161071, zh_CN="能不能帮我帮忙代班一会。", },
	[161072] = {id=161072, zh_CN="我家的梅园栅栏破损了，能不能帮帮我修理栅栏", },
	[161073] = {id=161073, zh_CN="只要你们能提供足够的食物给我，那么我就不会再来破坏梅园偷吃梅子了", },
	[161074] = {id=161074, zh_CN="你们要什么食物？", },
	[161075] = {id=161075, zh_CN="这下够了吧！", },
	[161076] = {id=161076, zh_CN="谢谢你帮我，不过我怀疑这件事还没结束……", },
	[161077] = {id=161077, zh_CN="测试用邀请函", },
	[161078] = {id=161078, zh_CN="梅，我来了！我给你带来了", },
	[161079] = {id=161079, zh_CN="不够！我们还要很多很多的冻干！", },
	[161080] = {id=161080, zh_CN="建筑回收成功", },
	[161081] = {id=161081, zh_CN="洛瑞昂", },
	[161082] = {id=161082, zh_CN="测试用花瓶", },
