	[161539] = {id=161539, zh_CN="你是这个游戏的主人，你可以制定规则。", },
	[161540] = {id=161540, zh_CN="（主）白天阶段，你可以煽动周围其他玩家。当全部在场玩家被煽动时，你将获得胜利。", },
	[161541] = {id=161541, zh_CN="（被）当你被投票放逐，你将获得胜利。", },
	[161542] = {id=161542, zh_CN="（被）免疫以你为目标的所有效果（包括药剂、庇佑、驱逐、占卜等正负面效果）。 \n（被）当在场人数少于3人时，你将获得胜利。当你成功驱逐恶魔阵营玩家后，获胜所需的在场人数+1。\n （主）入夜阶段，你可以驱逐任意一名玩家。", },
	[161543] = {id=161543, zh_CN="（被）随机一名玩家成为赏金目标（目标迷失后转移给除赏金猎人外的另一名玩家），累计成功驱逐3名赏金目标后你将获得胜利。（本局游戏人数大于8名时，每多2名玩家则你需要驱逐的目标数量+1。）\n（主）你可以在白天阶段驱逐赏金目标。", },
	[161544] = {id=161544, zh_CN="（被）入夜阶段，免疫以你为目标的所有驱逐。 （主）白天阶段，你可以驱逐其他玩家。当场上仅剩你一人时，你将获得胜利。", },
	[161545] = {id=161545, zh_CN="（主）限一次，可以在首夜阶段或入夜阶段选择一名玩家并复制其身份。\n 被复制的玩家被你投票放逐时，你将获得胜利。若目标玩家迷失，你获得他的获胜条件。", },
	[161546] = {id=161546, zh_CN="（主）入夜阶段，可选择一名其他玩家进行庇佑，在当前夜晚，此玩家免疫所有负面效果（药剂、侵蚀、驱逐）。", },
	[161547] = {id=161547, zh_CN="（被）入夜阶段，随机得知一名与你相邻的在场玩家身份（不会得知该身份属于哪名玩家）。", },
	[161548] = {id=161548, zh_CN="（被）白天阶段，若你因驱逐而迷失，驱逐者将立刻开启会议。", },
	[161549] = {id=161549, zh_CN="（主）入夜阶段，可调查一名已迷失玩家的身份。", },
	[161550] = {id=161550, zh_CN="（主）入夜阶段，可选择一名玩家，得知其在该阶段是否使用了技能及其使用对象。", },
	[161551] = {id=161551, zh_CN="（被）入夜阶段，你免疫恶魔阵营的驱逐。\n （被）你可以抵挡一次白天阶段的驱逐，若成功抵挡，则入夜阶段你会得知此事且失去该技能。", },
	[161552] = {id=161552, zh_CN="（主）入夜阶段，你可以审判一名玩家，若该玩家属于恶魔阵营，则其被放逐，否则你将永久失去该技能。", },
	[161553] = {id=161553, zh_CN="（主）整场游戏限一次，入夜阶段，你可以驱逐一名玩家，若该玩家属于村民阵营，则你会被放逐。", },
	[161554] = {id=161554, zh_CN="（被）入夜阶段，随机得知一名其他在场玩家的身份（不会得知身份所属玩家）。", },
	[161555] = {id=161555, zh_CN="（被）入夜阶段，随机得知一条其他在场玩家笔记中的信息。", },
	[161556] = {id=161556, zh_CN="（主）入夜阶段，你可以进入梦游状态。\n 梦游：当你被驱逐，则此次驱逐目标会随机转移给一名与你相邻的在场玩家。", },
	[161557] = {id=161557, zh_CN="（被）免疫侵蚀和药剂效果。\n （被）白天阶段，可以得知哪些玩家被侵蚀或药剂效果所影响。\n （被）入夜阶段，随机得知一条已迷失玩家笔记中的信息，但不会知道信息来源。", },
	[161558] = {id=161558, zh_CN="（主）白天阶段，你可以驱逐其他玩家。若该玩家属于村民阵营，则你会因内疚自我放逐。", },
	[161559] = {id=161559, zh_CN="（主）夜晚阶段，当你被投票放逐时，可选择一名玩家。若该玩家不属于村民阵营，则其会被放逐。", },
	[161560] = {id=161560, zh_CN="（被）白天阶段无法发动驱逐。\n （主）入夜阶段，可以选择一名玩家投放药剂，直至下次白天阶段结束，其失去全部技能。", },
	[161561] = {id=161561, zh_CN="（主）整场游戏中两次，入夜阶段你可以猜测一名玩家的身份，如果正确则该玩家被放逐，反之你被放逐。", },
	[161562] = {id=161562, zh_CN="（被）其他玩家使用技能得知你的身份时会随机显示为正义阵营中的一个未被选择身份。", },
	[161563] = {id=161563, zh_CN="（被）被你驱逐的玩家残留印记会持续隐形，残留印记只有你能看到并且可以转移名置，但其他玩家靠近残留印记后会自动发起会议。", },
	[161564] = {id=161564, zh_CN="（被）白天阶段，驱逐一名村民阵营玩家后，得知其笔记中的所有信息。", },
	[161565] = {id=161565, zh_CN="（被）被你驱逐的首个玩家会将身份转变为侍从。当你迷失时，侍从会转变成领主。", },
	[161566] = {id=161566, zh_CN="（被）领主迷失时，你的身份转变为领主。", },
	[161567] = {id=161567, zh_CN="（主）入夜阶段，你可以侵蚀2名玩家。 \n下个白天阶段，任意一名被侵蚀的玩家迷失，则另一名被侵蚀玩家也一同迷失。", },
	[161568] = {id=161568, zh_CN="永久伪装", },
	[161569] = {id=161569, zh_CN="永久变身", },
