	[164079] = {id=164079, },
	[164080] = {id=164080, zh_CN="寻访哈尔", },
	[164081] = {id=164081, zh_CN="接下小金毛的委托，但这”鬼魂“似乎有些蹊跷，一个人调查太冒险了，去找哈尔帮忙吧！", },
	[164082] = {id=164082, zh_CN="小金毛拜托你去调查城堡的“鬼魂”，一个人去似乎有些危险，去找哈尔帮忙吧！", },
	[164083] = {id=164083, zh_CN="广场", },
	[164084] = {id=164084, zh_CN="告别小金毛，你来找哈尔。", },
	[164085] = {id=164085, zh_CN="你巡视周围，却并未看到那个心目中的身影。", },
	[164086] = {id=164086, zh_CN="奇怪，哈尔去哪里了。", },
	[164087] = {id=164087, zh_CN="哈尔平常爱去哪里呢……", },
	[164088] = {id=164088, zh_CN="【哈尔的行踪】", },
	[164089] = {id=164089, zh_CN="听说哈尔最近常在甜品店后门的角落出没，快去找找，邀请他一起调查城堡！", },
	[164090] = {id=164090, zh_CN="寻找哈尔，一起调查城堡。", },
	[164091] = {id=164091, zh_CN="广场", },
	[164092] = {id=164092, zh_CN="哈尔果然在甜品店旁，看起来正在给小猫们梳毛。", },
	[164093] = {id=164093, zh_CN="哈尔！终于找到你了！", },
	[164094] = {id=164094, zh_CN="找我？", },
	[164095] = {id=164095, zh_CN="我遇到了一些困难，想要拜托你帮忙。", },
	[164096] = {id=164096, zh_CN="哈尔，你的背毛是谁梳的呢？", },
	[164097] = {id=164097, zh_CN="……", },
	[164098] = {id=164098, zh_CN="有时候我自己梳，有时候叫别人帮我梳……", },
	[164099] = {id=164099, zh_CN="夸他。", },
	[164100] = {id=164100, zh_CN="哈尔这么厉害的话，那帮我一点小忙肯定没问题的啦！", },
	[164102] = {id=164102, zh_CN="直接请求。", },
	[164103] = {id=164103, zh_CN="哎呀，明明是来办正事情的，怎么闲聊起来了。", },
	[164104] = {id=164104, zh_CN="我遇到了一些困难，想要拜托你帮帮我。", },
	[164105] = {id=164105, zh_CN="哈尔，你的背毛是谁梳的呢？", },
	[164106] = {id=164106, zh_CN="……", },
	[164107] = {id=164107, zh_CN="我会定期去宠物美容院。", },
	[164108] = {id=164108, zh_CN="那里不是不接受兽人族和猫族吗？", },
	[164109] = {id=164109, zh_CN="……", },
	[164110] = {id=164110, zh_CN="告诉我吧，好狗狗，告诉我吧~", },
	[164111] = {id=164111, zh_CN="就是可以变回原型，装成主人忙碌的宠物狗……", },
	[164112] = {id=164112, zh_CN="嘴里咬住写好的纸条和钱袋就可以了。", },
	[164113] = {id=164113, zh_CN="原来宠物店经常说的那只聪明又独立的黑色边牧是你呀！", },
	[164114] = {id=164114, zh_CN="对……", },
	[164115] = {id=164115, zh_CN="获得哈尔的称呼：护理终身VIC。", },
	[164116] = {id=164116, zh_CN="夸赞哈尔。", },
	[164117] = {id=164117, zh_CN="哈尔这么厉害的话，那帮我一点小忙肯定没问题的啦！", },
	[164119] = {id=164119, zh_CN="直接请求。", },
	[164120] = {id=164120, zh_CN="哎呀，明明是来办正事情的，怎么闲聊起来了。", },
	[164121] = {id=164121, zh_CN="我遇到了一些困难，想要拜托你帮帮我。", },
	[164122] = {id=164122, zh_CN="哦~可爱猫猫，你也来找我按摩吗？", },
	[164123] = {id=164123, zh_CN="按摩？你要对我做什么喵！", },
	[164124] = {id=164124, zh_CN="%PlayerName不愿意的话就算了……", },
	[164125] = {id=164125, zh_CN="哎呀，不要难过的喵。", },
	[164126] = {id=164126, zh_CN="我遇到了一些困难，想要拜托你帮忙。", },
	[164127] = {id=164127, zh_CN="当然没问题，我会尽我所能的。", },
	[164128] = {id=164128, zh_CN="那真的太好不过了。", },
	[164129] = {id=164129, zh_CN="你伸出手和哈尔击掌。", },
	[164130] = {id=164130, zh_CN="哈尔，你有听过“城堡闹鬼”吗？", },
	[164131] = {id=164131, zh_CN="听……听过。", },
	[164132] = {id=164132, zh_CN="那你知道什么消息吗？我正在调查这件事。", },
	[164133] = {id=164133, zh_CN="……", },
	[164134] = {id=164134, zh_CN="%PlayerName，对不起，我其实知道一些实情。", },
	[164135] = {id=164135, zh_CN="但是我现在不能告诉你。", },
	[164136] = {id=164136, zh_CN="没关系，你能来陪我调查就很好了。", },
	[164137] = {id=164137, zh_CN="能帮助到你，是我的荣幸。", },
	[164138] = {id=164138, zh_CN="我一定尽我所能。", },
	[164139] = {id=164139, zh_CN="那真的太好不过了。", },
	[164140] = {id=164140, zh_CN="你攥着哈尔的手臂，兴奋地跳起。", },
	[164141] = {id=164141, zh_CN="那“闹鬼城堡”探险队成立！", },
	[164142] = {id=164142, zh_CN="成立！", },
	[164143] = {id=164143, zh_CN="等等……", },
	[164144] = {id=164144, zh_CN="你说的是那个传闻吗？", },
	[164145] = {id=164145, zh_CN="对呀。哈尔，你知道什么消息吗？", },
	[164146] = {id=164146, zh_CN="……", },
	[164147] = {id=164147, zh_CN="%PlayerName，我不想骗你。", },
	[164148] = {id=164148, zh_CN="我愿意陪你一起调查这件事。", },
	[164149] = {id=164149, zh_CN="但是我没办法告诉你更多了，只是现在不能。", },
	[164150] = {id=164150, zh_CN="没关系，你能来陪我，我就很开心了。", },
	[164151] = {id=164151, zh_CN="能帮助到你，是我的荣幸。", },
	[164152] = {id=164152, zh_CN="出现这个问题的时候，你有第一个想到我吗？", },
	[164153] = {id=164153, zh_CN="当然！我的脑海里只有你一个身影闪过。", },
	[164154] = {id=164154, zh_CN="真的？", },
	[164155] = {id=164155, zh_CN="对呀。", },
	[164156] = {id=164156, zh_CN="你揽住哈尔的脖颈，兴奋跳起和他拥抱在一起。", },
	[164157] = {id=164157, zh_CN="那“闹鬼城堡”探险队成立啦！", },
	[164158] = {id=164158, zh_CN="成立！", },
	[164159] = {id=164159, zh_CN="等等……", },
	[164160] = {id=164160, zh_CN="你说的是那个传闻吗？", },
	[164161] = {id=164161, zh_CN="对呀，哈尔，你知道什么消息吗？", },
	[164162] = {id=164162, zh_CN="……", },
	[164163] = {id=164163, zh_CN="%PlayerName，我不想骗你，我其实知道一些实情。", },
	[164164] = {id=164164, zh_CN="但是我现在还没做好准备告诉你。", },
	[164165] = {id=164165, zh_CN="这样，你还愿意带上我去调查这件事吗？", },
	[164166] = {id=164166, zh_CN="没关系，你能来陪我，我已经很开心了。", },
	[164167] = {id=164167, zh_CN="毕竟狗狗是人类最好的伙伴！", },
	[164168] = {id=164168, zh_CN="走吧，出发！", },
	[164169] = {id=164169, zh_CN="哈尔任由你把他擒走。", },
	[164171] = {id=164171, zh_CN="毕竟人类是狗狗最好的伙伴！", },
	[164172] = {id=164172, zh_CN="好！那走吧，出发！", },
	[164174] = {id=164174, zh_CN="向着城堡前进！", },
	[164175] = {id=164175, zh_CN="【城堡鬼魂调查案】", },
	[164176] = {id=164176, zh_CN="你和哈尔约定第二日傍晚在鸭湖城堡外的喷泉旁集合，一同去探寻“城堡闹鬼”的真相。", },
	[164177] = {id=164177, zh_CN="你和哈尔约定第二日傍晚在鸭湖城堡外的喷泉旁集合，一同去探寻“城堡闹鬼”的真相。", },
	[164178] = {id=164178, zh_CN="鸭湖城堡", },
	[164179] = {id=164179, zh_CN="哦，你来了。", },
	[164180] = {id=164180, zh_CN="嗯！", },
	[164181] = {id=164181, zh_CN="接下来我们怎么展开调查呢？", },
	[164182] = {id=164182, zh_CN="分工合作。", },
	[164183] = {id=164183, zh_CN="哈尔，不如我们分头行动吧。", },
	[164184] = {id=164184, zh_CN="如果你有什么发现的话，就吹响这个口哨。", },
	[164185] = {id=164185, zh_CN="我们及时会合。", },
	[164186] = {id=164186, zh_CN="好。", },
	[164187] = {id=164187, zh_CN="%PlayerName，你注意安全。", },
	[164188] = {id=164188, zh_CN="包在我身上。", },
	[164189] = {id=164189, zh_CN="你和哈尔分道扬镳。", },
	[164190] = {id=164190, zh_CN="哈尔先前往小金毛所说的位置查看情况。", },
	[164191] = {id=164191, zh_CN="而你则选择独自前往另一边。", },
	[164192] = {id=164192, zh_CN="【调查藏书室】", },
	[164193] = {id=164193, zh_CN="古堡的藏书室似乎有着不为人知的秘密，等待你的探寻。", },
	[164194] = {id=164194, zh_CN="古堡的藏书室似乎有着不为人知的秘密，等待你的探寻。", },
	[164195] = {id=164195, zh_CN="鸭湖城堡", },
	[164196] = {id=164196, zh_CN="夜晚的月光透过阁楼的高窗，洒下柔和的银边。", },
	[164197] = {id=164197, zh_CN="你不禁在藏书室门前驻足，欣赏这难得的景致。", },
	[164198] = {id=164198, zh_CN="你闭上眼睛，感受夜晚的微风，四周寂静无人，除却风声，还有一丝细微的书页被翻动的声音。", },
	[164199] = {id=164199, zh_CN="你睁开眼睛，疑惑的看向四周。", },
	[164200] = {id=164200, zh_CN="有书没收拾好，落在藏书室外面了吗？", },
	[164201] = {id=164201, zh_CN="虽有月光，但四周还是很黑，你伸出手摸索着……", },
	[164202] = {id=164202, zh_CN="试试用侦察寻找到那本书吧。", },
	[164203] = {id=164203, zh_CN="【藏书室的秘密】", },
	[164204] = {id=164204, zh_CN="藏书室外面有一本被遗落的书，试试用侦察将其寻出。", },
	[164205] = {id=164205, zh_CN="藏书室外面有一本被遗落的书，试试用侦察将其寻出。", },
	[164206] = {id=164206, zh_CN="鸭湖城堡", },
	[164207] = {id=164207, zh_CN="就在这时，你的指尖传来羊皮纸温润的触感。", },
	[164208] = {id=164208, zh_CN="接着月光，你看清了这本书的样子，它没有书脊包装，也没有烫金标题，连封面都是简单的素色……", },
	[164209] = {id=164209, zh_CN="似乎是……一本日记？", },
	[164210] = {id=164210, zh_CN="你擦掉封面上的灰。", },
	[164211] = {id=164211, zh_CN="不知名的日记。", },
	[164212] = {id=164212, zh_CN="上面出现一行字符。", },
	[164213] = {id=164213, zh_CN="这串字符是……", },
	[164214] = {id=164214, zh_CN="哈尔？！！", },
	[164215] = {id=164215, zh_CN="难道这是哈尔的日记本？", },
	[164216] = {id=164216, zh_CN="那这个汪汪，嗷呜又是……", },
	[164217] = {id=164217, zh_CN="难道只是单纯的叫声吗？", },
	[164218] = {id=164218, zh_CN="你认为是“汪汪，嗷呜”是……", },
	[164219] = {id=164219, zh_CN="拟声词。", },
	[164220] = {id=164220, zh_CN="不对……哈尔的用词应该不会这么浅显……", },
	[164221] = {id=164221, zh_CN="动词。", },
	[164222] = {id=164222, zh_CN="猜不出来……", },
	[164223] = {id=164223, zh_CN="名词。", },
	[164224] = {id=164224, zh_CN="嗯！这么想就合理了！", },
	[164225] = {id=164225, zh_CN="假如汪汪是狗，嗷呜代表狼的话……", },
	[164226] = {id=164226, zh_CN="难道是？哈尔不是狼，是狗？", },
	[164227] = {id=164227, zh_CN="你缓缓翻开第一页。", },
	[164228] = {id=164228, zh_CN="纸张的质感有些粗糙，页面上密密麻麻写满了嗷呜嗷呜汪的奇怪符号。", },
	[164229] = {id=164229, zh_CN="这句话的翻译是……", },
	[164230] = {id=164230, zh_CN="妈妈说哈尔是热情小狗？", },
	[164231] = {id=164231, zh_CN="“他们说哈尔是狼，但妈妈说哈尔是忠诚，热情的小狗狗。”", },
	[164232] = {id=164232, zh_CN="一下就猜中了哈尔的心思呢！", },
	[164233] = {id=164233, zh_CN="（亲密＋一般）", },
	[164234] = {id=164234, zh_CN="他们说哈尔不是狼？", },
	[164235] = {id=164235, zh_CN="“哈尔是狼，他们说，哈尔不是狼，哈尔是狗，哈尔妈妈说，狗狗是忠诚热情的。”", },
	[164236] = {id=164236, zh_CN="哈尔似乎不是这个意思……", },
	[164237] = {id=164237, zh_CN="妈妈说小狗都是忠诚热情的？", },
	[164238] = {id=164238, zh_CN="“他们说哈尔是狼，但妈妈说哈尔是狗，小狗都是忠诚热情的。”", },
	[164239] = {id=164239, zh_CN="哈尔似乎不是这个意思……", },
	[164240] = {id=164240, zh_CN="越往后翻，慢慢地出现了很多你认识的字，从简单的狼，狗，到各类动词名词。", },
	[164241] = {id=164241, zh_CN="最后是逐渐连贯的语句 ……", },
	[164242] = {id=164242, zh_CN="哈尔……", },
	[164243] = {id=164243, zh_CN="一声哨声响破城堡。", },
	[164244] = {id=164244, zh_CN="是哈尔！", },
	[164245] = {id=164245, zh_CN="你心情复杂，将日记放回原位。", },
	[164246] = {id=164246, zh_CN="同心合力。", },
	[164247] = {id=164247, zh_CN="哈尔，我们要分头行动吗？", },
	[164248] = {id=164248, zh_CN="如果落单遇到“城堡鬼怪”就不好了，我们还是一起走吧。", },
	[164249] = {id=164249, zh_CN="好吧，听你的。", },
	[164250] = {id=164250, zh_CN="如果发生意外就吹响口哨。", },
	[164251] = {id=164251, zh_CN="我会最快速度来到你身边。", },
	[164252] = {id=164252, zh_CN="好。", },
	[164253] = {id=164253, zh_CN="你和哈尔决定先去小金毛所说的藏书室，一探究竟。", },
	[164254] = {id=164254, zh_CN="夜晚的月光透过阁楼的高窗，洒下柔和的银边。", },
	[164255] = {id=164255, zh_CN="你不禁在藏书室门前驻足，欣赏这难得的景致。", },
	[164256] = {id=164256, zh_CN="你闭上眼睛，感受夜晚的微风，四周寂静无人，除却风声，还有一丝细微的书页被翻动的声音。", },
	[164257] = {id=164257, zh_CN="你睁开眼睛，疑惑的看向四周。", },
	[164258] = {id=164258, zh_CN="有书没收拾好，落在藏书室外面了吗？", },
	[164259] = {id=164259, zh_CN="虽有月光，但四周还是很黑，你伸出手摸索着……", },
	[164260] = {id=164260, zh_CN="试试用侦察寻找到那本书吧。", },
	[164261] = {id=164261, zh_CN="就在这时，你的指尖传来羊皮纸温润的触感。", },
	[164262] = {id=164262, zh_CN="接着月光，你看清了这本书的样子，它没有书脊包装，也没有烫金标题，连封面都是简单的素色……", },
	[164263] = {id=164263, zh_CN="似乎是……一本日记？", },
	[164264] = {id=164264, zh_CN="你擦掉封面上的灰", },
	[164265] = {id=164265, zh_CN="正要翻开第一页时，哈尔的声音从后面传来。", },
	[164266] = {id=164266, zh_CN="嘿！别跑！！", },
	[164267] = {id=164267, zh_CN="哈尔跑到你面前", },
	[164268] = {id=164268, zh_CN="怎么了？", },
	[164269] = {id=164269, zh_CN="你看到那只猫了吗？", },
	[164270] = {id=164270, zh_CN="什么猫？", },
	[164271] = {id=164271, zh_CN="我刚刚发现了一本书……", },
	[164272] = {id=164272, zh_CN="一只白色的猫，我看到它从那里跳下去，越过围栏，往露台去了。", },
	[164273] = {id=164273, zh_CN="你顺着哈尔的手指看去。", },
	[164274] = {id=164274, zh_CN="犹豫了片刻后，目光在笔记本和露台之间徘徊。", },
	[164275] = {id=164275, zh_CN="笔记本。", },
	[164276] = {id=164276, zh_CN="还是先去看一眼笔记本吧，不耽误……", },
	[164277] = {id=164277, zh_CN="来不及了，我们快追！", },
	[164278] = {id=164278, zh_CN="（好感—少量）", },
	[164279] = {id=164279, zh_CN="猫。", },
	[164280] = {id=164280, zh_CN="走吧，先去追猫。", },
	[164281] = {id=164281, zh_CN="好。", },
	[164282] = {id=164282, zh_CN="（信任＋少量）", },
	[164283] = {id=164283, zh_CN="你和哈尔朝露台赶去。", },
	[164284] = {id=164284, zh_CN="日记封面。", },
	[164285] = {id=164285, zh_CN="—嗷呜—哈啊呜—\n（似乎是：汪：哈尔：）", },
	[164286] = {id=164286, zh_CN="第一篇日记：", },
	[164287] = {id=164287, zh_CN="：：哈尔：嗷呜：他们说。—哈尔—嗷呜—，：哈尔：汪汪：妈妈哈尔说。汪汪：忠诚，热情！", },
	[164288] = {id=164288, zh_CN="第七篇日记：", },
	[164289] = {id=164289, zh_CN="哈尔“少年音色好听吃香”直播夸，可我还会偷偷跑到山头去嚎叫，他们不知道。", },
	[164290] = {id=164290, zh_CN="小金毛说我该感谢偏见，因为争议带来流量，可流量……也不过是另一种笼子。", },
	[164291] = {id=164291, zh_CN="一本蒙灰的日记，被遗忘已久，隐藏着某个人的秘密。", },
	[164292] = {id=164292, zh_CN="第十六篇日记：", },
	[164293] = {id=164293, zh_CN="半路上，你们在走廊发现了几处可疑的闪光。", },
	[164294] = {id=164294, zh_CN="仔细检查了这几处闪光。", },
	[164295] = {id=164295, zh_CN="你捡到了一撮黑白相间的毛。", },
	[164296] = {id=164296, zh_CN="这个颜色，是年糕吗？它的尾巴……", },
	[164297] = {id=164297, zh_CN="刚刚年糕是往露台的方向跑了吗？", },
	[164298] = {id=164298, zh_CN="一定是的，路上还有小猫脚印！", },
	[164299] = {id=164299, zh_CN="我们轻声去看看吧。", },
	[164300] = {id=164300, zh_CN="你到达会客厅的时候，正巧和年糕对视。", },
	[164301] = {id=164301, zh_CN="年糕趴在会客厅的中间的红毯上，像是在等什么人，左右张望着。", },
	[164302] = {id=164302, zh_CN="年糕经常呆在会客厅里，它应该知道什么吧……", },
	[164303] = {id=164303, zh_CN="我们去问问年糕吧。", },
	[164304] = {id=164304, zh_CN="……好。", },
	[164305] = {id=164305, zh_CN="年糕！", },
	[164306] = {id=164306, zh_CN="唉？哈尔，你来的这么早的喵。", },
	[164307] = {id=164307, zh_CN="哈尔？", },
	[164308] = {id=164308, zh_CN="没事，你不是要问年糕关于“城堡闹鬼”的事情吗？", },
	[164309] = {id=164309, zh_CN="哦~原来是问这个，虽然我知道一些故事，但是现在不能告诉你们喵。", },
	[164310] = {id=164310, zh_CN="真的不说？", },
	[164311] = {id=164311, zh_CN="我是英勇的战士，不会屈服！", },
	[164312] = {id=164312, zh_CN="让我思考一下，年糕在想什么呢……", },
	[164313] = {id=164313, zh_CN="哼哼，猜小猫猫的心思对我来说易如反掌~", },
	[164314] = {id=164314, zh_CN="年糕的心声：把真相告诉说出来，我就没有哈尔的马萨基按摩了喵。", },
	[164315] = {id=164315, zh_CN="哦？哈尔？按摩？", },
	[164316] = {id=164316, zh_CN="喵！你怎么知道我在想什么！？", },
	[164317] = {id=164317, zh_CN="小猫猫的心思不简单啊……猜不出来，根本猜不出来！", },
	[164318] = {id=164318, zh_CN="突然你发现年糕频频看向哈尔，哈尔的眼生也躲躲闪闪的……", },
	[164319] = {id=164319, zh_CN="有猫腻！", },
	[164320] = {id=164320, zh_CN="看来这闹鬼的事情，年糕和哈尔都知晓，但是在刻意隐瞒……", },
	[164321] = {id=164321, zh_CN="你是来找哈尔按摩的吧？", },
	[164322] = {id=164322, zh_CN="要不要试试我的手艺呀？", },
	[164323] = {id=164323, zh_CN="我可是要求很高的。", },
	[164324] = {id=164324, zh_CN="不试试，怎么知道呢。货比三家哦。", },
	[164325] = {id=164325, zh_CN="哈尔，我们比赛梳毛吧，如果我胜利的话，你们要告诉我真相。", },
	[164326] = {id=164326, zh_CN="好。", },
	[164327] = {id=164327, zh_CN="你们拿出梳子。", },
	[164328] = {id=164328, zh_CN="你一时不慎，年糕疼得从你怀中跳出。", },
	[164329] = {id=164329, zh_CN="再给我一次机会，糕老板？", },
	[164330] = {id=164330, zh_CN="才不要！水平完全不行呀，和昨晚哈尔的……", },
	[164331] = {id=164331, zh_CN="昨晚哈尔的什么，按摩吗？", },
	[164332] = {id=164332, zh_CN="（解锁成就：昨夜，哈吉咪你……）", },
	[164333] = {id=164333, zh_CN="你迟疑了片刻。", },
	[164334] = {id=164334, zh_CN="那个城堡鬼魂不会是你吧，哈尔。", },
	[164335] = {id=164335, zh_CN="哈尔并没有回答你，他垂下尾巴灰溜溜地变成原型，逃似地跑走了。", },
	[164336] = {id=164336, zh_CN="哈尔！", },
	[164337] = {id=164337, zh_CN="你默默盯着哈尔的身影消失在黑夜中。", },
	[164338] = {id=164338, zh_CN="你比我还会摸毛茸茸！以后梳毛就拜托你了！", },
	[164339] = {id=164339, zh_CN="（好感度＋少量）", },
	[164340] = {id=164340, zh_CN="该告诉我真相了吧，两位。", },
	[164341] = {id=164341, zh_CN="那个城堡鬼魂不会是你吧，哈尔。", },
	[164342] = {id=164342, zh_CN="是我。", },
	[164343] = {id=164343, zh_CN="对不起，骗了你。", },
	[164344] = {id=164344, zh_CN="哈尔并没有等待你的回应，垂下尾巴灰溜溜地变成原型，逃似地跑走了。", },
	[164345] = {id=164345, zh_CN="哈尔！", },
	[164346] = {id=164346, zh_CN="你默默盯着哈尔的身影消失在黑夜中。", },
	[164347] = {id=164347, zh_CN="就算我们是同族，我也不能背叛朋友喵。", },
	[164348] = {id=164348, zh_CN="而且你也会拜倒在马萨基的淫威下的喵。", },
	[164349] = {id=164349, zh_CN="马萨基？", },
	[164350] = {id=164350, zh_CN="哈尔，快去！让年糕见识你的按摩功力！", },
	[164351] = {id=164351, zh_CN="哈尔夜夜都会给我梳毛，我不怕你喵。", },
	[164352] = {id=164352, zh_CN="年糕惊恐地捂嘴，眼瞳在你和哈尔之间来回转动。", },
	[164353] = {id=164353, zh_CN="夜夜梳毛？", },
	[164354] = {id=164354, zh_CN="你迟疑了片刻。", },
	[164355] = {id=164355, zh_CN="那个城堡鬼魂不会是你吧，哈尔。", },
	[164356] = {id=164356, zh_CN="哈尔并没有回答你，垂下尾巴灰溜溜地变成原型，逃似地跑走了。", },
	[164357] = {id=164357, zh_CN="哈尔！", },
	[164358] = {id=164358, zh_CN="你默默盯着哈尔的身影消失在黑夜中。", },
	[164359] = {id=164359, zh_CN="【紧急事件】", },
	[164360] = {id=164360, zh_CN="哈尔吹响了你给他的哨子，似乎是有急事需要你帮助。", },
	[164361] = {id=164361, zh_CN="哈尔吹响了你给他的哨子，似乎是有急事需要你帮助。", },
	[164362] = {id=164362, zh_CN="鸭湖城堡", },
	[164363] = {id=164363, zh_CN="【可疑的闪光】", },
	[164364] = {id=164364, zh_CN="你和哈尔朝露台赶去，行至走廊，你们发现了一处可疑的闪光，或许和年糕的去向有关，需要仔细探查一番。", },
	[164365] = {id=164365, zh_CN="你和哈尔朝露台赶去，行至走廊，你们发现了一处可疑的闪光，或许和年糕的去向有关，需要仔细探查一番。", },
	[164366] = {id=164366, zh_CN="鸭湖城堡", },
	[164367] = {id=164367, zh_CN="【真相揭露】", },
	[164368] = {id=164368, zh_CN="年糕早已在露台等候，去寻他询问城堡“鬼魂”的真相！", },
	[164369] = {id=164369, zh_CN="年糕早已在露台等候，去寻他询问城堡“鬼魂”的真相！", },
	[164370] = {id=164370, zh_CN="鸭湖城堡", },
	[164371] = {id=164371, zh_CN="【谈心】", },
	[164372] = {id=164372, zh_CN="你知道哈尔躲着你，便写了信约他今天下午在城堡花坊见面。", },
	[164373] = {id=164373, zh_CN="你知道哈尔躲着你，便写了信约他今天下午在城堡花坊见面。", },
	[164374] = {id=164374, zh_CN="鸭湖城堡", },
	[164375] = {id=164375, zh_CN="你在花坊等了许久，一只捷克狼犬出现在你面前。", },
	[164376] = {id=164376, zh_CN="哈尔幻化成原型，默不作声地来到你的身边来。", },
	[164377] = {id=164377, zh_CN="%PlayerName，你不害怕我吗？", },
	[164378] = {id=164378, zh_CN="不害怕。", },
	[164379] = {id=164379, zh_CN="那你摸着你的心脏，以忠诚发誓。", },
	[164380] = {id=164380, zh_CN="我发誓，我永远都不会害怕哈尔。", },
	[164381] = {id=164381, zh_CN="可是，我欺骗了你呀。", },
	[164382] = {id=164382, zh_CN="你摸摸哈尔的耳朵，哈尔嗖地塌下耳朵尖，飞机耳泛着红晕。", },
	[164383] = {id=164383, zh_CN="我觉得喜欢毛茸茸的毛茸茸更可爱了。", },
	[164384] = {id=164384, zh_CN="秘密交换秘密，我们现在是比朋友更加好的好朋友啦。", },
	[164385] = {id=164385, zh_CN="（信任度加大量，好感度加少量）", },
	[164386] = {id=164386, zh_CN="你为什么要这么做？", },
	[164387] = {id=164387, zh_CN="因为大家都挺害怕我的。", },
	[164388] = {id=164388, zh_CN="就算我把自己束缚起来，可是大家还是习惯性地远离我。", },
	[164389] = {id=164389, zh_CN="我不敢去店里摸猫猫。", },
	[164390] = {id=164390, zh_CN="但我最近创作压力很大，不能摸猫的话，会受不了的。", },
	[164391] = {id=164391, zh_CN="所以才想出这个办法。", },
	[164392] = {id=164392, zh_CN="我也没想到会发生这样的事情。", },
	[164393] = {id=164393, zh_CN="我不是故意的。", },
	[164394] = {id=164394, zh_CN="真的吗？", },
	[164395] = {id=164395, zh_CN="你真的这么想吗？", },
	[164396] = {id=164396, zh_CN="你真好，要是所有人都像你一样，就好了。", },
	[164397] = {id=164397, zh_CN="为什么这么说？", },
	[164398] = {id=164398, zh_CN="感觉大家总会因为我的体型而害怕我。", },
	[164399] = {id=164399, zh_CN="尤其是小金毛，我不是故意吓它的。", },
	[164400] = {id=164400, zh_CN="我只是最近创作压力很大，需要摸毛茸茸来释放自己。", },
	[164401] = {id=164401, zh_CN="哈尔郁闷地将头埋入你脖颈，身后的尾巴摇花了你的眼睛。", },
	[164402] = {id=164402, zh_CN="是不是只要是毛茸茸，你就都喜欢。", },
	[164403] = {id=164403, zh_CN="当然不是，我最喜欢你了。", },
	[164404] = {id=164404, zh_CN="真的？就算知道罪魁祸首是我。", },
	[164405] = {id=164405, zh_CN="我知道哈尔也因此内疚很久了。", },
	[164406] = {id=164406, zh_CN="想要和我说说看嘛？", },
	[164407] = {id=164407, zh_CN="大家因为我的体型都很害怕我。", },
	[164408] = {id=164408, zh_CN="我不敢去店里摸猫猫，感觉影响了别人。", },
	[164409] = {id=164409, zh_CN="就算我把自己束缚起来，可是大家还是习惯性地远离我。", },
	[164410] = {id=164410, zh_CN="我不会远离你。", },
	[164411] = {id=164411, zh_CN="但是我最近创作压力很大，不能摸猫的话，会受不了的。", },
	[164412] = {id=164412, zh_CN="我就想到了这个办法。", },
	[164413] = {id=164413, zh_CN="我也没想到会发生这样的事情。", },
	[164414] = {id=164414, zh_CN="我不是故意的。", },
	[164415] = {id=164415, zh_CN="%PlayerName，我是不是要变成大家最讨厌的人了。", },
	[164416] = {id=164416, zh_CN="绝对不会的。", },
	[164417] = {id=164417, zh_CN="%PlayerName……", },
	[164418] = {id=164418, zh_CN="嗯？", },
	[164419] = {id=164419, zh_CN="如果只有证明忠诚，才能被自己的族群接纳，如果是你，你会怎么做？", },
	[164420] = {id=164420, zh_CN="遵守规则。", },
	[164421] = {id=164421, zh_CN="那就遵守规则，表现得忠诚，无害。", },
	[164422] = {id=164422, zh_CN="对啊，保持无害就好了，这么简单的道理……", },
	[164423] = {id=164423, zh_CN="可是真的好累。", },
	[164424] = {id=164424, zh_CN="（好感＋少量）", },
	[164425] = {id=164425, zh_CN="打破规则。", },
	[164426] = {id=164426, zh_CN="我会逃离规则。", },
	[164427] = {id=164427, zh_CN="只有这样，才能找到真正的族群。", },
	[164428] = {id=164428, zh_CN="……你说得对。", },
	[164429] = {id=164429, zh_CN="我们好像都是局外人呢。", },
	[164430] = {id=164430, zh_CN="哈尔耷拉着耳朵，眼瞳蒙上一层灰蒙蒙的武器，暗淡无光。", },
	[164431] = {id=164431, zh_CN="原本晃动的尾巴无力地垂在他身侧，偶尔才抽动一下。", },
	[164432] = {id=164432, zh_CN="我们聊点开心的！", },
	[164433] = {id=164433, zh_CN="我刚刚听到……哈尔你说，创作压力？", },
	[164434] = {id=164434, zh_CN="你上下打量着哈尔，突然某个视角，哈尔的身形，声音一一对应。", },
	[164435] = {id=164435, zh_CN="哈尔，你不会是旅行博主—局外狗吧。", },
	[164436] = {id=164436, zh_CN="哈尔突然害羞紧张，他虽然没有回答，但躁动的尾巴暴露了他的心思。", },
	[164437] = {id=164437, zh_CN="我知道怎么办啦！", },
	[164438] = {id=164438, zh_CN="如果我用你的账号直播的话……", },
	[164439] = {id=164439, zh_CN="又能改善大家对你的印象，又能解开“城堡鬼魂”之谜。", },
	[164440] = {id=164440, zh_CN="一箭双雕呀！！", },
	[164441] = {id=164441, zh_CN="【直播风波】", },
	[164442] = {id=164442, zh_CN="你准备帮哈尔开直播解开“城堡鬼魂”之谜，一切准备就绪，前往城堡露台，开拍！", },
	[164443] = {id=164443, zh_CN="你准备帮哈尔开直播解开“城堡鬼魂”之谜，一切准备就绪，前往城堡露台，开拍！", },
	[164444] = {id=164444, zh_CN="鸭湖城堡", },
	[164445] = {id=164445, zh_CN="你站在会客厅门口，打开了标题为《重生之我是星之子探索鸭湖城堡”鬼魂“》的直播。", },
	[164446] = {id=164446, zh_CN="大家好，欢迎来到局外狗的直播间。", },
	[164447] = {id=164447, zh_CN="唉？狗君真变成星之子了？\n 难道要揭开马甲了？\n 我天，蹲屁股！", },
	[164448] = {id=164448, zh_CN="局外狗重生了，上一世他是不敢揭马甲的狗君……", },
	[164449] = {id=164449, zh_CN="这一世，他重生到了宇宙飞船上，星之子就是他的新名字。", },
	[164450] = {id=164450, zh_CN="难道要揭开马甲了？", },
	[164451] = {id=164451, zh_CN="我天，蹲屁股！", },
	[164452] = {id=164452, zh_CN="今天，我和重生而来的星之子——狗君。", },
	[164453] = {id=164453, zh_CN="就要揭秘“城堡鬼魂”的真相！", },
	[164454] = {id=164454, zh_CN="传闻说“城堡鬼魂”会吃光灵……", },
	[164455] = {id=164455, zh_CN="请问猫桑，你的亲朋好友有被吃掉吗？", },
	[164456] = {id=164456, zh_CN="虽然我们的猫灵不能回答问题，但它的状态已经说明了一切。", },
	[164457] = {id=164457, zh_CN="欸！好光滑的背毛啊，感觉被人梳过呢。", },
	[164458] = {id=164458, zh_CN="光灵灵那么可爱，怎么能吃光灵灵！\n 嘶，“城堡鬼魂”难道爱摸毛茸茸？\n 猫猫飞天教万岁，连“鬼魂”都迷倒的猫猫飞天教主万岁。\n 参见喵喵喵喵。", },
	[164459] = {id=164459, zh_CN="嘶，“城堡鬼魂”难道爱摸毛茸茸？", },
	[164460] = {id=164460, zh_CN="猫猫飞天教万岁，连“鬼魂”都迷倒的猫猫飞天教主万岁。", },
	[164461] = {id=164461, zh_CN="参见喵喵喵喵。", },
	[164462] = {id=164462, zh_CN="猫猫们看到哈尔，朝镜头冲来，哈尔将镜头交给你，便蹲下来拿出梳子，尽职尽责地摸每只猫猫。", },
	[164463] = {id=164463, zh_CN="舞厅传来此起彼伏的喵喵声。", },
	[164464] = {id=164464, zh_CN="弹幕护体，高能君你在哪？\n 啊，我受不了了，快让我看看狗君真容！", },
	[164465] = {id=164465, zh_CN="嘘。", },
	[164466] = {id=164466, zh_CN="我好像听到什么细细簌簌的声音，狗君在喷泉广场吗？", },
	[164467] = {id=164467, zh_CN="啊，我受不了了，快让我看看狗君真容！", },
	[164468] = {id=164468, zh_CN="别着急~这就带你们去找他！", },
	[164469] = {id=164469, zh_CN="【最后的谢幕】", },
	[164470] = {id=164470, zh_CN="是时候了！前往喷泉广场，揭露“城堡鬼魂”和“局外狗”的真相！", },
	[164471] = {id=164471, zh_CN="鸭湖城堡", },
	[164472] = {id=164472, zh_CN="！！！！！\n 前方可爱高能！", },
	[164473] = {id=164473, zh_CN="前方可爱高能！", },
	[164474] = {id=164474, zh_CN="一只浅灰的“大狼狗”正和一群猫猫打成一片。", },
	[164475] = {id=164475, zh_CN="“大狼狗”伸出指甲，给排队的小咪咪一个个梳毛按摩。", },
	[164476] = {id=164476, zh_CN="呼噜声此起彼伏。", },
	[164477] = {id=164477, zh_CN="“大狼狗”耳朵微动，似乎察觉到什么，朝镜头看过来，浅白脸毛下泛起的红晕被镜头抓个正着。", },
	[164478] = {id=164478, zh_CN="“大狼狗”飞奔而来，在镜头前化成人形。", },
	[164479] = {id=164479, zh_CN="%PlayerName，好了，我们关掉直播吧。", },
	[164480] = {id=164480, zh_CN="这是你的账号，和大家打个招呼吧。", },
	[164481] = {id=164481, zh_CN="大家好，我是“局外狗”——哈尔。", },
	[164482] = {id=164482, zh_CN="啊啊啊啊！\n 毛茸茸摸毛茸茸！\n 你的背毛有人梳嘛？宠物护理专业申请出战！", },
	[164483] = {id=164483, zh_CN="毛茸茸摸毛茸茸！", },
	[164484] = {id=164484, zh_CN="你的背毛有人梳嘛？宠物护理专业申请出战！", },
	[164485] = {id=164485, zh_CN="之前给大家造成了很大的困扰，我很抱歉。", },
	[164486] = {id=164486, zh_CN="毛茸茸永远没错！", },
	[164487] = {id=164487, zh_CN="你看见了几条奇怪的弹幕飘过。", },
	[164488] = {id=164488, zh_CN="维护哈尔。", },
	[164489] = {id=164489, zh_CN="主播不是狼啊，主播是狗，帅气的捷克狼犬兽人。", },
	[164490] = {id=164490, zh_CN="哈尔的尾巴欢快地摇动。", },
	[164491] = {id=164491, zh_CN="调侃哈尔。", },
	[164492] = {id=164492, zh_CN="主播是狼兽人吗？", },
	[164493] = {id=164493, zh_CN="我是狗，不是狼不是狼不是狼。", },
	[164494] = {id=164494, zh_CN="再乱讲就咬你！", },
	[164495] = {id=164495, zh_CN="（亲密度＋少量）", },
	[164496] = {id=164496, zh_CN="主播有移动城堡吗？", },
	[164497] = {id=164497, zh_CN="没有没有没有。", },
	[164498] = {id=164498, zh_CN="不和你们聊了，下播！", },
	[164499] = {id=164499, zh_CN="我们再来满足网友们一个心愿就下下播啦~", },
	[164500] = {id=164500, zh_CN="我看看……", },
	[164501] = {id=164501, zh_CN="哈尔捏着尾巴尖尖，好奇地凑过来。", },
	[164502] = {id=164502, zh_CN="狗君用尾巴画画！", },
	[164503] = {id=164503, zh_CN="用……尾巴画画？", },
	[164504] = {id=164504, zh_CN="……", },
	[164505] = {id=164505, zh_CN="这个好！！就这个！\n ＋111", },
	[164506] = {id=164506, zh_CN="111", },
	[164507] = {id=164507, zh_CN="哈尔吓了一跳，意识到自己说错了话。", },
	[164508] = {id=164508, zh_CN="那就画个画吧。", },
	[164509] = {id=164509, zh_CN="哈尔听话将蓬松的大尾巴交到你的手上。", },
	[164510] = {id=164510, zh_CN="你抓着哈尔的尾巴根，在地上描绘着。", },
	[164511] = {id=164511, zh_CN="哈尔背对着你，什么都窥探不到，他和弹幕们一同好奇着你的作品。", },
	[164512] = {id=164512, zh_CN="你拍掉手上的灰，擦干净了哈尔的尾巴。", },
	[164513] = {id=164513, zh_CN="好啦！", },
	[164514] = {id=164514, zh_CN="映入眼帘的，是两只小豆豆人，其中一只身边围绕着各种猫猫，大尾巴藏在身后，格外可爱。", },
	[164515] = {id=164515, zh_CN="画的是我和哈尔。", },
	[164516] = {id=164516, zh_CN="喜欢吗？", },
	[164517] = {id=164517, zh_CN="喜欢！", },
	[164518] = {id=164518, zh_CN="（好感度＋大量）", },
	[164519] = {id=164519, zh_CN="好蓬松的大尾巴勾引。", },
	[164520] = {id=164520, zh_CN="你眼疾手快地关掉直播。", },
	[164521] = {id=164521, zh_CN="狗君模仿光灵跳舞！", },
	[164522] = {id=164522, zh_CN="模仿……光灵跳舞？", },
	[164523] = {id=164523, zh_CN="……", },
	[164524] = {id=164524, zh_CN="这个好！！就这个！", },
	[164525] = {id=164525, zh_CN="111", },
	[164526] = {id=164526, zh_CN="哈尔吓了一跳，意识到自己说错了话。", },
	[164527] = {id=164527, zh_CN="我来打个样吧。", },
	[164528] = {id=164528, zh_CN="你随意哼唱着一首小调，脚步随便地跳着，跳到兴奋的时候，朝哈尔伸出手。", },
	[164529] = {id=164529, zh_CN="要和我共舞一曲吗？", },
	[164530] = {id=164530, zh_CN="好吧。", },
	[164531] = {id=164531, zh_CN="你和哈尔在舞池中旋转、滑步，每一个动作都默契十足。", },
	[164532] = {id=164532, zh_CN="舞毕。", },
	[164533] = {id=164533, zh_CN="很厉害嘛！", },
	[164534] = {id=164534, zh_CN="谢谢！你也是！！", },
	[164535] = {id=164535, zh_CN="我今天真的很开心！", },
	[164536] = {id=164536, zh_CN="（好感度＋大量）", },
	[164537] = {id=164537, zh_CN="哈尔可以考虑换舞蹈赛道了呢！", },
	[164538] = {id=164538, zh_CN="你和哈尔和观众道别后关闭了直播。", },
	[164539] = {id=164539, zh_CN="不一会，你的手机发出声响，你打开热搜，递给哈尔。", },
	[164540] = {id=164540, zh_CN="《人气旅行博主首次露出竟是他！！！》", },
	[164541] = {id=164541, zh_CN="大家都很喜欢你哦。", },
	[164542] = {id=164542, zh_CN="什么嘛！", },
	[164543] = {id=164543, zh_CN="%PlayerName，今天谢谢你。", },
	[164544] = {id=164544, zh_CN="我们是好朋友，这有什么。", },
	[164545] = {id=164545, zh_CN="不过……哈尔可以把尾巴给我摸摸吗？", },
	[164546] = {id=164546, zh_CN="当然没问题。", },
	[164547] = {id=164547, zh_CN="来吧！", },
	[164548] = {id=164548, zh_CN="你摸摸摸摸摸。也是体会到哈尔的快乐了。", },
	[164549] = {id=164549, zh_CN="这是我应该做的。", },
	[164550] = {id=164550, zh_CN="请问……", },
	[164551] = {id=164551, zh_CN="什么？", },
	[164552] = {id=164552, zh_CN="可以让我摸你的尾巴吗？", },
	[164553] = {id=164553, zh_CN="我没有这样的构造。", },
	[164554] = {id=164554, zh_CN="当然可以。", },
	[164555] = {id=164555, zh_CN="你小心捏了捏哈尔的尾巴，触感很奇怪，但你想猫咪被奉为教主是有原因的。", },
	[164556] = {id=164556, zh_CN="我们是朋友呐，大恩不言谢哦。", },
	[164557] = {id=164557, zh_CN="好。", },
	[164558] = {id=164558, zh_CN="不过……哈尔可以把尾巴给我摸摸吗？", },
	[164559] = {id=164559, zh_CN="当然没问题。", },
	[164560] = {id=164560, zh_CN="来吧！", },
	[164561] = {id=164561, zh_CN="你摸摸摸摸摸。也是体会到哈尔的快乐了。", },
	[164562] = {id=164562, zh_CN="哈尔，那我可以要一点点小的报酬吗？", },
	[164563] = {id=164563, zh_CN="当然可以。", },
	[164564] = {id=164564, zh_CN="可以把尾巴给我摸摸吗？", },
	[164565] = {id=164565, zh_CN="来吧！", },
	[164566] = {id=164566, zh_CN="片刻——", },
	[164567] = {id=164567, zh_CN="哈尔，那可以再给我摸摸耳朵吗？", },
	[164568] = {id=164568, zh_CN="可……可以。", },
	[164569] = {id=164569, zh_CN="片刻——", },
	[164570] = {id=164570, zh_CN="哈尔，可以变出原型给我摸摸吗？", },
	[164571] = {id=164571, zh_CN="我给你梳梳背毛呀。", },
	[164572] = {id=164572, zh_CN="最后一次哦。", },
	[164573] = {id=164573, zh_CN="片刻——", },
	[164574] = {id=164574, zh_CN="哈尔……", },
	[164575] = {id=164575, zh_CN="适可而止吧！%PlayerName。", },
	[164576] = {id=164576, zh_CN="（信任度—1，亲密度＋6）", },
	[164577] = {id=164577, zh_CN="你摸摸摸摸摸。也是体会到哈尔的快乐了。", },
	[164578] = {id=164578, zh_CN="（获得成就：狗狗教主执事）", },
	[164579] = {id=164579, zh_CN="你恋恋不舍的把手从哈尔的尾巴上收回。", },
	[164580] = {id=164580, zh_CN="以后可不可以只摸摸我一个人？", },
	[164581] = {id=164581, zh_CN="猫猫不可以，狗狗也不可以。", },
	[164582] = {id=164582, zh_CN="我随便给你摸摸。", },
	[164583] = {id=164583, zh_CN="好不好？", },
	[164584] = {id=164584, zh_CN="好！", },
	[164585] = {id=164585, zh_CN="嗯！", },
	[164586] = {id=164586, zh_CN="“求之不得”。", },
	[164587] = {id=164587, zh_CN="约定好了，就不许再反悔了。", },
	[164588] = {id=164588, zh_CN="哈尔害羞地收回尾巴", },
	[164589] = {id=164589, zh_CN="下次见面的时候，希望哈尔成为年度最受欢迎博主哦！", },
	[164590] = {id=164590, zh_CN="嗯！一定会的！", },
