	[166057] = {id=166057, zh_CN="为光灵分派工作岗位，将它们部署至作业区，调度生产的集成中心，协调社区工作区域的生产运作。在中心范围内才可以放置建筑哦。", },
	[166058] = {id=166058, zh_CN="人员分派中心的调度分支，方便社团成员的及时调度光灵工作。在分支节点的范围内也可以放置建筑哦。", },
	[166059] = {id=166059, zh_CN="集中储存并管理由社团工作区域生产出的物资和道具，社团成员可按需提取。", },
