	[168101] = {id=168101, zh_CN="快吃吧，专门为你准备的小鱼干", },
	[168102] = {id=168102, zh_CN="心疼流浪生活", },
	[168103] = {id=168103, zh_CN="你打开饭盒，里面是一份简单但可口的饭菜。", },
	[168104] = {id=168104, zh_CN="你喜欢真是太好了。", },
	[168105] = {id=168105, zh_CN="你挑了一块沾满卤汁的，递到小金毛嘴前。", },
	[168106] = {id=168106, zh_CN="小金毛才不会饥一顿饱一顿。", },
	[168107] = {id=168107, zh_CN="不喜餐食，买点同价位的", },
	[168108] = {id=168108, zh_CN="你盯着午餐，有些无从下口，随机的食物实在有些不合胃口。", },
	[168109] = {id=168109, zh_CN="你起身去一旁的餐馆。", },
	[168110] = {id=168110, zh_CN="买些差不多价位，合口的就行，要照顾狗狗的心情。", },
	[168111] = {id=168111, zh_CN="小金毛准备的午饭不够周到吗？", },
	[168112] = {id=168112, zh_CN="对不起……", },
	[168113] = {id=168113, zh_CN="没关系。心意到就很好了。", },
	[168114] = {id=168114, zh_CN="不喜餐食，买点昂贵合口的", },
	[168115] = {id=168115, zh_CN="你盯着午餐，有些无从下口，随机的食物实在有些不合胃口。", },
	[168116] = {id=168116, zh_CN="你起身去一旁的餐馆。", },
	[168117] = {id=168117, zh_CN="还是直接选自己想吃的吧。", },
	[168118] = {id=168118, zh_CN="小金毛准备的午饭太差了吗？", },
	[168119] = {id=168119, zh_CN="鸡腿不太合我口味而已。", },
	[168120] = {id=168120, zh_CN="为什么会被抓捕？", },
	[168121] = {id=168121, zh_CN="城市里不允许野生光灵流浪……", },
	[168122] = {id=168122, zh_CN="可能……他们把我当作是光灵了吧。", },
	[168123] = {id=168123, zh_CN="你察觉到小金毛口袋里还余下许多盒饭。", },
	[168124] = {id=168124, zh_CN="为什么不愿意去收容所？", },
	[168125] = {id=168125, zh_CN="小金毛，你为什么要拒绝去收容所？", },
	[168126] = {id=168126, zh_CN="小金毛不能离开他们。", },
	[168127] = {id=168127, zh_CN="它该不会是大胃王吧？", },
	[168128] = {id=168128, zh_CN="好多饭盒？它吃得完吗？", },
	[168129] = {id=168129, zh_CN="不会是负担不起自己大胃王的饭量吧。", },
	[168130] = {id=168130, zh_CN="好奇余下的饭盒。", },
	[168131] = {id=168131, zh_CN="你肚子下面捂住的饭盒是……？", },
	[168132] = {id=168132, zh_CN="这是给我朋友准备的午饭！", },
	[168133] = {id=168133, zh_CN="结束对话。", },
	[168134] = {id=168134, zh_CN="差点把收容所吃倒闭的大胃王", },
	[168135] = {id=168135, zh_CN="难道它曾经被收容所抓走。", },
	[168136] = {id=168136, zh_CN="因为太能吃了，", },
	[168137] = {id=168137, zh_CN="差点把收容所吃倒闭？", },
	[168138] = {id=168138, zh_CN="难道它是黑白通吃的收容所大佬？", },
	[168139] = {id=168139, zh_CN="小金毛其实是不显山水，", },
	[168140] = {id=168140, zh_CN="刚刚从收容所逃出的狗老大？", },
	[168141] = {id=168141, zh_CN="这些多出的食物一会儿还要分发给小弟们？", },
	[168142] = {id=168142, zh_CN="吃百家饭长大的可怜蛋……", },
	[168143] = {id=168143, zh_CN="难道它是吃百家饭长大的大胃王？", },
	[168144] = {id=168144, zh_CN="委托赚饭后，", },
	[168145] = {id=168145, zh_CN="每天都暴饮暴食？", },
	[168146] = {id=168146, zh_CN="嘿！你在想什么呢？", },
	[168147] = {id=168147, zh_CN="没，没什么。", },
	[168148] = {id=168148, zh_CN="……", },
	[168149] = {id=168149, zh_CN="小金毛的耳朵猛地竖起！绕着你转圈圈。", },
	[168150] = {id=168150, zh_CN="你怎么啦？", },
	[168151] = {id=168151, zh_CN="开玩笑——我回不去家了。", },
	[168152] = {id=168152, zh_CN="汪汪，%PlayerName和小金毛一样呢。", },
	[168153] = {id=168153, zh_CN="它摇动尾巴扫过你的脸颊，戳戳你。", },
	[168154] = {id=168154, zh_CN="你怎么啦？", },
	[168155] = {id=168155, zh_CN="我回不去家了。", },
	[168156] = {id=168156, zh_CN="嘿嘿，%PlayerName和小金毛一样呢。", },
	[168157] = {id=168157, zh_CN="别难过了，我们要振作起来！", },
	[168158] = {id=168158, zh_CN="迷失在旅途中，就寻找家乡的线索……", },
	[168159] = {id=168159, zh_CN="就努力建造争取属于自己的家呀。", },
	[168160] = {id=168160, zh_CN="小金毛……你原来真的是流浪狗吗？", },
	[168161] = {id=168161, zh_CN="不是的。", },
	[168162] = {id=168162, zh_CN="小金毛……", },
	[168163] = {id=168163, zh_CN="哎呀，解释不清楚啦。", },
	[168164] = {id=168164, zh_CN="这可是难为小金毛这只小狗了。", },
	[168165] = {id=168165, zh_CN="小金毛焦急地咬住你，围着你绕圈圈。", },
	[168166] = {id=168166, zh_CN="你来了就知道了！", },
	[168167] = {id=168167, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168168] = {id=168168, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168169] = {id=168169, zh_CN="将你拱上自己的背上，飞奔而去", },
	[168170] = {id=168170, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168171] = {id=168171, zh_CN="唉唉唉，我们要去哪里呀！", },
