	[168176] = {id=168176, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168177] = {id=168177, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168178] = {id=168178, zh_CN="将你拱上自己的背上，飞奔而去", },
	[168179] = {id=168179, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168180] = {id=168180, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168181] = {id=168181, zh_CN="快和我走。", },
	[168182] = {id=168182, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168183] = {id=168183, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168184] = {id=168184, zh_CN="将你拱上自己的背上，飞奔而去", },
	[168185] = {id=168185, zh_CN="唉唉唉，我们要去哪里呀！", },
	[168186] = {id=168186, zh_CN="唉唉唉，我们要去哪里呀！", },
