	[168188] = {id=168188, zh_CN="……", },
	[168189] = {id=168189, zh_CN="%PlayerName！小金毛终于等到你了！", },
	[168190] = {id=168190, zh_CN="小金毛，有什么事？", },
	[168191] = {id=168191, zh_CN="我找到你想要的情绪花种了！", },
	[168192] = {id=168192, zh_CN="那是一朵小小的花瓣晶体。", },
	[168193] = {id=168193, zh_CN="花瓣形似铃兰花，通体乳白色，散发着柔和的光芒。", },
	[168194] = {id=168194, zh_CN="你惊讶地伸出手，小心翼翼地接住了这颗种子。", },
	[168195] = {id=168195, zh_CN="花瓣在你的掌心轻轻颤动，仿佛有生命一般。", },
	[168196] = {id=168196, zh_CN="小金毛你从哪里找到的这个种子？", },
	[168197] = {id=168197, zh_CN="从小金毛身体里飘出来的！", },
	[168198] = {id=168198, zh_CN="小金毛知道你一直在寻找它，所以小金毛决定帮你。", },
	[168199] = {id=168199, zh_CN="谢谢你，小金毛。我不知道该怎么感谢你。", },
	[168200] = {id=168200, zh_CN="我们是朋友，朋友之间不需要这么多客套。", },
	[168201] = {id=168201, zh_CN="你紧紧握住手中的种子，心中暗暗发誓，一定要好好珍惜它。", },
	[168202] = {id=168202, zh_CN="小金毛狗爪微微颤抖，按在信封上。", },
	[168203] = {id=168203, zh_CN="小金毛看到警察靠近，眼神中闪过一丝惊恐。", },
	[168204] = {id=168204, zh_CN="但你的心中也被愧疚侵占。", },
	[168205] = {id=168205, zh_CN="小金毛趁着你创造的机会，转身就跑。", },
	[168206] = {id=168206, zh_CN="你和小金毛回到花海树下。", },
	[168207] = {id=168207, zh_CN="你和小金毛回到花海树下。", },
	[168208] = {id=168208, zh_CN="各样的光灵躲在树后，它们看起来瘦弱而疲惫。", },
	[168209] = {id=168209, zh_CN="小金毛将委托赚来的食物分给光灵们。", },
	[168210] = {id=168210, zh_CN="别害怕哦，这是%PlayerName，是帮助过小金毛的好心人。", },
	[168211] = {id=168211, zh_CN="你瞧着食物小金毛一口未吃，全部都分给了光灵们。", },
	[168212] = {id=168212, zh_CN="小金毛用舌头舔舐着脏兮兮的光灵，制止光灵之间的争抢行为。", },
	[168213] = {id=168213, zh_CN="所以小金毛赚这些食物并不是给自己吃的……", },
	[168214] = {id=168214, zh_CN="而是用来养活这些无家可归的流浪光灵？", },
	[168215] = {id=168215, zh_CN="动容其奉献。", },
	[168216] = {id=168216, zh_CN="小金毛，你一只小狗照顾这么流浪光灵，会不会太辛苦了？", },
	[168217] = {id=168217, zh_CN="这些光灵都很可爱，很听话的。", },
	[168218] = {id=168218, zh_CN="小金毛喜欢他们。", },
	[168219] = {id=168219, zh_CN="心疼其负担。", },
	[168220] = {id=168220, zh_CN="这么多小动物，你一个人照顾得过来吗？", },
	[168221] = {id=168221, zh_CN="小金毛会把它们养到成年，等它们有了生存能力，就会离开小金毛的庇护所，独自生活。", },
	[168222] = {id=168222, zh_CN="询问其行为意图。", },
	[168223] = {id=168223, zh_CN="你这样图什么呢？", },
	[168224] = {id=168224, zh_CN="这就是小金毛所图之事。", },
	[168225] = {id=168225, zh_CN="不理解其行为。", },
	[168226] = {id=168226, zh_CN="你真是太善良了，你不先想想自己吗？", },
	[168227] = {id=168227, zh_CN="我有想自己呀。", },
	[168228] = {id=168228, zh_CN="看着小金毛开朗地朝你咧嘴，你被小金毛的善良和责任感深深打动，但又无法认同它独自承担而累垮自己的行为。", },
	[168229] = {id=168229, zh_CN="好吧，我愿意尊重你的决定。", },
	[168230] = {id=168230, zh_CN="认同其行为。", },
	[168231] = {id=168231, zh_CN="小金毛，你真是不可貌相，这么小的身躯，却有这么大的勇气和担当。", },
	[168232] = {id=168232, zh_CN="都是小金毛决定要做的事情，小金毛就要把它坚持到底。", },
	[168233] = {id=168233, zh_CN="如果有需要，随时找我帮忙。", },
	[168234] = {id=168234, zh_CN="%PlayerName，谢谢你。", },
	[168235] = {id=168235, zh_CN="动容其奉献。", },
	[168236] = {id=168236, zh_CN="小金毛，你一只小狗照顾这么流浪光灵，会不会太辛苦了？", },
	[168237] = {id=168237, zh_CN="这是小金毛自己的选择，小金毛不觉得辛苦。", },
	[168238] = {id=168238, zh_CN="这些光灵都很可爱，很听话的，小金毛喜欢他们。", },
	[168239] = {id=168239, zh_CN="询问照顾光灵的负担", },
	[168240] = {id=168240, zh_CN="这么多小动物，你一个人照顾得过来吗？", },
	[168241] = {id=168241, zh_CN="偶尔也会有光灵带些材料回来卖，减轻一些负担。", },
	[168242] = {id=168242, zh_CN="询问小金毛照顾他们的原因", },
	[168243] = {id=168243, zh_CN="你这样图什么呢？", },
	[168244] = {id=168244, zh_CN="我想要把这件事一直做下去，这是小金毛想做的事情。也是小金毛所图之事。", },
	[168245] = {id=168245, zh_CN="结束对话。", },
	[168246] = {id=168246, zh_CN="它突然像是想起了什么……", },
	[168247] = {id=168247, zh_CN="这是之前一个小光灵给小金毛的，说是一个藏宝图。", },
	[168248] = {id=168248, zh_CN="如果能找到宝藏，就能负担很久的开销了。", },
	[168249] = {id=168249, zh_CN="你已经调查很久了？", },
	[168250] = {id=168250, zh_CN="是的，而且在我的调查中，似乎也有一种不知名花卉的存在痕迹。", },
	[168251] = {id=168251, zh_CN="小金毛想邀请你合作去找宝藏。", },
	[168252] = {id=168252, zh_CN="犹豫。", },
	[168253] = {id=168253, zh_CN="情绪种子的消息迟迟找不到，你不想放弃这个机会。", },
	[168254] = {id=168254, zh_CN="归属不明的藏宝图，我们就这样贸然前往，会不会有危险呢？", },
	[168255] = {id=168255, zh_CN="请相信小金毛，小金毛的消息从没有错过哦。", },
	[168256] = {id=168256, zh_CN="你很需要情绪花种的线索不是吗？", },
	[168257] = {id=168257, zh_CN="小金毛不强求你，如果愿意的话，请随我一同去吧。", },
	[168258] = {id=168258, zh_CN="好吧，我答应你的邀请。", },
	[168259] = {id=168259, zh_CN="答应。", },
	[168260] = {id=168260, zh_CN="或许这是暂时唯一的线索，我要牢牢把握才行。", },
	[168261] = {id=168261, zh_CN="好，我答应你，但你答应我，一定要小心。", },
	[168262] = {id=168262, zh_CN="请相信小金毛。", },
	[168263] = {id=168263, zh_CN="请相信小金毛。", },
	[168264] = {id=168264, zh_CN="小金毛能请你吃一顿优秀的饭，就很开心。", },
	[168265] = {id=168265, zh_CN="小金毛的头塞在口袋里将自己的午饭叼出，剩下的狗爪扒到你的面前。", },
	[168266] = {id=168266, zh_CN="你和小金毛兴高采烈地将泥土挖出。", },
	[168267] = {id=168267, zh_CN="小金毛奋力地狗刨着。", },
	[168268] = {id=168268, zh_CN="你和它身上，都是它刨出来的泥点子。", },
	[168269] = {id=168269, zh_CN="小金毛甩掉头顶的泥巴，", },
	[168270] = {id=168270, zh_CN="爪子敲了敲闷声的位置。", },
	[168271] = {id=168271, zh_CN="找到啦！", },
	[168272] = {id=168272, zh_CN="那是一个朴素的铁盒，", },
	[168273] = {id=168273, zh_CN="你和小金毛将其捧出地底。", },
	[168274] = {id=168274, zh_CN="你颠了颠铁盒。", },
	[168275] = {id=168275, zh_CN="奇怪，怎么这么轻？", },
	[168276] = {id=168276, zh_CN="里面真的有宝藏吗？", },
	[168277] = {id=168277, zh_CN="铁盒里唰——哗啦啦的声音此起彼伏。", },
	[168278] = {id=168278, zh_CN="尝试撬锁。", },
	[168279] = {id=168279, zh_CN="锁看起来有些生锈，你决定用铁丝试试撬锁。", },
	[168280] = {id=168280, zh_CN="你感觉铁丝似乎碰到了什么，", },
	[168281] = {id=168281, zh_CN="你感觉铁丝似乎碰到了什么……", },
	[168282] = {id=168282, zh_CN="暴力破坏。", },
	[168283] = {id=168283, zh_CN="看起来可以暴力拆解开。", },
	[168284] = {id=168284, zh_CN="你对准锁扣用力砸了下去。", },
	[168285] = {id=168285, zh_CN="你对准锁扣用力砸了下去。", },
	[168286] = {id=168286, zh_CN="随便输入密码试试。", },
	[168287] = {id=168287, zh_CN="说不定随便输入几个数字就能打开呢。", },
	[168288] = {id=168288, zh_CN="你随随便输入一串密码。", },
	[168289] = {id=168289, zh_CN="你随随便输入一串密码……", },
	[168290] = {id=168290, zh_CN="让小金毛帮忙。", },
	[168291] = {id=168291, zh_CN="小金毛拜托你啦。", },
	[168292] = {id=168292, zh_CN="包在我身上。", },
	[168293] = {id=168293, zh_CN="它一跃而起，用身体的重量扑向盒锁！", },
	[168294] = {id=168294, zh_CN="唉，让小金毛来吧。", },
	[168295] = {id=168295, zh_CN="它一跃而起，用身体的重量扑向盒锁！", },
	[168296] = {id=168296, zh_CN="%PlayerName真厉害！", },
	[168297] = {id=168297, zh_CN="铁盒被打开，里面静静摆放着一封古朴的信封。", },
	[168298] = {id=168298, zh_CN="前爪抵住盒盖，阻止你拿出信封的动作。", },
	[168299] = {id=168299, zh_CN="读心。", },
	[168300] = {id=168300, zh_CN="小金毛忽然感受到一阵眩晕……", },
	[168301] = {id=168301, zh_CN="喂！你在做什么！", },
	[168302] = {id=168302, zh_CN="一道不属于你的心声在脑海中响起……", },
	[168303] = {id=168303, zh_CN="这是……旧主人的信。", },
	[168304] = {id=168304, zh_CN="沉默。", },
	[168305] = {id=168305, zh_CN="察觉到小金毛抗拒的心理，你选择沉默。", },
	[168306] = {id=168306, zh_CN="出声询问。", },
	[168307] = {id=168307, zh_CN="你知道里面是什么？", },
	[168308] = {id=168308, zh_CN="反正，现在我们都不能打开。", },
	[168309] = {id=168309, zh_CN="我需要一个理由，小金毛。", },
	[168310] = {id=168310, zh_CN="是你的故人留给你的吗？", },
	[168311] = {id=168311, zh_CN="呜呜，算是吧。", },
	[168312] = {id=168312, zh_CN="比如……你的旧主人？", },
	[168313] = {id=168313, zh_CN="你……你怎么知道的？", },
	[168314] = {id=168314, zh_CN="小金毛从箱子里拿出信封，信封沉甸甸的。", },
	[168315] = {id=168315, zh_CN="还有一封“轻飘飘”的信，", },
	[168316] = {id=168316, zh_CN="你想要将信捡起，", },
	[168317] = {id=168317, zh_CN="小金毛却飞扑将信压在肚子下。", },
	[168318] = {id=168318, zh_CN="它的尾巴扫起尘土迷住你的眼睛。", },
	[168319] = {id=168319, zh_CN="对……对不起，%PlayerName你的眼睛没受伤吧。", },
	[168320] = {id=168320, zh_CN="就在这时，仿佛空气都凝固了。", },
	[168321] = {id=168321, zh_CN="你感到一种温暖而柔和的气息从身边弥漫开来，", },
	[168322] = {id=168322, zh_CN="小心翼翼地接住了这颗种子。", },
	[168323] = {id=168323, zh_CN="它在你的掌心轻轻颤动，仿佛有生命一般。", },
	[168324] = {id=168324, zh_CN="小金毛狗爪微微颤抖，按在信封上。", },
	[168325] = {id=168325, zh_CN="可以代小金毛读信吗？小金毛不认识字。", },
	[168326] = {id=168326, zh_CN="你伸手轻轻拨开表面的浮土，", },
	[168327] = {id=168327, zh_CN="信纸上书写的字迹被你读出。", },
	[168328] = {id=168328, zh_CN="给最爱捡破烂的小狗：", },
	[168329] = {id=168329, zh_CN="嗨嗨，小金毛，好久不见。", },
	[168330] = {id=168330, zh_CN="没想到我还会给你留一笔遗产吧。", },
	[168331] = {id=168331, zh_CN="请随意挥霍金币吧", },
	[168332] = {id=168332, zh_CN="将留信与金币转交给小金毛。", },
	[168333] = {id=168333, zh_CN="——永远在你打盹时画花脸的坏主人", },
	[168334] = {id=168334, zh_CN="沉默。", },
	[168335] = {id=168335, zh_CN="你沉默着，将信塞入小金毛的怀中。", },
	[168336] = {id=168336, zh_CN="将信还给小金毛。", },
	[168337] = {id=168337, zh_CN="你的信，还给你。", },
	[168338] = {id=168338, zh_CN="安慰小金毛。", },
	[168339] = {id=168339, zh_CN="你还好吗？", },
	[168340] = {id=168340, zh_CN="不要……", },
	[168341] = {id=168341, zh_CN="安慰的话卡在喉咙吐不出口……", },
	[168342] = {id=168342, zh_CN="……谢谢。", },
	[168343] = {id=168343, zh_CN="片刻，小金毛起身向你走来。", },
	[168344] = {id=168344, zh_CN="我想把信埋回去。", },
	[168345] = {id=168345, zh_CN="不应该珍藏起来吗？", },
	[168346] = {id=168346, zh_CN="你主人给你留的信，你为什么不保存起来呢？", },
	[168347] = {id=168347, zh_CN="小金毛低头刨坑，将信封郑重地放入土坑中。", },
	[168348] = {id=168348, zh_CN="这是属于小金毛的珍藏方式。", },
	[168349] = {id=168349, zh_CN="小金毛要告诉他，我已经收到信啦。", },
	[168350] = {id=168350, zh_CN="帮忙埋信。", },
	[168351] = {id=168351, zh_CN="你没有多问，加入小金毛的挖坑队伍。", },
	[168352] = {id=168352, zh_CN="你和小金毛捧起最后一把土，埋入土坑之中，", },
	[168353] = {id=168353, zh_CN="小金毛要告诉他，我已经收到信啦。", },
	[168354] = {id=168354, zh_CN="我们回家吧。", },
	[168355] = {id=168355, zh_CN="还好吗？", },
	[168356] = {id=168356, zh_CN="当然，我可是这里的半个守夜人呢！", },
	[168357] = {id=168357, zh_CN="明天就能带光灵们换新窝了。", },
	[168358] = {id=168358, zh_CN="你可以把这笔金币用在自己身上。", },
	[168359] = {id=168359, zh_CN="曾经旧主人，", },
	[168360] = {id=168360, zh_CN="我只是继承了旧主人的遗志。", },
	[168361] = {id=168361, zh_CN="会实现的。", },
	[168362] = {id=168362, zh_CN="恍然间，你瞥见了小金毛千年间，", },
	[168363] = {id=168363, zh_CN="不达标：你想要将信捡起，小金毛却飞扑将信压在肚子下，它的尾巴扫起尘土迷住你的眼睛。", },
	[168364] = {id=168364, zh_CN="对……对不起，%PlayerName你的眼睛没受伤吧。", },
	[168365] = {id=168365, zh_CN="就在这时，仿佛空气都凝固了，你感到一种温暖而柔和的气息从身边弥漫开来。", },
	[168366] = {id=168366, zh_CN="你看到小金毛的身体周围似乎泛起了一层淡淡的光芒。", },
	[168367] = {id=168367, zh_CN="一颗小小的铃兰花种子从小金毛的身体里飘了出来，轻盈地悬浮在空中。这颗种子形似铃兰花，通体乳白色，散发着柔和的光芒。", },
	[168368] = {id=168368, zh_CN="你惊讶地伸出手，小心翼翼地接住了这颗种子。它在你的掌心轻轻颤动，仿佛有生命一般。", },
	[168369] = {id=168369, zh_CN="获得铃兰种子：“守护一座城，未必要悲情。”", },
	[168370] = {id=168370, zh_CN="这封信小金毛想自己一只狗看，可以吗？", },
	[168371] = {id=168371, zh_CN="担心小金毛情绪，选择陪伴。", },
	[168372] = {id=168372, zh_CN="我帮你望风，有些晚了，我等会送你回家。", },
	[168373] = {id=168373, zh_CN="……谢谢。", },
	[168374] = {id=168374, zh_CN="片刻，小金毛起身向你走来。", },
	[168375] = {id=168375, zh_CN="我们回家吧。", },
	[168376] = {id=168376, zh_CN="还好吗？", },
	[168377] = {id=168377, zh_CN="当然，我可是城镇的半个守夜人呢！", },
	[168378] = {id=168378, zh_CN="明天就能带光灵们换新窝了。", },
	[168379] = {id=168379, zh_CN="你可以把这笔金币用在自己身上。", },
	[168380] = {id=168380, zh_CN="曾经旧主人一直在为光灵可以在城市中安身而努力。", },
	[168381] = {id=168381, zh_CN="我只是继承了旧主人的遗志。", },
	[168382] = {id=168382, zh_CN="会实现的。", },
	[168383] = {id=168383, zh_CN="恍然间，你瞥见了小金毛千年间在光灵中，街道上奔跑……", },
	[168384] = {id=168384, zh_CN="尊重小金毛的决定，先行离开。", },
	[168385] = {id=168385, zh_CN="有什么困难就来找我。", },
	[168386] = {id=168386, zh_CN="……谢谢。", },
	[168387] = {id=168387, zh_CN="小金毛低声呜咽混着夜风消散，你转过身去，故意踩着重步离开。", },
	[168388] = {id=168388, },
	[168389] = {id=168389, zh_CN="【深夜，城墙边，一只狗和一个人坐在城垛上……】", },
	[168390] = {id=168390, zh_CN="深夜，城墙边，一只狗和一个人坐在城垛上……", },
	[168391] = {id=168391, zh_CN="你为什么叫自己“半个守夜人”呀？", },
	[168392] = {id=168392, zh_CN="因为小金毛是不会化形的兽人族啊，只能算半个人。", },
	[168393] = {id=168393, zh_CN="你是自己选择不化形的？", },
	[168394] = {id=168394, zh_CN="小金毛还是幼崽的时候，就是一只流浪狗。", },
	[168395] = {id=168395, zh_CN="可是在这里，你想要学的话，有很多人可以教你呀。", },
	[168396] = {id=168396, zh_CN="我是跟随旧主人来到这里的。", },
	[168397] = {id=168397, zh_CN="他离开前，小金毛早就学会了正视自己……", },
	[168398] = {id=168398, zh_CN="你旧主人离开时……", },
	[168399] = {id=168399, zh_CN="他没“离开”。", },
	[168400] = {id=168400, zh_CN="你看，当小狗有什么不好？悲伤是两脚兽的毛病，狗只关心明天肉丸够不够大！", },
	[168401] = {id=168401, zh_CN="再说了，可以当吃瓜记者的小狗又有几只呢？", },
	[168402] = {id=168402, zh_CN="我好像听到有人在家里吵架了，我要去听听……", },
	[168403] = {id=168403, zh_CN="小金毛的目标，是让每个明天都值得胡闹——", },
	[168404] = {id=168404, },
	[168405] = {id=168405, },
	[168406] = {id=168406, },
	[168407] = {id=168407, zh_CN="一只蓬松毛发，身上略微带有草屑的小金毛，摇晃尾巴。", },
	[168408] = {id=168408, zh_CN="小金毛摇头晃脑地左顾右盼，背后的尾巴高高托在背上，细长蓬松的金色尾巴毛晃来晃去。", },
	[168409] = {id=168409, zh_CN="远远地，你便被这簇活泼的尾巴毛吸引，金灿灿，毛茸茸的。", },
	[168410] = {id=168410, zh_CN="好蓬松的尾巴毛，想rua！", },
	[168411] = {id=168411, zh_CN="眼瞳缓缓收缩，不受控制地匍匐下身躯，跃跃欲试", },
	[168412] = {id=168412, zh_CN="恼人的尾巴毛！我要矜持喵。", },
	[168413] = {id=168413, zh_CN="【回到对话镜头】", },
	[168414] = {id=168414, zh_CN="小金毛注意到你的视线，转头与你对视，它咧嘴吐舌，直勾勾地盯着你。", },
	[168415] = {id=168415, zh_CN="小金毛没有见过你。", },
	[168416] = {id=168416, zh_CN="你好啊，远道而来的旅人。", },
	[168417] = {id=168417, zh_CN="什么怪狗，溜了溜了", },
	[168418] = {id=168418, zh_CN="你推开小金毛的扑拥，上下打量着它。", },
	[168419] = {id=168419, zh_CN="小金毛吓到你了吗？", },
	[168420] = {id=168420, zh_CN="好奇怪的狗，热情地有点过头了，有点可疑。", },
	[168421] = {id=168421, zh_CN="一人一狗僵持了片刻，小金毛的热情也因获取不到回应而消散。", },
	[168422] = {id=168422, zh_CN="我能摸摸尾巴毛吗？", },
	[168423] = {id=168423, zh_CN="嗨嗨！我可以摸摸你的尾巴毛吗？", },
	[168424] = {id=168424, zh_CN="当然可以啦，你也喜欢小金毛的尾巴毛吗？", },
	[168425] = {id=168425, zh_CN="小金毛转过身躯，信任地将后背交给你。", },
	[168426] = {id=168426, zh_CN="它的尾巴像狄花摇曳，暖意融融，荡起的欢快节奏好像很期待你的抚摸。", },
	[168427] = {id=168427, zh_CN="它怎么笑得贱兮兮的，我摸不摸呢？", },
	[168428] = {id=168428, zh_CN="笑得好欠揍，可是又好想摸，喵~", },
	[168429] = {id=168429, zh_CN="摸", },
	[168430] = {id=168430, zh_CN="你拘谨地将手掌覆上小金毛的脑袋，一股柔软的暖流包裹住掌心。", },
	[168431] = {id=168431, zh_CN="不摸", },
	[168432] = {id=168432, zh_CN="你的手悬在半空，想要伸出又偷偷缩回，如同两个小人吵架。", },
	[168433] = {id=168433, zh_CN="还是算了吧，有点不礼貌。", },
	[168434] = {id=168434, zh_CN="真的不摸摸小金毛吗？我的背毛很软和的？", },
	[168435] = {id=168435, zh_CN="难逃诱惑", },
	[168436] = {id=168436, zh_CN="我只是礼貌一下，你这般反复邀请我，可不要怪我不客气了。", },
	[168437] = {id=168437, zh_CN="你双手齐下，逮住小金毛的肚子肉，提入怀中。", },
	[168438] = {id=168438, zh_CN="欲拒还迎", },
	[168439] = {id=168439, zh_CN="心中好像蚂蚁在爬，痒痒的，摧残人的意志。", },
	[168440] = {id=168440, zh_CN="摸摸毛不会冒犯到小金毛的，小金毛喜欢被摸摸。", },
	[168441] = {id=168441, zh_CN="你眼睛睁开一条缝，手悄咪咪地伸到小金毛的背毛上", },
	[168442] = {id=168442, zh_CN="我拒绝过你咯。", },
	[168443] = {id=168443, zh_CN="嗯嗯！", },
	[168444] = {id=168444, zh_CN="你的手逐渐放肆，在小金毛柔软的背毛里畅游，顺着脊柱一路摸上去，", },
	[168445] = {id=168445, zh_CN="坐怀不乱", },
	[168446] = {id=168446, zh_CN="心中好像蚂蚁在爬，痒痒的，摧残人的意志。", },
	[168447] = {id=168447, zh_CN="摸摸毛不会冒犯到小金毛的，小金毛喜欢被摸摸。", },
	[168448] = {id=168448, zh_CN="你大步流星地后退几步，", },
	[168449] = {id=168449, zh_CN="朝着小金毛的方向挥手告别，小声与自己辩驳。", },
	[168450] = {id=168450, zh_CN="摸！大摸特摸！", },
	[168451] = {id=168451, zh_CN="你的手逐渐放肆，在小金毛柔软的背毛里畅游，顺着脊柱一路摸上去，", },
	[168452] = {id=168452, zh_CN="意犹未尽。", },
	[168453] = {id=168453, zh_CN="你望着小金毛享受地眯起眼，软绵绵的身躯逐渐要侧躺到地上，心生一计。", },
	[168454] = {id=168454, zh_CN="速度就是王道！", },
	[168455] = {id=168455, zh_CN="你双手齐下，逮住小金毛的肚子肉，提入怀中。", },
	[168456] = {id=168456, zh_CN="嗨，介绍一下自己吧~", },
	[168457] = {id=168457, zh_CN="惊吓！！", },
	[168458] = {id=168458, zh_CN="你被小金毛热情的扑闹惊吓到，双手蜷缩在胸前，身躯一颤。", },
	[168459] = {id=168459, zh_CN="不好意思，吓到你了吗？", },
	[168460] = {id=168460, zh_CN="没关系。", },
	[168461] = {id=168461, zh_CN="热情过头，想逃", },
	[168462] = {id=168462, zh_CN="招架不住小金毛的热情，你撇开脸，试图阻止小金毛的扑拥。", },
	[168463] = {id=168463, zh_CN="不好意思，吓到你了吗？", },
	[168464] = {id=168464, zh_CN="逐渐放松下来，朝小金毛挥挥手。", },
	[168465] = {id=168465, zh_CN="好吧。", },
	[168466] = {id=168466, zh_CN="激光侦察扫描", },
	[168467] = {id=168467, zh_CN="开启激光扫描——", },
	[168468] = {id=168468, zh_CN="一阵机械转动的细微声响后，你的视觉仪器中释放出一束激光矩阵，快速扫过小金毛的身体。", },
	[168469] = {id=168469, zh_CN="基础信息检测中——", },
	[168470] = {id=168470, zh_CN="姓名：小金毛，种族妖灵族，性别：雄性，年龄：未知……", },
	[168471] = {id=168471, zh_CN="血脉仇恨作祟", },
	[168472] = {id=168472, zh_CN="不准把我扑倒在地。", },
	[168473] = {id=168473, zh_CN="及时刹车，在你的面前蹲坐下来。", },
	[168474] = {id=168474, zh_CN="要抓我的尾巴吗？", },
	[168475] = {id=168475, zh_CN="恼羞成怒", },
	[168476] = {id=168476, zh_CN="我才没有想玩你的尾巴喵。", },
	[168477] = {id=168477, zh_CN="真的吗？", },
	[168478] = {id=168478, zh_CN="找打！", },
	[168479] = {id=168479, zh_CN="话音刚落，你翘起屁股，匍匐着跃起，朝金灿灿的狄花尾伸出邪恶之爪。", },
	[168480] = {id=168480, zh_CN="傲娇答应", },
	[168481] = {id=168481, zh_CN="你不应该求求我喵？", },
	[168482] = {id=168482, zh_CN="求求你玩小金毛的尾巴呗？", },
	[168483] = {id=168483, zh_CN="好吧，勉为其难答应你啦。", },
	[168484] = {id=168484, zh_CN="话音刚落，你翘起屁股，匍匐着跃起，朝金灿灿的狄花尾伸出邪恶之爪。", },
	[168485] = {id=168485, zh_CN="不要口水！", },
	[168486] = {id=168486, zh_CN="你飞速跑起，避开小金毛的口水攻击，又以急速之姿一把合上小金毛的嘴筒。", },
	[168487] = {id=168487, zh_CN="不要把你的口水沾到我身上，我不喜欢臭臭的。", },
	[168488] = {id=168488, zh_CN="听懂了，你就眨眨眼。", },
	[168489] = {id=168489, zh_CN="小金毛眨眨眼睛。", },
	[168490] = {id=168490, zh_CN="你缓缓松开手，但还是和小金毛保持一定的距离。", },
	[168491] = {id=168491, zh_CN="惊魂一刻", },
	[168492] = {id=168492, zh_CN="啊啊啊！", },
	[168493] = {id=168493, zh_CN="一个不查，你便差点被小金毛的“血盆大口”咬住脑袋。", },
	[168494] = {id=168494, zh_CN="你拍着胸脯，还未从刚刚的惊吓中脱离。", },
	[168495] = {id=168495, zh_CN="嘿，陆地上的家伙，我不在你的食谱里。", },
	[168496] = {id=168496, zh_CN="对不起，对不起，你没有受伤吧。", },
	[168497] = {id=168497, zh_CN="不和你们这种陆地上的家伙计较。", },
	[168498] = {id=168498, zh_CN="老乡见面泪眼汪汪", },
	[168499] = {id=168499, zh_CN="你一把抱起飞扑小金毛，狠狠搓揉着狗狗的脑袋。", },
	[168500] = {id=168500, zh_CN="一人一狗，泪眼汪汪，好似故友相见。", },
	[168501] = {id=168501, zh_CN="你也是妖灵族的？说不定我们还是亲戚呢。", },
	[168502] = {id=168502, zh_CN="论辈分，小金毛说不定是你爷爷的堂叔的隔壁门的小舅子呢……", },
	[168503] = {id=168503, zh_CN="等等，我被绕晕了。", },
	[168504] = {id=168504, zh_CN="我叫小金毛，你呢？", },
	[168505] = {id=168505, zh_CN="行不改名，坐不改姓。", },
	[168506] = {id=168506, zh_CN="行不改名，坐不改姓，%PlayerName是也。", },
	[168507] = {id=168507, zh_CN="……", },
	[168508] = {id=168508, zh_CN="%PlayerName", },
	[168509] = {id=168509, zh_CN="小金毛目光灼灼，望眼欲穿", },
	[168510] = {id=168510, zh_CN="……", },
	[168511] = {id=168511, zh_CN="我的名字是……", },
	[168512] = {id=168512, zh_CN="我的名字是%PlayerName。", },
	[168513] = {id=168513, zh_CN="很高兴遇见你，口吐人言的……小金毛？", },
	[168514] = {id=168514, zh_CN="你握住小金毛的前爪，以示问好。", },
	[168515] = {id=168515, zh_CN="%PlayerName！小金毛记住你啦，你也要记住小金毛哦。", },
	[168516] = {id=168516, zh_CN="你可以向小金毛派发各种各样的委托，小到寻找跑失的宠物，大到获取对手机密……", },
	[168517] = {id=168517, zh_CN="你是什么行走的信息贩子吗？", },
	[168518] = {id=168518, zh_CN="城镇里的八卦风暴，没有小金毛不知晓的。", },
	[168519] = {id=168519, zh_CN="有什么尽管问！", },
	[168520] = {id=168520, zh_CN="那……先说说你吧", },
	[168521] = {id=168521, zh_CN="那……先说说你吧。", },
	[168522] = {id=168522, zh_CN="小金毛吗？", },
	[168523] = {id=168523, zh_CN="信任与否，总要了解一下。", },
	[168524] = {id=168524, zh_CN="你说的对！谨慎，是一位旅人必须的品德。", },
	[168525] = {id=168525, zh_CN="那就让我想一想吧，要从哪里说起呢 ……", },
	[168526] = {id=168526, zh_CN="比如你的年龄，身份，甚至来处。", },
	[168527] = {id=168527, zh_CN="小金毛是一只已经1000岁的犬科妖灵哦。", },
	[168528] = {id=168528, zh_CN="1000岁！", },
	[168529] = {id=168529, zh_CN="居然是可以当先祖的年纪了。", },
	[168530] = {id=168530, zh_CN="居然是个老爷爷！", },
	[168531] = {id=168531, zh_CN="要不要让一让老人家呢？", },
	[168532] = {id=168532, zh_CN="所以小金毛真的可能是你爷爷的堂叔的隔壁门的小舅子。", },
	[168533] = {id=168533, zh_CN="能再说说其它事吗？", },
	[168534] = {id=168534, zh_CN="能再让我多了解点你吗？", },
	[168535] = {id=168535, zh_CN="当然可以啦，让我想想哦。", },
	[168536] = {id=168536, zh_CN="小金毛可是去过很多地方哦。", },
	[168537] = {id=168537, zh_CN="继续问", },
	[168538] = {id=168538, zh_CN="所以是当时决定定居下来的？", },
	[168539] = {id=168539, zh_CN="算吧。确实是当时的见闻让小金毛决定留在这里的。", },
	[168540] = {id=168540, zh_CN="还有吗？", },
	[168541] = {id=168541, zh_CN="有点想不到啦~", },
	[168542] = {id=168542, zh_CN="你可以再问点别的。", },
	[168543] = {id=168543, zh_CN="关于情绪种子", },
	[168544] = {id=168544, zh_CN="请问，你有见过新奇的花种吗？", },
	[168545] = {id=168545, zh_CN="汪？", },
	[168546] = {id=168546, zh_CN="给小金毛描述细节", },
	[168547] = {id=168547, zh_CN="比如形态异于常态的蔷薇，睡莲 ……你有见过吗？", },
	[168548] = {id=168548, zh_CN="抱歉，我没有见过。", },
	[168549] = {id=168549, zh_CN="不过请你相信小金毛，小金毛一定能找到你想要的消息的！", },
	[168550] = {id=168550, zh_CN="谨慎寡言，含糊带过", },
	[168551] = {id=168551, zh_CN="唉，没有见过吗？", },
	[168552] = {id=168552, zh_CN="我痴迷在旅途中寻觅奇异花草，如果你有消息，请一定告知我。", },
	[168553] = {id=168553, zh_CN="包在我身上！", },
	[168554] = {id=168554, zh_CN="有任务委托请找小金毛！", },
	[168555] = {id=168555, zh_CN="诚信经营，老店靠谱！你的请求小金毛已收到，会帮你盯着，汪！", },
	[168556] = {id=168556, zh_CN="询问人文地理", },
	[168557] = {id=168557, zh_CN="那我可以考考你吗？", },
	[168558] = {id=168558, zh_CN="接受挑战！", },
	[168559] = {id=168559, zh_CN="那你和我介绍一下这里的人文地理吧。", },
	[168560] = {id=168560, zh_CN="有没有什么旅途必经必吃榜？", },
	[168561] = {id=168561, zh_CN="那你可问对人啦。", },
	[168562] = {id=168562, zh_CN="此处建在三族交界之处。", },
	[168563] = {id=168563, zh_CN="还有呢？", },
	[168564] = {id=168564, zh_CN="还有呢？", },
	[168565] = {id=168565, zh_CN="这里汇集全星球的美食原料……", },
	[168566] = {id=168566, zh_CN="这时候如果还能咬上一口肉汁四溢的炭火炖肉……要小金毛完成十单委托，都要使命必达！", },
	[168567] = {id=168567, zh_CN="任务？什么任务", },
	[168568] = {id=168568, zh_CN="小金毛要给你留点悬念，自己探索去，汪！", },
	[168569] = {id=168569, zh_CN="没有想问的", },
	[168570] = {id=168570, zh_CN="好哦，下次有需求，我会找你的。", },
	[168571] = {id=168571, zh_CN="再见。", },
	[168572] = {id=168572, zh_CN="再见，汪汪！", },
	[168573] = {id=168573, zh_CN="你来到花海，看到正在忙碌的小金毛。", },
	[168574] = {id=168574, zh_CN="嘿，小金毛！", },
	[168575] = {id=168575, zh_CN="汪！%PlayerName，你来啦！", },
	[168576] = {id=168576, zh_CN="你看啊……", },
	[168577] = {id=168577, zh_CN="数据显示，你与我同住的利处如下：", },
	[168578] = {id=168578, zh_CN="社区设施完善。", },
	[168579] = {id=168579, zh_CN="社区很温馨的。", },
	[168580] = {id=168580, zh_CN="比你的“秘密基地”要热闹便利呢。", },
	[168581] = {id=168581, zh_CN="你可以带着光灵们在小院里玩耍，", },
	[168582] = {id=168582, zh_CN="你这么努力，不就是为了给自己和光灵们更好的生活吗？", },
	[168583] = {id=168583, zh_CN="等待小金毛抉择。", },
	[168584] = {id=168584, zh_CN="给小流浪一个家。", },
	[168585] = {id=168585, zh_CN="你不想给你收留的那些光灵一个安稳的家吗？", },
	[168586] = {id=168586, zh_CN="可是，小金毛收留了太多的光灵。", },
	[168587] = {id=168587, zh_CN="小金毛也不能抛下它们自己去享受……", },
	[168588] = {id=168588, zh_CN="我愿意！", },
	[168589] = {id=168589, zh_CN="我愿意与你和光灵们做邻居。", },
	[168590] = {id=168590, zh_CN="我们一起照顾呀。", },
	[168591] = {id=168591, zh_CN="我愿意。", },
	[168592] = {id=168592, zh_CN="我愿意和你一起照顾光灵们。", },
	[168593] = {id=168593, zh_CN="你要相信自己。", },
	[168594] = {id=168594, zh_CN="你该相信自己的，小金毛。", },
	[168595] = {id=168595, zh_CN="你摸摸小金毛的脑袋。", },
	[168596] = {id=168596, zh_CN="你已经将光灵们照顾得很好了。", },
	[168597] = {id=168597, zh_CN="好友住在隔壁。", },
	[168598] = {id=168598, zh_CN="社区有很多好朋友啊！", },
	[168599] = {id=168599, zh_CN="光灵们也可以交到新朋友。", },
	[168600] = {id=168600, zh_CN="接委托更容易。", },
	[168601] = {id=168601, zh_CN="你来社区以后，就可以接取更多的委托啦。", },
	[168602] = {id=168602, zh_CN="都很不错呀。", },
	[168603] = {id=168603, zh_CN="你静静站定，伸出手。", },
	[168604] = {id=168604, zh_CN="小金毛，搬来与我一起吧。", },
	[168605] = {id=168605, zh_CN="对不起，我还是……", },
	[168606] = {id=168606, zh_CN="你才不是负担。", },
	[168607] = {id=168607, zh_CN="你是不是觉得，搬过来会给我添麻烦？", },
	[168608] = {id=168608, zh_CN="小金毛点头。", },
	[168609] = {id=168609, zh_CN="放轻松点，小狗不要有这么多负担呀。", },
	[168610] = {id=168610, zh_CN="因为喜欢你。", },
	[168611] = {id=168611, zh_CN="所以我才邀请你来做我的邻居。", },
	[168612] = {id=168612, zh_CN="我会想方设法让你卸下压力。", },
	[168613] = {id=168613, zh_CN="不是的，小金毛愿意的。", },
	[168614] = {id=168614, zh_CN="假意示弱，委托小金毛保镖。", },
	[168615] = {id=168615, zh_CN="我们是不是好朋友，是好朋友就听我的！", },
	[168616] = {id=168616, zh_CN="如果你过意不去，那就来当我保镖吧！", },
	[168617] = {id=168617, zh_CN="啊，你害怕呀。", },
	[168618] = {id=168618, zh_CN="对呀，但有你这厉害保镖在，我就不怕了。", },
	[168619] = {id=168619, zh_CN="你看你还有那么多光灵跟着我，多威风啊。", },
	[168620] = {id=168620, zh_CN="我们要称霸社区！", },
	[168621] = {id=168621, zh_CN="快来和我一起称霸社区！", },
	[168622] = {id=168622, zh_CN="身后跟着一群光灵多拉风！", },
	[168623] = {id=168623, zh_CN="喵！", },
	[168624] = {id=168624, zh_CN="如果你过意不去，那就来当我保镖吧，屋院空荡荡的，我也会害怕的。", },
	[168625] = {id=168625, zh_CN="啊，你害怕呀。", },
	[168626] = {id=168626, zh_CN="对呀，但如果有你这么厉害的保镖保护我的话，我就不用害怕了啊。", },
	[168627] = {id=168627, zh_CN="小金毛尾巴晃动着，眼神有一丝松动。", },
	[168628] = {id=168628, zh_CN="你看你还有那么多光灵跟着我，多威风啊。", },
	[168629] = {id=168629, zh_CN="老大就是要护着小弟。", },
	[168630] = {id=168630, zh_CN="猫猫作为狗小弟的老大，", },
	[168631] = {id=168631, zh_CN="就是要护着小弟的！", },
	[168632] = {id=168632, zh_CN="所以我说了才算。", },
	[168633] = {id=168633, zh_CN="你要来做我的邻居，", },
	[168634] = {id=168634, zh_CN="好吧，我答应你。", },
	[168635] = {id=168635, zh_CN="小金毛叼着6张委托单原地打转，", },
	[168636] = {id=168636, zh_CN="像一只追逐尾巴旋转的陀螺。", },
	[168637] = {id=168637, zh_CN="汪，今天要去看精灵奶奶的花开没开，", },
	[168638] = {id=168638, zh_CN="要告诉阿其妈妈，阿其不回家吃饭……", },
	[168639] = {id=168639, zh_CN="小金毛陷入如火燎的心绪中，", },
	[168640] = {id=168640, zh_CN="心里乱糟糟的，", },
	[168641] = {id=168641, zh_CN="汪！嗷呜~", },
	[168642] = {id=168642, zh_CN="询问缘故。", },
	[168643] = {id=168643, zh_CN="发生什么事情了？", },
	[168644] = {id=168644, zh_CN="今天的委托激增，小金毛要做不完了。", },
	[168645] = {id=168645, zh_CN="那你为什么不取消一些呢？", },
	[168646] = {id=168646, zh_CN="担心受伤。", },
	[168647] = {id=168647, zh_CN="快让我看看有没有受伤。", },
	[168648] = {id=168648, zh_CN="呜呜，%PlayerName好痛", },
	[168649] = {id=168649, zh_CN="打趣。", },
	[168650] = {id=168650, zh_CN="嘿，尾巴着火了？这么焦躁。", },
	[168651] = {id=168651, zh_CN="%PlayerName，小金毛要变得不受信任了！呜呜……", },
	[168652] = {id=168652, zh_CN="做不完的话，", },
	[168653] = {id=168653, zh_CN="心里的小金毛会谴责自己的。", },
	[168654] = {id=168654, zh_CN="好吧，那让我们一起来做吧。", },
	[168655] = {id=168655, zh_CN="好吧，那让我们一起来做吧。", },
	[168656] = {id=168656, zh_CN="教小金毛拒绝", },
	[168657] = {id=168657, zh_CN="陪小金毛一起做", },
	[168658] = {id=168658, zh_CN="那你以前都是怎么做的？", },
	[168659] = {id=168659, zh_CN="就……就拿出1000％的努力去做，会做完的。", },
	[168660] = {id=168660, zh_CN="所以你选择折磨自己？", },
	[168661] = {id=168661, zh_CN="其实，跑快点，做快点的话，小金毛应该能做完的。", },
	[168662] = {id=168662, zh_CN="你这样是不对的知道吗？不仅不能保障委托人的委托顺利完成，更重要的！不可以损耗自己的心力与健康去做委托。", },
	[168663] = {id=168663, zh_CN="我知道，可是小金毛做不到拒绝别人。", },
	[168664] = {id=168664, zh_CN="揉搓小金毛的耳朵令它放松，抚摸着打结又沾满草叶的背毛，令你更加心疼小金毛。", },
	[168665] = {id=168665, zh_CN="你挠着小金毛的下巴，趁其不备，将6张委托单抽出。", },
	[168666] = {id=168666, zh_CN="要想办法让小金毛学会拒绝。", },
	[168667] = {id=168667, zh_CN="坏人就让我来做吧。", },
	[168668] = {id=168668, zh_CN="这三个不着急，先去回绝掉。", },
	[168669] = {id=168669, zh_CN="可是 ……宠物光灵没有等到我，会难过的吧。", },
	[168670] = {id=168670, zh_CN="听着笨蛋！现在跟我念——“喵！不干！”", },
	[168671] = {id=168671, zh_CN="啊，会被讨厌的。", },
	[168672] = {id=168672, zh_CN="你是永动机吗？", },
	[168673] = {id=168673, zh_CN="你应该先照顾好自己！", },
	[168674] = {id=168674, zh_CN="我真的做不到，呜呜呜。", },
	[168675] = {id=168675, zh_CN="心疼地摸摸小金毛的脑袋", },
	[168676] = {id=168676, zh_CN="如果我逼你立刻马上去拒绝别人，你真的做不到吗？", },
	[168677] = {id=168677, zh_CN="小金毛真的做不到，呜呜。", },
	[168678] = {id=168678, zh_CN="好吧，那让我们一起来做吧。", },
	[168679] = {id=168679, zh_CN="纯帮忙，不分红。", },
	[168680] = {id=168680, zh_CN="我就帮你完成这三张吧。", },
	[168681] = {id=168681, zh_CN="好呀，结束后我们报酬平分。", },
	[168682] = {id=168682, zh_CN="我只是作为朋友帮你，", },
	[168683] = {id=168683, zh_CN="那可不行！不行不行！", },
	[168684] = {id=168684, zh_CN="要按劳分配才对。", },
	[168685] = {id=168685, zh_CN="这样才能做好搭档啊", },
	[168686] = {id=168686, zh_CN="小金毛的委托小金毛做主。", },
	[168687] = {id=168687, zh_CN="搭档共进退。", },
	[168688] = {id=168688, zh_CN="今天当你一天限定搭档吧。", },
	[168689] = {id=168689, zh_CN="那小金毛要请你吃烤肠。", },
	[168690] = {id=168690, zh_CN="你不准拒绝，就作为我们的搭档契约金。", },
	[168691] = {id=168691, zh_CN="来为我们第一次搭档打个气吧。", },
	[168692] = {id=168692, zh_CN="你举起拳头。", },
	[168693] = {id=168693, zh_CN="快走了，委托要超时了！", },
	[168694] = {id=168694, zh_CN="小金毛红着脸落荒而逃。", },
	[168695] = {id=168695, zh_CN="同行竞争，动力加倍。", },
	[168696] = {id=168696, zh_CN="来比赛看谁先完成吧？", },
	[168697] = {id=168697, zh_CN="好呀好呀，我接受挑战！", },
	[168698] = {id=168698, zh_CN="结束后我们报酬平分。", },
	[168699] = {id=168699, zh_CN="我们现在可是竞争对手，如果我先完成的话，", },
	[168700] = {id=168700, zh_CN="多劳多得，你应得的呀！", },
	[168701] = {id=168701, zh_CN="快快开始，输的人要用委托金请对方吃烤肠。", },
	[168702] = {id=168702, zh_CN="小金毛你……", },
	[168703] = {id=168703, zh_CN="听我指挥。", },
	[168704] = {id=168704, zh_CN="你跳到小金毛头上，一爪捞下所有委托。", },
	[168705] = {id=168705, zh_CN="就让猫猫老大来带领你走向胜利吧。", },
	[168706] = {id=168706, zh_CN="嘿嘿，老大威武。", },
	[168707] = {id=168707, zh_CN="你脚一滑，差点从小金毛头上摔下。", },
	[168708] = {id=168708, zh_CN="咳咳……你就负责当垫脚石吧。", },
	[168709] = {id=168709, zh_CN="它用爪子接住你，将你重新放回背上。", },
	[168710] = {id=168710, zh_CN="收到！猫老大和狗小弟启动！", },
	[168711] = {id=168711, zh_CN="喵！向铁匠铺出发！", },
	[168712] = {id=168712, zh_CN="你和小金毛一起去做委托。", },
	[168713] = {id=168713, zh_CN="又是某天，你临时帮小金毛完成委托。", },
	[168714] = {id=168714, zh_CN="傍晚，当你兜着一口袋星魂回来时。", },
	[168715] = {id=168715, zh_CN="小金毛从你的身后跑来，", },
	[168716] = {id=168716, zh_CN="嘴里叼着装有两根烤肠的袋子。", },
	[168717] = {id=168717, zh_CN="小金毛举起袋子，", },
	[168718] = {id=168718, zh_CN="你从它口中接过烤肠袋。", },
	[168719] = {id=168719, zh_CN="你从它口中接过烤肠袋。", },
	[168720] = {id=168720, zh_CN="呜呜汪汪！", },
	[168721] = {id=168721, zh_CN="你说什么？", },
	[168722] = {id=168722, zh_CN="快尝尝现烤的烤肠！可香了。", },
	[168723] = {id=168723, zh_CN="橙黄的余晖下，你和小金毛席地而坐。", },
	[168724] = {id=168724, zh_CN="一人一狗一同咬开溢出肉汁的烤肠，", },
	[168725] = {id=168725, zh_CN="胡椒洒满的肉香带着一股幸福的味道。", },
	[168726] = {id=168726, zh_CN="今天谢谢你帮我。", },
	[168727] = {id=168727, zh_CN="如果没有你，小金毛都不知道怎么办了。", },
	[168728] = {id=168728, zh_CN="我应该做的，我们是朋友嘛！", },
	[168729] = {id=168729, zh_CN="小金毛喜欢和你一起做委托。", },
	[168730] = {id=168730, zh_CN="如果拜托你的话……", },
	[168731] = {id=168731, zh_CN="你愿意做小金毛的搭档吗？", },
	[168732] = {id=168732, zh_CN="我想和你一直一直一起做委托。", },
	[168733] = {id=168733, zh_CN="不行的，答应你帮你的，没有再收金币的道理。", },
	[168734] = {id=168734, zh_CN="而且你也请我吃烤肠了。", },
	[168735] = {id=168735, zh_CN="我想和你一直一直一起做委托。", },
	[168736] = {id=168736, zh_CN="愿意。", },
	[168737] = {id=168737, zh_CN="嘿嘿！好耶！", },
	[168738] = {id=168738, zh_CN="不愿意。", },
	[168739] = {id=168739, zh_CN="不愿意，也没用！", },
	[168740] = {id=168740, zh_CN="吃了烤肠，我们就算是搭档咯。", },
	[168741] = {id=168741, zh_CN="怎么还强买强卖？", },
	[168742] = {id=168742, zh_CN="小金毛的烤肠可是每次委托做完才能有的奖励，", },
	[168743] = {id=168743, zh_CN="你吃了我的烤肠就是收下我的搭档契约金了！", },
	[168744] = {id=168744, zh_CN="好，我们还要一起吃烤肠。", },
	[168745] = {id=168745, zh_CN="小金毛脑袋拱埋在杂乱野花堆里。", },
	[168746] = {id=168746, zh_CN="蒲公英风吹就散，大车菊太艳丽……", },
	[168747] = {id=168747, zh_CN="小金毛听到脚步声抬起头，", },
	[168748] = {id=168748, zh_CN="狗脑袋轻顶你的腿，将你推到野花堆旁。", },
	[168749] = {id=168749, zh_CN="%PlayerName！你祭奠故人都会准备什么呢？", },
	[168750] = {id=168750, zh_CN="你过去都如何准备的？", },
	[168751] = {id=168751, zh_CN="你过去都会准备什么？鲜花吗？", },
	[168752] = {id=168752, zh_CN="对呀对呀。小金毛会踏遍城镇，", },
	[168753] = {id=168753, zh_CN="打扮他的小窝。", },
	[168754] = {id=168754, zh_CN="他喜欢吃什么吗？", },
	[168755] = {id=168755, zh_CN="人族通常会准备些爱吃的食物。", },
	[168756] = {id=168756, zh_CN="数据库查询：", },
	[168757] = {id=168757, zh_CN="你的旧主人生前有什么很喜欢的事物吗？", },
	[168758] = {id=168758, zh_CN="松露面包夹龙息菇辣酱！", },
	[168759] = {id=168759, zh_CN="或许表达思念的花？", },
	[168760] = {id=168760, zh_CN="每朵花都有属于自己的花语，", },
	[168761] = {id=168761, zh_CN="你可以在花束里选表达思念的花。", },
	[168762] = {id=168762, zh_CN="它的花语是祝愿他人幸福归来。", },
	[168763] = {id=168763, zh_CN="能代表你陪伴的物件就很不错", },
	[168764] = {id=168764, zh_CN="做一只小金毛形象的毛毡狗狗怎么样？", },
	[168765] = {id=168765, zh_CN="和你准备的花束放在一起，", },
	[168766] = {id=168766, zh_CN="在孤单的日子里代替你陪伴着他。", },
	[168767] = {id=168767, zh_CN="这个小金毛喜欢！", },
	[168768] = {id=168768, zh_CN="小金毛高高竖起的尾巴耷拉下来，", },
	[168769] = {id=168769, zh_CN="也是一种参与。", },
	[168770] = {id=168770, zh_CN="结束对话。", },
	[168771] = {id=168771, zh_CN="小金毛绕着你踱步半天，耳朵不时耸动，", },
	[168772] = {id=168772, zh_CN="像是权衡每个选项，", },
	[168773] = {id=168773, zh_CN="它的尾巴尖不自觉轻摆，却无法做出选择。", },
	[168774] = {id=168774, zh_CN="就准备花吧。", },
	[168775] = {id=168775, zh_CN="如果实在纠结的话，就保持过去习俗吧。", },
	[168776] = {id=168776, zh_CN="惊喜要一点点揭晓才令人期待啊。", },
	[168777] = {id=168777, zh_CN="况且你还有很多次要与他见面的机会，", },
	[168778] = {id=168778, zh_CN="不急于一时。", },
	[168779] = {id=168779, zh_CN="%PlayerName，你说得对！", },
	[168780] = {id=168780, zh_CN="只为一句“归来幸福”的寄托。", },
	[168781] = {id=168781, zh_CN="可以下次自己动手做毛毡狗狗哦。", },
	[168782] = {id=168782, zh_CN="这次可以准备花束和美食啊，", },
	[168783] = {id=168783, zh_CN="至于毛毡狗狗，下次再做的话，", },
	[168784] = {id=168784, zh_CN="你可以挑战自己动手呀。", },
	[168785] = {id=168785, zh_CN="自己动手，", },
	[168786] = {id=168786, zh_CN="寄于毛毡小狗的感情与真心一定很浓郁吧。", },
	[168787] = {id=168787, zh_CN="%PlayerName，你说得对！", },
	[168788] = {id=168788, zh_CN="麻烦你帮我照顾一下这些花花，", },
	[168789] = {id=168789, zh_CN="小金毛去去就回。", },
	[168790] = {id=168790, zh_CN="许久，小金毛叼着一个牛皮纸袋回来，", },
	[168791] = {id=168791, zh_CN="纸袋里传来阵阵麦香。", },
	[168792] = {id=168792, zh_CN="只为一句“归来幸福”的寄托。", },
	[168793] = {id=168793, zh_CN="全部都做吧。", },
	[168794] = {id=168794, zh_CN="那就全部都做吧。", },
	[168795] = {id=168795, zh_CN="把你能想到的，最好的，全部都献给他。", },
	[168796] = {id=168796, zh_CN="我和你一起做。", },
	[168797] = {id=168797, zh_CN="%PlayerName，你说得对！", },
	[168798] = {id=168798, zh_CN="麻烦你帮我照顾一下这些花花，", },
	[168799] = {id=168799, zh_CN="小金毛去去就回。", },
	[168800] = {id=168800, zh_CN="将自己的背毛梳落，", },
	[168801] = {id=168801, zh_CN="整理好交到你的手心，", },
	[168802] = {id=168802, zh_CN="小金毛便披着余晖奔向了出去。", },
	[168803] = {id=168803, zh_CN="看！只剩下将你的背毛扎入其中了哦。", },
	[168804] = {id=168804, zh_CN="好耶！", },
	[168805] = {id=168805, zh_CN="你与小金毛一同准备着礼物，小金毛扑进野花团中辨识各种花语。", },
	[168806] = {id=168806, zh_CN="千年春色献君，只为一句“归来幸福”的寄托。", },
	[168807] = {id=168807, zh_CN="你陪着小金毛准备好了礼物。", },
	[168808] = {id=168808, zh_CN="一夜过去——", },
	[168809] = {id=168809, zh_CN="那夜小金毛与他的旧主人诉说了怎样的故事，又是如何介绍你的，不为人知。", },
	[168810] = {id=168810, zh_CN="第二天，你又见到了小金毛。", },
	[168811] = {id=168811, zh_CN="%PlayerName！", },
	[168812] = {id=168812, zh_CN="你的旧主人喜欢你准备的礼物吗？", },
	[168813] = {id=168813, zh_CN="小金毛觉得旧主人会喜欢的！", },
	[168814] = {id=168814, zh_CN="谢谢你。", },
	[168815] = {id=168815, zh_CN="%PlayerName！", },
	[168816] = {id=168816, zh_CN="嗯？", },
	[168817] = {id=168817, zh_CN="可以拜托你和我一起去扫墓吗？", },
	[168818] = {id=168818, zh_CN="答应。", },
	[168819] = {id=168819, zh_CN="这样，可以吗？", },
	[168820] = {id=168820, zh_CN="当然了，", },
	[168821] = {id=168821, zh_CN="好吧，我答应你。", },
	[168822] = {id=168822, zh_CN="得到你的同意，", },
	[168823] = {id=168823, zh_CN="夜渐渐深了。", },
	[168824] = {id=168824, zh_CN="就是这里了！", },
	[168825] = {id=168825, zh_CN="小金毛停在鸭湖城堡前的一处草丛旁，", },
	[168826] = {id=168826, zh_CN="草垛中隐约能看清一块墓碑的形状。", },
	[168827] = {id=168827, zh_CN="旧主人，好久不见。", },
	[168828] = {id=168828, zh_CN="小金毛尾巴晃动，", },
	[168829] = {id=168829, zh_CN="脑袋轻轻拱你，将你带到墓碑前。", },
	[168830] = {id=168830, zh_CN="小金毛今天要给你介绍一个新朋友。", },
	[168831] = {id=168831, zh_CN="他是%PlayerName！小金毛很喜欢他。", },
	[168832] = {id=168832, zh_CN="小金毛知道，你也会喜欢他的，", },
	[168833] = {id=168833, zh_CN="所以将他带来和你认识一下。", },
	[168834] = {id=168834, zh_CN="你轻擦墓碑，以示打招呼。", },
	[168835] = {id=168835, zh_CN="你好。", },
	[168836] = {id=168836, zh_CN="又是小金毛的纪念日。", },
	[168837] = {id=168837, zh_CN="它特地邀请你一起前往。", },
	[168838] = {id=168838, zh_CN="小金毛对着月光整理花束，", },
	[168839] = {id=168839, zh_CN="爪尖不自觉地扣进泥土。", },
	[168840] = {id=168840, zh_CN="其实……小金毛也有点累了。", },
	[168841] = {id=168841, zh_CN="旧主人你曾经说过，", },
	[168842] = {id=168842, zh_CN="如果找到可以契约之人，便往前看吧。", },
	[168843] = {id=168843, zh_CN="旧主人，我找到了。", },
	[168844] = {id=168844, zh_CN="%PlayerName说铃兰花代表着幸福归来，", },
	[168845] = {id=168845, zh_CN="小金毛将它送给你。", },
	[168846] = {id=168846, zh_CN="小金毛会保护着光灵们，", },
	[168847] = {id=168847, zh_CN="%PlayerName会保护小金毛……", },
	[168848] = {id=168848, zh_CN="旧主人你就放心吧。", },
	[168849] = {id=168849, zh_CN="你的手心覆在墓碑上，", },
	[168850] = {id=168850, zh_CN="似穿越千年，与那不知名之人对话。", },
	[168851] = {id=168851, zh_CN="我会照顾好小金毛的，请你放心吧。", },
	[168852] = {id=168852, zh_CN="请看着我吧，", },
	[168853] = {id=168853, zh_CN="我会用事实证明给你看的。", },
	[168854] = {id=168854, zh_CN="你目光落在小金毛身上，", },
	[168855] = {id=168855, zh_CN="它只留给你一个背影。", },
	[168856] = {id=168856, zh_CN="草丛在它狗爪的扒挠下，", },
	[168857] = {id=168857, zh_CN="泥巴被翻起，草叶被搅得七零八落。", },
	[168858] = {id=168858, zh_CN="小金毛，我们回家了。", },
	[168859] = {id=168859, zh_CN="小金毛？", },
	[168860] = {id=168860, zh_CN="汪！", },
	[168861] = {id=168861, zh_CN="我们回家了。", },
