	[168866] = {id=168866, zh_CN="小金毛停在一处草丛旁，草垛中隐约能看清一块墓碑的形状。", },
	[168867] = {id=168867, zh_CN="小金毛用爪垫擦拭着墓碑上的灰尘，将“礼物”一件件摆在墓碑前。", },
	[168868] = {id=168868, zh_CN="旧主人，好久不见。", },
