	[168874] = {id=168874, zh_CN="旧主人你曾经说过，如果找到可以契约之人，便往前看吧。", },
	[168875] = {id=168875, zh_CN="旧主人，我找到了。", },
	[168876] = {id=168876, zh_CN="%PlayerName说铃兰花代表着幸福归来，小金毛将它送给你。", },
	[168877] = {id=168877, zh_CN="小金毛会保护着光灵们，%PlayerName会保护小金毛……旧主人你就放心吧。", },
	[168878] = {id=168878, zh_CN="你的手心覆在墓碑上，似穿越千年，与那不知名之人对话。", },
	[168879] = {id=168879, zh_CN="我会照顾好小金毛的，请你放心吧。", },
	[168880] = {id=168880, zh_CN="请看着我吧，我会用事实证明给你看的。", },
	[168881] = {id=168881, zh_CN="你目光落在小金毛身上，它只留给你一个背影。", },
	[168882] = {id=168882, zh_CN="小金毛？", },
	[168883] = {id=168883, zh_CN="汪！", },
	[168884] = {id=168884, zh_CN="我们回家了。", },
	[168885] = {id=168885, zh_CN="拒绝", },
	[168886] = {id=168886, zh_CN="那好吧。", },
	[168887] = {id=168887, zh_CN="与你告别，小金毛便独自踏上了探寻故人的路途。", },
	[168888] = {id=168888, zh_CN="一夜过去——", },
	[168889] = {id=168889, zh_CN="那夜小金毛与他的旧主人诉说了怎样的故事，又是如何介绍你的，不为人知。", },
	[168890] = {id=168890, zh_CN="第二天，你又见到了小金毛。", },
	[168891] = {id=168891, zh_CN="%PlayerName！", },
	[168892] = {id=168892, zh_CN="你的旧主人喜欢你准备的礼物吗？", },
	[168893] = {id=168893, zh_CN="小金毛觉得旧主人会喜欢的！", },
	[168894] = {id=168894, zh_CN="谢谢你。", },
	[168895] = {id=168895, zh_CN="树下人声鼎沸，", },
	[168896] = {id=168896, zh_CN="你穿过人群，", },
	[168897] = {id=168897, zh_CN="全部抓到市容管理所去！", },
	[168898] = {id=168898, zh_CN="铺上木屑，发酵好的排泄物还能当作花肥。", },
	[168899] = {id=168899, zh_CN="不行不行！夏天臭得都熏了！", },
	[168900] = {id=168900, zh_CN="说不过你这只狗，我们让%PlayerName评评理。", },
	[168901] = {id=168901, zh_CN="啊？", },
	[168902] = {id=168902, zh_CN="%PlayerName你说说，", },
	[168903] = {id=168903, zh_CN="这限制了他们自由……", },
	[168904] = {id=168904, zh_CN="这多臭啊！", },
	[168905] = {id=168905, zh_CN="等到夏天整个城镇都要被糟蹋了。", },
	[168906] = {id=168906, zh_CN="斥责小金毛。", },
	[168907] = {id=168907, zh_CN="你这样只聚焦在光灵身上是不对的！", },
	[168908] = {id=168908, zh_CN="你只是一个妖灵，", },
	[168909] = {id=168909, zh_CN="为什么要多管光灵族的闲事。", },
	[168910] = {id=168910, zh_CN="你们根本没有给予过光灵生存的空间过！", },
	[168911] = {id=168911, zh_CN="他们只能在荒野中，", },
	[168912] = {id=168912, zh_CN="乡间甚至城市的缝隙间生存。", },
	[168913] = {id=168913, zh_CN="与小金毛说道理。", },
	[168914] = {id=168914, zh_CN="城镇不是专属于任何一个种族的，", },
	[168915] = {id=168915, zh_CN="光灵有自由的权力，", },
	[168916] = {id=168916, zh_CN="但是不能打扰到其他种族的正常生活啊。", },
	[168917] = {id=168917, zh_CN="可是！", },
	[168918] = {id=168918, zh_CN="我！呜呜呜……", },
	[168919] = {id=168919, zh_CN="讨论会气氛紧张得仿佛能拧出水来，", },
	[168920] = {id=168920, zh_CN="争论愈发激烈，小金毛的脸蛋涨得通红。", },
	[168921] = {id=168921, zh_CN="小金毛就不明白了，", },
	[168922] = {id=168922, zh_CN="为什么你们总是这么固执，", },
	[168923] = {id=168923, zh_CN="但它的眼瞳里闪烁着坚持和倔强。", },
	[168924] = {id=168924, zh_CN="等到夏天整个城镇都要被糟蹋了。", },
	[168925] = {id=168925, zh_CN="被骨血中的愤怒驱使。", },
	[168926] = {id=168926, zh_CN="果然是蠢狗！", },
	[168927] = {id=168927, zh_CN="自身难保还要去管别的种族的私事。", },
	[168928] = {id=168928, zh_CN="光灵需要你去管了吗？", },
	[168929] = {id=168929, zh_CN="难道说……你要背叛妖灵族，加入光灵？", },
	[168930] = {id=168930, zh_CN="你！呜——汪！", },
	[168931] = {id=168931, zh_CN="小金毛发出警告的低吼。", },
	[168932] = {id=168932, zh_CN="小狗狗生气喵~真是意气用事！", },
	[168933] = {id=168933, zh_CN="无法做到不影响其他种族的生活，", },
	[168934] = {id=168934, zh_CN="当然要被市容管理所收容管理。", },
	[168935] = {id=168935, zh_CN="我们之间的种族仇怨，", },
	[168936] = {id=168936, zh_CN="何必要迁怒到光灵身上，他们是没错的。", },
	[168937] = {id=168937, zh_CN="他们影响到别的种族了，", },
	[168938] = {id=168938, zh_CN="他们影响到我的生活了", },
	[168939] = {id=168939, zh_CN="影响到居民的生活了，他们就是错的。", },
	[168940] = {id=168940, zh_CN="小金毛的尾巴不耐地甩动，", },
	[168941] = {id=168941, zh_CN="趁着所有人都不注意的空挡。", },
	[168942] = {id=168942, zh_CN="讨论会便也不了了之。", },
	[168943] = {id=168943, zh_CN="你深吸口气，逐渐冷静，", },
	[168944] = {id=168944, zh_CN="回想小金毛消失的背影。", },
	[168945] = {id=168945, zh_CN="吐槽小金毛。", },
	[168946] = {id=168946, zh_CN="我干嘛要同情它！", },
	[168947] = {id=168947, zh_CN="真是个不可理喻的狗东西！", },
	[168948] = {id=168948, zh_CN="下次见面，我绝对不给他好果子吃！", },
	[168949] = {id=168949, zh_CN="反思自己。", },
	[168950] = {id=168950, zh_CN="我是不是说得太过了，", },
	[168951] = {id=168951, zh_CN="或许……它有什么苦衷呢？", },
	[168952] = {id=168952, zh_CN="下次再见的时候希望可以解开心结吧。", },
	[168953] = {id=168953, zh_CN="思考小金毛的动机。", },
	[168954] = {id=168954, zh_CN="何必呢？它到底为什么不肯让步？", },
	[168955] = {id=168955, zh_CN="深夜，", },
	[168956] = {id=168956, zh_CN="小金毛正蹲在树旁啃一根磨牙棒，", },
	[168957] = {id=168957, zh_CN="尾巴蔫蔫地耷拉着。", },
	[168958] = {id=168958, zh_CN="你想起上次的争吵——", },
	[168959] = {id=168959, zh_CN="虽然还是不能理解小金毛的观点，", },
	[168960] = {id=168960, zh_CN="但是它的坚守值得去和他道歉。", },
	[168961] = {id=168961, zh_CN="嗨，好久不见。", },
	[168962] = {id=168962, zh_CN="你、你跟踪我？！", },
	[168963] = {id=168963, zh_CN="上次不分青红皂白地斥责你，", },
	[168964] = {id=168964, zh_CN="我表示很抱歉。", },
	[168965] = {id=168965, zh_CN="没事……我们只是坚持的事情不同而已。", },
	[168966] = {id=168966, zh_CN="你故意踩响枯枝，", },
	[168967] = {id=168967, zh_CN="小金毛吓得蹦起来撞到墙，", },
	[168968] = {id=168968, zh_CN="爪子慌乱地把磨牙棒藏到背后。", },
	[168969] = {id=168969, zh_CN="喂，你的磨牙棒沾上灰尘了。", },
	[168970] = {id=168970, zh_CN="你、你跟踪我？！", },
	[168971] = {id=168971, zh_CN="上次我们打架，", },
	[168972] = {id=168972, zh_CN="你被我抓伤的地方养好了吗？", },
	[168973] = {id=168973, zh_CN="那你呢，我咬得挺用力的。", },
	[168974] = {id=168974, zh_CN="你还敢提喵~太痛了喵！", },
	[168975] = {id=168975, zh_CN="小金毛飞快地跑出去，", },
	[168976] = {id=168976, zh_CN="没事，早就已经好了。", },
	[168977] = {id=168977, zh_CN="意外坦白。", },
	[168978] = {id=168978, zh_CN="你戳戳狗爪肉垫", },
	[168979] = {id=168979, zh_CN="为什么非要管这些闲事？", },
	[168980] = {id=168980, zh_CN="它低头抠着青苔，尾巴扫起蒲公英。", },
	[168981] = {id=168981, zh_CN="虽然小金毛还可以成为光灵的避风港，", },
	[168982] = {id=168982, zh_CN="几百年，几千年……", },
	[168983] = {id=168983, zh_CN="但是小金毛也想试试给他们创造一个，", },
	[168984] = {id=168984, zh_CN="不知从哪里掏出垃圾壳上写的计算草稿。", },
	[168985] = {id=168985, zh_CN="嘴硬心软。", },
	[168986] = {id=168986, zh_CN="下次吵架我照样骂你是榆木脑袋！", },
	[168987] = {id=168987, zh_CN="那我就把你偷藏的小鱼干全换成磨牙棒！", },
	[168988] = {id=168988, zh_CN="偶尔望着对方的蠢样笑出声。", },
	[168989] = {id=168989, zh_CN="沉默和解。", },
	[168990] = {id=168990, zh_CN="喂，别真被市容管理所抓去了。", },
	[168991] = {id=168991, zh_CN="放心！他们追不上我！", },
	[168992] = {id=168992, zh_CN="小金毛用湿鼻子蹭你的手心，", },
	[168993] = {id=168993, zh_CN="它忽然警觉竖耳！", },
	[168994] = {id=168994, zh_CN="隐约可见狗尾巴卷着半截磨牙棒。", },
	[168995] = {id=168995, zh_CN="你与小金毛变为了宿敌挚友。", },
	[168996] = {id=168996, zh_CN="你是不是暗恋我？", },
	[168997] = {id=168997, zh_CN="你是不是暗恋我？", },
	[168998] = {id=168998, zh_CN="还送我花呢？", },
	[168999] = {id=168999, zh_CN="才没有。是委托人送给%PlayerName和小金毛的感谢花束和锦旗。", },
	[169000] = {id=169000, zh_CN="是餐厅老板娘的手艺吧？", },
	[169001] = {id=169001, zh_CN="你接过锦旗仔细端详，红绸布上歪歪扭扭绣着“第一好搭档”。", },
	[169002] = {id=169002, zh_CN="委托被感谢了？", },
	[169003] = {id=169003, zh_CN="被委托人送感谢锦旗了嘛？", },
	[169004] = {id=169004, zh_CN="对呀对呀！", },
	[169005] = {id=169005, zh_CN="快看！委托人送的！", },
	[169006] = {id=169006, zh_CN="是餐厅老板娘的手艺吧？", },
	[169007] = {id=169007, zh_CN="你接过锦旗仔细端详，红绸布上歪歪扭扭绣着“第一好搭档”。", },
	[169008] = {id=169008, zh_CN="咦，今天怎么有花？", },
	[169009] = {id=169009, zh_CN="快看！委托人送的！", },
	[169010] = {id=169010, zh_CN="是餐厅老板娘的手艺吧？", },
	[169011] = {id=169011, zh_CN="你接过锦旗仔细端详，红绸布上歪歪扭扭绣着“第一好搭档”。", },
	[169012] = {id=169012, zh_CN="小跟班学会献殷勤了？", },
	[169013] = {id=169013, zh_CN="喵~今天怎么开窍，向老大献殷勤？", },
	[169014] = {id=169014, zh_CN="跳上小金毛脑袋，嗅闻花蕊", },
	[169015] = {id=169015, zh_CN="做的不错，老大很喜欢喵。", },
	[169016] = {id=169016, zh_CN="其实……花花是委托人送的。", },
	[169017] = {id=169017, zh_CN="看！委托人送给我们的锦旗。", },
	[169018] = {id=169018, zh_CN="你踩着小金毛的脑袋，凑上去端详，红绸布上歪歪扭扭绣着“第一好搭档”。", },
	[169019] = {id=169019, zh_CN="汪！今天精灵族奶奶送来了鲜花和锦旗。", },
	[169020] = {id=169020, zh_CN="小闹互损。", },
	[169021] = {id=169021, zh_CN="感谢大家送给我这张锦旗，我会继续努力，不辜负大家的期望的！", },
	[169022] = {id=169022, zh_CN="圆溜溜地盯着你，满心期待", },
	[169023] = {id=169023, zh_CN="也要感谢小金毛的小小付出。", },
	[169024] = {id=169024, zh_CN="尾巴竖起，兴奋地甩出残影", },
	[169025] = {id=169025, zh_CN="当然最需要感谢的还是我，因为我，制作出了委托需要的物品，因为我……", },
	[169026] = {id=169026, zh_CN="%PlayerName坏！", },
	[169027] = {id=169027, zh_CN="小金毛明明也很努力！", },
	[169028] = {id=169028, zh_CN="锦旗在扑闹中掉在地上，小金毛一脚踩上去，留下两只脏兮兮的狗爪印。", },
	[169029] = {id=169029, zh_CN="你与小金毛都低头望去，看着红绸布上灰灰蒙蒙的大爪印，两人陷入沉默……", },
	[169030] = {id=169030, zh_CN="好吧，其实小金毛也做了很多事情，我都有看见的。", },
	[169031] = {id=169031, zh_CN="对不起，不该开这样的玩笑。", },
	[169032] = {id=169032, zh_CN="小金毛也应该珍惜锦旗的。", },
	[169033] = {id=169033, zh_CN="大爪印挺好看的，留着吧。", },
	[169034] = {id=169034, zh_CN="谦虚互夸。", },
	[169035] = {id=169035, zh_CN="请小金毛发表获奖感言。", },
	[169036] = {id=169036, zh_CN="靠着%PlayerName高超的制作技艺……", },
	[169037] = {id=169037, zh_CN="以及小金毛灵敏的嗅觉和迅捷的爆发力……", },
	[169038] = {id=169038, zh_CN="最重要的，我们无与伦比的默契，创造了现在的满分委托答卷！", },
	[169039] = {id=169039, zh_CN="你与小金毛对视两秒，突然破功，笑出声来。", },
	[169040] = {id=169040, zh_CN="我们好像双胞胎……", },
	[169041] = {id=169041, zh_CN="谁能想到居然一字不差呢？", },
	[169042] = {id=169042, zh_CN="证明我们是默契搭档啊。", },
	[169043] = {id=169043, zh_CN="果然是“第一搭档。”", },
	[169044] = {id=169044, zh_CN="同喜同喜。", },
	[169045] = {id=169045, zh_CN="故作谦虚", },
	[169046] = {id=169046, zh_CN="喵~能取得现在的成绩，最大的功劳属于我脚下的忠心跟班。", },
	[169047] = {id=169047, zh_CN="它就是小金毛！现在请小金毛发表获奖感言。", },
	[169048] = {id=169048, zh_CN="跳下，望向小金毛", },
	[169049] = {id=169049, zh_CN="小金毛能如此高效的完成委托，都离不开%PlayerName老大的英明领导……", },
	[169050] = {id=169050, zh_CN="是猫族聪颖的头脑带领着小金毛……没有%PlayerName，就没有如今的成绩。", },
	[169051] = {id=169051, zh_CN="哪有，跟班你也很厉害！", },
	[169052] = {id=169052, zh_CN="不然怎么和%PlayerName老大组成默契搭档呢。", },
	[169053] = {id=169053, zh_CN="果然是“第一搭档”。喵~", },
	[169054] = {id=169054, zh_CN="老大担当。", },
	[169055] = {id=169055, zh_CN="喵~能取得现在的成绩，离不开我的英明领导喵~", },
	[169056] = {id=169056, zh_CN="没错！%PlayerName老大英明！", },
	[169057] = {id=169057, zh_CN="在我机智头脑的指挥下，小金毛利用爆发和速度顺利完成了各种委托。", },
	[169058] = {id=169058, zh_CN="是的汪！%PlayerName老大指挥得好！", },
	[169059] = {id=169059, zh_CN="不错不错，再接再厉！", },
	[169060] = {id=169060, zh_CN="不然怎么和%PlayerName老大组成默契搭档呢。", },
	[169061] = {id=169061, zh_CN="我们的下一目标是星球第一搭档喵~", },
	[169062] = {id=169062, zh_CN="收到！", },
	[169063] = {id=169063, zh_CN="【对话镜头】", },
	[169064] = {id=169064, zh_CN="今天有什么委托喵~", },
	[169065] = {id=169065, zh_CN="今天有两个委托，我选了产品试睡的委托。", },
	[169066] = {id=169066, zh_CN="那另一个呢？", },
	[169067] = {id=169067, zh_CN="是夜巡城堡。", },
	[169068] = {id=169068, zh_CN="虽然你这次选的不错，但是下次还是要先给我看看。", },
	[169069] = {id=169069, zh_CN="我才是老大，知道了没？", },
	[169070] = {id=169070, zh_CN="汪汪！那老大，我们现在就出发咯？", },
	[169071] = {id=169071, zh_CN="跟班出发！", },
	[169072] = {id=169072, zh_CN="收到老大！", },
	[169073] = {id=169073, zh_CN="报告老大，有一个夜巡城堡的委托！", },
	[169074] = {id=169074, zh_CN="向委托地点进发！", },
	[169075] = {id=169075, zh_CN="收到老大！", },
	[169076] = {id=169076, zh_CN="【城堡上奔跑的一猫一狗】", },
	[169077] = {id=169077, zh_CN="【狗窝里抱在一起的猫狗】", },
	[169078] = {id=169078, zh_CN="豪华狗窝里塞进一只不情愿的猫，小金毛窝在狗窝里，像一张顺滑的毛毯。", },
	[169079] = {id=169079, zh_CN="你怎么不和我说是试用狗窝！我堂堂猫族，怎么能屈居在狗窝之中。", },
	[169080] = {id=169080, zh_CN="可是，老大你也没说要看委托细节呀。", },
	[169081] = {id=169081, zh_CN="下次注意！", },
	[169082] = {id=169082, zh_CN="地板怎么能只铺一层绒布呢，太硬了。", },
	[169083] = {id=169083, zh_CN="我会记下的，建议加点绵绒。", },
	[169084] = {id=169084, zh_CN="棉绒太软，对腰不好。", },
	[169085] = {id=169085, zh_CN="包裹性不够，会冷的。", },
	[169086] = {id=169086, zh_CN="好的，增加包裹性要写入建议。", },
	[169087] = {id=169087, zh_CN="也要能及时清理。", },
	[169088] = {id=169088, zh_CN="收到。", },
	[169089] = {id=169089, zh_CN="老大看看还有什么需要修改的？", },
	[169090] = {id=169090, zh_CN="记录的还不错！", },
	[169091] = {id=169091, zh_CN="老大建议的好！", },
	[169092] = {id=169092, zh_CN="你在小金毛背上踩来踩去，最终选中一处缩成一团，滩进“小金毛牌毛毯”中。", },
	[169093] = {id=169093, zh_CN="尾巴毛轻轻拍打地板", },
	[169094] = {id=169094, zh_CN="别吵……", },
	[169095] = {id=169095, zh_CN="立刻停下动作，连呼吸的身体起伏都放轻下来。", },
	[169096] = {id=169096, zh_CN="一夜安眠，第二日你与小金毛上交的爪印评分表上墨迹斑斑。", },
	[169097] = {id=169097, zh_CN="勉强及格。把猫爪按在满分区勉强及格。尾巴偷偷圈住狗爪印", },
	[169098] = {id=169098, zh_CN="老大口是心非。", },
	[169099] = {id=169099, zh_CN="一只枕头砸向小金毛的脸蛋，止住了它呜咽笑语。", },
	[169100] = {id=169100, zh_CN="夜幕下的城墙砖石泛着冷光，你站在小金毛头顶迎风而立。", },
	[169101] = {id=169101, zh_CN="上制高点！芝麻糊要俯瞰全城！", },
	[169102] = {id=169102, zh_CN="任何疑点都逃不过猫族的眼睛！", },
	[169103] = {id=169103, zh_CN="抓稳咯！", },
	[169104] = {id=169104, zh_CN="瓦片哗啦啦掉落惊起夜鸟，两只眼睛忽然在夜色中亮起，盯着瓦片掉落的地方许久，又消失不见。", },
	[169105] = {id=169105, zh_CN="达到塔楼顶点，你从小金毛身上一跃而下，站在墙瓦边缘轻巧地踱步四周，巡查着夜色中的城堡。", },
	[169106] = {id=169106, zh_CN="小金毛跟在你的身后，用尾巴拦在你的身后，随时准备接应你。", },
	[169107] = {id=169107, zh_CN="老大，前面……", },
	[169108] = {id=169108, zh_CN="嘘！不要让可疑之人察觉了……", },
	[169109] = {id=169109, zh_CN="悄悄的，像我一样", },
	[169110] = {id=169110, zh_CN="这砖怎么……", },
	[169111] = {id=169111, zh_CN="你的猫肉垫刚触到飞檐……", },
	[169112] = {id=169112, zh_CN="老大你该减肥了！", },
	[169113] = {id=169113, zh_CN="左转！有可疑黑影！", },
	[169114] = {id=169114, zh_CN="小金毛驮着你，追上了可疑黑影，两只猫族从草丛中跃出，背毛竖起，拱起背随时准备攻击。", },
	[169115] = {id=169115, zh_CN="报告老大！是猫猫在约会！", },
	[169116] = {id=169116, zh_CN="好没有礼貌的家伙！", },
	[169117] = {id=169117, zh_CN="和狗同流合污的叛徒！和狗同流合污的叛徒！", },
	[169118] = {id=169118, zh_CN="今天又没有收获了。", },
	[169119] = {id=169119, zh_CN="有啊，我们可以把城墙瓦片修好，避免别的猫族失足掉下城墙。", },
	[169120] = {id=169120, zh_CN="有道理！", },
	[169121] = {id=169121, zh_CN="出发！目的地调整，任务—修整城墙瓦片。", },
	[169122] = {id=169122, zh_CN="一夜劳作，晨曦突破云层，阳光中裂缝爬满绿藤，开着不知名野花。", },
	[169123] = {id=169123, zh_CN="你和小金毛坐在修好的飞檐上望着初升的晨日。", },
	[169124] = {id=169124, zh_CN="小金毛：今天又是安稳夜！", },
	[169125] = {id=169125, zh_CN="无聊……明晚去警署抓真小偷！", },
	[169126] = {id=169126, zh_CN="又是你俩！给我把墙上的狗爪印擦干净！", },
	[169127] = {id=169127, zh_CN="汪！%PlayerName你回来啦！", },
	[169128] = {id=169128, zh_CN="看我给你准备了什么惊喜！", },
	[169129] = {id=169129, zh_CN="当当！", },
	[169130] = {id=169130, zh_CN="要把自己送给我吗？", },
	[169131] = {id=169131, zh_CN="桀桀桀~哪里跑！", },
	[169132] = {id=169132, zh_CN="惊喜！", },
	[169133] = {id=169133, zh_CN="哇！谢谢可爱的小金毛", },
	[169134] = {id=169134, zh_CN="辛苦还给我准备礼物呢。", },
	[169135] = {id=169135, zh_CN="好奇礼物", },
	[169136] = {id=169136, zh_CN="给我准备了什么呀？", },
	[169137] = {id=169137, zh_CN="是契约球哦！", },
	[169138] = {id=169138, zh_CN="应该我送你暖房礼物的，怎么反过来了？", },
	[169139] = {id=169139, zh_CN="小狗弄错暖房礼物也是很正常的嘛，而且小金毛送你也是一样的呀。", },
	[169140] = {id=169140, zh_CN="好吧，那谢谢你的礼物。", },
	[169141] = {id=169141, zh_CN="【被通缉的小金毛】", },
	[169142] = {id=169142, zh_CN="【情绪花】", },
	[169143] = {id=169143, zh_CN="【流浪光灵的真相】", },
	[169144] = {id=169144, zh_CN="【记忆中的宝藏】", },
	[169145] = {id=169145, zh_CN="【记忆中的宝藏】", },
	[169146] = {id=169146, zh_CN="【忠诚之道】", },
	[169147] = {id=169147, zh_CN="【好蓬松的尾巴毛】", },
	[169148] = {id=169148, zh_CN="被通缉的小金毛", },
	[169149] = {id=169149, zh_CN="小金毛给予你刚获得的情绪花种子", },
	[169150] = {id=169150, zh_CN="得到小金毛的认可，与它前往秘密基地。", },
	[169151] = {id=169151, zh_CN="跟随藏宝图，寻找到商会后巷……", },
	[169152] = {id=169152, zh_CN="跟随藏宝图，寻找到商会后巷……", },
	[169153] = {id=169153, zh_CN="小金毛与你袒露过去的跨越千年故事……", },
	[169154] = {id=169154, zh_CN="初见那只金毛狗，它好像就叫小金毛。", },
	[169155] = {id=169155, zh_CN="你盯着小金毛，心中显现奇怪的画像。", },
	[169156] = {id=169156, zh_CN="草坪上一处泥土格外引人注目——新鲜翻动过的土地。", },
	[169157] = {id=169157, zh_CN="土地下隐藏着的某种未知秘密，让你忍不住想要去探寻。", },
	[169158] = {id=169158, zh_CN="侦查", },
	[169159] = {id=169159, zh_CN="你伸手轻轻拨开表面的浮土，指尖触碰到牛皮纸的触感，你将其捡起，拂去粘在表面的细小的石子。", },
	[169160] = {id=169160, zh_CN="信纸被展开，你心跳加速，信纸上书写的字迹被你读出。", },
	[169161] = {id=169161, zh_CN="给最爱捡破烂的小狗：", },
	[169162] = {id=169162, zh_CN="好久不见，没想到我还会给你留一笔遗产吧。", },
	[169163] = {id=169163, zh_CN="请随意挥霍金币吧，金币换的肉骨头要分给新朋友吃哦！", },
	[169164] = {id=169164, zh_CN="——永远在你打盹时画花脸的坏主人", },
	[169165] = {id=169165, zh_CN="如果误启信封，请取走一些保存费，将留信与金币转交给小金毛。", },
	[169166] = {id=169166, zh_CN="玩家：", },
	[169167] = {id=169167, zh_CN="这是……小金毛的留信？原来小金毛还有旧主人吗？", },
	[169168] = {id=169168, zh_CN="金币已经被拿走，小金毛应该看过信了，是它重新将信封埋入土中的吗？", },
	[169169] = {id=169169, zh_CN="物归原主，归为原位。", },
	[169170] = {id=169170, zh_CN="这就是小金毛找到的信吗？它将其重新埋入土中，也是不想别人知晓这件事吧。", },
	[169171] = {id=169171, zh_CN="给你再埋深点，不用谢谢我哦。", },
	[169172] = {id=169172, zh_CN="离开", },
	[169173] = {id=169173, zh_CN="未知的秘密被人隐藏在土壤下，必然不想被人知晓。而我，只是一个“过客”。", },
	[169174] = {id=169174, zh_CN="默默祝愿这片土地下秘密的旧主人，无论他藏起了什么，都将被妥善珍藏。", },
