	[169188] = {id=169188, zh_CN="小金毛邀请你与它一同扫墓。", },
	[169189] = {id=169189, zh_CN="关于社区公共卫生，你和小金毛各执己见，和它对话。", },
	[169190] = {id=169190, zh_CN="与小金毛对话，了解它据理力争的原因。", },
	[169191] = {id=169191, zh_CN="被居民认证了两人的搭档身份，与小金毛一同庆祝。", },
	[169192] = {id=169192, zh_CN="和天生宿敌的小金毛竟然成为了默契的搭档。", },
