	[169291] = {id=169291, zh_CN="元气少女", },
	[169292] = {id=169292, zh_CN="青葱乐章套装", },
	[169293] = {id=169293, zh_CN="暖阳花叙套装", },
	[169294] = {id=169294, zh_CN="雨后清岚套装", },
	[169295] = {id=169295, zh_CN="桃意序曲套装", },
	[169296] = {id=169296, zh_CN="曼波的清新配色配上利落的工装剪裁，给繁忙的案前工作奏响一曲轻松的变奏。", },
	[169297] = {id=169297, zh_CN="轻盈的刺绣与厚实的灯芯绒将原野上的色彩缝入衣褶，这是一场关于泥土、花香与漫步的温柔约定。", },
	[169298] = {id=169298, zh_CN="套装如雨后初晴的竹林，交领的设计捕捉了古雅的韵味，而工装的线条则裁出了现代的利落。", },
	[169299] = {id=169299, zh_CN="它是午后气泡水的清甜，也是落日余晖下的温柔，收集下盛夏果园的第一抹甜香，制成夏日丰收的序曲。", },
	[169300] = {id=169300, zh_CN="暮色编织", },
	[169301] = {id=169301, zh_CN="柔栗余晖", },
	[169302] = {id=169302, zh_CN="浅金风絮", },
	[169303] = {id=169303, zh_CN="绵云浪潮", },
	[169304] = {id=169304, zh_CN="发丝编织成温婉的侧边鱼骨辫，发丝间透着如水波纹般的微光。", },
	[169305] = {id=169305, zh_CN="整齐的刘海修饰出乖巧的轮廓，在阳光下泛着微微的暖光，透着刚睡醒的慵懒。", },
	[169306] = {id=169306, zh_CN="长发如瀑布般垂落，耳畔轻盈卷起的弧度，仿佛是微风在林间穿行时留下的顽皮痕迹。", },
	[169307] = {id=169307, zh_CN="蓬松的及肩短发像是一团轻柔的棉花糖，梢微微外翘的弧度，定格了微风拂过耳畔的瞬间。", },
	[169308] = {id=169308, zh_CN="云朵贝雷帽", },
	[169309] = {id=169309, zh_CN="轻盈的贝雷帽扣在发间，为略显干练的造型增添了一抹法式的俏皮。", },
	[169310] = {id=169310, zh_CN="叶隙剪影", },
	[169311] = {id=169311, zh_CN="墨竹交领", },
	[169312] = {id=169312, zh_CN="轻纱开衫", },
	[169313] = {id=169313, zh_CN="清爽洒脱的衬衫，蕾丝与衬衫的拼接，宛如阳光穿过树叶留下的斑驳倒影。", },
	[169314] = {id=169314, zh_CN="交领的剪裁利落大方，墨色的竹影斜斜映出，像是晨曦照进了竹林深处。", },
	[169315] = {id=169315, zh_CN="薄款面料上压印着白色花纹，半透明的质感隐约透出内搭，是属于半夏的轻盈。", },
	[169316] = {id=169316, zh_CN="野卉刺绣", },
	[169317] = {id=169317, zh_CN="棉麻袖口上簇拥着手工绣制的彩色小花，明亮得仿佛能感受到原野的芬芳与大地给予的安心感。", },
	[169318] = {id=169318, zh_CN="原野足迹", },
	[169319] = {id=169319, zh_CN="系链工装", },
	[169320] = {id=169320, zh_CN="单宁短裙", },
	[169321] = {id=169321, zh_CN="利落的剪裁让行动更加自如，大腿处摇曳的细链，记录每一次踏青的欢快节奏。", },
	[169322] = {id=169322, zh_CN="工装面料挺括且富有质感，侧边的口袋兼顾了实用与风格，腰间垂下的细碎金链点缀一抹灵动。", },
	[169323] = {id=169323, zh_CN="蔚蓝色的牛仔裙经过特殊的水洗工艺，呈现出天空般的澄澈感，活泼与率性完美平衡。", },
	[169324] = {id=169324, zh_CN="远行底气", },
	[169325] = {id=169325, zh_CN="郊野漫步", },
	[169326] = {id=169326, zh_CN="厚底素瓷", },
	[169327] = {id=169327, zh_CN="暖阳运动鞋", },
	[169328] = {id=169328, zh_CN="穿上这对高帮马丁靴，让丈量世界的每一步都充满了探索未知的底气。", },
	[169329] = {id=169329, zh_CN="高帮帆布鞋采用了经典组合，厚实的鞋底踏过松软的草地，化作对郊野向往的信号。", },
	[169330] = {id=169330, zh_CN="这双厚底鞋如同上釉的素色瓷器般温润，亮面的皮质反射着低调的光。", },
	[169331] = {id=169331, zh_CN="干净的鞋面捕捉到正午的日光，陪你走过长长的街道，度过平凡的一天。", },
	[169332] = {id=169332, zh_CN="赶海余晖套装", },
	[169333] = {id=169333, zh_CN="书页叶签套装", },
	[169334] = {id=169334, zh_CN="初春秩序套装", },
	[169335] = {id=169335, zh_CN="深海波影套装", },
	[169336] = {id=169336, zh_CN="属于少年人的赶海时光，白色的浪花在脚边跳跃，风里满是海盐与自由的气息。", },
	[169337] = {id=169337, zh_CN="厚实的针织纹理包裹着少年，带着森林特有的松木香，像是一枚被夹在旧书页里的干燥叶签。", },
	[169338] = {id=169338, zh_CN="雨后湿润的春意与干净的霜雪交织出一种宁静的秩序感，霜雪下藏着一整个春日的萌芽。", },
	[169339] = {id=169339, zh_CN="潜入静谧的深海，深邃与静默交织，月光在水面碎成粼粼波影。", },
	[169340] = {id=169340, zh_CN="湿润海风", },
	[169341] = {id=169341, zh_CN="岩色质感", },
	[169342] = {id=169342, zh_CN="穿林影踪", },
	[169343] = {id=169343, zh_CN="流波子夜", },
	[169344] = {id=169344, zh_CN="深棕色的短发带着微微的卷度，像是被湿润的海风随手揉乱，透着几分随性。", },
	[169345] = {id=169345, zh_CN="深褐色的短发有着如同岩石般沉稳的质感，让人感到干净与安心。", },
	[169346] = {id=169346, zh_CN="发丝被精心打理出利落的层次，像是在静谧林间穿行的影子，透着处变不惊的沉稳。", },
	[169347] = {id=169347, zh_CN="沉静的深蓝色短发如同被海浪打湿的子夜，发丝间闪烁着幽微的光泽。", },
	[169348] = {id=169348, zh_CN="暮色渐变", },
	[169349] = {id=169349, zh_CN="落叶轮廓", },
	[169350] = {id=169350, zh_CN="霜降风衣", },
	[169351] = {id=169351, zh_CN="静默海底", },
	[169352] = {id=169352, zh_CN="细腻的菱形针织纹路像是有节奏的波浪，将一整个黄昏的色彩都穿在了身上。", },
	[169353] = {id=169353, zh_CN="经典粗棒针织出了厚实的麻花纹理，侧边的松针绿线条划出了森林的轮廓，展现晚秋最亮眼的一抹色彩。", },
	[169354] = {id=169354, zh_CN="立领的设计挺拔有力，面料平整且富有垂坠感，如同初雪覆盖的旷野般洁净。", },
	[169355] = {id=169355, zh_CN="立领的设计挺拔而克制，领口至胸前由浅入深，细密的几何暗纹如同层层推开的浪花。", },
	[169356] = {id=169356, zh_CN="苔痕褶皱", },
	[169357] = {id=169357, zh_CN="面料上分布着细密的风琴褶皱，像是雨后被风吹皱的池水，为沉稳的基调注入了一抹跳脱的生机。", },
	[169358] = {id=169358, zh_CN="晒干海盐", },
	[169359] = {id=169359, zh_CN="泥炭长裤", },
	[169360] = {id=169360, zh_CN="砂石纹理", },
	[169361] = {id=169361, zh_CN="条纹投影", },
	[169362] = {id=169362, zh_CN="裤脚折起，挺括的直筒剪裁利落而纯粹，如同被阳光晒干的洁白海盐。", },
	[169363] = {id=169363, zh_CN="略显厚重的暗褐色面料经过特殊的洗水工艺，呈现出如同潮湿泥土般的深邃色泽。", },
	[169364] = {id=169364, zh_CN="利落的直筒线条与白色的腰带相衔接，布料纹理清晰，有着如砂石般的颗粒感与韧性。", },
	[169365] = {id=169365, zh_CN="合体的剪裁勾勒出腿部线条，分布的纵向条纹，如光线穿透深海留下的笔直投影。", },
	[169366] = {id=169366, zh_CN="潮汐起伏", },
	[169367] = {id=169367, zh_CN="林间浮云", },
	[169368] = {id=169368, zh_CN="系带皮靴", },
	[169369] = {id=169369, zh_CN="拼色皮鞋", },
	[169370] = {id=169370, zh_CN="鞋身交织着撞色的浪花纹理，踩上它，仿佛能听见潮汐在脚下起伏的声音。", },
	[169371] = {id=169371, zh_CN="低帮板鞋像是在林间空地上停留的一片浮云。干净的线条没有一丝冗杂。", },
	[169372] = {id=169372, zh_CN="皮靴耐脏实用，交叉绑带带来稳固包裹感，行走时更像是划过雪地的利落辙痕。", },
	[169373] = {id=169373, zh_CN="亮面皮革相互拼接，稳重而轻盈，简约的金属带扣增加了视觉的层次感。", },
	[169374] = {id=169374, zh_CN="霓虹音浪套装", },
	[169375] = {id=169375, zh_CN="深夜街头，霓虹光影随节奏闪烁，是滑板滑过路面的金属摩擦声，也是耳机里循环的电子音效。", },
	[169376] = {id=169376, zh_CN="双响跃动", },
	[169377] = {id=169377, zh_CN="少女长发扎成高高的双马尾，略显凌乱的碎发修饰着眉眼，随着跳跃的步履在风中摆动。", },
	[169378] = {id=169378, zh_CN="文字电波", },
	[169379] = {id=169379, zh_CN="短袖上衣印有银色字母，内里叠穿着修身长袖，大胆撞色，甜美张扬。", },
	[169380] = {id=169380, zh_CN="破洞布带", },
	[169381] = {id=169381, zh_CN="水洗做旧的牛仔裤上，肆意的破洞、细碎毛边、细金属链与布带装饰，诉说着街头故事。", },
	[169382] = {id=169382, zh_CN="低音鼓点", },
	[169383] = {id=169383, zh_CN="拼接的厚底设计与霓虹线条相互呼应，每步都像是踏在合成器的低音鼓点上。", },
	[169384] = {id=169384, zh_CN="叠戴绳链", },
	[169385] = {id=169385, zh_CN="黑色细绳与银色细链双层叠戴，圆润的黑曜石珠子与闪亮的银质方块错落分布。", },
	[169386] = {id=169386, zh_CN="皮质腕扣", },
	[169387] = {id=169387, zh_CN="编织皮绳与平滑的皮带交错缠绕，中央镶嵌的一小块金属铭牌记录着不为人知的代码。", },
	[169388] = {id=169388, zh_CN="金脉花瓣", },
	[169389] = {id=169389, zh_CN="五瓣花形的金属底托精细勾勒出花脉的走向，它静静垂落在耳际，点缀着圆润的珠滴。", },
	[169390] = {id=169390, zh_CN="花石皮绳", },
	[169391] = {id=169391, zh_CN="芽尖颈圈", },
	[169392] = {id=169392, zh_CN="彩珠蝴蝶结", },
	[169393] = {id=169393, zh_CN="叠戴的皮质颈绳上，点缀着松石、瓷珠与圆环，花朵在呼吸起伏间折射着细碎的光芒。", },
	[169394] = {id=169394, zh_CN="丝绒带紧贴颈间，正中镶嵌着的明亮钻石，像是竹林尖头的一抹嫩芽，在晨露中闪烁着微光。", },
	[169395] = {id=169395, zh_CN="缎带系成小巧的蝴蝶结，轻盈地环绕在颈间，细长的银链串起剔透的彩色晶珠。", },
	[169396] = {id=169396, zh_CN="凝光晨星", },
	[169397] = {id=169397, zh_CN="由多色珠粒精心串起的手链，在手腕上随着动作轻轻晃动，如晨星般闪烁。", },
	[169398] = {id=169398, zh_CN="捉蝶少女", },
	[169399] = {id=169399, zh_CN="灵境蝶踪套装", },
	[169400] = {id=169400, zh_CN="森林深处的引路者，掌心轻拢星辉，从不强求捕捉，蝴蝶便自在栖落于他指尖。", },
	[169401] = {id=169401, zh_CN="蝶栖浅梦", },
	[169402] = {id=169402, zh_CN="柔卷长发漫落肩头，发丝间萦绕细碎星辉，似藏着灵境深处未说尽的温柔。", },
	[169403] = {id=169403, zh_CN="浮光翩跹", },
	[169404] = {id=169404, zh_CN="层叠薄纱织就林间裙摆，薄纱似晨雾朦胧，风拂过时，恍有蝶绕浮光缓缓翩跹。", },
	[169405] = {id=169405, zh_CN="蝶踪残影", },
	[169406] = {id=169406, zh_CN="鞋身嵌上薄薄蝉翼，步履轻踏林间，每一步都像惊扰不散的蝶踪残影。", },
	[169407] = {id=169407, zh_CN="轻纱挽萤", },
	[169408] = {id=169408, zh_CN="轻纱缠绕臂弯，缀小巧蝶翼装饰，温婉垂落，抬手间便似有蝴蝶甘愿栖停。", },
	[169409] = {id=169409, zh_CN="莹萤振翅", },
	[169410] = {id=169410, zh_CN="渐变蝶翼舒展身后，自带朦胧流光特效，振翅时散落细碎粉萤光点。", },
	[169411] = {id=169411, zh_CN="芳蝶缀枝", },
	[169412] = {id=169412, zh_CN="花枝缠绕成冠，缀着半透蝶翼碎饰，微光浅浅流转，像是特意为引蝶之人编织的林间冠冕。", },
	[169413] = {id=169413, zh_CN="星涟蝶影", },
	[169414] = {id=169414, zh_CN="细腻颈圈缠拢颈间，点缀细碎星辉与蝶影纹路，清浅温婉，衬得脖颈纤细。", },
	[169415] = {id=169415, zh_CN="成男11发型", },
	[169416] = {id=169416, zh_CN="成男11发型的描述", },
	[169417] = {id=169417, },
	[169418] = {id=169418, zh_CN="森间学府·淑女", },
	[169419] = {id=169419, zh_CN="俏皮的短发搭配严谨的西装校服，展现出优等生独有的干练与灵动，领口的蝴蝶结紧锁着少女的奇思妙想。", },
	[169420] = {id=169420, zh_CN="森间学府·才子", },
	[169421] = {id=169421, zh_CN="挺括的长裤与考究的针织马甲，层次分明的叠穿设计，将学院风的绅士礼仪与少年的不羁完美平衡。", },
	[169422] = {id=169422, zh_CN="樱木短发", },
	[169423] = {id=169423, zh_CN="短发俏皮灵动，发尾自然的弧度既修饰脸型又显得元气满满。", },
	[169424] = {id=169424, zh_CN="青藤礼服·淑女", },
	[169425] = {id=169425, zh_CN="统一的色调，修身的剪裁搭配校徽刺绣，象征着常青藤学府的生命力。", },
	[169426] = {id=169426, zh_CN="格纹百褶裙", },
	[169427] = {id=169427, zh_CN="整齐的苏格兰格纹，压褶平整且富有垂感，是校园里永不褪色的时尚符号。", },
	[169428] = {id=169428, zh_CN="长筒棉袜", },
	[169429] = {id=169429, zh_CN="棉质的干净袜身点缀束口，与裙摆呼应，展现出优越的腿部曲线。", },
	[169430] = {id=169430, zh_CN="英伦皮鞋", },
	[169431] = {id=169431, zh_CN="经典的乐福鞋款增加了一对俏皮的流苏，漆皮耐穿且富有复古韵味。", },
	[169432] = {id=169432, zh_CN="皮革书包·淑女", },
	[169433] = {id=169433, zh_CN="手工皮革制作的书包，侧边点缀着精致的刺绣小花，装满了少女的日记与课本。", },
	[169434] = {id=169434, zh_CN="合规碎发", },
	[169435] = {id=169435, zh_CN="修剪利落而不失层次感，透着一种拒人于千里之外却又极其聪慧的学霸气质。", },
	[169436] = {id=169436, zh_CN="绅士马甲", },
	[169437] = {id=169437, zh_CN="在严肃的制服外壳下叠穿的衬衫与马甲，既有少年的俏皮，也不失名校精英的端庄。", },
	[169438] = {id=169438, zh_CN="青藤礼服·才子", },
	[169439] = {id=169439, zh_CN="统一的色调，修身的剪裁搭配校徽刺绣，象征着常青藤学府的生命力。", },
	[169440] = {id=169440, zh_CN="制服长裤", },
	[169441] = {id=169441, zh_CN="经典的直筒修身版型，低调而百搭，是校园里永不褪色的时尚符号。", },
	[169442] = {id=169442, zh_CN="系带皮鞋", },
	[169443] = {id=169443, zh_CN="考究的牛津鞋设计，深浅交替的皮革，每一步都踏出坚定的学术信心。", },
	[169444] = {id=169444, zh_CN="皮革书包·才子", },
	[169445] = {id=169445, zh_CN="手工皮革制作的书包，金属扣环坚固耐用，是探索知识荒原的最佳伙伴。", },
	[169446] = {id=169446, zh_CN="名门淑女", },
	[169447] = {id=169447, zh_CN="儒雅才子", },
	[169448] = {id=169448, },
	[169449] = {id=169449, },
	[169450] = {id=169450, },
	[169451] = {id=169451, },
	[169452] = {id=169452, },
	[169453] = {id=169453, zh_CN="亲爱的，你出现的时机真完美。", },
	[169454] = {id=169454, zh_CN="想你带来的新情报，或者你？", },
	[169455] = {id=169455, zh_CN="你总能让我感到惊喜，亲爱的。", },
	[169456] = {id=169456, zh_CN="贵客莅临，月影蓬荜生辉。", },
	[169457] = {id=169457, zh_CN="看到你，甜点都变甜了。", },
	[169458] = {id=169458, zh_CN="偶尔也会想起你这个有趣的家伙。", },
	[169459] = {id=169459, zh_CN="你的价值，我一直记在账上。", },
	[169460] = {id=169460, zh_CN="这种时候出现，可没折扣。", },
	[169461] = {id=169461, zh_CN="别问这种没营养的问题，亲爱的。", },
	[169462] = {id=169462, zh_CN="我现在只想一个人待着。", },
	[169463] = {id=169463, zh_CN="心情不佳，别跟我搭话。", },
	[169464] = {id=169464, },
	[169465] = {id=169465, zh_CN="汪！想死你了汪！", },
	[169466] = {id=169466, zh_CN="汪！小金毛永远欢迎你！", },
	[169467] = {id=169467, zh_CN="汪！快给小金毛讲讲新见闻！", },
	[169468] = {id=169468, zh_CN="汪汪！欢迎回来，太棒了汪！", },
	[169469] = {id=169469, zh_CN="汪！看到你，尾巴就停不下来！", },
	[169470] = {id=169470, zh_CN="汪，见到你小金毛就安心多啦汪。", },
	[169471] = {id=169471, zh_CN="汪，一千年里的老朋友汪。", },
	[169472] = {id=169472, zh_CN="汪呜，你怎么才来看小金毛汪。", },
	[169473] = {id=169473, zh_CN="汪！刚才想你想得心好乱汪！", },
	[169474] = {id=169474, zh_CN="这么久不来，小金毛不理你汪！", },
	[169475] = {id=169475, zh_CN="汪汪汪！小金毛正烦呢！", },
	[169476] = {id=169476, },
	[169477] = {id=169477, zh_CN="利润翻倍，天气自然美妙无比。", },
	[169478] = {id=169478, zh_CN="气候宜人，适合举行大型拍卖。", },
	[169479] = {id=169479, zh_CN="让人想做点有趣投资。", },
	[169480] = {id=169480, zh_CN="此时相遇，确实是美妙的天气。", },
	[169481] = {id=169481, zh_CN="这种天气适合一起喝杯热茶。", },
	[169482] = {id=169482, zh_CN="和你一样迷人，亲爱的。", },
	[169483] = {id=169483, zh_CN="无论阴晴，生意都要继续。", },
	[169484] = {id=169484, zh_CN="阳光太刺眼，让我不舒服。", },
	[169485] = {id=169485, zh_CN="天气好而已，我心情可未必。", },
	[169486] = {id=169486, zh_CN="暴雨将至前，总是这般平静。", },
	[169487] = {id=169487, zh_CN="闷热得让人心烦，别跟我搭话。", },
	[169488] = {id=169488, },
	[169489] = {id=169489, zh_CN="汪！这天气适合出去跑跑！", },
	[169490] = {id=169490, zh_CN="汪！阳光闻起来香香的！", },
	[169491] = {id=169491, zh_CN="好天气最适合出外勤汪！", },
	[169492] = {id=169492, zh_CN="汪！喜欢阳光明媚的天气！", },
	[169493] = {id=169493, zh_CN="这种天气最适合守护城市汪！", },
	[169494] = {id=169494, zh_CN="汪……想睡个长长的午觉汪。", },
	[169495] = {id=169495, zh_CN="汪，小金毛欢迎你！", },
	[169496] = {id=169496, zh_CN="汪呜，阳光太刺眼了汪。", },
	[169497] = {id=169497, zh_CN="汪！好热好热汪！", },
	[169498] = {id=169498, zh_CN="汪！火气直冒汪！", },
	[169499] = {id=169499, zh_CN="汪汪！想把太阳吞下去汪！", },
	[169500] = {id=169500, },
	[169501] = {id=169501, zh_CN="好久不见？", },
	[169502] = {id=169502, zh_CN="嗨？", },
	[169503] = {id=169503, zh_CN="你在做什么呢？", },
	[169504] = {id=169504, zh_CN="今天天气不错。", },
	[169505] = {id=169505, zh_CN="最近过得怎么样？", },
	[169506] = {id=169506, zh_CN="好久不见，想我了吗？", },
	[169507] = {id=169507, zh_CN="这里风景真好，对吧？", },
	[169508] = {id=169508, zh_CN="你看起来心情不错。", },
	[169509] = {id=169509, zh_CN="今天真的很安静啊。", },
	[169510] = {id=169510, },
	[169511] = {id=169511, zh_CN="你现在在想什么？", },
	[169512] = {id=169512, zh_CN="我觉得你好像有点心事。", },
	[169513] = {id=169513, zh_CN="你现在的表情看起来很微妙。", },
	[169514] = {id=169514, zh_CN="幻彩调色师", },
	[169515] = {id=169515, zh_CN="有好天气，心情都变好啦。", },
	[169516] = {id=169516, zh_CN="嘿嘿，喜欢今天的天气。", },
	[169517] = {id=169517, zh_CN="这么好的天气，带我出去吧。", },
	[169518] = {id=169518, zh_CN="弦音协奏者", },
	[169519] = {id=169519, zh_CN="有点想打瞌睡。", },
	[169520] = {id=169520, zh_CN="今天天气真好，想出去。", },
	[169521] = {id=169521, zh_CN="浑身都暖洋洋的。", },
	[169522] = {id=169522, zh_CN="暮色挽歌", },
	[169523] = {id=169523, zh_CN="微卷长发如陈年红酒在暗夜中流淌，一缕发丝漫不经心地垂落在锁骨一侧，带着古老贵族特有的优雅。", },
	[169524] = {id=169524, zh_CN="交响诗回音", },
	[169525] = {id=169525, zh_CN="摇曳的暗金齿轮流苏悬挂于耳际，每当风拂过，仿佛能听见时间在废墟中剥落的细微声响。", },
	[169526] = {id=169526, zh_CN="虚妄之拥", },
	[169527] = {id=169527, zh_CN="半透明的蕾丝手套顺着手臂延伸，边缘是不规则的蔷薇花刺边。抬手之间，黑夜仿佛在指缝间缓缓漏沙。", },
	[169528] = {id=169528, zh_CN="荆棘誓约", },
	[169529] = {id=169529, zh_CN="丝绒质地的宽幅颈圈，中央缠绕着荆棘造型的冷银雕花，犹如月光下泛着寒芒的铁线莲。", },
	[169530] = {id=169530, zh_CN="幽影足音", },
	[169531] = {id=169531, zh_CN="皮革与雕花托起极细的鞋跟，鞋面的宝石在裙摆遮掩下闪烁。", },
	[169532] = {id=169532, zh_CN="织夜华章", },
	[169533] = {id=169533, zh_CN="重磅缎面与织锦在腰间重叠堆积，不对称的波浪裙摆层层荡开。裙底刺绣的藤蔓若隐若现，像是深夜静默流淌的暗河。", },
	[169534] = {id=169534, zh_CN="幽夜交响诗套装", },
	[169535] = {id=169535, zh_CN="提琴声暗哑，指针在虚无中滴答作响，在钟声停滞的永夜里，她用寂静的音符，唤醒石缝中沉睡的古老蔷薇。", },
	[169536] = {id=169536, zh_CN="无形约束", },
	[169537] = {id=169537, zh_CN="微雕藤蔓攀附在纤细的手臂上，碎钻点缀其间。手指轻抬，在空中拉扯出晶莹的轨迹。", },
	[169538] = {id=169538, zh_CN="折光蝴蝶结", },
	[169539] = {id=169539, zh_CN="腰后的巨大半透明幻彩蝴蝶结，薄若轻烟，风吹过时，它在阳光下投射出五彩交织的斑斓梦影。", },
	[169540] = {id=169540, zh_CN="泪光折射", },
	[169541] = {id=169541, zh_CN="细长的碎钻流苏从耳际摇曳而下，将周围单调的光线拆解成五彩的虹芒。", },
	[169542] = {id=169542, zh_CN="碎光回响", },
	[169543] = {id=169543, zh_CN="层叠交错的冷银线圈在额前微微悬浮，仿佛是灵感在空气中凝固留下的银质残影。", },
	[169544] = {id=169544, zh_CN="纱光织影", },
	[169545] = {id=169545, zh_CN="由细碎折光交织而成的半透明礼帽，轻覆于一侧发梢，帽沿垂落若隐若现的蕾丝网纱。", },
	[169546] = {id=169546, zh_CN="云朵留白", },
	[169547] = {id=169547, zh_CN="如云朵般蓬松堆叠的纯白颈饰，在斑斓多姿的华服之上留下了唯一的寂静。", },
	[169548] = {id=169548, zh_CN="丝带蛋糕", },
	[169549] = {id=169549, zh_CN="蓬松丝带层层缱绻，温柔缠绕脚踝，粗砺白绳细密堆叠，织出蛋糕般软糯厚实的厚底。", },
	[169550] = {id=169550, zh_CN="幻泡琉璃", },
	[169551] = {id=169551, zh_CN="裙摆如同一颗正在呼吸的彩色气泡，外罩一层注入了流光粒子的偏光薄纱，变幻出无数种自我的色彩。", },
	[169552] = {id=169552, zh_CN="折光琉璃套装", },
	[169553] = {id=169553, zh_CN="她是行走在黑白世界里的色彩捕手，她将自己化作三棱镜，把每一束微光拆解成属于自己的万千斑斓。", },
	[169554] = {id=169554, zh_CN="纯白约定", },
	[169555] = {id=169555, zh_CN="乖巧的短款白色礼服手套，手腕处收拢并环绕着一圈轻柔的白色荷叶边，正中装饰着精致的明黄色小蝴蝶结。", },
	[169556] = {id=169556, zh_CN="织梦礼蝴蝶结", },
	[169557] = {id=169557, zh_CN="多层裙幅缎带自然垂落至裙底的巨型绸缎蝴蝶结，在起舞时伴着微风轻轻起伏，将童话的序幕缓缓拉开。", },
	[169558] = {id=169558, zh_CN="滴答节拍", },
	[169559] = {id=169559, zh_CN="每当身体移动，耳际便会传来极细小的金属碰撞声，仿佛时间在玩具屋里快乐地打着节拍。", },
	[169560] = {id=169560, zh_CN="童真蝴蝶结", },
	[169561] = {id=169561, zh_CN="覆于发顶的超大提花蝴蝶结，点缀着交错的格子缎带与精细的手工抽褶蕾丝网，优雅而充满童话感。", },
	[169562] = {id=169562, zh_CN="齿轮重奏", },
	[169563] = {id=169563, zh_CN="宽幅的多层手工打褶白色荷叶边领圈，中央交织着明黄色的细窄丝带。", },
	[169564] = {id=169564, zh_CN="盘旋蕾丝", },
	[169565] = {id=169565, zh_CN="哑光玩偶皮鞋，丝带以交叉交叉的绑带方式顺着小腿盘旋而上，鞋头点缀着蓬松的蕾丝蝴蝶结。", },
	[169566] = {id=169566, zh_CN="动物偶戏", },
	[169567] = {id=169567, zh_CN="层叠繁复的公主糖果大蓬裙，腰间收拢成花瓣状。可爱的发条小熊和松鼠，在群上跳起舞来。", },
	[169568] = {id=169568, zh_CN="交叉旋律", },
	[169569] = {id=169569, zh_CN="中筒蕾丝袜顶端装饰着一圈蓬松的玩偶荷叶边花口，丝带呈交叉网格状优雅地缠绕在修长的双腿上。", },
	[169570] = {id=169570, zh_CN="发条人偶套装", },
	[169571] = {id=169571, zh_CN="她是旧玩具屋深处最珍贵的人偶，她随着拧紧的发条，翩翩独自舞到谢幕的一刻。", },
	[169572] = {id=169572, zh_CN="碎火微澜", },
	[169573] = {id=169573, zh_CN="它仿佛是流星划过夜空留下的无声残影，在寂静中悄悄闪烁。", },
	[169574] = {id=169574, zh_CN="留光纱袖", },
	[169575] = {id=169575, zh_CN="乳白蕾丝泡泡袖在指尖处收拢，当双臂抬起，朦胧的质感宛如夜雾中不小心捕捉到的一抹月光。", },
	[169576] = {id=169576, zh_CN="星焰垂珞", },
	[169577] = {id=169577, zh_CN="晚风揉碎升空的烟花星火，垂落细碎焰絮，悬于发梢，是夜色递来的温柔邀约。", },
	[169578] = {id=169578, zh_CN="盛放刹那", },
	[169579] = {id=169579, zh_CN="戴在发顶的星芒王冠，仿佛是千万颗烟火在最绚烂一刻突然定格凝固而成的冰晶。", },
	[169580] = {id=169580, zh_CN="缀夜星链", },
	[169581] = {id=169581, zh_CN="环绕在白皙颈间的层叠碎钻与泪滴状垂流，如同无数颗滑落天际的星辰在夜空中拉扯出的剔透银河。", },
	[169582] = {id=169582, zh_CN="尘埃足迹", },
	[169583] = {id=169583, zh_CN="细带优雅缠绕脚踝，托起鞋头处碎钻簇拥的星芒花簇。足间留存着星火燃尽后余下的微末暖意。", },
	[169584] = {id=169584, zh_CN="希光织锦", },
	[169585] = {id=169585, zh_CN="上身是绣着金属星轨的重磅束腰，下摆层叠交织着暗花织锦，裙身上点缀着如落星般的璀璨晶石，走动时，宛如一整场银河盛宴在足尖绽放。", },
	[169586] = {id=169586, zh_CN="余烬烟火套装", },
	[169587] = {id=169587, zh_CN="当夜幕垂落、万籁归于沉寂，消散在夜色里的细碎美好，尽数凝织成裙摆间熠熠长存的星光盛宴。", },
	[169588] = {id=169588, zh_CN="涂鸦少年", },
	[169589] = {id=169589, zh_CN="隐居雅士", },
	[169590] = {id=169590, zh_CN="裂变涂鸦套装", },
	[169591] = {id=169591, zh_CN="大胆的涂鸦元素与机能感十足的束带结合，彰显不被定义、勇于自我的态度。", },
	[169592] = {id=169592, zh_CN="凌乱短发", },
	[169593] = {id=169593, zh_CN="短促有力的修剪风格，透出一种永不妥协的野性与少年感。", },
	[169594] = {id=169594, zh_CN="律动活力", },
	[169595] = {id=169595, zh_CN="简约纯色，百搭版型，日常出行轻松解锁满格动感活力。", },
	[169596] = {id=169596, zh_CN="焦点涂鸦", },
	[169597] = {id=169597, zh_CN="鲜艳撞色涂鸦邂逅硬朗皮质，让你化身霓虹灯下最亮眼的视觉焦点。", },
	[169598] = {id=169598, zh_CN="潮行羁途", },
	[169599] = {id=169599, zh_CN="腿部束带勾勒飒爽轮廓，立体多口袋打造丰富层次，硬核机能质感与随性街头风潮完美相融。", },
	[169600] = {id=169600, zh_CN="游走街头", },
	[169601] = {id=169601, zh_CN="绳带束紧短靴，无论是街头游走还是极限运动，皆能稳步迈步、自在前行。", },
	[169602] = {id=169602, zh_CN="墨染山河套装", },
	[169603] = {id=169603, zh_CN="融中式水墨意境与现代长风衣剪裁于一体，自带大隐隐于市的清冷气韵与雅致贵态。", },
	[169604] = {id=169604, zh_CN="临风而归", },
	[169605] = {id=169605, zh_CN="发丝微垂随性错落，散漫间自带清雅风骨，宛若自山间踏风而归的温润君子。", },
	[169606] = {id=169606, zh_CN="云栖立领", },
	[169607] = {id=169607, zh_CN="精巧盘扣点缀雅致衣身，以现代简约形制，致敬东方传统美学底蕴。", },
	[169608] = {id=169608, zh_CN="远山行", },
	[169609] = {id=169609, zh_CN="长袍衣襟处晕染开的水墨山水，仿佛将万里江山披挂于肩，气场深邃而沉稳。", },
	[169610] = {id=169610, zh_CN="寒松长裤", },
	[169611] = {id=169611, zh_CN="直筒长裤挺括的版型如劲松般笔直，低调的暗纹在走动间流露出不凡的质感。", },
	[169612] = {id=169612, zh_CN="步尘靴", },
	[169613] = {id=169613, zh_CN="摒弃冗余繁杂设计，恪守极简利落格调，每一步起落，皆尽显从容不迫的超然风度。", },
	[169614] = {id=169614, zh_CN="萤花执灯人", },
	[169615] = {id=169615, zh_CN="碎钻星轨", },
	[169616] = {id=169616, zh_CN="长款不对称的流苏耳坠从耳际垂落，由无数颗细小的钻石紧密镶嵌而成。", },
	[169617] = {id=169617, zh_CN="雾霭轻纱", },
	[169618] = {id=169618, zh_CN="半透明的蕾丝长手套，紧贴着修长的双臂。朦胧的质感宛如清晨未散的浓雾，在指尖处留下了一抹若即若现的温柔。", },
	[169619] = {id=169619, zh_CN="闪耀永恒", },
	[169620] = {id=169620, zh_CN="晶莹剔透的水晶项圈紧贴着颈项，承载着深夜里所有闪耀的瞬间，将优雅永远定格。", },
	[169621] = {id=169621, zh_CN="寂静红毯", },
	[169622] = {id=169622, zh_CN="一字带轻敛于脚踝，踏过静谧红毯，步履轻悄无声，却每一步都从容笃定，自带笃定气场。", },
	[169623] = {id=169623, zh_CN="夜汐梦痕", },
	[169624] = {id=169624, zh_CN="修身剪裁的抹胸长裙，不对称的高开叉外摆裙幅层层叠叠向后延展，宛如夜色在足尖流淌。", },
	[169625] = {id=169625, zh_CN="幕下吻痕套装", },
	[169626] = {id=169626, zh_CN="当灯光暗去、华丽的幕布落下，她独自在静谧的露台上享受晚风的轻抚，只为自己绽放优雅。", },
	[169627] = {id=169627, zh_CN="凝夜流彩", },
	[169628] = {id=169628, zh_CN="长发如深夜的水波流动，额前轻垂的姬发式刘海修饰面庞。发间若隐若现地缠绕着微细的冷银丝线。", },
	[169629] = {id=169629, zh_CN="公主卷发", },
	[169630] = {id=169630, zh_CN="发顶扎成乖巧的半蓬公主头，发梢带着瓷娃娃般优雅温润的内卷弧度。", },
	[169631] = {id=169631, zh_CN="暖焰余温", },
	[169632] = {id=169632, zh_CN="微蜷长发在一侧扎成精致的侧辫，斜斜地搭在肩头，像是深夜火堆旁悄然升起的最后一缕温热暖意。", },
	[169633] = {id=169633, zh_CN="慵懒午夜", },
	[169634] = {id=169634, zh_CN="长发随意地盘成一个松散而优雅的高髻，几缕微卷的发丝垂落颊侧，带着复古名伶独有的慵懒与高贵。", },
	[169635] = {id=169635, zh_CN="剧院名伶", },
	[169636] = {id=169636, zh_CN="洛丽塔少女", },
	[169637] = {id=169637, },
	[169638] = {id=169638, },
	[169639] = {id=169639, },
	[169640] = {id=169640, zh_CN="疯癫", },
	[169641] = {id=169641, zh_CN="神志不清", },
	[169642] = {id=169642, zh_CN="恍惚", },
	[169643] = {id=169643, zh_CN="清醒", },
