	[169999] = {id=169999, },
	[170000] = {id=170000, zh_CN="已邀请该玩家加入闲聊，等待对方通过中……", },
	[170001] = {id=170001, zh_CN="菇菇甜梦套装", },
	[170002] = {id=170002, zh_CN="蘑菇林魔女亲手缝制的专属洋装，每一处蕾丝、刺绣、缎带都复刻糖果的柔和色彩，蓬松裙摆承载少女不褪色的童话幻想。", },
	[170003] = {id=170003, zh_CN="菇苞洋裙", },
	[170004] = {id=170004, zh_CN="挂脖露肩剪裁缀满褶皱花边，缎带蝴蝶结轻系颈间；花苞纱裙前短后长，兜满菇菇林的软甜气息。", },
	[170005] = {id=170005, zh_CN="菇菇糖粒", },
	[170006] = {id=170006, zh_CN="圆片碎钻拼成微型蘑菇糖粒，细碎光泽藏在卷发缝隙里，不张扬却足够精巧，是魔女悄悄藏起的小甜蜜。", },
	[170007] = {id=170007, zh_CN="薄糖领花", },
	[170008] = {id=170008, zh_CN="双层柔润缎带结成小巧蝴蝶结，轻薄缎面泛着温柔柔光，衔接渐变的配色，为整套童话装补层次。", },
	[170009] = {id=170009, zh_CN="圆菇粗跟鞋", },
	[170010] = {id=170010, zh_CN="圆头低粗跟小皮鞋，鞋头镶嵌宝石雕花，稳妥粗跟适配林间漫步，与花边中筒袜相映成趣。", },
	[170011] = {id=170011, zh_CN="甜莓中筒袜", },
	[170012] = {id=170012, zh_CN="贴合小腿曲线的软糯针织中筒袜，袜口堆叠双层褶皱蕾丝花边，两侧缀迷你小爱心。", },
	[170013] = {id=170013, zh_CN="蘑菇花边帽", },
	[170014] = {id=170014, zh_CN="宽大的帽檐上装饰着层层叠叠的荷叶边与精致蕾丝，宛如一朵倒扣的风铃草。帽檐下的阴影里，藏着少女今天偷偷许下的第三个愿望。", },
	[170015] = {id=170015, zh_CN="薰衣草之梦", },
	[170016] = {id=170016, zh_CN="浸过林间的短卷发，发尾蓬松向内收拢，细碎软发轻贴脸颊，像裹着未醒的甜梦的薰衣草香气。", },
	[170017] = {id=170017, zh_CN="柔序通勤套装", },
	[170018] = {id=170018, zh_CN="都市企划顾问的日常成套穿搭，特意柔化传统西装的硬朗线条，用珍珠、缎面打造无压迫感职场造型，兼顾专业度与女性温柔。", },
	[170019] = {id=170019, zh_CN="通勤西装", },
	[170020] = {id=170020, zh_CN="翻领内侧拼接肌理蕾丝，弱化传统西装的冷硬感。七分可翻卷袖口清爽利落，垂顺抗皱面料适配整日办公。", },
	[170021] = {id=170021, zh_CN="流云缎衫", },
	[170022] = {id=170022, zh_CN="缎面内搭底色浮着流云暗纹，门襟缀一排小巧珍珠扣。垂顺缎面自带细腻柔光，单穿雅致，叠搭西装更显穿搭层次。", },
	[170023] = {id=170023, zh_CN="双环方表", },
	[170024] = {id=170024, zh_CN="方形表盘与双圈金属细环叠搭成表，方形切割呼应职场干练线条。纤薄表身贴合腕间，抬腕之间流露不张扬的利落品味。", },
	[170025] = {id=170025, zh_CN="几何圈环", },
	[170026] = {id=170026, zh_CN="极细金属圆环层叠交错，简洁几何线条勾勒现代感轮廓。环面打磨细腻哑光，低调垂坠于耳畔，为职场造型注入一丝克制的设计感。", },
	[170027] = {id=170027, zh_CN="锁骨珠光", },
	[170028] = {id=170028, zh_CN="大小渐变珍珠串联双层锁骨链，柔和珠光轻贴锁骨线条，衬出独属于职场女性的温婉气质。", },
	[170029] = {id=170029, zh_CN="烟管西裤", },
	[170030] = {id=170030, zh_CN="高腰直筒烟管裤利落剪裁修饰腿部线条，哑光垂顺面料贴身不紧绷。利落收束的裤脚露出纤细脚踝，消解正装厚重感。", },
	[170031] = {id=170031, zh_CN="珍珠缎带", },
	[170032] = {id=170032, zh_CN="脚踝缠绕双层细缎带，缎带末端垂挂一颗迷你珍珠坠。高度适中的尖头细高跟行走从容，纯色设计完美适配通勤穿搭。", },
	[170033] = {id=170033, zh_CN="齐肩柔波", },
	[170034] = {id=170034, zh_CN="轻薄齐刘海柔和眉眼，平直发尾微微内收。干净柔和的发色褪去职场凌厉，举手投足皆是从容温婉。", },
