	[170469] = {id=170469, zh_CN="确定要退出对话吗", },
	[170470] = {id=170470, zh_CN="一只白色的小猫张开四肢，从草丛中跳起。它平稳地落在石阶上，弓背炸毛，高高竖起尾巴，雷达耳左右转动着，到处观察着。", },
	[170471] = {id=170471, zh_CN="喵嗷！是谁在阴影中试图吓唬伟大的超级侦探！", },
	[170472] = {id=170472, },
	[170473] = {id=170473, zh_CN="不要害怕，勇敢的侦探。", },
	[170474] = {id=170474, zh_CN="难道幽灵都会在光天化日之下漫游猫猫乐园了吗？", },
	[170475] = {id=170475, zh_CN="不，不会的，我必须冷静下来，勇气快点到来吧。", },
	[170476] = {id=170476, zh_CN="露出一只眼睛，年糕，你可不仅仅是一只血统纯正的贵族小猫，更是媲美喵尔摩斯的超级侦探！", },
	[170477] = {id=170477, zh_CN="打招呼。", },
	[170478] = {id=170478, zh_CN="藏起来。", },
	[170479] = {id=170479, zh_CN="嗨！", },
	[170480] = {id=170480, zh_CN="我……我已经找寻到你的踪迹了，如果你坚持自己的懦弱，我将被迫以惊吓市民罪逮捕你。", },
	[170481] = {id=170481, },
	[170482] = {id=170482, zh_CN="我……我已经找寻到你的踪迹了，如果你坚持自己的懦弱，我将被迫以惊吓市民罪逮捕你。", },
	[170483] = {id=170483, zh_CN="真的吗？那我被猫猫侦探逮捕啦。", },
	[170484] = {id=170484, zh_CN="啊啊啊啊啊啊啊！", },
	[170485] = {id=170485, zh_CN="不，不要过来啊，我只是喵喵，不好吃的。", },
	[170486] = {id=170486, zh_CN="没有鬼的，没有鬼的，相信科学，相信科学。", },
	[170487] = {id=170487, zh_CN="我把我赚来的小鱼干都给你，你不要吃我，求求你了。", },
	[170488] = {id=170488, zh_CN="小猫咪，你睁眼看看我呗？", },
	[170489] = {id=170489, zh_CN="年糕，你睁眼看看我是谁？", },
	[170490] = {id=170490, zh_CN="年糕，你睁眼看看我是谁？", },
	[170491] = {id=170491, zh_CN="年糕，你睁眼看看我是谁？", },
	[170492] = {id=170492, zh_CN="喵？", },
	[170493] = {id=170493, zh_CN="喵喵，你就是坠落喵间，身揣天命的星之子嘛？！", },
	[170494] = {id=170494, zh_CN="你猜对了。", },
	[170495] = {id=170495, zh_CN="站住！", },
	[170496] = {id=170496, zh_CN="？", },
	[170497] = {id=170497, zh_CN="喵喵我是隐居古堡的“超级侦探”——年糕，大名鼎鼎的星之子阁下，我正在招募新的搭档！", },
	[170498] = {id=170498, zh_CN="喵喵我看你资质不一般，有探险解密的天赋，不如来应聘我的侦探助理如何？", },
	[170499] = {id=170499, zh_CN="助理？刚刚不还是搭档吗？", },
	[170500] = {id=170500, zh_CN="我们这个行业讲究工作经验，就连金田一喵也是从爷爷的学徒开始做起的！", },
	[170501] = {id=170501, zh_CN="喵？", },
	[170502] = {id=170502, zh_CN="哦，星之子阁下，时间如过江之鲫，真是好久不见了！", },
	[170503] = {id=170503, zh_CN="过……过江之鲫？", },
	[170504] = {id=170504, zh_CN="我不过是考考你罢了。", },
	[170505] = {id=170505, zh_CN="这个热身就勉强算你通过吧。喵喵我正在招募新的搭档，阁下有兴趣吗？", },
	[170506] = {id=170506, zh_CN="不过作为守护正义的超级侦探，我也要对你进行面试的。", },
	[170507] = {id=170507, zh_CN="喵？", },
	[170508] = {id=170508, zh_CN="哦，星之子阁下，时间如过江之鲫，真是好久不见了！", },
	[170509] = {id=170509, zh_CN="这里该用。", },
	[170510] = {id=170510, zh_CN="喵喵我知道这里该用什么。", },
	[170511] = {id=170511, zh_CN="对了。%PlayerName，喵喵我正在招募新的搭档！", },
	[170512] = {id=170512, zh_CN="你愿意来应聘我的侦探助理吗？我可以破格将你提拔成搭档。", },
	[170513] = {id=170513, zh_CN="不过作为守护正义的超级侦探，我也要对你进行面试的。", },
	[170514] = {id=170514, zh_CN="喵？", },
	[170515] = {id=170515, zh_CN="哦，星之子阁下，时间如过江之鲫，真是好久不见了！", },
	[170516] = {id=170516, zh_CN="这里该用，比如，白马过隙？", },
	[170517] = {id=170517, zh_CN="好吧，还好有你在。", },
	[170518] = {id=170518, zh_CN="对了。%PlayerName，喵喵我正在招募新的搭档！", },
	[170519] = {id=170519, zh_CN="你愿意来应聘我的侦探助理吗？我可以破格将你提拔成搭档。", },
	[170520] = {id=170520, zh_CN="不过作为守护正义的超级侦探，我也要对你进行面试的。", },
	[170521] = {id=170521, zh_CN="还需要面试？", },
	[170522] = {id=170522, zh_CN="当然！喵喵侦探的搭档必须上知天文，下知地理。", },
	[170523] = {id=170523, zh_CN="抬手。", },
	[170524] = {id=170524, zh_CN="谢谢，垫脚。", },
	[170525] = {id=170525, zh_CN="现在开始第一题！", },
	[170526] = {id=170526, zh_CN="提问！月亮是什么做的？", },
	[170527] = {id=170527, zh_CN="奶酪。", },
	[170528] = {id=170528, zh_CN="月饼。", },
	[170529] = {id=170529, zh_CN="月亮上的土。", },
	[170530] = {id=170530, zh_CN="奶酪！咬一口都会掉渣的喵。", },
	[170531] = {id=170531, zh_CN="我也爱吃！", },
	[170532] = {id=170532, zh_CN="反了反了。", },
	[170533] = {id=170533, zh_CN="月饼才是月亮做的。", },
	[170534] = {id=170534, zh_CN="不是月饼做的月亮，是月亮做的月饼喵。", },
	[170535] = {id=170535, zh_CN="原来是这样吗？", },
	[170536] = {id=170536, zh_CN="原来不知道答案的吗？", },
	[170537] = {id=170537, zh_CN="学到了呀！", },
	[170538] = {id=170538, zh_CN="好，第二题！", },
	[170539] = {id=170539, zh_CN="这是一道跟刚刚相关的题目哦。", },
	[170540] = {id=170540, zh_CN="请问：太阳又是什么做的呢？", },
	[170541] = {id=170541, zh_CN="是烤焦的奶酪。", },
	[170542] = {id=170542, zh_CN="太阳上的土。", },
	[170543] = {id=170543, zh_CN="月亮是奶酪，太阳也是奶酪。", },
	[170544] = {id=170544, zh_CN="冰奶酪和烤奶酪，我应该先吃哪个呢？", },
	[170545] = {id=170545, zh_CN="原来是这样吗？", },
	[170546] = {id=170546, zh_CN="原来不知道答案的吗？", },
	[170547] = {id=170547, zh_CN="学到了呀！", },
	[170548] = {id=170548, zh_CN="好，第二题！", },
	[170549] = {id=170549, zh_CN="这是一道跟刚刚相关的题目哦。", },
	[170550] = {id=170550, zh_CN="请问太阳又是什么做的呢？", },
	[170551] = {id=170551, zh_CN="是烤焦的奶酪。", },
	[170552] = {id=170552, zh_CN="太阳上的土。", },
	[170553] = {id=170553, zh_CN="流心的奶酪就算烫舌头也要尝尝呢。", },
	[170554] = {id=170554, zh_CN="原来是这样吗？", },
	[170555] = {id=170555, zh_CN="原来不知道答案的吗？", },
	[170556] = {id=170556, zh_CN="学到了呀！", },
	[170557] = {id=170557, zh_CN="好，第二题！", },
	[170558] = {id=170558, zh_CN="这是一道跟刚刚相关的题目哦。", },
	[170559] = {id=170559, zh_CN="请问太阳又是什么做的呢？", },
	[170560] = {id=170560, zh_CN="是烤焦的奶酪。", },
	[170561] = {id=170561, zh_CN="太阳上的土。", },
	[170562] = {id=170562, zh_CN="流心的奶酪就算烫舌头也要尝尝呢。", },
	[170563] = {id=170563, zh_CN="等等。", },
	[170564] = {id=170564, zh_CN="星之子，你在敷衍猫猫吗？", },
	[170565] = {id=170565, zh_CN="我可不是一般的小猫，你这样可逃不过我的眼睛喵。", },
	[170566] = {id=170566, zh_CN="最后一个问题！", },
	[170567] = {id=170567, zh_CN="海水为什么是咸的？", },
	[170568] = {id=170568, zh_CN="太阳蒸发。", },
	[170569] = {id=170569, zh_CN="章鱼厨师撒盐煮汤。", },
	[170570] = {id=170570, zh_CN="咸鱼泡温泉。", },
	[170571] = {id=170571, zh_CN="太阳蒸发水分，盐分积累。", },
	[170572] = {id=170572, zh_CN="哇哦，果然是星之子，好聪明。", },
	[170573] = {id=170573, zh_CN="因为海底有一个章鱼厨师在撒盐煮汤。", },
	[170574] = {id=170574, zh_CN="真的吗？", },
	[170575] = {id=170575, zh_CN="那喵喵我有机会一定要一览章鱼厨师的风采。", },
	[170576] = {id=170576, zh_CN="如果能喝到它做的海鲜汤就更好了。", },
	[170577] = {id=170577, zh_CN="咸鱼在海水里泡澡呀。", },
	[170578] = {id=170578, zh_CN="虽然姐姐说海里的巴别族是小鱼干预制品，但……", },
	[170579] = {id=170579, zh_CN="你不相信我，还不相信你的芝麻糊姐姐吗？", },
	[170580] = {id=170580, zh_CN="好吧，算你对吧。", },
	[170581] = {id=170581, zh_CN="让喵喵我评估一下你的成绩。", },
	[170582] = {id=170582, zh_CN="喵喵侦探，我通过面试了吗？", },
	[170583] = {id=170583, zh_CN="亲爱的%PlayerName，您好。", },
	[170584] = {id=170584, zh_CN="……", },
	[170585] = {id=170585, zh_CN="恭喜你顺利通过了侦探助理实习生岗位的面试，喵喵我在此真诚地邀请你加入侦探小队。", },
	[170586] = {id=170586, zh_CN="请你左手按在喵喵我的爪上，在2分钟内口头回复：已接受聘用，遵守按爪约定，愿意到年糕手下实习。", },
	[170587] = {id=170587, zh_CN="……", },
	[170588] = {id=170588, zh_CN="沉默。", },
	[170589] = {id=170589, zh_CN="接受聘用。", },
	[170590] = {id=170590, zh_CN="2分钟过去……", },
	[170591] = {id=170591, zh_CN="果然找不到搭档吗？难道喵喵我要独自奋战在与恶势力对抗的前线吗？", },
	[170592] = {id=170592, zh_CN="好吧，我答应你。", },
	[170593] = {id=170593, zh_CN="真的吗！", },
	[170594] = {id=170594, zh_CN="盖章！", },
	[170595] = {id=170595, zh_CN="已接受聘用，遵守按爪约定，愿意到年糕手下实习。", },
	[170596] = {id=170596, zh_CN="很好很好，那么就立刻开始我们的第一站吧。", },
	[170597] = {id=170597, zh_CN="看看我们的默契如何！", },
	[170598] = {id=170598, zh_CN="已接受聘用，遵守按爪约定，愿意到年糕手下实习。", },
	[170599] = {id=170599, zh_CN="很好很好，那么就立刻开始我们的第一站吧。", },
	[170600] = {id=170600, zh_CN="看看我们的默契如何！", },
	[170601] = {id=170601, zh_CN="喵。", },
	[170602] = {id=170602, },
	[170603] = {id=170603, zh_CN="零星的几瓶宽口瓶歪歪扭扭地放在地上，只有一瓶里面放了一束花。", },
	[170604] = {id=170604, zh_CN="……", },
	[170605] = {id=170605, zh_CN="你在？", },
	[170606] = {id=170606, zh_CN="工作期间，请叫我侦探。", },
	[170607] = {id=170607, zh_CN="好的，侦探，你这是？", },
	[170608] = {id=170608, zh_CN="这是我和姐姐发送电报的通信电线！", },
	[170609] = {id=170609, zh_CN="搭档，这就是可疑分子！", },
	[170610] = {id=170610, zh_CN="这个花瓶一定就是外星间谍！", },
	[170611] = {id=170611, zh_CN="搭档，我们需要好好将它审讯一番。", },
	[170612] = {id=170612, zh_CN="怎么审讯？", },
	[170613] = {id=170613, zh_CN="敲花瓶三下。", },
	[170614] = {id=170614, zh_CN="假装威胁。", },
	[170615] = {id=170615, zh_CN="不说实话就把你卖给古董商！", },
	[170616] = {id=170616, zh_CN="……", },
	[170617] = {id=170617, zh_CN="它畏罪潜逃了！", },
	[170618] = {id=170618, zh_CN="其实我还有别的办法。", },
	[170619] = {id=170619, zh_CN="侦探要不要让我试试。", },
	[170620] = {id=170620, },
	[170621] = {id=170621, zh_CN="搭档上吧！", },
	[170622] = {id=170622, zh_CN="我是……", },
	[170623] = {id=170623, zh_CN="年糕因为瓶中通透又低沉的回响吓了一跳。", },
	[170624] = {id=170624, zh_CN="搭档后退！花瓶说话了！", },
	[170625] = {id=170625, zh_CN="你按着年糕的要求，敲了花瓶三下，花瓶纹丝不动。", },
