	[170639] = {id=170639, zh_CN="搭档后退！花瓶说话了！", },
	[170640] = {id=170640, zh_CN="匆忙中，你因为惊恐爬上肩头的年糕而踉跄一步，不慎将花瓶打碎，碎片四分五裂地躺在你的脚下，碎屑飞溅擦破了你的裤脚。", },
