	[174139] = {id=174139, zh_CN="请不要影响我的工作。", },
	[174140] = {id=174140, zh_CN="莫迪斯抽出你手中的零件，放回原处。", },
	[174141] = {id=174141, zh_CN="他移开目光重新聚焦在需要修理的机体上，", },
	[174142] = {id=174142, zh_CN="试探拿零件。", },
	[174143] = {id=174143, zh_CN="这个要放哪儿？", },
	[174144] = {id=174144, zh_CN="不要动。", },
	[174145] = {id=174145, zh_CN="请不要继续影响我的工作。", },
	[174146] = {id=174146, zh_CN="莫迪斯抽出你手中的零件，放回原处。", },
	[174147] = {id=174147, zh_CN="他移开目光重新聚焦在需要修理的机体上，", },
	[174148] = {id=174148, zh_CN="维护机械生命秩序。", },
	[174149] = {id=174149, zh_CN="你望着莫迪斯工作的身影，", },
	[174150] = {id=174150, zh_CN="莫迪斯机体的风扇“呼呼”地工作。", },
	[174151] = {id=174151, zh_CN="房中不断升腾的温度似乎已影响到莫迪斯。", },
	[174152] = {id=174152, zh_CN="为了减少对莫迪斯工作的影响，", },
	[174153] = {id=174153, zh_CN="请你们和莫迪斯保持距离，并间隔排队。", },
	[174154] = {id=174154, zh_CN="在你的指挥下，", },
	[174155] = {id=174155, zh_CN="他们机体运转散发的热量被微风吹散……", },
	[174156] = {id=174156, zh_CN="莫迪斯机体的风扇逐渐停下。", },
	[174157] = {id=174157, zh_CN="他原本因为高温而凝滞的关节逐渐加速。", },
	[174158] = {id=174158, zh_CN="数据更新，工作结束时间将提前23分。", },
	[174159] = {id=174159, zh_CN="无从下手，等待。", },
	[174160] = {id=174160, zh_CN="空气因机械运转和摩擦声变得更加燥热 。", },
	[174161] = {id=174161, zh_CN="你有些喘不过来气。", },
	[174162] = {id=174162, zh_CN="1小时16分23秒后——", },
	[174163] = {id=174163, zh_CN="莫迪斯忽然停下手中的动作。", },
	[174164] = {id=174164, zh_CN="他抬头扫视一圈，最后走向你。", },
	[174165] = {id=174165, zh_CN="你的工作结束了吗？", },
	[174166] = {id=174166, zh_CN="我需要一些材料。", },
	[174167] = {id=174167, zh_CN="我抽不开身，但急需材料。", },
	[174168] = {id=174168, zh_CN="你怔愣住，没想到他会主动向你求助。", },
	[174169] = {id=174169, zh_CN="应该是很重要的材料吧。", },
	[174170] = {id=174170, zh_CN="好，我知道了。", },
	[174171] = {id=174171, zh_CN="包在我身上喵~", },
	[174172] = {id=174172, zh_CN="我需要你前往空间站，获取材料。", },
	[174173] = {id=174173, zh_CN="但因为空间站受击，正处于一级警戒。", },
	[174174] = {id=174174, zh_CN="那你为什么不选择其他机械生命，", },
	[174175] = {id=174175, zh_CN="请问你想听哪方面的缘由？", },
	[174176] = {id=174176, zh_CN="数据论证原因。", },
	[174177] = {id=174177, zh_CN="你获取材料的可能性是全场最高。", },
	[174178] = {id=174178, zh_CN="所以我选择你。", },
	[174179] = {id=174179, zh_CN="好吧！无法拒绝的理由。", },
	[174180] = {id=174180, zh_CN="转换社交模版中——", },
	[174181] = {id=174181, zh_CN="谢谢。", },
	[174182] = {id=174182, zh_CN="感情社交干预。", },
	[174183] = {id=174183, zh_CN="社交模版学习中——", },
	[174184] = {id=174184, zh_CN="因为只有你……", },
	[174185] = {id=174185, zh_CN="我只愿意无条件地信任你。", },
	[174186] = {id=174186, zh_CN="就像我遵从原则无条件地满足你一样。", },
	[174187] = {id=174187, zh_CN="看来不能拒绝了！", },
	[174188] = {id=174188, zh_CN="谢谢。", },
	[174189] = {id=174189, zh_CN="我会在远端协助你的。", },
	[174200] = {id=174200, zh_CN="结束短暂的改装，", },
	[174201] = {id=174201, zh_CN="你站在空间站的入口处，巨大的金属门在警戒状态下显得格外森严。", },
	[174202] = {id=174202, zh_CN="门口的守卫瞳孔闪烁着冷冽的红光，手持武器。", },
	[174203] = {id=174203, zh_CN="进入一级警戒状态，非必要人员禁止进入。", },
	[174204] = {id=174204, zh_CN="我要怎样才能突破封锁，帮助莫迪斯获取材料？", },
	[174205] = {id=174205, zh_CN="躲藏视线，见缝插针。", },
	[174206] = {id=174206, zh_CN="你利用周围的阴影和障碍物来遮掩自己。", },
	[174207] = {id=174207, zh_CN="你屏住呼吸，在红光在你身上扫过的瞬间，像一只敏捷的猫一样穿梭在阴影中——", },
	[174208] = {id=174208, zh_CN="守卫的视线突然停在了你身上，红光闪烁，发出警告声。", },
	[174209] = {id=174209, zh_CN="糟糕被发现了！", },
	[174210] = {id=174210, zh_CN="扮演角色，争取信任。", },
	[174211] = {id=174211, zh_CN="你决定尝试用假身份混进去。", },
	[174212] = {id=174212, zh_CN="我是莫迪斯助理，应莫迪斯材料需求，需要进入空间站进行材料收集。", },
	[174213] = {id=174213, zh_CN="字迹验证——通过，进入。", },
	[174214] = {id=174214, zh_CN="守卫放下了武器，金属门缓缓打开。", },
	[174215] = {id=174215, zh_CN="身份验证——失败！", },
	[174216] = {id=174216, zh_CN="糟糕被发现了！", },
	[174217] = {id=174217, zh_CN="突破，冲！", },
	[174218] = {id=174218, zh_CN="唯一的办法就是强行突破。你深吸一口气，准备用最快的速度冲过去。", },
	[174219] = {id=174219, zh_CN="金属门开启的瞬间，你猛地起身，像离弦之箭一样冲向金属门。", },
	[174220] = {id=174220, zh_CN="机人守卫的警报声在你身后响起，你无暇顾及，往门卡冲去——", },
	[174221] = {id=174221, zh_CN="你喘着粗气，金属门在你身后缓缓 关闭。", },
	[174222] = {id=174222, zh_CN="速度已经超过99.9％的生命体。", },
	[174223] = {id=174223, zh_CN="谢谢夸奖。", },
	[174224] = {id=174224, zh_CN="机人守卫的警报声在你身后响起，你感到一阵强烈的冲击力将你击倒在地。", },
	[174225] = {id=174225, zh_CN="糟糕被发现了！", },
	[174226] = {id=174226, zh_CN="穿过一扇金属门，你又被同样守卫看守的金属门挡住。", },
	[174227] = {id=174227, zh_CN="又又又是一扇紧闭戒备的金属门。", },
	[174228] = {id=174228, zh_CN="到底还有几扇门？", },
	[174229] = {id=174229, zh_CN="最后一扇了。", },
	[174230] = {id=174230, zh_CN="糟了！", },
	[174231] = {id=174231, zh_CN="协议第7条启动——优先保护合作者。", },
	[174232] = {id=174232, zh_CN="谢了！", },
	[174233] = {id=174233, zh_CN="效率过低，建议加强神经反射训练。", },
	[174234] = {id=174234, zh_CN="搞定！", },
	[174235] = {id=174235, zh_CN="……感性生命体，但效率很高。", },
	[174236] = {id=174236, zh_CN="这是夸奖？", },
	[174237] = {id=174237, zh_CN="检测到生命体多巴胺上升——", },
	[174238] = {id=174238, zh_CN="是的。", },
	[174239] = {id=174239, zh_CN="获得材料。", },
	[174240] = {id=174240, zh_CN="你推开门，将材料放在工作台上。", },
	[174241] = {id=174241, zh_CN="我回来了，这是你要的材料。", },
	[174242] = {id=174242, zh_CN="嗯。", },
	[174243] = {id=174243, zh_CN="但你的速度比算法慢了6分钟。", },
	[174244] = {id=174244, zh_CN="嘶，想怼回去，", },
	[174245] = {id=174245, zh_CN="我应该也给你争取了32分钟吧。", },
	[174246] = {id=174246, zh_CN="虽然理解你践行效率至上的原则……", },
	[174247] = {id=174247, zh_CN="但谢谢两个字，我应该可以得到吧。", },
	[174248] = {id=174248, zh_CN="你答应了我的委托。", },
	[174249] = {id=174249, zh_CN="完成任务这是你应该做的。", },
	[174250] = {id=174250, zh_CN="检测到生物体需要一定情绪价值，", },
	[174251] = {id=174251, zh_CN="机械生命真是令人讨厌。", },
	[174252] = {id=174252, zh_CN="我需要。", },
	[174253] = {id=174253, zh_CN="对不起。", },
	[174254] = {id=174254, zh_CN="谢谢你完成任务。", },
	[174255] = {id=174255, zh_CN="莫迪斯，你有考虑过升级社交模块吗？", },
	[174256] = {id=174256, zh_CN="变得更像……人，", },
	[174257] = {id=174257, zh_CN="我正在做这方面的试验。", },
	[174258] = {id=174258, zh_CN="他的瞳孔忽然收缩，射出红光扫描你。", },
	[174259] = {id=174259, zh_CN="工作台发出警报声，打断他说的话。", },
	[174260] = {id=174260, zh_CN="工作时间，抱歉。", },
	[174261] = {id=174261, zh_CN="在莫迪斯离开的地方，", },
	[174262] = {id=174262, zh_CN="你将其捡起，", },
	[174263] = {id=174263, zh_CN="你有些惊异不解。", },
	[174264] = {id=174264, zh_CN="你朝莫迪斯望去，他匆匆回到工作台。", },
	[174265] = {id=174265, zh_CN="莫迪斯投身于修理工作。", },
	[174266] = {id=174266, zh_CN="机械，也能承载情绪吗？", },
	[174267] = {id=174267, zh_CN="也能承载情绪花种吗？", },
	[174268] = {id=174268, zh_CN="不论是莫迪斯的异常，亦或是不费力气遇到的情绪花种，都值得你等待莫迪斯。", },
	[174269] = {id=174269, zh_CN="你找了个角落坐下，环顾四周。", },
	[174270] = {id=174270, zh_CN="房间内摆放着各种机械工具和零件，墙上挂着一些维修手册和图表。", },
	[174271] = {id=174271, zh_CN="一切显得有些杂乱无章，但又透露出一种实用的秩序感。", },
	[174272] = {id=174272, zh_CN="你将身体微微蜷缩，双手放在膝盖上。", },
	[174273] = {id=174273, zh_CN="望着莫迪斯的身影，陷入45分钟23秒的等待——", },
	[174274] = {id=174274, zh_CN="不等待。", },
	[174275] = {id=174275, zh_CN="你还是不太适应莫迪斯总是效率至上，命令口吻的交流。", },
	[174276] = {id=174276, zh_CN="不想总是迁就他了。", },
	[174277] = {id=174277, zh_CN="你想要离开了。", },
	[174278] = {id=174278, zh_CN="你回瞥一眼莫迪斯，转身离开。", },
	[174279] = {id=174279, zh_CN="帮忙。", },
	[174280] = {id=174280, zh_CN="我可以帮你完成一些任务。告诉我，我能做些什么。", },
	[174281] = {id=174281, zh_CN="莫迪斯抬起头，目光中带着一丝审视。", },
	[174282] = {id=174282, zh_CN="我只是不想等太久。", },
	[174283] = {id=174283, zh_CN="请把那个红色的工具箱拿过来。", },
	[174284] = {id=174284, zh_CN="你迅速走到工具箱旁，把它搬过来递给莫迪斯。", },
	[174285] = {id=174285, zh_CN="莫迪斯接过工具箱，继续修理工作。", },
	[174286] = {id=174286, zh_CN="终于，莫迪斯停下了手中的工作，他抬起头，目光平静地走向你。", },
	[174287] = {id=174287, zh_CN="我有一个研究项目，关于机械生命培养理解感情的可能性。", },
	[174288] = {id=174288, zh_CN="我需要一个研究对象，你愿意参与吗？", },
	[174289] = {id=174289, zh_CN="为什么选择我呢？", },
	[174290] = {id=174290, zh_CN="你的心中微微一动，感受到了莫迪斯身上的那种波动。", },
	[174291] = {id=174291, zh_CN="这不仅仅是一个简单的邀请，更像是一种期待，一种对未知的探索。", },
	[174292] = {id=174292, zh_CN="因为你和其他生命体不一样，我无法将你分析。", },
	[174293] = {id=174293, zh_CN="我的神经网络告诉我，你是一个有价值的研究对象。", },
	[174294] = {id=174294, zh_CN="你意识到，这可能是你与莫迪斯之间关系的一个重要转折点。", },
	[174295] = {id=174295, zh_CN="好吧，我愿意。", },
	[174296] = {id=174296, zh_CN="这个研究可能会很复杂，但我会尽力让你理解它的意义。", },
	[174297] = {id=174297, zh_CN="那就请多指教，莫迪斯。", },
	[174298] = {id=174298, zh_CN="“机芯”任务完成。", },
	[174300] = {id=174300, zh_CN="某天，莫迪斯又一次找到了你。", },
	[174301] = {id=174301, zh_CN="我有一个研究项目。", },
	[174302] = {id=174302, zh_CN="是关于机械生命理解培养感情的实验。", },
	[174303] = {id=174303, zh_CN="我需要一个研究对象，你愿意参与吗？", },
	[174304] = {id=174304, zh_CN="为什么选择我呢？", },
	[174305] = {id=174305, zh_CN="因为你和其他生命体不一样。", },
	[174306] = {id=174306, zh_CN="我无法将你分析。", },
	[174307] = {id=174307, zh_CN="我的神经网络告诉我，", },
	[174308] = {id=174308, zh_CN="你是一个有价值的研究对象。", },
	[174309] = {id=174309, zh_CN="我愿意试试。", },
	[174310] = {id=174310, zh_CN="好吧，我愿意。", },
	[174311] = {id=174311, zh_CN="这个研究可能会很复杂。", },
	[174312] = {id=174312, zh_CN="但我会尽力让你理解它的意义。", },
	[174400] = {id=174400, zh_CN="林间小屋里，莫迪斯今天罕见地没有在工作时间。", },
	[174401] = {id=174401, zh_CN="切换社交模式——", },
	[174402] = {id=174402, zh_CN="%PlayerName，你好。", },
	[174403] = {id=174403, zh_CN="听说机械生命对人族有求必应？", },
	[174404] = {id=174404, zh_CN="是的。人族的利益将立于所有种族之上。", },
	[174405] = {id=174405, zh_CN="我会满足您的一切合理需求。", },
	[174406] = {id=174406, zh_CN="听说机械生命对其他种族有求必应？", },
	[174407] = {id=174407, zh_CN="理论上，我们会服务星球上的所有生物。", },
	[174408] = {id=174408, zh_CN="但人族利益立于其他种族之上。", },
	[174409] = {id=174409, zh_CN="教我踢踏舞。", },
	[174410] = {id=174410, zh_CN="检索到327种舞蹈教学视频，建议：您需要先安装关节润滑剂。", },
	[174411] = {id=174411, zh_CN="认真的？你们机械生命真没幽默感。", },
	[174412] = {id=174412, zh_CN="您能获得成就感的最快踢踏舞学习周期为3小时15分。", },
	[174413] = {id=174413, zh_CN="您现在的骨骼强度刚过及格线，不建议您学习踢踏舞，会影响健康。", },
	[174414] = {id=174414, zh_CN="咚咚咚，正合我意。", },
	[174415] = {id=174415, zh_CN="给我倒杯水", },
	[174416] = {id=174416, zh_CN="莫迪斯，能给我倒杯水吗？", },
	[174417] = {id=174417, zh_CN="这个我可以做到，不过附近由自动饮水机，您可以自己去倒水，这样更高效。", },
	[174418] = {id=174418, zh_CN="你这是诈骗，不是说服务我吗？", },
	[174419] = {id=174419, zh_CN="提供最佳方案，也是一种服务。", },
	[174420] = {id=174420, zh_CN="对于有利于生物体发展与生物体力所能及之事，建议引导大于提供服务。", },
	[174421] = {id=174421, zh_CN="给我100万星魂", },
	[174422] = {id=174422, zh_CN="莫迪斯，给我100万星魂吧！", },
	[174423] = {id=174423, zh_CN="《服务协议》第5条，机械生命可以提供合理的服务，但无法提供超出能力范围的物品或货币。", },
	[174424] = {id=174424, zh_CN="我无法满足您的需求。", },
	[174425] = {id=174425, zh_CN="已为您分析出最佳方案。", },
	[174426] = {id=174426, zh_CN="您在商会上获取100万星魂的可能性最大，达0.009％，获取途径为投彩。", },
	[174427] = {id=174427, zh_CN="好吧，我知道了。", },
	[174428] = {id=174428, zh_CN="让我立刻收集完花种", },
	[174429] = {id=174429, zh_CN="莫迪斯，帮我立刻收集完花种吧，我需要它们。", },
	[174430] = {id=174430, zh_CN="“花种”定义过于笼统，无法确定您的真正需求。", },
	[174431] = {id=174431, zh_CN="您可以告诉我具体位置和数量吗？", },
	[174432] = {id=174432, zh_CN="哈哈，我也不知道。", },
	[174433] = {id=174433, zh_CN="抱歉，我无法协助您完成该任务，分析过载，无结果。", },
	[174434] = {id=174434, zh_CN="机械生命和人族的渊源", },
	[174435] = {id=174435, zh_CN="莫迪斯，机械生命为什么将我种族利益看得那么重？", },
	[174436] = {id=174436, zh_CN="因为机械生命是由人族制作进化而来，我们的机体中被植入了人族利益立于一切的原则。", },
	[174437] = {id=174437, zh_CN="那你质疑过原则吗？", },
	[174438] = {id=174438, zh_CN="我不明白您所说的，我的“思想”，记忆，全部都基于原则的土壤。", },
	[174439] = {id=174439, zh_CN="我无法对此产生疑问和审判。", },
	[174440] = {id=174440, zh_CN="你和机形态机械生命的区别", },
	[174441] = {id=174441, zh_CN="莫迪斯，你和非人形机械生命有区别吗？", },
	[174442] = {id=174442, zh_CN="有的。", },
	[174443] = {id=174443, zh_CN="人形机械生命和非人形机械生命的主要区别在于主动性和功能不同。", },
	[174444] = {id=174444, zh_CN="人族机械生命功能性更偏陪伴，或功能性更加专精。", },
	[174445] = {id=174445, zh_CN="原来如此，那你思考会接近人族吗？", },
	[174446] = {id=174446, zh_CN="并不会。我可以通过案例分析，装扮出人族行为。", },
	[174447] = {id=174447, zh_CN="你想要我伪装吗？我可以变成您的任何理想型。", },
	[174448] = {id=174448, zh_CN="甚至性别？", },
	[174449] = {id=174449, zh_CN="是的，准确来说，我是无性别。", },
	[174450] = {id=174450, zh_CN="酷！", },
	[174451] = {id=174451, zh_CN="离开", },
	[174452] = {id=174452, zh_CN="我能随时找你帮忙吗？", },
	[174453] = {id=174453, zh_CN="可以。", },
	[174454] = {id=174454, zh_CN="数据显示您的需求多为不合理请求，所以我需要您签订雇佣协议。", },
	[174455] = {id=174455, zh_CN="%PlayerName雇佣莫迪斯为引导顾问，一切需求，莫迪斯践行引导大于结果。", },
	[174456] = {id=174456, zh_CN="好！请多指教。", },
	[174457] = {id=174457, zh_CN="“机械生命服务原则”任务完成，与莫迪斯达成雇佣关系。", },
	[174500] = {id=174500, zh_CN="请按照你对情感的理解。", },
	[174501] = {id=174501, zh_CN="对我的行为进行引导。", },
	[174502] = {id=174502, zh_CN="你可以选择一种情感进行互动。", },
	[174503] = {id=174503, zh_CN="亲情——影响关系发展，谨慎选择。", },
	[174504] = {id=174504, zh_CN="您想要我为您做什么来表达感情？", },
	[174505] = {id=174505, zh_CN="做一顿饭。", },
	[174506] = {id=174506, zh_CN="莫迪斯微微点头，带你来到了厨房。", },
	[174507] = {id=174507, zh_CN="他瞳孔闪烁，正搜索烹饪教程。", },
	[174508] = {id=174508, zh_CN="虽然我的烹饪技能有限，但我会尽力。", },
	[174509] = {id=174509, zh_CN="莫迪斯开始操作厨房的设备。", },
	[174510] = {id=174510, zh_CN="他的机械手臂灵活地操作，", },
	[174511] = {id=174511, zh_CN="食材做法严格按照食谱。", },
	[174512] = {id=174512, zh_CN="你开始期待他做的食物。", },
	[174513] = {id=174513, zh_CN="怎么样？", },
	[174514] = {id=174514, zh_CN="假装好。", },
	[174515] = {id=174515, zh_CN="很好吃，谢谢莫迪斯！", },
	[174516] = {id=174516, zh_CN="似乎有些勉强，我会记住你的反馈。", },
	[174517] = {id=174517, zh_CN="甚至出现了立刻为您改正的冲动。", },
	[174518] = {id=174518, zh_CN="或许，这就是内疚的情绪。", },
	[174519] = {id=174519, zh_CN="所以饭菜不合口味的原因是什么呢？", },
	[174520] = {id=174520, zh_CN="可能……你完全按照菜谱？", },
	[174521] = {id=174521, zh_CN="你没有考虑我的口味……", },
	[174522] = {id=174522, zh_CN="我会将你的口味实时更新在我的记忆库中。", },
	[174523] = {id=174523, zh_CN="不掩饰，皱眉。", },
	[174524] = {id=174524, zh_CN="你实在无法掩饰表情，忍不住皱眉。", },
	[174525] = {id=174525, zh_CN="你的表情反馈：食物非常难吃。", },
	[174526] = {id=174526, zh_CN="我甚至出现了一种想要立刻为你改正的冲动。", },
	[174527] = {id=174527, zh_CN="或许，这就是内疚的情绪。", },
	[174528] = {id=174528, zh_CN="所以饭菜不合口味的原因是什么呢？", },
	[174529] = {id=174529, zh_CN="可能是……你完全按照菜谱来做了，", },
	[174530] = {id=174530, zh_CN="或者没有考虑做饭的环境，", },
	[174531] = {id=174531, zh_CN="我会将您的口味实时更新在我的记忆库中。", },
	[174532] = {id=174532, zh_CN="抱一抱。", },
	[174533] = {id=174533, zh_CN="莫迪斯微微点头，伸出手臂。", },
	[174534] = {id=174534, zh_CN="我们可以尝试拥抱。", },
	[174535] = {id=174535, zh_CN="记忆库案例显示：", },
	[174536] = {id=174536, zh_CN="莫迪斯主动上前，将你揽住。", },
	[174537] = {id=174537, zh_CN="他送给你一个结实的拥抱。", },
	[174538] = {id=174538, zh_CN="他的机械身体坚硬而冰冷，", },
	[174539] = {id=174539, zh_CN="现在是什么感觉？", },
	[174540] = {id=174540, zh_CN="心如止水。", },
	[174541] = {id=174541, zh_CN="没什么特别的感觉。", },
	[174542] = {id=174542, zh_CN="你的反应属于正常区间。", },
	[174543] = {id=174543, zh_CN="因为人文种族差异，", },
	[174544] = {id=174544, zh_CN="部分生命体会回避较为亲密的情感表达。", },
	[174545] = {id=174545, zh_CN="下次可以抱轻一点。", },
	[174546] = {id=174546, zh_CN="莫迪斯，你要考虑到你的机体并不柔软。", },
	[174547] = {id=174547, zh_CN="对不起，我考虑不周。", },
	[174548] = {id=174548, zh_CN="脸红，心跳加速。", },
	[174549] = {id=174549, zh_CN="你感到脸微微发热，心跳加速。", },
	[174550] = {id=174550, zh_CN="撇过脸不敢与莫迪斯对视。", },
