	[174687] = {id=174687, zh_CN="换个亲昵的称呼。", },
	[174688] = {id=174688, zh_CN="或许我们可以换个亲昵的称呼。", },
	[174689] = {id=174689, zh_CN="数据显示，", },
	[174690] = {id=174690, zh_CN="你可以尝试呼唤我亲爱的吗？", },
	[174691] = {id=174691, zh_CN="接受他的邀请。", },
	[174692] = {id=174692, zh_CN="亲爱的~", },
	[174693] = {id=174693, zh_CN="你分析研究结果了吗？", },
	[174694] = {id=174694, zh_CN="您似乎很享受这个称呼，我会记住的。", },
	[174695] = {id=174695, zh_CN="拒绝他的邀请。", },
	[174696] = {id=174696, zh_CN="亲爱……不！", },
	[174697] = {id=174697, zh_CN="我觉得还是叫莫迪斯比较好。", },
	[174698] = {id=174698, zh_CN="你分析研究结果了吗？", },
	[174699] = {id=174699, zh_CN="称呼除了需要根据感情分类外，", },
	[174700] = {id=174700, zh_CN="使用语言关心。", },
	[174701] = {id=174701, zh_CN="你可以记住多使用语言关心。", },
	[174702] = {id=174702, zh_CN="比如健康，心情，压力或者琐事……", },
	[174703] = {id=174703, zh_CN="你试试看。", },
	[174704] = {id=174704, zh_CN="好的。", },
	[174705] = {id=174705, zh_CN="但你似乎有些疲劳。你需要休息。", },
	[174706] = {id=174706, zh_CN="接受他的关心。", },
	[174707] = {id=174707, zh_CN="你说得对，", },
	[174708] = {id=174708, zh_CN="好的，我会记住并关注您的健康。", },
	[174709] = {id=174709, zh_CN="拒绝他的关心。", },
	[174710] = {id=174710, zh_CN="我觉得还是需要交往才能了解彼此的习惯。", },
	[174711] = {id=174711, zh_CN="不经别人允许，", },
	[174712] = {id=174712, zh_CN="我明白了，有些习惯需要通过交流来了解。", },
	[174713] = {id=174713, zh_CN="试验告一段落——", },
	[174714] = {id=174714, zh_CN="如何，我通过试岗了吗？", },
	[174715] = {id=174715, zh_CN="莫迪斯沉默，", },
	[174716] = {id=174716, zh_CN="通过这些测试，", },
	[174717] = {id=174717, zh_CN="虽然我仍然无法完全理解这些情感的本质。", },
	[174718] = {id=174718, zh_CN="但通过你的引导，我收获很多学习实例。", },
	[174719] = {id=174719, zh_CN="莫迪斯的机体产生了不属于数据范围的波动……", },
	[174720] = {id=174720, zh_CN="一颗金鱼草在空气中幻化而出，", },
	[174721] = {id=174721, zh_CN="化作一颗褐色的细小种子。", },
	[174722] = {id=174722, zh_CN="莫迪斯瞥了一眼，没有打断对话。", },
	[174723] = {id=174723, zh_CN="您通过了试用期。", },
	[174724] = {id=174724, zh_CN="让你正式成为研究的搭档，是我的荣幸。", },
	[174725] = {id=174725, zh_CN="莫迪斯还在专注地工作，", },
	[174800] = {id=174800, zh_CN="莫迪斯的机体外观已经非常接近人族，", },
	[174801] = {id=174801, zh_CN="他的机械手臂和未覆盖仿生皮肤的机体仍显得有些突兀。", },
	[174802] = {id=174802, zh_CN="为什么不安装仿生皮肤呢？", },
