	[174805] = {id=174805, zh_CN="想改造莫迪斯的外观，他会同意吗？", },
	[174806] = {id=174806, zh_CN="莫迪斯，我有些想法……", },
	[174807] = {id=174807, zh_CN="从外表改造开始也许是个不错的主意。", },
	[174808] = {id=174808, zh_CN="你说得有道理。", },
	[174809] = {id=174809, zh_CN="我可以尝试改装我的形象。", },
	[174810] = {id=174810, zh_CN="任何部分都可以修改吗？", },
	[174811] = {id=174811, zh_CN="可以，我可以选择不同的声音，", },
	[174812] = {id=174812, zh_CN="可以，我可以选择不同的声音，", },
	[174813] = {id=174813, zh_CN="你任何部分都可以修改吗？", },
	[174814] = {id=174814, zh_CN="可以，我可以选择不同的声音，", },
	[174815] = {id=174815, zh_CN="修改声音。", },
	[174816] = {id=174816, zh_CN="我们可以试试更改声音，", },
	[174817] = {id=174817, zh_CN="你希望我选择哪一种？", },
	[174818] = {id=174818, zh_CN="女声。", },
	[174819] = {id=174819, zh_CN="试试女声吧，我觉得会很有趣。", },
	[174820] = {id=174820, zh_CN="莫迪斯的声音立刻变得柔和而清脆。", },
	[174821] = {id=174821, zh_CN="这样可以吗？", },
	[174822] = {id=174822, zh_CN="这样听起来很自然，很好！", },
	[174823] = {id=174823, zh_CN="老人声。", },
