	[174837] = {id=174837, zh_CN="他的身体表面变得光滑而有弹性，几乎与人类无异。", },
	[174838] = {id=174838, zh_CN="看起来很棒！", },
	[174839] = {id=174839, zh_CN="装扮衣服和配饰。", },
	[174840] = {id=174840, zh_CN="还给他戴上了一条精致的项链。", },
	[174841] = {id=174841, zh_CN="你退后一步，欣赏着自己的杰作。", },
