	[174856] = {id=174856, zh_CN="您喜欢的话，我可以保持这个外形。", },
	[174857] = {id=174857, zh_CN="满意自己的杰作。", },
	[174858] = {id=174858, zh_CN="你感到非常满意，心中充满了成就感。", },
	[174859] = {id=174859, zh_CN="你看起来很满意，为什么？", },
	[174860] = {id=174860, zh_CN="因为我是个改装天才啊，天才！", },
	[174861] = {id=174861, zh_CN="简直就是我的理想长相嘛。", },
	[174862] = {id=174862, zh_CN="太帅了！", },
	[174863] = {id=174863, zh_CN="确实，认证！", },
