	[174872] = {id=174872, zh_CN="当然是的。", },
	[174873] = {id=174873, zh_CN="你创造了我的人族外观，创造了我的记忆库，创造了我伪装感性的能力，创造了全新的莫迪斯……", },
	[174874] = {id=174874, zh_CN="没有你，我无法完成这些改变。", },
	[174875] = {id=174875, zh_CN="我应该承认，您已经成为了站在您面前这个莫迪斯的创造者。", },
	[174876] = {id=174876, zh_CN="“作者与作品”任务完成，与莫迪斯达成创作杰作关系。", },
