	[174955] = {id=174955, zh_CN="你躲开莫迪斯的关心，转身离开小屋。", },
	[174956] = {id=174956, zh_CN="莫迪斯疑惑地望着你离开的背影，", },
	[174957] = {id=174957, zh_CN="这段感情可能就此结束。", },
	[174958] = {id=174958, zh_CN="“恋爱辩论”任务完成，与莫迪斯达成未结果单恋关系。", },
	[174959] = {id=174959, zh_CN="我会努力变得更像人。", },
	[174960] = {id=174960, zh_CN="满足你对这段关系的想象。", },
