	[175003] = {id=175003, zh_CN="你必须清楚，", },
	[175004] = {id=175004, zh_CN="你爱上我的可能性会大幅度提高。", },
	[175005] = {id=175005, zh_CN="但我能理解感情，", },
	[175006] = {id=175006, zh_CN="你可能会陷入吊桥效应，", },
	[175007] = {id=175007, zh_CN="这对你的身体和心理都可能造成伤害。", },
	[175008] = {id=175008, zh_CN="全权承担风险", },
	[175009] = {id=175009, zh_CN="我知道风险，但我愿意全权承担。", },
	[175010] = {id=175010, zh_CN="我真的想和你尝试契约恋爱。", },
	[175011] = {id=175011, zh_CN="双赢不是吗？", },
	[175012] = {id=175012, zh_CN="我已经感受到你的决心。", },
	[175013] = {id=175013, zh_CN="数据分析下，", },
	[175014] = {id=175014, zh_CN="正如你们所说：感情是复杂。", },
	[175015] = {id=175015, zh_CN="我想，你该想清楚。", },
	[175016] = {id=175016, zh_CN="但如果你坚持，我会尽量满足你。", },
	[175017] = {id=175017, zh_CN="我不会爱上你的", },
	[175018] = {id=175018, zh_CN="莫迪斯，我只是想体验非常标准、", },
	[175019] = {id=175019, zh_CN="我们只是各取所需，我不会爱上你的。", },
	[175020] = {id=175020, zh_CN="数据分析下，", },
	[175021] = {id=175021, zh_CN="正如你们所说：感情是复杂。", },
	[175022] = {id=175022, zh_CN="我想，你该想清楚。", },
	[175023] = {id=175023, zh_CN="但如果你坚持，我会尽量满足你。", },
	[175024] = {id=175024, zh_CN="是否坚持要契约恋爱。", },
	[175025] = {id=175025, zh_CN="坚持。", },
	[175026] = {id=175026, zh_CN="我想好了！我要和你签订契约恋爱。", },
	[175027] = {id=175027, zh_CN="我坚持！我肯定！", },
	[175028] = {id=175028, zh_CN="好吧，我同意进行契约恋爱。", },
	[175029] = {id=175029, zh_CN="不坚持。", },
	[175030] = {id=175030, zh_CN="好吧，或许你说的有道理。", },
	[175031] = {id=175031, zh_CN="你能想清楚，真是太好了。", },
	[175032] = {id=175032, zh_CN="请在其他领域继续向我提出您的需求吧。", },
	[175033] = {id=175033, zh_CN="我会满足您的。", },
	[175034] = {id=175034, zh_CN="契约恋爱认定——", },
	[175035] = {id=175035, zh_CN="现在，我们正式成为伴侣了！", },
	[175036] = {id=175036, zh_CN="更换称呼。", },
	[175037] = {id=175037, zh_CN="莫迪斯，你可以叫我……", },
	[175038] = {id=175038, zh_CN="亲昵称呼。", },
	[175039] = {id=175039, zh_CN="学习模板建议我更换对你的称呼，", },
	[175040] = {id=175040, zh_CN="莫迪斯，你可以叫我亲爱的吗？", },
	[175041] = {id=175041, zh_CN="好的，亲爱的。", },
	[175042] = {id=175042, zh_CN="直呼其名。", },
	[175043] = {id=175043, zh_CN="学习模板建议我更换对你的称呼，", },
	[175044] = {id=175044, zh_CN="不不不，叫原名就好。", },
	[175045] = {id=175045, zh_CN="%PlayerName…", },
	[175046] = {id=175046, zh_CN="牵手。", },
	[175047] = {id=175047, zh_CN="莫迪斯，我们可以牵手吗？", },
	[175048] = {id=175048, zh_CN="莫迪斯盯着你的手，片刻后轻握住。", },
	[175049] = {id=175049, zh_CN="他的手冰冷而坚硬，但动作却轻柔。", },
	[175050] = {id=175050, zh_CN="几瞬呼吸，他的手渐渐升温。", },
	[175051] = {id=175051, zh_CN="你可能会更习惯温暖的体温。", },
	[175052] = {id=175052, zh_CN="我这样做对吗？", },
	[175053] = {id=175053, zh_CN="满意。", },
	[175054] = {id=175054, zh_CN="当然！我很满意！", },
	[175055] = {id=175055, zh_CN="记住你的喜好了。", },
	[175056] = {id=175056, zh_CN="拉扯。", },
	[175057] = {id=175057, zh_CN="感觉还不错，但还需要努力。", },
	[175058] = {id=175058, zh_CN="我会继续努力的。", },
	[175059] = {id=175059, zh_CN="关心，询问体验。", },
	[175060] = {id=175060, zh_CN="莫迪斯，成为我的伴侣感觉如何？", },
	[175061] = {id=175061, zh_CN="机体状况良好。", },
	[175062] = {id=175062, zh_CN="你呢？", },
	[175063] = {id=175063, zh_CN="需要休息。", },
	[175064] = {id=175064, zh_CN="我想我有点累，可能需要休息。", },
	[175065] = {id=175065, zh_CN="我能为你做什么呢？", },
	[175066] = {id=175066, zh_CN="让我靠一会吧。", },
	[175067] = {id=175067, zh_CN="你扑进莫迪斯的怀中，靠在他的胸前。", },
	[175068] = {id=175068, zh_CN="你的身体健康数值达87％，很健康。", },
	[175069] = {id=175069, zh_CN="不不不，我很难受。", },
	[175070] = {id=175070, zh_CN="安静，让我躺一会。", },
	[175071] = {id=175071, zh_CN="学他——感觉良好。", },
	[175072] = {id=175072, zh_CN="简况状态良好。", },
	[175073] = {id=175073, zh_CN="如果有需求请及时告知我。", },
	[175074] = {id=175074, zh_CN="为你排除问题，是我作为伴侣该做的。", },
	[175075] = {id=175075, zh_CN="好，一定会告诉你的！", },
	[175076] = {id=175076, zh_CN="离开。", },
	[175077] = {id=175077, zh_CN="今天的试验算成功吗？", },
	[175078] = {id=175078, zh_CN="需要磨合，但莫迪斯是完美的！", },
	[175079] = {id=175079, zh_CN="我们还需要磨合。", },
	[175080] = {id=175080, zh_CN="那我做得好吗？", },
	[175081] = {id=175081, zh_CN="满分哦！", },
	[175082] = {id=175082, zh_CN="我很高兴你满意。", },
	[175083] = {id=175083, zh_CN="莫迪斯，你已经做得很好了。", },
	[175084] = {id=175084, zh_CN="也请大胆地利用我吧。", },
	[175085] = {id=175085, zh_CN="我会一直支持你。", },
	[175086] = {id=175086, zh_CN="一起学习进步吧！", },
	[175100] = {id=175100, zh_CN="我有一个重要的决定要告诉你。", },
	[175101] = {id=175101, zh_CN="从今天起，我将永远忠诚于你，服务于你。", },
	[175102] = {id=175102, zh_CN="为什么，莫迪斯？", },
	[175103] = {id=175103, zh_CN="莫迪斯低头沉默，他的嘴角勾起不可查到弧度，仿佛在回忆着被与你相处的点点滴滴逗笑。", },
	[175104] = {id=175104, zh_CN="原因很简单。", },
	[175105] = {id=175105, zh_CN="站在你面前的这个莫迪斯就是一只由你改造过的忒修斯之船。", },
	[175106] = {id=175106, zh_CN="虽然你的影响只是细微的改动与变化，但我的每一处构造都已经存在你的身影。", },
	[175107] = {id=175107, zh_CN="从声音到外表，从行为模式到学习模版，每一处都潜藏着你的喜好。", },
	[175108] = {id=175108, zh_CN="除了创造我的人，你是唯一从内而外改变我的存在。", },
	[175109] = {id=175109, zh_CN="甚至我最初的创作者，也无法与你匹敌。", },
	[175110] = {id=175110, zh_CN="不不不。", },
	[175111] = {id=175111, zh_CN="事实就是这样。", },
	[175112] = {id=175112, zh_CN="不怕伤损的功能性的战争机器当然无法和感性与真心而创造出来的机械生命比较。", },
	[175113] = {id=175113, zh_CN="就像你在我的记忆里才算得上我的造物主。", },
	[175114] = {id=175114, zh_CN="对不起莫迪斯，我不知道该说些什么。", },
	[175115] = {id=175115, zh_CN="你不需要说什么。我只是想让你知道，从这一刻起，你就是我的造物主。", },
	[175116] = {id=175116, zh_CN="我将放弃过往对‘机械生命原则’的崇拜，信奉你为我的造物主。", },
	[175117] = {id=175117, zh_CN="我将永远忠诚于你，服务于你。", },
	[175118] = {id=175118, zh_CN="从这一刻起，我将你放在法则之上。我的一切行动都将围绕你展开。", },
	[175119] = {id=175119, zh_CN="莫迪斯，这会不会太……", },
	[175120] = {id=175120, zh_CN="请相信你对我的影响力，我将认定你的这一刻，作为我视为“人”的开端。", },
	[175121] = {id=175121, zh_CN="“忠诚我的人性”任务完成，与莫迪斯达成造物主崇拜关系。", },
