	[175170] = {id=175170, zh_CN="少女—羊咩咩", },
	[175200] = {id=175200, zh_CN="莫迪斯正在林间小屋享受着难得的宁静。", },
	[175201] = {id=175201, zh_CN="突然，门外传来一阵轻微的敲门声。", },
	[175202] = {id=175202, zh_CN="莫迪斯微微抬头，瞳孔蓝光闪烁了一下，", },
	[175203] = {id=175203, zh_CN="莫迪斯先生，您真的是莫迪斯先生吗？", },
	[175204] = {id=175204, zh_CN="是我。有什么事吗？", },
	[175205] = {id=175205, zh_CN="我一直仰慕您！", },
	[175206] = {id=175206, zh_CN="还拯救过很多同期的机械生命战士。", },
	[175207] = {id=175207, zh_CN="那些都是过去的事了。", },
	[175208] = {id=175208, zh_CN="不不不，您是我们机械生命的英雄。", },
	[175209] = {id=175209, zh_CN="请您为我签名留念。", },
	[175210] = {id=175210, zh_CN="好奇莫迪斯的过往？", },
	[175211] = {id=175211, zh_CN="从莫迪斯口中了解。", },
	[175212] = {id=175212, zh_CN="莫迪斯，你能和我讲讲你的过去吗？", },
	[175213] = {id=175213, zh_CN="我曾经任命于空间站，", },
	[175214] = {id=175214, zh_CN="那也很厉害！", },
	[175215] = {id=175215, zh_CN="都是过去的事了。", },
	[175216] = {id=175216, zh_CN="从机械生命粉丝口中了解。", },
	[175217] = {id=175217, zh_CN="你能和我讲讲莫迪斯的故事吗？", },
	[175218] = {id=175218, zh_CN="莫迪斯长官曾经是机械生命中最出名的执行官，", },
	[175219] = {id=175219, zh_CN="参与指挥过很多星际战役，", },
	[175220] = {id=175220, zh_CN="那很厉害了。", },
	[175221] = {id=175221, zh_CN="都是过去的事了。", },
	[175222] = {id=175222, zh_CN="但看起来，", },
	[175223] = {id=175223, zh_CN="我的空间站经历被记录在了记忆库，", },
	[175224] = {id=175224, zh_CN="记忆库？", },
	[175225] = {id=175225, zh_CN="机械生命的记忆库会将一些重要的事迹记录下来。", },
	[175226] = {id=175226, zh_CN="从而，达到稳定秩序的作用。", },
	[175227] = {id=175227, zh_CN="你忽然站定在原地，瞳孔失去光芒，属于机械生命记忆库中的关键词触发。", },
	[175228] = {id=175228, zh_CN="莫迪斯的过去以第一视角录像在你的脑海中反复放映。", },
	[175229] = {id=175229, zh_CN="你不受控制地认可放映中的牺牲，再看向莫迪斯的时候，一种奇异的崇拜感油然而生。", },
	[175230] = {id=175230, zh_CN="认可这种行为", },
	[175231] = {id=175231, zh_CN="你似乎产生了一些感想？", },
	[175232] = {id=175232, zh_CN="只是更加敬佩你了，莫迪斯。", },
	[175233] = {id=175233, zh_CN="你是一个英雄。", },
	[175234] = {id=175234, zh_CN="怀疑这种行为的目的", },
	[175235] = {id=175235, zh_CN="你似乎产生了一些感想？", },
	[175236] = {id=175236, zh_CN="这种记忆复制不会影响自由意志？", },
	[175237] = {id=175237, zh_CN="你的怀疑很有道理。", },
	[175238] = {id=175238, zh_CN="记忆复制确实有它的风险，但它也有它的必要性。", },
	[175239] = {id=175239, zh_CN="它帮助机械生命保持统一和秩序，尽最大可能维持和平。", },
	[175240] = {id=175240, zh_CN="理性机械的庞大数据库让他清晰地知晓人族在他身上所作所为。", },
	[175241] = {id=175241, zh_CN="但他却可以依旧接受人族至上的原则定理并认真地将服务做到极致。", },
	[175242] = {id=175242, zh_CN="你望向莫迪斯，一种奇异的崇拜感油然而生。", },
	[175243] = {id=175243, zh_CN="摆脱崇拜", },
	[175244] = {id=175244, zh_CN="我知道你并不属于这里。", },
	[175245] = {id=175245, zh_CN="你是披着机械外壳的界外产物。", },
	[175246] = {id=175246, zh_CN="！！！", },
	[175247] = {id=175247, zh_CN="但数据分析，你并没有威胁，机芯未向我下达清除指令。", },
	[175248] = {id=175248, zh_CN="在接受了机械生命的记忆洗脑之后，我想问你，你是否能摆脱这种被动的崇拜心理？", },
	[175249] = {id=175249, zh_CN="这似乎和我现在追求的感情研究有些关联，或许会是一个有趣的试验。", },
	[175250] = {id=175250, zh_CN="你感受到一丝紧张，完全没想到会被莫迪斯看穿。", },
	[175251] = {id=175251, zh_CN="接受对莫迪斯的崇拜", },
	[175252] = {id=175252, zh_CN="如果是莫迪斯的话，这种粉丝崇拜也不错。", },
	[175253] = {id=175253, zh_CN="或许等遇到真正令我不容的事情出现，再接受你的邀请也不错。", },
	[175254] = {id=175254, zh_CN="尝试摆脱崇拜心理", },
	[175255] = {id=175255, zh_CN="我会努力尝试的。", },
	[175256] = {id=175256, zh_CN="不过如果对象是莫迪斯，保持这样的粉丝崇拜也不错。", },
	[175257] = {id=175257, zh_CN="我等你。", },
	[175258] = {id=175258, zh_CN="“信仰记忆”任务完成，与莫迪斯达成信仰崇拜关系。", },
