	[175367] = {id=175367, zh_CN="与莫迪斯对话 在林间小屋初遇一位人形机械生命，似乎是一名修理师。", },
	[175368] = {id=175368, zh_CN="与莫迪斯对话 使用机械生命的《服务条例》，让莫迪斯成为你的朋友。", },
