	[175374] = {id=175374, zh_CN="与莫迪斯对话 与他更深入地研究亲情，探讨亲情，定义亲情。", },
	[175375] = {id=175375, zh_CN="与莫迪斯对话 莫迪斯想要邀请你共同完成某个实验，听听他的想法吧。", },
