	[175377] = {id=175377, zh_CN="与莫迪斯对话 偶遇莫迪斯的粉丝，了解机械生命的记忆继承和特殊的信仰崇拜。", },
	[175378] = {id=175378, zh_CN="与莫迪斯对话 或许可以和莫迪斯探讨一下机械生命特殊的信仰崇拜。", },
