	[175419] = {id=175419, zh_CN="测试交互对话14", },
	[175420] = {id=175420, zh_CN="机械手臂更适合我的工作需求，", },
	[175421] = {id=175421, zh_CN="如果要研究生命体的感情，", },
	[175422] = {id=175422, zh_CN="可以，我可以选择不同的声音模式。", },
	[175423] = {id=175423, zh_CN="莫迪斯的声音变得沙哑，", },
	[175424] = {id=175424, zh_CN="嘶——感觉看到了莫迪斯老时候。", },
	[175425] = {id=175425, zh_CN="你小心翼翼地拆掉莫迪斯的机械翼，", },
	[175426] = {id=175426, zh_CN="你为莫迪斯安装了仿生皮肤，", },
	[175427] = {id=175427, zh_CN="你为莫迪斯挑选了一套简单的衣服，", },
	[175428] = {id=175428, zh_CN="你好，%PlayerName。", },
	[175429] = {id=175429, zh_CN="我有一个问题想要询问你。", },
	[175430] = {id=175430, zh_CN="什么？", },
	[175431] = {id=175431, zh_CN="数据分析显示，", },
	[175432] = {id=175432, zh_CN="在这期间，", },
	[175433] = {id=175433, zh_CN="工作效率显著下降23％，", },
	[175434] = {id=175434, zh_CN="修理出错率上升0.8%…", },
	[175435] = {id=175435, zh_CN="这不符合我的工作状态，我的系统坏了。", },
	[175436] = {id=175436, zh_CN="我分析原因，只有你这一个变量。", },
	[175437] = {id=175437, zh_CN="我系统宕机的原因是什么吗？", },
	[175438] = {id=175438, zh_CN="失落。", },
	[175439] = {id=175439, zh_CN="你站在原地，没有作答。", },
	[175440] = {id=175440, zh_CN="许久…", },
	[175441] = {id=175441, zh_CN="莫迪斯，机械生命也会戒断吗？", },
	[175442] = {id=175442, zh_CN="戒断反应。", },
	[175443] = {id=175443, zh_CN="中枢分析中——", },
	[175444] = {id=175444, zh_CN="我的系统故障确实和戒断反应的表征相似。", },
	[175445] = {id=175445, zh_CN="这是否侧面证明我的系统在被情绪影响。", },
	[175446] = {id=175446, zh_CN="我现在，在与你分别而难过。", },
	[175447] = {id=175447, zh_CN="你说得对。", },
	[175448] = {id=175448, zh_CN="我想我们需要点时间冷静一下。", },
	[175449] = {id=175449, zh_CN="%PlayerName。", },
	[175450] = {id=175450, zh_CN="嗯？", },
	[175451] = {id=175451, zh_CN="我可能，对你产生了感情。", },
	[175452] = {id=175452, zh_CN="真的吗？我们的实验成功了？", },
	[175453] = {id=175453, zh_CN="经过持续观察与数据分析，", },
	[175454] = {id=175454, zh_CN="关于机械感情发展的实验，成功了。", },
	[175455] = {id=175455, zh_CN="我现在存在，想更新核心数据库的冲动。", },
	[175456] = {id=175456, zh_CN="你的喜好、习惯…", },
	[175457] = {id=175457, zh_CN="不再仅仅是用于优化服务或实验的数据。", },
	[175458] = {id=175458, zh_CN="我想将它们整合输入我的核心程序深处。", },
	[175459] = {id=175459, zh_CN="与我的底层法则并列。", },
	[175460] = {id=175460, zh_CN="我想将它们，你，与你相关的所有信息，", },
	[175461] = {id=175461, zh_CN="都认定为我存在的道标。", },
	[175462] = {id=175462, zh_CN="你愿意，让我继续学习。", },
	[175463] = {id=175463, zh_CN="如何成为你的完美伴侣？", },
	[175464] = {id=175464, zh_CN="我愿意！", },
	[175465] = {id=175465, zh_CN="我会不断前进的。", },
	[175466] = {id=175466, zh_CN="以莫迪斯的方式。", },
	[175468] = {id=175468, zh_CN="他们机体喷射出的热浪，", },
	[175469] = {id=175469, zh_CN="对不起。", },
	[175470] = {id=175470, zh_CN="莫迪斯抬头撇了你一眼，", },
	[175471] = {id=175471, zh_CN="便退到一旁，安静地等待着莫迪斯。", },
	[175472] = {id=175472, zh_CN="我需要你帮我去收集。", },
	[175473] = {id=175473, zh_CN="尤其是他刚刚拒绝过你。", },
	[175474] = {id=175474, zh_CN="是的。", },
	[175475] = {id=175475, zh_CN="除了空间站在编人员，", },
	[175476] = {id=175476, zh_CN="为72.333％，取无限小数。", },
