	[181999] = {id=181999, zh_CN="当月光拂过起居室的窗棂，我私心提笔向你倾诉心中的烦忧。\n 除了你，我不知道该向谁倾诉困扰。作为方舟的公主殿下，我被我的民众托举而起，我的所言所行承载着他们的期望，他们的目光环绕在我周身，赋予我无上的荣光。\n 除了你，我面对任何人，都无法放下权衡。与他们诉说我的烦闷，令我心有悔意与愧疚。我想要找寻一处休息之地，或许你会有办法的，对吗？\n 期望你能理解我的孤立无援，和你诉说这些已经用尽我的勇气，希望没有打扰到你。如果愿意，请带着这封信来找我吧。我现在需要你。\n 愿你一切安好。\n ——ThaTha", },
	[181401] = {id=181401, zh_CN="【新朋友】", },
	[181402] = {id=181402, zh_CN="与年糕对话", },
	[181403] = {id=181403, zh_CN="【师徒谈心】", },
	[181404] = {id=181404, zh_CN="与伙伴聊一聊", },
	[182000] = {id=182000, zh_CN="【阿加莎的烦恼信】", },
	[182001] = {id=182001, zh_CN="家园里好像收到一封来信", },
	[182002] = {id=182002, zh_CN="【伪装马甲初体验】", },
	[182003] = {id=182003, zh_CN="带着信前往城堡喷泉旁，帮助阿加莎开解烦恼。", },
	[182004] = {id=182004, zh_CN="前往家园，与家园中的阿加莎对话", },
	[182005] = {id=182005, zh_CN="一对母子", },
	[182006] = {id=182006, zh_CN="母亲", },
	[182007] = {id=182007, zh_CN="小男孩", },
	[182008] = {id=182008, zh_CN="家园", },
	[182009] = {id=182009, zh_CN="【秘密出游】", },
	[182010] = {id=182010, zh_CN="前往商会，和阿加莎对话", },
	[182011] = {id=182011, zh_CN="阿加莎的烦恼信", },
	[182012] = {id=182012, zh_CN="伪装马甲", },
	[182013] = {id=182013, zh_CN="【造访“记忆方舟”】", },
	[182014] = {id=182014, zh_CN="前往鸭湖城堡，和阿加莎对话", },
	[182015] = {id=182015, zh_CN="乐谱", },
	[182016] = {id=182016, zh_CN="使用侦查找找有什么线索吧", },
	[182017] = {id=182017, zh_CN="【联姻】", },
	[182018] = {id=182018, zh_CN="前往花房上，与阿加莎对话", },
	[182019] = {id=182019, zh_CN="【灵魂锚点】", },
	[182020] = {id=182020, zh_CN="阿加莎的邀请信", },
	[182021] = {id=182021, zh_CN="【“政治”真婚】", },
	[182022] = {id=182022, zh_CN="【庭台露面】", },
	[182023] = {id=182023, zh_CN="【一千夜最后一夜】", },
	[182024] = {id=182024, zh_CN="（屈膝礼）亲爱的%PlayerName阁下，祝你午安。", },
	[182025] = {id=182025, zh_CN="离开。", },
	[182026] = {id=182026, zh_CN="再会了，我的朋友。", },
	[182027] = {id=182027, zh_CN="伪装马甲初体验。", },
	[182028] = {id=182028, zh_CN="（挥手）阿加莎公主！我来了。", },
	[182029] = {id=182029, zh_CN="你还好吗？", },
	[182030] = {id=182030, zh_CN="亲爱的%PlayerName，请小声一点。", },
	[182031] = {id=182031, zh_CN="（气声）你，还，好，吗？", },
	[182032] = {id=182032, zh_CN="（扶额，摇头）说实话，不是很好。", },
	[182033] = {id=182033, zh_CN="我想我现在真的需要休息一下。", },
	[182034] = {id=182034, zh_CN="（点头）你需要离开这个环境才好。", },
	[182035] = {id=182035, zh_CN="（恳切握住阿加莎的手）我带你偷偷出去转转如何？", },
	[182036] = {id=182036, zh_CN="我想带你出去，哪怕只是短暂的时光，呼吸自由的空气会对你有帮助的。", },
	[182037] = {id=182037, zh_CN="（幻想）我们可以……", },
	[182038] = {id=182038, zh_CN="（温柔地打断）%PlayerName，不可以的。", },
	[182039] = {id=182039, zh_CN="（摇头）我的安全不完全属于我，在外面闲逛太过冒险，我不能让自己陷入风险之中。", },
	[182040] = {id=182040, zh_CN="（失落）", },
	[182041] = {id=182041, zh_CN="（再努力一下）去我的家园呢？我有信心那里足够安全，我只是想暂时让你逃离这些“责任”，哪怕挚友几个小时？", },
	[182042] = {id=182042, zh_CN="（沉默，眼中闪过动摇）……", },
	[182043] = {id=182043, zh_CN="（点头）好吧，但你必须帮我伪装一下，不能让人认出我来。", },
	[182044] = {id=182044, zh_CN="（点头）我会全力以赴的！", },
	[182045] = {id=182045, zh_CN="【换装关卡】", },
	[182046] = {id=182046, zh_CN="（望着打扮好的阿加莎）很漂亮。", },
	[182047] = {id=182047, zh_CN="（腼腆一笑）谢谢。", },
	[182048] = {id=182048, zh_CN="（伸出手）现在，我可以直呼你的名字吗？", },
	[182049] = {id=182049, zh_CN="当然可以。", },
	[182050] = {id=182050, zh_CN="阿加莎……", },
	[182051] = {id=182051, zh_CN="是否读心", },
	[182052] = {id=182052, zh_CN="不读心", },
	[182053] = {id=182053, zh_CN="魅力检定", },
	[182054] = {id=182054, zh_CN="理智检定", },
	[182055] = {id=182055, zh_CN="你好像错过了阿加莎的心声。", },
	[182056] = {id=182056, zh_CN="【第一次被直呼其名，好奇怪的感觉。（心中小人捂住胸口）心脏跳得好快！】", },
	[182057] = {id=182057, zh_CN="我们走吧。", },
	[182058] = {id=182058, zh_CN="我们走吧。", },
	[182059] = {id=182059, zh_CN="我们走吧。", },
	[182060] = {id=182060, zh_CN="我们走吧。", },
	[182061] = {id=182061, zh_CN="我们走吧。", },
	[182062] = {id=182062, zh_CN="我们走吧。", },
	[182063] = {id=182063, zh_CN="你的家园中，阳光透过落地窗洒进来。阿加莎略显拘谨地坐在会客区里，长发简单束起，脸上只化了淡妆，努力让自己看起来像个“普通人”。", },
	[182064] = {id=182064, zh_CN="你的家园中，阳光透过落地窗洒进来。阿加莎略显拘谨地坐在会客区里，长发简单束起，脸上只化了淡妆，努力让自己看起来像个“普通人”。", },
	[182065] = {id=182065, zh_CN="（端来两杯热茶）感觉怎么样？", },
	[182066] = {id=182066, zh_CN="（思考措辞）是不是和你在方舟……嗯，办公室的感觉很不一样？", },
	[182067] = {id=182067, zh_CN="（接过茶杯，指尖小心地触碰杯壁，眼神好奇地打量着周围。）", },
	[182068] = {id=182068, zh_CN="（轻轻抿了一口茶）非常……不同，谢谢你的茶。", },
	[182069] = {id=182069, zh_CN="这里……很安静。没有侍从待命在我的身边，我不需要时刻考虑自己仪态是否符合公主的礼仪。", },
	[182070] = {id=182070, zh_CN="我好像真正地在生活。", },
	[182071] = {id=182071, zh_CN="（她听着茶水搅动的声音） 这种感觉，很新奇。", },
	[182072] = {id=182072, zh_CN="是啊，这就是大家的日常。 想要做什么，只要不打扰别人，基本都可以。", },
	[182073] = {id=182073, zh_CN="我不知道该做什么，我平时会看书，（环顾四周）但这里没有我可以读的书。", },
	[182074] = {id=182074, zh_CN="（拿起通讯器晃了晃）比如……记录下这一刻怎么样？记录下普通人阿加莎的一天？", },
	[182075] = {id=182075, zh_CN="（微微歪头）记录？像公关摄影师那样吗？", },
	[182076] = {id=182076, zh_CN="（坐直身体，开始低头整理衣服）需要我摆出什么姿势吗？或者表情？我应该笑着还是严肃一点？", },
	[182077] = {id=182077, zh_CN="（抬头望你，她怔愣一瞬）我好像太沉浸在我的世界里了，对不起。", },
	[182078] = {id=182078, zh_CN="我没有做过这样的活动，所以，我有点紧张。", },
	[182079] = {id=182079, zh_CN="（笑着摇头） 不不不，那是工作。朋友之间记录生活，很随意的。", },
	[182080] = {id=182080, zh_CN="我们会把感情波动的瞬间定格下来，以后看到照片，当时的心情就好像活过来了一般。", },
	[182081] = {id=182081, zh_CN="重要的是那一刻的感受和分享的乐趣。", },
	[182082] = {id=182082, zh_CN="（拿出自己的手机，调出相机模式） 要不要试试？练习一下怎么被朋友拍照？", },
	[182083] = {id=182083, zh_CN="（看着手机镜头，身体明显僵硬了一下，手指无意识地绞着衣角）分享心情吗？", },
	[182084] = {id=182084, zh_CN="（尝试放松肩膀，但笑容有些勉强） 我可以试试看。", },
	[182085] = {id=182085, zh_CN="（环顾四周）就从……你觉得这杯茶味道不错开始？", },
	[182086] = {id=182086, zh_CN="是否读心", },
	[182087] = {id=182087, zh_CN="不读心", },
	[182088] = {id=182088, zh_CN="魅力检定", },
	[182089] = {id=182089, zh_CN="理智检定", },
	[182090] = {id=182090, zh_CN="（看着阿加莎摸摸自己的脸）你好像错过一些心声。", },
	[182091] = {id=182091, zh_CN="【天啊，镜头对着我……不是那种官方镜头……是记录我喝茶？这太私人了！】", },
	[182092] = {id=182092, zh_CN="【脸好像有点烫……他会不会觉得我很笨拙？】", },
	[182093] = {id=182093, zh_CN="（敏锐地捕捉到她的不自在，放下手机，语气温和）别紧张，阿加莎。不要把它当作拍照任务。", },
	[182094] = {id=182094, zh_CN="想想看，你现在只是在私人茶会上喝茶，你会做什么，按照习惯表现出来就好了。我会捕捉你最真实的瞬间的。", },
	[182095] = {id=182095, zh_CN="“真实的瞬间”……", },
	[182096] = {id=182096, zh_CN="（被你的话触动，深吸一口气，看向窗外，眼神渐渐柔和下来，她低头看着茶杯，嘴角浮现一丝真切的、放松的微笑。）", },
	[182097] = {id=182097, zh_CN="【拍照教程：阿加莎坐在沙发上，请拍下她“最真实的瞬间”，把美好的记忆留存下来吧。】", },
	[182098] = {id=182098, zh_CN="【提交照片，重新和阿加莎互动】", },
	[182099] = {id=182099, zh_CN="（迅速拿起手机，在她抬眼看过来时，捕捉到了那个自然流露的微笑）", },
	[182100] = {id=182100, zh_CN="对！就是这个感觉！", },
	[182101] = {id=182101, zh_CN="看！（把手机屏幕转向她） 很自然，很放松。", },
	[182102] = {id=182102, zh_CN="（凑近看着屏幕上的自己，有些惊讶） 这……真的是我？", },
	[182103] = {id=182103, zh_CN="镜头里的阿加莎褪去了精致的妆容和华服，时刻紧绷的姿态即使放松也保持着与生俱来的优雅气质。", },
	[182104] = {id=182104, zh_CN="而且，我们可以把这些觉得不错的照片或小视频，分享到社交媒体上，朋友们互相点赞评论，这样就把自己的快乐分享出去了。", },
	[182105] = {id=182105, zh_CN="不过为了保护你的隐私，我们可以创建一个全新的、完全匿名的账号。", },
	[182106] = {id=182106, zh_CN="（忽然想起上次的茶会）名字就叫…… “Momo_TeaTime”怎么样？", },
	[182107] = {id=182107, zh_CN="“Momo_TeaTime”…… （她轻声念着，眼中闪过一丝顽皮的光芒）", },
	[182108] = {id=182108, zh_CN="我还挺喜欢的。（主动掏出通讯器，有些不熟练地点开应用商店）我的账号都是外交部在管理，我应该怎么做，才能上传这个……嗯，记录我喝茶的“真实瞬间”？", },
	[182109] = {id=182109, zh_CN="【上传照片关卡—打开上传照片的玩法界面，点击添加文字，选择照片，发送】", },
	[182110] = {id=182110, zh_CN="【内容：一条Post发送出去，是一张下午茶的照片，文案上写着“新朋友家的茶，很香。”】", },
	[182111] = {id=182111, zh_CN="商会某处偏僻、爬满藤蔓的角落。夜晚，远处传来城市节日的喧嚣声。阿加莎的身影悄悄闪出。", },
	[182112] = {id=182112, zh_CN="她卸下了标志性的盘发，柔顺的雾紫色长发披散着，用一条简单的蓝色丝带束起一部分。穿着一条款式简洁的白色棉质连衣裙，外面套了件浅米色开衫，脸上只有淡淡的裸妆，戴着一副小巧的无框眼镜。她紧张地四处张望，手指紧紧抓着开衫的衣襟。：衣服可能要修改，根据最终衣服模型来定。", },
	[182113] = {id=182113, zh_CN="（小跑到你面前，声音压得极低。）这样……真的可以吗？不会被认出来吧？", },
	[182114] = {id=182114, zh_CN="（她不自在地扯了扯裙摆）希望看起来不太奇怪？", },
	[182115] = {id=182115, zh_CN="是否读心", },
	[182116] = {id=182116, zh_CN="不读心", },
	[182117] = {id=182117, zh_CN="魅力检定", },
	[182118] = {id=182118, zh_CN="理智检定", },
	[182119] = {id=182119, zh_CN="你好像错过了阿加莎的心声。", },
	[182120] = {id=182120, zh_CN="【天啊心跳快得像要蹦出来！比第一次主持晨会还紧张一百倍！】", },
	[182121] = {id=182121, zh_CN="【裙子会不会有褶皱？眼镜滑下来了……希望路灯够暗！千万不要有人认出我来。】", },
	[182122] = {id=182122, zh_CN="（忍住笑意，低声安抚）你现在看起来就像个刚下课的学生。放松点，你现在可是Momo，不会有人注意到我们的。", },
	[182123] = {id=182123, zh_CN="（自然地伸出手。）", },
	[182124] = {id=182124, zh_CN="（犹豫了一下，还是轻轻搭上你的手，指尖微凉）", },
	[182125] = {id=182125, zh_CN="（绽放笑容）让我看看吧，你会带我去向何方。", },
	[182126] = {id=182126, zh_CN="【插画】", },
	[182127] = {id=182127, zh_CN="热闹的节日市集。灯火璀璨，人声鼎沸，各种小吃香气混合，街头艺人表演吸引着人群。", },
	[182128] = {id=182128, zh_CN="阿加莎像第一次进游乐场的孩子，眼睛亮晶晶的，充满好奇。", },
	[182129] = {id=182129, zh_CN="（看得目不转睛，小心地鼓掌，小声惊叹） 哇……他们好厉害！", },
	[182130] = {id=182130, zh_CN="但还是要做好防护才对……哦不，我是说……这需要很强的技巧", },
	[182131] = {id=182131, zh_CN="（她意识到自己又用了“官方思维”，不好意思地吐了吐舌头）", },
	[182132] = {id=182132, zh_CN="你和阿加莎走到至一个卖可丽饼的摊位旁。", },
	[182133] = {id=182133, zh_CN="试试这个？经典草莓奶油味，市集必吃。", },
	[182134] = {id=182134, zh_CN="（看着摊主熟练的操作，有些犹豫）这个……卫生吗？我是说……看起来很好吃！", },
	[182135] = {id=182135, zh_CN="（望着你递来的可丽饼，在你的期望与鼓励的目光下接过一份，小心地咬了一口，奶油沾到嘴角）", },
	[182136] = {id=182136, zh_CN="唔……好甜！但……非常有趣！", },
	[182137] = {id=182137, zh_CN="（她像发现新大陆，又咬了一大口，眼睛满足地眯起）", },
	[182138] = {id=182138, zh_CN="（带她到一个套圈游戏摊前） 来试试运气？", },
	[182139] = {id=182139, zh_CN="你想要哪个？", },
	[182140] = {id=182140, zh_CN="目标是那个丑萌丑萌的独角兽！", },
	[182141] = {id=182141, zh_CN="（兴致勃勃地接过塑料圈，学着前面人的样子瞄准，扔出去——偏得离谱） 啊呀！好难！", },
	[182142] = {id=182142, zh_CN="（屏住呼吸，全神贯注地盯着地上的玩偶，收腕，抛出！）", },
	[182143] = {id=182143, zh_CN="我中了！看！小兔子！", },
	[182144] = {id=182144, zh_CN="（她举起战利品，笑容灿烂，完全忘记了形象管理）", },
	[182145] = {id=182145, zh_CN="（大笑） 恭喜Momo首战告捷！战利品很可爱哦！", },
	[182146] = {id=182146, zh_CN="（带她到一个套圈游戏摊前） 来试试运气？", },
	[182147] = {id=182147, zh_CN="忽然，人潮涌来，阿加莎被挤得一个踉跄，鼻梁上的眼镜差点掉落，阿加莎连忙扶起眼睛，惊魂未定。", },
	[182148] = {id=182148, zh_CN="（下意识紧紧抓住了你的衣袖，几乎半个身子靠过来寻求稳定） 啊！", },
	[182149] = {id=182149, zh_CN="（人潮稍退，她像触电般立刻松开手，脸颊飞起红晕，低头整理并不乱的头发） 对……对不起，人太多了……", },
	[182150] = {id=182150, zh_CN="（感受到她瞬间的依赖，心跳也漏了一拍，声音放柔） 没事，抓紧点安全。来，试试套圈？ （递给她圈）", },
	[182151] = {id=182151, zh_CN="（接过圈，心思却明显不在游戏上，目光总是不自觉地瞟向你专注的侧脸。）", },
	[182152] = {id=182152, zh_CN="（将刚刚抛到的小兔子递给她。）呐！小兔子。", },
	[182153] = {id=182153, zh_CN="（接过玩偶，指尖不经意触碰到你的手，像被烫到般迅速收回，低头看着兔子，声音细如蚊呐） 谢……谢谢。这个……很可爱。", },
	[182154] = {id=182154, zh_CN="（她把小兔子紧紧抱在怀里）", },
	[182155] = {id=182155, zh_CN="是否读心", },
	[182156] = {id=182156, zh_CN="不读心", },
	[182157] = {id=182157, zh_CN="魅力检定", },
	[182158] = {id=182158, zh_CN="理智检定", },
	[182159] = {id=182159, zh_CN="你好像错过了阿加莎的心声。", },
	[182160] = {id=182160, zh_CN="【他的手好温暖……】", },
	[182161] = {id=182161, zh_CN="【阿加莎，清醒点！这只是一次……工作间隙中的休息！】", },
	[182162] = {id=182162, zh_CN="【但这个小兔子真的好可爱……】", },
	[182163] = {id=182163, zh_CN="（带她到一个套圈游戏摊前） 来试试运气？", },
	[182164] = {id=182164, zh_CN="（刚要点头，目光扫过旁边摊位挂着的、带有拒绝妖灵族光顾符号的装饰品，身体猛地一僵，下意识抓住你的胳膊想拉你离开）", },
	[182165] = {id=182165, zh_CN="我们……我们去那边看看吧！", },
	[182166] = {id=182166, zh_CN="（声音带着一丝不易察觉的颤抖）", },
	[182167] = {id=182167, zh_CN="（感受到她的僵硬和视线方向，心下了然，眼神暗了暗） 好，听你的。", },
	[182168] = {id=182168, zh_CN="阿加莎在一个妖灵族部落特色手工编织的摊位前阿加莎停下脚步，眼神复杂。", },
	[182169] = {id=182169, zh_CN="（指着一种复杂的编织纹样，声音艰涩） 这个纹样……我在外交文献里见过。", },
	[182170] = {id=182170, zh_CN="阿加莎；（努力寻找话题）它代表……勇气与守护，对吗？", },
	[182171] = {id=182171, zh_CN="（于心不忍，握住阿加莎的肩膀，低声提议） 阿加莎，这里人越来越多了，要不……我们先回去？", },
	[182172] = {id=182172, zh_CN="（如释重负，但立刻涌上浓浓的歉意和失落，看向你的眼神充满挣扎）", },
	[182173] = {id=182173, zh_CN="对不起……我……我是不是扫兴了？", },
	[182174] = {id=182174, zh_CN="（看着阿加莎的侧脸，越看越疑惑，忍不住轻轻碰了碰旁边你的胳膊，压低声音）", },
	[182175] = {id=182175, zh_CN="（她的眼神既期待又有些不敢置信）诶，先生，打扰一下……那位小姐……看着好眼熟啊？是不是……是不是阿加莎公主殿下？", },
	[182176] = {id=182176, zh_CN="（心中一凛，面上保持镇定，同样压低声音） 您认错了吧？公主殿下怎么会在这里？", },
	[182177] = {id=182177, zh_CN="（扯着妈妈的衣角，兴奋地指着阿加莎，声音清脆响亮） 妈妈妈妈！是公主！电视里的漂亮公主！我想和公主拍照！", },
	[182178] = {id=182178, zh_CN="小男孩的声音不大不小，周围几个人都好奇地看了过来。阿加莎听到“公主”二字，身体瞬间僵住，脸上的笑容凝固了，下意识地后退半步，几乎要躲到你身后，手指紧张地攥紧了裙角。眼镜后的眼神充满了慌乱和一丝被戳穿的窘迫。", },
	[182179] = {id=182179, zh_CN="哎呀！真的是公主殿下！太荣幸了！", },
	[182180] = {id=182180, zh_CN="（她拉着小男孩挤到阿加莎面前，激动又有些语无伦次）", },
	[182181] = {id=182181, zh_CN="殿下！真没想到能在这里遇见您！我……我和我家小宝，都是您的忠实粉丝！他天天嚷着要像公主一样勇敢！", },
	[182182] = {id=182182, zh_CN="那个……那个……能不能……求您和我们合个影？就一张！拜托了！", },
	[182183] = {id=182183, zh_CN="（她双手合十，眼神充满恳求。小男孩也仰着头，大眼睛亮晶晶地看着阿加莎。）", },
	[182184] = {id=182184, zh_CN="是否读心", },
	[182185] = {id=182185, zh_CN="不读心", },
	[182186] = {id=182186, zh_CN="魅力检定", },
	[182187] = {id=182187, zh_CN="理智检定", },
	[182188] = {id=182188, zh_CN="你好像错过了阿加莎的心声。", },
	[182189] = {id=182189, zh_CN="【完了……被认出来了！护卫呢？记者会不会在附近？】", },
	[182190] = {id=182190, zh_CN="【现在该怎么办？拒绝会让他们失望……可答应的话……】", },
	[182191] = {id=182191, zh_CN="（努力维持镇定，但声音明显有些发紧，带着一丝不易察觉的颤抖，她下意识地看向你，） 我……这位女士，您可能……", },
	[182192] = {id=182192, zh_CN="（她想再次否认，但看着小男孩纯真期待的眼神，话又咽了回去。她深吸一口气，属于公主的责任感和亲民形象占了上风，脸上勉强挤出一个温和但略显僵硬的标准微笑）", },
	[182193] = {id=182193, zh_CN="……好吧。只是一张快照，可以吗？", },
	[182194] = {id=182194, zh_CN="隔开阿加莎和母子俩。", },
	[182195] = {id=182195, zh_CN="（用身躯将阿加莎与母子俩不动声色地隔离开来。）", },
	[182196] = {id=182196, zh_CN="女士，请带着您的孩子随我去比较安静的地方好吗？", },
	[182197] = {id=182197, zh_CN="为了阿加莎殿下的安全考虑，我们悄悄地合影。", },
	[182198] = {id=182198, zh_CN="（点头）好好好。", },
	[182199] = {id=182199, zh_CN="平复母子俩的激动。", },
	[182200] = {id=182200, zh_CN="你好这位女士，阿加莎殿下已经答应您合影了，但希望您能保持镇定。", },
	[182201] = {id=182201, zh_CN="我想您也不想招来更多的人影响节日庆典是吧？", },
	[182202] = {id=182202, zh_CN="（点头）对对对，我们小声一点。", },
	[182203] = {id=182203, zh_CN="女士，请带着您的孩子随我去比较安静的地方好吗？", },
	[182204] = {id=182204, zh_CN="为了阿加莎殿下的安全考虑，我们悄悄地合影。", },
	[182205] = {id=182205, zh_CN="（点头）好好好。", },
	[182206] = {id=182206, zh_CN="安抚好母子俩，你引领着母子俩走在阿加莎身后，你目不转睛地注视着阿加莎挺直的背脊，想要用灼热的目光为她提供力量。", },
	[182207] = {id=182207, zh_CN="阿加莎在一处花坛停下脚步，她求助般地回头望向你。", },
	[182208] = {id=182208, zh_CN="（做出请的姿势）两位，就在这里和殿下拍照，好吗？", },
	[182209] = {id=182209, zh_CN="（喜出望外） 太好了！太感谢您了殿下！小宝，快站好！要笑哦！", },
	[182210] = {id=182210, zh_CN="（她赶紧把兴奋得蹦跳的小男孩按在身边，自己站在阿加莎另一侧。）", },
	[182211] = {id=182211, zh_CN="（对你自然地递过自己的手机） 这位先生，麻烦您帮我们拍一下好吗？用这个！小宝，别傻站着，快摆个帅气的姿势给公主看！", },
	[182212] = {id=182212, zh_CN="（他立刻挺起小胸脯，一手叉腰，一手比了个自认很酷的“V”字，咧开嘴露出缺了颗门牙的笑容。）", },
	[182213] = {id=182213, zh_CN="（立刻接过手机，熟练地打开相机，半蹲下来找角度，笑着引导） 没问题！小宝，姿势很帅哦！公主殿下，您也放松点，看镜头！对，就这样，自然的笑容最好看！1， 2， 3……茄子！", },
	[182214] = {id=182214, zh_CN="（你的语气轻松自然，像在帮普通朋友拍照，有效缓解了阿加莎的紧张。）", },
	[182215] = {id=182215, zh_CN="（在你自然的引导下，紧绷的肩膀微微放松，看着镜头里小男孩搞怪的样子，嘴角终于勾起一丝更真实的、带着点无奈的温柔笑意。）", },
	[182216] = {id=182216, zh_CN="【拍照智能引导教程】", },
	[182217] = {id=182217, zh_CN="咔嚓——一张照片慢慢成像。 （接过手机查看，非常满意） 拍得太好了！谢谢殿下！", },
	[182218] = {id=182218, zh_CN="小宝，快谢谢公主殿下！ （恢复了部分从容，微微颔首） 不客气。祝你们节日愉快。", },
	[182219] = {id=182219, zh_CN="（恢复了部分从容，微微颔首） 不客气。祝你们节日愉快。", },
	[182220] = {id=182220, zh_CN="（她看向你，眼神带着一丝“快走”的暗示和完成“任务”后的轻微释然。）", },
	[182221] = {id=182221, zh_CN="（沉稳地接过手机，目光快速扫过周围环境确认安全，然后专注地看向镜头，声音温和但带着安抚的力量）", },
	[182222] = {id=182222, zh_CN="好的。殿下，请放松。小宝，你的姿势非常棒！看我这里……", },
	[182223] = {id=182223, zh_CN="（你调整位置，特意将阿加莎置于画面中心稍靠后的安全位置） 1， 2， 3……", },
	[182224] = {id=182224, zh_CN="（在你沉稳的声音中找到了依靠感，身体不自觉地微微向你所在方向倾斜了一点点。脸上飞起红霞。）", },
	[182225] = {id=182225, zh_CN="【拍照智能引导教程】", },
	[182226] = {id=182226, zh_CN="咔嚓——一张照片慢慢成像。 （没注意到这个小细节，只顾着看照片）", },
	[182227] = {id=182227, zh_CN="哎呀拍得真精神！殿下您真美！小宝快谢谢！", },
	[182228] = {id=182228, zh_CN="（心跳还未平复，强自镇定地点头，声音比平时更轻柔）", },
	[182229] = {id=182229, zh_CN="谢谢。祝你们玩得开心。", },
	[182230] = {id=182230, zh_CN="（她匆匆瞥了你一眼，那眼神里有羞涩，有感激，也有一丝被触碰后的慌乱。）", },
	[182231] = {id=182231, zh_CN="就在母亲递过手机时，阿加莎眼角的余光忽然瞥见不远处一个小摊上挂着的拒绝妖灵族光顾符号的装饰品，她瞳孔猛地一缩！不顾形象地想要将自己藏起来。 （敏锐地察觉到阿加莎瞬间的僵硬和恐惧，立刻上前半步，巧妙地用身体挡住了阿加莎看向那个摊位的视线，同时迅速接过手机", },
	[182232] = {id=182232, zh_CN="（语气比前两条线更急切。）", },
	[182233] = {id=182233, zh_CN="好的，马上拍。小宝看镜头！笑！", },
	[182234] = {id=182234, zh_CN="（你几乎没怎么调整，快速按下快门 ）", },
	[182235] = {id=182235, zh_CN="【拍照智能引导教程】", },
	[182236] = {id=182236, zh_CN="咔嚓——一张照片慢慢成像。", },
	[182237] = {id=182237, zh_CN="（在你挡住视线的瞬间，身体几不可查地颤抖了一下，脸上勉强维持的笑容变得极其苍白脆弱。）", },
	[182238] = {id=182238, zh_CN="（拿到照片，虽然觉得拍得有点仓促，但还是很开心）", },
	[182239] = {id=182239, zh_CN="谢谢殿下！谢谢您！小宝……", },
	[182240] = {id=182240, zh_CN="（没等小男孩道谢，就快速而略显生硬地打断，声音带着一丝不易察觉的急促和疏离）", },
	[182241] = {id=182241, zh_CN="不客气。请……请享受节日。", },
	[182242] = {id=182242, zh_CN="（她几乎是立刻转身，下意识地抓住了你的手臂，低声急促道） 我们……快离开这里。", },
	[182243] = {id=182243, zh_CN="（她的指尖冰凉，带着明显的惊悸。）", },
	[182244] = {id=182244, zh_CN="就在这时，一位穿着便装但气质精悍的男子悄然出现在不远处，目光锁定阿加莎。", },
	[182245] = {id=182245, zh_CN="（瞬间，阿加莎眼中所有的轻松、好奇、羞涩或挣扎如潮水般褪去，背脊挺得笔直，脸上迅速挂起一丝程式化的平静，她回头朝护卫方向几不可察地点了下头。）", },
	[182246] = {id=182246, zh_CN="（转向你，又回到了属于公主那温和，暖意的躯壳）非常感谢您，今天……非常、非常难忘。", },
	[182247] = {id=182247, zh_CN="（她快速行了一个极其微小、近乎朋友间点头礼的屈膝动作）", },
	[182248] = {id=182248, zh_CN="期待下次再会。", },
	[182249] = {id=182249, zh_CN="（眼中闪过一丝俏皮，随即转身，步履从容却快速地走向护卫，那个穿着素裙的纤细背影很快融入节日的人潮中，消失不见。）", },
	[182250] = {id=182250, zh_CN="阿加莎的私人收藏馆门口。这里没有王宫大厅的金碧辉煌，更像一个充满故事的老书房。厚重的橡木门虚掩着，门缝里透出温暖柔和的灯光和旧书、木头、干花混合的独特气息。", },
	[182251] = {id=182251, zh_CN="阿加莎亲自站在门口迎接，她穿着一条舒适的雾紫色羊毛长裙，长发松松挽起，脸上带着期待的微笑。", },
	[182252] = {id=182252, zh_CN="（看到你，笑容加深） 你来了！欢迎来到我的‘记忆方舟’。", },
	[182253] = {id=182253, zh_CN="（她侧身让你进门） 这里存放的，都是时间留下的碎片，一些……对我有特殊意义的‘证物’。", },
	[182254] = {id=182254, zh_CN="今天想请你玩一个游戏，一个……只有你能参与的解谜游戏。", },
	[182255] = {id=182255, zh_CN="（环顾四周，被琳琅满目又充满个人色彩的收藏品吸引） 这里太棒了！像是走进了你的时间胶囊。", },
	[182256] = {id=182256, zh_CN="什么游戏？", },
	[182257] = {id=182257, zh_CN="（眼中闪着狡黠的光）一个寻‘我’游戏。线索就藏在这些物件里。我会给你第一个提示，然后你需要通过它们之间的关联，找到最终指向我的‘钥匙’，打开那扇门。", },
	[182258] = {id=182258, zh_CN="（她指向收藏馆深处一扇紧闭的、雕刻着复杂花纹的木门） 我在门后等你。准备好了吗？", },
	[182259] = {id=182259, zh_CN="（被勾起了兴趣） 当然！放马过来吧，‘Momo小姐。", },
	[182260] = {id=182260, zh_CN="（轻笑，递过来一张泛黄的乐谱纸，上面只有几行音符） 这是第一个线索。", },
	[182261] = {id=182261, zh_CN="（说完，她转身，像一尾灵活的鱼，滑入了藏品之间，很快不见了踪影。）", },
	[182262] = {id=182262, zh_CN="侦察", },
	[182263] = {id=182263, zh_CN="乐谱的角落上写着：凝固的时间之歌，答案在‘心跳’与‘回响’之间。", },
	[182264] = {id=182264, zh_CN="你想到了", },
	[182265] = {id=182265, zh_CN="音乐", },
	[182266] = {id=182266, zh_CN="结合乐谱，你联想到音乐或者乐器，很快在一个玻璃展柜里发现了一个精美的古董八音盒。", },
	[182267] = {id=182267, zh_CN="你选择……", },
	[182268] = {id=182268, zh_CN="观察八音盒", },
	[182269] = {id=182269, zh_CN="你忽然想到“回响”，八音盒确实会产生很清脆的回响音乐，或许你找到关键了。", },
	[182270] = {id=182270, zh_CN="八音盒上有一个心形发条……", },
	[182271] = {id=182271, zh_CN="再找找别的", },
	[182272] = {id=182272, zh_CN="八音盒旁边放着一本翻开的、阿加莎少女时代的日记。", },
	[182273] = {id=182273, zh_CN="上面稚嫩的笔迹写着：……收到这个八音盒，拧紧发条，听着叮咚声，感觉时间都变慢了，像被施了魔法……", },
	[182274] = {id=182274, zh_CN="八音盒！", },
	[182275] = {id=182275, zh_CN="你立刻抓起旁边的八音盒，盒子屁股有一个心形发条。", },
	[182276] = {id=182276, zh_CN="拧动发条", },
	[182277] = {id=182277, zh_CN="你拧动八音盒发条，清脆的音乐流淌出来。", },
	[182278] = {id=182278, zh_CN="音乐停止时，八音盒底部一个小暗格“咔哒”一声弹开，里面竟然是一张小小的拍立得照片", },
	[182279] = {id=182279, zh_CN="照片上正是上次市集，阿加莎拍下的、她拿着可丽饼嘴角沾着奶油的瞬间！她的脑袋只占了照片的二分之一，另一边的某个角落里，正是你的身影。", },
	[182280] = {id=182280, zh_CN="（你的心跳微微加速，迅速将照片翻到背面。）", },
	[182281] = {id=182281, zh_CN="照片背面写着一个词Perspective” （视角） 和一个指向馆内某个方向的箭头。", },
	[182282] = {id=182282, zh_CN="再找找", },
	[182283] = {id=182283, zh_CN="能形成回响的事物？", },
	[182284] = {id=182284, zh_CN="心形或者心脏意象？", },
	[182285] = {id=182285, zh_CN="立刻联想到关于心脏，心形的意象，在馆内搜寻起来。", },
	[182286] = {id=182286, zh_CN="你找到了不少东西，长腿长脚的心形玩偶；栩栩如生的心脏玻璃制品；闪烁着跳动心脏的数码屏幕……", },
	[182287] = {id=182287, zh_CN="你觉得什么比较可疑？", },
	[182288] = {id=182288, zh_CN="心形玩偶", },
	[182289] = {id=182289, zh_CN="你捏了捏玩偶，里面除了软乎的棉花，似乎没有任何可疑的硬物……", },
	[182290] = {id=182290, zh_CN="玻璃制品", },
	[182291] = {id=182291, zh_CN="你将玻璃心脏举到灯光下检查，似乎除了隐约能拼出奇怪图案，什么发现都没有……", },
	[182292] = {id=182292, zh_CN="数码屏幕", },
	[182293] = {id=182293, zh_CN="你上前仔细端详了屏幕半天，除了每30秒重复一次的视频，一无所获。", },
	[182294] = {id=182294, zh_CN="放下，找点别的。", },
	[182295] = {id=182295, zh_CN="再观察观察", },
	[182296] = {id=182296, zh_CN="时间一分一秒过去，你终于放弃了它，它并不是那个被阿加莎选中的幸运儿。", },
	[182297] = {id=182297, zh_CN="着箭头方向，你来到一个画架前。画架上蒙着布。掀开布，是一幅未完成的抽象画，色彩大胆泼辣，但构图有些混乱。", },
	[182298] = {id=182298, zh_CN="你选择……", },
	[182299] = {id=182299, zh_CN="观察四周", },
	[182300] = {id=182300, zh_CN="你蹲下来四周瞥眼扫过，画架旁放着调色板和画笔。画架旁的小桌上，放着上次阿加莎写的一封信。", },
	[182301] = {id=182301, zh_CN="……有时候，跳出固有的框架，换个角度看世界，或许会有意想不到的风景……”", },
	[182302] = {id=182302, zh_CN="换个角度看世界？？", },
	[182303] = {id=182303, zh_CN="你一边思考着信中的信息，一边转换着方位观察画作……", },
	[182304] = {id=182304, zh_CN="忽然，你停在某个角度上，从这里往画作上看去，凹凸不平的干枯画料，似乎在光影间形成了有规则的线条。", },
	[182305] = {id=182305, zh_CN="分析画作", },
	[182306] = {id=182306, zh_CN="你凑近仔细观察着画作，除了发现画作没有完成外，没有任何可疑的地方。", },
	[182307] = {id=182307, zh_CN="观察四周", },
	[182308] = {id=182308, zh_CN="上手摸摸", },
	[182309] = {id=182309, zh_CN="你伸手轻轻触摸画上的油料，已经干透，于是你便大胆地摸过画作，每个角落都不放过。", },
	[182310] = {id=182310, zh_CN="奇怪的凹凸，以及若隐若现的阴影，难道……", },
	[182311] = {id=182311, zh_CN="（环顾四周，你找到一盏可调节角度的阅读灯，调整着灯光的角度照向画布。）", },
	[182312] = {id=182312, zh_CN="当灯光以一个特定的斜角照射在画布上时，那些看似混乱的色块在墙上投射出一个清晰的影子——一个钥匙孔的形状！ 影子旁边，用极淡的铅笔写着什么。", },
	[182313] = {id=182313, zh_CN="（你上前检查）", },
	[182314] = {id=182314, zh_CN="上面写着“找到锁” 。", },
	[182315] = {id=182315, zh_CN="钥匙孔……锁……你开始在馆内寻找可能隐藏锁孔的地方。", },
	[182316] = {id=182316, zh_CN="最终，你的目光落在了一排书架侧面一个不起眼的、装饰性的木雕纹路上。", },
	[182317] = {id=182317, zh_CN="其中一个纹路的中心，仔细看，正是一个小小的锁孔！", },
	[182318] = {id=182318, zh_CN="但钥匙在哪里？线索断了？", },
	[182319] = {id=182319, zh_CN="你回想之前的线索……", },
	[182320] = {id=182320, zh_CN="画作，视角，照片，八音盒，音乐", },
	[182321] = {id=182321, zh_CN="视角，画作，市集照片，回响，八音盒", },
	[182322] = {id=182322, zh_CN="画作，市集照片，视角，音乐，八音盒", },
	[182323] = {id=182323, zh_CN="似乎没有什么关联，再想想？", },
	[182324] = {id=182324, zh_CN="来自市集照片，市集照片来自八音盒，八音盒关联时间……", },
	[182325] = {id=182325, zh_CN="你再次看向那幅未完成的画。画的主题是什么？", },
	[182326] = {id=182326, zh_CN="你拿起旁边阿加莎常用的速写本翻看，里面夹着许多草图。其中一张，画的是一个女孩的背影，正透过一扇圆形的窗户眺望远方，窗框的形状……正是一个钥匙孔！速写下方写着：“我看见你的地方” 。", },
	[182327] = {id=182327, zh_CN="你猛地抬头，环顾四周。收藏馆唯一的窗户是方形的。", },
	[182328] = {id=182328, zh_CN="你想起第一次来参加阿加莎的茶会时，她坐在这里喝茶看风景的样子……", },
	[182329] = {id=182329, zh_CN="你快步走向收藏馆深处那扇紧闭的门，在门旁边的墙上，挂着一幅小尺寸的油画。", },
	[182330] = {id=182330, zh_CN="画中是你家园能看见的城市夜景，视角正是阿加莎当时坐的位置！", },
	[182331] = {id=182331, zh_CN="画的右下角，用极细的笔写着：“钥匙在凝视中” 。", },
	[182332] = {id=182332, zh_CN="凝视……你站在门前，看着那扇紧闭的门。", },
	[182333] = {id=182333, zh_CN="（再想想）", },
	[182334] = {id=182334, zh_CN="你想起阿加莎说“我在门后等你”。凝视……难道是……？", },
	[182335] = {id=182335, zh_CN="你凑近门上那个雕刻精美的猫眼（窥视孔），向内看去。里面一片漆黑。", },
	[182336] = {id=182336, zh_CN="（你仔细观察发现猫眼可以左右转动，一共可以转动五次，每次都能听到咔哒声，你决定尝试一下）", },
	[182337] = {id=182337, zh_CN="qte", },
	[182338] = {id=182338, zh_CN="几秒钟后，门内传来轻微的“咔哒”声——门锁开了！", },
	[182339] = {id=182339, zh_CN="你推开门，里面是一个更私密、更温馨的小房间，更像一个画室。", },
	[182340] = {id=182340, zh_CN="阿加莎正坐在窗边的画架前，背对着门。听到开门声，她转过身，脸上是毫不掩饰的惊喜和赞赏的笑容。", },
	[182341] = {id=182341, zh_CN="（她站起身，眼中闪着兴奋的光） 太棒了！你竟然真的解开了！比我预想的快多了！那些线索……感觉如何？”", },
	[182342] = {id=182342, zh_CN="（走进房间，仍沉浸在解谜的兴奋中） 挺有意思的！没想到线索全部都是阿加莎的记忆呢！", },
	[182343] = {id=182343, zh_CN="（脸微红，点点头）嗯……听到自己那么……‘放肆’的笑声，有点不好意思。", },
	[182344] = {id=182344, zh_CN="恭喜你解密成功，作为奖励，带你看看这些‘证物’背后的故事。", },
	[182345] = {id=182345, zh_CN="（热情地指着一个展柜） 看这个！我第一次独立主持小型外交晚宴时，紧张得手心全是汗，把演讲稿都捏成了咸菜干！", },
	[182346] = {id=182346, zh_CN="（柜子里是那份皱巴巴的演讲稿） 还有这个，学院时最好的朋友送的明信片，来自她家乡的海滩，颜色都快晒没了……", },
	[182347] = {id=182347, zh_CN="（褪色的明信片） 这副旧手套，是我偷偷跑去陆军训练营体验时磨破的，被父王发现后训了好久……", },
	[182348] = {id=182348, zh_CN="（她走到最重要的一个展柜，里面整齐排列着她写过的所有信件，里面也有你与她互通过的信件，旁边贴着许多她手写的感想便签）", },
	[182349] = {id=182349, zh_CN="这些……就不用我多说了吧？伙伴的珍贵墨宝！", },
	[182350] = {id=182350, zh_CN="（她忽然撇到被你收起放在八音盒旁的照片） 这个就不要看！", },
	[182351] = {id=182351, zh_CN="（笑）那你还作为线索。", },
	[182352] = {id=182352, zh_CN="（脸红）…… （在那副色彩狂放、笔触稚嫩的抽象涂鸦前停下，转移话题） 这是……？ （凑过来，有点不好意思地笑） 啊，这个！是我十三岁时的‘作品’，心情特别烦躁时画的。是不是以为是小孩子乱涂鸦？", },
	[182353] = {id=182353, zh_CN="其实……画的是我当时一直不能完美地记住所有公主礼仪，一气之下画的！", },
	[182354] = {id=182354, zh_CN="（她掠过旁边一个展示着各种华丽珠宝设计图的册子，其中一页描绘着象征王室联姻的传统冠冕） ……小时候觉得这些像童话，现在只觉得……脖子会断。", },
	[182355] = {id=182355, zh_CN="（走到一些泛黄的信件前，她停下，指尖隔着玻璃轻轻描摹信件的轮廓，声音低柔） 这些信……是母亲年轻时，也曾收到的让她轻松的信件。", },
	[182356] = {id=182356, zh_CN="父亲说，那些信是支撑母亲度过最初艰难时光的力量。因为这样的文字……我一直憧憬着父母那样……最终相守。", },
	[182357] = {id=182357, zh_CN="（她目光与你接触，带着一丝探寻） 抱歉，我聊的可能有点多了。", },
	[182358] = {id=182358, zh_CN="（她拿起一个修复过的、带有明显妖灵族风格的花瓶，上面裂纹清晰可见。）", },
	[182359] = {id=182359, zh_CN="（苦笑） 看，象征和平的礼物。多么脆弱。一次误解，一次冲突，就能轻易打碎，再高明的修复也掩盖不了裂痕。", },
	[182360] = {id=182360, zh_CN="气氛沉重，她强颜欢笑，", },
	[182361] = {id=182361, zh_CN="（指着自己那幅抽象涂鸦，笑容勉强）： 至少画画不需要考虑种族……虽然画得也够糟。", },
	[182362] = {id=182362, zh_CN="（郑重地看着你） 谢谢您愿意走进这里，解开谜题，也……走进这些碎片。", },
	[182363] = {id=182363, zh_CN="分享这些……对我而言，是前所未有的信任。", },
	[182364] = {id=182364, zh_CN="（她行了一个标准的、优雅的屈膝礼，这次更像是对这份信任的致意）", },
	[182365] = {id=182365, zh_CN="（笑容真诚温暖，伸出手）希望下次，“记忆方舟”还能有新的碎片与你分享。", },
	[182366] = {id=182366, zh_CN="再会了，我珍贵的朋友。", },
	[182367] = {id=182367, zh_CN="今天的谈话……请您务必保密。", },
	[182368] = {id=182368, zh_CN="（她优雅地行礼，抬眼看向你，眼神深邃，带着一丝请求和深意）", },
	[182369] = {id=182369, zh_CN="（语气轻柔却充满暗示）关于未来……或许下次，我们可以更深入地……聊聊您的见解？我很好奇。", },
	[182370] = {id=182370, zh_CN="（她微微侧身，避开你关切的目光，声音恢复了礼貌而疏离的距离感）", },
	[182371] = {id=182371, zh_CN="感谢您的到访。希望……希望您能理解方舟的立场和……历史的重量。再会。", },
	[182372] = {id=182372, zh_CN="（说完，她几乎是立刻转身，留给你一个决绝而落寞的背影。）", },
	[182373] = {id=182373, zh_CN="（走到阿加莎身边，递给她一份装订精美的文件，声音低沉而清晰）", },
	[182374] = {id=182374, zh_CN="阿加莎，我想和你谈一件……超越“互勉”和“秘密基地”的事。一件关于我们未来，以及方舟未来的事。", },
	[182375] = {id=182375, zh_CN="（转过身，接过文件，并未立刻翻开，雾紫色的眼眸直视你，带着属于公主的审慎。）", },
	[182376] = {id=182376, zh_CN="这么正式？看来不是邀请我去看新的街头艺人。说吧，我听着。", },
	[182377] = {id=182377, zh_CN="（她走回书桌旁，优雅地坐下，将文件放在桌上，手指无意识地摩挲着杯壁）", },
	[182378] = {id=182378, zh_CN="（坐在她对面，身体微微前倾，目光坦诚而锐利） 联姻。我向你，方舟的第一顺位继承人，提出联姻的请求。", },
	[182379] = {id=182379, zh_CN="（阿加莎的手指瞬间收紧，杯中的银杯微微晃动。她脸上完美的平静面具出现了一丝裂痕，眼神复杂地闪烁了一下，但没有打断。）", },
	[182380] = {id=182380, zh_CN="门当户对", },
	[182381] = {id=182381, zh_CN="（条理清晰地阐述）我们现在门当户对。", },
	[182382] = {id=182382, zh_CN="（手指抵住自己的心脏）我在米乐星球的影响力与声望已经不比你低了，况且我“天外来物”背景所吸引的独特资源网络，足以匹配整个方舟的需求。", },
	[182383] = {id=182383, zh_CN="我不是依附者，而是强力的盟友和支柱。", },
	[182384] = {id=182384, zh_CN="明星效应", },
	[182385] = {id=182385, zh_CN="（语气带着战略家的冷静）我们两位明星联姻所能制造的巨大流量效应是不可估计的。", },
	[182386] = {id=182386, zh_CN="我的“天外”身份自带话题性和神秘感，与方舟继承人联姻将是各大种族都瞩目的盛事，能极大提升方舟的软实力和形象，满足民众对王室新鲜活力的期待。", },
	[182387] = {id=182387, zh_CN="中立优势", },
	[182388] = {id=182388, zh_CN="（笑）同时，我的背景不隶属于任何传统势力或对立种族，是天然的有利于你巩固政权的优势，能有效化解内部因传统联姻对象选择可能引发的争议。", },
	[182389] = {id=182389, zh_CN="（靠近）你总不想内忧外患吧。", },
	[182390] = {id=182390, zh_CN="等待回应", },
	[182391] = {id=182391, zh_CN="（你没有要说的了，站在原地，等待着阿加莎的回应。）", },
	[182392] = {id=182392, zh_CN="阿加莎沉默了很久。她终于翻开那份文件，里面是详尽的分析报告、以及一份初步的、条件异常优渥且对自己约束相对宽松的协议草案。她看得非常仔细，手指划过那些条款，眼神深邃难辨。", },
	[182393] = {id=182393, zh_CN="（合上文件，抬起头，脸上已恢复平静，但眼底翻涌着激烈的思考）", },
	[182394] = {id=182394, zh_CN="你……准备得很充分。这份协议，几乎是在给我铺一条……相对自由的红毯。", },
	[182395] = {id=182395, zh_CN="但相比于上天的馈赠，它更像是一个卑鄙的陷阱。", },
	[182396] = {id=182396, zh_CN="我需要你足够打动我的理由，你的野心。", },
	[182397] = {id=182397, zh_CN="（语气忽然软化，眨巴着眼睛可怜巴巴地盯着阿加莎）", },
	[182398] = {id=182398, zh_CN="自由与合拍。这还不够吗？", },
	[182399] = {id=182399, zh_CN="阿加莎，我知道你渴望什么。", },
	[182400] = {id=182400, zh_CN="（身体前倾，声音压低，与面前人推心置腹。）比起其他候选人背后盘根错节的家族势力和对你一言一行的严苛审视……", },
	[182401] = {id=182401, zh_CN="……选择我，你受到的限制会少得多。我在米乐星球无亲无故，孑然一身。", },
	[182402] = {id=182402, zh_CN="某种意义上，你是‘捏着’我在这边的一切。", },
	[182403] = {id=182403, zh_CN="（你露出一个略带无奈又坦然的微笑） 而且，我们确实……合拍。", },
	[182404] = {id=182404, zh_CN="不是吗？", },
	[182405] = {id=182405, zh_CN="和你在一起，无论是讨论艺术还是参加宴会，我都觉得……很有意思。", },
	[182406] = {id=182406, zh_CN="这种基础，难道不比纯粹的政治筹码更可靠吗？", },
	[182407] = {id=182407, zh_CN="利益，你分析得很透彻。", },
	[182408] = {id=182408, zh_CN="“天外身份”的中立性和明星效应，确实无可替代。", },
	[182409] = {id=182409, zh_CN="自由……你给的承诺也很诱人。", },
	[182410] = {id=182410, zh_CN="（她转过身，目光如炬） 但是，婚姻不是商业并购。即使带着政治目的。", },
	[182411] = {id=182411, zh_CN="（也站起身，走到她面前，保持着一个尊重但亲近的距离）", },
	[182412] = {id=182412, zh_CN="阿加莎，我不是在向你推销一份冰冷的合同。", },
	[182413] = {id=182413, zh_CN="我是在向你，这个人，提出一个共同缔造未来的邀请。", },
	[182414] = {id=182414, zh_CN="这份邀请里，有责任，有利益，也有……我希望能继续发展下去的感情基础。", },
	[182415] = {id=182415, zh_CN="（看着你坦荡又带着一丝期待的眼神，她紧绷的肩膀微微放松，一丝极其浅淡、几乎不可见的红晕爬上耳尖。她低头，手指轻轻抚过杯壁。）", },
	[182416] = {id=182416, zh_CN="……和你在一起，或许不那么累。", },
	[182417] = {id=182417, zh_CN="（她抬起头，深吸一口气，做出了决定） 好。这份联姻提议，我……初步接受。", },
	[182418] = {id=182418, zh_CN="（你眼中瞬间亮起光芒）", },
	[182419] = {id=182419, zh_CN="（立刻抬手制止你的激动，语气恢复公主的冷静决断）", },
	[182420] = {id=182420, zh_CN="但是！有三个条件——", },
	[182421] = {id=182421, zh_CN="第一， 暂时绝对保密。 在时机成熟前，不能让外界知道一丝风声。", },
	[182422] = {id=182422, zh_CN="我需要时间……也需要你证明更多。", },
	[182423] = {id=182423, zh_CN="（郑重点头）当然，秘密守护是我们的专长。", },
	[182424] = {id=182424, zh_CN="第二， 继续“努力”。 在感情上，我需要看到你不仅仅是“合拍”，而是……更深的投入和诚意。在能力上，我需要你巩固并提升你承诺的影响力，确保联姻公布时，你的“砝码”足够重，重到能堵住所有质疑的嘴。", },
	[182425] = {id=182425, zh_CN="（微笑） 乐意之至。无论是感情还是事业，我的“努力”永不停止。", },
	[182426] = {id=182426, zh_CN="（眼神变得柔和而深邃） 第三， 我需要一个“观察期”。 观察我们是否真的能……在更大的压力和责任下，将这份‘合拍’转化为真正的……盟友，乃至……伴侣。", },
	[182427] = {id=182427, zh_CN="（她伸出手）%PlayerName，别让我失望。", },
	[182428] = {id=182428, zh_CN="（郑重地握住她的手，感受到她指尖微凉的坚定）绝不会让你失望，阿加莎。", },
	[182429] = {id=182429, zh_CN="猜猜我是谁？没错啦，就是ThaTha，我发现我们已经很久没有互通信件了。\n 我想你了。\n 前段时间需要处理的工作很多，冷落了你对不起。我会好好经营我们之间的感情的，我保证。\n 写信想邀请你来我的“秘密花房”，我们很久没度过独属于我们的二人世界了。\n 你不会拒绝我的吧，等你。\n 我和“惊喜”在这里等待你的到来。\n ——ThaTha", },
	[182430] = {id=182430, zh_CN="阿加莎的私人画室，与连接着的收藏馆不同。这里更显凌乱随性，巨大的画布靠在墙边，未完成的作品色彩大胆奔放；地上散落着颜料管、画笔和沾满颜料的抹布；书架塞满了艺术书籍、乐谱和写满批注的小说；空气中弥漫着松节油、颜料和旧纸张的混合气息。", },
	[182431] = {id=182431, zh_CN="阿加莎背对着门，雾紫色长发用一根炭笔随意挽起，穿着一件沾满各色颜料的旧帆布罩衫，正专注地在一幅中型画布上涂抹。", },
	[182432] = {id=182432, zh_CN="（忍不住笑了，轻声唤道） 嘿，Momo小姐，你的客人前来报到。", },
	[182433] = {id=182433, zh_CN="（闻声并未回头，只是画笔停顿了一下） 来得正好！快过来！", },
	[182434] = {id=182434, zh_CN="帮我看看这幅画……（她离远了些）我快要在色彩里失去平衡了！", },
	[182435] = {id=182435, zh_CN="（她快速在画布右下角抹上一笔浓烈的钴蓝。）", },
	[182436] = {id=182436, zh_CN="玩家： （走近，站在她侧后方，避免打扰她作画，目光被画布吸引。）", },
	[182437] = {id=182437, zh_CN="【插画】", },
	[182438] = {id=182438, zh_CN="画面主体是混乱奔放的彩色斑点和线条，但在中心区域，却有一种奇异的、螺旋上升的秩序感，仿佛混沌中诞生的星系，又像是解构的城市脉络。", },
	[182439] = {id=182439, zh_CN="你在……画星空吗？", },
	[182440] = {id=182440, zh_CN="你在……画星空吗？", },
	[182441] = {id=182441, zh_CN="哇哦……星际的能量感……扑面而来！", },
	[182442] = {id=182442, zh_CN="（应和）看来我画的还不错。", },
	[182443] = {id=182443, zh_CN="塔希主义抽象表达？", },
	[182444] = {id=182444, zh_CN="塔希主义抽象表达艺术？", },
	[182445] = {id=182445, zh_CN="（画笔猛地停在半空）你居然知道塔希主义！！", },
	[182446] = {id=182446, zh_CN="（兴奋）你知道吗，抽象艺术表达里，我最喜欢的就是塔希主义模糊的表现，我认为是最能隐藏和流露画家感情和心灵的画风。", },
	[182447] = {id=182447, zh_CN="你在解构秩序？", },
	[182448] = {id=182448, zh_CN="（沉思感受）你在尝试……解构秩序与混沌的边界？或者说……在无序中寻找内在的韵律？", },
	[182449] = {id=182449, zh_CN="（倏然转身，脸蛋沾上几点柠檬黄的颜料，眼底满是不可置信。）", },
	[182450] = {id=182450, zh_CN="（恍然大悟）对啊，结构秩序后对混乱的重新定义。", },
	[182451] = {id=182451, zh_CN="（她激动地一把抓住你的手臂）我一直都抓不住自己想要表达的东西，你居然一眼击中了这层薄纱！", },
	[182452] = {id=182452, zh_CN="是否读心", },
	[182453] = {id=182453, zh_CN="不读心", },
	[182454] = {id=182454, zh_CN="魅力检定", },
	[182455] = {id=182455, zh_CN="理智检定", },
	[182456] = {id=182456, zh_CN="你好像错过了阿加莎的心声。", },
	[182457] = {id=182457, zh_CN="【他真的懂！那些我表达不出的东西……】", },
	[182458] = {id=182458, zh_CN="【这就是灵魂伴侣间的……悸荡吗？】", },
	[182459] = {id=182459, zh_CN="静静欣赏", },
	[182460] = {id=182460, zh_CN="你沉浸在阿加莎幽蓝色的艺术色彩中，似乎探寻到她隐藏在内心深处的最真实的情绪。", },
	[182461] = {id=182461, zh_CN="（听着你的解读，眼神越来越亮，像是找到了失散已久的知己。她放下画笔，拉着你走到旁边堆满草稿的小桌旁，随手翻开一本速写本，里面是无数关于“混沌与秩序”的草图）", },
	[182462] = {id=182462, zh_CN="你知道吗？以前和别人聊我的画，聊我的这些……“胡思乱想”，我需要解释很多很多……", },
	[182463] = {id=182463, zh_CN="从构图意图到色彩理论，最后往往只能得到一个礼貌的微笑或者一句‘很有想法’。", },
	[182464] = {id=182464, zh_CN="那种感觉就像……就像隔着一层厚厚的毛玻璃说话。", },
	[182465] = {id=182465, zh_CN="只有自己回声的感觉，很不好。", },
	[182466] = {id=182466, zh_CN="所以……你才把想法藏在谜题和物件里珍藏起来？", },
	[182467] = {id=182467, zh_CN="（点点头，眼神温柔地落在你身上） 嗯。直到遇见你。", },
	[182468] = {id=182468, zh_CN="我对乐符，对涂鸦的渴望，在和你的交流中，找到了出口。", },
	[182469] = {id=182469, zh_CN="我想要的那种……流动的，瞬间的，难以言喻的共鸣……", },
	[182470] = {id=182470, zh_CN="（泛红的脸颊和亮晶晶的眼睛）就这样来到我的身边。", },
	[182471] = {id=182471, zh_CN="阿加莎……不是因为我启发了你，而是因为你本身就是一个如此敏锐的观察者和表达者。", },
	[182472] = {id=182472, zh_CN="我的某句话，只是一颗小石子，恰好投入了你本就波澜壮阔的思想湖泊里，激起了一点涟漪而已。", },
	[182473] = {id=182473, zh_CN="真正的力量，来自你自己。", },
	[182474] = {id=182474, zh_CN="阿加莎被你真挚的话语触动，眼眶微微发热。她走到画室最里面一个蒙着布的架子前，深吸一口气，像是下定了某种决心。她掀开蒙布，露出里面一幅尺幅很小的画。", },
	[182475] = {id=182475, zh_CN="画风极其稚嫩抽象，色彩混沌，笔触笨拙，像幼儿的涂鸦，但能隐约看出一个模糊的女性轮廓和一颗歪歪扭扭的星星）", },
	[182476] = {id=182476, zh_CN="……这是我……大概七岁时的作品。", },
	[182477] = {id=182477, zh_CN="自画像？", },
	[182478] = {id=182478, zh_CN="（看着这幅“糟糕”的画，没有笑，而是认真观察）", },
	[182479] = {id=182479, zh_CN="这是……你在画自己？", },
	[182480] = {id=182480, zh_CN="守护星？", },
	[182481] = {id=182481, zh_CN="（看着这幅“糟糕”的画，没有笑，而是认真观察）", },
	[182482] = {id=182482, zh_CN="这是……你在画自己？还有……你的守护星？", },
	[182483] = {id=182483, zh_CN="（露出一个无比释然和温暖的笑容） 对！连这个你都看出来了！", },
	[182484] = {id=182484, zh_CN="小时候我总是羡慕星星，觉得他们就是自由的象征，是我当时所向往的。", },
	[182485] = {id=182485, zh_CN="它很丑，技法一塌糊涂。", },
	[182486] = {id=182486, zh_CN="但它代表了我艺术探索的起点……", },
	[182487] = {id=182487, zh_CN="代表了我内心最原始、最笨拙也最真实的“呓语”。", },
	[182488] = {id=182488, zh_CN="（她小心翼翼地从架子上取下这幅画，像捧着最珍贵的易碎品，转身郑重地递到你面前）", },
	[182489] = {id=182489, zh_CN="现在，我把它送给你。%PlayerName，谢谢你。", },
	[182490] = {id=182490, zh_CN="（双眼盛满信任和期待）你愿意，成为我的锚点之一吗？", },
	[182491] = {id=182491, zh_CN="（伸出双手，极其郑重地接过那幅画，仿佛接过一颗跳动的心）", },
	[182492] = {id=182492, zh_CN="我的荣幸", },
	[182493] = {id=182493, zh_CN="这是我的荣幸，阿加莎。", },
	[182494] = {id=182494, zh_CN="像星星一样守护你", },
	[182495] = {id=182495, zh_CN="我会像守护最珍贵的星辰一样，守护这份友情。", },
	[182496] = {id=182496, zh_CN="心口灵魂常在", },
	[182497] = {id=182497, zh_CN="（你指了指自己的心口）你的灵魂激荡，随时都在这里。", },
	[182498] = {id=182498, zh_CN="（眼中闪烁着感动的泪光。她伸出手） 一言为定！", },
	[182499] = {id=182499, zh_CN="你和阿加莎两只手紧紧握在一起，手上还沾着未干的颜料，两个人笑着瘫倒在地。", },
	[182500] = {id=182500, zh_CN="又是一天，阿加莎与你独自约会的私人茶会……", },
	[182501] = {id=182501, zh_CN="（靠在舒适的沙发里，看着阿加莎娴熟地泡着花果茶。）", },
	[182502] = {id=182502, zh_CN="时间过得真快。还记得我们第一次正式见面吗？", },
	[182503] = {id=182503, zh_CN="在那个晚宴上，我紧张得差点把茶水洒在你裙子上。", },
	[182504] = {id=182504, zh_CN="（将一杯香气四溢的花果茶递给你，优雅地坐下，眼中带着笑意）", },
	[182505] = {id=182505, zh_CN="（比了比文件的大小）怎么会忘？没过多久，你便带着那么厚的举证来“威胁”我联姻。", },
	[182506] = {id=182506, zh_CN="（摇头笑着）没想到竟然变成我们交往密切的开端。", },
	[182507] = {id=182507, zh_CN="（感受到她的目光，心中暖流涌动）没想到我们竟成了最合拍的搭档，最信任的朋友……", },
	[182508] = {id=182508, zh_CN="（放下茶杯，指尖无意识地在杯沿轻轻划过，气氛忽然变得有些微妙）", },
	[182509] = {id=182509, zh_CN="最合拍的搭档，最信任的朋友……吗？", },
	[182510] = {id=182510, zh_CN="怎么会忘？那天之后，我怀着试探的心理约见你，也是在这里。", },
	[182511] = {id=182511, zh_CN="（摇头笑着）没想到竟然变成我们交往密切的开端。", },
	[182512] = {id=182512, zh_CN="（感受到她的目光，心中暖流涌动）没想到我们竟成了最信任的伙伴，最好的朋友……", },
	[182513] = {id=182513, zh_CN="（放下茶杯，指尖无意识地在杯沿轻轻划过，气氛忽然变得有些微妙）", },
	[182514] = {id=182514, zh_CN="最信任的伙伴，最好的朋友……吗？", },
	[182515] = {id=182515, zh_CN="（她抬起头，直视你的眼睛，那里面不再是单纯的友谊，而是涌动着一股更深沉的情愫）", },
	[182516] = {id=182516, zh_CN="那……有没有可能，再进一步呢？", },
	[182517] = {id=182517, zh_CN="（心跳漏了一拍，有些不确定地问） 进一步？你的意思是……", },
	[182518] = {id=182518, zh_CN="（深吸一口气，脸上泛起淡淡的红晕，但眼神坚定而坦率，带着公主特有的优雅和一丝难得的紧张）", },
	[182519] = {id=182519, zh_CN="我的意思是……我们之间，早就超越了普通的友谊，不是吗？", },
	[182520] = {id=182520, zh_CN="（她站起身，走到栏杆边，阳光勾勒出她美好的侧影） 过去我们相知相识的日子里，我看着你一步步成长，变得如此耀眼。", },
	[182521] = {id=182521, zh_CN="我们分享喜悦，分担忧愁，彼此理解，互相支持……", },
	[182522] = {id=182522, zh_CN="（她转过身，面对你，露出一个既温柔又带着点羞涩的微笑）", },
	[182523] = {id=182523, zh_CN="而且，我觉得你应该可以通过我的试用期了。", },
	[182524] = {id=182524, zh_CN="考察期总要有个尽头吧。", },
	[182525] = {id=182525, zh_CN="虽然你还算不上最佳的人选……", },
	[182526] = {id=182526, zh_CN="但连那些挑剔的王室顾问们，也开始觉得你这位‘青年才俊’是个‘不错的人选’了", },
	[182527] = {id=182527, zh_CN="（心中巨大的喜悦涌上来，你立刻起身走到她面前）", },
	[182528] = {id=182528, zh_CN="阿加莎……你是说……", },
	[182529] = {id=182529, zh_CN="（勇敢地迎上你的目光，声音清晰而温柔） 我是说，既然我们感情这么好，你的事业也蒸蒸日上，公众形象无可挑剔……", },
	[182530] = {id=182530, zh_CN="（她伸出手，轻轻抚平你衣服上并不存在的褶皱，动作带着亲昵）", },
	[182531] = {id=182531, zh_CN="是不是……可以考虑坐实身份了？", },
	[182532] = {id=182532, zh_CN="或许我们可以考虑一下升级成“有名有实”的身份呢？", },
	[182533] = {id=182533, zh_CN="（她微微歪头，眼中闪烁着期待的光） 正式的发展关系，你觉得怎么样？", },
	[182534] = {id=182534, zh_CN="不是为了任何人，只为了我们自己，为了这份……水到渠成的感情。", },
	[182535] = {id=182535, zh_CN="（再也抑制不住内心的激动，一把将她拥入怀中，声音带着难以置信的喜悦）", },
	[182536] = {id=182536, zh_CN="真的吗！！这是我梦寐以求的事情！", },
	[182537] = {id=182537, zh_CN="什么“觉得怎么样”？这简直是世界上最好的提议！", },
	[182538] = {id=182538, zh_CN="（你松开她一点，看着她的眼睛） 你知道吗？我一直想着在努力一点，等我足够强大，能堂堂正正站在你身边，让所有人都无话可说！", },
	[182539] = {id=182539, zh_CN="（在你怀里笑得明媚动人，之前的紧张一扫而空）", },
	[182540] = {id=182540, zh_CN="傻瓜，你早就可以堂堂正正站在我身边了。不过现在嘛……", },
	[182541] = {id=182541, zh_CN="（她调皮地眨眨眼） 我们可以更理直气壮一点。", },
	[182542] = {id=182542, zh_CN="那么，准备好迎接全新的身份和责任了吗？", },
	[182543] = {id=182543, zh_CN="（笑着吻了吻她的发顶）", },
	[182544] = {id=182544, zh_CN="只要女主角是你，我都奉陪到底。", },
	[182545] = {id=182545, zh_CN="城堡下的喷泉广场上， 晴朗的白天，彩旗飘扬。巨大的方舟王室旗帜在风中猎猎作响。", },
	[182546] = {id=182546, zh_CN="阿加莎身着剪裁完美的宫廷长裙，雾紫色长发盘成优雅精致的发髻，戴着象征王储的小巧钻石冠冕。", },
	[182547] = {id=182547, zh_CN="（她站在临时搭建的礼台上，仪态万方，脸上是温暖、自信、极具感染力的笑容，向热情的民众挥手致意。）", },
	[182548] = {id=182548, zh_CN="你期待阿加莎接下来的讲话吗？", },
	[182549] = {id=182549, zh_CN="期待——公开恋情", },
	[182550] = {id=182550, zh_CN="紧张——不公开恋情", },
	[182551] = {id=182551, zh_CN="（面对麦克风，声音清晰、温和而有力，传遍整个广场） 亲爱的诺亚方舟的子民们！看到你们充满希望和活力的脸庞，是我作为王储最大的动力和幸福源泉！", },
	[182552] = {id=182552, zh_CN="今天，除了例行和大家见面，分享方舟在种族社区融合项目上取得的喜人进展外……", },
	[182553] = {id=182553, zh_CN="（她顿了顿，目光温柔而坚定地看向台侧的你，这个动作吸引了所有人的注意）", },
	[182554] = {id=182554, zh_CN="我还有一个关于我个人的重要消息，希望能与你们，我视作家人的国民们分享。", },
	[182555] = {id=182555, zh_CN="广场瞬间安静下来，无数目光聚焦在阿加莎和你身上。", },
	[182556] = {id=182556, zh_CN="（自然地伸出手，轻轻握住你的手，两人十指相扣，动作优雅而充满宣告意味。她的笑容更加明媚，带着真挚的幸福，但姿态依旧保持着王储的庄重）", },
	[182557] = {id=182557, zh_CN="站在我身边的这位，%PlayerName，相信许多人已经熟悉他。他不仅是方舟忠诚的伙伴和盟友，他更用他的智慧、勇气和对这片土地深沉的爱，赢得了我的尊重、信赖和……倾心。", },
	[182558] = {id=182558, zh_CN="（她声音带着一丝恰到好处的羞涩，但立刻被更强大的自信取代）", },
	[182559] = {id=182559, zh_CN="经过慎重的考虑和彼此真诚的交往，我很荣幸也很幸福地告诉大家，%PlayerName，不仅是诺亚方舟值得信赖的朋友，更是我生命中认定的伴侣！我们正在以结婚为前提交往！", },
	[182560] = {id=182560, zh_CN="广场在短暂的寂静后，爆发出震耳欲聋的欢呼、掌声和祝福声！民众对阿加莎的爱戴延伸到了她选择的伴侣身上。", },
	[182561] = {id=182561, zh_CN="（抬手示意大家安静，脸上是幸福而郑重的表情）", },
	[182562] = {id=182562, zh_CN="我知道，作为王储，我的个人生活也承载着大家的关注。", },
	[182563] = {id=182563, zh_CN="我选择公开，是因为我深信，一份建立在真诚、责任和共同理想基础上的感情，只会让我更有力量去履行我的职责！", },
	[182564] = {id=182564, zh_CN="（她的声音充满力量） 我向你们保证，这份感情不会影响我对国家和人民的承诺！相反，它会激励我，和%PlayerName一起，在未来以更加坚定的步伐，带领诺亚方舟，走向更繁荣、更包容、更充满希望的明天！", },
	[182565] = {id=182565, zh_CN="请你们继续监督我，支持我！谢谢大家！", },
	[182566] = {id=182566, zh_CN="阿加莎优雅鞠躬，你也一同鞠躬致意。（阳光下的宣言，坦荡而充满力量。阿加莎成功地将私人情感升华为了对国家的承诺，赢得了民众更深的信任与祝福。", },
	[182567] = {id=182567, zh_CN="你混在广场最前排的民众之中。穿着低调但整洁，在人群中并不显眼。", },
	[182568] = {id=182568, zh_CN="（面对麦克风，声音清晰、温和而有力，传遍整个广场） 亲爱的诺亚方舟的子民们！看到你们充满希望和活力的脸庞，是我作为王储最大的动力和幸福源泉！", },
	[182569] = {id=182569, zh_CN="目光扫过前排人群的瞬间，精准地捕捉到了那个熟悉的身影。尽管你低着头，帽檐遮住了部分面容，但她就是知道，是你。阿加莎的心跳漏了一拍，但完美的表情管理让她嘴角的弧度没有丝毫变化。", },
	[182570] = {id=182570, zh_CN="（在人群中，微微抬起头。当阿加莎的目光看似无意地掠过你时，你极其迅速地、用只有她能看清的角度，轻轻眨了一下右眼，嘴角勾起一个微小而温暖的弧度。那眼神里，充满了无声的鼓励和浓浓的爱意。）", },
	[182571] = {id=182571, zh_CN="（正接过一位老者献上的花束。感受到那熟悉的注视和小动作，她递花束给侍从的动作极其轻微地顿了一下。）", },
	[182572] = {id=182572, zh_CN="（她脸上绽放出比刚才更加璀璨、更加真实的笑容，那笑容仿佛瞬间点亮了整个广场。）", },
	[182573] = {id=182573, zh_CN="谢谢您！这花真美，就像我们诺亚方舟人民的心灵一样纯洁美好！", },
	[182574] = {id=182574, zh_CN="（看着阿加莎在台上因自己的小动作而焕发的光彩，心中满是柔情。你悄悄将手放在心口位置，停留了一秒。）", },
	[182575] = {id=182575, zh_CN="（你指向阿加莎。无声地诉说。）为，你，骄，傲。", },
	[182576] = {id=182576, zh_CN="（眼角的余光捕捉到你那个心口指向的动作。一股暖流瞬间涌遍全身。她感觉脸颊有些微热，但巧妙地借着低头整理面前麦克风线的动作掩饰了过去。", },
	[182577] = {id=182577, zh_CN="（再抬头时，仿佛被注入了额外的能量。在发言结束的间隙，她拿起水杯喝水，借着杯身的掩护，她的嘴唇极其轻微地、快速地动了一下。）", },
	[182578] = {id=182578, zh_CN="（无声）谢谢。", },
	[182579] = {id=182579, zh_CN="当阿加莎的目光再次与你交汇时，那眼神深处除了爱意和依赖，还多了一层化不开的沉重悲伤和无奈。", },
	[182580] = {id=182580, zh_CN="阿加莎迅速移开目光，但眼眶却不受控制地微微湿润了。她强忍着，将那份心酸转化为更用力、更灿烂的笑容。", },
	[182581] = {id=182581, zh_CN="只是那笑容背后，藏着只有台下那个人才懂的苦涩。", },
	[182582] = {id=182582, zh_CN="深夜，鸭湖城堡一处僻静的小露台。阿加莎望着远处，雾紫色的长发在微凉的夜风中轻轻飘动。", },
	[182583] = {id=182583, zh_CN="阿加莎穿着简单的丝质睡袍，肩头披着一件薄毯，微微颤抖的背影单薄而孤寂。压抑的、几乎听不见的啜泣声在你的耳边萦绕。", },
	[182584] = {id=182584, zh_CN="（心被揪紧，声音放得极轻，怕惊扰她） 阿加莎？", },
	[182585] = {id=182585, zh_CN="（慢慢走到她身边，保持一点距离，想要搂住她的手凝滞在半空，望着她拒绝的背影，无法前进。）", },
	[182586] = {id=182586, zh_CN="（身体猛地一僵，迅速抬手抹去脸上的泪痕，没有回头，声音带着浓重的鼻音和极力维持的平静）", },
	[182587] = {id=182587, zh_CN="我没事。只是……看夜景。", },
	[182588] = {id=182588, zh_CN="你……怎么还没休息？", },
	[182589] = {id=182589, zh_CN="（看着她强撑的背影，心疼更甚）", },
	[182590] = {id=182590, zh_CN="城堡的夜景很美，但看夜景的人……似乎并不开心。", },
	[182591] = {id=182591, zh_CN="（你靠近一步，试探性地） 告诉我，发生了什么？", },
	[182592] = {id=182592, zh_CN="最近的压力很大吗？我们可以再偷偷出去……", },
	[182593] = {id=182593, zh_CN="（沉默了很久，久到你以为她不会再开口。夜风吹过，带来她压抑到极致、终于破碎的声音）", },
	[182594] = {id=182594, zh_CN="……他们说得对。", },
	[182595] = {id=182595, zh_CN="（一愣） 谁说得对？说什么？", },
	[182596] = {id=182596, zh_CN="（猛地转过身！月光下，她脸上泪痕未干，眼眶通红，平日里优雅从容的公主面具彻底碎裂，只剩下深不见底的痛苦和疲惫）", },
	[182597] = {id=182597, zh_CN="我不该对你的身份保留期待的，就算你的灵魂不属于这里，可是！你的样貌，你的尾巴，耳朵……", },
	[182598] = {id=182598, zh_CN="民众，媒体，对方舟虎视眈眈的势力，他们是不会听你解释，听我解释的。", },
	[182599] = {id=182599, zh_CN="他们只会认为：我！方舟继承人与宿敌之后交往过深，有通敌之嫌。", },
	[182600] = {id=182600, zh_CN="（她的声音陡然拔高，捂着脸带着崩溃的哭腔）我不该抱有侥幸心理地把你当作回避的港湾的 ……", },
	[182601] = {id=182601, zh_CN="我不该任由我的心……（话音未落，她的泪水已经喷涌而出。）", },
	[182602] = {id=182602, zh_CN="（被她的激烈反应和话语刺痛，脸色发白，你忽然想起过去几周阿加莎与你交往时紧张的状态。）", },
	[182603] = {id=182603, zh_CN="所以，你一直都处在紧张不安的情绪里吗？", },
	[182604] = {id=182604, zh_CN="阿加莎，你知道我不是！我们……", },
	[182605] = {id=182605, zh_CN="（激动地打断你，泪水决堤） 我知道！我当然知道！", },
	[182606] = {id=182606, zh_CN="我知道你有多好！知道你的幽默、你的智慧、你的体贴！", },
	[182607] = {id=182607, zh_CN="我知道你会带我去逛节日集会，会陪我解那些幼稚的谜题，会带我体验别人的平凡但对我却不普通的事物，！", },
	[182608] = {id=182608, zh_CN="（她用力捶着自己的胸口，泣不成声） 可是……可是我是方舟公主，我不只是你的Momo。", },
	[182609] = {id=182609, zh_CN="我知道把与你无关的仇恨强加在你身上很自私。", },
	[182610] = {id=182610, zh_CN="可是你外表所属于的种族在几百年前侵略，屠戮着我的先祖，我的身上流着“战士先辈”的血液……", },
	[182611] = {id=182611, zh_CN="我的子民看着我！他们的恨意、他们的恐惧……像冰冷的锁链，每时每刻都勒着我的脖子！", },
	[182612] = {id=182612, zh_CN="每一次和你见面，每一次对你微笑……我都要面对内心的叩问和周围无声的谴责！", },
	[182613] = {id=182613, zh_CN="你知道那种感觉吗？你知道吗？", },
	[182614] = {id=182614, zh_CN="你震惊地看着阿加莎崩溃的模样，听着她剖心泣血的哭诉，一股巨大的酸楚和无力感淹没了你。", },
	[182615] = {id=182615, zh_CN="（你终于明白，她独自承担了多少！你上前一步，想抓住她的肩膀） 阿加莎……我……", },
	[182616] = {id=182616, zh_CN="（却像受惊的兔子般猛地后退一步，眼神充满绝望）", },
	[182617] = {id=182617, zh_CN="不！你不知道！你怎么会知道？！", },
	[182618] = {id=182618, zh_CN="你是一阵自由的风，吹过我们的历史，却感受不到那沉积了百年的血腥和沉重！", },
	[182619] = {id=182619, zh_CN="你不知道每次接触你，我内心要经历怎样的撕裂！", },
	[182620] = {id=182620, zh_CN="一边是越来越清晰、越来越真实的你！一边是刻在骨血里的仇恨和责任！", },
	[182621] = {id=182621, zh_CN="（她靠着冰冷的栏杆滑坐在地上，将脸深深埋进膝盖，瘦弱的肩膀剧烈地颤抖着，发出压抑到极致的呜咽）", },
	[182622] = {id=182622, zh_CN="它们在我脑子里打架！快把我逼疯了！", },
	[182623] = {id=182623, zh_CN="我好累……我真的好累……", },
	[182624] = {id=182624, zh_CN="我只是想小小的逃避一下……", },
	[182625] = {id=182625, zh_CN="我只是……只是不小心喜欢了一个人……", },
	[182626] = {id=182626, zh_CN="为什么这么难……", },
	[182627] = {id=182627, zh_CN="你看着蜷缩在地上、哭得像个迷路孩子的阿加莎，心脏疼得像被狠狠攥住。所有想辩解的话，所有想质问“为什么不告诉我”的冲动，都堵在喉咙里，化为一片苦涩的沉默。", },
	[182628] = {id=182628, zh_CN="理解她", },
	[182629] = {id=182629, zh_CN="你忽然理解了她背负的枷锁有多沉重，理解了她笑容背后的如履薄冰。", },
	[182630] = {id=182630, zh_CN="怨恨她的隐瞒", },
	[182631] = {id=182631, zh_CN="怨恨她的隐瞒？不，你此刻只有无尽的心疼和自责——为她承受的痛苦，为自己无知带来的伤害。", },
	[182632] = {id=182632, zh_CN="心痛，努力安抚", },
	[182633] = {id=182633, zh_CN="你缓缓蹲下身，不再试图触碰她，只是用最温柔、最坚定的声音说） 阿加莎……看着我。", },
	[182634] = {id=182634, zh_CN="（她低着头，哭声渐弱，只剩下压抑的抽泣。）", },
	[182635] = {id=182635, zh_CN="道歉", },
	[182636] = {id=182636, zh_CN="（声音低沉而饱含力量） 对不起……为我让你独自承受这一切而道歉。为我无法感同身受那份历史的沉重而道歉。", },
	[182637] = {id=182637, zh_CN="认同阿加莎的观点", },
	[182638] = {id=182638, zh_CN="（你停顿了一下，深吸一口气） 你说得对，我是“天外”之风。我不懂你们的仇，但我懂你现在的痛。恨我？怨我？或者恨这命运？都可以。", },
	[182639] = {id=182639, zh_CN="承受你现在的情绪，是我应该，也必须该做的。", },
	[182640] = {id=182640, zh_CN="求她不要推开自己", },
	[182641] = {id=182641, zh_CN="（叹气）无论如何，请别推开我。让我陪你一起站在悬崖边，好吗？", },
	[182642] = {id=182642, zh_CN="等待阿加莎的反应", },
	[182643] = {id=182643, zh_CN="（你安静地盯着阿加莎，等她主动抬头面对你。）", },
	[182644] = {id=182644, zh_CN="（她缓缓抬起头，泪眼婆娑地看着你，眼神脆弱得像易碎的琉璃。）", },
	[182645] = {id=182645, zh_CN="（张开双臂，眼神是前所未有的坦诚和包容）", },
	[182646] = {id=182646, zh_CN="如果相爱无能，如果怨恨无力……那就拥抱吧。", },
	[182647] = {id=182647, zh_CN="（你保持着张开怀抱的姿势，等待她的选择）", },
	[182648] = {id=182648, zh_CN="请拥抱我吧。", },
	[182649] = {id=182649, zh_CN="我在这里。阿加莎，我在这里。", },
	[182650] = {id=182650, zh_CN="漫长的几秒钟。夜风似乎都静止了。", },
	[182651] = {id=182651, zh_CN="（她看着你敞开的怀抱，那里没有指责，没有索求，只有无声的接纳和支撑。）", },
	[182652] = {id=182652, zh_CN="（她眼中翻涌着激烈的挣扎、恐惧，最终，那累积到无法承受的疲惫和渴望压倒了冰冷的枷锁。）", },
	[182653] = {id=182653, zh_CN="：（她发出一声近乎崩溃的呜咽，像离弦的箭般扑进了你的怀里！）", },
	[182654] = {id=182654, zh_CN="（紧紧抱住你，仿佛抓住唯一的浮木，脸埋在你胸前，放声大哭，所有的委屈、恐惧、痛苦和挣扎都随着泪水汹涌而出）", },
	[182655] = {id=182655, zh_CN="……呜……为什么……为什么要是你……为什么偏偏是你……", },
	[182656] = {id=182656, zh_CN="我好讨厌你……可是……可是我更怕失去你……", },
	[182657] = {id=182657, zh_CN="（用力回抱住她颤抖的身体，下巴轻轻抵着她的头顶，感受着她滚烫的泪水浸湿衣襟。你的手臂收得很紧，仿佛要将自己的力量和决心传递给她）", },
	[182658] = {id=182658, zh_CN="哭吧，哭出来就好。我在这里。“宿敌”也好，“祸端”也罢。", },
	[182659] = {id=182659, zh_CN="我就在这里，抱着你，任你处置。", },
	[182660] = {id=182660, zh_CN="谁也不能再让你独自承担这份重量。我保证。", },
	[182661] = {id=182661, zh_CN="你与阿加莎紧紧相拥在冰冷的露台上，月光将你们的影子拉得很长。", },
	[182662] = {id=182662, zh_CN="仇恨的阴影仍在，但此刻，唯有这个拥抱是真实的温度。", },
	[182663] = {id=182663, zh_CN="（屈膝礼）亲爱的%PlayerName阁下，祝你午安。", },
	[182664] = {id=182664, zh_CN="离开", },
	[182665] = {id=182665, zh_CN="再会了，我的朋友。", },
	[182666] = {id=182666, zh_CN="秘密出游", },
	[182667] = {id=182667, zh_CN="造访“记忆方舟”", },
	[182668] = {id=182668, zh_CN="联姻", },
	[182669] = {id=182669, zh_CN="灵魂锚点", },
	[182670] = {id=182670, zh_CN="“政治”真婚", },
	[182671] = {id=182671, zh_CN="庭台露面", },
	[182672] = {id=182672, zh_CN="一千夜最后一夜", },
	[182690] = {id=182690, zh_CN="好感度任务测试", },
	[182691] = {id=182691, zh_CN="好感度", },
	[182692] = {id=182692, zh_CN="亲密度", },
	[182693] = {id=182693, zh_CN="信任度", },
	[182694] = {id=182694, zh_CN="阿加莎好感度表测试", },
	[182695] = {id=182695, zh_CN="%PlayerName主人怎么这么爱我，恨不得一口气把全天下的好吃好玩的都喂给我的哇！", },
	[182696] = {id=182696, zh_CN="哇哦， %PlayerName主人送得太快啦！我都没来得及好好欣赏呢！让我一个一个，好好感受你的心意。", },
	[182697] = {id=182697, zh_CN="%PlayerName你要把我的小肚子都变成蜜糖罐啦！甜蜜要溢出来啦~", },
	[182698] = {id=182698, zh_CN="哇！！礼物变成雨，我真的好幸福！%PlayerName我要给你的每份爱都写上名字！", },
	[182699] = {id=182699, zh_CN="%PlayerName的心意比月光更醉人……可愿明日携第一缕风与我共赏晨曦？", },
	[182700] = {id=182700, zh_CN="%PlayerName！你的礼物如月光银河泻落在我面前，让我为每颗星星礼物都谱写赞歌。", },
	[182701] = {id=182701, zh_CN="%PlayerName！小金毛只是一只小狗，礼物要拿不过来啦，汪汪！", },
	[182702] = {id=182702, zh_CN="汪汪！%PlayerName你真的好热情，还没有人对小金毛这般好，我们要做一辈子好朋狗。", },
	[182703] = {id=182703, zh_CN="%PlayerName小崽子，这么喜欢叔啊，心意叔领了哦~", },
	[182704] = {id=182704, zh_CN="年纪大了还能被%PlayerName崽子这么喜欢，叔甘拜下风，你先帮叔捏捏老腰。", },
	[182705] = {id=182705, zh_CN="喵~，我可不会被%PlayerName的小鱼干溺爱给打倒~呼噜噜~", },
	[182706] = {id=182706, zh_CN="喵~哪儿来的礼物炸弹，看在礼物多多的份上，主动给你摸摸吧，想摸多久摸多久哦~", },
	[182707] = {id=182707, zh_CN="喵~~~你的礼物不错，呼噜噜~明日一定要来，喵喵大仙会蹲在这里盼望着你和你的贡品。", },
	[182708] = {id=182708, zh_CN="%PlayerName！喵——诱惑喵喵大仙陷入你的美鱼心计？呼噜噜~", },
	[182709] = {id=182709, zh_CN="什么！这是你送给喵喵我的友情信物！！喵喵我要好好选回礼，喵~不能输给你的爱！", },
	[182710] = {id=182710, zh_CN="哦我的上帝喵！%PlayerName的友情信物如瀑布，待喵喵我用最得体的礼数接受！", },
	[182711] = {id=182711, zh_CN="正在努力感受%PlayerName的爱意，我愿意为你的爱，过载运行我的情感模块……", },
	[182712] = {id=182712, zh_CN="对不起，请稍后，正在备份%PlayerName的每一份礼物和我的心动数据……", },
	[182713] = {id=182713, zh_CN="啵啵啵！%PlayerName的爱意泡泡都挡住你啦，小鱼也要送你爱意泡泡~", },
	[182714] = {id=182714, zh_CN="%PlayerName的爱意浪花扑来啦！我要被拍到岸边啦~", },
	[182715] = {id=182715, zh_CN="嗷呜，这是无法拒绝的甜蜜陷阱，%PlayerName~，你降服我了。", },
	[182716] = {id=182716, zh_CN="哇哦！%PlayerName的礼物连击！我的毛毛都要兴奋得炸开了！慢点投喂嘛~", },
	[182717] = {id=182717, zh_CN="血量见底，求饶求饶，我承受不住%PlayerName的甜蜜攻势了，明日我们再战！", },
	[182718] = {id=182718, zh_CN="%PlayerName~这份宠爱够我炫耀三辈子啦！你是圣诞老人转世吗？", },
	[182719] = {id=182719, zh_CN="%PlayerName你再这样……我就要忍不住摇尾巴了！唔……我明天找你好不好？", },
	[182720] = {id=182720, zh_CN="%PlayerName，你送我这么多礼物，我要还不清了。请允许我向你用妖灵族的方式表达谢意。", },
	[182721] = {id=182721, zh_CN="这是你表达爱意的方式吗？那你喜欢什么呢？我想要为你付出，表达我的爱。", },
	[182722] = {id=182722, zh_CN="送礼物越多，彼此的感情越紧密吗？我的情感模块触发分享指令，我能与%PlayerName共享这些礼物吗？", },
	[182723] = {id=182723, zh_CN="%PlayerName……您让我心跳超王室礼仪标准了！请不要继续犯规。", },
	[182724] = {id=182724, zh_CN="%PlayerName！请、请稍微慢……在这样下去，我的记忆方舟要申请扩建了。", },
	[182725] = {id=182725, zh_CN="%PlayerName这份心意估值过高……我想我们的利益捆绑更紧密才能配上你的心意", },
	[182726] = {id=182726, zh_CN="你的爱改变了我的取向，执着于送礼物表达爱意好像也很不错，尤其是你，%PlayerName", },
	[182727] = {id=182727, zh_CN="%PlayerName的爱像日光般温暖我的每一处，花花要开撑起来啦~", },
	[182728] = {id=182728, zh_CN="哎呀呀，好多好多礼物哦！我要把每份礼物种进心田~你等等我", },
	[182729] = {id=182729, zh_CN="看台宾客", },
	[182730] = {id=182730, zh_CN="（插画）", },
	[182731] = {id=182731, zh_CN="滴——", },
	[182732] = {id=182732, zh_CN="你的个人终端收到一封与众不同的电子邀请函。设计简约却透着奢华本质的黑色信封底图，落款处是一枚闪耀的月牙徽记——月影商会象征身份的防伪标记，将检测机扫描在邀请函上，会直接提取到邀请函主人的信息。", },
	[182733] = {id=182733, zh_CN="【邀请函】\n 诚邀独一无二的贵宾—%PlayerName\n 莅临月影商会新季度珍品之夜。期待与您共鉴星河瑰宝。\n ——奥黛特·德·月影", },
	[182734] = {id=182734, },
	[182735] = {id=182735, },
	[182736] = {id=182736, zh_CN="【插画】", },
	[182737] = {id=182737, zh_CN="拍卖会当天，你来到商会。商会阶梯之上，一位身着剪裁利落、泛着冷光的黑银色礼服裙的女性优雅走下——正是奥黛特·德·月影。", },
	[182738] = {id=182738, zh_CN="她步伐从容，高跟鞋敲击地面的声音清脆而富有节奏感，脸上带着恰到好处的商业微笑。", },
	[182739] = {id=182739, zh_CN="目光扫过大名鼎鼎的“天外来客”，不动声色地将你从上到下“评估”了一遍", },
	[182740] = {id=182740, zh_CN="嘶，感觉在奥黛特视线中，每个人的头顶都标注着从高到低的“价格标签”。", },
	[182741] = {id=182741, zh_CN="%PlayerName，你来了。", },
	[182742] = {id=182742, zh_CN="我就知道，这份‘独一无二’的邀请函，不会落空。", },
	[182743] = {id=182743, zh_CN="大胆表达欲望", },
	[182744] = {id=182744, zh_CN="希望今天我能够满载而归。", },
	[182745] = {id=182745, zh_CN="那是当然，一定会让%PlayerName满意的。", },
	[182746] = {id=182746, zh_CN="恭维月影商会", },
	[182747] = {id=182747, zh_CN="久闻月影商会的大名，自然要来一览风采。", },
	[182748] = {id=182748, zh_CN="那预祝今天的拍卖能让你满意。", },
	[182749] = {id=182749, zh_CN="感谢邀请", },
	[182750] = {id=182750, zh_CN="感谢奥黛特小姐的邀请函。", },
	[182751] = {id=182751, zh_CN="不客气，月影商会立志收集星际奇物，这是我们应该做的。", },
	[182752] = {id=182752, zh_CN="沉默", },
	[182753] = {id=182753, zh_CN="回握，沉默。", },
	[182754] = {id=182754, zh_CN="礼貌地笑", },
	[182755] = {id=182755, zh_CN="奥黛特与你僵持在原地，隐隐间有什么气场在相互挤压撕斗，谁也不愿落下风。", },
	[182756] = {id=182756, zh_CN="（她的握手坚定有力，带着掌控感） 欢迎来到月影商会的珍品之夜。", },
	[182757] = {id=182757, zh_CN="旅途顺利吗？希望忽如其来的邀约，没让您这位‘天外来客’感到困扰。", },
	[182758] = {id=182758, zh_CN="她的目光始终带着评估，仿佛在计算着无形的价值砝码。", },
	[182759] = {id=182759, zh_CN="您的座位在VIP区，视野最佳。请随我来。", },
	[182760] = {id=182760, zh_CN="步入恢弘的拍卖主厅，璀璨的水晶灯下，一件件被特制玻璃罩着的拍品在聚光灯下熠熠生辉。", },
	[182761] = {id=182761, zh_CN="在走向VIP区的路上，你的目光被主展台旁边一个相对幽静的独立展区吸引。那里展示着几株形态奇异、散发着微弱流光的植物标本，其独特的外表和展台标签上的“未探索星域”字样，吸引着几位收藏家与植物学家驻足。", },
	[182762] = {id=182762, zh_CN="旁白；穿过展台，奥黛特领着你穿过中间的看台走向VIP包间，看台的宾客窃窃私语，都在讨论着今日的展品。零星几句对话飘入你的耳中。", },
	[182763] = {id=182763, zh_CN="你看到了吗？今天的拍卖会好多新兴活体标本啊，都是没有见过的……月影商会要开始涉足星域探索了吗？", },
	[182764] = {id=182764, zh_CN="嘘……小声点。我听说啊，这次月影商会的保密做得特别好，压轴商品不仅奥黛特会长亲自拍品，而且都没列在目录里。", },
	[182765] = {id=182765, zh_CN="据说是一份“拥有生命的”标本", },
	[182766] = {id=182766, zh_CN="奥黛特会长对展品很自信！我们拭目以待吧。", },
	[182767] = {id=182767, zh_CN="今晚的拍品，有些连我也为之动心。", },
	[182768] = {id=182768, zh_CN="尤其是……那些蕴藏着极高研究价值的全新“生命形态”。", },
	[182769] = {id=182769, zh_CN="相信我，你一定能得到心仪之物。", },
	[182770] = {id=182770, zh_CN="你望着奥黛特笃定的表情，不禁燃起一丝好奇。", },
	[182771] = {id=182771, zh_CN="刚刚的种种信息在脑海里整合，生命力充沛……植物标本……全新的生命形态……", },
	[182772] = {id=182772, zh_CN="一个强烈的念头瞬间击中了你，作为一个游历宇宙的星舰舰长，你滞留在此的原因便是灵魂碎成了“情绪花种”……", },
	[182773] = {id=182773, zh_CN="作为商会会长，想要知道我在寻找奇异的花朵并不困难……", },
	[182774] = {id=182774, zh_CN="你眼眸一亮，目光灼灼地盯住奥黛特，你的目光里有追问，有试探，亦有强烈的期待", },
	[182775] = {id=182775, zh_CN="难道她已经找到了新的“情绪花种”？", },
	[182776] = {id=182776, zh_CN="直白询问", },
	[182777] = {id=182777, zh_CN="奥黛特小姐，实不相瞒。", },
	[182778] = {id=182778, zh_CN="我一直在寻找一种以特异形态存在的花朵，不知您是否有相关消息？", },
	[182779] = {id=182779, zh_CN="笑而不语", },
	[182780] = {id=182780, zh_CN="或者您已经发现甚至拥有了新的实物？", },
	[182781] = {id=182781, zh_CN="旁敲侧击", },
	[182782] = {id=182782, zh_CN="听闻月影商会总能网罗宇宙奇珍……", },
	[182783] = {id=182783, zh_CN="不知今晚是否有……一些“感性”的拍品？", },
	[182784] = {id=182784, zh_CN="铺垫透露", },
	[182785] = {id=182785, zh_CN="（思索片刻）奥黛特小姐的收藏眼光一向独到。", },
	[182786] = {id=182786, zh_CN="（故意停顿）今晚的焦点拍品想必令人期待。", },
	[182787] = {id=182787, zh_CN="比如……一些能映射内心的稀有植物？", },
	[182788] = {id=182788, zh_CN="暂时不问", },
	[182789] = {id=182789, zh_CN="你思索片刻，还是决定先搁置“情绪花种”。", },
	[182790] = {id=182790, zh_CN="（望向奥黛特）谢谢您的安排。我很期待今晚的拍卖。", },
	[182791] = {id=182791, zh_CN="（点头）明智的选择。", },
	[182792] = {id=182792, zh_CN="未知的惊喜才最诱人，不是吗？", },
	[182793] = {id=182793, zh_CN="（笑容职业化） 请坐，拍卖即将开始。", },
	[182794] = {id=182794, zh_CN="（奥黛特脚步未停，嘴角勾起一抹意味深长的弧度，眼神锐利地扫过玩家。）", },
	[182795] = {id=182795, zh_CN="亲爱的，你是在寻找一种花吗，比如……绣球？", },
	[182796] = {id=182796, zh_CN="（望向远方，似乎陷入某种回忆）那真是一个令人着迷的奇物。", },
	[182797] = {id=182797, zh_CN="它的价值，往往超乎想象。", },
	[182798] = {id=182798, zh_CN="（她的唇瓣蹭过你的侧脸）今晚……或许会有惊喜？", },
	[182799] = {id=182799, zh_CN="（奥黛特笑容不变，但眼神略显审视）", },
	[182800] = {id=182800, zh_CN="哦？看来您有特定的目标。", },
	[182801] = {id=182801, zh_CN="商会的拍品目录想必您已看过……", },
	[182802] = {id=182802, zh_CN="至于未公开的惊喜，那就看缘份，也看……实力了。", },
	[182803] = {id=182803, zh_CN="（奥黛特笑容淡了一分，语气略显疏离）亲爱的，你不妨多关注目录上的珍品。", },
	[182804] = {id=182804, zh_CN="月影商会只交易……有明确价值的东西。", },
	[182805] = {id=182805, zh_CN="请保持期待吧。", },
	[182806] = {id=182806, zh_CN="（完成将你引至VIP座位的工作，奥黛特朝你优雅颔首，转身走向拍卖台。", },
	[182807] = {id=182807, zh_CN="无数聚光灯瞬间聚焦在奥黛特身上。此时此刻，奥黛特·德·月影，化身成这场拍卖会的庄家，站在欲望堆积的高塔上。", },
	[182808] = {id=182808, zh_CN="“珍品之夜”开始了……", },
	[182809] = {id=182809, },
	[182810] = {id=182810, },
	[182811] = {id=182811, zh_CN="【插画】", },
	[182812] = {id=182812, zh_CN="（站在拍卖台后，气场全开，声音透过扩音器清晰传遍全场，带着掌控一切的自信）", },
	[182813] = {id=182813, zh_CN="诸位尊贵的来宾，星际的探索者、收藏家、慧眼独具的投资者们！", },
	[182814] = {id=182814, zh_CN="欢迎莅临月影商会新季度珍品之夜！", },
	[182815] = {id=182815, zh_CN="今夜，我们将共同开启一场穿越星际、触及非凡的寻宝之旅！", },
	[182816] = {id=182816, zh_CN="台下的目光被她吸引，气氛逐渐热烈。奥黛特抬起手臂，她话锋一转，精准地将全场目光投向你的位置。", },
	[182817] = {id=182817, zh_CN="今晚，我们不仅汇聚了来自星海各处的奇珍名品……", },
	[182818] = {id=182818, zh_CN="更有幸迎来了一位极其特殊的贵宾……", },
	[182819] = {id=182819, zh_CN="一位真正来自浩瀚星空之外，拥有独一无二视角的‘天外来客’！”", },
	[182820] = {id=182820, zh_CN="全场目光瞬间聚焦在你身上！一束舞台光随着奥黛特逐渐激昂的声音，朝你射来，将你的身影完全照亮，倏然，拍卖舞台陷入黑暗，整个商会厅，只剩下你脚下的一隅方寸。", },
	[182821] = {id=182821, zh_CN="反客为主", },
	[182822] = {id=182822, zh_CN="你在众人注视下，从容起身，带着一丝了然的笑意，向奥黛特及全场微微颔首。", },
	[182823] = {id=182823, zh_CN="（声音沉稳清晰） “奥黛特小姐过誉了。宇宙之大，无奇不有。", },
	[182824] = {id=182824, zh_CN="能吸引我驻足此地的，正是奥黛特小姐您这位‘星际领航员’无与伦比的眼光。", },
	[182825] = {id=182825, zh_CN="（闪过一丝惊讶，随即化为毫不掩饰的欣赏和棋逢对手的兴奋。）", },
	[182826] = {id=182826, zh_CN="“星际领航员”，我喜欢这个称呼。", },
	[182827] = {id=182827, zh_CN="维持镇定", },
	[182828] = {id=182828, zh_CN="你在注视下有些紧张，但努力维持镇定，站起身来，略显僵硬地点头致意。", },
	[182829] = {id=182829, zh_CN="呃……谢谢奥黛特小姐。月影商会的名声……确实如雷贯耳。", },
	[182830] = {id=182830, zh_CN="感谢您的认可！这正是我们不懈追求的目标。", },
	[182831] = {id=182831, zh_CN="迅速站起", },
	[182832] = {id=182832, zh_CN="你在众目睽睽之下显得手足无措，迅速站起身时甚至碰了下椅子，发出轻微响声。", },
	[182833] = {id=182833, zh_CN="你满脸通红，张了张嘴却什么也没说出来。", },
	[182834] = {id=182834, zh_CN="请给我们的贵宾一点掌声，他有些害羞。", },
	[182835] = {id=182835, zh_CN="你捂着脸，在雷鸣掌声中迅速坐回座位", },
	[182836] = {id=182836, zh_CN="来我们的贵客也被今晚的珍品震撼得一时失语了！", },
	[182837] = {id=182837, zh_CN="那么，就让我们用一个足以点燃在座各位的开场仪式，来回应这份‘无声的震撼’吧！", },
	[182838] = {id=182838, zh_CN="奥黛特的声音在阴影下缓缓流淌，引诱着来客坠入欲望梦乡。", },
	[182839] = {id=182839, zh_CN="试想，连这样一位见惯了宇宙奇观的旅人，都专程为我们的珍品之夜而来……", },
	[182840] = {id=182840, zh_CN="你身上炙热的灼烧感消失，只是一瞬，在场的所有买家如万有引力般转头望向站在舞台的奥黛特，她像是火焰，星点火光便带起全场热潮。", },
	[182841] = {id=182841, zh_CN="她微微停顿，环视全场，眼神充满煽动性", },
	[182842] = {id=182842, zh_CN="这本身，不就是对我们月影商会所收揽奇物的最高认可吗？", },
	[182843] = {id=182843, zh_CN="这难道不预示着……", },
	[182844] = {id=182844, zh_CN="今晚的每一件拍品，都蕴含着足以打动星辰、跨越文明的非凡价值吗？”", },
	[182845] = {id=182845, zh_CN="一个令人印象深刻的开场，带领这场拍卖会达到了前所未有的高度。", },
	[182846] = {id=182846, zh_CN="虽然被奥黛特摆了一道，但看着如此热烈的气氛，你心中的气愤渐渐被扭曲的自傲所压抑。", },
	[182847] = {id=182847, zh_CN="啊，果然是我呢，影响力前所未有的大呀。", },
	[182848] = {id=182848, zh_CN="拍卖会在奥黛特的主持下有条不紊地进行着，你翻看目录的动作越发焦躁，拍卖会已经渐入尾声，你却还没有见到任何关于“情绪花种”的信息，更不要说实物了。", },
	[182849] = {id=182849, },
	[182850] = {id=182850, },
	[182851] = {id=182851, },
	[182852] = {id=182852, zh_CN="一位穿着商会制服、气质干练的助理悄然走到玩家身边，低声且恭敬地蹲下。", },
	[182853] = {id=182853, zh_CN="客人，奥黛特女士请您拍卖结束后，移步她的私人办公室一叙。她说……有您会感兴趣的东西。", },
	[182854] = {id=182854, zh_CN="直到拍卖会结束，奥黛特都没有再来找过你，你想要去质问她为什么不遵守承诺。", },
	[182855] = {id=182855, zh_CN="你向商会前台询问了奥黛特的办公室所在，工作人员似乎已经得到示意，没有任何阻拦地将奥黛特的行踪告知于你。", },
	[182856] = {id=182856, },
	[182857] = {id=182857, zh_CN="你敲门进入奥黛特的办公室，奥黛特已脱掉了拍卖时的裙装，只穿着剪裁合身的衬衫，背对着玩家，正看着窗外的夜景。听到脚步声，她转过身。", },
	[182858] = {id=182858, zh_CN="（她脸上带着毫不掩饰的、棋逢对手的愉悦笑容，眼神明亮而充满兴趣。奥黛特主动走向柜台。）", },
	[182859] = {id=182859, zh_CN="请坐。想喝点什么？星尘佳酿，还是方舟特产的月光茶？", },
	[182860] = {id=182860, zh_CN="水就可以。", },
	[182861] = {id=182861, zh_CN="亲爱的，你刚才在台上的表现……精彩绝伦。", },
	[182862] = {id=182862, zh_CN="说实话，我很久没遇到能这样‘反将一军’的聪明人了。", },
	[182863] = {id=182863, zh_CN="这份人情，我奥黛特记下了。", },
	[182864] = {id=182864, zh_CN="（她转过身，脸上是标准而略显疏离的商业微笑，指了指办公桌对面的椅子。）", },
	[182865] = {id=182865, zh_CN="请坐。感谢您今晚的出席……", },
	[182866] = {id=182866, zh_CN="特别是……在台上的配合。", },
	[182867] = {id=182867, zh_CN="您对情绪花很感兴趣？我们可以谈谈。", },
	[182868] = {id=182868, zh_CN="（她转过身，靠在办公桌边缘，双臂环抱，眼神平静无波，带着公事公办的审视。）", },
	[182869] = {id=182869, zh_CN="奥黛特小姐，我想我的配合应该得到该有的报酬。", },
	[182870] = {id=182870, zh_CN="比如……情绪花种的信息。", },
	[182871] = {id=182871, zh_CN="坐。时间宝贵，开门见山吧。", },
	[182872] = {id=182872, zh_CN="你想要情绪花的种子？", },
	[182873] = {id=182873, zh_CN="奥黛特小姐有见过以晶体形态保持活性的花种吗？", },
	[182874] = {id=182874, zh_CN="（笑着从同一个抽屉拿出那个恒温盒，放在桌上，推到玩家面前，但并未打开。她身体微微前倾，带着分享秘密的兴致。）", },
	[182875] = {id=182875, zh_CN="我知道你在找什么。", },
	[182876] = {id=182876, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，仿佛凝结着黑蓝色雾气的绣球花种。", },
	[182877] = {id=182877, zh_CN="你能告诉我它的来历吗，奥黛特小姐？", },
	[182878] = {id=182878, zh_CN="蕴藏着“自私”情绪的绣球结晶。", },
	[182879] = {id=182879, zh_CN="它……来自我。", },
	[182880] = {id=182880, zh_CN="眼神中闪过一丝追忆，但更多的是成功者的锐利。", },
	[182881] = {id=182881, zh_CN="一场差点吞噬整个商会的风暴。对手联合围剿，舆论汹汹。为了保全月影的根基，我做了选择……一些在外人看来冷酷、自私、落井下石的选择。", },
	[182882] = {id=182882, zh_CN="它就是那时从我身体里分离出来。", },
	[182883] = {id=182883, zh_CN="那一刻我就知道，它是无价之宝。", },
	[182884] = {id=182884, zh_CN="我一直小心保管，直到……", },
	[182885] = {id=182885, zh_CN="等来了一个值得交易的‘天外来客’。", },
	[182886] = {id=182886, zh_CN="报价吧。", },
	[182887] = {id=182887, zh_CN="你的价值比你想象中的还要大，今晚的拍卖会，我该承认，我利用了你。", },
	[182888] = {id=182888, zh_CN="但你也给了我足够的惊喜。", },
	[182889] = {id=182889, zh_CN="如果你愿意‘出卖’你的特别之处……", },
	[182890] = {id=182890, zh_CN="我很乐意为你量身打造一场绝无仅有的盛大拍卖，让你的价值响彻星际。如何？", },
	[182891] = {id=182891, zh_CN="她大方地将种子盒推到玩家面前。", },
	[182892] = {id=182892, zh_CN="至于这颗种子就当是……我欠你人情的抵押品？", },
	[182893] = {id=182893, zh_CN="当然也可以是我们合作的……", },
	[182894] = {id=182894, zh_CN="“定情信物。”", },
	[182895] = {id=182895, zh_CN="旧时代的信物大全里是这样解释的吗？", },
	[182896] = {id=182896, zh_CN="我想我应该没有引用错误。", },
	[182897] = {id=182897, zh_CN="接受种子", },
	[182898] = {id=182898, zh_CN="种子我收下。至于拍卖……以后再说。", },
	[182899] = {id=182899, zh_CN="好。", },
	[182900] = {id=182900, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182901] = {id=182901, zh_CN="购买种子", },
	[182902] = {id=182902, zh_CN="人情归人情，交易归交易。种子我按市价买。", },
	[182903] = {id=182903, zh_CN="哦？那就给你一个……VIP折扣吧。", },
	[182904] = {id=182904, zh_CN="这次不要拒绝了。", },
	[182905] = {id=182905, zh_CN="谢谢。", },
	[182906] = {id=182906, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182907] = {id=182907, zh_CN="（从办公桌一个带锁的抽屉里取出一个微小的、散发着微弱寒气的恒温盒。）", },
	[182908] = {id=182908, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，仿佛凝结着黑蓝色雾气的绣球花种。", },
	[182909] = {id=182909, zh_CN="一颗凝聚了“自私”情绪的绣球花，是你今天参加拍卖的原因，对吗？", },
	[182910] = {id=182910, zh_CN="是的，奥黛特小姐。", },
	[182911] = {id=182911, zh_CN="可以告诉我它的来历吗？", },
	[182912] = {id=182912, zh_CN="它确实在我这里保管了一段时间，至于来源，你只需知道它货真价实，且来源明确。", },
	[182913] = {id=182913, zh_CN="玩家；请开价吧。", },
	[182914] = {id=182914, zh_CN="关上盒子，目光直视玩家，带着商人的精明", },
	[182915] = {id=182915, zh_CN="我可以把它给你。但你需要告诉我两件事。", },
	[182916] = {id=182916, zh_CN="第一，这种子对你而言，真正的价值是什么？", },
	[182917] = {id=182917, zh_CN="第二，你收集它们……最终目的为何？", },
	[182918] = {id=182918, zh_CN="信息换信息，很公平，不是吗？", },
	[182919] = {id=182919, zh_CN="隐瞒部分", },
	[182920] = {id=182920, zh_CN="没什么价值，我只有收集齐这些花种，才能回到正轨。", },
	[182921] = {id=182921, zh_CN="原来是这样。", },
	[182922] = {id=182922, zh_CN="给。", },
	[182923] = {id=182923, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182924] = {id=182924, zh_CN="诚实回答", },
	[182925] = {id=182925, zh_CN="其实这些花种是我的一部分，我需要收集他们修复我的灵魂。", },
	[182926] = {id=182926, zh_CN="当然，也只有拼凑起灵魂，我才能回到正轨。", },
	[182927] = {id=182927, zh_CN="给。", },
	[182928] = {id=182928, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182929] = {id=182929, zh_CN="拒绝回答", },
	[182930] = {id=182930, zh_CN="对不起，我不能回答你这个问题，但是它确实对我非常重要。", },
	[182931] = {id=182931, zh_CN="我愿意花你任何报价来购买它", },
	[182932] = {id=182932, zh_CN="也算是实话。", },
	[182933] = {id=182933, zh_CN="（将花种递给你）给。", },
	[182934] = {id=182934, zh_CN="“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182935] = {id=182935, zh_CN="没有废话，直接从办公桌一个带锁的抽屉里取出一个微小的、散发着微弱寒气的恒温盒。", },
	[182936] = {id=182936, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，仿佛凝结着黑蓝色雾气的绣球花种。", },
	[182937] = {id=182937, zh_CN="一朵凝聚了“自私”情绪的绣球花，就是你的目标。", },
	[182938] = {id=182938, zh_CN="是的，奥黛特小姐。", },
	[182939] = {id=182939, zh_CN="她将盒子推向玩家，报出一个天文数字般的价格。", },
	[182940] = {id=182940, zh_CN="这个价。金币结算，或者等值的、让我心动的稀有资源、情报。不接受赊账。", },
	[182941] = {id=182941, zh_CN="玩家；我想知道奥黛特小姐从何得到这朵“情绪花种”。", },
	[182942] = {id=182942, zh_CN="来源？这不在交易范畴内。", },
	[182943] = {id=182943, zh_CN="你只需要知道，它货真价实……", },
	[182944] = {id=182944, zh_CN="且目前……独一无二。", },
	[182945] = {id=182945, zh_CN="你买，或者不买。 “欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182946] = {id=182946, zh_CN="站起身，走到巨大的落地窗前，望着窗外，声音恢复了掌控一切的从容。", },
	[182947] = {id=182947, zh_CN="种子你拿到了。记住，月影商会的大门永远对有‘价值’的客人敞开。", },
	[182948] = {id=182948, zh_CN="她转过身，脸上是标志性的、飒爽的笑容", },
	[182949] = {id=182949, zh_CN="如果你有关于其他‘情绪花’的消息，或者任何……足够‘稀有’的东西，随时来找我。", },
	[182950] = {id=182950, zh_CN="当然，想要购买什么，也可以来找我，但不要忘记带着让我满意的价码。", },
	[182951] = {id=182951, zh_CN="无论是金币、情报，还是……你本身的价值。", },
	[182952] = {id=182952, zh_CN="她优雅地做了个“请”的手势，送客之意明显。那笑容在璀璨星河的背景下，既迷人又带着不容置疑的距离感。", },
	[182953] = {id=182953, zh_CN="“期待我们的下一次……交易，或者合作。", },
	[182954] = {id=182954, zh_CN="再会。", },
	[182955] = {id=182955, zh_CN="你带着情绪花种子和与奥黛特打交道的复杂感受离开办公室。", },
	[182956] = {id=182956, zh_CN="奥黛特·德·月影，永远知道如何将一切，包括人心和秘密，都放在她的价值天平上衡量。", },
	[182957] = {id=182957, zh_CN="“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[182958] = {id=182958, zh_CN="全部音色", },
	[182959] = {id=182959, zh_CN="成男音色", },
	[182960] = {id=182960, zh_CN="成女音色", },
	[182961] = {id=182961, zh_CN="青年音色", },
	[182962] = {id=182962, zh_CN="少女音色", },
	[182963] = {id=182963, zh_CN="正太音色", },
	[182964] = {id=182964, zh_CN="萝莉音色", },
	[182965] = {id=182965, zh_CN="机械音色", },
	[182966] = {id=182966, zh_CN="底色", },
	[182967] = {id=182967, zh_CN="发尾", },
	[182968] = {id=182968, zh_CN="高光", },
	[182969] = {id=182969, zh_CN="商务关系", },
	[182970] = {id=182970, zh_CN="未接受", },
	[182971] = {id=182971, zh_CN="经济漩涡的涟漪", },
	[182972] = {id=182972, zh_CN="与奥黛特交互", },
	[182973] = {id=182973, zh_CN="【经济漩涡的涟漪（1）】", },
	[182974] = {id=182974, zh_CN="【经济漩涡的涟漪（2）】", },
	[182975] = {id=182975, zh_CN="【经济漩涡的涟漪（3）】", },
	[182976] = {id=182976, zh_CN="【经济漩涡的涟漪（4）】", },
	[182977] = {id=182977, zh_CN="【经济漩涡的涟漪（5）】", },
	[182978] = {id=182978, zh_CN="前往商会查明真相", },
	[182979] = {id=182979, zh_CN="前往商会寻找线索", },
	[182980] = {id=182980, zh_CN="经济漩涡的涟漪（6）", },
	[182981] = {id=182981, zh_CN="【比感情更坚贞的捆绑】", },
	[182982] = {id=182982, zh_CN="【恋爱开放公式】", },
	[182983] = {id=182983, zh_CN="好感线开启", },
	[182984] = {id=182984, zh_CN="【办公室恋情日常】", },
	[182985] = {id=182985, zh_CN="滴——", },
	[182986] = {id=182986, zh_CN="滴——", },
	[182987] = {id=182987, zh_CN="你的个人终端收到一封与众不同的电子邀请函。设计简约却透着奢华本质的黑色信封底图。", },
	[182988] = {id=182988, zh_CN="落款处是一枚闪耀的月牙徽记——月影商会象征身份的防伪标记。将检测机扫描在邀请函上，会直接提取到邀请函主人的信息。", },
	[182989] = {id=182989, zh_CN="【邀请函】\n 诚邀独一无二的贵宾—%PlayerName\n 莅临月影商会新季度珍品之夜。期待与您共鉴星河瑰宝。\n ——奥黛特·德·月影", },
	[182990] = {id=182990, },
	[182991] = {id=182991, },
	[182992] = {id=182992, zh_CN="拍卖会当天，你来到商会。商会阶梯之上，一位身着剪裁利落、泛着冷光的黑银色礼服裙的女性优雅走下——正是奥黛特·德·月影。", },
	[182993] = {id=182993, zh_CN="拍卖会当天，你来到商会。商会阶梯之上，一位身着剪裁利落、泛着冷光的黑银色礼服裙的女性优雅走下——正是奥黛特·德·月影。", },
	[182994] = {id=182994, zh_CN="她步伐从容，高跟鞋敲击地面的声音清脆而富有节奏感，脸上带着恰到好处的商业微笑。", },
	[182995] = {id=182995, zh_CN="目光扫过大名鼎鼎的“天外来客”，不动声色地将你从上到下“评估”了一遍", },
	[182996] = {id=182996, zh_CN="嘶，感觉在奥黛特视线中，每个人的头顶都标注着从高到低的“价格标签”。", },
	[182997] = {id=182997, zh_CN="%PlayerName，你来了。", },
	[182998] = {id=182998, zh_CN="我就知道，这份‘独一无二’的邀请函，不会落空。", },
	[182999] = {id=182999, zh_CN="大胆表达欲望", },
	[183000] = {id=183000, zh_CN="希望今天我能够满载而归。", },
	[183001] = {id=183001, zh_CN="那是当然，一定会让%PlayerName满意的。", },
	[183002] = {id=183002, zh_CN="恭维月影商会", },
	[183003] = {id=183003, zh_CN="久闻月影商会的大名，自然要来一览风采。", },
	[183004] = {id=183004, zh_CN="那预祝今天的拍卖能让你满意。", },
	[183005] = {id=183005, zh_CN="感谢邀请", },
	[183006] = {id=183006, zh_CN="感谢奥黛特小姐的邀请函。", },
	[183007] = {id=183007, zh_CN="不客气，月影商会立志收集星际奇物，这是我们应该做的。", },
	[183008] = {id=183008, zh_CN="沉默", },
	[183009] = {id=183009, zh_CN="回握，沉默。", },
	[183010] = {id=183010, zh_CN="礼貌地笑", },
	[183011] = {id=183011, zh_CN="奥黛特与你僵持在原地，隐隐间有什么气场在相互挤压撕斗，谁也不愿落下风。", },
	[183012] = {id=183012, zh_CN="欢迎来到月影商会的珍品之夜。", },
	[183013] = {id=183013, zh_CN="旅途顺利吗？", },
	[183014] = {id=183014, zh_CN="希望忽如其来的邀约，没让您这位“天外来客”感到困扰。", },
	[183015] = {id=183015, zh_CN="她的目光始终带着评估，仿佛在计算着无形的价值砝码。", },
	[183016] = {id=183016, zh_CN="您的座位在VIP区，视野最佳。请随我来。", },
	[183017] = {id=183017, zh_CN="步入恢弘的拍卖主厅，璀璨的水晶灯下，一件件被特制玻璃罩着的拍品在聚光灯下熠熠生辉。", },
	[183018] = {id=183018, zh_CN="在走向VIP区的路上，你的目光被主展台旁边一个相对幽静的独立展区吸引。", },
	[183019] = {id=183019, zh_CN="那里展示着几株形态奇异、散发着微弱流光的植物标本。", },
	[183020] = {id=183020, zh_CN="其独特的外表和展台标签上的“未探索星域”字样，吸引着几位收藏家与植物学家驻足。", },
	[183021] = {id=183021, zh_CN="穿过展台，奥黛特领着你穿过中间的看台走向VIP包间。", },
	[183022] = {id=183022, zh_CN="看台的宾客窃窃私语，都在讨论着今日的展品。零星几句对话飘入你的耳中。", },
	[183023] = {id=183023, zh_CN="都是没有见过的……月影商会要开始涉足星域探索了吗？", },
	[183024] = {id=183024, zh_CN="嘘……小声点。我听说啊，这次月影商会的保密做得特别好。", },
	[183025] = {id=183025, zh_CN="压轴商品不仅奥黛特会长亲自拍品，而且都没列在目录里。", },
	[183026] = {id=183026, zh_CN="据说是一份“拥有生命的”标本", },
	[183027] = {id=183027, zh_CN="奥黛特会长对展品很自信！我们拭目以待吧。", },
	[183028] = {id=183028, zh_CN="今晚的拍品，有些连我也为之动心。", },
	[183029] = {id=183029, zh_CN="尤其是……那些蕴藏着极高研究价值的全新“生命形态”。", },
	[183030] = {id=183030, zh_CN="相信我，你一定能得到心仪之物。", },
	[183031] = {id=183031, zh_CN="你望着奥黛特笃定的表情，不禁燃起一丝好奇。", },
	[183032] = {id=183032, zh_CN="刚刚的种种信息在脑海里整合……", },
	[183033] = {id=183033, zh_CN="生命力充沛……植物标本……全新的生命形态……", },
	[183034] = {id=183034, zh_CN="一个强烈的念头瞬间击中了你！", },
	[183035] = {id=183035, zh_CN="作为一个游历宇宙的星舰舰长，你滞留在此的原因便是灵魂碎成了“情绪花种”……", },
	[183036] = {id=183036, zh_CN="作为商会会长，想要知道我在寻找奇异的花朵并不困难……", },
	[183037] = {id=183037, zh_CN="你眼眸一亮，目光灼灼地盯住奥黛特，你的目光里有追问，有试探，亦有强烈的期待", },
	[183038] = {id=183038, zh_CN="难道她已经找到了新的“情绪花种”？", },
	[183039] = {id=183039, zh_CN="直白询问", },
	[183040] = {id=183040, zh_CN="奥黛特小姐，实不相瞒。", },
	[183041] = {id=183041, zh_CN="我一直在寻找一种以特异形态存在的花朵，不知您是否有相关消息？", },
	[183042] = {id=183042, zh_CN="笑而不语", },
	[183043] = {id=183043, zh_CN="或者您已经发现甚至拥有了新的实物？", },
	[183044] = {id=183044, zh_CN="旁敲侧击", },
	[183045] = {id=183045, zh_CN="听闻月影商会总能网罗宇宙奇珍……", },
	[183046] = {id=183046, zh_CN="不知今晚是否有……一些“感性”的拍品？", },
	[183047] = {id=183047, zh_CN="铺垫透露", },
	[183048] = {id=183048, zh_CN="奥黛特小姐的收藏眼光一向独到。", },
	[183049] = {id=183049, zh_CN="今晚的焦点拍品想必令人期待。", },
	[183050] = {id=183050, zh_CN="比如……一些能映射内心的稀有植物？", },
	[183051] = {id=183051, zh_CN="暂时不问", },
	[183052] = {id=183052, zh_CN="你思索片刻，还是决定先搁置“情绪花种”。", },
	[183053] = {id=183053, zh_CN="谢谢您的安排。我很期待今晚的拍卖。", },
	[183054] = {id=183054, zh_CN="明智的选择。", },
	[183055] = {id=183055, zh_CN="未知的惊喜才最诱人，不是吗？", },
	[183056] = {id=183056, zh_CN="请坐，拍卖即将开始。", },
	[183057] = {id=183057, zh_CN="奥黛特脚步未停，嘴角勾起一抹意味深长的弧度，眼神锐利地扫过你。", },
	[183058] = {id=183058, zh_CN="亲爱的，你是在寻找一种花吗，比如……绣球？", },
	[183059] = {id=183059, zh_CN="那真是一个令人着迷的奇物。", },
	[183060] = {id=183060, zh_CN="它的价值，往往超乎想象。", },
	[183061] = {id=183061, zh_CN="今晚……或许会有惊喜？", },
	[183062] = {id=183062, zh_CN="奥黛特笑容不变，但眼神略显审视", },
	[183063] = {id=183063, zh_CN="哦？看来您有特定的目标。", },
	[183064] = {id=183064, zh_CN="商会的拍品目录想必您已看过……", },
	[183065] = {id=183065, zh_CN="至于未公开的惊喜，那就看缘份，也看……实力了。", },
	[183066] = {id=183066, zh_CN="亲爱的，你不妨多关注目录上的珍品。", },
	[183067] = {id=183067, zh_CN="月影商会只交易……有明确价值的东西。", },
	[183068] = {id=183068, zh_CN="请保持期待吧。", },
	[183069] = {id=183069, zh_CN="完成将你引至VIP座位的工作，奥黛特朝你优雅颔首，转身走向拍卖台。", },
	[183070] = {id=183070, zh_CN="无数聚光灯瞬间聚焦在奥黛特身上。", },
	[183071] = {id=183071, zh_CN="此时此刻，奥黛特·德·月影，化身成这场拍卖会的庄家，站在欲望堆积的高塔上。", },
	[183072] = {id=183072, zh_CN="“珍品之夜”开始了……", },
	[183073] = {id=183073, },
	[183074] = {id=183074, },
	[183075] = {id=183075, zh_CN="站在拍卖台后，气场全开，声音透过扩音器清晰传遍全场，带着掌控一切的自信", },
	[183076] = {id=183076, zh_CN="站在拍卖台后，气场全开，声音透过扩音器清晰传遍全场，带着掌控一切的自信", },
	[183077] = {id=183077, zh_CN="诸位尊贵的来宾，星际的探索者、收藏家、慧眼独具的投资者们！", },
	[183078] = {id=183078, zh_CN="欢迎莅临月影商会新季度珍品之夜！", },
	[183079] = {id=183079, zh_CN="今夜，我们将共同开启一场穿越星际、触及非凡的寻宝之旅！", },
	[183080] = {id=183080, zh_CN="台下的目光被她吸引，气氛逐渐热烈。", },
	[183081] = {id=183081, zh_CN="奥黛特抬起手臂，她话锋一转，精准地将全场目光投向你的位置。", },
	[183082] = {id=183082, zh_CN="今晚，我们不仅汇聚了来自星海各处的奇珍名品……", },
	[183083] = {id=183083, zh_CN="更有幸迎来了一位极其特殊的贵宾……", },
	[183084] = {id=183084, zh_CN="一位真正来自浩瀚星空之外，拥有独一无二视角的‘天外来客’！”", },
	[183085] = {id=183085, zh_CN="全场目光瞬间聚焦在你身上！", },
	[183086] = {id=183086, zh_CN="一束舞台光随着奥黛特逐渐激昂的声音，朝你射来，将你的身影完全照亮。", },
	[183087] = {id=183087, zh_CN="倏然，拍卖舞台陷入黑暗，整个商会厅，只剩下你脚下的一隅方寸。", },
	[183088] = {id=183088, zh_CN="反客为主", },
	[183089] = {id=183089, zh_CN="你在众人注视下，从容起身，带着一丝了然的笑意，向奥黛特及全场微微颔首。", },
	[183090] = {id=183090, zh_CN="奥黛特小姐过誉了。宇宙之大，无奇不有。", },
	[183091] = {id=183091, zh_CN="能吸引我驻足此地的，正是奥黛特小姐您这位‘星际领航员’无与伦比的眼光。", },
	[183092] = {id=183092, zh_CN="奥黛特闪过一丝惊讶，随即化为毫不掩饰的欣赏和棋逢对手的兴奋。", },
	[183093] = {id=183093, zh_CN="“星际领航员”，我喜欢这个称呼。", },
	[183094] = {id=183094, zh_CN="维持镇定", },
	[183095] = {id=183095, zh_CN="你在注视下有些紧张，但努力维持镇定，站起身来，略显僵硬地点头致意。", },
	[183096] = {id=183096, zh_CN="呃……谢谢奥黛特小姐。月影商会的名声……确实如雷贯耳。", },
	[183097] = {id=183097, zh_CN="感谢您的认可！这正是我们不懈追求的目标。", },
	[183098] = {id=183098, zh_CN="迅速站起", },
	[183099] = {id=183099, zh_CN="你在众目睽睽之下显得手足无措，迅速站起身时甚至碰了下椅子，发出轻微响声。", },
	[183100] = {id=183100, zh_CN="你满脸通红，张了张嘴却什么也没说出来。", },
	[183101] = {id=183101, zh_CN="请给我们的贵宾一点掌声，他有些害羞。", },
	[183102] = {id=183102, zh_CN="你捂着脸，在雷鸣掌声中迅速坐回座位", },
	[183103] = {id=183103, zh_CN="我们的贵客也被今晚的珍品震撼得一时失语了！", },
	[183104] = {id=183104, zh_CN="那么，就让我们用一个足以点燃在座各位的开场仪式，来回应这份‘无声的震撼’吧！", },
	[183105] = {id=183105, zh_CN="奥黛特的声音在阴影下缓缓流淌，引诱着来客坠入欲望梦乡。", },
	[183106] = {id=183106, zh_CN="试想，连这样一位见惯了宇宙奇观的旅人，都专程为我们的珍品之夜而来……", },
	[183107] = {id=183107, zh_CN="你身上炙热的灼烧感消失，只是一瞬，在场的所有买家如万有引力般转头望向站在舞台的奥黛特，她像是火焰，星点火光便带起全场热潮。", },
	[183108] = {id=183108, zh_CN="你身上炙热的灼烧感消失……", },
	[183109] = {id=183109, zh_CN="只是一瞬，在场的所有买家如万有引力般转头望向站在舞台的奥黛特。", },
	[183110] = {id=183110, zh_CN="她微微停顿，环视全场，眼神充满煽动性。", },
	[183111] = {id=183111, zh_CN="这本身，不就是对我们月影商会所收揽奇物的最高认可吗？", },
	[183112] = {id=183112, zh_CN="这难道不预示着……··", },
	[183113] = {id=183113, zh_CN="今晚的每一件拍品，都蕴含着足以打动星辰、跨越文明的非凡价值吗？”", },
	[183114] = {id=183114, zh_CN="一个令人印象深刻的开场，带领这场拍卖会达到了前所未有的高度。", },
	[183115] = {id=183115, zh_CN="虽然被奥黛特摆了一道，但看着如此热烈的气氛，你心中的气愤渐渐被扭曲的自傲所压抑。", },
	[183116] = {id=183116, zh_CN="啊，果然是我呢，影响力前所未有的大呀。", },
	[183117] = {id=183117, zh_CN="拍卖会在奥黛特的主持下有条不紊地进行着……", },
	[183118] = {id=183118, zh_CN="你翻看目录的动作越发焦躁", },
	[183119] = {id=183119, zh_CN="拍卖会已经渐入尾声，你却还没有见到任何关于“情绪花种”的信息，更不要说实物了。", },
	[183120] = {id=183120, },
	[183121] = {id=183121, },
	[183122] = {id=183122, zh_CN="一位穿着商会制服、气质干练的助理悄然走到玩家身边，低声且恭敬地蹲下。", },
	[183123] = {id=183123, zh_CN="一位穿着商会制服、气质干练的助理悄然走到玩家身边，低声且恭敬地蹲下。", },
	[183124] = {id=183124, zh_CN="客人，奥黛特女士请您拍卖结束后，移步她的私人办公室一叙。", },
	[183125] = {id=183125, zh_CN="她说……有您会感兴趣的东西。", },
	[183126] = {id=183126, zh_CN="直到拍卖会结束，奥黛特都没有再来找过你。", },
	[183127] = {id=183127, zh_CN="你想要去质问她为什么不遵守承诺。", },
	[183128] = {id=183128, zh_CN="你向商会前台询问了奥黛特的办公室所在。", },
	[183129] = {id=183129, zh_CN="工作人员似乎已经得到示意，没有任何阻拦地将奥黛特的行踪告知于你。", },
	[183130] = {id=183130, zh_CN="你敲门进入奥黛特的办公室。", },
	[183131] = {id=183131, zh_CN="你敲门进入奥黛特的办公室。", },
	[183132] = {id=183132, zh_CN="她已脱掉了拍卖时的裙装，只穿着剪裁合身的衬衫。", },
	[183133] = {id=183133, zh_CN="她背对着玩家，正看着窗外的夜景。听到脚步声，转过身。", },
	[183134] = {id=183134, zh_CN="她脸上带着棋逢对手的愉悦笑容，眼神明亮而充满兴趣。", },
	[183135] = {id=183135, zh_CN="请坐。想喝点什么？", },
	[183136] = {id=183136, zh_CN="星尘佳酿，还是方舟特产的月光茶？", },
	[183137] = {id=183137, zh_CN="水就可以。", },
	[183138] = {id=183138, zh_CN="她亲自为你到了一杯水，放在桌上", },
	[183139] = {id=183139, zh_CN="亲爱的，你刚才在台上的表现……精彩绝伦。", },
	[183140] = {id=183140, zh_CN="说实话，我很久没遇到能这样‘反将一军’的聪明人了。", },
	[183141] = {id=183141, zh_CN="这份人情，我奥黛特记下了。", },
	[183142] = {id=183142, zh_CN="她转过身，脸上是标准而略显疏离的商业微笑。", },
	[183143] = {id=183143, zh_CN="她指了指办公桌对面的椅子。", },
	[183144] = {id=183144, zh_CN="请坐。感谢您今晚的出席……", },
	[183145] = {id=183145, zh_CN="特别是……在台上的配合。", },
	[183146] = {id=183146, zh_CN="您对情绪花很感兴趣？我们可以谈谈。", },
	[183147] = {id=183147, zh_CN="她转过身，靠在办公桌边缘，双臂环抱，眼神平静无波，带着公事公办的审视。", },
	[183148] = {id=183148, zh_CN="奥黛特小姐，我想我的配合应该得到该有的报酬。", },
	[183149] = {id=183149, zh_CN="比如……情绪花种的信息。", },
	[183150] = {id=183150, zh_CN="坐。时间宝贵，开门见山吧。", },
	[183151] = {id=183151, zh_CN="你想要情绪花的种子？", },
	[183152] = {id=183152, zh_CN="奥黛特小姐有见过以晶体形态保持活性的花种吗？", },
	[183153] = {id=183153, zh_CN="笑着从同一个抽屉拿出那个恒温盒，放在桌上，推到你面前。", },
	[183154] = {id=183154, zh_CN="她身体微微前倾，带着分享秘密的兴致。", },
	[183155] = {id=183155, zh_CN="我知道你在找什么。", },
	[183156] = {id=183156, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，萦绕着雾气的绣球花种。", },
	[183157] = {id=183157, zh_CN="你能告诉我它的来历吗，奥黛特小姐？", },
	[183158] = {id=183158, zh_CN="蕴藏着“自私”情绪的绣球结晶。", },
	[183159] = {id=183159, zh_CN="它……来自我。", },
	[183160] = {id=183160, zh_CN="奥黛特眼神中闪过一丝追忆，但更多的是成功者的锐利。", },
	[183161] = {id=183161, zh_CN="一场差点吞噬整个商会的风暴。对手联合围剿，舆论汹汹。为了保全月影的根基，我做了选择……一些在外人看来冷酷、自私、落井下石的选择。", },
	[183162] = {id=183162, zh_CN="它就是那时从我身体里分离出来。", },
	[183163] = {id=183163, zh_CN="那一刻我就知道，它是无价之宝。", },
	[183164] = {id=183164, zh_CN="我一直小心保管，直到……", },
	[183165] = {id=183165, zh_CN="等来了一个值得交易的‘天外来客’。", },
	[183166] = {id=183166, zh_CN="报价吧。", },
	[183167] = {id=183167, zh_CN="你的价值比你想象中的还要大，今晚的拍卖会，我该承认，我利用了你。", },
	[183168] = {id=183168, zh_CN="但你也给了我足够的惊喜。", },
	[183169] = {id=183169, zh_CN="如果你愿意‘出卖’你的特别之处……", },
	[183170] = {id=183170, zh_CN="我很乐意为你量身打造一场绝无仅有的盛大拍卖，让你的价值响彻星际。如何？", },
	[183171] = {id=183171, zh_CN="她大方地将种子盒推到玩家面前。", },
	[183172] = {id=183172, zh_CN="至于这颗种子就当是……我欠你人情的抵押品？", },
	[183173] = {id=183173, zh_CN="当然也可以是我们合作的……", },
	[183174] = {id=183174, zh_CN="定情信物。", },
	[183175] = {id=183175, zh_CN="旧时代的信物大全里是这样解释的吗？", },
	[183176] = {id=183176, zh_CN="我想我应该没有引用错误。", },
	[183177] = {id=183177, zh_CN="接受种子", },
	[183178] = {id=183178, zh_CN="种子我收下。至于拍卖……以后再说。", },
	[183179] = {id=183179, zh_CN="好。", },
	[183180] = {id=183180, },
	[183181] = {id=183181, zh_CN="购买种子", },
	[183182] = {id=183182, zh_CN="人情归人情，交易归交易。种子我按市价买。", },
	[183183] = {id=183183, zh_CN="哦？那就给你一个……VIP折扣吧。", },
	[183184] = {id=183184, zh_CN="可以先赊账，这次不要拒绝了。", },
	[183185] = {id=183185, zh_CN="谢谢。", },
	[183186] = {id=183186, },
	[183187] = {id=183187, zh_CN="从办公桌一个带锁的抽屉里取出一个散发着微弱寒气的恒温盒。", },
	[183188] = {id=183188, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，萦绕着雾气的绣球花种。", },
	[183189] = {id=183189, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，仿佛凝结着黑蓝色雾气的绣球花种。", },
	[183190] = {id=183190, zh_CN="一颗凝聚了“自私”情绪的绣球花，是你今天参加拍卖的原因，对吗？", },
	[183191] = {id=183191, zh_CN="是的，奥黛特小姐。", },
	[183192] = {id=183192, zh_CN="可以告诉我它的来历吗？", },
	[183193] = {id=183193, zh_CN="它确实在我这里保管了一段时间。", },
	[183194] = {id=183194, zh_CN="至于来源，你只需知道它货真价实，且来源明确。", },
	[183195] = {id=183195, zh_CN="请开价吧。", },
	[183196] = {id=183196, zh_CN="关上盒子，目光直视玩家，带着商人的精明", },
	[183197] = {id=183197, zh_CN="我可以把它给你。但你需要告诉我两件事。", },
	[183198] = {id=183198, zh_CN="第一，这种子对你而言，真正的价值是什么？", },
	[183199] = {id=183199, zh_CN="第二，你收集它们……最终目的为何？", },
	[183200] = {id=183200, zh_CN="信息换信息，很公平，不是吗？", },
	[183201] = {id=183201, zh_CN="隐瞒部分", },
	[183202] = {id=183202, zh_CN="没什么价值，我只有收集齐这些花种，才能回到正轨。", },
	[183203] = {id=183203, zh_CN="原来是这样。", },
	[183204] = {id=183204, zh_CN="给。", },
	[183205] = {id=183205, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[183206] = {id=183206, zh_CN="诚实回答", },
	[183207] = {id=183207, zh_CN="其实这些花种是我的一部分，我需要收集他们修复我的灵魂。", },
	[183208] = {id=183208, zh_CN="当然，也只有拼凑起灵魂，我才能回到正轨。", },
	[183209] = {id=183209, zh_CN="给。", },
	[183210] = {id=183210, zh_CN="获得情绪花种【绣球（阴生）】“欲望的逆位高塔下，自私如诚实一样坚凝。”", },
	[183211] = {id=183211, zh_CN="拒绝回答", },
	[183212] = {id=183212, zh_CN="对不起，我不能回答你这个问题，但是它确实对我非常重要。", },
	[183213] = {id=183213, zh_CN="我愿意花你任何报价来购买它", },
	[183214] = {id=183214, zh_CN="也算是实话。", },
	[183215] = {id=183215, zh_CN="给。", },
	[183216] = {id=183216, },
	[183217] = {id=183217, zh_CN="没有废话，直接从办公桌一个带锁的抽屉里取出一个散发着微弱寒气的恒温盒。", },
	[183218] = {id=183218, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，萦绕着雾气的绣球花种。", },
	[183219] = {id=183219, zh_CN="奥黛特将恒温盒打开，里面静静躺着一枚雾蓝色，仿佛凝结着黑蓝色雾气的绣球花种。", },
	[183220] = {id=183220, zh_CN="一朵凝聚了“自私”情绪的绣球花，就是你的目标。", },
	[183221] = {id=183221, zh_CN="是的，奥黛特小姐。", },
	[183222] = {id=183222, zh_CN="她将盒子推向玩家，报出一个天文数字般的价格。", },
	[183223] = {id=183223, zh_CN="1000万，金币结算，或者等值的、让我心动的稀有资源、情报。", },
	[183224] = {id=183224, zh_CN="我想知道奥黛特小姐从何得到这朵“情绪花种”。", },
	[183225] = {id=183225, zh_CN="来源？这不在交易范畴内。", },
	[183226] = {id=183226, zh_CN="你只需要知道，它货真价实……", },
	[183227] = {id=183227, zh_CN="且目前……独一无二。", },
	[183228] = {id=183228, zh_CN="你买，或者不买。", },
	[183229] = {id=183229, zh_CN="买！", },
	[183230] = {id=183230, zh_CN="但是可以赊账吗？", },
	[183231] = {id=183231, zh_CN="可以。", },
	[183232] = {id=183232, zh_CN="站起身，走到巨大的落地窗前，望着窗外。", },
	[183233] = {id=183233, zh_CN="种子你拿到了。记住，月影商会的大门永远对有‘价值’的客人敞开。", },
	[183234] = {id=183234, zh_CN="她转过身，脸上是标志性的、飒爽的笑容", },
	[183235] = {id=183235, zh_CN="如果你有关于其他‘情绪花’的消息，或者任何……足够‘稀有’的东西，随时来找我。", },
	[183236] = {id=183236, zh_CN="当然，想要购买什么，也可以来找我，但不要忘记带着让我满意的价码。", },
	[183237] = {id=183237, zh_CN="无论是金币、情报，还是……你本身的价值。", },
	[183238] = {id=183238, zh_CN="她优雅地做了个“请”的手势，送客之意明显。", },
	[183239] = {id=183239, zh_CN="那笑容在璀璨星河的背景下，既迷人又带着不容置疑的距离感。", },
	[183240] = {id=183240, zh_CN="期待我们的下一次……交易，或者合作。", },
	[183241] = {id=183241, zh_CN="再会。", },
	[183242] = {id=183242, zh_CN="你带着情绪花种子和与奥黛特打交道的复杂感受离开办公室。", },
	[183243] = {id=183243, zh_CN="奥黛特·德·月影，永远知道如何将一切，包括人心和秘密，都放在她的价值天平上衡量。", },
	[183244] = {id=183244, },
	[183245] = {id=183245, },
	[183246] = {id=183246, zh_CN="商会今日闭门谢客，空气中弥漫着淡淡的雪茄和古董木质家具的味道。", },
	[183247] = {id=183247, zh_CN="奥黛特长发挽起，正对着一堆矿石和古董艺术品皱眉。", },
	[183248] = {id=183248, zh_CN="%PlayerName，你来了。", },
	[183249] = {id=183249, zh_CN="亲爱的，很抱歉，我现在还不能招待你。", },
	[183250] = {id=183250, zh_CN="奥黛特小姐？这些都是……？", },
	[183251] = {id=183251, zh_CN="你扫过桌上形状各异的矿石，大大小小，闪烁着七彩的光泽，看起来价值不菲。", },
	[183252] = {id=183252, zh_CN="奥黛特拿起一块拳头大小，闪烁着蓝紫色光泽的矿石，放在日光灯下。", },
	[183253] = {id=183253, zh_CN="光线轻松透过矿石，在光的照耀下，矿石显示出内部流动地如水般的纹路。", },
	[183254] = {id=183254, zh_CN="是从其他星球购买珍稀矿石时遇到的小商贩。", },
	[183255] = {id=183255, zh_CN="他的店铺里品质极佳的珍稀矿石和一些我不熟识的矿石放在一起，肉眼望过去，都算佳品。", },
	[183256] = {id=183256, zh_CN="我将他们一同买回来。", },
	[183257] = {id=183257, zh_CN="不过现在想来，可能是专门设置给我的圈套。", },
	[183258] = {id=183258, zh_CN="我现在就在评定这些“疑似佳品”能不能有些价值。", },
	[183259] = {id=183259, zh_CN="毕竟相比于赚钱，商会的信用更为重要。", },
	[183260] = {id=183260, zh_CN="%PlayerName，你摸摸看。", },
	[183261] = {id=183261, zh_CN="我想你应该比我见多识广，不如帮我看看，我会支付你报酬的。", },
	[183262] = {id=183262, zh_CN="还有这些，据说是某个失落文明的祭品，你觉得呢？", },
	[183263] = {id=183263, zh_CN="没想到奥黛特小姐如此信任我？不怕我骗你？", },
	[183264] = {id=183264, zh_CN="商会当然还会复检，不过你的意见会成为很重要的参考依据，或是新的方向。", },
	[183265] = {id=183265, zh_CN="亲爱的，你如果能分析出它们的价值，当它们被卖出时，商会自然也会给你相应的佣金。", },
	[183266] = {id=183266, zh_CN="左右我不会亏的。", },
	[183267] = {id=183267, zh_CN="一窍不通，拒绝", },
	[183268] = {id=183268, zh_CN="我不行的，我对鉴宝一窍不通。", },
	[183269] = {id=183269, zh_CN="是我唐突了。", },
	[183270] = {id=183270, zh_CN="只是作为朋友，为我随便看看，也不可以吗？", },
	[183271] = {id=183271, zh_CN="好吧，我随便看看。", },
	[183272] = {id=183272, zh_CN="试试看", },
	[183273] = {id=183273, zh_CN="那我试试看吧。", },
	[183274] = {id=183274, zh_CN="请。", },
	[183275] = {id=183275, zh_CN="信心十足", },
	[183276] = {id=183276, zh_CN="交给我吧。", },
	[183277] = {id=183277, zh_CN="我拭目以待。", },
	[183278] = {id=183278, zh_CN="你指尖划过矿石表面，感受其微妙的能量波动和内部结构。", },
	[183279] = {id=183279, zh_CN="你仔细观察矿石，给其定价。", },
	[183280] = {id=183280, zh_CN="向奥黛特套取信", },
	[183281] = {id=183281, zh_CN="这些宝石都很漂亮，你不和我多聊聊收他们的故事吗？", },
	[183282] = {id=183282, zh_CN="好。", },
	[183283] = {id=183283, zh_CN="你自信分析奥黛特与你的对话，拿起“最漂亮”的宝石。", },
	[183284] = {id=183284, zh_CN="就是它了，对吧。", },
	[183285] = {id=183285, zh_CN="这些宝石都很漂亮，你……不和我多聊聊吗？", },
	[183286] = {id=183286, zh_CN="你想从我这里套话吗？", },
	[183287] = {id=183287, zh_CN="你没能从奥黛特的口中得到信息，没能找出品质上佳的宝石。", },
	[183288] = {id=183288, zh_CN="检索鉴宝知识", },
	[183289] = {id=183289, zh_CN="你小心拿起矿石，对着日照灯观察光泽和纹路，脑海里矿石的价值和种类一一和手上的矿石对应。", },
	[183290] = {id=183290, zh_CN="这颗成色极高，品质极佳的上拍宝石，价值不菲。", },
	[183291] = {id=183291, zh_CN="你拿起宝石，随意地扫了一眼便放下了，没注意到宝石表面的特殊光泽。", },
	[183292] = {id=183292, zh_CN="这颗矿石的收藏价值低，没有切割的必要。", },
	[183293] = {id=183293, zh_CN="随手拿一个", },
	[183294] = {id=183294, zh_CN="你随意拿起一块“普通”的宝石，", },
	[183295] = {id=183295, zh_CN="你将每一块宝石都拿起，左右对比，却没能发现任何“特别”的地方，你无奈将宝石放回原地。", },
	[183296] = {id=183296, zh_CN="抱歉，我能力有限。", },
	[183297] = {id=183297, zh_CN="观察光泽纹路", },
	[183298] = {id=183298, zh_CN="你小心拿起矿石，对着日照灯观察光泽和纹路，你的手指摩挲宝石表面，感受其温度。", },
	[183299] = {id=183299, zh_CN="这颗宝石制作成饰品价值会更高，适合佩戴。", },
	[183300] = {id=183300, zh_CN="你拿起宝石，随意地扫了一眼便放下了，没注意到宝石内部的瑕疵。", },
	[183301] = {id=183301, zh_CN="这个？", },
	[183302] = {id=183302, zh_CN="这颗宝石虽然漂亮，但可升值空间太低了。", },
	[183303] = {id=183303, zh_CN="使用鉴定工具", },
	[183304] = {id=183304, zh_CN="你从桌上取出鉴定工具，熟练固定上支架，轻轻转动宝石。宝石被敲打的声音在房间中回响，你细细聆听。", },
	[183305] = {id=183305, zh_CN="这颗宝石的硬度适中，品质很好。", },
	[183306] = {id=183306, zh_CN="你笨拙从桌上取出工具，手一抖，宝石从支架上滑落，你惊慌失措地望着满地碎片，懊悔不已。", },
	[183307] = {id=183307, zh_CN="没事，这块矿石不值钱。", },
	[183308] = {id=183308, zh_CN="你仔细观察矿石，给其定价", },
	[183309] = {id=183309, zh_CN="向奥黛特套取信", },
