	[183352] = {id=183352, zh_CN="你随意拿起一块“普通”的宝石，", },
	[183353] = {id=183353, zh_CN="你将每一块宝石都拿起，左右对比，却没能发现任何“特别”的地方，你无奈将宝石放回原地。", },
	[183354] = {id=183354, zh_CN="抱歉，我能力有限。", },
	[183355] = {id=183355, zh_CN="观察光泽纹路", },
	[183356] = {id=183356, zh_CN="你小心拿起矿石，对着日照灯观察光泽和纹路，你的手指摩挲宝石表面，感受其温度。", },
	[183357] = {id=183357, zh_CN="这颗宝石制作成饰品价值会更高，适合佩戴。", },
