	[183359] = {id=183359, zh_CN="这个？", },
	[183360] = {id=183360, zh_CN="这颗宝石虽然漂亮，但可升值空间太低了。", },
	[183361] = {id=183361, zh_CN="使用鉴定工具", },
	[183362] = {id=183362, zh_CN="你从桌上取出鉴定工具，熟练固定上支架，轻轻转动宝石。宝石被敲打的声音在房间中回响，你细细聆听。", },
	[183363] = {id=183363, zh_CN="这颗宝石的硬度适中，品质很好。", },
	[183364] = {id=183364, zh_CN="你笨拙从桌上取出工具，手一抖，宝石从支架上滑落，你惊慌失措地望着满地碎片，懊悔不已。", },
	[183365] = {id=183365, zh_CN="没事，这块矿石不值钱。", },
	[183366] = {id=183366, zh_CN="你的判断可以说全靠感觉，只能大致判断高低价值，缺乏专业的鉴定知识。", },
	[183367] = {id=183367, zh_CN="她的目光在你身姿、气质和举止上停留了片刻，似乎在评估另一种价值", },
	[183368] = {id=183368, zh_CN="有没有兴趣换个方式为商会发光发热？", },
	[183369] = {id=183369, zh_CN="商会缺一些能撑得起场面的“门面”。", },
	[183370] = {id=183370, zh_CN="想象一下，聚光灯下，你用专业、优雅的姿态捧起一件稀世珍宝。", },
	[183371] = {id=183371, zh_CN="你的气质、你的身份，就能为它增添一层无形的光环，让台下的买家心跳加速。", },
	[183372] = {id=183372, zh_CN="这份工作的报酬……绝对配得上你将要展现的价值。", },
	[183373] = {id=183373, zh_CN="至于工作要领……", },
	[183374] = {id=183374, zh_CN="如果有某些客户希望在拍卖前，能“近距离”感受一下心仪拍品的质感……", },
	[183375] = {id=183375, zh_CN="至于工作要领，如果有某些客户希望在拍卖前，能“近距离”感受一下心仪拍品的质感……", },
	[183376] = {id=183376, zh_CN="行个方便，提供一点“专属服务”，也是可以满足他们的。", },
	[183377] = {id=183377, zh_CN="你的仪态和分寸感，都很重要，学会了吗？", },
	[183378] = {id=183378, zh_CN="你能准确判断大部分物品的真伪和大致价值区间，尤其擅长为每件物品都编织出一个吸引人的“故事”或“概念”。", },
	[183379] = {id=183379, zh_CN="不错。还很会说话。", },
	[183380] = {id=183380, zh_CN="知道如何把一块石头说成感情的结晶，把一件器皿包装成历史的叹息……", },
	[183381] = {id=183381, zh_CN="这正是我们高级顾问需要的本事。", },
	[183382] = {id=183382, zh_CN="商会的客户，他们买的不仅是东西，更是身份、是故事、是独一无二的体验。", },
	[183383] = {id=183383, zh_CN="他们需要有人点燃他们的收藏欲。这份工作，你有兴趣试试吗？", },
	[183384] = {id=183384, zh_CN="待遇优渥，基础年薪加高额销售提成。", },
	[183385] = {id=183385, zh_CN="当然，有时候也需要替某些“重要朋友”的私人珍藏，稍微润色一下介绍词。", },
	[183386] = {id=183386, zh_CN="让它们的“来历”听起来更……符合主人的身份和品味。", },
	[183387] = {id=183387, zh_CN="这需要相当的技巧和……默契，你可以做到吗？", },
	[183388] = {id=183388, zh_CN="你逐一精准点出有价值的矿石以及潜在买家群体，逻辑清晰，证据确凿。", },
	[183389] = {id=183389, zh_CN="眼神从最初的审视，逐渐变为惊讶，最后化为毫不掩饰的欣赏。", },
	[183390] = {id=183390, zh_CN="精彩！太精彩了。", },
	[183391] = {id=183391, zh_CN="我正需要这样一双眼睛。下个月我们有一场季度拍卖会，形式比较新颖……", },
	[183392] = {id=183392, zh_CN="所以鉴定官的位置一直悬而未决……", },
	[183393] = {id=183393, zh_CN="你，有兴趣来帮我镇住这个场子吗？", },
	[183394] = {id=183394, zh_CN="报酬绝对让你满意。", },
	[183395] = {id=183395, zh_CN="拍卖成交额的千分之五作为基础佣金，外加特别委托的额外分成。", },
	[183396] = {id=183396, zh_CN="当然，高额的报酬也意味着你的工作不局限于鉴定。", },
	[183397] = {id=183397, zh_CN="有些拍品，它的“故事”需要讲得更有“深度”……", },
	[183398] = {id=183398, zh_CN="有些竞标者，他们的“偏好”也需要提前“了解”，做好引导……", },
	[183399] = {id=183399, zh_CN="灵活处理这些“人情世故”，也是首席鉴定官职责的一部分……", },
	[183400] = {id=183400, zh_CN="你明白我的意思吗？", },
	[183401] = {id=183401, zh_CN="接受", },
	[183402] = {id=183402, zh_CN="好，我接受你的邀请，奥黛特小姐。", },
	[183403] = {id=183403, zh_CN="欢迎加入月影商会。", },
	[183404] = {id=183404, zh_CN="不接受", },
	[183405] = {id=183405, zh_CN="抱歉，我需要再想象。", },
	[183406] = {id=183406, zh_CN="好吧，如果你想清楚的话，月影商会随时欢迎你。", },
	[183407] = {id=183407, },
	[183408] = {id=183408, zh_CN="没想到我们又见面了？", },
	[183409] = {id=183409, zh_CN="这次你想清楚了吗？", },
	[183410] = {id=183410, zh_CN="嗯。", },
	[183411] = {id=183411, zh_CN="我想今天会得到我想要的答案，对吗？", },
	[183412] = {id=183412, zh_CN="我接受你的工作邀请，奥黛特小姐。", },
	[183413] = {id=183413, zh_CN="欢迎加入月影商会。", },
	[183414] = {id=183414, },
	[183415] = {id=183415, zh_CN="刺耳的警笛声撕裂了清晨的宁静，蜂拥而至的记者像嗅到血腥的鲨鱼，将总部围得水泄不通。", },
	[183416] = {id=183416, zh_CN="巨大的全息投影屏上，滚动着触目惊心的头条新闻。", },
	[183417] = {id=183417, zh_CN="“月影商会深陷惊天赝品丑闻！会长奥黛特·月影涉嫌欺诈被捕！拍卖会疑为惊天骗局！”", },
	[183418] = {id=183418, zh_CN="你刚踏上商会前的平台，就被汹涌的人潮和刺眼的闪光灯淹没了，记者们的话筒几乎戳到你的脸上", },
	[183419] = {id=183419, zh_CN="“%PlayerName先生！月影商会深陷惊天赝品丑闻！报道称您是奥黛特会长的核心同谋，策划了整个拍卖骗局！您对此有何回应？”", },
	[183420] = {id=183420, zh_CN="“知情人士透露您负责‘艺术指导’，专门伪造高仿真品！证据确凿吗？”", },
	[183421] = {id=183421, zh_CN="“您是否早就知道会长在利用商会洗钱和走私？分了多少赃款？”", },
	[183422] = {id=183422, zh_CN="你的脑子“嗡”地一声炸开。", },
	[183423] = {id=183423, zh_CN="同谋？核心策划？拍卖骗局？这……这简直是天方夜谭！", },
	[183424] = {id=183424, zh_CN="那些所谓的“证据”是什么？谁在背后操纵这一切？为什么要拖我下水？！", },
	[183425] = {id=183425, zh_CN="你想开口辩解，但无数个问题像炮弹一样砸过来，闪光灯让你眩晕，推搡的人群让你寸步难行。", },
	[183426] = {id=183426, zh_CN="百口莫辩……一股巨大的无助感席卷全身，仿佛陷入一张精心编织的倒刺巨网，越挣扎缠得越紧！", },
	[183427] = {id=183427, zh_CN="就在你被记者围攻、几乎窒息之际，手腕上的个人终端发出强烈的震动，盖过了周围的喧嚣。", },
	[183428] = {id=183428, zh_CN="奥黛特·月影要求你与她紧急会见，地点在广场中心警署会面室，请在侧门由警员引导进入。", },
	[183429] = {id=183429, zh_CN="警卫将你带入会面室，锁上门。", },
	[183430] = {id=183430, zh_CN="冰冷的金属气息和消毒水味混合，厚重的防爆玻璃将狭小的空间一分为二。", },
	[183431] = {id=183431, zh_CN="玻璃另一侧，奥黛特坐在冰冷的金属椅上。", },
	[183432] = {id=183432, zh_CN="她褪去了华丽的裙装，只穿着简单的便服。", },
	[183433] = {id=183433, zh_CN="未施脂粉的脸庞有些苍白，几缕发丝垂落额前，透着一丝罕见的脆弱。", },
	[183434] = {id=183434, zh_CN="你来了。", },
	[183435] = {id=183435, zh_CN="她努力牵动嘴角，露出一个苦涩的笑容", },
	[183436] = {id=183436, zh_CN="外面乱成一团了吧。绘声绘色的故事呢，那些记者不去当编剧真是可惜了。", },
	[183437] = {id=183437, zh_CN="精彩？！奥黛特小姐！这到底是怎么回事？！", },
	[183438] = {id=183438, zh_CN="我为什么会被卷入月影商会的风波之中？", },
	[183439] = {id=183439, zh_CN="是你吧，为什么这样对我？！", },
	[183440] = {id=183440, zh_CN="%PlayerName，冷静点，听我说好吗？", },
	[183441] = {id=183441, zh_CN="没有保护好你是我的问题，但我是被栽赃的，而你……", },
	[183442] = {id=183442, zh_CN="是被他们选中，用来混淆视听、分散火力的牺牲品！", },
	[183443] = {id=183443, zh_CN="奥黛特的身体微微前倾，隔着冰冷的玻璃。", },
	[183444] = {id=183444, zh_CN="奥黛特的身体微微前倾，隔着冰冷的玻璃。", },
	[183445] = {id=183445, zh_CN="我需要你的帮助，%PlayerName。", },
	[183446] = {id=183446, zh_CN="现在，外面能自由行动，又……", },
	[183447] = {id=183447, zh_CN="她停顿了一下……", },
	[183448] = {id=183448, zh_CN="又让我此刻愿意赌上最后一丝信任的人，只有你了。", },
	[183449] = {id=183449, zh_CN="奥黛特从贴身口袋中小心翼翼地取出一枚物件。", },
	[183450] = {id=183450, zh_CN="那是一枚造型极其古朴的银质胸针。", },
	[183451] = {id=183451, zh_CN="线条流畅简洁，中心镶嵌着一颗微小却光华内敛的月牙形蓝宝石。", },
	[183452] = {id=183452, zh_CN="她将其轻轻推到玻璃窗下的狭窄传递口。", },
	[183453] = {id=183453, zh_CN="拿着它。这不是装饰徽章，是我作为会长代表的信物。", },
	[183454] = {id=183454, zh_CN="它能打开我办公室最深处一个独立于商会主系统的物理保险库。", },
	[183455] = {id=183455, zh_CN="那里面，藏着能撕破这张舆论之网的关键线索。能带领你找到真正的背叛者。", },
	[183456] = {id=183456, zh_CN="选择权在你，%PlayerName。", },
	[183457] = {id=183457, zh_CN="你愿意……拿起它，亲自去看看里面的东西。", },
	[183458] = {id=183458, zh_CN="用你自己的眼睛和判断，去揭开真相，还我们两人一个清白吗？", },
	[183459] = {id=183459, zh_CN="还是说，你也和他们一样……", },
	[183460] = {id=183460, zh_CN="认定了奥黛特·月影，就是一个彻头彻尾的信用诈骗犯？", },
	[183461] = {id=183461, zh_CN="相信奥黛特", },
	[183462] = {id=183462, zh_CN="你目光复杂地在奥黛特苍白的脸和那枚冰冷的月牙胸针之间游移。", },
	[183463] = {id=183463, zh_CN="你深吸一口气，伸手坚定地拿起了胸针。", },
	[183464] = {id=183464, zh_CN="愤怒未消，疑虑仍在，但“亲自去看”这个选项压倒了一切。", },
	[183465] = {id=183465, zh_CN="我要知道真相。无论它是什么。", },
	[183466] = {id=183466, zh_CN="好……小心。请非常小心。", },
	[183467] = {id=183467, zh_CN="保险箱的位置在办公室东墙第三块装饰板右下角，密码是……", },
	[183468] = {id=183468, zh_CN="请相信你的判断，注意安全。", },
	[183469] = {id=183469, zh_CN="你紧握着那枚仿佛带有奥黛特体温余温的胸针，离开了警局。愤怒暂时被一种沉甸甸的使命感和强烈的好奇心取代。", },
	[183470] = {id=183470, zh_CN="质疑奥黛特", },
	[183471] = {id=183471, zh_CN="你拿起那枚冰冷的月牙胸针，指尖感受到金属的凉意，心中的惊疑却如野草般疯长。", },
	[183472] = {id=183472, zh_CN="奥黛特小姐，关于你的新闻，我去商会的时间，以及你的讯息，一切都太巧了", },
	[183473] = {id=183473, zh_CN="这枚信物……是不是你设计的另一个陷阱？", },
	[183474] = {id=183474, zh_CN="你想让我进保险库做什么？销毁对你不利的证据？", },
	[183475] = {id=183475, zh_CN="还是……想把我变成你最后的替罪羊？", },
	[183476] = {id=183476, zh_CN="呵……", },
	[183477] = {id=183477, zh_CN="既然怀疑，那就去证明它！去我的保险库！去查！", },
	[183478] = {id=183478, zh_CN="用你自己的眼睛，看看里面装的到底是能洗刷我冤屈的证明，还是能把我在耻辱柱上的铁证！", },
	[183479] = {id=183479, zh_CN="保险箱的位置在办公室东墙第三块装饰板右下角，密码是……", },
	[183480] = {id=183480, zh_CN="去吧，去挥霍我的信任……", },
	[183481] = {id=183481, zh_CN="真希望 ……我的信任没有错付。", },
	[183482] = {id=183482, zh_CN="你紧握着那枚仿佛带有奥黛特体温余温的胸针，离开了警局，怀着极其复杂的心情。", },
	[183483] = {id=183483, zh_CN="商会总部外围依然有零星的记者，你利用侧门员工通道避开。", },
	[183484] = {id=183484, zh_CN="胸针在感应器上一晃，畅通无阻，一路来到会长办公室。", },
	[183485] = {id=183485, zh_CN="办公室内一片狼藉，显然被搜查过。", },
	[183486] = {id=183486, zh_CN="你按照指示，走到东墙。精美的装饰板看起来毫无异样。", },
	[183487] = {id=183487, zh_CN="你用胸针靠近第三块板的右下角——“咔哒”一声轻响。", },
	[183488] = {id=183488, zh_CN="一块约一尺见方的面板无声向内滑开，露出一个闪烁着幽蓝光芒的物理锁孔和密码输入屏。", },
	[183489] = {id=183489, zh_CN="输入奥黛特给的密码，厚重的合金门无声地向两侧滑开。", },
	[183490] = {id=183490, zh_CN="露出一个仅容一人进入的狭小空间。", },
	[183491] = {id=183491, zh_CN="里面只有一些数据硬盘，以及几份用特殊纸张装订的加密文件。", },
	[183492] = {id=183492, zh_CN="你快速浏览，触目惊心的条目映入眼帘。", },
	[183493] = {id=183493, zh_CN="一笔笔来源不明的庞大资金，通过复杂的星球网络，最终汇入几个内部账户……", },
	[183494] = {id=183494, zh_CN="拍卖会上登记拍卖成功的拍品却显示登记入库……", },
	[183495] = {id=183495, zh_CN="旁边相同的编号，却状态显示成功流出……这样的置换记录不止一条！", },
	[183496] = {id=183496, zh_CN="标注“维修/评估”的运输单，频繁往返于月影商会和几个偏僻的仓库地址。", },
	[183497] = {id=183497, zh_CN="运输物品描述模糊，但重量和体积与一些小型珍贵藏品吻合。", },
	[183498] = {id=183498, zh_CN="而异常记录的关键审批环节，电子签名赫然是几个不熟悉的名字，似乎是商会的元老董事。", },
	[183499] = {id=183499, zh_CN="寒意顺着脊椎爬升！这些骗局居然都是真的，只是罪魁祸首不是奥黛特！", },
	[183500] = {id=183500, zh_CN="所以……那些针对奥黛特和你的指控……", },
	[183501] = {id=183501, zh_CN="是为了掩盖他们自己的罪行，把水搅浑，争取时间毁灭证据！", },
	[183502] = {id=183502, zh_CN="要找到实质，还自己和奥黛特清白才行。", },
	[183503] = {id=183503, zh_CN="你迅速将异常运输记录、资金往来以及其作为可疑仓库的标注页单独打印出来……", },
	[183504] = {id=183504, zh_CN="离开商会时，你从侧面闪身而出。", },
	[183505] = {id=183505, zh_CN="并没有原路返回，而是小心地从商会正面穿梭，混入人群之中。", },
	[183506] = {id=183506, zh_CN="巨大的仓库内部堆满锈蚀的集装箱和废弃机械。", },
	[183507] = {id=183507, zh_CN="几位董事此刻正焦躁地用手帕擦着汗，对着通讯器低吼。", },
	[183508] = {id=183508, zh_CN="都搬上‘黑隼号’！对，真品、星矿、还有那些没处理掉的赝品样本……全搬上去！", },
	[183509] = {id=183509, zh_CN="警察和记者肯定被引到这边了，我们时间不多！动作快！", },
	[183510] = {id=183510, zh_CN="手下们正慌乱地将涂黑的箱子堆上一艘“废品回收”的星船。", },
	[183511] = {id=183511, zh_CN="在最后一个箱子即将被推进船舱的瞬间——", },
	[183512] = {id=183512, zh_CN="刺耳的警笛声由远及近，猛然爆发！仓库大门被强力破开！", },
	[183513] = {id=183513, zh_CN="所有人不许动！放下武器，举起双手！", },
	[183514] = {id=183514, zh_CN="早已埋伏的警察如潮水般涌入，激光瞄准器的红点瞬间布满仓库。", },
	[183515] = {id=183515, zh_CN="紧随其后的是汹涌的记者群，闪光灯将董事们一张张因惊愕、恐惧而彻底扭曲的脸，连同他身边堆积如山的罪证暴露在直播镜头下！", },
	[183516] = {id=183516, zh_CN="你的个人通讯器震动，一条信息出现。", },
	[183517] = {id=183517, zh_CN="谢谢。", },
	[183518] = {id=183518, zh_CN="你知道，风暴的中心，奥黛特·月影，正等待黎明。", },
	[183519] = {id=183519, },
	[183520] = {id=183520, zh_CN="商会总部外围依然有零星的记者，你利用侧门员工通道避开。", },
	[183521] = {id=183521, zh_CN="胸针在感应器上一晃，畅通无阻，一路来到会长办公室。", },
	[183522] = {id=183522, zh_CN="办公室内一片狼藉，显然被搜查过。", },
	[183523] = {id=183523, zh_CN="你按照指示，走到东墙。精美的装饰板看起来毫无异样。", },
	[183524] = {id=183524, zh_CN="你用胸针靠近第三块板的右下角——“咔哒”一声轻响。", },
	[183525] = {id=183525, zh_CN="一块约一尺见方的面板无声向内滑开，露出一个闪烁着幽蓝光芒的物理锁孔和密码输入屏。", },
	[183526] = {id=183526, zh_CN="输入奥黛特给的密码，厚重的合金门无声地向两侧滑开。", },
	[183527] = {id=183527, zh_CN="露出一个仅容一人进入的狭小空间。", },
	[183528] = {id=183528, zh_CN="里面只有一些数据硬盘，以及几份用特殊纸张装订的加密文件。", },
	[183529] = {id=183529, zh_CN="你快速浏览，触目惊心的条目映入眼帘。", },
	[183530] = {id=183530, zh_CN="一笔笔来源不明的庞大资金，通过复杂的星球网络，最终汇入几个内部账户……", },
	[183531] = {id=183531, zh_CN="拍卖会上登记拍卖成功的拍品却显示登记入库……", },
	[183532] = {id=183532, zh_CN="旁边相同的编号，却状态显示成功流出……这样的置换记录不止一条！", },
	[183533] = {id=183533, zh_CN="标注“维修/评估”的运输单，频繁往返于月影商会和几个偏僻的仓库地址。", },
	[183534] = {id=183534, zh_CN="运输物品描述模糊，但重量和体积与一些小型珍贵藏品吻合。", },
	[183535] = {id=183535, zh_CN="而异常记录的关键审批环节，电子签名赫然是几个不熟悉的名字，似乎是商会的元老董事。", },
	[183536] = {id=183536, zh_CN="就算如此，也不能放下对奥黛特的怀疑，或许这都是她做出的伪证？", },
	[183537] = {id=183537, zh_CN="不能打草惊蛇。", },
	[183538] = {id=183538, zh_CN="你开始了近乎偏执的搜查，不放过任何角落，却一无所获。", },
	[183539] = {id=183539, zh_CN="想要证明奥黛特的罪行，要找到实质，我需要另外的助力才行。", },
	[183540] = {id=183540, zh_CN="你迅速将异常运输记录、资金往来以及其作为可疑仓库的标注页单独打印出来……", },
	[183541] = {id=183541, zh_CN="离开商会时，你从侧面闪身而出。", },
	[183542] = {id=183542, zh_CN="并没有原路返回，而是小心地从商会正面穿梭，混入人群之中。", },
	[183543] = {id=183543, zh_CN="巨大的仓库内部堆满锈蚀的集装箱和废弃机械。", },
	[183544] = {id=183544, zh_CN="几位董事此刻正焦躁地用手帕擦着汗，对着通讯器低吼。", },
	[183545] = {id=183545, zh_CN="都搬上‘黑隼号’！对，真品、星矿、还有那些没处理掉的赝品样本……全搬上去！", },
	[183546] = {id=183546, zh_CN="警察和记者肯定被引到这边了，我们时间不多！动作快！", },
	[183547] = {id=183547, zh_CN="手下们正慌乱地将涂黑的箱子堆上一艘“废品回收”的星船……", },
	[183548] = {id=183548, zh_CN="在最后一个箱子即将被推进船舱的瞬间——", },
	[183549] = {id=183549, zh_CN="刺耳的警笛声由远及近，猛然爆发！仓库大门被强力破开！", },
	[183550] = {id=183550, zh_CN="所有人不许动！放下武器，举起双手！", },
	[183551] = {id=183551, zh_CN="早已埋伏的警察如潮水般涌入，激光瞄准器的红点瞬间布满仓库。", },
	[183552] = {id=183552, zh_CN="紧随其后的是汹涌的记者群……", },
	[183553] = {id=183553, zh_CN="闪光灯将董事们一张张因惊愕、恐惧而彻底扭曲的脸，连同他身边堆积如山的罪证暴露在直播镜头下！", },
	[183554] = {id=183554, zh_CN="你从暗处闪身而出，如雷劈中", },
	[183555] = {id=183555, zh_CN="居然不是奥黛特！难道是我错怪她了吗？", },
	[183556] = {id=183556, zh_CN="如果奥黛特是被栽赃的……", },
	[183557] = {id=183557, zh_CN="如果保险库里的账本是她留给你的“钩子”……", },
	[183558] = {id=183558, zh_CN="如果她早就知道你会怀疑……", },
	[183559] = {id=183559, zh_CN="把自己的清白全权交付给我，在我的身上全部投入一切，真的值得吗？", },
	[183560] = {id=183560, zh_CN="你的个人通讯器震动，一条信息出现。", },
	[183561] = {id=183561, zh_CN="谢谢。", },
	[183562] = {id=183562, zh_CN="一股复杂的情绪涌上心头，你的质疑，也为你和她，带来了黎明前的微光。", },
	[183563] = {id=183563, },
	[183564] = {id=183564, zh_CN="随着相关董事及其党羽的落网，大量确凿证据浮出水面……", },
	[183565] = {id=183565, zh_CN="指向奥黛特的指控被迅速推翻，她很快被无罪释放。", },
	[183566] = {id=183566, zh_CN="为了挽回商会的信誉，一场盛大的新闻发布会紧急召开。", },
	[183567] = {id=183567, zh_CN="闪光灯如同密集的星爆，将商会平台照得一片雪亮。", },
	[183568] = {id=183568, zh_CN="奥黛特·月影重新出现在公众视野中。", },
	[183569] = {id=183569, zh_CN="她身着礼服，妆容精致，乌黑的长发一丝不苟地挽起。", },
	[183570] = {id=183570, zh_CN="奥黛特走上台，步履沉稳，眼神坚定如磐石。", },
	[183571] = {id=183571, zh_CN="她眉宇间凝结着一份沉重的歉意。", },
	[183572] = {id=183572, zh_CN="各位尊敬的客户、合作伙伴，以及所有关注月影商会的朋友们……", },
	[183573] = {id=183573, zh_CN="大家下午好。", },
	[183574] = {id=183574, zh_CN="面向镜头，深深鞠躬", },
	[183575] = {id=183575, zh_CN="首先，请允许我代表月影商会全体同仁……", },
	[183576] = {id=183576, zh_CN="向所有在此次恶性事件中受到困扰、不安的诸位，致以歉意！", },
	[183577] = {id=183577, zh_CN="近期，关于月影商会涉及赝品交易、欺诈客户的丑闻喧嚣尘上。", },
	[183578] = {id=183578, zh_CN="给各位带来了极大的困扰和损失，也严重损害了商会百年积累的声誉。", },
	[183579] = {id=183579, zh_CN="经过警方全力侦办，现已查明。", },
	[183580] = {id=183580, zh_CN="这一切的罪魁祸首，是商会内部以商会董事元老为首的部分高层人员。", },
	[183581] = {id=183581, zh_CN="他们长期利用职务之便，勾结外部势力。", },
	[183582] = {id=183582, zh_CN="进行星际走私、洗钱以及令人发指的以赝品替换真品的欺诈行为！", },
	[183583] = {id=183583, zh_CN="为掩盖其滔天罪行，他们构陷于我，妄图将整个商会拖入深渊！", },
	[183584] = {id=183584, zh_CN="对此，我表示最强烈的愤慨和谴责！", },
	[183585] = {id=183585, zh_CN="作为月影商会的会长，我，奥黛特·月影，难辞其咎！", },
	[183586] = {id=183586, zh_CN="是我在商会快速扩张、业务多元化的进程中，过于专注于开拓。", },
	[183587] = {id=183587, zh_CN="而疏忽了对元老院权力的有效制衡与监督！", },
	[183588] = {id=183588, zh_CN="是我的失察，才让这些隐藏多年的蛀虫有了可乘之机，最终酿成如此大祸！", },
	[183589] = {id=183589, zh_CN="这次风波，其根源在于我整顿商会、清除毒瘤的决心触动了他们的利益。", },
	[183590] = {id=183590, zh_CN="却不幸让所有信任、支持月影的你们，", },
	[183591] = {id=183591, zh_CN="无辜地卷入了这场风暴，承受了本不该有的恐慌和损失。", },
	[183592] = {id=183592, zh_CN="对此，我承担全部责任！我再次向所有人，致以最深的歉意！", },
	[183593] = {id=183593, zh_CN="为了弥补过失，重塑信任，月影商会即刻启动以下措施：", },
	[183594] = {id=183594, zh_CN="第一， 所有涉案赃物、查获的赝品，已全部无条件移交警方处理！", },
	[183595] = {id=183595, zh_CN="商会内部将进行最彻底的清查，绝不姑息任何关联人员！", },
	[183596] = {id=183596, zh_CN="第二，所有在月影商会拍卖会中成功竞拍并已支付保证金的会员……", },
	[183597] = {id=183597, zh_CN="商会将在三个工作日内，双倍返还您的保证金！", },
	[183598] = {id=183598, zh_CN="这是我们对您信任被辜负的最直接歉意！", },
	[183599] = {id=183599, zh_CN="第三，凡持有月影商会拍卖会购买物品交易凭证的客户……", },
	[183600] = {id=183600, zh_CN="如对所购物品真伪存有疑虑，", },
	[183601] = {id=183601, zh_CN="均可携带物品及完整凭证，前往警方指定的第三方鉴定点进行免费鉴定！", },
	[183602] = {id=183602, zh_CN="如经鉴定确认为此次事件涉及的赝品，警方将现场监督，", },
	[183603] = {id=183603, zh_CN="协助您用该赝品直接、无偿兑换回真品。", },
	[183604] = {id=183604, zh_CN="第四，月影商会将开启为期三个月的“月影安心购”特别活动！", },
	[183605] = {id=183605, zh_CN="活动期间，为所有新老客户提供免费的鉴宝服务！", },
	[183606] = {id=183606, zh_CN="我们将以更透明的操作流程、更严格的内部监管体系，", },
	[183607] = {id=183607, zh_CN="不惜一切代价，重塑月影商会的信誉基石！", },
	[183608] = {id=183608, zh_CN="再次谢谢大家的信任和等待。", },
	[183609] = {id=183609, zh_CN="发布会结束，汹涌的人潮和闪光灯逐渐散去。风波告一段落……", },
	[183610] = {id=183610, zh_CN="深夜，月影商会顶层，会长办公室厚重的木门紧闭。", },
	[183611] = {id=183611, zh_CN="室内只亮着书桌上那盏复古台灯，昏黄的光晕桌面上画出一个温暖的孤岛。", },
	[183612] = {id=183612, zh_CN="奥黛特深陷在高背椅中，她闭着眼，浓密的睫毛在眼下投出一小片阴影。", },
	[183613] = {id=183613, zh_CN="她卸去了发布会上的所有锋芒，只剩下深入骨髓的疲惫。", },
	[183614] = {id=183614, zh_CN="你轻轻敲了敲门，然后推门而入。", },
	[183615] = {id=183615, zh_CN="来了？坐吧。", },
	[183616] = {id=183616, zh_CN="发布会……你都看到了？", },
	[183617] = {id=183617, zh_CN="……嗯。对不起，奥黛特。在警局的时候，我……", },
	[183618] = {id=183618, zh_CN="不用道歉，%PlayerName。真的不用。", },
	[183619] = {id=183619, zh_CN="换做是我……也未必能比你做得更明智，更冷静。", },
	[183620] = {id=183620, zh_CN="更何况，说到底，我又一次利用了你。", },
	[183621] = {id=183621, zh_CN="其实我有能力将你推出这场风波的。", },
	[183622] = {id=183622, zh_CN="是我纵容他们将你卷入其中，让自己的棋局可以走下去。", },
	[183623] = {id=183623, zh_CN="她身体微微前倾，灯光照亮了她的脸。", },
	[183624] = {id=183624, zh_CN="那双总是锐利或带着算计的眼眸，此刻竟流露出一种近乎脆弱的坦诚。", },
	[183625] = {id=183625, zh_CN="叫你过来，是想亲口对你说两件事。第一，是谢谢。", },
	[183626] = {id=183626, zh_CN="谢谢你，最终……站在了真相这边。", },
	[183627] = {id=183627, zh_CN="谢谢你，帮我洗刷了这不白之冤。", },
	[183628] = {id=183628, zh_CN="你保住了亲人留给我的……这个沉重的基业。", },
	[183629] = {id=183629, zh_CN="无论过程如何，结果是你撕破了那张网。", },
	[183630] = {id=183630, zh_CN="这份情，我记下了。", },
	[183631] = {id=183631, zh_CN="第二，是抱歉。", },
	[183632] = {id=183632, zh_CN="很抱歉，把你拖进了月影这滩深不见底的浑水里。", },
	[183633] = {id=183633, zh_CN="我利用了你的身份。利用你的背景，你的话题度，你的信任。", },
	[183634] = {id=183634, zh_CN="甚至…… 你那恰如其分的怀疑与愤怒……", },
	[183635] = {id=183635, zh_CN="%PlayerName，我是个自私到极点的女人。", },
	[183636] = {id=183636, zh_CN="为了保住父亲的心血，我算计了很多人，包括那些董事，包括媒体……也包括你。", },
	[183637] = {id=183637, zh_CN="她的手指无意识地在桌面上轻轻敲击，目光落在你身上，也带着一丝……释然。", },
	[183638] = {id=183638, zh_CN="还记得我送你的那个小玩意儿吗？", },
	[183639] = {id=183639, zh_CN="情绪花种？那点人情债，在这次的风波里，算是彻底……两清了。", },
	[183640] = {id=183640, zh_CN="我们之间账，平了。", },
	[183641] = {id=183641, zh_CN="我们之间不用算这么清楚。", },
	[183642] = {id=183642, zh_CN="经历了这些，我们难道不算朋友吗？", },
	[183643] = {id=183643, zh_CN="朋友？", },
	[183644] = {id=183644, zh_CN="亲爱的，你这样重视感情，会再一次被我利用的。", },
	[183645] = {id=183645, zh_CN="我只是在想，我们之间……除了利益交换，还有其他吗？", },
	[183646] = {id=183646, zh_CN="我们为彼此做的一切，是不是也只是在计算价值？", },
	[183647] = {id=183647, zh_CN="你永远在衡量我够不够格成为你棋盘上的一颗棋子？", },
	[183648] = {id=183648, zh_CN="没错。", },
	[183649] = {id=183649, zh_CN="我是个商人。我的血液里流淌着对价值的本能评估。", },
	[183650] = {id=183650, zh_CN="我习惯给一切标价，包括人情、关系、甚至……信任。", },
	[183651] = {id=183651, zh_CN="最初接近你……", },
	[183652] = {id=183652, zh_CN="只因为你是“天外来客”。", },
	[183653] = {id=183653, zh_CN="你稀有，有价值，背景干净得像一张白纸，有太多可能性。", },
	[183654] = {id=183654, zh_CN="后来留你，用你，是因为你在一次次考验中证明了自己的能力、应变，还有……某种让我觉得‘可靠’的品质。", },
	[183655] = {id=183655, zh_CN="但这不代表我们没有“感情”，%PlayerName。", },
	[183656] = {id=183656, zh_CN="只是我对“感情”的理解，可能和常人不同。", },
	[183657] = {id=183657, zh_CN="在权力与金钱交织的漩涡中心，唯有利益交换的深度，才是最牢固的纽带。", },
	[183658] = {id=183658, zh_CN="她的身体微微前倾，拉近了与你的距离，声音低沉而充满说服力。", },
	[183659] = {id=183659, zh_CN="我们，%PlayerName，共同经历了这场风波。", },
	[183660] = {id=183660, zh_CN="我们之间有基于事实的信任。", },
	[183661] = {id=183661, zh_CN="有在危机中磨合出的默契。", },
	[183662] = {id=183662, zh_CN="甚至…… 有对彼此能力和处事风格的欣赏。", },
	[183663] = {id=183663, zh_CN="这些，都是实实在在的。它们建立在一次次成功的利益交换之上。", },
	[183664] = {id=183664, zh_CN="也因此比那些空泛的誓言更经得起考验。", },
	[183665] = {id=183665, zh_CN="如果非要把这种关系类比成“友情”……", },
	[183666] = {id=183666, zh_CN="那么，以我们之间“利益交换”的程度和深度来衡量——", },
	[183667] = {id=183667, zh_CN="我们算得上是……", },
	[183668] = {id=183668, zh_CN="过命的深交。", },
	[183669] = {id=183669, zh_CN="%PlayerName，你愿意接受这种定位吗？", },
	[183670] = {id=183670, zh_CN="……", },
	[183671] = {id=183671, zh_CN="当然， 如果你觉得这种说法太不近人情，无法接受……", },
	[183672] = {id=183672, zh_CN="这也没关系。我们的合作依然可以继续。", },
	[183673] = {id=183673, zh_CN="只是……我们之间的关系，也就到此为止了。不会再深入一步。", },
	[183674] = {id=183674, zh_CN="接受", },
	[183675] = {id=183675, zh_CN="过命的深交？", },
	[183676] = {id=183676, zh_CN="这个说法……真的很奥黛特。我接受了。", },
	[183677] = {id=183677, zh_CN="明智的选择，%PlayerName。", },
	[183678] = {id=183678, zh_CN="欢迎加入我的“核心圈”。", },
	[183679] = {id=183679, zh_CN="不接受", },
	[183680] = {id=183680, zh_CN="我……明白了。抱歉，奥黛特小姐。", },
	[183681] = {id=183681, zh_CN="我想……我们还是保持单纯的合作关系吧。", },
	[183682] = {id=183682, zh_CN="当然可以。尊重你的选择。", },
	[183683] = {id=183683, zh_CN="我们依然是……重要的合作伙伴。", },
	[183684] = {id=183684, zh_CN="期待你接下来的工作表现。", },
	[183685] = {id=183685, zh_CN="今日是月影商会的休息日，你带着心事，打开商会大门，来找奥黛特。", },
	[183686] = {id=183686, zh_CN="吧台里的奥黛特心情似乎格外放松。", },
	[183687] = {id=183687, zh_CN="瞥见你的到来，她递给一杯上佳的茶水，自己则慵懒地倚靠在吧台上。", },
	[183688] = {id=183688, zh_CN="凉风吹拂着她微卷的发丝，侧脸在吧台柔和的氛围灯下柔和又带着一丝疏离。", },
	[183689] = {id=183689, zh_CN="与她轻轻碰杯，目光落在奥黛特被灯光勾勒的迷人侧影上。", },
	[183690] = {id=183690, zh_CN="奥黛特……", },
	[183691] = {id=183691, zh_CN="嗯？", },
	[183692] = {id=183692, zh_CN="你觉得我怎么样？", },
	[183693] = {id=183693, zh_CN="业务在线，人也不错，可以深交。", },
	[183694] = {id=183694, zh_CN="那你……会喜欢我吗？", },
	[183695] = {id=183695, zh_CN="%PlayerName，我们认识……也不短了。", },
	[183696] = {id=183696, zh_CN="你见过我在谈判桌上如何把人逼到墙角，寸步不让……", },
	[183697] = {id=183697, zh_CN="也见过我在觥筹交错间如何与那些阿谀奉承的人虚与委蛇…… 甚至……我利用过你一次，两次……", },
	[183698] = {id=183698, zh_CN="为了维持商会的稳定，摆平麻烦，清除异端……", },
	[183699] = {id=183699, zh_CN="我默许将周身的一切人与物，将你，将自己都卷入风波之中。", },
	[183700] = {id=183700, zh_CN="%PlayerName，月影商会是我的王国，是我的战场……", },
	[183701] = {id=183701, zh_CN="奥黛特·月影也是我的牢笼。", },
	[183702] = {id=183702, zh_CN="或许我也有点喜欢你 ……", },
	[183703] = {id=183703, zh_CN="但我无法……无法给你那种，那种童话里描绘的，毫无保留的爱。", },
	[183704] = {id=183704, zh_CN="她放下杯，无声地向前走了一步，两人之间的距离瞬间变得暧昧，盯着你看", },
	[183705] = {id=183705, zh_CN="你明白吗？", },
	[183706] = {id=183706, zh_CN="我明白的。", },
	[183707] = {id=183707, zh_CN="但同时，作为一个活生生的人。", },
	[183708] = {id=183708, zh_CN="我也有我的欲望和情感需求，我也憧憬着，只对我个人的，欣赏的目光……", },
	[183709] = {id=183709, zh_CN="我似乎没有理由拒绝你。", },
	[183710] = {id=183710, zh_CN="真的吗？", },
	[183711] = {id=183711, zh_CN="别着急答应我。", },
	[183712] = {id=183712, zh_CN="如果你愿意的话，我们可以试试开放式的恋爱。", },
	[183713] = {id=183713, zh_CN="我们会成为彼此特殊的存在，分享信任，分享激情，分享一部分真实的自我……", },
	[183714] = {id=183714, zh_CN="但我们不互相束缚。我不会是你的挚爱唯一，你也不会是我的生命全部……", },
	[183715] = {id=183715, zh_CN="我们在各自的轨道上运行，背负各自的职责和秘密……", },
	[183716] = {id=183716, zh_CN="我们是两只波浪线，只在需要温暖、理解、或者纯粹欲望的时刻交汇。", },
	[183717] = {id=183717, zh_CN="你愿意接受这样的关系吗，%PlayerName。", },
	[183718] = {id=183718, zh_CN="她的手指轻轻抬起，似乎想触碰你的脸颊，却又在咫尺之遥停住。", },
	[183719] = {id=183719, zh_CN="她的目光扫过你，等待着你的答案。", },
	[183720] = {id=183720, zh_CN="接受", },
	[183721] = {id=183721, zh_CN="你沉默着盯着奥黛特的眼睛，似乎从她的眼睛里望见了紧张，脆弱……", },
	[183722] = {id=183722, zh_CN="奥黛特小姐，你总是把简单的问题复杂化。", },
	[183723] = {id=183723, zh_CN="我接受，接受这样的你，也接受如此的我们。", },
	[183724] = {id=183724, zh_CN="原因也很简单，我的心脏会因为你而加速。", },
	[183725] = {id=183725, zh_CN="她眼中那丝紧张如同冰雪消融，瞬间绽放出璀璨的光彩。", },
	[183726] = {id=183726, zh_CN="她主动上前，双手捧住你的脸，带着卸下重负的热情与主动，轻吻你的脸颊。", },
	[183727] = {id=183727, zh_CN="明智的选择……我亲爱的。", },
	[183728] = {id=183728, zh_CN="不接受", },
	[183729] = {id=183729, zh_CN="你的内心经历着剧烈的挣扎，", },
	[183730] = {id=183730, zh_CN="你理解奥黛特，甚至欣赏她的坦诚，", },
	[183731] = {id=183731, zh_CN="但对感情的认知，你和奥黛特存在着无法横跨的鸿沟。", },
	[183732] = {id=183732, zh_CN="奥黛特……我……我很抱歉。", },
	[183733] = {id=183733, zh_CN="我理解你的处境，真的。", },
	[183734] = {id=183734, zh_CN="但是……这样的关系，我……我无法接受。", },
	[183735] = {id=183735, zh_CN="我想要的……可能更多，也可能……更简单。", },
	[183736] = {id=183736, zh_CN="她眼中的期待骤然熄灭，一丝黯然在她眼底迅速掠过，她几乎同步地也后退半步，脸上的完美笑容又重新浮现。", },
	[183737] = {id=183737, zh_CN="很遗憾听到这个答案，但……我尊重你的选择。", },
	[183738] = {id=183738, zh_CN="我们依然是……重要的合作伙伴。", },
	[183739] = {id=183739, zh_CN="月影商会和我本人，都依旧珍视你的能力。", },
	[183740] = {id=183740, zh_CN="我们依然是……重要的合作伙伴。月影商会和我本人，都依旧珍视你的能力。", },
	[183741] = {id=183741, zh_CN="祝你有一个美丽的一天。", },
	[183742] = {id=183742, zh_CN="商务会议室中，空气凝重得几乎能拧出水来。巨大的长条谈判桌两侧，壁垒分明。", },
	[183743] = {id=183743, zh_CN="来自旅游著称的某星球代表团个个面红耳赤，领头的男人额头青筋暴起。", },
	[183744] = {id=183744, zh_CN="奥黛特坐在商会领头的主位上，而你拿着一沓文件坐在她的身后，奥黛特回头看向你，你朝她点头，走上前去。", },
	[183745] = {id=183745, zh_CN="你和奥黛特并肩坐在商会领头的主位上，奥黛特作为商会会长似乎对商讨结果不在意，一直是你在掌控全局。", },
	[183746] = {id=183746, zh_CN="将一份文件精准地推到对方面前，手指重重地点在关键条款上。", },
	[183747] = {id=183747, zh_CN="贵方在附加条款上对于贵方需要付出的服务模糊描述……", },
	[183748] = {id=183748, zh_CN="我们有充分的理由认为，在投资贵方开发旅游度假村的项目上，存在较大的舆情风险。", },
	[183749] = {id=183749, zh_CN="必须修改，明确界定服务内容和添加对客户的隐私保护明细。", },
	[183750] = {id=183750, zh_CN="否则，我方将视为贵方缺乏合作诚意，停止项目推进。", },
	[183751] = {id=183751, zh_CN="你这是鸡蛋里挑骨头！", },
	[183752] = {id=183752, zh_CN="奥黛特会长！ 您就是这么纵容属下的吗？", },
	[183753] = {id=183753, zh_CN="奥黛特会长！您就看着您的合伙人如此武断，不把您放在眼里？", },
	[183754] = {id=183754, zh_CN="咄咄逼人，毫无商业风度，这是对我们工作能力的侮辱！", },
	[183755] = {id=183755, zh_CN="奥黛特纤细的手指正正慢条斯理地摆弄着手中的茶杯，仿佛眼前激烈的争吵只是一场无关紧要的戏剧。", },
	[183756] = {id=183756, zh_CN="奥黛特缓缓抬起眼皮，端起那杯伯爵茶，送到唇边，轻轻吹了吹根本不存在的热气。", },
	[183757] = {id=183757, zh_CN="她笑不见底，维持着表面的和气，一双冰冷的眼眸投向对面。", },
	[183758] = {id=183758, zh_CN="他说的，就是我的意思。", },
	[183759] = {id=183759, zh_CN="而且，我觉得他说的……有错吗？", },
	[183760] = {id=183760, zh_CN="如果贵方连这点基本的契约精神和合作的诚意都没有。", },
	[183761] = {id=183761, zh_CN="那我看今天的谈判，可以到此为止了。", },
	[183762] = {id=183762, zh_CN="月影商会的耐心和时间，都很宝贵。", },
	[183763] = {id=183763, zh_CN="代表慌忙站起来，椅子腿在地上刮出刺耳的声音。", },
	[183764] = {id=183764, zh_CN="等等！奥黛特会长！请留步！有话好商量！", },
	[183765] = {id=183765, zh_CN="最终还是签订了合作协议，以月影商会大获全胜告终。", },
	[183766] = {id=183766, zh_CN="送走垂头丧气的合作方，你和奥黛特紧绷的弦骤然松弛。", },
	[183767] = {id=183767, zh_CN="厚重的门在两人身后关上……“咔哒”，门锁落下。", },
	[183768] = {id=183768, zh_CN="没给你任何反应的时间，她猛地转身，一把将你重重地推到门板上。", },
	[183769] = {id=183769, zh_CN="做的不错。", },
	[183770] = {id=183770, zh_CN="她手指带着不容抗拒的力道，迅速抵上你的唇。", },
	[183771] = {id=183771, zh_CN="奖励你一下。", },
	[183772] = {id=183772, zh_CN="奥黛特脸上那层冰霜瞬间消融殆尽。", },
	[183773] = {id=183773, zh_CN="取而代之的是一种狡黠、得意又带着灼热欲望的笑。", },
	[183774] = {id=183774, zh_CN="她松开手，低笑着，吻上你的唇角。", },
	[183775] = {id=183775, zh_CN="你睁大眼睛，不可置信。", },
	[183776] = {id=183776, zh_CN="你刚才的表情……真可爱。", },
	[183777] = {id=183777, zh_CN="晚上的庆功宴，你也要来。", },
	[183778] = {id=183778, zh_CN="不要迟到哦，小助理。", },
	[183779] = {id=183779, zh_CN="好。", },
	[183780] = {id=183780, zh_CN="铺着柔软地毯的走廊里，只剩下你和奥黛特，你俩相视一笑，无需言语。", },
	[183781] = {id=183781, zh_CN="高跟鞋踩在地毯上发出沉闷的轻响。她忽然停下脚步，转向你。", },
	[183782] = {id=183782, zh_CN="她抬起手，微凉的指尖轻轻擦过你的脸颊。", },
	[183783] = {id=183783, zh_CN="刚才……挺厉害的。", },
	[183784] = {id=183784, zh_CN="你想要什么奖励呢？", },
	[183785] = {id=183785, zh_CN="温热的气息喷洒在耳廓，你身躯一震。", },
	[183786] = {id=183786, zh_CN="一个足够记住今夜的吻……", },
	[183787] = {id=183787, zh_CN="话音未落！旁边一间小会议室的门“吱呀”一声被推开！", },
	[183788] = {id=183788, zh_CN="你睁大眼睛，怔愣在原地。", },
	[183789] = {id=183789, zh_CN="你们姿态亲昵，奥黛特毫无被撞破的尴尬或愠怒。", },
	[183790] = {id=183790, zh_CN="原本停留在你脸颊爱的手下滑，搂住了你，姿态亲昵，毫无被撞破的尴尬或愠怒。", },
	[183791] = {id=183791, zh_CN="慌什么？", },
	[183792] = {id=183792, zh_CN="你和奥黛特对视一眼，再望向走廊远处已经空无一人。", },
	[183793] = {id=183793, zh_CN="你站在原地，任由奥黛特帮你整理被她弄皱的领口。", },
	[183794] = {id=183794, zh_CN="你又算计我。", },
	[183795] = {id=183795, zh_CN="这下好了，不出半小时，整个月影商会都会知道商会会长和她的合伙人……", },
	[183796] = {id=183796, zh_CN="怕什么？谣言？让他们传去。", },
	[183797] = {id=183797, zh_CN="压低声音，红唇几乎要碰到你", },
	[183798] = {id=183798, zh_CN="会长和合伙人的“秘辛”，在谈判桌上……也是张不错的牌。", },
	[183799] = {id=183799, zh_CN="对手会更加忌惮，看不穿我们的底牌，也猜不透我们的关系深浅……", },
	[183800] = {id=183800, zh_CN="晚上庆功宴，别迟到了。", },
	[183801] = {id=183801, zh_CN="我的……合伙人。", },
	[183802] = {id=183802, zh_CN="好。", },
	[183803] = {id=183803, zh_CN="晚会上，衣香鬓影，觥筹交错，宴会正在高潮。", },
	[183804] = {id=183804, zh_CN="舒缓的爵士乐流淌在空气中……", },
	[183805] = {id=183805, zh_CN="奥黛特一袭曳地长裙，挽着你，在各色猜测，艳羡的目光中穿梭。", },
	[183806] = {id=183806, zh_CN="几轮必要的交际过后，你疲于应对打量的目光，拉着奥黛特藏在露台一处安静的角落。", },
	[183807] = {id=183807, zh_CN="奥黛特，你就打算一直这样？任由他们猜测、编排我们之间的关系？", },
	[183808] = {id=183808, zh_CN="像刚才那种场合…… 不打算给我个明确的“名分”？", },
	[183809] = {id=183809, zh_CN="比如……宴会搭档？", },
	[183810] = {id=183810, zh_CN="比如……伴侣？或者至少是宴会搭档？……总是带着各种含义的合伙人，听着怪别扭的。", },
	[183811] = {id=183811, zh_CN="奥黛特正对着露台玻璃幕墙，优雅地取下一边的钻石流苏耳环。", },
	[183812] = {id=183812, zh_CN="闻言，她动作一顿，没有立刻回答。", },
	[183813] = {id=183813, zh_CN="她缓缓转过身，一步步走近你。夜风吹拂着她的长发和裙摆。", },
	[183814] = {id=183814, zh_CN="她抬手，带着一种不容抗拒的温柔，抚上你的脸颊。", },
	[183815] = {id=183815, zh_CN="我们是什么关系，你和我心里清楚，这就够了。", },
	[183816] = {id=183816, zh_CN="伴侣这个身份是束缚，也是靶子。", },
	[183817] = {id=183817, zh_CN="贴上“奥黛特的伴侣”这个标签，意味着你将永远活在我的阴影下……", },
	[183818] = {id=183818, zh_CN="意味着你会成为所有想对付我、想取代我、想拉拢我的人的首要目标。", },
	[183819] = {id=183819, zh_CN="意味着你的一举一动都会被放在显微镜下审视、评判。", },
	[183820] = {id=183820, zh_CN="现在这样不好吗？", },
	[183821] = {id=183821, zh_CN="我们是彼此最信任的盟友，最默契的拍档，最……", },
	[183822] = {id=183822, zh_CN="……最契合的灵魂伴侣。", },
	[183823] = {id=183823, zh_CN="月影商会的会长，巧舌如簧，能言善辩，你深知是说不过她的。", },
	[183824] = {id=183824, zh_CN="无论这场关于“名分”的小小对抗结果如何……", },
	[183825] = {id=183825, zh_CN="你们都会在下一秒将这个插曲抛掷脑后，在她温柔又迷人的温存中……", },
	[183826] = {id=183826, zh_CN="沉溺于这个利益与感情交织，彼此暧昧又支撑对方的开放关系。", },
	[183827] = {id=183827, },
	[183828] = {id=183828, zh_CN="嘿，%PlayerName，有没有兴趣看看月影商会的期货？", },
	[183829] = {id=183829, zh_CN="优惠力度包你满意。", },
	[183830] = {id=183830, zh_CN="离开", },
	[183831] = {id=183831, zh_CN="回见", },
	[183832] = {id=183832, zh_CN="“宝物”鉴定", },
	[183833] = {id=183833, zh_CN="经济漩涡的涟漪", },
	[183834] = {id=183834, zh_CN="比感情更坚贞的捆绑", },
	[183835] = {id=183835, zh_CN="恋爱开放公式", },
	[183836] = {id=183836, zh_CN="办公室恋情日常", },
	[183837] = {id=183837, zh_CN="重返邀约", },
	[183838] = {id=183838, zh_CN="失窃风波", },
	[183839] = {id=183839, zh_CN="对商会充值优惠力度不满意吗？", },
	[183840] = {id=183840, zh_CN="要不然来看看这些呢，亲爱的。", },
	[183841] = {id=183841, zh_CN="这是……促进消费的设计吗？", },
	[183842] = {id=183842, zh_CN="哦，居然又丢了！！", },
	[183843] = {id=183843, },
	[183844] = {id=183844, zh_CN="嗨，%PlayerName。今天是来购买商品的，还是来和我聊聊天的？", },
	[183845] = {id=183845, zh_CN="失窃风波", },
	[183846] = {id=183846, zh_CN="或许，看看商会最近的新产品呢？", },
	[183847] = {id=183847, zh_CN="美丽又价廉的珠宝，只此一家哦。", },
	[183848] = {id=183848, zh_CN="堂堂月影商户的大小姐，怎么出来摆地摊货？", },
	[183849] = {id=183849, zh_CN="新产品的推广运营，我当然要亲自体验一番了。", },
	[183850] = {id=183850, zh_CN="亲爱的，坐在商会里，可是赚不来钱的。", },
	[183851] = {id=183851, zh_CN="这是……你展示新品紧俏的设计吗？", },
	[183852] = {id=183852, zh_CN="哦，居然又丢了！！", },
	[183853] = {id=183853, },
	[183854] = {id=183854, zh_CN="“又”？不见了……", },
	[183855] = {id=183855, },
	[183856] = {id=183856, zh_CN="哦天，还好你没走。", },
	[183857] = {id=183857, zh_CN="你可以帮我找找吗？我可以付给你报酬。", },
	[183858] = {id=183858, zh_CN="当然，会长大人。", },
	[183859] = {id=183859, },
	[183860] = {id=183860, zh_CN="在哪，在哪呢？要快点找到才行。", },
	[183861] = {id=183861, zh_CN="我帮你一起找吧，奥黛特会长。", },
	[183862] = {id=183862, zh_CN="真的嘛，那真是拜托你了。", },
	[183863] = {id=183863, },
	[183864] = {id=183864, zh_CN="在哪，在哪呢？要快点找到才行。", },
	[183865] = {id=183865, zh_CN="居然有能难住月影大小姐的事情吗？", },
	[183866] = {id=183866, zh_CN="哦，亲爱的，别打趣我了。", },
	[183867] = {id=183867, zh_CN="快来帮我找吊坠。", },
	[183868] = {id=183868, zh_CN="它又不见了。", },
	[183869] = {id=183869, },
	[183870] = {id=183870, zh_CN="你上一次见到它，是什么时候呢？", },
	[183871] = {id=183871, zh_CN="说起来也奇怪，虽然这周首饰丢了三次……", },
	[183872] = {id=183872, zh_CN="但每次过几天之后便会重新出现，位置还特别离谱。", },
	[183873] = {id=183873, },
	[183874] = {id=183874, zh_CN="既然如此，那就不用找啦。", },
	[183875] = {id=183875, zh_CN="反正不管它，很快就会出现的。", },
	[183876] = {id=183876, zh_CN="虽然是这个理。", },
	[183877] = {id=183877, zh_CN="但是我急需使用它。", },
	[183878] = {id=183878, },
	[183879] = {id=183879, zh_CN="真相只有一个", },
	[183880] = {id=183880, zh_CN="什么？", },
	[183881] = {id=183881, zh_CN="有人暗恋你！是变态鬼！", },
	[183882] = {id=183882, zh_CN="啊！我好害怕。", },
	[183883] = {id=183883, zh_CN="好了，%PlayerName，请你正经一点。", },
	[183884] = {id=183884, zh_CN="请不要再逗我开心了。", },
	[183885] = {id=183885, },
	[183886] = {id=183886, zh_CN="那么我就义无反顾地接下委托啦。", },
	[183887] = {id=183887, zh_CN="请问我的委托小姐，之前丢的首饰，都是在哪里找到的呢？", },
	[183888] = {id=183888, zh_CN="有时会从高处的窗台上掉下来……或者花坛的里面。", },
	[183889] = {id=183889, zh_CN="哪有人会把赃物藏在窗台上……", },
	[183890] = {id=183890, zh_CN="虽然人不会，但是……动物或许会，比如，猫。", },
	[183891] = {id=183891, },
	[183892] = {id=183892, zh_CN="麻烦你去帮我找一找吧。", },
	[183893] = {id=183893, zh_CN="事成之后，必有重谢。", },
	[183894] = {id=183894, zh_CN="鉴宝成功", },
	[183895] = {id=183895, zh_CN="记者A", },
	[183896] = {id=183896, zh_CN="记者B", },
	[183897] = {id=183897, zh_CN="记者C", },
	[183898] = {id=183898, zh_CN="广场中心警署", },
	[183899] = {id=183899, zh_CN="商会董事", },
	[183900] = {id=183900, zh_CN="警察", },
	[183901] = {id=183901, zh_CN="【信息】", },
	[183902] = {id=183902, zh_CN="代表", },
	[183903] = {id=183903, zh_CN="【“宝物”鉴定】", },
	[183904] = {id=183904, zh_CN="【重返邀约】", },
	[183905] = {id=183905, zh_CN="利益交换", },
	[183906] = {id=183906, zh_CN="绣球", },
	[183907] = {id=183907, zh_CN="绣球种子1", },
	[183908] = {id=183908, zh_CN="绣球种子2", },
	[183909] = {id=183909, zh_CN="绣球种子3", },
	[183910] = {id=183910, zh_CN="绣球花瓣1", },
	[183911] = {id=183911, zh_CN="绣球花瓣2", },
	[183912] = {id=183912, zh_CN="绣球花瓣3", },
	[183913] = {id=183913, zh_CN="绣球花瓣4", },
	[183914] = {id=183914, zh_CN="绣球花瓣5", },
	[183915] = {id=183915, zh_CN="绣球花瓣6", },
	[183916] = {id=183916, zh_CN="绣球花瓣7", },
	[183917] = {id=183917, zh_CN="绣球花瓣8", },
	[183918] = {id=183918, zh_CN="绣球种", },
	[183919] = {id=183919, zh_CN="侍从", },
	[183920] = {id=183920, zh_CN="与商会门口的侍从对话互动。", },
	[184000] = {id=184000, zh_CN="嘿，这位面生的先生，有没有兴趣看看月影商会的期货？", },
	[184001] = {id=184001, zh_CN="优惠力度包你满意。", },
	[184002] = {id=184002, zh_CN="失窃风波", },
	[184003] = {id=184003, },
	[184004] = {id=184004, zh_CN="对商会充值优惠力度不满意吗？", },
	[184005] = {id=184005, zh_CN="要不然来看看这些呢，亲爱的。", },
	[184006] = {id=184006, zh_CN="这是……促进消费的设计吗？", },
	[184007] = {id=184007, zh_CN="哦，居然又丢了！！", },
	[184008] = {id=184008, },
	[184009] = {id=184009, zh_CN="嗨，%PlayerName。今天是来购买商品的，还是来和我聊聊天的？", },
	[184010] = {id=184010, zh_CN="失窃风波", },
	[184011] = {id=184011, zh_CN="或许，看看商会最近的新产品呢？", },
	[184012] = {id=184012, zh_CN="美丽又价廉的珠宝，只此一家哦。", },
	[184013] = {id=184013, zh_CN="堂堂月影商户的大小姐，怎么出来摆地摊货？", },
	[184014] = {id=184014, zh_CN="新产品的推广运营，我当然要亲自体验一番了。", },
	[184015] = {id=184015, zh_CN="亲爱的，坐在商会里，可是赚不来钱的。", },
	[184016] = {id=184016, zh_CN="这是……你展示新品紧俏的设计吗？", },
	[184017] = {id=184017, zh_CN="哦，居然又丢了！！", },
	[184018] = {id=184018, },
	[184019] = {id=184019, zh_CN="“又”？不见了……", },
	[184020] = {id=184020, },
	[184021] = {id=184021, zh_CN="哦天，还好你没走。", },
	[184022] = {id=184022, zh_CN="你可以帮我找找吗？我可以付给你报酬。", },
	[184023] = {id=184023, zh_CN="当然，会长大人。", },
	[184024] = {id=184024, },
	[184025] = {id=184025, zh_CN="在哪，在哪呢？要快点找到才行。", },
	[184026] = {id=184026, zh_CN="我帮你一起找吧，奥黛特会长。", },
	[184027] = {id=184027, zh_CN="真的嘛，那真是拜托你了。", },
	[184028] = {id=184028, },
	[184029] = {id=184029, zh_CN="在哪，在哪呢？要快点找到才行。", },
	[184030] = {id=184030, zh_CN="居然有能难住月影大小姐的事情吗？", },
	[184031] = {id=184031, zh_CN="哦，亲爱的，别打趣我了。", },
	[184032] = {id=184032, zh_CN="快来帮我找吊坠。", },
	[184033] = {id=184033, zh_CN="它又不见了。", },
	[184034] = {id=184034, },
	[184035] = {id=184035, zh_CN="你上一次见到它，是什么时候呢？", },
	[184036] = {id=184036, zh_CN="说起来也奇怪，虽然这周首饰丢了三次……", },
	[184037] = {id=184037, zh_CN="但每次过几天之后便会重新出现，位置还特别离谱。", },
	[184038] = {id=184038, },
	[184039] = {id=184039, zh_CN="既然如此，那就不用找啦。", },
	[184040] = {id=184040, zh_CN="反正不管它，很快就会出现的。", },
	[184041] = {id=184041, zh_CN="虽然是这个理。", },
	[184042] = {id=184042, zh_CN="但是我急需使用它。", },
	[184043] = {id=184043, },
	[184044] = {id=184044, zh_CN="真相只有一个", },
	[184045] = {id=184045, zh_CN="什么？", },
	[184046] = {id=184046, zh_CN="有人暗恋你！是变态鬼！", },
	[184047] = {id=184047, zh_CN="啊！我好害怕。", },
	[184048] = {id=184048, zh_CN="好了，%PlayerName，请你正经一点。", },
	[184049] = {id=184049, zh_CN="请不要再逗我开心了。", },
	[184050] = {id=184050, },
	[184051] = {id=184051, zh_CN="那么我就义无反顾地接下委托啦。", },
	[184052] = {id=184052, zh_CN="请问我的委托小姐，之前丢的首饰，都是在哪里找到的呢？", },
	[184053] = {id=184053, zh_CN="有时会从高处的窗台上掉下来……或者花坛的里面。", },
	[184054] = {id=184054, zh_CN="哪有人会把赃物藏在窗台上……", },
	[184055] = {id=184055, zh_CN="虽然人不会，但是……动物或许会，比如，猫。", },
	[184056] = {id=184056, },
	[184057] = {id=184057, zh_CN="麻烦你去帮我找一找吧。", },
	[184058] = {id=184058, zh_CN="事成之后，必有重谢。", },
	[184059] = {id=184059, },
	[184060] = {id=184060, zh_CN="城堡喷泉广场上，你打着手电，扫视过广场上下左右的各个边角。", },
	[184061] = {id=184061, zh_CN="忽然！一条黑影从你的身后窜出，飞速融入烛火灯下的阴影中。", },
	[184062] = {id=184062, zh_CN="你手电朝黑影消失的地方照去，一团闪光突然吸引你的注意。", },
	[184063] = {id=184063, },
	[184064] = {id=184064, zh_CN="这是……", },
	[184065] = {id=184065, zh_CN="这是……我的手链？！什么时候碰掉的？", },
	[184066] = {id=184066, zh_CN="你正要蹲下身来捡起手链……", },
	[184067] = {id=184067, zh_CN="黑暗中，玛瑙般的瞳孔翻出萤火般的紫幽光……", },
	[184068] = {id=184068, },
	[184069] = {id=184069, zh_CN="喵？", },
	[184070] = {id=184070, zh_CN="……", },
	[184071] = {id=184071, },
	[184072] = {id=184072, zh_CN="嘛一克！", },
	[184073] = {id=184073, },
	[184074] = {id=184074, zh_CN="原来是猫啊。", },
	[184075] = {id=184075, zh_CN="喵嗷？", },
	[184076] = {id=184076, zh_CN="嘶——！", },
	[184077] = {id=184077, zh_CN="（翻译：你才是流浪猫，芝麻糊家族是万万年前就住在古堡的贵族猫！）", },
	[184078] = {id=184078, zh_CN="真是失礼，请问这位小姐尊姓芳名？", },
	[184079] = {id=184079, zh_CN="喵！（翻译：芝麻·古堡主·糊。）", },
	[184080] = {id=184080, zh_CN="这是我的小鱼干干粮，算是见面礼吧。", },
	[184081] = {id=184081, zh_CN="你用手背将小鱼干拱到芝麻糊面前。", },
	[184082] = {id=184082, zh_CN="喵呜—（翻译：比人类上道的小弟。）", },
	[184083] = {id=184083, },
	[184084] = {id=184084, zh_CN="咪咪？", },
	[184085] = {id=184085, zh_CN="芝麻糊前身匍匐，耳朵高高竖起，尾巴扫地，目不转睛地凝视着你。", },
	[184086] = {id=184086, zh_CN="喵~~~嗷！", },
	[184087] = {id=184087, zh_CN="啊！", },
	[184088] = {id=184088, },
	[184089] = {id=184089, zh_CN="小可怜要和我回家吗？", },
	[184090] = {id=184090, zh_CN="喵嗷？喵！", },
	[184091] = {id=184091, zh_CN="它身体后倾，尾巴翘起，在你面前转了个圈，尾巴轻轻扫过你的指尖", },
	[184092] = {id=184092, zh_CN="触须下垂，芝麻糊满意嗅了嗅自己蹭下的气味后，优雅信步回阴影中。", },
	[184093] = {id=184093, },
	[184094] = {id=184094, zh_CN="这么漂亮的小流浪，包“手慢无”。", },
	[184095] = {id=184095, zh_CN="嘶—哈！！", },
	[184096] = {id=184096, zh_CN="芝麻糊并没有立刻离开，那双紫瞳迅速收缩，雷达耳左右转着，尾巴垂在烛台下。", },
	[184097] = {id=184097, zh_CN="喵！……喵喵喵呜！！", },
	[184098] = {id=184098, },
	[184099] = {id=184099, zh_CN="还好平时喂光灵，随身带了小鱼干。", },
	[184100] = {id=184100, zh_CN="你将小鱼干放在地上，一步步朝后退去。", },
	[184101] = {id=184101, zh_CN="吃吧，快吃吧。", },
	[184102] = {id=184102, zh_CN="芝麻糊瞳孔放大，嘴巴微张，叼着小鱼干便走了。", },
	[184103] = {id=184103, zh_CN="只留下玩家在原地望着消失的小猫。", },
	[184104] = {id=184104, zh_CN="那只黑云般的尾巴紧实高翘，微微卷曲……", },
	[184105] = {id=184105, zh_CN="尾巴晃晃的，昭告着好心情，像得胜的凯旋将军。", },
	[184106] = {id=184106, zh_CN="真是薄情的猫。", },
	[184107] = {id=184107, zh_CN="不远处……，猫的黑影似乎停下脚步，耳朵左右转动了几圈……", },
	[184108] = {id=184108, zh_CN="它将小鱼干放在尾巴尖尖上，细细品尝起小鱼干。", },
	[184109] = {id=184109, zh_CN="呼噜噜……（翻译：喵嗷~算你识相。）", },
	[184110] = {id=184110, },
	[184111] = {id=184111, zh_CN="它一跃而起，嘴巴微张着在你的周围转圈。", },
	[184112] = {id=184112, zh_CN="嗨~", },
	[184113] = {id=184113, zh_CN="喵嗷？喵——", },
	[184114] = {id=184114, zh_CN="芝麻糊眯着眼伸个懒腰，踏着猫步，神秘兮兮地转动耳朵。", },
	[184115] = {id=184115, zh_CN="它悄然转到你的身侧。一抓将你扑倒，张嘴咬上你的脑袋。", },
	[184116] = {id=184116, zh_CN="啊！", },
	[184117] = {id=184117, zh_CN="它触感不对，诧异地松开嘴。", },
	[184118] = {id=184118, zh_CN="喵嗷？（翻译：没有变成小鱼干的小鱼干？）", },
	[184119] = {id=184119, zh_CN="真是失礼，我是巴别族。和吃的鱼有很大区别的好不好？", },
	[184120] = {id=184120, zh_CN="喵~（翻译：鱼干预制品也不错嘛！）", },
	[184121] = {id=184121, },
	[184122] = {id=184122, zh_CN="跑得真快！", },
	[184123] = {id=184123, zh_CN="对了！", },
	[184124] = {id=184124, zh_CN="说不定芝麻糊有关于吊坠的线索。", },
	[184125] = {id=184125, },
	[184126] = {id=184126, zh_CN="你凭着印象，朝猫消失的地方走去。", },
	[184127] = {id=184127, zh_CN="倏然，一处油叽叽的脚印在手电的照耀下格外闪耀。", },
	[184128] = {id=184128, zh_CN="你附身观察这串小小的梅花脚印——", },
	[184129] = {id=184129, zh_CN="脚印顺着楼梯", },
	[184130] = {id=184130, zh_CN="一路延伸到鸭湖城堡深处", },
	[184131] = {id=184131, zh_CN="要找到你了，芝麻糊", },
	[184132] = {id=184132, },
	[184133] = {id=184133, zh_CN="芝麻糊躲在哪里了呢……", },
	[184134] = {id=184134, },
	[184135] = {id=184135, zh_CN="找到你了！", },
	[184136] = {id=184136, zh_CN="你在鸭湖城堡的角落找到了芝麻糊，它正揣着小爪，母鸡蹲在软垫上。", },
	[184137] = {id=184137, zh_CN="一只乌黑的尾巴随着微风晃着。", },
	[184138] = {id=184138, zh_CN="阳光照过，如同藏色的画。", },
	[184139] = {id=184139, zh_CN="那尾巴尖尖还勾着闪闪发光的吊坠——", },
	[184140] = {id=184140, zh_CN="是奥黛特丢的吊坠！", },
	[184141] = {id=184141, zh_CN="吊坠果然是你藏的！", },
	[184142] = {id=184142, zh_CN="这次不会让你跑了！", },
	[184143] = {id=184143, zh_CN="芝麻糊灵巧地尾巴勾起，正巧和你的手指擦肩而过。", },
	[184144] = {id=184144, zh_CN="它后爪着地，立起身体，假装舔爪。", },
	[184145] = {id=184145, zh_CN="芝麻糊粉嫩肉垫若隐若现，格外扰人", },
	[184146] = {id=184146, zh_CN="喵~（#￥%芝麻糊￥%）", },
	[184147] = {id=184147, zh_CN="突如其来的翻译如开窍般在你脑中绽开，芝麻糊在说……", },
	[184148] = {id=184148, },
	[184149] = {id=184149, zh_CN="“芝麻糊可是古堡贵族猫出身。”", },
	[184150] = {id=184150, zh_CN="好像不是……似乎缺少了什么重要元素，是什么呢？", },
	[184151] = {id=184151, },
	[184152] = {id=184152, zh_CN="“芝麻糊也是平民能摸到的？”", },
	[184153] = {id=184153, zh_CN="看着头顶蔑视的芝麻糊，好像很贴切……", },
	[184154] = {id=184154, },
	[184155] = {id=184155, zh_CN="“这是芝麻糊的战利品！”", },
	[184156] = {id=184156, zh_CN="简洁又正确，这就是芝麻糊想说的！竖起喵爪点赞！", },
	[184157] = {id=184157, zh_CN="（喵语言学习＋2）", },
	[184158] = {id=184158, },
	[184159] = {id=184159, zh_CN="芝麻糊将吊坠藏在身后，前爪踩了踩软垫。", },
	[184160] = {id=184160, zh_CN="喵……喵喵……喵喵喵……喵喵喵喵（翻译：整座古堡#$%$贵族^&*喵）", },
	[184161] = {id=184161, zh_CN="芝麻糊喋喋不休地叫着，好似在和你争辩什么，你猜芝麻糊要说的事情是……", },
	[184162] = {id=184162, },
	[184163] = {id=184163, zh_CN="关于吊坠", },
	[184164] = {id=184164, zh_CN="“所有人都拜倒在古堡喵喵家族脚下，何况是这吊坠？”", },
	[184165] = {id=184165, zh_CN="贴合题干，但比起当个翻译还差点。", },
	[184166] = {id=184166, },
	[184167] = {id=184167, zh_CN="关于尊贵的身份", },
	[184168] = {id=184168, zh_CN="“这里的人和物也是属于尊贵的古堡主殿下，当然也包括你。”", },
	[184169] = {id=184169, zh_CN="芝麻糊都想要应聘你当它的御用翻译官了呢。", },
	[184170] = {id=184170, },
	[184171] = {id=184171, zh_CN="关于你", },
	[184172] = {id=184172, zh_CN="“可怜的两脚兽，当你踏入这里，就属于喵喵殿下了。”", },
	[184173] = {id=184173, zh_CN="似乎是只霸总喵喵呢，但算你及格吧。", },
	[184174] = {id=184174, },
	[184175] = {id=184175, zh_CN="望着有些得意忘形的芝麻糊，你决定……", },
	[184176] = {id=184176, },
	[184177] = {id=184177, zh_CN="乘胜追击", },
	[184178] = {id=184178, zh_CN="尊敬的喵喵殿下，要不要在下给您梳毛呢？", },
	[184179] = {id=184179, zh_CN="它半信半疑地靠近，尾巴慢慢前后摆动着，侧身观察着你。", },
	[184180] = {id=184180, zh_CN="你拿出梳子为芝麻糊梳毛，黑色的背毛吸光吸热，暖洋洋的，触感似融化的奶油", },
	[184181] = {id=184181, },
	[184182] = {id=184182, zh_CN="喵喵喵，（翻译：就是这里~）", },
	[184183] = {id=184183, zh_CN="喵~（翻译：还凑合吧。）", },
	[184184] = {id=184184, zh_CN="弄疼我了，可恶的家伙！", },
	[184185] = {id=184185, },
	[184186] = {id=184186, zh_CN="芝麻糊的呼噜声渐响，尾巴垂落，吊坠掉在你的手中。", },
	[184187] = {id=184187, zh_CN="呼噜噜噜噜~（翻译：芝麻糊可不能被狡猾的手缠住，唔！好舒服~）", },
	[184188] = {id=184188, zh_CN="喵呜~（翻译：这里也要摸摸~）", },
	[184189] = {id=184189, zh_CN="喵喵喵呜~（翻译：没想到你这个小蛋糕还挺厉害的嘛。）", },
	[184190] = {id=184190, zh_CN="喵喵喵呜~（翻译：没想到你这个小猫咪还挺厉害的嘛。）", },
	[184191] = {id=184191, zh_CN="喵喵喵呜~（翻译：没想到你这个汪小弟还挺厉害的嘛。）", },
	[184192] = {id=184192, zh_CN="喵喵喵呜~（翻译：没想到你这个大家伙还挺厉害的嘛。）", },
	[184193] = {id=184193, zh_CN="喵喵喵呜~（翻译：没想到你这个鱼干预制品还挺厉害的嘛。）", },
	[184194] = {id=184194, },
	[184195] = {id=184195, zh_CN="芝麻糊抓挠你的手背，叼走了梳子。", },
	[184196] = {id=184196, zh_CN="喵呜！（翻译：可恶的狡猾鬼！再也不信你了。）", },
	[184197] = {id=184197, zh_CN="混乱中，吊坠因动作过大而从芝麻糊尾巴上滑落，你手疾眼快地拽住，避免了吊坠碎成无数碎片的“悲剧”。", },
	[184198] = {id=184198, zh_CN="而罪魁祸首早早就攀上城墙护栏上的“王座”，冷眼旁观。", },
	[184199] = {id=184199, },
	[184200] = {id=184200, zh_CN="趁火打劫", },
	[184201] = {id=184201, zh_CN="还给我！", },
	[184202] = {id=184202, zh_CN="芝麻糊挥起尾巴，吊坠顺着惯性抛出一个漂亮的弧度。", },
	[184203] = {id=184203, zh_CN="吊坠落在芝麻糊脖颈上，芝麻糊竖起的紫瞳凝视着你。", },
	[184204] = {id=184204, zh_CN="黑色皮草真是太适合展示珠宝了。", },
	[184205] = {id=184205, zh_CN="它烦躁地晃晃尾巴，撅起屁股，重新躲藏起来。", },
	[184206] = {id=184206, },
	[184207] = {id=184207, zh_CN="不小心把芝麻糊惹生气了，再次找到躲藏的芝麻糊，和它好好相处。", },
	[184208] = {id=184208, },
	[184209] = {id=184209, zh_CN="这次可不能莽撞了。", },
	[184210] = {id=184210, zh_CN="尊敬的喵喵殿下，要不要在下给您梳毛呢？", },
	[184211] = {id=184211, zh_CN="喵？（翻译：半信半疑地靠近，尾巴慢慢前后摆动着，侧身观察着你）", },
	[184212] = {id=184212, zh_CN="你拿出梳子为芝麻糊梳，黑色的背毛吸光吸热，暖洋洋的，触感似融化的奶油。", },
	[184213] = {id=184213, },
	[184214] = {id=184214, zh_CN="（扒拉你的手不许走）喵喵喵，（翻译：就是这里~）", },
	[184215] = {id=184215, zh_CN="喵~（翻译：还凑合吧。）", },
	[184216] = {id=184216, zh_CN="弄疼我了，可恶的家伙！", },
	[184217] = {id=184217, },
	[184218] = {id=184218, zh_CN="芝麻糊的呼噜声渐响，尾巴垂落，吊坠掉在你的手中。", },
	[184219] = {id=184219, zh_CN="呼噜噜噜噜~（翻译：芝麻糊可不能被狡猾的手缠住，唔！好舒服~）", },
	[184220] = {id=184220, zh_CN="（不小心翻出肚皮）喵呜~（翻译：这里也要摸摸~）", },
	[184221] = {id=184221, zh_CN="喵喵喵呜~（翻译：没想到你这个小蛋糕还挺厉害的嘛。）", },
	[184222] = {id=184222, zh_CN="喵喵喵呜~（翻译：没想到你这个小猫咪还挺厉害的嘛。）", },
	[184223] = {id=184223, zh_CN="喵喵喵呜~（翻译：没想到你这个汪小弟还挺厉害的嘛。）", },
	[184224] = {id=184224, zh_CN="喵喵喵呜~（翻译：没想到你这个大家伙还挺厉害的嘛。）", },
	[184225] = {id=184225, zh_CN="喵喵喵呜~（翻译：没想到你这个鱼干预制品还挺厉害的嘛。）", },
	[184226] = {id=184226, },
	[184227] = {id=184227, zh_CN="芝麻糊抓挠你的手背，叼走了梳子。", },
	[184228] = {id=184228, zh_CN="喵呜！（翻译：可恶的狡猾鬼！再也不信你了。）", },
	[184229] = {id=184229, zh_CN="混乱中，吊坠因动作过大而从芝麻糊尾巴上滑落，你手疾眼快地拽住，避免了吊坠碎成无数碎片的“悲剧”。", },
	[184230] = {id=184230, zh_CN="而罪魁祸首早早就攀上城墙护栏上的“王座”，冷眼旁观。", },
	[184231] = {id=184231, },
	[184232] = {id=184232, zh_CN="飘扬的旗帜吹得作响，芝麻糊瑟缩了一下，从城墙围栏上跳下。", },
	[184233] = {id=184233, zh_CN="芝麻糊来到你的面前，用身体蹭着你的裤腿。", },
	[184234] = {id=184234, zh_CN="喵喵，喵~（%……&%快跟我走~）", },
	[184235] = {id=184235, zh_CN="芝麻糊的语气听起来有些恳切，你猜芝麻糊要……", },
	[184236] = {id=184236, },
	[184237] = {id=184237, zh_CN="想求你办事", },
	[184238] = {id=184238, zh_CN="“求求你了，快跟我走吧~”", },
	[184239] = {id=184239, zh_CN="虽然意思差不多，但好像并不是芝麻糊会有的语气呢，难道你有看破心灵的能力~", },
	[184240] = {id=184240, },
	[184241] = {id=184241, zh_CN="雇佣你当管家", },
	[184242] = {id=184242, zh_CN="“本王任命你为管家大使，快跟我走~”", },
	[184243] = {id=184243, zh_CN="这么上道的人类，芝麻糊最喜欢了，留下来伺候我吧。", },
	[184244] = {id=184244, },
	[184245] = {id=184245, zh_CN="告诉你一个秘密", },
	[184246] = {id=184246, zh_CN="“我要告诉你一个秘密，快来！”", },
	[184247] = {id=184247, zh_CN="芝麻糊向一楼喷泉走去，你有些担心，紧随其后。", },
	[184248] = {id=184248, },
	[184249] = {id=184249, zh_CN="你跟在芝麻糊的身后，随着它的脚步回到一楼喷泉后。", },
	[184250] = {id=184250, zh_CN="芝麻糊在城墙下的座椅旁停下脚步，它跳上座椅，将尾巴落在你的手上。", },
	[184251] = {id=184251, zh_CN="喵喵喵！！！", },
	[184252] = {id=184252, zh_CN="芝麻糊的语气急促，你猜他在说……", },
	[184253] = {id=184253, },
	[184254] = {id=184254, zh_CN="“有眼力见点，快来帮帮我！”", },
	[184255] = {id=184255, zh_CN="可爱咪咪奶凶奶凶的。", },
	[184256] = {id=184256, zh_CN="（喵语言学习＋2）", },
	[184257] = {id=184257, },
	[184258] = {id=184258, zh_CN="“给我戴上吊坠，快点！”", },
	[184259] = {id=184259, zh_CN="听语气是非常急迫的需求呢，好心的人类，帮帮它吧。", },
	[184260] = {id=184260, zh_CN="（喵语言学习＋2）", },
	[184261] = {id=184261, },
	[184262] = {id=184262, zh_CN="“快来摸摸我！”", },
	[184263] = {id=184263, zh_CN="可怜的小猫咪，本人的胸膛给咪靠。", },
	[184264] = {id=184264, zh_CN="（喵语言学习＋1）", },
	[184265] = {id=184265, },
	[184266] = {id=184266, zh_CN="你用手拨开尾巴密黑的尾毛，尾巴根的一处发炎伤口露出。", },
	[184267] = {id=184267, zh_CN="你是想要我帮你清理包扎伤口吗？", },
	[184268] = {id=184268, zh_CN="喵！（翻译：嗯！）", },
	[184269] = {id=184269, zh_CN="你坐到芝麻糊身边，小心避开伤口查看。", },
	[184270] = {id=184270, zh_CN="那你知道医药箱在哪吗？", },
	[184271] = {id=184271, zh_CN="它灵巧地变成一滩“猫水”流入地面与木椅的缝隙，再出来的时候，嘴里叼着一个医药箱。", },
	[184272] = {id=184272, zh_CN="你接过医疗箱打开，里面的药水绷带撒落一箱。", },
	[184273] = {id=184273, zh_CN="你看着瑟缩的芝麻糊，心生不忍。", },
	[184274] = {id=184274, },
	[184275] = {id=184275, zh_CN="手帕垫伤口处", },
	[184276] = {id=184276, zh_CN="芝麻糊伸着懒腰，很惬意地蹲在太阳照到的椅背上。", },
	[184277] = {id=184277, zh_CN="喵喵~喵~（翻译：丝绸手帕果然适配芝麻糊的气质。）", },
	[184278] = {id=184278, },
	[184279] = {id=184279, zh_CN="纱布包伤口", },
	[184280] = {id=184280, zh_CN="芝麻糊嫌弃推开纱布。", },
	[184281] = {id=184281, zh_CN="喵！？！（翻译：包得这么丑，都压倒芝麻糊的毛了！）", },
	[184282] = {id=184282, },
	[184283] = {id=184283, zh_CN="你仔细检查芝麻糊的伤口后，从医药箱中拿出剃毛刀。", },
	[184284] = {id=184284, zh_CN="喵喵？（翻译：你要用它给我的伤口报仇吗？）", },
	[184285] = {id=184285, zh_CN="你的伤口发炎了，需要把伤口附近的尾毛剃掉。", },
	[184286] = {id=184286, zh_CN="芝麻糊忍痛将尾巴踩在脚下藏起来。", },
	[184287] = {id=184287, zh_CN="嗷呜——！！！（翻译：不可以不可以不可以，芝麻糊不要变丑八怪！）", },
	[184288] = {id=184288, zh_CN="我保证让你漂漂亮亮的，还是古堡第一美猫仔。", },
	[184289] = {id=184289, zh_CN="我 ……我要做第一美喵喵。", },
	[184290] = {id=184290, zh_CN="嗯嗯。保证让你满意。", },
	[184291] = {id=184291, zh_CN="芝麻糊尾巴在空中一晃一晃，看起来纠结了许久，才狠心得闭上眼，将尾巴放在你的手上。", },
	[184292] = {id=184292, zh_CN="它不再看自己的尾巴，撇开脸，望天望地。", },
	[184293] = {id=184293, zh_CN="你打开剃毛刀，滋滋作响的声音让芝麻糊双爪包头，将耳朵塞入脸颊毛中。", },
	[184294] = {id=184294, zh_CN="你需要……", },
	[184295] = {id=184295, },
	[184296] = {id=184296, zh_CN="调低转速", },
	[184297] = {id=184297, zh_CN="你察觉到芝麻糊颤抖的身躯，调低了剃毛刀的转速。", },
	[184298] = {id=184298, zh_CN="滋滋的机械声变小", },
	[184299] = {id=184299, zh_CN="芝麻糊的身体也缓缓伸展开来，偷偷地探出眼睛窥视着你的动作。", },
	[184300] = {id=184300, zh_CN="你最小范围地剃掉尾毛，从医药箱中拿出生理盐水，滴在手心。", },
	[184301] = {id=184301, zh_CN="盐水顺着缓冲滑过伤口，带走了灰尘。", },
	[184302] = {id=184302, zh_CN="喵~（翻译：很细心，喜欢……）", },
	[184303] = {id=184303, },
	[184304] = {id=184304, zh_CN="清理伤口", },
	[184305] = {id=184305, zh_CN="你快速清理完伤口。", },
	[184306] = {id=184306, zh_CN="剃毛刀的滋滋声消失——", },
	[184307] = {id=184307, zh_CN="你从医药箱中拿出生理盐水小心地滴在手心。", },
	[184308] = {id=184308, zh_CN="盐水顺着缓冲轻滑过伤口，带走了灰尘。", },
	[184309] = {id=184309, zh_CN="喵。（翻译：还挺专业的嘛。）", },
	[184310] = {id=184310, },
	[184311] = {id=184311, zh_CN="碘伏消毒", },
	[184312] = {id=184312, zh_CN="顺序好像不太对，再想想。", },
	[184313] = {id=184313, },
	[184314] = {id=184314, zh_CN="好啦！", },
	[184315] = {id=184315, zh_CN="芝麻糊站起身来，回头看自己的尾巴根，秃秃的肉肤对比浓黑的尾毛格外突兀。", },
	[184316] = {id=184316, zh_CN="你掏出漂亮的丝巾，遮住纱布。", },
	[184317] = {id=184317, zh_CN="这样就看不出来了。", },
	[184318] = {id=184318, zh_CN="你打算给芝麻糊扎个……", },
	[184319] = {id=184319, },
	[184320] = {id=184320, zh_CN="蝴蝶结", },
	[184321] = {id=184321, zh_CN="手指翻飞，一个蝴蝶结就初具雏形了。", },
	[184322] = {id=184322, zh_CN="芝麻糊惊喜地盯着蝴蝶结，它的爪子痒痒的，总觉得什么基因苏醒了。", },
	[184323] = {id=184323, zh_CN="喵！", },
	[184324] = {id=184324, zh_CN="喵~~~", },
	[184325] = {id=184325, },
	[184326] = {id=184326, zh_CN="平结", },
	[184327] = {id=184327, zh_CN="手指翻飞，一个平结就初具雏形了。", },
	[184328] = {id=184328, zh_CN="芝麻糊惊喜地盯着平结，尾巴在空中炫耀似的甩来甩去", },
	[184329] = {id=184329, zh_CN="平结的活扣顺着惯性，缓缓松开，最后化作空中的一条丝带，落在芝麻糊的背上。", },
	[184330] = {id=184330, zh_CN="喵？", },
	[184331] = {id=184331, },
	[184332] = {id=184332, zh_CN="蔷薇结", },
	[184333] = {id=184333, zh_CN="手指翻飞，一个蔷薇结就初具雏形了。", },
	[184334] = {id=184334, zh_CN="芝麻糊惊喜地盯着蔷薇结，它的爪子痒痒的，总觉得什么基因苏醒了。", },
	[184335] = {id=184335, zh_CN="喵！", },
	[184336] = {id=184336, zh_CN="蔷薇结随着跳跃腾飞的尾巴在空中滑动处一串“花影”。", },
	[184337] = {id=184337, zh_CN="喵喵喵～～", },
	[184338] = {id=184338, zh_CN="疗伤告一段落，你准备带着芝麻糊去给奥黛特还首饰。", },
	[184339] = {id=184339, },
	[184340] = {id=184340, zh_CN="亲爱的%PlayerName，谢谢你给我找到吊坠。", },
	[184341] = {id=184341, zh_CN="这是你的报酬。", },
	[184342] = {id=184342, zh_CN="当然，也谢谢你小猫咪。", },
	[184343] = {id=184343, zh_CN="这是你的报酬。", },
	[184344] = {id=184344, zh_CN="一切尘埃落定后，芝麻糊拽着你的裤脚，要带你去商会台阶处。", },
	[184345] = {id=184345, },
	[184346] = {id=184346, zh_CN="咕噜……喵！", },
	[184347] = {id=184347, zh_CN="芝麻糊名叫芝麻·古堡主·糊。", },
	[184348] = {id=184348, zh_CN="什么，你居然不是小猫灵吗？", },
	[184349] = {id=184349, zh_CN="蠢货！", },
	[184350] = {id=184350, zh_CN="收下芝麻糊的信物吧！", },
	[184351] = {id=184351, zh_CN="从此，你就是芝麻糊喵的忠实奴仆。", },
	[184352] = {id=184352, zh_CN="这是……你的毛？", },
	[184353] = {id=184353, },
	[184354] = {id=184354, zh_CN="我会珍藏的！", },
	[184355] = {id=184355, zh_CN="喵喵~（翻译：算你识相，喵。）", },
	[184356] = {id=184356, },
	[184357] = {id=184357, zh_CN="有点掉毛啊……", },
	[184358] = {id=184358, zh_CN="喵！（翻译：不给你了，还给芝麻糊！）", },
	[184359] = {id=184359, },
	[184360] = {id=184360, zh_CN="芝麻糊叼来一个项圈，递到玩家手上。内侧刻着“芝麻·古堡主·糊”。", },
	[184361] = {id=184361, zh_CN="芝麻糊允许你给我带上象征名字的项圈。", },
	[184362] = {id=184362, zh_CN="黑皮草就是好看！", },
