	[184576] = {id=184576, zh_CN="侦探需要救援，侦探需要救援！", },
	[184577] = {id=184577, zh_CN="抓到你了！", },
	[184578] = {id=184578, zh_CN="咔嚓——", },
	[184579] = {id=184579, zh_CN="它倏然跳起，扑向黑影。", },
	[184580] = {id=184580, zh_CN="年糕势在必得的表情还僵在脸上……", },
	[184581] = {id=184581, zh_CN="搭档！痛喵——！", },
	[184582] = {id=184582, zh_CN="吹吹就不痛了。", },
	[184583] = {id=184583, zh_CN="我们年糕是最伟大最勇敢的侦探大人。", },
	[184584] = {id=184584, zh_CN="喵~", },
	[184585] = {id=184585, zh_CN="你踩到枯叶，几只鸟惊飞。", },
	[184586] = {id=184586, zh_CN="敌袭！撤退！！", },
	[184587] = {id=184587, zh_CN="年糕埋怨地盯着你。", },
	[184588] = {id=184588, zh_CN="太阳缓缓落入建筑之后，", },
	[184589] = {id=184589, zh_CN="原来敌人会隐身术！", },
	[184590] = {id=184590, zh_CN="不愧是喵喵我的劲敌！", },
	[184591] = {id=184591, zh_CN="我们果然非常有默契。", },
	[184592] = {id=184592, zh_CN="我宣布你通过试用期啦！", },
	[184593] = {id=184593, zh_CN="年糕举着爪爪半天，都没得到反应。", },
	[184594] = {id=184594, zh_CN="嘶——嗷！", },
	[184595] = {id=184595, zh_CN="搭档！再不和我击拳，", },
	[184596] = {id=184596, zh_CN="击拳，标记着我们正式成为搭档！", },
	[184597] = {id=184597, zh_CN="击拳。", },
	[184598] = {id=184598, zh_CN="碰脑袋。", },
	[184599] = {id=184599, zh_CN="你蹲下身，用拳头蹭过年糕的爪爪。", },
	[184600] = {id=184600, zh_CN="很好！很有力量的标记！", },
	[184601] = {id=184601, zh_CN="你蹲下身，用拳头蹭过年糕的爪爪。", },
	[184602] = {id=184602, zh_CN="轻轻地抵上年糕的脑袋。", },
	[184603] = {id=184603, zh_CN="果然是我选中的搭档！", },
	[184604] = {id=184604, zh_CN="%PlayerName侦探，恭喜你通过考验。", },
	[184605] = {id=184605, zh_CN="又是一颗包着肉质皮衣的种子出现在年糕的爪中。", },
	[184606] = {id=184606, zh_CN="咕噜……喵？", },
	[184607] = {id=184607, zh_CN="要", },
	[184608] = {id=184608, zh_CN="看来你就是喵喵我命中注定的助理！", },
	[184609] = {id=184609, zh_CN="这个小种子便是得到古堡庇佑的证明！", },
	[184610] = {id=184610, zh_CN="喵喵我要再次送给你，作为我们的搭档证明！", },
	[184611] = {id=184611, zh_CN="它将木兰花种推向你。", },
	[184612] = {id=184612, zh_CN="从现在开始，你就正式升为我的搭档啦。", },
	[184613] = {id=184613, zh_CN="它的尾巴高翘成天线，年糕独自跳着喵喵步。", },
	[184614] = {id=184614, zh_CN="这是贵族唾液！不懂欣赏！", },
	[184615] = {id=184615, zh_CN="获得种子【木兰种（阳生）】：“哪里有案件，哪里就有我喵喵侦探。”", },
	[184616] = {id=184616, zh_CN="喵~什么东西控制了喵喵我！", },
	[184617] = {id=184617, zh_CN="搭档快跑！不要管我！！", },
	[184618] = {id=184618, zh_CN="可恶的气味，我要和你斗争到底！", },
	[184619] = {id=184619, zh_CN="有毒！但喵喵我愿意为爱牺牲！", },
	[184620] = {id=184620, zh_CN="年糕原地不知停歇地跳起踢踏舞。", },
	[184621] = {id=184621, zh_CN="（解锁成就：“为喵癫狂”）", },
	[184622] = {id=184622, zh_CN="喵~", },
	[184623] = {id=184623, zh_CN="自动门电量不足，需要更新电池。", },
	[184624] = {id=184624, zh_CN="你望着门上的信息，尝试敲门，却无人应答。", },
	[184625] = {id=184625, zh_CN="这居然自动门是仿木门吗？", },
	[184626] = {id=184626, zh_CN="你环顾四周，只有零星几个学生结伴聚在一起。", },
	[184627] = {id=184627, zh_CN="找人问问情况吧。", },
	[184628] = {id=184628, zh_CN="学院大门的电池电量不足了，需要更换电池。", },
	[184629] = {id=184629, zh_CN="你们知道要找谁报修吗？", },
	[184630] = {id=184630, zh_CN="几个学生思索了片刻。", },
	[184631] = {id=184631, zh_CN="我知道！你先通知导员，拿去保修表……", },
	[184632] = {id=184632, zh_CN="然后带着表格去找执行主任……", },
	[184633] = {id=184633, zh_CN="最后导员，主任，院长签名后……", },
	[184634] = {id=184634, zh_CN="交到后勤部就可以了。", },
	[184635] = {id=184635, zh_CN="然后就立刻来修理了？", },
	[184636] = {id=184636, zh_CN="后勤部会通知设备管理人员。", },
	[184637] = {id=184637, zh_CN="真的修理好可能还要两三天。", },
	[184638] = {id=184638, zh_CN="不，好麻烦。", },
	[184639] = {id=184639, zh_CN="其实还有一个办法。", },
	[184640] = {id=184640, zh_CN="据说学院里有一个机械大佬，但他神出鬼没，几乎无人见过他。", },
	[184641] = {id=184641, zh_CN="你可以去问问机械生命阿斯坎。", },
	[184642] = {id=184642, zh_CN="他曾经被路过的大佬修理过机身，可能知道其消息。", },
	[184643] = {id=184643, zh_CN="谢谢。", },
	[184644] = {id=184644, zh_CN="如果能迅速解决自动门的问题，也是方便我们。", },
	[184645] = {id=184645, zh_CN="请问你是机械生命阿斯坎吗？", },
	[184646] = {id=184646, zh_CN="是的。我有什么可以帮到你。", },
	[184647] = {id=184647, zh_CN="阿斯坎，你知道学院里的一位机械大佬在哪里吗？", },
	[184648] = {id=184648, zh_CN="教学大厅的自动门电量不足，学生们被困在外面。", },
	[184649] = {id=184649, zh_CN="原来你在找披风猫啊。", },
	[184650] = {id=184650, zh_CN="但我也很久没有见过它了。", },
	[184651] = {id=184651, zh_CN="我上一次见到他，已经是一年前的事情了。", },
	[184652] = {id=184652, zh_CN="一年？！", },
	[184653] = {id=184653, zh_CN="对，他不太喜欢社交。", },
	[184654] = {id=184654, zh_CN="经常一个人躲在房间里工作，就连来设备检查都要挑晚上。", },
	[184655] = {id=184655, zh_CN="啊……自动门的问题有点大呢。", },
	[184656] = {id=184656, zh_CN="你有办法现在联系到它吗？", },
	[184657] = {id=184657, zh_CN="阿斯坎忽然卡顿，似乎这个问题使他的系统宕机", },
	[184658] = {id=184658, zh_CN="披风猫是个很古怪的性格呢。", },
	[184659] = {id=184659, zh_CN="听说最近在林间小屋呆着，你可以去碰碰运气。", },
	[184660] = {id=184660, zh_CN="古怪的性格？", },
	[184661] = {id=184661, zh_CN="询问喜好", },
	[184662] = {id=184662, zh_CN="喜好的话，他喜欢数据线。", },
	[184663] = {id=184663, zh_CN="数据线？", },
	[184664] = {id=184664, zh_CN="是的，而且是彩色的，配套的最好。", },
	[184665] = {id=184665, zh_CN="他收集那玩意像机械生命囤机油似的。", },
	[184666] = {id=184666, zh_CN="你可以带些“诚意”过去。", },
	[184667] = {id=184667, zh_CN="询问忌讳", },
	[184668] = {id=184668, zh_CN="他讨厌工作时间被打扰，建议你发现他在工作的话，就等一等。", },
	[184669] = {id=184669, zh_CN="等一等？", },
	[184670] = {id=184670, zh_CN="天才的下马威吗？", },
	[184671] = {id=184671, zh_CN="它只是有点社交障碍", },
	[184672] = {id=184672, zh_CN="他对于视线很敏感的，让他自己发现你就好了。", },
	[184673] = {id=184673, zh_CN="不询问", },
	[184674] = {id=184674, zh_CN="只要你注意点，他还是挺好相处的。", },
	[184675] = {id=184675, zh_CN="这些注意事项你记住就好，千万别提是我说的！", },
	[184676] = {id=184676, zh_CN="带着准备好的礼物，你来到了林间小屋门口。", },
	[184677] = {id=184677, zh_CN="一件鼓鼓的绿色斗篷在木屋侧后方躲着，披风下面时不时传来键盘敲击的声音。", },
	[184678] = {id=184678, zh_CN="礼貌问候", },
	[184679] = {id=184679, zh_CN="您好，请问是社区空间站的管理员……", },
	[184680] = {id=184680, zh_CN="披风突然像被人定住，连键盘敲击声都没有了。", },
	[184681] = {id=184681, zh_CN="请问你是披风猫吗？", },
	[184682] = {id=184682, zh_CN="许久，一个显示屏幕从披风下被推出来。", },
	[184683] = {id=184683, zh_CN="工作期间，谢绝访客。", },
	[184684] = {id=184684, zh_CN="披风被里面的猫裹紧，屁股对着你。", },
	[184685] = {id=184685, zh_CN="坚决拒客的姿态很清晰。", },
	[184686] = {id=184686, zh_CN="你只好等待", },
	[184687] = {id=184687, zh_CN="过了好久……你坐在旁边你从白天等到黑夜。", },
	[184688] = {id=184688, zh_CN="披风猫起身，从披风中探出头来。", },
	[184689] = {id=184689, zh_CN="你……你好，找叔有什么事情吗？", },
	[184690] = {id=184690, zh_CN="等待", },
	[184691] = {id=184691, zh_CN="看样子应该是在工作吧，阿斯坎说过最好不要打扰他。", },
	[184692] = {id=184692, zh_CN="不如在旁边等待片刻吧。", },
	[184693] = {id=184693, zh_CN="你在一旁休息，那团披风像是被人戳了。", },
	[184694] = {id=184694, zh_CN="披风猫屁股如坐针毡，来回磨蹭着。", },
	[184695] = {id=184695, zh_CN="键盘敲打的声音也越来越大，越来越快。", },
	[184696] = {id=184696, zh_CN="披风猫起身，从披风中探出头来。", },
	[184697] = {id=184697, zh_CN="你……你好，找叔有什么事情吗？", },
	[184698] = {id=184698, zh_CN="拍拍披风", },
	[184699] = {id=184699, zh_CN="你走上前去拍拍披风", },
	[184700] = {id=184700, zh_CN="你……", },
	[184701] = {id=184701, zh_CN="那团披风耸肩颤抖了一瞬。", },
	[184702] = {id=184702, zh_CN="像个土螃蟹缩在壳里，飞速远离了你。", },
	[184703] = {id=184703, zh_CN="披风原本的位置上，放着一个显示屏幕。", },
	[184704] = {id=184704, zh_CN="工作期间，谢绝访客。", },
	[184705] = {id=184705, zh_CN="披风被里面的猫裹紧，屁股对着你。", },
	[184706] = {id=184706, zh_CN="坚决拒客的姿态很清晰。", },
	[184707] = {id=184707, zh_CN="你只好等待", },
	[184708] = {id=184708, zh_CN="过了好久…….你坐在旁边你从白天等到黑夜。", },
	[184709] = {id=184709, zh_CN="披风猫起身，从披风中探出头来。", },
	[184710] = {id=184710, zh_CN="没礼貌的小子，找叔有什么事情吗？", },
	[184711] = {id=184711, zh_CN="你迅速从包里翻出准备好的见面礼，递到披风猫面前。", },
	[184712] = {id=184712, zh_CN="阿斯坎让我准备的，一点礼物，麻烦收下。", },
	[184713] = {id=184713, zh_CN="拿出礼物", },
	[184714] = {id=184714, zh_CN="披风猫斗篷一掀，将见面礼收入披风下。", },
	[184715] = {id=184715, zh_CN="来麻烦叔什么事情呀？", },
	[184716] = {id=184716, zh_CN="学院的自动门故障了，需要更换电池。", },
	[184717] = {id=184717, zh_CN="哼，早就和他们说过更迭代码可以增强续航。", },
	[184718] = {id=184718, zh_CN="有解决的办法吗？", },
	[184719] = {id=184719, zh_CN="你凑到披风猫身边。", },
	[184720] = {id=184720, zh_CN="披风猫感到不适，忽然转身，瞳孔竖成一道天线。", },
	[184721] = {id=184721, zh_CN="菜鸟，你知道Bug和虫子的相似之处吗？", },
	[184722] = {id=184722, zh_CN="你茫然摇头。", },
	[184723] = {id=184723, zh_CN="不知道藏在哪里，也不知道藏了多少。", },
	[184724] = {id=184724, zh_CN="你要是很闲，去把那里的数据线收拾了，乱得叔眼睛疼！", },
	[184725] = {id=184725, zh_CN="那门的故障？", },
	[184726] = {id=184726, zh_CN="看不起叔！", },
	[184727] = {id=184727, zh_CN="就这，叔分分钟给你搞定。", },
	[184728] = {id=184728, zh_CN="小家伙啊，叔叔吃过的盐比你吃过的饭都多。", },
	[184729] = {id=184729, zh_CN="别到时候叔给你修好故障了，你还没给叔叔整理好数据线。", },
	[184730] = {id=184730, zh_CN="你被披风猫派去整理数据线。", },
	[184731] = {id=184731, zh_CN="而他则坐回了自己的工位。", },
	[184732] = {id=184732, zh_CN="劈里啪啦的键盘声和披风猫的自言自语此起彼伏地响起。", },
	[184733] = {id=184733, zh_CN="这个应该再敲一行……", },
	[184734] = {id=184734, zh_CN="这是哪个菜鸟写的一堆垃圾！", },
	[184735] = {id=184735, zh_CN="啊，叔这是个天才，这都能跑起来……", },
	[184736] = {id=184736, zh_CN="这报修流程，跟我奶奶的裹脚布一样长！", },
	[184737] = {id=184737, zh_CN="你今天这是……更换电池？", },
	[184738] = {id=184738, zh_CN="披风猫披风上的耳朵一抖。", },
	[184739] = {id=184739, zh_CN="不然呢？", },
	[184740] = {id=184740, zh_CN="昨天只是暂时增加了续航。", },
	[184741] = {id=184741, zh_CN="等学院的保修，又是好几天。", },
	[184742] = {id=184742, zh_CN="我不亲自过来换电池，你又跑来扰我清净。", },
	[184743] = {id=184743, zh_CN="去！帮叔递下工具。", },
	[184744] = {id=184744, zh_CN="递道具", },
	[184745] = {id=184745, zh_CN="不需要披风猫言语，你总能送上趁手的工具。", },
	[184746] = {id=184746, zh_CN="很快电池就更新好，披风猫上下打量你好几眼。", },
	[184747] = {id=184747, zh_CN="效率挺高不过和叔叔比起来还差一点。", },
	[184748] = {id=184748, zh_CN="拿着！给你的报酬。", },
	[184749] = {id=184749, zh_CN="叔不喜欢欠别人的。", },
	[184750] = {id=184750, zh_CN="你察觉披风猫的心理，总发觉披风猫有不为人知的故事。", },
	[184751] = {id=184751, zh_CN="当年捡垃圾学编程。", },
	[184752] = {id=184752, zh_CN="翻了3吨电子垃圾，就为换条新数据线……", },
	[184753] = {id=184753, zh_CN="那群蠢货笑我捡破烂，哼！", },
	[184754] = {id=184754, zh_CN="如今我也是成为了一代权威啊，哈哈。", },
	[184755] = {id=184755, zh_CN="猫叔呀，我平时没事能不能来找你玩啊？", },
	[184756] = {id=184756, zh_CN="你个小年轻跑我那里凑什么热闹？", },
	[184757] = {id=184757, zh_CN="别来啊，不准来啊！", },
	[184758] = {id=184758, zh_CN="那我有求于叔，还不行吗？", },
	[184759] = {id=184759, zh_CN="好嘛好嘛？", },
	[184760] = {id=184760, zh_CN="披风迅速裹住披风猫，遮住它绯红的脸颊。", },
	[184761] = {id=184761, zh_CN="行……行吧。随便你。", },
	[184762] = {id=184762, zh_CN="那我们明日小屋再见咯。", },
	[184763] = {id=184763, zh_CN="哦，你来啦，等叔一下，叔把这个忙完。", },
	[184764] = {id=184764, zh_CN="披风猫敲代码的速度加快，片刻，他便收起电脑，完成了工作。", },
	[184765] = {id=184765, zh_CN="今天来找叔干嘛？", },
	[184766] = {id=184766, zh_CN="我们已经两清了哦，不要再给我送数据线了！", },
	[184767] = {id=184767, zh_CN="叔，我是来还你这个的。", },
	[184768] = {id=184768, zh_CN="这个呀……都好久好久以前的事情了。", },
	[184769] = {id=184769, zh_CN="想知道这个？", },
	[184770] = {id=184770, zh_CN="嗯。", },
	[184771] = {id=184771, zh_CN="怎么，这么好奇叔过往的光辉岁月？", },
	[184772] = {id=184772, zh_CN="也不是不能告诉你，不过你要陪我去取个东西。", },
	[184773] = {id=184773, zh_CN="这样偷档案，真的好吗？", },
	[184774] = {id=184774, zh_CN="唉！拿自己的东西怎么能算偷呢！", },
	[184775] = {id=184775, zh_CN="其实叔的故事也没什么好玩的。", },
	[184776] = {id=184776, zh_CN="就是流浪猫嘛，都会经历的那些事情，芝麻点的事情，重提有些矫情了。", },
	[184777] = {id=184777, zh_CN="不过，叔也是做个大事的猫。", },
	[184778] = {id=184778, zh_CN="想当年，叔流浪的地方电子垃圾太多，好些都被违规改造成了犯罪机器。", },
	[184779] = {id=184779, zh_CN="叔当时，一爪敲代码，一爪捞小猫，可是保卫了一方猫族平安。", },
	[184780] = {id=184780, zh_CN="您真是英雄。", },
	[184781] = {id=184781, zh_CN="咳，陈芝麻烂谷子……", },
	[184782] = {id=184782, zh_CN="现在叔有小弟我了。", },
	[184783] = {id=184783, zh_CN="小子口气挺狂啊！", },
	[184784] = {id=184784, zh_CN="好啦，还想听，下次再来吧！", },
	[184785] = {id=184785, zh_CN="你这个小子朋友，叔交定了。", },
	[184786] = {id=184786, zh_CN="不会嫌弃叔年纪大吧。", },
	[184787] = {id=184787, zh_CN="怎么会？", },
	[184788] = {id=184788, zh_CN="那就好！", },
	[184789] = {id=184789, zh_CN="以后遇事儿报叔名号！", },
	[184790] = {id=184790, zh_CN="好好干，别给叔丢脸！", },
