	[185067] = {id=185067, zh_CN="绣球花瓣6", },
	[185068] = {id=185068, zh_CN="绣球花瓣7", },
	[185069] = {id=185069, zh_CN="初见，如骄阳盛放，振作萎靡心魂。靠近，终被自我灼伤。", },
	[185070] = {id=185070, zh_CN="种子如幽蓝琉璃，内藏星轨交错的漩涡。它曾在量子潮汐中碎为尘埃，却借执念之重凝成新的命核 —— 湮灭的终点，原是通往永续的甬道。", },
	[185071] = {id=185071, zh_CN="种子表面布满细密裂纹，如被岁月侵蚀的信笺。触碰时会听见遥远时空的呢喃，那是未竟的约定与未放手的执念。", },
	[185072] = {id=185072, zh_CN="种子泛着暗紫色幽光，仿佛吞噬星光的漩涡。它承认欲望的卑劣，却也因此迸发出超越毁灭的生机。", },
	[185073] = {id=185073, zh_CN="花瓣似浸透霞光的绡纱，露珠中冻着某年早春的雀鸣。风起时，会浮现幼犬追咬蒲公英的碎金光影。", },
	[185074] = {id=185074, zh_CN="集齐掉落的绣球花种，幻化而来的簇状小花。花瓣承载着人们最两面的情绪，阴影与向阳共存，如夏日的绣球包裹着湿酸的利刺。", },
	[185075] = {id=185075, zh_CN="高塔崩塌后，废墟下的绣球扎根生长 利益捆绑才是最坚固的感情， 就如欲望之下，自私和诚实一样坚凝。", },
	[185076] = {id=185076, zh_CN="焦糖色花瓣边缘闪着糖霜，吞噬沙漏漏下的慵懒光尘。甜涩的脉络里，蜿蜒着再偷半刻的孩子气。", },
	[185077] = {id=185077, zh_CN="青绒花瓣拓着梅花爪印，露水在纹路里酿成荔枝甜。雨落时爪印会发烫，像谁在云端偷偷呵气。", },
	[185078] = {id=185078, zh_CN="琉璃花瓣裹着晴空碎片，每阵风过都漾起学堂钟声。千年曝晒未褪的，是放学路上那句明天见的靛蓝。", },
	[185079] = {id=185079, zh_CN="雪瓣里冻着打盹的梨枝，每朵花苞皆是未响的哈欠。当月光哼起童谣时，花影会蜷成毛团状的云。", },
	[185080] = {id=185080, zh_CN="花瓣形如麻雀窝，用棉絮、蝉蜕和过期的压岁钱筑成。最深处埋着颗玻璃珠，折射出永不西沉的晨。", },
	[185081] = {id=185081, zh_CN="高险之地的孤枝绽放，是闯荡者无畏的奖励。花瓣坠落处，亦浸染与命运孤途对峙的切齿心酸。", },
	[185082] = {id=185082, zh_CN="种子如幽蓝琉璃，内藏星轨交错的漩涡。它曾在量子潮汐中碎为尘埃，却借执念之重凝成新的命核 —— 湮灭的终点，原是通往永续的甬道。", },
	[185083] = {id=185083, zh_CN="种子表面布满细密裂纹，如被岁月侵蚀的信笺。触碰时会听见遥远时空的呢喃，那是未竟的约定与未放手的执念。", },
	[185084] = {id=185084, zh_CN="集齐掉落的木兰花种，幻化而来的荆棘之上的纤细堇花。花瓣承载着属于踏上征程者的使命，独自开拓荆棘的苦痛与成就，化作紫色刻痕，留在身后的花瓣之上。", },
	[185085] = {id=185085, zh_CN="别在侦探胸前的木兰花瓣，每道划痕皆记录着喵踪迹。哪里有案件，哪里就有喵喵侦探。这是年轻孩子对征途最童真的祝福。", },
	[185086] = {id=185086, zh_CN="半透明花瓣如柳叶舟，载着十二粒星屑化成的萤火。舟尾垂着银铃铛，轻摇时唤醒草尖酣眠的薄暮。", },
	[185087] = {id=185087, zh_CN="花瓣蜷成未拆的信笺，紫纹是相思鸟衔来的雨痕。展开瞬间，墨香会化作一句我在花开处等你的潮气。", },
	[185088] = {id=185088, zh_CN="焦糖色花瓣边缘闪着糖霜，吞噬沙漏漏下的慵懒光尘。甜涩的脉络里，蜿蜒着再偷半刻的孩子气。", },
	[185089] = {id=185089, zh_CN="青绒花瓣拓着梅花爪印，露水在纹路里酿成荔枝甜。雨落时爪印会发烫，像谁在云端偷偷呵气。", },
	[185090] = {id=185090, zh_CN="琉璃花瓣裹着晴空碎片，每阵风过都漾起学堂钟声。千年曝晒未褪的，是放学路上那句『明天见』的靛蓝。", },
	[185091] = {id=185091, zh_CN="雪瓣里冻着打盹的梨枝，每朵花苞皆是未响的哈欠。当月光哼起童谣时，花影会蜷成毛团状的云。", },
	[185092] = {id=185092, zh_CN="华贵帝王，自有重瓣如冠冕。识其王者之气，亦需敬其不容亵渎的傲慢。", },
	[185093] = {id=185093, zh_CN="种子如幽蓝琉璃，内藏星轨交错的漩涡。它曾在量子潮汐中碎为尘埃，却借执念之重凝成新的命核 —— 湮灭的终点，原是通往永续的甬道。", },
	[185094] = {id=185094, zh_CN="种子表面布满细密裂纹，如被岁月侵蚀的信笺。触碰时会听见遥远时空的呢喃，那是未竟的约定与未放手的执念。", },
	[185095] = {id=185095, zh_CN="种子泛着暗紫色幽光，仿佛吞噬星光的漩涡。它承认欲望的卑劣，却也因此迸发出超越毁灭的生机。", },
	[185096] = {id=185096, zh_CN="集齐掉落的牡丹花种，幻化而来的绯红花蕊。花瓣承载着王的混杂记忆爱与恨，威严与多疑……", },
	[185097] = {id=185097, zh_CN="古堡废墟中寻得的牡丹花瓣，浸透古堡贵族猫最后的倨傲。喵呜！无人听清的呜咽并非并非旧世哀鸣，而是宣战的王昭。", },
	[185098] = {id=185098, zh_CN="花瓣蜷成未拆的信笺，紫纹是相思鸟衔来的雨痕。展开瞬间，墨香会化作一句我在花开处等你的潮气。", },
	[185099] = {id=185099, zh_CN="焦糖色花瓣边缘闪着糖霜，吞噬沙漏漏下的慵懒光尘。甜涩的脉络里，蜿蜒着再偷半刻的孩子气。", },
	[185100] = {id=185100, zh_CN="青绒花瓣拓着梅花爪印，露水在纹路里酿成荔枝甜。雨落时爪印会发烫，像谁在云端偷偷呵气。", },
	[185101] = {id=185101, zh_CN="琉璃花瓣裹着晴空碎片，每阵风过都漾起学堂钟声。千年曝晒未褪的，是放学路上那句明天见的靛蓝。", },
	[185102] = {id=185102, zh_CN="雪瓣里冻着打盹的梨枝，每朵花苞皆是未响的哈欠。当月光哼起童谣时，花影会蜷成毛团状的云。", },
	[185103] = {id=185103, zh_CN="花瓣形如麻雀窝，用棉絮、蝉蜕和过期的压岁钱筑成。最深处埋着颗玻璃珠，折射出永不西沉的晨。", },
	[185104] = {id=185104, zh_CN="浮生若梦，枕水而憩。 任凭时光在涟漪间流转，温柔无波，令人沉溺勿要怠惰了逐流的心帆。", },
	[185105] = {id=185105, zh_CN="种子如幽蓝琉璃，内藏星轨交错的漩涡。它曾在量子潮汐中碎为尘埃，却借执念之重凝成新的命核 —— 湮灭的终点，原是通往永续的甬道。", },
	[185106] = {id=185106, zh_CN="种子表面布满细密裂纹，如被岁月侵蚀的信笺。触碰时会听见遥远时空的呢喃，那是未竟的约定与未放手的执念。", },
	[185107] = {id=185107, zh_CN="种子泛着暗紫色幽光，仿佛吞噬星光的漩涡。它承认欲望的卑劣，却也因此迸发出超越毁灭的生机。", },
	[185108] = {id=185108, zh_CN="集齐掉落的睡莲花种，幻化而来的漂浮水面的睡莲玉瓣。花瓣承载着隐士的秘密，慵懒地漂浮于时光之上。", },
	[185109] = {id=185109, zh_CN="遗落在地的睡莲花瓣，在朴素的斜口瓶中生根发芽。光寒利刃在鞘里生锈，握紧时仍传来沉稳心跳，纵使锋芒暂歇，炙热血脉仍在隐士斗篷下猎猎作响。", },
	[185110] = {id=185110, zh_CN="花瓣蜷成未拆的信笺，紫纹是相思鸟衔来的雨痕。展开瞬间，墨香会化作一句『我在花开处等你』的潮气。", },
	[185111] = {id=185111, zh_CN="焦糖色花瓣边缘闪着糖霜，吞噬沙漏漏下的慵懒光尘。甜涩的脉络里，蜿蜒着『再偷半刻』的孩子气。", },
	[185112] = {id=185112, zh_CN="青绒花瓣拓着梅花爪印，露水在纹路里酿成荔枝甜。雨落时爪印会发烫，像谁在云端偷偷呵气。", },
	[185113] = {id=185113, zh_CN="琉璃花瓣裹着晴空碎片，每阵风过都漾起学堂钟声。千年曝晒未褪的，是放学路上那句『明天见』的靛蓝。", },
	[185114] = {id=185114, zh_CN="雪瓣里冻着打盹的梨枝，每朵花苞皆是未响的哈欠。当月光哼起童谣时，花影会蜷成毛团状的云。", },
	[185115] = {id=185115, zh_CN="花瓣形如麻雀窝，用棉絮、蝉蜕和过期的压岁钱筑成。最深处埋着颗玻璃珠，折射出永不西沉的晨。", },
	[185116] = {id=185116, zh_CN="碎金绒花，少女予人一笑当暖光褪去，绒球低垂，便是热情冷却后的无声神伤。", },
	[185117] = {id=185117, zh_CN="种子如幽蓝琉璃，内藏星轨交错的漩涡。它曾在量子潮汐中碎为尘埃，却借执念之重凝成新的命核 —— 湮灭的终点，原是通往永续的甬道。", },
	[185118] = {id=185118, zh_CN="种子表面布满细密裂纹，如被岁月侵蚀的信笺。触碰时会听见遥远时空的呢喃，那是未竟的约定与未放手的执念。", },
	[185119] = {id=185119, zh_CN="集齐掉落的合欢花种，幻化而来的曜日绒球。花瓣承载着花球少女的力量是振奋的“花球”与坚守的印痕。", },
	[185120] = {id=185120, zh_CN="绒绒碎金的合欢花，是世界赠予公主的无声加冕礼。她是就算雪夜，依旧被阳光偏爱的孩子。融不化雪花的温柔，是公主的“秘密武器”。", },
	[185121] = {id=185121, zh_CN="半透明花瓣如柳叶舟，载着十二粒星屑化成的萤火。舟尾垂着银铃铛，轻摇时唤醒草尖酣眠的薄暮。", },
	[185122] = {id=185122, zh_CN="花瓣蜷成未拆的信笺，紫纹是相思鸟衔来的雨痕。展开瞬间，墨香会化作一句我在花开处等你的潮气。", },
	[185123] = {id=185123, zh_CN="焦糖色花瓣边缘闪着糖霜，吞噬沙漏漏下的慵懒光尘。甜涩的脉络里，蜿蜒着再偷半刻的孩子气。", },
	[185124] = {id=185124, zh_CN="青绒花瓣拓着梅花爪印，露水在纹路里酿成荔枝甜。雨落时爪印会发烫，像谁在云端偷偷呵气。", },
	[185125] = {id=185125, zh_CN="琉璃花瓣裹着晴空碎片，每阵风过都漾起学堂钟声。千年曝晒未褪的，是放学路上那句明天见的靛蓝。", },
	[185126] = {id=185126, zh_CN="雪瓣里冻着打盹的梨枝，每朵花苞皆是未响的哈欠。当月光哼起童谣时，花影会蜷成毛团状的云。", },
