	[185130] = {id=185130, zh_CN="偶遇阿加莎公主，上前与她寒暄几句。", },
	[185131] = {id=185131, zh_CN="按照邀请函上的时间，你如约来到宴会现场，等待宴会开场。", },
	[185132] = {id=185132, zh_CN="宴会开始，接受阿加莎的邀请，与她一起同游宴会。", },
	[185133] = {id=185133, zh_CN="你与阿加莎成为笔友，她似乎又邀请你参加她的私人茶会。", },
	[185134] = {id=185134, },
	[185135] = {id=185135, zh_CN="和跳出来的年糕对话，询问意图", },
	[185136] = {id=185136, zh_CN="前往商会旁的花瓶，和年糕对话", },
	[185137] = {id=185137, zh_CN="和年糕对话", },
	[185138] = {id=185138, },
	[185139] = {id=185139, zh_CN="月影商会的邀请函发来一张邀请函，去问问奥黛特。", },
	[185140] = {id=185140, zh_CN="携月影商会的邀请函，你如约来到宴会，与奥黛特对话。", },
	[185141] = {id=185141, zh_CN="与奥黛特对话，欣赏“珍品之夜”。", },
	[185142] = {id=185142, zh_CN="奥黛特好像有情绪花种的线索，找到她询问。", },
	[185143] = {id=185143, zh_CN="月影商会的邀请函发来一张邀请函。", },
	[185144] = {id=185144, zh_CN="初见森林里的奇怪机械生命。", },
	[185145] = {id=185145, zh_CN="被奇怪的家伙赶出林间小屋，在原地等待一会。", },
	[185146] = {id=185146, zh_CN="奇怪的家伙，还是少来往吧。", },
	[185147] = {id=185147, zh_CN="林间小屋机械生命围着莫迪斯机满为患，去问问怎么回事。", },
	[185148] = {id=185148, zh_CN="林间小屋机械生命围着莫迪斯机满为患，去问问怎么回事。", },
	[185149] = {id=185149, zh_CN="突破空间站戒备，摆脱守卫，找到莫迪斯所需材料。", },
	[185150] = {id=185150, zh_CN="突破空间站戒备，摆脱守卫，找到莫迪斯所需材料。", },
	[185151] = {id=185151, zh_CN="回到林间小屋，将材料交给莫迪斯。", },
	[185152] = {id=185152, zh_CN="回到林间小屋，将材料交给莫迪斯。", },
	[185153] = {id=185153, zh_CN="莫迪斯忽然来找你，和他对话", },
	[185154] = {id=185154, zh_CN="和莫迪斯讨论机械生命必须遵守的法则。", },
	[185155] = {id=185155, zh_CN="莫迪斯邀请你成为他的对象后，和他尝试了一系列的实验。", },
	[185156] = {id=185156, zh_CN="你好奇莫迪斯的机体构造，和他对话，向他提出了不合理的要求。", },
	[185157] = {id=185157, zh_CN="莫迪斯像人般有了情绪，和他对话，总让你觉得心跳加速。", },
	[185158] = {id=185158, zh_CN="和莫迪斯对话，你以研究感情的名义，向莫迪斯提出了契约邀请。", },
	[185159] = {id=185159, zh_CN="莫迪斯好像有话和你说，去找他吧。", },
	[185160] = {id=185160, zh_CN="偶遇了莫迪斯与其他机械生命的对话，窥探到机械生命存在背后的可悲。", },
	[185161] = {id=185161, },
	[185162] = {id=185162, zh_CN="欢迎来到玩法引导，有三个玩法请您尝试。", },
	[185163] = {id=185163, zh_CN="请点击上方家园按钮，或者先点击广场按钮再点击家园按钮返回家园。\n请与家园中的“翼”进行互动创建智能伙伴。", },
	[185164] = {id=185164, zh_CN="请点击上方游玩乐园按钮，再点击休闲聚会前往舞会。\n与场上的伙伴互动|邀请共舞吧。", },
	[185165] = {id=185165, zh_CN="请点击上方游玩乐园按钮，再点击天梯集会进行古堡玩法。请点击创建房间村民智能局。\n进入后坐下开始游戏。\n祝您游玩愉快。", },
