	[185270] = {id=185270, zh_CN="【信仰崇拜】", },
	[185271] = {id=185271, zh_CN="【情绪花】", },
	[185272] = {id=185272, zh_CN="【流浪光灵的真相】", },
	[185273] = {id=185273, zh_CN="【记忆中的宝藏】", },
	[185274] = {id=185274, zh_CN="【记忆中的宝藏】", },
	[185275] = {id=185275, zh_CN="【忠诚之道】", },
	[185276] = {id=185276, zh_CN="【好蓬松的尾巴毛】", },
	[185277] = {id=185277, zh_CN="【来做我的邻居】", },
	[185278] = {id=185278, zh_CN="【焦躁的陀螺金毛】", },
	[185279] = {id=185279, zh_CN="【千年春色献故人】", },
	[185280] = {id=185280, zh_CN="【又是一年春】", },
	[185281] = {id=185281, zh_CN="【社区辩论赛】", },
	[185282] = {id=185282, zh_CN="【了解实情】", },
	[185283] = {id=185283, zh_CN="【第一搭档】", },
	[185284] = {id=185284, zh_CN="【狭路相逢冤家胜】", },
	[185285] = {id=185285, zh_CN="小金毛等待你好几日了，快去和它见面，看看它找你什么事情。", },
	[185286] = {id=185286, zh_CN="得到小金毛的认可，与它前往秘密基地。", },
	[185287] = {id=185287, zh_CN="小金毛翻找到一卷羊皮藏宝图，想要与你共同去探索。", },
	[185288] = {id=185288, zh_CN="与小金毛汇合，一同探寻藏宝图的秘密。", },
	[185289] = {id=185289, zh_CN="小金毛与你袒露过去的跨越千年故事……", },
	[185290] = {id=185290, zh_CN="初见那只金毛狗，它好像就叫小金毛。", },
	[185291] = {id=185291, zh_CN="邀请小金毛来家园做自己的邻居", },
	[185292] = {id=185292, zh_CN="小金毛好像遇到了麻烦，去帮帮它吧。", },
	[185293] = {id=185293, zh_CN="小金毛趴在花堆里，在准备什么纪念品，去和它对话，", },
	[185294] = {id=185294, zh_CN="小金毛邀请你与它一同扫墓。", },
	[185295] = {id=185295, zh_CN="关于社区公共卫生，你和小金毛各执己见，和它对话。", },
	[185296] = {id=185296, zh_CN="与小金毛对话，了解它据理力争的原因。", },
	[185297] = {id=185297, zh_CN="被居民认证了两人的搭档身份，与小金毛一同庆祝。", },
	[185298] = {id=185298, zh_CN="和天生宿敌的小金毛竟然成为了默契的搭档。", },
	[185299] = {id=185299, },
	[185300] = {id=185300, zh_CN="偶遇被市容管理所逮捕的小金毛，它的到来，让你也陷入了麻烦。", },
	[185301] = {id=185301, zh_CN="被通缉的小金毛·进入潜行，逃脱抓捕。和小金毛一起逃脱警察的抓捕，跟上它，瞧瞧小金毛去向哪里？", },
	[185302] = {id=185302, zh_CN="跟上它，瞧瞧小金毛去向哪里？", },
	[185303] = {id=185303, zh_CN="【追击花瓶】", },
	[185304] = {id=185304, },
	[185305] = {id=185305, zh_CN="跟随藏宝图，寻找到商会后巷……", },
	[185306] = {id=185306, zh_CN="跟随藏宝图，寻找到商会后巷……", },
	[185307] = {id=185307, zh_CN="家园里好像来了一位毛茸茸访客。", },
	[185308] = {id=185308, zh_CN="和跳出来的年糕对话，询问意图", },
	[185309] = {id=185309, zh_CN="电影厂旁的花瓶，和年糕对话", },
	[185310] = {id=185310, zh_CN="和年糕对话", },
	[185311] = {id=185311, zh_CN="花瓶", },
	[185312] = {id=185312, zh_CN="跟随年糕指引，追击花瓶黑影，找寻“花瓶”踪迹。", },
	[185313] = {id=185313, zh_CN="你和年糕追了一路，树影娑娑，年糕好像找到了“花瓶”的踪迹。", },
	[185314] = {id=185314, zh_CN="追击", },
	[185315] = {id=185315, zh_CN="【调查商会失窃案件】", },
	[185316] = {id=185316, zh_CN="【奇怪的黑影？】", },
	[185317] = {id=185317, zh_CN="【奇怪的足迹】", },
	[185318] = {id=185318, zh_CN="【古堡的主人……？】", },
	[185319] = {id=185319, zh_CN="【二重隐匿】", },
	[185320] = {id=185320, zh_CN="【芝麻糊的求助】", },
	[185321] = {id=185321, zh_CN="【疗伤危机】", },
	[185322] = {id=185322, zh_CN="【物归原主】", },
	[185323] = {id=185323, zh_CN="【堡主的认可】", },
	[185324] = {id=185324, zh_CN="【草丛里的身影】", },
	[185325] = {id=185325, zh_CN="【审讯花瓶】", },
	[185326] = {id=185326, zh_CN="【追击浮影续】", },
	[185327] = {id=185327, zh_CN="【解锁花瓣】", },
	[185328] = {id=185328, zh_CN="阿加莎公主的身影出现在不远处的喷泉旁，她似乎刚结束一场小型会晤，准备返回方舟。", },
	[185329] = {id=185329, zh_CN="出声叫住阿加莎。", },
	[185330] = {id=185330, zh_CN="阿加莎！", },
	[185331] = {id=185331, zh_CN="她眼眸倏然睁大，身躯一颤，朝着声音传来的方向侧脸望去。", },
	[185332] = {id=185332, zh_CN="下午好呀！", },
	[185333] = {id=185333, zh_CN="她透过水雾一眼便看见了你。脚步微顿，牵起裙锻朝你屈膝行礼。", },
	[185334] = {id=185334, zh_CN="阿加莎收起一瞬的惊愕，恢复那标志性的，温柔如暖阳的微笑。", },
	[185335] = {id=185335, zh_CN="她脚步轻盈又端庄地朝你走来，她雾紫色的长发流淌着如缎带的柔光。", },
	[185336] = {id=185336, zh_CN="上前打招呼。", },
	[185337] = {id=185337, zh_CN="你追上阿加莎略显匆忙的脚步，从身侧拍了拍她的肩膀。", },
	[185338] = {id=185338, zh_CN="阿加莎，下午好。", },
	[185339] = {id=185339, zh_CN="她眼眸倏然睁大，身躯一颤。", },
	[185340] = {id=185340, zh_CN="阿加莎收起一瞬的惊愕，恢复那标志性的，温柔如暖阳的微笑。", },
	[185341] = {id=185341, zh_CN="她脚步微顿，牵起裙锻朝你屈膝行礼。", },
	[185342] = {id=185342, zh_CN="雾紫色的长发在阳光下流淌着如缎带的柔光。", },
	[185343] = {id=185343, zh_CN="悄悄离开。", },
	[185344] = {id=185344, zh_CN="望着阿加莎略显匆忙的脚步，你不愿打扰，缓缓退步，用喷泉细密的水雾遮住身影，悄悄离开。", },
	[185345] = {id=185345, zh_CN="她忽地侧脸透过水雾一眼便看见了你，脚步微顿，牵起裙锻朝你屈膝行礼。", },
	[185346] = {id=185346, zh_CN="阿加莎收起一瞬的惊愕，恢复那标志性的，温柔如暖阳的微笑。", },
	[185347] = {id=185347, zh_CN="她脚步轻盈又端庄地朝你走来，她雾紫色的长发流淌着如缎带的柔光。", },
	[185348] = {id=185348, zh_CN="%PlayerName阁下，祝您午安。", },
	[185349] = {id=185349, zh_CN="希望午后的阳光没有让您感到不适。", },
	[185350] = {id=185350, zh_CN="没想到会在这里见到公主。公主是刚刚结束工作吗？", },
	[185351] = {id=185351, zh_CN="她点点头，笑容加深，闪烁着不易察觉的一丝探究。", },
	[185352] = {id=185352, zh_CN="我今日肯定受到了潘神的眷顾，让我在此处遇见您。", },
	[185353] = {id=185353, zh_CN="您来到这里也有些时日了，一切可还习惯？", },
	[185354] = {id=185354, zh_CN="如若有任何需要，请务必告知我，方舟一定竭尽所能地帮助阁下。", },
	[185355] = {id=185355, zh_CN="没什么不习惯的。如果有需要，我一定会麻烦公主的。", },
	[185356] = {id=185356, zh_CN="到时候不要说我太不客气才好。", },
	[185357] = {id=185357, zh_CN="当然不会。阁下能来，是方舟的幸事。", },
	[185358] = {id=185358, zh_CN="阿加莎从侍从的提篮中取出一封印有方舟徽印的邀请函，双手托着递交给玩家。", },
	[185359] = {id=185359, zh_CN="那信封是柔和的珍珠白色，边缘滚着细细的紫金线，方舟的暗纹图标刻印在信封上。", },
	[185360] = {id=185360, zh_CN="没有邀约便贸然上访实在不符合礼仪，今日的偶遇正好给我一个亲自发出邀请的机会。", },
	[185361] = {id=185361, zh_CN="下周二，方舟将会联合三族在城堡外的喷泉停台上将举行音乐晚宴。", },
	[185362] = {id=185362, zh_CN="为了近期三族之间的外交，以及欢迎……", },
	[185363] = {id=185363, zh_CN="像您这样尊贵而特别的客人的到来。", },
	[185364] = {id=185364, zh_CN="作为诺亚方舟的未来继承人，我真诚地希望能借此机会。", },
	[185365] = {id=185365, zh_CN="让您更加深入的感受这里的人文历史，也希望能有荣幸，在这个轻松的晚宴上，聆听您旅途中的故事。", },
	[185366] = {id=185366, zh_CN="不知您届时是否方便赏光？", },
	[185367] = {id=185367, zh_CN="欣然接受。", },
	[185368] = {id=185368, zh_CN="感谢公主的盛情邀请，我一定会准时赴约。", },
	[185369] = {id=185369, zh_CN="您有如此高的意愿，真是太好了。", },
	[185370] = {id=185370, zh_CN="希望您来自浩瀚星海之外的经历给方舟带来全新的视角。", },
	[185371] = {id=185371, zh_CN="礼貌询问晚宴礼仪。", },
	[185372] = {id=185372, zh_CN="非常感谢您的邀请。", },
	[185373] = {id=185373, zh_CN="阿加莎公主。不知晚宴对着装和礼仪方面有何要求？我希望能符合方舟的礼节。", },
	[185374] = {id=185374, zh_CN="眼睛微微睁大，她轻掩住嘴，发出轻柔愉悦的短促气音。", },
	[185375] = {id=185375, zh_CN="噢！您……您真是太体贴了。", },
	[185376] = {id=185376, zh_CN="如果您愿意穿着您觉得最得体的常服前来，", },
	[185377] = {id=185377, zh_CN="那便是对我、对方舟最大的尊重了。", },
	[185378] = {id=185378, zh_CN="希望您来自浩瀚星海之外的经历给方舟带来全新的视角。", },
	[185379] = {id=185379, zh_CN="略显犹豫。", },
	[185380] = {id=185380, zh_CN="这……非常感谢您的邀请。", },
	[185381] = {id=185381, zh_CN="只是我初来乍到，对方舟的礼仪尚不熟悉，恐怕……", },
	[185382] = {id=185382, zh_CN="眼睛微微睁大，她轻掩住嘴，发出轻柔愉悦的短促气音。", },
	[185383] = {id=185383, zh_CN="如果您愿意穿着您觉得最得体的常服前来，", },
	[185384] = {id=185384, zh_CN="那便是对我、对方舟最大的尊重了。", },
	[185385] = {id=185385, zh_CN="希望您来自浩瀚星海之外的经历给方舟带来全新的视角。", },
	[185386] = {id=185386, zh_CN="阿加莎将邀请函轻轻放入你手中，指尖不经意间划过掌心，带来一丝温凉。", },
	[185387] = {id=185387, zh_CN="她的笑容如春日暖阳，带着不容错辨的期待。", },
	[185388] = {id=185388, zh_CN="那么，我就当您答应了？期待着与您在流光下的再次会面。", },
	[185389] = {id=185389, zh_CN="阿加莎后退一步，再次优雅地屈膝行礼，这次行礼的角度似乎比初见时更标准一些。", },
	[185390] = {id=185390, zh_CN="阳光穿过她头顶的花架，在她精致的裙摆上投下斑驳的光影。", },
	[185391] = {id=185391, zh_CN="愿流光与冒险常伴您左右。", },
	[185392] = {id=185392, zh_CN="晚宴见！", },
	[185393] = {id=185393, zh_CN="期待与您在晚宴相见，失陪。", },
	[185394] = {id=185394, zh_CN="阿加莎挺直脊背，转身而去。雾紫色的长发随着动作划出一道优雅的弧线……", },
	[185395] = {id=185395, zh_CN="她的背影在侍从的簇拥下渐渐融入城堡喷泉下灿烂的阳光与水雾之中。", },
	[185396] = {id=185396, zh_CN="你低头看着手中那封制作精良、散发着淡淡冷香的邀请函。", },
	[185397] = {id=185397, zh_CN="封口处小小的徽印在阳光下闪烁着微光。", },
	[185398] = {id=185398, zh_CN="时间流转，你在宴会当夜来到城堡的喷泉亭台上。", },
	[185399] = {id=185399, zh_CN="喷泉旁灯火辉煌，来往的人群耳畔厮磨，衣香鬓影。", },
	[185400] = {id=185400, zh_CN="你隐匿在晚宴的角落，望着人群中光芒四射的阿加莎。", },
	[185401] = {id=185401, zh_CN="她如同一颗温润的雾紫色珍珠，优雅自如地穿梭在各方代表之间。", },
	[185402] = {id=185402, zh_CN="她总能精准地认出来访的宾客，为其送上最诚挚的欢迎。", },
	[185403] = {id=185403, zh_CN="她登上喷泉亭台的二楼，脸上是无可挑剔的温暖微笑，她温柔又坚定的声音在众人耳边响起。", },
	[185404] = {id=185404, zh_CN="她左手覆在胸前，微微低头。", },
	[185405] = {id=185405, zh_CN="她以最为古老，表达极高敬意的人族抚胸礼向在场的来宾表达感激之情。", },
	[185406] = {id=185406, zh_CN="愿这片今夜的流光，能抚平您灵魂的疲倦，带来片刻安宁。", },
	[185407] = {id=185407, zh_CN="余光落在你的身上，朝你轻轻点头示意。", },
	[185408] = {id=185408, zh_CN="尊贵的各位来宾，诺亚方舟的阿加莎，向您致以最诚挚的问候。", },
	[185409] = {id=185409, zh_CN="欢迎您莅临今晚的音乐盛会，我们在此庆祝和平常驻。", },
	[185410] = {id=185410, zh_CN="以及欢迎远道而来的“天外宾客”。", },
	[185411] = {id=185411, zh_CN="我宣布，宴会开始。", },
	[185412] = {id=185412, zh_CN="结束开场的阿加莎，在人群中迅速捕捉到你的位置，牵起裙摆从二楼走下，便直直朝你走来。", },
	[185413] = {id=185413, zh_CN="走到你面前微微屈膝，行了一个标准的方舟王室问候礼。", },
	[185414] = {id=185414, zh_CN="%PlayerName阁下，很高兴您能信守承诺，来参加我的晚宴。", },
	[185415] = {id=185415, zh_CN="模仿阿加莎行礼。", },
	[185416] = {id=185416, zh_CN="你模仿阿加莎的抚胸礼，略显生涩但态度认真。", },
	[185417] = {id=185417, zh_CN="感谢您的盛情邀请，阿加莎公主，您的美丽与热情，让我印象深刻。", },
	[185418] = {id=185418, zh_CN="眼中闪过一丝不易察觉的赞许，笑容似乎真切了一分。", },
	[185419] = {id=185419, zh_CN="试图尝试种族礼仪。", },
	[185420] = {id=185420, zh_CN="你行了自己种族的礼，但动作不够标准。", },
	[185421] = {id=185421, zh_CN="呃……谢谢，公主殿下。这宴会真……真盛大。", },
	[185422] = {id=185422, zh_CN="眼眸微微眯起，笑容弧度未变。", },
	[185423] = {id=185423, zh_CN="点头。", },
	[185424] = {id=185424, zh_CN="你点头致意。", },
	[185425] = {id=185425, zh_CN="好久不见，阿加莎公主。", },
	[185426] = {id=185426, zh_CN="阿加莎微笑的弧度未变，但却悄悄挺立了身躯。", },
	[185427] = {id=185427, zh_CN="您能适应就好，请不必拘束。", },
	[185428] = {id=185428, zh_CN="今日就让我来当您的导游吧。", },
	[185429] = {id=185429, zh_CN="我的荣幸。", },
	[185430] = {id=185430, zh_CN="三族盟约已有百年历史……", },
	[185431] = {id=185431, zh_CN="这晚宴不仅是欢庆米乐星球的和平，更是维系友谊与共同展望未来的桥梁。", },
	[185432] = {id=185432, zh_CN="您看，城墙上的壁画，便是描绘的三族签订和平休战契约的历史。", },
	[185433] = {id=185433, zh_CN="这划过天际的流光便象征着指引与合作……", },
	[185434] = {id=185434, zh_CN="阿加莎如同一只优雅的蝴蝶，在宾客间穿梭。", },
	[185435] = {id=185435, zh_CN="她为你导航历史的同时，还能自如地与周围的宾客谈论。", },
	[185436] = {id=185436, zh_CN="这是精灵族最年长的长老阁下。", },
	[185437] = {id=185437, zh_CN="您带来的“花露”我非常喜欢，我一定会好好品尝的。", },
	[185438] = {id=185438, zh_CN="您喜欢就好，古树庇佑您，阿加莎公主。", },
	[185439] = {id=185439, zh_CN="阿加莎公主！", },
	[185440] = {id=185440, zh_CN="酋长阁下，您新锻造的合金我已经收到了。", },
	[185441] = {id=185441, zh_CN="方舟就需要这样坚韧又耐用的材料，您的锻造技术正是方舟不可缺少的力量呢。", },
	[185442] = {id=185442, zh_CN="哈哈哈哈哈！那是当然了！", },
	[185443] = {id=185443, zh_CN="阿加莎一路应酬而过，你恍然发现，阿加莎不仅对于这样的软外交得心应手……", },
	[185444] = {id=185444, zh_CN="她也总能不动声色地发觉很多“小意外”，并温柔地将其解决。", },
	[185445] = {id=185445, zh_CN="阿加莎像温柔的紫色火烧云，梦幻又朦胧的色彩下是她如沐的降世之雨。", },
	[185446] = {id=185446, zh_CN="阿加莎忽掏出丝帕，递给甜品台前的少女，为其挡住周围的目光。", },
	[185447] = {id=185447, zh_CN="小姐不必惊慌，城堡侧厅有备用的礼服，让我的侍从陪您去更换吧。", },
	[185448] = {id=185448, zh_CN="相信小小的意外，无损您今晚的光彩。", },
	[185449] = {id=185449, zh_CN="另一边，阿加莎又及时俯身扶住追逐打闹的妖灵族小殿下。", },
	[185450] = {id=185450, zh_CN="小心脚下，我勇往直前的小勇士。", },
	[185451] = {id=185451, zh_CN="…………", },
	[185452] = {id=185452, zh_CN="晚宴在与阿加莎的陪伴下，如流光划过天际，山顶天白处染上一丝紫红，日光要亮了。", },
	[185453] = {id=185453, zh_CN="此时，阿加莎才有时间与精力与你说上几句话。", },
	[185454] = {id=185454, zh_CN="对不起，%PlayerName阁下。我想我的导游工作似乎做的不是很好。", },
	[185455] = {id=185455, zh_CN="没关系。", },
	[185456] = {id=185456, zh_CN="没关系，你要好好休息才是。", },
	[185457] = {id=185457, zh_CN="谢谢提醒，我会的。", },
	[185458] = {id=185458, zh_CN="你好厉害。", },
	[185459] = {id=185459, zh_CN="不，你让我见识了很多。", },
	[185460] = {id=185460, zh_CN="你今天真是太厉害了，我完全佩服你，阿加莎公主。", },
	[185461] = {id=185461, zh_CN="都是我作为公主应该做的。", },
	[185462] = {id=185462, zh_CN="我们可以下次再约。", },
	[185463] = {id=185463, zh_CN="也许遗憾会带来下次的相逢。", },
	[185464] = {id=185464, zh_CN="请不要感到抱歉，阿加莎公主。", },
	[185465] = {id=185465, zh_CN="好。我记住阁下的话了。", },
	[185466] = {id=185466, zh_CN="期待下次的再会。", },
	[185467] = {id=185467, zh_CN="数日后，阿加莎又寄给你一封亲笔的邀请函，信封上盖着阿加莎的私印。", },
	[185468] = {id=185468, zh_CN="那是一朵不知名的花章，香薰纸制成的信封上萦绕着沁人心脾的香气……", },
	[185469] = {id=185469, zh_CN="让人不自觉地就想起阿加莎的温柔。", },
	[185470] = {id=185470, zh_CN="你拆开信封，娟秀工整的字迹缓缓展开：阿加莎难消歉意，邀你隔日参加她的私人茶会。", },
	[185471] = {id=185471, zh_CN="约会当日。城堡旁的花房上，阿加莎已经坐在那里等候多时，而你，也如约而至。", },
	[185472] = {id=185472, zh_CN="她换下了繁复的晚礼服，身着一条剪裁优雅的淡紫色及膝裙。", },
	[185473] = {id=185473, zh_CN="雾紫色的长发松松挽起，别着一枚小巧的珍珠发夹。", },
	[185474] = {id=185474, zh_CN="她亲自在花架下布置茶点，看到你的到来，露出比晚宴时更放松一些的微笑。", },
	[185475] = {id=185475, zh_CN="你来了！请坐。希望你喜欢私人茶会。", },
	[185476] = {id=185476, zh_CN="她示意你入座，亲自为你斟上一杯香气馥郁的花茶。", },
	[185477] = {id=185477, zh_CN="晚宴那天，能与你交谈，我……感到非常愉快。", },
	[185478] = {id=185478, zh_CN="您身上有一种……独特的气质，在方舟并不常见。", },
	[185479] = {id=185479, zh_CN="这让我很希望能与您……多交流，成为朋友。", },
	[185480] = {id=185480, zh_CN="是否读心。", },
	[185481] = {id=185481, zh_CN="理智检定。", },
	[185482] = {id=185482, zh_CN="魅力检定。", },
	[185483] = {id=185483, zh_CN="幸运检定。", },
	[185484] = {id=185484, zh_CN="不读心。", },
	[185485] = {id=185485, zh_CN="但你敏锐地捕捉到一丝更深的考量——她在评估，在衡量。", },
	[185486] = {id=185486, zh_CN="但你敏锐地捕捉到一丝更深的考量——她在评估，在衡量。", },
	[185487] = {id=185487, zh_CN="但你敏锐地捕捉到一丝更深的考量——她在评估，在衡量。", },
	[185488] = {id=185488, zh_CN="一个轻柔的声线在你脑海想起，似乎是阿加莎的声音。", },
	[185489] = {id=185489, zh_CN="……希望这份友好能让他放下戒心。", },
	[185490] = {id=185490, zh_CN="作为完全中立的变量，他的观察视角或许能提供意想不到的价值……", },
	[185491] = {id=185491, zh_CN="朋友……如果能有一个不涉及利益的朋友……似乎也还不错呢~", },
	[185492] = {id=185492, zh_CN="你什么都没听见，阿加莎的心墙比你想象的要厚。", },
	[185493] = {id=185493, zh_CN="见玩家没立刻回应，自然地转换话题，指向旁边画架上的一幅抽象油画。", },
	[185494] = {id=185494, zh_CN="她眼神发亮，似乎沉浸在了画幅中的哲学与色彩中。", },
	[185495] = {id=185495, zh_CN="你看这幅画，画师试图捕捉超新星爆发瞬间，展现出混沌之处的灭亡与新生之美。", },
	[185496] = {id=185496, zh_CN="色彩如此大胆奔放，线条却带着有序的韵律……", },
	[185497] = {id=185497, zh_CN="仿佛宇宙在狂欢中的一声叹息。", },
	[185498] = {id=185498, zh_CN="表现出浓厚兴趣。", },
	[185499] = {id=185499, zh_CN="星空真是太令人着迷了！将瞬间的宇宙暴力转化为永恒的艺术……", },
	[185500] = {id=185500, zh_CN="阿加莎公主对画作的解读让我豁然开朗！", },
	[185501] = {id=185501, zh_CN="是否读心。", },
	[185502] = {id=185502, zh_CN="理智检定。", },
	[185503] = {id=185503, zh_CN="魅力检定。", },
	[185504] = {id=185504, zh_CN="幸运检定。", },
	[185505] = {id=185505, zh_CN="不读心。", },
	[185506] = {id=185506, zh_CN="你也这么觉得吗？！", },
	[185507] = {id=185507, zh_CN="你也这么觉得吗？！", },
	[185508] = {id=185508, zh_CN="你也这么觉得吗？！", },
	[185509] = {id=185509, zh_CN="啊啊啊啊，他居然和我有一样的爱好~好开心！", },
	[185510] = {id=185510, zh_CN="哦，我刚刚是不是太失礼了，他没有发现吧/（ㄒoㄒ）/~~", },
	[185511] = {id=185511, zh_CN="似乎有一串尖叫声从你的脑海里路过，但你未能听清其中含义。", },
	[185512] = {id=185512, zh_CN="这位画师的作品总是充满原始野性的生命力，也许和他的妖灵族种族有关。", },
	[185513] = {id=185513, zh_CN="他还有一系列关于“深海”的作品，用色更加纯粹梦幻。", },
	[185514] = {id=185514, zh_CN="阿加莎滔滔不绝地分享着。", },
	[185515] = {id=185515, zh_CN="你原本想要伸出制止的手也放了下来，托着腮望着她卸下一丝公主的姿态。", },
	[185516] = {id=185516, zh_CN="尝试理解，但有点困惑。", },
	[185517] = {id=185517, zh_CN="呃……很独特的视角。那些漩涡般的蓝色，是代表星云吗？", },
	[185518] = {id=185518, zh_CN="是否读心。", },
	[185519] = {id=185519, zh_CN="理智检定。", },
	[185520] = {id=185520, zh_CN="魅力检定。", },
	[185521] = {id=185521, zh_CN="幸运检定。", },
	[185522] = {id=185522, zh_CN="不读心。", },
	[185523] = {id=185523, zh_CN="是的。我很喜欢这位作家，他的作品总是充满原始野性的生命力……", },
	[185524] = {id=185524, zh_CN="是的。我很喜欢这位作家，他的作品总是充满原始野性的生命力……", },
	[185525] = {id=185525, zh_CN="是的。我很喜欢这位作家，他的作品总是充满原始野性的生命力……", },
	[185526] = {id=185526, zh_CN="唉，好像搞砸了……", },
	[185527] = {id=185527, zh_CN="怎么连“天外之物”都无法理解我对于星空的喜爱，/（ㄒoㄒ）/~~", },
	[185528] = {id=185528, zh_CN="似乎有一声声叹息从你的脑海里路过，但你未能听清其中含义。", },
	[185529] = {id=185529, zh_CN="不理解，直接表达抱歉。", },
	[185530] = {id=185530, zh_CN="说实话，这画有点……太抽象了，我看不太懂具体想表达什么。", },
	[185531] = {id=185531, zh_CN="是否读心。", },
	[185532] = {id=185532, zh_CN="理智检定。", },
	[185533] = {id=185533, zh_CN="魅力检定。", },
	[185534] = {id=185534, zh_CN="幸运检定。", },
	[185535] = {id=185535, zh_CN="不读心。", },
	[185536] = {id=185536, zh_CN="好吧，看来你不喜欢这些。", },
	[185537] = {id=185537, zh_CN="好吧，看来你不喜欢这些。", },
	[185538] = {id=185538, zh_CN="好吧，看来你不喜欢这些。", },
	[185539] = {id=185539, zh_CN="唉，好像搞砸了……", },
	[185540] = {id=185540, zh_CN="怎么连“天外之物”都无法理解我对于星空的喜爱，/（ㄒoㄒ）/~~", },
	[185541] = {id=185541, zh_CN="似乎有一声声叹息从你的脑海里路过，但你未能听清其中含义。", },
	[185542] = {id=185542, zh_CN="就在这时，一名年轻侍从端着新烤制的茶点走来。", },
	[185543] = {id=185543, zh_CN="侍从脚下被藤蔓绊了一下，手中的托盘倾斜，精美的瓷杯眼看就要摔落！", },
	[185544] = {id=185544, zh_CN="啊！公主殿下！对不……", },
	[185545] = {id=185545, zh_CN="阿加莎的反应快得惊人。她几乎是下意识地伸手去扶托盘。", },
	[185546] = {id=185546, zh_CN="虽然未能完全阻止茶杯翻倒，但却改变了茶杯摔落的轨迹，避免了烫伤到侍从的手臂。", },
	[185547] = {id=185547, zh_CN="她眉头都没皱一下，第一时间看向侍从，眼神充满关切。", },
	[185548] = {id=185548, zh_CN="别慌！亲爱的，你没事吧？有没有烫到？！", },
	[185549] = {id=185549, zh_CN="公主殿下！我……我没事！可是您的裙子……您的手！都是我的错！", },
	[185550] = {id=185550, zh_CN="阿加莎迅速抽出手帕按在自己手背。", },
	[185551] = {id=185551, zh_CN="没事就好。一点茶水而已。快去用冷水冲洗一下你的手，换身衣服。", },
	[185552] = {id=185552, zh_CN="这里我来处理。记住，安全第一。", },
	[185553] = {id=185553, zh_CN="理智检定。", },
	[185554] = {id=185554, zh_CN="魅力检定。", },
	[185555] = {id=185555, zh_CN="幸运检定。", },
	[185556] = {id=185556, zh_CN="不读心。", },
	[185557] = {id=185557, zh_CN="没事就好。一点茶水而已。快去用冷水冲洗一下你的手，换身衣服。这里我来处理。记住，安全第一。", },
	[185558] = {id=185558, zh_CN="没事就好。一点茶水而已。快去用冷水冲洗一下你的手，换身衣服。这里我来处理。记住，安全第一。", },
	[185559] = {id=185559, zh_CN="没事就好。一点茶水而已。快去用冷水冲洗一下你的手，换身衣服。这里我来处理。记住，安全第一。", },
	[185560] = {id=185560, zh_CN="呜呜呜，好痛~好痛好痛好痛……", },
	[185561] = {id=185561, zh_CN="希望侍从别太自责……裙子脏了等下还有日程……", },
	[185562] = {id=185562, zh_CN="得让侍女准备替换的……在%PlayerName面前失态了……", },
	[185563] = {id=185563, zh_CN="阿加莎你做的很棒了~镇定，镇定镇定。", },
	[185564] = {id=185564, zh_CN="电光火石间，你什么都没听到。", },
	[185565] = {id=185565, zh_CN="她看着侍从慌乱离开，才轻轻舒了一口气。", },
	[185566] = {id=185566, zh_CN="手指无意识地摩挲着茶杯光滑的边缘，眼神掠过一丝疲惫和紧张。", },
	[185567] = {id=185567, zh_CN="一抹阳光倏然出现在阿加莎的面前，那是一朵金黄色的金合欢，在阳光下显得格外耀眼。", },
	[185568] = {id=185568, zh_CN="毛茸茸的花瓣在微风中轻轻摇曳，如同啦啦队花球在鼓舞人心。", },
	[185569] = {id=185569, zh_CN="她望着这朵金合欢飘向对面，最终融入你的体内。", },
	[185570] = {id=185570, zh_CN="理智检定。", },
	[185571] = {id=185571, zh_CN="魅力检定。", },
	[185572] = {id=185572, zh_CN="幸运检定。", },
	[185573] = {id=185573, zh_CN="不读心。", },
	[185574] = {id=185574, zh_CN="一抹阳光倏然出现在阿加莎的面前，那是一朵金黄色的金合欢，在阳光下显得格外耀眼，毛茸茸的花瓣在微风中轻轻摇曳，如同啦啦队花球在鼓舞人心，阿加莎似乎感受到一股从心火中燃烧而起的活力与希望，她望着这朵金合欢飘向对面，最终融入你的体内。", },
	[185575] = {id=185575, zh_CN="一抹阳光倏然出现在阿加莎的面前，那是一朵金黄色的金合欢，在阳光下显得格外耀眼，毛茸茸的花瓣在微风中轻轻摇曳，如同啦啦队花球在鼓舞人心，阿加莎似乎感受到一股从心火中燃烧而起的活力与希望，她望着这朵金合欢飘向对面，最终融入你的体内。", },
	[185576] = {id=185576, zh_CN="一抹阳光倏然出现在阿加莎的面前，那是一朵金黄色的金合欢，在阳光下显得格外耀眼，毛茸茸的花瓣在微风中轻轻摇曳，如同啦啦队花球在鼓舞人心，阿加莎似乎感受到一股从心火中燃烧而起的活力与希望，她望着这朵金合欢飘向对面，最终融入你的体内。", },
	[185577] = {id=185577, zh_CN="毛茸茸的好可爱~感觉心灵都得到了振奋呢？", },
	[185578] = {id=185578, zh_CN="唉？飞向了%PlayerName，让善解人意的公主殿下出马吧~", },
	[185579] = {id=185579, zh_CN="忽如其来的情绪花种，打乱了你的心绪，读心的能力也就消散了。", },
	[185580] = {id=185580, zh_CN="获得情绪花种【金合欢（阳）】“就算星夜之下，也被阳光偏爱的孩子。”", },
	[185581] = {id=185581, zh_CN="茶会继续，气氛因小插曲略显微妙。阿加莎很快调整好状态，但那份放松感减弱了些。", },
	[185582] = {id=185582, zh_CN="茶会接近尾声时，她将一枚压着干燥百合花、散发着淡雅香气的书签轻轻推到你的面前。", },
	[185583] = {id=185583, zh_CN="一点小小的纪念，感谢您今日的陪伴。", },
	[185584] = {id=185584, zh_CN="看来我的判断失误了，希望下次在邀请你来的时候，我能投其所好，找到你所喜欢的事物。", },
	[185585] = {id=185585, zh_CN="其实我可以告诉你的。", },
	[185586] = {id=185586, zh_CN="拜托请让我猜一猜吧。", },
	[185587] = {id=185587, zh_CN="这是一个有趣的游戏，不是吗？", },
	[185588] = {id=185588, zh_CN="看来我的判断失误了。", },
	[185589] = {id=185589, zh_CN="您对艺术的见解如此独到，令人欣喜。", },
	[185590] = {id=185590, zh_CN="主动邀约下次见面。", },
	[185591] = {id=185591, zh_CN="或许可以和公主约定下次的艺术沙龙？", },
	[185592] = {id=185592, zh_CN="再好不过了。", },
	[185593] = {id=185593, zh_CN="如果您有兴趣，改日或许可以邀请您参观我的私人收藏馆？", },
	[185594] = {id=185594, zh_CN="那里有些……不太方便在公众场合展示的小爱好，也许能给您带来些不一样的灵感。", },
	[185595] = {id=185595, zh_CN="我想你一定会喜欢的。", },
	[185596] = {id=185596, zh_CN="想要下意识地开口答应，但却想到什么，缓缓合上了嘴巴。", },
	[185597] = {id=185597, zh_CN="如果公务不忙的话，我一定如约参加。", },
	[185598] = {id=185598, zh_CN="接受赞美。", },
	[185599] = {id=185599, zh_CN="阿加莎公主的智慧与见解也让人称叹。", },
	[185600] = {id=185600, zh_CN="一定付出了很多努力吧。", },
	[185601] = {id=185601, zh_CN="都是我的责任。", },
	[185602] = {id=185602, zh_CN="起身，恢复了她完美的公主仪态，屈膝行了一个优雅的告别礼。", },
	[185603] = {id=185603, zh_CN="今日的茶会非常愉快。希望很快能再次与您畅谈。", },
	[185604] = {id=185604, zh_CN="无论是艺术，星空，还是……方舟的风土人情。", },
	[185605] = {id=185605, zh_CN="请随时书信联系我。", },
	[185606] = {id=185606, zh_CN="她的笑容完美无瑕，晚宴时那层若有若无的晨雾似乎又重新笼罩上来。", },
	[185607] = {id=185607, zh_CN="你与阿加莎告别，阿加莎目送着你的离开。", },
	[185608] = {id=185608, zh_CN="她独自站在花房的紫藤花下，看着那枚被茶水染上淡淡渍痕的茶杯。", },
	[185609] = {id=185609, zh_CN="指尖轻轻拂过被烫红的手背。露出一丝不易察觉的复杂神情。", },
	[185610] = {id=185610, zh_CN="理智检定。", },
	[185611] = {id=185611, zh_CN="魅力检定。", },
	[185612] = {id=185612, zh_CN="幸运检定。", },
	[185613] = {id=185613, zh_CN="不读心。", },
	[185614] = {id=185614, zh_CN="你与阿加莎告别，阿加莎目送着你的离开，她独自站在花房的紫藤花下，看着那枚被茶水染上淡淡渍痕的茶杯，指尖轻轻拂过被烫红的手背。露出一丝不易察觉的、混杂着疲惫、期待和深深孤独的复杂神情。", },
	[185615] = {id=185615, zh_CN="你与阿加莎告别，阿加莎目送着你的离开，她独自站在花房的紫藤花下，看着那枚被茶水染上淡淡渍痕的茶杯，指尖轻轻拂过被烫红的手背。露出一丝不易察觉的、混杂着疲惫、期待和深深孤独的复杂神情。", },
	[185616] = {id=185616, zh_CN="你与阿加莎告别，阿加莎目送着你的离开，她独自站在花房的紫藤花下，看着那枚被茶水染上淡淡渍痕的茶杯，指尖轻轻拂过被烫红的手背。露出一丝不易察觉的、混杂着疲惫、期待和深深孤独的复杂神情。", },
	[185617] = {id=185617, zh_CN="抓不住的气声忽然闯入你的脑海，也许连阿加莎都没能意识到她自己的渴望。", },
	[185618] = {id=185618, zh_CN="下次……或许可以让他看看我那只会唱歌的机械小鸟 ……", },
	[185619] = {id=185619, zh_CN="阳光透过花架，在阿加莎精致的侧脸上投下斑驳的光影。", },
	[185620] = {id=185620, zh_CN="诺亚方舟的公主，在无人注视的角落，短暂地做了一秒钟名叫“莎莎”的女孩。", },
	[185626] = {id=185626, zh_CN="当月光拂过起居室的窗棂，我私心提笔向你倾诉心中的烦忧。\n除了你，我不知道该向谁倾诉困扰。作为方舟的公主殿下，我被我的民众托举而起，我的所言所行承载着他们的期望，他们的目光环绕在我周身，赋予我无上的荣光。\n除了你，我面对任何人，都无法放下权衡。与他们诉说我的烦闷，令我心有悔意与愧疚。我想要找寻一处休息之地，或许你会有办法的，对吗？\n期望你能理解我的孤立无援，和你诉说这些已经用尽我的勇气，希望没有打扰到你。如果愿意，请带着这封信来找我吧。我现在需要你。\n愿你一切安好。\n——ThaTha", },
	[185627] = {id=185627, zh_CN="亲爱的%PlayerName阁下，祝你午安。", },
	[185628] = {id=185628, zh_CN="离开。", },
	[185629] = {id=185629, zh_CN="再会了，我的朋友。", },
	[185630] = {id=185630, zh_CN="【伪装马甲初体验】", },
	[185631] = {id=185631, zh_CN="阿加莎公主！我来了。", },
	[185632] = {id=185632, zh_CN="你还好吗？", },
	[185633] = {id=185633, zh_CN="亲爱的%PlayerName，请小声一点。", },
	[185634] = {id=185634, zh_CN="你，还，好，吗？", },
	[185635] = {id=185635, zh_CN="说实话，不是很好。", },
	[185636] = {id=185636, zh_CN="我想我现在真的需要休息一下。", },
	[185637] = {id=185637, zh_CN="你需要离开这个环境才好。", },
	[185638] = {id=185638, zh_CN="我带你偷偷出去转转如何？", },
	[185639] = {id=185639, zh_CN="我想带你出去，哪怕只是短暂的时光，呼吸自由的空气会对你有帮助的。", },
	[185640] = {id=185640, zh_CN="我们可以……", },
	[185641] = {id=185641, zh_CN="%PlayerName，不可以的。", },
	[185642] = {id=185642, zh_CN="我的安全不完全属于我，在外面闲逛太过冒险。", },
	[185643] = {id=185643, zh_CN="我不能让自己陷入风险之中。", },
	[185644] = {id=185644, zh_CN="失落。", },
	[185645] = {id=185645, zh_CN="去我的家园呢？我有信心那里足够安全。", },
	[185646] = {id=185646, zh_CN="我只是想暂时让你逃离这些“责任”，哪怕只有几个小时？", },
	[185647] = {id=185647, zh_CN="……", },
	[185648] = {id=185648, zh_CN="好吧，但你必须帮我伪装一下，不能让人认出我来。", },
	[185649] = {id=185649, zh_CN="我会全力以赴的！", },
	[185650] = {id=185650, zh_CN="【换装关卡】", },
	[185651] = {id=185651, zh_CN="很漂亮。", },
	[185652] = {id=185652, zh_CN="谢谢。", },
	[185653] = {id=185653, zh_CN="现在，我可以直呼你的名字吗？", },
	[185654] = {id=185654, zh_CN="当然可以。", },
	[185655] = {id=185655, zh_CN="阿加莎……", },
	[185656] = {id=185656, zh_CN="是否读心。", },
	[185657] = {id=185657, zh_CN="不读心。", },
	[185658] = {id=185658, zh_CN="魅力检定。", },
	[185659] = {id=185659, zh_CN="理智检定。", },
	[185660] = {id=185660, zh_CN="你好像错过了阿加莎的心声。", },
	[185661] = {id=185661, zh_CN="【第一次被直呼其名，好奇怪的感觉。心脏跳得好快！】", },
	[185662] = {id=185662, zh_CN="我们走吧。", },
	[185663] = {id=185663, zh_CN="我们走吧。", },
	[185664] = {id=185664, zh_CN="我们走吧。", },
	[185665] = {id=185665, zh_CN="我们走吧。", },
	[185666] = {id=185666, zh_CN="我们走吧。", },
	[185667] = {id=185667, zh_CN="我们走吧。", },
	[185668] = {id=185668, zh_CN="你的家园中，阳光透过落地窗洒进来。", },
	[185669] = {id=185669, zh_CN="阿加莎略显拘谨地坐在会客区里，长发简单束起……", },
	[185670] = {id=185670, zh_CN="她的脸上只化了淡妆，努力让自己看起来像个“普通人”。", },
	[185671] = {id=185671, zh_CN="感觉怎么样？", },
	[185672] = {id=185672, zh_CN="是不是和你在方舟……嗯，办公室的感觉很不一样？", },
	[185673] = {id=185673, zh_CN="接过茶杯，指尖小心地触碰杯壁，眼神好奇地打量着周围。", },
	[185674] = {id=185674, zh_CN="非常……不同，谢谢你的茶。", },
	[185675] = {id=185675, zh_CN="这里……很安静。", },
	[185676] = {id=185676, zh_CN="没有侍从待命在我的身边，我不需要时刻考虑自己仪态是否符合公主的礼仪。", },
	[185677] = {id=185677, zh_CN="我好像真正地在生活。", },
	[185678] = {id=185678, zh_CN="这种感觉，很新奇。", },
	[185679] = {id=185679, zh_CN="是啊，这就是大家的日常。 想要做什么，只要不打扰别人，基本都可以。", },
	[185680] = {id=185680, zh_CN="我不知道该做什么，我平时会看书，但这里没有我可以读的书。", },
	[185681] = {id=185681, zh_CN="比如……记录下这一刻怎么样？记录下普通人阿加莎的一天？", },
	[185682] = {id=185682, zh_CN="记录？像公关摄影师那样吗？", },
	[185683] = {id=185683, zh_CN="需要我摆出什么姿势吗？", },
	[185684] = {id=185684, zh_CN="或者表情？我应该笑着还是严肃一点？", },
	[185685] = {id=185685, zh_CN="我好像太沉浸在我的世界里了，对不起。", },
	[185686] = {id=185686, zh_CN="我没有做过这样的活动，所以，我有点紧张。", },
	[185687] = {id=185687, zh_CN="不不不，那是工作。朋友之间记录生活，很随意的。", },
	[185688] = {id=185688, zh_CN="我们会把感情波动的瞬间定格下来，以后看到照片，当时的心情就好像活过来了一般。", },
	[185689] = {id=185689, zh_CN="重要的是那一刻的感受和分享的乐趣。", },
	[185690] = {id=185690, zh_CN="要不要试试？练习一下怎么被朋友拍照？", },
	[185691] = {id=185691, zh_CN="分享心情吗？", },
	[185692] = {id=185692, zh_CN="我可以试试看。", },
	[185693] = {id=185693, zh_CN="就从……你觉得这杯茶味道不错开始？", },
	[185694] = {id=185694, zh_CN="是否读心。", },
	[185695] = {id=185695, zh_CN="不读心。", },
	[185696] = {id=185696, zh_CN="魅力检定。", },
	[185697] = {id=185697, zh_CN="理智检定。", },
	[185698] = {id=185698, zh_CN="你好像错过一些心声。", },
	[185699] = {id=185699, zh_CN="【天啊，镜头对着我……不是那种官方镜头……是记录我喝茶？这太私人了！】", },
	[185700] = {id=185700, zh_CN="【脸好像有点烫……他会不会觉得我很笨拙？】", },
	[185701] = {id=185701, zh_CN="别紧张，阿加莎。不要把它当作拍照任务。", },
	[185702] = {id=185702, zh_CN="想想看，你现在只是在私人茶会上喝茶，你会做什么？", },
	[185703] = {id=185703, zh_CN="按照习惯表现出来就好了。我会捕捉你最真实的瞬间的。", },
	[185704] = {id=185704, zh_CN="“真实的瞬间”……", },
	[185705] = {id=185705, zh_CN="被你的话触动，深吸一口气，看向窗外。", },
	[185706] = {id=185706, zh_CN="她眼神渐渐柔和下来，低头看着茶杯，嘴角浮现一丝真切放松的微笑。", },
	[185707] = {id=185707, zh_CN="【拍照教程：阿加莎坐在沙发上，请拍下她“最真实的瞬间”，把美好的记忆留存下来吧。】", },
	[185708] = {id=185708, zh_CN="【提交照片，重新和阿加莎互动。】", },
	[185709] = {id=185709, zh_CN="迅速拿起手机，在她抬眼看过来时，捕捉到了那个自然流露的微笑。", },
	[185710] = {id=185710, zh_CN="对！就是这个感觉！", },
	[185711] = {id=185711, zh_CN="看！很自然，很放松。", },
	[185712] = {id=185712, zh_CN="这……真的是我？", },
	[185713] = {id=185713, zh_CN="镜头里的阿加莎褪去了精致的妆容和华服，时刻紧绷的姿态即使放松也保持着与生俱来的优雅气质。", },
	[185714] = {id=185714, zh_CN="而且，我们可以把这些觉得不错的照片或小视频，分享到社交媒体上。", },
	[185715] = {id=185715, zh_CN="朋友们互相点赞评论，这样就把自己的快乐分享出去了。", },
	[185716] = {id=185716, zh_CN="不过为了保护你的隐私，我们可以创建一个全新的、完全匿名的账号。", },
	[185717] = {id=185717, zh_CN="名字就叫…… “饮茶先啦”怎么样？", },
	[185718] = {id=185718, zh_CN="“饮茶先啦”……", },
	[185719] = {id=185719, zh_CN="我还挺喜欢的。", },
	[185720] = {id=185720, zh_CN="主动掏出通讯器，有些不熟练地点开应用商店。", },
	[185721] = {id=185721, zh_CN="我的账号都是外交部在管理，我应该怎么做，才能上传这个……嗯，记录我喝茶的“真实瞬间”？", },
	[185722] = {id=185722, zh_CN="【上传照片关卡—打开上传照片的玩法界面，点击添加文字，选择照片，发送。】", },
	[185723] = {id=185723, zh_CN="【内容：一条发送出去，是一张下午茶的照片，文案上写着“新朋友家的茶，很香。”】", },
	[185724] = {id=185724, zh_CN="商会某处偏僻、爬满藤蔓的角落。夜晚，远处传来城市节日的喧嚣声。阿加莎的身影悄悄闪出。", },
	[185725] = {id=185725, zh_CN="她卸下了标志性的盘发，柔顺的雾紫色长发披散着，用一条简单的蓝色丝带束起一部分。穿着一条款式简洁的白色棉质连衣裙，外面套了件浅米色开衫，脸上只有淡淡的裸妆，戴着一副小巧的无框眼镜。她紧张地四处张望，手指紧紧抓着开衫的衣襟。：衣服可能要修改，根据最终衣服模型来定。", },
	[185726] = {id=185726, zh_CN="这样……真的可以吗？不会被认出来吧？", },
	[185727] = {id=185727, zh_CN="希望看起来不太奇怪？", },
	[185728] = {id=185728, zh_CN="是否读心。", },
	[185729] = {id=185729, zh_CN="不读心。", },
	[185730] = {id=185730, zh_CN="魅力检定。", },
	[185731] = {id=185731, zh_CN="理智检定。", },
	[185732] = {id=185732, zh_CN="你好像错过了阿加莎的心声。", },
	[185733] = {id=185733, zh_CN="【天啊心跳快得像要蹦出来！比第一次主持晨会还紧张一百倍！】", },
	[185734] = {id=185734, zh_CN="【裙子会不会有褶皱？眼镜滑下来了……希望路灯够暗！千万不要有人认出我来。】", },
	[185735] = {id=185735, zh_CN="你现在看起来就像个刚下课的学生。放松点，你现在可是Momo，不会有人注意到我们的。", },
	[185736] = {id=185736, zh_CN="自然地伸出手。", },
	[185737] = {id=185737, zh_CN="犹豫了一下，还是轻轻搭上你的手，指尖微凉。", },
	[185738] = {id=185738, zh_CN="让我看看吧，你会带我去向何方。", },
	[185739] = {id=185739, },
	[185740] = {id=185740, zh_CN="热闹的节日市集。灯火璀璨，人声鼎沸，各种小吃香气混合，街头艺人表演吸引着人群。", },
	[185741] = {id=185741, zh_CN="阿加莎像第一次进游乐场的孩子，眼睛亮晶晶的，充满好奇。", },
	[185742] = {id=185742, zh_CN="哇……他们好厉害！", },
	[185743] = {id=185743, zh_CN="但还是要做好防护才对……哦不，我是说……这需要很强的技巧。", },
	[185744] = {id=185744, zh_CN="她意识到自己又用了“官方思维”，不好意思地吐了吐舌头。", },
	[185745] = {id=185745, zh_CN="你和阿加莎走到至一个卖可丽饼的摊位旁。", },
	[185746] = {id=185746, zh_CN="试试这个？经典草莓奶油味，市集必吃。", },
	[185747] = {id=185747, zh_CN="这个……卫生吗？我是说……看起来很好吃！", },
	[185748] = {id=185748, zh_CN="望着你递来的可丽饼，在你的期望与鼓励的目光下接过一份，小心地咬了一口，奶油沾到嘴角。", },
	[185749] = {id=185749, zh_CN="唔……好甜！但……非常有趣！", },
	[185750] = {id=185750, zh_CN="她像发现新大陆，又咬了一大口，眼睛满足地眯起。", },
	[185751] = {id=185751, zh_CN="来试试运气？", },
	[185752] = {id=185752, zh_CN="你想要哪个？", },
	[185753] = {id=185753, zh_CN="目标是那个丑萌丑萌的独角兽！", },
	[185754] = {id=185754, zh_CN="啊呀！好难！", },
	[185755] = {id=185755, zh_CN="屏住呼吸，全神贯注地盯着地上的玩偶，收腕，抛出！", },
	[185756] = {id=185756, zh_CN="我中了！看！小兔子！", },
	[185757] = {id=185757, zh_CN="她举起战利品，笑容灿烂，完全忘记了形象管理。", },
	[185758] = {id=185758, zh_CN="恭喜Momo首战告捷！战利品很可爱哦！", },
	[185759] = {id=185759, zh_CN="来试试运气？", },
	[185760] = {id=185760, zh_CN="忽然，人潮涌来，阿加莎被挤得一个踉跄，鼻梁上的眼镜差点掉落，阿加莎连忙扶起眼睛，惊魂未定。", },
	[185761] = {id=185761, zh_CN="啊！", },
	[185762] = {id=185762, zh_CN="对……对不起，人太多了……", },
	[185763] = {id=185763, zh_CN="没事，抓紧点安全。来，试试套圈？", },
	[185764] = {id=185764, zh_CN="接过圈，心思却明显不在游戏上，目光总是不自觉地瞟向你专注的侧脸。", },
	[185765] = {id=185765, zh_CN="呐！小兔子。", },
	[185766] = {id=185766, zh_CN="谢……谢谢。这个……很可爱。", },
	[185767] = {id=185767, zh_CN="她把小兔子紧紧抱在怀里。", },
	[185768] = {id=185768, zh_CN="是否读心。", },
	[185769] = {id=185769, zh_CN="不读心。", },
	[185770] = {id=185770, zh_CN="魅力检定。", },
	[185771] = {id=185771, zh_CN="理智检定。", },
	[185772] = {id=185772, zh_CN="你好像错过了阿加莎的心声。", },
	[185773] = {id=185773, zh_CN="【他的手好温暖……】", },
	[185774] = {id=185774, zh_CN="【阿加莎，清醒点！这只是一次……工作间隙中的休息！】", },
	[185775] = {id=185775, zh_CN="【但这个小兔子真的好可爱……】", },
	[185776] = {id=185776, zh_CN="来试试运气？", },
	[185777] = {id=185777, zh_CN="刚要点头，目光扫过旁边摊位挂着的、带有拒绝妖灵族光顾符号的装饰品，身体猛地一僵，下意识抓住你的胳膊想拉你离开。", },
	[185778] = {id=185778, zh_CN="我们……我们去那边看看吧！", },
	[185779] = {id=185779, zh_CN="声音带着一丝不易察觉的颤抖。", },
	[185780] = {id=185780, zh_CN="好，听你的。", },
	[185781] = {id=185781, zh_CN="阿加莎在一个妖灵族部落特色手工编织的摊位前阿加莎停下脚步，眼神复杂。", },
	[185782] = {id=185782, zh_CN="这个纹样……我在外交文献里见过。", },
	[185783] = {id=185783, zh_CN="它代表……勇气与守护，对吗？", },
	[185784] = {id=185784, zh_CN="阿加莎，这里人越来越多了，要不……我们先回去？", },
	[185785] = {id=185785, zh_CN="如释重负，但立刻涌上浓浓的歉意和失落，看向你的眼神充满挣扎。", },
	[185786] = {id=185786, zh_CN="对不起……我……我是不是扫兴了？", },
	[185787] = {id=185787, zh_CN="看着阿加莎的侧脸，越看越疑惑，忍不住轻轻碰了碰旁边你的胳膊，压低声音。", },
	[185788] = {id=185788, zh_CN="诶，先生，打扰一下……那位小姐……看着好眼熟啊？是不是……是不是阿加莎公主殿下？", },
	[185789] = {id=185789, zh_CN="您认错了吧？公主殿下怎么会在这里？", },
	[185790] = {id=185790, zh_CN="妈妈妈妈！是公主！电视里的漂亮公主！我想和公主拍照！", },
	[185791] = {id=185791, zh_CN="小男孩的声音不大不小，周围几个人都好奇地看了过来。阿加莎听到“公主”二字，身体瞬间僵住，脸上的笑容凝固了，下意识地后退半步，几乎要躲到你身后，手指紧张地攥紧了裙角。眼镜后的眼神充满了慌乱和一丝被戳穿的窘迫。", },
	[185792] = {id=185792, zh_CN="哎呀！真的是公主殿下！太荣幸了！", },
	[185793] = {id=185793, zh_CN="她拉着小男孩挤到阿加莎面前，激动又有些语无伦次。", },
	[185794] = {id=185794, zh_CN="殿下！真没想到能在这里遇见您！我……我和我家小宝，都是您的忠实粉丝！他天天嚷着要像公主一样勇敢！", },
	[185795] = {id=185795, zh_CN="那个……那个……能不能……求您和我们合个影？就一张！拜托了！", },
	[185796] = {id=185796, zh_CN="（她双手合十，眼神充满恳求。小男孩也仰着头，大眼睛亮晶晶地看着阿加莎。）", },
	[185797] = {id=185797, zh_CN="是否读心。", },
	[185798] = {id=185798, zh_CN="不读心。", },
	[185799] = {id=185799, zh_CN="魅力检定。", },
	[185800] = {id=185800, zh_CN="理智检定。", },
	[185801] = {id=185801, zh_CN="你好像错过了阿加莎的心声。", },
	[185802] = {id=185802, zh_CN="【完了……被认出来了！护卫呢？记者会不会在附近？】", },
	[185803] = {id=185803, zh_CN="【现在该怎么办？拒绝会让他们失望……可答应的话……】", },
	[185804] = {id=185804, zh_CN="我……这位女士，您可能……", },
	[185805] = {id=185805, zh_CN="她想再次否认，但看着小男孩纯真期待的眼神，话又咽了回去。她深吸一口气，属于公主的责任感和亲民形象占了上风，脸上勉强挤出一个温和但略显僵硬的标准微笑。", },
	[185806] = {id=185806, zh_CN="……好吧。只是一张快照，可以吗？", },
	[185807] = {id=185807, zh_CN="隔开阿加莎和母子俩。", },
	[185808] = {id=185808, zh_CN="用身躯将阿加莎与母子俩不动声色地隔离开来。", },
	[185809] = {id=185809, zh_CN="女士，请带着您的孩子随我去比较安静的地方好吗？", },
	[185810] = {id=185810, zh_CN="为了阿加莎殿下的安全考虑，我们悄悄地合影。", },
	[185811] = {id=185811, zh_CN="好好好。", },
	[185812] = {id=185812, zh_CN="平复母子俩的激动。", },
	[185813] = {id=185813, zh_CN="你好这位女士，阿加莎殿下已经答应您合影了，但希望您能保持镇定。", },
	[185814] = {id=185814, zh_CN="我想您也不想招来更多的人影响节日庆典是吧？", },
	[185815] = {id=185815, zh_CN="对对对，我们小声一点。", },
	[185816] = {id=185816, zh_CN="女士，请带着您的孩子随我去比较安静的地方好吗？", },
	[185817] = {id=185817, zh_CN="为了阿加莎殿下的安全考虑，我们悄悄地合影。", },
	[185818] = {id=185818, zh_CN="好好好。", },
	[185819] = {id=185819, zh_CN="安抚好母子俩，你引领着母子俩走在阿加莎身后，你目不转睛地注视着阿加莎挺直的背脊，想要用灼热的目光为她提供力量。", },
	[185820] = {id=185820, zh_CN="阿加莎在一处花坛停下脚步，她求助般地回头望向你。", },
	[185821] = {id=185821, zh_CN="两位，就在这里和殿下拍照，好吗？", },
	[185822] = {id=185822, zh_CN="太好了！太感谢您了殿下！小宝，快站好！要笑哦！", },
	[185823] = {id=185823, zh_CN="她赶紧把兴奋得蹦跳的小男孩按在身边，自己站在阿加莎另一侧。", },
	[185824] = {id=185824, zh_CN="这位先生，麻烦您帮我们拍一下好吗？用这个！小宝，别傻站着，快摆个帅气的姿势给公主看！", },
	[185825] = {id=185825, zh_CN="他立刻挺起小胸脯，一手叉腰，一手比了个自认很酷的“V”字，咧开嘴露出缺了颗门牙的笑容。", },
	[185826] = {id=185826, zh_CN="没问题！小宝，姿势很帅哦！公主殿下，您也放松点，看镜头！对，就这样，自然的笑容最好看！1， 2， 3……茄子！", },
	[185827] = {id=185827, zh_CN="你的语气轻松自然，像在帮普通朋友拍照，有效缓解了阿加莎的紧张。", },
	[185828] = {id=185828, zh_CN="在你自然的引导下，紧绷的肩膀微微放松，看着镜头里小男孩搞怪的样子，嘴角终于勾起一丝更真实的、带着点无奈的温柔笑意。", },
	[185829] = {id=185829, zh_CN="【拍照智能引导教程】", },
	[185830] = {id=185830, zh_CN="咔嚓——一张照片慢慢成像。 （接过手机查看，非常满意） 拍得太好了！谢谢殿下！", },
	[185831] = {id=185831, zh_CN="小宝，快谢谢公主殿下！不客气。祝你们节日愉快。", },
	[185832] = {id=185832, zh_CN="不客气。祝你们节日愉快。", },
	[185833] = {id=185833, zh_CN="她看向你，眼神带着一丝“快走”的暗示和完成“任务”后的轻微释然。", },
	[185834] = {id=185834, zh_CN="沉稳地接过手机，目光快速扫过周围环境确认安全，然后专注地看向镜头，声音温和但带着安抚的力量。", },
	[185835] = {id=185835, zh_CN="好的。殿下，请放松。小宝，你的姿势非常棒！看我这里……", },
	[185836] = {id=185836, zh_CN="1， 2， 3……", },
	[185837] = {id=185837, zh_CN="在你沉稳的声音中找到了依靠感，身体不自觉地微微向你所在方向倾斜了一点点。脸上飞起红霞。", },
	[185838] = {id=185838, zh_CN="【拍照智能引导教程】", },
	[185839] = {id=185839, zh_CN="咔嚓——一张照片慢慢成像。 （没注意到这个小细节，只顾着看照片）", },
	[185840] = {id=185840, zh_CN="哎呀拍得真精神！殿下您真美！小宝快谢谢！", },
	[185841] = {id=185841, zh_CN="心跳还未平复，强自镇定地点头，声音比平时更轻柔。", },
	[185842] = {id=185842, zh_CN="谢谢。祝你们玩得开心。", },
	[185843] = {id=185843, zh_CN="她匆匆瞥了你一眼，那眼神里有羞涩，有感激，也有一丝被触碰后的慌乱。", },
	[185844] = {id=185844, zh_CN="就在母亲递过手机时，阿加莎眼角的余光忽然瞥见不远处一个小摊上挂着的拒绝妖灵族光顾符号的装饰品，她瞳孔猛地一缩！不顾形象地想要将自己藏起来。 （敏锐地察觉到阿加莎瞬间的僵硬和恐惧，立刻上前半步，巧妙地用身体挡住了阿加莎看向那个摊位的视线，同时迅速接过手机。", },
	[185845] = {id=185845, zh_CN="语气比前两条线更急切。", },
	[185846] = {id=185846, zh_CN="好的，马上拍。小宝看镜头！笑！", },
	[185847] = {id=185847, zh_CN="你几乎没怎么调整，快速按下快门 。", },
	[185848] = {id=185848, zh_CN="【拍照智能引导教程】", },
	[185849] = {id=185849, zh_CN="咔嚓——一张照片慢慢成像。", },
	[185850] = {id=185850, zh_CN="在你挡住视线的瞬间，身体几不可查地颤抖了一下，脸上勉强维持的笑容变得极其苍白脆弱。", },
	[185851] = {id=185851, zh_CN="（拿到照片，虽然觉得拍得有点仓促，但还是很开心。）", },
	[185852] = {id=185852, zh_CN="谢谢殿下！谢谢您！小宝……", },
	[185853] = {id=185853, zh_CN="没等小男孩道谢，就快速而略显生硬地打断，声音带着一丝不易察觉的急促和疏离。", },
	[185854] = {id=185854, zh_CN="不客气。请……请享受节日。", },
	[185855] = {id=185855, zh_CN="我们……快离开这里。", },
	[185856] = {id=185856, zh_CN="她的指尖冰凉，带着明显的惊悸。", },
	[185857] = {id=185857, zh_CN="就在这时，一位穿着便装但气质精悍的男子悄然出现在不远处，目光锁定阿加莎。", },
	[185858] = {id=185858, zh_CN="瞬间，阿加莎眼中所有的轻松、好奇、羞涩或挣扎如潮水般褪去，背脊挺得笔直，脸上迅速挂起一丝程式化的平静，她回头朝护卫方向几不可察地点了下头。", },
	[185859] = {id=185859, zh_CN="非常感谢您，今天……非常、非常难忘。", },
	[185860] = {id=185860, zh_CN="她快速行了一个极其微小、近乎朋友间点头礼的屈膝动作。", },
	[185861] = {id=185861, zh_CN="期待下次再会。", },
	[185862] = {id=185862, zh_CN="眼中闪过一丝俏皮，随即转身，步履从容却快速地走向护卫，那个穿着素裙的纤细背影很快融入节日的人潮中，消失不见。", },
	[185863] = {id=185863, zh_CN="阿加莎的私人收藏馆门口。这里没有王宫大厅的金碧辉煌，更像一个充满故事的老书房。厚重的橡木门虚掩着，门缝里透出温暖柔和的灯光和旧书、木头、干花混合的独特气息。", },
	[185864] = {id=185864, zh_CN="阿加莎亲自站在门口迎接，她穿着一条舒适的雾紫色羊毛长裙，长发松松挽起，脸上带着期待的微笑。", },
	[185865] = {id=185865, zh_CN="你来了！欢迎来到我的‘记忆方舟’。", },
	[185866] = {id=185866, zh_CN="这里存放的，都是时间留下的碎片，一些……对我有特殊意义的‘证物’。", },
	[185867] = {id=185867, zh_CN="今天想请你玩一个游戏，一个……只有你能参与的解谜游戏。", },
	[185868] = {id=185868, zh_CN="这里太棒了！像是走进了你的时间胶囊。", },
	[185869] = {id=185869, zh_CN="什么游戏？", },
	[185870] = {id=185870, zh_CN="一个寻‘我’游戏。线索就藏在这些物件里。我会给你第一个提示，然后你需要通过它们之间的关联，找到最终指向我的‘钥匙’，打开那扇门。", },
	[185871] = {id=185871, zh_CN="我在门后等你。准备好了吗？", },
	[185872] = {id=185872, zh_CN="当然！放马过来吧，‘Momo小姐。", },
	[185873] = {id=185873, zh_CN="这是第一个线索。", },
	[185874] = {id=185874, zh_CN="说完，她转身，像一尾灵活的鱼，滑入了藏品之间，很快不见了踪影。", },
	[185875] = {id=185875, zh_CN="侦察。", },
	[185876] = {id=185876, zh_CN="乐谱的角落上写着：凝固的时间之歌，答案在‘心跳’与‘回响’之间。", },
	[185877] = {id=185877, zh_CN="你想到了。", },
	[185878] = {id=185878, zh_CN="音乐。", },
	[185879] = {id=185879, zh_CN="结合乐谱，你联想到音乐或者乐器，很快在一个玻璃展柜里发现了一个精美的古董八音盒。", },
	[185880] = {id=185880, zh_CN="你选择……", },
	[185881] = {id=185881, zh_CN="观察八音盒。", },
	[185882] = {id=185882, zh_CN="你忽然想到“回响”，八音盒确实会产生很清脆的回响音乐，或许你找到关键了。", },
	[185883] = {id=185883, zh_CN="八音盒上有一个心形发条……", },
	[185884] = {id=185884, zh_CN="再找找别的。", },
	[185885] = {id=185885, zh_CN="八音盒旁边放着一本翻开的、阿加莎少女时代的日记。", },
	[185886] = {id=185886, zh_CN="上面稚嫩的笔迹写着：……收到这个八音盒，拧紧发条，听着叮咚声，感觉时间都变慢了，像被施了魔法……", },
	[185887] = {id=185887, zh_CN="八音盒！", },
	[185888] = {id=185888, zh_CN="你立刻抓起旁边的八音盒，盒子屁股有一个心形发条。", },
	[185889] = {id=185889, zh_CN="拧动发条。", },
	[185890] = {id=185890, zh_CN="你拧动八音盒发条，清脆的音乐流淌出来。", },
	[185891] = {id=185891, zh_CN="音乐停止时，八音盒底部一个小暗格“咔哒”一声弹开，里面竟然是一张小小的拍立得照片。", },
	[185892] = {id=185892, zh_CN="照片上正是上次市集，阿加莎拍下的、她拿着可丽饼嘴角沾着奶油的瞬间！她的脑袋只占了照片的二分之一，另一边的某个角落里，正是你的身影。", },
	[185893] = {id=185893, zh_CN="你的心跳微微加速，迅速将照片翻到背面。", },
	[185894] = {id=185894, zh_CN="照片背面写着一个词“Perspective” 和一个指向馆内某个方向的箭头。", },
	[185895] = {id=185895, zh_CN="再找找。", },
	[185896] = {id=185896, zh_CN="能形成回响的事物？", },
	[185897] = {id=185897, zh_CN="心形或者心脏意象？", },
	[185898] = {id=185898, zh_CN="立刻联想到关于心脏，心形的意象，在馆内搜寻起来。", },
	[185899] = {id=185899, zh_CN="你找到了不少东西，长腿长脚的心形玩偶；栩栩如生的心脏玻璃制品；闪烁着跳动心脏的数码屏幕……", },
	[185900] = {id=185900, zh_CN="你觉得什么比较可疑？", },
	[185901] = {id=185901, zh_CN="心形玩偶。", },
	[185902] = {id=185902, zh_CN="你捏了捏玩偶，里面除了软乎的棉花，似乎没有任何可疑的硬物……", },
	[185903] = {id=185903, zh_CN="玻璃制品。", },
	[185904] = {id=185904, zh_CN="你将玻璃心脏举到灯光下检查，似乎除了隐约能拼出奇怪图案，什么发现都没有……", },
	[185905] = {id=185905, zh_CN="数码屏幕。", },
	[185906] = {id=185906, zh_CN="你上前仔细端详了屏幕半天，除了每30秒重复一次的视频，一无所获。", },
	[185907] = {id=185907, zh_CN="放下，找点别的。", },
	[185908] = {id=185908, zh_CN="再观察观察。", },
	[185909] = {id=185909, zh_CN="时间一分一秒过去，你终于放弃了它，它并不是那个被阿加莎选中的幸运儿。", },
	[185910] = {id=185910, zh_CN="着箭头方向，你来到一个画架前。画架上蒙着布。掀开布，是一幅未完成的抽象画，色彩大胆泼辣，但构图有些混乱。", },
	[185911] = {id=185911, zh_CN="你选择……", },
	[185912] = {id=185912, zh_CN="观察四周。", },
	[185913] = {id=185913, zh_CN="你蹲下来四周瞥眼扫过，画架旁放着调色板和画笔。画架旁的小桌上，放着上次阿加莎写的一封信。", },
	[185914] = {id=185914, zh_CN="……有时候，跳出固有的框架，换个角度看世界，或许会有意想不到的风景……”", },
	[185915] = {id=185915, zh_CN="换个角度看世界？？", },
	[185916] = {id=185916, zh_CN="你一边思考着信中的信息，一边转换着方位观察画作……", },
	[185917] = {id=185917, zh_CN="忽然，你停在某个角度上，从这里往画作上看去，凹凸不平的干枯画料，似乎在光影间形成了有规则的线条。", },
	[185918] = {id=185918, zh_CN="分析画作。", },
	[185919] = {id=185919, zh_CN="你凑近仔细观察着画作，除了发现画作没有完成外，没有任何可疑的地方。", },
	[185920] = {id=185920, zh_CN="观察四周。", },
	[185921] = {id=185921, zh_CN="上手摸摸。", },
	[185922] = {id=185922, zh_CN="你伸手轻轻触摸画上的油料，已经干透，于是你便大胆地摸过画作，每个角落都不放过。", },
	[185923] = {id=185923, zh_CN="奇怪的凹凸，以及若隐若现的阴影，难道……", },
	[185924] = {id=185924, zh_CN="环顾四周，你找到一盏可调节角度的阅读灯，调整着灯光的角度照向画布。", },
	[185925] = {id=185925, zh_CN="当灯光以一个特定的斜角照射在画布上时，那些看似混乱的色块在墙上投射出一个清晰的影子——一个钥匙孔的形状！ 影子旁边，用极淡的铅笔写着什么。", },
	[185926] = {id=185926, zh_CN="你上前检查。", },
	[185927] = {id=185927, zh_CN="上面写着“Find the Lock” 。", },
	[185928] = {id=185928, zh_CN="钥匙孔……锁……你开始在馆内寻找可能隐藏锁孔的地方。", },
	[185929] = {id=185929, zh_CN="最终，你的目光落在了一排书架侧面一个不起眼的、装饰性的木雕纹路上。", },
	[185930] = {id=185930, zh_CN="其中一个纹路的中心，仔细看，正是一个小小的锁孔！", },
	[185931] = {id=185931, zh_CN="但钥匙在哪里？线索断了？", },
	[185932] = {id=185932, zh_CN="你回想之前的线索……", },
	[185933] = {id=185933, zh_CN="画作，视角，照片，八音盒，音乐。", },
	[185934] = {id=185934, zh_CN="视角，画作，市集照片，回响，八音盒。", },
	[185935] = {id=185935, zh_CN="画作，市集照片，视角，音乐，八音盒。", },
	[185936] = {id=185936, zh_CN="似乎没有什么关联，再想想？", },
	[185937] = {id=185937, zh_CN="Perspective”来自市集照片，市集照片来自八音盒，八音盒关联时间……", },
	[185938] = {id=185938, zh_CN="你再次看向那幅未完成的画。画的主题是什么？", },
	[185939] = {id=185939, zh_CN="你拿起旁边阿加莎常用的速写本翻看，里面夹着许多草图。其中一张，画的是一个女孩的背影，正透过一扇圆形的窗户眺望远方，窗框的形状……正是一个钥匙孔！速写下方写着：“Where I See You” （我看见你的地方）。", },
	[185940] = {id=185940, zh_CN="你猛地抬头，环顾四周。收藏馆唯一的窗户是方形的。", },
	[185941] = {id=185941, zh_CN="你想起第一次来参加阿加莎的茶会时，她坐在这里喝茶看风景的样子……", },
	[185942] = {id=185942, zh_CN="你快步走向收藏馆深处那扇紧闭的门，在门旁边的墙上，挂着一幅小尺寸的油画。", },
	[185943] = {id=185943, zh_CN="画中是你家园能看见的城市夜景，视角正是阿加莎当时坐的位置！", },
	[185944] = {id=185944, zh_CN="画的右下角，用极细的笔写着：“The Key is in the Gaze” （钥匙在凝视中）。", },
	[185945] = {id=185945, zh_CN="凝视……你站在门前，看着那扇紧闭的门。", },
	[185946] = {id=185946, zh_CN="再想想。", },
	[185947] = {id=185947, zh_CN="你想起阿加莎说“我在门后等你”。凝视……难道是……？", },
	[185948] = {id=185948, zh_CN="你凑近门上那个雕刻精美的猫眼（窥视孔），向内看去。里面一片漆黑。", },
	[185949] = {id=185949, zh_CN="你仔细观察发现猫眼可以左右转动，一共可以转动五次，每次都能听到咔哒声，你决定尝试一下", },
	[185950] = {id=185950, zh_CN="qte。", },
	[185951] = {id=185951, zh_CN="几秒钟后，门内传来轻微的“咔哒”声——门锁开了！", },
	[185952] = {id=185952, zh_CN="你推开门，里面是一个更私密、更温馨的小房间，更像一个画室。", },
	[185953] = {id=185953, zh_CN="阿加莎正坐在窗边的画架前，背对着门。听到开门声，她转过身，脸上是毫不掩饰的惊喜和赞赏的笑容。", },
	[185954] = {id=185954, zh_CN="太棒了！你竟然真的解开了！比我预想的快多了！那些线索……感觉如何？”", },
	[185955] = {id=185955, zh_CN="挺有意思的！没想到线索全部都是阿加莎的记忆呢！", },
	[185956] = {id=185956, zh_CN="嗯……听到自己那么……‘放肆’的笑声，有点不好意思。", },
	[185957] = {id=185957, zh_CN="恭喜你解密成功，作为奖励，带你看看这些‘证物’背后的故事。", },
	[185958] = {id=185958, zh_CN="看这个！我第一次独立主持小型外交晚宴时，紧张得手心全是汗，把演讲稿都捏成了咸菜干！", },
	[185959] = {id=185959, zh_CN="还有这个，学院时最好的朋友送的明信片，来自她家乡的海滩，颜色都快晒没了……", },
	[185960] = {id=185960, zh_CN="这副旧手套，是我偷偷跑去陆军训练营体验时磨破的，被父王发现后训了好久……", },
	[185961] = {id=185961, zh_CN="她走到最重要的一个展柜，里面整齐排列着她写过的所有信件，里面也有你与她互通过的信件，旁边贴着许多她手写的感想便签。", },
	[185962] = {id=185962, zh_CN="这些……就不用我多说了吧？伙伴的珍贵墨宝！", },
	[185963] = {id=185963, zh_CN="这个就不要看！", },
	[185964] = {id=185964, zh_CN="那你还作为线索。", },
	[185965] = {id=185965, zh_CN="…… 这是……？啊，这个！是我十三岁时的‘作品’，心情特别烦躁时画的。是不是以为是小孩子乱涂鸦？", },
	[185966] = {id=185966, zh_CN="其实……画的是我当时一直不能完美地记住所有公主礼仪，一气之下画的！", },
	[185967] = {id=185967, zh_CN="……小时候觉得这些像童话，现在只觉得……脖子会断。", },
	[185968] = {id=185968, zh_CN="这些信……是母亲年轻时，也曾收到的让她轻松的信件。", },
	[185969] = {id=185969, zh_CN="父亲说，那些信是支撑母亲度过最初艰难时光的力量。因为这样的文字……我一直憧憬着父母那样……最终相守。", },
	[185970] = {id=185970, zh_CN="抱歉，我聊的可能有点多了。", },
	[185971] = {id=185971, zh_CN="她拿起一个修复过的、带有明显妖灵族风格的花瓶，上面裂纹清晰可见。", },
	[185972] = {id=185972, zh_CN="看，象征和平的礼物。多么脆弱。一次误解，一次冲突，就能轻易打碎，再高明的修复也掩盖不了裂痕。", },
	[185973] = {id=185973, zh_CN="气氛沉重，她强颜欢笑，", },
	[185974] = {id=185974, zh_CN="至少画画不需要考虑种族……虽然画得也够糟。", },
	[185975] = {id=185975, zh_CN="谢谢您愿意走进这里，解开谜题，也……走进这些碎片。", },
	[185976] = {id=185976, zh_CN="分享这些……对我而言，是前所未有的信任。", },
	[185977] = {id=185977, zh_CN="她行了一个标准的、优雅的屈膝礼，这次更像是对这份信任的致意。", },
	[185978] = {id=185978, zh_CN="希望下次，“记忆方舟”还能有新的碎片与你分享。", },
	[185979] = {id=185979, zh_CN="再会了，我珍贵的朋友。", },
	[185980] = {id=185980, zh_CN="今天的谈话……请您务必保密。", },
	[185981] = {id=185981, zh_CN="她优雅地行礼，抬眼看向你，眼神深邃，带着一丝请求和深意。", },
	[185982] = {id=185982, zh_CN="关于未来……或许下次，我们可以更深入地……聊聊您的见解？我很好奇。", },
	[185983] = {id=185983, zh_CN="她微微侧身，避开你关切的目光，声音恢复了礼貌而疏离的距离感。", },
	[185984] = {id=185984, zh_CN="感谢您的到访。希望……希望您能理解方舟的立场和……历史的重量。再会。", },
	[185985] = {id=185985, zh_CN="说完，她几乎是立刻转身，留给你一个决绝而落寞的背影。", },
	[185986] = {id=185986, zh_CN="走到阿加莎身边，递给她一份装订精美的文件，声音低沉而清晰。", },
	[185987] = {id=185987, zh_CN="阿加莎，我想和你谈一件……超越“互勉”和“秘密基地”的事。一件关于我们未来，以及方舟未来的事。", },
	[185988] = {id=185988, zh_CN="转过身，接过文件，并未立刻翻开，雾紫色的眼眸直视你，带着属于公主的审慎。", },
	[185989] = {id=185989, zh_CN="这么正式？看来不是邀请我去看新的街头艺人。说吧，我听着。", },
	[185990] = {id=185990, zh_CN="她走回书桌旁，优雅地坐下，将文件放在桌上，手指无意识地摩挲着杯壁。", },
	[185991] = {id=185991, zh_CN="联姻。我向你，方舟的第一顺位继承人，提出联姻的请求。", },
	[185992] = {id=185992, zh_CN="阿加莎的手指瞬间收紧，杯中的液体微微晃动。她脸上完美的平静面具出现了一丝裂痕，眼神复杂地闪烁了一下，但没有打断。", },
	[185993] = {id=185993, zh_CN="门当户对。", },
	[185994] = {id=185994, zh_CN="我们现在门当户对。", },
	[185995] = {id=185995, zh_CN="我在米乐星球的影响力与声望已经不比你低了，况且我“天外来物”背景所吸引的独特资源网络，足以匹配整个方舟的需求。", },
	[185996] = {id=185996, zh_CN="我不是依附者，而是强力的盟友和支柱。", },
	[185997] = {id=185997, zh_CN="明星效应。", },
	[185998] = {id=185998, zh_CN="我们两位明星联姻所能制造的巨大流量效应是不可估计的。", },
	[185999] = {id=185999, zh_CN="我的“天外”身份自带话题性和神秘感，与方舟继承人联姻将是各大种族都瞩目的盛事，能极大提升方舟的软实力和形象，满足民众对王室新鲜活力的期待。", },
	[186000] = {id=186000, zh_CN="中立优势。", },
	[186001] = {id=186001, zh_CN="同时，我的背景不隶属于任何传统势力或对立种族，是天然的有利于你巩固政权的优势，能有效化解内部因传统联姻对象选择可能引发的争议。", },
	[186002] = {id=186002, zh_CN="你总不想内忧外患吧。", },
	[186003] = {id=186003, zh_CN="等待回应。", },
	[186004] = {id=186004, zh_CN="你没有要说的了，站在原地，等待着阿加莎的回应。", },
	[186005] = {id=186005, zh_CN="阿加莎沉默了很久。她终于翻开那份文件，里面是详尽的分析报告、以及一份初步的、条件异常优渥且对自己约束相对宽松的协议草案。她看得非常仔细，手指划过那些条款，眼神深邃难辨。", },
	[186006] = {id=186006, zh_CN="合上文件，抬起头，脸上已恢复平静，但眼底翻涌着激烈的思考。", },
	[186007] = {id=186007, zh_CN="你……准备得很充分。这份协议，几乎是在给我铺一条……相对自由的红毯。", },
	[186008] = {id=186008, zh_CN="但相比于上天的馈赠，它更像是一个卑鄙的陷阱。", },
	[186009] = {id=186009, zh_CN="我需要你足够打动我的理由，你的野心。", },
	[186010] = {id=186010, zh_CN="语气忽然软化，眨巴着眼睛可怜巴巴地盯着阿加莎。", },
	[186011] = {id=186011, zh_CN="自由与合拍。这还不够吗？", },
	[186012] = {id=186012, zh_CN="阿加莎，我知道你渴望什么。", },
	[186013] = {id=186013, zh_CN="比起其他候选人背后盘根错节的家族势力和对你一言一行的严苛审视……", },
	[186014] = {id=186014, zh_CN="……选择我，你受到的限制会少得多。我在米乐星球无亲无故，孑然一身。", },
	[186015] = {id=186015, zh_CN="某种意义上，你是‘捏着’我在这边的一切。", },
	[186016] = {id=186016, zh_CN="而且，我们确实……合拍。", },
	[186017] = {id=186017, zh_CN="不是吗？", },
	[186018] = {id=186018, zh_CN="和你在一起，无论是讨论艺术还是参加宴会，我都觉得……很有意思。", },
	[186019] = {id=186019, zh_CN="这种基础，难道不比纯粹的政治筹码更可靠吗？", },
	[186020] = {id=186020, zh_CN="利益，你分析得很透彻。", },
	[186021] = {id=186021, zh_CN="“天外身份”的中立性和明星效应，确实无可替代。", },
	[186022] = {id=186022, zh_CN="自由……你给的承诺也很诱人。", },
	[186023] = {id=186023, zh_CN="但是，婚姻不是商业并购。即使带着政治目的。", },
	[186024] = {id=186024, zh_CN="也站起身，走到她面前，保持着一个尊重但亲近的距离。", },
	[186025] = {id=186025, zh_CN="阿加莎，我不是在向你推销一份冰冷的合同。", },
	[186026] = {id=186026, zh_CN="我是在向你，这个人，提出一个共同缔造未来的邀请。", },
	[186027] = {id=186027, zh_CN="这份邀请里，有责任，有利益，也有……我希望能继续发展下去的感情基础。", },
	[186028] = {id=186028, zh_CN="看着你坦荡又带着一丝期待的眼神，她紧绷的肩膀微微放松，一丝极其浅淡、几乎不可见的红晕爬上耳尖。她低头，手指轻轻抚过杯壁。", },
	[186029] = {id=186029, zh_CN="……和你在一起，或许不那么累。", },
	[186030] = {id=186030, zh_CN="好。这份联姻提议，我……初步接受。", },
	[186031] = {id=186031, zh_CN="你眼中瞬间亮起光芒。", },
	[186032] = {id=186032, zh_CN="立刻抬手制止你的激动，语气恢复公主的冷静决断。", },
	[186033] = {id=186033, zh_CN="但是！有三个条件——", },
	[186034] = {id=186034, zh_CN="第一， 暂时绝对保密。 在时机成熟前，不能让外界知道一丝风声。", },
	[186035] = {id=186035, zh_CN="我需要时间……也需要你证明更多。", },
	[186036] = {id=186036, zh_CN="当然，秘密守护是我们的专长。", },
	[186037] = {id=186037, zh_CN="第二， 继续“努力”。 在感情上，我需要看到你不仅仅是“合拍”，而是……更深的投入和诚意。在能力上，我需要你巩固并提升你承诺的影响力，确保联姻公布时，你的“砝码”足够重，重到能堵住所有质疑的嘴。", },
	[186038] = {id=186038, zh_CN="乐意之至。无论是感情还是事业，我的“努力”永不停止。", },
	[186039] = {id=186039, zh_CN="第三， 我需要一个“观察期”。 观察我们是否真的能……在更大的压力和责任下，将这份‘合拍’转化为真正的……盟友，乃至……伴侣。", },
	[186040] = {id=186040, zh_CN="%PlayerName，别让我失望。", },
	[186041] = {id=186041, zh_CN="绝不会让你失望，阿加莎。", },
	[186042] = {id=186042, zh_CN="猜猜我是谁？没错啦，就是ThaTha，我发现我们已经很久没有互通信件了。\n我想你了。\n前段时间需要处理的工作很多，冷落了你对不起。我会好好经营我们之间的感情的，我保证。\n写信想邀请你来我的“秘密花房”，我们很久没度过独属于我们的二人世界了。\n你不会拒绝我的吧，等你。\n我和“惊喜”在这里等待你的到来。\n——ThaTha", },
	[186043] = {id=186043, zh_CN="阿加莎的私人画室，与连接着的收藏馆不同。这里更显凌乱随性，巨大的画布靠在墙边，未完成的作品色彩大胆奔放；地上散落着颜料管、画笔和沾满颜料的抹布；书架塞满了艺术书籍、乐谱和写满批注的小说；空气中弥漫着松节油、颜料和旧纸张的混合气息。", },
	[186044] = {id=186044, zh_CN="阿加莎背对着门，雾紫色长发用一根炭笔随意挽起，穿着一件沾满各色颜料的旧帆布罩衫，正专注地在一幅中型画布上涂抹。", },
	[186045] = {id=186045, zh_CN="嘿，Momo小姐，你的客人前来报到。", },
	[186046] = {id=186046, zh_CN="来得正好！快过来！", },
	[186047] = {id=186047, zh_CN="帮我看看这幅画……我快要在色彩里失去平衡了！", },
	[186048] = {id=186048, zh_CN="她快速在画布右下角抹上一笔浓烈的钴蓝。", },
	[186049] = {id=186049, zh_CN="玩家： （走近，站在她侧后方，避免打扰她作画，目光被画布吸引。）", },
	[186050] = {id=186050, zh_CN="【插画】", },
	[186051] = {id=186051, zh_CN="画面主体是混乱奔放的彩色斑点和线条，但在中心区域，却有一种奇异的、螺旋上升的秩序感，仿佛混沌中诞生的星系，又像是解构的城市脉络。", },
	[186052] = {id=186052, zh_CN="你在……画星空吗？", },
	[186053] = {id=186053, zh_CN="你在……画星空吗？", },
	[186054] = {id=186054, zh_CN="哇哦……星际的能量感……扑面而来！", },
	[186055] = {id=186055, zh_CN="看来我画的还不错。", },
	[186056] = {id=186056, zh_CN="塔希主义抽象表达？", },
	[186057] = {id=186057, zh_CN="塔希主义抽象表达艺术？", },
	[186058] = {id=186058, zh_CN="你居然知道塔希主义！！", },
	[186059] = {id=186059, zh_CN="你知道吗，抽象艺术表达里，我最喜欢的就是塔希主义模糊的表现，我认为是最能隐藏和流露画家感情和心灵的画风。", },
	[186060] = {id=186060, zh_CN="你在解构秩序？", },
	[186061] = {id=186061, zh_CN="你在尝试……解构秩序与混沌的边界？或者说……在无序中寻找内在的韵律？", },
	[186062] = {id=186062, zh_CN="倏然转身，脸蛋沾上几点柠檬黄的颜料，眼底满是不可置信。", },
	[186063] = {id=186063, zh_CN="对啊，结构秩序后对混乱的重新定义。", },
	[186064] = {id=186064, zh_CN="我一直都抓不住自己想要表达的东西，你居然一眼击中了这层薄纱！", },
	[186065] = {id=186065, zh_CN="是否读心。", },
	[186066] = {id=186066, zh_CN="不读心。", },
	[186067] = {id=186067, zh_CN="魅力检定。", },
	[186068] = {id=186068, zh_CN="理智检定。", },
	[186069] = {id=186069, zh_CN="你好像错过了阿加莎的心声。", },
	[186070] = {id=186070, zh_CN="【他真的懂！那些我表达不出的东西……】", },
	[186071] = {id=186071, zh_CN="【这就是灵魂伴侣间的……悸荡吗？】", },
	[186072] = {id=186072, zh_CN="静静欣赏。", },
	[186073] = {id=186073, zh_CN="你沉浸在阿加莎幽蓝色的艺术色彩中，似乎探寻到她隐藏在内心深处的最真实的情绪。", },
	[186074] = {id=186074, zh_CN="听着你的解读，眼神越来越亮，像是找到了失散已久的知己。她放下画笔，拉着你走到旁边堆满草稿的小桌旁，随手翻开一本速写本，里面是无数关于“混沌与秩序”的草图。", },
	[186075] = {id=186075, zh_CN="你知道吗？以前和别人聊我的画，聊我的这些……“胡思乱想”，我需要解释很多很多……", },
	[186076] = {id=186076, zh_CN="从构图意图到色彩理论，最后往往只能得到一个礼貌的微笑或者一句‘很有想法’。", },
	[186077] = {id=186077, zh_CN="那种感觉就像……就像隔着一层厚厚的毛玻璃说话。", },
	[186078] = {id=186078, zh_CN="只有自己回声的感觉，很不好。", },
	[186079] = {id=186079, zh_CN="所以……你才把想法藏在谜题和物件里珍藏起来？", },
	[186080] = {id=186080, zh_CN="嗯。直到遇见你。", },
	[186081] = {id=186081, zh_CN="我对乐符，对涂鸦的渴望，在和你的交流中，找到了出口。", },
	[186082] = {id=186082, zh_CN="我想要的那种……流动的，瞬间的，难以言喻的共鸣……", },
	[186083] = {id=186083, zh_CN="就这样来到我的身边。", },
	[186084] = {id=186084, zh_CN="阿加莎……不是因为我启发了你，而是因为你本身就是一个如此敏锐的观察者和表达者。", },
	[186085] = {id=186085, zh_CN="我的某句话，只是一颗小石子，恰好投入了你本就波澜壮阔的思想湖泊里，激起了一点涟漪而已。", },
	[186086] = {id=186086, zh_CN="真正的力量，来自你自己。", },
	[186087] = {id=186087, zh_CN="阿加莎被你真挚的话语触动，眼眶微微发热。她走到画室最里面一个蒙着布的架子前，深吸一口气，像是下定了某种决心。她掀开蒙布，露出里面一幅尺幅很小的画。", },
	[186088] = {id=186088, zh_CN="（画风极其稚嫩抽象，色彩混沌，笔触笨拙，像幼儿的涂鸦，但能隐约看出一个模糊的女性轮廓和一颗歪歪扭扭的星星。）", },
	[186089] = {id=186089, zh_CN="……这是我……大概七岁时的作品。", },
	[186090] = {id=186090, zh_CN="自画像？", },
	[186091] = {id=186091, zh_CN="看着这幅“糟糕”的画，没有笑，而是认真观察。", },
	[186092] = {id=186092, zh_CN="这是……你在画自己？", },
	[186093] = {id=186093, zh_CN="守护星？", },
	[186094] = {id=186094, zh_CN="看着这幅“糟糕”的画，没有笑，而是认真观察。", },
	[186095] = {id=186095, zh_CN="这是……你在画自己？还有……你的守护星？", },
	[186096] = {id=186096, zh_CN="对！连这个你都看出来了！", },
	[186097] = {id=186097, zh_CN="小时候我总是羡慕星星，觉得他们就是自由的象征，是我当时所向往的。", },
	[186098] = {id=186098, zh_CN="它很丑，技法一塌糊涂。", },
	[186099] = {id=186099, zh_CN="但它代表了我艺术探索的起点……", },
	[186100] = {id=186100, zh_CN="代表了我内心最原始、最笨拙也最真实的“呓语”。", },
	[186101] = {id=186101, zh_CN="她小心翼翼地从架子上取下这幅画，像捧着最珍贵的易碎品，转身郑重地递到你面前。", },
	[186102] = {id=186102, zh_CN="现在，我把它送给你。%PlayerName，谢谢你。", },
	[186103] = {id=186103, zh_CN="你愿意，成为我的锚点之一吗？", },
	[186104] = {id=186104, zh_CN="伸出双手，极其郑重地接过那幅画，仿佛接过一颗跳动的心。", },
	[186105] = {id=186105, zh_CN="我的荣幸。", },
	[186106] = {id=186106, zh_CN="这是我的荣幸，阿加莎。", },
	[186107] = {id=186107, zh_CN="像星星一样守护你。", },
	[186108] = {id=186108, zh_CN="我会像守护最珍贵的星辰一样，守护这份友情。", },
	[186109] = {id=186109, zh_CN="心口灵魂常在。", },
	[186110] = {id=186110, zh_CN="你的灵魂激荡，随时都在这里。", },
	[186111] = {id=186111, zh_CN="一言为定！", },
	[186112] = {id=186112, zh_CN="你和阿加莎两只手紧紧握在一起，手上还沾着未干的颜料，两个人笑着瘫倒在地。", },
	[186113] = {id=186113, zh_CN="又是一天，阿加莎与你独自约会的私人茶会……", },
	[186114] = {id=186114, zh_CN="靠在舒适的沙发里，看着阿加莎娴熟地泡着花果茶。", },
	[186115] = {id=186115, zh_CN="时间过得真快。还记得我们第一次正式见面吗？", },
	[186116] = {id=186116, zh_CN="在那个晚宴上，我紧张得差点把茶水洒在你裙子上。", },
	[186117] = {id=186117, zh_CN="将一杯香气四溢的花果茶递给你，优雅地坐下，眼中带着笑意。", },
	[186118] = {id=186118, zh_CN="怎么会忘？没过多久，你便带着那么厚的举证来“威胁”我联姻。", },
	[186119] = {id=186119, zh_CN="没想到竟然变成我们交往密切的开端。", },
	[186120] = {id=186120, zh_CN="没想到我们竟成了最合拍的搭档，最信任的朋友……", },
	[186121] = {id=186121, zh_CN="放下茶杯，指尖无意识地在杯沿轻轻划过，气氛忽然变得有些微妙。", },
	[186122] = {id=186122, zh_CN="最合拍的搭档，最信任的朋友……吗？", },
	[186123] = {id=186123, zh_CN="怎么会忘？那天之后，我怀着试探的心理约见你，也是在这里。", },
	[186124] = {id=186124, zh_CN="没想到竟然变成我们交往密切的开端。", },
	[186125] = {id=186125, zh_CN="没想到我们竟成了最信任的伙伴，最好的朋友……", },
	[186126] = {id=186126, zh_CN="放下茶杯，指尖无意识地在杯沿轻轻划过，气氛忽然变得有些微妙。", },
	[186127] = {id=186127, zh_CN="最信任的伙伴，最好的朋友……吗？", },
	[186128] = {id=186128, zh_CN="她抬起头，直视你的眼睛，那里面不再是单纯的友谊，而是涌动着一股更深沉的情愫。", },
	[186129] = {id=186129, zh_CN="那……有没有可能，再进一步呢？", },
	[186130] = {id=186130, zh_CN="进一步？你的意思是……", },
	[186131] = {id=186131, zh_CN="深吸一口气，脸上泛起淡淡的红晕，但眼神坚定而坦率，带着公主特有的优雅和一丝难得的紧张。", },
	[186132] = {id=186132, zh_CN="我的意思是……我们之间，早就超越了普通的友谊，不是吗？", },
	[186133] = {id=186133, zh_CN="过去我们相知相识的日子里，我看着你一步步成长，变得如此耀眼。", },
	[186134] = {id=186134, zh_CN="我们分享喜悦，分担忧愁，彼此理解，互相支持……", },
	[186135] = {id=186135, zh_CN="她转过身，面对你，露出一个既温柔又带着点羞涩的微笑。", },
	[186136] = {id=186136, zh_CN="而且，我觉得你应该可以通过我的试用期了。", },
	[186137] = {id=186137, zh_CN="考察期总要有个尽头吧。", },
	[186138] = {id=186138, zh_CN="虽然你还算不上最佳的人选……", },
	[186139] = {id=186139, zh_CN="但连那些挑剔的王室顾问们，也开始觉得你这位‘青年才俊’是个‘不错的人选’了。", },
	[186140] = {id=186140, zh_CN="心中巨大的喜悦涌上来，你立刻起身走到她面前。", },
	[186141] = {id=186141, zh_CN="阿加莎……你是说……", },
	[186142] = {id=186142, zh_CN="我是说，既然我们感情这么好，你的事业也蒸蒸日上，公众形象无可挑剔……", },
	[186143] = {id=186143, zh_CN="她伸出手，轻轻抚平你衣服上并不存在的褶皱，动作带着亲昵。", },
	[186144] = {id=186144, zh_CN="那么，我们这位“有名无实”先生，是不是……可以考虑坐实身份了？", },
	[186145] = {id=186145, zh_CN="或许我们可以考虑一下升级成“有名有实”的身份呢？", },
	[186146] = {id=186146, zh_CN="正式的培养感情，你觉得怎么样？", },
	[186147] = {id=186147, zh_CN="不是为了任何人，只为了我们自己，为了这份……水到渠成的感情。", },
	[186148] = {id=186148, zh_CN="再也抑制不住内心的激动，一把将她拥入怀中，声音带着难以置信的喜悦。", },
	[186149] = {id=186149, zh_CN="真的吗！！这是我梦寐以求的事情！", },
	[186150] = {id=186150, zh_CN="什么“觉得怎么样”？这简直是世界上最好的提议！", },
	[186151] = {id=186151, zh_CN="你知道吗？我一直想着在努力一点，等我足够强大，能堂堂正正站在你身边，让所有人都无话可说！", },
	[186152] = {id=186152, zh_CN="在你怀里笑得明媚动人，之前的紧张一扫而空。", },
	[186153] = {id=186153, zh_CN="傻瓜，你早就可以堂堂正正站在我身边了。不过现在嘛……", },
	[186154] = {id=186154, zh_CN="我们可以更理直气壮一点。", },
	[186155] = {id=186155, zh_CN="那么，准备好迎接全新的身份和责任了吗？", },
	[186156] = {id=186156, zh_CN="笑着吻了吻她的发顶。", },
	[186157] = {id=186157, zh_CN="只要女主角是你，我都奉陪到底。", },
	[186158] = {id=186158, zh_CN="城堡下的喷泉广场上， 晴朗的白天，彩旗飘扬。巨大的方舟王室旗帜在风中猎猎作响。", },
	[186159] = {id=186159, zh_CN="阿加莎身着剪裁完美的宫廷长裙，雾紫色长发盘成优雅精致的发髻，戴着象征王储的小巧钻石冠冕。", },
	[186160] = {id=186160, zh_CN="她站在临时搭建的礼台上，仪态万方，脸上是温暖、自信、极具感染力的笑容，向热情的民众挥手致意。", },
	[186161] = {id=186161, zh_CN="你期待阿加莎接下来的讲话吗？", },
	[186162] = {id=186162, zh_CN="期待——公开恋情。", },
	[186163] = {id=186163, zh_CN="紧张——不公开恋情。", },
	[186164] = {id=186164, zh_CN="亲爱的诺亚方舟的子民们！看到你们充满希望和活力的脸庞，是我作为王储最大的动力和幸福源泉！", },
	[186165] = {id=186165, zh_CN="今天，除了例行和大家见面，分享方舟在种族社区融合项目上取得的喜人进展外……", },
	[186166] = {id=186166, zh_CN="她顿了顿，目光温柔而坚定地看向台侧的你，这个动作吸引了所有人的注意。", },
	[186167] = {id=186167, zh_CN="我还有一个关于我个人的重要消息，希望能与你们，我视作家人的国民们分享。", },
	[186168] = {id=186168, zh_CN="广场瞬间安静下来，无数目光聚焦在阿加莎和你身上。", },
	[186169] = {id=186169, zh_CN="自然地伸出手，轻轻握住你的手，两人十指相扣，动作优雅而充满宣告意味。她的笑容更加明媚，带着真挚的幸福，但姿态依旧保持着王储的庄重。", },
	[186170] = {id=186170, zh_CN="站在我身边的这位，%PlayerName，相信许多人已经熟悉他。他不仅是方舟忠诚的伙伴和盟友，他更用他的智慧、勇气和对这片土地深沉的爱，赢得了我的尊重、信赖和……倾心。", },
	[186171] = {id=186171, zh_CN="她声音带着一丝恰到好处的羞涩，但立刻被更强大的自信取代。", },
	[186172] = {id=186172, zh_CN="经过慎重的考虑和彼此真诚的交往，我很荣幸也很幸福地告诉大家，%PlayerName，不仅是诺亚方舟值得信赖的朋友，更是我生命中认定的伴侣！我们正在以结婚为前提交往！", },
	[186173] = {id=186173, zh_CN="广场在短暂的寂静后，爆发出震耳欲聋的欢呼、掌声和祝福声！民众对阿加莎的爱戴延伸到了她选择的伴侣身上。", },
	[186174] = {id=186174, zh_CN="抬手示意大家安静，脸上是幸福而郑重的表情。", },
	[186175] = {id=186175, zh_CN="我知道，作为王储，我的个人生活也承载着大家的关注。", },
	[186176] = {id=186176, zh_CN="我选择公开，是因为我深信，一份建立在真诚、责任和共同理想基础上的感情，只会让我更有力量去履行我的职责！", },
	[186177] = {id=186177, zh_CN="我向你们保证，这份感情不会影响我对国家和人民的承诺！相反，它会激励我，和%PlayerName一起，在未来以更加坚定的步伐，带领诺亚方舟，走向更繁荣、更包容、更充满希望的明天！", },
	[186178] = {id=186178, zh_CN="请你们继续监督我，支持我！谢谢大家！", },
	[186179] = {id=186179, zh_CN="阿加莎优雅鞠躬，你也一同鞠躬致意。阿加莎成功地将私人情感升华为了对国家的承诺，赢得了民众更深的信任与祝福。", },
	[186180] = {id=186180, zh_CN="你混在广场最前排的民众之中。穿着低调但整洁，在人群中并不显眼。", },
	[186181] = {id=186181, zh_CN="亲爱的诺亚方舟的子民们！看到你们充满希望和活力的脸庞，是我作为王储最大的动力和幸福源泉！", },
	[186182] = {id=186182, zh_CN="目光扫过前排人群的瞬间，精准地捕捉到了那个熟悉的身影。尽管你低着头，帽檐遮住了部分面容，但她就是知道，是你。阿加莎的心跳漏了一拍，但完美的表情管理让她嘴角的弧度没有丝毫变化。", },
	[186183] = {id=186183, zh_CN="在人群中，微微抬起头。当阿加莎的目光看似无意地掠过你时，你极其迅速地、用只有她能看清的角度，轻轻眨了一下右眼，嘴角勾起一个微小而温暖的弧度。那眼神里，充满了无声的鼓励和浓浓的爱意。", },
	[186184] = {id=186184, zh_CN="正接过一位老者献上的花束。感受到那熟悉的注视和小动作，她递花束给侍从的动作极其轻微地顿了一下。", },
	[186185] = {id=186185, zh_CN="她脸上绽放出比刚才更加璀璨、更加真实的笑容，那笑容仿佛瞬间点亮了整个广场。", },
	[186186] = {id=186186, zh_CN="谢谢您！这花真美，就像我们诺亚方舟人民的心灵一样纯洁美好！", },
	[186187] = {id=186187, zh_CN="看着阿加莎在台上因自己的小动作而焕发的光彩，心中满是柔情。你悄悄将手放在心口位置，停留了一秒。", },
	[186188] = {id=186188, zh_CN="为，你，骄，傲。", },
	[186189] = {id=186189, zh_CN="眼角的余光捕捉到你那个心口指向的动作。一股暖流瞬间涌遍全身。她感觉脸颊有些微热，但巧妙地借着低头整理面前麦克风线的动作掩饰了过去。", },
	[186190] = {id=186190, zh_CN="再抬头时，仿佛被注入了额外的能量。在发言结束的间隙，她拿起水杯喝水，借着杯身的掩护，她的嘴唇极其轻微地、快速地动了一下。", },
	[186191] = {id=186191, zh_CN="谢谢。", },
	[186192] = {id=186192, zh_CN="当阿加莎的目光再次与你交汇时，那眼神深处除了爱意和依赖，还多了一层化不开的沉重悲伤和无奈。", },
	[186193] = {id=186193, zh_CN="阿加莎迅速移开目光，但眼眶却不受控制地微微湿润了。她强忍着，将那份心酸转化为更用力、更灿烂的笑容。", },
	[186194] = {id=186194, zh_CN="只是那笑容背后，藏着只有台下那个人才懂的苦涩。", },
	[186195] = {id=186195, zh_CN="深夜，鸭湖城堡一处僻静的小露台。阿加莎望着远处，雾紫色的长发在微凉的夜风中轻轻飘动。", },
	[186196] = {id=186196, zh_CN="阿加莎穿着简单的丝质睡袍，肩头披着一件薄毯，微微颤抖的背影单薄而孤寂。压抑的、几乎听不见的啜泣声在你的耳边萦绕。", },
	[186197] = {id=186197, zh_CN="阿加莎？", },
	[186198] = {id=186198, zh_CN="慢慢走到她身边，保持一点距离，想要搂住她的手凝滞在半空，望着她拒绝的背影，无法前进。", },
	[186199] = {id=186199, zh_CN="身体猛地一僵，迅速抬手抹去脸上的泪痕，没有回头，声音带着浓重的鼻音和极力维持的平静。", },
	[186200] = {id=186200, zh_CN="我没事。只是……看夜景。", },
	[186201] = {id=186201, zh_CN="你……怎么还没休息？", },
	[186202] = {id=186202, zh_CN="看着她强撑的背影，心疼更甚。", },
	[186203] = {id=186203, zh_CN="城堡的夜景很美，但看夜景的人……似乎并不开心。", },
	[186204] = {id=186204, zh_CN="告诉我，发生了什么？", },
	[186205] = {id=186205, zh_CN="最近的压力很大吗？我们可以再偷偷出去……", },
	[186206] = {id=186206, zh_CN="沉默了很久，久到你以为她不会再开口。夜风吹过，带来她压抑到极致、终于破碎的声音。", },
	[186207] = {id=186207, zh_CN="……他们说得对。", },
	[186208] = {id=186208, zh_CN="谁说得对？说什么？", },
	[186209] = {id=186209, zh_CN="猛地转过身！月光下，她脸上泪痕未干，眼眶通红，平日里优雅从容的公主面具彻底碎裂，只剩下深不见底的痛苦和疲惫。", },
	[186210] = {id=186210, zh_CN="我不该对你的身份保留期待的，就算你的灵魂不属于这里，可是！你的样貌，你的尾巴，耳朵……", },
	[186211] = {id=186211, zh_CN="民众，媒体，对方舟虎视眈眈的势力，他们是不会听你解释，听我解释的。", },
	[186212] = {id=186212, zh_CN="他们只会认为：我！方舟继承人与宿敌之后交往过深，有通敌之嫌。", },
	[186213] = {id=186213, zh_CN="我不该抱有侥幸心理地把你当作回避的港湾的 ……", },
	[186214] = {id=186214, zh_CN="我不该任由我的心……", },
	[186215] = {id=186215, zh_CN="被她的激烈反应和话语刺痛，脸色发白，你忽然想起过去几周阿加莎与你交往时紧张的状态。", },
	[186216] = {id=186216, zh_CN="所以，你一直都处在紧张不安的情绪里吗？", },
	[186217] = {id=186217, zh_CN="阿加莎，你知道我不是！我们……", },
	[186218] = {id=186218, zh_CN="我知道！我当然知道！", },
	[186219] = {id=186219, zh_CN="我知道你有多好！知道你的幽默、你的智慧、你的体贴！", },
	[186220] = {id=186220, zh_CN="我知道你会带我去逛节日集会，会陪我解那些幼稚的谜题，会带我体验别人的平凡但对我却不普通的事物！", },
	[186221] = {id=186221, zh_CN="可是……可是我是方舟公主，我不只是你的Momo。", },
	[186222] = {id=186222, zh_CN="我知道把与你无关的仇恨强加在你身上很自私。", },
	[186223] = {id=186223, zh_CN="可是你外表所属于的种族在几百年前侵略，屠戮着我的先祖，我的身上流着“战士先辈”的血液……", },
	[186224] = {id=186224, zh_CN="我的子民看着我！他们的恨意、他们的恐惧……像冰冷的锁链，每时每刻都勒着我的脖子！", },
	[186225] = {id=186225, zh_CN="每一次和你见面，每一次对你微笑……我都要面对内心的叩问和周围无声的谴责！", },
	[186226] = {id=186226, zh_CN="你知道那种感觉吗？你知道吗？", },
	[186227] = {id=186227, zh_CN="你震惊地看着阿加莎崩溃的模样，听着她剖心泣血的哭诉，一股巨大的酸楚和无力感淹没了你。", },
	[186228] = {id=186228, zh_CN="阿加莎……我……", },
	[186229] = {id=186229, zh_CN="却像受惊的兔子般猛地后退一步，眼神充满绝望。", },
	[186230] = {id=186230, zh_CN="不！你不知道！你怎么会知道？！", },
	[186231] = {id=186231, zh_CN="你是一阵自由的风，吹过我们的历史，却感受不到那沉积了百年的血腥和沉重！", },
	[186232] = {id=186232, zh_CN="你不知道每次接触你，我内心要经历怎样的撕裂！", },
	[186233] = {id=186233, zh_CN="一边是越来越清晰、越来越真实的你！一边是刻在骨血里的仇恨和责任！", },
	[186234] = {id=186234, zh_CN="她靠着冰冷的栏杆滑坐在地上，将脸深深埋进膝盖，瘦弱的肩膀剧烈地颤抖着，发出压抑到极致的呜咽。", },
	[186235] = {id=186235, zh_CN="它们在我脑子里打架！快把我逼疯了！", },
	[186236] = {id=186236, zh_CN="我好累……我真的好累……", },
	[186237] = {id=186237, zh_CN="我只是想小小的逃避一下……", },
	[186238] = {id=186238, zh_CN="我只是……只是不小心喜欢了一个人……", },
	[186239] = {id=186239, zh_CN="为什么这么难……", },
	[186240] = {id=186240, zh_CN="你看着蜷缩在地上、哭得像个迷路孩子的阿加莎，心脏疼得像被狠狠攥住。所有想辩解的话，所有想质问“为什么不告诉我”的冲动，都堵在喉咙里，化为一片苦涩的沉默。", },
	[186241] = {id=186241, zh_CN="理解她。", },
	[186242] = {id=186242, zh_CN="你忽然理解了她背负的枷锁有多沉重，理解了她笑容背后的如履薄冰。", },
	[186243] = {id=186243, zh_CN="怨恨她的隐瞒。", },
	[186244] = {id=186244, zh_CN="怨恨她的隐瞒？不，你此刻只有无尽的心疼和自责——为她承受的痛苦，为自己无知带来的伤害。", },
	[186245] = {id=186245, zh_CN="心痛，努力安抚。", },
	[186246] = {id=186246, zh_CN="你缓缓蹲下身，不再试图触碰她，只是用最温柔、最坚定的声音说） 阿加莎……看着我。", },
	[186247] = {id=186247, zh_CN="她低着头，哭声渐弱，只剩下压抑的抽泣。", },
	[186248] = {id=186248, zh_CN="道歉。", },
	[186249] = {id=186249, zh_CN="对不起……为我让你独自承受这一切而道歉。为我无法感同身受那份历史的沉重而道歉。", },
	[186250] = {id=186250, zh_CN="认同阿加莎的观点。", },
	[186251] = {id=186251, zh_CN="你说得对，我是“天外”之风。我不懂你们的血仇，但我懂你现在的痛。恨我？怨我？或者恨这命运？都可以。", },
	[186252] = {id=186252, zh_CN="承受你现在的情绪，是我应该，也必须该做的。", },
	[186253] = {id=186253, zh_CN="求她不要推开自己。", },
	[186254] = {id=186254, zh_CN="无论如何，请别推开我。让我陪你一起站在悬崖边，好吗？", },
	[186255] = {id=186255, zh_CN="等待阿加莎的反应。", },
	[186256] = {id=186256, zh_CN="你安静地盯着阿加莎，等她主动抬头面对你。", },
	[186257] = {id=186257, zh_CN="她缓缓抬起头，泪眼婆娑地看着你，眼神脆弱得像易碎的琉璃。", },
	[186258] = {id=186258, zh_CN="张开双臂，眼神是前所未有的坦诚和包容。", },
	[186259] = {id=186259, zh_CN="如果相爱无能，如果怨恨无力……那就拥抱吧。", },
	[186260] = {id=186260, zh_CN="你保持着张开怀抱的姿势，等待她的选择。", },
	[186261] = {id=186261, zh_CN="请拥抱我吧。", },
	[186262] = {id=186262, zh_CN="我在这里。阿加莎，我在这里。", },
	[186263] = {id=186263, zh_CN="漫长的几秒钟。夜风似乎都静止了。", },
	[186264] = {id=186264, zh_CN="她看着你敞开的怀抱，那里没有指责，没有索求，只有无声的接纳和支撑。", },
	[186265] = {id=186265, zh_CN="她眼中翻涌着激烈的挣扎、恐惧，最终，那累积到无法承受的疲惫和渴望压倒了冰冷的枷锁。", },
	[186266] = {id=186266, zh_CN="她发出一声近乎崩溃的呜咽，像离弦的箭般扑进了你的怀里！", },
	[186267] = {id=186267, zh_CN="紧紧抱住你，仿佛抓住唯一的浮木，脸埋在你胸前，放声大哭，所有的委屈、恐惧、痛苦和挣扎都随着泪水汹涌而出。", },
	[186268] = {id=186268, zh_CN="……呜……为什么……为什么要是你……为什么偏偏是你……", },
	[186269] = {id=186269, zh_CN="我好讨厌你……可是……可是我更怕失去你……", },
	[186270] = {id=186270, zh_CN="用力回抱住她颤抖的身体，下巴轻轻抵着她的头顶，感受着她滚烫的泪水浸湿衣襟。你的手臂收得很紧，仿佛要将自己的力量和决心传递给她。", },
	[186271] = {id=186271, zh_CN="哭吧，哭出来就好。我在这里。“宿敌”也好，“祸端”也罢。", },
	[186272] = {id=186272, zh_CN="我就在这里，抱着你，任你处置。", },
	[186273] = {id=186273, zh_CN="谁也不能再让你独自承担这份重量。我保证。", },
	[186274] = {id=186274, zh_CN="你与阿加莎紧紧相拥在冰冷的露台上，月光将你们的影子拉得很长。", },
	[186275] = {id=186275, zh_CN="仇恨的阴影仍在，但此刻，唯有这个拥抱是真实的温度。", },
	[186276] = {id=186276, zh_CN="亲爱的%PlayerName阁下，祝你午安。", },
	[186277] = {id=186277, zh_CN="离开。", },
	[186278] = {id=186278, zh_CN="再会了，我的朋友。", },
	[186279] = {id=186279, zh_CN="【秘密出游】", },
	[186280] = {id=186280, zh_CN="【造访“记忆方舟”】", },
	[186281] = {id=186281, zh_CN="【联姻】", },
	[186282] = {id=186282, zh_CN="【灵魂锚点】", },
	[186283] = {id=186283, zh_CN="【“政治”真婚】", },
	[186284] = {id=186284, zh_CN="【庭台露面】", },
	[186285] = {id=186285, zh_CN="【一千夜最后一夜】", },
	[186286] = {id=186286, zh_CN="绣球种", },
	[186287] = {id=186287, zh_CN="木兰种", },
	[186288] = {id=186288, zh_CN="牡丹种", },
	[186289] = {id=186289, zh_CN="睡莲种", },
	[186290] = {id=186290, zh_CN="请点击上方历程中的花瓣—牡丹种—帝王牡丹界面解锁牡丹花瓣", },
	[186291] = {id=186291, zh_CN="请点击上方历程中的花瓣—睡莲种—沉水睡莲界面解锁睡莲花瓣", },
	[186292] = {id=186292, zh_CN="请点击上方历程中的花瓣—木兰种—紫夷木兰界面解锁木兰花瓣", },
	[186293] = {id=186293, zh_CN="请点击上方历程中的花瓣—绣球种—夏尽绣团界面解锁绣球花瓣", },
	[186300] = {id=186300, zh_CN="辛德瑞拉", },
	[186301] = {id=186301, zh_CN="谨慎花种", },
	[186302] = {id=186302, zh_CN="敏感花种", },
	[186303] = {id=186303, zh_CN="惭秽花种", },
	[186304] = {id=186304, zh_CN="教母的馈赠", },
	[186305] = {id=186305, zh_CN="以心起誓", },
	[186306] = {id=186306, zh_CN="杜鹃花瓣3", },
	[186307] = {id=186307, zh_CN="杜鹃花瓣4", },
	[186308] = {id=186308, zh_CN="杜鹃花瓣5", },
	[186309] = {id=186309, zh_CN="杜鹃花瓣6", },
	[186310] = {id=186310, zh_CN="杜鹃花瓣7", },
	[186311] = {id=186311, zh_CN="杜鹃花瓣8", },
	[186312] = {id=186312, zh_CN="易碎梦境的微光，映照步步小心的缜密，午夜钟声敲碎水晶，徒留惶惑心惊与自惭形秽。", },
	[186313] = {id=186313, zh_CN="如纺锤的种子，收紧纺绡，蜷成避风的湾。", },
	[186314] = {id=186314, zh_CN="花种微小，细密，几乎不可见，如尘埃般散落。", },
	[186315] = {id=186315, zh_CN="—种核附着几乎透明的轻薄翅膜，藏匿惧光的影。", },
	[186316] = {id=186316, zh_CN="集齐掉落的杜鹃花种，幻化而来的琉璃球茎。花瓣承载着转瞬即逝的心者露珠是最寻常的，最平凡，最芥微的存在。", },
	[186317] = {id=186317, zh_CN="从自卑心门摘下的辛德瑞拉，内侧镌刻兽神忠诚符文。当第一缕晨光穿透尘埃，照亮少年，黑夜便裂开一道温柔的罅隙。", },
	[186318] = {id=186318, zh_CN="杜鹃花瓣3物品描述", },
	[186319] = {id=186319, zh_CN="杜鹃花瓣4物品描述", },
	[186320] = {id=186320, zh_CN="杜鹃花瓣5物品描述", },
	[186321] = {id=186321, zh_CN="杜鹃花瓣6物品描述", },
	[186322] = {id=186322, zh_CN="杜鹃花瓣7物品描述", },
	[186323] = {id=186323, zh_CN="杜鹃花瓣8物品描述", },
	[186324] = {id=186324, zh_CN="和披风猫对话", },
	[186325] = {id=186325, zh_CN="不对……和芝麻糊的亲密度好像还没到那种程度！", },
	[186326] = {id=186326, zh_CN="阿加莎（心声）", },
	[186350] = {id=186350, zh_CN="喵嗷~~喵喵。", },
	[186351] = {id=186351, zh_CN="（翻译：芝麻糊掉落的花种收好了吗？）", },
	[186352] = {id=186352, zh_CN="（翻译：检查！）", },
	[186353] = {id=186353, zh_CN="（翻译：快去收好。）", },
	[186354] = {id=186354, zh_CN="喵喵~呼噜噜……", },
	[186355] = {id=186355, zh_CN="（翻译：芝麻糊还有事情找你呢。）", },
	[186356] = {id=186356, zh_CN="咕噜……喵！", },
	[186357] = {id=186357, zh_CN="芝麻糊名叫芝麻·古堡主·糊。", },
	[186358] = {id=186358, zh_CN="什么，你居然不是小猫灵吗？", },
	[186359] = {id=186359, zh_CN="蠢货！", },
	[186360] = {id=186360, zh_CN="收下芝麻糊的信物吧！", },
	[186361] = {id=186361, zh_CN="从此，你就是芝麻糊喵的忠实奴仆。", },
	[186362] = {id=186362, zh_CN="这是……你的毛？", },
	[186363] = {id=186363, zh_CN="我会珍藏的！", },
	[186364] = {id=186364, zh_CN="喵喵~（翻译：算你识相，喵。）", },
	[186365] = {id=186365, zh_CN="有点掉毛啊……", },
	[186366] = {id=186366, zh_CN="喵！（翻译：不给你了，还给芝麻糊！）", },
	[186367] = {id=186367, zh_CN="芝麻糊叼来一个项圈，递到玩家手上。内侧刻着“芝麻·古堡主·糊”。", },
	[186368] = {id=186368, zh_CN="芝麻糊允许你给我带上象征名字的项圈。", },
	[186369] = {id=186369, zh_CN="黑皮草就是好看！", },
	[186370] = {id=186370, zh_CN="钻石项圈真是衬你的毛色。", },
	[186371] = {id=186371, zh_CN="那是当然。", },
	[186372] = {id=186372, zh_CN="好了，喵喵殿下要回城堡享受众人的朝拜了。", },
	[186373] = {id=186373, zh_CN="你就自行离开吧，好心的家伙。", },
	[186374] = {id=186374, zh_CN="下次带双倍小鱼干再来喵~", },
	[186375] = {id=186375, zh_CN="社团科技", },
	[186376] = {id=186376, zh_CN="说书人开关", },
	[186377] = {id=186377, zh_CN="垂危", },
	[186378] = {id=186378, zh_CN="功能暂未开放。", },
	[186400] = {id=186400, zh_CN="它灵活地在人群中穿梭，很快消失在视线中。", },
	[186401] = {id=186401, zh_CN="它灵活地在人群中穿梭，很快消失在视线中。", },
	[186402] = {id=186402, zh_CN="警察拿出手铐……", },
	[186403] = {id=186403, zh_CN="它灵活地在人群中穿梭，很快消失在视线中。", },
	[186404] = {id=186404, zh_CN="既然是你的狗……", },
	[186405] = {id=186405, zh_CN="请你登记它的姓名，年龄，出示宠物证明。", },
	[186406] = {id=186406, zh_CN="去管理所解释吧，现在和我们走一趟。", },
	[186407] = {id=186407, zh_CN="警察拿出手铐……", },
	[186408] = {id=186408, zh_CN="我只是认为相比在城市中流浪，被收容也许是更好的选择。", },
	[186409] = {id=186409, zh_CN="小金毛歪着脑袋，仿佛在思考……", },
	[186410] = {id=186410, zh_CN="小金毛歪着脑袋，仿佛在思考……", },
	[186411] = {id=186411, zh_CN="一想到可以请你吃一顿好吃的午饭。", },
	[186412] = {id=186412, zh_CN="你帮了小金毛，小金毛也要回报你。", },
	[186413] = {id=186413, zh_CN="洛瑞昂俯身将一盒卤鸡腿挂在小金毛嘴里。", },
	[186414] = {id=186414, zh_CN="这是约定好的报酬。", },
	[186415] = {id=186415, zh_CN="今天是他帮助小金毛逃脱管理所抓捕哦。", },
	[186416] = {id=186416, zh_CN="小金毛现在要请他吃饭！", },
	[186417] = {id=186417, zh_CN="洛瑞昂又递给小金毛一袋食物。", },
	[186418] = {id=186418, zh_CN="这是你让我准备的另外食物。", },
	[186419] = {id=186419, zh_CN="祝你们有一个美丽的午后。", },
	[186420] = {id=186420, zh_CN="谢谢你的招待，小金毛。我很喜欢。", },
	[186421] = {id=186421, zh_CN="你每天就这么凑合吃饭？", },
	[186422] = {id=186422, zh_CN="小金毛一口吞掉鸡腿，它摇摇头。", },
	[186423] = {id=186423, zh_CN="凑合？小金毛有最低保障哦！", },
	[186424] = {id=186424, zh_CN="毕竟我是少见的保持动物形态的妖灵。", },
	[186425] = {id=186425, zh_CN="收容所的待遇不太好。", },
	[186426] = {id=186426, zh_CN="而且小金毛还有很多朋友需要我照顾。", },
	[186427] = {id=186427, zh_CN="小金毛这么艰苦的生活……", },
	[186428] = {id=186428, zh_CN="那我们下次再见咯。", },
	[186429] = {id=186429, zh_CN="不像我，连自己都照顾不好……", },
	[186430] = {id=186430, zh_CN="它摇动尾巴扫过你的脸颊，戳戳你。", },
	[186431] = {id=186431, zh_CN="妖灵族的小金毛最近不知道受到了什么惊吓。", },
	[186432] = {id=186432, zh_CN="身份：兽人族，姓名：小金毛，身体状况异常。", },
