	[186628] = {id=186628, zh_CN="小金毛甩掉头顶的泥巴，爪子敲了敲闷声的位置。", },
	[186629] = {id=186629, zh_CN="你蹲在箱子前，仔细观察着锁的结构。", },
	[186630] = {id=186630, zh_CN="但锁依然纹丝不动。", },
	[186631] = {id=186631, zh_CN="轻轻一捅，锁扣弹开。", },
	[186632] = {id=186632, zh_CN="一声闷响后，锁扣晃了晃，但并没有坏掉。", },
	[186633] = {id=186633, zh_CN="一声闷响后，锁扣“咔哒”一声，", },
	[186634] = {id=186634, zh_CN="盒锁发出了一声“嘀嘀”的提示音，没有任何反应。", },
	[186635] = {id=186635, zh_CN="小金毛鼻子拱了拱锁扣，轻轻一推。", },
	[186636] = {id=186636, zh_CN="“咔哒”一声，锁竟然开了！", },
	[186637] = {id=186637, zh_CN="锁扣在巨大冲击力下，", },
	[186638] = {id=186638, zh_CN="“咔哒”一声，竟然被撞开了。", },
	[186639] = {id=186639, zh_CN="这密码总不可能太复杂吧。", },
	[186640] = {id=186640, zh_CN="信封角落还有一处墨色晕开的签名。", },
	[186641] = {id=186641, zh_CN="呜呜呜，我好想你啊，主人。", },
	[186642] = {id=186642, zh_CN="小金毛扭头回避，将盒子揽到自己身前。", },
	[186643] = {id=186643, zh_CN="搪塞。", },
	[186644] = {id=186644, zh_CN="我……", },
	[186645] = {id=186645, zh_CN="我随口猜到的，没想到真是啊。", },
	[186646] = {id=186646, zh_CN="坦白。", },
	[186647] = {id=186647, zh_CN="我刚刚有点担心你，所以对你读心了。", },
	[186648] = {id=186648, zh_CN="我不是故意听到你的过去的，抱歉。", },
	[186649] = {id=186649, zh_CN="惊慌失措。", },
	[186650] = {id=186650, zh_CN="我 ……", },
	[186651] = {id=186651, zh_CN="你想不出解释的话语，最终陷入沉默。", },
	[186652] = {id=186652, zh_CN="信封里的金币滑向已没有韧性的信封口。", },
	[186653] = {id=186653, zh_CN="“叮叮当当”从接口处掉出。", },
	[186654] = {id=186654, zh_CN="随之飘落在地的……", },
	[186655] = {id=186655, zh_CN="一朵花瓣从小金毛身体里飘出，", },
	[186656] = {id=186656, zh_CN="轻盈地悬浮在空中。", },
	[186657] = {id=186657, zh_CN="你沉默着，将信塞入小金毛的怀中。", },
	[186658] = {id=186658, zh_CN="你将信收入信封，看向小金毛。", },
	[186659] = {id=186659, zh_CN="什么话语好似都太单薄了，承载不住这炙热的情感。", },
	[186660] = {id=186660, zh_CN="草坪又恢复原本的模样。", },
	[186661] = {id=186661, zh_CN="小金毛炫耀展示着沉甸甸的金币。", },
	[186662] = {id=186662, zh_CN="小金毛的愿望很简单。", },
	[186663] = {id=186663, zh_CN="希望社区能科学合理地接纳这些流浪光灵，", },
	[186664] = {id=186664, zh_CN="你抬头看向千年未变的街道……", },
	[186665] = {id=186665, zh_CN="小金毛炫耀展示着沉甸甸的金币。", },
	[186666] = {id=186666, zh_CN="小金毛的愿望很简单。", },
	[186667] = {id=186667, zh_CN="希望社区能科学合理地接纳这些流浪光灵，", },
	[186668] = {id=186668, zh_CN="你抬头看向千年未变的街道……", },
	[186669] = {id=186669, zh_CN="你拍拍狗头起身，", },
	[186670] = {id=186670, zh_CN="小金毛站起身，眺望远方，望着被群山环绕的城镇。", },
	[186671] = {id=186671, zh_CN="它咧着嘴笑，跳下城垛，踏入街道的黑暗之中。", },
