	[186901] = {id=186901, zh_CN="伙伴邀请你一起即兴表演。", },
	[186902] = {id=186902, zh_CN="手指灵活且能变换出各种器具。", },
	[186903] = {id=186903, zh_CN="在关节活动的“咔哒”“咔哒”的声响……", },
	[186904] = {id=186904, zh_CN="与夹杂着的轻微电子嗡嗡声中。", },
	[186905] = {id=186905, zh_CN="他沉默地沉浸在自己的工作中。", },
	[186906] = {id=186906, zh_CN="精灵族城邦为何出现人形机械生命？", },
	[186907] = {id=186907, zh_CN="难道是种族卧底？", },
	[186908] = {id=186908, zh_CN="难道是精灵族和机械生命产生嫌隙？", },
	[186909] = {id=186909, zh_CN="与我社交几分钟，", },
	[186910] = {id=186910, zh_CN="难道还没修理机械臂重要吗？", },
	[186911] = {id=186911, zh_CN="莫迪斯用沾满机油的布料擦拭手指。", },
	[186912] = {id=186912, zh_CN="将“保护”你的保护光罩收起。", },
	[186913] = {id=186913, zh_CN="转换社交模版中——", },
	[186914] = {id=186914, zh_CN="你好，我是莫迪斯。", },
	[186915] = {id=186915, zh_CN="你是要违背合约原则吗？", },
	[186916] = {id=186916, zh_CN="仿佛是某种高科技扫描装置启动的信号。", },
	[186917] = {id=186917, zh_CN="复杂的光学数据在瞳孔中流转……", },
	[186918] = {id=186918, zh_CN="分析处理出的信息有序出现在他的记忆数据中。", },
	[186919] = {id=186919, zh_CN="现表征符合种族特征的特殊未知生命体——", },
	[186920] = {id=186920, zh_CN="社交提示：保持观察与正常社交。", },
	[186921] = {id=186921, zh_CN="分析数据波动还差不多……", },
	[186922] = {id=186922, zh_CN="你放弃读心。", },
	[186923] = {id=186923, zh_CN="时间有限……", },
	[186924] = {id=186924, zh_CN="我将拒绝与你社交。", },
	[186925] = {id=186925, zh_CN="并警告其他生物体与你保持安全距离。", },
	[186926] = {id=186926, zh_CN="考虑到莫迪斯还在工作时间。", },
	[186927] = {id=186927, zh_CN="你没有询问过多的问题。", },
	[186928] = {id=186928, zh_CN="莫迪斯转身，投入在工作中。", },
	[186929] = {id=186929, zh_CN="你压抑着心中好奇，在一旁等待他。", },
	[186930] = {id=186930, zh_CN="忽然你感受到手心刺痛，打开手心……", },
	[186931] = {id=186931, zh_CN="一颗细小的种子静静躺在手心。", },
	[186932] = {id=186932, zh_CN="金鱼草的细叶萦绕的画面一闪而过。", },
	[186933] = {id=186933, zh_CN="几小时后——", },
	[186934] = {id=186934, zh_CN="莫迪斯终于结束了工作。", },
	[186935] = {id=186935, zh_CN="检测到生命体。", },
	[186936] = {id=186936, zh_CN="你没离开。", },
	[186937] = {id=186937, zh_CN="转换社交模版中——", },
	[186938] = {id=186938, zh_CN="还有什么，需要我帮助的吗？", },
	[186939] = {id=186939, zh_CN="听说机械生命对其他种族有求必应？", },
	[186940] = {id=186940, zh_CN="我可以命令你帮我做任何事吗？", },
	[186941] = {id=186941, zh_CN="您是机械生命的造物主，", },
	[186942] = {id=186942, zh_CN="您的生物基因高于我的法则之上。", },
	[186943] = {id=186943, zh_CN="我会满足您的一切合理需求。", },
	[186944] = {id=186944, zh_CN="理论上是这样的。", },
	[186945] = {id=186945, zh_CN="机械生命要无条件遵守《服务条例》。", },
	[186946] = {id=186946, zh_CN="只要不违背基础原则的是任何事情，", },
	[186947] = {id=186947, zh_CN="你向我提出的需求是？", },
	[186948] = {id=186948, zh_CN="教我踢踏舞。", },
	[186949] = {id=186949, zh_CN="检索到327种舞蹈教学视频。", },
	[186950] = {id=186950, zh_CN="建议：您需要先涂抹关节润滑剂。", },
	[186951] = {id=186951, zh_CN="关节润滑剂？认真的？", },
	[186952] = {id=186952, zh_CN="莫迪斯调出你的健康数值。", },
	[186953] = {id=186953, zh_CN="您最快3 时 15 分能获得学成的成就感。", },
	[186954] = {id=186954, zh_CN="不建议您学习踢踏舞，会影响健康。", },
	[186955] = {id=186955, zh_CN="咚咚！打退堂鼓。", },
	[186956] = {id=186956, zh_CN="咚咚咚，正合我意。", },
	[186957] = {id=186957, zh_CN="给我倒杯水。", },
	[186958] = {id=186958, zh_CN="莫迪斯，能给我倒杯水吗？", },
	[186959] = {id=186959, zh_CN="这个我可以做到。", },
	[186960] = {id=186960, zh_CN="不过附近有自动饮水机。", },
	[186961] = {id=186961, zh_CN="您可以自己去倒水，这样更高效。", },
	[186962] = {id=186962, zh_CN="你这是诈骗！", },
	[186963] = {id=186963, zh_CN="不是说服务我吗？", },
	[186964] = {id=186964, zh_CN="提供最佳方案，也是一种服务。", },
	[186965] = {id=186965, zh_CN="建议引导大于提供服务。", },
	[186966] = {id=186966, zh_CN="给我100万星魂。", },
	[186967] = {id=186967, zh_CN="莫迪斯，给我100万星魂吧！", },
	[186968] = {id=186968, zh_CN="《服务协议》第5条，", },
	[186969] = {id=186969, zh_CN="但无法提供超出能力范围的物品或星魂。", },
	[186970] = {id=186970, zh_CN="我无法满足您的需求。", },
	[186971] = {id=186971, zh_CN="我将额外为您分析出最佳方案。", },
	[186972] = {id=186972, zh_CN="您在商会上获取100万星魂的可能性最大，", },
	[186973] = {id=186973, zh_CN="好吧，我知道了。", },
	[186974] = {id=186974, zh_CN="让我立刻收集完花种。", },
	[186975] = {id=186975, zh_CN="莫迪斯，帮我立刻收集完情绪花种吧。", },
	[186976] = {id=186976, zh_CN="我需要它们。", },
	[186977] = {id=186977, zh_CN="“花种”定义过于笼统。", },
	[186978] = {id=186978, zh_CN="未在数据库中找到“情绪花种”的任何信息。", },
	[186979] = {id=186979, zh_CN="无法确定您的真正需求。", },
	[186980] = {id=186980, zh_CN="您可以告诉我具体位置和数量吗？", },
	[186981] = {id=186981, zh_CN="尬笑，哈哈，我也不知道。", },
	[186982] = {id=186982, zh_CN="抱歉，我无法协助您完成该任务。", },
	[186983] = {id=186983, zh_CN="分析过载，无结果。", },
	[186984] = {id=186984, zh_CN="机械生命和人族的渊源。", },
	[186985] = {id=186985, zh_CN="莫迪斯，", },
	[186986] = {id=186986, zh_CN="因为机械生命是由人族制作进化而来。", },
	[186987] = {id=186987, zh_CN="我们的机体中植入了人族利益至上原则。", },
	[186988] = {id=186988, zh_CN="那你质疑过原则吗？", },
	[186989] = {id=186989, zh_CN="我不明白您所说的，", },
	[186990] = {id=186990, zh_CN="我无法对此产生疑问和审判。", },
	[186991] = {id=186991, zh_CN="你和非人形机械生命的区别。", },
	[186992] = {id=186992, zh_CN="莫迪斯，你和非人形机械生命有区别吗？", },
	[186993] = {id=186993, zh_CN="有的。", },
	[186994] = {id=186994, zh_CN="人形机械生命和非人形机械生命的主要区别，", },
	[186995] = {id=186995, zh_CN="人形机械生命功能性更偏陪伴，", },
	[186996] = {id=186996, zh_CN="那你思考会接近人族吗？", },
	[186997] = {id=186997, zh_CN="并不会。", },
	[186998] = {id=186998, zh_CN="你想要我伪装吗？", },
	[186999] = {id=186999, zh_CN="甚至性别？", },
	[187000] = {id=187000, zh_CN="是的，准确来说，我是无性别。", },
	[187001] = {id=187001, zh_CN="酷！", },
	[187002] = {id=187002, zh_CN="离开。", },
	[187003] = {id=187003, zh_CN="酣畅淋漓的解答。", },
	[187004] = {id=187004, zh_CN="莫迪斯，我记住你了。", },
	[187005] = {id=187005, zh_CN="我还会再回来的。", },
	[187006] = {id=187006, zh_CN="再会。", },
	[187007] = {id=187007, zh_CN="再见。", },
