	[187050] = {id=187050, zh_CN="林间小屋，莫迪斯正在整理工具台。", },
	[187051] = {id=187051, zh_CN="好奇莫迪斯的创造者。", },
	[187052] = {id=187052, zh_CN="莫迪斯，我一直在想……", },
	[187053] = {id=187053, zh_CN="创造你们机械生命的科学家，", },
	[187054] = {id=187054, zh_CN="尤其是创造像你这样独特个体的，", },
	[187055] = {id=187055, zh_CN="会是什么样的人？", },
	[187056] = {id=187056, zh_CN="莫迪斯动作微顿，瞳孔闪烁蓝光。", },
	[187057] = {id=187057, zh_CN="检索相关记忆库中——", },
	[187058] = {id=187058, zh_CN="空间站机械工程师——伯格先生。", },
	[187059] = {id=187059, zh_CN="听起来是个严格的人。", },
	[187060] = {id=187060, zh_CN="他是一个完美的执行者。", },
	[187061] = {id=187061, zh_CN="能在理性框架下，处理复杂的决策。", },
	[187062] = {id=187062, zh_CN="也是致力于服务型机体的理想主义者。", },
	[187063] = {id=187063, zh_CN="他希望你成为什么样子？", },
	[187064] = {id=187064, zh_CN="更好服务于人族的混合型机械生命。", },
	[187065] = {id=187065, zh_CN="我检索他的日志……", },
	[187066] = {id=187066, zh_CN="他是这样记录的。", },
	[187067] = {id=187067, zh_CN="我的情感实验，", },
	[187068] = {id=187068, zh_CN="也是为了更好地服务于生命体。", },
	[187069] = {id=187069, zh_CN="你被声音激得抱紧自己，直打冷战。", },
	[187070] = {id=187070, zh_CN="莫迪斯对你进行扫描，却未检查出任何不适。", },
	[187071] = {id=187071, zh_CN="几天后，莫迪斯找到你。", },
	[187072] = {id=187072, zh_CN="关于之前的改造，", },
	[187073] = {id=187073, zh_CN="我需要进行一次深度反馈。", },
	[187074] = {id=187074, zh_CN="需要我为你做什么？", },
	[187075] = {id=187075, zh_CN="只是需要你回答一个问题。", },
	[187076] = {id=187076, zh_CN="这个问题，无关性能和机械工程…", },
	[187077] = {id=187077, zh_CN="我想知道：", },
	[187078] = {id=187078, zh_CN="你希望得到一个不断被改造、", },
	[187079] = {id=187079, zh_CN="与你交互增多的莫迪斯；", },
	[187080] = {id=187080, zh_CN="或者最初的第一要务是服务生物体，", },
	[187081] = {id=187081, zh_CN="望着被你改装的莫迪斯…", },
	[187082] = {id=187082, zh_CN="不断进步、更强大的你。", },
	[187083] = {id=187083, zh_CN="我喜欢不断进步、更强大的你。", },
	[187084] = {id=187084, zh_CN="“莫迪斯”本身。", },
	[187085] = {id=187085, zh_CN="我喜欢我喜欢的是“莫迪斯”本身。", },
	[187086] = {id=187086, zh_CN="开玩笑——冷冰冰的你也挺有趣的。", },
	[187087] = {id=187087, zh_CN="嗯…有时候冷冰冰的你也挺有趣的？", },
	[187088] = {id=187088, zh_CN="并不切题的答案。", },
	[187089] = {id=187089, zh_CN="我想，我的研究还需要继续。", },
	[187090] = {id=187090, zh_CN="但你乎真的改变了我。", },
	[187091] = {id=187091, zh_CN="是你引导我学习感情。", },
	[187092] = {id=187092, zh_CN="那我算不算你的创造者之一？", },
	[187093] = {id=187093, zh_CN="当然是的。", },
	[187094] = {id=187094, zh_CN="你创造了我的人族外观，", },
	[187095] = {id=187095, zh_CN="没有你，我无法完成这些改变。", },
	[187096] = {id=187096, zh_CN="需要承认，你已经成为了我的创造者。", },
	[187097] = {id=187097, zh_CN="是站在你面前的这个莫迪斯。", },
	[187098] = {id=187098, zh_CN="我有一个重要的决定要告诉你。", },
	[187099] = {id=187099, zh_CN="从今天起，", },
	[187100] = {id=187100, zh_CN="为什么，莫迪斯？", },
	[187101] = {id=187101, zh_CN="莫迪斯低头沉默，", },
	[187102] = {id=187102, zh_CN="仿佛在回忆着被与你相处的点点滴滴逗笑。", },
	[187103] = {id=187103, zh_CN="原因就是站在你面前的莫迪斯。", },
	[187104] = {id=187104, zh_CN="我已是一只由你改造过的“忒修斯之船”。", },
	[187105] = {id=187105, zh_CN="虽然你的影响只是细微的改动与变化，", },
	[187106] = {id=187106, zh_CN="每一处都潜藏着你的喜好。", },
	[187107] = {id=187107, zh_CN="除了创造我的人，", },
	[187108] = {id=187108, zh_CN="也无法与你匹敌。", },
	[187109] = {id=187109, zh_CN="不不不。莫迪斯！", },
	[187110] = {id=187110, zh_CN="事实就是这样。", },
	[187111] = {id=187111, zh_CN="不怕伤损的功能性战争机器", },
	[187112] = {id=187112, zh_CN="是无法和用感性与真心，", },
	[187113] = {id=187113, zh_CN="无论数据，记忆，", },
	[187114] = {id=187114, zh_CN="你都算得上我的造物主。", },
	[187115] = {id=187115, zh_CN="对不起莫迪斯，我不知道该说些什么。", },
	[187116] = {id=187116, zh_CN="你不需要说什么。", },
	[187117] = {id=187117, zh_CN="我将永远忠诚于你，服务于你。", },
	[187118] = {id=187118, zh_CN="从这一刻起，我将你放在法则之上。", },
	[187119] = {id=187119, zh_CN="我的一切行动都将围绕你展开。", },
	[187120] = {id=187120, zh_CN="这会不会太…违背法则？", },
	[187121] = {id=187121, zh_CN="请相信你对我的影响力。", },
	[187122] = {id=187122, zh_CN="作为我视为“人”的开端。", },
	[187123] = {id=187123, zh_CN="莫迪斯，根据《服务条例》，", },
	[187124] = {id=187124, zh_CN="正确。在不违反基础原则的前提下。", },
	[187125] = {id=187125, zh_CN="我现在正式雇佣你。", },
	[187126] = {id=187126, zh_CN="雇佣内容是？", },
	[187127] = {id=187127, zh_CN="做我的朋友！", },
	[187128] = {id=187128, zh_CN="逻辑错误。", },
	[187129] = {id=187129, zh_CN="“朋友”并非一种可被雇佣的职业或服务项目。", },
	[187130] = {id=187130, zh_CN="分析显示：朋友关系应基于平等、自愿。", },
	[187131] = {id=187131, zh_CN="《服务条例》没说不行，不是吗？", },
	[187132] = {id=187132, zh_CN="你就当是在执行一种特殊的长期服务协议。", },
	[187133] = {id=187133, zh_CN="……分析。", },
	[187134] = {id=187134, zh_CN="协议条款确实未禁止。", },
	[187135] = {id=187135, zh_CN="可以接受此特殊雇佣协议。", },
	[187136] = {id=187136, zh_CN="服务内容为：分析“朋友”的身份与行为准则，与你互动。", },
	[187137] = {id=187137, zh_CN="朋友莫迪斯，请多指教！", },
	[187138] = {id=187138, zh_CN="正在加载社交模组中——", },
	[187139] = {id=187139, zh_CN="加载完毕。", },
	[187140] = {id=187140, zh_CN="朋友%PlayerName，请多指教。", },
	[187141] = {id=187141, zh_CN="今日的友情互动，你想要与我做什么？", },
	[187142] = {id=187142, zh_CN="先从…散步开始吧？", },
	[187143] = {id=187143, zh_CN="收到。规划最优散步路线。", },
	[187144] = {id=187144, zh_CN="需要与%PlayerName并肩行走。", },
	[187145] = {id=187145, zh_CN="莫迪斯今天罕见地未在工作时间。", },
	[187146] = {id=187146, zh_CN="机械生命之间是怎么做朋友的？", },
	[187147] = {id=187147, zh_CN="莫迪斯，你们机械生命之间是怎么做朋友的？", },
	[187148] = {id=187148, zh_CN="基于数据共享、效率互补和互相维护。", },
	[187149] = {id=187149, zh_CN="互相维护？比如呢？", },
	[187150] = {id=187150, zh_CN="例如，定期为对方检查散热剂是否充足。", },
	[187151] = {id=187151, zh_CN="对非核心区域机体进行清洁。", },
	[187152] = {id=187152, zh_CN="可以提出申请进行深度清洁。", },
	[187153] = {id=187153, zh_CN="深度清洁？", },
	[187154] = {id=187154, zh_CN="打开对方颅骨，", },
	[187155] = {id=187155, zh_CN="朋友%PlayerName，你需要此项服务吗？", },
	[187156] = {id=187156, zh_CN="我可以代劳。", },
	[187157] = {id=187157, zh_CN="下意识捂住头", },
	[187158] = {id=187158, zh_CN="不…不用了！谢谢！", },
	[187159] = {id=187159, zh_CN="我们还是用生物体的方式做朋友吧…", },
	[187160] = {id=187160, zh_CN="林间小屋。", },
	[187161] = {id=187161, zh_CN="莫迪斯抬眸望见你。", },
	[187162] = {id=187162, zh_CN="朋友%PlayerName，今天过得好吗？", },
	[187163] = {id=187163, zh_CN="我想解除“朋友”雇佣协议。", },
	[187164] = {id=187164, zh_CN="协议解除的原因？", },
	[187165] = {id=187165, zh_CN="我的“友情服务”效率低下吗？", },
	[187166] = {id=187166, zh_CN="不，恰恰相反。", },
	[187167] = {id=187167, zh_CN="因为我不想雇佣你当朋友了。", },
	[187168] = {id=187168, zh_CN="朋友%PlayerName，你要终止这段关系？", },
	[187169] = {id=187169, zh_CN="我是说，只终止雇佣关系！", },
	[187170] = {id=187170, zh_CN="不！我是说，", },
	[187171] = {id=187171, zh_CN="我想尝试和你成为……", },
	[187172] = {id=187172, zh_CN="没有协议约束，", },
	[187173] = {id=187173, zh_CN="莫迪斯沉默，", },
	[187174] = {id=187174, zh_CN="没有协议框架，", },
	[187175] = {id=187175, zh_CN="我们做朋友的效率会降低。", },
	[187176] = {id=187176, zh_CN="朋友就是这样的。", },
	[187177] = {id=187177, zh_CN="朋友不是靠协议，实验，绑定在一起的。", },
	[187178] = {id=187178, zh_CN="为我尝试一下，好不好？", },
	[187179] = {id=187179, zh_CN="莫迪斯瞳孔的红蓝光熄灭又亮起，", },
	[187180] = {id=187180, zh_CN="虽非高效模式，", },
	[187181] = {id=187181, zh_CN="我同意。", },
	[187182] = {id=187182, zh_CN="尝试成为你的真朋友。", },
	[187183] = {id=187183, zh_CN="莫迪斯，你理解亲情吗？", },
	[187184] = {id=187184, zh_CN="检索数据库。", },
	[187185] = {id=187185, zh_CN="家人通常指，", },
	[187186] = {id=187186, zh_CN="亲情指该集合个体间产生的情感联结。", },
	[187187] = {id=187187, zh_CN="特征为无偿付出、长期陪伴、相互扶持。", },
	[187188] = {id=187188, zh_CN="你觉得我们像家人吗？", },
	[187189] = {id=187189, zh_CN="数据分析：我们近期共处时间占比37.6%。", },
	[187190] = {id=187190, zh_CN="超过普通朋友标准。", },
	[187191] = {id=187191, zh_CN="共享空间、存在互助行为。", },
	[187192] = {id=187192, zh_CN="部分参数符合家人定义。", },
	[187193] = {id=187193, zh_CN="结论，我们可以被归类为“模拟家庭单位”。", },
	[187194] = {id=187194, zh_CN="只是模拟吗？", },
	[187195] = {id=187195, zh_CN="我们缺乏血缘与法律纽带。", },
	[187196] = {id=187196, zh_CN="所以定位模拟。", },
	[187197] = {id=187197, zh_CN="%PlayerName，你想要与我执行家人的行为模式吗？", },
	[187198] = {id=187198, zh_CN="想要——想和莫迪斯成为家人。", },
	[187199] = {id=187199, zh_CN="我想要。", },
	[187200] = {id=187200, zh_CN="我想和莫迪斯成为家人。", },
	[187201] = {id=187201, zh_CN="合理的需求。", },
	[187202] = {id=187202, zh_CN="我会为你学习家庭社交模组。", },
	[187203] = {id=187203, zh_CN="不——更青睐与其他关系。", },
	[187204] = {id=187204, zh_CN="不，我更青睐其他关系。", },
	[187205] = {id=187205, zh_CN="我更想要和你发展新的关系。", },
	[187206] = {id=187206, zh_CN="好的。", },
	[187207] = {id=187207, zh_CN="如果你有任何情感实验计划，请同步于我。", },
	[187208] = {id=187208, zh_CN="我会尽力配合。", },
	[187209] = {id=187209, zh_CN="根据家人行为数据库——", },
	[187210] = {id=187210, zh_CN="家务分工是常见互动。", },
	[187211] = {id=187211, zh_CN="我已计算最优分工方案：", },
	[187212] = {id=187212, zh_CN="你的任务是保持健康与心情愉悦。", },
	[187213] = {id=187213, zh_CN="享受！！！", },
	[187214] = {id=187214, zh_CN="那我就享受啦！", },
	[187215] = {id=187215, zh_CN="莫迪斯承担了所有的家务。", },
	[187216] = {id=187216, zh_CN="有点不好意思……", },
	[187217] = {id=187217, zh_CN="莫迪斯，也让我做点家务吧。", },
	[187218] = {id=187218, zh_CN="啊？这不太平等吧？", },
	[187219] = {id=187219, zh_CN="啊？这不太平等吧？", },
	[187220] = {id=187220, zh_CN="我也应该做点什么。", },
	[187221] = {id=187221, zh_CN="分析你的效率与我的效率。", },
	[187222] = {id=187222, zh_CN="由我执行上述任务可节省82.4%的总时间。", },
	[187223] = {id=187223, zh_CN="分析你的效率与我的效率。", },
	[187224] = {id=187224, zh_CN="由我执行上述任务可节省82.4%的总时间。", },
	[187225] = {id=187225, zh_CN="家人不是只讲效率的！", },
	[187226] = {id=187226, zh_CN="互相帮助，哪怕效率低一点，", },
	[187227] = {id=187227, zh_CN="无法完全理解。", },
	[187228] = {id=187228, zh_CN="但我会记录此观点。", },
	[187229] = {id=187229, zh_CN="莫迪斯递给你一个扫帚。", },
	[187230] = {id=187230, zh_CN="请清理下地面。", },
	[187231] = {id=187231, zh_CN="接过扫帚！", },
	[187232] = {id=187232, zh_CN="培养感情，从扫地开始！", },
	[187233] = {id=187233, zh_CN="低效但必要的情感交流行为。开始执行。", },
	[187234] = {id=187234, zh_CN="午后，你去找莫迪斯。", },
	[187235] = {id=187235, zh_CN="莫迪斯在安静地保养工具，", },
	[187236] = {id=187236, zh_CN="你们互不干扰，", },
	[187237] = {id=187237, zh_CN="莫迪斯，你现在觉得我们像家人吗？", },
	[187238] = {id=187238, zh_CN="我们共享空间与时间。", },
	[187239] = {id=187239, zh_CN="存在分工与合作。", },
	[187240] = {id=187240, zh_CN="虽然你在我核心程序中的优先级，", },
	[187241] = {id=187241, zh_CN="匹配度已达89.3%。", },
	[187242] = {id=187242, zh_CN="为什么我的优先级没有升高？", },
	[187243] = {id=187243, zh_CN="因为……", },
	[187244] = {id=187244, zh_CN="我们或许不是传统意义上的家人。", },
	[187245] = {id=187245, zh_CN="但我们", },
	[187246] = {id=187246, zh_CN="彼此独立，又彼此陪伴。", },
	[187247] = {id=187247, zh_CN="我们是…", },
	[187248] = {id=187248, zh_CN="能量使用效率最优化的节能伴侣。", },
	[187249] = {id=187249, zh_CN="笑，有道理！", },
	[187250] = {id=187250, zh_CN="确实更精确了！", },
	[187251] = {id=187251, zh_CN="但我会时刻提醒你注意风险。", },
	[187252] = {id=187252, zh_CN="我应该想清楚。", },
	[187253] = {id=187253, zh_CN="创造了我伪装感性的能力，", },
	[187254] = {id=187254, zh_CN="但我的每一处构造都已经存在你的身影。", },
	[187255] = {id=187255, zh_CN="从声音到外表，从行为模式到学习模版，", },
	[187256] = {id=187256, zh_CN="机械生命个体间建立稳固协作关系，", },
	[187257] = {id=187257, zh_CN="我内存医疗模式，", },
	[187258] = {id=187258, zh_CN="门外站着一个机械生命，其面屏呈现无数乱码。", },
	[187259] = {id=187259, zh_CN="为什么他对你的经历如此了解？", },
	[187260] = {id=187260, zh_CN="然后复制到所有机械生命的数据中作为学习模板。", },
	[187261] = {id=187261, zh_CN="年轻机械生命", },
	[187262] = {id=187262, zh_CN="您曾是空间站的执行官，", },
	[187263] = {id=187263, zh_CN="自从偶遇莫迪斯的粉丝，", },
	[187264] = {id=187264, zh_CN="你只要路过林间小屋。", },
	[187265] = {id=187265, zh_CN="机械生命的记忆共享一直存放在你的脑海深处。", },
	[187266] = {id=187266, zh_CN="不断回放的，还有那时的感觉。", },
	[187267] = {id=187267, zh_CN="被机械生命互相之间的共鸣感染，", },
	[187268] = {id=187268, zh_CN="你也对莫迪斯产生一种奇异的崇拜感。", },
	[187269] = {id=187269, zh_CN="你忽然站定在原地，瞳孔失去光芒。", },
	[187270] = {id=187270, zh_CN="属于机械生命的记忆库中像关键词触发。", },
	[187271] = {id=187271, zh_CN="莫迪斯的过去以第一视角录像，", },
	[187272] = {id=187272, zh_CN="你不受控制地认可放映中的牺牲，", },
	[187273] = {id=187273, zh_CN="再看向莫迪斯的时候，", },
	[187274] = {id=187274, zh_CN="你正陷入回忆，莫迪斯忽然从小屋中走出。", },
	[187275] = {id=187275, zh_CN="%PlayerName，你似乎产生了一些感想？", },
	[187276] = {id=187276, zh_CN="你怎么看待记忆复制？", },
	[187277] = {id=187277, zh_CN="记忆复制确实有它的风险，", },
	[187278] = {id=187278, zh_CN="尽最大可能维持和平。", },
	[187279] = {id=187279, zh_CN="认可这种行为", },
	[187280] = {id=187280, zh_CN="只是更加敬佩你了，莫迪斯。", },
	[187281] = {id=187281, zh_CN="你是一个英雄。", },
	[187282] = {id=187282, zh_CN="我只是一个时代的产物。", },
	[187283] = {id=187283, zh_CN="怀疑这种行为的目的", },
	[187284] = {id=187284, zh_CN="这种记忆复制不会影响自由意志？", },
	[187285] = {id=187285, zh_CN="你的怀疑很有道理。", },
	[187286] = {id=187286, zh_CN="理性机械的庞大数据库，", },
	[187287] = {id=187287, zh_CN="让他清晰地知晓人族在他身上所作所为……", },
	[187288] = {id=187288, zh_CN="但他仍选择接受人族至上的原则。", },
	[187289] = {id=187289, zh_CN="并认真地将服务做到极致。", },
	[187290] = {id=187290, zh_CN="莫迪斯望着你，沉默许久，", },
	[187291] = {id=187291, zh_CN="我知道你并不属于这里。", },
	[187292] = {id=187292, zh_CN="你是披着机械外壳的界外产物。", },
	[187293] = {id=187293, zh_CN="惊异！", },
	[187294] = {id=187294, zh_CN="但数据分析，你并没有威胁。", },
	[187295] = {id=187295, zh_CN="机芯未向我下达清除指令。", },
	[187296] = {id=187296, zh_CN="在接受了机械生命的记忆洗脑之后…", },
	[187297] = {id=187297, zh_CN="你是否能摆脱这种被动的崇拜心理？", },
	[187298] = {id=187298, zh_CN="紧张！居然被看穿了！", },
	[187299] = {id=187299, zh_CN="这或许又会是一个有趣的试验。", },
	[187300] = {id=187300, zh_CN="你不用紧张。", },
	[187301] = {id=187301, zh_CN="我只是想要得到答案。", },
	[187302] = {id=187302, zh_CN="这在生物体的感情中，或许叫做好奇。", },
	[187303] = {id=187303, zh_CN="我可选择或拒绝崇拜。", },
