	[187476] = {id=187476, zh_CN="莫迪斯用沾满机油的布料擦拭手指。", },
	[187477] = {id=187477, zh_CN="曾隶属于空间站编制。", },
	[187478] = {id=187478, zh_CN="和非数据支持的语言而皱眉。", },
	[187479] = {id=187479, zh_CN="我当然会满足您的任何需求。", },
	[187480] = {id=187480, zh_CN="保持高水平的机械修复和维护能力，", },
	[187481] = {id=187481, zh_CN="修理工作是我自我维持和完善的方式。", },
	[187482] = {id=187482, zh_CN="我当然会满足您的任何需求。", },
	[187483] = {id=187483, zh_CN="你都可以要求我为你代劳。", },
	[187484] = {id=187484, zh_CN="您现在的骨骼强度刚过及格线，", },
	[187485] = {id=187485, zh_CN="对于有利于生物体发展，", },
	[187486] = {id=187486, zh_CN="机械生命可以提供合理的服务。", },
	[187487] = {id=187487, zh_CN="达0.009％，获取途径为投彩。", },
	[187488] = {id=187488, zh_CN="机械生命为什么将我种族利益看得那么重？", },
	[187489] = {id=187489, zh_CN="我的“思想”，记忆，", },
	[187490] = {id=187490, zh_CN="与生物体力所能及之事，", },
	[187491] = {id=187491, zh_CN="全部都基于原则的土壤。", },
	[187492] = {id=187492, zh_CN="在于主动性和功能不同。", },
	[187493] = {id=187493, zh_CN="或功能性更加专精。", },
	[187494] = {id=187494, zh_CN="我可以通过案例分析，", },
	[187495] = {id=187495, zh_CN="装扮出人族行为。", },
	[187496] = {id=187496, zh_CN="我可以变成您的任何理想型。", },
	[187497] = {id=187497, zh_CN="周围的待维修的机械生命焦急地等待着。", },
	[187498] = {id=187498, zh_CN="莫迪斯半跪在一个机械生命旁，", },
	[187499] = {id=187499, zh_CN="手臂上的工具迅速切换，", },
	[187500] = {id=187500, zh_CN="你现在变成“永不停歇”的陀螺了？", },
	[187501] = {id=187501, zh_CN="如有修理需求，", },
	[187502] = {id=187502, zh_CN="请在工作台获取号码。", },
	[187503] = {id=187503, zh_CN="2小时45分32秒。", },
	[187504] = {id=187504, zh_CN="2小时45分32秒。", },
	[187505] = {id=187505, zh_CN="未来的5小时22分26秒已经被预定了。", },
	[187506] = {id=187506, zh_CN="如果莫迪斯有帮手，提高速度，", },
	[187507] = {id=187507, zh_CN="机械关节迅速转动，重复修理工作。", },
	[187508] = {id=187508, zh_CN="机械关节迅速转动，重复修理工作。", },
	[187509] = {id=187509, zh_CN="心里清楚在修理机械上帮不上莫迪斯什么。", },
	[187510] = {id=187510, zh_CN="以及加快你们结束修理的时间……", },
	[187511] = {id=187511, zh_CN="机械生命间隔几米在小屋门口整齐划一地排队。", },
	[187512] = {id=187512, zh_CN="他们是从空间站来的。", },
	[187513] = {id=187513, zh_CN="数据显示：", },
	[187514] = {id=187514, zh_CN="又低下头去工作。", },
	[187515] = {id=187515, zh_CN="让小屋方圆几十米如同蒸拿房。", },
	[187516] = {id=187516, zh_CN="其他闲杂人等都禁止入内。", },
	[187517] = {id=187517, zh_CN="小屋里弥漫着金属和机油的气味。", },
	[187518] = {id=187518, zh_CN="可以给你减少很多交流的阻碍。", },
	[187519] = {id=187519, zh_CN="一颗暗色的种子落在地上。", },
	[187520] = {id=187520, zh_CN="“杜鹃”缓缓绽放，花蕊从层叠的花瓣中探出……", },
	[187521] = {id=187521, zh_CN="由冰冷机械创造的理智物体，", },
	[187522] = {id=187522, zh_CN="比如没有考虑我的口味。", },
	[187523] = {id=187523, zh_CN="是否与菜谱制作的环境相同。", },
	[187524] = {id=187524, zh_CN="你的建议很有参考价值，", },
