	[187549] = {id=187549, zh_CN="你努力掩饰着自己的表情。", },
	[187550] = {id=187550, zh_CN="是否与菜谱制作的环境相同。", },
	[187551] = {id=187551, zh_CN="你努力掩饰着自己的表情。", },
