	[187588] = {id=187588, zh_CN="内部发出轻微的处理器运转声。", },
	[187589] = {id=187589, zh_CN="交互的边界和义务都会变得模糊。", },
	[187590] = {id=187590, zh_CN="反反复复。", },
	[187591] = {id=187591, zh_CN="但数据分析并非没有道理，可以尝试。", },
	[187592] = {id=187592, zh_CN="基于血缘、婚姻或法律纽带共同居住生活的个体集合。", },
	[187593] = {id=187593, zh_CN="也是情感交流的一部分。", },
	[187594] = {id=187594, zh_CN="而你在角落发呆，晒太阳。", },
