	[187598] = {id=187598, zh_CN="我们并没有干预彼此的空间和时间。", },
	[187599] = {id=187599, zh_CN="从而更加深入的研究感情，你觉得呢？", },
	[187600] = {id=187600, zh_CN="但是风险很高，并不适合实践。", },
