	[187605] = {id=187605, zh_CN="理想化的感情反馈。", },
	[187606] = {id=187606, zh_CN="你控制住自己的情绪的可能是12％。", },
	[187607] = {id=187607, zh_CN="他都在努力扮演着完美伴侣的角色。", },
