	[187692] = {id=187692, zh_CN="望着被群山环绕的城镇。", },
	[187693] = {id=187693, zh_CN="狗只关心明天肉丸够不够大！", },
	[187694] = {id=187694, zh_CN="再说了，", },
	[187695] = {id=187695, zh_CN="跳下城垛，踏入街道的黑暗之中。", },
	[187696] = {id=187696, zh_CN="我好像听到有人在家里吵架了，", },
