	[187700] = {id=187700, zh_CN="小金毛叼着一篮刚烤好的骨头饼干站在门口。", },
	[187701] = {id=187701, zh_CN="汪！%PlayerName！新邻居的礼物！", },
	[187702] = {id=187702, zh_CN="接过篮子——快进来！", },
	[187703] = {id=187703, zh_CN="好香啊！", },
