	[187942] = {id=187942, zh_CN="又是你俩！给我把墙上的狗爪印擦干净！", },
	[187943] = {id=187943, zh_CN="宠物店豪华狗窝里塞进一只不情愿的猫，", },
	[187944] = {id=187944, zh_CN="小金毛窝在狗窝里，像一张顺滑的毛毯。", },
	[187945] = {id=187945, zh_CN="你睡在小金毛起伏的肚腹上，", },
	[187946] = {id=187946, zh_CN="伸爪对着小金毛挠来挠去，表示着不满！", },
	[187947] = {id=187947, zh_CN="你怎么不和我说是试用狗窝！", },
	[187948] = {id=187948, zh_CN="我堂堂猫族，怎么能屈居在狗窝之中。", },
	[187949] = {id=187949, zh_CN="可是，老大你也没说要看委托细节呀。", },
	[187950] = {id=187950, zh_CN="你将头埋进小金毛的腹毛之中。", },
	[187951] = {id=187951, zh_CN="下次注意！", },
	[187952] = {id=187952, zh_CN="你试着踩了踩小金毛身下的狗窝。", },
	[187953] = {id=187953, zh_CN="地板怎么能只铺一层绒布呢，太硬了。", },
	[187954] = {id=187954, zh_CN="我会记下的，建议加点绵绒。", },
	[187955] = {id=187955, zh_CN="又用爪子拍打绒布", },
	[187956] = {id=187956, zh_CN="棉绒太软，对腰不好。", },
	[187957] = {id=187957, zh_CN="你绕着狗窝转圈。", },
	[187958] = {id=187958, zh_CN="包裹性不够，会冷的。", },
	[187959] = {id=187959, zh_CN="小金毛立刻将你叼到自己的肚上，", },
	[187960] = {id=187960, zh_CN="用尾巴盖住你。", },
	[187961] = {id=187961, zh_CN="好的，增加包裹性要写入建议。", },
	[187962] = {id=187962, zh_CN="沾上的茸毛也要能及时清理。", },
	[187963] = {id=187963, zh_CN="你因为尾巴的狗毛飞絮，打了喷嚏。", },
	[187964] = {id=187964, zh_CN="收到。", },
	[187965] = {id=187965, zh_CN="老大看看还有什么需要修改的？", },
	[187966] = {id=187966, zh_CN="小金毛默默用尾巴扫去飞絮，", },
	[187967] = {id=187967, zh_CN="将记录表叼给你。", },
	[187968] = {id=187968, zh_CN="记录得还不错！", },
	[187969] = {id=187969, zh_CN="小金毛从肚皮下掏出私藏小鱼干。", },
	[187970] = {id=187970, zh_CN="老大建议的好！", },
	[187971] = {id=187971, zh_CN="你在小金毛背上踩来踩去，", },
	[187972] = {id=187972, zh_CN="最终选中一处缩成一团，", },
	[187973] = {id=187973, zh_CN="瘫进“小金毛牌毛毯”中。", },
	[187974] = {id=187974, zh_CN="小金毛的尾巴毛轻轻拍打地板。", },
	[187975] = {id=187975, zh_CN="别吵喵……", },
	[187976] = {id=187976, zh_CN="小金毛立刻停下动作，", },
	[187977] = {id=187977, zh_CN="连呼吸的身体起伏都放轻下来。", },
	[187978] = {id=187978, zh_CN="一夜安眠，", },
	[187979] = {id=187979, zh_CN="第二日你与小金毛上交的爪印评分表上墨迹斑斑。", },
	[187980] = {id=187980, zh_CN="勉强及格。", },
	[187981] = {id=187981, zh_CN="你将猫爪按在满分区，尾巴偷偷圈住狗爪印。", },
	[187982] = {id=187982, zh_CN="小金毛对着爪印傻笑。", },
	[187983] = {id=187983, zh_CN="老大口是心非。", },
	[187984] = {id=187984, zh_CN="一只枕头砸向小金毛的脸蛋，", },
	[187985] = {id=187985, zh_CN="止住了它呜咽笑语。", },
	[187986] = {id=187986, zh_CN="你与小金毛成了欢喜冤家。", },
	[187987] = {id=187987, zh_CN="想不想搬来社区跟我做邻居呀？", },
	[187988] = {id=187988, zh_CN="汪？好突然。", },
	[187989] = {id=187989, zh_CN="有可以随意奔跑的小院……", },
	[187990] = {id=187990, zh_CN="冬暖夏凉的阳房……", },
	[187991] = {id=187991, zh_CN="还有允许招待光灵的洗浴打理店……", },
	[187992] = {id=187992, zh_CN="可以有更多的时间去陪伴光灵们……", },
	[187993] = {id=187993, zh_CN="你这么努力工作……", },
	[187994] = {id=187994, zh_CN="小金毛买不起那么大的屋子。", },
	[187995] = {id=187995, zh_CN="你蹲下身，将小金毛脑袋托起。", },
	[187996] = {id=187996, zh_CN="大家一起住在社区里，肯定很热闹。", },
	[187997] = {id=187997, zh_CN="你加入，肯定会喜欢上这里的。", },
	[187998] = {id=187998, zh_CN="而且也有居民养光灵宠物啊。", },
	[187999] = {id=187999, zh_CN="比如帮邻居采买物品……", },
	[188000] = {id=188000, zh_CN="帮大家传话也能少跑点路。", },
	[188001] = {id=188001, zh_CN="无论是陪伴光灵更多的时间，", },
	[188002] = {id=188002, zh_CN="还是有精力赚更多委托费，", },
	[188003] = {id=188003, zh_CN="太麻烦你了吧。", },
	[188004] = {id=188004, zh_CN="小金毛闪过犹豫，", },
	[188005] = {id=188005, zh_CN="尾巴耷拉落地，闭眼躲闪你的注视。", },
	[188006] = {id=188006, zh_CN="这样，你也不愿意接受吗？", },
	[188007] = {id=188007, zh_CN="小金毛慌张抬头！", },
	[188008] = {id=188008, zh_CN="小金毛尾巴晃动着，眼神有一丝松动。", },
	[188009] = {id=188009, zh_CN="给我撸光灵，给我当跟班。", },
	[188010] = {id=188010, zh_CN="就这么决定啦，喵喵。", },
	[188011] = {id=188011, zh_CN="视线逐渐模糊，闷头撞上路边的垃圾桶。", },
	[188012] = {id=188012, zh_CN="疼痛瞬间袭来，", },
	[188013] = {id=188013, zh_CN="委托单洋洋洒洒飘落在地上，", },
	[188014] = {id=188014, zh_CN="小金毛坐在地上用前爪揉了揉红肿的脑袋。", },
	[188015] = {id=188015, zh_CN="为什么不和委托人说明情况，取消委托呢？", },
	[188016] = {id=188016, zh_CN="小金毛……小金毛做不到拒绝别人，", },
	[188017] = {id=188017, zh_CN="不用给我分报酬，都是你的。", },
	[188018] = {id=188018, zh_CN="就这么说定啦！", },
	[188019] = {id=188019, zh_CN="小金毛跃起，用脑袋轻轻撞击你的拳头，", },
	[188020] = {id=188020, zh_CN="一个击拳像石子砸入你和小金毛的心湖，", },
	[188021] = {id=188021, zh_CN="泛起涟漪。", },
	[188022] = {id=188022, zh_CN="可是会抢走你的委托的。", },
	[188023] = {id=188023, zh_CN="对不起，我还是……", },
	[188024] = {id=188024, zh_CN="你决定……", },
	[188025] = {id=188025, zh_CN="你与小金毛的目光被霞紫色的花瓣吸引，", },
	[188026] = {id=188026, zh_CN="你将小金毛头顶的寒豆兰拍落。", },
	[188027] = {id=188027, zh_CN="东边采一朵，南边采一朵，", },
	[188028] = {id=188028, zh_CN="西边采一朵，南边采一朵，", },
	[188029] = {id=188029, zh_CN="好看的花，小金毛都要采给他欣赏，", },
	[188030] = {id=188030, zh_CN="67％的人族会准备生前喜爱的事物作为祭奠品。", },
	[188031] = {id=188031, zh_CN="表达思念花语的花？", },
	[188032] = {id=188032, zh_CN="那天从你胸口飞出的情绪花碎片，", },
	[188033] = {id=188033, zh_CN="就是表达思念的铃兰，", },
	[188034] = {id=188034, zh_CN="盯着自己的爪子。", },
	[188035] = {id=188035, zh_CN="……但小金毛爪笨，做不出来。", },
	[188036] = {id=188036, zh_CN="你抚摸着小金毛的背毛。", },
	[188037] = {id=188037, zh_CN="你可以委托我来帮你做。", },
	[188038] = {id=188038, zh_CN="梳下你的背毛插进毛毡里，", },
	[188039] = {id=188039, zh_CN="它小心翼翼调整姿势，", },
	[188040] = {id=188040, zh_CN="生怕压坏娇嫩的花瓣。", },
	[188041] = {id=188041, zh_CN="风吹起几片花瓣，", },
	[188042] = {id=188042, zh_CN="飘落在小金毛的鼻尖，", },
	[188043] = {id=188043, zh_CN="馥郁的花香填满它的鼻腔……", },
	[188044] = {id=188044, zh_CN="小金毛眼睛微微眯起，", },
	[188045] = {id=188045, zh_CN="旧主人最喜欢的松露面包！", },
	[188046] = {id=188046, zh_CN="听老板说改良了口味，", },
	[188047] = {id=188047, zh_CN="不知道他还喜不喜欢。", },
	[188048] = {id=188048, zh_CN="他会喜欢的。", },
	[188049] = {id=188049, zh_CN="千年春色献君，", },
	[188050] = {id=188050, zh_CN="你和旧主人都是小金毛很重要的存在，", },
	[188051] = {id=188051, zh_CN="小金毛要亲自介绍你们认识。", },
	[188052] = {id=188052, zh_CN="小金毛引领着你踏上了，", },
	[188053] = {id=188053, zh_CN="过去它独自一人探寻旧主人的路途。", },
	[188054] = {id=188054, zh_CN="小金毛用爪垫擦拭着墓碑上的灰尘，", },
	[188055] = {id=188055, zh_CN="将“礼物”一件件摆在墓碑前。", },
	[188056] = {id=188056, zh_CN="弄得公共区域臭了，", },
	[188057] = {id=188057, zh_CN="可以在城镇东角设置一个收集点，", },
	[188058] = {id=188058, zh_CN="我们要求市容管理所将流浪光灵看管起来，", },
	[188059] = {id=188059, zh_CN="有错吗？", },
	[188060] = {id=188060, zh_CN="明明有折中的办法，小金毛都想出来了。", },
	[188061] = {id=188061, zh_CN="就是它说要在草坪上，", },
	[188062] = {id=188062, zh_CN="划出收集排泄物的区域，", },
	[188063] = {id=188063, zh_CN="说什么木屑发酵，花肥再利用。", },
	[188064] = {id=188064, zh_CN="无法做到不影响其他种族的生活，", },
	[188065] = {id=188065, zh_CN="当然要被市容管理所收容管理。", },
	[188066] = {id=188066, zh_CN="难道你要去陪他们吗？", },
	[188067] = {id=188067, zh_CN="被市容管理所关起来？", },
	[188068] = {id=188068, zh_CN="你们！你们欺负光灵，欺负弱小！", },
	[188069] = {id=188069, zh_CN="他们只能在荒野中，", },
	[188070] = {id=188070, zh_CN="乡间甚至城市的缝隙间生存。", },
	[188071] = {id=188071, zh_CN="你的提议出发点是好的。", },
	[188072] = {id=188072, zh_CN="但只存在于纸上，你也没有实践，", },
	[188073] = {id=188073, zh_CN="不能让其他居民与你共同承担后果！", },
	[188074] = {id=188074, zh_CN="激烈的情绪即将被点炸，", },
	[188075] = {id=188075, zh_CN="所有人都陷入沉默。", },
	[188076] = {id=188076, zh_CN="你与小金毛都低着头，", },
	[188077] = {id=188077, zh_CN="小金毛避开眼神，拒绝对视，", },
	[188078] = {id=188078, zh_CN="我们猫族拉屎都知道埋到土里，", },
	[188079] = {id=188079, zh_CN="他们为什么不行？", },
	[188080] = {id=188080, zh_CN="原来是……和狗学的，喵~", },
	[188081] = {id=188081, zh_CN="不如，你们一起进收容所吧，", },
	[188082] = {id=188082, zh_CN="管教好了再出来。", },
	[188083] = {id=188083, zh_CN="汪汪！", },
	[188084] = {id=188084, zh_CN="你轻盈地跳到沙发上，", },
	[188085] = {id=188085, zh_CN="居高临下地盯着小金毛，", },
	[188086] = {id=188086, zh_CN="小金毛四肢一蹬，", },
	[188087] = {id=188087, zh_CN="瞬间与你纠缠在一起。", },
	[188088] = {id=188088, zh_CN="猫爪不断挥舞，", },
	[188089] = {id=188089, zh_CN="锋利的指甲在狗的毛发中划过，", },
	[188090] = {id=188090, zh_CN="发出轻微的“嘶嘶”声。", },
	[188091] = {id=188091, zh_CN="狗也不示弱，用嘴巴轻轻咬住猫的后腿。", },
	[188092] = {id=188092, zh_CN="周围居民见情况不对，", },
	[188093] = {id=188093, zh_CN="立刻将你们分开，讨论会便也不了了之。", },
	[188094] = {id=188094, zh_CN="激烈的情绪即将被点炸，", },
	[188095] = {id=188095, zh_CN="所有人都陷入沉默。", },
	[188096] = {id=188096, zh_CN="你与小金毛都低着头，", },
	[188097] = {id=188097, zh_CN="小金毛避开眼神，拒绝对视。", },
	[188098] = {id=188098, zh_CN="片刻叼着急救包回来。", },
	[188099] = {id=188099, zh_CN="它用爪子笨拙地缠纱布……", },
	[188100] = {id=188100, zh_CN="疼就说……", },
	[188101] = {id=188101, zh_CN="狗耳朵被你挠出红痕，", },
	[188102] = {id=188102, zh_CN="你的尾巴烦躁地拍地！", },
	[188103] = {id=188103, zh_CN="轻点！你当是捆火腿肠？！", },
	[188104] = {id=188104, zh_CN="你突然瞥见狗爪上的旧伤疤——", },
	[188105] = {id=188105, zh_CN="对于上次抓你，我表示抱歉……", },
	[188106] = {id=188106, zh_CN="属于他们的区域。", },
	[188107] = {id=188107, zh_CN="可以不用很大，但是……至少要有一个。", },
	[188108] = {id=188108, zh_CN="晚风卷着槐花香飘过，你踢飞小石子。", },
	[188109] = {id=188109, zh_CN="未来如果还有讨论会，我还会反对你。", },
	[188110] = {id=188110, zh_CN="正好！我也找到新数据了！", },
	[188111] = {id=188111, zh_CN="城墙下响起追逐打闹声，", },
	[188112] = {id=188112, zh_CN="一猫一狗追逐着，", },
	[188113] = {id=188113, zh_CN="行踪诡秘。", },
	[188114] = {id=188114, zh_CN="【流浪光灵之家】", },
	[188115] = {id=188115, zh_CN="【半个守夜人】", },
	[188116] = {id=188116, zh_CN="【记忆中的宝藏】", },
	[188117] = {id=188117, zh_CN="【来做我的邻居】", },
	[188118] = {id=188118, zh_CN="【邻居的礼物】", },
	[188119] = {id=188119, zh_CN="【忙晕的邻居】", },
	[188120] = {id=188120, zh_CN="【焦躁的陀螺金毛】", },
	[188121] = {id=188121, zh_CN="【委托搭档】", },
	[188122] = {id=188122, zh_CN="【最强搭档】", },
	[188123] = {id=188123, zh_CN="【狭路相逢冤家胜】", },
	[188124] = {id=188124, zh_CN="【千年春色献故人】", },
	[188125] = {id=188125, zh_CN="【旧人新友】", },
	[188126] = {id=188126, zh_CN="【又是一年春】", },
	[188127] = {id=188127, zh_CN="【社区辩论赛】", },
	[188128] = {id=188128, zh_CN="【城墙下的和解】", },
	[188129] = {id=188129, zh_CN="汪！%PlayerName你来啦！今天要给小金毛培养感情，去做委托吗？", },
	[188130] = {id=188130, zh_CN="你握紧种子，花影消失。", },
	[188131] = {id=188131, zh_CN="小金毛也已走远。", },
	[188132] = {id=188132, zh_CN="它正回头望你。", },
	[188133] = {id=188133, zh_CN="花草交映中，它的尾巴如蓬草兴奋摇曳。", },
	[188134] = {id=188134, zh_CN="平稳地落在石阶上。", },
	[188135] = {id=188135, zh_CN="它弓背炸毛，高高竖起尾巴。", },
	[188136] = {id=188136, zh_CN="雷达耳左右转动着，到处观察着……", },
	[188137] = {id=188137, zh_CN="喵嗷——！", },
	[188138] = {id=188138, zh_CN="年糕缩成一团。", },
	[188139] = {id=188139, zh_CN="它甩尾捂住自己的眼睛。", },
	[188140] = {id=188140, zh_CN="耳朵紧贴脑袋，瑟瑟发抖。", },
	[188141] = {id=188141, zh_CN="不要害怕，我是勇敢的侦探……", },
	[188142] = {id=188142, zh_CN="幽灵在漫游猫猫乐园了吗？", },
	[188143] = {id=188143, zh_CN="我……我已经找寻到你的踪迹了……", },
	[188144] = {id=188144, zh_CN="我只是一只胆小鬼侦探……", },
	[188145] = {id=188145, zh_CN="请不要继续吓我。", },
	[188146] = {id=188146, zh_CN="毛茸的尾巴挡住你的视线，", },
	[188147] = {id=188147, zh_CN="将自己团团围住，", },
	[188148] = {id=188148, zh_CN="年糕便不怕了。", },
	[188149] = {id=188149, zh_CN="年糕惊跳到半空，", },
	[188150] = {id=188150, zh_CN="翻身落在你面前。", },
	[188151] = {id=188151, zh_CN="它用尾巴捂住眼睛。", },
	[188152] = {id=188152, zh_CN="不，不要过来啊。", },
	[188153] = {id=188153, zh_CN="呜呜呜呜呜……", },
	[188154] = {id=188154, zh_CN="我把我赚来的小鱼干都给你。", },
	[188155] = {id=188155, zh_CN="你不要吃我，求求你了。", },
	[188156] = {id=188156, zh_CN="看清你的面孔，它扑向你，", },
	[188157] = {id=188157, zh_CN="给你一个大大的抱抱。", },
	[188158] = {id=188158, zh_CN="喵喵！", },
	[188159] = {id=188159, zh_CN="它四爪交叉地跳舞，炫耀着“知识”。", },
	[188160] = {id=188160, zh_CN="它尾巴绕成一个灯泡的形状……", },
	[188161] = {id=188161, zh_CN="它尾巴绕成一个灯泡的形状……", },
	[188162] = {id=188162, zh_CN="它尾巴绕成一个灯泡的形状……", },
	[188163] = {id=188163, zh_CN="它尾巴绞成问号……", },
	[188164] = {id=188164, zh_CN="最后一个问题！", },
	[188165] = {id=188165, zh_CN="年糕眼睛亮亮，一脸崇拜。", },
	[188166] = {id=188166, zh_CN="年糕尾巴翘起，激动颤抖！", },
	[188167] = {id=188167, zh_CN="海里的巴别族是小鱼干预制品，但……", },
	[188168] = {id=188168, zh_CN="你不相信我，", },
	[188169] = {id=188169, zh_CN="请你左手按在喵喵我的爪上。", },
	[188170] = {id=188170, zh_CN="可恶的记忆涌上心头！！", },
	[188171] = {id=188171, zh_CN="喵喵侦探，我通过面试了吗？", },
	[188172] = {id=188172, zh_CN="紧张……", },
	[188173] = {id=188173, zh_CN="年糕泪眼汪汪。", },
	[188174] = {id=188174, zh_CN="难道喵喵我要独自奋战在与恶势力对抗的前线吗？", },
	[188175] = {id=188175, zh_CN="它惊喜回头，伸出爪爪。", },
	[188176] = {id=188176, zh_CN="你伸出手按在年糕的爪爪上。", },
	[188177] = {id=188177, zh_CN="年糕跳上你的肩头，尾巴尖塌下，扫过你的耳廓。", },
	[188178] = {id=188178, zh_CN="一颗光滑坚硬的褐色花种出现在年糕的爪爪上。", },
	[188179] = {id=188179, zh_CN="欸！这是什么！", },
	[188180] = {id=188180, zh_CN="欲言又止。", },
	[188181] = {id=188181, zh_CN="年糕注意到你关注的目光……", },
	[188182] = {id=188182, zh_CN="给你！", },
	[188183] = {id=188183, zh_CN="就作为你和喵喵我结为搭档的信物吧！", },
	[188184] = {id=188184, zh_CN="哼哼，喵喵我不满意的话，", },
	[188185] = {id=188185, zh_CN="可会收回信物哦。", },
	[188186] = {id=188186, zh_CN="零星的几瓶宽口瓶歪歪扭扭地放在地上。", },
	[188187] = {id=188187, zh_CN="一只花瓶里面放了束花。", },
	[188188] = {id=188188, zh_CN="年糕尾巴高高竖起，黑尾尖颤动着。", },
	[188189] = {id=188189, zh_CN="它黑尾尖划到你眼前！", },
	[188190] = {id=188190, zh_CN="尾巴倏地绷紧，直指花瓶——", },
	[188191] = {id=188191, zh_CN="年糕跳下你的肩膀，围着花瓶转……", },
	[188192] = {id=188192, zh_CN="年糕用爪子挠了挠花瓶。", },
	[188193] = {id=188193, zh_CN="年糕后退几步，站在你的身前，炸毛哈气！", },
	[188194] = {id=188194, zh_CN="它尾巴缠着自己的脚，", },
	[188195] = {id=188195, zh_CN="好似这样可以站稳一些。", },
	[188196] = {id=188196, zh_CN="你上前几步，扒着花瓶的瓶口。", },
	[188197] = {id=188197, zh_CN="年糕惊得后退半步，弓起身。", },
	[188198] = {id=188198, zh_CN="搭档，你去敲敲花瓶。", },
	[188199] = {id=188199, zh_CN="花瓶纹丝不动。", },
	[188200] = {id=188200, zh_CN="年糕用爪子挠了挠花瓶。", },
	[188201] = {id=188201, zh_CN="小鱼干坠入花瓶，底部分出闷响。", },
	[188202] = {id=188202, zh_CN="不慎将花瓶打碎。", },
	[188203] = {id=188203, zh_CN="碎片四分五裂地躺在你的脚下，", },
	[188204] = {id=188204, zh_CN="你伸手去接年糕，却与它错过——", },
	[188205] = {id=188205, zh_CN="布面撕裂成四条，", },
	[188206] = {id=188206, zh_CN="连着你的皮肤都带着几串血珠。", },
	[188207] = {id=188207, zh_CN="啊！", },
	[188208] = {id=188208, zh_CN="它头转到侧面，只有耳朵来回转动……", },
	[188209] = {id=188209, zh_CN="谢谢你。", },
	[188210] = {id=188210, zh_CN="阳光倾斜地穿过缝隙，", },
	[188211] = {id=188211, zh_CN="黑乌乌的影子落在地上。", },
	[188212] = {id=188212, zh_CN="年糕踮起脚尖，尾巴落地，匍匐着前进。", },
	[188213] = {id=188213, zh_CN="它紧绷的身躯跳到半空，", },
	[188214] = {id=188214, zh_CN="翻身扑向地上的黑影。", },
	[188215] = {id=188215, zh_CN="发现敌方黑影！", },
	[188216] = {id=188216, zh_CN="你望着专心致志的年糕，无奈摇头。", },
	[188217] = {id=188217, zh_CN="搭档搭档！", },
	[188218] = {id=188218, zh_CN="我在！", },
	[188219] = {id=188219, zh_CN="毫无缓冲地奔向地面，一个帅气的猫啃泥！", },
	[188220] = {id=188220, zh_CN="强装镇定地站起身来……", },
	[188221] = {id=188221, zh_CN="……", },
	[188222] = {id=188222, zh_CN="搭档！痛喵——！", },
	[188223] = {id=188223, zh_CN="吹吹就不痛了。", },
	[188224] = {id=188224, zh_CN="我们年糕是最伟大最勇敢的侦探大人。", },
	[188225] = {id=188225, zh_CN="它团在你的臂弯里，眼泪汪汪。", },
	[188226] = {id=188226, zh_CN="喵~", },
	[188227] = {id=188227, zh_CN="喵——！", },
	[188228] = {id=188228, zh_CN="所有的一切都陷入阴影之中。", },
	[188229] = {id=188229, zh_CN="“花瓶的黑影”再也找不到了踪迹。", },
	[188230] = {id=188230, zh_CN="年糕眼瞳睁圆。", },
	[188231] = {id=188231, zh_CN="下次喵喵我一定不会放过花瓶嫌疑犯的！", },
	[188232] = {id=188232, zh_CN="它端坐着伸出爪爪，望向你。", },
	[188233] = {id=188233, zh_CN="我要收回给你通过的决定喵。", },
	[188234] = {id=188234, zh_CN="轻轻地抵上年糕的脑袋。", },
	[188235] = {id=188235, zh_CN="年糕被你的拳击掀倒，它蓬头垢面地起身。", },
	[188236] = {id=188236, zh_CN="独属于我们的标记！", },
	[188237] = {id=188237, zh_CN="年糕尾巴翘起。", },
	[188238] = {id=188238, zh_CN="居然连喵喵我都骗过去了！", },
	[188239] = {id=188239, zh_CN="电影厂一处略显昏暗的走廊，", },
	[188240] = {id=188240, zh_CN="窗外乌云密布，雷声隐隐作响。", },
	[188241] = {id=188241, zh_CN="年糕尾巴尖警惕地扫来扫去。", },
	[188242] = {id=188242, zh_CN="正审讯着一只花瓷瓶。", },
	[188243] = {id=188243, zh_CN="嫌疑人花瓶！喵喵我劝你老实交代！", },
	[188244] = {id=188244, zh_CN="昨夜吧台失窃的那条小鱼干，", },
	[188245] = {id=188245, zh_CN="是否就藏匿于你的腹中？", },
	[188246] = {id=188246, zh_CN="喵喵我劝你速速坦白。", },
	[188247] = {id=188247, zh_CN="轰隆——！", },
	[188248] = {id=188248, zh_CN="一道惨白的闪电划破天际。", },
	[188249] = {id=188249, zh_CN="喵嗷——！", },
	[188250] = {id=188250, zh_CN="搭档！搭档你在哪儿！", },
	[188251] = {id=188251, zh_CN="快来接应喵喵我呀！掩护掩护。", },
	[188252] = {id=188252, zh_CN="芝麻糊吓得高高跳起，", },
	[188253] = {id=188253, zh_CN="背毛炸开，像一颗蓬松的白色蒲公英。", },
	[188254] = {id=188254, zh_CN="望见你，它四只小爪子并用。", },
	[188255] = {id=188255, zh_CN="哧溜哧溜地迅速爬上了你的肩膀。", },
	[188256] = {id=188256, zh_CN="别怕，只是打雷而已。", },
	[188257] = {id=188257, zh_CN="哇！侦探大人怎么怕打雷呀？", },
	[188258] = {id=188258, zh_CN="喵喵我才不怕打雷。", },
	[188259] = {id=188259, zh_CN="这……这只是战略性避险。", },
	[188260] = {id=188260, zh_CN="话音刚落，一声炸雷响起。", },
	[188261] = {id=188261, zh_CN="喵哇！又来了！", },
	[188262] = {id=188262, zh_CN="闪电似乎震动了电影厂的电路，", },
	[188263] = {id=188263, zh_CN="廊道的自动扫地机突然被激活，", },
	[188264] = {id=188264, zh_CN="发出低沉的嗡嗡声。", },
	[188265] = {id=188265, zh_CN="钢……钢铁巨兽也苏醒了！", },
	[188266] = {id=188266, zh_CN="雷声是进攻的号角！", },
	[188267] = {id=188267, zh_CN="搭档搭档！快带着喵喵我战略转移！", },
	[188268] = {id=188268, zh_CN="去哪儿都行，立刻！马上！离开电影厂！", },
	[188269] = {id=188269, zh_CN="某日，年糕寻来新的侦探任务。", },
	[188270] = {id=188270, zh_CN="约你一同去调查地点。", },
	[188271] = {id=188271, zh_CN="而你今天到达电影厂集合地的时间稍晚了些。", },
	[188272] = {id=188272, zh_CN="年糕端坐在平台上，", },
	[188273] = {id=188273, zh_CN="尾巴尖有节奏地拍打着地面。", },
	[188274] = {id=188274, zh_CN="喵嗷，哼！", },
	[188275] = {id=188275, zh_CN="你终于出现了。", },
	[188276] = {id=188276, zh_CN="你比约定时间迟到了整整2分33秒！", },
	[188277] = {id=188277, zh_CN="你过来的途中莫非遭遇了小鱼罐头绑架事件？", },
	[188278] = {id=188278, zh_CN="还是被会跳舞的猫草饼干迷惑了心智？", },
	[188279] = {id=188279, zh_CN="抱歉抱歉，是我的错。", },
	[188280] = {id=188280, zh_CN="让小侦探等这么久，对不起嘛。", },
	[188281] = {id=188281, zh_CN="好吧，下不为例哦！", },
	[188282] = {id=188282, zh_CN="哎呀，难道小侦探想我啦？", },
	[188283] = {id=188283, zh_CN="荒谬！喵喵我只是……", },
	[188284] = {id=188284, zh_CN="只是迫切需要一名助手记录探案过程。", },
	[188285] = {id=188285, zh_CN="年糕似无意地甩了甩尾巴。", },
	[188286] = {id=188286, zh_CN="毛茸茸的尾巴尖悄悄绕到你的身后，", },
	[188287] = {id=188287, zh_CN="像柔软的挂钩，轻轻地勾住了你的脚腕。", },
	[188288] = {id=188288, zh_CN="电影厂门口，天色已近黄昏。", },
	[188289] = {id=188289, zh_CN="你和年糕刚刚完成“丢失的毛线球”案件。", },
	[188290] = {id=188290, zh_CN="对着一个滚到商会货架下的线团指挥了半天，", },
	[188291] = {id=188291, zh_CN="年糕看起来累坏了。", },
	[188292] = {id=188292, zh_CN="呼……呼呼。", },
	[188293] = {id=188293, zh_CN="今天破获一桩大案，可累坏喵喵我了。", },
	[188294] = {id=188294, zh_CN="年糕四肢彻底摊开，", },
	[188295] = {id=188295, zh_CN="像一块快要融化了的白色猫饼。", },
	[188296] = {id=188296, zh_CN="只有尾巴尖还偶尔无力地晃动一下。", },
	[188297] = {id=188297, zh_CN="今天消耗的体力，要连续吃了5条小鱼干！", },
	[188298] = {id=188298, zh_CN="喵喵我继续补充搭档的抱抱喵~", },
	[188299] = {id=188299, zh_CN="年糕像液体般向你挪动。", },
	[188300] = {id=188300, zh_CN="先是脑袋蹭上你的腿边，", },
	[188301] = {id=188301, zh_CN="然后整个身体软软地靠了上来。", },
	[188302] = {id=188302, zh_CN="年糕找了个舒服的姿势，枕在你的腿上。", },
	[188303] = {id=188303, zh_CN="它闭上眼，无意识地抬起两只前爪。", },
	[188304] = {id=188304, zh_CN="呼噜噜~", },
	[188305] = {id=188305, zh_CN="它一下下，有节奏地踩奶，", },
	[188306] = {id=188306, zh_CN="下一秒就要进入梦乡。", },
	[188307] = {id=188307, zh_CN="挠下巴。", },
	[188308] = {id=188308, zh_CN="呼噜噜~", },
	[188309] = {id=188309, zh_CN="调整姿势。", },
	[188310] = {id=188310, zh_CN="喵呜！呼噜！", },
	[188311] = {id=188311, zh_CN="柔软的长尾巴熟练地缠绕上你的手腕。", },
	[188312] = {id=188312, zh_CN="辅助喵喵我休息，责任重大！", },
	[188313] = {id=188313, zh_CN="搭档不得擅自离岗……", },
	[188314] = {id=188314, zh_CN="呼噜噜~", },
	[188315] = {id=188315, zh_CN="你有好几天没来陪年糕玩了。", },
	[188316] = {id=188316, zh_CN="今天你来到电影厂时，", },
	[188317] = {id=188317, zh_CN="年糕正围着平台焦躁地来回转圈。", },
	[188318] = {id=188318, zh_CN="它的步伐又快又乱，", },
	[188319] = {id=188319, zh_CN="尾尖不安地颤抖着。", },
	[188320] = {id=188320, zh_CN="搭档失踪！", },
	[188321] = {id=188321, zh_CN="这是长达52个小时的严重失踪事件！", },
	[188322] = {id=188322, zh_CN="喵喵我的追踪术完全失效！", },
	[188323] = {id=188323, zh_CN="差点……差点就要启动紧急预案。", },
	[188324] = {id=188324, zh_CN="向古堡乃至整个星球发布寻人启事了！", },
	[188325] = {id=188325, zh_CN="搭档你到底去哪儿了？", },
	[188326] = {id=188326, zh_CN="好啦，这不是回来了嘛。", },
	[188327] = {id=188327, zh_CN="哼！", },
	[188328] = {id=188328, zh_CN="下次要和喵喵我提前说明原因。", },
	[188329] = {id=188329, zh_CN="不然喵喵我要担心你的。", },
	[188330] = {id=188330, zh_CN="逗它——想起来还有点急事要处理。", },
	[188331] = {id=188331, zh_CN="喵！！", },
	[188332] = {id=188332, zh_CN="禁止撤离！绝对禁止！", },
	[188333] = {id=188333, zh_CN="搭档你要提交一份详细的说明报告给我！", },
	[188334] = {id=188334, zh_CN="仔细说明你失踪离岗的原因！", },
	[188335] = {id=188335, zh_CN="这是严重违纪行为！", },
	[188336] = {id=188336, zh_CN="你要上交小鱼干作为保证金！", },
	[188337] = {id=188337, zh_CN="不准不通知喵喵我呀，", },
	[188338] = {id=188338, zh_CN="就擅自离开喵喵我那么久了！", },
	[188339] = {id=188339, zh_CN="某天，年糕搬来一摞侦探小说。", },
	[188340] = {id=188340, zh_CN="它站在摇摇欲坠的书堆上，", },
	[188341] = {id=188341, zh_CN="尾巴尖像教鞭一样敲打墙壁。", },
	[188342] = {id=188342, zh_CN="搭档！快做好笔记！", },
	[188343] = {id=188343, zh_CN="经喵喵我长达数日……", },
	[188344] = {id=188344, zh_CN="呃，也可能是数小时的深入研究与严谨推理。", },
	[188345] = {id=188345, zh_CN="我们可以得到一个关重要的结论！", },
	[188346] = {id=188346, zh_CN="所有罪犯，无论其种族、犯罪动机如何，", },
	[188347] = {id=188347, zh_CN="都必定会返回犯罪现场！", },
	[188348] = {id=188348, zh_CN="你知道这是为什么吗？", },
	[188349] = {id=188349, zh_CN="期待——什么什么？", },
	[188350] = {id=188350, zh_CN="摇头——不知道。", },
	[188351] = {id=188351, zh_CN="因为他们在挑衅喵喵我呀！", },
	[188352] = {id=188352, zh_CN="在向喵喵我宣战！", },
	[188353] = {id=188353, zh_CN="年糕侦探好厉害！", },
	[188354] = {id=188354, zh_CN="这个理论……听起来很精彩。", },
	[188355] = {id=188355, zh_CN="哼哼，那是当然！", },
	[188356] = {id=188356, zh_CN="小侦探，你在实践中验证过这条定律吗？", },
	[188357] = {id=188357, zh_CN="比如成功抓到过返回现场的小偷？", },
	[188358] = {id=188358, zh_CN="并听到他的亲口承认？", },
	[188359] = {id=188359, zh_CN="当……当然实践过！", },
	[188360] = {id=188360, zh_CN="喵喵我的每一个理论都是无数次现场经验所得！", },
	[188361] = {id=188361, zh_CN="年糕激动地挥舞着爪子，", },
	[188362] = {id=188362, zh_CN="不小心碰倒脚下的那摞书堆。", },
	[188363] = {id=188363, zh_CN="搭档救命！", },
	[188364] = {id=188364, zh_CN="快帮喵喵我顶住智慧的重压！", },
	[188365] = {id=188365, zh_CN="今天，你和芝麻糊正在电影厂调查“失窃的彩虹糖”。", },
	[188366] = {id=188366, zh_CN="角落里，", },
	[188367] = {id=188367, zh_CN="一个圆盘形的自动扫地机正安静地停在充电座上。", },
	[188368] = {id=188368, zh_CN="搭档，根据喵喵我的直觉，", },
	[188369] = {id=188369, zh_CN="此地必然留有线索……喵嗷？！", },
	[188370] = {id=188370, zh_CN="忽然自动扫地机的指示灯亮起，", },
	[188371] = {id=188371, zh_CN="开始按照预定程序进行清扫工作。", },
	[188372] = {id=188372, zh_CN="喵嗷！", },
	[188373] = {id=188373, zh_CN="年糕猛地向后一跳，条件反射般地弓起背。", },
	[188374] = {id=188374, zh_CN="搭……搭档退后！", },
	[188375] = {id=188375, zh_CN="看我先用无敌侦探气势压倒它！", },
	[188376] = {id=188376, zh_CN="哈——呜！", },
	[188377] = {id=188377, zh_CN="上前！挡在中间。", },
	[188378] = {id=188378, zh_CN="你没有犹豫，迅速上前一步。", },
	[188379] = {id=188379, zh_CN="用身体挡在中间，形成一道屏障。", },
	[188380] = {id=188380, zh_CN="年糕，别怕。我来处理它！", },
	[188381] = {id=188381, zh_CN="年糕加油！你可以的！", },
	[188382] = {id=188382, zh_CN="用你的无敌喵喵拳打败它！", },
	[188383] = {id=188383, zh_CN="我相信你！", },
	[188384] = {id=188384, zh_CN="年糕闭紧双眼，像是下定了某种决心！", },
	[188385] = {id=188385, zh_CN="为了搭档！看招吧！", },
	[188386] = {id=188386, zh_CN="正义喵喵拳！", },
	[188387] = {id=188387, zh_CN="喵喵！喵嗷嗷嗷嗷——！", },
	[188388] = {id=188388, zh_CN="将自动扫地机镇压回充电站后，", },
	[188389] = {id=188389, zh_CN="年糕惊魂未定地舔着自己的爪子。", },
	[188390] = {id=188390, zh_CN="喵嗷……搭档。", },
	[188391] = {id=188391, zh_CN="以后遇到这种特殊情况，你需要保护好我。", },
	[188392] = {id=188392, zh_CN="经过喵喵我严谨的风险评估。", },
	[188393] = {id=188393, zh_CN="这种高速旋转、", },
	[188394] = {id=188394, zh_CN="发出噪音且行为不可预测的物体，", },
	[188395] = {id=188395, zh_CN="产生适当的警惕与战略性的敬畏，", },
	[188396] = {id=188396, zh_CN="是完全合理且必要的。", },
	[188397] = {id=188397, zh_CN="这有助于规避风险，", },
	[188398] = {id=188398, zh_CN="是战术层面的谨慎。", },
	[188399] = {id=188399, zh_CN="完全……完全不影响喵喵我英勇无畏之形象！", },
	[188400] = {id=188400, zh_CN="表情严肃——年糕侦探说得对。", },
	[188401] = {id=188401, zh_CN="谨慎是优秀侦探的美德。", },
	[188402] = {id=188402, zh_CN="低头偷笑——噗嗤！", },
	[188403] = {id=188403, zh_CN="严肃点，搭档！", },
	[188404] = {id=188404, zh_CN="现在不是笑的时候！", },
	[188405] = {id=188405, zh_CN="真正的勇士敢于直面恐惧，", },
	[188406] = {id=188406, zh_CN="并且……并且想办法克服它！", },
	[188407] = {id=188407, zh_CN="喵喵我不是胆小猫侦探！", },
	[188408] = {id=188408, zh_CN="喵喵我是现在是“有一点勇敢”猫侦探！", },
	[188409] = {id=188409, zh_CN="电影厂外的一棵树下，", },
	[188410] = {id=188410, zh_CN="年糕正四肢并用地紧紧抱着一根离地颇高的细长树杈，", },
	[188411] = {id=188411, zh_CN="小小的身体随着树枝微微晃动，摇摇欲坠。", },
	[188412] = {id=188412, zh_CN="芝……芝麻糊！", },
	[188413] = {id=188413, zh_CN="姐姐！救命呀！", },
	[188414] = {id=188414, zh_CN="你最聪明、最勇敢的弟弟兼大侦探遭遇树陷阱了！", },
	[188415] = {id=188415, zh_CN="年糕？你需要救援吗？", },
	[188416] = {id=188416, zh_CN="喵？喵嗷！", },
	[188417] = {id=188417, zh_CN="不，不需要。这是获取制高点视野。", },
	[188418] = {id=188418, zh_CN="是喵喵我的战略性地形侦察。", },
	[188419] = {id=188419, zh_CN="作为助理，要记录下伟大的瞬间！", },
	[188420] = {id=188420, zh_CN="作为侦探助理，", },
	[188421] = {id=188421, zh_CN="我要记录下小侦探勇攀高峰的瞬间！", },
	[188422] = {id=188422, zh_CN="年糕，说茄子~", },
	[188423] = {id=188423, zh_CN="哦不对，要说喵~", },
	[188424] = {id=188424, zh_CN="喵嗷！禁止拍摄！", },
	[188425] = {id=188425, zh_CN="搭档快执行备用计划，接住我！", },
	[188426] = {id=188426, zh_CN="跳下来吧，我接住你。", },
	[188427] = {id=188427, zh_CN="年糕往我这里跳，", },
	[188428] = {id=188428, zh_CN="我保证接住你！", },
	[188429] = {id=188429, zh_CN="年糕望着你的方向，心一横，", },
	[188430] = {id=188430, zh_CN="闭上眼睛松开了爪子。", },
	[188431] = {id=188431, zh_CN="它精准地被你接住。", },
	[188432] = {id=188432, zh_CN="你不准告诉姐姐！不准告诉芝麻糊！", },
	[188433] = {id=188433, zh_CN="好，答应你。", },
	[188434] = {id=188434, zh_CN="太丢猫了，喵啊啊啊！", },
	[188435] = {id=188435, zh_CN="电影厂外，年糕逮住了你。", },
	[188436] = {id=188436, zh_CN="终于抓到你了，搭档！", },
	[188437] = {id=188437, zh_CN="快和我走！", },
	[188438] = {id=188438, zh_CN="去哪儿？", },
	[188439] = {id=188439, zh_CN="喵喵我要把你介绍给我姐姐！", },
	[188440] = {id=188440, zh_CN="说着年糕拽着你的裤脚，一路跑到古堡。", },
	[188441] = {id=188441, zh_CN="突然，一道黑影悄无声息地出现在墙头。", },
	[188442] = {id=188442, zh_CN="芝麻糊姐姐！你来得正好！", },
	[188443] = {id=188443, zh_CN="郑重向你介绍！", },
	[188444] = {id=188444, zh_CN="这位便是喵喵我呀，你亲爱的弟弟！", },
	[188445] = {id=188445, zh_CN="经过层层筛选、严格考核，", },
	[188446] = {id=188446, zh_CN="和喵喵我并肩作战、屡破奇案的侦探助理！", },
	[188447] = {id=188447, zh_CN="我的搭档——%PlayerName！", },
	[188448] = {id=188448, zh_CN="拿出小鱼干——小小的见面礼。", },
	[188449] = {id=188449, zh_CN="一点小小的见面礼，不成敬意。", },
	[188450] = {id=188450, zh_CN="你好，我是年糕的朋友。", },
	[188451] = {id=188451, zh_CN="绅士礼——很高兴见到你。", },
	[188452] = {id=188452, zh_CN="很高兴见到你，芝麻糊小姐。", },
	[188453] = {id=188453, zh_CN="年糕经常提起您。", },
	[188454] = {id=188454, zh_CN="芝麻糊从高墙上一跃而下，落地无声。", },
	[188455] = {id=188455, zh_CN="喵~（翻译：还不错。）", },
	[188456] = {id=188456, zh_CN="对喵对喵！", },
	[188457] = {id=188457, zh_CN="虽然……%PlayerName会偷偷撸侦探的尾巴。", },
	[188458] = {id=188458, zh_CN="但是%PlayerName是喵喵我的好助理！", },
	[188459] = {id=188459, zh_CN="喵嗷~（翻译：回了。）", },
	[188460] = {id=188460, zh_CN="芝麻糊转身，优雅而敏捷地再次跳上高墙。", },
	[188461] = {id=188461, zh_CN="经过年糕身边时，", },
	[188462] = {id=188462, zh_CN="她的尾巴尖似乎无意，轻轻扫过年糕的额头。", },
	[188463] = {id=188463, zh_CN="像是在安抚。", },
	[188464] = {id=188464, zh_CN="随后，黑色的身影便消失在墙头。", },
	[188465] = {id=188465, zh_CN="电影厂的外围，有一处浅滩。", },
	[188466] = {id=188466, zh_CN="年糕正蹲在浅滩边，对着一只蕉绿鸭侃侃而谈。", },
	[188467] = {id=188467, zh_CN="年糕正和一只蕉绿鸭对话。", },
	[188468] = {id=188468, zh_CN="嘎嘎阁下，早安。", },
	[188469] = {id=188469, zh_CN="今日水域警戒状况如何？", },
	[188470] = {id=188470, zh_CN="有无异常水流或可疑漂浮物？", },
	[188471] = {id=188471, zh_CN="嘎嘎！报告长官，一切正常。", },
	[188472] = {id=188472, zh_CN="年糕看到你的到来……", },
	[188473] = {id=188473, zh_CN="很好。", },
	[188474] = {id=188474, zh_CN="嘎嘎阁下，向你正式介绍！", },
	[188475] = {id=188475, zh_CN="这位是喵喵我亲自面试，考核，", },
	[188476] = {id=188476, zh_CN="并通过多次实战检验的特别助理！", },
	[188477] = {id=188477, zh_CN="%PlayerName。", },
	[188478] = {id=188478, zh_CN="搭档，这位是嘎嘎阁下。", },
	[188479] = {id=188479, zh_CN="负责管辖这片浅滩区域的监测与安全工作。", },
	[188480] = {id=188480, zh_CN="嘎嘎阁下，以后请多指教。", },
	[188481] = {id=188481, zh_CN="你好，%PlayerName阁下。", },
	[188482] = {id=188482, zh_CN="请多指教，嘎！", },
	[188483] = {id=188483, zh_CN="好喵好喵。", },
	[188484] = {id=188484, zh_CN="喵喵我要继续挖掘人才！", },
	[188485] = {id=188485, zh_CN="扩充我的交际圈和侦探团！", },
	[188486] = {id=188486, zh_CN="电影厂平台上，", },
	[188487] = {id=188487, zh_CN="年糕和你最常集合的地方。", },
	[188488] = {id=188488, zh_CN="年糕昂首挺胸地坐在那里，", },
	[188489] = {id=188489, zh_CN="胸前别着一个用闪亮的瓶盖和彩色纸片制成的胸章。", },
	[188490] = {id=188490, zh_CN="这是？", },
	[188491] = {id=188491, zh_CN="经过全面、客观、严谨的自我评估，", },
	[188492] = {id=188492, zh_CN="喵喵我现已正式达成了一只成熟喵的所有标准！", },
	[188493] = {id=188493, zh_CN="可以升级为“成熟的社会喵”身份。", },
	[188494] = {id=188494, zh_CN="它用爪子骄傲地指了指胸口的徽章。", },
	[188495] = {id=188495, zh_CN="这是官方认证的身份证明！", },
	[188496] = {id=188496, zh_CN="由喵喵我亲自设计、制作并颁发！", },
	[188497] = {id=188497, zh_CN="这意味着……", },
	[188498] = {id=188498, zh_CN="喵喵我已具备独立处理诸多复杂事务的能力。", },
	[188499] = {id=188499, zh_CN="包括但不限于案件侦查、社交谈判……", },
	[188500] = {id=188500, zh_CN="以及小鱼干资源管理！", },
	[188501] = {id=188501, zh_CN="鼓掌——真是了不起的成就！", },
	[188502] = {id=188502, zh_CN="太棒了！恭喜小侦探正式升级！", },
	[188503] = {id=188503, zh_CN="不过你的尾巴和影子打架咯。", },
	[188504] = {id=188504, zh_CN="笑——你的尾巴和影子打架咯。", },
	[188505] = {id=188505, zh_CN="这也是成熟社会喵的必备技能吗？", },
	[188506] = {id=188506, zh_CN="年糕猛地回头！", },
	[188507] = {id=188507, zh_CN="自己的尾巴果然不受控制地左右摇摆，", },
	[188508] = {id=188508, zh_CN="试图去扑捉地上晃动的影子。", },
	[188509] = {id=188509, zh_CN="年糕一把抓住自己那不听话的尾巴，抱在怀里。", },
	[188510] = {id=188510, zh_CN="没……没错！", },
	[188511] = {id=188511, zh_CN="一只成熟的社会喵要学会抓紧任何时间训练！", },
	[188512] = {id=188512, zh_CN="这……这是喵喵我的灵活性训练！", },
	[188513] = {id=188513, zh_CN="喵嗷！", },
	[188514] = {id=188514, zh_CN="我们快去计划一下晚上的“抓捕偷鱼贼”的任务吧。", },
	[188515] = {id=188515, zh_CN="【超级侦探】", },
	[188516] = {id=188516, zh_CN="【浮影追击】", },
	[188517] = {id=188517, zh_CN="【临时庇护所】", },
	[188518] = {id=188518, zh_CN="【专属助理】", },
	[188519] = {id=188519, zh_CN="【踩奶挂件】", },
	[188520] = {id=188520, zh_CN="【阿贝贝】", },
	[188521] = {id=188521, zh_CN="【纸上谈兵】", },
	[188522] = {id=188522, zh_CN="【战胜恐惧】", },
	[188523] = {id=188523, zh_CN="【喵侦探宣言】", },
	[188524] = {id=188524, zh_CN="【树上的求救】", },
	[188525] = {id=188525, zh_CN="【大家长审视】", },
	[188526] = {id=188526, zh_CN="【社交拓展】", },
	[188527] = {id=188527, zh_CN="【成长宣言】", },
	[188528] = {id=188528, zh_CN="试试运气，抓捕黑影。", },
	[188529] = {id=188529, zh_CN="给年糕梳毛。", },
	[188530] = {id=188530, zh_CN="与年糕玩侦探游戏。", },
	[188531] = {id=188531, zh_CN="你梳理了年糕的背毛。", },
	[188532] = {id=188532, zh_CN="你和年糕玩了一会侦探游戏。", },
	[188533] = {id=188533, zh_CN="【梳毛抚摸】", },
	[188534] = {id=188534, zh_CN="【侦探游戏】", },
	[188535] = {id=188535, zh_CN="梳毛抚摸。", },
	[188536] = {id=188536, zh_CN="侦探游戏。", },
	[188537] = {id=188537, zh_CN="年糕鉴定——依赖1", },
	[188538] = {id=188538, zh_CN="年糕鉴定——依赖2", },
	[188539] = {id=188539, zh_CN="年糕鉴定——依赖3", },
	[188540] = {id=188540, zh_CN="年糕鉴定——依赖4", },
	[188541] = {id=188541, zh_CN="年糕鉴定——侦探1", },
	[188542] = {id=188542, zh_CN="年糕鉴定——侦探2", },
	[188543] = {id=188543, zh_CN="年糕惊得后退半步，弓起身。", },
	[188544] = {id=188544, zh_CN="喵！在那里！", },
	[188545] = {id=188545, zh_CN="年糕想想便留下口水。", },
	[188546] = {id=188546, zh_CN="它耳朵垂下，闷闷不乐。", },
	[188547] = {id=188547, zh_CN="初见", },
	[188548] = {id=188548, zh_CN="那里有一只小喵喵，快去认识它吧", },
	[188549] = {id=188549, zh_CN="年糕鉴定——是谁", },
