	[188552] = {id=188552, zh_CN="年糕鉴定——紧张", },
	[188553] = {id=188553, zh_CN="年糕鉴定——在我心理", },
	[188600] = {id=188600, zh_CN="芝麻糊—任务1道具", },
	[188601] = {id=188601, zh_CN="芝麻糊—任务2道具", },
	[188602] = {id=188602, zh_CN="芝麻糊—任务3道具", },
	[190000] = {id=190000, zh_CN="他们机体喷射出的热浪让小屋方圆几十米如同蒸拿房。", },
	[190001] = {id=190001, zh_CN="对不起。", },
	[190002] = {id=190002, zh_CN="莫迪斯抬头撇了你一眼，又低下头去工作。", },
	[190003] = {id=190003, zh_CN="你的目光落到周围的机械生命身上，", },
	[190004] = {id=190004, zh_CN="便退到一旁，安静地等待着莫迪斯。", },
	[190005] = {id=190005, zh_CN="我需要你帮我去收集。", },
	[190006] = {id=190006, zh_CN="尤其是他刚刚拒绝过你。", },
	[190007] = {id=190007, zh_CN="是的。", },
	[190008] = {id=190008, zh_CN="除了空间站在编人员，其他闲杂人等都禁止入内。", },
	[190009] = {id=190009, zh_CN="为72.333％，取无限小数。", },
