	[190234] = {id=190234, zh_CN="请相信小金毛。", },
	[190235] = {id=190235, zh_CN="你与小金毛穿过狭窄的小路。", },
	[190236] = {id=190236, zh_CN="一路来到来到商会安静的空地旁，", },
	[190237] = {id=190237, zh_CN="安保的脚步声在栅栏外来回移动。", },
	[190238] = {id=190238, zh_CN="偶尔传来手电筒的光束扫过栅栏的声响。", },
	[190239] = {id=190239, zh_CN="你确定宝藏在这儿？", },
	[190240] = {id=190240, zh_CN="小金毛撅着屁股刨坑", },
	[190241] = {id=190241, zh_CN="进去就知道了。", },
	[190242] = {id=190242, zh_CN="眼神中带着一丝警惕。", },
	[190243] = {id=190243, zh_CN="几个市容管理所的警察正朝这边走来。", },
	[190244] = {id=190244, zh_CN="其中一警察手里拿着电棍，", },
	[190245] = {id=190245, zh_CN="你转身沿着小金毛的逃跑路线迅速消失在人群中。", },
	[190246] = {id=190246, zh_CN="你转身沿着小金毛的逃跑路线迅速消失在人群中。", },
	[190247] = {id=190247, zh_CN="你转身沿着小金毛的逃跑路线迅速消失在人群中。", },
	[190248] = {id=190248, zh_CN="几人抄起警棍迅速朝小金毛包围", },
	[190249] = {id=190249, zh_CN="立刻朝你的方向看来，", },
	[190250] = {id=190250, zh_CN="灵活地在人群中穿梭，很快消失在视线中。", },
	[190251] = {id=190251, zh_CN="有什么困难请记得派遣小金毛。", },
	[190252] = {id=190252, zh_CN="一颗鲜红油亮的种子从小金毛的茸毛中掉落在地上。", },
	[190253] = {id=190253, zh_CN="递到小金毛嘴前。", },
	[190254] = {id=190254, zh_CN="没有能称之为“家”的地方，", },
	[190255] = {id=190255, zh_CN="它们看起来瘦弱而疲惫。", },
	[190256] = {id=190256, zh_CN="它们立刻围住小金毛，", },
	[190257] = {id=190257, zh_CN="警备地盯着你这个“不速之客”。", },
	[190258] = {id=190258, zh_CN="小金毛用鼻子轻轻蹭了蹭它们，", },
	[190259] = {id=190259, zh_CN="安抚他们紧张的情绪。", },
	[190260] = {id=190260, zh_CN="会不会太辛苦了？", },
	[190261] = {id=190261, zh_CN="小金毛不觉得辛苦。", },
	[190262] = {id=190262, zh_CN="偶尔也会有光灵带些材料回来卖，", },
	[190263] = {id=190263, zh_CN="可小金毛也需要它们。", },
	[190264] = {id=190264, zh_CN="但小金毛那么纯真的心灵，", },
	[190265] = {id=190265, zh_CN="要相信它吗？", },
	[190266] = {id=190266, zh_CN="归属不明的藏宝图，", },
	[190267] = {id=190267, zh_CN="我们就这样贸然前往，", },
	[190268] = {id=190268, zh_CN="会不会有危险呢？", },
	[190269] = {id=190269, zh_CN="请相信小金毛，", },
	[190270] = {id=190270, zh_CN="小金毛的消息从没有错过哦。", },
	[190271] = {id=190271, zh_CN="我要牢牢把握才行。", },
	[190272] = {id=190272, zh_CN="这里被高高的铁栅栏围住。", },
	[190273] = {id=190273, zh_CN="社团金币占位用", },
	[190274] = {id=190274, zh_CN="<color=#dcb56c>%s</color>开始在<u>%s</u>制作<color=#E69BEC>神秘料理</color>", },
	[190275] = {id=190275, zh_CN="咦？今天有访客吗？让我看看登记本。", },
	[190276] = {id=190276, zh_CN="未经登记进入这里是违规行为。站住", },
	[190277] = {id=190277, zh_CN="乡野里禁止乱跑，站住！", },
	[190278] = {id=190278, zh_CN="追花瓶？你们先赔我踩坏的花田！", },
	[190279] = {id=190279, zh_CN="不要让我再见到你们，离开我的领地。", },
	[190280] = {id=190280, zh_CN="被花粉眯眼睛喵。", },
	[190281] = {id=190281, zh_CN="嘿，我们马上离开。", },
	[190282] = {id=190282, zh_CN="快跑！", },
	[191000] = {id=191000, zh_CN="这位便是%PlayerName阁下，", },
	[191001] = {id=191001, zh_CN="年轻的天外星旅舰长。", },
	[191002] = {id=191002, zh_CN="话音刚落，一种丽阳般的灼热感萦绕在四周，", },
	[191003] = {id=191003, zh_CN="遥遥望去，一朵牡丹的幻影在阿加莎面前若隐若现，", },
	[191004] = {id=191004, zh_CN="那颗至黑的牡丹王种落在你的手上。", },
	[191005] = {id=191005, zh_CN="……", },
