	[192008] = {id=192008, zh_CN="【舞会考核】", },
	[192009] = {id=192009, zh_CN="【姐弟情深】", },
	[192010] = {id=192010, zh_CN="【委托与察觉】", },
	[192011] = {id=192011, zh_CN="【王室教师】", },
	[192012] = {id=192012, zh_CN="【世袭教师】", },
	[192013] = {id=192013, zh_CN="【初次纵容】", },
	[192014] = {id=192014, zh_CN="【聚会潜入】", },
	[192015] = {id=192015, zh_CN="【甜蜜“掠夺”】", },
	[192016] = {id=192016, zh_CN="【投喂认可】", },
	[192017] = {id=192017, zh_CN="【健康之争】", },
	[192018] = {id=192018, zh_CN="【甜品尝试】", },
	[192019] = {id=192019, zh_CN="【零食尝试】", },
	[192020] = {id=192020, zh_CN="【唯一饲养官】", },
	[192021] = {id=192021, zh_CN="【梳毛任命】", },
	[192022] = {id=192022, zh_CN="【主动求摸】", },
	[192024] = {id=192024, zh_CN="夜色中的古堡庭院，月光稀疏。", },
	[192025] = {id=192025, zh_CN="打开手电照明。", },
	[192026] = {id=192026, zh_CN="手电光束扫过寂静的广场角落。", },
	[192027] = {id=192027, zh_CN="忽然！", },
	[192028] = {id=192028, zh_CN="一道黑影极快地从你身后掠过，", },
	[192029] = {id=192029, zh_CN="融入烛台下的阴影中。", },
	[192030] = {id=192030, zh_CN="手电移向黑影。", },
	[192031] = {id=192031, zh_CN="光束迅速移向黑影消失的方向……", },
	[192032] = {id=192032, zh_CN="光束所及之处，", },
	[192033] = {id=192033, zh_CN="一点微光在阴影中闪烁了一下。", },
	[192034] = {id=192034, zh_CN="谁在那儿？", },
	[192035] = {id=192035, zh_CN="啪！啪啦！", },
	[192036] = {id=192036, zh_CN="除了烛火燃烧，无人回应。", },
	[192037] = {id=192037, zh_CN="你警惕走近。", },
	[192038] = {id=192038, zh_CN="嗯？那反光是……", },
	[192039] = {id=192039, zh_CN="正当你试图看清时，", },
	[192040] = {id=192040, zh_CN="一对玛瑙般的瞳孔猛地睁开，", },
	[192041] = {id=192041, zh_CN="泛出幽幽的紫光。", },
	[192042] = {id=192042, zh_CN="嘛一克——！", },
	[192043] = {id=192043, zh_CN="一只通体漆黑的猫弓着背，尾巴炸开。", },
	[192044] = {id=192044, zh_CN="它缓缓从黑暗中显形。", },
	[192045] = {id=192045, zh_CN="尾巴尖上似乎卷着什么亮晶晶的东西。", },
	[192046] = {id=192046, zh_CN="一只……小黑猫？", },
	[192047] = {id=192047, zh_CN="是古堡里的流浪猫族吗？", },
	[192048] = {id=192048, zh_CN="芝麻糊尾巴不耐烦地重重拍打地面。", },
	[192049] = {id=192049, zh_CN="嘶——！哈！", },
	[192050] = {id=192050, zh_CN="喵嗷！嗷呜！", },
	[192051] = {id=192051, zh_CN="芝麻糊尾巴收在身后，", },
	[192052] = {id=192052, zh_CN="用一只前爪用力拍了拍地面，", },
	[192053] = {id=192053, zh_CN="然后高傲地仰起头。", },
	[192054] = {id=192054, zh_CN="你想说……自己不是流浪猫吗？", },
	[192055] = {id=192055, zh_CN="喵~", },
	[192056] = {id=192056, zh_CN="居然在点头？", },
	[192057] = {id=192057, zh_CN="好聪明的猫。", },
	[192058] = {id=192058, zh_CN="小猫小猫，有看见亮晶晶的闪光吗？", },
	[192059] = {id=192059, zh_CN="芝麻糊瞳孔微微放大，", },
	[192060] = {id=192060, zh_CN="它立刻扭头假装专心舔舐胸前的毛发。", },
	[192061] = {id=192061, zh_CN="喵~咕噜噜……", },
	[192062] = {id=192062, zh_CN="读心。", },
	[192063] = {id=192063, zh_CN="一长串喵喵叫传入你的脑海。", },
	[192064] = {id=192064, zh_CN="喵~喵嗷.......喵喵,喵！", },
	[192065] = {id=192065, zh_CN="（翻译：我可是堂堂古堡贵族，）", },
	[192066] = {id=192066, zh_CN="（不会这么容易被发现的喵，镇定！）", },
	[192067] = {id=192067, zh_CN="你听不懂喵喵语。", },
	[192068] = {id=192068, zh_CN="但总觉得它很懊恼。", },
	[192069] = {id=192069, zh_CN="似乎经历了纠缠难分的心理战争。", },
	[192070] = {id=192070, zh_CN="小猫咪哪有什么心事~", },
	[192071] = {id=192071, zh_CN="你发觉芝麻糊在偷瞄你。", },
	[192072] = {id=192072, zh_CN="朝着它焦躁的尾巴望去——", },
	[192073] = {id=192073, zh_CN="尾巴尖缠绕着物件，亮晶晶地晃眼。", },
	[192074] = {id=192074, zh_CN="喵！嗷呜……", },
	[192075] = {id=192075, zh_CN="尾巴却下意识地往身后藏了藏。", },
	[192076] = {id=192076, zh_CN="观察芝麻糊。", },
	[192077] = {id=192077, zh_CN="你发觉芝麻糊在偷瞄你。", },
	[192078] = {id=192078, zh_CN="朝着它焦躁的尾巴望去——", },
	[192079] = {id=192079, zh_CN="尾巴尖缠绕着物件，亮晶晶地晃眼。", },
	[192080] = {id=192080, zh_CN="喵！嗷呜……", },
	[192081] = {id=192081, zh_CN="芝麻糊停下动作，端正坐好。", },
	[192082] = {id=192082, zh_CN="尾巴却下意识地往身后藏了藏。", },
	[192083] = {id=192083, zh_CN="你……是不是拿了什么东西？", },
	[192084] = {id=192084, zh_CN="亮晶晶的？", },
	[192085] = {id=192085, zh_CN="喵嗷。", },
	[192086] = {id=192086, zh_CN="不说话，故意的吗？", },
	[192087] = {id=192087, zh_CN="它用尾巴尖极其明显地指向你装有食物的背包方向。", },
	[192088] = {id=192088, zh_CN="喵嗷~", },
	[192089] = {id=192089, zh_CN="你想要食物？", },
	[192090] = {id=192090, zh_CN="芝麻糊眼睛一亮，但立刻克制住。", },
	[192091] = {id=192091, zh_CN="它尾巴尖小幅度晃了晃。", },
	[192092] = {id=192092, zh_CN="喵！", },
	[192093] = {id=192093, zh_CN="它伸爪向前推了推。", },
	[192094] = {id=192094, zh_CN="要我……放在地上？", },
	[192095] = {id=192095, zh_CN="喵！", },
	[192096] = {id=192096, zh_CN="掏出食物。", },
	[192097] = {id=192097, zh_CN="好吧，给你。", },
	[192098] = {id=192098, zh_CN="但你要告诉我那个亮晶晶的东西是哪来的。", },
	[192099] = {id=192099, zh_CN="摇头拒绝。", },
	[192100] = {id=192100, zh_CN="不行。", },
	[192101] = {id=192101, zh_CN="你先把尾巴上的东西给我看看。", },
	[192102] = {id=192102, zh_CN="你从口袋拿出一个小鱼干，放在手心。", },
	[192103] = {id=192103, zh_CN="芝麻糊鼻子微微抽动，", },
	[192104] = {id=192104, zh_CN="紫瞳紧盯着小鱼干，", },
	[192105] = {id=192105, zh_CN="但身体依旧保持优雅坐姿。", },
	[192106] = {id=192106, zh_CN="喵呜……", },
	[192107] = {id=192107, zh_CN="它小心地、保持距离地凑近。", },
	[192108] = {id=192108, zh_CN="迅速而轻巧地叼走小鱼干，", },
	[192109] = {id=192109, zh_CN="跳到一旁才开始享用小鱼干。", },
	[192110] = {id=192110, zh_CN="芝麻糊满意地舔舔嘴巴和爪子。", },
	[192111] = {id=192111, zh_CN="咕噜噜……喵~", },
	[192112] = {id=192112, zh_CN="它用尾巴尖将那个亮晶晶的吊坠从身后勾出来，", },
	[192113] = {id=192113, zh_CN="在你面前晃了晃，然后迅速收回。", },
	[192114] = {id=192114, zh_CN="喵！嗷呜喵！", },
	[192115] = {id=192115, zh_CN="是在说，这是它发现的吗？", },
	[192116] = {id=192116, zh_CN="喵！", },
	[192117] = {id=192117, zh_CN="芝麻糊用力点头，", },
	[192118] = {id=192118, zh_CN="然后又把吊坠藏回身后，", },
	[192119] = {id=192119, zh_CN="一只前爪按在上面。", },
	[192120] = {id=192120, zh_CN="呜……！", },
	[192121] = {id=192121, zh_CN="（翻译：我的！我的！是我先发现的！）", },
	[192122] = {id=192122, zh_CN="飞机耳瞬现，尾巴猛地甩到身后藏好。", },
	[192123] = {id=192123, zh_CN="哈——！喵嗷！！", },
	[192124] = {id=192124, zh_CN="它转过身，用屁股对着你。", },
	[192125] = {id=192125, zh_CN="芝麻糊尾巴紧紧卷着……", },
	[192126] = {id=192126, zh_CN="但尖端的闪光还是泄露了出来。", },
	[192127] = {id=192127, zh_CN="你从口袋拿出一个小鱼干，放在手心。", },
	[192128] = {id=192128, zh_CN="喵呜……", },
	[192129] = {id=192129, zh_CN="它小心地、保持距离地凑近。", },
	[192130] = {id=192130, zh_CN="把你背后的亮闪闪给我看看，", },
	[192131] = {id=192131, zh_CN="这个小鱼干就是你的了。", },
	[192132] = {id=192132, zh_CN="喵！嗷嗷嗷！呜喵！", },
	[192133] = {id=192133, zh_CN="它一边激动地喵喵叫，", },
	[192134] = {id=192134, zh_CN="一边用爪子比划着，", },
	[192135] = {id=192135, zh_CN="似乎在强调发现过程，", },
	[192136] = {id=192136, zh_CN="最后把亮闪闪紧紧抱在怀里。", },
	[192137] = {id=192137, zh_CN="你才看清楚，那是一只宝石吊坠。", },
	[192138] = {id=192138, zh_CN="咕噜！哼！", },
	[192139] = {id=192139, zh_CN="是在说，这是它发现的吗？", },
	[192140] = {id=192140, zh_CN="芝麻糊点点头，拍拍自己。", },
	[192141] = {id=192141, zh_CN="（翻译：我的！我的！是我先发现的！）", },
	[192142] = {id=192142, zh_CN="但这不是你的，对吗？", },
	[192143] = {id=192143, zh_CN="吊坠是有失主的。", },
	[192144] = {id=192144, zh_CN="芝麻糊的耳朵瞬间耷拉下来，", },
	[192145] = {id=192145, zh_CN="假装听不懂看向别处。", },
	[192146] = {id=192146, zh_CN="咕噜……喵呜……", },
	[192147] = {id=192147, zh_CN="（翻译：捡到的就是我的……）", },
	[192148] = {id=192148, zh_CN="芝麻糊低头看看怀里闪闪发光的吊坠，", },
	[192149] = {id=192149, zh_CN="它把吊坠搂得更紧，身体微微蜷缩。", },
	[192150] = {id=192150, zh_CN="呜喵……咕噜噜……", },
	[192151] = {id=192151, zh_CN="（翻译：可是……它在这里……就是没有主人。）", },
	[192152] = {id=192152, zh_CN="（翻译：它亮亮的……和我最配了……）", },
	[192153] = {id=192153, zh_CN="剧烈的能量波动从它身上散发出来，", },
	[192154] = {id=192154, zh_CN="你忽地就能听懂芝麻糊的喵叫了。", },
	[192155] = {id=192155, zh_CN="就在芝麻糊强烈的占有欲和纠结情绪达到顶峰时，", },
	[192156] = {id=192156, zh_CN="空气中似乎浮现出淡淡的、扭曲的光晕，", },
	[192157] = {id=192157, zh_CN="一朵由微弱光影构成的、", },
	[192158] = {id=192158, zh_CN="紧紧闭合的绣球花苞虚影在它头顶一闪而过，", },
	[192159] = {id=192159, zh_CN="随即碎裂成点点荧光，", },
	[192160] = {id=192160, zh_CN="其中一小点光芒悄然落入你的掌心，", },
	[192161] = {id=192161, zh_CN="形成一枚触感微凉、带着微妙排斥感的深蓝色种子。", },
	[192162] = {id=192162, zh_CN="芝麻糊打了个激灵，疑惑看了看四周，", },
	[192163] = {id=192163, zh_CN="最后狐疑地盯住了你刚刚收拢的手掌。", },
	[192164] = {id=192164, zh_CN="喵？……嗷？", },
	[192165] = {id=192165, zh_CN="岔开话题，提出调查。", },
	[192166] = {id=192166, zh_CN="这样吧，我们一起去你发现它的地方看看？", },
	[192167] = {id=192167, zh_CN="如果找不到失主，", },
	[192168] = {id=192168, zh_CN="那才能算是你捡到的藏品。", },
	[192169] = {id=192169, zh_CN="喵？咕噜……", },
	[192170] = {id=192170, zh_CN="芝麻糊点点头，算是答应了你的要求。", },
	[192171] = {id=192171, zh_CN="芝麻糊带着你来到一处回廊角落。", },
	[192172] = {id=192172, zh_CN="你们恰好遇见了一位正在焦急寻找什么的女士——奥黛特小姐。", },
	[192173] = {id=192173, zh_CN="哦，可爱的小猫和%PlayerName，", },
	[192174] = {id=192174, zh_CN="你们有看见一只蓝宝石吊坠吗？", },
	[192175] = {id=192175, zh_CN="归还失主。", },
	[192176] = {id=192176, zh_CN="看，失主就在这儿呢。", },
	[192177] = {id=192177, zh_CN="再多的亮晶晶，这一件也是独一无二的。", },
	[192178] = {id=192178, zh_CN="你应该还给她，你答应我的，不是吗？", },
	[192179] = {id=192179, zh_CN="纵容暂存。", },
	[192180] = {id=192180, zh_CN="奥黛特小姐，请问……", },
	[192181] = {id=192181, zh_CN="如果这只小猫非常喜欢这个吊坠，", },
	[192182] = {id=192182, zh_CN="您是否允许它……代为保管两天？", },
	[192183] = {id=192183, zh_CN="哦！是这只喜欢“借”东西去藏的小猫啊。", },
	[192184] = {id=192184, zh_CN="上次我那枚胸针它也是稀罕了两天就好好还回来了。", },
	[192185] = {id=192185, zh_CN="好吧，既然它这么喜欢，", },
	[192186] = {id=192186, zh_CN="就让它再保管两天吧。", },
	[192187] = {id=192187, zh_CN="说好了哦，小猫咪，两天后要还给我。", },
	[192188] = {id=192188, zh_CN="芝麻糊极其缓慢、极其不情愿地，", },
	[192189] = {id=192189, zh_CN="用爪子推了推吊坠。", },
	[192190] = {id=192190, zh_CN="它立刻扭开头，忍痛割爱。", },
	[192191] = {id=192191, zh_CN="……呜……喵嗷。", },
	[192192] = {id=192192, zh_CN="捡起吊坠，递给奥黛特。", },
	[192193] = {id=192193, zh_CN="是这个吗？", },
	[192194] = {id=192194, zh_CN="很感谢你们。", },
	[192195] = {id=192195, zh_CN="尤其是你，古堡里的小贵族。", },
	[192196] = {id=192196, zh_CN="我会为你提供一箱小鱼干，希望你喜欢。", },
	[192197] = {id=192197, zh_CN="芝麻糊听到小鱼干，瞬间精神。", },
	[192198] = {id=192198, zh_CN="它矜持地抖动耳朵，朝奥黛特行了一礼。", },
	[192199] = {id=192199, zh_CN="芝麻糊感谢你的慷慨，魅力的商会老大。", },
	[192200] = {id=192200, zh_CN="归还吊坠后，", },
	[192201] = {id=192201, zh_CN="芝麻糊与你拿着奥黛特小姐的谢礼，", },
	[192202] = {id=192202, zh_CN="分道扬镳。", },
	[192203] = {id=192203, zh_CN="芝麻糊眼睛瞬间亮了起来，", },
	[192204] = {id=192204, zh_CN="难以置信地看着奥黛特又看看你。", },
	[192205] = {id=192205, zh_CN="它尾巴一下子竖得笔直，", },
	[192206] = {id=192206, zh_CN="尖端兴奋地颤抖。", },
	[192207] = {id=192207, zh_CN="喵嗷？！", },
	[192208] = {id=192208, zh_CN="它兴奋转圈！很快克制住雀跃的心情。", },
	[192209] = {id=192209, zh_CN="咕噜噜……喵！喵呜~", },
	[192210] = {id=192210, zh_CN="我，芝麻糊，以古堡贵族名誉担保。", },
	[192211] = {id=192211, zh_CN="两日后，将吊坠归还于商会。", },
	[192212] = {id=192212, zh_CN="两天后，你在发现了一封小巧精致的信封，", },
	[192213] = {id=192213, zh_CN="上面只有一个清晰的、", },
	[192214] = {id=192214, zh_CN="略显骄傲的梅花状泥爪印。", },
	[192215] = {id=192215, zh_CN="里面是一张简单的感谢卡片，", },
	[192216] = {id=192216, zh_CN="来自奥黛特小姐。", },
	[192217] = {id=192217, zh_CN="感谢“一位守信用的喵喵大人”归还了她珍贵的吊坠。——奥黛特·德·月影", },
	[192218] = {id=192218, zh_CN="你抬起头，似乎看到高处古堡的窗沿上，", },
	[192219] = {id=192219, zh_CN="一对熟悉的紫色瞳孔在黑暗中一闪而过，", },
	[192220] = {id=192220, zh_CN="随即隐没不见。", },
	[192224] = {id=192224, zh_CN="几天后，阳光正好。你再次来到古堡。", },
	[192225] = {id=192225, zh_CN="虽然已经得知了吊坠承诺的后续，", },
	[192226] = {id=192226, zh_CN="但你对芝麻糊“与值得的对象说话”的行为耿耿于怀。", },
	[192227] = {id=192227, zh_CN="你在一个阳光充足的角落找到了它。", },
	[192228] = {id=192228, zh_CN="它正揣着小爪，母鸡蹲在软垫上。", },
	[192229] = {id=192229, zh_CN="一只乌黑的尾巴垂落。", },
	[192230] = {id=192230, zh_CN="阳光透过茸毛，如同藏色的画。", },
	[192231] = {id=192231, zh_CN="找到你了！", },
	[192232] = {id=192232, zh_CN="芝麻糊眼皮都懒得抬一下，", },
	[192233] = {id=192233, zh_CN="尾巴尖有一下没一下地晃着。", },
	[192234] = {id=192234, zh_CN="咕噜……", },
	[192235] = {id=192235, zh_CN="你明明会说话！", },
	[192236] = {id=192236, zh_CN="你明明会说话！", },
	[192237] = {id=192237, zh_CN="为什么老是跟我“喵嗷喵嗷”的？", },
	[192238] = {id=192238, zh_CN="芝麻糊慢悠悠地睁开一只黄瞳，", },
	[192239] = {id=192239, zh_CN="瞥了你一眼。", },
	[192240] = {id=192240, zh_CN="喵~呜。", },
	[192241] = {id=192241, zh_CN="不要打扰芝麻糊晒太阳。", },
	[192242] = {id=192242, zh_CN="我们猫族的喵喵语是最高贵的语言。", },
	[192243] = {id=192243, zh_CN="这不是捉弄人的借口！", },
	[192244] = {id=192244, zh_CN="芝麻糊伸了个长长的懒腰，", },
	[192245] = {id=192245, zh_CN="露出粉嫩的肉垫。", },
	[192246] = {id=192246, zh_CN="喵嗷，喵喵，咕噜噜喵。", },
	[192247] = {id=192247, zh_CN="哼，是你不懂欣赏。", },
	[192248] = {id=192248, zh_CN="芝麻糊的每一声喵叫都蕴含着无尽的信息与优雅。", },
	[192249] = {id=192249, zh_CN="是你自己语言不精，听不懂罢了。", },
	[192250] = {id=192250, zh_CN="那你说几句，我来猜！", },
	[192251] = {id=192251, zh_CN="芝麻糊被勾起了一点兴致，", },
	[192252] = {id=192252, zh_CN="尾巴尖轻轻翘起。", },
	[192253] = {id=192253, zh_CN="喵？看在你虚心求教的份上。", },
	[192254] = {id=192254, zh_CN="芝麻糊不介意用你能理解的语言，", },
	[192255] = {id=192255, zh_CN="为你这……", },
	[192256] = {id=192256, zh_CN="咳咳，为你这好奇的家伙启蒙一番。", },
	[192257] = {id=192257, zh_CN="优雅地站起身，尾巴尖轻巧地一翘。", },
	[192258] = {id=192258, zh_CN="喵~", },
	[192259] = {id=192259, zh_CN="那一声清晰而温柔。", },
	[192260] = {id=192260, zh_CN="你猜测第一声喵叫的含义。", },
	[192261] = {id=192261, zh_CN="阳光好舒服。", },
	[192262] = {id=192262, zh_CN="是不是“阳光好舒服”？", },
	[192263] = {id=192263, zh_CN="芝麻糊微微点头，", },
	[192264] = {id=192264, zh_CN="尾巴优雅地卷了个小圈。", },
	[192265] = {id=192265, zh_CN="咕噜……算你接近。是“享受此刻”。", },
	[192266] = {id=192266, zh_CN="你是不是带了小鱼干。", },
	[192267] = {id=192267, zh_CN="你是不是带了小鱼干？", },
	[192268] = {id=192268, zh_CN="喵嗷！", },
	[192269] = {id=192269, zh_CN="庸俗！错误！", },
	[192270] = {id=192270, zh_CN="给我挠挠下巴。", },
	[192271] = {id=192271, zh_CN="芝麻糊顿了一下，", },
	[192272] = {id=192272, zh_CN="居然有点不好意思地别开脸。", },
	[192273] = {id=192273, zh_CN="……喵。", },
	[192274] = {id=192274, zh_CN="虽然不算正确，但不是不行。", },
	[192275] = {id=192275, zh_CN="好，来看第二题。", },
	[192276] = {id=192276, zh_CN="喵！嗷——", },
	[192277] = {id=192277, zh_CN="第二声，清脆上扬。", },
	[192278] = {id=192278, zh_CN="你猜测第二声喵叫的含义。", },
	[192279] = {id=192279, zh_CN="表达了……满足和舒适。", },
	[192280] = {id=192280, zh_CN="听起来……像是表达了某种满足和舒适？", },
	[192281] = {id=192281, zh_CN="咕噜……不错。", },
	[192282] = {id=192282, zh_CN="打招呼说你好？", },
	[192283] = {id=192283, zh_CN="是在用喵喵语说你好吗？", },
	[192284] = {id=192284, zh_CN="有些瑕疵，但距离正确答案不远了。", },
	[192285] = {id=192285, zh_CN="猫猫语言，还需要认真学习，细细体会。", },
	[192286] = {id=192286, zh_CN="逗弄——命令我跪下。", },
	[192287] = {id=192287, zh_CN="……难道是命令我跪下？", },
	[192288] = {id=192288, zh_CN="喵嗷？！荒唐！", },
	[192289] = {id=192289, zh_CN="芝麻糊哪里是如此肤浅的猫！！", },
	[192290] = {id=192290, zh_CN="逗弄我的坏家伙！", },
	[192291] = {id=192291, zh_CN="快快最后一题。", },
	[192292] = {id=192292, zh_CN="喵！嗷——", },
	[192293] = {id=192293, zh_CN="第三声，声音短促，略带警示。", },
	[192294] = {id=192294, zh_CN="你猜测第三声喵叫的含义。", },
	[192295] = {id=192295, zh_CN="别靠近？", },
	[192296] = {id=192296, zh_CN="这个……是表示警惕？还是别靠近？", },
	[192297] = {id=192297, zh_CN="咕噜~没错。", },
	[192298] = {id=192298, zh_CN="附加题！", },
	[192299] = {id=192299, zh_CN="喵~~~~~？", },
	[192300] = {id=192300, zh_CN="这最后一声，声调上扬，充满期待。", },
	[192301] = {id=192301, zh_CN="芝麻糊亮晶晶地盯着你看。", },
	[192302] = {id=192302, zh_CN="有没有带好吃的？", },
	[192303] = {id=192303, zh_CN="芝麻糊忍不住用爪子拍了下地面！", },
	[192304] = {id=192304, zh_CN="芝麻糊果然连教学语言都可以做得很好。", },
	[192305] = {id=192305, zh_CN="果然是古堡贵族猫！", },
	[192306] = {id=192306, zh_CN="没错，交出你的小鱼干来吧。", },
	[192307] = {id=192307, zh_CN="从芝麻糊这里学到知识，", },
	[192308] = {id=192308, zh_CN="是需要学费的呀。", },
	[192309] = {id=192309, zh_CN="喵！", },
	[192310] = {id=192310, zh_CN="（翻译：快快！小鱼干拿来！）", },
	[192311] = {id=192311, zh_CN="在芝麻糊沉迷于自己的教学成果，", },
	[192312] = {id=192312, zh_CN="得意于自己教导有方的优越感中时，", },
	[192313] = {id=192313, zh_CN="空气中似乎轻轻波动了一下，", },
	[192314] = {id=192314, zh_CN="一朵由金色光晕构成的、", },
	[192315] = {id=192315, zh_CN="盛气凌人的牡丹花虚影，", },
	[192316] = {id=192316, zh_CN="绽放一瞬便碎裂成点点金芒，", },
	[192317] = {id=192317, zh_CN="其中一小点落入你的掌心，", },
	[192318] = {id=192318, zh_CN="化作一枚带着些许刺麻感的金红色种子。", },
	[192319] = {id=192319, zh_CN="……嗯？", },
	[192320] = {id=192320, zh_CN="你是不是偷藏什么？", },
	[192321] = {id=192321, zh_CN="快给芝麻糊看看。", },
	[192322] = {id=192322, zh_CN="说不定可以放入我的藏品室！", },
	[192323] = {id=192323, zh_CN="它好奇地凑过来，", },
	[192324] = {id=192324, zh_CN="用鼻子轻轻嗅了嗅那颗种子。", },
	[192325] = {id=192325, zh_CN="这是什么？", },
	[192326] = {id=192326, zh_CN="闻起来……有股和我很像的味道？", },
	[192327] = {id=192327, zh_CN="这是我一直寻找的花种。", },
	[192328] = {id=192328, zh_CN="芝麻糊用头顶蹭了蹭你的手腕。", },
	[192329] = {id=192329, zh_CN="是你的东西？", },
	[192330] = {id=192330, zh_CN="好好收着吧。", },
	[192331] = {id=192331, zh_CN="我会好好珍藏的！", },
	[192332] = {id=192332, zh_CN="喵喵~", },
	[192333] = {id=192333, zh_CN="那为了表示对我的感谢，", },
	[192334] = {id=192334, zh_CN="呃……你的毛沾上去了。", },
	[192335] = {id=192335, zh_CN="猫影炸毛飞扑在你脸上！", },
	[192336] = {id=192336, zh_CN="喵！", },
	[192337] = {id=192337, zh_CN="它气鼓鼓地舔着自己的爪子，", },
	[192338] = {id=192338, zh_CN="假装不理你。", },
	[192339] = {id=192339, zh_CN="想要我还理你！", },
	[192340] = {id=192340, zh_CN="下次小鱼干加倍！", },
	[192344] = {id=192344, zh_CN="这天，你照例来到古堡，", },
	[192345] = {id=192345, zh_CN="手里晃着美味的小鱼干。", },
	[192346] = {id=192346, zh_CN="芝麻糊——！喵喵大仙——！", },
	[192347] = {id=192347, zh_CN="今天给你带了美味的小鱼干哦！", },
	[192348] = {id=192348, zh_CN="……古堡里没有任何回应。", },
	[192349] = {id=192349, zh_CN="平时早就该窜出来的黑影也不见踪迹。", },
	[192350] = {id=192350, zh_CN="四处张望。", },
	[192351] = {id=192351, zh_CN="嗯？不在老地方晒太阳？跑哪儿去了？", },
	[192352] = {id=192352, zh_CN="你又呼唤了几声。", },
	[192353] = {id=192353, zh_CN="终于，高处传来一声极其微弱、", },
	[192354] = {id=192354, zh_CN="带着点颤抖的猫叫。", },
	[192355] = {id=192355, zh_CN="喵……", },
	[192356] = {id=192356, zh_CN="你抬头，发现蜷在一個很高的书架顶上。", },
	[192357] = {id=192357, zh_CN="原来在那儿啊。", },
	[192358] = {id=192358, zh_CN="芝麻糊，快下来。", },
	[192359] = {id=192359, zh_CN="有小鱼干哦。", },
	[192360] = {id=192360, zh_CN="芝麻糊瑟缩了一下，放弃站起身。", },
	[192361] = {id=192361, zh_CN="喵……嗷！", },
	[192362] = {id=192362, zh_CN="（翻译：小鱼干……小鱼干放在下面就好！）", },
	[192363] = {id=192363, zh_CN="察觉不对，你怎么了？", },
	[192364] = {id=192364, zh_CN="你怎么了？声音听起来怪怪的。下来嘛。", },
	[192365] = {id=192365, zh_CN="喵喵，喵嗷！喵呜呜！", },
	[192366] = {id=192366, zh_CN="（翻译：哼……芝麻糊只是……只是在视察更高的领地！）", },
	[192367] = {id=192367, zh_CN="咕噜！", },
	[192368] = {id=192368, zh_CN="（翻译：芝麻糊想待在哪里就待在哪里！）", },
	[192369] = {id=192369, zh_CN="喵！（翻译：哎呀！）", },
	[192370] = {id=192370, zh_CN="芝麻糊想像往常一样帅气地一跃而下。", },
	[192371] = {id=192371, zh_CN="却无法在空中控制平衡，动作变形！", },
	[192372] = {id=192372, zh_CN="直接栽了下来！", },
	[192373] = {id=192373, zh_CN="小心！", },
	[192374] = {id=192374, zh_CN="你下意识上前一步，伸手接住芝麻糊。", },
	[192375] = {id=192375, zh_CN="一团毛茸茸落入你怀中，微微发抖。", },
	[192376] = {id=192376, zh_CN="喵，喵！", },
	[192377] = {id=192377, zh_CN="（翻译：放……放开！芝麻糊只是脚滑了一下！）", },
	[192378] = {id=192378, zh_CN="抱紧它。", },
	[192379] = {id=192379, zh_CN="你抱紧它，不让它乱动。", },
	[192380] = {id=192380, zh_CN="别动！让我看看……", },
	[192381] = {id=192381, zh_CN="轻抚它的后背。", },
	[192382] = {id=192382, zh_CN="你轻轻抚摸着它的后背，", },
	[192383] = {id=192383, zh_CN="检查芝麻糊的状态。", },
	[192384] = {id=192384, zh_CN="是不是哪里受伤了？", },
	[192385] = {id=192385, zh_CN="芝麻糊放弃挣扎，", },
	[192386] = {id=192386, zh_CN="把脑袋埋进你的胳膊肘里。", },
	[192387] = {id=192387, zh_CN="喵呜……", },
	[192388] = {id=192388, zh_CN="（翻译：尾巴……尾巴根有点疼。）", },
	[192389] = {id=192389, zh_CN="你用手拨开尾巴密黑的尾毛，", },
	[192390] = {id=192390, zh_CN="尾巴根的一处发炎伤口露出。", },
	[192391] = {id=192391, zh_CN="这里吗？", },
	[192392] = {id=192392, zh_CN="哎呀，有点红肿，还破了点皮。", },
	[192393] = {id=192393, zh_CN="怎么弄伤的？", },
	[192394] = {id=192394, zh_CN="喵！咕噜噜……", },
	[192395] = {id=192395, zh_CN="（翻译：巡视古堡的时候被荆棘蹭到了。）", },
	[192396] = {id=192396, zh_CN="（翻译：小伤而已，我已经抓秃它的叶子了！）", },
	[192397] = {id=192397, zh_CN="想要我帮你清理伤口吗？", },
	[192398] = {id=192398, zh_CN="喵！（翻译：嗯！）", },
	[192399] = {id=192399, zh_CN="那你知道医药箱在哪吗？", },
	[192400] = {id=192400, zh_CN="芝麻糊灵巧地变成一滩猫水流入地面与木椅的缝隙，", },
	[192401] = {id=192401, zh_CN="再出来的时候，嘴里叼着一个医药箱。", },
	[192402] = {id=192402, zh_CN="你接过医疗箱打开，", },
	[192403] = {id=192403, zh_CN="里面的药水绷带撒落一箱。", },
	[192404] = {id=192404, zh_CN="你拿出需要的物品。", },
	[192405] = {id=192405, zh_CN="可能会有点疼，忍一下。", },
	[192406] = {id=192406, zh_CN="芝麻糊身体明显僵住！", },
	[192407] = {id=192407, zh_CN="喵嗷！？", },
	[192408] = {id=192408, zh_CN="（翻译：你……你轻点！芝麻糊警告你！）", },
	[192409] = {id=192409, zh_CN="轻抚脑袋。", },
	[192410] = {id=192410, zh_CN="乖乖，很快就不疼了。", },
	[192411] = {id=192411, zh_CN="好了好了，马上就好……", },
	[192412] = {id=192412, zh_CN="你一边轻声安慰，一边小心清理消毒。", },
	[192413] = {id=192413, zh_CN="芝麻糊原本紧绷的身体慢慢放松下来。", },
	[192414] = {id=192414, zh_CN="咕噜……呜……", },
	[192415] = {id=192415, zh_CN="（翻译：还……还算温柔……）", },
	[192416] = {id=192416, zh_CN="快速处理。", },
	[192417] = {id=192417, zh_CN="长痛不如短痛，忍一下。", },
	[192418] = {id=192418, zh_CN="你屏住呼吸，动作麻利地完成清理。", },
	[192419] = {id=192419, zh_CN="喵！嗷呜……！", },
	[192420] = {id=192420, zh_CN="（翻译：疼！粗鲁！）", },
	[192421] = {id=192421, zh_CN="好了，清理干净了。", },
	[192422] = {id=192422, zh_CN="现在要包扎一下，防止感染。", },
	[192423] = {id=192423, zh_CN="手帕垫伤口处。", },
	[192424] = {id=192424, zh_CN="芝麻糊盯着手帕，乖巧递上尾巴。", },
	[192425] = {id=192425, zh_CN="喵喵~喵~", },
	[192426] = {id=192426, zh_CN="（翻译：丝绸手帕果然适配芝麻糊的气质。）", },
	[192427] = {id=192427, zh_CN="纱布包伤口。", },
	[192428] = {id=192428, zh_CN="芝麻糊嫌弃推开。", },
	[192429] = {id=192429, zh_CN="喵！？！", },
	[192430] = {id=192430, zh_CN="（翻译：包得这么丑，都压倒芝麻糊的毛了！）", },
	[192431] = {id=192431, zh_CN="你掏出一条漂亮的丝巾。", },
	[192432] = {id=192432, zh_CN="用这个给你包，好吧？", },
	[192433] = {id=192433, zh_CN="咕噜！", },
	[192434] = {id=192434, zh_CN="（翻译：……嗯……这个颜色勉强配得上芝麻糊）", },
	[192435] = {id=192435, zh_CN="你从医药箱中拿出剃毛刀。", },
	[192436] = {id=192436, zh_CN="喵喵？", },
	[192437] = {id=192437, zh_CN="（翻译：你要用它给我的伤口报仇吗？）", },
	[192438] = {id=192438, zh_CN="你的伤口发炎了，", },
	[192439] = {id=192439, zh_CN="需要把伤口附近的尾毛剃掉。", },
	[192440] = {id=192440, zh_CN="芝麻糊忍痛将尾巴踩在脚下藏起来。", },
	[192441] = {id=192441, zh_CN="嗷呜——！！！", },
	[192442] = {id=192442, zh_CN="（翻译：不可以不可以不可以，芝麻糊不要变丑八怪！）", },
	[192443] = {id=192443, zh_CN="我保证让你漂漂亮亮的，", },
	[192444] = {id=192444, zh_CN="还是古堡第一美猫仔。", },
	[192445] = {id=192445, zh_CN="我 ……我要做第一美喵喵。", },
	[192446] = {id=192446, zh_CN="嗯嗯。保证让你满意。", },
	[192447] = {id=192447, zh_CN="芝麻糊尾巴在空中一晃一晃，", },
	[192448] = {id=192448, zh_CN="看起来纠结了许久，", },
	[192449] = {id=192449, zh_CN="才狠心得闭上眼，将尾巴放在你的手上。", },
	[192450] = {id=192450, zh_CN="它不再看自己的尾巴，撇开脸，", },
	[192451] = {id=192451, zh_CN="望天望地，不愿面对。", },
	[192452] = {id=192452, zh_CN="你打开剃毛刀，", },
	[192453] = {id=192453, zh_CN="滋滋作响的声音让芝麻糊双爪包头，", },
	[192454] = {id=192454, zh_CN="将耳朵塞入脸颊毛中。", },
	[192455] = {id=192455, zh_CN="好啦！", },
	[192456] = {id=192456, zh_CN="芝麻糊站起身来，", },
	[192457] = {id=192457, zh_CN="回头看自己的尾巴根，", },
	[192458] = {id=192458, zh_CN="秃秃的肉肤对比浓黑的尾毛格外突兀。", },
	[192459] = {id=192459, zh_CN="你打算给芝麻糊扎个……", },
	[192460] = {id=192460, zh_CN="蝴蝶结。", },
	[192461] = {id=192461, zh_CN="你手指翻飞，一个蝴蝶结就初具雏形了。", },
	[192462] = {id=192462, zh_CN="芝麻糊惊喜地盯着蝴蝶结，", },
	[192463] = {id=192463, zh_CN="它的爪子痒痒的，", },
	[192464] = {id=192464, zh_CN="总觉得什么基因苏醒了。", },
	[192465] = {id=192465, zh_CN="它扑向尾巴！", },
	[192466] = {id=192466, zh_CN="喵！", },
	[192467] = {id=192467, zh_CN="芝麻糊的指甲刮蹭在蝴蝶结上，", },
	[192468] = {id=192468, zh_CN="身体失去平衡，", },
	[192469] = {id=192469, zh_CN="滚落在椅子上，撞上你的大腿才停下。", },
	[192470] = {id=192470, zh_CN="喵~~~", },
	[192471] = {id=192471, zh_CN="平结。", },
	[192472] = {id=192472, zh_CN="你手指翻飞，一个平结就初具雏形了。", },
	[192473] = {id=192473, zh_CN="芝麻糊惊喜地盯着平结，", },
	[192474] = {id=192474, zh_CN="尾巴在空中炫耀似的甩来甩去。", },
	[192475] = {id=192475, zh_CN="平结的活扣顺着惯性，缓缓松开，", },
	[192476] = {id=192476, zh_CN="最后化作空中的一条丝带，", },
	[192477] = {id=192477, zh_CN="落在芝麻糊的背上。", },
	[192478] = {id=192478, zh_CN="喵？", },
	[192479] = {id=192479, zh_CN="它失落地盯着尾巴的纱布。", },
	[192480] = {id=192480, zh_CN="蔷薇结。", },
	[192481] = {id=192481, zh_CN="你手指翻飞，", },
	[192482] = {id=192482, zh_CN="一个蔷薇结就初具雏形了。", },
	[192483] = {id=192483, zh_CN="芝麻糊惊喜地盯着蝴蝶结，", },
	[192484] = {id=192484, zh_CN="它的爪子痒痒的，", },
	[192485] = {id=192485, zh_CN="总觉得什么基因苏醒了。", },
	[192486] = {id=192486, zh_CN="它扑向尾巴！", },
	[192487] = {id=192487, zh_CN="喵！", },
	[192488] = {id=192488, zh_CN="蔷薇结随着跳跃腾飞的尾巴在空中滑动处一串花影。", },
	[192489] = {id=192489, zh_CN="喵喵喵～～", },
	[192490] = {id=192490, zh_CN="它兴奋地巴拉自己的尾巴，", },
	[192491] = {id=192491, zh_CN="稀罕地不得了。", },
	[192492] = {id=192492, zh_CN="好了，这几天别沾水，知道吗？", },
	[192493] = {id=192493, zh_CN="芝麻糊低头看着自己尾巴上漂亮的“装饰”。", },
	[192494] = {id=192494, zh_CN="它别扭地转过头。", },
	[192495] = {id=192495, zh_CN="喵，咕噜……", },
	[192496] = {id=192496, zh_CN="（翻译：知道啦，啰嗦……）", },
	[192497] = {id=192497, zh_CN="芝麻糊坚硬的外壳短暂卸下。", },
	[192498] = {id=192498, zh_CN="空气中似乎泛起一丝微不可查的涟漪。", },
	[192499] = {id=192499, zh_CN="一抹云雾般朦胧的光晕在它周身一闪而过。", },
	[192500] = {id=192500, zh_CN="一朵含苞待放的杜鹃花虚影悄然浮现又迅速消散。", },
	[192501] = {id=192501, zh_CN="留下一枚触感微凉、", },
	[192502] = {id=192502, zh_CN="带着些许湿润的种子，", },
	[192503] = {id=192503, zh_CN="轻轻落在你的掌心。", },
	[192504] = {id=192504, zh_CN="咕噜……", },
	[192505] = {id=192505, zh_CN="（翻译：不过……谢谢啦……）", },
	[192506] = {id=192506, zh_CN="不客气，小猫殿下。", },
	[192507] = {id=192507, zh_CN="你笑着摸摸它的头。", },
	[192508] = {id=192508, zh_CN="芝麻糊没有躲开你的抚摸，", },
	[192509] = {id=192509, zh_CN="反而往你手心蹭了蹭。", },
	[192510] = {id=192510, zh_CN="咕噜噜……喵。", },
	[192511] = {id=192511, zh_CN="（翻译：看在你今天表现不错的份上……）", },
	[192512] = {id=192512, zh_CN="（翻译：芝麻糊特许你……以后可以多摸几下。）", },
