	[192968] = {id=192968, zh_CN="紫瞳望着书页上褪色的插画。", },
	[192969] = {id=192969, zh_CN="那上面描绘着盛大的宴会，", },
	[192970] = {id=192970, zh_CN="和衣着华丽的人们。", },
	[192971] = {id=192971, zh_CN="喵嗷……呜，喵喵，喵嗷。", },
	[192972] = {id=192972, zh_CN="（翻译：书上说……这里曾经充满光亮和音乐。）", },
	[192973] = {id=192973, zh_CN="（翻译：还有……古堡猫家族的祖先。）", },
	[192974] = {id=192974, zh_CN="喵喵，咕噜，咕噜噜，喵！", },
	[192975] = {id=192975, zh_CN="（翻译：传说古堡猫族被誉为古堡守护者。）", },
	[192976] = {id=192976, zh_CN="（翻译：与古堡主人共享最高的贵族荣光。）", },
	[192977] = {id=192977, zh_CN="它抬起眼，眼神里有一丝罕见的迷茫。", },
	[192978] = {id=192978, zh_CN="喵？", },
	[192979] = {id=192979, zh_CN="（翻译：可是……）", },
	[192980] = {id=192980, zh_CN="喵喵，喵嗷喵！", },
	[192981] = {id=192981, zh_CN="（翻译：我和年糕……我们生下来就在这里了。）", },
	[192982] = {id=192982, zh_CN="（翻译：我们除了大房子和冷风，什么都没见过。）", },
	[192983] = {id=192983, zh_CN="你们就是这段历史的延续啊。", },
	[192984] = {id=192984, zh_CN="芝麻糊用爪子抓了抓书页边缘。", },
	[192985] = {id=192985, zh_CN="哈！喵呜……", },
	[192986] = {id=192986, zh_CN="（翻译：延续？才不是呢！）", },
	[192987] = {id=192987, zh_CN="喵，咕噜……喵？", },
	[192988] = {id=192988, zh_CN="（翻译：别的猫族聚在一起晒太阳。）", },
	[192989] = {id=192989, zh_CN="（翻译：有好多同伴……）", },
	[192990] = {id=192990, zh_CN="喵喵喵！", },
	[192991] = {id=192991, zh_CN="（翻译：我和年糕只有彼此和这些发霉的书！）", },
	[192992] = {id=192992, zh_CN="喵~", },
	[192993] = {id=192993, zh_CN="%PlayerName~", },
	[192994] = {id=192994, zh_CN="喵喵……喵嗷？", },
	[192995] = {id=192995, zh_CN="（翻译：“贵族”，“血统”……）", },
	[192996] = {id=192996, zh_CN="（翻译：这些东西，真的存在过吗？）", },
	[192997] = {id=192997, zh_CN="喵嗷……喵？", },
	[192998] = {id=192998, zh_CN="（翻译：还是……只是书里的故事？）", },
	[192999] = {id=192999, zh_CN="它跳上书脊……", },
	[193000] = {id=193000, zh_CN="低头看着插画中的黑猫。", },
	[193001] = {id=193001, zh_CN="一只贵妇人怀中神态倨傲、", },
	[193002] = {id=193002, zh_CN="颈戴宝石项圈的猫。", },
	[193003] = {id=193003, zh_CN="喵……嗷呜？", },
	[193004] = {id=193004, zh_CN="（翻译：古堡猫族真的存在吗？）", },
	[193005] = {id=193005, zh_CN="（翻译：我……真的属于这里吗？）", },
	[193006] = {id=193006, zh_CN="肯定——当然存在！", },
	[193007] = {id=193007, zh_CN="当然存在！", },
	[193008] = {id=193008, zh_CN="你就是古堡当之无愧的猫主人！", },
	[193009] = {id=193009, zh_CN="开导——最重要的是怎么生活。", },
	[193010] = {id=193010, zh_CN="也许血统并不重要……", },
	[193011] = {id=193011, zh_CN="重要的是你现在怎么生活。", },
	[193012] = {id=193012, zh_CN="我有一个主意！", },
	[193013] = {id=193013, zh_CN="欸！我有一个主意！", },
	[193014] = {id=193014, zh_CN="我们去电影厂拍部电影吧！", },
	[193015] = {id=193015, zh_CN="把你从书中看到的辉煌“重现”出来。", },
	[193016] = {id=193016, zh_CN="让你重返古堡荣光年代！", },
	[193017] = {id=193017, zh_CN="芝麻糊耳朵瞬间竖立，歪头。", },
	[193018] = {id=193018, zh_CN="喵？咕噜噜？", },
	[193019] = {id=193019, zh_CN="（翻译：重现？怎么重现？）", },
	[193020] = {id=193020, zh_CN="芝麻糊来当导演！", },
	[193021] = {id=193021, zh_CN="我们去电影厂。", },
	[193022] = {id=193022, zh_CN="你来当导演，当编剧……", },
	[193023] = {id=193023, zh_CN="我们把它拍成一部属于你的电影！", },
	[193024] = {id=193024, zh_CN="喵嗷……", },
	[193025] = {id=193025, zh_CN="（翻译：电……电影？芝麻糊……能行吗？）", },
	[193026] = {id=193026, zh_CN="你犹豫了吗？", },
	[193027] = {id=193027, zh_CN="喵！（翻译：不要不要！）", },
	[193028] = {id=193028, zh_CN="喵嗷，咕噜噜，喵！", },
	[193029] = {id=193029, zh_CN="（翻译：芝麻糊来当演员，）", },
	[193030] = {id=193030, zh_CN="（导演和编剧就交给你了！）", },
	[193031] = {id=193031, zh_CN="喵！", },
	[193032] = {id=193032, zh_CN="（翻译：我相信你喵！）", },
	[193033] = {id=193033, zh_CN="从电影厂出来，", },
	[193034] = {id=193034, zh_CN="你蹲下身，与芝麻糊平视。", },
	[193035] = {id=193035, zh_CN="这是属于你的过去！", },
	[193036] = {id=193036, zh_CN="看到了吗？这就是你的过去。", },
	[193037] = {id=193037, zh_CN="这是你的血脉所承载的荣耀。", },
	[193038] = {id=193038, zh_CN="芝麻糊，你不是凭空出现的。", },
	[193039] = {id=193039, zh_CN="你属于这里。", },
	[193040] = {id=193040, zh_CN="芝麻糊缓缓转过头，", },
	[193041] = {id=193041, zh_CN="眼睛里有水光闪烁。", },
	[193042] = {id=193042, zh_CN="它努力瞪大眼睛不让它掉下来。", },
	[193043] = {id=193043, zh_CN="喵嗷……喵？", },
	[193044] = {id=193044, zh_CN="（翻译：这些……真的曾经发生过，对吗？）", },
	[193045] = {id=193045, zh_CN="是的，你就是辉煌存在的证明。", },
	[193046] = {id=193046, zh_CN="你就是古堡的喵喵大仙！", },
	[193047] = {id=193047, zh_CN="就是芝麻·古堡主·糊！", },
	[193048] = {id=193048, zh_CN="血统纯正，身份高贵，毋庸置疑。", },
	[193049] = {id=193049, zh_CN="芝麻糊猛地扑过来，", },
	[193050] = {id=193050, zh_CN="用毛茸茸的脑袋使劲你的脸颊和下巴。", },
	[193051] = {id=193051, zh_CN="咕噜噜噜噜！喵！呜喵！", },
	[193052] = {id=193052, zh_CN="（翻译：谢谢你……%PlayerName，谢谢你……）", },
	[193053] = {id=193053, zh_CN="它蹭了好一会儿才退开，", },
	[193054] = {id=193054, zh_CN="似乎有些不好意思地扭过头。", },
	[193055] = {id=193055, zh_CN="芝麻糊快速舔了几下自己的爪子，", },
	[193056] = {id=193056, zh_CN="试图恢复高傲的模样。", },
	[193057] = {id=193057, zh_CN="但微微发抖的尾巴尖卖了它。", },
	[193058] = {id=193058, zh_CN="喵嗷！", },
	[193059] = {id=193059, zh_CN="（翻译：芝麻糊当然知道自己是高贵的！）", },
	[193060] = {id=193060, zh_CN="喵……喵嗷！", },
	[193061] = {id=193061, zh_CN="（翻译：只……只是偶尔需要一些事实证明一下！）", },
	[193062] = {id=193062, zh_CN="咕噜噜，咕噜……", },
	[193063] = {id=193063, zh_CN="（翻译：这个电影……拷贝一份！）", },
	[193064] = {id=193064, zh_CN="（翻译：芝麻糊要收进藏品室的最里面！）", },
	[193065] = {id=193065, zh_CN="芝麻糊跳下电影厂的楼梯，", },
	[193066] = {id=193066, zh_CN="回头看了你一眼。", },
	[193067] = {id=193067, zh_CN="眼神恢复了往日的神采，", },
	[193068] = {id=193068, zh_CN="甚至更多了几分底气十足的骄傲。", },
	[193069] = {id=193069, zh_CN="喵！", },
