	[193313] = {id=193313, zh_CN="你有什么事吗，芝麻糊？", },
	[193314] = {id=193314, zh_CN="喵嗷……喵……", },
	[193315] = {id=193315, zh_CN="（翻译：芝麻糊今天有个重大任务委派给你。）", },
