	[193330] = {id=193330, zh_CN="潜入", },
	[193331] = {id=193331, zh_CN="聚会潜入·进入潜行，找到密道入口。与芝麻糊一起，在他的指引下，潜入聚会，寻找亮闪闪的藏品。", },
	[193332] = {id=193332, zh_CN="聚会潜入·进入潜行，找到密道入口。与芝麻糊一起，在他的指引下，潜入聚会，寻找亮闪闪的藏品。", },
	[193333] = {id=193333, zh_CN="【聚会潜入】", },
	[193334] = {id=193334, zh_CN="躲开守卫，找到密道入口。与芝麻糊一起，在他的指引下，潜入聚会，寻找亮闪闪的藏品。", },
	[193335] = {id=193335, zh_CN="躲开守卫，找到密道入口。与芝麻糊一起，在他的指引下，潜入聚会，寻找亮闪闪的藏品。", },
	[193336] = {id=193336, zh_CN="密道入口", },
	[193337] = {id=193337, zh_CN="请点击上方游玩乐园—休闲聚会。\n前往舞会。与场上的芝麻糊互动|邀请共舞吧。", },
	[193338] = {id=193338, zh_CN="芝麻糊对你一直以来的舞蹈技艺成长感到满意，现在是时候接受考试，完成出师了。", },
	[193339] = {id=193339, zh_CN="舞会场景，和芝麻糊一起跳舞", },
	[193340] = {id=193340, zh_CN="【舞会考核：完成】", },
	[193341] = {id=193341, zh_CN="你完成了舞蹈。去和芝麻糊说话吧。", },
	[193342] = {id=193342, zh_CN="前往古堡，和芝麻糊对话。你将从芝麻门下顺利出师！", },
	[193343] = {id=193343, zh_CN="请点击右上方制片厂，发布剧本，一键成片。\n为芝麻糊制作你想象中的古堡传奇历史，重现书籍中的古堡荣光。", },
	[193344] = {id=193344, zh_CN="前往制片厂，创作剧本，一键成片。为芝麻糊制作你想象中的古堡传奇历史，重现书籍中的古堡荣光。", },
	[193345] = {id=193345, zh_CN="【聚会潜入：完成】", },
