	[193347] = {id=193347, zh_CN="潜行场景，寻找密道入口", },
	[193348] = {id=193348, zh_CN="你已经完成与芝麻糊的舞蹈考核，去古堡和她说话吧。", },
	[193349] = {id=193349, zh_CN="你已经成功制作好一部讲述了古堡辉煌历史的影像，现在回去古堡和芝麻糊分享吧。", },
	[193350] = {id=193350, zh_CN="哪来的小猫？别来捣乱！", },
