	[193580] = {id=193580, zh_CN="喵~，芝麻糊可不会被%PlayerName的礼物美食给打倒。", },
	[193581] = {id=193581, zh_CN="哦我的上帝喵！美食礼物如瀑布般，淹没喵喵我了！", },
	[193582] = {id=193582, zh_CN="和芝麻糊对话，无人的古堡里，藏着一双眼睛……请一定小心。", },
	[193583] = {id=193583, zh_CN="和芝麻糊对话，芝麻糊的高傲激起你学习猫族的语言的驱力，向芝麻糊请教，听懂它的喵喵叫。", },
	[193584] = {id=193584, zh_CN="和芝麻糊对话，今日的古堡十分反常，高墙上的芝麻糊迟迟未出现，去找找它吧。", },
	[193585] = {id=193585, zh_CN="前往古堡，与芝麻糊对话。你得到了芝麻糊的认可！喵喵，它有很多话想对你说！", },
	[193586] = {id=193586, zh_CN="前往古堡，与芝麻糊对话。你的舞姿得到了芝麻糊的认可！", },
	[193587] = {id=193587, zh_CN="前往古堡，与芝麻糊对话。向芝麻糊虚心请教礼仪知识。它很痴迷于当你的小老师。", },
	[193588] = {id=193588, zh_CN="前往古堡，与芝麻糊对话。你即将出师！向芝麻糊询问最后的考验吧！", },
	[193589] = {id=193589, zh_CN="前往古堡，与芝麻糊对话。芝麻糊居然还有一只白猫弟弟，可姐弟俩的性格……", },
	[193590] = {id=193590, zh_CN="前往古堡，与芝麻糊对话。芝麻糊有事情想要拜托你。", },
	[193591] = {id=193591, zh_CN="前往古堡，与芝麻糊对话。你得到了芝麻糊的认可！喵喵，它有很多话想对你说！", },
	[193592] = {id=193592, zh_CN="前往古堡，与芝麻糊对话。你的地位越发巩固！喵，芝麻糊有很多感谢的话想对你说！", },
	[193593] = {id=193593, zh_CN="前往古堡，与芝麻糊对话。你得到了芝麻糊的认可！", },
	[193594] = {id=193594, zh_CN="前往古堡，与芝麻糊对话。芝麻糊想要邀请你参与它的冒险！", },
	[193595] = {id=193595, zh_CN="前往古堡，与芝麻糊对话。聚会开始！你和芝麻糊的寻物探险开始了！", },
	[193596] = {id=193596, zh_CN="前往古堡，与芝麻糊对话。你的投喂得到了猫猫的认可！", },
	[193597] = {id=193597, zh_CN="前往古堡，与芝麻糊对话。你的投喂似乎改变了猫猫的口味。", },
	[193598] = {id=193598, zh_CN="前往古堡，与芝麻糊对话。你的投喂似乎改变了猫猫的口味。", },
	[193599] = {id=193599, zh_CN="前往古堡，与芝麻糊对话。你的投喂似乎改变了猫猫的口味。", },
	[193600] = {id=193600, zh_CN="前往古堡，与芝麻糊对话。你的投喂得到了猫猫的认可！喵，它有很多话要告诉你哦。", },
	[193601] = {id=193601, zh_CN="前往古堡，与芝麻糊对话。你的抚摸得到了猫猫的认可！", },
	[193602] = {id=193602, zh_CN="前往古堡，与芝麻糊对话。你的抚摸得到了猫猫的认可！喵，它有很多话要告诉你哦。", },
