	[193674] = {id=193674, zh_CN="更换昵称。", },
	[193675] = {id=193675, zh_CN="好的，我会记住。", },
	[193676] = {id=193676, zh_CN="最终停在了生物体标准的36度。", },
	[193677] = {id=193677, zh_CN="你与他的手心中交换温差。", },
	[193678] = {id=193678, zh_CN="惊异！！好温暖。", },
	[193679] = {id=193679, zh_CN="我想相比于冰冷的机械，", },
	[193680] = {id=193680, zh_CN="工作已全部完成。", },
	[193681] = {id=193681, zh_CN="记忆无差错。", },
	[193682] = {id=193682, zh_CN="他默默升高你接触到的机体温度。", },
