	[200109] = {id=200109, zh_CN="【一千夜最后一夜】", },
	[200110] = {id=200110, zh_CN="阿加莎公主的身影出现，", },
	[200111] = {id=200111, zh_CN="她似乎刚结束一场小型会晤，", },
	[200112] = {id=200112, zh_CN="准备离开。", },
	[200113] = {id=200113, zh_CN="出声叫住阿加莎。", },
	[200114] = {id=200114, zh_CN="阿加莎！", },
	[200115] = {id=200115, zh_CN="阿加莎眼眸倏然睁大，身躯一颤。", },
	[200116] = {id=200116, },
	[200117] = {id=200117, zh_CN="她朝着声音传来的方向侧脸望去。", },
	[200118] = {id=200118, },
	[200119] = {id=200119, zh_CN="下午好呀！", },
	[200120] = {id=200120, zh_CN="阿加莎脚步微顿，", },
	[200121] = {id=200121, zh_CN="牵起裙缎朝你屈膝行礼。", },
	[200122] = {id=200122, zh_CN="她脚步轻盈地朝你走来，", },
	[200123] = {id=200123, },
	[200124] = {id=200124, zh_CN="雾紫色的长发流淌着如缎的柔光。", },
	[200125] = {id=200125, },
	[200126] = {id=200126, zh_CN="上前打招呼。", },
	[200127] = {id=200127, zh_CN="你追上阿加莎略显匆忙的脚步，", },
	[200128] = {id=200128, zh_CN="轻轻从身侧拍了拍她的肩膀。", },
	[200129] = {id=200129, zh_CN="阿加莎，下午好。", },
	[200130] = {id=200130, zh_CN="阿加莎眼眸倏然睁大，身躯一颤。", },
	[200131] = {id=200131, },
	[200132] = {id=200132, zh_CN="几秒后，她恢复温柔如暖阳的微笑。", },
	[200133] = {id=200133, zh_CN="阿加莎脚步微顿，", },
	[200134] = {id=200134, zh_CN="牵起裙缎朝你屈膝行礼。", },
	[200135] = {id=200135, zh_CN="雾紫色的长发流淌着如缎的柔光。", },
	[200136] = {id=200136, },
	[200137] = {id=200137, zh_CN="悄悄离开。", },
	[200138] = {id=200138, zh_CN="你不愿打扰，缓缓退步……", },
	[200139] = {id=200139, zh_CN="喷泉细密的水雾将你身影遮住，", },
	[200140] = {id=200140, zh_CN="你即将悄悄离开。", },
	[200141] = {id=200141, zh_CN="阿加莎透过水雾一眼便看见了你。", },
	[200142] = {id=200142, },
	[200143] = {id=200143, zh_CN="下午好。", },
	[200144] = {id=200144, zh_CN="阿加莎脚步微顿，", },
	[200145] = {id=200145, zh_CN="牵起裙缎朝你屈膝行礼。", },
	[200146] = {id=200146, zh_CN="她脚步轻盈地朝你走来，", },
	[200147] = {id=200147, },
	[200148] = {id=200148, zh_CN="雾紫色的长发流淌着如缎的柔光。", },
	[200149] = {id=200149, },
	[200150] = {id=200150, zh_CN="%PlayerName阁下，祝您午安。", },
	[200151] = {id=200151, zh_CN="希望午后的阳光没有让您感到不适。", },
	[200152] = {id=200152, zh_CN="没有让您感到不适。", },
	[200153] = {id=200153, zh_CN="没想到会在这里见到公主。", },
	[200154] = {id=200154, zh_CN="我刚刚结束会议。", },
	[200155] = {id=200155, zh_CN="今日在此处偶遇您，", },
	[200156] = {id=200156, zh_CN="我大概受到了潘神的眷顾。", },
	[200157] = {id=200157, zh_CN="您来到这里，一切可还习惯？", },
	[200158] = {id=200158, zh_CN="习惯！", },
	[200159] = {id=200159, zh_CN="如若有任何需要，请务必告知我。", },
	[200160] = {id=200160, zh_CN="方舟一定竭尽所能地帮助阁下。", },
	[200161] = {id=200161, zh_CN="点头——谢谢。", },
	[200162] = {id=200162, zh_CN="谢谢。", },
	[200163] = {id=200163, zh_CN="如果有需要，我一定会麻烦公主的。", },
	[200164] = {id=200164, zh_CN="到时候可不要说我不客气。", },
	[200165] = {id=200165, zh_CN="当然不会。", },
	[200166] = {id=200166, zh_CN="阁下能来，是方舟的幸事。", },
	[200167] = {id=200167, zh_CN="阿加莎从侍从的提篮中取出一封邀请函。", },
	[200168] = {id=200168, },
	[200169] = {id=200169, zh_CN="那信封是柔和的珍珠白色，", },
	[200170] = {id=200170, zh_CN="边缘滚着细细的紫金线。", },
	[200171] = {id=200171, zh_CN="方舟的暗纹图标刻印在信封上。", },
	[200172] = {id=200172, zh_CN="我这样贸然邀请您，", },
	[200173] = {id=200173, zh_CN="实在不符合礼仪。", },
	[200174] = {id=200174, zh_CN="但今日的偶遇，", },
	[200175] = {id=200175, zh_CN="让我有机会亲自向您发出邀请。", },
	[200176] = {id=200176, zh_CN="过几日，", },
	[200177] = {id=200177, zh_CN="方舟将会联合三族，", },
	[200178] = {id=200178, zh_CN="在城堡外的喷泉平台上举行音乐晚宴。", },
	[200179] = {id=200179, zh_CN="举行音乐晚宴。", },
	[200180] = {id=200180, zh_CN="为了近期三族之间的外交，", },
	[200181] = {id=200181, zh_CN="以及欢迎！", },
	[200182] = {id=200182, zh_CN="像您这样尊贵又特别的客人。", },
	[200183] = {id=200183, zh_CN="不知阁下届时是否方便赏光？", },
	[200184] = {id=200184, zh_CN="作为诺亚方舟的未来继承人，", },
	[200185] = {id=200185, zh_CN="我真诚地希望能借此机会，", },
	[200186] = {id=200186, zh_CN="带您更加深入地感受，", },
	[200187] = {id=200187, zh_CN="这里的人文历史。", },
	[200188] = {id=200188, zh_CN="也希望能有荣幸……", },
	[200189] = {id=200189, zh_CN="在这个轻松的晚宴上，", },
	[200190] = {id=200190, zh_CN="聆听您旅途中的故事。", },
	[200191] = {id=200191, zh_CN="接过信封，欣然接受。", },
	[200192] = {id=200192, zh_CN="感谢公主的盛情邀请，", },
	[200193] = {id=200193, zh_CN="我一定会准时赴约。", },
	[200194] = {id=200194, zh_CN="您有如此高的意愿，真是太好了。", },
	[200195] = {id=200195, zh_CN="希望您来自浩瀚星海之外的经历，", },
	[200196] = {id=200196, zh_CN="能给方舟带来全新的视角。", },
	[200197] = {id=200197, zh_CN="礼貌询问晚宴礼仪。", },
	[200198] = {id=200198, zh_CN="非常感谢公主的盛情邀请。", },
	[200199] = {id=200199, zh_CN="阿加莎公主。", },
	[200200] = {id=200200, zh_CN="不知晚宴对着装和礼仪方面有何要求？", },
	[200201] = {id=200201, zh_CN="我希望能符合方舟的礼节。", },
	[200202] = {id=200202, zh_CN="阿加莎眼睛微微睁大，她轻掩住嘴。", },
	[200203] = {id=200203, zh_CN="噢！您……您真是太体贴了。", },
	[200204] = {id=200204, zh_CN="如果您愿意穿着得体的常服前来。", },
	[200205] = {id=200205, zh_CN="那便是对我、对方舟最大的敬意了。", },
	[200206] = {id=200206, zh_CN="希望您来自浩瀚星海之外的经历，", },
	[200207] = {id=200207, zh_CN="能给方舟带来全新的视角。", },
	[200208] = {id=200208, zh_CN="接过信封，略显犹豫。", },
	[200209] = {id=200209, zh_CN="这……非常感谢您的邀请。", },
	[200210] = {id=200210, zh_CN="只是我初来乍到，对方舟的礼仪尚不熟悉，", },
	[200211] = {id=200211, zh_CN="恐怕……", },
	[200212] = {id=200212, zh_CN="阿加莎眼睛微微睁大，她轻掩住嘴。", },
	[200213] = {id=200213, zh_CN="您不用为此苦恼。", },
	[200214] = {id=200214, zh_CN="如果您愿意穿着得体的常服前来。", },
	[200215] = {id=200215, zh_CN="那便是对我、对方舟最大的敬意了。", },
	[200216] = {id=200216, zh_CN="希望您可以赏光。", },
	[200217] = {id=200217, zh_CN="点头答应——我会的。", },
	[200218] = {id=200218, zh_CN="那真是太好了。", },
	[200219] = {id=200219, zh_CN="希望您来自浩瀚星海之外的经历，", },
	[200220] = {id=200220, zh_CN="能给方舟带来全新的视角。", },
	[200221] = {id=200221, zh_CN="阿加莎将邀请函轻轻放入你的手中，", },
	[200222] = {id=200222, zh_CN="指尖不经意间划过你的掌心，", },
	[200223] = {id=200223, zh_CN="带来一丝温凉。", },
	[200224] = {id=200224, zh_CN="她的笑容如春日暖阳，", },
	[200225] = {id=200225, zh_CN="带着不容错辨的期待。", },
	[200226] = {id=200226, zh_CN="那么，我就当您答应了！", },
	[200227] = {id=200227, zh_CN="期待着与您在流光下的再次会面。", },
	[200228] = {id=200228, zh_CN="阿加莎后退一步，", },
	[200229] = {id=200229, zh_CN="再次优雅地屈膝行礼。", },
	[200230] = {id=200230, zh_CN="这次行礼的角度似乎比初见时，", },
	[200231] = {id=200231, zh_CN="更标准一些。", },
	[200232] = {id=200232, zh_CN="阳光穿过她头顶的花架，", },
	[200233] = {id=200233, zh_CN="在她精致的裙摆上投下斑驳的光影。", },
	[200234] = {id=200234, zh_CN="愿流光与冒险常伴您左右。", },
	[200235] = {id=200235, zh_CN="晚宴见！", },
	[200236] = {id=200236, zh_CN="期待与您在晚宴相见。", },
	[200237] = {id=200237, zh_CN="抱歉，我还有其他事务，失陪。", },
	[200238] = {id=200238, zh_CN="阿加莎挺直脊背，转身而去。", },
	[200239] = {id=200239, zh_CN="雾紫色的长发随着动作，", },
	[200240] = {id=200240, zh_CN="划出一道优雅的弧线……", },
	[200241] = {id=200241, zh_CN="她的背影在侍从的簇拥下，", },
	[200242] = {id=200242, zh_CN="渐渐融入灿烂的阳光之中。", },
	[200243] = {id=200243, zh_CN="灿烂的阳光与水雾之中。", },
	[200244] = {id=200244, zh_CN="手中那封制作精良，", },
	[200245] = {id=200245, zh_CN="散发着淡淡冷香的邀请函，", },
	[200246] = {id=200246, zh_CN="在阳光下闪烁着微光。", },
	[200247] = {id=200247, zh_CN="时间流转，宴会当夜，", },
	[200248] = {id=200248, zh_CN="你来到城堡的喷泉亭台上。", },
	[200249] = {id=200249, zh_CN="喷泉旁灯火辉煌，", },
	[200250] = {id=200250, zh_CN="来往的人群耳畔厮磨，衣香鬓影。", },
	[200251] = {id=200251, zh_CN="你隐匿在晚宴的角落，", },
	[200252] = {id=200252, zh_CN="望着人群中光芒四射的阿加莎。", },
	[200253] = {id=200253, zh_CN="她如同一颗温润的雾紫色珍珠，", },
	[200254] = {id=200254, zh_CN="优雅自如地穿梭在各方代表之间。", },
	[200255] = {id=200255, zh_CN="每每有宾客来至，", },
	[200256] = {id=200256, zh_CN="她总能精准地认出来访的宾客，", },
	[200257] = {id=200257, zh_CN="为其送上最诚挚的欢迎。", },
	[200258] = {id=200258, zh_CN="音乐宴会演奏其第一章……", },
	[200259] = {id=200259, zh_CN="阿加莎微笑着登上喷泉亭台的二楼，", },
	[200260] = {id=200260, zh_CN="温柔又坚定的声音，", },
	[200261] = {id=200261, zh_CN="在众人耳边响起。", },
	[200262] = {id=200262, zh_CN="她左手覆在胸前，微微低头。", },
	[200263] = {id=200263, zh_CN="愿这片今夜的流光，", },
	[200264] = {id=200264, zh_CN="能抚平您灵魂的疲倦，", },
	[200265] = {id=200265, zh_CN="带来片刻安宁。", },
	[200266] = {id=200266, zh_CN="她以最为古老，", },
	[200267] = {id=200267, zh_CN="表达极高敬意的人族抚胸礼，", },
	[200268] = {id=200268, zh_CN="向在场的来宾表达感激之情。", },
	[200269] = {id=200269, zh_CN="阿加莎的余光落在你的身上，", },
	[200270] = {id=200270, zh_CN="朝你轻轻点头示意。", },
	[200271] = {id=200271, zh_CN="尊贵的各位来宾，", },
	[200272] = {id=200272, zh_CN="诺亚方舟，向您致以最诚挚的问候。", },
	[200273] = {id=200273, zh_CN="欢迎您莅临今晚的音乐盛会，", },
	[200274] = {id=200274, zh_CN="我们在此庆祝和平常驻。", },
	[200275] = {id=200275, zh_CN="以及欢迎远道而来的天外宾客。", },
	[200276] = {id=200276, zh_CN="热烈的掌声响起，", },
	[200277] = {id=200277, zh_CN="宣告着宴会的开场。", },
	[200278] = {id=200278, zh_CN="结束开场的阿加莎，", },
	[200279] = {id=200279, zh_CN="在人群中迅速捕捉到你的位置。", },
	[200280] = {id=200280, zh_CN="她牵起裙摆从二楼走下，", },
	[200281] = {id=200281, zh_CN="直直朝你走来。", },
	[200282] = {id=200282, zh_CN="阿加莎微微屈膝，", },
	[200283] = {id=200283, zh_CN="行了一个标准的问候礼。", },
	[200284] = {id=200284, zh_CN="%PlayerName阁下，", },
	[200285] = {id=200285, zh_CN="我很高兴您能信守承诺，", },
	[200286] = {id=200286, zh_CN="来参加晚宴。", },
	[200287] = {id=200287, zh_CN="模仿阿加莎行礼。", },
	[200288] = {id=200288, zh_CN="你模仿阿加莎，", },
	[200289] = {id=200289, zh_CN="生涩地朝她低头行礼。", },
	[200290] = {id=200290, zh_CN="感谢您的盛情邀请。", },
	[200291] = {id=200291, zh_CN="感谢您的盛情邀请，阿加莎公主。", },
	[200292] = {id=200292, zh_CN="您的美丽与热情，让我印象深刻。", },
	[200293] = {id=200293, zh_CN="试图尝试种族礼仪。", },
	[200294] = {id=200294, zh_CN="你试图行自己种族的礼节。", },
	[200295] = {id=200295, zh_CN="但动作不够标准。", },
	[200296] = {id=200296, zh_CN="呃……谢谢你的邀请，公主殿下。", },
	[200297] = {id=200297, zh_CN="点头。", },
	[200298] = {id=200298, zh_CN="好久不见，阿加莎公主。", },
	[200299] = {id=200299, zh_CN="感谢你的邀请。", },
	[200300] = {id=200300, zh_CN="您能适应就好，请不必拘束。", },
	[200301] = {id=200301, zh_CN="今日就让我来当您的导游吧。", },
	[200302] = {id=200302, zh_CN="我的荣幸。", },
	[200303] = {id=200303, zh_CN="三族盟约已有百年历史……", },
	[200304] = {id=200304, zh_CN="这晚宴不仅是欢庆米乐星球的和平，", },
	[200305] = {id=200305, zh_CN="更是维系友谊与共同展望未来的桥梁。", },
	[200306] = {id=200306, zh_CN="她指着城墙上的壁画……", },
	[200307] = {id=200307, zh_CN="您看这城墙上的壁画，", },
	[200308] = {id=200308, zh_CN="它们描绘的便是三族签订，", },
	[200309] = {id=200309, zh_CN="和平休战契约的历史。", },
	[200310] = {id=200310, zh_CN="这些划过天际的流光，", },
	[200311] = {id=200311, zh_CN="便象征着指引与合作……", },
	[200312] = {id=200312, zh_CN="阿加莎如同一只优雅的蝴蝶，", },
	[200313] = {id=200313, zh_CN="带你在宾客间穿梭。", },
	[200314] = {id=200314, zh_CN="她为你导航史迹的同时，", },
	[200315] = {id=200315, zh_CN="还能自如地与周围的宾客谈论。", },
	[200316] = {id=200316, zh_CN="这是精灵族最年长的长老阁下。", },
	[200317] = {id=200317, zh_CN="您带来的花露我非常喜欢！", },
	[200318] = {id=200318, zh_CN="我一定会好好品尝的。", },
	[200319] = {id=200319, zh_CN="您喜欢就好，", },
	[200320] = {id=200320, zh_CN="古树庇佑您，阿加莎公主。", },
	[200321] = {id=200321, zh_CN="一道粗迈又高亢的声音插入！", },
	[200322] = {id=200322, zh_CN="阿加莎公主！", },
	[200323] = {id=200323, zh_CN="阿加莎攥紧拳头与其重重拳击。", },
	[200324] = {id=200324, zh_CN="酋长阁下，", },
	[200325] = {id=200325, zh_CN="您新锻造的合金我已经收到了。", },
	[200326] = {id=200326, zh_CN="方舟就需要这样坚韧又耐用的材料，", },
	[200327] = {id=200327, zh_CN="您的锻造技术正是方舟不可缺少的力量呢。", },
	[200328] = {id=200328, zh_CN="哈哈哈哈哈！那是当然了！", },
	[200329] = {id=200329, zh_CN="这位便是%PlayerName阁下，", },
	[200330] = {id=200330, zh_CN="年轻的天外星旅舰长。", },
	[200331] = {id=200331, zh_CN="话音刚落，", },
	[200332] = {id=200332, zh_CN="一种丽阳般的灼热感萦绕在四周，", },
	[200333] = {id=200333, zh_CN="遥遥望去，一朵牡丹的幻影，", },
	[200334] = {id=200334, zh_CN="在阿加莎面前若隐若现，", },
	[200335] = {id=200335, zh_CN="那颗至黑的牡丹王种落在你的手上。", },
	[200336] = {id=200336, zh_CN="……", },
	[200337] = {id=200337, zh_CN="与阿加莎一路应酬而过，", },
	[200338] = {id=200338, zh_CN="你恍然发现，", },
	[200339] = {id=200339, zh_CN="阿加莎像温柔的紫色火烧云，", },
	[200340] = {id=200340, zh_CN="梦幻又朦胧的色彩下，", },
	[200341] = {id=200341, zh_CN="是她如沐的降世之雨。", },
	[200342] = {id=200342, zh_CN="阿加莎忽掏出丝帕，", },
	[200343] = {id=200343, zh_CN="递给甜品台前的少女，", },
	[200344] = {id=200344, zh_CN="为其挡住周围的目光。", },
	[200345] = {id=200345, zh_CN="小姐不必惊慌，", },
	[200346] = {id=200346, zh_CN="城堡侧厅有备用的礼服，", },
	[200347] = {id=200347, zh_CN="让我的侍从陪您去更换吧。", },
	[200348] = {id=200348, zh_CN="相信小小的意外，", },
	[200349] = {id=200349, zh_CN="无损您今晚的光彩。", },
	[200350] = {id=200350, zh_CN="另一边，阿加莎又及时附身，", },
	[200351] = {id=200351, zh_CN="扶住追逐打闹的妖灵族小殿下。", },
	[200352] = {id=200352, zh_CN="小心脚下，我勇往直前的小勇士。", },
	[200353] = {id=200353, zh_CN="晚宴在与阿加莎的陪伴下，", },
	[200354] = {id=200354, zh_CN="如晨星划过天际。", },
	[200355] = {id=200355, zh_CN="此时，阿加莎才有时间与精力，", },
	[200356] = {id=200356, zh_CN="与你说上几句话。", },
	[200357] = {id=200357, zh_CN="对不起，%PlayerName阁下。", },
	[200358] = {id=200358, zh_CN="我想我的导游工作，", },
	[200359] = {id=200359, zh_CN="似乎做得不是很好。", },
	[200360] = {id=200360, zh_CN="关心——没关系。", },
	[200361] = {id=200361, zh_CN="没关系，你要好好休息才是。", },
	[200362] = {id=200362, zh_CN="谢谢提醒，我会的。", },
	[200363] = {id=200363, zh_CN="痴迷——你好厉害。", },
	[200364] = {id=200364, zh_CN="不，你让我见识了很多。", },
	[200365] = {id=200365, zh_CN="你今天真是太厉害了，阿加莎公主。", },
	[200366] = {id=200366, zh_CN="都是我作为公主应该做的。", },
	[200367] = {id=200367, zh_CN="安慰——我们可以下次再约。", },
	[200368] = {id=200368, zh_CN="也许遗憾会带来下次的相逢。", },
	[200369] = {id=200369, zh_CN="请不要感到抱歉，阿加莎公主。", },
	[200370] = {id=200370, zh_CN="好。我记住阁下的话了。", },
	[200371] = {id=200371, zh_CN="期待下次的再会。", },
	[200372] = {id=200372, zh_CN="数日后，", },
	[200373] = {id=200373, zh_CN="阿加莎又寄给你一封亲笔的邀请函，", },
	[200374] = {id=200374, zh_CN="信封上盖着阿加莎的私印。", },
	[200375] = {id=200375, zh_CN="那是一朵不知名的花章，", },
	[200376] = {id=200376, zh_CN="香薰纸制成的信封上，", },
	[200377] = {id=200377, zh_CN="萦绕着沁人心脾的香气……", },
	[200378] = {id=200378, zh_CN="让人不自觉地就想起阿加莎的温柔。", },
	[200379] = {id=200379, zh_CN="阿加莎的温柔。", },
	[200380] = {id=200380, zh_CN="你拆开信封，", },
	[200381] = {id=200381, zh_CN="娟秀工整的字迹缓缓展开：", },
	[200382] = {id=200382, zh_CN="阿加莎难消歉意，", },
	[200383] = {id=200383, zh_CN="邀你隔日参加她的私人茶会。", },
	[200384] = {id=200384, zh_CN="约会当日。", },
	[200385] = {id=200385, zh_CN="城堡旁的花房上，", },
	[200386] = {id=200386, zh_CN="阿加莎已经等候多时。", },
	[200387] = {id=200387, zh_CN="而你，也如约而至。", },
	[200388] = {id=200388, zh_CN="她换下了繁复的晚礼服，", },
	[200389] = {id=200389, zh_CN="身着一条剪裁优雅的淡紫色及膝裙。", },
	[200390] = {id=200390, zh_CN="雾紫色的长发松松挽起，", },
	[200391] = {id=200391, zh_CN="别着一枚小巧的珍珠发夹。", },
	[200392] = {id=200392, zh_CN="她亲自在花架下布置茶点，", },
	[200393] = {id=200393, zh_CN="看到你的到来，", },
	[200394] = {id=200394, zh_CN="露出比晚宴时更放松一些的微笑。", },
	[200395] = {id=200395, zh_CN="你来了！请坐。", },
	[200396] = {id=200396, zh_CN="希望你喜欢私人茶会。", },
	[200397] = {id=200397, zh_CN="她示意你入座，", },
	[200398] = {id=200398, zh_CN="亲自为你斟上一杯香气馥郁的花茶。", },
	[200399] = {id=200399, zh_CN="晚宴那天，与你交谈，", },
	[200400] = {id=200400, zh_CN="我……感到非常愉快。", },
	[200401] = {id=200401, zh_CN="您身上有一种……独特的气质，", },
	[200402] = {id=200402, zh_CN="在方舟并不常见。", },
	[200403] = {id=200403, zh_CN="这让我很希望能与您……", },
	[200404] = {id=200404, zh_CN="多多交流，成为朋友。", },
	[200405] = {id=200405, zh_CN="你敏锐地捕捉到一丝考量。", },
	[200406] = {id=200406, zh_CN="阿加莎在评估衡量你。", },
	[200407] = {id=200407, zh_CN="是否读心？", },
	[200408] = {id=200408, zh_CN="读心。", },
	[200409] = {id=200409, zh_CN="摆事实，自信分析。", },
	[200410] = {id=200410, zh_CN="抛个眉眼，宫心计！", },
	[200411] = {id=200411, zh_CN="天灵灵，地灵灵。", },
	[200412] = {id=200412, zh_CN="不读心。", },
	[200413] = {id=200413, zh_CN="一个轻柔的声线在你脑海响起，", },
	[200414] = {id=200414, zh_CN="似乎是阿加莎的声音。", },
	[200415] = {id=200415, zh_CN="希望这份友好能让他放下戒心。", },
	[200416] = {id=200416, zh_CN="作为中立的变量，", },
	[200417] = {id=200417, zh_CN="他的观察视角或许能提供，", },
	[200418] = {id=200418, zh_CN="意想不到的价值！", },
	[200419] = {id=200419, zh_CN="朋友……", },
	[200420] = {id=200420, zh_CN="如果能有一个不涉及利益的朋友，", },
	[200421] = {id=200421, zh_CN="似乎也还不错呢！", },
	[200422] = {id=200422, zh_CN="你什么都没听见，", },
	[200423] = {id=200423, zh_CN="阿加莎的心墙比你想象的要厚。", },
	[200424] = {id=200424, zh_CN="阿加莎见你没立刻回应，", },
	[200425] = {id=200425, zh_CN="她忽指向旁边画架上的一幅抽象油画。", },
	[200426] = {id=200426, zh_CN="你看这幅画，", },
	[200427] = {id=200427, zh_CN="画师试图捕捉超新星爆发瞬间，", },
	[200428] = {id=200428, zh_CN="展现出混沌之处的灭亡与新生之美。", },
	[200429] = {id=200429, zh_CN="色彩如此大胆奔放，", },
	[200430] = {id=200430, zh_CN="线条却带着有序的韵律……", },
	[200431] = {id=200431, zh_CN="仿佛宇宙在狂欢中的一声叹息。", },
	[200432] = {id=200432, zh_CN="表现出浓厚兴趣。", },
	[200433] = {id=200433, zh_CN="星空确实令人着迷了！", },
	[200434] = {id=200434, zh_CN="阿加莎公主对画作的解读很特别。", },
	[200435] = {id=200435, zh_CN="你也这么觉得吗？！", },
	[200436] = {id=200436, zh_CN="【读心】", },
	[200437] = {id=200437, zh_CN="啊啊啊啊，", },
	[200438] = {id=200438, zh_CN="他居然和我有一样的爱好好开心！", },
	[200439] = {id=200439, zh_CN="哦，我刚刚是不是太失礼了，", },
	[200440] = {id=200440, zh_CN="他没有发现吧！", },
	[200441] = {id=200441, zh_CN="似乎有一串尖叫声！", },
	[200442] = {id=200442, zh_CN="从你的脑海里路过。", },
	[200443] = {id=200443, zh_CN="你未能听清其中含义。", },
	[200444] = {id=200444, zh_CN="这位画师的作品总是充满，", },
	[200445] = {id=200445, zh_CN="原始野性的生命力，", },
	[200446] = {id=200446, zh_CN="这也许和他的妖灵族种族有关。", },
	[200447] = {id=200447, zh_CN="他还有一系列关于“深海”的作品，", },
	[200448] = {id=200448, zh_CN="用色更加纯粹梦幻。", },
	[200449] = {id=200449, zh_CN="制止……", },
	[200450] = {id=200450, zh_CN="阿加莎滔滔不绝地分享着。", },
	[200451] = {id=200451, zh_CN="你原本想要伸出制止的手也放了下来，", },
	[200452] = {id=200452, zh_CN="托着腮望着她卸下一丝公主的姿态。", },
	[200453] = {id=200453, zh_CN="尝试理解，但有点困惑。", },
	[200454] = {id=200454, zh_CN="呃……很独特的视角。", },
	[200455] = {id=200455, zh_CN="这些漩涡般的蓝色，是代表星云吗？", },
	[200456] = {id=200456, zh_CN="是的。我很喜欢这位作家。", },
	[200457] = {id=200457, zh_CN="他的作品总是充满原始野性的生命力……", },
	[200458] = {id=200458, zh_CN="【读心】", },
	[200459] = {id=200459, zh_CN="唉，好像搞砸了……", },
	[200460] = {id=200460, zh_CN="连你都无法理解，", },
	[200461] = {id=200461, zh_CN="我对于星空的喜爱？难过！", },
	[200462] = {id=200462, zh_CN="似乎有一串尖叫声", },
	[200463] = {id=200463, zh_CN="从你的脑海里路过，", },
	[200464] = {id=200464, zh_CN="但你未能听清其中含义。", },
	[200465] = {id=200465, zh_CN="不理解，直接表达抱歉。", },
	[200466] = {id=200466, zh_CN="说实话，这画有点……太抽象了。", },
	[200467] = {id=200467, zh_CN="我看不太懂具体想表达什么。", },
	[200468] = {id=200468, zh_CN="好吧，看来你不喜欢这些。", },
	[200469] = {id=200469, zh_CN="【读心】", },
	[200470] = {id=200470, zh_CN="唉，好像搞砸了……", },
	[200471] = {id=200471, zh_CN="连你都无法理解，", },
	[200472] = {id=200472, zh_CN="我对于星空的喜爱吗？", },
	[200473] = {id=200473, zh_CN="似乎有一串尖叫声", },
	[200474] = {id=200474, zh_CN="从你的脑海里路过，", },
	[200475] = {id=200475, zh_CN="但你未能听清其中含义。", },
	[200476] = {id=200476, zh_CN="就在这时，", },
	[200477] = {id=200477, zh_CN="一名年轻侍从端着新烤制的茶点走来。", },
	[200478] = {id=200478, zh_CN="侍从脚下被藤蔓绊了一下，", },
	[200479] = {id=200479, zh_CN="手中的托盘倾斜，", },
	[200480] = {id=200480, zh_CN="精美的瓷杯眼看就要摔落！", },
	[200481] = {id=200481, zh_CN="啊！公主殿下！对不起……", },
	[200482] = {id=200482, zh_CN="阿加莎的反应快得惊人。", },
	[200483] = {id=200483, zh_CN="她几乎是下意识地伸手去扶托盘。", },
	[200484] = {id=200484, zh_CN="虽然未能完全阻止茶杯翻倒，", },
	[200485] = {id=200485, zh_CN="但却改变了茶杯摔落的轨迹，", },
	[200486] = {id=200486, zh_CN="但避免了茶水烫伤侍从的手臂。", },
	[200487] = {id=200487, zh_CN="她眉头都没皱，", },
	[200488] = {id=200488, zh_CN="第一时间看向侍从，", },
	[200489] = {id=200489, zh_CN="眼神充满关切。", },
	[200490] = {id=200490, zh_CN="别慌！亲爱的。", },
	[200491] = {id=200491, zh_CN="你没事吧？有没有烫到？！", },
	[200492] = {id=200492, zh_CN="公主殿下！我……我没事！", },
	[200493] = {id=200493, zh_CN="可是您的裙子，您的手！", },
	[200494] = {id=200494, zh_CN="都是我的错！", },
	[200495] = {id=200495, zh_CN="阿加莎迅速抽出手帕按在自己手背。", },
	[200496] = {id=200496, zh_CN="没事就好。一点茶水而已。", },
	[200497] = {id=200497, zh_CN="快去用冷水冲洗一下你的手，", },
	[200498] = {id=200498, zh_CN="换身衣服。", },
	[200499] = {id=200499, zh_CN="这里我来处理。", },
	[200500] = {id=200500, zh_CN="记住，安全第一。", },
	[200501] = {id=200501, zh_CN="【读心】", },
	[200502] = {id=200502, zh_CN="呜呜呜，好痛好痛好痛好痛……", },
	[200503] = {id=200503, zh_CN="希望侍从别太自责……", },
	[200504] = {id=200504, zh_CN="裙子脏了等下还有日程……", },
	[200505] = {id=200505, zh_CN="得让侍女准备替换的……", },
	[200506] = {id=200506, zh_CN="在%PlayerName面前失态了……", },
	[200507] = {id=200507, zh_CN="镇定镇定，", },
	[200508] = {id=200508, zh_CN="阿加莎你已经做得很棒了！", },
	[200509] = {id=200509, zh_CN="电光火石间，你什么都没听到。", },
	[200510] = {id=200510, zh_CN="阿加莎看着侍从慌乱离开，", },
	[200511] = {id=200511, zh_CN="才轻轻舒了一口气。", },
	[200512] = {id=200512, zh_CN="她手指无意识地摩挲着，", },
	[200513] = {id=200513, zh_CN="茶杯光滑的边缘。", },
	[200514] = {id=200514, zh_CN="一抹阳光倏然出现在阿加莎的面前，", },
	[200515] = {id=200515, zh_CN="那是一朵金黄色的金合欢，", },
	[200516] = {id=200516, zh_CN="在阳光下显得格外耀眼。", },
	[200517] = {id=200517, zh_CN="毛茸茸的花瓣在微风中轻轻摇曳，", },
	[200518] = {id=200518, zh_CN="如同啦啦队花球在鼓舞人心。", },
	[200519] = {id=200519, zh_CN="阿加莎望着这朵金合欢飘向对面，", },
	[200520] = {id=200520, zh_CN="最终融入你的体内。", },
	[200521] = {id=200521, zh_CN="【读心】", },
	[200522] = {id=200522, zh_CN="毛茸茸的好可爱！", },
	[200523] = {id=200523, zh_CN="感觉心灵都得到了振奋呢！", },
	[200524] = {id=200524, zh_CN="唉？飞向了%PlayerName？", },
	[200525] = {id=200525, zh_CN="突如其来的情绪花种，", },
	[200526] = {id=200526, zh_CN="打乱了你的心绪，", },
	[200527] = {id=200527, zh_CN="读心的能力便消散了。", },
	[200528] = {id=200528, zh_CN="茶会接近尾声，", },
	[200529] = {id=200529, zh_CN="阿加莎将一枚压着干燥百合花的书签，", },
	[200530] = {id=200530, zh_CN="轻轻推到你的面前。", },
	[200531] = {id=200531, zh_CN="一点小小的纪念，", },
	[200532] = {id=200532, zh_CN="感谢您今日的陪伴。", },
	[200533] = {id=200533, zh_CN="看来我的判断失误了。", },
	[200534] = {id=200534, zh_CN="希望下次在邀请你来的时候，", },
	[200535] = {id=200535, zh_CN="我能投其所好，找到你所喜欢的事物。", },
	[200536] = {id=200536, zh_CN="其实我可以告诉你的。", },
	[200537] = {id=200537, zh_CN="拜托请让我猜一猜吧。", },
	[200538] = {id=200538, zh_CN="这是一个有趣的游戏，不是吗？", },
	[200539] = {id=200539, zh_CN="您对艺术的见解如此独到，令人欣喜。", },
	[200540] = {id=200540, zh_CN="主动邀约下次见面。", },
	[200541] = {id=200541, zh_CN="或许可以和公主约定下次的艺术沙龙？", },
	[200542] = {id=200542, zh_CN="再好不过了。", },
	[200543] = {id=200543, zh_CN="如果您有兴趣，改日可以邀请您，", },
	[200544] = {id=200544, zh_CN="参观我的私人收藏馆？", },
	[200545] = {id=200545, zh_CN="那里有些……", },
	[200546] = {id=200546, zh_CN="不太方便向公众展示的小爱好。", },
	[200547] = {id=200547, zh_CN="也许能给您带来些不一样的灵感。", },
	[200548] = {id=200548, zh_CN="我想你一定会喜欢的。", },
	[200549] = {id=200549, zh_CN="接受赞美。", },
	[200550] = {id=200550, zh_CN="阿加莎公主的智慧与见解也让人称叹。", },
	[200551] = {id=200551, zh_CN="一定付出了很多努力吧。", },
	[200552] = {id=200552, zh_CN="这是我应该履行的责任。", },
	[200553] = {id=200553, zh_CN="今日的茶会非常愉快。", },
	[200554] = {id=200554, zh_CN="希望很快能再次与您畅谈！", },
	[200555] = {id=200555, zh_CN="无论是艺术，星空，还是……", },
	[200556] = {id=200556, zh_CN="方舟的风土人情。", },
	[200557] = {id=200557, zh_CN="请随时书信联系我。", },
	[200558] = {id=200558, zh_CN="她的笑容完美无瑕，", },
	[200559] = {id=200559, zh_CN="晚宴时那层若有若无的雾气，", },
	[200560] = {id=200560, zh_CN="似乎又重新笼罩上来。", },
	[200561] = {id=200561, zh_CN="你与阿加莎告别，", },
	[200562] = {id=200562, zh_CN="阿加莎目送着你的离开。", },
	[200563] = {id=200563, zh_CN="她独自站在花房的紫藤花下，", },
	[200564] = {id=200564, zh_CN="看着那枚被茶水染上淡淡渍痕的茶杯。", },
	[200565] = {id=200565, zh_CN="阿加莎指尖轻轻拂过被烫红的手背。", },
	[200566] = {id=200566, zh_CN="【读心】", },
	[200567] = {id=200567, zh_CN="抓不住的气声忽然闯入你的脑海，", },
	[200568] = {id=200568, zh_CN="也许连阿加莎都没能意识到她自己的渴望。", },
	[200569] = {id=200569, zh_CN="下次……", },
	[200570] = {id=200570, zh_CN="或许可以让他看看我那只会唱歌的机械小鸟……", },
	[200571] = {id=200571, zh_CN="电光火石间，你什么都没听到。", },
	[200572] = {id=200572, zh_CN="阳光透过花架，", },
	[200573] = {id=200573, zh_CN="在阿加莎精致的侧脸上，", },
	[200574] = {id=200574, zh_CN="投下斑驳的光影。", },
	[200575] = {id=200575, zh_CN="商会某处偏僻、爬满藤蔓的角落，", },
	[200576] = {id=200576, zh_CN="夜晚，远处传来城市节日的喧嚣声。", },
	[200577] = {id=200577, zh_CN="阿加莎的身影悄悄闪出。", },
	[200578] = {id=200578, zh_CN="她卸下了标志性的盘发，", },
	[200579] = {id=200579, zh_CN="柔顺的雾紫色长发披散着，", },
	[200580] = {id=200580, zh_CN="用一条简单的蓝色丝带束起一部分。", },
	[200581] = {id=200581, zh_CN="她穿着一条款式简洁的白色棉质连衣裙，", },
	[200582] = {id=200582, zh_CN="外面套了件浅米色开衫。", },
	[200583] = {id=200583, zh_CN="阿加莎脸上只有淡淡的裸妆，", },
	[200584] = {id=200584, zh_CN="戴着一副小巧的无框眼镜。", },
	[200585] = {id=200585, zh_CN="这样……真的可以吗？", },
	[200586] = {id=200586, zh_CN="不会被认出来吧？", },
	[200587] = {id=200587, zh_CN="希望看起来不太奇怪？", },
	[200588] = {id=200588, zh_CN="【读心】", },
	[200589] = {id=200589, zh_CN="天啊心跳快得像要蹦出来！", },
	[200590] = {id=200590, zh_CN="比第一次主持晨会还紧张一百倍！", },
	[200591] = {id=200591, zh_CN="裙子会不会有褶皱？眼镜滑下来了……", },
	[200592] = {id=200592, zh_CN="希望路灯够暗！", },
	[200593] = {id=200593, zh_CN="千万不要有人认出我来。", },
	[200594] = {id=200594, zh_CN="你好像错过了阿加莎的心声。", },
	[200595] = {id=200595, zh_CN="开玩笑，低声安抚。", },
	[200596] = {id=200596, zh_CN="你现在看起来就像个刚下课的学生。", },
	[200597] = {id=200597, zh_CN="放松点，不会有人注意到我们的。", },
	[200598] = {id=200598, zh_CN="伸出手，等待。", },
	[200599] = {id=200599, zh_CN="阿加莎犹豫了一下，轻轻搭上你的手，", },
	[200600] = {id=200600, zh_CN="指尖微凉。", },
	[200601] = {id=200601, zh_CN="让我看看吧，你会带我去向何方。", },
	[200602] = {id=200602, zh_CN="热闹的节日市集。", },
	[200603] = {id=200603, zh_CN="灯火璀璨，人声鼎沸，", },
	[200604] = {id=200604, zh_CN="各种小吃香气混合，", },
	[200605] = {id=200605, zh_CN="街头艺人表演吸引着人群。", },
	[200606] = {id=200606, zh_CN="阿加莎像第一次进游乐场的孩子，", },
	[200607] = {id=200607, zh_CN="眼睛亮晶晶的，充满好奇。", },
	[200608] = {id=200608, zh_CN="你指着一个正在表演喷火的街头艺人。", },
	[200609] = {id=200609, zh_CN="看那个！", },
	[200610] = {id=200610, zh_CN="小心别靠太近，但很震撼对吧？", },
	[200611] = {id=200611, zh_CN="哇……他们好厉害！", },
	[200612] = {id=200612, zh_CN="但还是要做好防护才对……", },
	[200613] = {id=200613, zh_CN="哦不，我是说……这需要很强的技巧。", },
	[200614] = {id=200614, zh_CN="她意识到自己又用了官方思维，", },
	[200615] = {id=200615, zh_CN="不好意思地吐了吐舌头。", },
	[200616] = {id=200616, zh_CN="你和阿加莎走到至一个卖可丽饼的摊位旁。", },
	[200617] = {id=200617, zh_CN="试试这个？", },
	[200618] = {id=200618, zh_CN="经典草莓奶油味，市集必吃。", },
	[200619] = {id=200619, zh_CN="这个……卫生吗？", },
	[200620] = {id=200620, zh_CN="不，我是说……看起来很好吃！", },
	[200621] = {id=200621, zh_CN="将可丽饼塞给阿加莎！", },
	[200622] = {id=200622, zh_CN="阿加莎望着你递来的可丽饼，", },
	[200623] = {id=200623, zh_CN="在你的鼓励的目光下接过一份，", },
	[200624] = {id=200624, zh_CN="小心地咬了一口。", },
	[200625] = {id=200625, zh_CN="唔……好甜！", },
	[200626] = {id=200626, zh_CN="但好吃！", },
	[200627] = {id=200627, zh_CN="她像发现新大陆，又咬了一大口，", },
	[200628] = {id=200628, zh_CN="眼睛满足地眯起。", },
	[200629] = {id=200629, zh_CN="你带她来到一个套圈游戏摊前。", },
	[200630] = {id=200630, zh_CN="来试试运气？", },
	[200631] = {id=200631, zh_CN="你想要哪个？", },
	[200632] = {id=200632, zh_CN="目标是丑萌丑萌的独角兽！", },
	[200633] = {id=200633, zh_CN="她兴致勃勃地接过塑料圈，", },
	[200634] = {id=200634, zh_CN="学着前面人的样子瞄准，", },
	[200635] = {id=200635, zh_CN="扔出去——偏得离谱。", },
	[200636] = {id=200636, zh_CN="啊呀！好难！", },
	[200637] = {id=200637, zh_CN="再试一次！", },
	[200638] = {id=200638, zh_CN="阿加莎屏住呼吸，", },
	[200639] = {id=200639, zh_CN="全神贯注地盯着地上的玩偶。", },
	[200640] = {id=200640, zh_CN="收腕，抛出！", },
	[200641] = {id=200641, zh_CN="我中了！看！小兔子！", },
	[200642] = {id=200642, zh_CN="她举起战利品，笑容灿烂。", },
	[200643] = {id=200643, zh_CN="首战告捷！战利品很可爱哦！", },
	[200644] = {id=200644, zh_CN="你带她来到一个套圈游戏摊前。", },
	[200645] = {id=200645, zh_CN="来试试运气？", },
	[200646] = {id=200646, zh_CN="忽然，人潮涌来，", },
	[200647] = {id=200647, zh_CN="阿加莎被挤得一个踉跄，", },
	[200648] = {id=200648, zh_CN="鼻梁上的眼镜差点掉落。", },
	[200649] = {id=200649, zh_CN="阿加莎连忙扶起眼睛，惊魂未定。", },
	[200650] = {id=200650, zh_CN="她下意识紧紧抓住了你的衣袖，", },
	[200651] = {id=200651, zh_CN="几乎半个身子靠过来寻求稳定。", },
	[200652] = {id=200652, zh_CN="人潮稍退，她像触电般立刻松开手，", },
	[200653] = {id=200653, zh_CN="脸颊飞起红晕，", },
	[200654] = {id=200654, zh_CN="低头整理并不乱的头发。", },
	[200655] = {id=200655, zh_CN="对……对不起，人太多了……", },
	[200656] = {id=200656, zh_CN="没事，安全最重要。", },
	[200657] = {id=200657, zh_CN="来，试试套圈？", },
	[200658] = {id=200658, zh_CN="她接过圈，心思却明显不在游戏上，", },
	[200659] = {id=200659, zh_CN="目光总是不自觉地瞟向你专注的侧脸。", },
	[200660] = {id=200660, zh_CN="将套圈套到的兔子给她。", },
	[200661] = {id=200661, zh_CN="呐！小兔子。", },
	[200662] = {id=200662, zh_CN="阿加莎接过玩偶，", },
	[200663] = {id=200663, zh_CN="指尖不经意触碰到你的手，", },
	[200664] = {id=200664, zh_CN="像被烫到般迅速收回。", },
	[200665] = {id=200665, zh_CN="谢……谢谢。这个很可爱。", },
	[200666] = {id=200666, zh_CN="她把小兔子紧紧抱在怀里。", },
	[200667] = {id=200667, zh_CN="【读心】", },
	[200668] = {id=200668, zh_CN="他的手好温暖……", },
	[200669] = {id=200669, zh_CN="阿加莎，清醒点！", },
	[200670] = {id=200670, zh_CN="这只是一次……工作间隙中的休息！", },
	[200671] = {id=200671, zh_CN="但这个小兔子真的好可爱……", },
	[200672] = {id=200672, zh_CN="你好像错过了阿加莎的心声。", },
	[200673] = {id=200673, zh_CN="你带她来到一个套圈游戏摊前。", },
	[200674] = {id=200674, zh_CN="来试试运气？", },
	[200675] = {id=200675, zh_CN="阿加莎刚要点头，", },
	[200676] = {id=200676, zh_CN="她的目光扫过旁边摊位，", },
	[200677] = {id=200677, zh_CN="拒绝妖灵族光顾的符号。", },
	[200678] = {id=200678, zh_CN="她身体猛地一僵，", },
	[200679] = {id=200679, zh_CN="下意识抓住你的胳膊想拉你离开。", },
	[200680] = {id=200680, zh_CN="我们……我们去那边看看吧！", },
	[200681] = {id=200681, zh_CN="好，听你的。", },
	[200682] = {id=200682, zh_CN="阿加莎在一个妖灵族部落，", },
	[200683] = {id=200683, zh_CN="特色手工编织的摊位前停下脚步，", },
	[200684] = {id=200684, zh_CN="眼神复杂。", },
	[200685] = {id=200685, zh_CN="阿加莎指着一种复杂的编织纹样，", },
	[200686] = {id=200686, zh_CN="声音艰涩。", },
	[200687] = {id=200687, zh_CN="这个纹样，我在外交文献里见过。", },
	[200688] = {id=200688, zh_CN="它代表勇气与守护，对吗？", },
	[200689] = {id=200689, zh_CN="要不……我们先回去？", },
	[200690] = {id=200690, zh_CN="这里人越来越多了。", },
	[200691] = {id=200691, zh_CN="对不起，我……我是不是扫兴了？", },
	[200692] = {id=200692, zh_CN="没有，是我考虑不周。", },
	[200693] = {id=200693, zh_CN="我们走吧。", },
	[200694] = {id=200694, zh_CN="一对母子看着阿加莎的侧脸，", },
	[200695] = {id=200695, zh_CN="越看越疑惑。", },
	[200696] = {id=200696, zh_CN="他们忍不住轻轻碰了碰旁边你的胳膊。", },
	[200697] = {id=200697, zh_CN="诶，打扰一下。", },
	[200698] = {id=200698, zh_CN="那位小姐……看着好眼熟啊？", },
	[200699] = {id=200699, zh_CN="是不是阿加莎公主殿下？", },
	[200700] = {id=200700, zh_CN="您认错了吧？", },
	[200701] = {id=200701, zh_CN="公主殿下怎么会在这里？", },
	[200702] = {id=200702, zh_CN="妈妈妈妈！是公主！", },
	[200703] = {id=200703, zh_CN="电视里的漂亮公主！", },
	[200704] = {id=200704, zh_CN="我想和公主拍照！", },
	[200705] = {id=200705, zh_CN="小男孩的声音不大不小，", },
	[200706] = {id=200706, zh_CN="周围几个人都好奇地看了过来。", },
	[200707] = {id=200707, zh_CN="阿加莎听到公主二字，", },
	[200708] = {id=200708, zh_CN="身体瞬间僵住。", },
	[200709] = {id=200709, zh_CN="她下意识地后退半步，", },
	[200710] = {id=200710, zh_CN="几乎要躲到你身后，", },
	[200711] = {id=200711, zh_CN="手指紧张地攥紧了裙角。", },
	[200712] = {id=200712, zh_CN="哎呀！真的是公主殿下！太荣幸了！", },
	[200713] = {id=200713, zh_CN="殿下！真没想到能在这里遇见您！", },
	[200714] = {id=200714, zh_CN="我……我和我家小宝，", },
	[200715] = {id=200715, zh_CN="都是您的忠实粉丝！", },
	[200716] = {id=200716, zh_CN="他天天嚷着要像公主一样勇敢！", },
	[200717] = {id=200717, zh_CN="那个，那个……", },
	[200718] = {id=200718, zh_CN="能不能求您和我们合个影？", },
	[200719] = {id=200719, zh_CN="就一张！拜托了！", },
	[200720] = {id=200720, zh_CN="那位母亲双手合十，眼神充满恳求。", },
	[200721] = {id=200721, zh_CN="小男孩也仰着头，", },
	[200722] = {id=200722, zh_CN="大眼睛亮晶晶地看着阿加莎。", },
	[200723] = {id=200723, zh_CN="【读心】", },
	[200724] = {id=200724, zh_CN="完了……被认出来了！", },
	[200725] = {id=200725, zh_CN="护卫呢？记者会不会在附近？", },
	[200726] = {id=200726, zh_CN="现在该怎么办？", },
	[200727] = {id=200727, zh_CN="拒绝会让他们失望……可答应的话……", },
	[200728] = {id=200728, zh_CN="你好像错过了阿加莎的心声。", },
	[200729] = {id=200729, zh_CN="我……", },
	[200730] = {id=200730, zh_CN="这位女士，您……", },
	[200731] = {id=200731, zh_CN="阿加莎想再次否认，", },
	[200732] = {id=200732, zh_CN="但看着小男孩纯真期待的眼神，", },
	[200733] = {id=200733, zh_CN="话又咽了回去。", },
	[200734] = {id=200734, zh_CN="她深吸一口气，", },
	[200735] = {id=200735, zh_CN="属于公主的责任感和亲民形象占了上风。", },
	[200736] = {id=200736, zh_CN="……好吧。只是一张合照，可以吗？", },
	[200737] = {id=200737, zh_CN="隔开阿加莎和母子俩。", },
	[200738] = {id=200738, zh_CN="你用身躯将阿加莎与母子俩，", },
	[200739] = {id=200739, zh_CN="不动声色地隔离开来。", },
	[200740] = {id=200740, zh_CN="女士，请带着您的孩子，", },
	[200741] = {id=200741, zh_CN="随我去比较安静的地方好吗？", },
	[200742] = {id=200742, zh_CN="为了阿加莎殿下的安全考虑，", },
	[200743] = {id=200743, zh_CN="我们悄悄地合影。", },
	[200744] = {id=200744, zh_CN="好好好。", },
	[200745] = {id=200745, zh_CN="平复母子俩的激动。", },
	[200746] = {id=200746, zh_CN="你好这位女士，", },
	[200747] = {id=200747, zh_CN="阿加莎殿下已经答应您合影了，", },
	[200748] = {id=200748, zh_CN="但希望您能保持镇定。", },
	[200749] = {id=200749, zh_CN="我想您也不想招来更多的人。", },
	[200750] = {id=200750, zh_CN="影响节日庆典是吧？", },
	[200751] = {id=200751, zh_CN="对对对，我们小声一点。", },
	[200752] = {id=200752, zh_CN="女士，请带着您的孩子，", },
	[200753] = {id=200753, zh_CN="随我去比较安静的地方好吗？", },
	[200754] = {id=200754, zh_CN="为了阿加莎殿下的安全考虑，", },
	[200755] = {id=200755, zh_CN="我们悄悄地合影。", },
	[200756] = {id=200756, zh_CN="好好好。", },
	[200757] = {id=200757, zh_CN="安抚好母子俩，", },
	[200758] = {id=200758, zh_CN="你引领着母子俩走在阿加莎身后。", },
	[200759] = {id=200759, zh_CN="你目不转睛地注视着阿加莎挺直的背脊，", },
	[200760] = {id=200760, zh_CN="想要用灼热的目光为她提供力量。", },
	[200761] = {id=200761, zh_CN="阿加莎在一处花坛停下脚步，", },
	[200762] = {id=200762, zh_CN="她求助般地回头望向你。", },
	[200763] = {id=200763, zh_CN="两位就在这里，和殿下拍照好吗？", },
	[200764] = {id=200764, zh_CN="太好了！太感谢您了殿下！", },
	[200765] = {id=200765, zh_CN="小宝，快站好！要笑哦！", },
	[200766] = {id=200766, zh_CN="她赶紧把兴奋得蹦跳的小男孩按在身边，", },
	[200767] = {id=200767, zh_CN="自己站在阿加莎另一侧。", },
	[200768] = {id=200768, zh_CN="麻烦您帮我们拍一下好吗？用这个！", },
	[200769] = {id=200769, zh_CN="小宝，别傻站着，", },
	[200770] = {id=200770, zh_CN="快摆个帅气的姿势给公主看！", },
	[200771] = {id=200771, zh_CN="他立刻挺起小胸脯，一手叉腰，", },
	[200772] = {id=200772, zh_CN="一手比了个自认很酷的“耶”，", },
	[200773] = {id=200773, zh_CN="咧开嘴露出缺了颗门牙的笑容。", },
	[200774] = {id=200774, zh_CN="你熟练地打开相机，半蹲下来找角度。", },
	[200775] = {id=200775, zh_CN="没问题！小宝，姿势很帅哦！", },
	[200776] = {id=200776, zh_CN="公主殿下，您也放松点，看镜头！", },
	[200777] = {id=200777, zh_CN="对，就这样，自然的笑容最好看！", },
	[200778] = {id=200778, zh_CN="1， 2， 3，茄子！", },
	[200779] = {id=200779, zh_CN="在你自然的引导下，", },
	[200780] = {id=200780, zh_CN="阿加莎紧绷的肩膀微微放松。", },
	[200781] = {id=200781, zh_CN="她看着镜头里小男孩搞怪的样子，", },
	[200782] = {id=200782, zh_CN="嘴角终于勾起一丝带着点无奈的温柔笑意。", },
	[200783] = {id=200783, zh_CN="咔嚓——一张照片慢慢成像。", },
	[200784] = {id=200784, zh_CN="拍得太好了！谢谢殿下！", },
	[200785] = {id=200785, zh_CN="小宝，快谢谢公主殿下！", },
	[200786] = {id=200786, zh_CN="不客气。祝你们节日愉快。", },
	[200787] = {id=200787, zh_CN="你沉稳地打开相机，", },
	[200788] = {id=200788, zh_CN="目光快速扫过周围环境确认安全。", },
	[200789] = {id=200789, zh_CN="好的。殿下，请放松。", },
	[200790] = {id=200790, zh_CN="小宝，你的姿势非常棒！看我这里。", },
	[200791] = {id=200791, zh_CN="你调整位置，", },
	[200792] = {id=200792, zh_CN="特意将阿加莎置于画面中心，", },
	[200793] = {id=200793, zh_CN="稍靠后的安全位置。", },
	[200794] = {id=200794, zh_CN="1， 2， 3，茄子。", },
	[200795] = {id=200795, zh_CN="阿加莎找到了些许依靠，", },
	[200796] = {id=200796, zh_CN="身体不自觉地微微向你所在方向，", },
	[200797] = {id=200797, zh_CN="倾斜了一点点。脸上飞起红霞。", },
	[200798] = {id=200798, zh_CN="咔嚓！一张照片慢慢成像。", },
	[200799] = {id=200799, zh_CN="哎呀拍得真精神！殿下您真美！", },
	[200800] = {id=200800, zh_CN="小宝快谢谢！", },
	[200801] = {id=200801, zh_CN="谢谢。祝你们玩得开心。", },
	[200802] = {id=200802, zh_CN="阿加莎匆匆瞥了你一眼，", },
	[200803] = {id=200803, zh_CN="那眼神里有羞涩，有感激，", },
	[200804] = {id=200804, zh_CN="也有一丝被触碰后的慌乱。", },
	[200805] = {id=200805, zh_CN="就在母亲递过手机时，", },
	[200806] = {id=200806, zh_CN="阿加莎眼角的余光忽然瞥见！", },
	[200807] = {id=200807, zh_CN="不远处一个小摊上挂着的，", },
	[200808] = {id=200808, zh_CN="拒绝妖灵族光顾的符号。", },
	[200809] = {id=200809, zh_CN="她瞳孔猛地一缩！", },
	[200810] = {id=200810, zh_CN="不顾形象地想要将自己藏起来。", },
	[200811] = {id=200811, zh_CN="立刻挡住摊位的视线！", },
	[200812] = {id=200812, zh_CN="好的，马上拍。", },
	[200813] = {id=200813, zh_CN="小宝看镜头！笑！", },
	[200814] = {id=200814, zh_CN="你几乎没怎么调整，快速按下快门。", },
	[200815] = {id=200815, zh_CN="咔嚓——一张照片慢慢成像。", },
	[200816] = {id=200816, zh_CN="在你挡住视线的瞬间，", },
	[200817] = {id=200817, zh_CN="阿加莎身体几不可查地颤抖了一下，", },
	[200818] = {id=200818, zh_CN="脸上勉强维持的笑容变得极其苍白脆弱。", },
	[200819] = {id=200819, zh_CN="谢谢殿下！谢谢您！小宝……", },
	[200820] = {id=200820, zh_CN="不客气。请……请享受节日。", },
	[200821] = {id=200821, zh_CN="她几乎是立刻转身，", },
	[200822] = {id=200822, zh_CN="下意识地抓住了你的手臂。", },
	[200823] = {id=200823, zh_CN="我们……快离开这里。", },
	[200824] = {id=200824, zh_CN="阿加莎的指尖冰凉，带着明显的惊悸。", },
	[200825] = {id=200825, zh_CN="就在这时，一位穿着便装", },
	[200826] = {id=200826, zh_CN="但气质精悍的男子悄然出现在不远处，", },
	[200827] = {id=200827, zh_CN="目光锁定阿加莎。", },
	[200828] = {id=200828, zh_CN="瞬间，阿加莎眼中的轻松、好奇，", },
	[200829] = {id=200829, zh_CN="羞涩或挣扎如潮水般褪去。", },
	[200830] = {id=200830, zh_CN="她背脊挺得笔直，", },
	[200831] = {id=200831, zh_CN="脸上迅速挂起一丝程式化的平静，", },
	[200832] = {id=200832, zh_CN="她回头朝护卫方向几不可察地点了下头。", },
	[200833] = {id=200833, zh_CN="一颗干枯的金合欢种。", },
	[200834] = {id=200834, zh_CN="随着阿加莎的叹息，", },
	[200835] = {id=200835, zh_CN="悄悄融入你的体内，", },
	[200836] = {id=200836, zh_CN="这颗花种失去了往日令人欢愉的力量，", },
	[200837] = {id=200837, zh_CN="好似吸纳了阿加莎今夜的欢乐，", },
	[200838] = {id=200838, zh_CN="令她又回归了公主的宁静姿态。", },
	[200839] = {id=200839, zh_CN="阿加莎望着它最终融入你的体内。", },
	[200840] = {id=200840, zh_CN="非常感谢你。", },
	[200841] = {id=200841, zh_CN="今天非常、非常难忘。", },
	[200842] = {id=200842, zh_CN="她快速行了一个近乎朋友间点头礼。", },
	[200843] = {id=200843, zh_CN="期待下次再会。", },
	[200844] = {id=200844, zh_CN="她眼中闪过一丝俏皮，随即转身，", },
	[200845] = {id=200845, zh_CN="步履从容却快速地走向护卫。", },
	[200846] = {id=200846, zh_CN="那个穿着素裙的纤细背影，", },
	[200847] = {id=200847, zh_CN="很快融入节日的人潮中，消失不见。", },
	[200848] = {id=200848, zh_CN="你和阿加莎的私下交集越来越多，", },
	[200849] = {id=200849, zh_CN="今天，你与阿加莎又约定见面。", },
	[200850] = {id=200850, zh_CN="阿加莎的私人收藏馆门口。", },
	[200851] = {id=200851, zh_CN="这里没有王宫大厅的金碧辉煌，", },
	[200852] = {id=200852, zh_CN="更像一个充满故事的老书屋。", },
	[200853] = {id=200853, zh_CN="厚重的橡木门虚掩着，", },
	[200854] = {id=200854, zh_CN="门缝里透出温暖柔和的灯光，", },
	[200855] = {id=200855, zh_CN="和旧书、木头、干花混合的独特气息。", },
	[200856] = {id=200856, zh_CN="阿加莎长发松松挽起，", },
	[200857] = {id=200857, zh_CN="脸上带着期待的微笑。", },
	[200858] = {id=200858, zh_CN="你来了！", },
	[200859] = {id=200859, zh_CN="欢迎来到我的“记忆方舟”。", },
	[200860] = {id=200860, zh_CN="这里存放的，都是时间留下的碎片。", },
	[200861] = {id=200861, zh_CN="一些……对我有特殊意义的“证物”。", },
	[200862] = {id=200862, zh_CN="好棒！像是走进了你的时间胶囊。", },
	[200863] = {id=200863, zh_CN="今天我想请你玩一个游戏。", },
	[200864] = {id=200864, zh_CN="一个……只有你能参与的解谜游戏。", },
	[200865] = {id=200865, zh_CN="什么游戏？", },
	[200866] = {id=200866, zh_CN="一个寻‘我’游戏。", },
	[200867] = {id=200867, zh_CN="线索就藏在这些物件里。", },
	[200868] = {id=200868, zh_CN="我会给你第一个提示。", },
	[200869] = {id=200869, zh_CN="你需要通过它们之间的关联，", },
	[200870] = {id=200870, zh_CN="找到最终指向我的“钥匙”，", },
	[200871] = {id=200871, zh_CN="打开那扇门。", },
	[200872] = {id=200872, zh_CN="阿加莎指向收藏馆深处一扇紧闭的，", },
	[200873] = {id=200873, zh_CN="雕刻着复杂花纹的木门。", },
	[200874] = {id=200874, zh_CN="我在门后等你。准备好了吗？", },
	[200875] = {id=200875, zh_CN="当然！放马过来吧。", },
	[200876] = {id=200876, zh_CN="她轻笑，递过来一张泛黄的乐谱纸，", },
	[200877] = {id=200877, zh_CN="上面只有几行音符。", },
	[200878] = {id=200878, zh_CN="这是第一个线索。", },
	[200879] = {id=200879, zh_CN="说完，她转身，像一尾灵活的鱼，", },
	[200880] = {id=200880, zh_CN="滑入了藏品之间，很快不见了踪影。", },
	[200881] = {id=200881, zh_CN="侦察。", },
	[200882] = {id=200882, zh_CN="乐谱的角落上写着：凝固的时间之歌，", },
	[200883] = {id=200883, zh_CN="答案在“心跳”与“回响”之间。", },
	[200884] = {id=200884, zh_CN="你想到了——", },
	[200885] = {id=200885, zh_CN="音乐。", },
	[200886] = {id=200886, zh_CN="结合乐谱，你联想到音乐或者乐器……", },
	[200887] = {id=200887, zh_CN="翻找一番，很快在一个玻璃展柜里，", },
	[200888] = {id=200888, zh_CN="发现了一个精美的古董八音盒。", },
	[200889] = {id=200889, zh_CN="你选择……", },
	[200890] = {id=200890, zh_CN="观察八音盒。", },
	[200891] = {id=200891, zh_CN="你忽然想到“回响”，", },
	[200892] = {id=200892, zh_CN="八音盒确实会产生很清脆的回响音乐，", },
	[200893] = {id=200893, zh_CN="或许你找到关键了。", },
	[200894] = {id=200894, zh_CN="你自己检查了一番，", },
	[200895] = {id=200895, zh_CN="八音盒上有一个心形发条……", },
	[200896] = {id=200896, zh_CN="再找找别的。", },
	[200897] = {id=200897, zh_CN="八音盒旁边放着一本翻开的、", },
	[200898] = {id=200898, zh_CN="阿加莎少女时代的日记。", },
	[200899] = {id=200899, zh_CN="……收到这个八音盒，拧紧发条，", },
	[200900] = {id=200900, zh_CN="听着叮咚声，感觉时间都变慢了，", },
	[200901] = {id=200901, zh_CN="像被施了魔法……", },
	[200902] = {id=200902, zh_CN="八音盒！", },
	[200903] = {id=200903, zh_CN="你立刻抓起旁边的八音盒，", },
	[200904] = {id=200904, zh_CN="盒子屁股有一个心形发条。", },
	[200905] = {id=200905, zh_CN="拧动发条。", },
	[200906] = {id=200906, zh_CN="你拧动八音盒发条，", },
	[200907] = {id=200907, zh_CN="清脆的音乐流淌出来。", },
	[200908] = {id=200908, zh_CN="音乐停止时，八音盒底部一个小暗格，", },
	[200909] = {id=200909, zh_CN="“咔哒”一声弹开，", },
	[200910] = {id=200910, zh_CN="里面竟然是一张小小的拍立得照片，", },
	[200911] = {id=200911, zh_CN="照片上正是上次市集，", },
	[200912] = {id=200912, zh_CN="阿加莎拍下的、她拿着可丽饼，", },
	[200913] = {id=200913, zh_CN="嘴角沾着奶油的瞬间！", },
	[200914] = {id=200914, zh_CN="她的脑袋只占了照片的二分之一，", },
	[200915] = {id=200915, zh_CN="另一边的某个角落里，正是你的身影。", },
	[200916] = {id=200916, zh_CN="你的心跳微微加速，", },
	[200917] = {id=200917, zh_CN="迅速将照片翻到背面。", },
	[200918] = {id=200918, zh_CN="照片背面写着一个词。", },
	[200919] = {id=200919, zh_CN="“视角”和一个指向馆内某个方向的箭头。", },
	[200920] = {id=200920, zh_CN="心形或者心脏意象？", },
	[200921] = {id=200921, zh_CN="立刻联想到关于心脏，心形的意象，", },
	[200922] = {id=200922, zh_CN="在馆内搜寻起来。", },
	[200923] = {id=200923, zh_CN="你找到了不少东西……", },
	[200924] = {id=200924, zh_CN="长腿长脚的心形玩偶；", },
	[200925] = {id=200925, zh_CN="栩栩如生的心脏玻璃制品；", },
	[200926] = {id=200926, zh_CN="闪烁着跳动心脏的数码屏幕……", },
	[200927] = {id=200927, zh_CN="你觉得什么比较可疑？", },
	[200928] = {id=200928, zh_CN="心形玩偶。", },
	[200929] = {id=200929, zh_CN="你捏了捏玩偶，", },
	[200930] = {id=200930, zh_CN="里面除了软乎的棉花，", },
	[200931] = {id=200931, zh_CN="似乎没有任何可疑的硬物……", },
	[200932] = {id=200932, zh_CN="一无所获。", },
	[200933] = {id=200933, zh_CN="玻璃制品。", },
	[200934] = {id=200934, zh_CN="你将玻璃心脏举到灯光下检查，", },
	[200935] = {id=200935, zh_CN="似乎除了隐约能拼出奇怪图案，", },
	[200936] = {id=200936, zh_CN="什么发现都没有……", },
	[200937] = {id=200937, zh_CN="你选择……", },
	[200938] = {id=200938, zh_CN="数码屏幕。", },
	[200939] = {id=200939, zh_CN="你上前仔细端详了屏幕半天，", },
	[200940] = {id=200940, zh_CN="除了每30秒重复一次的视频，", },
	[200941] = {id=200941, zh_CN="一无所获。", },
	[200942] = {id=200942, zh_CN="放下，找点别的。", },
	[200943] = {id=200943, zh_CN="再观察观察。", },
	[200944] = {id=200944, zh_CN="时间一分一秒过去，你终于放弃了它，", },
	[200945] = {id=200945, zh_CN="它并不是那个被阿加莎选中的幸运儿。", },
	[200946] = {id=200946, zh_CN="能形成回响的事物？", },
	[200947] = {id=200947, zh_CN="结合乐谱，你联想到音乐或者乐器……", },
	[200948] = {id=200948, zh_CN="翻找一番，很快在一个玻璃展柜里，", },
	[200949] = {id=200949, zh_CN="发现了一个精美的古董八音盒。", },
	[200950] = {id=200950, zh_CN="你选择……", },
	[200951] = {id=200951, zh_CN="观察八音盒。", },
	[200952] = {id=200952, zh_CN="你忽然想到“乐谱”，", },
	[200953] = {id=200953, zh_CN="八音盒确实会产生很清脆的回响音乐，", },
	[200954] = {id=200954, zh_CN="或许你找到关键了。", },
	[200955] = {id=200955, zh_CN="八音盒上有一个心形发条……", },
	[200956] = {id=200956, zh_CN="再找找别的。", },
	[200957] = {id=200957, zh_CN="八音盒旁边放着一本翻开的、", },
	[200958] = {id=200958, zh_CN="阿加莎少女时代的日记。", },
	[200959] = {id=200959, zh_CN="……收到这个八音盒，拧紧发条，", },
	[200960] = {id=200960, zh_CN="听着叮咚声，感觉时间都变慢了，", },
	[200961] = {id=200961, zh_CN="像被施了魔法……", },
	[200962] = {id=200962, zh_CN="八音盒！", },
	[200963] = {id=200963, zh_CN="你立刻抓起旁边的八音盒，", },
	[200964] = {id=200964, zh_CN="盒子屁股有一个心形发条。", },
	[200965] = {id=200965, zh_CN="拧动发条。", },
	[200966] = {id=200966, zh_CN="你拧动八音盒发条，", },
	[200967] = {id=200967, zh_CN="清脆的音乐流淌出来。", },
	[200968] = {id=200968, zh_CN="音乐停止时，八音盒底部一个小暗格，", },
	[200969] = {id=200969, zh_CN="“咔哒”一声弹开，", },
	[200970] = {id=200970, zh_CN="里面竟然是一张小小的拍立得照片。", },
	[200971] = {id=200971, zh_CN="照片上正是上次市集，", },
	[200972] = {id=200972, zh_CN="阿加莎拍下的、她拿着可丽饼，", },
	[200973] = {id=200973, zh_CN="嘴角沾着奶油的瞬间！", },
	[200974] = {id=200974, zh_CN="她的脑袋只占了照片的二分之一，", },
	[200975] = {id=200975, zh_CN="另一边的某个角落里，正是你的身影。", },
	[200976] = {id=200976, zh_CN="你的心跳微微加速，", },
	[200977] = {id=200977, zh_CN="迅速将照片翻到背面。", },
	[200978] = {id=200978, zh_CN="照片背面写着一个词。", },
	[200979] = {id=200979, zh_CN="“视角”和一个指向馆内某个方向的箭头。", },
	[200980] = {id=200980, zh_CN="再找找。", },
	[200981] = {id=200981, zh_CN="跟着箭头方向，你来到一个画架前。", },
	[200982] = {id=200982, zh_CN="画架上蒙着布。", },
	[200983] = {id=200983, zh_CN="掀开布，是一幅未完成的抽象画，", },
	[200984] = {id=200984, zh_CN="色彩大胆泼辣，但构图有些混乱。", },
	[200985] = {id=200985, zh_CN="你选择……", },
	[200986] = {id=200986, zh_CN="观察四周。", },
	[200987] = {id=200987, zh_CN="你蹲下来四周瞥眼扫过，", },
	[200988] = {id=200988, zh_CN="画架旁放着调色板和画笔。", },
	[200989] = {id=200989, zh_CN="画架旁的小桌上，", },
	[200990] = {id=200990, zh_CN="放着上次阿加莎写的一封信。", },
	[200991] = {id=200991, zh_CN="……有时候，跳出固有的框架，", },
	[200992] = {id=200992, zh_CN="换个角度看世界，", },
	[200993] = {id=200993, zh_CN="或许会有意想不到的风景……", },
	[200994] = {id=200994, zh_CN="换个角度看世界？", },
	[200995] = {id=200995, zh_CN="你一边思考着信中的信息，", },
	[200996] = {id=200996, zh_CN="一边转换着方位观察画作……", },
	[200997] = {id=200997, zh_CN="忽然，你停在某个角度上，", },
	[200998] = {id=200998, zh_CN="从这里往画作上看去……", },
	[200999] = {id=200999, zh_CN="凹凸不平的干枯画料，", },
	[201000] = {id=201000, zh_CN="似乎在光影间形成了有规则的线条。", },
	[201001] = {id=201001, zh_CN="分析画作。", },
	[201002] = {id=201002, zh_CN="你凑近仔细观察着画作，", },
	[201003] = {id=201003, zh_CN="除了发现画作没有完成外，", },
	[201004] = {id=201004, zh_CN="没有任何可疑的地方。", },
	[201005] = {id=201005, zh_CN="上手摸摸。", },
	[201006] = {id=201006, zh_CN="你伸手轻轻触摸画上的油料，", },
	[201007] = {id=201007, zh_CN="已经干透，于是你便大胆地摸过画作，", },
	[201008] = {id=201008, zh_CN="每个角落都不放过。", },
	[201009] = {id=201009, zh_CN="奇怪的凹凸，以及若隐若现的阴影，", },
	[201010] = {id=201010, zh_CN="难道……", },
	[201011] = {id=201011, zh_CN="环顾四周，", },
	[201012] = {id=201012, zh_CN="你找到一盏可调节角度的阅读灯，", },
	[201013] = {id=201013, zh_CN="调整着灯光的角度照向画布。", },
	[201014] = {id=201014, zh_CN="当灯光以一个特定的斜角，", },
	[201015] = {id=201015, zh_CN="照射在画布上时……", },
	[201016] = {id=201016, zh_CN="那些看似混乱的色块，", },
	[201017] = {id=201017, zh_CN="在墙上投射出一个清晰的影子，", },
	[201018] = {id=201018, zh_CN="一个钥匙孔的形状！", },
	[201019] = {id=201019, zh_CN="影子旁边，用极淡的铅笔写着什么。", },
	[201020] = {id=201020, zh_CN="上前检查。", },
	[201021] = {id=201021, zh_CN="上面写着“寻找锁”。", },
	[201022] = {id=201022, zh_CN="钥匙孔……锁……", },
	[201023] = {id=201023, zh_CN="寻找锁孔。", },
	[201024] = {id=201024, zh_CN="最终，你的目光落在了一排书架侧面，", },
	[201025] = {id=201025, zh_CN="一个不起眼的、装饰性的木雕纹路上。", },
	[201026] = {id=201026, zh_CN="其中一个纹路的中心，仔细看，", },
	[201027] = {id=201027, zh_CN="正是一个小小的锁孔！", },
	[201028] = {id=201028, zh_CN="但钥匙在哪里？线索断了？", },
	[201029] = {id=201029, zh_CN="你回想之前的线索……", },
	[201030] = {id=201030, zh_CN="画作，视角，市集照片，八音盒，音乐。", },
	[201031] = {id=201031, zh_CN="视角，画作，市集照片，回响，八音盒。", },
	[201032] = {id=201032, zh_CN="画作，市集照片，视角，音乐，八音盒。", },
	[201033] = {id=201033, zh_CN="似乎没有什么关联，再想想？", },
	[201034] = {id=201034, zh_CN="“视角”的提示来自市集照片，", },
	[201035] = {id=201035, zh_CN="市集照片来自八音盒，", },
	[201036] = {id=201036, zh_CN="八音盒关联时间……", },
	[201037] = {id=201037, zh_CN="你再次看向那幅未完成的画。", },
	[201038] = {id=201038, zh_CN="画的主题是什么？", },
	[201039] = {id=201039, zh_CN="你拿起旁边阿加莎常用的速写本翻看，", },
	[201040] = {id=201040, zh_CN="里面夹着许多草图。", },
	[201041] = {id=201041, zh_CN="其中一张，画的是一个女孩的背影，", },
	[201042] = {id=201042, zh_CN="正透过一扇圆形的窗户眺望远方，", },
	[201043] = {id=201043, zh_CN="窗框的形状……正是一个钥匙孔！", },
	[201044] = {id=201044, zh_CN="速写下方写着：“我看见你的地方”。", },
	[201045] = {id=201045, zh_CN="你猛地抬头，环顾四周。", },
	[201046] = {id=201046, zh_CN="收藏馆唯一的窗户是方形的。", },
	[201047] = {id=201047, zh_CN="你想起第一次来参加阿加莎的茶会时，", },
	[201048] = {id=201048, zh_CN="她坐在这里喝茶看风景的样子……", },
	[201049] = {id=201049, zh_CN="你快步走向收藏馆深处那扇紧闭的门，", },
	[201050] = {id=201050, zh_CN="在门旁边的墙上，", },
	[201051] = {id=201051, zh_CN="挂着一幅小尺寸的油画。", },
	[201052] = {id=201052, zh_CN="画的右下角，用极细的笔写着：", },
	[201053] = {id=201053, zh_CN="“钥匙在凝视中”。", },
	[201054] = {id=201054, zh_CN="再想想。", },
	[201055] = {id=201055, zh_CN="凝视……", },
	[201056] = {id=201056, zh_CN="你站在门前，看着那扇紧闭的门。", },
	[201057] = {id=201057, zh_CN="你凑近门上那个雕刻精美的猫眼，", },
	[201058] = {id=201058, zh_CN="向内看去。", },
	[201059] = {id=201059, zh_CN="猫眼内部似乎有一个极小的反光点。", },
	[201060] = {id=201060, zh_CN="那个反光点是一把小巧的、", },
	[201061] = {id=201061, zh_CN="镶嵌着紫水晶的黄铜钥匙！", },
	[201062] = {id=201062, zh_CN="它就插在门内的锁孔上！", },
	[201063] = {id=201063, zh_CN="尝试。", },
	[201064] = {id=201064, zh_CN="怎么拿到？", },
	[201065] = {id=201065, zh_CN="用力扣动钥匙。", },
	[201066] = {id=201066, zh_CN="你试着推门，门锁着。", },
	[201067] = {id=201067, zh_CN="锁孔可以伸进去手指，", },
	[201068] = {id=201068, zh_CN="你扣动住钥匙，", },
	[201069] = {id=201069, zh_CN="用力用指腹抵住锁孔边缘，", },
	[201070] = {id=201070, zh_CN="将其生生拽出。", },
	[201071] = {id=201071, zh_CN="你不小心打掉八音盒。", },
	[201072] = {id=201072, zh_CN="你试图后退寻找到新的视角，", },
	[201073] = {id=201073, zh_CN="就像刚刚那幅画一样。", },
	[201074] = {id=201074, zh_CN="你没注意到身后摇摇欲坠的八音盒……", },
	[201075] = {id=201075, zh_CN="八音盒落在地上，发条开始转动，", },
	[201076] = {id=201076, zh_CN="阿加莎清脆的笑声录音在房间中回响。", },
	[201077] = {id=201077, zh_CN="想起“回响”的提示……", },
	[201078] = {id=201078, zh_CN="你想起第一个线索的“回响”。", },
	[201079] = {id=201079, zh_CN="你重新拿起八音盒，仔细观察，", },
	[201080] = {id=201080, zh_CN="摆弄着八音盒的发条……", },
	[201081] = {id=201081, zh_CN="你尝试着往反方向转动发条。", },
	[201082] = {id=201082, zh_CN="阿加莎清脆的笑声录音在房间中回响。", },
	[201083] = {id=201083, zh_CN="几秒钟后，门内传来轻微的“咔哒”声。", },
	[201084] = {id=201084, zh_CN="门锁开了！", },
	[201085] = {id=201085, zh_CN="你推开门，里面是一个更私密，", },
	[201086] = {id=201086, zh_CN="更温馨的小房间，更像一个画室。", },
	[201087] = {id=201087, zh_CN="阿加莎正坐在窗边的画架前，", },
	[201088] = {id=201088, zh_CN="背对着门。", },
	[201089] = {id=201089, zh_CN="听到开门声，她转过身，", },
	[201090] = {id=201090, zh_CN="脸上是毫不掩饰的惊喜和赞赏的笑容。", },
	[201091] = {id=201091, zh_CN="太棒了！你竟然真的解开了！", },
	[201092] = {id=201092, zh_CN="比我预想的快多了！", },
	[201093] = {id=201093, zh_CN="那些线索……感觉如何？", },
	[201094] = {id=201094, zh_CN="挺有意思的。", },
	[201095] = {id=201095, zh_CN="没想到线索全部都是阿加莎的记忆呢！", },
	[201096] = {id=201096, zh_CN="嗯……", },
	[201097] = {id=201097, zh_CN="听到自己那么……放肆的笑声，", },
	[201098] = {id=201098, zh_CN="有点不好意思。", },
	[201099] = {id=201099, zh_CN="恭喜你解密成功。", },
	[201100] = {id=201100, zh_CN="作为奖励，带你看看这些‘证物’", },
	[201101] = {id=201101, zh_CN="背后的故事吧。", },
	[201102] = {id=201102, zh_CN="阿加莎热情地指着一个展柜。", },
	[201103] = {id=201103, zh_CN="看这个！", },
	[201104] = {id=201104, zh_CN="我第一次独立主持小型外交晚宴。", },
	[201105] = {id=201105, zh_CN="紧张得手心全是汗，", },
	[201106] = {id=201106, zh_CN="把演讲稿都捏成了卫生纸！", },
	[201107] = {id=201107, zh_CN="柜子里是那份皱巴巴的演讲稿。", },
	[201108] = {id=201108, zh_CN="还有这个，", },
	[201109] = {id=201109, zh_CN="学院时最好的朋友送的明信片。", },
	[201110] = {id=201110, zh_CN="风景照来自她家乡的海滩，", },
	[201111] = {id=201111, zh_CN="颜色都快晒没了……", },
	[201112] = {id=201112, zh_CN="这是张已经褪色的明信片。", },
	[201113] = {id=201113, zh_CN="这副旧手套，", },
	[201114] = {id=201114, zh_CN="是我偷偷跑去陆军训练营体验时磨破的，", },
	[201115] = {id=201115, zh_CN="被父亲发现后训了好久……", },
	[201116] = {id=201116, zh_CN="她掠过旁边一个展示着，", },
	[201117] = {id=201117, zh_CN="各种华丽珠宝设计图的册子，", },
	[201118] = {id=201118, zh_CN="其中一页描绘着象征王室联姻的传统冠冕。", },
	[201119] = {id=201119, zh_CN="传统冠冕。", },
	[201120] = {id=201120, zh_CN="小时候觉得这些像童话，", },
	[201121] = {id=201121, zh_CN="现在只觉得……脖子会断。", },
	[201122] = {id=201122, zh_CN="阿加莎走到一些泛黄的信件前，", },
	[201123] = {id=201123, zh_CN="她停下，指尖隔着玻璃，", },
	[201124] = {id=201124, zh_CN="轻轻描摹信件的轮廓。", },
	[201125] = {id=201125, zh_CN="这些信……是母亲年轻时，", },
	[201126] = {id=201126, zh_CN="也曾收到的让她轻松的信件。", },
	[201127] = {id=201127, zh_CN="父亲说，那些信是支撑母亲，", },
	[201128] = {id=201128, zh_CN="度过最初艰难时光的力量。", },
	[201129] = {id=201129, zh_CN="因为这样的文字……", },
	[201130] = {id=201130, zh_CN="我一直憧憬着父母那样……", },
	[201131] = {id=201131, zh_CN="最终相守。", },
	[201132] = {id=201132, zh_CN="抱歉，我聊的可能有点多了。", },
	[201133] = {id=201133, zh_CN="她拿起一个修复过的、", },
	[201134] = {id=201134, zh_CN="带有明显妖灵族风格的花瓶，", },
	[201135] = {id=201135, zh_CN="上面裂纹清晰可见。", },
	[201136] = {id=201136, zh_CN="看，象征和平的礼物。多么脆弱。", },
	[201137] = {id=201137, zh_CN="一次误解，一次冲突，", },
	[201138] = {id=201138, zh_CN="就能轻易打碎，", },
	[201139] = {id=201139, zh_CN="再高明的修复也掩盖不了裂痕。", },
	[201140] = {id=201140, zh_CN="气氛沉重，她强颜欢笑。", },
	[201141] = {id=201141, zh_CN="至少画画不需要考虑种族……", },
	[201142] = {id=201142, zh_CN="虽然画得也够糟。", },
	[201143] = {id=201143, zh_CN="阿加莎走到最重要的一个展柜，", },
	[201144] = {id=201144, zh_CN="里面整齐排列着，", },
	[201145] = {id=201145, zh_CN="她写过的所有信件。", },
	[201146] = {id=201146, zh_CN="里面也有你与她互通过的信件，", },
	[201147] = {id=201147, zh_CN="旁边贴着许多她手写的感想便签。", },
	[201148] = {id=201148, zh_CN="这些……就不用我多说了吧？", },
	[201149] = {id=201149, zh_CN="伙伴的珍贵墨宝！", },
	[201150] = {id=201150, zh_CN="她忽然撇到被你收起，", },
	[201151] = {id=201151, zh_CN="放在八音盒旁的照片。", },
	[201152] = {id=201152, zh_CN="这个就不要看！", },
	[201153] = {id=201153, zh_CN="那你还作为线索。", },
	[201154] = {id=201154, zh_CN="……", },
	[201155] = {id=201155, zh_CN="你在那幅色彩狂放，", },
	[201156] = {id=201156, zh_CN="笔触稚嫩的抽象涂鸦前停下。", },
	[201157] = {id=201157, zh_CN="这是……？", },
	[201158] = {id=201158, zh_CN="啊，这个！", },
	[201159] = {id=201159, zh_CN="是我十三岁时的“作品”，", },
	[201160] = {id=201160, zh_CN="心情特别烦躁时画的。", },
	[201161] = {id=201161, zh_CN="是不是以为是小孩子乱涂鸦？", },
	[201162] = {id=201162, zh_CN="才没有。", },
	[201163] = {id=201163, zh_CN="其实……画的是我当时，", },
	[201164] = {id=201164, zh_CN="一直不能完美地记住所有公主礼仪，", },
	[201165] = {id=201165, zh_CN="所有公主礼仪，", },
	[201166] = {id=201166, zh_CN="一气之下画的！", },
	[201167] = {id=201167, zh_CN="谢谢您愿意走进这里，", },
	[201168] = {id=201168, zh_CN="解开谜题，也……走进这些碎片。", },
	[201169] = {id=201169, zh_CN="分享这些……对我而言，", },
	[201170] = {id=201170, zh_CN="是前所未有的信任。", },
	[201171] = {id=201171, zh_CN="阿加莎伸出手。", },
	[201172] = {id=201172, zh_CN="希望下次，", },
	[201173] = {id=201173, zh_CN="这里还能有新的碎片与你分享。", },
	[201174] = {id=201174, zh_CN="再会了，我珍贵的朋友。", },
	[201175] = {id=201175, zh_CN="今天的谈话……请您务必保密。", },
	[201176] = {id=201176, zh_CN="她优雅地行礼，抬眼看向你，", },
	[201177] = {id=201177, zh_CN="带着一丝请求和深意。", },
	[201178] = {id=201178, zh_CN="我们可以更深入地……", },
	[201179] = {id=201179, zh_CN="聊聊您的见解？", },
	[201180] = {id=201180, zh_CN="我真的很好奇。", },
	[201181] = {id=201181, zh_CN="阿加莎微微侧身，", },
	[201182] = {id=201182, zh_CN="避开你关切的目光，", },
	[201183] = {id=201183, zh_CN="声音恢复了礼貌而疏离的距离感。", },
	[201184] = {id=201184, zh_CN="的距离感。", },
	[201185] = {id=201185, zh_CN="希望……希望您能理解。", },
	[201186] = {id=201186, zh_CN="方舟的立场和……历史的重量。", },
	[201187] = {id=201187, zh_CN="希望我们还有下次再会的机会。", },
	[201188] = {id=201188, zh_CN="你走到阿加莎身边，", },
	[201189] = {id=201189, zh_CN="递给她一份装订精美的文件，", },
	[201190] = {id=201190, zh_CN="声音低沉而清晰。", },
	[201191] = {id=201191, zh_CN="阿加莎，我想和你谈一件……", },
	[201192] = {id=201192, zh_CN="关于我们未来，", },
	[201193] = {id=201193, zh_CN="以及方舟未来的事。", },
	[201194] = {id=201194, zh_CN="阿加莎转过身，接过文件，", },
	[201195] = {id=201195, zh_CN="并未立刻翻开。", },
	[201196] = {id=201196, zh_CN="她雾紫色的眼眸直视着你，", },
	[201197] = {id=201197, zh_CN="带着审慎。", },
	[201198] = {id=201198, zh_CN="这么正式？", },
	[201199] = {id=201199, zh_CN="看来不是邀请我去新的艺术沙龙。", },
	[201200] = {id=201200, zh_CN="联姻。", },
	[201201] = {id=201201, zh_CN="我要向你，阿加莎，", },
	[201202] = {id=201202, zh_CN="方舟的第一顺位继承人，", },
	[201203] = {id=201203, zh_CN="提出联姻的请求。", },
	[201204] = {id=201204, zh_CN="阿加莎的手指瞬间收紧，", },
	[201205] = {id=201205, zh_CN="茶杯微微晃动。", },
	[201206] = {id=201206, zh_CN="我需要的是，", },
	[201207] = {id=201207, zh_CN="一个带给方舟推力的同伴。", },
	[201208] = {id=201208, zh_CN="抱歉，我不能……", },
	[201209] = {id=201209, zh_CN="门当户对。", },
	[201210] = {id=201210, zh_CN="我们现在就是门当户对。", },
	[201211] = {id=201211, zh_CN="我在星球的影响力与声望，", },
	[201212] = {id=201212, zh_CN="已经不比你低了。", },
	[201213] = {id=201213, zh_CN="并且，我作为室外星旅的背景，", },
	[201214] = {id=201214, zh_CN="可以为你吸引来独特资源网络，", },
	[201215] = {id=201215, zh_CN="完全可以覆盖方舟的需求。", },
	[201216] = {id=201216, zh_CN="我不是依附者，", },
	[201217] = {id=201217, zh_CN="而是强力的盟友和支柱。", },
	[201218] = {id=201218, zh_CN="明星效应。", },
	[201219] = {id=201219, zh_CN="我们两位明星联姻，", },
	[201220] = {id=201220, zh_CN="所能制造的巨大流量效应，", },
	[201221] = {id=201221, zh_CN="是不可估计的。", },
	[201222] = {id=201222, zh_CN="我的“天外”身份，", },
	[201223] = {id=201223, zh_CN="自带话题性和神秘感。", },
	[201224] = {id=201224, zh_CN="如果与方舟继承人联姻，", },
	[201225] = {id=201225, zh_CN="这将会是各大种族都瞩目的盛事。", },
	[201226] = {id=201226, zh_CN="这可以极大提升方舟的形象，", },
	[201227] = {id=201227, zh_CN="满足民众对王室新鲜活力的期待。", },
	[201228] = {id=201228, zh_CN="中立优势。", },
	[201229] = {id=201229, zh_CN="我的背景不隶属于任何传统势力，", },
	[201230] = {id=201230, zh_CN="或者你的对立种族。", },
	[201231] = {id=201231, zh_CN="是天然的有利于，", },
	[201232] = {id=201232, zh_CN="你巩固政权的优势。", },
	[201233] = {id=201233, zh_CN="能有效化解，", },
	[201234] = {id=201234, zh_CN="方舟民众对你身旁位置的争议。", },
	[201235] = {id=201235, zh_CN="你总不想内忧外患吧。", },
	[201236] = {id=201236, zh_CN="等待回应。", },
	[201237] = {id=201237, zh_CN="你站在原地，等待着阿加莎的回应。", },
	[201238] = {id=201238, zh_CN="阿加莎沉默了很久。", },
	[201239] = {id=201239, zh_CN="她终于翻开那份文件。", },
	[201240] = {id=201240, zh_CN="里面是详尽的分析报告。", },
	[201241] = {id=201241, zh_CN="以及一份对她约束相对宽松的，", },
	[201242] = {id=201242, zh_CN="协议草案。", },
	[201243] = {id=201243, zh_CN="许久……", },
	[201244] = {id=201244, zh_CN="阿加莎合上文件，抬起头。", },
	[201245] = {id=201245, zh_CN="你……准备得很充分。", },
	[201246] = {id=201246, zh_CN="这份协议，几乎是在给我铺一条，", },
	[201247] = {id=201247, zh_CN="相对自由的红毯。", },
	[201248] = {id=201248, zh_CN="但我需要为我的民众考虑，", },
	[201249] = {id=201249, zh_CN="我还需要更加能打动我的理由。", },
	[201250] = {id=201250, zh_CN="%PlayerName阁下，", },
	[201251] = {id=201251, zh_CN="你可以为方舟带来什么？", },
	[201252] = {id=201252, zh_CN="装可怜。", },
	[201253] = {id=201253, zh_CN="自由与合拍。这还不够吗？", },
	[201254] = {id=201254, zh_CN="阿加莎，我知道你渴望什么。", },
	[201255] = {id=201255, zh_CN="比起其他候选人、", },
	[201256] = {id=201256, zh_CN="盘根错节的家族势力、", },
	[201257] = {id=201257, zh_CN="以及对你一言一行的严苛审视……", },
	[201258] = {id=201258, zh_CN="……选择我，你受到的限制会少得多。", },
	[201259] = {id=201259, zh_CN="我在这里无亲无故，孑然一身。", },
	[201260] = {id=201260, zh_CN="某种意义上，你拿捏着我的一切。", },
	[201261] = {id=201261, zh_CN="而且，我们确实合拍。", },
	[201262] = {id=201262, zh_CN="不是吗？", },
	[201263] = {id=201263, zh_CN="可是我的婚姻注定带着政治目的。", },
	[201264] = {id=201264, zh_CN="我在向你提出！", },
	[201265] = {id=201265, zh_CN="我在向你提出共同缔造未来的邀请。", },
	[201266] = {id=201266, zh_CN="和你在一起，", },
	[201267] = {id=201267, zh_CN="无论是讨论艺术还是参加宴会，", },
	[201268] = {id=201268, zh_CN="我都觉得很有意思。", },
	[201269] = {id=201269, zh_CN="这种基础，", },
	[201270] = {id=201270, zh_CN="难道不比纯粹的政治筹码更可靠吗？", },
	[201271] = {id=201271, zh_CN="阿加莎……", },
	[201272] = {id=201272, zh_CN="我在向你，无论是你这个人，", },
	[201273] = {id=201273, zh_CN="还是背后的方舟，", },
	[201274] = {id=201274, zh_CN="提出一个共同缔造未来的邀请。", },
	[201275] = {id=201275, zh_CN="这份邀请里，有责任，有利益。", },
	[201276] = {id=201276, zh_CN="更有……我希望能与你发展下去的感情。", },
	[201277] = {id=201277, zh_CN="发展下去的感情。", },
	[201278] = {id=201278, zh_CN="阿加莎紧绷的肩膀微微放松。", },
	[201279] = {id=201279, zh_CN="一丝极其浅淡，", },
	[201280] = {id=201280, zh_CN="几乎不可见的红晕爬上耳尖。", },
	[201281] = {id=201281, zh_CN="……和你在一起，或许不那么累。", },
	[201282] = {id=201282, zh_CN="好。", },
	[201283] = {id=201283, zh_CN="这份联姻提议，我……初步接受。", },
	[201284] = {id=201284, zh_CN="拥抱！", },
	[201285] = {id=201285, zh_CN="阿加莎立刻抬手制止你的激动。", },
	[201286] = {id=201286, zh_CN="但是！有三个条件。", },
	[201287] = {id=201287, zh_CN="第一， 暂时绝对保密。", },
	[201288] = {id=201288, zh_CN="在时机成熟前，", },
	[201289] = {id=201289, zh_CN="不能让外界知道一丝风声。", },
	[201290] = {id=201290, zh_CN="我需要时间……也需要你证明更多。", },
	[201291] = {id=201291, zh_CN="点头——当然！", },
	[201292] = {id=201292, zh_CN="当然！", },
	[201293] = {id=201293, zh_CN="第二， 继续努力。", },
	[201294] = {id=201294, zh_CN="在感情上，", },
	[201295] = {id=201295, zh_CN="我需要看到你更深的投入和诚意。", },
	[201296] = {id=201296, zh_CN="能力上，", },
	[201297] = {id=201297, zh_CN="我需要你巩固并提升你承诺的影响力。", },
	[201298] = {id=201298, zh_CN="确保联姻公布时，", },
	[201299] = {id=201299, zh_CN="你的砝码足够重，", },
	[201300] = {id=201300, zh_CN="重到能堵住所有质疑的嘴。", },
	[201301] = {id=201301, zh_CN="乐意之至。", },
	[201302] = {id=201302, zh_CN="第三， 我需要一个观察期。", },
	[201303] = {id=201303, zh_CN="观察我们是否真的能……", },
	[201304] = {id=201304, zh_CN="在更大的压力和责任下，", },
	[201305] = {id=201305, zh_CN="将这份合拍转化为真正的……", },
	[201306] = {id=201306, zh_CN="盟友，乃至伴侣。", },
	[201307] = {id=201307, zh_CN="阿加莎伸出手……", },
	[201308] = {id=201308, zh_CN="%PlayerName阁下，别让我失望。", },
	[201309] = {id=201309, zh_CN="郑重握手！", },
	[201310] = {id=201310, zh_CN="你感受到她指尖微凉的坚定。", },
	[201311] = {id=201311, zh_CN="我绝不会让你失望的，阿加莎。", },
	[201312] = {id=201312, zh_CN="关于未来……或许下次，", },
	[201313] = {id=201313, zh_CN="猜猜我是谁？没错啦，就是莎莎，我发现我们已经很久没有互通信件了。\n 我想你了。\n 前段时间需要处理的工作很多，冷落了你对不起。我会好好经营我们之间的感情的，我保证。\n 写信想邀请你来我的“秘密花房”，我们很久没度过独属于我们的二人世界了。\n 你不会拒绝我的吧，等你。\n 我和“惊喜”在这里等待你的到来。\n ——莎", },
	[201314] = {id=201314, zh_CN="你带着信赴约阿加莎。", },
	[201315] = {id=201315, zh_CN="阿加莎的私人画室里，更显凌乱随性。", },
	[201316] = {id=201316, zh_CN="巨大的画布靠在墙边，", },
	[201317] = {id=201317, zh_CN="未完成的作品色彩大胆奔放。", },
	[201318] = {id=201318, zh_CN="地上散落着颜料管、", },
	[201319] = {id=201319, zh_CN="炭笔和沾满颜料的衬布；", },
	[201320] = {id=201320, zh_CN="书架塞满了画册、", },
	[201321] = {id=201321, zh_CN="乐谱和写满批注的小说……", },
	[201322] = {id=201322, zh_CN="空气中弥漫着松节油、", },
	[201323] = {id=201323, zh_CN="颜料和旧纸张的混合气息。", },
	[201324] = {id=201324, zh_CN="阿加莎背对着门，", },
	[201325] = {id=201325, zh_CN="雾紫色长发用一根炭笔随意挽起。", },
	[201326] = {id=201326, zh_CN="她穿着一件沾满各色颜料的旧帆布罩衫，", },
	[201327] = {id=201327, zh_CN="正专注地在一幅中型画布上涂抹。", },
	[201328] = {id=201328, zh_CN="阿加莎小姐，你的客人前来报到。", },
	[201329] = {id=201329, zh_CN="来得正好！快过来！", },
	[201330] = {id=201330, zh_CN="帮我看看这幅画……", },
	[201331] = {id=201331, zh_CN="我快要在色彩里失去平衡了！", },
	[201332] = {id=201332, zh_CN="她离远了些，", },
	[201333] = {id=201333, zh_CN="迅速观察后在画布抹上一笔浓烈的钴蓝。", },
	[201334] = {id=201334, zh_CN="走进观察画布。", },
	[201335] = {id=201335, zh_CN="画面主体是混乱奔放的彩色斑点和线条，", },
	[201336] = {id=201336, zh_CN="中心有一种奇异的、", },
	[201337] = {id=201337, zh_CN="螺旋上升的秩序感……", },
	[201338] = {id=201338, zh_CN="仿佛混沌中诞生的星系，", },
	[201339] = {id=201339, zh_CN="又像是解构的城市脉络。", },
	[201340] = {id=201340, zh_CN="你在……画星空吗？", },
	[201341] = {id=201341, zh_CN="哇哦，你在……画星空吗？", },
	[201342] = {id=201342, zh_CN="星际的能量感扑面而来！", },
	[201343] = {id=201343, zh_CN="看来我画的还不错。", },
	[201344] = {id=201344, zh_CN="塔希主义抽象表达？", },
	[201345] = {id=201345, zh_CN="塔希主义抽象表达艺术？", },
	[201346] = {id=201346, zh_CN="你知道塔希主义！！", },
	[201347] = {id=201347, zh_CN="你知道吗？", },
	[201348] = {id=201348, zh_CN="在抽象艺术表达里，", },
	[201349] = {id=201349, zh_CN="我最喜欢的就是塔希主义模糊的表现。", },
	[201350] = {id=201350, zh_CN="我认为这是最能隐藏，", },
	[201351] = {id=201351, zh_CN="和流露画家感情和心灵的画风。", },
	[201352] = {id=201352, zh_CN="你在解构秩序？", },
	[201353] = {id=201353, zh_CN="你在尝试……解构秩序？", },
	[201354] = {id=201354, zh_CN="或者说……在无序中寻找秩序的边界？", },
	[201355] = {id=201355, zh_CN="阿加莎倏然转身，", },
	[201356] = {id=201356, zh_CN="脸蛋沾上几点柠檬黄的颜料。", },
	[201357] = {id=201357, zh_CN="我其实一直都抓不住自己想要表达的东西。", },
	[201358] = {id=201358, zh_CN="你能理解真是太好了。", },
	[201359] = {id=201359, zh_CN="读心", },
	[201360] = {id=201360, zh_CN="他真的懂！那些我表达不出的东西……", },
	[201361] = {id=201361, zh_CN="这就是灵魂伴侣间的悸荡吗？", },
	[201362] = {id=201362, zh_CN="你好像错过了阿加莎的心声。", },
	[201363] = {id=201363, zh_CN="静静欣赏。", },
	[201364] = {id=201364, zh_CN="你静静地欣赏着阿加莎的画作。", },
	[201365] = {id=201365, zh_CN="结束对话。", },
	[201366] = {id=201366, zh_CN="你沉浸在阿加莎幽蓝色的艺术色彩中，", },
	[201367] = {id=201367, zh_CN="陪伴着阿加莎完成最后的几笔画作。", },
	[201368] = {id=201368, zh_CN="某天，", },
	[201369] = {id=201369, zh_CN="阿加莎罕见地没有邀约便登门拜访。", },
	[201370] = {id=201370, zh_CN="阿加莎犹豫了片刻，", },
	[201371] = {id=201371, zh_CN="将一本速写本递给你。", },
	[201372] = {id=201372, zh_CN="%PlayerName，今天冒昧拜访。", },
	[201373] = {id=201373, zh_CN="有些心里话我想要和你说。", },
	[201374] = {id=201374, zh_CN="认真聆听——我听。", },
	[201375] = {id=201375, zh_CN="你知道吗？", },
	[201376] = {id=201376, zh_CN="以前和别人聊我的画，", },
	[201377] = {id=201377, zh_CN="聊我的这些胡思乱想，", },
	[201378] = {id=201378, zh_CN="总是需要我解释很多……", },
	[201379] = {id=201379, zh_CN="从构图意图到色彩理论，", },
	[201380] = {id=201380, zh_CN="最后往往只能得到一个礼貌的微笑，", },
	[201381] = {id=201381, zh_CN="或者一句很有想法。", },
	[201382] = {id=201382, zh_CN="那种感觉就像……被毛玻璃笼罩，", },
	[201383] = {id=201383, zh_CN="只有自己的回声。", },
	[201384] = {id=201384, zh_CN="这种感觉很不好。", },
	[201385] = {id=201385, zh_CN="所以你将想法藏在谜题和物件里？", },
	[201386] = {id=201386, zh_CN="嗯。直到遇见你。", },
	[201387] = {id=201387, zh_CN="我对乐符，对涂鸦的渴望，", },
	[201388] = {id=201388, zh_CN="在和你的交流中，找到了出口。", },
	[201389] = {id=201389, zh_CN="那些流动，瞬间，难以言喻的共鸣……", },
	[201390] = {id=201390, zh_CN="就这样来到我的身边。", },
	[201391] = {id=201391, zh_CN="我并没有启发你什么，阿加莎。", },
	[201392] = {id=201392, zh_CN="你本身就是一个如此敏锐的观察者和表达者。", },
	[201393] = {id=201393, zh_CN="我只是一颗石子，投入你波澜的湖泊。", },
	[201394] = {id=201394, zh_CN="我的某句话只是一颗小石子，", },
	[201395] = {id=201395, zh_CN="恰好投入了你本就波澜壮阔的思想湖泊里，", },
	[201396] = {id=201396, zh_CN="激起了一点涟漪而已。", },
	[201397] = {id=201397, zh_CN="真正的力量，来自你自己。", },
	[201398] = {id=201398, zh_CN="她掀开蒙布，", },
	[201399] = {id=201399, zh_CN="露出里面一幅尺幅很小的画。", },
	[201400] = {id=201400, zh_CN="画风极其稚嫩抽象，", },
	[201401] = {id=201401, zh_CN="色彩混沌，笔触笨拙，像幼儿的涂鸦。", },
	[201402] = {id=201402, zh_CN="但能隐约看出一颗歪歪扭扭的星星。", },
	[201403] = {id=201403, zh_CN="这是我大概七岁时的作品。", },
	[201404] = {id=201404, zh_CN="小时候我总是羡慕星星，", },
	[201405] = {id=201405, zh_CN="觉得他们就是自由的象征，", },
	[201406] = {id=201406, zh_CN="是我当时所向往的。", },
	[201407] = {id=201407, zh_CN="它不算好看，技法也一塌糊涂。", },
	[201408] = {id=201408, zh_CN="但它代表了我艺术探索的起点……", },
	[201409] = {id=201409, zh_CN="代表了我内心最原始笨拙的呓语。", },
	[201410] = {id=201410, zh_CN="现在，我把它送给你。", },
	[201411] = {id=201411, zh_CN="%PlayerName，", },
	[201412] = {id=201412, zh_CN="你愿意，成为我的锚点之一吗？", },
	[201413] = {id=201413, zh_CN="我的荣幸。", },
	[201414] = {id=201414, zh_CN="这是我的荣幸，阿加莎。", },
	[201415] = {id=201415, zh_CN="像星星一样守护你。", },
	[201416] = {id=201416, zh_CN="我会像守护最珍贵的星辰一样，", },
	[201417] = {id=201417, zh_CN="守护这份友情。", },
	[201418] = {id=201418, zh_CN="灵魂在心口长存。", },
	[201419] = {id=201419, zh_CN="你指了指自己的心口。", },
	[201420] = {id=201420, zh_CN="你会在这里。", },
	[201421] = {id=201421, zh_CN="我会保护好你的。", },
	[201422] = {id=201422, zh_CN="你和阿加莎两只手紧紧握在一起，", },
	[201423] = {id=201423, zh_CN="两个人笑着瘫倒在地。", },
	[201424] = {id=201424, zh_CN="又是一天，", },
	[201425] = {id=201425, zh_CN="阿加莎与你独自约会的私人茶会……", },
	[201426] = {id=201426, zh_CN="还记得我们第一次正式见面吗？", },
	[201427] = {id=201427, zh_CN="在晚宴上，你把我介绍给大家。", },
	[201428] = {id=201428, zh_CN="怎么会忘？", },
	[201429] = {id=201429, zh_CN="那次晚宴成为了我们交往密切的开端。", },
	[201430] = {id=201430, zh_CN="没想到和公主成为了合拍信任的朋友。", },
	[201431] = {id=201431, zh_CN="合拍信任的朋友吗？", },
	[201432] = {id=201432, zh_CN="那……有没有可能，再进一步呢？", },
	[201433] = {id=201433, zh_CN="心跳漏拍——进一步？", },
	[201434] = {id=201434, zh_CN="阿加莎深吸一口气，", },
	[201435] = {id=201435, zh_CN="脸上泛起淡淡的红晕。", },
	[201436] = {id=201436, zh_CN="我们之间，早就超越了普通的友谊，", },
	[201437] = {id=201437, zh_CN="不是吗？", },
	[201438] = {id=201438, zh_CN="过去我们相知相识的日子里，", },
	[201439] = {id=201439, zh_CN="我看着你一步步成长，变得如此耀眼。", },
	[201440] = {id=201440, zh_CN="我们分享喜悦，分担忧愁，", },
	[201441] = {id=201441, zh_CN="彼此理解，互相支持……", },
	[201442] = {id=201442, zh_CN="我觉得你应该可以通过我的试用期了。", },
	[201443] = {id=201443, zh_CN="考察期总要有个尽头吧。", },
	[201444] = {id=201444, zh_CN="虽然你还算不上最佳的人选……", },
	[201445] = {id=201445, zh_CN="但连那些挑剔的王室顾问们，", },
	[201446] = {id=201446, zh_CN="也开始觉得你是个不错的人选了。", },
	[201447] = {id=201447, zh_CN="难道！阿加莎你……", },
	[201448] = {id=201448, zh_CN="既然我们感情这么好……", },
	[201449] = {id=201449, zh_CN="你的能力、公众形象、影响力无可挑剔……", },
	[201450] = {id=201450, zh_CN="她伸出手，", },
	[201451] = {id=201451, zh_CN="轻轻抚平你衣服上并不存在的褶皱，", },
	[201452] = {id=201452, zh_CN="动作带着亲昵。", },
	[201453] = {id=201453, zh_CN="我们有名无实的身份，", },
	[201454] = {id=201454, zh_CN="是不是可以考虑坐实一下了？", },
	[201455] = {id=201455, zh_CN="或许我们可以升级成，", },
	[201456] = {id=201456, zh_CN="有名有实的身份呢？", },
	[201457] = {id=201457, zh_CN="正式的培养感情，你觉得怎么样？", },
	[201458] = {id=201458, zh_CN="不是为了任何人，只为了我们自己，", },
	[201459] = {id=201459, zh_CN="为了这份……水到渠成的感情。", },
	[201460] = {id=201460, zh_CN="拥抱——这是我梦寐以求的事情！", },
	[201461] = {id=201461, zh_CN="真的吗！！这是我梦寐以求的事情！", },
	[201462] = {id=201462, zh_CN="这简直是世界上最好的提议！", },
	[201463] = {id=201463, zh_CN="我要变得更加有影响力，", },
	[201464] = {id=201464, zh_CN="我要堂堂正正站在你身边，", },
	[201465] = {id=201465, zh_CN="让所有人都无话可说！", },
	[201466] = {id=201466, zh_CN="傻瓜，", },
	[201467] = {id=201467, zh_CN="你早就可以堂堂正正站在我身边了。", },
	[201468] = {id=201468, zh_CN="现在，我们可以更理直气壮一点。", },
	[201469] = {id=201469, zh_CN="%PlayerName，", },
	[201470] = {id=201470, zh_CN="准备好迎接全新的身份和责任了吗？", },
	[201471] = {id=201471, zh_CN="吻了吻阿加莎的发顶。", },
	[201472] = {id=201472, zh_CN="只要女主角是你，我都奉陪到底。", },
	[201473] = {id=201473, zh_CN="阿加莎公主。", },
	[201474] = {id=201474, zh_CN="深夜，鸭湖城堡一处僻静的小露台。", },
	[201475] = {id=201475, zh_CN="阿加莎望着远处，", },
	[201476] = {id=201476, zh_CN="雾紫色的长发在微凉的夜风中轻轻飘动。", },
	[201477] = {id=201477, zh_CN="压抑的啜泣声在你的耳边萦绕。", },
	[201478] = {id=201478, zh_CN="搂住她——阿加莎？", },
	[201479] = {id=201479, zh_CN="你想要搂住她的手凝滞在半空，", },
	[201480] = {id=201480, zh_CN="望着她拒绝的背影，无法前进。", },
	[201481] = {id=201481, zh_CN="阿加莎身体猛地一僵，", },
	[201482] = {id=201482, zh_CN="迅速抬手抹去脸上的泪痕。", },
	[201483] = {id=201483, zh_CN="我没事。只是……看夜景。", },
	[201484] = {id=201484, zh_CN="你……怎么还没休息？", },
	[201485] = {id=201485, zh_CN="夜景很美，但看夜景的人不开心。", },
	[201486] = {id=201486, zh_CN="城堡的夜景很美，", },
	[201487] = {id=201487, zh_CN="但看夜景的人……似乎并不开心。", },
	[201488] = {id=201488, zh_CN="靠近——最近压力很大吗？", },
	[201489] = {id=201489, zh_CN="我们可以再偷偷出去……", },
	[201490] = {id=201490, zh_CN="阿加莎沉默了很久，", },
	[201491] = {id=201491, zh_CN="久到你以为她不会再开口。", },
	[201492] = {id=201492, zh_CN="他们说得对。", },
	[201493] = {id=201493, zh_CN="谁说得对？", },
	[201494] = {id=201494, zh_CN="阿加莎猛地转过身！", },
	[201495] = {id=201495, zh_CN="月光下，她脸上泪痕未干，眼眶通红。", },
	[201496] = {id=201496, zh_CN="我不该对你的身份抱有期待的。", },
	[201497] = {id=201497, zh_CN="就算你的灵魂不属于这里……", },
	[201498] = {id=201498, zh_CN="可是！你的样貌，你的尾巴，耳朵……", },
	[201499] = {id=201499, zh_CN="依旧属于妖灵族。", },
	[201500] = {id=201500, zh_CN="民众、媒体、敌对的势力！", },
	[201501] = {id=201501, zh_CN="他们是不会听你解释，听我解释的。", },
	[201502] = {id=201502, zh_CN="他们只会认为！！！", },
	[201503] = {id=201503, zh_CN="我！方舟继承人与宿敌之后交往过深，", },
	[201504] = {id=201504, zh_CN="有通敌之嫌。", },
	[201505] = {id=201505, zh_CN="我不该抱有侥幸心理，", },
	[201506] = {id=201506, zh_CN="把你当作回避的港湾的。", },
	[201507] = {id=201507, zh_CN="我不该任由我的心……", },
	[201508] = {id=201508, zh_CN="话音未落，她的泪水已经喷涌而出。", },
	[201509] = {id=201509, zh_CN="回想起交往时阿加莎总是紧张的状态。", },
	[201510] = {id=201510, zh_CN="所以，", },
	[201511] = {id=201511, zh_CN="你一直都处在紧张不安的情绪里吗？", },
	[201512] = {id=201512, zh_CN="阿加莎，你知道我不是你的敌人。", },
	[201513] = {id=201513, zh_CN="我知道！我当然知道！", },
	[201514] = {id=201514, zh_CN="我知道你有多好！", },
	[201515] = {id=201515, zh_CN="知道你的幽默、你的智慧、你的体贴！", },
	[201516] = {id=201516, zh_CN="我知道你会带我去逛节日集会，", },
	[201517] = {id=201517, zh_CN="会陪我解那些幼稚的谜题……", },
	[201518] = {id=201518, zh_CN="会带我体验别人的平凡，", },
	[201519] = {id=201519, zh_CN="但对我却不普通的事物！", },
	[201520] = {id=201520, zh_CN="可是……可是我是方舟公主，", },
	[201521] = {id=201521, zh_CN="我不是普通民众。", },
	[201522] = {id=201522, zh_CN="我知道，", },
	[201523] = {id=201523, zh_CN="把与你无关的仇恨强加在你身上很自私。", },
	[201524] = {id=201524, zh_CN="可是你外表所属于的种族在几百年前侵略，", },
	[201525] = {id=201525, zh_CN="屠戮着我的先祖！", },
	[201526] = {id=201526, zh_CN="我的子民看着我！", },
	[201527] = {id=201527, zh_CN="他们的恨意、他们的恐惧……", },
	[201528] = {id=201528, zh_CN="像冰冷的锁链，", },
	[201529] = {id=201529, zh_CN="每时每刻都勒着我的脖子！", },
	[201530] = {id=201530, zh_CN="每一次和你见面，每一次对你微笑……", },
	[201531] = {id=201531, zh_CN="我都要面对内心的叩问和周围无声的谴责！", },
	[201532] = {id=201532, zh_CN="你知道那种感觉吗？你知道吗？", },
	[201533] = {id=201533, zh_CN="你听着她剖心泣血的哭诉，", },
	[201534] = {id=201534, zh_CN="一股巨大的酸楚和无力感淹没了你。", },
	[201535] = {id=201535, zh_CN="阿加莎……", },
	[201536] = {id=201536, zh_CN="不！你不知道！你怎么会知道？！", },
	[201537] = {id=201537, zh_CN="你是一阵自由的风，", },
	[201538] = {id=201538, zh_CN="吹过我们的历史，", },
	[201539] = {id=201539, zh_CN="却感受不到那沉积了百年的血腥和沉重！", },
	[201540] = {id=201540, zh_CN="你不知道每次接触你，", },
	[201541] = {id=201541, zh_CN="我内心要经历怎样的撕裂！", },
	[201542] = {id=201542, zh_CN="阿加莎靠着冰冷的栏杆滑坐在地上，", },
	[201543] = {id=201543, zh_CN="将脸深埋进膝盖，", },
	[201544] = {id=201544, zh_CN="瘦弱的肩膀剧烈颤抖着，", },
	[201545] = {id=201545, zh_CN="发出压抑的呜咽。", },
	[201546] = {id=201546, zh_CN="它们在我脑子里打架！快把我逼疯了！", },
	[201547] = {id=201547, zh_CN="我好累，我真的好累……", },
	[201548] = {id=201548, zh_CN="我只是想小小的逃避一下。", },
	[201549] = {id=201549, zh_CN="我只是，只是不小心喜欢你。", },
	[201550] = {id=201550, zh_CN="为什么这么难……", },
	[201551] = {id=201551, zh_CN="你看着蜷缩在地上、", },
	[201552] = {id=201552, zh_CN="哭得像个迷路孩子的阿加莎，", },
	[201553] = {id=201553, zh_CN="心脏疼得像被狠狠攥住。", },
	[201554] = {id=201554, zh_CN="所有想辩解的话，", },
	[201555] = {id=201555, zh_CN="所有想质问“为什么不告诉我”的冲动，", },
	[201556] = {id=201556, zh_CN="都堵在喉咙里，化为一片苦涩的沉默。", },
	[201557] = {id=201557, zh_CN="理解她。", },
	[201558] = {id=201558, zh_CN="你忽然理解了她背负的枷锁有多沉重，", },
	[201559] = {id=201559, zh_CN="理解了她笑容背后的如履薄冰。", },
	[201560] = {id=201560, zh_CN="怨恨她的隐瞒？", },
	[201561] = {id=201561, zh_CN="怨恨她的隐瞒？", },
	[201562] = {id=201562, zh_CN="不，你此刻只有无尽的心疼和自责……", },
	[201563] = {id=201563, zh_CN="为她承受的痛苦，为自己无知带来的伤害。", },
	[201564] = {id=201564, zh_CN="深深自责。", },
	[201565] = {id=201565, zh_CN="心痛，安抚她。", },
	[201566] = {id=201566, zh_CN="你缓缓蹲下身，默默陪伴她。", },
	[201567] = {id=201567, zh_CN="阿加莎……看着我。", },
	[201568] = {id=201568, zh_CN="阿加莎低着头，哭声渐弱，", },
	[201569] = {id=201569, zh_CN="只剩下压抑的抽泣。", },
	[201570] = {id=201570, zh_CN="对不起。", },
	[201571] = {id=201571, zh_CN="对不起……", },
	[201572] = {id=201572, zh_CN="为我让你独自承受这一切而道歉。", },
	[201573] = {id=201573, zh_CN="为我无法感同身受那份历史的沉重而道歉。", },
	[201574] = {id=201574, zh_CN="是，我是不懂你的天外之风。", },
	[201575] = {id=201575, zh_CN="你说得对，我是天外之风。", },
	[201576] = {id=201576, zh_CN="我不懂你们的血仇，但我懂你现在的痛。", },
	[201577] = {id=201577, zh_CN="恨我？怨我？或者恨这命运？", },
	[201578] = {id=201578, zh_CN="都可以。", },
	[201579] = {id=201579, zh_CN="承受你现在的情绪，是我应该，", },
	[201580] = {id=201580, zh_CN="也必须该做的。", },
	[201581] = {id=201581, zh_CN="无论如何，请别推开我。", },
	[201582] = {id=201582, zh_CN="无论如何，请别推开我。", },
	[201583] = {id=201583, zh_CN="让我陪你一起站在悬崖边，好吗？", },
	[201584] = {id=201584, zh_CN="等待。", },
	[201585] = {id=201585, zh_CN="你安静地盯着阿加莎，", },
	[201586] = {id=201586, zh_CN="等她主动抬头面对你。", },
	[201587] = {id=201587, zh_CN="阿加莎缓缓抬起头，泪眼婆娑地看着你。", },
	[201588] = {id=201588, zh_CN="张开双臂——让我们拥抱吧。", },
	[201589] = {id=201589, zh_CN="如果相爱无能，如果怨恨无力……", },
	[201590] = {id=201590, zh_CN="那就拥抱吧。", },
	[201591] = {id=201591, zh_CN="请拥抱我吧。", },
	[201592] = {id=201592, zh_CN="我在这里，阿加莎。", },
	[201593] = {id=201593, zh_CN="拥抱我吧。", },
	[201594] = {id=201594, zh_CN="漫长的几秒钟里，夜风似乎都静止了。", },
	[201595] = {id=201595, zh_CN="阿加莎看着你敞开的怀抱，", },
	[201596] = {id=201596, zh_CN="那里没有指责，没有索求，", },
	[201597] = {id=201597, zh_CN="只有无声的接纳和支撑。", },
	[201598] = {id=201598, zh_CN="她眼中翻涌着激烈的挣扎、恐惧……", },
	[201599] = {id=201599, zh_CN="最终，那积累到无法承受的疲惫和渴望，", },
	[201600] = {id=201600, zh_CN="压倒了最后的枷锁。", },
	[201601] = {id=201601, zh_CN="阿加莎呜咽一声，", },
	[201602] = {id=201602, zh_CN="像离弦的箭般扑进了你的怀里！", },
	[201603] = {id=201603, zh_CN="所有的委屈、恐惧、痛苦和挣扎，", },
	[201604] = {id=201604, zh_CN="都随着泪水汹涌而出。", },
	[201605] = {id=201605, zh_CN="呜……为什么……", },
	[201606] = {id=201606, zh_CN="为什么是你……", },
	[201607] = {id=201607, zh_CN="为什么偏偏是你……", },
	[201608] = {id=201608, zh_CN="我讨厌你。", },
	[201609] = {id=201609, zh_CN="我不会再让你独自承担这份重量。", },
	[201610] = {id=201610, zh_CN="哭吧，哭出来就好。", },
	[201611] = {id=201611, zh_CN="宿敌也好，祸端也罢。", },
	[201612] = {id=201612, zh_CN="我就在这里，抱着你，任你处置。", },
	[201613] = {id=201613, zh_CN="谁也不能再让你独自承担这份重量。", },
	[201614] = {id=201614, zh_CN="我保证。", },
	[201615] = {id=201615, zh_CN="阿加莎的邀请信", },
	[201616] = {id=201616, zh_CN="母亲", },
	[201617] = {id=201617, zh_CN="小男孩", },
	[201618] = {id=201618, zh_CN="一对母子", },
	[201619] = {id=201619, zh_CN="侍从", },
	[201620] = {id=201620, zh_CN="妖灵族酋长", },
	[201621] = {id=201621, zh_CN="精灵长老", },
	[201622] = {id=201622, zh_CN="如何读心？", },
	[210000] = {id=210000, zh_CN="助理", },
	[210001] = {id=210001, zh_CN="记者", },
	[210002] = {id=210002, zh_CN="董事", },
	[210003] = {id=210003, zh_CN="警察", },
	[210004] = {id=210004, zh_CN="嘿，%PlayerName，有没有兴趣看看月影商会的期货？", },
	[210005] = {id=210005, zh_CN="优惠力度包你满意。", },
	[210006] = {id=210006, zh_CN="【珍品之夜】", },
	[210007] = {id=210007, zh_CN="【经济漩涡之涟漪】", },
	[210008] = {id=210008, zh_CN="【坦白与道歉】", },
	[210009] = {id=210009, zh_CN="【利益捆绑的“友情”】", },
	[210010] = {id=210010, zh_CN="【恋爱开放公式】", },
	[210011] = {id=210011, zh_CN="【办公室恋情日常】", },
	[210012] = {id=210012, zh_CN="【无需标签的我们】", },
	[210013] = {id=210013, zh_CN="结束对话", },
	[210014] = {id=210014, zh_CN="滴——", },
	[210015] = {id=210015, zh_CN="诚邀独一无二的贵宾—%PlayerName", },
	[210016] = {id=210016, zh_CN="莅临月影商会新季度珍品之夜。期待与您共鉴星河瑰宝。", },
	[210017] = {id=210017, zh_CN="——奥黛特·德·月影", },
	[210018] = {id=210018, zh_CN="拍卖会当天，你来到商会。", },
	[210019] = {id=210019, zh_CN="商会阶梯之上，", },
	[210020] = {id=210020, zh_CN="一位身着黑银色礼服裙的女性优雅走下。", },
	[210021] = {id=210021, zh_CN="正是奥黛特·德·月影。", },
	[210022] = {id=210022, zh_CN="%PlayerName，你来了。", },
	[210023] = {id=210023, zh_CN="我就知道，这份‘独一无二’的邀请函，不会落空。", },
	[210024] = {id=210024, zh_CN="久闻月影商会大名。", },
	[210025] = {id=210025, zh_CN="久闻月影商会的大名，", },
	[210026] = {id=210026, zh_CN="有幸受邀，当然要来一览风采。", },
	[210027] = {id=210027, zh_CN="那预祝今夜月影拍卖会让你得偿所愿。", },
	[210028] = {id=210028, zh_CN="感谢邀请。", },
	[210029] = {id=210029, zh_CN="感谢奥黛特小姐的邀请函。", },
	[210030] = {id=210030, zh_CN="不客气。", },
	[210031] = {id=210031, zh_CN="邀请有品位的看客共赏星际奇物，", },
	[210032] = {id=210032, zh_CN="是我们应该做的。", },
	[210033] = {id=210033, zh_CN="沉默。", },
	[210034] = {id=210034, zh_CN="……", },
	[210035] = {id=210035, zh_CN="奥黛特与你僵持在原地，", },
	[210036] = {id=210036, zh_CN="隐隐间有什么气场在相互挤压撕斗，", },
	[210037] = {id=210037, zh_CN="谁也不愿落下风。", },
	[210038] = {id=210038, zh_CN="欢迎来到月影商会的珍品之夜。", },
	[210039] = {id=210039, zh_CN="我带你进去吧。", },
	[210040] = {id=210040, zh_CN="好。", },
	[210041] = {id=210041, zh_CN="奥黛特带领着你，往商会里走去。", },
	[210042] = {id=210042, zh_CN="旅途顺利吗？", },
	[210043] = {id=210043, zh_CN="顺利。", },
	[210044] = {id=210044, zh_CN="希望忽如其来的邀约，", },
	[210045] = {id=210045, zh_CN="没让你这位天外来客感到困扰。", },
	[210046] = {id=210046, zh_CN="走入商会的拍卖场，", },
	[210047] = {id=210047, zh_CN="奥黛特优雅地侧身，示意你跟随她。", },
	[210048] = {id=210048, zh_CN="你的座位在VIP区，视野最佳。", },
	[210049] = {id=210049, zh_CN="请随我来。", },
	[210050] = {id=210050, zh_CN="步入恢弘的拍卖主厅，", },
	[210051] = {id=210051, zh_CN="璀璨的水晶灯下，", },
	[210052] = {id=210052, zh_CN="展台上一件件的拍品熠熠生辉。", },
	[210053] = {id=210053, zh_CN="被幽静的独立展区吸引。", },
	[210054] = {id=210054, zh_CN="那里展示着几株形态奇异的植物标本。", },
	[210055] = {id=210055, zh_CN="其独特的外表和展台上的“未探索星域”标签，", },
	[210056] = {id=210056, zh_CN="吸引着几位收藏家与植物学家驻足。", },
	[210057] = {id=210057, zh_CN="穿过展区与看台，一路走进包间。", },
	[210058] = {id=210058, zh_CN="%PlayerName，你的座位就在这里。", },
	[210059] = {id=210059, zh_CN="我还要去准备接下来的流程，", },
	[210060] = {id=210060, zh_CN="先失陪了。", },
	[210061] = {id=210061, zh_CN="望着朝你颔首的奥黛特，", },
	[210062] = {id=210062, zh_CN="月影商会网罗星际，或许接触过情绪花种。", },
	[210063] = {id=210063, zh_CN="要向奥黛特询问情绪花种的售卖吗？", },
	[210064] = {id=210064, zh_CN="直白询问。", },
	[210065] = {id=210065, zh_CN="奥黛特小姐，实不相瞒。", },
	[210066] = {id=210066, zh_CN="我一直在寻找一种以可以承载情绪的花种。", },
	[210067] = {id=210067, zh_CN="不知您是否有相关消息？", },
	[210068] = {id=210068, zh_CN="旁敲侧击。", },
	[210069] = {id=210069, zh_CN="听闻月影商会总能网罗宇宙奇珍。", },
	[210070] = {id=210070, zh_CN="不知今晚的拍品是什么主题的？", },
	[210071] = {id=210071, zh_CN="科技？人文？或是感性……", },
	[210072] = {id=210072, zh_CN="铺垫透露。", },
	[210073] = {id=210073, zh_CN="奥黛特小姐的收藏眼光一向独到。", },
	[210074] = {id=210074, zh_CN="今晚的焦点拍品想必令人期待。", },
	[210075] = {id=210075, zh_CN="比如……一些能映射内心的稀有植物？", },
	[210076] = {id=210076, zh_CN="暂时不问。", },
	[210077] = {id=210077, zh_CN="谢谢您的安排。", },
	[210078] = {id=210078, zh_CN="我很期待今晚的拍卖。", },
	[210079] = {id=210079, zh_CN="祝你在月影商会度过愉快的一夜。", },
	[210080] = {id=210080, zh_CN="拍卖即将开始。", },
	[210081] = {id=210081, zh_CN="亲爱的，你在寻找的花种会是绣球吗？", },
	[210082] = {id=210082, zh_CN="你见过！", },
	[210083] = {id=210083, zh_CN="那真是一个令人着迷的奇物。", },
	[210084] = {id=210084, zh_CN="她的唇瓣蹭过你的侧脸。", },
	[210085] = {id=210085, zh_CN="请保持期待吧。", },
	[210086] = {id=210086, zh_CN="今晚……或许会有惊喜？", },
	[210087] = {id=210087, zh_CN="哦？看来你有特定的目标。", },
	[210088] = {id=210088, zh_CN="商会的拍品目录想必您已看过。", },
	[210089] = {id=210089, zh_CN="请保持期待吧。", },
	[210090] = {id=210090, zh_CN="能否得到心仪的目标……", },
	[210091] = {id=210091, zh_CN="看缘分，也看实力。", },
	[210092] = {id=210092, zh_CN="亲爱的，你不妨多关注目录上的珍品。", },
	[210093] = {id=210093, zh_CN="只要是有明确价值的东西。", },
	[210094] = {id=210094, zh_CN="月影商会来者不拒。", },
	[210095] = {id=210095, zh_CN="奥黛特转身缓步离开。", },
	[210096] = {id=210096, zh_CN="一盏盏聚光灯聚焦在奥黛特身上，", },
	[210097] = {id=210097, zh_CN="托送着她走向拍卖台。", },
	[210098] = {id=210098, zh_CN="瞬息之间，", },
	[210099] = {id=210099, zh_CN="奥黛特·德·月影，", },
	[210100] = {id=210100, zh_CN="化身成这场拍卖会的庄家，", },
	[210101] = {id=210101, zh_CN="站在欲望堆积的高塔上。", },
	[210102] = {id=210102, zh_CN="“珍品之夜”开始了……", },
	[210103] = {id=210103, zh_CN="诸位尊贵的来宾！", },
	[210104] = {id=210104, zh_CN="星际的探索者、收藏家！", },
	[210105] = {id=210105, zh_CN="慧眼独具的投资者们！", },
	[210106] = {id=210106, zh_CN="欢迎莅临月影商会新季度珍品之夜！", },
	[210107] = {id=210107, zh_CN="今夜，我们将共同开启一场穿越星际、触及非凡的寻宝之旅！", },
	[210108] = {id=210108, zh_CN="今晚，我们不仅汇聚了来自星海各处的奇珍名品……", },
	[210109] = {id=210109, zh_CN="更有幸迎来了一位极其特殊的贵宾！", },
	[210110] = {id=210110, zh_CN="奥黛特抬起手臂，全场目光瞬间聚焦在你身上！", },
	[210111] = {id=210111, zh_CN="一位真正来自星空之外的旅行者——%PlayerName！", },
	[210112] = {id=210112, zh_CN="一束舞台光随着奥黛特逐渐激昂的声音，朝你射来！", },
	[210113] = {id=210113, zh_CN="将你的身影完全照亮。", },
	[210114] = {id=210114, zh_CN="倏然，拍卖舞台陷入黑暗。", },
	[210115] = {id=210115, zh_CN="整个商会厅，只剩下你脚下的一隅方寸。", },
	[210116] = {id=210116, zh_CN="反客为主——过誉了。", },
	[210117] = {id=210117, zh_CN="奥黛特小姐过誉了。", },
	[210118] = {id=210118, zh_CN="宇宙之大，无奇不有。", },
	[210119] = {id=210119, zh_CN="如果没有奥黛特小姐您这位领航员的邀约，", },
	[210120] = {id=210120, zh_CN="我也无法驻足此处。", },
	[210121] = {id=210121, zh_CN="领航员，我喜欢这个称呼。", },
	[210122] = {id=210122, zh_CN="维持镇定——感谢盛赞。", },
	[210123] = {id=210123, zh_CN="你在注视下有些紧张，但努力维持镇定，站起身来，略显僵硬地点头致意。", },
	[210124] = {id=210124, zh_CN="呃……", },
	[210125] = {id=210125, zh_CN="感谢奥黛特小姐的盛赞。", },
	[210126] = {id=210126, zh_CN="月影商会也是宇宙闻名。", },
	[210127] = {id=210127, zh_CN="感谢您的认可！", },
	[210128] = {id=210128, zh_CN="这正是我们不懈追求的目标。", },
	[210129] = {id=210129, zh_CN="迅速站起，手足无措。", },
	[210130] = {id=210130, zh_CN="你满脸通红，张了张嘴却什么也没说出来。", },
	[210131] = {id=210131, zh_CN="请给我们的贵宾一点掌声，他有些害羞。", },
	[210132] = {id=210132, zh_CN="谢谢，谢谢。", },
	[210133] = {id=210133, zh_CN="你捂着脸，在雷鸣掌声中迅速坐回座位。", },
	[210134] = {id=210134, zh_CN="我们的贵客已被今晚的珍品震撼得一时失语了！", },
	[210135] = {id=210135, zh_CN="你身上炙热的灼烧感消失……", },
	[210136] = {id=210136, zh_CN="在场的看客如引力牵动般转头望向拍卖台上的奥黛特。", },
	[210137] = {id=210137, zh_CN="她像是火焰，星点火光便带起全场热潮。", },
	[210138] = {id=210138, zh_CN="试想，连这样一位见惯了宇宙奇观的旅人，", },
	[210139] = {id=210139, zh_CN="都专程为我们的珍品之夜而来……", },
	[210140] = {id=210140, zh_CN="这便是对我们月影商会本身，所收揽的奇物，", },
	[210141] = {id=210141, zh_CN="以及在座各位毒辣眼光的最高认可吗？", },
	[210142] = {id=210142, zh_CN="今晚的每一件拍品，", },
	[210143] = {id=210143, zh_CN="都蕴含着足以打动星辰的非凡价值！", },
	[210144] = {id=210144, zh_CN="敬请期待吧！", },
	[210145] = {id=210145, zh_CN="一个令人印象深刻的开场。", },
	[210146] = {id=210146, zh_CN="我被奥黛特摆了一道？", },
	[210147] = {id=210147, zh_CN="虽然被奥黛特摆了一道……", },
	[210148] = {id=210148, zh_CN="气愤填胸——可恶！", },
	[210149] = {id=210149, zh_CN="可恶！", },
	[210150] = {id=210150, zh_CN="果然是我！魅力真大！", },
	[210151] = {id=210151, zh_CN="啊，果然是我呢！", },
	[210152] = {id=210152, zh_CN="魅力前所未有的大！", },
	[210153] = {id=210153, zh_CN="吸取教训——下次绝不会让她得逞！", },
	[210154] = {id=210154, zh_CN="下次绝不会再落入奥黛特的圈套了！", },
	[210155] = {id=210155, zh_CN="拍卖会在奥黛特的主持下有条不紊地进行着……", },
	[210156] = {id=210156, zh_CN="拍卖会逐渐渐入尾声。", },
	[210157] = {id=210157, zh_CN="一位气质干练的助理悄然走到你身边。", },
	[210158] = {id=210158, zh_CN="客人，奥黛特女士请您拍卖结束后，移步她的私人办公室一叙。", },
	[210159] = {id=210159, zh_CN="她说，有您会感兴趣的东西。", },
	[210160] = {id=210160, zh_CN="好的。", },
	[210161] = {id=210161, zh_CN="你随指引来到在奥黛特办公室前。", },
	[210162] = {id=210162, zh_CN="敲门。", },
	[210163] = {id=210163, zh_CN="进。", },
	[210164] = {id=210164, zh_CN="请坐。想喝点什么？", },
	[210165] = {id=210165, zh_CN="蜜露花茶，还是啵啵冻？", },
	[210166] = {id=210166, zh_CN="水。", },
	[210167] = {id=210167, zh_CN="水就可以。", },
	[210168] = {id=210168, zh_CN="奥黛特亲自为你倒了一杯水，放在桌上。", },
	[210169] = {id=210169, zh_CN="蜜露花茶。", },
	[210170] = {id=210170, zh_CN="一杯蜜露花茶，谢谢。", },
	[210171] = {id=210171, zh_CN="奥黛特亲自为你倒了一杯蜜露花茶，放在桌上。", },
	[210172] = {id=210172, zh_CN="夏日啵啵冻。", },
	[210173] = {id=210173, zh_CN="我要夏日啵啵冻。", },
	[210174] = {id=210174, zh_CN="奥黛特亲自为你倒了一杯夏日啵啵冻，放在桌上。", },
	[210175] = {id=210175, zh_CN="亲爱的，你刚才在台上的表现真是精彩绝伦。", },
	[210176] = {id=210176, zh_CN="感谢你配合我为拍卖造势。", },
	[210177] = {id=210177, zh_CN="这份人情，我奥黛特记下了。", },
	[210178] = {id=210178, zh_CN="请坐。感谢您今晚的出席。", },
	[210179] = {id=210179, zh_CN="特别是在台上的配合。", },
	[210180] = {id=210180, zh_CN="你对情绪花种很感兴趣？", },
	[210181] = {id=210181, zh_CN="作为回报，我们可以聊聊。", },
	[210182] = {id=210182, zh_CN="咳，奥黛特小姐有见过情绪花种吗？", },
	[210183] = {id=210183, zh_CN="当然。", },
	[210184] = {id=210184, zh_CN="奥黛特笑着取出恒温盒，将其缓缓打开。", },
	[210185] = {id=210185, zh_CN="里面静静躺着一枚雾蓝色，萦绕着雾气的绣球花种。", },
	[210186] = {id=210186, zh_CN="她身体微微前倾。", },
	[210187] = {id=210187, zh_CN="我知道你在找什么。", },
	[210188] = {id=210188, zh_CN="这是你今天参加拍卖的原因，对吗？", },
	[210189] = {id=210189, zh_CN="是的，奥黛特小姐。", },
	[210190] = {id=210190, zh_CN="你能告诉我它的来历吗，奥黛特小姐？", },
	[210191] = {id=210191, zh_CN="这颗情绪种子，", },
	[210192] = {id=210192, zh_CN="它……来自我。", },
	[210193] = {id=210193, zh_CN="一场差点泯灭商会的风暴。", },
	[210194] = {id=210194, zh_CN="对手联合围剿，舆论汹汹。", },
	[210195] = {id=210195, zh_CN="为了保全月影的根基，我做出选择。", },
	[210196] = {id=210196, zh_CN="一些看来冷酷、自私、落井下石的选择。", },
	[210197] = {id=210197, zh_CN="奥黛特捏起花种。", },
	[210198] = {id=210198, zh_CN="它就是此时从我身体里分离出来。", },
	[210199] = {id=210199, zh_CN="我一直小心保管，直到……", },
	[210200] = {id=210200, zh_CN="等来了值得交易的收藏家。", },
	[210201] = {id=210201, zh_CN="报价吧。", },
	[210202] = {id=210202, zh_CN="你的价值比你想象中的还要大。", },
	[210203] = {id=210203, zh_CN="我该承认，我利用了你。", },
	[210204] = {id=210204, zh_CN="但你也给了我足够的惊喜。", },
	[210205] = {id=210205, zh_CN="我很乐意为你量身打造一场拍卖。", },
	[210206] = {id=210206, zh_CN="它会让你的名声响彻星际。如何？", },
	[210207] = {id=210207, zh_CN="她大方地将种子盒推到你面前。", },
	[210208] = {id=210208, zh_CN="至于这颗种子……", },
	[210209] = {id=210209, zh_CN="既可以作为我还你的人情，", },
	[210210] = {id=210210, zh_CN="当然也可以是我们合作的信物。", },
	[210211] = {id=210211, zh_CN="接受种子。", },
	[210212] = {id=210212, zh_CN="种子我收下。", },
	[210213] = {id=210213, zh_CN="至于拍卖…以后再说。", },
	[210214] = {id=210214, zh_CN="好。", },
	[210215] = {id=210215, zh_CN="购买种子。", },
	[210216] = {id=210216, zh_CN="人情与交易不能混为一谈。", },
	[210217] = {id=210217, zh_CN="种子我按市价买。", },
	[210218] = {id=210218, zh_CN="哦？", },
	[210219] = {id=210219, zh_CN="那就给你一个VIP折扣吧。", },
	[210220] = {id=210220, zh_CN="1000金币。", },
	[210221] = {id=210221, zh_CN="可以先赊账，这次不要拒绝了。", },
	[210222] = {id=210222, zh_CN="谢谢。", },
	[210223] = {id=210223, zh_CN="奥黛特取出恒温盒，将其缓缓打开。", },
	[210224] = {id=210224, zh_CN="里面静静躺着一枚雾蓝色，萦绕着雾气的绣球花种。", },
	[210225] = {id=210225, zh_CN="一颗凝聚了“自私”情绪的绣球花种，", },
	[210226] = {id=210226, zh_CN="这是你今天参加拍卖的原因，对吗？", },
	[210227] = {id=210227, zh_CN="是的，奥黛特小姐。", },
	[210228] = {id=210228, zh_CN="可以告诉我它的来历吗？", },
	[210229] = {id=210229, zh_CN="它确实在我这里保管了一段时间。", },
	[210230] = {id=210230, zh_CN="至于来源，你只需知道它货真价实，且来源明确。", },
	[210231] = {id=210231, zh_CN="报价吧。", },
	[210232] = {id=210232, zh_CN="我该承认，我利用了你。", },
	[210233] = {id=210233, zh_CN="她大方地将种子盒推到你面前。", },
	[210234] = {id=210234, zh_CN="这颗种子，作为我还你的人情。", },
	[210235] = {id=210235, zh_CN="接受种子", },
	[210236] = {id=210236, zh_CN="种子我收下。", },
	[210237] = {id=210237, zh_CN="谢谢。", },
	[210238] = {id=210238, zh_CN="不客气。", },
	[210239] = {id=210239, zh_CN="购买种子", },
	[210240] = {id=210240, zh_CN="人情与交易不能混为一谈。", },
	[210241] = {id=210241, zh_CN="种子我按市价买。", },
	[210242] = {id=210242, zh_CN="哦？", },
	[210243] = {id=210243, zh_CN="那就给你一个VIP折扣吧。", },
	[210244] = {id=210244, zh_CN="1000金币。", },
	[210245] = {id=210245, zh_CN="可以先赊账，这次不要拒绝了。", },
	[210246] = {id=210246, zh_CN="谢谢。", },
	[210247] = {id=210247, zh_CN="月影商会的大门永远对有价值的客人敞开。", },
	[210248] = {id=210248, zh_CN="获取任何讯息或交易稀有珍品，", },
	[210249] = {id=210249, zh_CN="可以随时找我。", },
	[210250] = {id=210250, zh_CN="带上满意的价码，月影商会将为你办成任何事。", },
	[210251] = {id=210251, zh_CN="她优雅地做了个请的手势，送客意味明显。", },
	[210252] = {id=210252, zh_CN="期待我们下次的交易或合作。", },
	[210253] = {id=210253, zh_CN="再会。", },
	[210254] = {id=210254, zh_CN="再会，奥黛特小姐。", },
	[210255] = {id=210255, zh_CN="你离开奥黛特的办公室。", },
	[210256] = {id=210256, zh_CN="奥黛特·德·月影，", },
	[210257] = {id=210257, zh_CN="人心和秘密，都被她放在价值天平上衡量。", },
	[210258] = {id=210258, zh_CN="商会外，蜂拥而至的记者将总部围得水泄不通。", },
	[210259] = {id=210259, zh_CN="月影商会深陷惊天赝品丑闻！", },
	[210260] = {id=210260, zh_CN="会长奥黛特·月影涉嫌欺诈被捕！", },
	[210261] = {id=210261, zh_CN="拍卖会疑为惊天骗局！", },
	[210262] = {id=210262, zh_CN="你刚踏上商会前的平台，", },
	[210263] = {id=210263, zh_CN="看！是%PlayerName！", },
	[210264] = {id=210264, zh_CN="你迅速被汹涌的人潮和闪光灯淹没。", },
	[210265] = {id=210265, zh_CN="记者们的话筒几乎戳到你的脸上。", },
	[210266] = {id=210266, zh_CN="%PlayerName！月影商会深陷惊天赝品丑闻，你对此知情吗？", },
	[210267] = {id=210267, zh_CN="报道称您与奥黛特会长共同策划了整个拍卖骗局！", },
	[210268] = {id=210268, zh_CN="您对此有何回应？", },
	[210269] = {id=210269, zh_CN="知情人士透露已收集到确凿证据。", },
	[210270] = {id=210270, zh_CN="您是否早就知道会长在利用商会洗钱和走私？", },
	[210271] = {id=210271, zh_CN="请问您分走了多少赃款？", },
	[210272] = {id=210272, zh_CN="沉默，脑子炸开。", },
	[210273] = {id=210273, zh_CN="这……这……", },
	[210274] = {id=210274, zh_CN="你想开口狡辩，却发现任何解释都可能被扭曲。", },
	[210275] = {id=210275, zh_CN="无可奉告。", },
	[210276] = {id=210276, zh_CN="迷蒙——同谋？策划？", },
	[210277] = {id=210277, zh_CN="你们……你们在说什么？", },
	[210278] = {id=210278, zh_CN="什么骗局？同谋？", },
	[210279] = {id=210279, zh_CN="这到底是怎么回事？", },
	[210280] = {id=210280, zh_CN="您上次高调出席拍卖会。", },
	[210281] = {id=210281, zh_CN="难道不是为骗局站台？", },
	[210282] = {id=210282, zh_CN="我只是受邀参加拍卖会。", },
	[210283] = {id=210283, zh_CN="气愤——这…这简直是天方夜谭！", },
	[210284] = {id=210284, zh_CN="谁在背后操控这一切？", },
	[210285] = {id=210285, zh_CN="为什么要拖我下水？！", },
	[210286] = {id=210286, zh_CN="所以您承认自己被拖下水了？", },
	[210287] = {id=210287, zh_CN="您是否遭到了奥黛特会长的威胁？", },
	[210288] = {id=210288, zh_CN="我不是这个意思！", },
	[210289] = {id=210289, zh_CN="这是诬陷！", },
	[210290] = {id=210290, zh_CN="请问！", },
	[210291] = {id=210291, zh_CN="%PlayerName！", },
	[210292] = {id=210292, zh_CN="月影商会……", },
	[210293] = {id=210293, zh_CN="无数个问题像炮弹一样砸过来。", },
	[210294] = {id=210294, zh_CN="推搡的人群让你寸步难行。", },
	[210295] = {id=210295, zh_CN="百口莫辩……一股巨大的无助感席卷全身。", },
	[210296] = {id=210296, zh_CN="就在你被记者围攻、几乎窒息之际。", },
	[210297] = {id=210297, zh_CN="手腕上的个人终端发出强烈的震动。", },
	[210298] = {id=210298, zh_CN="广场中心警署：奥黛特·月影女士要求与你紧急会见。请即刻至学院侧面的中心警署会面室。可从侧面由警员引导进入。", },
	[210299] = {id=210299, zh_CN="警卫将你带入会面室，锁上门。", },
	[210300] = {id=210300, zh_CN="厚重的防爆玻璃将狭小的空间一分为二，", },
	[210301] = {id=210301, zh_CN="玻璃另一侧，奥黛特坐在金属椅上。", },
	[210302] = {id=210302, zh_CN="她褪去了华丽的裙装，只穿着简单的便服。", },
	[210303] = {id=210303, zh_CN="几缕发丝垂落额前，透着一丝你未见过的脆弱。", },
	[210304] = {id=210304, zh_CN="你来了。", },
	[210305] = {id=210305, zh_CN="比我想象的要快。", },
	[210306] = {id=210306, zh_CN="奥黛特小姐！这到底是怎么回事？", },
	[210307] = {id=210307, zh_CN="我刚刚在商会门口被记者围攻！", },
	[210308] = {id=210308, zh_CN="他们说我跟你合谋诈骗！", },
	[210309] = {id=210309, zh_CN="我猜到了。", },
	[210310] = {id=210310, zh_CN="外面现在一定充斥着各种绘声绘色的故事吧。", },
	[210311] = {id=210311, zh_CN="那些记者，不去当编剧真是制片厂的损失。", },
	[210312] = {id=210312, zh_CN="精彩？！", },
	[210313] = {id=210313, zh_CN="现在不是玩笑的时候。", },
	[210314] = {id=210314, zh_CN="我为什么会被卷入月影商会的风波之中？", },
	[210315] = {id=210315, zh_CN="是你做的吗？", },
	[210316] = {id=210316, zh_CN="是你把我拖下水的吗？", },
	[210317] = {id=210317, zh_CN="外面现在很乱吧。", },
	[210318] = {id=210318, zh_CN="辛苦你与记者们周旋了。", },
	[210319] = {id=210319, zh_CN="%PlayerName，请你冷静下来。", },
	[210320] = {id=210320, zh_CN="听我说，好吗？", },
	[210321] = {id=210321, zh_CN="点头——好。", },
	[210322] = {id=210322, zh_CN="我知道你现在很慌张。", },
	[210323] = {id=210323, zh_CN="是你吧，为什么这样对我？！", },
	[210324] = {id=210324, zh_CN="为什么要把我拖下水！", },
	[210325] = {id=210325, zh_CN="外面现在很乱吧。", },
	[210326] = {id=210326, zh_CN="辛苦你与记者们周旋了。", },
	[210327] = {id=210327, zh_CN="%PlayerName，请你冷静下来。", },
	[210328] = {id=210328, zh_CN="给我一个解释的机会好吗？", },
	[210329] = {id=210329, zh_CN="点头——好。", },
	[210330] = {id=210330, zh_CN="我知道你现在很愤怒。", },
	[210331] = {id=210331, zh_CN="我很抱歉将你置于如此境地。", },
	[210332] = {id=210332, zh_CN="但请你相信，我也是受害者。", },
	[210333] = {id=210333, zh_CN="你相信我吗？", },
	[210334] = {id=210334, zh_CN="相信。", },
	[210335] = {id=210335, zh_CN="受害者？他们都说你是主谋。", },
	[210336] = {id=210336, zh_CN="你要我怎么相信你。", },
	[210337] = {id=210337, zh_CN="因为你的一面之词吗？", },
	[210338] = {id=210338, zh_CN="不相信。", },
	[210339] = {id=210339, zh_CN="你难道不是主谋吗？", },
	[210340] = {id=210340, zh_CN="我是不会被你利用的。", },
	[210341] = {id=210341, zh_CN="不要游说我了。", },
	[210342] = {id=210342, zh_CN="我不会相信你的一面之词。", },
	[210343] = {id=210343, zh_CN="%PlayerName，你已经无法脱身了。", },
	[210344] = {id=210344, zh_CN="惊愕——什么？", },
	[210345] = {id=210345, zh_CN="虽然这是月影商会内部的争斗，", },
	[210346] = {id=210346, zh_CN="但你……被他们选中。", },
	[210347] = {id=210347, zh_CN="是用来混淆视听的牺牲品！", },
	[210348] = {id=210348, zh_CN="分散公众的注意力，分担警署调查的警力。", },
	[210349] = {id=210349, zh_CN="他们需要伪造出一位奥黛特会长的共犯。", },
	[210350] = {id=210350, zh_CN="最近高调亮相，与我关系不错的你，", },
	[210351] = {id=210351, zh_CN="就是最佳人选。", },
	[210352] = {id=210352, zh_CN="抱歉，没有保护好你。", },
	[210353] = {id=210353, zh_CN="我的问题。", },
	[210354] = {id=210354, zh_CN="他们的目的是什么？", },
	[210355] = {id=210355, zh_CN="你们的目的是什么？", },
	[210356] = {id=210356, zh_CN="需要一个焦点来为他们争取时间。", },
	[210357] = {id=210357, zh_CN="做什么！", },
	[210358] = {id=210358, zh_CN="转移资产，打击商会的信誉，", },
	[210359] = {id=210359, zh_CN="销毁证据，引导调查方向偏离。", },
	[210360] = {id=210360, zh_CN="奥黛特的身体前倾，压低声音。", },
	[210361] = {id=210361, zh_CN="%PlayerName，我需要你的帮助。", },
	[210362] = {id=210362, zh_CN="现在，外面能自由行动，又……", },
	[210363] = {id=210363, zh_CN="又……", },
	[210364] = {id=210364, zh_CN="又让我此刻愿意赌上一丝信任的人，", },
	[210365] = {id=210365, zh_CN="只有你了，%PlayerName。", },
	[210366] = {id=210366, zh_CN="奥黛特从贴身口袋中小心翼翼地取出一枚物件。", },
	[210367] = {id=210367, zh_CN="那是一枚造型古朴，线条流畅的银质胸针。", },
	[210368] = {id=210368, zh_CN="中心镶嵌着一颗光华内敛的月牙形蓝宝石。", },
	[210369] = {id=210369, zh_CN="她将其轻轻推到玻璃窗下的狭窄传递口。", },
	[210370] = {id=210370, zh_CN="拿着它。这不是装饰徽章，是我作为会长代表的信物。", },
	[210371] = {id=210371, zh_CN="盯着胸针——这是什么？", },
	[210372] = {id=210372, zh_CN="这是什么？", },
	[210373] = {id=210373, zh_CN="不立刻拿起——另一个陷阱？", },
	[210374] = {id=210374, zh_CN="这是什么？另一个陷阱吗？", },
	[210375] = {id=210375, zh_CN="它能打开我办公室最深处，", },
	[210376] = {id=210376, zh_CN="一个独立于商会安全系统的保险库。", },
	[210377] = {id=210377, zh_CN="那里面，藏着能撕破这张舆论之网的关键线索。", },
	[210378] = {id=210378, zh_CN="它能带领你找到真正的背叛者。", },
	[210379] = {id=210379, zh_CN="我为什么要相信你？", },
	[210380] = {id=210380, zh_CN="也许，你想让我去帮你销毁对你不利的证据？", },
	[210381] = {id=210381, zh_CN="选择权在你，%PlayerName。", },
	[210382] = {id=210382, zh_CN="我希望你用你自己的眼睛和判断，去揭开真相。", },
	[210383] = {id=210383, zh_CN="还是说，你已经和他们一样……", },
	[210384] = {id=210384, zh_CN="认定了奥黛特·月影，就是一个彻头彻尾的信用诈骗犯？", },
	[210385] = {id=210385, zh_CN="相信奥黛特。", },
	[210386] = {id=210386, zh_CN="你深吸一口气，伸手坚定地拿起了胸针。", },
	[210387] = {id=210387, zh_CN="好。我去。", },
	[210388] = {id=210388, zh_CN="我不是为了你，我要知道真相。", },
	[210389] = {id=210389, zh_CN="无论它是什么。", },
	[210390] = {id=210390, zh_CN="好……谢谢你。", },
	[210391] = {id=210391, zh_CN="保险库的位置在我办公室东墙，第三块装饰板右下角。", },
	[210392] = {id=210392, zh_CN="密码是……", },
	[210393] = {id=210393, zh_CN="请务必小心。", },
	[210394] = {id=210394, zh_CN="他们可能还在监视商会。", },
	[210395] = {id=210395, zh_CN="请相信你的判断。", },
	[210396] = {id=210396, zh_CN="你紧握着那枚尚有奥黛特体温余温的胸针，离开了警局。", },
	[210397] = {id=210397, zh_CN="质疑奥黛特。", },
	[210398] = {id=210398, zh_CN="你拿起那枚冰冷的月牙胸针，指尖感受到金属的凉意。", },
	[210399] = {id=210399, zh_CN="奥黛特小姐。", },
	[210400] = {id=210400, zh_CN="月影的丑闻，我恰好出现在商会的时间，以及你的讯息……", },
	[210401] = {id=210401, zh_CN="一切都太巧了。", },
	[210402] = {id=210402, zh_CN="这枚信物，是不是你设计的另一个环节？", },
	[210403] = {id=210403, zh_CN="你想让我进保险库做什么？", },
	[210404] = {id=210404, zh_CN="替你拿回某些东西，", },
	[210405] = {id=210405, zh_CN="还是……想把我变成你最后的替罪羊？", },
	[210406] = {id=210406, zh_CN="奥黛特身体几不可察地晃了一下。", },
	[210407] = {id=210407, zh_CN="你……", },
	[210408] = {id=210408, zh_CN="既然怀疑，那就去证明它！", },
	[210409] = {id=210409, zh_CN="去我的保险库！去查！", },
	[210410] = {id=210410, zh_CN="用你自己的眼睛，去看！", },
	[210411] = {id=210411, zh_CN="看看里面装的到底是能洗刷我冤屈的证明，", },
	[210412] = {id=210412, zh_CN="还是能把我钉在耻辱柱上的铁证！", },
	[210413] = {id=210413, zh_CN="保险库的位置在我办公室东墙，第三块装饰板右下角。", },
	[210414] = {id=210414, zh_CN="密码是……", },
	[210415] = {id=210415, zh_CN="去吧……去验证你的怀疑。", },
	[210416] = {id=210416, zh_CN="真希望……我这最后的信任，没有错付。", },
	[210417] = {id=210417, zh_CN="你紧握着那枚尚有奥黛特体温余温的胸针，离开了警局。", },
	[210418] = {id=210418, zh_CN="商会总部外围依然有零星的记者。", },
	[210419] = {id=210419, zh_CN="胸针在侧门感应器上一晃，你一路畅通无阻，来到会长办公室。", },
	[210420] = {id=210420, zh_CN="办公室内一片狼藉，显然被搜查过。", },
	[210421] = {id=210421, zh_CN="你按照指示，走到东墙。", },
	[210422] = {id=210422, zh_CN="胸针贴上墙壁。", },
	[210423] = {id=210423, zh_CN="“咔哒”一声轻响，面板滑开，露出密码输入屏。", },
	[210424] = {id=210424, zh_CN="输入密码。", },
	[210425] = {id=210425, zh_CN="合金门无声滑开，露出一个仅容一人进入的狭小空间。", },
	[210426] = {id=210426, zh_CN="里面只有少数数据硬盘和几份加密文件。", },
	[210427] = {id=210427, zh_CN="快速浏览。", },
	[210428] = {id=210428, zh_CN="这笔资金……来源不明，最终汇入了内部账户。", },
	[210429] = {id=210429, zh_CN="记录显示成功售出的拍品，又重新登记入库？", },
	[210430] = {id=210430, zh_CN="而旁边相同编号的状态……是已流出？", },
	[210431] = {id=210431, zh_CN="这是……掉包！", },
	[210432] = {id=210432, zh_CN="你继续查看运输记录。", },
	[210433] = {id=210433, zh_CN="标注“维修评估”的运输单，频繁往返于商会和这几个偏僻仓库。", },
	[210434] = {id=210434, zh_CN="物品描述模糊，但重量和体积……", },
	[210435] = {id=210435, zh_CN="和一些小型珍贵藏品吻合。", },
	[210436] = {id=210436, zh_CN="审批签名……", },
	[210437] = {id=210437, zh_CN="商会的元老董事！", },
	[210438] = {id=210438, zh_CN="造假骗局居然都是真的！", },
	[210439] = {id=210439, zh_CN="但罪魁祸首不是奥黛特！", },
	[210440] = {id=210440, zh_CN="必须找到实质证据！", },
	[210441] = {id=210441, zh_CN="就算如此，也可能是奥黛特伪造的……", },
	[210442] = {id=210442, zh_CN="不能轻易下结论。", },
	[210443] = {id=210443, zh_CN="需要找到更直接的证据！", },
	[210444] = {id=210444, zh_CN="你迅速将异常运输记录、资金往来账户，以及可疑仓库地址的标注页收集起来。", },
	[210445] = {id=210445, zh_CN="离开时，你混入人群，格外小心。", },
	[210446] = {id=210446, zh_CN="前往郊区仓库一探究竟！", },
	[210447] = {id=210447, zh_CN="深夜的学院角落，你隐蔽在阴影中。", },
	[210448] = {id=210448, zh_CN="几位董事此刻正焦躁地用手帕擦着汗，对着通讯器低吼。", },
	[210449] = {id=210449, zh_CN="快！都搬上“黑隼号”！", },
	[210450] = {id=210450, zh_CN="真品、星魂、还有那些没处理掉的赝品……全搬上去！", },
	[210451] = {id=210451, zh_CN="几个光灵正慌乱地将箱子堆上一艘“废品回收”的星舰。", },
	[210452] = {id=210452, zh_CN="警察和记者肯定被引到这边了。", },
	[210453] = {id=210453, zh_CN="我们时间不多！动作再快点儿！", },
	[210454] = {id=210454, zh_CN="在最后一个箱子即将被推进船舱的瞬间——", },
	[210455] = {id=210455, zh_CN="刺耳的警笛声由远及近！", },
	[210456] = {id=210456, zh_CN="所有人不许动！放下武器，举起双手！", },
	[210457] = {id=210457, zh_CN="早已埋伏的警察如潮水般涌入。", },
	[210458] = {id=210458, zh_CN="紧随其后的是汹涌的记者群。", },
	[210459] = {id=210459, zh_CN="闪光灯将董事们因惊愕扭曲的脸照得一片惨白。", },
	[210460] = {id=210460, zh_CN="在直播镜头下，他们身边的罪证暴露无遗！", },
	[210461] = {id=210461, zh_CN="这时，你的个人终端再次震动。", },
	[210462] = {id=210462, zh_CN="谢谢。", },
	[210463] = {id=210463, zh_CN="随着相关董事及其党羽的落网，大量确凿证据浮出水面。", },
	[210464] = {id=210464, zh_CN="针对奥黛特的指控被迅速推翻。", },
	[210465] = {id=210465, zh_CN="很快，奥黛特被无罪释放。", },
	[210466] = {id=210466, zh_CN="各位尊敬的客户、合作伙伴，", },
	[210467] = {id=210467, zh_CN="以及所有关注月影商会的朋友们，", },
	[210468] = {id=210468, zh_CN="大家下午好。", },
	[210469] = {id=210469, zh_CN="她面向镜头，深深鞠躬。", },
	[210470] = {id=210470, zh_CN="首先，请允许我代表月影商会全体同仁，", },
	[210471] = {id=210471, zh_CN="向所有在此次恶性事件中受到困扰，感到不安的诸位，", },
	[210472] = {id=210472, zh_CN="致以最诚挚的歉意！", },
	[210473] = {id=210473, zh_CN="近期，关于月影商会涉及赝品交易、欺诈客户的传闻，", },
	[210474] = {id=210474, zh_CN="给各位带来了极大的困扰和损失，也严重损害了商会百年积累的声誉。", },
	[210475] = {id=210475, zh_CN="对此，我深感痛心。", },
	[210476] = {id=210476, zh_CN="经过警方全力侦办，现已查明。", },
	[210477] = {id=210477, zh_CN="这一切的罪魁祸首，是商会内部以商会董事元老为首的部分高层人员。", },
	[210478] = {id=210478, zh_CN="他们长期利用职务之便，勾结外部势力。", },
	[210479] = {id=210479, zh_CN="进行星际私自买卖以及赝品替换的欺诈行为！", },
	[210480] = {id=210480, zh_CN="为掩盖罪行，他们不惜构陷于我，妄图将整个商会拖入深渊！", },
	[210481] = {id=210481, zh_CN="对此，我表示最强烈的愤慨和谴责！", },
	[210482] = {id=210482, zh_CN="然而，作为月影商会的会长，", },
	[210483] = {id=210483, zh_CN="我，奥黛特·月影，难辞其咎！", },
	[210484] = {id=210484, zh_CN="是我在商会快速发展中，过于专注于开拓，", },
	[210485] = {id=210485, zh_CN="而疏忽了对内部权力的有效制衡与监督！", },
	[210486] = {id=210486, zh_CN="是我的失察，才让这些蛀虫有了可乘之机，最终酿成大祸！", },
	[210487] = {id=210487, zh_CN="让所有信任、支持月影的你们，无辜地卷入了这场风暴。", },
	[210488] = {id=210488, zh_CN="承受了本不该有的恐慌和损失。", },
	[210489] = {id=210489, zh_CN="对此，我承担全部责任！", },
	[210490] = {id=210490, zh_CN="我再次向所有人，致以最深的歉意！", },
	[210491] = {id=210491, zh_CN="为了弥补过失，重塑信任，月影商会即刻启动以下措施：", },
	[210492] = {id=210492, zh_CN="第一， 所有涉案赝品已全部无条件移交官方处理！", },
	[210493] = {id=210493, zh_CN="商会内部绝不姑息任何关联人员！", },
	[210494] = {id=210494, zh_CN="第二，所有在月影商会已支付保证金的会员，", },
	[210495] = {id=210495, zh_CN="商会将双倍返还您的保证金！", },
	[210496] = {id=210496, zh_CN="这是我们对您的最直接歉意！", },
	[210497] = {id=210497, zh_CN="第三，凡持有交易凭证的客户，", },
	[210498] = {id=210498, zh_CN="如对所购物品真伪存有疑虑，", },
	[210499] = {id=210499, zh_CN="均可携带商品及完整凭证，", },
	[210500] = {id=210500, zh_CN="前往指定鉴定点进行免费鉴定！", },
	[210501] = {id=210501, zh_CN="如是此次事件涉及的商品，", },
	[210502] = {id=210502, zh_CN="将在官方现场监督下，兑换回真品。", },
	[210503] = {id=210503, zh_CN="第四，月影商会开启为期三个月的“月影安心购”活动！", },
	[210504] = {id=210504, zh_CN="活动期间，为所有新老客户提供免费的鉴宝服务！", },
	[210505] = {id=210505, zh_CN="我们将以更透明的操作流程、更严格的内部监管体系。", },
	[210506] = {id=210506, zh_CN="不惜一切代价，重塑月影商会的信誉基石！", },
	[210507] = {id=210507, zh_CN="再次谢谢大家的信任和等待。", },
	[210508] = {id=210508, zh_CN="发布会结束，人潮渐散。", },
	[210509] = {id=210509, zh_CN="你盯着手中闪烁光芒的花种……", },
	[210510] = {id=210510, zh_CN="你的终端再次响起。", },
	[210511] = {id=210511, zh_CN="危机暂息，余波未平。不知道是否愿意与我再饮一杯蜜露花茶？有些话我想当面说清，商会等你。", },
	[210512] = {id=210512, zh_CN="深夜，月影商会顶层。", },
	[210513] = {id=210513, zh_CN="你轻轻敲了敲门，然后推门而入。", },
	[210514] = {id=210514, zh_CN="你来了？坐吧。", },
	[210515] = {id=210515, zh_CN="发布会……你都看到了？", },
	[210516] = {id=210516, zh_CN="嗯。奥黛特，我……", },
	[210517] = {id=210517, zh_CN="不用道歉，%PlayerName。真的不用。", },
	[210518] = {id=210518, zh_CN="换做是我，在那种情况下，未必能做到比你更冷静。", },
	[210519] = {id=210519, zh_CN="但我确实怀疑过你。", },
	[210520] = {id=210520, zh_CN="我确实也……我犹豫了。", },
	[210521] = {id=210521, zh_CN="那是很正常的反应。", },
	[210522] = {id=210522, zh_CN="更何况，我也利用了这份怀疑。", },
	[210523] = {id=210523, zh_CN="我又一次利用了你。", },
	[210524] = {id=210524, zh_CN="其实我有能力将你推出这场风波的。", },
	[210525] = {id=210525, zh_CN="但我没有。", },
	[210526] = {id=210526, zh_CN="是我纵容他们将你卷入其中。", },
	[210527] = {id=210527, zh_CN="因为你的介入，能让我的棋局活起来。", },
	[210528] = {id=210528, zh_CN="叫你过来，是想亲口对你说两件事。", },
	[210529] = {id=210529, zh_CN="什么？", },
	[210530] = {id=210530, zh_CN="第一，是谢谢。", },
	[210531] = {id=210531, zh_CN="谢谢你，最终选择站在了真相这边。", },
	[210532] = {id=210532, zh_CN="谢谢你，帮我洗刷了这不白之冤。", },
	[210533] = {id=210533, zh_CN="你保住了这份沉重的基业。", },
	[210534] = {id=210534, zh_CN="无论过程如何，结果是你撕破了那张网。", },
	[210535] = {id=210535, zh_CN="这份情，我记下了。", },
	[210536] = {id=210536, zh_CN="这是我应该做的。", },
	[210537] = {id=210537, zh_CN="不，这不是任何人的应该。", },
	[210538] = {id=210538, zh_CN="第二，是抱歉。", },
	[210539] = {id=210539, zh_CN="很抱歉，把你拖进了月影这滩浑水里。", },
	[210540] = {id=210540, zh_CN="我利用了你的身份、你的背景、你的话题度、你的信任。", },
	[210541] = {id=210541, zh_CN="甚至……你那时恰如其分的愤怒。", },
	[210542] = {id=210542, zh_CN="%PlayerName，我是个自私到极点的人。", },
	[210543] = {id=210543, zh_CN="为了保住月影商会，我算计了很多人。", },
	[210544] = {id=210544, zh_CN="包括那些董事，包括媒体……", },
	[210545] = {id=210545, zh_CN="也包括你。", },
	[210546] = {id=210546, zh_CN="所以，一切都在你的计划之中？", },
	[210547] = {id=210547, zh_CN="大部分是。", },
	[210548] = {id=210548, zh_CN="还记得我送你的那个小玩意儿吗？", },
	[210549] = {id=210549, zh_CN="情绪花种？", },
	[210550] = {id=210550, zh_CN="是的。", },
	[210551] = {id=210551, zh_CN="作为我欺骗你的清账。", },
	[210552] = {id=210552, zh_CN="我想用它换回你的信任。", },
	[210553] = {id=210553, zh_CN="我们之间重新开始，", },
	[210554] = {id=210554, zh_CN="现在我欠你一个人情。", },
	[210555] = {id=210555, zh_CN="接受清算。", },
	[210556] = {id=210556, zh_CN="明白了。过去一笔勾销。", },
	[210557] = {id=210557, zh_CN="商场上，账目清晰是长久合作的基础。", },
	[210558] = {id=210558, zh_CN="别忘了你欠我的人情。", },
	[210559] = {id=210559, zh_CN="好。", },
	[210560] = {id=210560, zh_CN="表达不满。", },
	[210561] = {id=210561, zh_CN="在你眼里，所有关系最终都能用“利益账目”来结算吗？", },
	[210562] = {id=210562, zh_CN="当然。", },
	[210563] = {id=210563, zh_CN="清晰的账目，才能避免不必要的误会和情感损耗。", },
	[210564] = {id=210564, zh_CN="不是吗？", },
	[210565] = {id=210565, zh_CN="奥黛特小姐，经历了这么多，", },
	[210566] = {id=210566, zh_CN="我们之间，难道只能用账目和价值来衡量吗？", },
	[210567] = {id=210567, zh_CN="我们不算朋友吗？", },
	[210568] = {id=210568, zh_CN="朋友？", },
	[210569] = {id=210569, zh_CN="亲爱的，你这样重视感情，", },
	[210570] = {id=210570, zh_CN="在星际商海里是很容易受伤的。", },
	[210571] = {id=210571, zh_CN="你只会再一次被我利用。", },
	[210572] = {id=210572, zh_CN="我只是在想，我们之间，除了利益交换，还有其他吗？", },
	[210573] = {id=210573, zh_CN="我们为彼此做的一切，是否都只是在计算价值？", },
	[210574] = {id=210574, zh_CN="你永远在衡量我够不够格做你棋盘上的棋子？", },
	[210575] = {id=210575, zh_CN="没错。", },
	[210576] = {id=210576, zh_CN="我是个商人。我的血液里流淌着对价值的本能评估。", },
	[210577] = {id=210577, zh_CN="我习惯给一切标价，包括人情、关系、甚至……信任。", },
	[210578] = {id=210578, zh_CN="最初接近你，只因为你是“天外来客”。", },
	[210579] = {id=210579, zh_CN="你稀有，有价值。", },
	[210580] = {id=210580, zh_CN="背景干净，有太多可能性。", },
	[210581] = {id=210581, zh_CN="那么现在呢？", },
	[210582] = {id=210582, zh_CN="现在，你在一次次考验中证明了自己的能力、应变……", },
	[210583] = {id=210583, zh_CN="还有某种令我可依靠的品质。", },
	[210584] = {id=210584, zh_CN="但这不代表我们没有感情，%PlayerName。", },
	[210585] = {id=210585, zh_CN="%PlayerName。只是我对“感情”的理解，可能与众不同。", },
	[210586] = {id=210586, zh_CN="在权力与金币交织的漩涡中心，", },
	[210587] = {id=210587, zh_CN="唯有深度的利益交换，才是最牢固的纽带。", },
	[210588] = {id=210588, zh_CN="她的身体微微前倾，拉近了与你的距离。", },
	[210589] = {id=210589, zh_CN="%PlayerName，", },
	[210590] = {id=210590, zh_CN="我们，共同经历了这场风波。", },
	[210591] = {id=210591, zh_CN="我们之间有基于事实的信任。", },
	[210592] = {id=210592, zh_CN="有在危机中磨合出的默契。", },
	[210593] = {id=210593, zh_CN="甚至有对彼此能力的欣赏。", },
	[210594] = {id=210594, zh_CN="这些东西，都是实实在在的。", },
	[210595] = {id=210595, zh_CN="它们建立在一次次成功的利益交换之上。", },
	[210596] = {id=210596, zh_CN="比空泛的誓言更经得起考验。", },
	[210597] = {id=210597, zh_CN="如果非要把这种关系类比成“友情”……", },
	[210598] = {id=210598, zh_CN="那么，以我们之间利益交换的广度与深度来衡量，", },
	[210599] = {id=210599, zh_CN="我们算得上是——过命的深交。", },
	[210600] = {id=210600, zh_CN="%PlayerName，你愿意接受这种解释吗？", },
	[210601] = {id=210601, zh_CN="比感情更加坚贞的利益捆绑？", },
	[210602] = {id=210602, zh_CN="沉默思考。", },
	[210603] = {id=210603, zh_CN="当然， 如果你觉得这种说法太不近人情，无法接受。", },
	[210604] = {id=210604, zh_CN="这也没关系，我们的合作依然可以继续。", },
	[210605] = {id=210605, zh_CN="只是我们之间的关系，也就到此为止了。", },
	[210606] = {id=210606, zh_CN="接受利益捆绑。", },
	[210607] = {id=210607, zh_CN="过命的深交……这个说法，真的很奥黛特。", },
	[210608] = {id=210608, zh_CN="好吧，我接受。", },
	[210609] = {id=210609, zh_CN="明智的选择，%PlayerName。", },
	[210610] = {id=210610, zh_CN="欢迎加入我的核心圈。", },
	[210611] = {id=210611, zh_CN="我亲爱的合伙人。", },
	[210612] = {id=210612, zh_CN="拒绝，坚持纯粹合作。", },
	[210613] = {id=210613, zh_CN="我…明白了。", },
	[210614] = {id=210614, zh_CN="抱歉，奥黛特小姐。", },
	[210615] = {id=210615, zh_CN="我想我们还是保持单纯的合作关系吧。", },
	[210616] = {id=210616, zh_CN="当然可以。尊重你的选择。", },
	[210617] = {id=210617, zh_CN="我们依然是……重要的合作伙伴。", },
	[210618] = {id=210618, zh_CN="期待你接下来的表现。", },
	[210619] = {id=210619, zh_CN="商会的休息日，你在吧台找到奥黛特。", },
	[210620] = {id=210620, zh_CN="她递给你一杯蜜露花茶。", },
	[210621] = {id=210621, zh_CN="鼓起勇气，表白！", },
	[210622] = {id=210622, zh_CN="奥黛特……", },
	[210623] = {id=210623, zh_CN="嗯？", },
	[210624] = {id=210624, zh_CN="你觉得我怎么样？", },
	[210625] = {id=210625, zh_CN="业务在线，人也不错，是可以深交的伙伴。", },
	[210626] = {id=210626, zh_CN="那……你会喜欢我吗？", },
	[210627] = {id=210627, zh_CN="%PlayerName，我们认识也不短了。", },
	[210628] = {id=210628, zh_CN="你见过我在谈判桌上如何把人逼到墙角，寸步不让。", },
	[210629] = {id=210629, zh_CN="也见过我在觥筹交错间如何与那些人虚与委蛇。", },
	[210630] = {id=210630, zh_CN="甚至，我还会继续利用你一次，两次……", },
	[210631] = {id=210631, zh_CN="为了维持商会的稳定。", },
	[210632] = {id=210632, zh_CN="我默许周身的一切人与物，", },
	[210633] = {id=210633, zh_CN="将你，将自己一次次卷入风波之中。", },
	[210634] = {id=210634, zh_CN="%PlayerName，月影·德是我的王国，是我的战场……", },
	[210635] = {id=210635, zh_CN="也是我的牢笼。", },
	[210636] = {id=210636, zh_CN="所以，你喜欢我吗？", },
	[210637] = {id=210637, zh_CN="或许我也有点喜欢你……", },
	[210638] = {id=210638, zh_CN="但我无法，无法给你纯粹的感情。", },
	[210639] = {id=210639, zh_CN="画本里那种描绘的，毫无保留的爱。", },
	[210640] = {id=210640, zh_CN="你明白吗？", },
	[210641] = {id=210641, zh_CN="我明白的。", },
	[210642] = {id=210642, zh_CN="但同时，作为一个活生生的人，", },
	[210643] = {id=210643, zh_CN="我也有我的欲望和情感需求。", },
	[210644] = {id=210644, zh_CN="我也憧憬着，只对我一人的欣赏目光。", },
	[210645] = {id=210645, zh_CN="我似乎没有理由拒绝你。", },
	[210646] = {id=210646, zh_CN="真的吗？", },
	[210647] = {id=210647, zh_CN="她无声地向前走了一步，你与她的距离瞬间变得暧昧。", },
	[210648] = {id=210648, zh_CN="我们可以试试开放式恋爱。", },
	[210649] = {id=210649, zh_CN="别着急答应我。", },
	[210650] = {id=210650, zh_CN="她手指抵在唇边。", },
	[210651] = {id=210651, zh_CN="我们会成为彼此特殊的存在，分享信任，分享激情，分享一部分真实的自我。", },
	[210652] = {id=210652, zh_CN="但我们不互相束缚。我不会是你的挚爱唯一，你也不会是我的生命全部。", },
	[210653] = {id=210653, zh_CN="我们在各自的轨道上运行，背负各自的职责和秘密。", },
	[210654] = {id=210654, zh_CN="我们是两只波浪线。", },
	[210655] = {id=210655, zh_CN="只在需要温暖、理解、或者纯粹欲望的时刻交汇。", },
	[210656] = {id=210656, zh_CN="你愿意接受这样的关系吗，%PlayerName。", },
	[210657] = {id=210657, zh_CN="她的手指轻轻抬起，似乎想触碰你的脸颊。", },
	[210658] = {id=210658, zh_CN="接受开放式关系。", },
	[210659] = {id=210659, zh_CN="奥黛特小姐，你总是把简单的问题复杂化。", },
	[210660] = {id=210660, zh_CN="我接受，接受这样的你，也接受如此的我们。", },
	[210661] = {id=210661, zh_CN="因为我的心脏会因你而加速。", },
	[210662] = {id=210662, zh_CN="她双手捧住你的脸，轻吻你的脸颊。", },
	[210663] = {id=210663, zh_CN="明智的选择，我亲爱的。", },
	[210664] = {id=210664, zh_CN="拒绝，渴望专一。", },
	[210665] = {id=210665, zh_CN="奥黛特，我……我很抱歉。", },
	[210666] = {id=210666, zh_CN="我理解你的处境，真的。", },
	[210667] = {id=210667, zh_CN="但是这样的关系，我……我无法接受。", },
	[210668] = {id=210668, zh_CN="我想要的，可能更多，也更简单。", },
	[210669] = {id=210669, zh_CN="很遗憾听到这个答案，但我尊重你的选择。", },
	[210670] = {id=210670, zh_CN="我们依然是重要的合作伙伴。", },
	[210671] = {id=210671, zh_CN="月影商会和我本人，都依旧珍视你的能力。", },
	[210672] = {id=210672, zh_CN="某日，你陪奥黛特完成了一次谈判。", },
	[210673] = {id=210673, zh_CN="厚重的门在两人身后关上。", },
	[210674] = {id=210674, zh_CN="奥黛特微微踮脚，贴着你。", },
	[210675] = {id=210675, zh_CN="做得不错。", },
	[210676] = {id=210676, zh_CN="她手指迅速抵住你的唇。", },
	[210677] = {id=210677, zh_CN="嘘……", },
	[210678] = {id=210678, zh_CN="奖励你一下。", },
	[210679] = {id=210679, zh_CN="她低笑着，吻上你的唇角。", },
	[210680] = {id=210680, zh_CN="睁大眼睛，不可置信。", },
	[210681] = {id=210681, zh_CN="你刚才的表情……真可爱。", },
	[210682] = {id=210682, zh_CN="晚上的庆功宴，你也要来。", },
	[210683] = {id=210683, zh_CN="不要迟到哦，亲爱的。", },
	[210684] = {id=210684, zh_CN="好。", },
	[210685] = {id=210685, zh_CN="她抬起手，微凉的指尖轻轻擦过你的脸颊。", },
	[210686] = {id=210686, zh_CN="刚才……挺厉害的。", },
	[210687] = {id=210687, zh_CN="你想要什么奖励呢？", },
	[210688] = {id=210688, zh_CN="温热的气息喷洒在耳廓。", },
	[210689] = {id=210689, zh_CN="一个足够记住今夜的吻，怎么样？", },
	[210690] = {id=210690, zh_CN="话音未落！门被推开！", },
	[210691] = {id=210691, zh_CN="睁大眼睛，怔愣在原地。", },
	[210692] = {id=210692, zh_CN="奥黛特搂住你，姿势亲昵。", },
	[210693] = {id=210693, zh_CN="慌什么？", },
	[210694] = {id=210694, zh_CN="你和奥黛特对视一眼。", },
	[210695] = {id=210695, zh_CN="再望向走廊远处已经空无一人。", },
	[210696] = {id=210696, zh_CN="你又算计我？", },
	[210697] = {id=210697, zh_CN="这下好了，不出半小时，整个商会都会知道会长和合伙人的绯闻了。", },
	[210698] = {id=210698, zh_CN="怕什么？谣言？让他们传去。", },
	[210699] = {id=210699, zh_CN="她的红唇几乎要碰到你唇角。", },
	[210700] = {id=210700, zh_CN="会长的秘辛，在谈判桌上也是张不错的牌。", },
	[210701] = {id=210701, zh_CN="晚上庆功宴，别迟到了。", },
	[210702] = {id=210702, zh_CN="别迟到，我亲爱的合伙人。", },
	[210703] = {id=210703, zh_CN="好。", },
	[210704] = {id=210704, zh_CN="一日的晚会上，你和奥黛特在露台吹风。", },
	[210705] = {id=210705, zh_CN="奥黛特，你就打算一直这样？", },
	[210706] = {id=210706, zh_CN="不打算给我个明确的名分吗？", },
	[210707] = {id=210707, zh_CN="总让他们编排我们的关系，听着别扭。", },
	[210708] = {id=210708, zh_CN="奥黛特正对着露台玻璃幕墙，优雅地取下一边的钻石流苏耳环。", },
	[210709] = {id=210709, zh_CN="闻言，她动作一顿，缓缓走向你。", },
	[210710] = {id=210710, zh_CN="夜风吹拂着她的长发和裙摆。", },
	[210711] = {id=210711, zh_CN="我们是什么关系，你和我心里清楚，这就够了。", },
	[210712] = {id=210712, zh_CN="伴侣这个身份是束缚，也是靶子。", },
	[210713] = {id=210713, zh_CN="贴上“奥黛特的伴侣”这个标签，", },
	[210714] = {id=210714, zh_CN="意味着你将永远活在我的阴影下。", },
	[210715] = {id=210715, zh_CN="意味着你会成为所有与我有利益往来的人的首要目标。", },
	[210716] = {id=210716, zh_CN="你的一举一动都会被审视、评判。", },
	[210717] = {id=210717, zh_CN="现在这样不好吗？", },
	[210718] = {id=210718, zh_CN="我们是彼此最信任的盟友，最默契的拍档，最……", },
	[210719] = {id=210719, zh_CN="她凑近，几乎鼻尖相触，气息交融。", },
	[210720] = {id=210720, zh_CN="最契合的灵魂伴侣。", },
	[210721] = {id=210721, zh_CN="是吗？", },
	[210722] = {id=210722, zh_CN="无论这场关于“名分”的小小对抗结果如何……", },
	[210723] = {id=210723, zh_CN="你们都会在下一秒将这个插曲抛掷脑后，", },
	[210724] = {id=210724, zh_CN="重新沉溺于这个利益与感情交织的开放关系。", },
	[210725] = {id=210725, zh_CN="月影商会邀请函", },
	[210726] = {id=210726, zh_CN="珍品之夜", },
	[210727] = {id=210727, zh_CN="经济漩涡之涟漪", },
	[210728] = {id=210728, zh_CN="坦白与道歉", },
	[210729] = {id=210729, zh_CN="利益捆绑的“友情”", },
	[210730] = {id=210730, zh_CN="恋爱开放公式", },
	[210731] = {id=210731, zh_CN="办公室恋情日常", },
	[210732] = {id=210732, zh_CN="无需标签的我们", },
	[210733] = {id=210733, zh_CN="与商会门口的奥黛特对话互动。", },
	[210734] = {id=210734, zh_CN="与商会门口的奥黛特对话互动。", },
	[210735] = {id=210735, zh_CN="前往商会，与奥黛特对话，参加月影商会拍卖。", },
	[210736] = {id=210736, zh_CN="前往空白指引点", },
	[210737] = {id=210737, zh_CN="前往学院找奥黛特", },
	[210738] = {id=210738, zh_CN="前往商会找保险库", },
	[210739] = {id=210739, zh_CN="前往学院角落的郊区仓库等待", },
	[210740] = {id=210740, zh_CN="前往商会听奥黛特的新闻发布会", },
	[210741] = {id=210741, zh_CN="在商会与奥黛特说话", },
	[210742] = {id=210742, zh_CN="在商会与奥黛特说话", },
	[210743] = {id=210743, zh_CN="在商会与奥黛特说话", },
	[210744] = {id=210744, zh_CN="在商会与奥黛特说话", },
	[210745] = {id=210745, zh_CN="在商会与奥黛特说话", },
	[210746] = {id=210746, zh_CN="任务详情1", },
	[210747] = {id=210747, zh_CN="任务详情2", },
