	[210757] = {id=210757, zh_CN="任务详情12", },
	[210758] = {id=210758, zh_CN="任务详情13", },
	[210759] = {id=210759, zh_CN="奥黛特检定道具1（发言表现良好）", },
	[210760] = {id=210760, zh_CN="奥黛特检定道具2（选择相信）", },
	[210761] = {id=210761, zh_CN="奥黛特检定道具3（合伙人）", },
	[210762] = {id=210762, zh_CN="奥黛特检定道具4（坦白完成）", },
	[210763] = {id=210763, zh_CN="奥黛特检定道具5（友情事件2完成）", },
	[210764] = {id=210764, zh_CN="奥黛特检定道具6（恋爱事件1完成）", },
