	[220000] = {id=220000, zh_CN="直播的青年", },
	[220001] = {id=220001, zh_CN="观景台上，一个青年身影正背对着湖面。", },
	[220002] = {id=220002, zh_CN="衬衫下，一条蓬松的尾巴正卷住三脚架，", },
	[220003] = {id=220003, zh_CN="男人左右挪动，调整摄像机的角度。", },
	[220004] = {id=220004, zh_CN="好奇上前，探头观察。", },
	[220005] = {id=220005, zh_CN="测试，测试。", },
	[220006] = {id=220006, zh_CN="测试收音。", },
	[220007] = {id=220007, zh_CN="这里的风声比预想中小。", },
	[220008] = {id=220008, zh_CN="收音效果不错。", },
	[220009] = {id=220009, zh_CN="嗯，我们开始直播吧。", },
	[220010] = {id=220010, zh_CN="脚步声渐近。", },
	[220011] = {id=220011, zh_CN="嗯？谁！", },
	[220012] = {id=220012, zh_CN="青年将尾巴悄悄藏到身后。", },
	[220013] = {id=220013, zh_CN="我是不是打扰你了？", },
	[220014] = {id=220014, zh_CN="啊！抱歉。", },
	[220015] = {id=220015, zh_CN="这里风景不错。", },
	[220016] = {id=220016, zh_CN="我随便转转，正好遇到你……", },
	[220017] = {id=220017, zh_CN="我是不是打扰你了？", },
	[220018] = {id=220018, zh_CN="我……我有点好奇。", },
	[220019] = {id=220019, zh_CN="所以我过来看看。", },
	[220020] = {id=220020, zh_CN="我是不是打扰你了？", },
	[220021] = {id=220021, zh_CN="嗷呜！没有。", },
	[220022] = {id=220022, zh_CN="青年慌张摇头，身后的尾巴炸起。", },
	[220023] = {id=220023, zh_CN="他的尾巴触电般随着脑袋甩动！", },
	[220024] = {id=220024, zh_CN="呜——！", },
	[220025] = {id=220025, zh_CN="哐当！", },
	[220026] = {id=220026, zh_CN="巨大力量将三脚架从平台上扫飞出去！", },
	[220027] = {id=220027, zh_CN="呜！", },
	[220028] = {id=220028, zh_CN="直播画面天旋地转……", },
	[220029] = {id=220029, zh_CN="某个瞬间似乎捕捉到，", },
	[220030] = {id=220030, zh_CN="青年线条流畅的下巴与紧绷的唇线。", },
	[220031] = {id=220031, zh_CN="咔嚓！", },
	[220032] = {id=220032, zh_CN="镜头砸在旁边的碎石地上，", },
	[220033] = {id=220033, zh_CN="发出令人心碎的碎裂声。", },
	[220034] = {id=220034, zh_CN="直播中断前，弹幕瞬间爆炸：", },
	[220035] = {id=220035, zh_CN="哇！尾巴！", },
	[220036] = {id=220036, zh_CN="主播真的是狗狗妖灵？实锤了！", },
	[220037] = {id=220037, zh_CN="啊啊啊差点看到脸了！可惜！", },
	[220038] = {id=220038, zh_CN="主播你没事吧？", },
	[220039] = {id=220039, zh_CN="摔到哪里了？好担心！", },
	[220040] = {id=220040, zh_CN="大型掉马现场？", },
	[220041] = {id=220041, zh_CN="事故都这么有节目效果（狗头）。", },
	[220042] = {id=220042, zh_CN="嗷呜呜呜……", },
	[220043] = {id=220043, zh_CN="他像受惊的兔子，向后跳开了一大步。", },
	[220044] = {id=220044, zh_CN="他和你保持到安全的距离。", },
	[220045] = {id=220045, zh_CN="扶起设备残骸。", },
	[220046] = {id=220046, zh_CN="对、对不起！", },
	[220047] = {id=220047, zh_CN="你，你受伤了吗？", },
	[220048] = {id=220048, zh_CN="这个相机……", },
	[220049] = {id=220049, zh_CN="青年急促地喘息几下。", },
	[220050] = {id=220050, zh_CN="鼻翼翕动，嗅闻着你的气味。", },
	[220051] = {id=220051, zh_CN="没……没事。", },
	[220052] = {id=220052, zh_CN="设备我自己能处理。", },
	[220053] = {id=220053, zh_CN="他迅速蹲下身，检查还能使用的部件。", },
	[220054] = {id=220054, zh_CN="他的尾巴扫过一堆机械残骸，", },
	[220055] = {id=220055, zh_CN="将储存芯片一一找出。", },
	[220056] = {id=220056, zh_CN="不行不行。", },
	[220057] = {id=220057, zh_CN="是我吓到你了才弄坏的。", },
	[220058] = {id=220058, zh_CN="好奇询问身份。", },
	[220059] = {id=220059, zh_CN="那个，请问你是……博主吗？", },
	[220060] = {id=220060, zh_CN="刚看你的通讯器弹幕刷得好快。", },
	[220061] = {id=220061, zh_CN="人气很高吧。", },
	[220062] = {id=220062, zh_CN="嗯，旅行博主。", },
	[220063] = {id=220063, zh_CN="主动告知自己身份。", },
	[220064] = {id=220064, zh_CN="我叫%PlayerName。", },
	[220065] = {id=220065, zh_CN="方便告诉我你的名字或者联系方式吗？", },
	[220066] = {id=220066, zh_CN="不，不用了。", },
	[220067] = {id=220067, zh_CN="要求赔偿。", },
	[220068] = {id=220068, zh_CN="设备的损失我来承担。", },
	[220069] = {id=220069, zh_CN="你给我个联系方式？", },
	[220070] = {id=220070, zh_CN="谢谢，真的不用。", },
	[220071] = {id=220071, zh_CN="担心身体。", },
	[220072] = {id=220072, zh_CN="你盯着他夹紧的尾巴。", },
	[220073] = {id=220073, zh_CN="他几不可查地瑟缩了一下。", },
	[220074] = {id=220074, zh_CN="你真的没受伤吗？", },
	[220075] = {id=220075, zh_CN="我看你刚才跳得好远。", },
	[220076] = {id=220076, zh_CN="力道那么大，尾巴……有没有扭到？", },
	[220077] = {id=220077, zh_CN="没有。", },
	[220078] = {id=220078, zh_CN="谢，谢谢关心。", },
	[220079] = {id=220079, zh_CN="询问是否前往医院。", },
	[220080] = {id=220080, zh_CN="要不要我陪你去医院检查一下？", },
	[220081] = {id=220081, zh_CN="不去！", },
	[220082] = {id=220082, zh_CN="等待回应。", },
	[220083] = {id=220083, zh_CN="他将捡起的零件抱在怀里。", },
	[220084] = {id=220084, zh_CN="我很好！设备…也没关系。", },
	[220085] = {id=220085, zh_CN="谢谢，不用……不需要。", },
	[220086] = {id=220086, zh_CN="设备已经旧了，真的没事。", },
	[220087] = {id=220087, zh_CN="留下个联系方式？", },
	[220088] = {id=220088, zh_CN="好吧，我明白了。", },
	[220089] = {id=220089, zh_CN="至少让我留下我的联系方式吧。", },
	[220090] = {id=220090, zh_CN="如果你之后发现设备有其他问题，", },
	[220091] = {id=220091, zh_CN="或者哪里不舒服，", },
	[220092] = {id=220092, zh_CN="请联系我。", },
	[220093] = {id=220093, zh_CN="报出个人信息。", },
	[220094] = {id=220094, zh_CN="你可以在社区找到我，很方便的！", },
	[220095] = {id=220095, zh_CN="我的地址是……", },
	[220096] = {id=220096, zh_CN="青年迅速捂住通讯器的收音孔。", },
	[220097] = {id=220097, zh_CN="嘘！", },
	[220098] = {id=220098, zh_CN="直播设备可能还在工作。", },
	[220099] = {id=220099, zh_CN="不要公开信息，不安全。", },
	[220100] = {id=220100, zh_CN="你盯着他近在咫尺，张合的嘴唇……", },
	[220101] = {id=220101, zh_CN="讪讪闭上了嘴。", },
	[220102] = {id=220102, zh_CN="写纸条。", },
	[220103] = {id=220103, zh_CN="你瞥了眼青年怀里的通讯器。", },
	[220104] = {id=220104, zh_CN="你掏出便签本和笔，快速写下名字和地址。", },
	[220105] = {id=220105, zh_CN="给，我的联系方式在上面。", },
	[220106] = {id=220106, zh_CN="他犹豫了下，嗅了嗅空气。", },
	[220107] = {id=220107, zh_CN="他伸出手，将便签对折再对折，", },
	[220108] = {id=220108, zh_CN="最后郑重地塞入口袋。", },
	[220109] = {id=220109, zh_CN="谢谢。我……该走了。", },
	[220110] = {id=220110, zh_CN="他抱着那些设备，始终低着头、", },
	[220111] = {id=220111, zh_CN="像一道白色的影子，从你身边掠过。", },
	[220112] = {id=220112, zh_CN="擦肩而过的瞬间，", },
	[220113] = {id=220113, zh_CN="那毛茸茸的尾巴尖，极快地扫过你的裤脚。", },
	[220114] = {id=220114, zh_CN="一颗情绪种子在你的手中凝结。", },
	[220115] = {id=220115, zh_CN="种子上还残留着一丝受惊的喧嚣余韵。", },
	[220116] = {id=220116, zh_CN="你握紧如纺锤的小种核。", },
	[220117] = {id=220117, zh_CN="忘记问名字了。", },
	[220118] = {id=220118, zh_CN="不过……问了也会被拒绝吧。", },
	[220119] = {id=220119, zh_CN="有机会再认识这位种子主人吧。", },
	[220120] = {id=220120, zh_CN="嗷呜……", },
