	[220122] = {id=220122, zh_CN="一板止痛药被他找出。", },
	[220123] = {id=220123, zh_CN="过期了……", },
	[220124] = {id=220124, zh_CN="嗷呜，好痛。", },
	[220125] = {id=220125, zh_CN="他犹豫片刻，掰开止痛药。", },
	[220126] = {id=220126, zh_CN="手里拿的什么？", },
	[220127] = {id=220127, zh_CN="哈尔！手里拿的什么？", },
	[220128] = {id=220128, zh_CN="没，没什么。", },
	[220129] = {id=220129, zh_CN="你怎么…在这里？", },
	[220130] = {id=220130, zh_CN="抠出哈尔嘴里的药。", },
	[220131] = {id=220131, zh_CN="不可以吃！", },
	[220132] = {id=220132, zh_CN="你怎么…在这里？", },
	[220133] = {id=220133, zh_CN="我刚路过。", },
	[220134] = {id=220134, zh_CN="我看见你翻垃圾桶了。", },
	[220135] = {id=220135, zh_CN="我找找有没有止疼药。", },
	[220136] = {id=220136, zh_CN="翻看药的日期。", },
	[220137] = {id=220137, zh_CN="已经过期……", },
	[220138] = {id=220138, zh_CN="不能吃过期药。", },
	[220139] = {id=220139, zh_CN="知道了。", },
	[220140] = {id=220140, zh_CN="你哪里痛吗？", },
	[220141] = {id=220141, zh_CN="尾巴。", },
	[220142] = {id=220142, zh_CN="是老毛病了。睡一觉就好了。", },
	[220143] = {id=220143, zh_CN="老毛病？", },
	[220144] = {id=220144, zh_CN="你目光落在他的不自然抽动的尾巴上。", },
	[220145] = {id=220145, zh_CN="疼到找过期药？", },
	[220146] = {id=220146, zh_CN="你哪里不舒服？", },
	[220147] = {id=220147, zh_CN="你哪里不舒服？", },
	[220148] = {id=220148, zh_CN="尾巴。", },
	[220149] = {id=220149, zh_CN="是老毛病了。睡一觉就好了。", },
	[220150] = {id=220150, zh_CN="老毛病？", },
	[220151] = {id=220151, zh_CN="你目光落在他的不自然抽动的尾巴上。", },
	[220152] = {id=220152, zh_CN="疼到找过期药？", },
	[220153] = {id=220153, zh_CN="建议去医院。", },
	[220154] = {id=220154, zh_CN="我觉得你应该去看医生。", },
	[220155] = {id=220155, zh_CN="嗷呜…我不去！", },
	[220156] = {id=220156, zh_CN="哈尔吓得缩成一团。", },
	[220157] = {id=220157, zh_CN="他夹住尾巴，耳朵紧贴脑袋。", },
	[220158] = {id=220158, zh_CN="我不去，绝对不去！", },
	[220159] = {id=220159, zh_CN="消毒水……要打针，呜呜。", },
	[220160] = {id=220160, zh_CN="不怕不怕。", },
	[220161] = {id=220161, zh_CN="呜呜，不去医院。", },
