	[220164] = {id=220164, zh_CN="轻拍他的背。", },
	[220165] = {id=220165, zh_CN="你搂住哈尔，轻拍他的背。", },
	[220166] = {id=220166, zh_CN="%PlayerName，我不要去医院……", },
