	[220168] = {id=220168, zh_CN="抱歉，我有点失态。", },
	[220169] = {id=220169, zh_CN="这样硬扛不行。", },
	[220170] = {id=220170, zh_CN="这样硬扛不行。", },
	[220171] = {id=220171, zh_CN="忍忍就过去了。", },
	[220172] = {id=220172, zh_CN="我都习惯了。", },
	[220173] = {id=220173, zh_CN="哈尔站起身，踉跄了一下。", },
	[220174] = {id=220174, zh_CN="看，你连路都走不稳了。", },
	[220175] = {id=220175, zh_CN="去医院。", },
	[220176] = {id=220176, zh_CN="去医院！", },
	[220177] = {id=220177, zh_CN="不去。", },
	[220178] = {id=220178, zh_CN="去医院。", },
