	[220184] = {id=220184, zh_CN="唉，不管了。", },
	[220185] = {id=220185, zh_CN="追上哈尔。", },
	[220186] = {id=220186, zh_CN="不能放任哈尔的尾巴恶化。", },
	[220187] = {id=220187, zh_CN="我去找他。", },
