	[220189] = {id=220189, zh_CN="如果再遇见哈尔……", },
	[220190] = {id=220190, zh_CN="要换种方式开导他。", },
	[220191] = {id=220191, zh_CN="好吧，不去医院。", },
	[220192] = {id=220192, zh_CN="呼……", },
	[220193] = {id=220193, zh_CN="同居！我来照顾你。", },
	[220194] = {id=220194, zh_CN="跟我回家，我来照顾你。", },
	[220195] = {id=220195, zh_CN="如果你不嫌弃，搬到我社区去？", },
	[220196] = {id=220196, zh_CN="或者，直接让我来照顾你一段时间？", },
	[220197] = {id=220197, zh_CN="嗯！", },
	[220198] = {id=220198, zh_CN="他兴奋地想要摇尾巴……", },
	[220199] = {id=220199, zh_CN="嘶！", },
