	[220201] = {id=220201, zh_CN="我会努力快点好起来的。", },
	[220202] = {id=220202, zh_CN="模拟医患，玩个游戏。", },
	[220203] = {id=220203, zh_CN="我们玩个游戏怎么样？", },
	[220204] = {id=220204, zh_CN="嗷，什么？", },
	[220205] = {id=220205, zh_CN="哈尔先生，你现在是我的特别病患。", },
	[220206] = {id=220206, zh_CN="让我为你检查一下？", },
	[220207] = {id=220207, zh_CN="哈尔盯着你……", },
