	[819604] = {id=819604, zh_CN="期待你再次应邀我的茶会。", },
	[819699] = {id=819699, zh_CN="漂亮的礼服", },
	[819700] = {id=819700, zh_CN="你今天这件礼服很漂亮。", },
	[819701] = {id=819701, zh_CN="真的吗？", },
	[819702] = {id=819702, zh_CN="我还在担心紫色会不会太张扬？", },
	[819703] = {id=819703, zh_CN="很适合你。", },
	[819704] = {id=819704, zh_CN="谢谢。", },
	[819799] = {id=819799, zh_CN="精彩的演出", },
	[819800] = {id=819800, zh_CN="你的演讲非常精彩。", },
	[819801] = {id=819801, zh_CN="不，还有很多不足。", },
	[819802] = {id=819802, zh_CN="我的语速可能偏快，手势也不够自然……", },
	[819803] = {id=819803, zh_CN="观众的反响很好啊。", },
	[819804] = {id=819804, zh_CN="那是大家宽容。", },
	[819805] = {id=819805, zh_CN="我需要改进的地方还有很多。", },
	[819806] = {id=819806, zh_CN="继续努力。", },
	[819807] = {id=819807, zh_CN="我会的。", },
	[819899] = {id=819899, zh_CN="有点辛苦", },
	[819900] = {id=819900, zh_CN="晚宴的准备工作辛苦吗？", },
	[819901] = {id=819901, zh_CN="职责所在，不觉得辛苦。", },
	[819902] = {id=819902, zh_CN="只希望能让每位来宾都感受到方舟的诚意。", },
	[819999] = {id=819999, zh_CN="需要帮忙吗？", },
	[820000] = {id=820000, zh_CN="我能帮上什么忙吗？", },
	[820001] = {id=820001, zh_CN="您能赏光出席，就很好了。", },
	[820002] = {id=820002, zh_CN="请尽情享受晚宴吧。", },
	[820099] = {id=820099, zh_CN="事后茶会", },
	[820100] = {id=820100, zh_CN="您泡的花茶很香。", },
	[820101] = {id=820101, zh_CN="你喜欢就好。", },
	[820102] = {id=820102, zh_CN="下次茶会，我还可以为您调配其他口味。", },
	[820199] = {id=820199, zh_CN="秘密出游", },
	[820200] = {id=820200, zh_CN="今天这身打扮很可爱。", },
	[820201] = {id=820201, zh_CN="真的吗？我有点不习惯……", },
	[820202] = {id=820202, zh_CN="但第一次出逃，感觉很自由。", },
	[820299] = {id=820299, zh_CN="别怕，阿加莎", },
	[820300] = {id=820300, zh_CN="不用担心，不会被认出来的。", },
	[820301] = {id=820301, zh_CN="嗯……我相信你。", },
	[820399] = {id=820399, zh_CN="开心的一天", },
	[820400] = {id=820400, zh_CN="得开心吗？", },
	[820401] = {id=820401, zh_CN="非常开心！", },
	[820402] = {id=820402, zh_CN="像做了一场美好的梦。", },
	[820403] = {id=820403, zh_CN="以后我们还会一起偷偷出游吗？", },
	[820404] = {id=820404, zh_CN="当然。", },
	[820405] = {id=820405, zh_CN="那我们约定好了。", },
	[820499] = {id=820499, zh_CN="小时候的事", },
	[820500] = {id=820500, zh_CN="能和我讲讲你小时候的事吗？", },
	[820501] = {id=820501, zh_CN="小时候……我最喜欢躲在母后的书房里。", },
	[820502] = {id=820502, zh_CN="我会翻看那些书籍。", },
	[820503] = {id=820503, zh_CN="虽然看不懂文字，但里面的插画令我着迷。", },
	[820599] = {id=820599, zh_CN="分享秘密", },
	[820600] = {id=820600, zh_CN="你愿意和我分享这些，我很感动。", },
	[820601] = {id=820601, zh_CN="因为你是我能坦诚对话的朋友。", },
	[820602] = {id=820602, zh_CN="希望我们的友谊可以长存。", },
