	[820603] = {id=820603, zh_CN="初次相逢", },
	[840000] = {id=840000, zh_CN="喵喵~", },
	[840001] = {id=840001, zh_CN="你是一只……会说话的猫？", },
	[840002] = {id=840002, zh_CN="喵~真没见识。", },
	[840003] = {id=840003, zh_CN="会说话很奇怪吗？", },
	[840004] = {id=840004, zh_CN="你还没有报上名字，很没有礼貌。", },
	[840005] = {id=840005, zh_CN="你好，我是%PlayerName。", },
	[840006] = {id=840006, zh_CN="%PlayerName……芝麻糊记下来。", },
	[840007] = {id=840007, zh_CN="你叫我芝麻糊就行。", },
	[840008] = {id=840008, zh_CN="你在这里做什么？", },
	[840009] = {id=840009, zh_CN="芝麻糊来品尝新出的限定甜点，以及……监督某个蠢弟弟别闯祸。", },
	[840020] = {id=840020, zh_CN="是你，把我吓了一大跳的家伙。", },
	[840021] = {id=840021, zh_CN="你好，我是%PlayerName。", },
	[840022] = {id=840022, zh_CN="我是年糕，请多指教啦。", },
	[840023] = {id=840023, zh_CN="你不会再忽然消失了吧？", },
	[840024] = {id=840024, zh_CN="不会的，我就在这里。", },
	[840025] = {id=840025, zh_CN="说不定哦～", },
	[840026] = {id=840026, zh_CN="那就好……", },
	[840027] = {id=840027, zh_CN="喵啊啊啊~", },
	[840028] = {id=840028, zh_CN="啊啊真是的，不要吓我喵。", },
	[840029] = {id=840029, zh_CN="刚才你突然出现，我差点从椅子上跳起来。", },
	[840030] = {id=840030, zh_CN="我、我还以为是坏人来了。", },
	[840031] = {id=840031, zh_CN="但看你睡得那么香，我又觉得你应该不是坏人。", },
	[840032] = {id=840032, zh_CN="坏人才不会在陌生的地方睡得那么香呢，喵~", },
	[840053] = {id=840053, zh_CN="开门请求", },
	[840060] = {id=840060, zh_CN="芝麻糊，可以帮我打开这扇门吗？", },
	[840061] = {id=840061, zh_CN="芝麻糊刚才吃到了你投喂的好吃的，当然要报答你啦。", },
	[840062] = {id=840062, zh_CN="芝麻糊伸爪轻轻一勾，掏出钥匙。", },
	[840063] = {id=840063, zh_CN="“咔”，门开了。", },
	[840064] = {id=840064, zh_CN="喵嗷，帮你把门打开了。", },
	[840065] = {id=840065, zh_CN="别打扰我享受宁静了。", },
	[840066] = {id=840066, zh_CN="谢谢你，芝麻糊。", },
	[840067] = {id=840067, zh_CN="喵~不谢。", },
	[840100] = {id=840100, zh_CN="年糕，这门打不开了，你能帮帮我吗？", },
	[840101] = {id=840101, zh_CN="喵、喵呜……好、好的。", },
	[840102] = {id=840102, zh_CN="帮助遇到困难的人是喵喵我的职责。", },
	[840103] = {id=840103, zh_CN="年糕竖起耳朵，来回检查门锁。", },
	[840104] = {id=840104, zh_CN="这种简单的门锁难不倒我。", },
	[840105] = {id=840105, zh_CN="交给我喵。", },
	[840106] = {id=840106, zh_CN="年糕摸索一阵，掏出钥匙。", },
