	[850036] = {id=850036, zh_CN="前往鸭湖城堡，和年糕一起去找导演拍摄短剧吧。", },
	[850037] = {id=850037, zh_CN="嗨，我是你的伙伴，请多关照。", },
	[850038] = {id=850038, zh_CN="作为见面礼，我把这个观察技能交给你！", },
	[850039] = {id=850039, zh_CN="在这里，想要了解信息，了解对方，", },
	[850040] = {id=850040, zh_CN="你好？请问需要帮忙吗？", },
	[850041] = {id=850041, zh_CN="喵呜……", },
	[850042] = {id=850042, zh_CN="芝麻糊现在脑子里乱糟糟的。", },
	[850043] = {id=850043, zh_CN="一点也不想说话。", },
	[850044] = {id=850044, zh_CN="请离我远一点，喵呜……", },
	[850045] = {id=850045, zh_CN="这只叫芝麻糊的小猫状态不太对", },
	[850046] = {id=850046, zh_CN="芝麻糊的心情很糟糕", },
	[850047] = {id=850047, zh_CN="喵~~芝麻糊最喜欢吃的猫罐头~~", },
	[850048] = {id=850048, zh_CN="来，你也试试。", },
	[850049] = {id=850049, zh_CN="哎呀呀，你凭空出现可把喵喵我吓了一跳！", },
	[850050] = {id=850050, zh_CN="嗨，猫猫。你知道芝麻糊是怎么了吗？", },
	[850051] = {id=850051, zh_CN="刚才喵喵我和芝麻糊在给店里做新品直播。", },
	[850052] = {id=850052, zh_CN="结果莫迪斯店长不小心弄出了好大动静。", },
	[850053] = {id=850053, zh_CN="把芝麻糊吓坏了。", },
	[850054] = {id=850054, zh_CN="你可以去问问莫迪斯店长。", },
	[850055] = {id=850055, zh_CN="芝麻糊，你好点了吗？", },
	[850056] = {id=850056, zh_CN="芝麻糊好多了，谢谢你喵。", },
	[850057] = {id=850057, zh_CN="喵~本来和年糕约好要去鸭湖城堡拍摄短剧的。", },
	[850058] = {id=850058, zh_CN="但芝麻糊的身体还没完全恢复。", },
	[850059] = {id=850059, zh_CN="能不能……拜托你和你的伙伴去鸭湖城堡，去拍摄短剧？", },
	[850060] = {id=850060, zh_CN="芝麻糊不想砸了猫猫的招牌。", },
	[850061] = {id=850061, zh_CN="拍短剧？当然可以啊。", },
	[850062] = {id=850062, zh_CN="太好了喵！", },
	[850063] = {id=850063, zh_CN="我会让年糕在鸭湖城堡等你们。", },
	[850064] = {id=850064, zh_CN="为了感谢你们，", },
	[850065] = {id=850065, zh_CN="芝麻糊教你们一个猫猫招牌动作吧。", },
	[850066] = {id=850066, zh_CN="看好喵！", },
	[850067] = {id=850067, zh_CN="就需要使用这个观察技能。", },
	[850068] = {id=850068, zh_CN="哇，年糕在那里。", },
	[850069] = {id=850069, zh_CN="我们一起去找他吧。", },
	[850100] = {id=850100, zh_CN="这位客人，我看你身上有种特别温柔的气场，", },
	[850101] = {id=850101, zh_CN="能不能请你和你的伙伴帮我安抚一下芝麻糊？", },
	[850102] = {id=850102, zh_CN="我这里有两个猫罐头。", },
	[850103] = {id=850103, zh_CN="麻烦去投喂一下芝麻糊，拜托了。", },
	[850104] = {id=850104, zh_CN="我会把投喂技能卡和猫罐头交给你。", },
	[850105] = {id=850105, zh_CN="长按投喂按钮，装备猫罐头，瞄准芝麻糊。", },
	[850106] = {id=850106, zh_CN="使用一次投喂，芝麻糊应该会开心一点。", },
	[850107] = {id=850107, zh_CN="拜托你们了。", },
	[840131] = {id=840131, zh_CN="提升信任度，让一位居民完成自我介绍。", },
	[840132] = {id=840132, zh_CN="提升一位居民的信任度，让他与你完成基础的自我介绍。/n提升信任度，让一位居民完成自我介绍。", },
	[840136] = {id=840136, zh_CN="向对你有好感的居民提出开门的请求。", },
	[840137] = {id=840137, zh_CN="你与居民相处得不错，是时候提出你的请求了。向对你有好感的居民提出开门的请求。/n向对你有好感的居民提出开门的请求。", },
	[840199] = {id=840199, zh_CN="紧闭的门", },
	[840200] = {id=840200, zh_CN="前往指引点，尝试打开门。", },
	[840201] = {id=840201, zh_CN="尝试打开面前的门，前往更广阔的世界。", },
	[840202] = {id=840202, zh_CN="与创建的伙伴对话。", },
	[840203] = {id=840203, zh_CN="与创建的伙伴对话，讨论如何离开甜品店。", },
	[840204] = {id=840204, zh_CN="通过右下角的社交技能、投喂赠礼以及对话，提升他们好感度。", },
	[840205] = {id=840205, zh_CN="投喂一次食物", },
	[840206] = {id=840206, zh_CN="向背包中的食物赠送给一位居民。\n投喂一次食物", },
	[840207] = {id=840207, zh_CN="破冰行动", },
	[840208] = {id=840208, zh_CN="通过右下角的社交技能、食物投喂或对话互动，提升芝麻糊、年糕、莫迪斯任意一位的信任度和好感度。", },
	[840250] = {id=840250, zh_CN="利用对话、投喂食物或社交技能,提升与芝麻糊、年糕莫迪斯任意一位的信任度和好感度,为获取开门帮助做准备。", },
	[840209] = {id=840209, zh_CN="美食诱惑", },
	[840210] = {id=840210, zh_CN="向芝麻糊和年糕任意一位进行喂食。", },
	[840211] = {id=840211, zh_CN="向芝麻糊和年糕任意一位进行喂食，提升信任度。", },
	[840212] = {id=840212, zh_CN="初次相逢", },
	[840213] = {id=840213, zh_CN="继续使用技能，提升芝麻糊或年糕的信任度至1级，与他进行更轻松的闲聊。", },
	[840214] = {id=840214, zh_CN="使用技能提升芝麻糊或年糕的信任度至1级，当关系破冰，与他进行更轻松的闲聊。", },
	[840258] = {id=840258, zh_CN="破冰闲聊", },
	[840215] = {id=840215, zh_CN="拉近关系", },
	[840216] = {id=840216, zh_CN="查看右上角好感，与一位居民好感度达到3级。\n并与自己创建的伙伴对话。", },
	[840217] = {id=840217, zh_CN="右上角的好感可以查看与居民的好感，迅速与他拉近关系吧。\n查看右上角好感，与一位居民好感度达到3。", },
	[840218] = {id=840218, zh_CN="巧言妙语", },
	[840219] = {id=840219, zh_CN="靠近芝麻糊或年糕，点击右下角“踌躇”/“搭讪”图标，对芝麻糊或年糕任意一位“搭讪”一次。", },
	[840220] = {id=840220, zh_CN="靠近芝麻糊或年糕，点击右下角“踌躇”/“搭讪”图标，对芝麻糊或年糕任意一位“搭讪”一次。", },
	[840221] = {id=840221, zh_CN="巧言妙语", },
	[840222] = {id=840222, zh_CN="对居民使用一次试探、搭讪等技能。", },
	[840223] = {id=840223, zh_CN="对一位居民使用试探、搭讪或夸赞等技能，观察其反应。\n对居民使用一次试探、搭讪等技能。", },
	[840224] = {id=840224, zh_CN="友谊的钥匙", },
	[840225] = {id=840225, zh_CN="与创建的伙伴对话。", },
	[840226] = {id=840226, zh_CN="你与芝麻糊和年糕相处得不错，是时候提出你的请求了。", },
	[840251] = {id=840251, zh_CN="开门请求", },
	[840227] = {id=840227, zh_CN="与芝麻糊和年糕任意一位对话，向他提出帮忙开门的请求。", },
	[840228] = {id=840228, zh_CN="你和芝麻糊、年糕的信任已经更进一步，选择一位，向他提出帮忙开门的请求。", },
	[840229] = {id=840229, zh_CN="新世界的序幕", },
	[840230] = {id=840230, zh_CN="与创建的伙伴对话。", },
	[840231] = {id=840231, zh_CN="穿过显现的传送门，正式开启你的探索之旅。", },
	[840232] = {id=840232, zh_CN="靠近莫迪斯，点击右下角“踌躇”/“搭讪”图标，对莫迪斯“搭讪”一次。", },
	[840233] = {id=840233, zh_CN="远处的人似乎是莫迪斯，与他对话了解下情况吧。靠近莫迪斯，点击右下角“踌躇”/“搭讪”图标，对莫迪斯“搭讪”一次。", },
	[400010] = {id=400010, zh_CN="走近那扇门，握住门把手轻轻转动……", },
	[400011] = {id=400011, zh_CN="门纹丝不动。", },
	[400012] = {id=400012, zh_CN="锁住了。", },
	[400020] = {id=400020, zh_CN="看来我们需要一点帮助才能离开这里。", },
	[400021] = {id=400021, zh_CN="店里有两只猫咪客人，或许他们中有人能打开门。", },
	[400022] = {id=400022, zh_CN="你可以尝试与芝麻糊和年糕多聊聊，提升他们对你的信任。", },
	[400023] = {id=400023, zh_CN="当他们觉得你是友善的，也许就会帮你开门了。", },
	[400024] = {id=400024, zh_CN="集中精力和一位打好关系会更有效率。", },
	[400027] = {id=400027, zh_CN="看来你和芝麻糊、年糕或莫迪斯相处得不错！是时候提出你的请求了。", },
	[400028] = {id=400028, zh_CN="走向那位与你关系最好的朋友，坦诚说出你的困境吧。", },
	[400029] = {id=400029, zh_CN="真是完美的破冰。", },
	[400030] = {id=400030, zh_CN="你已经在这个新世界结交到了朋友。", },
	[400031] = {id=400031, zh_CN="现在，深吸一口气。", },
	[400032] = {id=400032, zh_CN="让我们正式出发，去熟悉一下这个星球吧！", },
	[400033] = {id=400033, zh_CN="第一站：鸭湖城堡。", },
	[400034] = {id=400034, zh_CN="通过右下角的社交技能、食物投喂或对话互动，提升芝麻糊、年糕、莫迪斯任意一位的信任度和好感度吧！", },
	[400035] = {id=400035, zh_CN="你已经和这位居民建立了一些信任。", },
	[400036] = {id=400036, zh_CN="趁现在，一口作气，拿下它吧。", },
