	[300150] = {id=300150, zh_CN="抱起他人", },
	[300200] = {id=300200, zh_CN="有人来了", },
	[300201] = {id=300201, zh_CN="我也发现了", },
	[300202] = {id=300202, zh_CN="警告，有外卖小偷", },
