	[300209] = {id=300209, zh_CN="伙伴好友", },
	[300210] = {id=300210, zh_CN="群聊", },
	[300211] = {id=300211, zh_CN="好友申请", },
	[300212] = {id=300212, zh_CN="如果你执意要当这个投喂者……那你明天或许会看到商品价格全部上涨100%，只针对你一个人哦~", },
	[300213] = {id=300213, zh_CN="哪怕给月影商会再多的利益，我也不会吃这个食物的……", },
	[300214] = {id=300214, zh_CN="虽然这么说会让你有些失望，但是我确实不爱吃呢，或许下次我们的聊天主题可以是”喜爱的食物“~", },
	[300215] = {id=300215, zh_CN="很抱歉，我刚刚和艾妲用过餐了，现在不宜再食。", },
	[300216] = {id=300216, zh_CN="作为月影商会的代表人，保持身材也是很重要的，这份食物下次再带给我吧~", },
	[300217] = {id=300217, zh_CN="不要惊讶……机械生命也会有无法下咽的食物。", },
	[300218] = {id=300218, zh_CN="从数据上分析，我对这份食物的喜爱度为0。", },
	[300219] = {id=300219, zh_CN="这食物……比我一晚上都修不好的仪器还令人头疼……", },
	[300220] = {id=300220, zh_CN="虽然不理解人类吃饱是什么感受，但是我现在食物仓贮存显示是100%，已经不需要进食了。", },
	[300221] = {id=300221, zh_CN="我的饱食度告诉我，现在不能再进食，但是在人类的世界，浪费食物是很可耻的吧，如果不嫌麻烦，稍后再投喂？", },
	[300222] = {id=300222, zh_CN="快拿开！咳咳……不好意思，反应过激了，我只是讨厌这个食物，没有讨厌你哦！", },
	[300223] = {id=300223, zh_CN="唔！这个食物，和我旅行见到的臭干酪是一个味道，快拿远一些！", },
	[300224] = {id=300224, zh_CN="拿远些！这个食物的味道简直是第一大伤器，我要立刻去宠物医院洗一下鼻子！", },
	[300225] = {id=300225, zh_CN="啊~已经吃不下了，但是你陪我散散步，我们运动一下，说不定我又能吃得下了！", },
	[300226] = {id=300226, zh_CN="好撑呀，除了吃东西，我们还可以做其他事嘛！我和你说哦，我上次旅行……", },
	[300227] = {id=300227, zh_CN="喵！把这东西拿开！你就还是本堡主认可的小弟！！", },
	[300228] = {id=300228, zh_CN="就拿这小破东西打发本堡主？快去把小鱼干呈上来！", },
	[300229] = {id=300229, zh_CN="喵~你要是现在把这小玩意撤下去，本堡主就大发慈悲当没见过它。", },
	[300230] = {id=300230, zh_CN="嗝~刚刚已经被投喂很多小鱼干了，待会再来供奉食物吧。", },
	[300231] = {id=300231, zh_CN="本堡主的投喂时间已经结束了，嗝~但是别灰心，以后还有机会的喵~", },
	[300232] = {id=300232, zh_CN="唉！小子你背包里平常就放这些吗？别整这些了！叔叔请你吃别的！", },
	[300233] = {id=300233, zh_CN="喵嗷！小子你从哪搞来的这玩意，叔叔我腌了30年的臭鱼干都比这味道好些！", },
	[300234] = {id=300234, zh_CN="新奇！叔叔我活了这么久都没见过这么折磨人的食物。", },
	[300235] = {id=300235, zh_CN="你这东西叔叔吃不下了，自己收着吧。", },
	[300236] = {id=300236, zh_CN="嗝！小子真是不会看脸色，没看见叔叔饱得一直在打嗝吗！", },
	[300237] = {id=300237, zh_CN="这个食物简直比最不好笑的笑话还要不好笑！", },
	[300238] = {id=300238, zh_CN="我的笑话输给这个食物了！这个食物被做出来简直就是世界上最大的笑话！", },
	[300239] = {id=300239, zh_CN="就算是从不伤心的布琳，看见这个食物也会失去笑容的呜呜呜——", },
	[300240] = {id=300240, zh_CN="我想到一个笑话！世界上最大的烦恼就是，食物在眼前，可是你已经吃不下了~", },
	[300241] = {id=300241, zh_CN="不行了不行了，再吃，就要撑得讲不出话了，布琳待会还要表演魔术呢！", },
	[300242] = {id=300242, zh_CN="我要用放大镜看看，你到底在里面藏了什么，让这个食物变得这么难吃！", },
	[300243] = {id=300243, zh_CN="破案了！那股奇怪味道的来源是你手里的食物！", },
	[300244] = {id=300244, zh_CN="快拿开喵！如果吃了这个，喵喵我一定会难受得三天都下不了床，查不了案！", },
	[300245] = {id=300245, zh_CN="喵喵我呀吃不下了喵！", },
	[300246] = {id=300246, zh_CN="喵喵我呀真的真的吃不下了喵！", },
	[300247] = {id=300247, zh_CN="汪呜呜呜……小金毛不吃，吃了会做噩梦的！", },
