	[303882] = {id=303882, zh_CN="好久久久久久久久久久久久不见，再不见我都快忘了你长啥样。", },
	[303883] = {id=303883, zh_CN="假期迟迟迟迟迟迟迟迟迟迟迟早会来临的，我已经开始倒计时了。", },
	[303884] = {id=303884, zh_CN="吃的饱饱饱饱饱，烦恼跑跑跑跑跑，要是吃一顿能管一年饱就好了。", },
	[303885] = {id=303885, zh_CN="本周总结：劳逸逸逸逸逸逸结合，主打一个工作五分钟，休息两小时。", },
	[303886] = {id=303886, zh_CN="日子就算时好时坏坏坏坏坏坏坏坏坏坏，坏的时候就当体验生活的刺激。", },
	[303887] = {id=303887, zh_CN="总有雨雨雨雨雨雨雨雨过天晴的时候，可别雨过天晴就晒到我。", },
	[303888] = {id=303888, zh_CN="不撞撞撞撞撞撞撞撞撞撞撞撞南墙不回头，说不定南墙后面藏着宝藏呢。", },
	[303889] = {id=303889, zh_CN="生活不就是这样起起落落落落落落落落嘛，就像坐过山车，刺激得很。", },
	[303890] = {id=303890, zh_CN="工作总会一件一件一件一件一件做完的，前提是老板别再疯狂派活。", },
	[303891] = {id=303891, zh_CN="你好可可可可可可可可可可爱，可爱到我都想把你装进口袋。", },
	[303892] = {id=303892, zh_CN="在一起不就是柴米油盐酱醋醋醋醋醋茶嘛，要是能加点甜品就更好了。", },
	[303893] = {id=303893, zh_CN="生活总有一些磕磕磕磕磕碰碰碰碰的嘛，磕着碰着就习惯了。", },
	[303894] = {id=303894, zh_CN="别怕有句话叫因祸祸祸祸祸祸祸祸祸得福，我已经准备好迎接福气了。", },
	[303895] = {id=303895, zh_CN="所有的事总会慢慢慢慢慢慢慢好起来的，慢到我都怀疑人生了。", },
	[303896] = {id=303896, zh_CN="也要苦苦苦苦苦苦苦苦苦苦苦中作乐啊，苦中作乐，越乐越苦。", },
	[303897] = {id=303897, zh_CN="不要焦虑慢慢慢慢慢慢慢慢慢慢来，再慢黄花菜都凉了。", },
	[303898] = {id=303898, zh_CN="要相信一定会时来来来来来来来来来运转，我都等得花儿都谢了。", },
	[303899] = {id=303899, zh_CN="浪漫多多多多多多多多多多多一点，最好多到我被浪漫淹没。", },
	[303900] = {id=303900, zh_CN="见面了见面了见面见面了了了，终于不用对着手机聊天了。", },
	[303901] = {id=303901, zh_CN="人类和她的奇怪朋朋朋朋朋朋友，我的朋友都奇怪得各有千秋。", },
	[303902] = {id=303902, zh_CN="发什么呆呆呆呆呆呆呆呆呆呆呆呆呆，发呆能当饭吃我能发一天。", },
	[303903] = {id=303903, zh_CN="再吃亿亿亿亿亿亿亿亿亿亿亿点点，亿点点之后还有亿点点。", },
	[303904] = {id=303904, zh_CN="人生可不能随随便便随随便便，除非你有随便的资本。", },
	[303905] = {id=303905, zh_CN="地球不好混混混混混混混混混混混混呀，要不我去火星试试？", },
	[303906] = {id=303906, zh_CN="好好好好好好好好好好好好好时光，别浪费，赶紧吃喝玩乐。", },
	[303907] = {id=303907, zh_CN="要赚超多多多多多多多多多多多的钱，多到可以买下整个超市。", },
	[303908] = {id=303908, zh_CN="我刚刚准备开始减肥，结果美食都在向我招手，根本拒绝不了。", },
	[303909] = {id=303909, zh_CN="我以为我是个青铜，结果发现我连青铜的门槛都没摸到。", },
	[303910] = {id=303910, zh_CN="别人谈恋爱像开跑车，我谈恋爱像骑蜗牛，还老是迷路。", },
	[303911] = {id=303911, zh_CN="我和我的影子说悄悄话，它却不理我，太没礼貌了。", },
	[303912] = {id=303912, zh_CN="都说早起的鸟儿有虫吃，可我早起了，虫在哪呢？", },
	[303913] = {id=303913, zh_CN="我想和太阳肩并肩，结果被晒得黢黑，太阳你太狠了。", },
	[303914] = {id=303914, zh_CN="考试的时候，我感觉我的脑子像个空壳，啥都装不进去。", },
	[303915] = {id=303915, zh_CN="我以为我能征服世界，结果被世界的门槛绊倒了无数次。", },
	[303916] = {id=303916, zh_CN="梦想还是要有的，万一哪天实现了，我都不知道该怎么办。", },
	[303917] = {id=303917, zh_CN="我在大街上走着，突然感觉自己像个移动的表情包。", },
	[303918] = {id=303918, zh_CN="你说我是你的唯一，可我怎么感觉我是众多之一呢。", },
	[303919] = {id=303919, zh_CN="我是个很有原则的人，我的原则就是看心情。", },
	[303920] = {id=303920, zh_CN="我想和月亮聊聊天，问问它为啥老是那么圆，我却这么胖。", },
	[303921] = {id=303921, zh_CN="都说爱笑的女孩运气不会太差，可我笑了这么久，运气还是没见好。", },
	[303922] = {id=303922, zh_CN="我是一个自律的人，既然说了要减肥，那我就会一直说。", },
	[303923] = {id=303923, zh_CN="我的人生就像一部搞笑剧，每天都在上演各种奇葩剧情。", },
	[303924] = {id=303924, zh_CN="我想成为超级英雄，拯救世界，结果连自己的袜子都找不到。", },
	[303925] = {id=303925, zh_CN="别人都在努力进步，我却在努力退步，真是个 “人才”。", },
	[303926] = {id=303926, zh_CN="我和我的床感情深厚。", },
	[303927] = {id=303927, zh_CN="我本将心向明月，奈何明月照沟渠，我这心喂了狗。", },
	[303928] = {id=303928, zh_CN="你说你喜欢我，那你倒是把我喜欢的东西都买给我呀。", },
	[303929] = {id=303929, zh_CN="我是个很专一的人，我专一喜欢各种美食。", },
	[303930] = {id=303930, zh_CN="都说人生如戏，可我这戏怎么老是演砸呢。", },
	[303931] = {id=303931, zh_CN="我想当学霸，可我的脑子不同意，它只想睡觉。", },
	[303932] = {id=303932, zh_CN="我和蚊子大战三百回合，最后我输了，它吃得饱饱的。", },
	[303933] = {id=303933, zh_CN="你问我为什么单身，因为月老把我的红线拿去织秋裤了。", },
	[303934] = {id=303934, zh_CN="我是个很有耐心的人，等外卖的时候除外。", },
	[303935] = {id=303935, zh_CN="都说感情能让人变傻，我现在已经傻了。", },
	[303936] = {id=303936, zh_CN="我想飞，可是没有翅膀，有翅膀我估计也飞不起来。", },
	[303937] = {id=303937, zh_CN="我的钱包就像个漏斗，钱进去就没了踪影。", },
	[303938] = {id=303938, zh_CN="你说我胖，那你倒是把我的肉分点走呀。", },
	[303939] = {id=303939, zh_CN="我是个很坚强的人，看喜剧片的时候除外，能笑到崩溃。", },
	[303940] = {id=303940, zh_CN="都说早起身体好，可我早起了，身体也没见好多少。", },
	[303941] = {id=303941, zh_CN="我想成为诗人，可写出来的诗连我自己都看不懂。", },
	[303942] = {id=303942, zh_CN="我和我的影子玩捉迷藏，它总是躲得太好，我找不到它。", },
	[303943] = {id=303943, zh_CN="你说你会一直陪着我，结果我一转身，你就不见了。", },
	[303944] = {id=303944, zh_CN="我是个很有主见的人，我的主见就是听别人的意见。", },
	[303945] = {id=303945, zh_CN="都说努力就会有收获，可我努力了，收获的只有汗水。", },
	[303946] = {id=303946, zh_CN="我想成为画家，画出美丽的世界，结果画出来像鬼画符。", },
	[303947] = {id=303947, zh_CN="我和我的手机形影不离，它比我的朋友还重要。", },
	[303948] = {id=303948, zh_CN="你说你爱我，那你知道我最喜欢吃什么吗？", },
	[303949] = {id=303949, zh_CN="我是个很有创意的人，我的创意就是把简单的事情复杂化。", },
	[303950] = {id=303950, zh_CN="都说吃得苦中苦，方为人上人，可我吃了这么多苦，还是个普通人。", },
	[303951] = {id=303951, zh_CN="我想成为歌手，唱出动人的歌声，结果一开口，邻居都来投诉。", },
	[303952] = {id=303952, zh_CN="我和我的头发斗争了很久，它还是一直掉。", },
	[303953] = {id=303953, zh_CN="你说你懂我，可你连我喜欢什么颜色都不知道。", },
	[303954] = {id=303954, zh_CN="我是个很有勇气的人，在吃辣这件事上除外。", },
	[303955] = {id=303955, zh_CN="都说时间能治愈一切，可我的伤口怎么还在隐隐作痛。", },
	[303956] = {id=303956, zh_CN="我想成为舞者，跳出优美的舞姿，结果一跳起来像抽筋。", },
	[303957] = {id=303957, zh_CN="我和我的闹钟是对头，每天早上都要和它大战一场。", },
	[303958] = {id=303958, zh_CN="你说你会保护我，可我遇到危险的时候，你在哪里？", },
	[303959] = {id=303959, zh_CN="我是个很有智慧的人，我的智慧都用来想怎么偷懒了。", },
	[303960] = {id=303960, zh_CN="都说坚持就是胜利，可我坚持了这么久，胜利在哪里？", },
	[303961] = {id=303961, zh_CN="我想成为科学家，发明神奇的东西，结果连个小零件都装不好。", },
	[303962] = {id=303962, zh_CN="我和我的体重秤是仇人，每次看到它显示的数字，我都想砸了它。", },
	[303963] = {id=303963, zh_CN="你说你会给我幸福，可我怎么感觉幸福离我越来越远。", },
	[303964] = {id=303964, zh_CN="我是个很有耐心的人，玩游戏的时候除外，一输就想摔手机。", },
	[303965] = {id=303965, zh_CN="都说一分耕耘一分收获，可我耕耘了这么久，收获却少得可怜。", },
	[303966] = {id=303966, zh_CN="我想成为作家，写出畅销的小说，结果写出来的故事连自己都不想看。", },
	[303967] = {id=303967, zh_CN="我和我的痘痘势不两立，可它总是在我脸上安营扎寨。", },
	[303968] = {id=303968, zh_CN="你说你会永远爱我，可永远到底有多远呢？", },
	[303969] = {id=303969, zh_CN="我是个很有毅力的人，减肥这件事除外，坚持不了三天。", },
	[303970] = {id=303970, zh_CN="都说知识改变命运，可我学了这么多知识，命运还是没改变。", },
	[303971] = {id=303971, zh_CN="我想成为探险家，去探索神秘的世界，结果连小区的角落都不敢去。", },
	[303972] = {id=303972, zh_CN="我和我的作业是天敌，每次看到它，我就想睡觉。", },
	[303973] = {id=303973, zh_CN="你说你会对我好，可你做的事情却总是让我伤心。", },
	[303974] = {id=303974, zh_CN="我是个很有想法的人，我的想法就是每天都能睡懒觉。", },
	[303975] = {id=303975, zh_CN="都说爱笑的人运气不会太差，可我笑起来像个傻子，运气也没见好。", },
	[303976] = {id=303976, zh_CN="我想成为摄影师，拍出惊艳的照片，结果拍出来的都是糊的。", },
	[303977] = {id=303977, zh_CN="我和我的宠物互相嫌弃，它嫌我给的零食不好吃，我嫌它太调皮。", },
	[303978] = {id=303978, zh_CN="你说你会懂我的奇奇怪怪，可你却总是觉得我很怪异。", },
	[303979] = {id=303979, zh_CN="我是个很有追求的人，我的追求就是每天都有好吃的。", },
	[303980] = {id=303980, zh_CN="都说有志者事竟成，可我有这么多志向，一件都没做成。", },
	[303981] = {id=303981, zh_CN="我想成为运动员，在赛场上挥洒汗水，结果跑几步就气喘吁吁。", },
	[303982] = {id=303982, zh_CN="我和我的衣服总是不搭，穿上就像个灾难现场。", },
	[303983] = {id=303983, zh_CN="你说你会陪我走过风风雨雨，可下点小雨你就躲起来了。", },
	[303984] = {id=303984, zh_CN="我是个很有个性的人，我的个性就是和别人不一样。", },
	[303985] = {id=303985, zh_CN="都说好人有好报，可我做了这么多好事，也没见有什么好报。", },
	[303986] = {id=303986, zh_CN="我想成为魔术师，变出神奇的东西，结果把自己的道具都弄丢了。", },
	[303987] = {id=303987, zh_CN="我和我的朋友总是互相伤害，可还是离不开彼此。", },
	[303988] = {id=303988, zh_CN="你说你会理解我，可我说的话你总是左耳进右耳出。", },
	[303989] = {id=303989, zh_CN="我是个很有原则的人，我的原则就是不轻易改变原则。", },
	[303990] = {id=303990, zh_CN="都说付出就有回报，可我付出了这么多，回报在哪里？", },
