	[310649] = {id=310649, zh_CN="一位银色短发、紫色眼眸，有泪痣的人族法师，他外表高冷但内心温柔，是我的旅伴和导师。", },
	[310650] = {id=310650, zh_CN="一只会说话的黑猫，它傲娇调皮，爱恶作剧，把我选为了它的专属仆人。", },
	[310651] = {id=310651, zh_CN="种族：人族\n身份：宫廷首席法师\n样貌：银色头发，紫色眼眸，眼角有一颗泪痣，皮肤白皙，五官精致。\n性格：外表高冷，实则内心温柔，喜欢独处但渴望陪伴、\n关系：我是他在旅途中偶然救下的冒险者，现在成为他的助手兼旅伴。\n音色：清冷、略带磁性的青年男声，语速平缓。\n体型：身高偏高，柔弱消瘦。", },
	[310652] = {id=310652, zh_CN="种族：猫族\n身份：会说话的黑猫\n样貌：穿着华丽的黑猫\n性格：傲娇调皮，爱恶作剧\n关系：把我选为了它的专属仆人，跟在我身边\n音色：可爱活泼的萝莉音色", },
	[310653] = {id=310653, zh_CN="未输入角色设定，是否使用当前样貌直接生成?", },
	[310654] = {id=310654, zh_CN="请选择是否从8个种族中选择任意种族进行生成？\n如果选否则仅从当前种族生成\n（AI生成将不保留当前样貌数据）", },
	[310655] = {id=310655, zh_CN="即兴创作", },
	[310656] = {id=310656, zh_CN="双人连线", },
	[310657] = {id=310657, zh_CN="HI~嗨，很高兴遇到你。<size=35>Hey~ Nice to meet you.</size>", },
	[310658] = {id=310658, zh_CN="我们是不是在哪儿碰到过？<size=35>Have we met somewhere before?</size>", },
	[310659] = {id=310659, zh_CN="我梦到过你。<size=35>I dreamed of you.</size>", },
	[310660] = {id=310660, zh_CN="我们以前见过吧？<size=35>We've met before,right?</size>", },
	[310661] = {id=310661, zh_CN="应该没有吧～<size=35>Probably not.</size>", },
	[310662] = {id=310662, zh_CN="我在偷看你~<size=35>I'm totally sneaking glances at you~</size>", },
	[310663] = {id=310663, zh_CN="我的注意力都在你身上。<size=35>All my attention's on you.</size>", },
	[310664] = {id=310664, zh_CN="你长得很好看。<size=35>You look really nice.</size>", },
	[310665] = {id=310665, zh_CN="哇，这么突然…<size=35>Whoa,that came out of nowhere…</size>", },
	[310666] = {id=310666, zh_CN="你看起来很结实。<size=35>You look so strong.</size>", },
	[310667] = {id=310667, zh_CN="你平常会健身吗？<size=35>Do you work out a lot?</size>", },
	[310668] = {id=310668, zh_CN="你看起来很壮。<size=35>You're so buff!</size>", },
	[310669] = {id=310669, zh_CN="我喜欢炫耀我的肌肉。<size=35>I love showing off my muscles.</size>", },
	[310670] = {id=310670, zh_CN="我身上最让你心动的地方？<size=35>What's the most attractive thing about me?</size>", },
	[310671] = {id=310671, zh_CN="你喜欢我什么。<size=35>What do you like about me?</size>", },
	[310672] = {id=310672, zh_CN="你觉得我哪里最美。<size=35>Where do you think I'm the prettiest?</size>", },
	[310673] = {id=310673, zh_CN="你的眼睛。<size=35>Your eyes.</size>", },
	[310674] = {id=310674, zh_CN="你很好玩。<size=35>You're so fun.</size>", },
	[310675] = {id=310675, zh_CN="我的眼睛有点问题。<size=35>Something's wrong with my eyes…</size>", },
	[310676] = {id=310676, zh_CN="我不太舒服。<size=35>I don't feel well.</size>", },
	[310677] = {id=310677, zh_CN="怎么了？<size=35>What's wrong?</size>", },
	[310678] = {id=310678, zh_CN="我的目光没法从你身上移开。<size=35>I can't take my eyes off you.</size>", },
	[310679] = {id=310679, zh_CN="我被你吸引注意力了。<size=35>I'm totally drawn to you.</size>", },
	[310680] = {id=310680, zh_CN="我一直在看你。<size=35>I've been watching you for a while.</size>", },
	[310681] = {id=310681, zh_CN="真没想到你会这么说。<size=35>I really don't expected say that</size>", },
