	[331032] = {id=331032, zh_CN="呵，摸够没。", },
	[331033] = {id=331033, zh_CN="喂，别……", },
	[331034] = {id=331034, zh_CN="抓住可就不许松开了。", },
	[331035] = {id=331035, zh_CN="嗯？想要解开它？（笑）胆子倒不小。", },
	[331036] = {id=331036, zh_CN="很好玩？", },
	[331037] = {id=331037, zh_CN="……酥酥痒痒的，很舒服。", },
	[331038] = {id=331038, zh_CN="头发", },
	[331039] = {id=331039, zh_CN="摸脸", },
	[331040] = {id=331040, zh_CN="胸部", },
	[331041] = {id=331041, zh_CN="腹部", },
	[331042] = {id=331042, zh_CN="手", },
	[331043] = {id=331043, zh_CN="腰带", },
	[331044] = {id=331044, zh_CN="披风", },
	[331045] = {id=331045, zh_CN="诶？小子，没大没小。", },
	[331046] = {id=331046, zh_CN="呜，真是的，别把我当小猫。", },
	[331047] = {id=331047, zh_CN="当心，我的爪子很锋利。", },
	[331048] = {id=331048, zh_CN="我肚子很软？哈哈，喜欢就摸吧。", },
	[331049] = {id=331049, zh_CN="喂，你。", },
	[331050] = {id=331050, zh_CN="嗯，有点痒。", },
	[331051] = {id=331051, zh_CN="你问我是怎么双腿站立的？当然是跟人类一样啊。", },
	[331052] = {id=331052, zh_CN="腿部", },
	[331053] = {id=331053, zh_CN="要对披风猫做什么？", },
	[331054] = {id=331054, zh_CN="什么意思，你说我像青蛙王子？", },
	[331055] = {id=331055, zh_CN="要对莫迪斯做什么？", },
	[331056] = {id=331056, zh_CN="机翼", },
	[331057] = {id=331057, zh_CN="又摸，被你摸得乱成鸡窝了。", },
	[331058] = {id=331058, zh_CN="我很凶吗？哪有。", },
	[331059] = {id=331059, zh_CN="我身躯，很冰冷吧。", },
	[331060] = {id=331060, zh_CN="别看我这一副人类身躯，其实我不需要进食。", },
	[331061] = {id=331061, zh_CN="嗯？要吃我做的饭？", },
	[331062] = {id=331062, zh_CN="我看起来与人类无异，对吗？", },
	[331063] = {id=331063, zh_CN="机翼很锋利，小心别伤着手。", },
	[331064] = {id=331064, zh_CN="要对奥黛特做什么？", },
	[331065] = {id=331065, zh_CN="裙子", },
	[331066] = {id=331066, zh_CN="裙摆", },
	[331067] = {id=331067, zh_CN="呵~这是另外付费的服务哦。", },
	[331068] = {id=331068, zh_CN="亲爱的，你对我很感兴趣？", },
	[331069] = {id=331069, zh_CN="你手相看起来很招财，要不要做我的“招财猫”？", },
	[331070] = {id=331070, zh_CN="你心跳得很快，很紧张吗？", },
	[331071] = {id=331071, zh_CN="确实是很名贵的裙子，不过你若是喜欢，我也可以送你一套。", },
	[331072] = {id=331072, zh_CN="这条裙子和我很相配？呵~亲爱的多谢，（附耳低语）你也是。", },
	[331073] = {id=331073, zh_CN="肩膀", },
	[331074] = {id=331074, zh_CN="要对阿加莎做什么？", },
	[331075] = {id=331075, zh_CN="这是你表达亲密的方式吗？", },
	[331076] = {id=331076, zh_CN="抱歉，让你看到疲惫的姿态了。", },
	[331077] = {id=331077, zh_CN="抱歉……我的手很凉吗？", },
	[331078] = {id=331078, zh_CN="我的裙子很好看？谢谢。", },
	[331079] = {id=331079, zh_CN="多谢关心，我并不冷。", },
	[331080] = {id=331080, zh_CN="啊，裙子什么时候弄脏的……在阁下面前失礼了。", },
	[331081] = {id=331081, zh_CN="难道它曾经被收容所抓走，因为太能吃了，差点把收容所吃倒闭？", },
	[331082] = {id=331082, zh_CN="这些多出的食物一会儿还要分发给小弟们？", },
	[331083] = {id=331083, zh_CN="因为害怕被大家讨厌它，而一直克制吃欲，饿着肚子长大？", },
	[331084] = {id=331084, zh_CN="可以委托赚饭后，每天都暴饮暴食？", },
	[331085] = {id=331085, zh_CN="小金毛知道你一直在寻找它，所以小金毛决定帮你。", },
	[331086] = {id=331086, zh_CN="希望这颗种子能让你找到你想要的。", },
	[331087] = {id=331087, zh_CN="院内堆满了各种杂物，只有几缕阳光透过树影洒在破旧窗台上。", },
	[331088] = {id=331088, zh_CN="看到小金毛回来时，便立刻围住小金毛，警备地盯着你这个“不速之客”。", },
	[331089] = {id=331089, zh_CN="它自己则用舌头舔舐着脏兮兮的光灵，制止光灵之间的争抢行为。", },
	[331090] = {id=331090, zh_CN="而是用来养活这些无家可归的流浪光灵？", },
	[331091] = {id=331091, zh_CN="偶尔也会有光灵带些材料回来卖，减轻一些负担。", },
	[331092] = {id=331092, zh_CN="羊皮卷上画着一张地图，上面标记着一些奇怪的符号。", },
	[331093] = {id=331093, zh_CN="可能就是%PlayerName需要的情绪花种。", },
	[331094] = {id=331094, zh_CN="忽然出现的藏宝图……不知道是惊喜还是陷阱。", },
	[331095] = {id=331095, zh_CN="谨慎一点？", },
	[331096] = {id=331096, zh_CN="你转过身去，故意踩着重步离开。", },
	[331097] = {id=331097, zh_CN="你和小金毛兴高采烈地将泥土统统挖出。", },
	[331098] = {id=331098, zh_CN="小金毛奋力地狗刨着，你和它身上，都是它刨出来的泥点子。", },
	[331099] = {id=331099, zh_CN="牛皮信封已经泛黄，看上去很长时间了。", },
	[331100] = {id=331100, zh_CN="你主动转过身去，不再去查看铁盒中的内容。", },
	[331101] = {id=331101, zh_CN="小金毛叼着信封的一角……", },
	[331102] = {id=331102, zh_CN="你看到小金毛的身体周围似乎泛起了一层淡淡的光芒。", },
	[331103] = {id=331103, zh_CN="那光芒并不刺眼，却带着一种温暖的质感。", },
	[331104] = {id=331104, zh_CN="像是从它内心深处散发出来的情感力量。", },
	[331105] = {id=331105, zh_CN="你看到小金毛的身体周围似乎泛起了一层淡淡的光芒。", },
	[331106] = {id=331106, zh_CN="那光芒并不刺眼，却带着一种温暖的质感。", },
	[331107] = {id=331107, zh_CN="这颗种子形似铃兰花，通体乳白色，", },
	[331108] = {id=331108, zh_CN="时间在这座城里是环形的，就像狗追尾巴。", },
	[331109] = {id=331109, zh_CN="你看，当小狗有什么不好？", },
	[331110] = {id=331110, zh_CN="悲伤是两脚兽的毛病，狗只关心明天肉丸够不够大！", },
	[331111] = {id=331111, zh_CN="你看时机正好，便迅速离开了这只奇怪的狗狗妖灵。", },
	[331112] = {id=331112, zh_CN="没有，只是麻烦你不要这么热情，我不太适应。", },
	[331113] = {id=331113, zh_CN="小金毛转过身来，将脑袋拱入你的手心，蹭来蹭去，好不快活。", },
	[331114] = {id=331114, zh_CN="你撇过脸去，不敢看小金毛期冀的目光。", },
	[331115] = {id=331115, zh_CN="脑袋狠狠扎进它的背毛里，贪婪地满足自己“邪性”的小瘾。", },
	[331116] = {id=331116, zh_CN="那好吧，是你让我摸的哦。", },
	[331117] = {id=331117, zh_CN="揉揉圆鼓鼓的肚子，拍拍脑袋，捏捏耳朵……你与小金毛都沉浸在这一刻的惬意中。", },
	[331118] = {id=331118, zh_CN="好了好了，快离开这是非之地。", },
	[331119] = {id=331119, zh_CN="揉揉圆鼓鼓的肚子，拍拍脑袋，捏捏耳朵……你与小金毛都沉浸在这一刻的惬意中。", },
	[331120] = {id=331120, zh_CN="脑袋狠狠扎进它的背毛里，贪婪地满足自己“邪性”的小瘾。", },
	[331121] = {id=331121, zh_CN="欢迎来找小金毛委托哦，诚信经营，客单量可查。", },
	[331122] = {id=331122, zh_CN="囊括了人族高速运转的科技城厦风貌，", },
	[331123] = {id=331123, zh_CN="精灵族自然至上的乡土风情，", },
	[331124] = {id=331124, zh_CN="以及原始野性的妖灵族部落风俗，", },
	[331125] = {id=331125, zh_CN="四面环山，由精灵族的墨瞳王室管理执政……", },
	[331126] = {id=331126, zh_CN="酥脆奶香的碳烤面包夹上清脆可口的翡翠菜心，搭配上龙息菇熬制的辣酱。", },
	[331127] = {id=331127, zh_CN="光是想想小金毛就要流口水啦！", },
	[331128] = {id=331128, zh_CN="可以不再为了给光灵洗澡而搞得焦头烂额，", },
	[331129] = {id=331129, zh_CN="是为了给自己和光灵们更好的生活呀！", },
	[331130] = {id=331130, zh_CN="屋院空荡荡的，我也会害怕的。", },
	[331131] = {id=331131, zh_CN="疼痛瞬间袭来，委托单洋洋洒洒飘落在地上，小金毛坐在地上用前爪揉了揉红肿的脑袋。", },
	[331132] = {id=331132, zh_CN="一想到要对着委托人真挚期盼的目光说出拒绝的话语，小金毛就喘不过气来，就想要逃跑！", },
	[331133] = {id=331133, zh_CN="一人一狗一同咬开溢出肉汁的烤肠，胡椒洒满的肉香带着一股幸福的味道。", },
	[331134] = {id=331134, zh_CN="头顶几朵寒豆兰随风坠落，似蝴蝶翩跹。", },
	[331135] = {id=331135, zh_CN="小金毛轻叹一口气，", },
	[331136] = {id=331136, zh_CN="靠着野花堆缓缓瘫成一团毛球，", },
	[331137] = {id=331137, zh_CN="打了一个响亮的喷嚏。", },
	[331138] = {id=331138, zh_CN="千年春色献君。", },
	[331139] = {id=331139, zh_CN="这是？", },
	[331140] = {id=331140, zh_CN="它在你的指导下，挑出各色鲜花，组成它想要承载在春色中的寄语。", },
	[331141] = {id=331141, zh_CN="草丛在它狗爪的扒挠下，泥巴被翻起，草叶被搅得七零八落。", },
	[331142] = {id=331142, zh_CN="小金毛被围在中间，群战舌儒。", },
	[331143] = {id=331143, zh_CN="那些光灵就该统统抓起来！", },
	[331144] = {id=331144, zh_CN="在城镇里到处乱拉乱尿，", },
	[331145] = {id=331145, zh_CN="城镇被那些光灵糟蹋得臭气轰天。", },
	[331146] = {id=331146, zh_CN="他们没有进化，", },
	[331147] = {id=331147, zh_CN="你们根本没有给光灵保留在城市居住的权利。", },
	[331148] = {id=331148, zh_CN="不肯接受一个明显更好的方案？", },
	[331149] = {id=331149, zh_CN="固执？是你自己太自信，", },
	[331150] = {id=331150, zh_CN="不愿意接受别人的意见吧！", },
	[331151] = {id=331151, zh_CN="猫爪不断挥舞，锋利的指甲在狗的毛发中划过，发出轻微的“嘶嘶”声。", },
	[331152] = {id=331152, zh_CN="狗也不示弱，用嘴巴轻轻咬住猫的后腿。", },
	[331153] = {id=331153, zh_CN="你这么关心光灵，", },
	[331154] = {id=331154, zh_CN="为什么不做好光灵的管理呢？", },
	[331155] = {id=331155, zh_CN="糟了！巡逻车！", },
	[331156] = {id=331156, zh_CN="两道影子仓皇翻过城墙，惊起夜栖的麻雀。", },
	[331157] = {id=331157, zh_CN="月光把追逐的剪影投在百年砖墙上，", },
	[331158] = {id=331158, zh_CN="小金毛灵机一动，转过身用尾巴轻柔又迅速扫去地上的花瓣，生怕弄脏怀里的花。", },
	[331159] = {id=331159, zh_CN="听奶奶说，锦旗是大家联名送给%PlayerName和小金毛的！", },
	[331160] = {id=331160, zh_CN="整片瓦砾突然塌陷，发出清脆的断裂声惊动了远处隐匿的眼睛，反光的眼瞳迅速消失在草丛中。", },
	[331161] = {id=331161, zh_CN="你睡在小金毛起伏的肚腹上，伸爪对着小金毛挠来挠去，表示着不满！", },
	[331162] = {id=331162, zh_CN="你睡在小金毛起伏的肚腹上，伸爪对着小金毛挠来挠去，表示着不满！", },
	[331163] = {id=331163, zh_CN="好吧！小金毛接受邀请。", },
	[331164] = {id=331164, zh_CN="汪！", },
	[331165] = {id=331165, zh_CN="“千年春色献故人”任务完成，与小金毛达成搭档关系。", },
	[331166] = {id=331166, zh_CN="“又是一年春”任务完成，与小金毛达成人外契约关系。", },
	[331167] = {id=331167, zh_CN="“又是一年春”任务完成。", },
	[331168] = {id=331168, zh_CN="“社区辩论赛”任务完成，与小金毛达成宿敌挚友关系。", },
	[331169] = {id=331169, zh_CN="散发着柔和的光芒。", },
	[332000] = {id=332000, zh_CN="头部", },
	[332001] = {id=332001, zh_CN="前肢", },
	[332002] = {id=332002, zh_CN="后肢", },
	[332003] = {id=332003, zh_CN="尾巴粗细", },
	[332004] = {id=332004, zh_CN="尾巴长短", },
	[332005] = {id=332005, zh_CN="整体大小", },
	[332006] = {id=332006, zh_CN="尾鳍", },
	[332007] = {id=332007, zh_CN="鱼鳍", },
