	[340000] = {id=340000, zh_CN="点燃蜡烛", },
	[340001] = {id=340001, zh_CN="配置泉水", },
	[340002] = {id=340002, zh_CN="找到草莓蛋糕", },
	[340003] = {id=340003, zh_CN="找到巧克力慕斯", },
	[340004] = {id=340004, zh_CN="找到巧克力奶油蛋糕", },
	[340005] = {id=340005, zh_CN="解读真名1", },
	[340006] = {id=340006, zh_CN="解读真名2", },
	[340007] = {id=340007, zh_CN="解读真名3", },
	[340008] = {id=340008, zh_CN="点燃壁炉", },
	[340009] = {id=340009, zh_CN="打开宝箱1", },
	[340010] = {id=340010, zh_CN="打开宝箱2", },
	[340011] = {id=340011, zh_CN="砍苹果树枝1", },
	[340012] = {id=340012, zh_CN="砍苹果树枝2", },
	[340013] = {id=340013, zh_CN="清除藤蔓1", },
	[340014] = {id=340014, zh_CN="清除藤蔓2", },
	[340015] = {id=340015, zh_CN="熬制大蒜汤", },
	[340016] = {id=340016, zh_CN="拓印壁画1", },
	[340017] = {id=340017, zh_CN="拓印壁画2", },
	[340018] = {id=340018, zh_CN="捡拾银器", },
	[340019] = {id=340019, zh_CN="擦净预言镜", },
	[340020] = {id=340020, zh_CN="把驱魔方位的熄灭烛台重新点燃，驱散魂影……", },
	[340021] = {id=340021, zh_CN="舀起泉水，喷向恶魔，叫他在滋滋作响中化作灰烬吧。", },
	[340022] = {id=340022, zh_CN="找到幽灵猫最喜欢的草莓蛋糕，喂饱它的肚子，安抚它的灵魂……", },
	[340023] = {id=340023, zh_CN="找到幽灵猫最喜欢的巧克力慕斯，喂饱它的肚子，安抚它的灵魂……", },
	[340024] = {id=340024, zh_CN="找到幽灵猫最喜欢的巧克力奶油蛋糕，喂饱它的肚子，安抚它的灵魂……", },
	[340025] = {id=340025, zh_CN="寻找旧日书籍，揭示祂的真名，暴露真名的恶魔不足为惧。", },
	[340026] = {id=340026, zh_CN="寻找旧日书籍，揭示祂的真名，暴露真名的恶魔不足为惧。", },
	[340027] = {id=340027, zh_CN="寻找旧日书籍，揭示祂的真名，暴露真名的恶魔不足为惧。", },
	[340028] = {id=340028, zh_CN="火焰燃起时，驱散身上的寒意，在温暖中与伙伴会合。", },
	[340029] = {id=340029, zh_CN="宝箱中或许有恶魔千年的财宝，勿贪心，小心成为恶魔的“新藏品”。", },
