	[410000] = {id=410000, zh_CN="序章·启程", },
	[410001] = {id=410001, zh_CN="一片漆黑，仿佛耽于温暖的茧中。", },
	[410002] = {id=410002, zh_CN="静谧中，你的烦恼化作三束微光……", },
	[410003] = {id=410003, zh_CN="微光闪烁，唤起你的记忆。", },
	[410004] = {id=410004, zh_CN="这些瞬间，你是否也曾经历过？", },
	[410005] = {id=410005, zh_CN="疲惫的社交？", },
	[410006] = {id=410006, zh_CN="或许是永无止境的工作群聊……", },
	[410007] = {id=410007, zh_CN="或许是成为人群中的无声孤岛……", },
	[410008] = {id=410008, zh_CN="无趣的日常？", },
	[410009] = {id=410009, zh_CN="或许是日复一日的走过的街景……", },
	[410010] = {id=410010, zh_CN="或许是窗外永远灰蒙蒙的天空……", },
	[410011] = {id=410011, zh_CN="信息洪流后的空虚？", },
	[410012] = {id=410012, zh_CN="手指无意识地滑动，屏幕熄灭……", },
	[410013] = {id=410013, zh_CN="茫然与空虚悄然漫上心头……", },
	[410014] = {id=410014, zh_CN="种种记忆如潮水般涌来，", },
	[410015] = {id=410015, zh_CN="令人倦怠后，又迅速褪去。", },
	[410016] = {id=410016, zh_CN="如果可以逃离这一切！", },
	[410017] = {id=410017, zh_CN="如果能逃离这一切，该多好啊……", },
	[410018] = {id=410018, zh_CN="触摸屏幕。", },
	[410019] = {id=410019, zh_CN="记忆的潮水退去，", },
	[410020] = {id=410020, zh_CN="周围的黑暗旋转扭曲……", },
	[410021] = {id=410021, zh_CN="新的旅程，开始了！", },
	[410022] = {id=410022, zh_CN="欢迎抵达银河制片厂——米乐星球！", },
	[410023] = {id=410023, zh_CN="你困惑地环顾四周。", },
	[410024] = {id=410024, zh_CN="风格奇特的建筑……", },
	[410025] = {id=410025, zh_CN="空气中漂浮的微光尘埃……", },
	[410026] = {id=410026, zh_CN="查看自己。", },
	[410027] = {id=410027, zh_CN="你观察到并不是你自己的身躯。", },
	[410028] = {id=410028, zh_CN="我是谁！我……这是在哪？", },
	[410029] = {id=410029, zh_CN="穿越：来到新世界", },
	[410030] = {id=410030, zh_CN="寻找创造的伙伴，与他对话。", },
	[410031] = {id=410031, zh_CN="触摸屏幕，前往米乐星球。", },
	[410032] = {id=410032, zh_CN="探索房间，寻找信息。探索房间", },
	[410033] = {id=410033, zh_CN="探索房间", },
	[410034] = {id=410034, zh_CN="点击查看发光的信", },
	[410035] = {id=410035, zh_CN="宝箱", },
	[410036] = {id=410036, },
	[410037] = {id=410037, zh_CN="猫乐园", },
	[410038] = {id=410038, zh_CN="似乎有什么热闹的事情？", },
	[410039] = {id=410039, },
	[410040] = {id=410040, zh_CN="我这是……穿越了？", },
	[410041] = {id=410041, zh_CN="你试图理清思绪，此时你注意到一封信。", },
	[410042] = {id=410042, zh_CN="你走近，地上躺着一封散发光芒的信封。", },
	[410043] = {id=410043, zh_CN="探索房间。", },
	[410044] = {id=410044, zh_CN="转动视角，移动查看房间情况。", },
	[410045] = {id=410045, zh_CN="结识一位新朋友", },
	[410046] = {id=410046, zh_CN="真相只有……什么来着？", },
	[410047] = {id=410047, zh_CN="给原主的？", },
	[410048] = {id=410048, zh_CN="还是拆开看看吧。", },
	[410049] = {id=410049, zh_CN="搞清楚怎么回事。", },
	[410050] = {id=410050, zh_CN="给我的？", },
	[410051] = {id=410051, zh_CN="穿越者的标准福利？", },
	[410052] = {id=410052, zh_CN="打开看看吧。", },
	[410053] = {id=410053, zh_CN="点击查看发光的信。", },
	[410054] = {id=410054, zh_CN="米乐博士的信：", },
	[410055] = {id=410055, zh_CN="嘿，我亲爱的孩子！", },
	[410056] = {id=410056, zh_CN="当你读到这封信，说明爷爷我的小发明成功啦！", },
	[410057] = {id=410057, zh_CN="我自作主张，邀请你来“米乐星球”度个假。", },
	[410058] = {id=410058, zh_CN="这里是个特别的地方！你那些天马行空的白日梦，在这里是最珍贵的宝藏，也是你强大的力量源泉。", },
	[410059] = {id=410059, zh_CN="我希望你在这里可以疗愈生活的不快和压力，重新找到快乐和勇气。拾起面对困境的心气儿！", },
	[410060] = {id=410060, zh_CN="第一步总是最难迈出的。但别担心，有我陪着你。", },
	[410061] = {id=410061, zh_CN="我为你准备了一位向导。他会陪你探索、创造，结交超棒的新朋友。", },
	[410062] = {id=410062, zh_CN="勇敢地去体验这一切吧！", },
	[410063] = {id=410063, zh_CN="——爱你的爷爷：米乐博士。", },
	[410064] = {id=410064, zh_CN="新伙伴：缔造专属向导！", },
	[410065] = {id=410065, zh_CN="信封上的光芒飞散。", },
	[410066] = {id=410066, zh_CN="凝聚成一只圆滚滚的浮游生物。", },
	[410067] = {id=410067, zh_CN="你好呀，%PlayerName。我叫云团！", },
	[410068] = {id=410068, zh_CN="是米乐博士的助手！", },
	[410069] = {id=410069, zh_CN="欢迎来到充满无限可能的米乐星球~", },
	[410070] = {id=410070, zh_CN="会说话的浮游生物……", },
	[410071] = {id=410071, zh_CN="在这里。", },
	[410072] = {id=410072, zh_CN="一位可靠且独特的伙伴，将会是你最好的旅伴。", },
	[410073] = {id=410073, zh_CN="将会是你最好的旅伴哦！", },
	[410074] = {id=410074, zh_CN="他可以陪你探索未知，为你分担工作。", },
	[410075] = {id=410075, zh_CN="也会当你的小信使，和你聊天解闷。", },
	[410076] = {id=410076, zh_CN="甚至在你灵感枯竭时，帮你“噗”地点亮小火花！", },
	[410077] = {id=410077, zh_CN="帮你“噗”地点亮小火花！", },
	[410078] = {id=410078, zh_CN="还有其他功能吗？", },
	[410079] = {id=410079, zh_CN="有哦！", },
	[410080] = {id=410080, zh_CN="但更多的奇妙功能，就等你和他一起去发现吧。", },
	[410081] = {id=410081, zh_CN="我迫不及待要见到他了！", },
	[410082] = {id=410082, zh_CN="太好了！", },
	[410083] = {id=410083, zh_CN="不不不，我只是博士的助手。", },
	[410084] = {id=410084, zh_CN="不不不！", },
	[410085] = {id=410085, zh_CN="伙伴都是独一无二的，由你亲手定义。", },
	[410086] = {id=410086, zh_CN="来吧，想象你心中最棒的伙伴是什么样子！", },
	[410087] = {id=410087, zh_CN="与云团互动，点击创建角色。", },
	[410088] = {id=410088, zh_CN="进入伙伴创角界面，选择种族、外形、性格、声音……", },
	[410089] = {id=410089, zh_CN="哇，一个全新的生命因你而诞生。", },
	[410090] = {id=410090, zh_CN="从今往后，你们是一起生活的伙伴了~", },
	[410091] = {id=410091, zh_CN="他已经迫不及待想要与你见面了。", },
	[410092] = {id=410092, zh_CN="去和他打个招呼吧！", },
	[410093] = {id=410093, zh_CN="点击互动，与原创伙伴对话。", },
	[410094] = {id=410094, zh_CN="（交互界面-闲聊）", },
	[410095] = {id=410095, zh_CN="小向导，接下来去哪？", },
	[410096] = {id=410096, zh_CN="太好了，你已经迫不及待要冒险了吗？", },
	[410097] = {id=410097, zh_CN="让我先带你熟悉一下星球的基础环境吧！", },
	[410098] = {id=410098, zh_CN="第一站，我们去看起来充满生机的——鸭湖城堡！", },
	[410099] = {id=410099, zh_CN="点击伙伴跟随，一同去鸭湖城堡看看新星球的“生机”吧。", },
	[410100] = {id=410100, zh_CN="开荒新星球！", },
	[410101] = {id=410101, zh_CN="抵达鸭湖城堡。", },
	[410102] = {id=410102, zh_CN="这里的生物……长得都很有创意。", },
	[410103] = {id=410103, zh_CN="%PlayerName，米乐博士给你发来了新邮件！", },
	[410104] = {id=410104, zh_CN="请注意查收！", },
	[410105] = {id=410105, zh_CN="打开邮件看看。", },
	[410106] = {id=410106, zh_CN="米乐博士的第二封信：", },
	[410107] = {id=410107, zh_CN="孩子，看你出来探索，我真高兴！", },
	[410108] = {id=410108, zh_CN="我查看你的坐标，发现你已经探索到了鸭湖城堡。", },
	[410109] = {id=410109, zh_CN="米乐星球上有很多可爱的小光灵,他们会成为你的超级帮手。", },
	[410110] = {id=410110, zh_CN="我给你准备了几个小道具,已经拜托云团送到你的背包里啦。", },
	[410111] = {id=410111, zh_CN="继续往前探索吧。", },
	[410112] = {id=410112, zh_CN="具体怎么操作，等你捕捉到第一位光灵朋友，我再细说。", },
	[410113] = {id=410113, zh_CN="我给你准备了几个小道具，已经拜托云团送到你的背包里啦！", },
	[410114] = {id=410114, zh_CN="去试试吧！", },
	[410115] = {id=410115, zh_CN="亲爱的爷爷：米乐博士", },
	[410116] = {id=410116, zh_CN="前往湖边，捕捉蕉绿鸭。", },
	[410117] = {id=410117, zh_CN="看！湖边一直嘀嘀咕咕的小黄鸭们就是蕉绿鸭。", },
	[410118] = {id=410118, zh_CN="我们一起找找附近的蕉绿鸭吧~", },
	[410119] = {id=410119, zh_CN="在右下角的快捷道具中即可装备精灵球。", },
	[410120] = {id=410120, zh_CN="对准蕉绿鸭投掷精灵球就能抓到啦~", },
	[410121] = {id=410121, zh_CN="目标确认！", },
	[410122] = {id=410122, zh_CN="在右下角的快捷道具中即可装备精灵球。", },
	[410123] = {id=410123, zh_CN="轻轻地、准确地对准他投掷出去吧！", },
	[410124] = {id=410124, zh_CN="精灵球投掷教学：快捷道具—装备精灵球—移动准星，对准蕉绿鸭—投掷精灵球。", },
	[410125] = {id=410125, zh_CN="成功捕捉到第一位光灵伙伴~", },
	[410126] = {id=410126, zh_CN="小奶酪", },
	[410127] = {id=410127, zh_CN="现在点击伙伴跟随，让蕉绿鸭加入我们的开荒队伍吧！", },
	[410128] = {id=410128, zh_CN="未来，你可以邀请20位伙伴同行。", },
	[410129] = {id=410129, zh_CN="可以组成一支威风凛凛的队伍呢！", },
	[410130] = {id=410130, zh_CN="继续探索。", },
	[410131] = {id=410131, zh_CN="剧团成员", },
	[410132] = {id=410132, },
	[410133] = {id=410133, },
	[410134] = {id=410134, zh_CN="前往最近的蓝调餐厅看看吧。", },
	[410135] = {id=410135, zh_CN="那里有很多有趣的人和事，说不定会遇到活动呢~", },
	[410136] = {id=410136, },
	[410137] = {id=410137, zh_CN="继续探索。", },
	[410138] = {id=410138, zh_CN="前往蓝调餐厅。", },
	[410139] = {id=410139, zh_CN="月影商会回馈新老朋友，幸运大放送！", },
	[410140] = {id=410140, zh_CN="无需成本，仅需一点运气！", },
	[410141] = {id=410141, zh_CN="%PlayerName，那个摊位看起来很热闹.", },
	[410142] = {id=410142, zh_CN="似乎有什么活动，去看看吧。", },
	[410143] = {id=410143, },
	[410144] = {id=410144, zh_CN="和奥黛特互动对话。", },
	[410145] = {id=410145, zh_CN="哦？一位新面孔。", },
	[410146] = {id=410146, zh_CN="看您气度不凡，想必是位幸运之人！", },
	[410147] = {id=410147, zh_CN="要不要来试试手气？", },
	[410148] = {id=410148, zh_CN="参加月影商会的回馈活动——幸运大放送！", },
	[410149] = {id=410149, zh_CN="有什么奖励吗？", },
	[410150] = {id=410150, zh_CN="听起来很有趣！", },
	[410151] = {id=410151, zh_CN="具体有什么奖励呢？", },
	[410152] = {id=410152, zh_CN="奖励是限量工艺礼袋。", },
	[410153] = {id=410153, zh_CN="那失败呢？", },
	[410154] = {id=410154, zh_CN="失败也会获得一份参与奖。", },
	[410155] = {id=410155, zh_CN="是美味的牛奶粥一份哦。", },
	[410156] = {id=410156, zh_CN="怎么个试法？", },
	[410157] = {id=410157, zh_CN="掷一次幸运星骰即可。", },
	[410158] = {id=410158, zh_CN="点数决定一切！", },
	[410159] = {id=410159, zh_CN="怎么样，要试试看吗？", },
	[410160] = {id=410160, zh_CN="说不定头奖就是您的。", },
	[410161] = {id=410161, zh_CN="免费的吗？", },
	[410162] = {id=410162, zh_CN="完全免费的哦。", },
	[410163] = {id=410163, zh_CN="不会亏本吗？", },
	[410164] = {id=410164, zh_CN="为新朋友投资一点幸运资金。", },
	[410165] = {id=410165, zh_CN="这可是笔划算的长期买卖。", },
	[410166] = {id=410166, zh_CN="要试试看吗？", },
	[410167] = {id=410167, zh_CN="我看到幸运女神在向您微笑呢。", },
	[410168] = {id=410168, zh_CN="我要试试！", },
	[410169] = {id=410169, zh_CN="那么，请掷出骰子吧。", },
	[410170] = {id=410170, zh_CN="哇哦，您就是我一直在等到的幸运之星！", },
	[410171] = {id=410171, zh_CN="这份限量工艺礼袋的奖励送给你。", },
	[410172] = {id=410172, zh_CN="愿这份好运陪伴您一整天！", },
	[410173] = {id=410173, zh_CN="很不错的点数！", },
	[410174] = {id=410174, zh_CN="看来好运常伴你左右。", },
	[410175] = {id=410175, zh_CN="这份限量工艺礼袋的奖励送给你。", },
	[410176] = {id=410176, zh_CN="愿这份好运陪伴您一整天！", },
	[410177] = {id=410177, zh_CN="没关系，幸运偶尔也喜欢与我们捉迷藏。", },
	[410178] = {id=410178, zh_CN="这是您的参与奖，一份牛奶粥。", },
	[410179] = {id=410179, zh_CN="希望它能温暖您的一天。", },
	[410180] = {id=410180, zh_CN="话音刚落，空中闪过的光点聚落在你的手心。", },
	[410181] = {id=410181, zh_CN="这是？", },
	[410182] = {id=410182, zh_CN="光点缓缓凝聚出一颗绣球。", },
	[410183] = {id=410183, zh_CN="这是由你的力量凝结的情绪种子。", },
	[410184] = {id=410184, zh_CN="你将收获的喜悦与慷慨的心意，凝聚成了绣球种子。", },
	[410185] = {id=410185, zh_CN="我……拥有了魔法？", },
	[410186] = {id=410186, zh_CN="魔法？这确实是银河制片厂独有的魔法。", },
	[410187] = {id=410187, zh_CN="如果想要更进一步了解凝结情绪的能力。", },
	[410188] = {id=410188, zh_CN="去花海转转吧，那里有正在找灵感的剧团成员。", },
	[410189] = {id=410189, zh_CN="他会给予你满意的答案。", },
	[410190] = {id=410190, zh_CN="谢谢你的解答。", },
	[410191] = {id=410191, zh_CN="您满意就好。", },
	[410192] = {id=410192, zh_CN="希望这份小插曲，能让您的旅途有个愉快的开端。", },
	[410193] = {id=410193, zh_CN="前往电影厂。", },
	[410194] = {id=410194, zh_CN="与电影厂外的剧团成员对话。", },
	[410195] = {id=410195, zh_CN="向剧团成员展示绣球种族，询问情绪种子。", },
	[410196] = {id=410196, zh_CN="你好。", },
	[410197] = {id=410197, zh_CN="展示绣球种子。", },
	[410198] = {id=410198, zh_CN="你好，我想了解情绪种子。", },
	[410199] = {id=410199, zh_CN="这颗绣球种子这是你凝聚出来的吗？", },
	[410200] = {id=410200, zh_CN="是的。", },
	[410201] = {id=410201, zh_CN="哇，真了不起！", },
	[410202] = {id=410202, zh_CN="你是……？", },
	[410203] = {id=410203, zh_CN="我是银河制片厂的剧团成员。", },
	[410204] = {id=410204, zh_CN="你想要加入我们吗？", },
	[410205] = {id=410205, zh_CN="制片厂？剧团？", },
	[410206] = {id=410206, zh_CN="剧团是一个旨在通过创作影片传递情绪、分享故事的亚文化组织。", },
	[410207] = {id=410207, zh_CN="别被复杂的前缀吓到，剧团准备了非常便捷的工具。", },
	[410208] = {id=410208, zh_CN="即便是零基础，只需要输入文字，就能创作出一部短片。", },
	[410209] = {id=410209, zh_CN="试试看吗？", },
	[410210] = {id=410210, zh_CN="文字成片。", },
	[410211] = {id=410211, zh_CN="输入文字，生成影片。", },
	[410212] = {id=410212, zh_CN="展示成片。", },
	[410213] = {id=410213, zh_CN="不错的开始。", },
	[410214] = {id=410214, zh_CN="现在你想更深入地了解一下我们吗？", },
	[410215] = {id=410215, zh_CN="关于情绪种子。", },
	[410216] = {id=410216, zh_CN="情绪种子，是从真挚的情感互动中诞生的奇迹。", },
	[410217] = {id=410217, zh_CN="它是剧团创作的源泉，也是制片厂运作的核心能量。", },
	[410218] = {id=410218, zh_CN="米乐星球上有一部分居民会受到制片厂的影响。", },
	[410219] = {id=410219, zh_CN="拥有凝聚情绪种子的能力。", },
	[410220] = {id=410220, zh_CN="关于剧团。", },
	[410221] = {id=410221, zh_CN="米乐星球有超多剧团。", },
	[410222] = {id=410222, zh_CN="剧团是由一群志同道合的朋友组成的社区。", },
	[410223] = {id=410223, zh_CN="大家分工合作，负责导演，编剧，道具，制片，演员……", },
	[410224] = {id=410224, zh_CN="会很有意思的。", },
	[410225] = {id=410225, zh_CN="关于创作影片。", },
	[410226] = {id=410226, zh_CN="你可以在我身后的银河制片厂，创作你的故事。", },
	[410227] = {id=410227, zh_CN="从写剧本、搭场景到指挥、拍摄，整个过程都充满乐趣。", },
	[410228] = {id=410228, zh_CN="哪怕你是“光杆司令”，也能指挥你的光灵，拍出精彩的作品呢。", },
	[410229] = {id=410229, zh_CN="明白了，是一个“白日做梦”合法的地方。", },
	[410230] = {id=410230, zh_CN="那你想要尝试哪方面的创作呢？", },
	[410231] = {id=410231, zh_CN="导演", },
	[410232] = {id=410232, zh_CN="片场指挥全局的导演吗？", },
	[410233] = {id=410233, zh_CN="能想象你喊“Action”时的帅气样子了！", },
	[410234] = {id=410234, zh_CN="编剧", },
	[410235] = {id=410235, zh_CN="期待你笔下诞生的故事！", },
	[410236] = {id=410236, zh_CN="告诉你一个小秘诀，制片厂有可爱的光灵编剧可以合作哦~", },
	[410237] = {id=410237, zh_CN="制片", },
	[410238] = {id=410238, zh_CN="选择搭建片场吗？", },
	[410239] = {id=410239, zh_CN="成为导演，演员背后的人，很酷的选择！", },
	[410240] = {id=410240, zh_CN="演员", },
	[410241] = {id=410241, zh_CN="剧团成员：剧团的灯光都将为你而亮！", },
	[410242] = {id=410242, zh_CN="全能一体机！", },
	[410243] = {id=410243, zh_CN="自己就是一支队伍！", },
	[410244] = {id=410244, zh_CN="真是令人敬仰的职业规划！", },
	[410245] = {id=410245, zh_CN="我还没想好。", },
	[410246] = {id=410246, zh_CN="完全不用急！探索本身也是乐趣。", },
	[410247] = {id=410247, zh_CN="随时欢迎你来尝试不同角色。", },
	[410248] = {id=410248, zh_CN="无论选择哪条路，尝试创作就是最大的快乐。", },
	[410249] = {id=410249, zh_CN="随时欢迎你来制片厂和剧团玩！", },
	[410250] = {id=410250, zh_CN="解锁社团系统", },
	[410251] = {id=410251, zh_CN="咕噜噜……咕……", },
	[410252] = {id=410252, zh_CN="嘎嘎嘎，我的肚子都在抗议啦。", },
	[410253] = {id=410253, zh_CN="蕉绿鸭提醒我们，该关注一下它的状态了。", },
	[410254] = {id=410254, zh_CN="随时关注伙伴的饥饿、健康、理智情况，才能让伙伴更有活力。", },
	[410255] = {id=410255, zh_CN="查看蕉绿鸭状态", },
	[410256] = {id=410256, zh_CN="与蕉绿鸭互动，点击查看详情。", },
	[410257] = {id=410257, zh_CN="果然，饥饿值快见底了。", },
	[410258] = {id=410258, zh_CN="得想办法解决它的用餐问题了。", },
	[410259] = {id=410259, zh_CN="解锁社团与工作台", },
	[410260] = {id=410260, zh_CN="正好，我刚才收到通知。", },
	[410261] = {id=410261, zh_CN="我们获得了加入或创建社团的资格。", },
	[410262] = {id=410262, zh_CN="社团里就有现成的工作台可以做饭。", },
	[410263] = {id=410263, zh_CN="我们去社团看看，解决吃饭问题要紧。", },
