	[410484] = {id=410484, zh_CN="小奶酪品尝，惊吓晕倒", },
	[410485] = {id=410485, zh_CN="小奶酪品尝，满足微笑", },
	[410486] = {id=410486, zh_CN="小奶酪品尝，惊喜跳起", },
	[410487] = {id=410487, zh_CN="素材都选好了。让我们看看最终的效果如何。", },
	[410488] = {id=410488, zh_CN="一键成片。", },
	[410489] = {id=410489, zh_CN="哇，里面有我耶。", },
	[410490] = {id=410490, zh_CN="看起来很不错，我可以保存一份吗？", },
	[410491] = {id=410491, zh_CN="当然可以，你是主角呀。", },
	[410492] = {id=410492, zh_CN="恭喜您踏出了制作短片的第一步。", },
	[410493] = {id=410493, zh_CN="无论记录得如何，这份回忆都是独一无二的珍宝。", },
	[410494] = {id=410494, zh_CN="今天真是高效而充实的一天。", },
	[410495] = {id=410495, zh_CN="帮助朋友、拍摄短片、还赚到了外快~", },
	[410496] = {id=410496, zh_CN="叮咚~米乐博士来信了。", },
	[410497] = {id=410497, zh_CN="爷爷的第三封信：", },
	[410498] = {id=410498, zh_CN="嘿，我亲爱的孩子：", },
	[410499] = {id=410499, zh_CN="看到你亲手记录下美好的瞬间，我真为你高兴。", },
	[410500] = {id=410500, zh_CN="祝贺你掌握了一个新的能力。", },
	[410501] = {id=410501, zh_CN="记住，在这个星球，每一个角色，他们的故事、他们的情感都是一座灵感的宝库。", },
	[410502] = {id=410502, zh_CN="运用这份能力，将亲身经历的故事拍摄下来，将转瞬即逝的心情定格下来。", },
	[410503] = {id=410503, zh_CN="希望你在制片厂，能记录下更多属于你的珍贵回忆。", },
	[410504] = {id=410504, zh_CN="——爱你的爷爷：米乐博士", },
	[410505] = {id=410505, zh_CN="剧团协会来信", },
	[410506] = {id=410506, zh_CN="制片厂权限开放通知", },
	[410507] = {id=410507, zh_CN="致我们才华横溢的%PlayerName：", },
	[410508] = {id=410508, zh_CN="你的首部视频日志我们已欣赏，其中蕴含的轻松与快乐令人印象深刻。", },
	[410509] = {id=410509, zh_CN="为此，我们很高兴能为你开放银河制片厂的完整权限。", },
	[410510] = {id=410510, zh_CN="一个优秀的制片人需要学习如何调配自己的资源——金币、伙伴还有乍现的灵感，缺一不可。", },
	[410511] = {id=410511, zh_CN="世界已在你的镜头之下，请尽情探索吧。", },
	[410512] = {id=410512, zh_CN="——银河制片厂剧团协会", },
	[410513] = {id=410513, zh_CN="爷爷的第四封封信：", },
	[410514] = {id=410514, zh_CN="嘿，我亲爱的孩子：", },
	[410515] = {id=410515, zh_CN="来信想告诉你，你现实世界的一切我都照料得很好，生机勃勃，井井有条。", },
	[410516] = {id=410516, zh_CN="所以，请完全安心地待在米乐星球吧。", },
	[410517] = {id=410517, zh_CN="去创作，去结交朋友，去感受美好的情绪，去体会快乐与幸福。", },
	[410518] = {id=410518, zh_CN="爷爷会一直在这里，等你带着故事回来。", },
	[410519] = {id=410519, zh_CN="——爱你的爷爷：米乐博士", },
	[410520] = {id=410520, zh_CN="致%PlayerName:", },
	[410521] = {id=410521, zh_CN="感谢你为米乐星球带来的每一次欢声笑语与每一份温暖的记录。", },
	[410522] = {id=410522, zh_CN="你的到来，是米乐博士赠予这片星空最棒的礼物。", },
	[410523] = {id=410523, zh_CN="为此，我们想举办一场小小的舞会举杯纪念这份美好的回忆。", },
	[410524] = {id=410524, zh_CN="真诚地希望你能前来。", },
	[410525] = {id=410525, zh_CN="——银河制片厂剧团协会", },
	[410526] = {id=410526, zh_CN="按照舞会的惯例，大家会收到一些……心意的回响。", },
	[410527] = {id=410527, zh_CN="或许可以送给那位你特别喜欢的朋友？", },
	[410528] = {id=410528, zh_CN="哦，舞池中央很热闹嘛~", },
	[410529] = {id=410529, zh_CN="你想邀请谁做你的舞伴呢？", },
	[410530] = {id=410530, zh_CN="音乐似乎渐渐慢了。", },
	[410531] = {id=410531, zh_CN="一场很愉快的派对，不是吗？", },
	[410532] = {id=410532, zh_CN="看来你在米乐星球的生活，已经稳稳地迈出了第一步。", },
	[410533] = {id=410533, zh_CN="准备好开始你的故事了吗？", },
	[410534] = {id=410534, zh_CN="无论你去哪里，我都会陪伴在你身边的。", },
	[410535] = {id=410535, zh_CN="舞会邀请函", },
	[410536] = {id=410536, zh_CN="古堡聚会邀请函", },
	[410537] = {id=410537, zh_CN="亲爱的%PlayerName:", },
	[410538] = {id=410538, zh_CN="为帮助每位成员更好地理解角色与情感，剧团内部组织内部组织了个聚会游戏。", },
	[410539] = {id=410539, zh_CN="当红月攀上尖顶，迷雾笼罩回廊，古堡的钟声自会为你引路。", },
	[410540] = {id=410540, zh_CN="一场关于谎言与真实的游戏即将开场。", },
	[410541] = {id=410541, zh_CN="祝你……玩得愉快。", },
	[410542] = {id=410542, zh_CN="——银河制片厂剧团协会", },
	[410543] = {id=410543, zh_CN="舞曲响起，邀请你心中的那位舞伴，共舞一曲，为今夜画上句号。\n查看爷爷的来信。", },
	[410544] = {id=410544, zh_CN="你找到了一瓶牛奶。", },
	[410545] = {id=410545, zh_CN="你找到了一袋精致面粉。", },
	[410546] = {id=410546, zh_CN="你找到了一些木莓。", },
	[410547] = {id=410547, zh_CN="你找到了一罐蜂蜜。", },
	[410548] = {id=410548, zh_CN="你找到了一袋黑麦粉。", },
	[410549] = {id=410549, zh_CN="与跟随的伙伴对话，查收查收舞会邀请函。", },
	[410550] = {id=410550, zh_CN="与跟随的伙伴对话，讨论关于小奶酪的事。", },
	[410551] = {id=410551, zh_CN="时光放映屋", },
	[420000] = {id=420000, zh_CN="启程", },
	[420001] = {id=420001, zh_CN="触摸屏幕，前往米乐星球。", },
	[420002] = {id=420002, zh_CN="耽于黑暗，奇怪的声音响起，前往无压的新星球——米乐星球吧。\n触摸屏幕，前往米乐星球。", },
	[420003] = {id=420003, zh_CN="穿越新世界", },
	[420004] = {id=420004, zh_CN="探索房间，寻找信息。", },
	[420005] = {id=420005, zh_CN="来到陌生的星球，先探索了解下周围，寻找有用的信息吧。\n探索房间，寻找信息。", },
	[420006] = {id=420006, zh_CN="转动视角，移动查看房间情况。", },
	[420007] = {id=420007, zh_CN="来到陌生的星球，先探索了解下周围，寻找有用的信息吧。\n转动视角，移动查看房间情况。", },
	[420008] = {id=420008, zh_CN="点击查看发光的信。", },
	[420009] = {id=420009, zh_CN="来到陌生的星球，先探索了解下周围，寻找有用的信息吧。\n点击查看发光的信。", },
	[420010] = {id=420010, zh_CN="缔造专属向导", },
	[420011] = {id=420011, zh_CN="与云团对话，了解向导伙伴。", },
	[420012] = {id=420012, zh_CN="光芒凝聚成名为“云团”的浮游生物，它是爷爷为你准备的伙伴，向它询问新星球的情况吧。\n与云团对话，了解向导伙伴。", },
	[420013] = {id=420013, zh_CN="与云团互动，点击创建角色。", },
	[420014] = {id=420014, zh_CN="你心中理想的伙伴是什么形象呢？按照自己的心意，将他创造出来吧。\n与云团互动，点击创建角色。", },
	[420015] = {id=420015, zh_CN="寻找原创伙伴，与他对话。", },
	[420016] = {id=420016, zh_CN="一个全新的生命因你而诞生，与他打个招呼，更加了解他。\n寻找原创伙伴，与他对话。", },
	[420017] = {id=420017, zh_CN="新星球开荒", },
	[420018] = {id=420018, zh_CN="前往鸭湖城堡。", },
	[420019] = {id=420019, zh_CN="一座因湖边小黄鸭命名的湖边堡垒，会有什么奇遇等待着你呢？\n前往鸭湖城堡。", },
	[420020] = {id=420020, zh_CN="抵达鸭湖城堡，查看爷爷的来信。", },
	[420021] = {id=420021, zh_CN="抵达鸭湖城堡时，云团收到了爷爷的信，随信还有贴心的礼物，快打开来看看吧。\n抵达鸭湖城堡，查看爷爷的来信。", },
	[420022] = {id=420022, zh_CN="与正在跟随你的伙伴对话，了解更多关于伙伴的事。", },
	[420023] = {id=420023, zh_CN="湖边的黄鸭嘀嘀咕咕，拿起精灵球，选择一只心仪的蕉绿鸭，捕捉他吧~\n前往湖边，捕捉蕉绿鸭。", },
	[420024] = {id=420024, zh_CN="前往蓝调餐厅。", },
	[420025] = {id=420025, zh_CN="星球开荒的第二站——蓝调餐厅。会遇到什么有趣的人和事呢？\n前往蓝调餐厅。", },
	[420026] = {id=420026, zh_CN="抵达蓝调餐厅，与奥黛特对话。", },
	[420027] = {id=420027, zh_CN="抵达蓝调餐厅，前方好像有人在举办什么活动，去看看吧。\n抵达蓝调餐厅，与奥黛特对话。", },
	[420028] = {id=420028, zh_CN="寻觅情绪力量", },
	[420029] = {id=420029, zh_CN="前往银河电影厂。", },
	[420030] = {id=420030, zh_CN="意外获得凝聚情绪种子的能力，这似乎是与银河制片厂息息相关的魔力，去电影厂寻找答案或帮助吧。\n前往银河电影厂。", },
	[420031] = {id=420031, zh_CN="抵达花海，与剧团成员对话。", },
	[420032] = {id=420032, zh_CN="花海里正站着一位剧团成员，向他展示情绪种子，能得到关于情绪凝结能力的答案吗？\n抵达花海，与剧团成员对话。", },
	[420033] = {id=420033, zh_CN="输入文字，一键成片。", },
	[420034] = {id=420034, zh_CN="情绪竟是电影厂制片的动力，试用电影厂的一键成片工具，体验剧团活动，生成属于你的影片。\n输入文字，一键成片。", },
	[420035] = {id=420035, zh_CN="与剧团成员对话，分享影片。", },
	[420036] = {id=420036, zh_CN="这位剧团成员蠢蠢欲动，想要邀请你加入剧团组织，向他询问，更加深入地了解剧团吧。\n与剧团成员对话，分享影片。", },
	[420037] = {id=420037, zh_CN="社团申请", },
	[420038] = {id=420038, zh_CN="点击右上角社团图标加入社团，或在商城购买社团许可证创建社团。", },
	[420039] = {id=420039, zh_CN="与志同道合者同行，旅途将充满新的乐趣与力量。\n点击右上角社团图标加入社团，或在商城购买社团许可证创建社团。", },
	[420040] = {id=420040, zh_CN="不速之客", },
	[420041] = {id=420041, zh_CN="前往家园。", },
	[420042] = {id=420042, zh_CN="一位自称小电池的仙人掌食味族找上门来，它为了朋友的事情焦急万分。\n与家园中的访客小电池对话。", },
	[420043] = {id=420043, zh_CN="与家园中的访客“小电池”对话。", },
	[420044] = {id=420044, zh_CN="小奶酪失去了制作甜品的灵感，小电池希望委托你帮助他找回灵感。\n与家园中的访客小电池对话。", },
	[420045] = {id=420045, zh_CN="灵感烘焙计划", },
	[420046] = {id=420046, zh_CN="前往寻找小奶酪。", },
	[420047] = {id=420047, zh_CN="即刻出发去寻找这位失落的委托人吧。\n前往寻找小奶酪。", },
	[420048] = {id=420048, zh_CN="寻找小奶酪，与他对话。", },
	[420049] = {id=420049, zh_CN="与小奶酪对话。", },
	[420050] = {id=420050, zh_CN="头脑风暴，点亮小奶酪的美味灵感火花。\n与小奶酪对话。", },
	[420051] = {id=420051, zh_CN="与小电池对话，讨论想到的食谱。", },
	[420052] = {id=420052, zh_CN="想到了很有趣的食谱呢，和小电池讨论一下想到的食谱吧！\n与小电池对话，讨论想到的食谱。", },
	[420053] = {id=420053, zh_CN="根据食谱，收集所需的食材。", },
	[420054] = {id=420054, zh_CN="食谱就绪，是时候将食谱变为美味甜品了，出发去收集新鲜的食材吧。\n根据食谱，收集所需的食材。", },
	[420055] = {id=420055, zh_CN="前往寻找小奶酪，与小奶酪对话。", },
	[420056] = {id=420056, zh_CN="甜品出炉，香气四溢，与朋友们分享并品尝劳动成果。\n前往学院，与小奶酪对话。", },
	[420057] = {id=420057, zh_CN="咔嚓，记录瞬间", },
	[420058] = {id=420058, zh_CN="与小奶酪对话，制作回忆日志。", },
	[420059] = {id=420059, zh_CN="这值得纪念的一刻，理应被永久保存。使用制片厂的工具，将这一瞬记录成影片吧。\n与小奶酪对话，制作回忆日志。", },
	[420060] = {id=420060, zh_CN="与伙伴对话，编辑并生成你的回忆日志。", },
	[420061] = {id=420061, zh_CN="选择心仪的片段，定格镜头……搞定！恭喜你，踏出了成为记录者的第一步。\n编辑并生成你的回忆日志。", },
	[420062] = {id=420062, zh_CN="与跟随的伙伴对话，查看爷爷的来信。", },
	[420063] = {id=420063, zh_CN="你的成长，爷爷都看在眼里。又一封满载关爱的信件与新的期许已然送达。\n查看爷爷的来信。", },
	[420064] = {id=420064, zh_CN="开放制片厂", },
	[420065] = {id=420065, zh_CN="查收剧团协会的信。", },
	[420066] = {id=420066, zh_CN="你的才华得到了官方认可！银河制片厂向你敞开了更大的创作之门。", },
	[420067] = {id=420067, zh_CN="剧本撰写", },
	[420068] = {id=420068, zh_CN="从剧本开始。尽情发挥你的想象力，创作并发布你的故事吧。\n创作一部剧本并发布。", },
	[420069] = {id=420069, zh_CN="场景搭建", },
	[420070] = {id=420070, zh_CN="故事需要舞台。运用你的审美，亲手搭建一个场景。\n搭建一个场景并发布。", },
	[420071] = {id=420071, zh_CN="亲身演绎一段故事。感受从角色内心迸发的情感力量吧。\n演绎一个作品并发布。", },
	[420072] = {id=420072, zh_CN="演绎一个作品并发布。", },
	[420073] = {id=420073, zh_CN="执掌导筒，协调一切资源，完成你作为导演的处女作。\n拍摄一个作品并发布。", },
	[420074] = {id=420074, zh_CN="执掌导筒", },
	[420075] = {id=420075, zh_CN="与跟随的伙伴互动，查收古堡聚会邀请函。", },
	[420076] = {id=420076, zh_CN="红月、迷雾与钟声……一场聚会，考验着你洞察谎言与真相的智慧。\n点击游玩乐园，参加一场古堡奇妙夜的集会。", },
	[420077] = {id=420077, zh_CN="盛宴与共舞", },
	[420078] = {id=420078, zh_CN="查收舞会邀请函。", },
	[420079] = {id=420079, zh_CN="一场表达感谢的舞会正等待你的光临~", },
	[420080] = {id=420080, zh_CN="点击游玩乐园，进入舞会。", },
	[420081] = {id=420081, zh_CN="一场表达感谢的舞会正等待你的光临~\n点击游玩乐园，前往舞会现场。", },
	[420082] = {id=420082, zh_CN="向你喜欢的居民赠送一份礼物。", },
	[420083] = {id=420083, zh_CN="舞会是表达心意的绝佳场合。为你珍视的朋友准备一份礼物，收获一份心意的回响。\n向你喜欢的居民赠送一份礼物。", },
	[420084] = {id=420084, zh_CN="邀请一位星球居民或玩家与你共舞。", },
	[420085] = {id=420085, zh_CN="舞曲响起，邀请你心中的那位舞伴，共舞一曲，为今夜画上句号。\n邀请一位星球居民或玩家与你共舞。", },
	[420086] = {id=420086, zh_CN="请查收剧团协会的来信，制片厂已向你开放。", },
	[420087] = {id=420087, zh_CN="古堡的秘密", },
	[420088] = {id=420088, zh_CN="点击游玩乐园，参加一场古堡奇妙夜的集会。", },
	[420089] = {id=420089, zh_CN="捕捉蕉绿鸭", },
	[420090] = {id=420090, zh_CN="前往制片厂，成为编剧，创作一部剧本并发布。", },
	[420091] = {id=420091, zh_CN="前往制片厂，成为制片，搭建一个场景并发布。", },
	[420092] = {id=420092, zh_CN="前往制片厂，成为导演，拍摄一个作品并发布。", },
	[420093] = {id=420093, zh_CN="古堡奇妙夜（天梯集会）", },
	[420094] = {id=420094, zh_CN="舞会开场", },
	[420095] = {id=420095, zh_CN="邀约舞池", },
	[420096] = {id=420096, zh_CN="爷爷来信", },
	[420097] = {id=420097, zh_CN="红月、迷雾与钟声……一场聚会，考验着你洞察谎言与真相的智慧。\n查收古堡聚会邀请函。", },
	[420098] = {id=420098, zh_CN="共筑社团", },
	[420099] = {id=420099, zh_CN="与跟随的伙伴对话，查看社团来信，了解社团功能。", },
	[420100] = {id=420100, zh_CN="与跟随的伙伴对话，查看社团来信，了解社团功能。", },
	[420101] = {id=420101, zh_CN="社团开启通知", },
	[420102] = {id=420102, zh_CN="致%PlayerName", },
	[420103] = {id=420103, zh_CN="察觉到你最近好像遇到了小难题？", },
	[420104] = {id=420104, zh_CN="协会这就为你解锁社团功能。在这里，你可以指挥光灵伙伴分工协作——搭建工作台、采集资源与食材，收获美味食物、实用道具以及漂亮服饰。", },
	[420105] = {id=420105, zh_CN="社团里还有商店同步开放啦！多余的资源可以在这里上架出售变现，也能在商店选购心仪的食物和资源～", },
	[420106] = {id=420106, zh_CN="要是在社团里遇到任何疑问，别担心！你的 AI 伙伴随时待命。与TA交互，向TA询问“AI社团咨询”，它会为你耐心解答所有细节。", },
	[420107] = {id=420107, zh_CN="期待看到你与伙伴们共同打造的温馨社团。", },
	[420108] = {id=420108, zh_CN="——银河制片厂剧团协会", },
	[420109] = {id=420109, zh_CN="没有导演，无法开始拍摄", },
	[420110] = {id=420110, zh_CN="执掌镜筒", },
	[420111] = {id=420111, zh_CN="前往制片厂，成为导演，拍摄一个影片并上传发布。", },
	[420112] = {id=420112, zh_CN="成为导演，协调一切资源，完成你作为导演的处女作。\n拍摄一个影片并发布。", },
	[420113] = {id=420113, zh_CN="前往花海。", },
	[420114] = {id=420114, zh_CN="前往花海，寻找那位正在找灵感的剧团成员。\n前往花海。", },
	[420115] = {id=420115, zh_CN="再次抵达花海，与剧团成员对话。", },
	[420116] = {id=420116, zh_CN="在你深入了解制片厂的运作后，剧团成员似乎还有更深层的秘密想要分享。/n抵达花海，与剧团成员对话。", },
	[420117] = {id=420117, zh_CN="点击右上角的游戏乐园，参与一场天梯集会：古堡奇妙夜。", },
	[420118] = {id=420118, zh_CN="当红月升起，真相往往隐藏在面具之后。一场关于谎言与真实的游戏即将开场。点击右上角的游戏乐园，参与一场天梯集会：古堡奇妙夜。", },
	[420119] = {id=420119, zh_CN="在制片厂的初体验感觉如何？", },
	[420120] = {id=420120, zh_CN="感觉不错？", },
	[420121] = {id=420121, zh_CN="感觉非常棒！", },
	[420122] = {id=420122, zh_CN="听着，孩子。", },
	[420123] = {id=420123, zh_CN="捕捉情绪，学习拍摄技巧只是第一步。", },
	[420124] = {id=420124, zh_CN="为了帮助每位成员更深刻地理解角色与情感。", },
	[420125] = {id=420125, zh_CN="剧团内部会定期组织一些特别的聚会游戏。", },
	[420126] = {id=420126, zh_CN="你已经拥有了参加聚会的资格。", },
	[420127] = {id=420127, zh_CN="这是给你的邀请函。", },
	[420128] = {id=420128, zh_CN="祝你……玩得愉快。", },
	[420129] = {id=420129, zh_CN="唔……头好晕……",},
	[420130] = {id=420130, zh_CN="刚刚好像做了一个梦",}, 
    [420131] = {id=420131, zh_CN="这是哪",},
	[420132] = {id=420132, zh_CN="得知穿越", },
	[420133] = {id=420133, zh_CN="查看自己", },
	[420134] = {id=420134, zh_CN="小声抱怨后查看自己。", },
	[420135] = {id=420135, zh_CN="爷爷……你怎么把我一个人送到这里啊。", },
	[420136] = {id=420136, zh_CN="我就这样被爷爷发明的时光机送到了莫名其妙的地方。", },
	[420137] = {id=420137, zh_CN="芝麻糊，你好点了吗？",},
	[420138] = {id=420138, zh_CN="芝麻糊好多了，谢谢你喵。",},
	[420139] = {id=420139, zh_CN="我刚才有侦查到一些信息，现在我有问题要问你。",},
	[420140] = {id=420140, zh_CN="请讲。",},
	[420141] = {id=420141, zh_CN="你哥哥明明也受伤了，我看到他的爪子其实不止烧到指甲，猫垫子也有一点点烫伤，应该是需要简单处理一下的。",},
	[420142] = {id=420142, zh_CN="但是他没处理，也没有留下来照顾应激的你，就着急去片场了。",},
	[420143] = {id=420143, zh_CN="你们一只布偶，一只蓝猫，根本也不是一个品种。为什么他喊你弟弟？",},
	[420144] = {id=420144, zh_CN="甜品店是没有明火的，现场除了年糕，整个房间，也没有任何可燃物燃烧的痕迹。年糕是怎么烧伤的？",},
	[420145] = {id=420145, zh_CN="最不合理的是，他说你是他最亲爱的弟弟，但是他却留一个陌生人来照顾你，自己抛下你？",},
	[420146] = {id=420146, zh_CN="……",},
	[420147] = {id=420147, zh_CN="没想到你发现了就这么多异常，真不愧是我哥哥口中那个一眼能看透真相的侦探呢。",},
	[420148] = {id=420148, zh_CN="这些疑点实在是很明显。",},
	[420149] = {id=420149, zh_CN="是你的确很敏锐呢。",},
	[420150] = {id=420150, zh_CN="让我来一一解释吧。",},
	[420151] = {id=420151, zh_CN="我哥哥烧伤，都怪这个笨蛋机器人莫迪斯。",},
	[420152] = {id=420152, zh_CN="莫迪斯听到芝麻糊远远的还在抱怨自己，一个震动。手里的甜品都差点没拿稳。",},
	[420153] = {id=420153, zh_CN="（机器人的情绪波动还真是表现的比较笨拙）",},
	[420154] = {id=420154, zh_CN="莫迪斯看到有直播观众许愿想要看烟花，是个动手能力极强的机器人，就说既然想看烟花，那就在甜品店里表演。",},
	[420155] = {id=420155, zh_CN="烟花的确是很绚烂。",},
	[420156] = {id=420156, zh_CN="但是莫迪斯这个笨蛋机器人，没看到我就在烟花筒前面，所以点燃了烟花桶，火星子直扑我而来。",},
	[420157] = {id=420157, zh_CN="芝麻糊眼圈一红。是的，猫也是会流眼泪的\\(╥╯^╰╥\\)。",},
	[420158] = {id=420158, zh_CN="他扑过来扑倒用身体盖住你，并且伸手用爪子接住 了火星子。",},
	[420159] = {id=420159, zh_CN="你怎么知道？",},
	[420160] = {id=420160, zh_CN="因为地上除了年糕白色的毛发被晒黑的痕迹，你的毛发完整无缺。",},
	[420161] = {id=420161, zh_CN="呜呜……是啊……他真的很爱我。",},
	[420162] = {id=420162, zh_CN="我是蓝猫。我哥哥是布偶，我们都是被莫迪斯从小收养的。",},
	[420163] = {id=420163, zh_CN="莫迪斯虽然没有装任何关于猫猫养育 的芯片，但是他还是用心的把我们养大了。",},
	[420164] = {id=420164, zh_CN="因此莫迪斯 我 我哥哥都知道你的到来，我们也为此做了迎接你的准备。这是他很信任你的原因。",},
	[420165] = {id=420165, zh_CN="谁让你是救命恩人的亲 孙子（女）呢！",},
	[420166] = {id=420166, zh_CN="只是……哥哥为了救我，把给你准备的甜品也打翻了……",},
	[420167] = {id=420167, zh_CN="（黑线……好吧，偷偷咽了口水）",},
	[420168] = {id=420168, zh_CN="你哥哥那么爱你，怎么忍心丢下刚才应激的你？",},
	[420169] = {id=420169, zh_CN="芝麻糊亮晶晶的眼睛低沉了下来。",},
	[420170] = {id=420170, zh_CN="因为我们都要活下去。在米乐小镇，除了要喂饱自己之外，我们每天的推理，思考和行动，都会消耗星石。在你们现实世界，星石就是token的意思。也就是说，你只是意识体穿越到小镇，这些小镇的居民都是AI。",},
	[420171] = {id=420171, zh_CN="赚取星石的办法，有很多。我和哥哥选择去在小镇里去制片厂里打工，可以做导演或者演员。",},
	[420172] = {id=420172, zh_CN="哥哥和我们都是制片厂的演员呢，今天在这里就是莫迪斯要为甜品店做直播，我和哥哥都是猫粮代言人，嘿嘿。",},
	[420173] = {id=420173, zh_CN="怎么你们猫都还要自力更生吗？",},
	[420174] = {id=420174, zh_CN="对啊  我和哥哥都成年了呢！怎么好意思一直啃他呢",},
	[420175] = {id=420175, zh_CN="最后一个问题，为什么我爷爷送我到这里……",},
	[420176] = {id=420176, zh_CN="此时，看到芝麻糊状态好转，莫迪斯也靠近了过来。",},
	[420177] = {id=420177, zh_CN="因为米乐小镇都是你爷爷创建的一个虚拟世界。你在现实生活中宅在家里每天都刷视频，爷爷看在眼里，疼在心里。",},
	[420178] = {id=420178, zh_CN="爷爷知道你有很多梦想，但是爷爷也知道，在现实世界，实现梦想，实现很多很多梦想，却不是一件容易的事情。",},
	[420179] = {id=420179, zh_CN="作为人工智能博士的他，把你传送到这个小镇这件事，不仅是我，镇子里的人都知道。",},
	[420180] = {id=420180, zh_CN="也就是说，整个镇子无论是人类，妖灵，精灵还是巴别族，族长们都投票通过，一致同意欢迎你的到来。",},
	[420181] = {id=420181, zh_CN="这是一个 无论你做什么，都会接纳你的世界。即使是你对陌生人搭讪，也会收到回应的世界，这个世界是没有冷暴力的。",},
	[420182] = {id=420182, zh_CN="爷爷……",},
	[480000] = {id=480000, zh_CN="当前视频无法上传，请拍摄新视频", },
