	[470006] = {id=470006, zh_CN="投喂专家", },
	[470007] = {id=470007, zh_CN="心情调解师", },
	[470008] = {id=470008, zh_CN="新老友记", },
	[470009] = {id=470009, zh_CN="喵尔摩斯与花生", },
	[470010] = {id=470010, zh_CN="古堡通行证", },
	[470011] = {id=470011, zh_CN="特别笔友", },
	[470012] = {id=470012, zh_CN="特殊原则", },
	[470013] = {id=470013, zh_CN="拥有1个好感度达到3级的伙伴", },
	[470014] = {id=470014, zh_CN="拥有1位好感度达到15级的伙伴", },
	[470015] = {id=470015, zh_CN="拥有3个亲密度达到10级的伙伴", },
	[470016] = {id=470016, zh_CN="拥有5位亲密度达到15级的伙伴", },
	[470017] = {id=470017, zh_CN="拥有5个亲密度达到30级的伙伴", },
	[470018] = {id=470018, zh_CN="累计与伙伴进行50次对话互动", },
	[470019] = {id=470019, zh_CN="累计向伙伴投喂成功50次", },
	[470020] = {id=470020, zh_CN="累计将5次伙伴的心情达到高兴1级", },
	[470021] = {id=470021, zh_CN="和小金毛好感度达到20级", },
	[470022] = {id=470022, zh_CN="和年糕好感度达到20级", },
	[470023] = {id=470023, zh_CN="和芝麻糊好感度达到20级", },
	[470024] = {id=470024, zh_CN="和奥黛特好感度达到20级", },
	[470025] = {id=470025, zh_CN="和莫迪斯好感度达到20级", },
	[470026] = {id=470026, zh_CN="服饰穿戴中，无法丢弃", },
	[470027] = {id=470027, zh_CN="当前场景已选中。", },
	[470028] = {id=470028, zh_CN="是否保存当前外观数据", },
	[470029] = {id=470029, zh_CN="改变OC伙伴后不会保留当前外观数据，是否继续", },
	[470030] = {id=470030, zh_CN="先稍等片刻，过会儿再踌躇搭讪吧", },
	[470031] = {id=470031, zh_CN="没有合适的目标", },
	[470032] = {id=470032, zh_CN="运镜大师刚刚开了会小差,现在帮您重新生成镜头", },
	[470033] = {id=470033, zh_CN="当您处于其他人社团时，无法进行采集", },
	[470034] = {id=470034, zh_CN="是否保存剧场", },
	[470035] = {id=470035, zh_CN="确定切换至下一幕吗？切换后，当前一幕的进度与参数将会自动保存。", },
	[470036] = {id=470036, zh_CN="该指令包含其他演员，无法删除", },
	[470037] = {id=470037, zh_CN="今日AI请求已达上限，请明日再试", },
	[470038] = {id=470038, zh_CN="是否保存剧场并退出", },
	[450040] = {id=450040, zh_CN="种子已集齐！点击历程—花瓣—铃兰种—云溪铃兰，去解锁云溪铃兰的第一朵花瓣——山谷铃音。", },
	[450041] = {id=450041, zh_CN="汪汪，小金毛对你有种奇怪的感应。", },
	[450042] = {id=450042, zh_CN="%PlayerName的灵魂里响起阵阵铃音……", },
	[450043] = {id=450043, zh_CN="那是什么？快去探索一下吧。", },
	[460000] = {id=460000, zh_CN="演出后你会马上洗澡吗？", },
	[460001] = {id=460001, zh_CN="当然啦，身上还沾着魔法气息呢，不洗当心床单变魔毯！", },
	[460002] = {id=460002, zh_CN="热水冲下来的瞬间，超解压的！", },
	[460003] = {id=460003, },
	[465000] = {id=465000, zh_CN="你洗澡用水吗？", },
	[465001] = {id=465001, zh_CN="靠晨露就够啦！晨露带草木养分，比水养肤。", },
	[465002] = {id=465002, zh_CN="洗完花更艳丽，刺都亮堂堂的～", },
	[465003] = {id=465003, },
	[500001] = {id=500001, zh_CN="你喜欢什么口味的猫粮呢？", },
	[500002] = {id=500002, zh_CN="喵喵我最钟爱三文鱼口味，那简直是天上人间绝无仅有的美味！", },
	[500003] = {id=500003, zh_CN="在你心里我是什么？", },
	[500004] = {id=500004, zh_CN="您在我心中就像...就像...", },
	[500005] = {id=500005, zh_CN="像太阳一样温暖！像蜂蜜一样甜蜜！", },
	[500006] = {id=500006, zh_CN="不对不对，应该说是像皇家猫粮一样不可或缺！", },
	[500007] = {id=500007, zh_CN="找个地方晒太阳！", },
	[500008] = {id=500008, zh_CN="真是个好主意！", },
	[500009] = {id=500009, zh_CN="我知道城堡屋顶有个绝佳的晒太阳地点！", },
	[500010] = {id=500010, zh_CN="约定一个秘密暗号", },
	[500011] = {id=500011, zh_CN="当我说’今天的阳光真明媚‘的时候", },
	[500012] = {id=500012, zh_CN="您就要回答’像小鱼干一样美味‘！", },
	[500013] = {id=500013, zh_CN="那个瓶子很可疑吗？", },
	[500014] = {id=500014, zh_CN="那个瓶子...确实散发着可疑的气息", },
	[500015] = {id=500015, zh_CN="我们还是离它远点比较好喵！", },
	[500016] = {id=500016, zh_CN="照顾好自己", },
	[500017] = {id=500017, zh_CN="您真是太体贴了！", },
	[500018] = {id=500018, zh_CN="讲个冷笑话", },
