	[600000] = {id=600000, zh_CN="喵！%PlayerName。", },
	[600001] = {id=600001, zh_CN="你居然解开了日月联系的问题。", },
	[600002] = {id=600002, zh_CN="你简直就是我理想中的完美搭……", },
	[600003] = {id=600003, zh_CN="我好像听到有喵夸我是完美搭档？", },
	[600004] = {id=600004, zh_CN="喵嗷？那、那是你的幻听。", },
	[600005] = {id=600005, zh_CN="喵喵我说的是完备。", },
	[700000] = {id=700000, zh_CN="你被逮捕了。", },
	[700001] = {id=700001, zh_CN="你有权保持沉默。", },
	[700002] = {id=700002, zh_CN="我的录音功能会如实记录并上传。", },
	[700003] = {id=700003, zh_CN="废话少说，直接跑！（敏捷50）", },
	[700004] = {id=700004, zh_CN="废话少说跑就对了！", },
	[700005] = {id=700005, zh_CN="你和小金毛扭头就冲。", },
	[700006] = {id=700006, zh_CN="欸，怎么跑了。", },
	[700007] = {id=700007, zh_CN="警卫飞碟想要加速追上你们，但已经来不及了。", },
	[700008] = {id=700008, zh_CN="小金毛刚想跑，结果脚下一滑。", },
	[700009] = {id=700009, zh_CN="连你也一起绊倒了。", },
	[700010] = {id=700010, zh_CN="逃跑只会增加你们的罪行。", },
	[700011] = {id=700011, zh_CN="我们迷路了。（魅力50）", },
	[700012] = {id=700012, zh_CN="我们好像走错了，这是哪里？", },
	[700013] = {id=700013, zh_CN="对，我和主人是出来散步的。", },
	[700014] = {id=700014, zh_CN="迷路了？不应该啊。", },
	[700015] = {id=700015, zh_CN="算了，前面右转能出去。", },
	[700016] = {id=700016, zh_CN="下次看清楚地图。", },
	[700017] = {id=700017, zh_CN="迷路？", },
	[700018] = {id=700018, zh_CN="不要狡辩了。", },
	[700019] = {id=700019, zh_CN="逮捕信息上的在逃犯就是你们。", },
