	[700021] = {id=700021, zh_CN="你抓错人了，你要抓的是一只狗。", },
	[700022] = {id=700022, zh_CN="而我们是一人一狗。", },
	[700023] = {id=700023, zh_CN="你看，是不是抓错了？", },
	[700024] = {id=700024, zh_CN="好像有道理……", },
