	[700111] = {id=700111, zh_CN="我们好像走错了，这是哪里？", },
	[700112] = {id=700112, zh_CN="对，我和主人是出来散步的。", },
	[700113] = {id=700113, zh_CN="迷路了？不应该啊。", },
	[700114] = {id=700114, zh_CN="算了，前面右转能出去。", },
	[700115] = {id=700115, zh_CN="下次看清楚地图。", },
	[700116] = {id=700116, zh_CN="迷路？", },
	[700117] = {id=700117, zh_CN="不要狡辩了。", },
	[700118] = {id=700118, zh_CN="偷偷摸摸潜入的身影就是你们。", },
	[700119] = {id=700119, zh_CN="我们是来找东西的。（才智50）", },
	[700120] = {id=700120, zh_CN="我的……我狗的飞盘掉进来了。", },
	[700121] = {id=700121, zh_CN="就是一个会圆形的狗狗飞盘，你有看见吗？", },
	[700122] = {id=700122, zh_CN="嗷呜，嗷呜~", },
	[700123] = {id=700123, zh_CN="你看我家狗着急的，真的在找飞盘。", },
	[700124] = {id=700124, zh_CN="好像有道理……", },
	[700125] = {id=700125, zh_CN="你和小金毛趁着警卫飞碟陷入思考，悄悄溜走。", },
	[700126] = {id=700126, zh_CN="不要狡辩了。", },
	[700127] = {id=700127, zh_CN="逮捕信息上的在逃犯就是你们。", },
	[700128] = {id=700128, zh_CN="你追上了小金毛，逃脱了警卫飞碟的严密逮捕。", },
	[700129] = {id=700129, zh_CN="汪汪！%PlayerName这里就安全啦。", },
	[700130] = {id=700130, zh_CN="成功穿过层层守卫，你和小金毛终于来到了藏宝地点。", },
	[700131] = {id=700131, zh_CN="以小金毛千年的藏宝经验……", },
	[700132] = {id=700132, zh_CN="这里面一定有丰富的宝藏！", },
	[700133] = {id=700133, zh_CN="嘿嘿，珠宝，星石，无数的食物和温暖的小屋……", },
	[700134] = {id=700134, zh_CN="小金毛来啦！", },
	[700135] = {id=700135, zh_CN="嗯？栅栏那边是不是有动静？", },
	[700136] = {id=700136, zh_CN="非法闯入者，不许再跑了！", },
	[700137] = {id=700137, zh_CN="别躲了，我知道你们在哪儿", },
	[700200] = {id=700200, zh_CN="你们未登记擅自闯入这里，我有权将你们护送离开。", },
	[700201] = {id=700201, zh_CN="如果不能提供一个合理的解释，", },
	[700202] = {id=700202, zh_CN="我恐怕只能……请你们从头开始了！", },
	[700203] = {id=700203, zh_CN="花盆变形", },
	[700204] = {id=700204, zh_CN="嘘……看我的。成功", },
	[700205] = {id=700205, zh_CN="你迅速拉着年糕钻进草丛。", },
	[700206] = {id=700206, zh_CN="花盆被你变形成你和年糕的模样。", },
	[700207] = {id=700207, zh_CN="管理员对着花盆训话了半分钟才发现上当。", },
	[700208] = {id=700208, zh_CN="上当了，可恶。", },
	[700209] = {id=700209, zh_CN="你的动作太大，碰倒了一排花盆。", },
	[700210] = {id=700210, zh_CN="破坏公物，罪加一等。", },
	[700211] = {id=700211, zh_CN="嘿！声东击西。", },
	[700212] = {id=700212, zh_CN="看！那里有人潜入了。", },
	[700213] = {id=700213, zh_CN="哪里？", },
	[700214] = {id=700214, zh_CN="周围的管理员都转过头去。", },
	[700215] = {id=700215, zh_CN="你和年糕迅速逃走。", },
	[700216] = {id=700216, zh_CN="你在侮辱我的工作态度吗？", },
	[700217] = {id=700217, zh_CN="漏洞百出的招式对我是无效的。", },
	[700218] = {id=700218, zh_CN="躺倒打滚，萌混过关。", },
	[700219] = {id=700219, zh_CN="呼噜噜……喵~", },
	[700220] = {id=700220, zh_CN="年糕躺倒在地，露出毛茸茸的肚皮。", },
	[700221] = {id=700221, zh_CN="好……好可爱。", },
	[700222] = {id=700222, zh_CN="下不为例~", },
	[700223] = {id=700223, zh_CN="年糕滚了一身泥。", },
	[700224] = {id=700224, zh_CN="不行不行，太脏了。", },
	[700225] = {id=700225, zh_CN="离开这里，快去洗澡。", },
	[700226] = {id=700226, zh_CN="我是上级派来的巡查员。", },
	[700227] = {id=700227, zh_CN="管理员，你的警觉性值得赞赏。", },
	[700228] = {id=700228, zh_CN="但我们是派来检查的巡查员，请让开。", },
	[700229] = {id=700229, zh_CN="年糕配合亮出自制的徽章。", },
	[700230] = {id=700230, zh_CN="原……原来是特派员。", },
	[700231] = {id=700231, zh_CN="请快速通过。", },
	[700232] = {id=700232, zh_CN="你的表演过于浮夸，破绽百出。", },
	[700233] = {id=700233, zh_CN="抱歉，你们的演技不及格。", },
	[700234] = {id=700234, zh_CN="我的光灵走失了。", },
	[700235] = {id=700235, zh_CN="我的光灵走丢了，它怎么这么可怜……", },
	[700236] = {id=700236, zh_CN="它为了贴补家用，一直勤勤恳恳的工作……", },
	[700237] = {id=700237, zh_CN="你与年糕挤出两滴眼泪……", },
	[700238] = {id=700238, zh_CN="天哪，怎么不早说。", },
	[700239] = {id=700239, zh_CN="一定要找到它。", },
	[700240] = {id=700240, zh_CN="谎言无法引起他人的同情。", },
	[700241] = {id=700241, zh_CN="想好真正的理由再来。", },
	[700242] = {id=700242, zh_CN="拜托拜托，真诚承诺。", },
	[700243] = {id=700243, zh_CN="我们是追寻影子来到这里。", },
	[700244] = {id=700244, zh_CN="我发誓，真的会遵守规矩的。", },
	[700245] = {id=700245, zh_CN="年糕也举起爪子发誓。", },
	[700246] = {id=700246, zh_CN="好吧，看你们也不是坏蛋。", },
	[700247] = {id=700247, zh_CN="给，这是你们的临时访客身份。", },
	[700248] = {id=700248, zh_CN="你的理由无法说服我。", },
	[700249] = {id=700249, zh_CN="规则就是规则。请离开这里。", },
	[700300] = {id=700300, zh_CN="你看起来好像在发抖哦？", },
	[700301] = {id=700301, zh_CN="瞎说！我这是在进行高频预警！", },
	[700302] = {id=700302, zh_CN="别怕,我会一直挡在你前面。", },
	[700303] = {id=700303, zh_CN="呜……那你以后都要保护我喵。", },
	[700304] = {id=700304, zh_CN="是遇到扫地机了吗？", },
	[700305] = {id=700305, zh_CN="喵哇！快带喵喵我呀离开危险区！", },
	[700306] = {id=700306, zh_CN="怎么一直勾着我的裤脚呀？", },
	[700307] = {id=700307, zh_CN="喵呜,有一点点害怕喵。", },
	[700308] = {id=700308, zh_CN="既然这么离不开我,那就抱抱？", },
	[700309] = {id=700309, zh_CN="咳,作为奖励,只准抱三分钟喵！", },
	[700310] = {id=700310, zh_CN="你这样我没法去破大案了喔。", },
	[700311] = {id=700311, zh_CN="不准走！不准离开喵喵我呀！", },
	[700312] = {id=700312, zh_CN="喵嗷,不小心勾上的。", },
	[700313] = {id=700313, zh_CN="既然这么离不开我,那就抱抱？", },
	[700314] = {id=700314, zh_CN="咳,作为奖励,只准抱三分钟喵！", },
	[700315] = {id=700315, zh_CN="真的吗？那你松开吧。", },
	[700316] = {id=700316, zh_CN="不准走！不准离开喵喵我呀！", },
	[700317] = {id=700317, zh_CN="姐姐最近有没有夸奖你？", },
	[700318] = {id=700318, zh_CN="嘿嘿,姐姐说我是最棒的弟弟！", },
	[700319] = {id=700319, zh_CN="那要不要吃个甜品庆祝一下？", },
	[700320] = {id=700320, zh_CN="咕噜噜~喵喵我呀准许你投喂了！", },
	[700321] = {id=700321, zh_CN="可姐姐说你还是个爱哭鬼喔。", },
	[700322] = {id=700322, zh_CN="喵嗷！那是姐姐在说反话喵！", },
	[700323] = {id=700323, zh_CN="姐姐很厉害,就是总把我当小猫看。", },
	[700324] = {id=700324, zh_CN="放心,这是我们之间的秘密。", },
	[700325] = {id=700325, zh_CN="嘘！那你绝对不可以告诉姐姐喵！", },
	[700326] = {id=700326, zh_CN="感觉你根本离不开姐姐嘛。", },
	[700327] = {id=700327, zh_CN="哪有！我可是成熟的社会喵了！", },
	[700328] = {id=700328, zh_CN="你想成为什么样的侦探？", },
	[700329] = {id=700329, zh_CN="当然是像喵尔摩斯那样响彻星球！", },
	[700330] = {id=700330, zh_CN="果然是有志气的名侦探呢！", },
	[700331] = {id=700331, zh_CN="哼哼,喵喵我呀的专业度可是顶级的。", },
	[700332] = {id=700332, zh_CN="可你连机器人和打雷都怕啊。", },
	[700333] = {id=700333, zh_CN="喵嗷！那是侦探必备的谨慎品格！", },
	[700334] = {id=700334, zh_CN="刚才那道闪电好大声呀。", },
	[700335] = {id=700335, zh_CN="喵哇！掩护掩护！战略性避险！", },
	[700336] = {id=700336, zh_CN="抓紧我的肩膀,没事的。", },
	[700337] = {id=700337, zh_CN="快保护喵喵我呀。", },
	[700338] = {id=700338, zh_CN="那只是下雨而已。", },
	[700339] = {id=700339, zh_CN="喵……还是很可怕。", },
	[700340] = {id=700340, zh_CN="我通过试用期面试了吗？", },
	[700341] = {id=700341, zh_CN="哼哼,喵喵我呀正真诚地邀请你。", },
	[700342] = {id=700342, zh_CN="我已接受聘用,年糕侦探！", },
	[700343] = {id=700343, zh_CN="那我们现在就是搭档了喵。", },
	[700344] = {id=700344, zh_CN="那我可以领到小鱼干薪水吗？", },
	[700345] = {id=700345, zh_CN="喵嗷,看你表现。", },
	[700346] = {id=700346, zh_CN="你现在是不是有点饿了？", },
	[700347] = {id=700347, zh_CN="喵呜,肚子正在对喵喵我发起抗议。", },
	[700348] = {id=700348, zh_CN="刚好我带了你最爱的小鱼干。", },
	[700349] = {id=700349, zh_CN="喵~你真是喵喵我呀的福星！", },
	[700350] = {id=700350, zh_CN="我会记得多带点甜品给你的。", },
	[700351] = {id=700351, zh_CN="算你上道,喵喵我呀会给你记功的。", },
	[700352] = {id=700352, zh_CN="感觉你今天格外英姿飒爽。", },
	[700353] = {id=700353, zh_CN="毕竟保持整洁是侦探的职业操守。", },
	[700354] = {id=700354, zh_CN="我来帮你打理一下背上的毛。", },
	[700355] = {id=700355, zh_CN="喵~力道不错,喵喵我呀很满意。", },
	[700356] = {id=700356, zh_CN="可你背上好像蹭到泥巴了。", },
	[700357] = {id=700357, zh_CN="喵哇！快帮我弄掉,这不符合贵族！", },
	[700358] = {id=700358, zh_CN="年糕不管什么时候都好威风呢。", },
	[700359] = {id=700359, zh_CN="喵,你终于发现了？", },
	[700360] = {id=700360, zh_CN="有什么特别的秘诀吗？", },
	[700361] = {id=700361, zh_CN="这是天生的气质。", },
	[700362] = {id=700362, zh_CN="告诉我吧,年糕大侦探。", },
	[700363] = {id=700363, zh_CN="喵,要多多观察喵喵我呀！", },
	[700364] = {id=700364, zh_CN="噗……原来如此。", },
	[700365] = {id=700365, zh_CN="喵！你的笑声怎么回事！", },
	[700366] = {id=700366, zh_CN="有什么要领吗？", },
	[700367] = {id=700367, zh_CN="喵嗷,要时刻保持专业。", },
	[700368] = {id=700368, zh_CN="感觉某只猫正幸福得冒泡？", },
	[700369] = {id=700369, zh_CN="喵！被看穿了？要专业点！", },
	[700370] = {id=700370, zh_CN="既然这么开心,抱我一下？", },
	[700371] = {id=700371, zh_CN="喵~当然可以啦。", },
	[700372] = {id=700372, zh_CN="和你一起庆祝？", },
	[700373] = {id=700373, zh_CN="那我们一起打滚吧~", },
	[700374] = {id=700374, zh_CN="要去完成什么任务？", },
	[700375] = {id=700375, zh_CN="喵嗷嗷！正义的伙伴出击！", },
	[700376] = {id=700376, zh_CN="走！我陪你一起！", },
	[700377] = {id=700377, zh_CN="喵哈哈,这就是我们的配合！", },
	[700378] = {id=700378, zh_CN="跑太快会摔跤的,慢一点。", },
	[700379] = {id=700379, zh_CN="喵呜！你太婆婆妈妈了！", },
	[700380] = {id=700380, zh_CN="在盯着那个闪光的东西看？", },
	[700381] = {id=700381, zh_CN="喵！那一定是犯人的证物！", },
	[700382] = {id=700382, zh_CN="我去帮你捡过来看看？", },
	[700383] = {id=700383, zh_CN="喵喵我呀给你记大功！", },
	[700384] = {id=700384, zh_CN="嘿,我看不到哪里闪光呀。", },
	[700385] = {id=700385, zh_CN="走开走开！别挡住我的视线！", },
	[700386] = {id=700386, zh_CN="年糕你在学习跳舞吗？", },
	[700387] = {id=700387, zh_CN="气氛组快就位！喵喵我呀要跳舞！", },
	[700388] = {id=700388, zh_CN="跳舞都很有大侦探风范呢。", },
	[700389] = {id=700389, zh_CN="喵呼呼,那当然是自然的喵！", },
	[700390] = {id=700390, zh_CN="我也转一圈,你看像不像？", },
	[700391] = {id=700391, zh_CN="喵嗷！你的步子太重了啦！", },
	[700392] = {id=700392, zh_CN="晒着太阳是不是快睡着了？", },
	[700393] = {id=700393, zh_CN="呼噜噜……这里好暖好香。", },
	[700394] = {id=700394, zh_CN="这里的毛软乎乎的。", },
	[700395] = {id=700395, zh_CN="喵嗷~喜欢喜欢,再揉一揉。", },
	[700396] = {id=700396, zh_CN="我也躺一会儿,陪你发呆。", },
	[700397] = {id=700397, zh_CN="喵喵我的位置分你一半。", },
	[700398] = {id=700398, zh_CN="年糕,你在想念姐姐吗？", },
	[700399] = {id=700399, zh_CN="嘿嘿,我是姐姐最棒的弟弟！", },
	[700400] = {id=700400, zh_CN="当然,你可是大侦探年糕呀。", },
	[700401] = {id=700401, zh_CN="快再说一遍,喵喵我呀爱听！", },
	[700402] = {id=700402, zh_CN="你姐姐不要你咯。", },
	[700403] = {id=700403, zh_CN="喵呜！才不是呢,我姐姐要我。", },
	[700404] = {id=700404, zh_CN="别装在思考了,小年糕。", },
	[700405] = {id=700405, zh_CN="侦探的事……能叫打盹吗喵！", },
	[700406] = {id=700406, zh_CN="做了什么梦？", },
	[700407] = {id=700407, zh_CN="喵喵我呀破获了超级大案哦。", },
	[700408] = {id=700408, zh_CN="来,捏捏耳朵。", },
	[700409] = {id=700409, zh_CN="呼噜噜,这时候捏耳朵最舒服了喵。", },
	[700410] = {id=700410, zh_CN="抱歉,没注意到你。", },
	[700411] = {id=700411, zh_CN="哼,居然敢无视喵喵我呀。", },
	[700412] = {id=700412, zh_CN="下次一定多多找你。", },
	[700413] = {id=700413, zh_CN="既然你这么诚心,原谅你喵。", },
	[700414] = {id=700414, zh_CN="怎么像个受气的小包子呀？", },
	[700415] = {id=700415, zh_CN="谁、谁是包子！", },
	[700416] = {id=700416, zh_CN="我帮你梳理背毛？", },
	[700417] = {id=700417, zh_CN="喵呜,快帮帮我喵……", },
	[700418] = {id=700418, zh_CN="帮你把打结的毛毛理顺。", },
	[700419] = {id=700419, zh_CN="呼噜噜,喵喵我的帅气回来了。", },
	[700420] = {id=700420, zh_CN="我就在这坐着,不说话。", },
	[700421] = {id=700421, zh_CN="喵……靠近一点也行喵。", },
	[700422] = {id=700422, zh_CN="谁敢欺负我们小侦探？", },
	[700423] = {id=700423, zh_CN="就是扫地机！它挑衅我！", },
	[700424] = {id=700424, zh_CN="走,我带你去把它关禁闭！", },
	[700425] = {id=700425, zh_CN="没错！让它见识正义喵喵拳！", },
	[700426] = {id=700426, zh_CN="摸摸头,不气不气喔。", },
	[700427] = {id=700427, zh_CN="喵呼噜噜……这招太犯规了。", },
	[700428] = {id=700428, zh_CN="别气啦,再炸毛就不帅了喔。", },
	[700429] = {id=700429, zh_CN="喵喵我呀现在要进行清算！", },
	[700430] = {id=700430, zh_CN="快看！那边有很多需要帮忙的人哦！", },
	[700431] = {id=700431, zh_CN="喵？哪呢？", },
	[700432] = {id=700432, zh_CN="冷静点,我要使出拥抱杀咯。", },
	[700433] = {id=700433, zh_CN="喵哇！放开我喵！", },
	[700434] = {id=700434, zh_CN="嘿！", },
	[700435] = {id=700435, zh_CN="喵呜哇！是谁试图偷袭喵喵我呀！", },
	[700436] = {id=700436, zh_CN="抱歉抱歉,吓到你了。", },
	[700437] = {id=700437, zh_CN="哼……喵喵我呀才没有被你吓到。", },
	[700438] = {id=700438, zh_CN="你的胆子真的好小。", },
	[700439] = {id=700439, zh_CN="不准这么说喵！", },
	[700440] = {id=700440, zh_CN="哈哈,刚才那个姿势挺帅。", },
	[700441] = {id=700441, zh_CN="咳咳,真的喵？", },
	[700442] = {id=700442, zh_CN="年糕,你肚子饿不饿？", },
	[700443] = {id=700443, zh_CN="你无法瓦解喵喵我的侦探意志。", },
	[700444] = {id=700444, zh_CN="快吃个猫罐头吧。", },
	[700445] = {id=700445, zh_CN="喵喵我呀愿意以身试毒！", },
	[700446] = {id=700446, zh_CN="饿着肚子才能保持清醒。", },
	[700447] = {id=700447, zh_CN="喵……这种残忍的话！", },
	[700448] = {id=700448, zh_CN="你戏真多……", },
	[700449] = {id=700449, zh_CN="扮演角色才能更好的观察喵。", },
	[700450] = {id=700450, zh_CN="年糕,你今天真可爱。", },
	[700451] = {id=700451, zh_CN="喵！请用睿智、优雅来形容喵喵我呀！", },
	[700452] = {id=700452, zh_CN="好吧,睿智的年糕。", },
	[700453] = {id=700453, zh_CN="哼哼,不亏是喵喵我呀。", },
	[700454] = {id=700454, zh_CN="可是你现在的样子真的很萌。", },
	[700455] = {id=700455, zh_CN="喵！", },
	[700456] = {id=700456, zh_CN="额,你没有这些特质。", },
	[700457] = {id=700457, zh_CN="喵！喵喵我说有就有。", },
