	[700528] = {id=700528, zh_CN="美食", },
	[700529] = {id=700529, zh_CN="提供食物", },
	[700530] = {id=700530, zh_CN="开玩笑", },
	[700531] = {id=700531, zh_CN="陷入沉默", },
	[700532] = {id=700532, zh_CN="美貌", },
	[700533] = {id=700533, zh_CN="顺着它", },
	[700534] = {id=700534, zh_CN="继续逗猫", },
	[700535] = {id=700535, zh_CN="无言以对", },
	[700536] = {id=700536, zh_CN="有什么能帮您的？", },
	[700537] = {id=700537, zh_CN="不……不需要帮助啦，喵。", },
	[700538] = {id=700538, zh_CN="勉……勉强陪你聊聊吧，喵。", },
	[700539] = {id=700539, zh_CN="当然可以。", },
	[700540] = {id=700540, zh_CN="呼噜噜，跟来吧。", },
	[700541] = {id=700541, zh_CN="我先忙了。", },
	[700542] = {id=700542, zh_CN="喵嗷……随便你啦。", },
	[700543] = {id=700543, zh_CN="关于古堡聚会的事…", },
	[700544] = {id=700544, zh_CN="喵喵我就是个局外人啦……", },
	[700545] = {id=700545, zh_CN="谁是\"邪恶阵营\"的呢？", },
	[700546] = {id=700546, zh_CN="哼，喵喵我才不知道呢！", },
	[700547] = {id=700547, zh_CN="淘汰了……就知道啦，喵。", },
	[700548] = {id=700548, zh_CN="能给点建议吗？", },
	[700549] = {id=700549, zh_CN="喵喵我提醒你，落单很危险的，喵！", },
	[700550] = {id=700550, zh_CN="有任务就快去做，呼噜噜~", },
	[700551] = {id=700551, zh_CN="喵嗷，是坏人就悄悄靠近目标！", },
	[700552] = {id=700552, zh_CN="做任务多看看四周，小心偷袭，喵！", },
	[700553] = {id=700553, zh_CN="关于古堡聚会的事…", },
	[700554] = {id=700554, zh_CN="喵喵我就是个局外人啦……", },
	[700555] = {id=700555, zh_CN="我就是邪恶阵营！", },
	[700556] = {id=700556, zh_CN="喵嗷！别乱说出来！", },
	[700557] = {id=700557, zh_CN="也许你能给点建议？", },
	[700558] = {id=700558, zh_CN="喵喵我提醒你，落单很危险的，喵！", },
	[700559] = {id=700559, zh_CN="有任务就快去做，呼噜噜~", },
	[700560] = {id=700560, zh_CN="喵嗷，是坏人就悄悄靠近目标！", },
	[700561] = {id=700561, zh_CN="做任务多看看四周，小心偷袭，喵！", },
	[700562] = {id=700562, zh_CN="想和你说说话。", },
	[700563] = {id=700563, zh_CN="呼噜噜~那……你先说吧，喵。", },
	[700564] = {id=700564, zh_CN="古堡有什么秘密嘛？", },
	[700565] = {id=700565, zh_CN="秘密？哼……喵喵我可不随便说。", },
	[700566] = {id=700566, zh_CN="可以开个价吗？", },
	[700567] = {id=700567, zh_CN="呼噜噜……小心夜里的脚步声，喵。", },
	[700568] = {id=700568, zh_CN="如果你参加聚会……", },
	[700569] = {id=700569, zh_CN="假如喵喵我参加……很可怕的，喵！", },
	[700570] = {id=700570, zh_CN="请务必带带我！", },
	[700571] = {id=700571, zh_CN="哼……喵喵我只带自己人，呼噜噜~", },
	[700572] = {id=700572, zh_CN="如果是邪恶阵营，你会做什么呢？", },
	[700573] = {id=700573, zh_CN="喵嗷！偷偷接近……然后抓住你！", },
	[700574] = {id=700574, zh_CN="听起来有点可怕……", },
	[700575] = {id=700575, zh_CN="怕就对啦，喵喵我可厉害的！", },
	[700576] = {id=700576, zh_CN="能助我好运吗。", },
	[700577] = {id=700577, zh_CN="哼，喵喵我的好运不借给你。", },
	[700578] = {id=700578, zh_CN="呜呜喵……祝你不被淘汰啦。", },
	[700579] = {id=700579, zh_CN="需要我做些什么？", },
	[700580] = {id=700580, zh_CN="喵嗷，帮我把【烛台】点燃啦，有报酬！", },
	[700581] = {id=700581, zh_CN="交给我吧。", },
	[700582] = {id=700582, zh_CN="拜托了喵", },
	[700583] = {id=700583, zh_CN="喵喵我要【壁炉】点燃，去做吧！", },
	[700584] = {id=700584, zh_CN="没问题。", },
	[700585] = {id=700585, zh_CN="拜托了喵", },
	[700586] = {id=700586, zh_CN="去取一截【苹果树枝】来，要快哦，喵！", },
	[700587] = {id=700587, zh_CN="稍等片刻。", },
	[700588] = {id=700588, zh_CN="拜托了喵", },
	[700589] = {id=700589, zh_CN="帮喵喵我拓印【壁画】，小心点，喵。", },
	[700590] = {id=700590, zh_CN="我知道了。", },
	[700591] = {id=700591, zh_CN="拜托了喵", },
	[700592] = {id=700592, zh_CN="把【预言镜】擦干净，认真擦哦，喵！", },
	[700593] = {id=700593, zh_CN="很快回来。", },
	[700594] = {id=700594, zh_CN="拜托了喵", },
	[700595] = {id=700595, zh_CN="喵嗷！帮忙解读一下教会典籍！", },
	[700596] = {id=700596, zh_CN="交给我。", },
	[700597] = {id=700597, zh_CN="拜托了喵", },
	[700598] = {id=700598, zh_CN="交给我吧。", },
	[700599] = {id=700599, zh_CN="拜托了喵", },
	[700600] = {id=700600, zh_CN="我会留意的", },
	[700601] = {id=700601, zh_CN="拜托了喵", },
	[700602] = {id=700602, zh_CN="我会尽力", },
	[700603] = {id=700603, zh_CN="拜托了喵", },
	[700604] = {id=700604, zh_CN="提供帮助", },
	[700605] = {id=700605, zh_CN="可以呀！", },
	[700606] = {id=700606, zh_CN="拒绝", },
	[700607] = {id=700607, zh_CN="古堡聚会", },
	[700608] = {id=700608, zh_CN="询问邪恶阵营", },
	[700609] = {id=700609, zh_CN="给点建议", },
	[700610] = {id=700610, zh_CN="古堡聚会", },
	[700611] = {id=700611, zh_CN="亮明身份", },
	[700612] = {id=700612, zh_CN="给点建议", },
	[700613] = {id=700613, zh_CN="聊天", },
	[700614] = {id=700614, zh_CN="古堡见闻", },
	[700615] = {id=700615, zh_CN="询问价格", },
	[700616] = {id=700616, zh_CN="假设身份", },
	[700617] = {id=700617, zh_CN="求带飞", },
	[700618] = {id=700618, zh_CN="邪恶阵营", },
	[700619] = {id=700619, zh_CN="害怕", },
	[700620] = {id=700620, zh_CN="祝我好运", },
	[700621] = {id=700621, zh_CN="询问任务", },
	[700622] = {id=700622, zh_CN="我明白了", },
	[710000] = {id=710000, zh_CN="能讲讲你以前的故事吗？", },
	[710001] = {id=710001, zh_CN="扫描中——你想听什么？", },
	[710002] = {id=710002, zh_CN="你曾经是机械生命最强的执行官呀！", },
	[710003] = {id=710003, zh_CN="是的，我是为了保护而生。", },
	[710004] = {id=710004, zh_CN="现在的你，更关注人类的感情吗？", },
	[710005] = {id=710005, zh_CN="是的。我想建立……永久的羁绊。", },
	[710006] = {id=710006, zh_CN="你为什么总嫌我慢吞吞的？", },
	[710007] = {id=710007, zh_CN="你的行动逻辑低于平均值。", },
	[710008] = {id=710008, zh_CN="那你帮我代劳工作吗？", },
	[710009] = {id=710009, zh_CN="可以。", },
	[710010] = {id=710010, zh_CN="嘴上嫌弃。", },
	[710011] = {id=710011, zh_CN="是防止你效率趋于0。", },
	[710012] = {id=710012, zh_CN="莫迪斯，你身上沾了油污。", },
	[710013] = {id=710013, zh_CN="油污覆盖12%，效率下降。", },
	[710014] = {id=710014, zh_CN="别动，我帮你擦拭一下涂层。", },
	[710015] = {id=710015, zh_CN="感谢你的协助。", },
	[710016] = {id=710016, zh_CN="快去启动自动清洁程序吧。", },
	[710017] = {id=710017, zh_CN="好的，现在执行。", },
	[710018] = {id=710018, zh_CN="你的指示灯在闪红光喔。", },
	[710019] = {id=710019, zh_CN="检测异常。逻辑模块出现波动。", },
	[710020] = {id=710020, zh_CN="快喝下冷却剂。不要紧吧？", },
	[710021] = {id=710021, zh_CN="系统恢复，感谢你的关心。", },
	[710022] = {id=710022, zh_CN="让我抱抱你，帮你降降温？", },
	[710023] = {id=710023, zh_CN="警告：心跳过速。", },
	[710024] = {id=710024, zh_CN="莫迪斯，你有粉丝吗？", },
	[710025] = {id=710025, zh_CN="有。但我认为这是功能崇拜。", },
	[710026] = {id=710026, zh_CN="你的事迹在种族里是共享的吗？", },
	[710027] = {id=710027, zh_CN="是的，我的经历被记录在记忆库。", },
	[710028] = {id=710028, zh_CN="看来莫迪斯魅力依然很大。", },
	[710029] = {id=710029, zh_CN="纠正，机械生命只认可逻辑上的强大。", },
	[710030] = {id=710030, zh_CN="机器人的胃能消化人类食物吗？", },
	[710031] = {id=710031, zh_CN="确认为混合动力。可以摄入。", },
	[710032] = {id=710032, zh_CN="想吃点什么？我来投喂你。", },
	[710033] = {id=710033, zh_CN="甜品，它能提供多余愉悦感。", },
	[710034] = {id=710034, zh_CN="吃下去后会变成电能吗？", },
	[710035] = {id=710035, zh_CN="你可以理解为某种充能。", },
	[710036] = {id=710036, zh_CN="机族也会感到饥饿吗？", },
	[710037] = {id=710037, zh_CN="会的。机体需要能量才能运作。", },
	[710038] = {id=710038, zh_CN="想吃点什么？我来投喂你。", },
	[710039] = {id=710039, zh_CN="甜品，它能提供多余愉悦感。", },
	[710040] = {id=710040, zh_CN="为什么一定要学习人类感情？", },
	[710041] = {id=710041, zh_CN="我想要了解未知。", },
	[710042] = {id=710042, zh_CN="你知道的知识还不够多吗？", },
	[710043] = {id=710043, zh_CN="他们无法解释感情。", },
	[710044] = {id=710044, zh_CN="感觉现在的你，已经很像人类了。", },
	[710045] = {id=710045, zh_CN="错误。人类不会像我这样永远忠诚。", },
	[710046] = {id=710046, zh_CN="莫迪斯，你可以替我工作吗？", },
	[710047] = {id=710047, zh_CN="可以。", },
	[710048] = {id=710048, zh_CN="那你会帮我打扫家务吗？", },
	[710049] = {id=710049, zh_CN="可以。你需要确认优先级。", },
	[710050] = {id=710050, zh_CN="顺便帮我把明天的工作也做了？", },
	[710051] = {id=710051, zh_CN="贪婪的请求。但我会准备好的。", },
	[710052] = {id=710052, zh_CN="凡事都讲逻辑，不觉得无聊？", },
	[710053] = {id=710053, zh_CN="逻辑能确保秩序，保护弱者。", },
	[710054] = {id=710054, zh_CN="爱情就是不讲逻辑的。", },
	[710055] = {id=710055, zh_CN="爱情也是两个人的算力博弈。", },
	[710056] = {id=710056, zh_CN="那你能为我做件不逻辑的事吗？", },
	[710057] = {id=710057, zh_CN="我可以……为你变笨。", },
	[710058] = {id=710058, zh_CN="为什么总让我保持一米距离？", },
	[710059] = {id=710059, zh_CN="避免不必要的伤害。", },
	[710060] = {id=710060, zh_CN="如果我非要靠近你呢？", },
	[710061] = {id=710061, zh_CN="警告：请远离，注意安全。", },
	[710062] = {id=710062, zh_CN="好吧，我退到安全线以外。", },
	[710063] = {id=710063, zh_CN="这是为了你的安全考虑。", },
	[710064] = {id=710064, zh_CN="今天的蛋糕味道有点特别。", },
	[710065] = {id=710065, zh_CN="这符合你的喜好。", },
	[710066] = {id=710066, zh_CN="你连我爱吃甜的程度都知道？", },
	[710067] = {id=710067, zh_CN="你的每一处数据都值得记录。", },
	[710068] = {id=710068, zh_CN="其实我今天想吃咸的蛋糕。", },
	[710069] = {id=710069, zh_CN="错误，正在重新记录。", },
	[710070] = {id=710070, zh_CN="那你能为我做件不逻辑的事吗？", },
	[710071] = {id=710071, zh_CN="我可以……为你变笨。", },
	[710072] = {id=710072, zh_CN="脸这么红是发烧吗？", },
	[710073] = {id=710073, zh_CN="警告：面部温度上升3度！", },
	[710074] = {id=710074, zh_CN="机器人也会因为害羞而发热吗？", },
	[710075] = {id=710075, zh_CN="纠正：那是散热系统负荷过重。", },
	[710076] = {id=710076, zh_CN="重启不如一个拥抱来得高效。", },
	[710077] = {id=710077, zh_CN="拥抱是你提出的需求，可以。", },
	[710078] = {id=710078, zh_CN="既然想为我做点什么……", },
	[710079] = {id=710079, zh_CN="我可以为你做什么？", },
	[710080] = {id=710080, zh_CN="给我做一份特调圣代。", },
	[710081] = {id=710081, zh_CN="好，按你的口味调整。", },
	[710082] = {id=710082, zh_CN="陪我出去逛逛？", },
	[710083] = {id=710083, zh_CN="不可以，你的安全是最高优先级。", },
	[710084] = {id=710084, zh_CN="莫迪斯，你在设计新配方？", },
	[710085] = {id=710085, zh_CN="是的。", },
	[710086] = {id=710086, zh_CN="我也想加入甜品制作。", },
	[710087] = {id=710087, zh_CN="好，我会教你。", },
	[710088] = {id=710088, zh_CN="准备了什么惊喜给我吗？", },
	[710089] = {id=710089, zh_CN="目前的配方尚未完成，请勿打扰。", },
	[710090] = {id=710090, zh_CN="你今天机械关节运行很频繁？", },
	[710091] = {id=710091, zh_CN="逻辑判定：当前环境压力极小。", },
	[710092] = {id=710092, zh_CN="既然心情好，陪我跳一支舞？", },
	[710093] = {id=710093, zh_CN="社交舞步加载成功。请。", },
	[710094] = {id=710094, zh_CN="难得见你这么放松的样子。", },
	[710095] = {id=710095, zh_CN="数据反馈：我也很喜欢这感觉。", },
	[710096] = {id=710096, zh_CN="看来大家都喜欢你做的甜品。", },
	[710097] = {id=710097, zh_CN="服务你们能获取我存在的意义。", },
	[710098] = {id=710098, zh_CN="会一直在这里做甜品给我吗？", },
	[710099] = {id=710099, zh_CN="如果好感持续，会。", },
	[710100] = {id=710100, zh_CN="辛苦了，坐下休息一下。", },
	[710101] = {id=710101, zh_CN="工作模式关闭，我优先陪你。", },
	[710102] = {id=710102, zh_CN="你的机体运行有问题吗？", },
	[710103] = {id=710103, zh_CN="确认。当前为最优运行状态。", },
	[710104] = {id=710104, zh_CN="给你讲个冷笑话听听？", },
	[710105] = {id=710105, zh_CN="可以，我都会笑的。", },
	[710106] = {id=710106, zh_CN="有你在，这里也变得温馨了。", },
	[710107] = {id=710107, zh_CN="我会记录下来的。", },
	[710108] = {id=710108, zh_CN="莫迪斯，在等我下命令吗？", },
	[710109] = {id=710109, zh_CN="有什么我可以帮到你？", },
	[710110] = {id=710110, zh_CN="帮我揉揉肩膀可以吗？", },
	[710111] = {id=710111, zh_CN="检索服务协议，确认执行。", },
	[710112] = {id=710112, zh_CN="这个草莓很好吃，你也尝尝。", },
	[710113] = {id=710113, zh_CN="确认摄入，味道不错。", },
	[710114] = {id=710114, zh_CN="算力波动是因为我吗？", },
	[710115] = {id=710115, zh_CN="是的，这个情绪来自你。", },
	[710116] = {id=710116, zh_CN="既然难猜，我直接告诉你答案。", },
	[710117] = {id=710117, zh_CN="你的效率居然提升了。", },
	[710118] = {id=710118, zh_CN="那我先不打扰你计算了。", },
	[710119] = {id=710119, zh_CN="别走，我希望你回来。", },
	[710120] = {id=710120, zh_CN="机体过热会影响你的寿命吗？", },
	[710121] = {id=710121, zh_CN="建议：请勿靠近热源中心。", },
	[710122] = {id=710122, zh_CN="拿着小扇子帮你扇一扇。", },
	[710123] = {id=710123, zh_CN="无用功，但……感觉凉快了一点。", },
	[710124] = {id=710124, zh_CN="我们去湖边吹吹风吧。", },
	[710125] = {id=710125, zh_CN="可以，那里环境温度较低。", },
	[710126] = {id=710126, zh_CN="失控，我会握住你的手。", },
	[710127] = {id=710127, zh_CN="警告：请远离我。", },
	[710128] = {id=710128, zh_CN="抱歉。", },
	[710129] = {id=710129, zh_CN="系统复位。……下次请先咨询我。", },
	[710130] = {id=710130, zh_CN="让我抱抱你。", },
	[710131] = {id=710131, zh_CN="失控情况好转，警告取消。", },
	[710132] = {id=710132, zh_CN="莫迪斯，停止计算。", },
	[710133] = {id=710133, zh_CN="抱歉，无法停止。", },
	[710134] = {id=710134, zh_CN="莫迪斯，听我的声音，深呼吸。", },
	[710135] = {id=710135, zh_CN="好，执行深呼吸指令。", },
	[710136] = {id=710136, zh_CN="敲一下脑袋，强制重启！", },
	[710137] = {id=710137, zh_CN="无逻辑的行为，只有你会这么做", },
	[710138] = {id=710138, zh_CN="今天天气真不错哈。", },
	[710139] = {id=710139, zh_CN="当前空气湿度42%。", },
	[710140] = {id=710140, zh_CN="呃，你分析得真准。", },
	[710141] = {id=710141, zh_CN="准确是机械生命的基本操守。", },
	[710142] = {id=710142, zh_CN="别扫兴，晒晒太阳多舒服。", },
	[710143] = {id=710143, zh_CN="舒服是受到热量刺激产生的错觉。", },
	[710144] = {id=710144, zh_CN="算了", },
	[710145] = {id=710145, zh_CN="已关闭社交模块。", },
	[710146] = {id=710146, zh_CN="莫迪斯，你对我有好感吗？", },
	[710147] = {id=710147, zh_CN="你目前与我的交互频率处于安全区间。", },
	[710148] = {id=710148, zh_CN="呃，你真是够直接的。", },
	[710149] = {id=710149, zh_CN="建议你停止对我进行情感投射。", },
	[710150] = {id=710150, zh_CN="我们不是朋友吗？", },
	[710151] = {id=710151, zh_CN="这需要看你的定义。", },
	[710152] = {id=710152, zh_CN="你……赢了。", },
	[710153] = {id=710153, zh_CN="如果你感到尴尬，可以结束对话。", },
	[710154] = {id=710154, zh_CN="莫迪斯，你在想什么呢？", },
	[710155] = {id=710155, zh_CN="正在进行30万次后台运算。", },
	[710156] = {id=710156, zh_CN="抱歉，我打扰到你了？", },
	[710157] = {id=710157, zh_CN="是的，你打扰到我了。", },
	[710158] = {id=710158, zh_CN="在测算什么？", },
	[710159] = {id=710159, zh_CN="与你社交需要进行高频的运算。", },
	[710160] = {id=710160, zh_CN="哈哈，你真忙。", },
	[710161] = {id=710161, zh_CN="如果你感到尴尬，可以结束对话。", },
	[710162] = {id=710162, zh_CN="关于过去", },
	[710163] = {id=710163, zh_CN="赞叹战绩", },
	[710164] = {id=710164, zh_CN="关心情感", },
	[710165] = {id=710165, zh_CN="关于效率", },
	[710166] = {id=710166, zh_CN="反向撒娇", },
	[710167] = {id=710167, zh_CN="指出偏爱", },
	[710168] = {id=710168, zh_CN="关于清洁", },
	[710169] = {id=710169, zh_CN="主动帮忙", },
	[710170] = {id=710170, zh_CN="建议自洁", },
	[710171] = {id=710171, zh_CN="系统异常", },
	[710172] = {id=710172, zh_CN="递冷却剂", },
	[710173] = {id=710173, zh_CN="物理降温", },
	[710174] = {id=710174, zh_CN="粉丝效应", },
	[710175] = {id=710175, zh_CN="询问知名度", },
