	[720000] = {id=720000, zh_CN="芝麻糊不论什么时候都很优雅呢。", },
	[720001] = {id=720001, zh_CN="喵~你终于注意到了吗。", },
	[720002] = {id=720002, zh_CN="有什么特别的秘诀吗？", },
	[720003] = {id=720003, zh_CN="哼，这是与生俱来的天赋。", },
	[720004] = {id=720004, zh_CN="芝麻糊有很多值得我学习的地方呢。", },
	[720005] = {id=720005, zh_CN="喵，要多观察我的举止。", },
	[720006] = {id=720006, zh_CN="噗……原来如此", },
	[720007] = {id=720007, zh_CN="喵！你那明显的笑声是怎么回事？", },
	[720008] = {id=720008, zh_CN="喵~那是自然！我可是舞蹈达人~", },
	[720009] = {id=720009, zh_CN="你还会跳舞？", },
	[720010] = {id=720010, zh_CN="那是当然~", },
	[720011] = {id=720011, zh_CN="舞步要注意什么？", },
	[720012] = {id=720012, zh_CN="喵。（翻译：挺胸抬头，步子轻。）", },
	[720013] = {id=720013, zh_CN="有什么要领吗？", },
	[720014] = {id=720014, zh_CN="喵嗷。（翻译：别踩我的尾巴。）", },
	[720015] = {id=720015, zh_CN="我可以邀你跳舞吗？", },
	[720016] = {id=720016, zh_CN="喵？（翻译：芝麻糊要考虑下。）", },
	[720017] = {id=720017, zh_CN="我会非常小心的。", },
	[720018] = {id=720018, zh_CN="喵。（翻译：勉强相信你。）", },
	[720019] = {id=720019, zh_CN="随时等待你受邀参加。", },
	[720020] = {id=720020, zh_CN="咕噜……（翻译：那答应你吧。）", },
	[720021] = {id=720021, zh_CN="可以让我摸摸你吗？", },
	[720022] = {id=720022, zh_CN="喵？不要随便碰本喵", },
	[720023] = {id=720023, zh_CN="唉，连摸一下都不行吗？", },
	[720024] = {id=720024, zh_CN="喵呜？（翻译：我要保持威严。）", },
	[720025] = {id=720025, zh_CN="真的不能摸一下吗？", },
	[720026] = {id=720026, zh_CN="喵，真受不了你，只准摸一下哦。", },
	[720027] = {id=720027, zh_CN="喵，那就给你摸一下吧。", },
	[720028] = {id=720028, zh_CN="一小会怎么够？", },
	[720029] = {id=720029, zh_CN="芝麻糊说一小会就是一小会！", },
	[720030] = {id=720030, zh_CN="一小会就一小会。", },
	[720031] = {id=720031, zh_CN="喵呼呼，算你识相。", },
	[720032] = {id=720032, zh_CN="保证让你舒舒服服的~", },
	[720033] = {id=720033, zh_CN="喵呜~非常有觉悟！", },
	[720034] = {id=720034, zh_CN="时间到了，我先停下吧。", },
	[720035] = {id=720035, zh_CN="喵嗷，谁允许你停下的！继续！", },
	[720036] = {id=720036, zh_CN="再让我摸摸，一下怎么够？", },
	[720037] = {id=720037, zh_CN="喵~稍微再往下一点，呼噜噜……", },
	[720038] = {id=720038, zh_CN="奇怪，怎么听见呼噜噜的声音？", },
	[720039] = {id=720039, zh_CN="喵嗷？芝麻糊才没有打呼噜。", },
	[720040] = {id=720040, zh_CN="再让我摸摸，一下怎么够？", },
	[720041] = {id=720041, zh_CN="喵~稍微再往下一点，呼噜噜……", },
	[720042] = {id=720042, zh_CN="那……我先停下吧。", },
	[720043] = {id=720043, zh_CN="喵嗷，谁允许你停下的！继续！", },
	[720044] = {id=720044, zh_CN="芝麻糊喜欢什么零食？", },
	[720045] = {id=720045, zh_CN="喵？（翻译：准备投喂我吗？）", },
	[720046] = {id=720046, zh_CN="当然，芝麻糊给一点指导意见？", },
	[720047] = {id=720047, zh_CN="喵嗷~（翻译：我口味很挑。）", },
	[720048] = {id=720048, zh_CN="芝麻糊喜欢吃什么？", },
	[720049] = {id=720049, zh_CN="海苔味小鱼干就很合我的口味。", },
	[720050] = {id=720050, zh_CN="出了新的甜品哦。", },
	[720051] = {id=720051, zh_CN="喵？咕噜噜~（翻译：快让我尝尝喵~）", },
	[720052] = {id=720052, zh_CN="不可以挑食。", },
	[720053] = {id=720053, zh_CN="喵，只要不是蔬菜，什么都好说。", },
	[720054] = {id=720054, zh_CN="没有，我只是问问。", },
	[720055] = {id=720055, zh_CN="你不可以偷吃零食不带我哦。", },
	[720056] = {id=720056, zh_CN="你身上好像有点脏了。", },
	[720057] = {id=720057, zh_CN="喵？一派胡言！", },
	[720058] = {id=720058, zh_CN="真的，背上有一块灰。", },
	[720059] = {id=720059, zh_CN="喵……（翻译：够不到……可恶。)", },
	[720060] = {id=720060, zh_CN="我帮你清理吧。", },
	[720061] = {id=720061, zh_CN="喵~（翻译：要给芝麻糊擦干净哦~）", },
	[720062] = {id=720062, zh_CN="喵？（翻译：难道是掉毛期到了？）", },
	[720063] = {id=720063, zh_CN="正常现象，别怕。", },
	[720064] = {id=720064, zh_CN="喵喵~（翻译：芝麻糊不会秃吧？）", },
	[720065] = {id=720065, zh_CN="我来帮你梳梳毛吧。", },
	[720066] = {id=720066, zh_CN="喵。（翻译：必须动作轻柔。）", },
	[720067] = {id=720067, zh_CN="芝麻糊怎样，我都喜欢。", },
	[720068] = {id=720068, zh_CN="咕噜……（翻译：油嘴滑舌。）", },
	[720069] = {id=720069, zh_CN="确实有点掉毛严重。", },
	[720070] = {id=720070, zh_CN="喵呜！（翻译：闭嘴！不许看！）", },
	[720071] = {id=720071, zh_CN="芝麻糊平时喜欢做什么？", },
	[720072] = {id=720072, zh_CN="最近在收集亮晶晶喵。", },
	[720073] = {id=720073, zh_CN="给我看看你的收藏？", },
	[720074] = {id=720074, zh_CN="看，从喷泉底下捞的玻璃珠。", },
	[720075] = {id=720075, zh_CN="很漂亮呢。", },
	[720076] = {id=720076, zh_CN="喵~（翻译：那是我的眼光好。）", },
	[720077] = {id=720077, zh_CN="你的藏品都藏在哪里啦？", },
	[720078] = {id=720078, zh_CN="喵嗷嗷。（翻译：想偷看藏宝库？那可不行。）", },
	[720079] = {id=720079, zh_CN="喵~（翻译：难以抵抗阳光沐浴。）", },
	[720080] = {id=720080, zh_CN="一只享受阳光的普通小猫咪", },
	[720081] = {id=720081, zh_CN="喵嗷！我可是古堡贵族小猫。", },
	[720082] = {id=720082, zh_CN="往旁边挪挪让我也躺会儿呗？", },
	[720083] = {id=720083, zh_CN="喵呜！（翻译：想得美！）", },
	[720084] = {id=720084, zh_CN="今天阳光真好啊。", },
	[720085] = {id=720085, zh_CN="喵~正适合在高处晒太阳。", },
	[720086] = {id=720086, zh_CN="喵，最近迷上站在高处。", },
	[720087] = {id=720087, zh_CN="站在高处干嘛？", },
	[720088] = {id=720088, zh_CN="喵。（翻译：芝麻糊在审视领地。）", },
	[720089] = {id=720089, zh_CN="你真的能爬上去？", },
	[720090] = {id=720090, zh_CN="喵喵~要看看我的英姿吗？", },
	[720091] = {id=720091, zh_CN="喵~喵，喵喵。", },
	[720092] = {id=720092, zh_CN="你在做什么呢？", },
	[720093] = {id=720093, zh_CN="我在尝试用猫语和你交流啊。", },
	[720094] = {id=720094, zh_CN="喵……（翻译：别丢猫现眼了！）", },
	[720095] = {id=720095, zh_CN="喵喵喵！那这样说呢？", },
	[720096] = {id=720096, zh_CN="喵！不要胡言乱语了。", },
	[720097] = {id=720097, zh_CN="刚才发音标准吗？", },
	[720098] = {id=720098, zh_CN="喵嗷！（翻译：第三声要上扬~）", },
	[720099] = {id=720099, zh_CN="哎呀，这语言也太难掌握了吧。", },
	[720100] = {id=720100, zh_CN="还是用你习惯的语言交流喵~", },
	[720101] = {id=720101, zh_CN="哎呀，这语言也太难掌握了吧。", },
	[720102] = {id=720102, zh_CN="还是用你习惯的语言交流喵~", },
	[720103] = {id=720103, zh_CN="我觉得我可能也是一只猫。", },
	[720104] = {id=720104, zh_CN="喵！猫猫的优雅你都没掌握~", },
	[720105] = {id=720105, zh_CN="谁说我不优雅了？", },
	[720106] = {id=720106, zh_CN="你踏入喵喵界也还差得远呢。", },
	[720107] = {id=720107, zh_CN="想冲你多喵两声。喵~喵~喵~", },
	[720108] = {id=720108, zh_CN="离我远点，喵！", },
	[720109] = {id=720109, zh_CN="就不！我偏要凑过来！", },
	[720110] = {id=720110, zh_CN="放肆！你这个没有边界感的家伙！", },
	[720111] = {id=720111, zh_CN="咳，开个玩笑。", },
	[720112] = {id=720112, zh_CN="你的精神状态真令芝麻糊担心。", },
	[720113] = {id=720113, zh_CN="承认吧，你期待和我亲近对吧？", },
	[720114] = {id=720114, zh_CN="喵！？胡…胡言乱语！！", },
	[720115] = {id=720115, zh_CN="你尾巴都紧张得绷直了。", },
	[720116] = {id=720116, zh_CN="这、这是只是随时戒备的标志。", },
	[720117] = {id=720117, zh_CN="摸摸你，休息一下吧。", },
	[720118] = {id=720118, zh_CN="喵，休息一下……可不是亲近你。", },
	[720119] = {id=720119, zh_CN="唉，只是我一厢情愿吗？", },
	[720120] = {id=720120, zh_CN="喵呜……本喵没有否认！", },
	[720121] = {id=720121, zh_CN="唉，只是我一厢情愿吗？", },
	[720122] = {id=720122, zh_CN="喵呜……本喵没有否认！", },
	[720123] = {id=720123, zh_CN="换个说法，是我想亲近你。", },
	[720124] = {id=720124, zh_CN="咳，芝麻糊确实不排斥你。", },
	[720125] = {id=720125, zh_CN="开个玩笑，别紧张。", },
	[720126] = {id=720126, zh_CN="算你识相！", },
	[720127] = {id=720127, zh_CN="咳……！！没有的事！", },
	[720128] = {id=720128, zh_CN="那你为什么要心虚地咳嗽？", },
	[720129] = {id=720129, zh_CN="因为，因为吃到毛毛了。", },
	[720130] = {id=720130, zh_CN="我想…了解芝麻糊更多的事。", },
	[720131] = {id=720131, zh_CN="如果是你，芝麻糊也能分享。", },
	[720132] = {id=720132, zh_CN="年糕和你的性格似乎很不一样呢？", },
	[720133] = {id=720133, zh_CN="即使是姐弟，性格也会不同喵。", },
	[720134] = {id=720134, zh_CN="芝麻糊是怎么评价年糕的呢？", },
	[720135] = {id=720135, zh_CN="一个笨弟弟，但我会给它兜底。", },
	[720136] = {id=720136, zh_CN="芝麻糊如此优雅、高贵，傲娇……", },
	[720137] = {id=720137, zh_CN="喵！听到了一个不该属于我的词汇！", },
	[720138] = {id=720138, zh_CN="贵族小猫傲娇一点更显高贵。", },
	[720139] = {id=720139, zh_CN="喵~（翻译：那是自然！）", },
	[720140] = {id=720140, zh_CN="分享一下和年糕的旧故事？", },
	[720141] = {id=720141, zh_CN="喵嗷…年糕上次爬到树上吓哭了。", },
	[720142] = {id=720142, zh_CN="那它怎么下来的？", },
	[720143] = {id=720143, zh_CN="当然是我拯救了胆小鬼弟弟。", },
	[720144] = {id=720144, zh_CN="你看起来不太高兴。", },
	[720145] = {id=720145, zh_CN="喵…这么明显吗？", },
	[720146] = {id=720146, zh_CN="是啊，都写在你脸上了。", },
	[720147] = {id=720147, zh_CN="喵嗷，贵族小猫也会心烦。", },
	[720148] = {id=720148, zh_CN="我可以帮你什么忙吗", },
	[720149] = {id=720149, zh_CN="喵，芝麻糊会自己想办法解决。", },
	[720150] = {id=720150, zh_CN="也许你需要一点甜食？", },
	[720151] = {id=720151, zh_CN="咕噜……（翻译：本殿下才不馋。）", },
	[720152] = {id=720152, zh_CN="遇到什么麻烦了？", },
	[720153] = {id=720153, zh_CN="喵。（翻译：计划被打乱了。）", },
	[720154] = {id=720154, zh_CN="我帮你……理理思路？", },
	[720155] = {id=720155, zh_CN="好喵~不过最后是芝麻糊拿主意。", },
	[720156] = {id=720156, zh_CN="在谁那儿吃亏了？", },
	[720157] = {id=720157, zh_CN="胡说八道！芝麻糊怎么可能吃亏？", },
	[720158] = {id=720158, zh_CN="别气坏了聪明的脑袋。", },
	[720159] = {id=720159, zh_CN="不要摸我的脑袋，这次就算了。", },
	[720160] = {id=720160, zh_CN="喵？本喵好得很。", },
	[720161] = {id=720161, zh_CN="都写在你脸上了", },
	[720162] = {id=720162, zh_CN="……可恶，身体的本能背叛了我。", },
	[720163] = {id=720163, zh_CN="喵。（翻译：猫猫也会心烦。）", },
	[720164] = {id=720164, zh_CN="心情好些了吗？", },
	[720165] = {id=720165, zh_CN="喵~（翻译：没那么烦躁了。）", },
	[720166] = {id=720166, zh_CN="别气坏了聪明的脑袋。", },
	[720167] = {id=720167, zh_CN="不要摸我的脑袋，这次就算了。", },
	[720168] = {id=720168, zh_CN="那我下次不碰了。", },
	[720169] = {id=720169, zh_CN="喵……不是不行，你要提前打报告！", },
	[720170] = {id=720170, zh_CN="可是你刚才明明呼噜得很大声啊~", },
	[720171] = {id=720171, zh_CN="呼噜噜……胡、胡说八道！", },
	[720172] = {id=720172, zh_CN="也许你需要一点甜食？", },
	[720173] = {id=720173, zh_CN="都说了芝麻糊不馋嘴！", },
	[720174] = {id=720174, zh_CN="有什么高兴的事吗？", },
	[720175] = {id=720175, zh_CN="喵~眼尖的家伙。", },
	[720176] = {id=720176, zh_CN="你的尾巴都翘到屁股上了。", },
	[720177] = {id=720177, zh_CN="哼，芝麻糊不告诉你。", },
	[720178] = {id=720178, zh_CN="高兴到摇屁股", },
	[720179] = {id=720179, zh_CN="喵！才没有呢。", },
	[720180] = {id=720180, zh_CN="你今天好开心。", },
	[720181] = {id=720181, zh_CN="胡说！没有！", },
	[720182] = {id=720182, zh_CN="尾巴都飘起来了，芝麻糊。", },
	[720183] = {id=720183, zh_CN="喵！（翻译：这是贵族仪态！）", },
	[720184] = {id=720184, zh_CN="好好好，没有。", },
	[720185] = {id=720185, zh_CN="哼，算你懂事", },
	[720186] = {id=720186, zh_CN="要庆祝一下吗？", },
	[720187] = {id=720187, zh_CN="不需要！多此一举。", },
	[720188] = {id=720188, zh_CN="我给你带了甜品，吃一块？", },
	[720189] = {id=720189, zh_CN="咕噜……（翻译：也行。）", },
	[720190] = {id=720190, zh_CN="要打个滚吗？", },
	[720191] = {id=720191, zh_CN="放肆，谁要打滚。", },
	[720192] = {id=720192, zh_CN="你刚刚转圈打滚了。", },
	[720193] = {id=720193, zh_CN="芝麻糊那是舒展筋骨！", },
	[720194] = {id=720194, zh_CN="芝麻糊不会心脏加速了吧。", },
	[720195] = {id=720195, zh_CN="庸俗的推测，喵！", },
	[720196] = {id=720196, zh_CN="耳朵都红了喔。", },
	[720197] = {id=720197, zh_CN="喵！那是热的。", },
	[720198] = {id=720198, zh_CN="好好好，其实芝麻糊是有点热。", },
	[720199] = {id=720199, zh_CN="咕噜……", },
	[720200] = {id=720200, zh_CN="要出去溜达吗？", },
	[720201] = {id=720201, zh_CN="不需要你来做决定喵~", },
	[720202] = {id=720202, zh_CN="你要自己一个人独行吗？", },
	[720203] = {id=720203, zh_CN="你，你来也行。", },
	[720204] = {id=720204, zh_CN="那我就在这儿待着了。", },
	[720205] = {id=720205, zh_CN="哼！随你。", },
	[720206] = {id=720206, zh_CN="要我摸摸你吗？芝麻糊。", },
	[720207] = {id=720207, zh_CN="喵？才不要，谁让你来的。", },
	[720208] = {id=720208, zh_CN="芝麻糊，给我摸摸，好不好？", },
	[720209] = {id=720209, zh_CN="咕噜，好吧，多摸摸我……\"", },
	[720210] = {id=720210, zh_CN="不管，摸了！", },
	[720211] = {id=720211, zh_CN="咕噜噜……算了。", },
	[720212] = {id=720212, zh_CN="我听到你的心声咯。", },
	[720213] = {id=720213, zh_CN="喵！芝麻糊什么都没有想。", },
	[720214] = {id=720214, zh_CN="好吧，那我什么都没听见。", },
	[720215] = {id=720215, zh_CN="咕噜，摸吧摸吧。", },
	[720216] = {id=720216, zh_CN="我不客气了！", },
	[720217] = {id=720217, zh_CN="别太得寸进尺喵……呼噜噜。", },
	[720218] = {id=720218, zh_CN="要一起跳舞吗？", },
	[720219] = {id=720219, zh_CN="现在不适合跳……", },
	[720220] = {id=720220, zh_CN="我来邀请你共舞一曲？", },
	[720221] = {id=720221, zh_CN="咕噜，尾巴别踩！", },
	[720222] = {id=720222, zh_CN="芝麻糊老师先示范一下？", },
	[720223] = {id=720223, zh_CN="睁大眼睛欣赏芝麻糊吧。", },
	[720224] = {id=720224, zh_CN="你刚刚在转圈跳舞吗？", },
	[720225] = {id=720225, zh_CN="那是猫猫舒展腰身！", },
	[720226] = {id=720226, zh_CN="这是你编造的吧，其实你在跳舞。", },
	[720227] = {id=720227, zh_CN="喵嗷！（翻译：胡说！）", },
	[720228] = {id=720228, zh_CN="芝麻糊跳得真好看。", },
	[720229] = {id=720229, zh_CN="咕噜噜……那是自然。", },
	[720230] = {id=720230, zh_CN="今日状态很好哦，芝麻糊。", },
	[720231] = {id=720231, zh_CN="优雅小猫的日常而已。", },
	[720232] = {id=720232, zh_CN="因为吃到了喜欢的甜品吗？", },
	[720233] = {id=720233, zh_CN="喵嗷，倒也不完全是。", },
	[720234] = {id=720234, zh_CN="今日状态好的原因是什么呢？", },
	[720235] = {id=720235, zh_CN="才不告诉你，喵！", },
	[720236] = {id=720236, zh_CN="要一起发呆吗？", },
	[720237] = {id=720237, zh_CN="芝麻糊才不是发呆。", },
	[720238] = {id=720238, zh_CN="不管你在做什么，我陪陪你。", },
	[720239] = {id=720239, zh_CN="咕噜……随便你。", },
	[720240] = {id=720240, zh_CN="那我走了哦。", },
	[720241] = {id=720241, zh_CN="等……等一下别走。", },
	[720242] = {id=720242, zh_CN="今天天气不错哦，芝麻糊", },
	[720243] = {id=720243, zh_CN="今天天气暖烘烘的。", },
	[720244] = {id=720244, zh_CN="那我们一起出去走走？", },
	[720245] = {id=720245, zh_CN="现在是芝麻糊的下午茶时间，不出门喵。", },
	[720246] = {id=720246, zh_CN="适合品尝下午茶的好天气。", },
	[720247] = {id=720247, zh_CN="我可以加入你的下午茶吗？", },
	[720248] = {id=720248, zh_CN="喵嗷，看在天气不错，可以喵。", },
	[720249] = {id=720249, zh_CN="你在想什么，芝麻糊。", },
	[720250] = {id=720250, zh_CN="我在思考……", },
	[720251] = {id=720251, zh_CN="在思考什么，说来听听？", },
	[720252] = {id=720252, zh_CN="第一条：还我清净。", },
	[720253] = {id=720253, zh_CN="我对芝麻糊不太感兴趣哦。", },
	[720254] = {id=720254, zh_CN="无趣，哼！", },
	[720255] = {id=720255, zh_CN="要我帮你梳梳毛吗？", },
	[720256] = {id=720256, zh_CN="谁让你来的，你怎么知道……", },
	[720257] = {id=720257, zh_CN="我知道你很想梳毛的。", },
	[720258] = {id=720258, zh_CN="喵！不准这样无礼。", },
	[720259] = {id=720259, zh_CN="要接受我的服务吗？", },
	[720260] = {id=720260, zh_CN="咕噜……那好吧。", },
	[720261] = {id=720261, zh_CN="很烦，是我惹到你了？", },
	[720262] = {id=720262, zh_CN="也没有，芝麻糊就是烦。", },
	[720263] = {id=720263, zh_CN="那我先离开咯。", },
	[720264] = {id=720264, zh_CN="喵……也别走太远。", },
	[720265] = {id=720265, zh_CN="有我陪着你，芝麻糊。", },
	[720266] = {id=720266, zh_CN="咕噜，随便你。", },
	[720267] = {id=720267, zh_CN="我不打扰你了", },
	[720268] = {id=720268, zh_CN="喵……倒也不必。", },
	[720269] = {id=720269, zh_CN="有我陪着你，芝麻糊。", },
	[720270] = {id=720270, zh_CN="靠近一点也行喵~", },
	[720271] = {id=720271, zh_CN="那我走了哦。", },
	[720272] = {id=720272, zh_CN="嗯，等等，别走。", },
	[720273] = {id=720273, zh_CN="遇到什么烦心事了？", },
	[720274] = {id=720274, zh_CN="喵嗷~（翻译：别啰嗦！）", },
	[720275] = {id=720275, zh_CN="好，我不问了。", },
	[720276] = {id=720276, zh_CN="喵。", },
	[720277] = {id=720277, zh_CN="有我陪着你，芝麻糊。", },
	[720278] = {id=720278, zh_CN="喵，让芝麻糊躺一会。", },
	[720279] = {id=720279, zh_CN="看我给你带了什么？", },
	[720280] = {id=720280, zh_CN="喵嗷，芝麻糊哪儿有心情？", },
	[720281] = {id=720281, zh_CN="是亮闪闪哦~", },
	[720282] = {id=720282, zh_CN="喵？快给芝麻糊瞧瞧。", },
	[720283] = {id=720283, zh_CN="是你最爱的海苔小鱼干。", },
	[720284] = {id=720284, zh_CN="咕噜……大吃一口。", },
	[720285] = {id=720285, zh_CN="我去帮你出气？", },
	[720286] = {id=720286, zh_CN="我要自己来，不用你帮忙。", },
	[720287] = {id=720287, zh_CN="芝麻糊你说怎么办？", },
	[720288] = {id=720288, zh_CN="先给我消消气喵~", },
	[720289] = {id=720289, zh_CN="到底谁惹你了？", },
	[720290] = {id=720290, zh_CN="总之，你离远点。", },
	[720291] = {id=720291, zh_CN="先冷静冷静，芝麻糊。", },
	[720292] = {id=720292, zh_CN="芝麻糊很冷静！", },
	[720293] = {id=720293, zh_CN="先吃小鱼干，消消气。", },
	[720294] = {id=720294, zh_CN="咕噜……等我嚼完再说。", },
	[720295] = {id=720295, zh_CN="摸摸脑袋好了。", },
	[720296] = {id=720296, zh_CN="喵呼噜噜……", },
	[720297] = {id=720297, zh_CN="先冷静冷静，芝麻糊。", },
	[720298] = {id=720298, zh_CN="芝麻糊清算完再说！", },
	[720299] = {id=720299, zh_CN="先吃小鱼干，消消气。", },
	[720300] = {id=720300, zh_CN="咕噜……等我嚼完再说。", },
	[720301] = {id=720301, zh_CN="贵族小猫要保持优雅，不气不气。", },
	[720302] = {id=720302, zh_CN="咕噜……你说得有点道理。", },
	[720303] = {id=720303, zh_CN="我替你讨回公道！", },
	[720304] = {id=720304, zh_CN="快去快去，他们都欺负我。", },
	[720305] = {id=720305, zh_CN="好！你说，怎么报仇。", },
	[720306] = {id=720306, zh_CN="把那个……喵，算了吧。", },
	[720307] = {id=720307, zh_CN="们对你做什么了，这么生气？", },
	[720308] = {id=720308, zh_CN="不想说喵，你只要站在我身边就行。", },
	[720309] = {id=720309, zh_CN="芝麻糊，你盯着墙角看什么呢？", },
	[720310] = {id=720310, zh_CN="喵……", },
	[720311] = {id=720311, zh_CN="芝麻糊，你说什么？", },
	[720312] = {id=720312, zh_CN="喵呜。（翻译：我只是发呆，不要打扰我。）", },
	[720313] = {id=720313, zh_CN="难道那里有小虫子？", },
	[720314] = {id=720314, zh_CN="离芝麻糊太近了。", },
	[720315] = {id=720315, zh_CN="那你慢慢看。", },
	[720316] = {id=720316, zh_CN="咕噜……", },
	[720317] = {id=720317, zh_CN="芝麻糊，我帮你理理毛？", },
	[720318] = {id=720318, zh_CN="喵呜~（翻译：准了。）", },
	[720319] = {id=720319, zh_CN="遵命。", },
	[720320] = {id=720320, zh_CN="呼噜噜……（翻译：左边再重一点。）", },
	[720321] = {id=720321, zh_CN="你的毛好像变稀了。", },
	[720322] = {id=720322, zh_CN="喵嗷！（翻译：诽谤！）", },
	[720323] = {id=720323, zh_CN="额，你舒服得都流口水了。", },
	[720324] = {id=720324, zh_CN="喵！不准说了。", },
	[720325] = {id=720325, zh_CN="芝麻糊，你今天真的很优雅。", },
