	[720495] = {id=720495, zh_CN="有什么能帮您的？", },
	[720496] = {id=720496, zh_CN="喵。（翻译：没空理你。）", },
	[720497] = {id=720497, zh_CN="芝麻糊不需要帮助。", },
	[720498] = {id=720498, zh_CN="别急，陪我聊聊？", },
	[720499] = {id=720499, zh_CN="喵呜。（翻译：勉强准了。）", },
	[720500] = {id=720500, zh_CN="我先忙了。", },
	[720501] = {id=720501, zh_CN="喵。（翻译：随便你。）", },
	[720502] = {id=720502, zh_CN="关于古堡聚会的事…", },
	[720503] = {id=720503, zh_CN="作为古堡的主人，要公平公正。", },
	[720504] = {id=720504, zh_CN="谁是\"邪恶阵营\"的呢？", },
	[720505] = {id=720505, zh_CN="芝麻糊不喜欢愚蠢的问题。", },
	[720506] = {id=720506, zh_CN="被驱逐的人，自然会了解。", },
	[720507] = {id=720507, zh_CN="淘汰了我自己就知道啦！", },
	[720508] = {id=720508, zh_CN="喵嗷~（翻译：不过是说说。别放心上。）", },
	[720509] = {id=720509, zh_CN="关于古堡聚会的事…", },
	[720510] = {id=720510, zh_CN="作为古堡的主人，要公平公正。", },
	[720511] = {id=720511, zh_CN="我就是邪恶阵营！", },
	[720512] = {id=720512, zh_CN="喵！别随便说出来。", },
	[720513] = {id=720513, zh_CN="能给点建议吗？", },
	[720514] = {id=720514, zh_CN="落单的猫会被抓走。你也一样。", },
	[720515] = {id=720515, zh_CN="喵嗷~有空就去做任务。可以推动胜利。", },
	[720516] = {id=720516, zh_CN="喵嗷~（翻译：躲在暗处，等目标落单。）", },
	[720517] = {id=720517, zh_CN="做任务时多留意周围。小心偷袭。", },
	[720518] = {id=720518, zh_CN="想和你说说话。", },
	[720519] = {id=720519, zh_CN="喵嗷~（翻译：说吧。）", },
	[720520] = {id=720520, zh_CN="古堡有什么秘密嘛？", },
	[720521] = {id=720521, zh_CN="喵。（翻译：秘密？芝麻糊不随便说。）", },
	[720522] = {id=720522, zh_CN="偷偷告诉我。", },
	[720523] = {id=720523, zh_CN="别在古堡里乱走。芝麻糊提醒你了。", },
	[720524] = {id=720524, zh_CN="如果你参加聚会……", },
	[720525] = {id=720525, zh_CN="喵嗷~（翻译：那就有趣多了。）", },
	[720526] = {id=720526, zh_CN="请务必带带我！", },
	[720527] = {id=720527, zh_CN="喵。（翻译：靠自己。）", },
	[720528] = {id=720528, zh_CN="如果是邪恶阵营，你会做什么呢？", },
	[720529] = {id=720529, zh_CN="潜伏。用猫的方式接近目标。", },
	[720530] = {id=720530, zh_CN="听起来有点可怕……", },
	[720531] = {id=720531, zh_CN="怕就对了。", },
	[720532] = {id=720532, zh_CN="能助我好运吗。", },
	[720533] = {id=720533, zh_CN="喵嗷~（翻译：好运这东西，不存在的。）", },
	[720534] = {id=720534, zh_CN="芝麻糊靠实力，不靠运气。", },
	[720535] = {id=720535, zh_CN="芝麻糊，你需要帮忙吗？", },
	[720536] = {id=720536, zh_CN="喵嗷~（翻译：把【烛台】点燃。）", },
	[720537] = {id=720537, zh_CN="交给我吧。", },
	[720538] = {id=720538, zh_CN="拜托了喵", },
