	[73000] = {id=73000, zh_CN="奥黛特，在忙什么？", },
	[73001] = {id=73001, zh_CN="在看新到的货品清单。", },
	[73002] = {id=73002, zh_CN="有我的份吗？", },
	[73003] = {id=73003, zh_CN="我会给你满意的折扣。", },
	[73004] = {id=73004, zh_CN="别太累了。", },
	[73005] = {id=73005, zh_CN="关心我？那陪我坐会儿。", },
	[73006] = {id=73006, zh_CN="奥黛特，你用过餐了吗？", },
	[73007] = {id=73007, zh_CN="忙到忘记了用餐时间。", },
	[73008] = {id=73008, zh_CN="一起吃点？", },
	[73009] = {id=73009, zh_CN="明智的选择，走吧。", },
	[73010] = {id=73010, zh_CN="我带了甜点。", },
	[73011] = {id=73011, zh_CN="呵呵，真是体贴。", },
	[73012] = {id=73012, zh_CN="看起来很疲惫？", },
	[73013] = {id=73013, zh_CN="被你发现了，亲爱的。", },
	[73014] = {id=73014, zh_CN="喝杯热茶吧。", },
	[73015] = {id=73015, zh_CN="谢谢你的茶，我很喜欢。", },
	[73016] = {id=73016, zh_CN="休息一下。", },
	[73017] = {id=73017, zh_CN="只要有你，我就不累。", },
	[73018] = {id=73018, zh_CN="你袖口沾到灰尘了。", },
	[73019] = {id=73019, zh_CN="真是失礼，谢谢提醒。", },
	[73020] = {id=73020, zh_CN="帮你清理。", },
	[73021] = {id=73021, zh_CN="你的手很温柔，亲爱的。", },
	[73022] = {id=73022, zh_CN="换件裙装？", },
	[73023] = {id=73023, zh_CN="陪我去试衣间挑选？", },
	[73024] = {id=73024, zh_CN="我想要内部优惠。", },
	[73025] = {id=73025, zh_CN="给你用我的个人折扣额度。", },
	[73026] = {id=73026, zh_CN="真的吗？", },
	[73027] = {id=73027, zh_CN="只要你开口，都可以。", },
	[73028] = {id=73028, zh_CN="太贵重了。", },
	[73029] = {id=73029, zh_CN="我们之间，不谈钱。", },
	[73030] = {id=73030, zh_CN="今天阳光很不错。", },
	[73031] = {id=73031, zh_CN="正适合谈一笔生意。", },
	[73032] = {id=73032, zh_CN="是……跟我谈吗？", },
	[73033] = {id=73033, zh_CN="当然可以，亲爱的，你愿意吗？", },
	[73034] = {id=73034, zh_CN="比如？", },
	[73035] = {id=73035, zh_CN="比如，共进一次晚餐。", },
	[73036] = {id=73036, zh_CN="今天这身很衬你。", },
	[73037] = {id=73037, zh_CN="亲爱的，专为见你挑选的。", },
	[73038] = {id=73038, zh_CN="你迷住我了。", },
	[73039] = {id=73039, zh_CN="你的眼光一向卓越。", },
	[73040] = {id=73040, zh_CN="没有见过，是商会新款吗？", },
	[73041] = {id=73041, zh_CN="是的，你可以在我这里购入哦。", },
	[73042] = {id=73042, zh_CN="赢得很漂亮？", },
	[73043] = {id=73043, zh_CN="我将拿下这次交易的全部赢面。", },
	[73044] = {id=73044, zh_CN="一起庆祝一下？", },
	[73045] = {id=73045, zh_CN="你请客吗……开玩笑，当然。", },
	[73046] = {id=73046, zh_CN="可以分我一点利润？", },
	[73047] = {id=73047, zh_CN="你说笑了。", },
	[73048] = {id=73048, zh_CN="盯上谁了？", },
	[73049] = {id=73049, zh_CN="遇到一个自以为是的对手。", },
	[73050] = {id=73050, zh_CN="祝你成功。", },
	[73051] = {id=73051, zh_CN="结局早已注定了，亲爱的。", },
	[73052] = {id=73052, zh_CN="奥黛特，别太心狠。", },
	[73053] = {id=73053, zh_CN="商业场，从不留情。", },
	[73054] = {id=73054, zh_CN="找到宝贝了？", },
	[73055] = {id=73055, zh_CN="真是一件独一无二的奇物。", },
	[73056] = {id=73056, zh_CN="像我一样独一无二？", },
	[73057] = {id=73057, zh_CN="你比他们都更有趣。", },
	[73058] = {id=73058, zh_CN="给我看看。", },
	[73059] = {id=73059, zh_CN="抱歉，现在的你还没权限。", },
	[73060] = {id=73060, zh_CN="诸事顺遂？", },
	[73061] = {id=73061, zh_CN="月影商会，蒸蒸日上。", },
	[73062] = {id=73062, zh_CN="这都是你的功劳。", },
	[73063] = {id=73063, zh_CN="这是我们共同的成功。", },
	[73064] = {id=73064, zh_CN="奥黛特，你请客吃饭？", },
	[73065] = {id=73065, zh_CN="想要什么，随便点。", },
	[73066] = {id=73066, zh_CN="甜品好吗？", },
	[73067] = {id=73067, zh_CN="甜度刚好，沁人心脾。", },
	[73068] = {id=73068, zh_CN="要不要再来一块？", },
	[73069] = {id=73069, zh_CN="诱惑我，但难拒绝。", },
	[73070] = {id=73070, zh_CN="可以分我尝一口吗？", },
	[73071] = {id=73071, zh_CN="你真像个孩子啊。", },
	[73072] = {id=73072, zh_CN="感觉很放松？", },
	[73073] = {id=73073, zh_CN="难得不需要算计。", },
	[73074] = {id=73074, zh_CN="奥黛特，我想要一个拥抱。", },
	[73075] = {id=73075, zh_CN="当然可以，亲爱的。", },
	[73076] = {id=73076, zh_CN="我陪你坐一会。", },
	[73077] = {id=73077, zh_CN="我很珍惜片刻的宁静。", },
	[73078] = {id=73078, zh_CN="在衡量我？", },
	[73079] = {id=73079, zh_CN="我正在评估投资价值。", },
	[73080] = {id=73080, zh_CN="评估的结果如何？", },
	[73081] = {id=73081, zh_CN="你的价值超乎我想象，亲爱的。", },
	[73082] = {id=73082, zh_CN="奥黛特，你需要感性一点。", },
	[73083] = {id=73083, zh_CN="理智，是我的护身符。", },
	[73084] = {id=73084, zh_CN="出现偏差了？", },
	[73085] = {id=73085, zh_CN="我讨厌意外带来的风险。", },
	[73086] = {id=73086, zh_CN="我来帮你，别怕。", },
	[73087] = {id=73087, zh_CN="哦？向我展示一下你的价值吧。", },
	[73088] = {id=73088, zh_CN="奥黛特，别太在意了。", },
	[73089] = {id=73089, zh_CN="我不允许发生失败。", },
	[73090] = {id=73090, zh_CN="杂事很多吗？", },
	[73091] = {id=73091, zh_CN="毫无意义的重复性工作。", },
	[73092] = {id=73092, zh_CN="我帮你分担一些。", },
	[73093] = {id=73093, zh_CN="亲爱的，你真可靠。", },
	[73094] = {id=73094, zh_CN="我们一起换个心情？", },
	[73095] = {id=73095, zh_CN="听你的，一起去喝杯热茶。", },
	[73096] = {id=73096, zh_CN="谁惹你了？", },
	[73097] = {id=73097, zh_CN="某些不知好歹的跳蚤。", },
	[73098] = {id=73098, zh_CN="奥黛特，别气坏了。", },
	[73099] = {id=73099, zh_CN="既然敢做，他们就得付出。", },
	[73100] = {id=73100, zh_CN="我帮你教训他们。", },
	[73101] = {id=73101, zh_CN="这种脏活，不必劳烦你。", },
	[73102] = {id=73102, zh_CN="计划全乱了？", },
	[73103] = {id=73103, zh_CN="错误必须被彻底抹除。", },
	[73104] = {id=73104, zh_CN="别被怒火冲昏头脑。", },
	[73105] = {id=73105, zh_CN="你说得对，亲爱的。", },
	[73106] = {id=73106, zh_CN="我们离开这里，我带你走。", },
	[73107] = {id=73107, zh_CN="亲爱的，你想私奔吗？", },
	[73108] = {id=73108, zh_CN="奥黛特，今天太阳是不是太大了？", },
	[73109] = {id=73109, zh_CN="我觉得今天阳光挺好的。", },
	[73110] = {id=73110, zh_CN="但走在路上真的好晒啊……", },
	[73111] = {id=73111, zh_CN="要购入我旗下的阳伞吗，很好用哦。", },
