	[73115] = {id=73115, zh_CN="只有能提升社交效率，我都可以尝试。", },
	[73116] = {id=73116, zh_CN="那你个人有没有特别喜欢的？", },
	[73117] = {id=73117, zh_CN="唔……我没有特别的偏好。", },
	[73118] = {id=73118, zh_CN="我知道一家超赞的店！", },
	[73119] = {id=73119, zh_CN="听起来，翻台率太高，不适合聊天呢。", },
	[73120] = {id=73120, zh_CN="奥黛特，你今天这身衣服真漂亮。", },
	[73121] = {id=73121, zh_CN="谢谢，亲爱的。", },
	[73122] = {id=73122, zh_CN="你的眼光真的没话说。", },
	[73123] = {id=73123, zh_CN="亲爱的，毕竟我是商会会长。", },
	[73124] = {id=73124, zh_CN="哈哈，好看就行。", },
	[73125] = {id=73125, zh_CN="亲爱的，美丽是推销自己最快捷的名片。", },
