	[74004] = {id=74004, zh_CN="汪……其实小金毛还没吃饱汪。", },
	[74005] = {id=74005, zh_CN="给你买个香喷喷的面包吃吧？", },
	[74006] = {id=74006, zh_CN="真的吗？谢谢你，你真好汪！", },
	[74007] = {id=74007, zh_CN="走，我带你去大餐。", },
	[74008] = {id=74008, zh_CN="汪！%PlayerName 最好了！", },
	[74009] = {id=74009, zh_CN="今天天气真不错呀。", },
	[74010] = {id=74010, zh_CN="汪！阳光闻起来香喷喷的！", },
	[74011] = {id=74011, zh_CN="适合出去玩。", },
	[74012] = {id=74012, zh_CN="快带小金毛跑起来汪！", },
	[74013] = {id=74013, zh_CN="要不要在这里睡个觉？", },
