	[74015] = {id=74015, zh_CN="感觉真惬意。", },
	[74016] = {id=74016, zh_CN="只要你陪着小金毛，天天是好天。", },
	[74017] = {id=74017, zh_CN="今天心情怎么样？", },
	[74018] = {id=74018, zh_CN="看到你，尾巴就停不下来！", },
	[74019] = {id=74019, zh_CN="这么喜欢我？", },
