	[74021] = {id=74021, zh_CN="让我也分一点你的好心情。", },
	[74022] = {id=74022, zh_CN="汪！那我们就一起转个圈！", },
	[74023] = {id=74023, zh_CN="城里有啥新鲜事？", },
