	[74025] = {id=74025, zh_CN="偷偷告诉我哪只猫呀？", },
	[74026] = {id=74026, zh_CN="嘿嘿，就是那只披风猫汪。", },
	[74027] = {id=74027, zh_CN="嘿嘿，又有大八卦要发生啦！", },
	[74028] = {id=74028, zh_CN="快跟我也分享一下那个瓜。", },
	[74029] = {id=74029, zh_CN="有一对小情侣最近在吵架哦。", },
	[74030] = {id=74030, zh_CN="每天都这么八卦，不累吗？", },
	[74031] = {id=74031, zh_CN="汪！这是了解世界的办法！", },
	[74032] = {id=74032, zh_CN="小金毛，你看起来不舒服？", },
