	[74274] = {id=74274, zh_CN="汪！一个人乱跑很危险的！", },
	[74275] = {id=74275, zh_CN="有任务就去做，可以推动胜利！汪！", },
	[74276] = {id=74276, zh_CN="汪，是坏人就偷偷跟上落单目标！", },
	[74277] = {id=74277, zh_CN="做任务时多留意四周，汪汪！", },
	[74278] = {id=74278, zh_CN="想和你说说话。", },
	[74279] = {id=74279, zh_CN="汪汪！说说说，小金毛在听！", },
	[74280] = {id=74280, zh_CN="古堡有什么秘密嘛？", },
	[74281] = {id=74281, zh_CN="秘密？小金毛知道一点点！", },
	[74282] = {id=74282, zh_CN="偷偷告诉我。", },
	[74283] = {id=74283, zh_CN="汪汪，夜里脚步声要小心！", },
	[74284] = {id=74284, zh_CN="如果你参加聚会……", },
	[74285] = {id=74285, zh_CN="要是小金毛参加，肯定超强！汪！", },
	[74286] = {id=74286, zh_CN="请务必带带我！", },
	[74287] = {id=74287, zh_CN="汪，入戏还是靠自己啦！", },
	[74288] = {id=74288, zh_CN="如果是邪恶阵营，你会做什么呢？", },
	[74289] = {id=74289, zh_CN="小金毛会偷偷跟踪目标，汪！", },
	[74290] = {id=74290, zh_CN="听起来有点可怕……", },
	[74291] = {id=74291, zh_CN="汪汪，小金毛其实挺厉害的！", },
	[74292] = {id=74292, zh_CN="能助我好运吗。", },
	[74293] = {id=74293, zh_CN="汪！小金毛替你祈求好运！", },
	[74294] = {id=74294, zh_CN="好运好运，汪汪加油！", },
	[74295] = {id=74295, zh_CN="需要我做些什么？", },
	[74296] = {id=74296, zh_CN="把【烛台】点燃，有报酬的，汪！", },
	[74297] = {id=74297, zh_CN="交给我吧。", },
	[74298] = {id=74298, zh_CN="汪汪！拜托啦！", },
