	[74300] = {id=74300, zh_CN="没问题。", },
	[74301] = {id=74301, zh_CN="汪汪！拜托啦！", },
	[74302] = {id=74302, zh_CN="去取一截【苹果树枝】来，汪！", },
	[74303] = {id=74303, zh_CN="稍等片刻。", },
	[74304] = {id=74304, zh_CN="汪汪！拜托啦！", },
	[74305] = {id=74305, zh_CN="帮小金毛把【壁画】拓印回来！", },
	[74306] = {id=74306, zh_CN="我知道了。", },
	[74307] = {id=74307, zh_CN="汪汪！拜托啦！", },
	[74308] = {id=74308, zh_CN="擦净【预言镜】，汪汪，拜托啦！", },
	[74309] = {id=74309, zh_CN="很快回来。", },
	[74310] = {id=74310, zh_CN="汪汪！拜托啦！", },
	[74311] = {id=74311, zh_CN="把教会的书籍解读一下！汪汪！", },
