	[74313] = {id=74313, zh_CN="汪汪！拜托啦！", },
	[74314] = {id=74314, zh_CN="交给我吧。", },
	[74315] = {id=74315, zh_CN="汪汪！拜托啦！", },
	[74316] = {id=74316, zh_CN="我会留意的", },
	[74317] = {id=74317, zh_CN="汪汪！拜托啦！", },
	[74318] = {id=74318, zh_CN="我会尽力", },
	[74319] = {id=74319, zh_CN="汪汪！拜托啦！", },
