	[74331] = {id=74331, zh_CN="古堡见闻", },
	[74332] = {id=74332, zh_CN="询问秘密", },
	[74333] = {id=74333, zh_CN="假设身份", },
	[74334] = {id=74334, zh_CN="求带飞", },
	[74335] = {id=74335, zh_CN="邪恶阵营", },
	[74336] = {id=74336, zh_CN="害怕", },
	[74337] = {id=74337, zh_CN="祝我好运", },
	[74338] = {id=74338, zh_CN="询问任务", },
	[74339] = {id=74339, zh_CN="我明白了", },
	[75000] = {id=75000, zh_CN="最近过得怎么样？", },
	[75001] = {id=75001, zh_CN="还不错，日子挺充实的。", },
	[75002] = {id=75002, zh_CN="又是美好的一天，对吧？", },
	[75003] = {id=75003, zh_CN="确实，希望一直如此。", },
	[75004] = {id=75004, zh_CN="真高兴又见到你了。", },
	[75005] = {id=75005, zh_CN="我也是，见到你很开心。", },
	[75006] = {id=75006, zh_CN="这里的风景，你喜欢吗？", },
	[75007] = {id=75007, zh_CN="很美，适合发呆。", },
	[75008] = {id=75008, zh_CN="和你在一起的时光很开心。", },
	[75009] = {id=75009, zh_CN="嗯，我也是。", },
	[75010] = {id=75010, zh_CN="我们还挺有共同语言的。", },
	[75011] = {id=75011, zh_CN="对吧？我也这么觉得~", },
	[75012] = {id=75012, zh_CN="嘿，好巧，又见面了。", },
	[75013] = {id=75013, zh_CN="是啊。", },
	[75014] = {id=75014, zh_CN="还在忙手头的事情吗？", },
	[75015] = {id=75015, zh_CN="快忙完了，正好歇一歇。", },
	[75016] = {id=75016, zh_CN="如果你需要帮忙，我会帮助你的。", },
	[75017] = {id=75017, zh_CN="谢谢，但我自己能应付的~", },
	[75018] = {id=75018, zh_CN="太忙碌的话，记得想到我。", },
	[75019] = {id=75019, zh_CN="谢谢，但我自己能应付的~", },
	[75020] = {id=75020, zh_CN="你今天看起来很不错！", },
	[75021] = {id=75021, zh_CN="哎？是吗，谢谢。", },
	[75022] = {id=75022, zh_CN="感觉你今天特别有精神！", },
	[75023] = {id=75023, zh_CN="哈哈，托你的福啦", },
	[75024] = {id=75024, zh_CN="你脸色很差，是不是生病了？", },
	[75025] = {id=75025, zh_CN="脑袋晕乎乎，看东西有重影。", },
	[75026] = {id=75026, zh_CN="我这里有药，快服下。", },
	[75027] = {id=75027, zh_CN="还好有你在，谢谢。", },
	[75028] = {id=75028, zh_CN="去休息吧，别硬撑了。", },
	[75029] = {id=75029, zh_CN="嗯，我先去躺一会。", },
	[75030] = {id=75030, zh_CN="听到你肚子在咕咕叫了？", },
	[75031] = {id=75031, zh_CN="唔……思考都变慢了。", },
	[75032] = {id=75032, zh_CN="快吃点东西补充能量。", },
	[75033] = {id=75033, zh_CN="哇，救命恩人！", },
	[75034] = {id=75034, zh_CN="想吃什么？我去买。", },
	[75035] = {id=75035, zh_CN="只要能填饱肚子就行。", },
	[75036] = {id=75036, zh_CN="感觉你现在幸福得冒泡？", },
	[75037] = {id=75037, zh_CN="嘿嘿，被你看穿了吗？", },
	[75038] = {id=75038, zh_CN="既然这么开心，抱一个？", },
	[75039] = {id=75039, zh_CN="当然可以！来抱抱~", },
	[75040] = {id=75040, zh_CN="走，带你去大餐一顿！", },
	[75041] = {id=75041, zh_CN="哇！那是最好的庆祝！", },
	[75042] = {id=75042, zh_CN="感觉你浑身是劲，要冲出去？", },
	[75043] = {id=75043, zh_CN="没错！感觉现在无所不能！", },
	[75044] = {id=75044, zh_CN="等等我，带我一个！", },
	[75045] = {id=75045, zh_CN="快快快，我们出发！", },
	[75046] = {id=75046, zh_CN="别跑太快，小心摔跤。", },
	[75047] = {id=75047, zh_CN="知道啦，我会注意的。", },
	[75048] = {id=75048, zh_CN="眼神闪亮亮的，发现宝藏了？", },
	[75049] = {id=75049, zh_CN="嘘，那是一个大发现！", },
	[75050] = {id=75050, zh_CN="我帮你捡过来看看？", },
	[75051] = {id=75051, zh_CN="太感谢了，快给我！", },
	[75052] = {id=75052, zh_CN="那是啥？快告诉我。", },
	[75053] = {id=75053, zh_CN="嘘，这是个大秘密！", },
	[75054] = {id=75054, zh_CN="感觉你现在想大声唱歌？", },
	[75055] = {id=75055, zh_CN="这种气氛，真想跳个舞！", },
	[75056] = {id=75056, zh_CN="我也来！咱们一起转圈。", },
	[75057] = {id=75057, zh_CN="好耶！转圈圈转圈圈~", },
	[75058] = {id=75058, zh_CN="跳得真棒！再来一个。", },
	[75059] = {id=75059, zh_CN="嘿嘿，我可是专业的。", },
	[75060] = {id=75060, zh_CN="嘴角上扬，遇到了好事？", },
	[75061] = {id=75061, zh_CN="嗯，今天真是个好日子。", },
	[75062] = {id=75062, zh_CN="遇到啥好事啦？说下。", },
	[75063] = {id=75063, zh_CN="就是觉得，阳光真暖。", },
	[75064] = {id=75064, zh_CN="我也很开心，送你个礼。", },
	[75065] = {id=75065, zh_CN="哇，今天真是好日子。", },
	[75066] = {id=75066, zh_CN="此时的他非常放松吧？", },
	[75067] = {id=75067, zh_CN="暖烘烘的，感觉真舒服。", },
	[75068] = {id=75068, zh_CN="我也歇会儿，这儿挺好。", },
	[75069] = {id=75069, zh_CN="是吧，这种感觉真好。", },
	[75070] = {id=75070, zh_CN="嘘，咱们静静享受。", },
	[75071] = {id=75071, zh_CN="嗯，这一刻太治愈了。", },
	[75072] = {id=75072, zh_CN="盯着某处看，在发呆吗？", },
	[75073] = {id=75073, zh_CN="只是觉得，世界很安静。", },
	[75074] = {id=75074, zh_CN="嗨，你在看什么呢？", },
	[75075] = {id=75075, zh_CN="没什么，就发发呆。", },
	[75076] = {id=75076, zh_CN="不吵你了，你先歇着。", },
	[75077] = {id=75077, zh_CN="好哦，回见。", },
	[75078] = {id=75078, zh_CN="眉头微皱，遇到烦心事了？", },
	[75079] = {id=75079, zh_CN="别提了，感觉有点扫兴。", },
	[75080] = {id=75080, zh_CN="别难过，我会陪着你。", },
	[75081] = {id=75081, zh_CN="谢谢你，心里好受点。", },
	[75082] = {id=75082, zh_CN="看那个！是不是很有趣？", },
	[75083] = {id=75083, zh_CN="噗，确实挺有意思的。", },
	[75084] = {id=75084, zh_CN="看起来你现在很没耐心？", },
	[75085] = {id=75085, zh_CN="烦死了，别来惹我。", },
	[75086] = {id=75086, zh_CN="那你先冷静，我走啦。", },
	[75087] = {id=75087, zh_CN="……嗯，回见。", },
	[75088] = {id=75088, zh_CN="喝口水吧，消消气。", },
	[75089] = {id=75089, zh_CN="呼……谢谢，冷静多了。", },
	[75090] = {id=75090, zh_CN="眼神好凶，快要爆发了？", },
	[75091] = {id=75091, zh_CN="实在是太过分了！", },
	[75092] = {id=75092, zh_CN="别生气了，气大伤身。", },
	[75093] = {id=75093, zh_CN="哼，还是你懂我。", },
	[75094] = {id=75094, zh_CN="谁惹你了？告诉我。", },
	[75095] = {id=75095, zh_CN="唉，一言难尽。", },
	[75096] = {id=75096, zh_CN="感觉你完全失控了？", },
	[75097] = {id=75097, zh_CN="谁也别想让我冷静下来！", },
	[75098] = {id=75098, zh_CN="我先撤了，你保重。", },
	[75099] = {id=75099, zh_CN="离我远点就行！", },
	[75100] = {id=75100, zh_CN="冷静点！深呼吸。", },
	[75101] = {id=75101, zh_CN="呼……呼……我试试。", },
	[75102] = {id=75102, zh_CN="那个……今天天气不错哈。", },
	[75103] = {id=75103, zh_CN="还可以，湿度有点稍高。", },
	[75104] = {id=75104, zh_CN="是啊。", },
	[75105] = {id=75105, zh_CN="适合出门散心。", },
	[75106] = {id=75106, zh_CN="适合晒太阳！", },
	[75107] = {id=75107, zh_CN="呃……", },
	[75108] = {id=75108, zh_CN="阳光很温暖。", },
	[75109] = {id=75109, zh_CN="算了，话不投机。", },
	[75110] = {id=75110, zh_CN="咳，你肚子饿不饿？", },
	[75111] = {id=75111, zh_CN="能量已充满。", },
	[75112] = {id=75112, zh_CN="要不要再吃一点？", },
	[75113] = {id=75113, zh_CN="暂无进食需求。", },
	[75114] = {id=75114, zh_CN="这个肉最香了！", },
	[75115] = {id=75115, zh_CN="我说了我不想吃。", },
	[75116] = {id=75116, zh_CN="呃，要不要休息会儿？", },
	[75117] = {id=75117, zh_CN="别打扰我。", },
	[75118] = {id=75118, zh_CN="靠着我，休息一会儿吧。", },
	[75119] = {id=75119, zh_CN="那、那好吧。", },
	[75120] = {id=75120, zh_CN="你确实该休息一下了。", },
	[75121] = {id=75121, zh_CN="不用你管。", },
