	[531001] = {id=531001, zh_CN="卡！对手戏拍摄结束啦。", },
	[531002] = {id=531002, zh_CN="大家辛苦嘎嘎。", },
	[531003] = {id=531003, zh_CN="%PlayerName，演得不错哦！", },
	[531004] = {id=531004, zh_CN="休息一下，我们准备拍下一幕了哦。", },
	[531005] = {id=531005, zh_CN="呜啊啊啊啊啊！我来晚了！", },
	[531006] = {id=531006, zh_CN="嘎，云团贵客啊。你怎么来啦。", },
	[531007] = {id=531007, zh_CN="云团沉浸在vibecoding中，差点忘记米乐博士交给俺的事情。", },
	[531008] = {id=531008, zh_CN="我爷爷？", },
	[531009] = {id=531009, zh_CN="嗯，你爷爷担心你在镇子里初来乍到，不熟悉，特地叮嘱我给你定制属于你的第一个oc伙伴。", },
	[531010] = {id=531010, zh_CN="oc？", },
	[531011] = {id=531011, zh_CN="鸭导你明知故问哪。oc就是玩家自定义角色，也可以称呼ai伙伴。", },
	[531012] = {id=531012, zh_CN="ai伙伴？", },
	[531013] = {id=531013, zh_CN="你可以创造只属于自己的伙伴来和你一起演绎属于你的剧本。", },
	[531014] = {id=531014, zh_CN="真的？", },
	[531015] = {id=531015, zh_CN="让云团帮你创建一个自己的伙伴，来和你一起完成下一场戏吧！", },

